	private string GetNewValidPath(string path, int i = 1)
	{
		int num = i;
		string result = string.Concat(path + "_" + num, ".png");
		if (File.Exists(result))
		{
			num++;
			result = GetNewValidPath(path, num);
		}
		return result;
	}

