	protected virtual void OnEditorUpdate()
	{
		if (!computingNormal)
		{
			return;
		}
		if (needToWait)
		{
			waitingCycles++;
			if (waitingCycles > 5)
			{
				needToWait = false;
				timesWeWaited++;
			}
			return;
		}
		if (timesWeWaited == 1)
		{
			SetNewNormalTexture2();
		}
		if (timesWeWaited == 2)
		{
			SetNewNormalTexture3();
		}
		if (timesWeWaited == 3)
		{
			SetNewNormalTexture4();
		}
		needToWait = true;
	}

