[ExecuteInEditMode]
public class FoggyLight : MonoBehaviour
{
	public enum BlendModeEnum
	{
		Additive,
		AlphaBlended
	}

	public BlendModeEnum BlendMode;

	public bool ApplyTonemap = true;

	private UnityEngine.Component FogVolumeComponent;

	public Color PointLightColor = Color.white;

	private Vector3 Position;

	[Range(0f, 8f)]
	public float PointLightIntensity = 1f;

	[Range(0f, 20f)]
	public float FoggyLightIntensity = 1f;

	public float PointLightExponent = 5f;

	public float Offset = -2f;

	[Range(1f, 40f)]
	public float IntersectionRange = 2f;

	public int DrawOrder = 1;

	public bool AttatchLight;

	private Light AttachedLight;

	private Material FoggyLightMaterial;

	[SerializeField]
	private GameObject FogVolumeContainer;

	public bool InsideFogVolume;

	public Material GetMaterial()
	{
		return FoggyLightMaterial;
	}

	private void CreateMaterial()
	{
		if (!FoggyLightMaterial)
		{
			FoggyLightMaterial = new Material(Shader.Find("Hidden/FoggyLight"));
			FoggyLightMaterial.name = base.name.ToString() + " Material";
			base.gameObject.GetComponent<Renderer>().sharedMaterial = FoggyLightMaterial;
			FoggyLightMaterial.hideFlags = HideFlags.HideAndDontSave;
		}
	}

	private void OnEnable()
	{
		CreateMaterial();
	}

	private void OnDisable()
	{
		Disable();
	}

	private void OnWillRenderObject()
	{
		Renderer component = GetComponent<Renderer>();
		component.sortingOrder = DrawOrder;
		Position = base.gameObject.transform.position;
		PointLightExponent = Mathf.Max(1f, PointLightExponent);
		Position = base.gameObject.transform.position;
		component.sharedMaterial.SetColor("PointLightColor", PointLightColor);
		if ((bool)FogVolumeContainer && InsideFogVolume)
		{
			if (!FogVolumeComponent)
			{
				FogVolumeComponent = FogVolumeContainer.GetComponent("FogVolume");
			}
			FoggyLightMaterial.EnableKeyword("_FOG_CONTAINER");
			float value = (float)FogVolumeComponent.GetType().GetMethod("GetVisibility").Invoke(FogVolumeComponent, null);
			component.sharedMaterial.SetFloat("_Visibility", value);
		}
		else
		{
			FoggyLightMaterial.DisableKeyword("_FOG_CONTAINER");
		}
		if (ApplyTonemap)
		{
			FoggyLightMaterial.EnableKeyword("TONEMAP");
		}
		else
		{
			FoggyLightMaterial.DisableKeyword("TONEMAP");
		}
		FoggyLightMaterial.SetVector("PointLightPosition", Position);
		FoggyLightMaterial.SetFloat("PointLightIntensity", PointLightIntensity * FoggyLightIntensity);
		FoggyLightMaterial.SetFloat("PointLightExponent", PointLightExponent);
		FoggyLightMaterial.SetFloat("Offset", Offset);
		FoggyLightMaterial.SetFloat("IntersectionRange", IntersectionRange);
		if (AttatchLight)
		{
			if (AttachedLight == null)
			{
				AttachedLight = base.gameObject.GetComponent<Light>();
				if (AttachedLight == null)
				{
					AttachedLight = base.gameObject.AddComponent<Light>();
				}
				AttachedLight.shadows = LightShadows.Hard;
			}
			AttachedLight.intensity = PointLightIntensity / 2f;
			AttachedLight.color = PointLightColor;
			AttachedLight.enabled = true;
		}
		else if ((bool)AttachedLight)
		{
			AttachedLight.enabled = false;
		}
		BlendValues(BlendMode);
	}

	private void BlendValues(BlendModeEnum BlendMode)
	{
		switch (BlendMode)
		{
		case BlendModeEnum.Additive:
			FoggyLightMaterial.EnableKeyword("_ADDITIVE");
			FoggyLightMaterial.SetInt("_SrcBlend", 1);
			FoggyLightMaterial.SetInt("_DstBlend", 1);
			break;
		case BlendModeEnum.AlphaBlended:
			FoggyLightMaterial.DisableKeyword("_ADDITIVE");
			FoggyLightMaterial.SetInt("_SrcBlend", 5);
			FoggyLightMaterial.SetInt("_DstBlend", 10);
			break;
		}
	}

	public void Disable()
	{
		FoggyLightMaterial.SetFloat("PointLightIntensity", 0f);
	}

	public bool ReturnIsLightAttached(Light light)
	{
		if (light == null)
		{
			return false;
		}
		if (AttatchLight)
		{
			if ((bool)AttachedLight)
			{
				return AttachedLight == light;
			}
			return light == GetComponent<Light>();
		}
		return false;
	}
}
public class FoggyLightsOrbits : MonoBehaviour
{
	public float SpinSpeed = 50f;

	private float X;

	private float Y;

	private float Z;

	[Range(0f, 1f)]
	public float _ColorSpeed = 1f;

	private float ColorSpeed;

	private Vector3 RandomRangeXYZ;

	private float Opacity;

	private void Start()
	{
		Opacity = base.transform.GetChild(0).GetComponent<FoggyLight>().PointLightColor.a;
		RandomRangeXYZ.x = UnityEngine.Random.Range(0f, 1f);
		RandomRangeXYZ.y = UnityEngine.Random.Range(0f, 1f);
		RandomRangeXYZ.z = UnityEngine.Random.Range(0f, 1f);
	}

	private void Update()
	{
		ColorSpeed += Time.deltaTime * _ColorSpeed;
		base.transform.Rotate(0f, Time.deltaTime * SpinSpeed, 0f);
		X = Mathf.Sin(ColorSpeed * RandomRangeXYZ.x) * 0.5f + 0.5f;
		Y = Mathf.Sin(ColorSpeed * RandomRangeXYZ.y) * 0.5f + 0.5f;
		Z = Mathf.Sin(ColorSpeed * RandomRangeXYZ.z) * 0.5f + 0.5f;
		Color pointLightColor = new Color(X, Y, Z, Opacity);
		base.transform.GetChild(0).GetComponent<FoggyLight>().PointLightColor = pointLightColor;
	}
}
[ExecuteInEditMode]
public class ProgressBarPro : MonoBehaviour
{
	public enum AnimationType
	{
		FixedTimeForChange,
		ChangeSpeed
	}

	[SerializeField]
	[Range(0f, 1f)]
	private float m_value = 1f;

	private float displayValue = -1f;

	[Space(10f)]
	[Tooltip("Smoothes out the animation of the bar.")]
	[SerializeField]
	private bool animateBar = true;

	[SerializeField]
	private AnimationType animationType;

	[SerializeField]
	private float animTime = 0.25f;

	[Space(10f)]
	[SerializeField]
	private ProgressBarProView[] views;

	private Coroutine sizeAnim;

	public float Value
	{
		get
		{
			return m_value;
		}
		set
		{
			if (value != m_value)
			{
				SetValue(value);
			}
		}
	}

	public void Start()
	{
		if (views == null || views.Length == 0)
		{
			views = GetComponentsInChildren<ProgressBarProView>();
		}
	}

	private void OnEnable()
	{
		SetDisplayValue(m_value, forceUpdate: true);
	}

	public void SetValue(float value, float maxValue)
	{
		if (maxValue != 0f)
		{
			SetValue(value / maxValue);
		}
		else
		{
			SetValue(0f);
		}
	}

	public void SetValue(int value, int maxValue)
	{
		if (maxValue != 0)
		{
			SetValue((float)value / (float)maxValue);
		}
		else
		{
			SetValue(0f);
		}
	}

	public void SetValue(float percentage, bool forceUpdate = false)
	{
		if (forceUpdate || !Mathf.Approximately(m_value, percentage))
		{
			m_value = Mathf.Clamp01(percentage);
			for (int i = 0; i < views.Length; i++)
			{
				views[i].NewChangeStarted(displayValue, m_value);
			}
			if (animateBar && Application.isPlaying && base.gameObject.activeInHierarchy)
			{
				StartSizeAnim(percentage);
			}
			else
			{
				SetDisplayValue(percentage);
			}
		}
	}

	public bool IsAnimating()
	{
		if (!animateBar)
		{
			return false;
		}
		return !Mathf.Approximately(displayValue, m_value);
	}

	public void SetBarColor(Color color)
	{
		for (int i = 0; i < views.Length; i++)
		{
			views[i].SetBarColor(color);
		}
	}

	private void StartSizeAnim(float percentage)
	{
		if (sizeAnim != null)
		{
			StopCoroutine(sizeAnim);
		}
		sizeAnim = StartCoroutine(DoBarSizeAnim());
	}

	private IEnumerator DoBarSizeAnim()
	{
		float startValue = displayValue;
		float time = 0f;
		float change = m_value - displayValue;
		float duration = ((animationType == AnimationType.FixedTimeForChange) ? animTime : (Mathf.Abs(change) / animTime));
		while (time < duration)
		{
			time += Time.deltaTime;
			SetDisplayValue(Utils.EaseSinInOut(time / duration, startValue, change));
			yield return null;
		}
		SetDisplayValue(m_value, forceUpdate: true);
		sizeAnim = null;
	}

	private void SetDisplayValue(float value, bool forceUpdate = false)
	{
		if (forceUpdate || !(displayValue >= 0f) || !Mathf.Approximately(displayValue, value))
		{
			displayValue = value;
			UpdateBarViews(displayValue, m_value, forceUpdate);
		}
	}

	private void UpdateBarViews(float currentValue, float targetValue, bool forceUpdate = false)
	{
		if (views == null)
		{
			return;
		}
		for (int i = 0; i < views.Length; i++)
		{
			if (views[i] != null && (forceUpdate || views[i].CanUpdateView(currentValue, targetValue)))
			{
				views[i].UpdateView(currentValue, targetValue);
			}
		}
	}

	private void OnDidApplyAnimationProperties()
	{
		SetValue(m_value, forceUpdate: true);
	}
}
public static class RandomFromDistribution
{
	public enum ConfidenceLevel_e
	{
		_60,
		_80,
		_90,
		_95,
		_98,
		_99,
		_998,
		_999
	}

	public enum Direction_e
	{
		Right,
		Left
	}

	private static float[] confidence_to_z_score = new float[8] { 0.8416212f, 1.2815516f, 1.6448536f, 1.959964f, 2.3263478f, 2.5758293f, 3.0902324f, 3.2905266f };

	public static float RandomRangeNormalDistribution(float min, float max, ConfidenceLevel_e confidence_level_cutoff)
	{
		float mean = 0.5f * (min + max);
		float num = confidence_to_z_score[(int)confidence_level_cutoff];
		float std_dev = (max - min) / 2f / num;
		float num2;
		do
		{
			num2 = RandomNormalDistribution(mean, std_dev);
		}
		while (num2 > max || num2 < min);
		return num2;
	}

	public static float RandomNormalDistribution(float mean, float std_dev)
	{
		return RandomFromStandardNormalDistribution() * std_dev + mean;
	}

	public static float RandomFromStandardNormalDistribution()
	{
		float num;
		float num2;
		float num3;
		do
		{
			num = UnityEngine.Random.Range(-1f, 1f);
			num2 = UnityEngine.Random.Range(-1f, 1f);
			num3 = num * num + num2 * num2;
		}
		while (num3 == 0f || !(num3 < 1f));
		float num4 = ((UnityEngine.Random.Range(0, 2) != 0) ? num2 : num);
		return num4 * Mathf.Sqrt(-2f * Mathf.Log(num3) / num3);
	}

	public static float RandomRangeSlope(float min, float max, float skew, Direction_e direction)
	{
		return min + RandomFromSlopedDistribution(skew, direction) * (max - min);
	}

	public static float RandomFromSlopedDistribution(float skew, Direction_e direction)
	{
		float num = Inverse_Sec_Sqrd(skew);
		float maxInclusive = Sec_Sqrd_CumulativeDistributionFunction(num);
		float num2 = Sec_Sqrd_InverseCumulativeDistributionFunction(UnityEngine.Random.Range(0f, maxInclusive)) / num;
		if (direction == Direction_e.Left)
		{
			num2 = 1f - num2;
		}
		return num2;
	}

	private static float Inverse_Sec_Sqrd(float y)
	{
		return Mathf.Acos(1f / Mathf.Sqrt(y));
	}

	private static float Sec_Sqrd_CumulativeDistributionFunction(float x)
	{
		return Mathf.Tan(x);
	}

	private static float Sec_Sqrd_InverseCumulativeDistributionFunction(float x)
	{
		return Mathf.Atan(x);
	}

	public static float RandomRangeLinear(float min, float max, float slope)
	{
		float num = RandomLinear(slope);
		return min + (max - min) * num;
	}

	public static float RandomLinear(float slope)
	{
		float num = RandomFromLinearWithPositiveSlope(Mathf.Abs(slope));
		if (slope < 0f)
		{
			return 1f - num;
		}
		return num;
	}

	private static float RandomFromLinearWithPositiveSlope(float slope)
	{
		if (slope == 0f)
		{
			return UnityEngine.Random.Range(0f, 1f);
		}
		float num;
		float num2;
		do
		{
			num = UnityEngine.Random.Range(0f, 1f);
			num2 = UnityEngine.Random.Range(0f, 1f);
			if (slope < 1f)
			{
				num2 -= (1f - slope) / 2f;
			}
		}
		while (num2 > num * slope);
		return num;
	}

	public static float RandomRangeExponential(float min, float max, float exponent, Direction_e direction)
	{
		return min + RandomFromExponentialDistribution(exponent, direction) * (max - min);
	}

	public static float RandomFromExponentialDistribution(float exponent, Direction_e direction)
	{
		float maxInclusive = ExponentialRightCDF(1f, exponent);
		float num = EponentialRightInverseCDF(UnityEngine.Random.Range(0f, maxInclusive), exponent);
		if (direction == Direction_e.Left)
		{
			num = 1f - num;
		}
		return num;
	}

	private static float ExponentialRightInverse(float y, float exponent)
	{
		return Mathf.Pow(y, 1f / exponent);
	}

	private static float ExponentialRightCDF(float x, float exponent)
	{
		float num = exponent + 1f;
		return Mathf.Pow(x, num) / num;
	}

	private static float EponentialRightInverseCDF(float x, float exponent)
	{
		float num = exponent + 1f;
		return Mathf.Pow(num * x, 1f / num);
	}

	public static int RandomChoiceFollowingDistribution(List<float> probabilities)
	{
		float[] array = new float[probabilities.Count];
		float num = 0f;
		for (int i = 0; i < probabilities.Count; i++)
		{
			array[i] = num + probabilities[i];
			num = array[i];
		}
		float value = UnityEngine.Random.Range(0f, array[probabilities.Count - 1]);
		int num2 = Array.BinarySearch(array, value);
		if (num2 < 0)
		{
			num2 = ~num2;
		}
		return num2;
	}
}
