public class AchievementEvent : GameEvent
{
	private static AchievementEvent _instance;

	public EnergyManualProducer EnergyManualProducer { get; private set; }

	public MoraleEffect MoraleEffect { get; private set; }

	public AchievementEvent(GameEventType type)
		: base(type)
	{
	}

	private static AchievementEvent Get(GameEventType type)
	{
		if (_instance == null)
		{
			_instance = new AchievementEvent(type);
		}
		else
		{
			_instance.EventType = type;
		}
		_instance.Clear();
		return _instance;
	}

	private void Clear()
	{
		EnergyManualProducer = null;
		MoraleEffect = null;
	}

	public static void Dispatch(GameEventType type, EnergyManualProducer energyManualProducer)
	{
		AchievementEvent achievementEvent = Get(type);
		achievementEvent.EnergyManualProducer = energyManualProducer;
		achievementEvent.Dispatch();
	}

	public static void Dispatch(GameEventType type, MoraleEffect moraleEffect)
	{
		AchievementEvent achievementEvent = Get(type);
		achievementEvent.MoraleEffect = moraleEffect;
		achievementEvent.Dispatch();
	}
}
[CreateAssetMenu(menuName = "Flotsam/Achievements/Buildable Built")]
public class BuildableAchievement : AchievementBase
{
	[Header("Buildable Achievement")]
	[SerializeField]
	private BuildableProperties _buildableProperties;

	[SerializeField]
	[Min(1f)]
	private int _requirement = 1;

	protected override void Initialize()
	{
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, OnBuildableBuilt);
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, OnBuildableBuilt);
	}

	private void OnBuildableBuilt(GameEvent gameEvent)
	{
		if (!(gameEvent is BuildableEvent buildableEvent) || !(buildableEvent.BuildableProperties == _buildableProperties))
		{
			return;
		}
		if (_requirement == 1 && UnlockAchievement())
		{
			Uninitialize();
		}
		int num = 0;
		foreach (Buildable buildable in Community.PlayerCommunity.Buildables)
		{
			if (buildable.Properties == _buildableProperties)
			{
				num++;
			}
		}
		if (num >= _requirement && UnlockAchievement())
		{
			Uninitialize();
		}
	}
