[CreateAssetMenu(menuName = "Flotsam/Achievements/Jack of all trades")]
public class JackOfAllTrades : AchievementBase
{
	[Header("Jack Of All Trades")]
	[SerializeField]
	private DrifterAttributes.AttributeType[] _attributeTypes;

	[SerializeField]
	[Tooltip("The required attribute level to trigger the achievement.")]
	private int _requirement;

	protected override void Initialize()
	{
		GameEventDispatcher.AddListener(GameEventType.AgentAttributeLeveled, OnAttributeLeveled);
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentAttributeLeveled, OnAttributeLeveled);
	}

	private void OnAttributeLeveled(GameEvent gameEvent)
	{
		if (!(gameEvent is AttributeEvent attributeEvent) || attributeEvent.Agent.Attributes.ReturnExpertise(attributeEvent.AttributeType) < _requirement)
		{
			return;
		}
		DrifterAttributes.AttributeType[] attributeTypes = _attributeTypes;
		foreach (DrifterAttributes.AttributeType type in attributeTypes)
		{
			if (attributeEvent.Agent.Attributes.ReturnExpertise(type) < _requirement)
			{
				return;
			}
		}
		if (UnlockAchievement())
		{
			Uninitialize();
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Achievements/Lone Wolf")]
public class LoneWolf : DayEndedAchievementBase
{
	[Header("Lone Wolf")]
	[SerializeField]
	private int _days;

	protected override void OnDayEnded(GameEvent gameEvent)
	{
		if (!(gameEvent is DayEvent dayEvent))
		{
			return;
		}
		int i = dayEvent.Days.Count - _days;
		if (i < 0)
		{
			return;
		}
		for (; i < dayEvent.Days.Count; i++)
		{
			DailyReport report = dayEvent.Days[i].Report;
			if (report.StartAgentCount != 1 || report.HasActorRescue(ActorType.Agent))
			{
				return;
			}
		}
		if (UnlockAchievement())
		{
			Uninitialize();
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Achievements/Modules Active Achievement")]
public class ModulesActiveAchievement : AchievementBase
{
	[Header("Modules Active Achievement")]
	[SerializeField]
	private ModuleProperties _module;

	[SerializeField]
	private int _count;

	[SerializeField]
	[Tooltip("The amount of buildable that will be evaluated per frame.")]
	private int _evaluateStepSize = 10;

	private Coroutine _coroutine;

	private bool _reevaluate;

	protected override void Initialize()
	{
		_coroutine = CoroutineMotor.StartRoutine(Evaluate());
		GameEventDispatcher.AddListener(GameEventType.ModuleActivated, OnModuleActivated);
		GameEventDispatcher.AddListener(GameEventType.BuildableSalvaged, OnBuildableSalvaged);
	}

	public override void Uninitialize()
	{
		_coroutine = null;
		GameEventDispatcher.RemoveListener(GameEventType.ModuleActivated, OnModuleActivated);
		GameEventDispatcher.AddListener(GameEventType.BuildableSalvaged, OnBuildableSalvaged);
	}

	private IEnumerator Evaluate()
	{
		List<Buildable> buildables = Community.PlayerCommunity.Buildables;
		int count = 0;
		int yieldIndex = ((_evaluateStepSize <= 0) ? buildables.Count : _evaluateStepSize);
		for (int i = 0; i < buildables.Count; i++)
		{
			if (buildables[i].HasActiveModule(_module))
			{
				count++;
			}
			if (i == yieldIndex)
			{
				yieldIndex += _evaluateStepSize;
				yield return null;
			}
		}
		if (count >= _count && UnlockAchievement())
		{
			Uninitialize();
		}
		else if (_reevaluate)
		{
			_reevaluate = false;
			_coroutine = CoroutineMotor.StartRoutine(Evaluate());
		}
		else
		{
			_coroutine = null;
		}
	}

	private void OnModuleActivated(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent && !(buildableEvent.ModuleProperties != _module))
		{
			if (_coroutine == null)
			{
				_coroutine = CoroutineMotor.StartRoutine(Evaluate());
			}
			else
			{
				_reevaluate = true;
			}
		}
	}

	private void OnBuildableSalvaged(GameEvent gameEvent)
	{
		if (_coroutine != null)
		{
			CoroutineMotor.StopRoutine(_coroutine);
			_coroutine = CoroutineMotor.StartRoutine(Evaluate());
			_reevaluate = false;
		}
	}
}
