[CreateAssetMenu(fileName = "BuildableActionConnect", menuName = "Flotsam/Actions/Buildable/Connect")]
public class BuildableActionConnect : ISelectableActionBase<Buildable>
{
	[SerializeField]
	private uint _index;

	[SerializeField]
	[FormerlySerializedAs("_canLink")]
	private ActionData _canConnect;

	[SerializeField]
	[FormerlySerializedAs("_cannotLink")]
	private ActionData _cannotConnect;

	[SerializeField]
	private EnergyGridConnectCursorProperties _cursorProperties;

	[NonSerialized]
	private EnergyGridBuildableComponent _energyGridComponent;

	public override bool IsEnabled
	{
		get
		{
			if ((bool)_energyGridComponent)
			{
				return _index < _energyGridComponent.ConnectionsCapacity;
			}
			return false;
		}
	}

	public override bool IsInteractable => IsEnabled;

	public override void SetSelectable(Buildable selectable)
	{
		base.SetSelectable(selectable);
		selectable.TryReturnBuildableExtendable<EnergyGridBuildableComponent>(out _energyGridComponent);
	}

	public override void Trigger()
	{
		if (_energyGridComponent.CanConnect(_index))
		{
			_cursorProperties.Initialize(_energyGridComponent, _index);
			GameManager.CursorManager.Activate(_cursorProperties);
		}
		else
		{
			EnergyGrid.DisconnectWithIndex(_energyGridComponent, _index);
		}
	}

	public override Sprite GetIcon()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Icon;
		}
		return _canConnect.Icon;
	}

	public override LocalizedString GetLabel()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Label;
		}
		return _canConnect.Label;
	}

	public override LocalizedString GetDescription()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Description;
		}
		return _canConnect.Description;
	}
}
[CreateAssetMenu(fileName = "BuildableActionDeconstruct", menuName = "Flotsam/Actions/Buildable/Deconstruct")]
public class BuildableActionDeconstruct : ISelectableActionBase<Buildable>
{
	[SerializeField]
	private Sprite _salvageIcon;

	[SerializeField]
	private LocalizedString _salvageLabel;

	[SerializeField]
	private LocalizedString _salvageDescription;

	[SerializeField]
	private Sprite _cancelIcon;

	[SerializeField]
	private LocalizedString _cancelLabel;

	[SerializeField]
	private LocalizedString _cancelDescription;

	public override bool IsEnabled
	{
		get
		{
			if ((bool)base.Selectable)
			{
				return base.Selectable.Properties.ShowDurabilityElements;
			}
			return false;
		}
	}

	public override void Trigger()
	{
		LocalizedString error;
		if (base.Selectable.BuildPhase == BuildPhase.SalvageShutdown || base.Selectable.BuildPhase == BuildPhase.Deconstructing)
		{
			base.Selectable.CancelDeconstruction();
		}
		else if (base.Selectable.CanBeDeconstructed(out error))
		{
			base.Selectable.Salvage();
		}
	}

	public override Sprite GetIcon()
	{
		if (base.Selectable.BuildPhase == BuildPhase.SalvageShutdown || base.Selectable.BuildPhase == BuildPhase.Deconstructing)
		{
			return _cancelIcon;
		}
		return _salvageIcon;
	}

	public override LocalizedString GetDescription()
	{
		if (base.Selectable.BuildPhase == BuildPhase.SalvageShutdown || base.Selectable.BuildPhase == BuildPhase.Deconstructing)
		{
			return _cancelDescription;
		}
		if (!base.Selectable.CanBeDeconstructed(out var error))
		{
			return error;
		}
		return _salvageDescription;
	}

	public override LocalizedString GetLabel()
	{
		if (base.Selectable.BuildPhase == BuildPhase.SalvageShutdown || base.Selectable.BuildPhase == BuildPhase.Deconstructing)
		{
			return _cancelLabel;
		}
		return _salvageLabel;
	}

	public override void RadialMenuSelect(RadialMenu radialMenu)
	{
		if (base.Selectable.BuildPhase != BuildPhase.SalvageShutdown && base.Selectable.BuildPhase != BuildPhase.Deconstructing && base.Selectable.CanBeDeconstructed(out var _))
		{
			radialMenu.SetDeconstructInfo(base.Selectable);
		}
	}

	public override void RadialMenuDeselect(RadialMenu radialMenu)
	{
		radialMenu.ClearBuildable();
	}
}
