[CreateAssetMenu(fileName = "BuildableActionUpgrade", menuName = "Flotsam/Actions/Buildable/Upgrade")]
public class BuildableActionUpgrade : ISelectableActionBase<Buildable>
{
	private enum State
	{
		Locked,
		Upgrade,
		Cancel
	}

	[SerializeField]
	private Sprite _lockedSprite;

	[SerializeField]
	private LocalizedString _lockedLabel;

	[SerializeField]
	private LocalizedString _lockedDescription;

	[SerializeField]
	private Sprite _upgradeIcon;

	[SerializeField]
	private LocalizedString _upgradeLabel;

	[SerializeField]
	private LocalizedString _upgradeDescription;

	[SerializeField]
	private Sprite _cancelIcon;

	[SerializeField]
	private LocalizedString _cancelLabel;

	[SerializeField]
	private LocalizedString _cancelDescription;

	public override bool IsEnabled
	{
		get
		{
			if ((bool)base.Selectable)
			{
				return base.Selectable.Properties.Upgrade;
			}
			return false;
		}
	}

	public override bool IsInteractable
	{
		get
		{
			if ((bool)base.Selectable)
			{
				if (!base.Selectable.CanUpgrade() && base.Selectable.BuildPhase != BuildPhase.UpgradeShutdown)
				{
					return base.Selectable.BuildPhase == BuildPhase.UpgradeHaulTo;
				}
				return true;
			}
			return false;
		}
	}

	public override void Trigger()
	{
		if (IsInteractable)
		{
			switch (GetState())
			{
			case State.Upgrade:
				base.Selectable.Upgrade();
				break;
			case State.Cancel:
				base.Selectable.CancelUpgrade();
				break;
			default:
				UnityEngine.Debug.Log("Open Research Panel?");
				break;
			}
		}
	}

	public override void RadialMenuSelect(RadialMenu radialMenu)
	{
		if (GetState() == State.Upgrade)
		{
			radialMenu.SetUpgradeInfo(base.Selectable, upgradeResources: true);
		}
	}

	public override void RadialMenuDeselect(RadialMenu radialMenu)
	{
		radialMenu.ClearBuildable();
	}

	public override Sprite GetIcon()
	{
		return GetState() switch
		{
			State.Upgrade => _upgradeIcon, 
			State.Cancel => _cancelIcon, 
			_ => _lockedSprite, 
		};
	}

	public override LocalizedString GetLabel()
	{
		return GetState() switch
		{
			State.Upgrade => _upgradeLabel, 
			State.Cancel => _cancelLabel, 
			_ => _lockedLabel, 
		};
	}

	public override LocalizedString GetDescription()
	{
		return GetState() switch
		{
			State.Upgrade => _upgradeDescription, 
			State.Cancel => _cancelDescription, 
			_ => _lockedDescription, 
		};
	}

	private State GetState()
	{
		if (base.Selectable.Properties.Upgrade.IsUnlocked())
		{
			if (base.Selectable.BuildPhase == BuildPhase.UpgradeShutdown || base.Selectable.BuildPhase == BuildPhase.UpgradeHaulTo)
			{
				return State.Cancel;
			}
			return State.Upgrade;
		}
		return State.Locked;
	}
}
[CreateAssetMenu(fileName = "DecorationActionConnect", menuName = "Flotsam/Actions/Buildable/Decoration Action Connect")]
public class DecorationActionConnect : ISelectableActionBase<Decoration>
{
	[SerializeField]
	private uint _index;

	[SerializeField]
	[FormerlySerializedAs("_canLink")]
	private ActionData _canConnect;

	[SerializeField]
	[FormerlySerializedAs("_cannotLink")]
	private ActionData _cannotConnect;

	[SerializeField]
	private EnergyGridConnectCursorProperties _cursorProperties;

	[NonSerialized]
	private EnergyGridBuildableComponent _energyGridComponent;

	public override bool IsEnabled
	{
		get
		{
			if ((bool)_energyGridComponent)
			{
				return _index < _energyGridComponent.ConnectionsCapacity;
			}
			return false;
		}
	}

	public override bool IsInteractable => IsEnabled;

	public override void SetSelectable(Decoration selectable)
	{
		base.SetSelectable(selectable);
		selectable.TryGetComponent<EnergyGridBuildableComponent>(out _energyGridComponent);
	}

	public override void Trigger()
	{
		if (_energyGridComponent.CanConnect(_index))
		{
			_cursorProperties.Initialize(_energyGridComponent, _index);
			GameManager.CursorManager.Activate(_cursorProperties);
		}
		else
		{
			EnergyGrid.DisconnectWithIndex(_energyGridComponent, _index);
		}
	}

	public override Sprite GetIcon()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Icon;
		}
		return _canConnect.Icon;
	}

	public override LocalizedString GetLabel()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Label;
		}
		return _canConnect.Label;
	}

	public override LocalizedString GetDescription()
	{
		if (!_energyGridComponent.CanConnect(_index))
		{
			return _cannotConnect.Description;
		}
		return _canConnect.Description;
	}
}
