public class AnimationLoopBehaviour : StateMachineBehaviour
{
	[SerializeField]
	private AnimationClip _enterClip;

	[SerializeField]
	private AnimationClip _exitClip;

	[SerializeField]
	private string _triggerName = "";

	private float _timer;

	private float _triggerTime;

	public override void OnStateEnter(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
	{
		base.OnStateEnter(animator, stateInfo, layerIndex);
		float num = animator.GetFloat("Transition Time");
		float length = _enterClip.length;
		float length2 = _exitClip.length;
		if (num < length + length2)
		{
			UnityEngine.Debug.LogError($"Entered animation state {animator.GetCurrentAnimatorClipInfo(layerIndex)[0].clip.name} but the enter and exit length is longer than the loop time.");
		}
		_triggerTime = num - length - length2;
		_timer = 0f;
	}

	public override void OnStateUpdate(Animator animator, AnimatorStateInfo stateInfo, int layerIndex)
	{
		base.OnStateUpdate(animator, stateInfo, layerIndex);
		_timer += Time.deltaTime;
		if (_timer >= _triggerTime)
		{
			animator.SetTrigger(_triggerName);
		}
	}
}
public class AnimationTools : MonoBehaviour
{
	public class RigEvent : UnityEvent<DrifterRigItemEvent>
	{
	}

	public class RigTypeEvent : UnityEvent<DrifterRigEventType>
	{
	}

	[SerializeField]
	[FormerlySerializedAs("_chest")]
	private Transform _chestSocket;

	[SerializeField]
	[FormerlySerializedAs("_leftHand")]
	private Transform _leftHandSocket;

	[SerializeField]
	[FormerlySerializedAs("_rightHand")]
	private Transform _rightHandSocket;

	[SerializeField]
	private Transform _leftFloaterSocket;

	[SerializeField]
	private Transform _rightFloaterSocket;

	[SerializeField]
	private Transform _leftHipSocket;

	[SerializeField]
	private Transform _rightHipSocket;

	private Agent _agent;

	private GameObject _backpack;

	private GameObject _leftHandPrefab;

	private GameObject _leftHandInstance;

	private GameObject _rightHandPrefab;

	private GameObject _rightHandInstance;

	private GameObject _leftFloaterPrefab;

	private GameObject _leftFloaterInstance;

	private GameObject _rightFloaterPrefab;

	private GameObject _rightFloaterInstance;

	private GameObject _leftHipPrefab;

	private GameObject _leftHipInstance;

	private GameObject _rightHipPrefab;

	private GameObject _rightHipInstance;

	private static Dictionary<GameObject, List<GameObject>> _toolInstances = new Dictionary<GameObject, List<GameObject>>();

	public RigEvent DrifterRigEvent { get; private set; } = new RigEvent();

	public RigTypeEvent DrifterRigTypeEvent { get; private set; } = new RigTypeEvent();

	public void Initialize(Agent agent)
	{
		_agent = agent;
		if (_agent != null)
		{
			_backpack = UnityEngine.Object.Instantiate(_agent.Properties.BackpackPrefab).gameObject;
			_backpack.transform.SetParent(_chestSocket, worldPositionStays: true);
			_backpack.transform.localPosition = Vector3.zero;
			_backpack.transform.localRotation = Quaternion.identity;
			_backpack.SetActive(value: false);
			_agent.Inventory.InventoryUpdatedEvent.AddListener(CheckForBackpack);
		}
	}

	private void OnDestroy()
	{
		if (_agent != null)
		{
			_agent.Inventory.InventoryUpdatedEvent.RemoveListener(CheckForBackpack);
		}
	}

	public void CheckForBackpack()
	{
		if (_backpack == null)
		{
			return;
		}
		Activity currentActivity = _agent.CurrentActivity;
		if ((uint)(currentActivity - 5) <= 1u)
		{
			Navigator navigator = _agent.ReturnNavigator();
			if (navigator.Terrain == Navigator.TerrainType.Construction || navigator.Terrain == Navigator.TerrainType.UnityNavMesh)
			{
				_backpack.SetActive(value: false);
				return;
			}
		}
		_backpack.SetActive(0 < _agent.Inventory.ReturnCount());
	}

	public void ClearAnimationTools()
	{
		ClearLeftHand();
		ClearRightHand();
		ClearLeftFloater();
		ClearRightFloater();
		ClearLeftHip();
		ClearRightHip();
	}

	private void SetSocket(UnityEngine.Object toolToSet, Transform socket, ref GameObject currentTool, ref GameObject currentToolInstance)
	{
		if (!(toolToSet == currentTool))
		{
			if (currentToolInstance != null)
			{
				ReleaseToolInstance(currentTool, currentToolInstance);
			}
			currentTool = toolToSet as GameObject;
			if ((bool)currentTool)
			{
				currentToolInstance = ReturnToolInstance(currentTool);
				Transform obj = currentToolInstance.transform;
				obj.SetParent(socket);
				obj.CopyLocalPositionRotationAndScale(currentTool.transform);
			}
			else
			{
				currentToolInstance = currentTool;
			}
		}
	}

	public void OnDrifterRigItemEvent(DrifterRigItemEvent evt)
	{
		evt.Dispatch(this);
	}

	public void OnDrifterRigEvent(DrifterRigEventType evt)
	{
		evt.Dispatch(this);
	}

	public void SetLeftHand(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _leftHandSocket, ref _leftHandPrefab, ref _leftHandInstance);
	}

	public void ClearLeftHand()
	{
		ReleaseToolInstance(_leftHandPrefab, _leftHandInstance);
		_leftHandPrefab = null;
		_leftHandInstance = null;
	}

	public void SetRightHand(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _rightHandSocket, ref _rightHandPrefab, ref _rightHandInstance);
	}

	public void ClearRightHand()
	{
		ReleaseToolInstance(_rightHandPrefab, _rightHandInstance);
		_rightHandPrefab = null;
		_rightHandInstance = null;
	}

	public void SetLeftFloater(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _leftFloaterSocket, ref _leftFloaterPrefab, ref _leftFloaterInstance);
	}

	public void ClearLeftFloater()
	{
		ReleaseToolInstance(_leftFloaterPrefab, _leftFloaterInstance);
		_leftFloaterPrefab = null;
		_leftFloaterInstance = null;
	}

	public void SetRightFloater(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _rightFloaterSocket, ref _rightFloaterPrefab, ref _rightFloaterInstance);
	}

	public void ClearRightFloater()
	{
		ReleaseToolInstance(_rightFloaterPrefab, _rightFloaterInstance);
		_rightFloaterPrefab = null;
		_rightFloaterInstance = null;
	}

	public void SetLeftHip(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _leftHipSocket, ref _leftHipPrefab, ref _leftHipInstance);
	}

	public void ClearLeftHip()
	{
		ReleaseToolInstance(_leftHipPrefab, _leftHipInstance);
		_leftHipPrefab = null;
		_leftHipInstance = null;
	}

	public void SetRightHip(UnityEngine.Object socketFiller)
	{
		SetSocket(socketFiller, _rightHipSocket, ref _rightHipPrefab, ref _rightHipInstance);
	}

	public void ClearRightHip()
	{
		ReleaseToolInstance(_rightHipPrefab, _rightHipInstance);
		_rightHipPrefab = null;
		_rightHipInstance = null;
	}

	private GameObject ReturnToolInstance(GameObject prefab)
	{
		GameObject gameObject = null;
		if (_toolInstances.TryGetValue(prefab, out var value) && 0 < value.Count)
		{
			while (0 < value.Count)
			{
				int index = value.Count - 1;
				gameObject = value[index];
				value.RemoveAt(index);
				if ((bool)gameObject)
				{
					break;
				}
			}
		}
		if (gameObject == null)
		{
			gameObject = UnityEngine.Object.Instantiate(prefab);
		}
		gameObject.SetActive(value: true);
		return gameObject;
	}

	private void ReleaseToolInstance(GameObject prefab, GameObject instance)
	{
		if ((bool)instance)
		{
			instance.SetActive(value: false);
			if (_toolInstances.TryGetValue(prefab, out var value))
			{
				value.Add(instance);
				return;
			}
			_toolInstances.Add(prefab, new List<GameObject> { instance });
		}
	}
}
public class AnimationTween
{
	public struct Cubic
	{
		public Vector3 Position;

		public Vector3 Derivative;
	}

	public static Vector3 SphericalPositionLerp(Vector3 startPosition, Vector3 endPosition, float progress, float height = 1f)
	{
		if (height == 0f)
		{
			PajamaLlama.Debugs.Debugger.Warning("Height can not be 0!");
			return (startPosition + endPosition) * 0.5f;
		}
		if (height >= Vector3.Distance(startPosition, endPosition) * 0.5f)
		{
			height = Vector3.Distance(startPosition, endPosition) * 0.5f - 0.01f;
		}
		float f = Vector3.Distance(startPosition, endPosition);
		float num = height / 2f + Mathf.Pow(f, 2f) / (8f * height);
		Vector3 index = PajamaLlama.Math.Math.ReturnPerpendicularVector(endPosition - startPosition);
		Vector3 normalized = PajamaLlama.Math.Math.ReturnPerpendicularVector(endPosition - startPosition, index).normalized;
		Vector3 vector = (startPosition + endPosition) * 0.5f;
		vector -= -normalized * (num - height);
		startPosition -= vector;
		endPosition -= vector;
		AnimationCurve animationCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);
		return Vector3.Slerp(startPosition, endPosition, animationCurve.Evaluate(progress)) + vector;
	}

	public static Vector3 LinearPositionLerp(Vector3 startPosition, Vector3 endPosition, float progress)
	{
		AnimationCurve animationCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);
		return Vector3.Lerp(startPosition, endPosition, animationCurve.Evaluate(progress));
	}

	public static Cubic CubicLerp(Vector3 startPosition, Vector3 endPosition, float progress, Vector3 curvature, AnimationCurve curve)
	{
		Vector3 item = startPosition;
		Vector3 item2 = endPosition;
		Vector3 vector = endPosition - startPosition;
		item.x += vector.x * curvature.x;
		item.y += vector.y * curvature.y;
		item.z += vector.z * curvature.z;
		item2.x -= vector.x * curvature.x;
		item2.y -= vector.y * curvature.y;
		item2.z -= vector.z * curvature.z;
		progress = curve.Evaluate(progress);
		List<Vector3> list = new List<Vector3>();
		list.Add(startPosition);
		list.Add(item);
		list.Add(item2);
		list.Add(endPosition);
		Cubic result = default(Cubic);
		result.Position = Bezier.CalculatePointInTime(progress, list);
		result.Derivative = Bezier.CalculateDerivative(progress, list);
		return result;
	}
}
[RequireComponent(typeof(Animator))]
public class AnimatorGameObjectToggler : MonoBehaviour
{
	[Serializable]
	internal struct AnimationGameObjectToggle
	{
		[Tooltip("The state name that will trigger the disabling / enabling of the gameobjects.")]
		public string AnimationStateName;

		[Tooltip("The state name that will trigger the disabling / enabling of the gameobjects.")]
		public GameObject[] GameObjects;

		[Tooltip("State to set the gameobjects to when entering the animation state.")]
		public bool OnEnter;

		[Tooltip("State to set the gameobjects to when exiting the animation state.")]
		public bool OnExit;

		public void ToggleGameObjects(bool enter)
		{
			for (int i = 0; i < GameObjects.Length; i++)
			{
				GameObjects[i].SetActive(enter ? OnEnter : OnExit);
			}
		}
	}

	[SerializeField]
	[Tooltip("Array of all the animation gameobjects to toggle.")]
	private AnimationGameObjectToggle[] _animationGameObjectToggles;

	[SerializeField]
	[Tooltip("Layer index of the layer to check animation states for.")]
	private int _layerIndex;

	private Animator _animator;

	private AnimatorStateInfo _cachedAnimatorStateInfo;

	private AnimatorStateInfo _currentAnimatorStateInfo;

	private void Awake()
	{
		_animator = GetComponent<Animator>();
	}

	private void Update()
	{
		_cachedAnimatorStateInfo = _animator.GetCurrentAnimatorStateInfo(_layerIndex);
		if (_cachedAnimatorStateInfo.fullPathHash != _currentAnimatorStateInfo.fullPathHash)
		{
			HandleStateChange(_currentAnimatorStateInfo, enter: false);
			HandleStateChange(_cachedAnimatorStateInfo, enter: true);
			_currentAnimatorStateInfo = _cachedAnimatorStateInfo;
		}
	}

	private void HandleStateChange(AnimatorStateInfo stateInfo, bool enter)
	{
		for (int i = 0; i < _animationGameObjectToggles.Length; i++)
		{
			AnimationGameObjectToggle animationGameObjectToggle = _animationGameObjectToggles[i];
			if (stateInfo.IsName(animationGameObjectToggle.AnimationStateName))
			{
				animationGameObjectToggle.ToggleGameObjects(enter);
			}
		}
	}
}
public static class AnimatorHelper
{
	public const string AGENT_PARAMETER_Activity = "Activity";

	public const string AGENT_PARAMETER_ActivityTrigger = "Activity Trigger";

	public const string AGENT_PARAMETER_Floor = "Floor";

	public const string AGENT_PARAMETER_TransitionTrigger = "Transition Trigger";

	public const string AGENT_PARAMETERS_SpeedMultiplier = "Speed Multiplier";

	public static float ReturnAnimationLength(Agent agent, string name)
	{
		if (TryReturnAnimator(agent, out var animator))
		{
			return ReturnAnimationLength(animator, name);
		}
		return 0f;
	}

	public static void SetTransitionTrigger(Agent agent)
	{
		if (TryReturnAnimator(agent, out var animator))
		{
			animator.SetTrigger("Transition Trigger");
		}
	}

	public static void SetInteger(Agent agent, string name, int value)
	{
		if (TryReturnAnimator(agent, out var animator))
		{
			animator.SetInteger(name, value);
		}
	}

	public static void SetFloat(Agent agent, string name, float value)
	{
		if (TryReturnAnimator(agent, out var animator))
		{
			animator.SetFloat(name, value);
		}
	}

	public static float ReturnCurrentAnimatorStateLength(Agent agent, int layerIndex = 0)
	{
		if (TryReturnAnimator(agent, out var animator))
		{
			AnimatorStateInfo currentAnimatorStateInfo = animator.GetCurrentAnimatorStateInfo(layerIndex);
			return currentAnimatorStateInfo.length * currentAnimatorStateInfo.speedMultiplier;
		}
		return 0f;
	}

	public static void AddDirfterRigEventListener(Agent agent, UnityAction<DrifterRigItemEvent> listener)
	{
		if (TryReturnAnimationTools(agent, out var animationTools))
		{
			animationTools.DrifterRigEvent.AddListener(listener);
		}
	}

	public static void RemoveDirfterRigEventListener(Agent agent, UnityAction<DrifterRigItemEvent> listener)
	{
		if (TryReturnAnimationTools(agent, out var animationTools))
		{
			animationTools.DrifterRigEvent.RemoveListener(listener);
		}
	}

	public static void AddDrifterRigTypeEventListener(Agent agent, UnityAction<DrifterRigEventType> listener)
	{
		if (TryReturnAnimationTools(agent, out var animationTools))
		{
			animationTools.DrifterRigTypeEvent.AddListener(listener);
		}
	}

	public static void RemoveDrifterRigTypeEventListener(Agent agent, UnityAction<DrifterRigEventType> listener)
	{
		if (TryReturnAnimationTools(agent, out var animationTools))
		{
			animationTools.DrifterRigTypeEvent.RemoveListener(listener);
		}
	}

	private static bool TryReturnAnimator(Agent agent, out Animator animator)
	{
		animator = null;
		if (agent == null || agent.DrifterRig == null || agent.DrifterRig.MeshAnimator == null)
		{
			return false;
		}
		animator = agent.DrifterRig.MeshAnimator.Animator;
		return animator != null;
	}

	private static bool TryReturnAnimationTools(Agent agent, out AnimationTools animationTools)
	{
		animationTools = null;
		if (agent == null || agent.DrifterRig == null)
		{
			return false;
		}
		animationTools = agent.DrifterRig.AnimationTools;
		return animationTools != null;
	}

	public static float ReturnAnimationLength(this Buildable buildable, string name)
	{
		if (TryReturnAnimator(buildable, out var animator))
		{
			return ReturnAnimationLength(animator, name);
		}
		return 0f;
	}

	public static void SetAnimatorInteger(this Buildable buildable, string name, int value)
	{
		if (TryReturnAnimator(buildable, out var animator))
		{
			animator.SetInteger(name, value);
		}
	}

	private static bool TryReturnAnimator(Buildable buildable, out Animator animator)
	{
		animator = null;
		if (buildable == null || buildable.BuildableAnimator == null)
		{
			return false;
		}
		animator = buildable.BuildableAnimator.Animator;
		return animator != null;
	}

	private static float ReturnAnimationLength(Animator animator, string name)
	{
		if (animator.runtimeAnimatorController == null)
		{
			return 0f;
		}
		AnimationClip[] animationClips = animator.runtimeAnimatorController.animationClips;
		foreach (AnimationClip animationClip in animationClips)
		{
			if (animationClip.name == name)
			{
				return animationClip.length;
			}
		}
		return 0f;
	}
}
[Serializable]
public struct AnimatorState : IEquatable<AnimatorState>
{
	public string AgentName;

	public bool Alive;

	public Navigator.TerrainType Terrain;

	public int BoatID;

	public Activity Activity;

	public bool TriggerActivity;

	public int LoopBlocked;

	public int AttributeVariation;

	public AnimatorState(Agent agent, bool triggerActivity, int loopBlock)
	{
		AgentName = agent.Name;
		Navigator.TerrainType terrain = agent.ReturnNavigator(alwaysReturnDrifter: true).Terrain;
		bool flag = terrain == Navigator.TerrainType.UnityNavMesh;
		Terrain = (flag ? Navigator.TerrainType.Construction : terrain);
		Alive = agent.IsAlive;
		Activity = ((agent.CurrentActivity == Activity.Idling && flag) ? Activity.Landmark_Idling : agent.CurrentActivity);
		TriggerActivity = triggerActivity;
		BoatID = -1;
		LoopBlocked = loopBlock;
		AttributeVariation = agent.DrifterRig.AttributeVariation;
		if (Alive && Terrain == Navigator.TerrainType.Vessel && agent.Boat != null)
		{
			BoatID = agent.Boat.BoatAnimationID;
		}
	}

	public bool Equals(AnimatorState other)
	{
		return object.Equals(other, this);
	}

	public bool Equals(Agent agent, bool triggerActivity, int loopBlocked)
	{
		Navigator.TerrainType terrain = agent.ReturnNavigator(alwaysReturnDrifter: true).Terrain;
		terrain = ((terrain == Navigator.TerrainType.UnityNavMesh) ? Navigator.TerrainType.Construction : terrain);
		int boatID = -1;
		if (Alive && Terrain == Navigator.TerrainType.Vessel && agent.Boat != null)
		{
			boatID = agent.Boat.BoatAnimationID;
		}
		return Equals(terrain, agent.IsAlive, agent.CurrentActivity, triggerActivity, boatID, loopBlocked, agent.DrifterRig.AttributeVariation);
	}

	public bool Equals(Navigator.TerrainType terrain, bool alive, Activity activity, bool triggerActivity, int boatID, int loopBlocked, int attributeVariation)
	{
		if (terrain == Terrain && alive == Alive && activity == Activity && triggerActivity == TriggerActivity && boatID == BoatID && loopBlocked == LoopBlocked)
		{
			return attributeVariation == AttributeVariation;
		}
		return false;
	}

	public override bool Equals(object animatorStateObject)
	{
		if (animatorStateObject == null || GetType() != animatorStateObject.GetType())
		{
			return false;
		}
		return ((AnimatorState)animatorStateObject).Equals(Terrain, Alive, Activity, TriggerActivity, BoatID, LoopBlocked, AttributeVariation);
	}

	public static bool operator ==(AnimatorState firstAnimatorState, AnimatorState secondAnimatorState)
	{
		return firstAnimatorState.Equals(secondAnimatorState);
	}

	public static bool operator !=(AnimatorState firstAnimatorState, AnimatorState secondAnimatorState)
	{
		return !firstAnimatorState.Equals(secondAnimatorState);
	}

	public override int GetHashCode()
	{
		return ((17 * 23 + Terrain.GetHashCode()) * 23 + BoatID.GetHashCode()) * 23 + Activity.GetHashCode();
	}
}
[AddComponentMenu("Flotsam/Animation/Buildable Animator")]
[DisallowMultipleComponent]
public class BuildableAnimator : MonoBehaviour
{
	public Animator Animator { get; private set; }

	public void Initialize(Animator animator)
	{
		Animator = animator;
	}

	public void ResetAnimation(string defaultState)
	{
		if (Animator == null)
		{
			return;
		}
		Animator.Play(defaultState);
		for (int i = 0; i < Animator.parameters.Length; i++)
		{
			if (Animator.parameters[i].type == AnimatorControllerParameterType.Int)
			{
				Animator.SetInteger(Animator.parameters[i].name, Animator.parameters[i].defaultInt);
			}
		}
	}

	public void Play(string animationState)
	{
		Animator.Play(animationState);
	}

	public AnimatorStateInfo ReturnCurrentAnimatorClipInfo()
	{
		return Animator.GetCurrentAnimatorStateInfo(0);
	}

	public void RestoreAnimatorState(int shortNameHash, float normalizedTime)
	{
		Animator.Play(shortNameHash, 0, normalizedTime);
	}

	public bool HasParameter(string parameterName)
	{
		if (Animator == null)
		{
			return false;
		}
		AnimatorControllerParameter[] parameters = Animator.parameters;
		for (int i = 0; i < parameters.Length; i++)
		{
			if (parameters[i].name == parameterName)
			{
				return true;
			}
		}
		return false;
	}
}
