public class AssignmentIcon : MonoBehaviour, IPointerClickHandler, IEventSystemHandler, IPointerDownHandler, IPointerEnterHandler, IPointerExitHandler
{
	[Header("General")]
	[SerializeField]
	private Image _backgroundImage;

	[SerializeField]
	private Image _assignmentImage;

	[SerializeField]
	private GUIAudio _GUIAudio;

	[SerializeField]
	private AssignmentTooltip _tooltip;

	[Header("Settings")]
	[SerializeField]
	private Color _normalColor = Color.white;

	[SerializeField]
	private Color _highlightedColor = new Color32(220, 220, 220, byte.MaxValue);

	[SerializeField]
	private Color _pressedColor = new Color32(180, 180, 180, byte.MaxValue);

	private AssignmentType _assignment;

	private AssignmentPanel _assignmentPanel;

	public void Initialize(AssignmentPanel panel, AssignmentSetting settings)
	{
		_assignmentPanel = panel;
		_assignment = settings.Type;
		_assignmentImage.sprite = settings.Sprite;
		_tooltip.Initialize(settings);
	}

	public void OnPointerDown(PointerEventData eventData)
	{
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		StartCoroutine(TemporaryColourCoroutine(_pressedColor));
		if (eventData.button == PointerEventData.InputButton.Middle)
		{
			return;
		}
		_GUIAudio.OnButtonClick();
		if (!(_assignmentPanel == null))
		{
			switch (eventData.button)
			{
			case PointerEventData.InputButton.Left:
				_assignmentPanel.UpdatePriorityForAllEntries(increase: true, _assignment);
				break;
			case PointerEventData.InputButton.Right:
				_assignmentPanel.UpdatePriorityForAllEntries(increase: false, _assignment);
				break;
			}
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		_backgroundImage.color = _highlightedColor;
		AgentEvent.Dispatch(null, _assignment);
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		_backgroundImage.color = _normalColor;
	}

	private IEnumerator TemporaryColourCoroutine(Color color, float time = 0.1f)
	{
		Color saveColor = _backgroundImage.color;
		_backgroundImage.color = color;
		yield return new WaitForSeconds(time);
		_backgroundImage.color = saveColor;
	}
}
public class AssignmentPanel : Panel
{
	[Header("Assignments")]
	[Tooltip("The transform that is parent to the assignment images.")]
	public Transform AssignmentParent;

	[Tooltip("The transform that is parent to the drifter entries.")]
	public Transform EntryParent;

	[Tooltip("The transform that is the parent of the priority template.")]
	public Transform TemplateParent;

	[HideInInspector]
	public List<AssignmentType> DisplayedAssignments = new List<AssignmentType>();

	private List<AssignmentPanelEntry> _entries = new List<AssignmentPanelEntry>();

	private void Start()
	{
		Community.PlayerCommunity.AgentsUpdatedEvent += UpdatePanels;
		for (int i = 0; i < GameManager.Settings.ProjectSettings.AssignmentSettings.Count; i++)
		{
			AssignmentSetting assignmentSetting = GameManager.Settings.ProjectSettings.AssignmentSettings[i];
			if (assignmentSetting.Type != AssignmentType.None)
			{
				AssignmentIcon assignmentIcon = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.AssignmentPrefab, AssignmentParent);
				assignmentIcon.gameObject.name = "Assignment" + assignmentSetting.Type;
				DisplayedAssignments.Add(assignmentSetting.Type);
				assignmentIcon.Initialize(this, assignmentSetting);
			}
		}
		CreateEntry(null, isTemplate: true);
		UpdatePanels();
	}

	private void OnDestroy()
	{
		Community.PlayerCommunity.AgentsUpdatedEvent -= UpdatePanels;
	}

	private void UpdatePanels()
	{
		IEnumerable<Agent> enumerable = _entries.Select((AssignmentPanelEntry assignmentEntry) => assignmentEntry.Drifter);
		List<Agent> agents = Community.PlayerCommunity.Agents;
		List<Agent> list = enumerable.Except(agents).ToList();
		List<Agent> list2 = agents.Except(enumerable).ToList();
		foreach (Agent item in list)
		{
			RemoveEntry(item);
		}
		foreach (AssignmentPanelEntry entry in _entries)
		{
			entry.UpdateEntry();
		}
		foreach (Agent item2 in list2)
		{
			CreateEntry(item2);
		}
	}

	public void UpdatePriorityForAllEntries(bool increase, AssignmentType type)
	{
		foreach (AssignmentPanelEntry entry in _entries)
		{
			entry.UpdatePriority(increase, type);
		}
	}

	private void CreateEntry(Agent agent, bool isTemplate = false)
	{
		AssignmentPanelEntry assignmentPanelEntry = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.AssignmentPanelEntryPrefab, isTemplate ? TemplateParent : EntryParent);
		assignmentPanelEntry.Initialize(agent, this, isTemplate);
		_entries.Add(assignmentPanelEntry);
		if (isTemplate)
		{
			assignmentPanelEntry.DragImage.gameObject.SetActive(value: false);
		}
	}

	private void RemoveEntry(Agent agent)
	{
		AssignmentPanelEntry assignmentPanelEntry = _entries.FirstOrDefault((AssignmentPanelEntry entry) => entry.Drifter == agent);
		if (!(assignmentPanelEntry == null) && !assignmentPanelEntry.IsTemplate)
		{
			_entries.Remove(assignmentPanelEntry);
			UnityEngine.Object.Destroy(assignmentPanelEntry.gameObject);
		}
	}
}
public class AssignmentPanelEntry : MonoBehaviour, IAgentReference
{
	[Header("Agent")]
	[SerializeField]
	[Tooltip("Agent's name.")]
	private TextMeshProUGUI _name;

	[SerializeField]
	private GameObject _selectionHighlight;

	[SerializeField]
	private GameObject _drifterInfoParent;

	[Header("Assignments")]
	[SerializeField]
	[Tooltip("The transform that is parent to the priority boxes.")]
	private Transform _priorityParent;

	[Tooltip("'Burger' Image that indicates this panel is draggable.")]
	[SerializeField]
	public Image DragImage;

	[Header("Prefabs")]
	[SerializeField]
	[Tooltip("Prefab for the priority box.")]
	private GameObject _priorityBoxPrefab;

	[Header("Localization")]
	[SerializeField]
	[Tooltip("Name to put in assignment template.")]
	private LocalizedString _templateName = null;

	private List<AssignmentBox> _assignmentBoxes = new List<AssignmentBox>();

	private DoubleClickDetector _doubleClickDetector = new DoubleClickDetector();

	[HideInInspector]
	public bool IsTemplate;

	private AssignmentPanel AssignmentPanel;

	private Draggable _draggable;

	public Agent Drifter { get; private set; }

	public Agent AgentReference => Drifter;

	public UnityEvent OnAgentUpdated { get; private set; } = new UnityEvent();

	public void Initialize(Agent agent, AssignmentPanel assignmentPanel, bool isTemplate)
	{
		_draggable = GetComponent<Draggable>();
		IsTemplate = isTemplate;
		AssignmentPanel = assignmentPanel;
		base.transform.localScale = Vector3.one;
		if (!IsTemplate)
		{
			Drifter = agent;
			Drifter.OnSelectedEvent.AddListener(OnAgentSelected);
			Drifter.OnDeselectedEvent.AddListener(OnAgentDeselected);
			_selectionHighlight.gameObject.SetActive(Selector.ReturnIsSelected(Drifter.gameObject));
			OnAgentUpdated.Invoke();
			agent.AssignmentPanelEntry = this;
		}
		else
		{
			_draggable.enabled = false;
		}
		_drifterInfoParent.SetActive(!IsTemplate);
		foreach (AssignmentType assignment in assignmentPanel.DisplayedAssignments)
		{
			Transform obj = UnityEngine.Object.Instantiate(_priorityBoxPrefab, _priorityParent).transform;
			obj.name = $"Priority box ({assignment.ToString()})";
			obj.localScale = Vector3.one;
			Assignment assignment2 = null;
			assignment2 = ((!IsTemplate || !ProjectSettings.TryGetAssignmentSettings(out var settings, assignment)) ? agent.Assignments.Find((Assignment asssignmentEntry) => asssignmentEntry.Type == assignment) : new Assignment(settings, GameManager.AgentManager.AssignmentPriorityTemplates[assignment], 0, null));
			AssignmentBox component = obj.GetComponent<AssignmentBox>();
			component.Initialize(agent, assignment2, IsTemplate);
			_assignmentBoxes.Add(component);
		}
		UpdateEntry();
	}

	public void UpdateEntry()
	{
		if (IsTemplate)
		{
			string text = _templateName;
			base.gameObject.name = $"{text} entry";
			_name.text = text;
		}
		else
		{
			string text2 = Drifter.Name;
			base.gameObject.name = $"{text2} entry";
			_name.text = text2;
		}
		foreach (AssignmentBox assignmentBox in _assignmentBoxes)
		{
			assignmentBox.Refresh();
		}
	}

	private void OnDestroy()
	{
		if (Drifter != null)
		{
			Drifter.OnSelectedEvent.RemoveListener(OnAgentSelected);
			Drifter.OnDeselectedEvent.RemoveListener(OnAgentDeselected);
		}
	}

	public void UpdatePriority(bool increase, AssignmentType type)
	{
		if (IsTemplate || Drifter.ReturnAcceptsAssignmentType(type))
		{
			AssignmentBox assignmentBox = _assignmentBoxes.FirstOrDefault((AssignmentBox box) => box.Assignment.Type == type);
			if (assignmentBox == null)
			{
				PajamaLlama.Debugs.Debugger.Error($"Couldn't retrieve assignment box for type {type}.");
				return;
			}
			assignmentBox.UpdatePriority(increase);
			assignmentBox.Refresh();
		}
	}

	public void UpdatePriorityForAllTypes(bool increase)
	{
		foreach (AssignmentType displayedAssignment in AssignmentPanel.DisplayedAssignments)
		{
			if (displayedAssignment != AssignmentType.None)
			{
				UpdatePriority(increase, displayedAssignment);
			}
		}
	}

	public void SelectAgent()
	{
		if (!IsTemplate)
		{
			Selector.Select(Drifter.gameObject, ObjectType.CommunityMember);
			if (_doubleClickDetector.IsDoubleClick())
			{
				CameraController.Instance.Lock(Drifter.gameObject);
			}
		}
	}

	private void OnAgentSelected()
	{
		_selectionHighlight.SetActive(value: true);
	}

	private void OnAgentDeselected()
	{
		_selectionHighlight.SetActive(value: false);
	}
}
[Serializable]
[CreateAssetMenu(menuName = "Flotsam/Assignment")]
public class AssignmentSetting : ScriptableObject
{
	[Header("Text")]
	[Tooltip("Localized text of this assignment.")]
	public LocalizedString Name = "";

	public LocalizedString Description = "";

	public bool AppliesEnabledToAllAgents;

	public bool HideInDutiesPanel;

	[Tooltip("Tooltip that says what this assignment is used in.")]
	public LocalizedString UsedIn = "";

	[Tooltip("Tooltip that shows what attributes this assignment is affected by.")]
	public LocalizedString AffectedBy = "";

	[Space]
	[Tooltip("Type of the assignment.")]
	public AssignmentType Type;

	[Tooltip("Sprite of this assignment.")]
	public Sprite Sprite;

	[Tooltip("List of BuildableProperties this assignment is linked to.")]
	public BuildableProperties[] UsedInProperties;

	[Tooltip("When computing the priority score for this assignment, should only the priority assigned by the player be used? (the order and project priorities will be ignored)")]
	public bool AssingmentPriorityOnly;

	public string GetTooltip(DrifterAttributes drifterAttributes, string tooltip = null)
	{
		if (UsedInProperties.Length != 0)
		{
			tooltip = CombineStrings(tooltip, Regex.Replace(UsedIn, "%BUILDINGS%", UsedInPropertiesToString(", ", UsedInProperties), RegexOptions.IgnoreCase));
		}
		if (drifterAttributes.TryReturnAffectedAttributesText(this, out var text))
		{
			tooltip = CombineStrings(tooltip, Regex.Replace(AffectedBy, "%ATTRIBUTES%", text, RegexOptions.IgnoreCase));
		}
		return tooltip;
	}

	private string CombineStrings(string original, string toAppend)
	{
		if (string.IsNullOrEmpty(original))
		{
			return toAppend;
		}
		return original + "\n\n" + toAppend;
	}

	private string UsedInPropertiesToString(string joiner, BuildableProperties[] properties)
	{
		string text = "";
		bool flag = false;
		foreach (BuildableProperties buildableProperties in properties)
		{
			if (flag)
			{
				text += joiner;
			}
			text += buildableProperties.Name;
			flag = true;
		}
		return text;
	}
}
public class GlobalHaulingPriorities
{
	public int Constructing { get; private set; }

	public int Cooking { get; private set; }

	public int Crafting { get; private set; }

	public int Hauling { get; private set; }

	public int Farming { get; private set; }

	public int AnimalHandling { get; private set; }

	public void Update(List<Assignment> assignments)
	{
		foreach (Assignment assignment in assignments)
		{
			switch (assignment.Type)
			{
			case AssignmentType.Constructing:
				Constructing = assignment.ResourceProviderWeight;
				break;
			case AssignmentType.Cooking:
				Cooking = assignment.ResourceProviderWeight;
				break;
			case AssignmentType.Crafting:
				Crafting = assignment.ResourceProviderWeight;
				break;
			case AssignmentType.Hauling:
				Hauling = assignment.ResourceProviderWeight;
				break;
			case AssignmentType.Farming:
				Farming = assignment.ResourceProviderWeight;
				break;
			case AssignmentType.AnimalHandling:
				AnimalHandling = assignment.ResourceProviderWeight;
				break;
			}
		}
		Constructing = Mathf.Max(Constructing, Hauling);
		Cooking = Mathf.Max(Cooking, Hauling);
		Crafting = Mathf.Max(Crafting, Hauling);
		Farming = Mathf.Max(Farming, Hauling);
		AnimalHandling = Mathf.Max(AnimalHandling, Hauling);
	}
}
