public class FMODEvent
{
	private GameObject _source;

	private EventDescription _eventDescription;

	private FMOD.Studio.EventInstance _instance;

	private bool _isOneShot;

	public EventReference EventReference { get; private set; }

	public AudioClipProperties Properties { get; private set; }

	public FMODEvent(EventReference eventReference)
	{
		EventReference = eventReference;
	}

	public FMODEvent(AudioClipProperties properties)
	{
		Properties = properties;
	}

	public void Dispose()
	{
		if (_instance.isValid())
		{
			RuntimeManager.DetachInstanceFromGameObject(_instance);
			if (_eventDescription.isValid() && _isOneShot)
			{
				_instance.release();
				_instance.clearHandle();
			}
		}
	}

	public bool Start(GameObject source = null)
	{
		if (!_eventDescription.isValid() && !TryReturnEventDescription(out _eventDescription))
		{
			return false;
		}
		bool is3D = false;
		_eventDescription.isSnapshot(out var snapshot);
		if (!snapshot)
		{
			_eventDescription.isOneshot(out _isOneShot);
		}
		if (source != null)
		{
			_eventDescription.is3D(out is3D);
		}
		if (_instance.isValid())
		{
			if (_isOneShot)
			{
				_instance.release();
				_instance.clearHandle();
			}
		}
		else
		{
			_instance.clearHandle();
		}
		if (!_instance.isValid())
		{
			_eventDescription.createInstance(out _instance);
			if (is3D)
			{
				Rigidbody component = source.GetComponent<Rigidbody>();
				Transform transform = source.transform;
				_source = source;
				_instance.set3DAttributes(RuntimeUtils.To3DAttributes(transform, component));
				RuntimeManager.AttachInstanceToGameObject(_instance, transform, component);
			}
		}
		_instance.start();
		return true;
	}

	public void Pause()
	{
		if (ReturnIsPlaying())
		{
			Pause(paused: true);
		}
	}

	public void Unpause(bool start = false)
	{
		if (ReturnIsPlaying())
		{
			Pause(paused: false);
		}
		else if (start)
		{
			Start();
		}
	}

	private void Pause(bool paused)
	{
		if (_instance.isValid())
		{
			_instance.getPaused(out var paused2);
			if (paused2 != paused)
			{
				_instance.setPaused(paused);
			}
		}
	}

	public void Stop()
	{
		if (_instance.isValid())
		{
			_instance.stop(FMOD.Studio.STOP_MODE.ALLOWFADEOUT);
			_instance.release();
			_instance.clearHandle();
		}
	}

	public bool ReturnIsPlaying()
	{
		if (_instance.isValid())
		{
			_instance.getPlaybackState(out var state);
			return state != PLAYBACK_STATE.STOPPED;
		}
		return false;
	}

	private bool TryReturnEventDescription(out EventDescription eventDescription)
	{
		if (!EventReference.IsNull)
		{
			RuntimeUtils.EnforceLibraryOrder();
			eventDescription = RuntimeManager.GetEventDescription(EventReference);
			return eventDescription.isValid();
		}
		if (Properties != null)
		{
			return Properties.TryReturnFMODEventDescription(out eventDescription);
		}
		eventDescription = default(EventDescription);
		return false;
	}
}
public class FMODEventEmitter : MonoBehaviour
{
	private bool _initialized;

	private bool _isQuitting;

	private Dictionary<string, FMODEvent> _events;

	private Dictionary<AudioClipProperties, FMODEvent> _audioClipPropertiesEvents;

	private void Start()
	{
		Initialize();
	}

	private void Initialize()
	{
		if (!_initialized)
		{
			RuntimeUtils.EnforceLibraryOrder();
			_events = new Dictionary<string, FMODEvent>(5);
			_audioClipPropertiesEvents = new Dictionary<AudioClipProperties, FMODEvent>(5);
		}
	}

	private void OnDestroy()
	{
		if (!_isQuitting && !_audioClipPropertiesEvents.IsNullOrEmpty())
		{
			Dictionary<AudioClipProperties, FMODEvent>.Enumerator enumerator = _audioClipPropertiesEvents.GetEnumerator();
			while (enumerator.MoveNext())
			{
				enumerator.Current.Value.Dispose();
			}
			_audioClipPropertiesEvents.Clear();
		}
	}

	private void OnApplicationQuit()
	{
		_isQuitting = true;
	}

	public bool Play(AudioClipProperties properties, GameObject source = null)
	{
		Initialize();
		if (!_audioClipPropertiesEvents.TryGetValue(properties, out var value))
		{
			value = new FMODEvent(properties);
			_audioClipPropertiesEvents.Add(properties, value);
		}
		return value.Start((source == null) ? base.gameObject : source);
	}

	public bool StopAllAndPlay(AudioClipProperties properties, GameObject source = null)
	{
		Stop();
		return Play(properties, source);
	}

	public void Pause(AudioClipProperties properties)
	{
		if (_audioClipPropertiesEvents != null && _audioClipPropertiesEvents.TryGetValue(properties, out var value))
		{
			value.Pause();
		}
	}

	public void Stop(AudioClipProperties properties)
	{
		if (_audioClipPropertiesEvents != null && _audioClipPropertiesEvents.TryGetValue(properties, out var value))
		{
			value.Stop();
		}
	}

	public bool Emit(EventReference eventReference, GameObject source = null)
	{
		if (eventReference.IsNull)
		{
			return false;
		}
		Initialize();
		string key = eventReference.ToString();
		if (!_events.TryGetValue(key, out var value))
		{
			value = new FMODEvent(eventReference);
			_events.Add(key, value);
		}
		return value.Start((source == null) ? base.gameObject : source);
	}

	public void Stop(EventReference eventReference)
	{
		if (!eventReference.IsNull && !_events.IsNullOrEmpty() && _events.TryGetValue(eventReference.ToString(), out var value))
		{
			value.Stop();
		}
	}

	public void Stop()
	{
		if (!_isQuitting && _audioClipPropertiesEvents != null)
		{
			Dictionary<AudioClipProperties, FMODEvent>.Enumerator enumerator = _audioClipPropertiesEvents.GetEnumerator();
			while (enumerator.MoveNext())
			{
				enumerator.Current.Value.Stop();
			}
		}
	}

	public bool ReturnIsPlaying(EventReference eventReference)
	{
		if (_events.TryGetValue(eventReference.ToString(), out var value))
		{
			return value.ReturnIsPlaying();
		}
		return false;
	}

	public bool ReturnIsPlaying(AudioClipProperties properties)
	{
		if (_audioClipPropertiesEvents == null)
		{
			return false;
		}
		if (_audioClipPropertiesEvents.TryGetValue(properties, out var value))
		{
			return value.ReturnIsPlaying();
		}
		return false;
	}
}
public static class FMODManager
{
	private static VCA _masterVCA;

	private static VCA _musicVCA;

	private static VCA _uiVCA;

	private static VCA _sfxVCA;

	public static bool IsInitialized => RuntimeManager.IsInitialized;

	public static void ApplyAudioPlayerData(AudioPlayerData audioPlayerData)
	{
		SetMasterVolume(audioPlayerData.MasterVolume);
		SetMusicVolume(audioPlayerData.MusicVolume);
		SetUIVolume(audioPlayerData.UIVolume);
		SetSFXVolume(audioPlayerData.SFXVolume);
	}

	public static void SetAllVolumeLevels(float volume)
	{
		SetMasterVolume(volume);
		SetMusicVolume(volume);
		SetUIVolume(volume);
		SetSFXVolume(volume);
	}

	public static void SetMasterVolume(float volume)
	{
		if (_masterVCA.handle == IntPtr.Zero)
		{
			_masterVCA = RuntimeManager.GetVCA("vca:/master");
		}
		_masterVCA.setVolume(Mathf.Clamp(volume, 0f, 1f));
	}

	public static void SetMusicVolume(float volume)
	{
		if (_musicVCA.handle == IntPtr.Zero)
		{
			_musicVCA = RuntimeManager.GetVCA("vca:/music");
		}
		_musicVCA.setVolume(Mathf.Clamp(volume, 0f, 1f));
	}

	public static void SetUIVolume(float volume)
	{
		if (_uiVCA.handle == IntPtr.Zero)
		{
			_uiVCA = RuntimeManager.GetVCA("vca:/ui");
		}
		_uiVCA.setVolume(Mathf.Clamp(volume, 0f, 1f));
	}

	public static void SetSFXVolume(float volume)
	{
		if (_sfxVCA.handle == IntPtr.Zero)
		{
			_sfxVCA = RuntimeManager.GetVCA("vca:/sfx");
		}
		_sfxVCA.setVolume(Mathf.Clamp(volume, 0f, 1f));
	}
}
[Serializable]
public class FMODParameter
{
	[ParamRef]
	[SerializeField]
	private string _parameter;

	private RESULT _result;

	private PARAMETER_DESCRIPTION _parameterDescription;

	private bool Initialize()
	{
		if (string.IsNullOrEmpty(_parameterDescription.name))
		{
			if (_result == RESULT.OK)
			{
				_result = RuntimeManager.StudioSystem.getParameterDescriptionByName(_parameter, out _parameterDescription);
				if (_result == RESULT.OK)
				{
					return true;
				}
				UnityEngine.Debug.LogErrorFormat("Initialization of FMODParameter '{0}' intialization failed with result: {1}", _parameter, _result);
			}
			return false;
		}
		return true;
	}

	public void SetValue(float value)
	{
		if (Initialize())
		{
			RuntimeManager.StudioSystem.setParameterByID(_parameterDescription.id, value);
		}
	}
}
public class FMODUIEventEmitter : FMODEventEmitter
{
	private static FMODUIEventEmitter _instance;

	public static bool PlayAudioClipProperties(AudioClipProperties audioClipProperties)
	{
		FMODUIEventEmitter instance = GetInstance();
		if (audioClipProperties == null || (audioClipProperties.Loop && instance.ReturnIsPlaying(audioClipProperties)))
		{
			return false;
		}
		return instance.Play(audioClipProperties);
	}

	public static void PauseAudioClipProperties(AudioClipProperties audioClipProperties)
	{
		if ((bool)audioClipProperties && audioClipProperties.Loop)
		{
			GetInstance().Pause(audioClipProperties);
		}
	}

	public static void StopAudioClipProperties(AudioClipProperties audioClipProperties)
	{
		if ((bool)audioClipProperties && audioClipProperties.Loop)
		{
			GetInstance().Stop(audioClipProperties);
		}
	}

	public static bool PlayEventReferenceUnique(EventReference eventReference)
	{
		FMODUIEventEmitter instance = GetInstance();
		if (instance.ReturnIsPlaying(eventReference))
		{
			return false;
		}
		return instance.Emit(eventReference);
	}

	public static void StopEventReference(EventReference eventReference)
	{
		GetInstance().Stop(eventReference);
	}

	private static FMODUIEventEmitter GetInstance()
	{
		if (_instance == null)
		{
			_instance = new GameObject().AddComponent<FMODUIEventEmitter>();
		}
		return _instance;
	}
}
public class GUIAudio : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerClickHandler, ISelectHandler, ISubmitHandler
{
	[Tooltip("The audio clip played when either a button is clicked")]
	[SerializeField]
	[FormerlySerializedAs("_guiClickActivate")]
	private AudioClipProperties _onClick;

	[Tooltip("The audio clip played when a toggle is turned on. Defaults to 'On Click' if null.")]
	[SerializeField]
	private AudioClipProperties _onToggleOn;

	[Tooltip("The audio clip played when toggle is turned off. Default to 'On Toggle On' if null.")]
	[SerializeField]
	private AudioClipProperties _onToggleOff;

	[Tooltip("This is the sound that plays when you hover over this GUI element.")]
	[SerializeField]
	[FormerlySerializedAs("_guiHoverAudio")]
	private AudioClipProperties _onPointerEnter;

	[Tooltip("The audio clip played when OnSubmit is triggered. Defaults to 'On Click' if null.")]
	[SerializeField]
	[ConditionalHide("_submitUsesOnClick", HideInInspector = true, Inverse = true)]
	private AudioClipProperties _onSubmit;

	[Tooltip("The audio clip played when OnSelected is triggered. Defaults to 'On Trigger Enter' if null")]
	[SerializeField]
	[ConditionalHide("_onSelectUsesOnPointerEnter", HideInInspector = true, Inverse = true)]
	private AudioClipProperties _onSelect;

	[Tooltip("Audioclip properties to play on the creation of this object.")]
	[SerializeField]
	private AudioClipProperties _onCreation;

	[Tooltip("Audioclip properties to play when a player clicks on something without being able to use it.")]
	[SerializeField]
	private AudioClipProperties _guiClickError;

	[Tooltip("Audiocilp properties to play when the object is enabled.")]
	[SerializeField]
	private AudioClipProperties _onEnable;

	private UIInteractableToggle _menuToggleComp;

	private Toggle _toggle;

	private UIInteractableToggle _uiInteractableToggle;

	private Button _button;

	private void Start()
	{
		if (_onToggleOn == null)
		{
			_onToggleOn = _onClick;
		}
		if (_onToggleOff == null)
		{
			_onToggleOff = _onToggleOn;
		}
		if (_onSubmit == null)
		{
			_onSubmit = _onClick;
		}
		if (_onSelect == null)
		{
			_onSelect = _onPointerEnter;
		}
		_button = GetComponent<Button>();
		if ((bool)_button)
		{
			_button.onClick.AddListener(OnButtonClick);
		}
		_toggle = GetComponent<Toggle>();
		if ((bool)_toggle)
		{
			_toggle.onValueChanged.AddListener(OnToggleValueChanged);
		}
		_uiInteractableToggle = GetComponent<UIInteractableToggle>();
		if ((bool)_uiInteractableToggle)
		{
			_uiInteractableToggle.ToggleUpdatedEvent += PlayGUIClickMenuToggle;
		}
		Play(_onCreation);
	}

	private void OnEnable()
	{
		Play(_onEnable);
	}

	private void OnDestroy()
	{
		if ((bool)_toggle)
		{
			_toggle.onValueChanged.RemoveListener(OnToggleValueChanged);
		}
		if ((bool)_uiInteractableToggle)
		{
			_uiInteractableToggle.ToggleUpdatedEvent -= PlayGUIClickMenuToggle;
		}
		if ((bool)_button)
		{
			_button.onClick.RemoveListener(OnButtonClick);
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		Play(_onPointerEnter);
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (!_button)
		{
			Play(_onClick);
		}
	}

	public void OnSelect(BaseEventData eventData)
	{
		Play(_onPointerEnter);
	}

	public void OnSubmit(BaseEventData eventData)
	{
		Play(_onSubmit);
	}

	public void OnButtonClick()
	{
		Play(_onClick);
	}

	public void OnToggleValueChanged(bool value)
	{
		if (value)
		{
			Play(_onToggleOn);
		}
		else
		{
			Play(_onToggleOff);
		}
	}

	public void PlayGUIClickError()
	{
		Play(_guiClickError);
	}

	public void PlayGUIClickMenuToggle()
	{
		OnToggleValueChanged((bool)_menuToggleComp && _menuToggleComp.IsOn);
	}

	private void Play(AudioClipProperties audioClipProperties)
	{
		if ((bool)audioClipProperties)
		{
			AudioManager.Play(audioClipProperties);
		}
	}
}
