	{
		bool num = !base.RequiresMooringPoint || community.IsThereAMooringPointFree();
		bool flag = ReturnBuildableRequirement(community);
		bool flag2 = !checkResources || ResourceManager.AreCommunityResourcesAvailable(((IReadOnlyCollection<CountedItemProperty>)(object)base.RequiredResources).IsNullOrEmpty() ? PlacementCursorProperties.ReturnRequiredResources(this) : base.RequiredResources);
		bool flag3 = base.IgnoreWeightForPlacement || Engine.CanTug(this);
		return num && flag && flag2 && flag3;
	}

