[RequireComponent(typeof(MeshRenderer), typeof(MeshFilter))]
public class BuildingGrid : SceneBehaviour
{
	[SerializeField]
	private VisualBoundary _gridBoundary;

	public float HeightOffset = 0.25f;

	[Header("Debug")]
	[SerializeField]
	private Vector2 _debugGridOffset = new Vector2(0f, 5f);

	[SerializeField]
	private int _debugGridWidth = 10;

	[SerializeField]
	private int _debugGridHeight = 10;

	private static BuildingGrid _instance;

	private MeshRenderer _meshRenderer;

	private MeshFilter _meshFilter;

	private Material _material;

	private Mesh _mesh;

	private Color[] _colors;

	private List<Vector2[]> _polygons;

	private List<Vector2[]> _localPolygons;

	private int _currentWidth;

	private int _currentHeight;

	private Vector2 _evenOffset = Vector2.zero;

	private Vector2 _unevenOffset = Vector2.zero;

	private Rect _localRectangle;

	private Rect _axisAlignedRect;

	public bool IsOn { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if (_instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
		_instance = this;
		_meshRenderer = base.gameObject.GetComponent<MeshRenderer>();
		_material = _meshRenderer.material;
		_meshFilter = base.gameObject.GetComponent<MeshFilter>();
		GameEventDispatcher.AddListener(GameEventType.ShowBuildGridSettingUpdated, OnGridSettingUpdated);
		IsOn = false;
		base.gameObject.SetActive(value: false);
	}

	private void OnDestroy()
	{
		if (_instance == this)
		{
			_instance = null;
		}
		GameEventDispatcher.RemoveListener(GameEventType.ShowBuildGridSettingUpdated, OnGridSettingUpdated);
	}

	[ContextMenu("Generate")]
	public void DebugGenerate()
	{
		_meshRenderer = base.gameObject.GetComponent<MeshRenderer>();
		_meshFilter = base.gameObject.GetComponent<MeshFilter>();
		_currentHeight = 0;
		_currentWidth = 0;
		Generate(_debugGridWidth, _debugGridHeight, _debugGridOffset);
	}

	public void Generate(int width, int height, Vector2 offset)
	{
		if (_currentWidth != width || _currentHeight != height)
		{
			_currentHeight = height;
			_currentWidth = width;
			if (width / 2 % 2 == 0)
			{
				_evenOffset = new Vector2(0.5f, 0.5f);
				_unevenOffset = new Vector2(0f, 0.5f);
			}
			else
			{
				_evenOffset = new Vector2(0f, 0.5f);
				_unevenOffset = new Vector2(0.5f, 0.5f);
			}
			_gridBoundary.SetSize((float)width / 2f, (float)height / 2f);
			_gridBoundary.transform.localPosition = offset.Vector3TopDown();
			_mesh = GenerateMesh(width, height, offset, ref _localPolygons, ref _polygons, ref _localRectangle);
			_meshFilter.mesh = _mesh;
			int gridSize = GameSettings.Instance.BuildableSettings.GridSize;
			_material.SetTextureScale("_Grid", new Vector2(width * gridSize / 2, height * gridSize / 2));
		}
	}

	public Mesh GenerateMesh(int width, int height, Vector2 offset, ref List<Vector2[]> localPolygons, ref List<Vector2[]> polygons, ref Rect localRectangle)
	{
		Mesh mesh = new Mesh();
		int gridSize = GameSettings.Instance.BuildableSettings.GridSize;
		int num = height * width;
		int num2 = num * 4;
		int num3 = num * 6;
		localPolygons = new List<Vector2[]>(num2);
		polygons = new List<Vector2[]>(num2);
		Vector3[] array = new Vector3[num2];
		Vector2[] array2 = new Vector2[num2];
		Vector3[] array3 = new Vector3[num2];
		int[] array4 = new int[num3];
		_colors = new Color[num2];
		int num4 = 0;
		float num5 = gridSize * width;
		float num6 = gridSize * height;
		Vector3 vector = new Vector3(num5 / 2f + offset.x, 0f, (0f - num6) / 2f + offset.y);
		Vector3 vector2 = new Vector3(0f, 0f, 1f);
		Vector3 vector3 = new Vector3(1f, 0f, 0f);
		localRectangle = new Rect(new Vector2((0f - num5) / 2f + offset.x, (0f - num6) / 2f + offset.y), new Vector2(num5, num6));
		float num7 = 1f / (float)height;
		float num8 = 1f / (float)width;
		for (int i = 0; i < height; i++)
		{
			Vector3 vector4 = vector + i * gridSize * vector2;
			Vector3 vector5 = vector + (i + 1) * gridSize * vector2;
			for (int j = 0; j < width; j++)
			{
				Vector2[] array5 = new Vector2[4];
				localPolygons.Add(array5);
				Vector2[] array6 = new Vector2[4];
				polygons.Add(array6);
				int num9 = num4 * 4;
				int num10 = num4 * 6;
				int num11 = num9;
				Vector3 vector6 = vector4 - vector3 * gridSize * j;
				Vector3 vector7 = base.transform.TransformPoint(vector6);
				array[num11] = vector6;
				Color white = Color.white;
				if (i == 0 || j == 0)
				{
					white.g = 0f;
				}
				_colors[num11] = white;
				array5[0] = vector6.Vector2TopDown();
				array6[0] = vector7.Vector2TopDown();
				num11 = num9 + 1;
				vector6 = vector4 - vector3 * gridSize * (j + 1);
				vector7 = base.transform.TransformPoint(vector6);
				array[num11] = vector6;
				white = Color.white;
				if (i == 0 || j == width - 1)
				{
					white.g = 0f;
				}
				_colors[num11] = white;
				array5[1] = vector6.Vector2TopDown();
				array6[1] = vector7.Vector2TopDown();
				num11 = num9 + 2;
				vector6 = vector5 - vector3 * gridSize * j;
				vector7 = base.transform.TransformPoint(vector6);
				array[num11] = vector6;
				white = Color.white;
				if (i == height - 1 || j == 0)
				{
					white.g = 0f;
				}
				_colors[num11] = white;
				array5[2] = vector6.Vector2TopDown();
				array6[2] = vector7.Vector2TopDown();
				num11 = num9 + 3;
				vector6 = vector5 - vector3 * gridSize * (j + 1);
				vector7 = base.transform.TransformPoint(vector6);
				array[num11] = vector6;
				white = Color.white;
				if (i == height - 1 || j == width - 1)
				{
					white.g = 0f;
				}
				_colors[num11] = white;
				array5[3] = vector6.Vector2TopDown();
				array6[3] = vector7.Vector2TopDown();
				int num12 = i + 1;
				int num13 = j + 1;
				array2[num9] = new Vector2((float)j * num8, (float)i * num7);
				array2[num9 + 1] = new Vector2((float)num13 * num8, (float)i * num7);
				array2[num9 + 2] = new Vector2((float)j * num8, (float)num12 * num7);
				array2[num9 + 3] = new Vector2((float)num13 * num8, (float)num12 * num7);
				array3[num9] = Vector3.up;
				array3[num9 + 1] = Vector3.up;
				array3[num9 + 2] = Vector3.up;
				array3[num9 + 3] = Vector3.up;
				array4[num10] = num9 + 2;
				array4[num10 + 1] = num9 + 1;
				array4[num10 + 2] = num9 + 3;
				array4[num10 + 3] = num9;
				array4[num10 + 4] = num9 + 1;
				array4[num10 + 5] = num9 + 2;
				num4++;
			}
		}
		mesh.vertices = array;
		mesh.uv = array2;
		mesh.normals = array3;
		mesh.triangles = array4;
		mesh.SetColors(_colors);
		mesh.RecalculateNormals();
		return mesh;
	}

	private void RecalculateGridPositions()
	{
		if (!base.gameObject.activeSelf || _polygons == null || _localPolygons == null)
		{
			return;
		}
		if (_polygons.Count != _localPolygons.Count)
		{
			throw new NotImplementedException();
		}
		Vector2[] array = new Vector2[4]
		{
			base.transform.TransformPoint(new Vector2(_localRectangle.xMin, _localRectangle.yMin).Vector3TopDown()).Vector2TopDown(),
			base.transform.TransformPoint(new Vector2(_localRectangle.xMin, _localRectangle.yMax).Vector3TopDown()).Vector2TopDown(),
			base.transform.TransformPoint(new Vector2(_localRectangle.xMax, _localRectangle.yMin).Vector3TopDown()).Vector2TopDown(),
			base.transform.TransformPoint(new Vector2(_localRectangle.xMax, _localRectangle.yMax).Vector3TopDown()).Vector2TopDown()
		};
		_axisAlignedRect = Rect.MinMaxRect(Mathf.Min(array[0].x, array[1].x, array[2].x, array[3].x), Mathf.Min(array[0].y, array[1].y, array[2].y, array[3].y), Mathf.Max(array[0].x, array[1].x, array[2].x, array[3].x), Mathf.Max(array[0].y, array[1].y, array[2].y, array[3].y));
		for (int i = 0; i < _localPolygons.Count; i++)
		{
			Vector2[] array2 = _polygons[i];
			Vector2[] array3 = _localPolygons[i];
			if (array2.Length != array3.Length)
			{
				throw new NotImplementedException();
			}
			for (int j = 0; j < array3.Length; j++)
			{
				array2[j] = base.transform.TransformPoint(array3[j].Vector3TopDown()).Vector2TopDown();
			}
		}
	}

	private void UpdateCollisions()
	{
		if (!base.gameObject.activeSelf || _polygons == null || _localPolygons == null)
		{
			return;
		}
		RecalculateGridPositions();
		bool flag = false;
		int count = _polygons.Count;
		List<Buildable> list = new List<Buildable>();
		foreach (Buildable buildable in Community.PlayerCommunity.Buildables)
		{
			if (buildable.BlockingPolygon.ReturnIsAxisAllignedRectangleOverlapping(_axisAlignedRect.min, _axisAlignedRect.max))
			{
				buildable.BlockingPolygon.FastUpdate();
				list.Add(buildable);
			}
		}
		for (int i = 0; i < count; i++)
		{
			flag = false;
			Vector2[] vertices = _polygons[i];
			foreach (Buildable item in list)
			{
				if (item.BlockingPolygon.ReturnArePolygonsOverlapping(vertices, includeTolerance: true))
				{
					flag = true;
					break;
				}
			}
			int num = i * 4;
			for (int j = 0; j < 4; j++)
			{
				_colors[num + j].r = (flag ? 1f : 0f);
			}
		}
		_mesh.SetColors(_colors);
		_mesh.RecalculateNormals();
	}

	public void SetTextureOffset(bool even)
	{
		Vector2 value = (even ? _evenOffset : _unevenOffset);
		_meshRenderer.sharedMaterial.SetTextureOffset("_Grid", value);
	}

	private void OnGridSettingUpdated(GameEvent gameEvent)
	{
		if (Settings.Instance.GameplayPlayerData.ShowBuildingGrid)
		{
			base.gameObject.SetActive(IsOn);
			if (IsOn)
			{
				UpdateCollisions();
			}
		}
		else
		{
			base.gameObject.SetActive(value: false);
		}
	}

	public static void SetPlacement(Vector3 position, Hookable.Hook hook)
	{
		int gridIndex;
		Vector3 position2 = hook.ReturnPosition(position.Leveled(), snap: true, out gridIndex);
		Quaternion rotation = Quaternion.LookRotation(hook.Forward);
		SetPlacement(position2, rotation, gridIndex);
	}

	public static void SetPlacement(Vector3 position, Quaternion rotation, int gridIndex)
	{
		if (!(_instance == null))
		{
			Transform obj = _instance.transform;
			obj.position = position.SetY(_instance.HeightOffset);
			obj.rotation = rotation;
			_instance.SetTextureOffset(gridIndex % 2 == 0);
			_instance.UpdateCollisions();
		}
	}

	public static void Enable(BuildableProperties buildingProperties)
	{
		Enable(buildingProperties.Width, buildingProperties.Depth);
	}

	public static void Enable(int gridWidth, int gridHeight)
	{
		if (!(_instance == null))
		{
			int num = GameSettings.Instance.BuildableSettings.GridWidthDisplayPadding * 2;
			int gridHeightDisplayPadding = GameSettings.Instance.BuildableSettings.GridHeightDisplayPadding;
			int num2 = gridWidth * 2;
			int num3 = gridHeight * 2;
			Vector2 offset = new Vector2(0f, (float)(-gridHeightDisplayPadding - num3) / 2f);
			_instance.IsOn = true;
			_instance.gameObject.SetActive(Settings.Instance.GameplayPlayerData.ShowBuildingGrid ? true : false);
			_instance.Generate(num2 + num, num3 + gridHeightDisplayPadding, offset);
		}
	}

	public static void Disable()
	{
		if (!(_instance == null))
		{
			_instance.IsOn = false;
			_instance.gameObject.SetActive(value: false);
		}
	}
}
public class ConstructibleStatus
{
	public System.Action OnMalfunctionsUpdated;

	private WorldIconHandler _worldIconHandler;

	private readonly List<PlaceableAlertProperties> _malfunctions = new List<PlaceableAlertProperties>();

	private bool _malfunctionsUpdated;

	public PlaceableAlertProperties Status { get; private set; }

	public void Initialize(WorldIconHandler worldIconHandler)
	{
		_worldIconHandler = worldIconHandler;
		UpdateWorldIcons();
	}

	private void UpdateWorldIcons()
	{
		using ListPool<PlaceableAlertProperties>.List list = ListPool<PlaceableAlertProperties>.Get();
		PopulateMalfunctions(list, PlaceableAlertProperties.AlertType.Major);
		if (!(_worldIconHandler == null))
		{
			_worldIconHandler.ClearAllIcons();
			if (list.Count > 1)
			{
				_worldIconHandler.AddIcon(GameSettings.Instance.BuildableSettings.MultipleMalfunctionsIconProperties);
			}
			else if (list.Count == 1)
			{
				_worldIconHandler.AddIcon(list[0]);
			}
			else if ((bool)Status && Status.Alert == PlaceableAlertProperties.AlertType.Major)
			{
				_worldIconHandler.AddIcon(Status);
			}
		}
	}

	public void SetStatus(PlaceableAlertProperties status)
	{
		if (!(Status == status))
		{
			Status = status;
			UpdateWorldIcons();
			FlagMalfunctionsUpdated();
		}
	}

	public void AddMalfunction(PlaceableAlertProperties properties)
	{
		if (_malfunctions.AddUnique(properties))
		{
			FlagMalfunctionsUpdated();
		}
	}

	public void RemoveMalfunction(PlaceableAlertProperties properties)
	{
		if (_malfunctions.Remove(properties))
		{
			FlagMalfunctionsUpdated();
		}
	}

	public void RemoveAllMalfunctions()
	{
		if (_malfunctions.Count > 0)
		{
			_malfunctions.Clear();
			FlagMalfunctionsUpdated();
		}
	}

	public void FlagMalfunctionsUpdated()
	{
		if (!_malfunctionsUpdated)
		{
			_malfunctionsUpdated = true;
			FinalUpdate.RegisterEndOfFrameOneShot(UpdateMalfunctions);
		}
	}

	private void UpdateMalfunctions()
	{
		_malfunctionsUpdated = false;
		UpdateWorldIcons();
		OnMalfunctionsUpdated.SafeInvoke();
	}

	public void PopulateMalfunctions(List<PlaceableAlertProperties> malfunctions, PlaceableAlertProperties.AlertType minimumAlertType = PlaceableAlertProperties.AlertType.Minor)
	{
		foreach (PlaceableAlertProperties malfunction in _malfunctions)
		{
			if (minimumAlertType <= malfunction.Alert)
			{
				malfunctions.Add(malfunction);
			}
		}
	}
}
public enum BuildPhase
{
	Build,
	Finished,
	Deconstructing,
	SalvageShutdown,
	HaulTo,
	HaulFrom,
	UpgradeShutdown,
	UpgradeHaulTo,
	UpgradeHaulFrom
}
public class ConstructionHandler
{
	public Action<float> OnProgressUpdated;

	private WeakReference<IConstructible> _owner;

	private PlaceableProperties _properties;

	private ConstructibleStatus _status;

	private Inventory _inventory;

	private ResourceProvider _resourceProvider;

	private int _assignmentLimit = 1;

	public BuildPhase BuildPhase { get; private set; }

	public bool CancelConstructionAfterHaul { get; private set; }

	public float Progress { get; private set; }

	public Project AssignedProject { get; private set; }

	public int AssignmentLimit
	{
		get
		{
			if (AssignedProject == null || !AssignedProject.Properties.AllowAgentLimitOverride)
			{
				return _assignmentLimit;
			}
			return AssignedProject.AssignmentLimit;
		}
		set
		{
			value = Mathf.Max(1, value);
			if (AssignedProject != null && AssignedProject.Properties.AllowAgentLimitOverride)
			{
				if (AssignedProject.Properties.AllowAgentLimitOverride)
				{
					AssignedProject.AssignmentLimit = value;
				}
			}
			else
			{
				_assignmentLimit = value;
			}
		}
	}

	public bool IsInitialized => _owner != null;

	public void Start()
	{
		if (BuildPhase == BuildPhase.HaulFrom)
		{
			EndSalvaging();
		}
		if (BuildPhase == BuildPhase.HaulTo && (bool)_properties && _properties.HaulToConstructibleProjectProperties.IsGlobal && !_inventory.HasIncomingItems(SubInventoryType.Composition))
		{
			if (_inventory.ReturnCompositionProgress() < 1f)
			{
				StartSalvaging();
			}
			else
			{
				FinishBuilding();
			}
		}
	}

	public void Initialize(IConstructible owner)
	{
		_owner = new WeakReference<IConstructible>(owner);
		_properties = owner.Properties;
		_status = owner.StatusHolder;
		_inventory = owner.Inventory;
		_inventory.CompositionUpdatedEvent += OnCompositionUpdatedEvent;
	}

	~ConstructionHandler()
	{
		if (AssignedProject != null)
		{
			AssignedProject.ProjectAssignmentsUpdated.RemoveListener(UpdateBuildPhaseStatus);
			AssignedProject.FinishedEvent.RemoveListener(OnAssignedProjectFinished);
		}
		_inventory.CompositionUpdatedEvent -= OnCompositionUpdatedEvent;
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, FinishBuilding);
	}

	public void StartBuilding(bool instantFreeBuild = false)
	{
		if (instantFreeBuild || BuildingDevTools.InstantBuild)
		{
			ChangeBuildPhase(BuildPhase.Build);
			_inventory.FillComposition(_properties.RequiredResources);
			FinishBuilding();
		}
		else
		{
			StartConstructionProject();
		}
	}

	public void TryToSalvage()
	{
		if (_owner.TryGetTarget(out var target) && target.CanBeSalvaged())
		{
			StartSalvaging();
		}
	}

	public void CancelSalvaging()
	{
		if (BuildPhase == BuildPhase.HaulTo)
		{
			CancelConstructionAfterHaul = false;
			UpdateBuildPhaseStatus();
			return;
		}
		if (BuildPhase == BuildPhase.SalvageShutdown)
		{
			FinishBuilding();
			return;
		}
		BuildPhase buildPhase = BuildPhase;
		if (buildPhase != BuildPhase.Deconstructing && buildPhase != BuildPhase.HaulFrom)
		{
			return;
		}
		using ListPool<Agent>.List list = ListPool<Agent>.Get();
		if (AssignedProject != null)
		{
			AssignedProject.ReturnAssignedAgents(list);
			AssignedProject.Stop(ProjectFlags.Cancelled);
		}
		_inventory.InventoryUpdatedEvent.RemoveListener(EndSalvaging);
		if (_owner.TryGetTarget(out var target))
		{
			target.DetachBuildingAgents();
		}
		foreach (Agent item in list)
		{
			item.ReturnNavigator().AttachToTarget(item.ReturnClosestConstruction(onlyFinished: true).Target, overrideCheck: true);
		}
		if (Mathf.Approximately(Progress, 1f))
		{
			FinishBuilding();
		}
		else
		{
			BuildConstructible();
		}
	}

	private void StartConstructionProject()
	{
		if (!_owner.TryGetTarget(out var target))
		{
			UnityEngine.Debug.LogException(new NullReferenceException("Trying to start constructing a constructible but ConstructionHandler's owner is null!"));
			return;
		}
		using ListPool<CountedItemProperty>.List list = ListPool<CountedItemProperty>.Get();
		CountedItemProperty[] requiredResources = _properties.RequiredResources;
		foreach (CountedItemProperty countedItemProperty in requiredResources)
		{
			ItemProperties itemProperties = countedItemProperty.ItemProperties;
			int num = countedItemProperty.Amount - _inventory.ReturnCount(countedItemProperty.ItemProperties, SubInventoryType.Resources) - _inventory.ReturnCount(countedItemProperty.ItemProperties, SubInventoryType.Composition);
			if (num > 0)
			{
				list.Add(new CountedItemProperty(itemProperties, num));
			}
		}
		List<Item> list2 = ((list.Count > 0) ? ResourceManager.ReserveClosestItems(target, list) : null);
		if (_properties.HaulToConstructibleProjectProperties.IsGlobal)
		{
			foreach (Item item in list2)
			{
				if (!_inventory.ReturnContainsItem(item.Properties, 1, SubInventoryType.Composition) && !_inventory.ReserveIncomingItem(item, SubInventoryType.Composition))
				{
					UnityEngine.Debug.LogException(new NotSupportedException("Could not reserve item \"" + item.Properties.name + "\" for constructing decoration " + target.Name + "!"));
				}
			}
		}
		if (_properties.HaulToConstructibleProjectProperties != null)
		{
			AssignProject(_properties.HaulToConstructibleProjectProperties, list2);
			ChangeBuildPhase(BuildPhase.HaulTo);
		}
		else
		{
			StartBuildPhase();
		}
	}

	private void StartSalvaging()
	{
		if (BuildPhase == BuildPhase.HaulTo && _inventory.HasIncomingItems(SubInventoryType.Composition))
		{
			CancelConstructionAfterHaul = true;
			UpdateBuildPhaseStatus();
		}
		else if (_inventory.ReturnCount(SubInventoryType.Composition, includeReserved: true) > 0)
		{
			StartDeconstructing();
		}
		else if (_inventory.ReturnCount(SubInventoryType.Resources, includeReserved: true) > 0)
		{
			HaulFromConstructible();
		}
		else
		{
			EndSalvaging();
		}
	}

	private void StartDeconstructing()
	{
		if (_properties.ShouldDeconstructInstantly)
		{
			foreach (Item item in _inventory.ReturnAllItems(SubInventoryType.Composition))
			{
				_inventory.MoveToSubInventory(item, SubInventoryType.Resources);
			}
			HaulFromConstructible();
		}
		else
		{
			AssignProject(GameSettings.Instance.ProjectSettings.DeconstructBuildableProperties);
			ChangeBuildPhase(BuildPhase.Deconstructing);
			_status.FlagMalfunctionsUpdated();
		}
	}

	private void HaulFromConstructible(bool restore = false)
	{
		if (_inventory.ReturnCount(SubInventoryType.Resources, includeReserved: true) <= 0 && !restore)
		{
			EndSalvaging();
			return;
		}
		ChangeBuildPhase(BuildPhase.HaulFrom);
		_inventory.InventoryUpdatedEvent.AddListener(EndSalvaging);
		if (_owner.TryGetTarget(out var target))
		{
			_resourceProvider = ResourceProvider.Get(target, SubInventoryType.Resources, AssignmentType.Constructing);
			_resourceProvider.Register();
		}
	}

	private void EndSalvaging()
	{
		if (_inventory.ReturnCount(SubInventoryType.Resources, includeReserved: true) <= 0)
		{
			if (_resourceProvider != null)
			{
				_resourceProvider.Unregister();
				_resourceProvider = null;
			}
			_inventory.InventoryUpdatedEvent.RemoveListener(EndSalvaging);
			if (_owner.TryGetTarget(out var target))
			{
				target.RemoveConstructible();
			}
		}
	}

	private void AssignProject(ProjectProperties projectProperties, List<Item> items = null)
	{
		if (_owner.TryGetTarget(out var target))
		{
			if (AssignedProject != null)
			{
				UnityEngine.Debug.LogException(new NotSupportedException($"Trying to assign a project to {target.Name}, but it still has a reference to '{AssignedProject.Properties}'"));
			}
			if (projectProperties.IsGlobal && Community.PlayerCommunity.TryReturnProjectWithProperties(projectProperties, out var project))
			{
				AssignedProject = project;
			}
			else
			{
				AssignedProject = new Project(projectProperties, target.gameObject, items);
				AssignedProject.ProjectAssignmentsUpdated.AddListener(UpdateBuildPhaseStatus);
				AssignedProject.FinishedEvent.AddListener(OnAssignedProjectFinished);
				Community.PlayerCommunity.QueueProject(AssignedProject);
			}
			if (projectProperties.AllowAgentLimitOverride)
			{
				AssignedProject.AssignmentLimit = _assignmentLimit;
				_assignmentLimit = 1;
			}
		}
	}

	private void OnAssignedProjectFinished(Project project, bool success)
	{
		if (AssignedProject != null)
		{
			AssignedProject.ProjectAssignmentsUpdated.RemoveListener(UpdateBuildPhaseStatus);
			AssignedProject.FinishedEvent.RemoveListener(OnAssignedProjectFinished);
			AssignedProject = null;
		}
		IConstructible target;
		switch (BuildPhase)
		{
		case BuildPhase.HaulTo:
			OnHaulToFinished();
			break;
		case BuildPhase.Build:
			if (Progress >= 1f)
			{
				FinishBuilding();
			}
			break;
		case BuildPhase.UpgradeHaulTo:
			if (_owner.TryGetTarget(out target))
			{
				target.StartUpgrade();
			}
			break;
		case BuildPhase.Deconstructing:
			if (Progress <= 0f)
			{
				HaulFromConstructible();
			}
			break;
		case BuildPhase.SalvageShutdown:
			TryToSalvage();
			break;
		case BuildPhase.HaulFrom:
			if (_owner.TryGetTarget(out target))
			{
				target.RemoveConstructible();
			}
			break;
		case BuildPhase.Finished:
		case BuildPhase.UpgradeShutdown:
			break;
		}
	}

	public void SetProgress(float progress)
	{
		Progress = Mathf.Clamp01(progress);
		if (_owner.TryGetTarget(out var target))
		{
			target.SetProgress(progress);
		}
		OnProgressUpdated.SafeInvoke(progress);
	}

	private void MoveReservedResources(SubInventoryType from, SubInventoryType to)
	{
		using ListPool<Item>.List list = ListPool<Item>.Get();
		_inventory.ReturnAllItems(from, list);
		foreach (Item item in list)
		{
			if (item.IsReserved)
			{
				item.CancelReservation();
				_inventory.MoveToSubInventory(item, to);
			}
		}
	}

	private void OnCompositionUpdatedEvent(float progress)
	{
		if (BuildPhase != BuildPhase.Finished)
		{
			SetProgress(progress);
		}
		if (AssignedProject != null && AssignedProject.Properties.IsGlobal)
		{
			BuildPhase buildPhase = BuildPhase;
			if (((buildPhase == BuildPhase.HaulTo || buildPhase == BuildPhase.Build) && progress >= 1f) || (BuildPhase == BuildPhase.Deconstructing && progress <= 0f))
			{
				OnAssignedProjectFinished(AssignedProject, success: true);
			}
		}
	}

	private void OnHaulToFinished()
	{
		if (CancelConstructionAfterHaul)
		{
			ChangeBuildPhase(BuildPhase.SalvageShutdown);
			TryToSalvage();
			CancelConstructionAfterHaul = false;
		}
		else
		{
			StartBuildPhase();
		}
	}

	private void FinishBuilding(GameEvent gameEvent)
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, FinishBuilding);
		FinishBuilding();
	}

	private void FinishBuilding(bool restored = false)
	{
		ChangeBuildPhase(BuildPhase.Finished);
		if (_owner.TryGetTarget(out var target))
		{
			target.FinishConstruction(restored);
		}
	}

	private void ChangeBuildPhase(BuildPhase buildPhase)
	{
		BuildPhase = buildPhase;
		UpdateBuildPhaseStatus();
		if (_owner.TryGetTarget(out var target))
		{
			target.OnBuildPhaseUpdated(BuildPhase);
		}
	}

	private void StartBuildPhase()
	{
		if (BuildPhase != BuildPhase.Build)
		{
			BuildConstructible();
		}
	}

	public void BuildConstructible()
	{
		if (_properties.ConstructionProjectProperties != null)
		{
			AssignProject(_properties.ConstructionProjectProperties);
			ChangeBuildPhase(BuildPhase.Build);
			return;
		}
		foreach (Item item in _inventory.ReturnAllItems(SubInventoryType.Resources))
		{
			if (!_inventory.ReserveIncomingItem(item, SubInventoryType.Composition))
			{
				UnityEngine.Debug.LogException(new NotSupportedException("Could not reserve item \"" + item.Properties.name + "\" for constructing constructible " + _properties.Name + "!"));
			}
		}
		FinishBuilding();
	}

	private void UpdateBuildPhaseStatus()
	{
		switch (BuildPhase)
		{
		case BuildPhase.HaulTo:
			if (CancelConstructionAfterHaul)
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusStoppingConstructionProperties);
			}
			else if (AssignedProject != null && AssignedProject.ReturnAssignedAgents().Count > 0)
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusResourcesComingProperties);
			}
			else
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusWaitingForResourcesProperties);
			}
			break;
		case BuildPhase.Build:
			if (AssignedProject != null && AssignedProject.ReturnAssignedAgents().Count > 0)
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusBuildingProperties);
			}
			else
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusWaitingForConstructorProperties);
			}
			break;
		case BuildPhase.Deconstructing:
			if (AssignedProject != null && AssignedProject.ReturnAssignedAgents().Count > 0)
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusDeconstructingProperties);
			}
			else
			{
				_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusWaitingForDeconstructorProperties);
			}
			break;
		case BuildPhase.HaulFrom:
			_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusSalvagingHaulingItemstoStorageProperties);
			break;
		default:
			_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusIdleProperties);
			break;
		}
	}

	public bool CanBeDeconstructed(out LocalizedString error)
	{
		error = GameSettings.Instance.BuildableSettings.DeconstructionTooltip;
		BuildPhase buildPhase = BuildPhase;
		if (buildPhase == BuildPhase.HaulFrom || buildPhase == BuildPhase.UpgradeHaulFrom)
		{
			error = GameSettings.Instance.BuildableSettings.HaulFromTooltip;
			return false;
		}
		buildPhase = BuildPhase;
		if (buildPhase == BuildPhase.UpgradeHaulTo || buildPhase == BuildPhase.UpgradeShutdown)
		{
			error = GameSettings.Instance.BuildableSettings.UpgradeHaulToTooltip;
			return false;
		}
		if (BuildPhase == BuildPhase.Deconstructing || (BuildPhase == BuildPhase.HaulTo && CancelConstructionAfterHaul))
		{
			error = GameSettings.Instance.BuildableSettings.CancelDeconstructionTooltip;
			return true;
		}
		if (_owner.TryGetTarget(out var target))
		{
			return target.CanBeDeconstructed(out error);
		}
		return true;
	}

	public void Restore(int assignmentLimit, BuildPhase buildPhase, float progress)
	{
		_assignmentLimit = assignmentLimit;
		SetProgress(progress);
		RestorePhase(buildPhase);
	}

	public void RestoreReferences(Project project)
	{
		AssignedProject = project;
		if (AssignedProject != null)
		{
			AssignedProject.ProjectAssignmentsUpdated.AddListener(UpdateBuildPhaseStatus);
			AssignedProject.FinishedEvent.AddListener(OnAssignedProjectFinished);
		}
	}

	public void RestorePhase(BuildPhase buildPhase)
	{
		BuildPhase = buildPhase;
		switch (buildPhase)
		{
		case BuildPhase.Build:
			MoveReservedResources(SubInventoryType.Resources, SubInventoryType.Composition);
			if (_inventory.ReturnCount(SubInventoryType.Resources) == 0)
			{
				GameEventDispatcher.AddListener(GameEventType.GameStart, FinishBuilding);
			}
			break;
		case BuildPhase.Deconstructing:
			if (_properties.ShouldDeconstructInstantly)
			{
				MoveReservedResources(SubInventoryType.Composition, SubInventoryType.Resources);
				if (_inventory.ReturnCount(SubInventoryType.Composition) == 0)
				{
					goto case BuildPhase.HaulFrom;
				}
			}
			_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusDeconstructingProperties);
			break;
		case BuildPhase.HaulFrom:
			_status.SetStatus(GameSettings.Instance.BuildableSettings.StatusSalvagingHaulingItemstoStorageProperties);
			HaulFromConstructible(restore: true);
			break;
		case BuildPhase.Finished:
			FinishBuilding(restored: true);
			break;
		case BuildPhase.SalvageShutdown:
		case BuildPhase.HaulTo:
			break;
		}
	}
}
public class BirdHouse : SceneBehaviour, IBuildableExtendable, IPersistentReference
{
	public enum BirdHouseState
	{
		None,
		Working,
		Sleeping
	}

	[Header("Bird Food")]
	[FormerlySerializedAs("_foodSource")]
	[Tooltip("Food ingredient to convert to bird food.")]
	public ItemProperties FoodSource;

	[Tooltip("Amount of bird food 1 ingredient gives.")]
	public int ConversionRate = 2;

	[SerializeField]
	[Tooltip("Percentage of stored food that needs to be reached before the storage will be refilled.")]
	[Range(0f, 1f)]
	private float _refillThreshold = 0.5f;

	[SerializeField]
	[Tooltip("Import project to collect fish.")]
	[FormerlySerializedAs("_fishImportProject")]
	private ProjectProperties _fishImportProjectProperties;

	[SerializeField]
	private FoodRationVisual _foodRationPrefab;

	[SerializeField]
	private List<Transform> _foodRationPositions = new List<Transform>();

	[Header("Salvaging")]
	[SerializeField]
	private ItemPropertiesGroup[] _itemGroups;

	[Header("Other")]
	[Tooltip("Where birds will move to when approaching this construction.")]
	public Transform BirdTarget;

	[Tooltip("Positions where the birds will sit when sleeping / eating.")]
	public AttachableSlots PerchSpots;

	[Tooltip("Maximum amount of birds that can reside here.")]
	[FormerlySerializedAs("Capacity")]
	public int BirdCapacity = 5;

	[Space]
	[SerializeField]
	[EnumFlag(1)]
	[Tooltip("Assignment type for hauling away items.")]
	public AssignmentType _haulingAssignmentType;

	[SerializeField]
	private int _storageCapacity = 50;

	[FormerlySerializedAs("StorageSlots")]
	[SerializeField]
	private InventorySlots _storageSlots;

	private Project _importProject;

	private ResourceProvider _exportResourceProvider;

	private int _fishNeeded;

	private FoodRationVisual[] _foodRationVisuals;

	private List<Item> _cachedIngredients = new List<Item>();

	private bool _processIngredients;

	private WorldManager _worldManager;

	public ItemPropertiesGroup[] ItemGroups => _itemGroups;

	public bool RefillFood { get; set; } = true;

	public Buildable Buildable { get; private set; }

	public BirdHouseState State { get; private set; }

	public List<Bird> Birds { get; private set; } = new List<Bird>();

	public List<Item> SalvageableItems { get; private set; } = new List<Item>();

	public bool Active { get; private set; }

	public int FoodStore { get; private set; }

	public bool Moving { get; private set; }

	public FoodRation[] FoodRations { get; private set; }

	public bool ExportItems { get; set; } = true;

	public int PersistentIndex { get; set; } = -1;

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		Buildable.Community.AddBirdhouse(this);
		Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Storage, _storageCapacity);
		Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Import);
		EnableItemExport(exportItems: true);
		_storageSlots.Initialize(Buildable.Inventory, SubInventoryType.Storage, Buildable.OutlineRenderer);
		GameEventDispatcher.AddListener(GameEventType.DaytimeStarted, OnDaytimeStarted);
		GameEventDispatcher.AddListener(GameEventType.NighttimeStarted, OnNighttimeStarted);
		GameEventDispatcher.AddListener(GameEventType.TownheartMoved, OnTownheartMoved);
		Buildable.Community.Inventory.InventoryUpdatedEvent.AddListener(TryToQueueFood);
		_worldManager = GameManager.WorldManager;
	}

	public void Finish(bool restored = false)
	{
		if (!restored)
		{
			State = BirdHouseState.Working;
			TryToQueueFood();
			RefillFood = true;
		}
		UpdateFoodRations();
		UpdateItemsInRadius();
		Buildable.Community.BirdhouseFinished();
	}

	private void LateUpdate()
	{
		if (Buildable.BuildPhase == BuildPhase.Finished)
		{
			if (0 < GameManager.WorldManager.FlotsamInWorld.Count)
			{
				UpdateItemsInRadius();
			}
			if (_processIngredients)
			{
				ProcessIngredients();
			}
			UpdateBirdFullfillment();
			if (ReturnStorageIsFull())
			{
				Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorExportStorageFullProperties);
			}
			else
			{
				Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorExportStorageFullProperties);
			}
		}
	}

	public void Remove()
	{
		Buildable.Community.RemoveBirdhouse(this);
		EnableItemExport(exportItems: false);
	}

	public void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.TownheartMoved, OnTownheartMoved);
		GameEventDispatcher.RemoveListener(GameEventType.DaytimeStarted, OnDaytimeStarted);
		GameEventDispatcher.RemoveListener(GameEventType.NighttimeStarted, OnNighttimeStarted);
		_storageSlots.Remove();
	}

	private void OnDaytimeStarted(GameEvent gameEvent)
	{
		State = BirdHouseState.Working;
	}

	private void OnNighttimeStarted(GameEvent gameEvent)
	{
		State = BirdHouseState.Sleeping;
	}

	public bool AddBird(Bird bird)
	{
		if (Birds.Contains(bird))
		{
			return false;
		}
		if (Birds.Count >= BirdCapacity)
		{
			PajamaLlama.Debugs.Debugger.Log($"{bird.Name} can't join this birdhouse because it's full.", this);
			return false;
		}
		Birds.Add(bird);
		TryToQueueFood();
		return true;
	}

	public bool RemoveBird(Bird bird)
	{
		if (!Birds.Contains(bird))
		{
			return false;
		}
		Birds.Remove(bird);
		return true;
	}

	public bool SalvageableItemAvailable(out Item item)
	{
		float num = float.MaxValue;
		item = null;
		if (!Active || ReturnStorageIsFull())
		{
			return false;
		}
		foreach (Item salvageableItem in SalvageableItems)
		{
			if (!salvageableItem.IsReserved && salvageableItem.InventoryType == InventoryType.Flotsam && salvageableItem.Project == null)
			{
				float sqrMagnitude = salvageableItem.Owner.transform.position.sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					item = salvageableItem;
				}
			}
		}
		if (item == null)
		{
			return false;
		}
		if (item.Reserve())
		{
			if (Buildable.Inventory.ReserveIncomingItem(item, SubInventoryType.Storage))
			{
				return true;
			}
			item.CancelReservation();
		}
		item = null;
		return false;
	}

	public void ReleaseItem(Item item)
	{
		item.CancelReservation();
		item.UnreserveMoveToInventory();
	}

	public void OnTownheartMoved(GameEvent gameEvent)
	{
		UpdateItemsInRadius();
		for (int i = 0; i < Birds.Count; i++)
		{
			Birds[i].WorldStoppedMoving();
		}
	}

	public void ToggleFoodRefilling(bool isOn)
	{
		RefillFood = isOn;
		if (RefillFood)
		{
			TryToQueueFood();
		}
	}

	private bool ShouldRequestIngredients()
	{
		if (!RefillFood)
		{
			return false;
		}
		if (Birds.Count == 0)
		{
			return false;
		}
		if (_importProject != null)
		{
			return false;
		}
		int num = Mathf.CeilToInt(FoodStore / ConversionRate);
		int num2 = Mathf.FloorToInt(_refillThreshold * (float)Buildable.Inventory.ReturnCapacity(SubInventoryType.Import));
		if (num >= num2)
		{
			return false;
		}
		if (Buildable.Inventory.HasItems(SubInventoryType.Import, includeReserved: true))
		{
			_processIngredients = true;
			return false;
		}
		float num3 = BirdCapacity * ConversionRate - FoodStore;
		_fishNeeded = Mathf.FloorToInt(num3 / (float)ConversionRate);
		return true;
	}

	private void TryToQueueFood()
	{
		if (!ShouldRequestIngredients())
		{
			return;
		}
		int num = Mathf.Min(Community.PlayerCommunity.Inventory.ReturnCount(FoodSource), _fishNeeded);
		if (num > 0 && ResourceManager.TryReserveClosestItems(Buildable, FoodSource, num, out var reservedItems))
		{
			if (_fishImportProjectProperties == null)
			{
				UnityEngine.Debug.LogError("Fish import project properties are null!");
			}
			_importProject = new Project(_fishImportProjectProperties, base.gameObject, reservedItems);
			Buildable.Community.QueueProject(_importProject);
			_importProject.FinishedEvent.AddListener(OnImportProjectFinished);
			_fishNeeded -= num;
		}
	}

	private void OnImportProjectFinished(Project project, bool success)
	{
		_importProject.FinishedEvent.RemoveListener(OnImportProjectFinished);
		_importProject = null;
		_processIngredients = true;
	}

	private void ProcessIngredients()
	{
		Buildable.Inventory.ReturnAllItems(SubInventoryType.Import, _cachedIngredients);
		foreach (Item cachedIngredient in _cachedIngredients)
		{
			FoodStore += ConversionRate;
			Buildable.Inventory.TakeItem(cachedIngredient);
		}
		_cachedIngredients.Clear();
		UpdateFoodRations();
		_processIngredients = false;
	}

	public void ConsumeFood()
	{
		FoodStore--;
		UpdateFoodRations();
		TryToQueueFood();
	}

	private void UpdateItemsInRadius()
	{
		List<Flotsam> flotsamInWorld = GameManager.WorldManager.FlotsamInWorld;
		int count = flotsamInWorld.Count;
		ItemPropertiesGroup[] itemGroups = _itemGroups;
		for (int i = 0; i < itemGroups.Length; i++)
		{
			itemGroups[i].ClearItems();
		}
		for (int j = 0; j < count; j++)
		{
			PopulateItemLists(flotsamInWorld[j]);
		}
		SalvageableItems.Clear();
		itemGroups = _itemGroups;
		foreach (ItemPropertiesGroup itemPropertiesGroup in itemGroups)
		{
			if (itemPropertiesGroup.Enabled)
			{
				SalvageableItems.AddRange(itemPropertiesGroup.Items);
			}
		}
		if (SalvageableItems.Count == 0)
		{
			Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorNoItemsToSalvageProperties);
		}
		else
		{
			Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorNoItemsToSalvageProperties);
		}
	}

	private void PopulateItemLists(Flotsam flotsam)
	{
		if (!_worldManager.IsInBoatRadius(flotsam.Position))
		{
			return;
		}
		foreach (Item item in flotsam.Inventory.ReturnAllItems())
		{
			ItemPropertiesGroup[] itemGroups = _itemGroups;
			for (int i = 0; i < itemGroups.Length && !itemGroups[i].TryAddItem(item); i++)
			{
			}
		}
	}

	private int ReturnIncomingItems()
	{
		int num = 0;
		foreach (Bird bird in Birds)
		{
			Bird.BirdState state = bird.State;
			if ((uint)(state - 5) <= 1u)
			{
				num++;
			}
		}
		return num;
	}

	private void UpdateBirdFullfillment()
	{
		if (FoodStore < Birds.Count)
		{
			for (int i = 0; i < Birds.Count; i++)
			{
				if (!Birds[i].IsFed)
				{
					Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorSeagullsHungryProperties);
					return;
				}
			}
		}
		Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorSeagullsHungryProperties);
	}

	private void UpdateFoodRations()
	{
		if (FoodRations == null)
		{
			FoodRations = new FoodRation[BirdCapacity];
			for (int i = 0; i < FoodRations.Length; i++)
			{
				FoodRations[i] = new FoodRation(ConversionRate);
			}
		}
		if (Buildable.BuildPhase == BuildPhase.Finished)
		{
			int result;
			int num = System.Math.DivRem(FoodStore, ConversionRate, out result);
			for (int j = 0; j < FoodRations.Length; j++)
			{
				FoodRation foodRation = FoodRations[j];
				if (j < num)
				{
					foodRation.Count = ConversionRate;
				}
				else if (j == num)
				{
					foodRation.Count = result;
				}
				else
				{
					foodRation.Count = 0;
				}
			}
		}
		else
		{
			FoodRation[] foodRations = FoodRations;
			for (int k = 0; k < foodRations.Length; k++)
			{
				foodRations[k].Count = 0;
			}
		}
		UpdateFoodVisuals();
	}

	private void UpdateFoodVisuals()
	{
		if (_foodRationVisuals == null)
		{
			_foodRationVisuals = new FoodRationVisual[BirdCapacity];
			for (int i = 0; i < BirdCapacity; i++)
			{
				_foodRationVisuals[i] = UnityEngine.Object.Instantiate(_foodRationPrefab, _foodRationPositions[i]);
			}
		}
		for (int j = 0; j < _foodRationVisuals.Length; j++)
		{
			FoodRation foodRation = FoodRations[j];
			if (foodRation != null)
			{
				_foodRationVisuals[j].UpdateVisual(foodRation.Count);
			}
			else
			{
				_foodRationVisuals[j].UpdateVisual(0);
			}
		}
	}

	public void EnableItemExport(bool exportItems)
	{
		ExportItems = exportItems;
		if (ExportItems)
		{
			if (_exportResourceProvider == null)
			{
				_exportResourceProvider = ResourceProvider.Get(Buildable, SubInventoryType.Storage, _haulingAssignmentType);
			}
			_exportResourceProvider.Register();
		}
		else if (!ExportItems && _exportResourceProvider != null)
		{
			_exportResourceProvider.Unregister();
		}
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public bool CanBeSalvaged()
	{
		if (Birds.Count > 0)
		{
			return false;
		}
		if (Buildable.Inventory.ReturnCount(SubInventoryType.Storage, includeReserved: true) > 0)
		{
			return false;
		}
		return true;
	}

	public void Shutdown()
	{
		_exportResourceProvider.AddAssignmentType(AssignmentType.Constructing);
		Deactivate();
	}

	public void Activate()
	{
		Active = true;
		UpdateFoodRations();
	}

	public void Deactivate()
	{
		Active = false;
		Buildable.RemoveAllMalfunctions();
		UpdateFoodRations();
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new BirdHousePersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
		BirdHousePersistentData birdHousePersistentData = persistentData as BirdHousePersistentData;
		ToggleFoodRefilling(birdHousePersistentData.RefillFood);
		if (PersistenceManager.DoesSaveInfoVersionComeBefore(0, 3, 4))
		{
			EnableItemExport(exportItems: true);
		}
		else
		{
			EnableItemExport(birdHousePersistentData.ExportItems);
		}
		State = birdHousePersistentData.State;
		FoodStore = birdHousePersistentData.FoodStore;
		UpdateFoodRations();
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
		BirdHousePersistentData birdHousePersistentData = persistentData as BirdHousePersistentData;
		ItemPropertiesGroup[] itemGroups = _itemGroups;
		foreach (ItemPropertiesGroup itemPropertiesGroup in itemGroups)
		{
			itemPropertiesGroup.Enabled = birdHousePersistentData.IsItemGroupEnabled(itemPropertiesGroup);
		}
		if (birdHousePersistentData.ImportProject != null && birdHousePersistentData.ImportProject.TryReturn(out var instance))
		{
			_importProject = instance;
			_importProject.FinishedEvent.AddListener(OnImportProjectFinished);
		}
		for (int j = 0; j < birdHousePersistentData.Birds.Length; j++)
		{
			if (birdHousePersistentData.Birds[j].TryReturn(out var instance2))
			{
				instance2.JoinBirdHouse(this, restored: true);
			}
		}
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		BirdHousePersistentData birdHousePersistentData = persistentData as BirdHousePersistentData;
		birdHousePersistentData.ImportProject = _importProject;
		birdHousePersistentData.Birds = new PersistentReference<Bird>.Reference[Birds.Count];
		for (int i = 0; i < Birds.Count; i++)
		{
			birdHousePersistentData.Birds[i] = Birds[i];
		}
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		return true;
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	private bool ReturnStorageIsFull()
	{
		return Buildable.Inventory.ReturnCapacity() <= Buildable.Inventory.ReturnCount(SubInventoryType.Storage, includeReserved: true) + ReturnIncomingItems();
	}

	public bool HasVacancies()
	{
		if (IsEnabled())
		{
			return Birds.Count < BirdCapacity;
		}
		return false;
	}

	public float ReturnWeight()
	{
		return 0f;
	}
}
public class FoodRation
{
	public int Count;

	public int Capacity { get; private set; }

	public FoodRation(int capacity, int count = 0)
	{
		Capacity = capacity;
		Count = count;
	}

	public float ReturnProgress()
	{
		return (float)Count / (float)Capacity;
	}
}
[RequireComponent(typeof(Obstacle), typeof(Inventory))]
public class Construction : MonoBehaviour, IPersistentReference, IBuildableExtendable
{
	[Tooltip("Allow buildings to snap to the side.")]
	public bool AllowSideSnapping = true;

	public bool GenerateObstacleVertices = true;

	private static readonly HashSet<Construction> _cachedIgnoredConstructions = new HashSet<Construction>();

	private Obstacle _obstacle;

	private HierarchicalNodeMarker[] _hierarchicalNodeMarkers;

	public UnityEvent OnNeighbourChangeEvent = new UnityEvent();

	public static UnityEvent OnNeighboursChangedEvent = new UnityEvent();

	public List<Construction> NeighbourConstructions { get; private set; } = new List<Construction>();

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public HierarchicalNodeMarker BuildPhaseTargetMarker { get; private set; }

	public static Construction Townheart { get; set; }

	public static Vector3 TownheartPosition
	{
		get
		{
			if ((bool)Townheart)
			{
				return Townheart.transform.position;
			}
			return Vector3.zero;
		}
	}

	public Target Target { get; private set; }

	public Buildable Buildable { get; private set; }

	private void Awake()
	{
		_obstacle = GetComponent<Obstacle>();
		_hierarchicalNodeMarkers = GetComponentsInChildren<HierarchicalNodeMarker>();
		Target = _obstacle;
	}

	private void Start()
	{
		if (LoadingScreen.IsLoading)
		{
			GameEventDispatcher.AddListener(GameEventType.LoadingCompleted, UpdateBuildPhaseTargetMarker);
		}
		else
		{
			UpdateBuildPhaseTargetMarker();
		}
	}

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.blue;
		for (int i = 0; i < NeighbourConstructions.Count; i++)
		{
			if (NeighbourConstructions[i] == null)
			{
				PajamaLlama.Debugs.Debugger.Log("neighbour is null.");
			}
			Gizmos.DrawLine(base.transform.position.Leveled() + new Vector3(0f, 10f, 0f), NeighbourConstructions[i].transform.position.Leveled() + new Vector3(0f, 10f, 0f));
		}
	}

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		Target.SetConstruction(this);
		if (GenerateObstacleVertices)
		{
			_obstacle.Initialize(buildable.OutlineCorners, Buildable.Properties.PathfindingOutlines);
		}
		else
		{
			_obstacle.Initialize();
		}
		Target.PrimaryMarker.AddToConstructionGraph();
		GraphManager.RefreshNavigatorPaths();
		buildable.Community.AddConstruction(this);
	}

	public void Finish(bool restored = false)
	{
	}

	public void Remove()
	{
		Agent[] componentsInChildren = GetComponentsInChildren<Agent>();
		foreach (Agent agent in componentsInChildren)
		{
			DetachAgent(agent);
		}
		Target.PrimaryMarker.RemoveFromConstructionGraph();
		GraphManager.RefreshNavigatorPaths();
		Buildable.Community.RemoveConstruction(this);
		for (int j = 0; j < NeighbourConstructions.Count; j++)
		{
			NeighbourConstructions[j].RemoveNeighbour(this);
		}
		NeighbourConstructions.Clear();
	}

	private void DetachAgent(Agent agent)
	{
		if (agent.Boat == null)
		{
			Navigator navigator = agent.ReturnNavigator();
			Vector3 position = agent.transform.position;
			Construction construction = null;
			float num = float.MaxValue;
			foreach (Construction neighbourConstruction in NeighbourConstructions)
			{
				float num2 = neighbourConstruction.transform.position.DistanceToLeveledSquared(position);
				if (num2 < num)
				{
					construction = neighbourConstruction;
					num = num2;
				}
			}
			if (construction != null)
			{
				navigator.AttachToTarget(construction.Target);
				return;
			}
		}
		agent.transform.SetParent(GameManager.AgentManager.AgentParent);
		agent.ReturnNavigator().StopIdling();
		Vector3 position2 = base.transform.position;
		agent.ReturnNavigator(alwaysReturnDrifter: true).PlaceAt(position2, overrideCheck: true, placeOnObstacle: false);
		agent.TryGoToTown();
	}

	public bool AddNeighbourConstruction(Construction neighbour)
	{
		if (NeighbourConstructions.AddUnique(neighbour))
		{
			OnNeighbourChangeEvent.Invoke();
			OnNeighboursChangedEvent.Invoke();
			UpdateBuildPhaseTargetMarker();
			return true;
		}
		return false;
	}

	public bool RemoveNeighbour(Construction neighbour)
	{
		if (NeighbourConstructions.Remove(neighbour))
		{
			OnNeighbourChangeEvent.Invoke();
			OnNeighboursChangedEvent.Invoke();
			UpdateBuildPhaseTargetMarker();
			return true;
		}
		return false;
	}

	public void RemoveNeighbours()
	{
		if (NeighbourConstructions.Count != 0)
		{
			for (int num = NeighbourConstructions.Count - 1; num >= 0; num--)
			{
				RemoveNeighbour(NeighbourConstructions[num]);
			}
		}
	}

	private void UpdateBuildPhaseTargetMarker(GameEvent gameEvent = null)
	{
		if (LoadingScreen.IsLoading)
		{
			return;
		}
		GameEventDispatcher.RemoveListener(GameEventType.LoadingCompleted, UpdateBuildPhaseTargetMarker);
		Vector3 position = Target.PrimaryMarker.transform.position;
		float num = float.MaxValue;
		BuildPhaseTargetMarker = null;
		foreach (Construction neighbourConstruction in NeighbourConstructions)
		{
			if (neighbourConstruction.IsConnectedToTownheart() && neighbourConstruction.Buildable.TryReturnBuildableExtendable<Hookable>(out var buildableExtendable) && buildableExtendable.TryReturnClosestHierarchicalNodeMarker(out var closestMarker, Target.PrimaryMarker.transform.position))
			{
				float num2 = position.DistanceToLeveledSquared(closestMarker.transform.position);
				if (num2 < num)
				{
					BuildPhaseTargetMarker = closestMarker;
					num = num2;
				}
			}
		}
	}

	public bool CanStartBuilding()
	{
		if (!Buildable.Properties.NeedsTownConnection)
		{
			return true;
		}
		for (int i = 0; i < NeighbourConstructions.Count; i++)
		{
			if (NeighbourConstructions[i].Buildable.BuildPhase == BuildPhase.Finished)
			{
				return true;
			}
		}
		return false;
	}

	public ITarget ReturnGoToTownTarget(Agent agent)
	{
		if (_hierarchicalNodeMarkers == null || _hierarchicalNodeMarkers.Length == 0)
		{
			return Target;
		}
		Vector3 position = agent.transform.position;
		HierarchicalNodeMarker[] hierarchicalNodeMarkers = _hierarchicalNodeMarkers;
		foreach (HierarchicalNodeMarker hierarchicalNodeMarker in hierarchicalNodeMarkers)
		{
			if (hierarchicalNodeMarker.Children != null && hierarchicalNodeMarker.Children.Length != 0 && hierarchicalNodeMarker.Node != null)
			{
				return new PathfindingNodeTarget(hierarchicalNodeMarker.Node.ReturnClosestNode(position));
			}
		}
		return Target;
	}

	public bool IsConnectedToTownheart()
	{
		_cachedIgnoredConstructions.Clear();
		return IsConnectedToTownheartInternal();
	}

	public bool IsConnectedToTownheart(Construction ignoredConstruction)
	{
		_cachedIgnoredConstructions.Clear();
		_cachedIgnoredConstructions.Add(ignoredConstruction);
		return IsConnectedToTownheartInternal();
	}

	private bool IsConnectedToTownheartInternal()
	{
		if (this == Townheart)
		{
			return true;
		}
		_cachedIgnoredConstructions.Add(this);
		foreach (Construction neighbourConstruction in NeighbourConstructions)
		{
			if (!neighbourConstruction.IsBeingSalvaged() && !_cachedIgnoredConstructions.Contains(neighbourConstruction) && (neighbourConstruction == Townheart || neighbourConstruction.IsConnectedToTownheartInternal()))
			{
				return true;
			}
		}
		return false;
	}

	public float ReturnWeight()
	{
		return 0f;
	}

	public bool TryReturnBuildablePhaseTargetNode(out HierarchicalNode node)
	{
		if (Buildable.BuildPhase == BuildPhase.Finished || BuildPhaseTargetMarker == null)
		{
			node = null;
		}
		else
		{
			node = BuildPhaseTargetMarker.Node;
		}
		return node != null;
	}

	public void Activate()
	{
		Active = true;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public void Shutdown()
	{
		Deactivate();
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public bool CanBeSalvaged()
	{
		return true;
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new ConstructionPersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
		ConstructionPersistentData constructionPersistentData = persistentData as ConstructionPersistentData;
		for (int i = 0; i < constructionPersistentData.Neighbours.Length; i++)
		{
			if (constructionPersistentData.Neighbours[i].TryReturn(out var instance))
			{
				AddNeighbourConstruction(instance);
			}
		}
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		ConstructionPersistentData constructionPersistentData = persistentData as ConstructionPersistentData;
		constructionPersistentData.Neighbours = new PersistentReference<Construction>.Reference[NeighbourConstructions.Count];
		for (int i = 0; i < NeighbourConstructions.Count; i++)
		{
			constructionPersistentData.Neighbours[i] = NeighbourConstructions[i];
		}
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		return true;
	}

	public void Upgrade(Buildable upgradedBuildable)
	{
		Construction component = upgradedBuildable.GetComponent<Construction>();
		foreach (Construction neighbourConstruction in NeighbourConstructions)
		{
			if (neighbourConstruction.AddNeighbourConstruction(component))
			{
				component.AddNeighbourConstruction(neighbourConstruction);
			}
		}
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	private bool IsBeingSalvaged()
	{
		BuildPhase buildPhase = Buildable.BuildPhase;
		if ((uint)(buildPhase - 2) <= 1u || buildPhase == BuildPhase.HaulFrom)
		{
			return true;
		}
		return false;
	}
}
public class ConstructionPreview : BuildablePreview
{
	public bool IsHooked;

	public Hookable Hookable;

	public Hookable.Hook Hook;

	public VisualBoundary Boundary;

	public Polygon BlockingPolygon;

	public BuildableProperties Properties;

	private MarkerProxy _primaryMarker;

	public bool CanPlace { get; private set; }

	public ConstructionPreview(Buildable buildable, VisualPrefabPreviewSettings previewSettings, int visualIndex, bool createMarkerProxy, bool isHooked = false)
		: base(buildable, previewSettings, visualIndex)
	{
		IsHooked = isHooked;
		Hookable = null;
		Hook = null;
		CanPlace = false;
		Properties = buildable.Properties;
		BlockingPolygon = Buildable.CreateBlockingPolygon(buildable.Properties, GameSettings.Instance.BuildableSettings.GridSize, base.Transform.transform, base.Transform.transform);
		Enable();
		Boundary = InstantiateVisualBoundart(buildable.Properties);
		VisualBoundary.Display(Boundary != null);
		if (createMarkerProxy && buildable.TryGetComponent<Target>(out var component))
		{
			_primaryMarker = ((component.PrimaryMarker == null) ? null : new MarkerProxy(component.PrimaryMarker, this, base.Transform.transform));
		}
	}

	public void Enable()
	{
		base.Transform.gameObject.SetActive(value: true);
	}

	public void Disable()
	{
		base.Transform.gameObject.SetActive(value: false);
	}

	public void SetCanPlace(bool canPlace)
	{
		CanPlace = canPlace;
		SetValid(canPlace);
	}

	public bool ConnectsToNavMesh()
	{
		if (_primaryMarker == null)
		{
			return true;
		}
		if (IsHooked && Hookable.TryReturnWalkwaySegment(out var walkwaySegment))
		{
			return _primaryMarker.ReturnConnectsToNavMesh(walkwaySegment);
		}
		return _primaryMarker.ReturnConnectsToNavMesh();
	}

	private VisualBoundary InstantiateVisualBoundart(BuildableProperties buildableProperties)
	{
		VisualBoundary visualBoundary = buildableProperties.ReturnBoundary();
		if (visualBoundary == null)
		{
			throw new NotImplementedException();
		}
		VisualBoundary visualBoundary2 = UnityEngine.Object.Instantiate(visualBoundary, base.Transform.transform);
		if (!buildableProperties.UseCustomSize)
		{
			visualBoundary2.SetSize(buildableProperties.Width, buildableProperties.Depth);
		}
		return visualBoundary2;
	}

	public void UpdateCanBePlaced(bool needsHook = true, bool checkFreeformBlockers = false)
	{
		bool flag = base.Transform.transform.position.IsInRange(Construction.TownheartPosition, GameSettings.Instance.GameplaySettings.ConstructionRadius);
		bool flag2 = !needsHook || IsHooked;
		bool flag3 = IsOverlapping(Buildable.BlockingPolygons);
		if (!flag3 && checkFreeformBlockers && IsOverlapping(Buildable.FreeformBlockerPolygons))
		{
			flag3 = true;
		}
		SetCanPlace(flag && flag2 && !flag3 && ConnectsToNavMesh());
	}

	public bool IsOverlapping(IEnumerable<Polygon> blockingPolygons)
	{
		base.Polygon.FastUpdate();
		foreach (Polygon blockingPolygon in blockingPolygons)
		{
			blockingPolygon.FastUpdate();
			if (base.Polygon.ReturnArePolygonsOverlapping(blockingPolygon, includeTolerance: true))
			{
				return true;
			}
		}
		return false;
	}
}
