	{
		if (Buildable == null)
		{
			UnityEngine.Debug.LogError($"ENERGYPASSIVEGENERATOR::Buildable was null in update in {base.name}");
		}
		IsRunning = ReturnCanRun();
		if (_running != IsRunning)
		{
			if (OnUpdateGeneratingEnergy == null)
			{
				UnityEngine.Debug.LogError($"ENERGYPASSIVEGENERATOR::OnUpdateGeneratingEnergy was null in update in {base.name}");
			}
			OnUpdateGeneratingEnergy.Invoke();
			_running = IsRunning;
		}
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
