	public void Activate()
	{
		Active = true;
		if ((bool)_buildableAnimator && (bool)_buildableAnimator.Animator)
		{
			_buildableAnimator.Animator?.SetInteger("IsWorking", 1);
		}
		if ((bool)_fmodEventEmitter)
		{
			_fmodEventEmitter.Emit(_activeEvent);
		}
