[RequireComponent(typeof(EnergyGridConnector))]
public class Engine : SceneBehaviour, IBuildableExtendable, IPersistentReference, IEnergyGridComponent
{
	[SerializeField]
	private bool _isTownheartEngine;

	[SerializeField]
	private float _tugCapacity = 2000f;

	[FormerlySerializedAs("WeightTiers")]
	[SerializeField]
	[ConditionalHide("_isTownheartEngine", true)]
	private WeightTier[] _weightTiers;

	[SerializeField]
	[ConditionalHide("_isTownheartEngine", true)]
	[Tooltip("The cooldown is based on the last distance moved. The distance is multiplied by this value to be able to tweak the effect")]
	private float _cooldownThreshold = 10f;

	[Header("Energy")]
	[SerializeField]
	private float _startEnergy = 5000f;

	[Header("Audio")]
	[SerializeField]
	private StudioEventEmitter _engineEventEmitter;

	[Header("Malfunctions")]
	[SerializeField]
	private PlaceableAlertProperties _notConnectedToTownHeart;

	private static float _townTugCapacity;

	private static Engine _townheartEngine;

	private static List<Engine> _engines;

	private BuildableVisual _visual;

	private bool _updateMalfunctions;

	public Buildable Buildable { get; private set; }

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public WeightTier[] WeightTiers => _weightTiers;

	public static float TownWeight { get; private set; }

	public static WeightTier WeightTier { get; private set; }

	public static float TownUsedTugCapacityPercentage { get; private set; }

	public static float TownAvailableTugCapacity { get; private set; }

	public static float TownTugCapacity => _townTugCapacity;

	public static bool IsCoolingDown { get; private set; }

	public static float CooldownStartTime { get; private set; }

	public EnergyGridConnector Connector { get; set; }

	public EnergyGrid EnergyGrid => Connector.EnergyGrid;

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		Buildable.OnBuildableVisualRegister.AddListener(RegisterVisual);
		Buildable.OnBuildableVisualUnregister.AddListener(UnregisterVisual);
		GameEventDispatcher.AddListener(GameEventType.EnergyGridConnectionAdded, OnEnergyGridConnectionUpdated);
		GameEventDispatcher.AddListener(GameEventType.EnergyGridConnectionRemoved, OnEnergyGridConnectionUpdated);
		Connector = GetComponent<EnergyGridConnector>();
		Connector.AddComponent(this);
		if (_isTownheartEngine)
		{
			_townheartEngine = this;
		}
		if (_engines == null)
		{
			_engines = new List<Engine>();
		}
		_engines.Add(this);
	}

	public void Finish(bool restored = false)
	{
		if (_isTownheartEngine)
		{
			if (Buildable.Community.Engine != null)
			{
				UnityEngine.Debug.LogError("Multiple engines were added to the community. This is not possible.");
			}
			Buildable.Community.Engine = this;
		}
		else
		{
			if (Buildable.Community.Engine == null)
			{
				UnityEngine.Debug.LogError("A tugger engine is finished, but the Community engine is not yet fixed");
			}
			RotateVisual();
		}
		if (!restored)
		{
			EnergyGrid.FillStorageEnergy(_startEnergy);
		}
		GraphManager.RefreshNavigatorPaths();
		_engineEventEmitter?.Play();
		_updateMalfunctions = true;
	}

	public void Remove()
	{
	}

	private void LateUpdate()
	{
		if (Buildable == null)
		{
			return;
		}
		if (_isTownheartEngine)
		{
			float townWeight = TownWeight;
			TownWeight = Buildable.Community.ReturnWeight();
			float townTugCapacity = _townTugCapacity;
			_townTugCapacity = ReturnTownTugCapacity();
			TownUsedTugCapacityPercentage = Mathf.Clamp(TownWeight / _townTugCapacity, 0f, 1f);
			TownAvailableTugCapacity = Mathf.Max(_townTugCapacity - TownWeight, 0f);
			WeightTier weightTier = WeightTier;
			WeightTier = ReturnWeightTier(TownUsedTugCapacityPercentage);
			if (TownWeight != townWeight || _townTugCapacity != townTugCapacity)
			{
				WeightEvent.Dispatch(GameEventType.TownWeightUpdated, TownWeight, WeightTier);
			}
			if (WeightTier != weightTier)
			{
				WeightEvent.Dispatch(GameEventType.WeightTierUpdated, TownWeight, WeightTier);
			}
			if (IsCoolingDown)
			{
				IsCoolingDown = EnergyGrid.ReturnStorageEnergy() < _cooldownThreshold;
			}
		}
		else if (_updateMalfunctions)
		{
			UpdateMalfunctions();
		}
	}

	private void OnDestroy()
	{
		if (Buildable != null)
		{
			Buildable.OnBuildableVisualRegister.RemoveListener(RegisterVisual);
			Buildable.OnBuildableVisualUnregister.RemoveListener(UnregisterVisual);
		}
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridConnectionAdded, OnEnergyGridConnectionUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridConnectionRemoved, OnEnergyGridConnectionUpdated);
		if (_townheartEngine == this)
		{
			_townheartEngine = null;
		}
		if (!_engines.IsNullOrEmpty())
		{
			_engines.Remove(this);
		}
	}

	public bool ConsumeEnergy(float distance)
	{
		if (EnergyDevTools.FreeMovement)
		{
			return true;
		}
		EnergyGrid.RequestStorageEnergy(ReturnEnergyCost(distance));
		if (!IsCoolingDown && ReturnEnergyRange() == 0f)
		{
			IsCoolingDown = true;
			CooldownStartTime = Time.realtimeSinceStartup;
		}
		return true;
	}

	private void UpdateMalfunctions()
	{
		if (!_isTownheartEngine)
		{
			if (IsConnectedToTownheartEnergyGrid())
			{
				Buildable.RemoveMalfunction(_notConnectedToTownHeart);
			}
			else
			{
				Buildable.AddMalfunction(_notConnectedToTownHeart);
			}
			_updateMalfunctions = false;
		}
	}

	private void RegisterVisual(BuildableVisual visual)
	{
		_visual = visual;
		if (Buildable.BuildPhase == BuildPhase.Finished)
		{
			RotateVisual();
		}
	}

	private void UnregisterVisual(BuildableVisual visual)
	{
		if (_visual == visual)
		{
			_visual.transform.localRotation = Quaternion.identity;
		}
	}

	private void RotateVisual()
	{
		if (!(_visual == null))
		{
			_visual.transform.forward = Buildable.Community.Engine.transform.forward;
		}
	}

	private void OnEnergyGridConnectionUpdated(GameEvent gameEvent)
	{
		_updateMalfunctions = true;
	}

	public float ReturnMovementSpeed()
	{
		return Buildable.ReturnModifier(ModifierType.MovementSpeed);
	}

	public float ReturnMoveableDistance(float desiredDistance)
	{
		if (IsCoolingDown)
		{
			return 0f;
		}
		return desiredDistance;
	}

	private WeightTier ReturnWeightTier(float capacityPercentage)
	{
		WeightTier[] weightTiers = WeightTiers;
		foreach (WeightTier weightTier in weightTiers)
		{
			if (weightTier.IsInRange(capacityPercentage))
			{
				return weightTier;
			}
		}
		throw new NotImplementedException("No tier for weight " + capacityPercentage.ToString("F1"));
	}

	public float ReturnEnergyCost(float distance)
	{
		if (_townTugCapacity == 0f)
		{
			return 1f;
		}
		return distance * ReturnEelsPerUnit();
	}

	public float ReturnEnergyRange()
	{
		return ReturnEnergyRange(EnergyGrid.ReturnStorageEnergy());
	}

	public float ReturnEnergyRange(float energy)
	{
		return energy / ReturnEelsPerUnit();
	}

	private float ReturnEelsPerUnit()
	{
		return GameplaySettings.ReturnEelsPerUnit(TownWeight) * Buildable.ReturnModifier(ModifierType.MovementEnergyCost);
	}

	private bool IsConnectedToTownheartEnergyGrid()
	{
		if (EnergyGrid != null)
		{
			return EnergyGrid.IsTownheartGrid;
		}
		return false;
	}

	private float ReturnTownTugCapacity()
	{
		if (_engines.IsNullOrEmpty())
		{
			return 0f;
		}
		float num = 0f;
		foreach (Engine engine in _engines)
		{
			if (engine.IsEnabled() || engine._isTownheartEngine)
			{
				num += engine._tugCapacity;
			}
		}
		return num;
	}

	public float ReturnWeight()
	{
		return 0f;
	}

	public static bool CanTug(PlaceableProperties placeableProperties)
	{
		if (_townheartEngine == null)
		{
			return false;
		}
		return placeableProperties.GetWeightModeWeight() <= TownAvailableTugCapacity;
	}

	public static WeightTier[] ReturnWeightTiers()
	{
		if ((bool)_townheartEngine)
		{
			return _townheartEngine.WeightTiers;
		}
		return null;
	}

	public static float ReturnRange()
	{
		if ((bool)_townheartEngine)
		{
			return _townheartEngine.ReturnEnergyRange();
		}
		return 0f;
	}

	public void Activate()
	{
		Active = true;
		RotateVisual();
	}

	public bool CanBeSalvaged()
	{
		return !_isTownheartEngine;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public bool IsEnabled()
	{
		if (Active && Buildable.BuildPhase == BuildPhase.Finished)
		{
			if (!(this == _townheartEngine))
			{
				return IsConnectedToTownheartEnergyGrid();
			}
			return true;
		}
		return false;
	}

	public void OnDeconstruct()
	{
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new EnginePersistentData(this);
	}

	public void Shutdown()
	{
	}

	public void ShutdownImmediately()
	{
	}

	public bool CanBeDeconstructed()
	{
		return true;
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public void AddToEnergyGrid(EnergyGrid grid)
	{
		grid.AddComponent(this);
		_updateMalfunctions = true;
	}

	public void RemoveFromEnergyGrid(EnergyGrid grid)
	{
		if (grid != null)
		{
			grid.RemoveComponent(this);
			_updateMalfunctions = true;
		}
	}

	public EnergyGridOverviewSlotUI ReturnUI()
	{
		return null;
	}
}
[CreateAssetMenu(fileName = "Weight Tier", menuName = "Flotsam/Buildable/Weight Tier")]
public class WeightTier : ScriptableObject
{
	public LocalizedString Name = null;

	[MinMaxRangeFloat(0f, 1f)]
	public RangedFloat Limits;

	[FormerlySerializedAs("EnergyModifier")]
	[Tooltip("The amount of eels needed to move a single unit")]
	public float EelsPerUnit = 1f;

	public Color Color = Color.white;

	public Color LabelColor = Color.white;

	public float ReturnNormalizedWeightProgress(float weight)
	{
		float num = Limits.Maximum - Limits.Minimum;
		return (weight - Limits.Minimum) / num;
	}

	public bool IsInRange(float value)
	{
		return Limits.ReturnContainsValue(value);
	}
}
[RequireComponent(typeof(Construction))]
public class Hookable : MonoBehaviour, IBuildableExtendable, IPersistentReference
{
	public class Edge
	{
		public Vector3 StartPoint;

		public Vector3 EndPoint;

		public Vector3 Center;

		public Vector3 Vector;

		public Vector3 InwardNormal;

		public Vector3[] GridPoints;

		public Edge(Transform startPointTransform, Transform endPointTransform)
		{
			StartPoint = FlotsamGame.SetY(startPointTransform.position, 0f);
			EndPoint = FlotsamGame.SetY(endPointTransform.position, 0f);
			Center = (StartPoint + EndPoint) / 2f;
			Vector = EndPoint - StartPoint;
			InwardNormal = Vector3.Cross(Vector, Vector3.up);
			float num = GameSettings.Instance.BuildableSettings.GridSize;
			int num2 = (int)((float)System.Math.Round(Vector.magnitude, 1) / num) + 1;
			GridPoints = new Vector3[num2];
			Vector3 normalized = Vector.normalized;
			for (int i = 0; i < num2; i++)
			{
				float num3 = (float)i * num;
				GridPoints[i] = StartPoint + normalized * num3;
			}
			Vector.Normalize();
			InwardNormal.Normalize();
		}

		public void DrawGizmos(Color color)
		{
			Color color2 = Gizmos.color;
			Gizmos.color = color;
			Gizmos.DrawLine(StartPoint, EndPoint);
			Gizmos.DrawSphere(Center, 0.1f);
			Gizmos.DrawLine(Center, Center + InwardNormal);
			Gizmos.color = Color.red;
			Vector3[] gridPoints = GridPoints;
			foreach (Vector3 vector in gridPoints)
			{
				Gizmos.DrawSphere(vector, 0.1f);
				Gizmos.DrawLine(vector, vector + InwardNormal);
			}
			Gizmos.color = color2;
		}
	}

	public class Hook
	{
		public Edge Edge;

		public Vector3 Projection;

		public float SqrDistance;

		public float SqrDistanceToCenter;

		public Vector3 Forward => Edge.InwardNormal;

		public Vector3 Right => Edge.Vector;

		public Vector3 ReturnHookedPosition(Vector3 position, float distance)
		{
			Vector3 vector = Edge.InwardNormal * distance;
			return position - vector;
		}

		public Vector3 ReturnPosition(Vector3 position, bool snap, out int gridIndex)
		{
			if (snap)
			{
				return ReturnClosestGridPosition(position, out gridIndex);
			}
			gridIndex = 0;
			return Projection;
		}

		private Vector3 ReturnClosestGridPosition(Vector3 position, out int gridIndex)
		{
			gridIndex = 0;
			Vector3 result = Edge.Center;
			float num = float.MaxValue;
			for (int i = 0; i < Edge.GridPoints.Length; i++)
			{
				Vector3 vector = Edge.GridPoints[i];
				float magnitude = (position - vector).magnitude;
				if (magnitude < num)
				{
					result = vector;
					num = magnitude;
					gridIndex = i;
				}
			}
			return result;
		}

		public bool HasMatchingEdge(Hook other)
		{
			if (other == this)
			{
				return true;
			}
			float num = Vector3.Angle(other.Edge.StartPoint - Edge.StartPoint, Edge.Vector);
			if (!(num < 1f))
			{
				return num > 179f;
			}
			return true;
		}
	}

	public float HookHeightOffset;

	[FormerlySerializedAs("AngleCanAdjustHook")]
	public bool RotateAroundHook;

	[ConditionalHide(false, ConditionalSourceField = "RotateAroundHook")]
	public float RotateRadius = 1f;

	private Edge[] _edges;

	private Color _gizmoColor;

	private WalkwaySegment _walkwaySegment;

	private bool _isHookable;

	private List<WalkwaySegment> _segmentsToBuildPontonFor;

	public static List<Hookable> Hookables = new List<Hookable>();

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public Buildable Buildable { get; private set; }

	public Construction Construction { get; private set; }

	private void LateUpdate()
	{
		bool flag = IsHookable(Buildable);
		if (_isHookable != flag)
		{
			_isHookable = flag;
			if (_isHookable)
			{
				Hookables.AddUnique(this);
			}
			else
			{
				Hookables.Remove(this);
			}
		}
	}

	private void OnDestroy()
	{
		Hookables.Remove(this);
	}

	private void OnDrawGizmosSelected()
	{
		if (_edges != null)
		{
			Edge[] edges = _edges;
			for (int i = 0; i < edges.Length; i++)
			{
				edges[i].DrawGizmos(_gizmoColor);
			}
		}
	}

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		_isHookable = IsHookable(buildable);
		if (_isHookable)
		{
			Hookables.AddUnique(this);
		}
		InitializeEdges(buildable);
		_gizmoColor = UnityEngine.Random.ColorHSV();
		if (Buildable.TryReturnBuildableExtendable<Construction>(out var buildableExtendable))
		{
			Construction = buildableExtendable;
			_walkwaySegment = GetComponent<WalkwaySegment>();
			return;
		}
		throw new NotImplementedException($"Hookable {Buildable.Properties.Name} has no construction component.");
	}

	private void InitializeEdges(Buildable buildable)
	{
		int count = buildable.OutlineCorners.Count;
		if (((IReadOnlyCollection<Edge>)(object)_edges).IsNullOrEmpty())
		{
			_edges = new Edge[count];
		}
		for (int i = 0; i < count; i++)
		{
			Edge edge = new Edge(buildable.OutlineCorners[(int)Mathf.Repeat(i + 1, count)], buildable.OutlineCorners[i]);
			_edges[i] = edge;
		}
	}

	public static bool TryReturnClosestIntersection(out Vector2 closestIntersection, Vector2 start, Vector2 end, Hookable illegalHook = null)
	{
		float num = Vector2.Distance(start, end);
		closestIntersection = Vector2.zero;
		bool result = false;
		foreach (Hookable hookable in Hookables)
		{
			if (hookable == illegalHook)
			{
				continue;
			}
			hookable.Buildable.OutlinePolygon.FastUpdate();
			if (hookable.Buildable.OutlinePolygon.ReturnIsLineIntersecting(start, end, out var closestIntersection2))
			{
				float num2 = Vector2.Distance(start, closestIntersection2);
				if (num2 < num)
				{
					num = num2;
					closestIntersection = closestIntersection2;
					result = true;
				}
			}
		}
		return result;
	}

	public static bool TryHook(out Hook closestHook, out Hookable closestHookable, float snapDistance, Vector3 pointToHook, Hookable illegalHook, bool construction = true, Vector3 hookDirection = default(Vector3), float hookableWidth = 0f)
	{
		float num = snapDistance * snapDistance;
		float num2 = num;
		float num3 = float.MaxValue;
		closestHook = null;
		closestHookable = null;
		foreach (Hookable hookable in Hookables)
		{
			if (hookable == illegalHook || (construction && !hookable.CanHookConstruction()) || !hookable.TryToHookPoint(pointToHook, num, out var hook, hookDirection, hookableWidth))
			{
				continue;
			}
			if (Mathf.Approximately(hook.SqrDistance, num2))
			{
				if (num3 <= hook.SqrDistanceToCenter)
				{
					continue;
				}
			}
			else
			{
				if (!(hook.SqrDistance < num2))
				{
					continue;
				}
				num2 = hook.SqrDistance;
			}
			num3 = hook.SqrDistanceToCenter;
			closestHook = hook;
			closestHookable = hookable;
		}
		return closestHook != null;
	}

	public bool TryToHookPoint(Vector3 pointToHook, float sqrMaximumDistance, out Hook hook, Vector3 hookDirection = default(Vector3), float hookableWidth = 0f)
	{
		if (TryReturnClosestEdge(pointToHook, sqrMaximumDistance, out var closestEdge, out var sqrSmallestDistance, out var closestEdgeProjection) && !IsHookingParallelToEdge(closestEdge, sqrSmallestDistance, hookDirection, hookableWidth))
		{
			hook = new Hook
			{
				Edge = closestEdge,
				Projection = closestEdgeProjection,
				SqrDistance = sqrSmallestDistance,
				SqrDistanceToCenter = (closestEdge.Center - pointToHook).sqrMagnitude
			};
			return true;
		}
		hook = null;
		return false;
	}

	private bool IsHookingParallelToEdge(Edge edge, float sqrDistance, Vector3 hookDirection, float hookableWidth)
	{
		if (hookDirection != Vector3.zero && MathExtensions.Approximately(Mathf.Abs(Vector3.Dot(edge.Vector.normalized, hookDirection)), 1f))
		{
			return MathExtensions.Approximately(sqrDistance, hookableWidth * hookableWidth);
		}
		return false;
	}

	public bool TryReturnClosestEdge(Vector3 point, float sqrMaximumDistance, out Edge closestEdge, out float sqrSmallestDistance, out Vector3 closestEdgeProjection)
	{
		sqrSmallestDistance = sqrMaximumDistance;
		closestEdge = null;
		closestEdgeProjection = Vector3.zero;
		Vector3 projectedPoint = Vector3.zero;
		Edge[] edges = _edges;
		foreach (Edge edge in edges)
		{
			if (Math3d.TryProjectPointOnLineSegment(out projectedPoint, edge.StartPoint, edge.EndPoint, point))
			{
				float sqrMagnitude = (point - projectedPoint).sqrMagnitude;
				if (sqrMagnitude <= sqrSmallestDistance)
				{
					closestEdge = edge;
					closestEdgeProjection = projectedPoint;
					sqrSmallestDistance = sqrMagnitude;
				}
			}
		}
		return closestEdge != null;
	}

	public bool TryReturnWalkwaySegment(out WalkwaySegment walkwaySegment)
	{
		walkwaySegment = _walkwaySegment;
		return walkwaySegment != null;
	}

	public float ReturnWeight()
	{
		return 0f;
	}

	public bool TryReturnClosestHierarchicalNodeMarker(out HierarchicalNodeMarker closestMarker, Vector3 position)
	{
		closestMarker = null;
		Construction buildableExtendable;
		if ((bool)_walkwaySegment)
		{
			closestMarker = _walkwaySegment.ReturnClosestHierarchicalNodeMarker(position);
		}
		else if (Buildable.TryReturnBuildableExtendable<Construction>(out buildableExtendable))
		{
			closestMarker = buildableExtendable.Target.PrimaryMarker.ReturnChildClosestToPoint(position);
		}
		return closestMarker != null;
	}

	public void ReturnBlockingNeighbours(ref ListPool<VisualPrefab>.List blockingConstructions)
	{
		if (!(Construction != null))
		{
			return;
		}
		foreach (Construction neighbourConstruction in Construction.NeighbourConstructions)
		{
			if (!neighbourConstruction.IsConnectedToTownheart(Construction))
			{
				blockingConstructions.Add(neighbourConstruction.Buildable.SpawnedVisual);
			}
		}
	}

	private bool IsHookable(Buildable buildable)
	{
		bool flag = (bool)buildable && !buildable.CancelConstructionAfterHaul;
		if (flag)
		{
			BuildPhase buildPhase = buildable.BuildPhase;
			bool flag2 = (((uint)(buildPhase - 2) > 1u && buildPhase != BuildPhase.HaulFrom) ? true : false);
			flag = flag2;
		}
		return flag;
	}

	private bool CanHookConstruction()
	{
		if (Buildable.TryReturnBuildableExtendable<WalkwayPonton>(out var buildableExtendable))
		{
			foreach (WalkwaySegment neighbouringWalkwaySegment in buildableExtendable.NeighbouringWalkwaySegments)
			{
				if (IsHookable(neighbouringWalkwaySegment.Buildable))
				{
					return true;
				}
			}
			return false;
		}
		return true;
	}

	private void PopulateDependentNeighbouringWalkways()
	{
		foreach (Construction neighbourConstruction in Construction.NeighbourConstructions)
		{
			if (neighbourConstruction.Buildable.TryReturnBuildableExtendable<WalkwaySegment>(out var buildableExtendable) && !Construction.Buildable.TryReturnBuildableExtendable<WalkwayPonton>(out var _) && buildableExtendable.IsHookedTo(this, out var _))
			{
				if (_segmentsToBuildPontonFor == null)
				{
					_segmentsToBuildPontonFor = new List<WalkwaySegment>();
				}
				_segmentsToBuildPontonFor.Add(buildableExtendable);
			}
		}
	}

	private void BuildPontonsForNeighbouringSegments()
	{
		foreach (WalkwaySegment item in _segmentsToBuildPontonFor)
		{
			if (item.Buildable.Properties is WalkwaySegmentProperties walkwaySegmentProperties && walkwaySegmentProperties.walkwayPontonProperties.PlacementCursorProperties is LineConstructionCursorProperties lineConstructionCursorProperties)
			{
				item.IsHookedTo(this, out var isHookedToEnd);
				lineConstructionCursorProperties.CreatePontonForSegment(item, walkwaySegmentProperties.walkwayPontonProperties.Prefab, isHookedToEnd);
			}
		}
		_segmentsToBuildPontonFor = null;
	}

	public void Finish(bool restored = false)
	{
	}

	public void Remove()
	{
		Hookables.Remove(this);
		if (_segmentsToBuildPontonFor != null)
		{
			BuildPontonsForNeighbouringSegments();
		}
	}

	public void Activate()
	{
		Active = true;
		if (Buildable != null && _isHookable)
		{
			Hookables.AddUnique(this);
			InitializeEdges(Buildable);
		}
	}

	public void Deactivate()
	{
		Active = false;
		Hookables.Remove(this);
		if (_segmentsToBuildPontonFor == null)
		{
			PopulateDependentNeighbouringWalkways();
			if (_segmentsToBuildPontonFor != null)
			{
				BuildPontonsForNeighbouringSegments();
			}
		}
	}

	public void Shutdown()
	{
		Active = false;
		Hookables.Remove(this);
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public bool CanBeUpgraded()
	{
		return true;
	}

	public bool CanBeSalvaged()
	{
		if (_walkwaySegment != null)
		{
			return _walkwaySegment.CanBeSalvaged();
		}
		foreach (Construction neighbourConstruction in Construction.NeighbourConstructions)
		{
			if (!neighbourConstruction.IsConnectedToTownheart(Construction))
			{
				return false;
			}
		}
		return true;
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new HookablePersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void OnDeconstruct()
	{
		PopulateDependentNeighbouringWalkways();
	}

	public bool CanBeDeconstructed()
	{
		return CanBeSalvaged();
	}

	public void Upgrade(Buildable upgradedBuildable)
	{
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}
}
[RequireComponent(typeof(Construction))]
public class House : MonoBehaviour, IBuildableExtendable, IPersistentReference
{
	public delegate void HouseEventHandler();

	[Tooltip("Properties of this house.")]
	public HouseProperties Properties;

	public int InhabitantCount { get; private set; }

	public Agent[] Inhabitants { get; private set; }

	public Buildable Buildable { get; private set; }

	public Rejuvenator Rejuvenator { get; private set; }

	public bool Active { get; private set; }

	public bool HasCapacity => InhabitantCount < Inhabitants.Length;

	public int PersistentIndex { get; set; } = -1;

	public event HouseEventHandler InhabitantsUpdated;

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		Rejuvenator = GetComponent<Rejuvenator>();
		InhabitantCount = 0;
		Inhabitants = new Agent[Properties.Capacity];
	}

	public void Finish(bool restored = false)
	{
		new GameEvent(GameEventType.HouseFinished).Dispatch();
		Buildable.Community.AddHouse(this);
		GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnCommunityAgentAdded);
		GameEventDispatcher.AddListener(GameEventType.AgentRemovedFromPlayerCommunity, OnCommunityAgentRemoved);
		GameEventDispatcher.AddListener(GameEventType.HouseDeconstructed, TryFillCapacity);
		TryFillCapacity();
	}

	public void Remove()
	{
		for (int i = 0; i < Inhabitants.Length; i++)
		{
			Agent agent = Inhabitants[i];
			if ((bool)agent)
			{
				agent.SetHouse(null);
				Inhabitants[i] = null;
			}
		}
		if (this.InhabitantsUpdated != null)
		{
			this.InhabitantsUpdated();
		}
		new GameEvent(GameEventType.HouseDeconstructed).Dispatch();
		Buildable.Community.RemoveHouse(this);
	}

	private void OnCommunityAgentAdded(GameEvent gameEvent)
	{
		if (!LoadingScreen.IsLoading)
		{
			Agent agent = (gameEvent as AgentEvent).Agent;
			if (agent.ReservedHouse == null && Buildable.Community == agent.Community && AddAgent(agent) && this.InhabitantsUpdated != null)
			{
				this.InhabitantsUpdated();
			}
		}
	}

	private void OnCommunityAgentRemoved(GameEvent gameEvent)
	{
		Agent agent = (gameEvent as AgentEvent).Agent;
		if (Buildable.Community == agent.Community && RemoveAgent(agent))
		{
			TryFillCapacity();
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnCommunityAgentAdded);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRemovedFromPlayerCommunity, OnCommunityAgentRemoved);
		GameEventDispatcher.RemoveListener(GameEventType.HouseDeconstructed, TryFillCapacity);
	}

	public bool AddAgent(Agent agent)
	{
		if (InhabitantCount == Inhabitants.Length)
		{
			return false;
		}
		for (int i = 0; i < Properties.Capacity; i++)
		{
			if (Inhabitants[i] == null)
			{
				agent.SetHouse(this);
				Inhabitants[i] = agent;
				InhabitantCount++;
				return true;
			}
		}
		return false;
	}

	public bool RemoveAgent(Agent agent)
	{
		for (int i = 0; i < Properties.Capacity; i++)
		{
			if (Inhabitants[i] == agent)
			{
				agent.SetHouse(null);
				Inhabitants[i] = null;
				InhabitantCount--;
				return true;
			}
		}
		return false;
	}

	private void TryFillCapacity(GameEvent gameEvent = null)
	{
		if (!IsEnabled())
		{
			return;
		}
		List<Agent> agents = Buildable.Community.Agents;
		bool flag = false;
		foreach (Agent item in agents)
		{
			if (!(item.ReservedHouse != null))
			{
				if (!AddAgent(item))
				{
					break;
				}
				flag = true;
			}
		}
		if (flag && this.InhabitantsUpdated != null)
		{
			this.InhabitantsUpdated();
		}
	}

	public bool HasFreeSlot()
	{
		return InhabitantCount < Properties.Capacity;
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public bool CanBeSalvaged()
	{
		return true;
	}

	public void Shutdown()
	{
		Deactivate();
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnCommunityAgentAdded);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRemovedFromPlayerCommunity, OnCommunityAgentRemoved);
		GameEventDispatcher.RemoveListener(GameEventType.HouseDeconstructed, TryFillCapacity);
	}

	public void Activate()
	{
		Active = true;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new HousePersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
		HousePersistentData housePersistentData = persistentData as HousePersistentData;
		for (int i = 0; i < housePersistentData.Inhabitants.Length; i++)
		{
			if (i < Inhabitants.Length && housePersistentData.Inhabitants[i].TryReturn(out var instance))
			{
				instance.SetHouse(this);
				Inhabitants[i] = instance;
				InhabitantCount++;
			}
		}
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		HousePersistentData housePersistentData = persistentData as HousePersistentData;
		housePersistentData.Inhabitants = new PersistentReference<Agent>.Reference[Inhabitants.Length];
		for (int i = 0; i < Inhabitants.Length; i++)
		{
			housePersistentData.Inhabitants[i] = Inhabitants[i];
		}
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		return true;
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public bool ReturnIsInhabitant(Agent agent)
	{
		for (int i = 0; i < Properties.Capacity; i++)
		{
			if (Inhabitants[i] == agent)
			{
				return true;
			}
		}
		return false;
	}

	public float ReturnWeight()
	{
		return 0f;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Buildable/House Properties")]
public class HouseProperties : ScriptableObject
{
	[Tooltip("The total capacity of agents that can live in this type of house.")]
	public int Capacity = 5;
}
[RequireComponent(typeof(Construction))]
public class MooringPoint : MooringPointBase, IBuildableExtendable
{
	[Header("Malfunctions")]
	[SerializeField]
	private PlaceableAlertProperties _blockedMalfunction;

	[Header("Townheart MooringPoint")]
	[SerializeField]
	[Tooltip("The target used to embark a moored boat.")]
	private Target _embarkTarget;

	[SerializeField]
	private BuildableProperties _startingBoat;

	private Coroutine _evaluateBlockedCoroutine;

	private int _evaluateBlockedFrame;

	public Buildable Buildable { get; private set; }

	public bool Active { get; private set; }

	public override bool IsInTown => true;

	public override bool IsAvailableForMooring
	{
		get
		{
			if (base.IsAvailableForMooring && LinkedBoat == null)
			{
				return Buildable.BuildPhase == BuildPhase.Finished;
			}
			return false;
		}
	}

	public Boat LinkedBoat { get; private set; }

	public UnityEvent OnBoatLinkUpdatedEvent { get; private set; } = new UnityEvent();

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		base.EmbarkTarget = ((_embarkTarget != null) ? _embarkTarget : buildable.ReturnExtendable<Construction>().Target);
		base.MooringPointUpdated.AddListener(UpdateFreeMooringPointIcon);
		FreeMooringPointPrefab.SetActive(value: false);
		Buildable.Community.AddMooringPoint(this);
		GameEventDispatcher.AddListener(GameEventType.ConstructionGraphUpdated, EvaluateBlocked);
		GameEventDispatcher.AddListener(GameEventType.TownheartMoved, EvaluateBlocked);
	}

	public void Finish(bool restored = false)
	{
		Buildable.Community.UpdateMooringPoints();
		base.MooringPointUpdated.Invoke();
		EvaluateBlocked();
	}

	protected override void FixedUpdate()
	{
		if (base.MooredBoat != null)
		{
			base.MooredBoat.Buildable.transform.position = ReturnBoatPosition();
			base.MooredBoat.Buildable.transform.rotation = MooringTransform.rotation;
			base.MooredBoat.Buildable.BuoyantTransform.localRotation = Quaternion.identity;
		}
		base.FixedUpdate();
	}

	public void Remove()
	{
		RemoveListeners();
		if (base.MooredBoat != null)
		{
			UnmoorBoat();
		}
		Buildable.Community.RemoveMooringPoint(this);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		GameEventDispatcher.RemoveListener(GameEventType.ConstructionGraphUpdated, EvaluateBlocked);
		GameEventDispatcher.RemoveListener(GameEventType.TownheartMoved, EvaluateBlocked);
	}

	public void SpawnStartingBoat()
	{
		if (!_startingBoat)
		{
			return;
		}
		Boat boat = Buildable.Place(_startingBoat.Prefab, MooringTransform.position, MooringTransform.rotation, 0, instantPlacement: true).GetComponent<Boat>();
		LinkBoat(boat);
		if (LoadingScreen.IsLoading)
		{
			FinalUpdate.RegisterGameStartOneShot(delegate
			{
				MoorBoat(boat);
			});
		}
		else
		{
			FinalUpdate.RegisterOneShot(delegate
			{
				MoorBoat(boat);
			});
		}
	}

	public bool LinkBoat(Boat boat)
	{
		LogBlock.Begin();
		if ((bool)LinkedBoat && LinkedBoat != boat)
		{
			LogBlock.LogFormat("Unable to link Boat '{0}' to Mooringpoint '{1}' because the MooringPoint is already linked to Boat '{2}'", boat.Buildable.Name, Buildable.Name, LinkedBoat.Buildable.Name);
		}
		if ((bool)boat.TownMooringPoint && boat.TownMooringPoint != this)
		{
			LogBlock.LogFormat("Unable to link Boat '{0}' to Mooringpoint '{1}' because the boat is already linked to MooringPoint '{2}'", boat.Buildable.Name, Buildable.Name, boat.TownMooringPoint.Buildable.Name);
		}
		if (LogBlock.End(out var log))
		{
			UnityEngine.Debug.LogWarning(log);
			return false;
		}
		LinkedBoat = boat;
		boat.TownMooringPoint = this;
		OnBoatLinkUpdatedEvent.Invoke();
		return true;
	}

	public void UnlinkBoat(Boat boat)
	{
		LinkedBoat = null;
		boat.TownMooringPoint = null;
		OnBoatLinkUpdatedEvent.Invoke();
	}

	public override bool MoorBoat(Boat boat, bool restored = false)
	{
		if (ValidateLink(boat) && base.MoorBoat(boat, restored))
		{
			if (boat.Buildable.Community.CommunityType == Community.Type.Abandoned)
			{
				boat.AddToCommunity(Buildable.Community);
			}
			if (!boat.Buildable.Inventory.HasItems(SubInventoryType.Storage))
			{
				boat.UpdateMooredStoredItems();
			}
			boat.ResourceProvider.Register();
			return true;
		}
		return false;
	}

	public override bool UnmoorBoat(Agent agent)
	{
		Boat mooredBoat = base.MooredBoat;
		if (base.UnmoorBoat(agent))
		{
			mooredBoat.ResourceProvider.Unregister();
			return true;
		}
		return false;
	}

	private bool ValidateLink(Boat boat)
	{
		if (LinkedBoat == boat && boat.TownMooringPoint == this)
		{
			return true;
		}
		LogBlock.Begin();
		if ((bool)LinkedBoat)
		{
			LogBlock.LogFormat("Unable to validate link between MooringPoint '{0}' and Boat '{1}' because the MooringPoint is linked to Boat '{2}'.", Buildable.Name, boat.Buildable.Name, LinkedBoat.Buildable.Name);
		}
		else
		{
			LogBlock.LogFormat("Unable to validate link between MooringPoint '{0}' and Boat '{1}' because the MooringPoint has no linked Boat.", Buildable.Name, boat.Buildable.Name);
		}
		if ((bool)boat.TownMooringPoint)
		{
			LogBlock.LogFormat("Unable to validate link between Boat '{0}' and MooringPoint '{1}' because the Boat is linked to MooringPoint '{2}'.", boat.Buildable.Name, Buildable.Name, boat.TownMooringPoint.Buildable.Name);
		}
		else
		{
			LogBlock.LogFormat("Unable to validate link between Boat '{0}' and MooringPoint '{1}' because the Boat has no linked MooringPoint.", boat.Buildable.Name, Buildable.Name);
		}
		if (LogBlock.End(out var log))
		{
			UnityEngine.Debug.LogError(log);
		}
		return false;
	}

	public Vector3 ReturnBoatPosition()
	{
		return ReturnBoatPosition(base.MooredBoat.MooringOffset, base.MooredBoat.Buildable.transform.position);
	}

	public Vector3 ReturnBoatPosition(Vector3 mooringOffset, Vector3 position)
	{
		return (MooringTransform.position + mooringOffset).SetY(position.y);
	}

	public bool ReturnHasAvailableBoat(BoatType boatType)
	{
		if (Active && !base.IsBlocked && base.ReservingAgent == null && base.MooredBoat != null && base.MooredBoat.Type == boatType && base.MooredBoat.Buildable.BuildPhase == BuildPhase.Finished)
		{
			return base.MooredBoat.Buildable.Inventory.ReturnIsEmpty();
		}
		return false;
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public bool CanBeSalvaged()
	{
		if (!base.IsEmpty)
		{
			return false;
		}
		if (LinkedBoat != null)
		{
			return false;
		}
		return true;
	}

	public void Shutdown()
	{
		Deactivate();
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public void Activate()
	{
		Active = true;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		if (base.IsReserved)
		{
			return false;
		}
		if (LinkedBoat == null)
		{
			return true;
		}
		return false;
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public float ReturnWeight()
	{
		return 0f;
	}

	public void UpdateFreeMooringPointIcon()
	{
		if (!GameManager.UIManager.DisplayFreeMooringPointIcons)
		{
			FreeMooringPointPrefab.SetActive(value: false);
		}
		else
		{
			FreeMooringPointPrefab.SetActive(IsAvailableForMooring && Buildable.BuildPhase == BuildPhase.Finished);
		}
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new MooringPointPersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		MooringPointPersistentData obj = persistentData as MooringPointPersistentData;
		obj.MooredBoat = base.MooredBoat;
		obj.LinkedBoat = LinkedBoat;
	}

	private void EvaluateBlocked(GameEvent gameEvent = null)
	{
		if (base.gameObject.activeInHierarchy && _evaluateBlockedFrame != Time.frameCount)
		{
			if (_evaluateBlockedCoroutine != null)
			{
				StopCoroutine(_evaluateBlockedCoroutine);
			}
			_evaluateBlockedCoroutine = StartCoroutine(EvaluateBlockedRoutine());
			_evaluateBlockedFrame = Time.frameCount;
		}
	}

	private IEnumerator EvaluateBlockedRoutine()
	{
		yield return new WaitForEndOfFrame();
		_evaluateBlockedCoroutine = null;
		if (Pathfinder.HasInstance)
		{
			MooringPointBlockedQuery query = MooringPointBlockedQuery.Get(this, 3);
			Pathfinder.QueueQuery(query);
			while (query.IsExecuting)
			{
				yield return null;
			}
			base.IsBlocked = query.IsBlocked;
			query.Return();
		}
		else
		{
			base.IsBlocked = false;
		}
		if (base.IsBlocked)
		{
			Buildable.AddMalfunction(_blockedMalfunction);
		}
		else
		{
			Buildable.RemoveMalfunction(_blockedMalfunction);
		}
	}
}
public class OzoneShield : BuildableExtendableBase
{
	[SerializeField]
	private BuildableProperties _fusionReactorProperties;

	[SerializeReference]
	[InstantiateSerializeReference]
	private ScenarioTriggerableBase _triggerable;

	private void Start()
	{
		if ((bool)base.Buildable.BuildableAnimator && (bool)base.Buildable.BuildableAnimator.Animator && GameManager.WorldManager.World.HasEndTile)
		{
			base.Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 1);
		}
		else
		{
			GameEventDispatcher.AddListener(GameEventType.ActivateOzoneShield, OnActivateOzoneShield);
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActivateOzoneShield, OnActivateOzoneShield);
	}

	public void Trigger()
	{
		if (_triggerable.TryTrigger())
		{
			GameManager.UIManager.ClosePanel(PanelID.BuildablePanel);
		}
	}

	public bool IsInteractable()
	{
		if (IsConnected() && !_triggerable.WasTriggered)
		{
			return _triggerable.ConditionsAreMet();
		}
		return false;
	}

	private bool IsConnected()
	{
		if (base.Buildable.TryReturnBuildableExtendable<EnergyGridBuildableComponent>(out var buildableExtendable) && buildableExtendable.EnergyGrid != null)
		{
			foreach (IEnergyGridComponent component in buildableExtendable.EnergyGrid.Components)
			{
				if (component is EnergyPassiveGenerator { IsGenerating: not false } energyPassiveGenerator && energyPassiveGenerator.Buildable.Properties == _fusionReactorProperties)
				{
					return true;
				}
			}
		}
		return false;
	}

	private void OnActivateOzoneShield(GameEvent gameEvent)
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActivateOzoneShield, OnActivateOzoneShield);
		base.Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 1);
	}
}
public class Perchable : BuildableExtendableBase
{
	[SerializeField]
	[FormerlySerializedAs("_perchSpots")]
	public ReservableAttachableSlots PerchSpots;

	private static List<Perchable> _allPerchables;

	public event UnityAction Deconstructed;

	public override void Finish(bool restored = false)
	{
		if (_allPerchables == null)
		{
			_allPerchables = new List<Perchable>();
		}
		_allPerchables.Add(this);
	}

	public override void OnDeconstruct()
	{
		_allPerchables?.Remove(this);
		this.Deconstructed?.Invoke();
	}

	public static bool TryReturnClosestPerchable(Vector3 position, out Perchable closestPerchable)
	{
		closestPerchable = null;
		if (_allPerchables.IsNullOrEmpty())
		{
			return false;
		}
		float num = float.MaxValue;
		foreach (Perchable allPerchable in _allPerchables)
		{
			if (allPerchable.IsAccessible())
			{
				float num2 = Vector3.Distance(position, allPerchable.transform.position);
				if (num2 < num)
				{
					num = num2;
					closestPerchable = allPerchable;
				}
			}
		}
		return closestPerchable != null;
	}

	public bool IsAccessible()
	{
		if ((bool)base.Buildable && base.Buildable.BuildPhase == BuildPhase.Finished)
		{
			return PerchSpots.AreSlotsAvailable();
		}
		return false;
	}
}
public class AquaFarm : BuildableExtendableBase, IPersistentReference, IItemProducer
{
	public class Fish : IItemConsumer
	{
		[Serializable]
		public class PersistentData
		{
			private int _fishPropertiesIndex;

			private float _consumed;

			private PersistentReference<Item>.Reference _broodItem;

			public PersistentData(Fish instance)
			{
				_fishPropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(instance.FishProperties);
				_consumed = instance.Consumed;
				_broodItem = instance.BroodItem;
			}

			public bool TryRestore(out Fish fish, AquaFarm aquaFarm, bool isBroodfish)
			{
				if (GameManager.PersistenceManager.TryReturnPropertiesReference<FishProperties>(_fishPropertiesIndex, out var reference))
				{
					fish = new Fish(aquaFarm, reference, isBroodfish ? reference.FeedRequirementBrooding : reference.FeedRequirementGrowing);
					fish.Consumed = _consumed;
					fish.Progress = ((fish.Requirement <= 0f) ? 0f : (fish.Consumed / fish.Requirement));
					fish.BroodItem = _broodItem;
					if (1f <= fish.Progress)
					{
						if (isBroodfish)
						{
							fish.ResetBroodCycle();
						}
						else
						{
							aquaFarm.CountCompletedFish(fish);
						}
					}
					return true;
				}
				fish = null;
				return false;
			}
		}

		private AquaFarm _farm;

		private float _consumptionPerSecond;

		public FishProperties FishProperties { get; private set; }

		public ItemProperties ItemToConsumeProperties => FishProperties.FeedItemProperties;

		public float ConsumptionPerDay { get; private set; }

		public float Requirement { get; private set; }

		public float Consumed { get; private set; }

		public float Progress { get; private set; }

		public Item BroodItem { get; private set; }

		public bool Hungry { get; private set; }

		public Fish(AquaFarm farm, FishProperties fishProperties, float feedRequirement)
		{
			FishProperties = fishProperties;
			Requirement = feedRequirement;
			ConsumptionPerDay = ((FishProperties.FeedConsumptionPerDay < feedRequirement) ? FishProperties.FeedConsumptionPerDay : feedRequirement);
			Consumed = 0f;
			Progress = 0f;
			_farm = farm;
			_consumptionPerSecond = fishProperties.FeedConsumptionPerDay / TimeManager.CycleDuration;
		}

		public bool TryReserveBroodItem()
		{
			if (BroodItem == null)
			{
				if (!_farm.Buildable.Community.Inventory.TryReserveItems(FishProperties.BroodItemProperties, 1, out var reservedItems))
				{
					return false;
				}
				BroodItem = reservedItems[0];
				_farm.ItemDistributer.ImportItems(reservedItems);
			}
			return true;
		}

		public void ResetBroodCycle()
		{
			Requirement = FishProperties.FeedRequirementBrooding;
			ConsumptionPerDay = FishProperties.FeedConsumptionPerDay;
			Consumed = 0f;
		}

		public float Consume(float available)
		{
			if (Consumed < Requirement)
			{
				float num = Mathf.Min(_consumptionPerSecond * TimeManager.GetDeltaTime(), available);
				Consumed += num;
				if (Requirement <= Consumed)
				{
					Progress = 1f;
					if (BroodItem == null)
					{
						_farm.ItemDistributer.DetachConsumer(this);
						_farm.OnFishCompleted(this);
					}
					else
					{
						_farm.OnBroodCycleCompleted(this);
						ResetBroodCycle();
					}
				}
				else
				{
					Hungry = available <= 0f;
					Progress = Consumed / Requirement;
				}
				return num;
			}
			return 0f;
		}

		public LocalizedString GetName()
		{
			return FishProperties.HarvestProperties.LocalizedName;
		}

		public Sprite GetIcon()
		{
			return FishProperties.HarvestProperties.InventorySprite;
		}

		public bool IsWatingForBroodItem()
		{
			if (BroodItem != null && !(_farm == null))
			{
				return BroodItem.Inventory != _farm.Buildable.Inventory;
			}
			return true;
		}

		public PersistentData ReturnPersistentData()
		{
			return new PersistentData(this);
		}
	}

	[Serializable]
	public class PersistentData : BuildableExtendablePersistentData<AquaFarm>
	{
		private int _activeFishPropertiesIndex;

		private Fish.PersistentData[] _broodstock;

		private Fish.PersistentData[] _fishes;

		[NonSerialized]
		private AquaFarm _instance;

		public PersistentData(AquaFarm instance)
			: base(instance)
		{
			_instance = instance;
		}

		public override void PopulateReferences()
		{
			if (_instance == null)
			{
				return;
			}
			_activeFishPropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(_instance.ActiveFishProperties);
			if (!_instance.Broodstock.IsNullOrEmpty())
			{
				int count = _instance.Broodstock.Count;
				_broodstock = new Fish.PersistentData[count];
				for (int i = 0; i < count; i++)
				{
					_broodstock[i] = _instance.Broodstock[i].ReturnPersistentData();
				}
			}
			if (!_instance.Fishes.IsNullOrEmpty())
			{
				int count2 = _instance.Fishes.Count;
				_fishes = new Fish.PersistentData[count2];
				for (int i = 0; i < count2; i++)
				{
					_fishes[i] = _instance.Fishes[i].ReturnPersistentData();
				}
			}
		}

		public override void RestoreData(Buildable buildable)
		{
			buildable.TryReturnBuildableExtendable<AquaFarm>(out _instance);
		}

		public override void RestoreReferences()
		{
			if (_instance == null)
			{
				return;
			}
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<FishProperties>(_activeFishPropertiesIndex, out var reference))
			{
				_instance.ActiveFishProperties = reference;
			}
			if (!((IReadOnlyCollection<Fish.PersistentData>)(object)_broodstock).IsNullOrEmpty())
			{
				for (int i = 0; i < _broodstock.Length; i++)
				{
					if (_instance.Broodstock.Count < _instance.Broodstock.Capacity && _broodstock[i].TryRestore(out var fish, _instance, isBroodfish: true))
					{
						_instance.AddBroodFish(fish);
						if (fish.BroodItem != null && fish.BroodItem.Inventory == _instance.Buildable.Inventory)
						{
							_instance.ItemDistributer.AttachConsumer(fish);
						}
					}
				}
			}
			if (((IReadOnlyCollection<Fish.PersistentData>)(object)_fishes).IsNullOrEmpty())
			{
				return;
			}
			Fish.PersistentData[] fishes = _fishes;
			for (int j = 0; j < fishes.Length; j++)
			{
				if (fishes[j].TryRestore(out var fish2, _instance, isBroodfish: false))
				{
					_instance.Fishes.Add(fish2);
					if (fish2.Progress < 1f)
					{
						_instance.ItemDistributer.AttachConsumer(fish2);
					}
				}
			}
		}
	}

	[Serializable]
	public struct FishPersistentData
	{
		public int PropertiesIndex;

		public float[] Consumed;
	}

	[SerializeField]
	private FishProperties[] _availableFishes;

	[SerializeField]
	private ItemDistributer _itemDistributer;

	[SerializeField]
	private int _broodstockCapacity = 10;

	[SerializeField]
	private int _exportCapacity = 100;

	[Header("Malfunctions")]
	[SerializeField]
	private PlaceableAlertProperties _broodstockItemMissing;

	private List<ItemProperties> _broodStockPropertiesList;

	private List<Item> _itemList = new List<Item>();

	private List<CountedItemProperty> _itemsWaitingForExport = new List<CountedItemProperty>();

	private bool _updated;

	public UnityEvent UpdatedEvent { get; private set; } = new UnityEvent();

	public FishProperties[] AvailableFishProperties => _availableFishes;

	public ItemDistributer ItemDistributer => _itemDistributer;

	public FishProperties ActiveFishProperties { get; private set; }

	public List<Fish> Broodstock { get; private set; }

	public List<Fish> Fishes { get; private set; }

	public int FishCountMaximum => _broodstockCapacity;

	public List<ItemProperties> ProducedItems { get; private set; } = new List<ItemProperties>();

	public ResourceProvider ExportResourceProvider { get; private set; }

	public int PersistentIndex { get; set; }

	private void LateUpdate()
	{
		bool flag = false;
		foreach (Fish item in Broodstock)
		{
			if (!item.TryReserveBroodItem())
			{
				flag = true;
			}
		}
		if (flag)
		{
			AddMalfunction(_broodstockItemMissing ? _broodstockItemMissing : GameManager.Settings.BuildableSettings.ErrorItemsMissingProperties);
		}
		else
		{
			RemoveMalfunction(_broodstockItemMissing ? _broodstockItemMissing : GameManager.Settings.BuildableSettings.ErrorItemsMissingProperties);
		}
		if (_updated)
		{
			_updated = false;
			UpdatedEvent.Invoke();
		}
	}

	public override void Initialize(Buildable buildable, bool restored = false)
	{
		base.Initialize(buildable, restored);
		ActiveFishProperties = _availableFishes[0];
		Broodstock = new List<Fish>(_broodstockCapacity);
		Fishes = new List<Fish>();
		base.Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Storage);
		base.Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Export, _exportCapacity);
		ExportResourceProvider = ResourceProvider.Get(base.Buildable, SubInventoryType.Export, GameManager.ResourceManager, AssignmentType.AnimalHandling);
		ExportResourceProvider.Register();
		base.Buildable.Inventory.InventoryUpdatedEvent.AddListener(OnInventoryUpdated);
		if (_broodStockPropertiesList == null)
		{
			_broodStockPropertiesList = new List<ItemProperties>();
		}
		else
		{
			_broodStockPropertiesList.Clear();
		}
		FishProperties[] availableFishes = _availableFishes;
		foreach (FishProperties fishProperties in availableFishes)
		{
			_broodStockPropertiesList.Add(fishProperties.BroodItemProperties);
		}
		GameEventDispatcher.AddListener(GameEventType.ItemResourceLimitUpdated, OnItemResourceLimitUpdated);
	}

	public override void Remove()
	{
		base.Remove();
		ExportResourceProvider.Unregister();
		base.Buildable.Inventory.InventoryUpdatedEvent.RemoveListener(OnInventoryUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.ItemResourceLimitUpdated, OnItemResourceLimitUpdated);
	}

	public void SetActiveFishProperties(FishProperties fishProperties)
	{
		ActiveFishProperties = fishProperties;
		_updated = true;
	}

	public bool AddBroodFish()
	{
		if (Broodstock.Count < Broodstock.Capacity)
		{
			Fish fish = new Fish(this, ActiveFishProperties, ActiveFishProperties.FeedRequirementBrooding);
			fish.ResetBroodCycle();
			AddBroodFish(fish);
			_updated = true;
			return true;
		}
		UnityEngine.Debug.LogFormat("Unable to add broodfish '{0}'!", ActiveFishProperties.BroodItemProperties);
		return false;
	}

	private void AddBroodFish(Fish broodfish)
	{
		Broodstock.Add(broodfish);
		if (ProducedItems.AddUnique(ActiveFishProperties.HarvestProperties))
		{
			GameManager.ResourceManager.AddProductionLimits(this);
		}
	}

	public void RemoveBroodFish()
	{
		int count = Broodstock.Count;
		while (0 < count--)
		{
			Fish fish = Broodstock[count];
			if (fish.FishProperties == ActiveFishProperties)
			{
				Broodstock.RemoveAt(count);
				_itemDistributer.DetachConsumer(fish);
				_updated = true;
				break;
			}
		}
	}

	private void OnBroodCycleCompleted(Fish broodfish)
	{
		for (int i = 0; i < broodfish.FishProperties.OffspringMaximum; i++)
		{
			Fish fish = new Fish(this, broodfish.FishProperties, broodfish.FishProperties.FeedRequirementGrowing);
			Fishes.Add(fish);
			_itemDistributer.AttachConsumer(fish);
		}
		_updated = true;
	}

	private void OnFishCompleted(Fish fish)
	{
		_itemDistributer.DetachConsumer(fish);
		base.Buildable.Inventory.AddItem(new Item(fish.FishProperties.HarvestProperties), SubInventoryType.Export);
		ItemEvent.Dispatch(GameEventType.ItemFarmed, fish.FishProperties.HarvestProperties);
		CountCompletedFish(fish);
	}

	private void CountCompletedFish(Fish fish)
	{
		_updated = true;
		foreach (CountedItemProperty item in _itemsWaitingForExport)
		{
			if (item.ItemProperties == fish.FishProperties.HarvestProperties)
			{
				item.Amount++;
				return;
			}
		}
		_itemsWaitingForExport.Add(new CountedItemProperty(fish.FishProperties.HarvestProperties, 1));
	}

	private void OnInventoryUpdated()
	{
		_itemList.Clear();
		base.Buildable.Inventory.ReturnAllItems(SubInventoryType.Import, _itemList);
		foreach (Item item in _itemList)
		{
			TrySetBroodItem(item);
		}
		foreach (CountedItemProperty item2 in _itemsWaitingForExport)
		{
			int num = base.Buildable.Inventory.ReturnCount(item2.ItemProperties, SubInventoryType.Export, includeReserved: true);
			int num2 = item2.Amount - num;
			while (0 < num2--)
			{
				foreach (Fish fish in Fishes)
				{
					if (1f <= fish.Progress && fish.FishProperties.HarvestProperties == item2.ItemProperties)
					{
						Fishes.Remove(fish);
						_updated = true;
						break;
					}
				}
			}
			item2.Amount = num;
		}
	}

	private void TrySetBroodItem(Item item)
	{
		foreach (Fish item2 in Broodstock)
		{
			if (item2.BroodItem == item)
			{
				if (!GameManager.ResourceManager.IsProductionLimitReached(item2.FishProperties.HarvestProperties))
				{
					_itemDistributer.AttachConsumer(item2);
				}
				base.Buildable.Inventory.MoveToSubInventory(item, SubInventoryType.Storage);
				_updated = true;
				break;
			}
		}
	}

	private void AttachFishes(List<Fish> fishes, FishProperties fishProperties)
	{
		foreach (Fish fish in fishes)
		{
			if (fish.Progress < 1f && fish.FishProperties == fishProperties)
			{
				_itemDistributer.AttachConsumer(fish);
			}
		}
	}

	private void DetachFishes(List<Fish> fishes, FishProperties fishProperties)
	{
		foreach (Fish fish in fishes)
		{
			if (fish.FishProperties == fishProperties)
			{
				_itemDistributer.DetachConsumer(fish);
			}
		}
	}

	int IItemProducer.GetItemsInProductionCount(ItemProperties itemProperties)
	{
		int num = 0;
		foreach (Fish fish in Fishes)
		{
			if (fish.FishProperties.HarvestProperties == itemProperties)
			{
				num++;
			}
		}
		return num;
	}

	public void ReturnDailyConsumption(out float dailyConsumption, out int itemCount)
	{
		_itemDistributer.ReturnDailyConsumption(ActiveFishProperties.FeedItemProperties, out dailyConsumption, out itemCount);
	}

	public int ReturnBroodstockCount(FishProperties fishProperties)
	{
		return ReturnFishCount(Broodstock, fishProperties);
	}

	public int ReturnConsumingBroodstockCount(FishProperties fishProperties)
	{
		return ReturnConsumingFishCount(Broodstock, fishProperties);
	}

	public int ReturnFishCount(FishProperties fishProperties)
	{
		return ReturnFishCount(Fishes, fishProperties);
	}

	public int ReturnConsumingFishCount(FishProperties fishProperties)
	{
		return ReturnConsumingFishCount(Fishes, fishProperties);
	}

	private int ReturnFishCount(List<Fish> fishes, FishProperties fishProperties)
	{
		int num = 0;
		foreach (Fish fish in fishes)
		{
			if (fish.FishProperties == fishProperties)
			{
				num++;
			}
		}
		return num;
	}

	private int ReturnConsumingFishCount(List<Fish> fishes, FishProperties fishProperties)
	{
		int num = 0;
		foreach (Fish fish in fishes)
		{
			if (fish.FishProperties == fishProperties && fish.Progress < 1f)
			{
				num++;
			}
		}
		return num;
	}

	private void OnItemResourceLimitUpdated(GameEvent gameEvent)
	{
		if (!(gameEvent is ItemEvent itemEvent) || !ProducedItems.Contains(itemEvent.ItemProperties))
		{
			return;
		}
		ResourceManager resourceManager = GameManager.ResourceManager;
		FishProperties[] availableFishes = _availableFishes;
		foreach (FishProperties fishProperties in availableFishes)
		{
			if (!resourceManager.IsProductionLimitReached(fishProperties.HarvestProperties))
			{
				AttachFishes(Broodstock, fishProperties);
			}
		}
	}

	public override IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new PersistentData(this);
	}
}
public class Desalinator : MonoBehaviour
{
	[SerializeField]
	private Producer _producer;

	[SerializeField]
	private float _pollutionRadius = 15f;

	[SerializeField]
	private ParticleSystem _particleSystem;

	private float _pollutionPerSecond;

	private void Awake()
	{
		if (!(_producer == null))
		{
			_producer.OnStartProducing.AddListener(OnProductionStarted);
			_producer.OnStopProducing.AddListener(OnProductionStopped);
		}
	}

	private void LateUpdate()
	{
		if (_pollutionPerSecond <= 0f)
		{
			return;
		}
		Vector3 position = base.transform.position;
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent.transform.position.IsInRangeXZ(position, _pollutionRadius))
			{
				agent.Vitals.Pollution.Increase(_pollutionPerSecond * TimeManager.GetDeltaTime());
			}
		}
	}

	private void OnDestroy()
	{
		if (!(_producer == null))
		{
			_producer.OnStartProducing.RemoveListener(OnProductionStarted);
			_producer.OnStopProducing.RemoveListener(OnProductionStopped);
		}
	}

	private void OnProductionStarted(Buildable buildable)
	{
		GameEventDispatcher.AddListener(GameEventType.TownheartMoved, UpdatePollutionPerSecond);
		UpdatePollutionPerSecond();
	}

	private void OnProductionStopped(Buildable buildable)
	{
		GameEventDispatcher.RemoveListener(GameEventType.TownheartMoved, UpdatePollutionPerSecond);
		_pollutionPerSecond = 0f;
		if ((bool)_particleSystem)
		{
			_particleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
	}

	private void UpdatePollutionPerSecond(GameEvent gameEvent = null)
	{
		_pollutionPerSecond = ReturnPollutionPerSecond();
		if (0f < _pollutionPerSecond && (bool)_particleSystem)
		{
			_particleSystem.Play();
		}
	}

	private float ReturnPollutionPerSecond()
	{
		if (GameManager.WorldManager.CurrentRegion.PollutionLevel == PollutionLevels.None)
		{
			return 0f;
		}
		foreach (QueuedRecipe queuedRecipe in _producer.QueuedRecipes)
		{
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
			{
				return queuedRecipe.Pollution / queuedRecipe.ProductionTime;
			}
		}
		return 0f;
	}
}
[RequireComponent(typeof(Construction))]
public class Producer : BuildableExtendableBase, IEnergyGridConsumer, IEnergyGridComponent, IItemProducer, IBlockingProjectProvider, IPersistentReference
{
	public enum Type
	{
		Workshop,
		Farm
	}

	public enum ContinuousMode
	{
		Single,
		SingleFillQueue,
		Multiple
	}

	public class Recipe : IComparable<Recipe>
	{
		private int _persistedQueueIndex = int.MaxValue;

		public Producer Producer { get; private set; }

		public int Index { get; private set; }

		public ProductionRecipeProperties Properties { get; private set; }

		public int AmountToProduce { get; private set; }

		public IReadOnlyList<CountedItemProperty> Ingredients => Properties.RequiredItems;

		public IReadOnlyList<CountedItemProperty> ProducedItems => Properties.ProducedItems;

		public bool IsContinuous => AmountToProduce < 0;

		public bool IsPrioritized { get; private set; }

		public List<PlaceableAlertProperties> Malfunctions { get; private set; } = new List<PlaceableAlertProperties>();

		public Recipe(Producer producer, int index, ProductionRecipeProperties properties)
		{
			Producer = producer;
			Index = index;
			Properties = properties;
		}

		public void SetAmountToProduce(int amount)
		{
			AmountToProduce = Mathf.Clamp(amount, 0, 99);
		}

		public void IncreaseAmountToProduce(int amount = 1)
		{
			AmountToProduce = Mathf.Min(AmountToProduce + amount, 99);
		}

		public void DecreaseAmountToProduce(int amount = 1)
		{
			int num = GetQueuedCount();
			AmountToProduce = Mathf.Max(AmountToProduce - amount, 0);
			while (AmountToProduce < num && Producer.CancelLastQueuedRecipe(this))
			{
				num--;
			}
		}

		public bool ToggleContinuous()
		{
			if (IsContinuous)
			{
				DisableContinuous();
				return false;
			}
			AmountToProduce = -1;
			return true;
		}

		public void DisableContinuous()
		{
			int num = 0;
			foreach (QueuedRecipe queuedRecipe in Producer.QueuedRecipes)
			{
				if (queuedRecipe.Recipe == this)
				{
					num++;
				}
			}
			AmountToProduce = num;
		}

		public void OnQueuedRecipeRemoved(QueuedRecipe queuedRecipe)
		{
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToExportItems)
			{
				if (0 < AmountToProduce)
				{
					AmountToProduce--;
				}
			}
			else
			{
				DisableContinuous();
			}
		}

		public bool AddMallfunction(PlaceableAlertProperties malfunction)
		{
			if (GetQueuedCount() == 0)
			{
				return Malfunctions.AddUnique(malfunction);
			}
			return false;
		}

		public void PopulateMalfunctions(List<PlaceableAlertProperties> malfunctions, PlaceableAlertProperties.AlertType minimumAlertType)
		{
			foreach (PlaceableAlertProperties malfunction in Malfunctions)
			{
				if (minimumAlertType <= malfunction.Alert)
				{
					malfunctions.AddUnique(malfunction);
				}
			}
		}

		public bool ClearMalfunctions()
		{
			if (Malfunctions.Count == 0)
			{
				return false;
			}
			Malfunctions.Clear();
			return true;
		}

		public bool IsUnlocked()
		{
			return Properties.IsUnlocked();
		}

		public bool IsWaitingToBeQueued()
		{
			if (AmountToProduce >= 0)
			{
				return 0 < AmountToProduce - GetQueuedCount();
			}
			return true;
		}

		public Sprite GetIcon(ItemProperties itemProperties)
		{
			return Properties.ReturnIcon(itemProperties);
		}

		public ItemProperties GetFirstIngredientItemProperties()
		{
			return Properties.ReturnFirstRequiredItemProperties();
		}

		public ItemProperties GetFirstProducedItemProperties()
		{
			return Properties.ReturnFirstProducedItemProperties();
		}

		private int GetQueuedCount()
		{
			int num = 0;
			foreach (QueuedRecipe queuedRecipe in Producer.QueuedRecipes)
			{
				if (queuedRecipe.Recipe == this)
				{
					num++;
				}
			}
			return num;
		}

		public void Restore(ProducerPersistentData.Recipe persistentData)
		{
			AmountToProduce = persistentData.AmountToProduce;
			IsPrioritized = persistentData.IsPrioritized;
			_persistedQueueIndex = persistentData.QueueIndex;
		}

		public int CompareTo(Recipe other)
		{
			return _persistedQueueIndex - other._persistedQueueIndex;
		}
	}

	[SerializeField]
	private ProductionProperties _properties;

	[SerializeField]
	private AssignmentType _additionalAssignmentType;

	[SerializeField]
	[FormerlySerializedAs("WorkerSlots")]
	private AttachableSlots _workerSlots;

	[SerializeField]
	[FormerlySerializedAs("FarmSlots")]
	private FarmSlots _farmSlots;

	[SerializeField]
	[FormerlySerializedAs("ImportSlots")]
	private InventorySlots _importSlots;

	[FormerlySerializedAs("ExportSlots")]
	[SerializeField]
	private InventorySlots _exportSlots;

	private IProducerVisualHelper[] _producerVisualHelpers;

	private static readonly Queue<Producer> _producerQueue = new Queue<Producer>();

	private readonly List<Agent> _attachedWorkers = new List<Agent>();

	private ProjectSettings _projectSettings;

	private ContinuousMode _continuousMode;

	private bool _queuedUpdated;

	private int _queueContinuousRecipeThreshold = -1;

	private bool _wasRestored;

	public Project ProductionProject { get; set; }

	public Project ImportProject { get; private set; }

	public int SelectedRecipeIndex { get; private set; }

	public Recipe SelectedRecipe => Recipes[SelectedRecipeIndex];

	public List<Recipe> Recipes { get; private set; } = new List<Recipe>();

	public List<Recipe> RecipeQueue { get; private set; } = new List<Recipe>();

	public List<QueuedRecipe> QueuedRecipes { get; private set; } = new List<QueuedRecipe>();

	public QueuedRecipe ProductionRecipe
	{
		get
		{
			if (QueuedRecipes.Count <= 0)
			{
				return null;
			}
			return QueuedRecipes[0];
		}
	}

	public bool HasEnergyCost { get; private set; }

	public int SelectedFuelIndex { get; private set; }

	public int MaximumQueuedRecipes { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public bool IsBlockedByImport { get; set; }

	public bool IsProducingItems { get; set; }

	public int MaxProducedItemCount { get; private set; }

	public ResourceProvider ExportResourceProvider { get; private set; }

	public List<ItemProperties> ProducedItems { get; private set; } = new List<ItemProperties>();

	public IReadOnlyList<Agent> AttachedWorkers => _attachedWorkers;

	public ProjectSettings.Priority Priority { get; private set; }

	public int QueueContinuousRecipeThreshold
	{
		get
		{
			return _queueContinuousRecipeThreshold;
		}
		set
		{
			_queueContinuousRecipeThreshold = Mathf.Clamp(value, 1, MaximumQueuedRecipes);
		}
	}

	public ProductionProperties ProductionProperties => _properties;

	public EnergyGridConnector Connector { get; set; }

	public EnergyGrid EnergyGrid => Connector.EnergyGrid;

	public float CurrentEnergyConsumption => ReturnCurrentEnergyConsumption();

	public float EnergyRequirement => ReturnCurrentEnergyRequirement();

	public UnityEvent<Buildable> OnStartProducing { get; private set; } = new UnityEvent<Buildable>();

	public UnityEvent<Buildable> OnStopProducing { get; private set; } = new UnityEvent<Buildable>();

	[HideInInspector]
	public event BuildableEventHandler QueueUpdatedEvent;

	protected override void Awake()
	{
		HasEnergyCost = _properties.EnergyCost > 0f;
		base.Awake();
	}

	private void Start()
	{
		StopDuplicateProjects(ImportProject);
		StopDuplicateProjects(ProductionProject);
	}

	private void Update()
	{
		if (!IsEnabled())
		{
			return;
		}
		switch (_properties.Type)
		{
		case Type.Workshop:
			if (ProductionRecipe != null)
			{
				AdvanceQueuedRecipeStage(ProductionRecipe, !ProductionRecipe.RequiresPerson);
			}
			break;
		case Type.Farm:
		{
			for (int i = 0; i < QueuedRecipes.Count; i++)
			{
				AdvanceQueuedRecipeStage(QueuedRecipes[i], autoProduce: true);
			}
			break;
		}
		}
	}

	private void LateUpdate()
	{
		if (base.Buildable.IsActive && base.Buildable.BuildPhase == BuildPhase.Finished && QueuedRecipes.Count == 0 && base.Buildable.Inventory.ReturnCount(SubInventoryType.Export, includeReserved: true) == 0)
		{
			if (_properties.Type == Type.Workshop)
			{
				base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusQueueEmptyProperties);
			}
			else
			{
				base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusIdleProperties);
			}
		}
		TryQueueRecipe();
		if (_queuedUpdated)
		{
			_queuedUpdated = false;
			this.QueueUpdatedEvent?.Invoke();
		}
	}

	private void OnDestroy()
	{
		_producerQueue?.Remove(this);
		ExportResourceProvider.Unregister();
		UninitializeProjects();
		RemoveListeners();
		if (base.gameObject.scene.isLoaded)
		{
			ImportProject?.Stop(ProjectFlags.BuildableRemoved);
		}
		if (_properties.Type == Type.Workshop)
		{
			_importSlots.Remove();
			_exportSlots.Remove();
		}
	}

	public override void Initialize(Buildable buildable, bool restored = false)
	{
		base.Initialize(buildable, restored);
		AssignmentType assignmentType = _additionalAssignmentType;
		if (HasEnergyCost)
		{
			if (TryGetComponent<EnergyGridConnector>(out var component))
			{
				Connector = component;
				Connector.AddComponent(this);
			}
			else
			{
				UnityEngine.Debug.LogError("Producer " + base.name + " that requires fuel does not have an EnergyGridConnector.");
			}
		}
		for (int i = 0; i < ProductionProperties.Recipes.Count; i++)
		{
			AddRecipe(i);
		}
		base.Buildable.Community.AddProducer(this);
		if (ProductionProperties.ProductionProject != null)
		{
			assignmentType |= ProductionProperties.ProductionProject.AssignmentType;
		}
		base.Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Import);
		base.Buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Export, _properties.ExportCapacity);
		ExportResourceProvider = ResourceProvider.Get(base.Buildable, SubInventoryType.Export, ReturnInventorySpaceLimiter(), assignmentType);
		base.Buildable.Inventory.InventoryUpdatedEvent.AddListener(UpdateImports);
		base.Buildable.Inventory.InventoryUpdatedEvent.AddListener(UpdateExports);
		AddNewFoundItems();
		_producerVisualHelpers = GetComponentsInChildren<IProducerVisualHelper>(includeInactive: true);
		switch (_properties.Type)
		{
		case Type.Farm:
			_farmSlots.Initialize();
			MaximumQueuedRecipes = _properties.SlotAmount;
			break;
		case Type.Workshop:
			_importSlots.Initialize(base.Buildable.Inventory, SubInventoryType.Import, base.Buildable.OutlineRenderer);
			_exportSlots.Initialize(base.Buildable.Inventory, SubInventoryType.Export, base.Buildable.OutlineRenderer);
			MaximumQueuedRecipes = GameManager.Settings.BuildableSettings.MaximumQueuedRecipes;
			if (_queueContinuousRecipeThreshold < 1)
			{
				_queueContinuousRecipeThreshold = MaximumQueuedRecipes;
			}
			break;
		}
		_projectSettings = GameManager.Settings.ProjectSettings;
		Priority = _projectSettings.ProducerProjectDefaultPriority;
		_continuousMode = GameSettings.Instance.GameplaySettings.ProducerContinuousMode;
	}

	private void InitializeProjects()
	{
		AssignmentType assignmentType = _additionalAssignmentType;
		if (ProductionProperties.ProductionProject != null)
		{
			assignmentType |= ProductionProperties.ProductionProject.AssignmentType;
		}
		if (_properties.Type == Type.Workshop && ProductionProject == null)
		{
			ProductionProject = new Project(_properties.ProductionProject, base.gameObject);
			ProductionProject.SetBlockingProjectProvider(this);
			base.Buildable.Community.QueueProject(ProductionProject);
		}
		if (ImportProject == null)
		{
			ImportProject = new Project(GameManager.Settings.ProjectSettings.ImportProperties, base.gameObject);
			ImportProject.AddAssignmentType(assignmentType);
			base.Buildable.Community.QueueProject(ImportProject);
		}
	}

	private void UninitializeProjects()
	{
		ProductionProject?.Stop(ProjectFlags.BuildableRemoved);
		ProductionProject = null;
		ImportProject?.Stop(ProjectFlags.BuildableRemoved);
		ImportProject = null;
	}

	public override void Finish(bool restored = false)
	{
		ExportResourceProvider.Register();
		if (!restored)
		{
			InitializeProjects();
		}
		switch (_properties.Type)
		{
		case Type.Farm:
			SetSelectedRecipe(0);
			if (!restored && QueuedRecipes.Count < MaximumQueuedRecipes)
			{
				for (int i = 0; i < MaximumQueuedRecipes; i++)
				{
					QueuedRecipes.Add(QueuedRecipe.Get());
				}
			}
			break;
		case Type.Workshop:
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusQueueEmptyProperties);
			break;
		}
		if (_properties.AutomaticallyStart)
		{
			SetSelectedRecipe(0);
		}
		_producerQueue.Enqueue(this);
	}

	public override void Remove()
	{
		ExportResourceProvider.Unregister();
		UninitializeProjects();
		RemoveListeners();
		for (int i = 0; i < QueuedRecipes.Count; i++)
		{
			QueuedRecipes[i].Reset();
		}
		if (HasEnergyCost)
		{
			Connector.RemoveComponent(this);
		}
		base.Buildable.Community.RemoveProducer(this);
	}

	private void RemoveListeners()
	{
		base.Buildable.Inventory.InventoryUpdatedEvent.RemoveListener(UpdateImports);
		base.Buildable.Inventory.InventoryUpdatedEvent.RemoveListener(UpdateExports);
	}

	private void AddNewFoundItems()
	{
		for (int i = 0; i < ProductionProperties.Recipes.Count; i++)
		{
			ProductionRecipeProperties productionRecipeProperties = ProductionProperties.Recipes[i];
			for (int j = 0; j < productionRecipeProperties.ProducedItems.Count; j++)
			{
				CountedItemProperty countedItemProperty = productionRecipeProperties.ProducedItems[j];
				Community.PlayerCommunity.AddFoundItem(countedItemProperty.ItemProperties);
			}
		}
	}

	public void AddRecipe(int index)
	{
		Recipe recipe = new Recipe(this, index, ProductionProperties.Recipes[index]);
		Recipes.Add(recipe);
		RecipeQueue.Add(recipe);
		foreach (CountedItemProperty producedItem in recipe.ProducedItems)
		{
			ProducedItems.AddUnique(producedItem.ItemProperties);
		}
	}

	public void SetSelectedRecipe(int recipeIndex)
	{
		if (!_properties.Recipes.IsValidIndex(recipeIndex))
		{
			UnityEngine.Debug.LogException(new ArgumentException($"Trying to set SelectedRecipeIndex to {recipeIndex} for producer '{_properties}' which has {_properties.Recipes.Count} recipes"));
		}
		SelectedRecipeIndex = _properties.Recipes.ClampIndex(recipeIndex);
		if (recipeIndex < 0 || recipeIndex >= _properties.Recipes.Count)
		{
			base.Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorItemsMissingProperties);
			if (IsEnabled())
			{
				base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusNoRecipeSelectedProperties);
			}
		}
		else if (IsEnabled())
		{
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusIdleProperties);
		}
		if (_properties.Type != Type.Farm)
		{
			return;
		}
		foreach (QueuedRecipe queuedRecipe in QueuedRecipes)
		{
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToReserveItems)
			{
				queuedRecipe.Reset(SelectedRecipeIndex, Recipes);
			}
		}
		if (TryReturnRecipe(SelectedRecipeIndex, out var recipe))
		{
			ExportResourceProvider.OverrideCapacity(recipe.ProducedItems.Count * _properties.SlotAmount);
		}
	}

	public void ToggleSelecteRecipeContinuous()
	{
		if (SelectedRecipe == null || !SelectedRecipe.ToggleContinuous())
		{
			return;
		}
		ContinuousMode continuousMode = _continuousMode;
		if ((uint)continuousMode <= 1u)
		{
			foreach (Recipe recipe in Recipes)
			{
				if (recipe != SelectedRecipe)
				{
					recipe.DisableContinuous();
				}
			}
		}
		QueueRecipes(SelectedRecipe, MaximumQueuedRecipes);
		_queuedUpdated = true;
	}

	private bool QueueRecipe(Recipe recipe)
	{
		if (QueuedRecipes.Count < MaximumQueuedRecipes && TryReserveRequiredItems(out var reservedItems, recipe, handleMalfunctions: true))
		{
			QueuedRecipe queuedRecipe = QueuedRecipe.Get(recipe);
			queuedRecipe.RecipeItems = reservedItems;
			queuedRecipe.RecipeStage = QueuedRecipe.Stage.WaitingToImport;
			AddQueuedRecipe(queuedRecipe);
			AddQueuedRecipeItemsToImportProject(queuedRecipe);
			UpdateImports();
			_queuedUpdated = true;
			return true;
		}
		return false;
	}

	private void QueueRecipes(Recipe recipe, int amount)
	{
		for (int i = 0; i < amount; i++)
		{
			if (!QueueRecipe(recipe))
			{
				break;
			}
		}
	}

	private bool TryQueueRecipe()
	{
		if (QueuedRecipes.Count >= MaximumQueuedRecipes)
		{
			return false;
		}
		bool result = false;
		for (int i = 0; i < RecipeQueue.Count; i++)
		{
			Recipe recipe = RecipeQueue[i];
			if (!recipe.IsWaitingToBeQueued())
			{
				continue;
			}
			result = true;
			if (QueueRecipe(recipe))
			{
				if (!recipe.IsPrioritized)
				{
					RecipeQueue.RemoveAt(i);
					RecipeQueue.Add(recipe);
				}
				return true;
			}
		}
		return result;
	}

	public void IncreaseSelectedRecipeAmountToProduce()
	{
		SelectedRecipe.IncreaseAmountToProduce();
		RecipeQueue.Remove(SelectedRecipe);
		RecipeQueue.Insert(0, SelectedRecipe);
		TryQueueRecipe();
	}

	public void AddQueuedRecipe(QueuedRecipe queuedRecipe)
	{
		QueuedRecipes.Add(queuedRecipe);
		foreach (CountedItemProperty producedItem in queuedRecipe.ProducedItems)
		{
			ItemEvent.Dispatch(GameEventType.ProducerItemQueued, producedItem.ItemProperties);
		}
		_queuedUpdated = true;
	}

	private void RemoveQueuedRecipe(QueuedRecipe queuedRecipe)
	{
		if (base.Buildable.BuildPhase == BuildPhase.Finished && _properties.Type == Type.Farm)
		{
			UnityEngine.Debug.LogException(new Exception("Queued recipes should never be removed from an active producer of type 'FARM'"));
		}
		else if (QueuedRecipes.Remove(queuedRecipe))
		{
			queuedRecipe.Recipe.OnQueuedRecipeRemoved(queuedRecipe);
			queuedRecipe.Release();
			if (QueuedRecipes.Count == 0)
			{
				base.Buildable.RemoveAllMalfunctions();
				base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusQueueEmptyProperties);
			}
			_queuedUpdated = true;
		}
	}

	public void CancelRecipe(int index)
	{
		if (index < QueuedRecipes.Count)
		{
			QueuedRecipe queuedRecipe = QueuedRecipes[index];
			switch (queuedRecipe.RecipeStage)
			{
			case QueuedRecipe.Stage.WaitingToProduce:
			case QueuedRecipe.Stage.Producing:
				base.Buildable.Inventory.ExportItems(queuedRecipe.RecipeItems);
				break;
			case QueuedRecipe.Stage.WaitingToExportItems:
				return;
			}
			if (_properties.Type == Type.Farm)
			{
				_farmSlots.Remove(index);
			}
			RemoveQueuedRecipe(queuedRecipe);
			CleanImportInventory();
		}
	}

	public bool CancelLastQueuedRecipe(Recipe recipe)
	{
		int count = QueuedRecipes.Count;
		while (0 < count--)
		{
			QueuedRecipe queuedRecipe = QueuedRecipes[count];
			if (queuedRecipe.Recipe == recipe && CancelQueuedRecipe(queuedRecipe))
			{
				return true;
			}
		}
		return false;
	}

	private bool CancelQueuedRecipe(QueuedRecipe queuedRecipe)
	{
		switch (queuedRecipe.RecipeStage)
		{
		case QueuedRecipe.Stage.WaitingToProduce:
		case QueuedRecipe.Stage.Producing:
			base.Buildable.Inventory.ExportItems(queuedRecipe.RecipeItems);
			break;
		case QueuedRecipe.Stage.WaitingToExportItems:
			return false;
		}
		if (_properties.Type == Type.Farm)
		{
			throw new NotImplementedException();
		}
		RemoveQueuedRecipe(queuedRecipe);
		CleanImportInventory();
		return true;
	}

	public static void UpdateQueuedProducer()
	{
		if (_producerQueue == null)
		{
			return;
		}
		int count = _producerQueue.Count;
		for (int i = 0; i < count; i++)
		{
			if (!_producerQueue.TryDequeue(out var result) || !result)
			{
				continue;
			}
			_producerQueue.Enqueue(result);
			switch (result._properties.Type)
			{
			case Type.Farm:
				if (result.UpdateQueuedRecipeItems())
				{
					return;
				}
				break;
			case Type.Workshop:
				if (result.TryQueueRecipe())
				{
					return;
				}
				break;
			}
		}
	}

	private bool UpdateQueuedRecipeItems()
	{
		if (QueuedRecipes.IsNullOrEmpty())
		{
			return false;
		}
		using ListPool<Recipe>.List list = ListPool<Recipe>.Get(_properties.Recipes.Count);
		for (int i = 0; i < QueuedRecipes.Count; i++)
		{
			QueuedRecipe queuedRecipe = QueuedRecipes[i];
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToReserveItems && !list.Contains(queuedRecipe.Recipe) && !TryToReserveRequiredItems(queuedRecipe, i == 0))
			{
				list.Add(queuedRecipe.Recipe);
			}
		}
		UpdateImports();
		return true;
	}

	private bool TryToReserveRequiredItems(QueuedRecipe queuedRecipe, bool canChangeMalfunctions)
	{
		if (TryReserveRequiredItems(out var reservedItems, ProductionRecipe.Recipe, canChangeMalfunctions))
		{
			queuedRecipe.RecipeItems = reservedItems;
			queuedRecipe.RecipeStage = QueuedRecipe.Stage.WaitingToImport;
			_queuedUpdated = true;
			AddQueuedRecipeItemsToImportProject(queuedRecipe);
			return true;
		}
		return false;
	}

	private bool TryReserveRequiredItems(out List<Item> reservedItems, Recipe recipe, bool handleMalfunctions)
	{
		reservedItems = null;
		if (!IsEnabled() || recipe == null)
		{
			return false;
		}
		bool flag = recipe.ClearMalfunctions();
		try
		{
			foreach (CountedItemProperty producedItem in recipe.ProducedItems)
			{
				if (_properties.Type == Type.Workshop && GameManager.ResourceManager.IsProductionLimitReached(producedItem.ItemProperties, producedItem.Amount))
				{
					flag = handleMalfunctions && recipe.AddMallfunction(GameManager.Settings.BuildableSettings.ErrorProductionLimitReachedProperties);
					return false;
				}
			}
			if (!ResourceManager.AreItemsAvailable(recipe.Ingredients))
			{
				flag = handleMalfunctions && _properties.Type == Type.Workshop && recipe.AddMallfunction(GameManager.Settings.BuildableSettings.ErrorItemsMissingProperties);
				return false;
			}
			reservedItems = ResourceManager.ReserveClosestItems(base.Buildable, recipe.Ingredients);
			return true;
		}
		finally
		{
			if (flag)
			{
				UpdateMalfunctions();
			}
		}
	}

	private void AddQueuedRecipeItemsToImportProject(QueuedRecipe queuedRecipe)
	{
		using ListPool<Item>.List list = ListPool<Item>.Get();
		int count = queuedRecipe.RecipeItems.Count;
		while (0 < count--)
		{
			Item item = queuedRecipe.RecipeItems[count];
			if (item.Inventory == base.Buildable.Inventory)
			{
				if (item.SubInventory != SubInventoryType.Import)
				{
					base.Buildable.Inventory.MoveToSubInventory(item, SubInventoryType.Import);
				}
			}
			else
			{
				list.Add(item);
			}
		}
		if (0 < list.Count)
		{
			ImportProject.AddItems(list);
		}
		else if (!HasEnergyCost)
		{
			queuedRecipe.RecipeStage = QueuedRecipe.Stage.WaitingToProduce;
		}
	}

	private void UpdateImports()
	{
		CleanImportInventory();
		for (int i = 0; i < QueuedRecipes.Count; i++)
		{
			QueuedRecipe queuedRecipe = QueuedRecipes[i];
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToImport && queuedRecipe.AreItemsInInventory(base.Buildable.Inventory, SubInventoryType.Import))
			{
				queuedRecipe.RecipeStage = QueuedRecipe.Stage.WaitingToProduce;
			}
		}
		_queuedUpdated = true;
	}

	private void CleanImportInventory()
	{
		using ListPool<Item>.List list = ListPool<Item>.Get();
		base.Buildable.Inventory.ReturnAllItems(SubInventoryType.Import, list);
		foreach (Item item in list)
		{
			if (!ReturnIsRecipeItem(item))
			{
				base.Buildable.Inventory.ExportItem(item);
			}
		}
	}

	private void UpdateExports()
	{
		for (int i = 0; i < QueuedRecipes.Count; i++)
		{
			QueuedRecipe queuedRecipe = QueuedRecipes[i];
			if (queuedRecipe.Recipe == null)
			{
				continue;
			}
			if (base.Buildable.Inventory.ReturnCapacity(SubInventoryType.Export) >= base.Buildable.Inventory.ReturnCount(SubInventoryType.Export) + queuedRecipe.ProducedItems.Count)
			{
				base.Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorExportStorageFullProperties);
			}
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToExportItems && !queuedRecipe.AreItemsInInventory(base.Buildable.Inventory, SubInventoryType.Export))
			{
				Type type = _properties.Type;
				if (type != Type.Workshop && type == Type.Farm)
				{
					queuedRecipe.Reset(SelectedRecipeIndex, Recipes, resetRecipeState: true);
					_farmSlots.Remove(i);
				}
			}
		}
		_queuedUpdated = true;
	}

	private void FinishQueuedRecipe(QueuedRecipe queuedRecipe)
	{
		queuedRecipe.Finish();
		base.Buildable.Inventory.AddItems(queuedRecipe.RecipeItems, SubInventoryType.Export);
		ItemEvent.DispatchItemsProduced(ProductionRecipe.RecipeItems);
		AudioManager.PlayOneShot(_properties.FMODEventReference_FarmItemCompleted, base.transform);
		switch (_properties.Type)
		{
		case Type.Workshop:
			RemoveQueuedRecipe(queuedRecipe);
			break;
		case Type.Farm:
			_farmSlots.Finish(QueuedRecipes.IndexOf(queuedRecipe));
			break;
		}
		_queuedUpdated = true;
	}

	public void DecreasePriority()
	{
		int index = _projectSettings.ProducerProjectPriorities.IndexOf(Priority);
		if (0 < index--)
		{
			ProjectSettings.Priority priority = _projectSettings.ProducerProjectPriorities[index];
			SetPriority(priority);
			ProductionRecipeEvent.DispatchPriorityChange(priority.Score);
		}
	}

	public void IncreasePriority()
	{
		int num = _projectSettings.ProducerProjectPriorities.IndexOf(Priority) + 1;
		if (num < _projectSettings.ProducerProjectPriorities.Count)
		{
			ProjectSettings.Priority priority = _projectSettings.ProducerProjectPriorities[num];
			SetPriority(priority);
			ProductionRecipeEvent.DispatchPriorityChange(priority.Score);
		}
	}

	private void SetPriority(ProjectSettings.Priority priority)
	{
		Priority = priority;
		ImportProject.SetPriority(Priority.Score);
		if (ProductionProperties.Type == Type.Workshop)
		{
			ProductionProject.SetPriority(Priority.Score);
		}
	}

	public void AttachWorker(Agent worker)
	{
		_attachedWorkers.Add(worker);
		_workerSlots.Attach(worker.transform);
	}

	public void DetachWorker(Agent worker, Transform newParent)
	{
		_attachedWorkers.Remove(worker);
		_workerSlots.Detach(worker.transform, newParent);
	}

	public void AdvanceQueuedRecipeStage(QueuedRecipe queuedRecipe, bool autoProduce)
	{
		switch (queuedRecipe.RecipeStage)
		{
		case QueuedRecipe.Stage.WaitingToImport:
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusWaitingForResourcesProperties);
			break;
		case QueuedRecipe.Stage.WaitingToProduce:
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusWaitingForProducerProperties);
			if (IsBlockedByImport)
			{
				break;
			}
			if (base.Buildable.Inventory.ReturnCapacity(SubInventoryType.Export) < base.Buildable.Inventory.ReturnCount(SubInventoryType.Export) + queuedRecipe.ReturnProducedItemCount())
			{
				base.Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorExportStorageFullProperties);
				break;
			}
			if (HasEnergyCost)
			{
				if (!Connector.EnergyGrid.HasEnergy)
				{
					base.Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorNoEnergyProperties);
					break;
				}
				base.Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorNoEnergyProperties);
			}
			if (autoProduce)
			{
				StartProducing(queuedRecipe);
			}
			UpdateProducerVisuals(queuedRecipe);
			break;
		case QueuedRecipe.Stage.Producing:
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusWorkingProperties);
			if (autoProduce)
			{
				if (HasEnergyCost && !Connector.EnergyGrid.HasEnergy)
				{
					StopProducing();
				}
				Produce(queuedRecipe);
			}
			UpdateProducerVisuals(queuedRecipe);
			if (!(queuedRecipe.Progress < queuedRecipe.ProductionTime))
			{
				FinishQueuedRecipe(queuedRecipe);
			}
			break;
		case QueuedRecipe.Stage.WaitingToExportItems:
			base.Buildable.SetStatus(GameManager.Settings.BuildableSettings.StatusProducerHaulingItemstoStorageProperties);
			if (queuedRecipe.RecipeItems.Count == 0)
			{
				UnityEngine.Debug.LogException(new Exception("QueuedRecipe with 0 recipe item is waiting to export items which should be impossible...!"));
				if (_properties.Type == Type.Workshop)
				{
					RemoveQueuedRecipe(queuedRecipe);
				}
				else
				{
					queuedRecipe.Reset(SelectedRecipeIndex, Recipes, resetRecipeState: true);
				}
			}
			break;
		case QueuedRecipe.Stage.WaitingToReserveItems:
			break;
		}
	}

	public void Produce(QueuedRecipe recipe, float agentModifier = 1f)
	{
		float num = TimeManager.GetDeltaTime() * agentModifier * base.Buildable.ReturnModifier(ModifierType.ProductionSpeed);
		float addedProgress = ((!HasEnergyCost) ? num : (Connector.EnergyGrid.GridEfficiency * num));
		recipe.Produce(addedProgress);
		if (_properties.Type == Type.Farm)
		{
			_farmSlots.Update(QueuedRecipes.IndexOf(recipe), recipe.Progress);
		}
	}

	public void StartProducing(QueuedRecipe recipe, float modifier = 1f)
	{
		if (recipe == null)
		{
			UnityEngine.Debug.LogError($"PRODUCER::Recipe was null in StartProducing in {base.Buildable.name}");
		}
		if (base.Buildable.FMODEventEmitter == null)
		{
			UnityEngine.Debug.LogError($"PRODUCER::FMODEventEmitter was null in StartProducing in {base.Buildable.name}");
		}
		if (_properties.FMODEventReference_Production.IsNull)
		{
			UnityEngine.Debug.LogError($"PRODUCER::FMODEvent_Production was null in StartProducing in {base.Buildable.name}");
		}
		if (recipe.RecipeStage == QueuedRecipe.Stage.WaitingToProduce || recipe.RecipeStage == QueuedRecipe.Stage.Producing)
		{
			base.Buildable.FMODEventEmitter.Emit(_properties.FMODEventReference_Production);
			StartProductionAnimation(recipe, modifier);
			recipe.RecipeStage = QueuedRecipe.Stage.Producing;
			if (_properties.Type == Type.Farm)
			{
				_farmSlots.Display(QueuedRecipes.IndexOf(recipe), recipe);
			}
		}
		OnStartProducing.Invoke(base.Buildable);
	}

	private void StartProductionAnimation(QueuedRecipe recipe, float modifier)
	{
		if (!(base.Buildable.BuildableAnimator == null))
		{
			base.Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 1);
			if (base.Buildable.BuildableAnimator.HasParameter("Transition Time"))
			{
				base.Buildable.BuildableAnimator.Animator.SetFloat("Transition Time", recipe.ProductionTime / modifier);
			}
		}
	}

	public void StopProducing()
	{
		if (base.Buildable.FMODEventEmitter != null)
		{
			base.Buildable.FMODEventEmitter.Stop(_properties.FMODEventReference_Production);
		}
		if (base.Buildable.BuildableAnimator != null)
		{
			base.Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 0);
		}
		OnStopProducing.Invoke(base.Buildable);
		if (ProductionRecipe != null && ProductionRecipe.Progress < ProductionRecipe.ProductionTime && ProductionRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
		{
			ProductionRecipe.RecipeStage = QueuedRecipe.Stage.WaitingToProduce;
		}
	}

	private void UpdateProducerVisuals(QueuedRecipe queuedRecipe)
	{
		if (queuedRecipe != null && queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
		{
			for (int i = 0; i < _producerVisualHelpers.Length; i++)
			{
				_producerVisualHelpers[i].SetProgress(ReturnProgressNormalized(queuedRecipe));
			}
		}
		else
		{
			for (int j = 0; j < _producerVisualHelpers.Length; j++)
			{
				_producerVisualHelpers[j].Reset();
			}
		}
	}

	public bool IsProducerOf(ProductionRecipeProperties recipeProperties)
	{
		foreach (Recipe recipe in Recipes)
		{
			if (recipe.Properties == recipeProperties)
			{
				return true;
			}
		}
		return false;
	}

	public float ReturnEnergyCost()
	{
		return _properties.EnergyCost * base.Buildable.ReturnModifier(ModifierType.ProductionEnergyCost);
	}

	public bool TryReturnRecipe(int index, out Recipe recipe)
	{
		return Recipes.TryGetValue(index, out recipe);
	}

	public bool TryReturnRecipe(ProductionRecipeProperties properties, out Recipe recipe)
	{
		int count = Recipes.Count;
		while (0 < count--)
		{
			recipe = Recipes[count];
			if (recipe.Properties == properties)
			{
				return true;
			}
		}
		recipe = null;
		return false;
	}

	public bool TryReturnRestoredProducingRecipe(out QueuedRecipe queuedRecipe)
	{
		if (_wasRestored)
		{
			_wasRestored = false;
			for (int i = 0; i < QueuedRecipes.Count; i++)
			{
				queuedRecipe = QueuedRecipes[i];
				if (queuedRecipe != null && queuedRecipe.Recipe != null && queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
				{
					return true;
				}
			}
		}
		queuedRecipe = null;
		return false;
	}

	public bool TryReturnNextRecipeToProduce(out QueuedRecipe queuedRecipe)
	{
		if (base.Buildable.Inventory.ReturnIsFull(SubInventoryType.Export))
		{
			queuedRecipe = null;
			return false;
		}
		for (int i = 0; i < QueuedRecipes.Count; i++)
		{
			queuedRecipe = QueuedRecipes[i];
			if (queuedRecipe != null && queuedRecipe.Recipe != null && (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToProduce || queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing) && base.Buildable.Inventory.FitsInInventory(queuedRecipe.ProducedItems, SubInventoryType.Export))
			{
				return true;
			}
		}
		queuedRecipe = null;
		return false;
	}

	public float ReturnProgressNormalized(QueuedRecipe queuedRecipe = null)
	{
		if (queuedRecipe == null)
		{
			if (ProductionRecipe == null)
			{
				return 0f;
			}
			queuedRecipe = ProductionRecipe;
		}
		return queuedRecipe.Progress / queuedRecipe.ProductionTime;
	}

	public bool ReturnProducesItem(ItemProperties itemProperties)
	{
		if (_properties == null || _properties.Recipes.IsNullOrEmpty())
		{
			return false;
		}
		foreach (ProductionRecipeProperties recipe in _properties.Recipes)
		{
			if (recipe.ReturnProducesItem(itemProperties))
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnUsesItem(ItemProperties itemProperties)
	{
		if (_properties == null || _properties.Recipes.IsNullOrEmpty())
		{
			return false;
		}
		foreach (ProductionRecipeProperties recipe in _properties.Recipes)
		{
			if (recipe.ReturnUsesItem(itemProperties))
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnCanRun()
	{
		if (IsEnabled() && GameManager.TimeManager.CurrentDay.DayTime == Day.E_DayTime.Day)
		{
			if (HasEnergyCost)
			{
				return Connector.EnergyGrid.HasEnergy;
			}
			return true;
		}
		return false;
	}

	private IInventorySpaceLimiter ReturnInventorySpaceLimiter()
	{
		if (_properties.Type != Type.Workshop)
		{
			return GameManager.ResourceManager;
		}
		return base.Buildable.Community.Inventory;
	}

	private float ReturnCurrentEnergyConsumption()
	{
		if (IsProducing())
		{
			return ReturnEnergyCost();
		}
		return 0f;
	}

	private float ReturnCurrentEnergyRequirement()
	{
		if (IsProducing())
		{
			return ReturnEnergyCost();
		}
		if (_properties.Type == Type.Workshop && ProductionRecipe != null && ProductionRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToProduce)
		{
			return ReturnEnergyCost();
		}
		return 0f;
	}

	private bool IsProducing()
	{
		switch (_properties.Type)
		{
		case Type.Workshop:
			if (ProductionRecipe == null)
			{
				return false;
			}
			if (ProductionRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
			{
				return true;
			}
			break;
		case Type.Farm:
			foreach (QueuedRecipe queuedRecipe in QueuedRecipes)
			{
				if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
				{
					return true;
				}
			}
			break;
		}
		return false;
	}

	private bool ReturnIsRecipeItem(Item item)
	{
		foreach (QueuedRecipe queuedRecipe in QueuedRecipes)
		{
			if (!queuedRecipe.RecipeItems.IsNullOrEmpty() && queuedRecipe.RecipeItems.Contains(item))
			{
				return true;
			}
		}
		return false;
	}

	public bool TryReturnBlockingProject(out Project blockingProject, Agent agent)
	{
		blockingProject = null;
		if (base.Buildable == null || base.Buildable.Community == null)
		{
			UnityEngine.Debug.LogException(new Exception("Unable to return blocking project. The producer has been Destroyed! Uninitialzing its projects."));
			UninitializeProjects();
			return false;
		}
		foreach (IItemProducer producer2 in base.Buildable.Community.Producers)
		{
			if (producer2 is Producer { ProductionProject: not null } producer && ProductionProject.AgentPriorityScore <= producer.ProductionProject.AgentPriorityScore && 0 < producer.QueuedRecipes.Count && producer.QueuedRecipes[0].RecipeStage == QueuedRecipe.Stage.WaitingToProduce && producer.ProductionProject.Assignments.IsNullOrEmpty())
			{
				return false;
			}
		}
		if (0 < QueuedRecipes.Count && QueuedRecipes[0].RecipeStage == QueuedRecipe.Stage.WaitingToImport && ImportProject.Assignments.IsNullOrEmpty())
		{
			blockingProject = ImportProject;
		}
		return blockingProject != null;
	}

	public override bool IsEnabled()
	{
		if (base.IsEnabled())
		{
			return base.Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public override bool CanBeSalvaged()
	{
		if (base.Buildable.Inventory.ReturnCount(SubInventoryType.Export, includeReserved: true) > 0)
		{
			return false;
		}
		if (base.Buildable.Inventory.ReturnCount(SubInventoryType.Import, includeReserved: true) > 0)
		{
			return false;
		}
		switch (_properties.Type)
		{
		case Type.Workshop:
			if (ProductionRecipe != null)
			{
				return ProductionRecipe.IsSalvagable();
			}
			return true;
		case Type.Farm:
		{
			for (int i = 0; i < QueuedRecipes.Count; i++)
			{
				if (!QueuedRecipes[i].IsSalvagable())
				{
					return false;
				}
			}
			return true;
		}
		default:
			return true;
		}
	}

	public override void Shutdown()
	{
		int count = QueuedRecipes.Count;
		while (0 < count--)
		{
			CancelRecipe(count);
		}
		Deactivate();
	}

	public override void Activate()
	{
		base.Activate();
		_queuedUpdated = true;
	}

	public override void Deactivate()
	{
		base.Deactivate();
		base.Buildable.RemoveAllMalfunctions();
		_queuedUpdated = true;
	}

	public override void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public override void PopulateMalfunctions(List<PlaceableAlertProperties> malfunctions, PlaceableAlertProperties.AlertType minimumAlertType = PlaceableAlertProperties.AlertType.Minor)
	{
		base.PopulateMalfunctions(malfunctions, minimumAlertType);
		foreach (Recipe recipe in Recipes)
		{
			if (minimumAlertType == PlaceableAlertProperties.AlertType.Major || SelectedRecipe == recipe)
			{
				recipe.PopulateMalfunctions(malfunctions, minimumAlertType);
			}
		}
	}

	public override IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new ProducerPersistentData(this);
	}

	public override void Restore(IBuildableExtendablePersistentData persistentData)
	{
		if (!(persistentData is ProducerPersistentData producerPersistentData))
		{
			return;
		}
		if (base.Buildable.BuildPhase == BuildPhase.SalvageShutdown || base.Buildable.BuildPhase == BuildPhase.UpgradeShutdown)
		{
			ExportResourceProvider.Register();
		}
		SetSelectedRecipe(producerPersistentData.SelectedRecipeIndex);
		if (producerPersistentData.Recipes == null)
		{
			RestoreContinuousRecipe(producerPersistentData.ContinuousRecipeIndex);
		}
		else
		{
			ProducerPersistentData.Recipe[] recipes = producerPersistentData.Recipes;
			for (int i = 0; i < recipes.Length; i++)
			{
				ProducerPersistentData.Recipe persistentData2 = recipes[i];
				if (persistentData2.TryGetProperties(out var properties) && TryReturnRecipe(properties, out var recipe))
				{
					recipe.Restore(persistentData2);
				}
			}
			Sorting.SlowSort(RecipeQueue);
		}
		_wasRestored = true;
	}

	private void RestoreContinuousRecipe(int index)
	{
		if (Recipes.TryGetValue(index, out var value))
		{
			value.ToggleContinuous();
		}
	}

	public override void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
		ProducerPersistentData producerPersistentData = persistentData as ProducerPersistentData;
		if (producerPersistentData.ImportProject != null && producerPersistentData.ImportProject.TryReturn(out var instance))
		{
			ImportProject = instance;
		}
		if (producerPersistentData.ProductionProject != null && producerPersistentData.ProductionProject.TryReturn(out var instance2))
		{
			ProductionProject = instance2;
			ProductionProject.SetBlockingProjectProvider(this);
		}
		InitializeProjects();
		_projectSettings = GameManager.Settings.ProjectSettings;
		if (_projectSettings.ProducerProjectPriorities.IsValidIndex(producerPersistentData.PriorityIndex))
		{
			SetPriority(_projectSettings.ProducerProjectPriorities[producerPersistentData.PriorityIndex]);
		}
		int num = ((_properties.Type == Type.Workshop) ? producerPersistentData.QueuedRecipes.Length : MaximumQueuedRecipes);
		if (num == 0)
		{
			return;
		}
		for (int i = 0; i < num; i++)
		{
			if (!TryRestoreQueuedRecipe(i, producerPersistentData.QueuedRecipes, out var queuedRecipe))
			{
				continue;
			}
			AddQueuedRecipe(queuedRecipe);
			if (ProductionProperties.Type == Type.Farm && queuedRecipe.Recipe != null)
			{
				QueuedRecipe.Stage recipeStage = queuedRecipe.RecipeStage;
				if ((uint)(recipeStage - 2) <= 2u)
				{
					_farmSlots.Display(i, queuedRecipe);
				}
			}
		}
	}

	private bool TryRestoreQueuedRecipe(int index, QueuedRecipePersistentData[] persistentData, out QueuedRecipe queuedRecipe)
	{
		if (index < persistentData.Length && QueuedRecipe.TryGet(persistentData[index], Recipes, out queuedRecipe))
		{
			return true;
		}
		if (_properties.Type == Type.Farm)
		{
			UnityEngine.Debug.LogException(new Exception("Producer '" + base.Buildable.Name + "' did not persist its QueuedRecipes correctly"));
			queuedRecipe = QueuedRecipe.Get(SelectedRecipeIndex, Recipes);
			return true;
		}
		queuedRecipe = null;
		return false;
	}

	private void StopDuplicateProjects(Project project)
	{
		if (project == null)
		{
			return;
		}
		int count = base.Buildable.Community.Projects.Count;
		while (0 < count--)
		{
			Project project2 = base.Buildable.Community.Projects[count];
			if (project2 != project && project2.Target == project.Target && project2.Properties == project.Properties)
			{
				project2.Stop(ProjectFlags.BugFix);
				UnityEngine.Debug.LogException(new Exception($"Project '{project2.Properties}' was stopped by '{base.Buildable.Name}', because it was a duplicate!"));
			}
		}
	}

	public override void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		ProducerPersistentData producerPersistentData = persistentData as ProducerPersistentData;
		producerPersistentData.ProductionProject = ProductionProject;
		producerPersistentData.ImportProject = ImportProject;
		producerPersistentData.PriorityIndex = _projectSettings.ProducerProjectPriorities.IndexOf(Priority);
		if (ProductionRecipe != null && ProductionRecipe.RecipeStage == QueuedRecipe.Stage.Producing)
		{
			producerPersistentData.BuildableAnimatorData = BuildableAnimatorPersistentData.Create(base.Buildable);
			if (ProductionProject != null && ProductionProject.Assignments.Count > 0)
			{
				producerPersistentData.AgentAnimatorData = new MeshAnimatorPersistentData(ProductionProject.Assignments[0].Agent);
			}
		}
		else
		{
			producerPersistentData.BuildableAnimatorData = null;
			producerPersistentData.AgentAnimatorData = null;
		}
		producerPersistentData.PopulateQueuedRecipes(this);
	}

	public override void OnDeconstruct()
	{
		ExportResourceProvider.Unregister();
	}

	public List<Agent> GetWorkers(List<Agent> listToPopulate = null)
	{
		if (listToPopulate == null)
		{
			listToPopulate = new List<Agent>(_attachedWorkers.Count);
		}
		listToPopulate.AddUniqueRange(listToPopulate);
		return listToPopulate;
	}

	public void AddToEnergyGrid(EnergyGrid grid)
	{
		grid.Consumers.AddUnique(this);
		grid.AddComponent(this);
	}

	public void RemoveFromEnergyGrid(EnergyGrid grid)
	{
		if (grid != null)
		{
			grid.Consumers.Remove(this);
			grid.RemoveComponent(this);
		}
	}

	public EnergyGridOverviewSlotUI ReturnUI()
	{
		if (!ProducerOverviewUI.TryReturnAvailableUI(out var ui))
		{
			ui = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.ProducerOverviewUIPrefab);
		}
		ui.Initialize(this);
		return ui;
	}

	int IItemProducer.GetItemsInProductionCount(ItemProperties itemProperties)
	{
		int num = 0;
		foreach (QueuedRecipe queuedRecipe in QueuedRecipes)
		{
			if (queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToReserveItems || queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToExportItems)
			{
				continue;
			}
			foreach (CountedItemProperty producedItem in queuedRecipe.ProducedItems)
			{
				if (producedItem.ItemProperties == itemProperties)
				{
					num += producedItem.Amount;
				}
			}
		}
		return num;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Buildable/Production Properties")]
public class ProductionProperties : ScriptableObject
{
	[Header("General")]
	[Tooltip("Type of this producer.")]
	public Producer.Type Type;

	[ConditionalEnumHide("Type", 0, false, HideInInspector = true)]
	[Tooltip("Project for this production.")]
	public ProjectProperties ProductionProject;

	[ConditionalEnumHide("Type", 0, false, HideInInspector = true)]
	[Tooltip("Project for this production.")]
	public int ExportCapacity = 10;

	[Tooltip("Amount of slots the producer has.")]
	[ConditionalEnumHide("Type", 1, false, HideInInspector = true)]
	public int SlotAmount = 6;

	[Header("Recipes")]
	[Tooltip("Automatically queue up the first recipe from the list below.")]
	public bool AutomaticallyStart;

	[Tooltip("Available recipes for this production.")]
	public List<ProductionRecipeProperties> Recipes = new List<ProductionRecipeProperties>();

	[Tooltip("Cost of the recipe per second.")]
	public float EnergyCost;

	[Header("FMOD")]
	public EventReference FMODEventReference_Production;

	public EventReference FMODEventReference_FarmItemCompleted;

	[NonSerialized]
	private List<ItemProperties> _allRecipeIngredients;

	public bool IsItemRecipeIngredient(Item item)
	{
		if (_allRecipeIngredients == null)
		{
			_allRecipeIngredients = ReturnAllRecipeIngredients();
		}
		return _allRecipeIngredients.Contains(item.Properties);
	}

	private List<ItemProperties> ReturnAllRecipeIngredients()
	{
		List<ItemProperties> list = new List<ItemProperties>();
		foreach (ProductionRecipeProperties recipe in Recipes)
		{
			foreach (CountedItemProperty requiredItem in recipe.RequiredItems)
			{
				list.AddUnique(requiredItem.ItemProperties);
			}
		}
		return list;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Buildable/Production Recipe Properties")]
public class ProductionRecipeProperties : Unlockable, ILocalizationParamsManager
{
	[Header("Description")]
	[SerializeField]
	private LocalizedString _localizedName = "";

	[SerializeField]
	private LocalizedString _localizedDescription = "";

	[SerializeField]
	private Sprite _producedItemIconOverride;

	[Header("Input")]
	[SerializeField]
	private List<CountedItemProperty> _requiredItems = new List<CountedItemProperty>();

	[Header("Production Process")]
	[SerializeField]
	private DrifterAttributes.AttributeType _attribute = DrifterAttributes.AttributeType.Recycling;

	[SerializeField]
	private float _productionTime = 10f;

	[SerializeField]
	private float _pollution;

	[SerializeField]
	private bool _requiresPerson = true;

	[Header("Output")]
	[SerializeField]
	private List<CountedItemProperty> _producedItems = new List<CountedItemProperty>();

	[SerializeField]
	private float _productionExperience;

	[SerializeField]
	private QueuedRecipe.Stage _resetToStage;

	[Header("Animation")]
	[SerializeField]
	private Activity _activity = Activity.Working;

	[SerializeField]
	private List<RecipeVisual> _recipeVisualPrefabs;

	[Header("Scenario")]
	[SerializeField]
	private bool _requiresUnlock;

	[SerializeReference]
	[InstantiateSerializeReference]
	[Tooltip("If the recipe has unlock conditions it will not be unlocked in the Unlockable Manaer")]
	private IScenarioTriggerableCondition[] _unlockConditions;

	public LocalizedString LocalizedName => _localizedName;

	public LocalizedString LocalizedDescription => _localizedDescription;

	public IReadOnlyList<CountedItemProperty> RequiredItems => _requiredItems;

	public DrifterAttributes.AttributeType Attribute => _attribute;

	public float ProductionTime => _productionTime;

	public float Pollution => _pollution;

	public bool RequiresPerson => _requiresPerson;

	public IReadOnlyList<CountedItemProperty> ProducedItems => _producedItems;

	public float ProductionExperience => _productionExperience;

	public QueuedRecipe.Stage ResetToStage => _resetToStage;

	public Activity Activity => _activity;

	public IReadOnlyList<RecipeVisual> RecipeVisualPrefabs => _recipeVisualPrefabs;

	public override Types Type => Types.ProductionRecipe;

	public override bool IsUnlocked()
	{
		if (_requiresUnlock)
		{
			if (base.IsUnlocked())
			{
				return true;
			}
			if (((IReadOnlyCollection<IScenarioTriggerableCondition>)(object)_unlockConditions).IsNullOrEmpty())
			{
				return false;
			}
			IScenarioTriggerableCondition[] unlockConditions = _unlockConditions;
			for (int i = 0; i < unlockConditions.Length; i++)
			{
				if (!unlockConditions[i].IsMet())
				{
					return false;
				}
			}
			Unlock();
		}
		return true;
	}

	public override void Unlock()
	{
		base.Unlock();
		List<Buildable> buildables = Community.PlayerCommunity.Buildables;
		GameObject objectOfInterest = null;
		foreach (Buildable item in (IEnumerable<Buildable>)buildables)
		{
			if (item.TryReturnBuildableExtendable<Producer>(out var buildableExtendable) && buildableExtendable.IsProducerOf(this))
			{
				objectOfInterest = item.gameObject;
				break;
			}
		}
		GameManager.UIManager.NotificationHandler.AddNotification(GameSettings.Instance.UISettings.UnlockableRecipeNotification, new UnlockableRecipeNotification(objectOfInterest, this));
	}

	public Sprite ReturnIcon(ItemProperties itemProperties)
	{
		if ((bool)_producedItemIconOverride && itemProperties == ReturnFirstProducedItemProperties())
		{
			return _producedItemIconOverride;
		}
		return itemProperties.InventorySprite;
	}

	public List<Item> ReturnProducedItems()
	{
		List<Item> list = new List<Item>();
		for (int i = 0; i < ProducedItems.Count; i++)
		{
			for (int j = 0; j < ProducedItems[i].Amount; j++)
			{
				list.Add(new Item(ProducedItems[i].ItemProperties));
			}
		}
		return list;
	}

	public ItemProperties ReturnFirstProducedItemProperties()
	{
		if (ProducedItems.Count == 0)
		{
			return null;
		}
		return ProducedItems[0].ItemProperties;
	}

	public ItemProperties ReturnFirstRequiredItemProperties()
	{
		return RequiredItems[0].ItemProperties;
	}

	public bool ReturnProducesItem(ItemProperties itemProperties)
	{
		if (ProducedItems.IsNullOrEmpty())
		{
			return false;
		}
		foreach (CountedItemProperty producedItem in ProducedItems)
		{
			if (producedItem.ItemProperties == itemProperties && 0 < producedItem.Amount)
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnUsesItem(ItemProperties itemProperties)
	{
		if (RequiredItems.IsNullOrEmpty())
		{
			return false;
		}
		foreach (CountedItemProperty requiredItem in RequiredItems)
		{
			if (requiredItem.ItemProperties == itemProperties && 0 < requiredItem.Amount)
			{
				return true;
			}
		}
		return false;
	}

	public int ReturnProducedItemCount()
	{
		int num = 0;
		if (ProducedItems.IsNullOrEmpty())
		{
			return num;
		}
		foreach (CountedItemProperty producedItem in ProducedItems)
		{
			num += producedItem.Amount;
		}
		return num;
	}

	public GameEventType ReturnFinishedGameEventType()
	{
		if (Attribute == DrifterAttributes.AttributeType.Farming)
		{
			return GameEventType.ItemFarmed;
		}
		return GameEventType.ProducerItemProduced;
	}

	string ILocalizationParamsManager.GetParameterValue(string param)
	{
		if (!(param == "DURATIONMINUTES"))
		{
			if (param == "DURATIONSECONDS")
			{
				return (Mathf.FloorToInt(_productionTime) % 60).ToString();
			}
			return null;
		}
		return (Mathf.FloorToInt(_productionTime) / 60).ToString();
	}
}
public class QueuedRecipe
{
	public enum Stage
	{
		WaitingToReserveItems,
		WaitingToImport,
		WaitingToProduce,
		Producing,
		WaitingToExportItems
	}

	private static Stack<QueuedRecipe> _pool = new Stack<QueuedRecipe>(64);

	public Producer.Recipe Recipe { get; private set; }

	public List<Item> RecipeItems { get; set; }

	public float Progress { get; set; }

	public float NormalizedProgress
	{
		get
		{
			if (ProductionTime != 0f)
			{
				return Mathf.Clamp01(Progress / ProductionTime);
			}
			return 0f;
		}
	}

	public Stage RecipeStage { get; set; }

	public IReadOnlyList<CountedItemProperty> ProducedItems { get; private set; }

	public float ProductionTime { get; private set; }

	public float Pollution { get; private set; }

	public bool RequiresPerson { get; private set; }

	public Activity Activity { get; private set; }

	public DrifterAttributes.AttributeType Attribute { get; private set; }

	private QueuedRecipe()
	{
	}

	public static QueuedRecipe Get(Producer.Recipe recipe)
	{
		QueuedRecipe queuedRecipe = Get();
		queuedRecipe.Initialize(recipe);
		return queuedRecipe;
	}

	public static QueuedRecipe Get(int index, List<Producer.Recipe> recipes)
	{
		if (recipes.TryGetValue(index, out var value))
		{
			return Get(value);
		}
		throw new IndexOutOfRangeException();
	}

	public static bool TryGet(QueuedRecipePersistentData data, List<Producer.Recipe> recipes, out QueuedRecipe instance)
	{
		if (data.RecipeIndex < 0 || recipes.Count <= data.RecipeIndex)
		{
			instance = null;
			return false;
		}
		instance = Get();
		instance.Initialize(recipes[data.RecipeIndex]);
		instance.RecipeItems = data.ReturnItems();
		instance.RecipeStage = data.RecipeStage;
		instance.Progress = data.Progress;
		return true;
	}

	public static QueuedRecipe Get()
	{
		_ = _pool.Count;
		if (_pool.TryPop(out var result))
		{
			result.Reset();
			return result;
		}
		return new QueuedRecipe();
	}

	public void Release()
	{
		Reset();
		if (_pool.Contains(this))
		{
			UnityEngine.Debug.LogError("You are trying to release a QueuedRecipe that is already in the QueuedRecipe Pool!");
		}
		else
		{
			_pool.Push(this);
		}
	}

	public void Initialize(Producer.Recipe recipe)
	{
		Recipe = recipe;
		ProducedItems = recipe.Properties.ProducedItems;
		ProductionTime = recipe.Properties.ProductionTime;
		Pollution = recipe.Properties.Pollution;
		RequiresPerson = recipe.Properties.RequiresPerson;
		Activity = recipe.Properties.Activity;
		Attribute = recipe.Properties.Attribute;
	}

	public void Produce(float addedProgress)
	{
		Progress += addedProgress;
	}

	public void Finish()
	{
		if (!RecipeItems.IsNullOrEmpty())
		{
			foreach (Item recipeItem in RecipeItems)
			{
				if (recipeItem.TakeFromInventory())
				{
					ItemEvent.Dispatch(GameEventType.ProducerItemConsumed, recipeItem);
				}
			}
		}
		RecipeItems = Recipe.Properties.ReturnProducedItems();
		foreach (Item recipeItem2 in RecipeItems)
		{
			ItemEvent.Dispatch(Recipe.Properties.ReturnFinishedGameEventType(), recipeItem2);
		}
		RecipeStage = Stage.WaitingToExportItems;
	}

	public void Reset(int recipeIndex, List<Producer.Recipe> recipes, bool resetRecipeState = false)
	{
		Reset();
		Initialize(recipes[recipeIndex]);
		if (resetRecipeState)
		{
			RecipeStage = Recipe.Properties.ResetToStage;
		}
	}

	public void Reset()
	{
		Recipe = null;
		ProducedItems = null;
		ProductionTime = 0f;
		Pollution = 0f;
		RequiresPerson = false;
		Activity = Activity.None;
		Attribute = DrifterAttributes.AttributeType.None;
		RecipeStage = Stage.WaitingToReserveItems;
		Progress = 0f;
		RecipeItems?.Clear();
	}

	public bool AreItemsInInventory(Inventory inventory, SubInventoryType subInventory)
	{
		if (RecipeStage == Stage.WaitingToReserveItems)
		{
			return false;
		}
		foreach (Item recipeItem in RecipeItems)
		{
			if (recipeItem.Inventory != inventory || recipeItem.SubInventory != subInventory)
			{
				return false;
			}
		}
		return true;
	}

	public bool IsSalvagable()
	{
		Stage recipeStage = RecipeStage;
		if (recipeStage == Stage.WaitingToImport || (uint)(recipeStage - 3) <= 1u)
		{
			return false;
		}
		return true;
	}

	public int ReturnProducedItemCount()
	{
		int num = 0;
		if (Recipe != null)
		{
			int count = Recipe.ProducedItems.Count;
			while (0 < count--)
			{
				num += Recipe.ProducedItems[count].Amount;
			}
		}
		return num;
	}

	public ItemProperties ReturnFirstRequiredItemProperties()
	{
		if (Recipe == null || !(Recipe.Properties != null))
		{
			return null;
		}
		return Recipe.Properties.ReturnFirstRequiredItemProperties();
	}

	public ItemProperties ReturnFirstProducedItemProperties()
	{
		if (Recipe == null || !(Recipe.Properties != null))
		{
			return null;
		}
		return Recipe.Properties.ReturnFirstProducedItemProperties();
	}
}
[RequireComponent(typeof(Construction))]
public class Rejuvenator : MonoBehaviour, IBuildableExtendable, IPersistentReference
{
	public enum Stage
	{
		Idle,
		Rejuvenating,
		WaitingToStart
	}

	[SerializeField]
	private RejuvenatorProperties _properties;

	[SerializeField]
	[FormerlySerializedAs("Slots")]
	private AttachableSlots _slots;

	public Stage CurrentStage { get; private set; }

	public RejuvenatorProperties Properties => _properties;

	public Buildable Buildable { get; private set; }

	public bool Active { get; private set; }

	public bool Reserved { get; set; }

	public int PersistentIndex { get; set; } = -1;

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		Buildable.Community.AddRejuvenator(this);
	}

	public void Finish(bool restored = false)
	{
	}

	public void Remove()
	{
		Buildable.Community.RemoveRejuvenator(this);
	}

	public void AddAgent(Agent agent)
	{
		_slots.Attach(agent.transform);
	}

	public void RemoveAgent(Agent patient, Transform newParent)
	{
		_slots.Detach(patient.transform, newParent);
	}

	public IEnumerator RejuvenateCoroutine(Agent agent)
	{
		float timer = 0f;
		while (GameManager.TimeManager.CurrentDay.DayTime == _properties.Time || timer <= _properties.MinimumTime)
		{
			timer += TimeManager.GetDeltaTime();
			yield return null;
		}
		if (!Buildable.TryReturnBuildableExtendable<ModuleManager>(out var buildableExtendable))
		{
			yield break;
		}
		RejuvenatorProperties.ModuleRejuvenator[] moduleRejuvenators = _properties.ModuleRejuvenators;
		for (int i = 0; i < moduleRejuvenators.Length; i++)
		{
			RejuvenatorProperties.ModuleRejuvenator moduleRejuvenator = moduleRejuvenators[i];
			if (buildableExtendable.IsActiveModule(moduleRejuvenator.Module))
			{
				ApplyModuleRejuvenator(agent, moduleRejuvenator);
			}
		}
	}

	public void SetCurrentStage(Stage stage)
	{
		if (stage != CurrentStage)
		{
			CurrentStage = stage;
			switch (CurrentStage)
			{
			case Stage.Idle:
				Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 0);
				break;
			case Stage.Rejuvenating:
				Buildable.BuildableAnimator.Animator.SetInteger("IsWorking", 1);
				break;
			}
		}
	}

	public bool RejuvenatesVital(VitalType vital)
	{
		return vital == _properties.Vital;
	}

	private void ApplyModuleRejuvenator(Agent agent, RejuvenatorProperties.ModuleRejuvenator moduleRejuvenator)
	{
		if (moduleRejuvenator.Vital == VitalType.Pollution)
		{
			agent.Vitals.Pollution.Decrease(moduleRejuvenator.Module.ModifierValue);
		}
		else
		{
			UnityEngine.Debug.LogException(new NotImplementedException());
		}
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public bool CanBeSalvaged()
	{
		return CurrentStage == Stage.Idle;
	}

	public void Shutdown()
	{
		Deactivate();
	}

	public void Activate()
	{
		Active = true;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new RejuvenatorPersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		return true;
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public float ReturnWeight()
	{
		return 0f;
	}
}
