	[SerializeField]
	private Item.Tags _liquidTags = Item.Tags.Drink | Item.Tags.Liquid;

	private SubInventory _liquidInventory;

	private StorageResourceProvider _resourceProviderLiquid;

	private ResourceProvider _shutdownResourceProviderLiquid;

	private ItemDataItemProvider _itemDataItemProviderLiquid;

	public override void Initialize(Buildable buildable, bool restored = false)
	{
		Initialize(buildable, SubInventoryType.Storage);
		_liquidInventory = buildable.Inventory.GetOrAddSubInventory(SubInventoryType.Liquid, _liquidCapacity);
		Construction.Townheart = buildable.ReturnExtendable<Construction>();
	}

	public override void Finish(bool restored = false)
	{
		base.Finish(restored);
		base.Buildable.Community.Inventory.AddItemProvider(_itemDataItemProviderLiquid);
		_shutdownResourceProviderLiquid?.Unregister();
		_liquidInventory.Updated += base.OnStorageInventoryUpdated;
		if (_resourceProviderLiquid == null)
		{
			_resourceProviderLiquid = new StorageResourceProvider(this, SubInventoryType.Liquid);
		}
		_resourceProviderLiquid.Register();
	}

	public override void Remove()
	{
		base.Remove();
		base.Buildable.Community.Inventory.RemoveItemProvier(_itemDataItemProviderLiquid);
		_liquidInventory.Updated -= base.OnStorageInventoryUpdated;
		_resourceProviderLiquid?.Unregister();
		_shutdownResourceProviderLiquid?.Unregister();
	}

	public override void Count(InventoryAuditor auditor, SubInventoryType subInventoryType)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			auditor.CountInventory(_liquidInventory);
		}
		else
		{
			base.Count(auditor, subInventoryType);
		}
	}

	public override void PopulateAllItems(List<Item> allItems, SubInventoryType subInventoryType)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			_liquidInventory.ReturnAllItems(allItems);
		}
		else
		{
			base.PopulateAllItems(allItems, subInventoryType);
		}
	}

	public override bool ReserveIncomingItem(Item item)
	{
		if (base.Buildable.BuildPhase == BuildPhase.Finished && IsLiquid(item))
		{
			return base.Buildable.Inventory.ReserveIncomingItem(item, SubInventoryType.Liquid);
		}
		return base.ReserveIncomingItem(item);
	}

	protected override void UnreserveStuckItems()
	{
		base.UnreserveStuckItems();
		base.Buildable.Community.UnreserveStuckItems(base.Buildable.Inventory, SubInventoryType.Liquid);
	}

	public override void Shutdown()
	{
		base.Shutdown();
		if (_shutdownResourceProviderLiquid == null)
		{
			_shutdownResourceProviderLiquid = ResourceProvider.Get(base.Buildable, SubInventoryType.Liquid, AssignmentType.Constructing);
		}
		_shutdownResourceProviderLiquid.Register();
	}

	public override bool CanBeSalvaged()
	{
		if (base.CanBeSalvaged() && _liquidInventory.ReturnItemCount(includeReserved: true) <= 0)
		{
			return _liquidInventory.IncomingItems.Count == 0;
		}
		return false;
	}

	public override bool AcceptsItem(ItemProperties itemProperties)
	{
		if (!itemProperties.ExcludeFromItemFilter)
		{
			return base.AcceptsItem(itemProperties);
		}
		return true;
	}

	public override int ReturnCount(SubInventoryType subInventoryType, bool includeReserved)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			return _liquidInventory.ReturnItemCount(includeReserved);
		}
		return base.ReturnCount(subInventoryType, includeReserved);
	}

	public override int ReturnCount(Item.Tags itemTags, bool includeReserved)
	{
		if (IsLiquid(itemTags))
		{
			return _liquidInventory.ReturnItemCount(includeReserved);
		}
		return base.ReturnCount(itemTags, includeReserved);
	}

	public override int ReturnAvailableCapacity(ItemProperties itemProperties)
	{
		if (IsLiquid(itemProperties))
		{
			return _liquidInventory.AvailableCapacity - _liquidInventory.IncomingItems.Count;
		}
		return base.ReturnAvailableCapacity(itemProperties);
	}

	public override int ReturnCapacity(SubInventoryType subInventoryType)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			return _liquidInventory.Capacity;
		}
		return base.ReturnCapacity(subInventoryType);
	}

	public override int ReturnCapacity(Item.Tags itemTags)
	{
		if (IsLiquid(itemTags))
		{
			return _liquidInventory.Capacity;
		}
		return base.ReturnCapacity(itemTags);
	}

	public override Item ReturnItem(ItemProperties itemProperties, SubInventoryType subInventoryType)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			return _liquidInventory.ReturnItemFromProperties(itemProperties);
		}
		return base.ReturnItem(itemProperties, subInventoryType);
	}

	public override int ReturnIncomingItemCount(SubInventoryType subInventoryType)
	{
		if (subInventoryType == SubInventoryType.Liquid)
		{
			return _liquidInventory.IncomingItems.Count;
		}
		return base.ReturnIncomingItemCount(subInventoryType);
	}

	public override int ReturnIncomingItemCount(Item.Tags tags)
	{
		if (IsLiquid(tags))
		{
			return _liquidInventory.IncomingItems.Count;
		}
		return base.ReturnIncomingItemCount(tags);
	}

	public override bool HasItemIncoming(Item item)
	{
		if (IsLiquid(item))
		{
			return _liquidInventory.IncomingItems.Contains(item);
		}
		return base.HasItemIncoming(item);
	}

	private bool IsLiquid(Item item)
	{
		if (item != null)
		{
			return IsLiquid(item.Properties);
		}
		return false;
	}

	private bool IsLiquid(ItemProperties itemProperties)
	{
		if (itemProperties != null)
		{
			return IsLiquid(itemProperties.Tags);
		}
		return false;
	}

	private bool IsLiquid(Item.Tags tags)
	{
		return (tags & _liquidTags) != 0;
	}
}
[RequireComponent(typeof(Construction))]
public class WalkwayPonton : SceneBehaviour, IBuildableExtendable, IPersistentReference
{
	[SerializeField]
	private DecorationSlots _energyPoleSlots;

	private EnergyGridPole _energyPole;

	private List<WalkwaySegment> _neighbouringWalkwaySegments = new List<WalkwaySegment>();

	private Construction _construction;

	private bool _canSalvage;

	public Buildable Buildable { get; private set; }

	public Construction Construction => _construction;

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public EnergyGridPole EnergyPole => _energyPole;

	public IReadOnlyList<WalkwaySegment> NeighbouringWalkwaySegments => _neighbouringWalkwaySegments;

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		_construction = Buildable.GetComponent<Construction>();
		_construction.OnNeighbourChangeEvent.AddListener(UpdateWalkwayNeighbours);
		UpdateWalkwayNeighbours();
		if (_energyPoleSlots != null)
		{
			if (_energyPole == null)
			{
				DecorationSlots energyPoleSlots = _energyPoleSlots;
				energyPoleSlots.OnDecorationAdded = (Action<Decoration>)Delegate.Combine(energyPoleSlots.OnDecorationAdded, new Action<Decoration>(AttachEnergyPole));
			}
			else
			{
				DecorationSlots energyPoleSlots2 = _energyPoleSlots;
				energyPoleSlots2.OnDecorationRemoved = (Action<Decoration>)Delegate.Combine(energyPoleSlots2.OnDecorationRemoved, new Action<Decoration>(DetachEnergyPole));
			}
		}
		Buildable.Community.AddWalkwayPonton(this);
		Construction.OnNeighboursChangedEvent.AddListener(UpdateCanSalvage);
	}

	public void Remove()
	{
		Buildable.Community.RemoveWalkwayPonton(this);
		RemoveListeners();
	}

	private void OnDestroy()
	{
		RemoveListeners();
	}

	public void Activate()
	{
		Active = true;
	}

	public void Deactivate()
	{
		Active = false;
	}

	public bool CanBeSalvaged()
	{
		if (_canSalvage)
		{
			if (!(_energyPoleSlots == null))
			{
				return _energyPoleSlots.CanBeSalvaged();
			}
			return true;
		}
		return false;
	}

	public bool CanBeUpgraded()
	{
		return true;
	}

	public void Shutdown()
	{
		Deactivate();
	}

	public void ShutdownImmediately()
	{
		throw new NotImplementedException();
	}

	public bool IsEnabled()
	{
		if (Active)
		{
			return Buildable.BuildPhase == BuildPhase.Finished;
		}
		return false;
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new PontonPersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
		PontonPersistentData pontonPersistentData = persistentData as PontonPersistentData;
		if (pontonPersistentData.EnergyGridPole != null && pontonPersistentData.EnergyGridPole.TryReturn(out var instance))
		{
			AttachEnergyPole(instance);
			AttachTransform(instance.transform);
		}
		if (Buildable.BuildPhase != BuildPhase.HaulFrom && Buildable.BuildPhase != BuildPhase.Finished)
		{
			Buildable.BuildBuildable();
		}
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		PontonPersistentData pontonPersistentData = persistentData as PontonPersistentData;
		if (_energyPole != null && _energyPole.Buildable != null)
		{
			pontonPersistentData.EnergyGridPole = _energyPole;
		}
	}

	public void OnDeconstruct()
	{
	}

	public bool CanBeDeconstructed()
	{
		return CanBeSalvaged();
	}

	public void Upgrade(Buildable buildable)
	{
	}

	public void ShowResearchInfo(RectTransform parent)
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public float ReturnWeight()
	{
		return 0f;
	}

	public void AttachEnergyPole(EnergyGridPole pole)
	{
		_energyPole = pole;
		Buildable.OnBuildableUpgradedEvent.AddListener(MoveEnergyPole);
		if (pole.Decoration != null)
		{
			if (_energyPoleSlots != null)
			{
				DecorationSlots energyPoleSlots = _energyPoleSlots;
				energyPoleSlots.OnDecorationAdded = (Action<Decoration>)Delegate.Remove(energyPoleSlots.OnDecorationAdded, new Action<Decoration>(AttachEnergyPole));
				DecorationSlots energyPoleSlots2 = _energyPoleSlots;
				energyPoleSlots2.OnDecorationRemoved = (Action<Decoration>)Delegate.Combine(energyPoleSlots2.OnDecorationRemoved, new Action<Decoration>(DetachEnergyPole));
			}
			return;
		}
		if (pole.Buildable.TryReturnBuildableExtendable<Construction>(out var buildableExtendable))
		{
			Construction.AddNeighbourConstruction(buildableExtendable);
		}
		pole.Buildable.OnBuildableRemovedEvent.AddListener(DetachEnergyPole);
		if (_energyPoleSlots != null)
		{
			_energyPoleSlots.SetPlacementAllowed(allowed: false);
		}
		Construction.OnNeighboursChangedEvent.Invoke();
	}

	private void AttachEnergyPole(Decoration decoration)
	{
		if (_energyPole == null && decoration.TryGetExtendable<EnergyGridPole>(out var extendable))
		{
			AttachEnergyPole(extendable);
		}
	}

	public void MoveEnergyPole(Buildable removed, Buildable upgraded)
	{
		if (_energyPole != null && upgraded.TryReturnBuildableExtendable<WalkwayPonton>(out var buildableExtendable))
		{
			buildableExtendable.AttachEnergyPole(_energyPole);
			if (_energyPole.Buildable != null)
			{
				buildableExtendable.AttachTransform(_energyPole.Buildable.transform);
			}
		}
		DetachEnergyPole();
	}

	public void DetachEnergyPole(Buildable buildable = null)
	{
		EnergyGridPole energyPole = _energyPole;
		_energyPole = null;
		Buildable.OnBuildableUpgradedEvent.RemoveListener(MoveEnergyPole);
		if (energyPole.Decoration != null)
		{
			if (_energyPoleSlots != null)
			{
				DecorationSlots energyPoleSlots = _energyPoleSlots;
				energyPoleSlots.OnDecorationRemoved = (Action<Decoration>)Delegate.Remove(energyPoleSlots.OnDecorationRemoved, new Action<Decoration>(DetachEnergyPole));
				DecorationSlots energyPoleSlots2 = _energyPoleSlots;
				energyPoleSlots2.OnDecorationAdded = (Action<Decoration>)Delegate.Combine(energyPoleSlots2.OnDecorationAdded, new Action<Decoration>(AttachEnergyPole));
			}
			return;
		}
		if (energyPole.Buildable.TryReturnBuildableExtendable<Construction>(out var buildableExtendable))
		{
			Construction.RemoveNeighbour(buildableExtendable);
		}
		energyPole.Buildable.OnBuildableRemovedEvent.RemoveListener(DetachEnergyPole);
		if (_energyPoleSlots != null)
		{
			_energyPoleSlots.SetPlacementAllowed(allowed: true);
		}
		Construction.OnNeighboursChangedEvent.Invoke();
	}

	private void DetachEnergyPole(Decoration decoration)
	{
		if (_energyPole != null && _energyPole.Decoration == decoration)
		{
			DetachEnergyPole();
		}
	}

	public void AttachTransform(Transform transform)
	{
		transform.SetParent(Buildable.BuoyantTransform);
		transform.localPosition = Vector3.zero;
		transform.localRotation = Quaternion.identity;
	}

	public void Finish(bool restored = false)
	{
		int count = _construction.NeighbourConstructions.Count;
		if (count == 0 || count != _neighbouringWalkwaySegments.Count)
		{
			return;
		}
		foreach (WalkwaySegment neighbouringWalkwaySegment in _neighbouringWalkwaySegments)
		{
			neighbouringWalkwaySegment.Buildable.CancelDeconstruction();
		}
	}

	private void RemoveListeners()
	{
		_construction.OnNeighbourChangeEvent.RemoveListener(UpdateWalkwayNeighbours);
		for (int i = 0; i < _neighbouringWalkwaySegments.Count; i++)
		{
			_neighbouringWalkwaySegments[i].Buildable.OnBuildableRemovedEvent.RemoveListener(RemoveWalkwayNeighbour);
		}
		if (_energyPole != null)
		{
			if (_energyPole.Buildable != null)
			{
				_energyPole.Buildable.OnBuildableRemovedEvent.RemoveListener(DetachEnergyPole);
			}
			Buildable.OnBuildableUpgradedEvent.RemoveListener(MoveEnergyPole);
		}
		if (_energyPoleSlots != null)
		{
			DecorationSlots energyPoleSlots = _energyPoleSlots;
			energyPoleSlots.OnDecorationAdded = (Action<Decoration>)Delegate.Remove(energyPoleSlots.OnDecorationAdded, new Action<Decoration>(AttachEnergyPole));
			DecorationSlots energyPoleSlots2 = _energyPoleSlots;
			energyPoleSlots2.OnDecorationRemoved = (Action<Decoration>)Delegate.Remove(energyPoleSlots2.OnDecorationRemoved, new Action<Decoration>(DetachEnergyPole));
		}
		Construction.OnNeighboursChangedEvent.RemoveListener(UpdateCanSalvage);
	}

	private void UpdateWalkwayNeighbours()
	{
		_neighbouringWalkwaySegments.Clear();
		for (int i = 0; i < _construction.NeighbourConstructions.Count; i++)
		{
			AddWalkwayNeighbour(_construction.NeighbourConstructions[i].Buildable);
		}
	}

	private void AddWalkwayNeighbour(Buildable buildable)
	{
		WalkwaySegment component = buildable.GetComponent<WalkwaySegment>();
		if (!(component == null))
		{
			buildable.OnBuildableRemovedEvent.RemoveListener(RemoveWalkwayNeighbour);
			buildable.OnBuildableRemovedEvent.AddListener(RemoveWalkwayNeighbour);
			_neighbouringWalkwaySegments.AddUnique(component);
		}
	}

	private void RemoveWalkwayNeighbour(Buildable buildable)
	{
		for (int num = _neighbouringWalkwaySegments.Count - 1; num >= 0; num--)
		{
			if (!(_neighbouringWalkwaySegments[num].Buildable != buildable))
			{
				_neighbouringWalkwaySegments.RemoveAt(num);
				buildable.OnBuildableRemovedEvent.RemoveListener(RemoveWalkwayNeighbour);
			}
		}
		if (_neighbouringWalkwaySegments.Count == 0)
		{
			Buildable.Remove();
		}
	}

	public void SalvageWalkwayNeighbours()
	{
		for (int num = _neighbouringWalkwaySegments.Count - 1; num >= 0; num--)
		{
			_neighbouringWalkwaySegments[num].Buildable.Salvage();
		}
	}

	public bool RemoveAttachedWalkwaySegment()
	{
		_ = _neighbouringWalkwaySegments.Count;
		if (_neighbouringWalkwaySegments.Count == 1)
		{
			WalkwaySegment walkwaySegment = _neighbouringWalkwaySegments[0];
			walkwaySegment.Buildable.Deactivate();
			walkwaySegment.Buildable.Remove();
			_neighbouringWalkwaySegments.Clear();
			return true;
		}
		if (NeighbouringWalkwaySegments.Count > 1)
		{
			UnityEngine.Debug.LogException(new NotSupportedException("Only pontons with a 1 or no walkway segment attached should invoke RemoveAttachedWalkwaySegment."));
		}
		return false;
	}

	public void UpdateCanSalvage()
	{
		_canSalvage = ReturnCanSalvage();
	}

	private bool ReturnCanSalvage()
	{
		if (_energyPole != null || (_energyPoleSlots != null && !_energyPoleSlots.CanBeSalvaged()))
		{
			return false;
		}
		int count = _construction.NeighbourConstructions.Count;
		if (count == 0)
		{
			return true;
		}
		if (count != _neighbouringWalkwaySegments.Count)
		{
			return false;
		}
		foreach (WalkwaySegment neighbouringWalkwaySegment in _neighbouringWalkwaySegments)
		{
			if (neighbouringWalkwaySegment.ReturnNeighboursBlockSalvaging())
			{
				return false;
			}
			if (!neighbouringWalkwaySegment.Construction.IsConnectedToTownheart(_construction))
			{
				return false;
			}
		}
		return true;
	}

	public void ReturnBlockingNeighbours(ref ListPool<VisualPrefab>.List blockingConstructions)
	{
		if (Construction == null)
		{
			return;
		}
		foreach (Construction neighbourConstruction in Construction.NeighbourConstructions)
		{
			blockingConstructions.Add(neighbourConstruction.Buildable.SpawnedVisual);
		}
		if (_energyPole != null && _energyPole.Decoration != null)
		{
			blockingConstructions.Add(_energyPole.Decoration.SpawnedVisual);
		}
	}

	public bool NeighbouringWalkwaysFinished()
	{
		foreach (WalkwaySegment neighbouringWalkwaySegment in _neighbouringWalkwaySegments)
		{
			if (neighbouringWalkwaySegment.Buildable.BuildPhase != BuildPhase.Finished)
			{
				return false;
			}
		}
		return true;
	}
}
public class WalkwayScalable : MonoBehaviour
{
	private Vector3 _scale;

	private void Awake()
	{
		_scale = base.transform.localScale;
	}

	public void SetScale(Vector3 scale)
	{
		base.transform.localScale = new Vector3(scale.x * _scale.x, scale.y * _scale.y, scale.z * scale.z);
	}

	public void SetXScale(float scale)
	{
		base.transform.localScale = new Vector3(scale * _scale.x, _scale.y, _scale.z);
	}

	public void SetYScale(float scale)
	{
		base.transform.localScale = new Vector3(_scale.x, scale * _scale.y, _scale.z);
	}

	public void SetZScale(float scale)
	{
		base.transform.localScale = new Vector3(_scale.x, _scale.y, scale * _scale.z);
	}

	public static void SetZScale(IReadOnlyList<WalkwayScalable> scalables, float scale)
	{
		foreach (WalkwayScalable scalable in scalables)
		{
			scalable.SetZScale(scale);
		}
	}
}
public class WalkwaySegment : SceneBehaviour, IBuildableExtendable, IPersistentReference
{
	[Header("Properties")]
	public int Length;

	public int Width = 1;

	public Construction Construction;

	public float HierarchicalMarkerSpread = 1.5f;

	public Transform OutlineParent;

	public Obstacle Obstacle;

	[SerializeField]
	private BoxCollider _collider;

	private float _scaledLength;

	private Hookable _startHookable;

	private Hookable _endHookable;

	private WalkwayScalable[] _scalables;

	private Transform _startTransform;

	private Transform _endTransform;

	private bool _canBeSalvaged;

	public Buildable Buildable { get; private set; }

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public Vector3 StartPosition { get; private set; }

	public Vector3 EndPosition { get; private set; }

	public HierarchicalNodeMarker[] _futureHierarchicalNodeMarkers { get; private set; }

	public void InitializeSegment(Vector3 startLocation, Vector3 endLocation, Hookable startHookable, Hookable endHookable, float scaledLength)
	{
		InstantiateHooks(startLocation, endLocation, startHookable, endHookable, scaledLength);
		startHookable.Buildable.OnBuildableUpgradedEvent.AddListener(OnNeighbourConstructionUpgrade);
		Buildable.OnBuildableUpgradedEvent.AddListener(OnNeighbourConstructionUpgrade);
		endHookable.Buildable.OnBuildableUpgradedEvent.AddListener(OnNeighbourConstructionUpgrade);
		if (Construction != null && Obstacle != null)
		{
			InstantiateFutureHierarchicalMarkers(_scaledLength);
		}
	}

	private void InstantiateHooks(Vector3 startLocation, Vector3 endLocation, Hookable startHookable, Hookable endHookable, float scaledLength)
	{
		StartPosition = startLocation;
		EndPosition = endLocation;
		GameObject gameObject = new GameObject("LineStart");
		GameObject gameObject2 = new GameObject("LineEnd");
		gameObject.transform.position = startLocation;
		gameObject2.transform.position = endLocation;
		gameObject.transform.SetParent(startHookable.Buildable.BuoyantTransform, worldPositionStays: true);
		gameObject.transform.localPosition = gameObject.transform.localPosition.SetY(startHookable.HookHeightOffset);
		gameObject2.transform.SetParent(endHookable.Buildable.BuoyantTransform, worldPositionStays: true);
		gameObject2.transform.localPosition = gameObject2.transform.localPosition.SetY(endHookable.HookHeightOffset);
		_startTransform = gameObject.transform;
		_endTransform = gameObject2.transform;
		_scaledLength = scaledLength;
		_collider.size = FlotsamGame.SetZ(_collider.size, scaledLength);
		_startHookable = startHookable;
		_endHookable = endHookable;
	}

	public void SetStartHookable(Hookable hookable, Vector3 segmentStartPositionAdjustment = default(Vector3))
	{
		if (_startHookable != null)
		{
			_startHookable.Buildable.OnBuildableUpgradedEvent.RemoveListener(OnNeighbourConstructionUpgrade);
		}
		_startHookable = hookable;
		_startHookable.Buildable.OnBuildableUpgradedEvent.AddListener(OnNeighbourConstructionUpgrade);
		_startTransform.position += segmentStartPositionAdjustment;
		_startTransform.SetParent(hookable.Buildable.BuoyantTransform, worldPositionStays: true);
		_startTransform.localPosition = _startTransform.localPosition.SetY(hookable.HookHeightOffset);
	}

	public void SetEndHookable(Hookable hookable, Vector3 segmentEndPositionAdjustment = default(Vector3))
	{
		if (_endHookable != null)
		{
			_endHookable.Buildable.OnBuildableUpgradedEvent.RemoveListener(OnNeighbourConstructionUpgrade);
		}
		_endHookable = hookable;
		_endHookable.Buildable.OnBuildableUpgradedEvent.AddListener(OnNeighbourConstructionUpgrade);
		_endTransform.position += segmentEndPositionAdjustment;
		_endTransform.SetParent(hookable.Buildable.BuoyantTransform, worldPositionStays: true);
		_endTransform.localPosition = _endTransform.localPosition.SetY(hookable.HookHeightOffset);
	}

	private void LateUpdate()
	{
		if (_scaledLength < 1f)
		{
			Buildable.Remove();
			return;
		}
		Buildable.BuoyantTransform.position = Vector3.Lerp(_startTransform.position, _endTransform.position, 0.5f);
		Buildable.BuoyantTransform.rotation = FlotsamGame.PointsToRotation(_startTransform.position, _endTransform.position, level: false);
	}

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		buildable.Community.AddWalkwaySegment(this);
		buildable.SetStatus(GameSettings.Instance.BuildableSettings.StatusBuildingProperties);
		_scalables = GetComponentsInChildren<WalkwayScalable>(includeInactive: true);
	}

	public void Finish(bool restored = false)
	{
		if (_startHookable != null)
		{
			_startHookable.Buildable.CancelDeconstruction();
		}
		if (_endHookable != null)
		{
			_endHookable.Buildable.CancelDeconstruction();
		}
		Buildable.SetStatus(GameSettings.Instance.BuildableSettings.StatusIdleProperties);
		if (!restored && Construction != null && Obstacle != null)
		{
			AddHierarchicalMarkersToConstructionGraph();
		}
	}

	public void Remove()
	{
		Buildable.Community.RemoveWalkwaySegment(this);
		RemoveListeners();
	}

