public class Decoration : SceneBehaviour, IPersistentReference, ISelectable, IPanelContext, IOutlineRenderControllerProvider, IConstructible, IPathfindingNodeProvider
{
	private const float FLOTSAM_UNIT = 2f;

	[SerializeField]
	private Inventory _inventory;

	[SerializeField]
	private BoxCollider _collider;

	[SerializeField]
	private OutlineRendererComponent _outlineRenderer;

	[SerializeField]
	private AudioClipProperties _buildStateChangeSFX;

	public Action<Decoration> OnSalvageDone;

	private static Dictionary<DecorationProperties, Decoration> _prefabsWithProperties = new Dictionary<DecorationProperties, Decoration>();

	private bool _isPrefab;

	private readonly List<IDecorationExtendable> _decorationExtendables = new List<IDecorationExtendable>();

	private string _cachedDescription;

	public string Name
	{
		get
		{
			if (CustomName == null)
			{
				return Properties.Name;
			}
			return CustomName;
		}
		set
		{
			CustomName = (IsDefaultName(value) ? null : value);
		}
	}

	public string CustomName { get; private set; }

	public DecorationSlots Parent { get; private set; }

	public VisualPrefab SpawnedVisual { get; private set; }

	public IDecorationBehaviour Behaviour { get; private set; }

	public OutlineRendererComponent OutlineRenderer => _outlineRenderer;

	OutlineRenderController IOutlineRenderControllerProvider.OutlineController => SpawnedVisual.GetComponentInChildren<OutlineRenderController>();

	public DecorationProperties Properties { get; private set; }

	PlaceableProperties IConstructible.Properties => Properties;

	public DecorationProperties.Turns Turn { get; private set; }

	public int Visual { get; private set; }

	public int[] SlotIndices { get; private set; }

	public Inventory Inventory => _inventory;

	public ConstructionHandler ConstructionHandler { get; } = new ConstructionHandler();

	public ConstructibleStatus StatusHolder { get; } = new ConstructibleStatus();

	ObjectType ISelectable.ObjectType => ObjectType.Decoration;

	GameObject ISelectable.RelatedGameObject => base.gameObject;

	PanelID IPanelContext.PanelID => PanelID.DecorationPanel;

	public int AssignmentLimit
	{
		get
		{
			return ConstructionHandler.AssignmentLimit;
		}
		set
		{
			ConstructionHandler.AssignmentLimit = value;
		}
	}

	public Community Community
	{
		get
		{
			if (!(Parent != null) || !(Parent.Buildable != null))
			{
				return null;
			}
			return Parent.Buildable.Community;
		}
	}

	public int PersistentIndex { get; set; } = -1;

	protected override void Awake()
	{
		base.Awake();
		Behaviour = GetComponent<IDecorationBehaviour>();
		_decorationExtendables.AddRange(GetComponentsInChildren<IDecorationExtendable>());
	}

	private void Start()
	{
		UpdateBuildPhase(ConstructionHandler.BuildPhase);
		ConstructionHandler.Start();
	}

	public void Initialize(DecorationSlots parent, DecorationProperties properties, DecorationProperties.Turns turn, int visual, int[] slotIndices, bool instantFreeBuild = false)
	{
		if (instantFreeBuild || ResourceManager.AreCommunityResourcesAvailable(properties.RequiredResources))
		{
			InitializeThis(parent, properties, turn, visual, slotIndices);
			ConstructionHandler.StartBuilding(instantFreeBuild);
			DecorationEvent.DispatchPlaced(this);
		}
		else
		{
			UnityEngine.Debug.LogError("Unable to initialize Decoration \"" + base.name + "\", the required resources are not available in the inventory");
		}
	}

	public void RotateVisualPrefab()
	{
		SpawnedVisual.transform.Reset();
		SpawnedVisual.transform.rotation = Parent.transform.rotation * Properties.TurnToRotation(Turn);
	}

	public void Upgrade(DecorationSlots parent)
	{
		Parent = parent;
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			decorationExtendable.Upgrade(this);
		}
	}

	public void StartUpgrade()
	{
	}

	public void Restore(DecorationSlots parent, DecorationProperties properties, DecorationProperties.Turns turn, int visual, int[] slotIndices)
	{
		InitializeThis(parent, properties, turn, visual, slotIndices);
	}

	public void RestoreConstruction(int assignmentLimit, BuildPhase buildPhase, float progress)
	{
		ConstructionHandler.Restore(assignmentLimit, buildPhase, progress);
	}

	public void RestoreConstructionReferences(Project assignedProject)
	{
		ConstructionHandler.RestoreReferences(assignedProject);
	}

	private void InitializeThis(DecorationSlots parent, DecorationProperties properties, DecorationProperties.Turns turn, int visual, int[] slotIndices)
	{
		Parent = parent;
		Properties = properties;
		Turn = turn;
		Visual = ((properties.VisualPrefabs.Length > visual) ? visual : 0);
		SlotIndices = slotIndices;
		_inventory.GetOrAddSubInventory(SubInventoryType.Resources);
		SpawnedVisual = UnityEngine.Object.Instantiate(properties.VisualPrefabs[Visual], base.transform);
		SpawnedVisual.OverrideBuildStateChangeSFX(_buildStateChangeSFX);
		RotateVisualPrefab();
		if ((bool)SpawnedVisual.SelectionLink)
		{
			SpawnedVisual.SelectionLink.SetObjectToSelect(base.gameObject, ObjectType.Decoration, changeInitialObject: true);
			SpawnedVisual.SelectionLink.SetOnSelectedListener(OnSelected);
		}
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			decorationExtendable.Initialize(this);
		}
		if (!((IReadOnlyCollection<CountedItemProperty>)(object)Properties.RequiredResources).IsNullOrEmpty())
		{
			_inventory.Initialize(InventoryType.Decoration);
			_inventory.InitializeComposition(properties.RequiredResources);
			if (_collider != null)
			{
				_collider.size = new Vector3((float)Properties.Width * 2f, _collider.size.y, (float)properties.Depth * 2f);
				if (!properties.IsSelectable)
				{
					_collider.enabled = false;
				}
			}
		}
		if (!ConstructionHandler.IsInitialized)
		{
			StatusHolder.Initialize(GetComponentInChildren<WorldIconHandler>(includeInactive: true));
			ConstructionHandler.Initialize(this);
		}
		ConstructionHandler.SetProgress(0f);
	}

	public void AddToConstructionGraph()
	{
		if (Parent.SlotsAreOutOfBounds)
		{
			_inventory.Target.SetOverride(Parent.Buildable.Inventory.Target);
			return;
		}
		Target target = _inventory.Target;
		target.PrimaryMarker.SetParent(Parent.Buildable.Inventory.Target.PrimaryMarker);
		target.PrimaryMarker.IsOutOfBounds = Parent.SlotsAreOutOfBounds;
		target.PrimaryMarker.AddToConstructionGraph();
	}

	public void RemoveFromConstructionGraph()
	{
		if (Parent.SlotsAreOutOfBounds)
		{
			_inventory.Target.SetOverride(null);
		}
		else
		{
			_inventory.Target.PrimaryMarker.RemoveFromConstructionGraph();
		}
	}

	public void SetColliderActive(bool active)
	{
		if (_collider != null)
		{
			_collider.enabled = active;
		}
	}

	private void OnSelected(bool playSelectionSound = true)
	{
		if (playSelectionSound)
		{
			AudioManager.PlayOneShot(Properties.FMODEventReference_Select);
		}
		Parent.SetSelectedDecoration(this);
	}

	public void OnRemoveCursorEnter()
	{
		if (ConstructionHandler.CanBeDeconstructed(out var _) && !ConstructionHandler.CancelConstructionAfterHaul)
		{
			int[] slotIndices = SlotIndices;
			foreach (int num in slotIndices)
			{
				Parent.Slots[num].SetOutlineActive(value: true);
			}
		}
	}

	public void OnRemoveCursorExit()
	{
		int[] slotIndices = SlotIndices;
		foreach (int num in slotIndices)
		{
			Parent.Slots[num].SetOutlineActive(value: false);
		}
	}

	public void Remove(bool immediately = false)
	{
		if (_isPrefab)
		{
			return;
		}
		OnRemoveCursorExit();
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			decorationExtendable.OnDeconstruct();
		}
		if (immediately)
		{
			RemoveConstructible();
		}
		else
		{
			ConstructionHandler.TryToSalvage();
		}
	}

	public void RemoveConstructible()
	{
		List<Item> list = Inventory.ReturnIncomingItems(SubInventoryType.Composition);
		for (int num = list.Count - 1; num >= 0; num--)
		{
			Item item = list[num];
			if (item.Project != null)
			{
				item.Project.RemoveItem(item);
			}
			_inventory.UnreserveIncomingItem(item);
		}
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			decorationExtendable.Remove();
		}
		RemoveFromConstructionGraph();
		SetSlotOutlinesActive(active: false, Color.white);
		OnSalvageDone.SafeInvoke(this);
		if ((bool)Parent)
		{
			Parent.RemoveDecorationImmediate(this);
		}
		UnityEngine.Object.Destroy(base.gameObject);
	}

	public void FinishConstruction(bool restored = false)
	{
		if (Behaviour != null)
		{
			Behaviour.Initialize();
		}
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			decorationExtendable.Finish();
		}
		if (!restored)
		{
			DecorationEvent.DispatchConstructed(this);
		}
	}

	void IConstructible.SetProgress(float progress)
	{
		if (SpawnedVisual != null)
		{
			SpawnedVisual.SetProgress(progress);
		}
	}

	public void Select()
	{
		DecorationEvent.DispatchSelected(this);
		GameManager.UIManager.DisplayPanel(this);
	}

	public void Deselect()
	{
		GameManager.UIManager.ClosePanel(PanelID.DecorationPanel);
		OutlineRenderer.ResetHighlightOutline();
		Selector.Deselect(GetComponentsInChildren<SelectionLink>());
	}

	public string GetDescription()
	{
		if (!_cachedDescription.IsNullOrEmpty())
		{
			return _cachedDescription;
		}
		_cachedDescription = Properties.Description;
		_cachedDescription = Regex.Replace(_cachedDescription, "%NAME%", "<b>" + Properties.Name + "</b>", RegexOptions.IgnoreCase);
		IDecorationExtendable[] componentsInChildren = GetComponentsInChildren<IDecorationExtendable>();
		foreach (IDecorationExtendable decorationExtendable in componentsInChildren)
		{
			_cachedDescription = decorationExtendable.GetDescription(_cachedDescription);
		}
		return _cachedDescription;
	}

	public void AddSubInventory(SubInventoryType subInventory)
	{
		if (!(Inventory == null) && !Inventory.HasSubInventory(subInventory))
		{
			Inventory.GetOrAddSubInventory(subInventory);
		}
	}

	void IConstructible.OnBuildPhaseUpdated(BuildPhase buildPhase)
	{
		UpdateBuildPhase(buildPhase);
	}

	private void UpdateBuildPhase(BuildPhase buildPhase)
	{
		switch (buildPhase)
		{
		case BuildPhase.HaulTo:
			SetSlotOutlinesActive(active: true, Color.yellow);
			break;
		case BuildPhase.HaulFrom:
			SetSlotOutlinesActive(active: true, Color.red);
			break;
		default:
			SetSlotOutlinesActive(active: false, Color.white);
			break;
		}
	}

	private void SetSlotOutlinesActive(bool active, Color color)
	{
	}

	public bool IsInConstruction()
	{
		if (ConstructionHandler != null)
		{
			return ConstructionHandler.BuildPhase != BuildPhase.Finished;
		}
		return false;
	}

	public Decoration GetPrefabWithProperties(DecorationProperties properties)
	{
		if (_prefabsWithProperties.TryGetValue(properties, out var value))
		{
			return value;
		}
		value = UnityEngine.Object.Instantiate(properties.DecorationPrefab);
		value.name = $"{properties} (DecorationPrefab)";
		value.Properties = properties;
		value._isPrefab = true;
		value.gameObject.SetActive(value: false);
		UnityEngine.Object.DontDestroyOnLoad(value.gameObject);
		_prefabsWithProperties.Add(properties, value);
		return value;
	}

	public T GetExtendable<T>() where T : UnityEngine.Component, IDecorationExtendable
	{
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			if (decorationExtendable is T result)
			{
				return result;
			}
		}
		return null;
	}

	public bool TryGetExtendable<T>(out T extendable) where T : UnityEngine.Component, IDecorationExtendable
	{
		extendable = GetExtendable<T>();
		return extendable != null;
	}

	private bool IsDefaultName(string name)
	{
		LocalizedString nameLocalizedString = Properties.NameLocalizedString;
		if (!(name == Properties.Name))
		{
			return name == LocalizationManager.GetTranslation(nameLocalizedString.mTerm, !nameLocalizedString.mRTL_IgnoreArabicFix, nameLocalizedString.mRTL_MaxLineLength, !nameLocalizedString.mRTL_ConvertNumbers, applyParameters: true, null, "English");
		}
		return true;
	}

	bool IConstructible.CanBeDeconstructed(out LocalizedString error)
	{
		foreach (IDecorationExtendable decorationExtendable in _decorationExtendables)
		{
			if (!decorationExtendable.CanBeDeconstructed())
			{
				error = Properties.CantDeconstructTooltip;
				return false;
			}
		}
		error = GameSettings.Instance.BuildableSettings.DeconstructionTooltip;
		return true;
	}

	public virtual bool IsDraggable()
	{
		return ConstructionHandler.AssignedProject == null;
	}

	public PathfindingNode ReturnPathfindingNode(Navigator navigator = null)
	{
		if (Parent.SlotsAreOutOfBounds)
		{
			ReturnPathfindingNode(Parent.Buildable.Inventory.Target);
		}
		else if ((bool)_inventory && (bool)_inventory.Target)
		{
			ReturnPathfindingNode(_inventory.Target);
		}
		return null;
	}

	private PathfindingNode ReturnPathfindingNode(Target target)
	{
		if ((bool)target && (bool)target.PrimaryMarker && target.PrimaryMarker.Node != null)
		{
			return target.PrimaryMarker.Node;
		}
		return target.ReturnNode(Graph.Type.Constructions);
	}

	GameObject IConstructible.get_gameObject()
	{
		return base.gameObject;
	}

	Transform IPathfindingNodeProvider.get_transform()
	{
		return base.transform;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Buildable/Decorations/Decoration Properties")]
public class DecorationProperties : PlaceableProperties
{
	public class FootprintAttribute : PropertyAttribute
	{
	}

	public enum Turns
	{
		Full,
		Quarter,
		Half,
		ThreeQuarter
	}

	[Serializable]
	public struct Footprint
	{
		public bool[] Toggles;

		[NonSerialized]
		private int _width;

		[NonSerialized]
		private int _depth;

		[NonSerialized]
		private Dictionary<Turns, bool[]> _turnToggles;

		public void InitializeTurns(int width, int depth)
		{
			if (_turnToggles.IsNullOrEmpty() || _width != width || _depth != depth)
			{
				_width = width;
				_depth = depth;
				_turnToggles = new Dictionary<Turns, bool[]>
				{
					{
						Turns.Full,
						Toggles
					},
					{
						Turns.Quarter,
						ReturnQuarterTurnToggles(width, depth)
					},
					{
						Turns.Half,
						ReturnHalfTurnToggles(width, depth)
					},
					{
						Turns.ThreeQuarter,
						ReturnThreeQuarterTurnToggles(width, depth)
					}
				};
			}
		}

		public bool IsToggled(int x, int y, Turns turn)
		{
			switch (turn)
			{
			case Turns.Full:
			case Turns.Half:
				return Toggles[y * _width + x];
			case Turns.Quarter:
			case Turns.ThreeQuarter:
				return Toggles[x * _depth + y];
			default:
				UnityEngine.Debug.LogError("Not Supported!");
				return false;
			}
		}

		private bool[] ReturnQuarterTurnToggles(int width, int depth)
		{
			bool[] array = new bool[Toggles.Length];
			int num = 0;
			for (int i = 0; i < width; i++)
			{
				int num2 = depth;
				while (0 < num2--)
				{
					array[num++] = Toggles[i * depth + num2];
				}
			}
			return array;
		}

		private bool[] ReturnHalfTurnToggles(int width, int depth)
		{
			bool[] array = new bool[Toggles.Length];
			int num = 0;
			int num2 = depth;
			while (0 < num2--)
			{
				int num3 = width;
				while (0 < num3--)
				{
					array[num++] = Toggles[num2 * width + num3];
				}
			}
			return array;
		}

		private bool[] ReturnThreeQuarterTurnToggles(int width, int depth)
		{
			bool[] array = new bool[Toggles.Length];
			int num = 0;
			int num2 = width;
			while (0 < num2--)
			{
				for (int i = 0; i < depth; i++)
				{
					array[num] = Toggles[num2 * depth + i];
				}
			}
			return array;
		}
	}

	public static readonly Quaternion ROTATION_FULL = Quaternion.AngleAxis(0f, Vector3.up);

	public static readonly Quaternion ROTATION_QUARTER = Quaternion.AngleAxis(90f, Vector3.up);

	public static readonly Quaternion ROTATION_HALF = Quaternion.AngleAxis(180f, Vector3.up);

	public static readonly Quaternion ROTATION_THREE_QUARTER = Quaternion.AngleAxis(270f, Vector3.up);

	[Header("Decoration Properties")]
	[SerializeField]
	private DecorationType _decorationType;

	[SerializeField]
	private VisualPrefab _visualPrefab;

	[SerializeField]
	private VisualPrefab[] _visualPrefabs;

	[Footprint]
	[SerializeField]
	private Footprint _footprint;

	[SerializeField]
	private DecorationCursorProperties _cursorProperties;

	[SerializeField]
	private bool _isSelectable;

	[SerializeField]
	private LocalizedString _tooltip;

	[Header("Navigation")]
	[SerializeField]
	private bool _overrideHierarchicalNodePanelty;

	[SerializeField]
	[ConditionalHide(false, ConditionalSourceField = "_overrideHierarchicalNodePanelty")]
	private int _hierarchicalNodePanelty;

	[Header("UI Panel")]
	[SerializeField]
	private Sprite _headerSprite;

	[SerializeField]
	private DecorationPanelElementId _uiElements;

	[SerializeField]
	private bool _showMalfunctionElements;

	[SerializeField]
	private bool _showEnergyGridLinkElements;

	[SerializeField]
	private bool _showEnergyStorageElements;

	[SerializeField]
	private bool _showEnergyGridEfficiency;

	[SerializeField]
	private TutorialID _tutorialPageID;

	[Header("FMOD Events")]
	[SerializeField]
	private EventReference _variationEvent;

	[SerializeField]
	private EventReference _rotateEvent;

	[SerializeField]
	private EventReference _placeEvent;

	[SerializeField]
	private EventReference _selectEvent;

	public DecorationType DecorationType => _decorationType;

	public virtual Decoration DecorationPrefab => GameManager.Settings.BuildableSettings.DecorationPrefab;

	public VisualPrefab VisualPrefab => _visualPrefab;

	public VisualPrefab[] VisualPrefabs => _visualPrefabs;

	public override string SurvivalGuideIdentifier => "decoration-" + base.name.ToLower();

	public override Types Type => Types.DecorationProperties;

	public bool IsSelectable => _isSelectable;

	public bool OverrideHierarchicalNodePanelty => _overrideHierarchicalNodePanelty;

	public int HierarchicalNodePanelty => _hierarchicalNodePanelty;

	public Sprite HeaderSprite => _headerSprite;

	public DecorationPanelElementId UIElements => _uiElements;

	public bool ShowMalfunctionElements => _showMalfunctionElements;

	public bool ShowEnergyGridLinkElements => _showEnergyGridLinkElements;

	public bool ShowEnergyStorageElements => _showEnergyStorageElements;

	public bool ShowEnergyGridEfficiency => _showEnergyGridEfficiency;

	public TutorialID TutorialPageID => _tutorialPageID;

	protected override bool DefaultToUnlocked => false;

	public EventReference FMODEventReference_Variation => _variationEvent;

	public EventReference FMODEventReference_Rotate => _rotateEvent;

	public EventReference FMODEventReference_Place => _placeEvent;

	public EventReference FMODEventReference_Select => _selectEvent;

	public override void ActivateCursor(CursorManager.CursorEvent deactivatedCallback)
	{
		_cursorProperties.Initialize(this);
		GameManager.CursorManager.Activate(_cursorProperties, deactivatedCallback);
	}

	public override bool ReturnCanBePlaced(Community community, bool checkResources = true)
	{
		if (((IReadOnlyCollection<CountedItemProperty>)(object)base.RequiredResources).IsNullOrEmpty())
		{
			return true;
		}
		return ResourceManager.AreCommunityResourcesAvailable(base.RequiredResources);
	}

	public bool ReturnCanPlaceOnSlots(DecorationSlots decorationSlots)
	{
		if (base.Width <= decorationSlots.Width)
		{
			return base.Depth <= decorationSlots.Height;
		}
		return false;
	}

	public bool ReturnCanPlaceOnSlot(DecorationSlots decorationSlots, int index, Turns turn, List<int> footprintIndices, List<int> boundsInidices)
	{
		bool flag = decorationSlots.Slots[index].IsAvailable(this);
		if (base.Width == 1 && base.Depth == 1 && flag)
		{
			footprintIndices.Add(index);
			boundsInidices.Add(index);
			return true;
		}
		if (decorationSlots.Width < base.Width || decorationSlots.Height < base.Depth || !flag)
		{
			return false;
		}
		int slotX = index % decorationSlots.Width;
		int slotY = index / decorationSlots.Width;
		switch (turn)
		{
		case Turns.Full:
		case Turns.Half:
			return FitsFootprintHorizontal(decorationSlots, turn, slotX, slotY, footprintIndices, boundsInidices);
		case Turns.Quarter:
		case Turns.ThreeQuarter:
			return FitsFootprintVertical(decorationSlots, turn, slotX, slotY, footprintIndices, boundsInidices);
		default:
			throw new NotImplementedException();
		}
	}

	private bool FitsFootprintHorizontal(DecorationSlots decorationSlots, Turns turn, int slotX, int slotY, List<int> footprintIndices, List<int> boundsIndices)
	{
		if (decorationSlots.Width < slotX + base.Width || decorationSlots.Height < slotY + base.Depth)
		{
			return false;
		}
		for (int i = 0; i < base.Depth; i++)
		{
			int num = (slotY + i) * decorationSlots.Width;
			for (int j = 0; j < base.Width; j++)
			{
				int num2 = num + slotX + j;
				boundsIndices.Add(num2);
				if (decorationSlots.Slots[num2].IsAvailable(this) && _footprint.IsToggled(j, i, turn))
				{
					footprintIndices.Add(num2);
					continue;
				}
				return false;
			}
		}
		return true;
	}

	private bool FitsFootprintVertical(DecorationSlots decorationSlots, Turns turn, int slotX, int slotY, List<int> footprintIndices, List<int> boundsIndices)
	{
		if (decorationSlots.Width < slotX + base.Depth || decorationSlots.Height < slotY + base.Width)
		{
			return false;
		}
		for (int i = 0; i < base.Width; i++)
		{
			int num = (slotY + i) * decorationSlots.Width;
			for (int j = 0; j < base.Depth; j++)
			{
				int num2 = num + slotX + j;
				boundsIndices.Add(num2);
				if (decorationSlots.Slots[num2].IsAvailable(this) && _footprint.IsToggled(i, j, turn))
				{
					footprintIndices.Add(num2);
					continue;
				}
				return false;
			}
		}
		return true;
	}

	public override string GetTooltip(TooltipBuilder tooltipBuilder)
	{
		return _tooltip;
	}

	public Quaternion TurnToRotation(Turns turn)
	{
		return turn switch
		{
			Turns.Full => ROTATION_FULL, 
			Turns.Quarter => ROTATION_QUARTER, 
			Turns.Half => ROTATION_HALF, 
			Turns.ThreeQuarter => ROTATION_THREE_QUARTER, 
			_ => throw new NotSupportedException(), 
		};
	}

	public Turns RotationToTurn(Quaternion rotation)
	{
		float y = rotation.eulerAngles.y;
		if (Mathf.Approximately(y, 0f))
		{
			return Turns.Full;
		}
		if (Mathf.Approximately(y, 90f))
		{
			return Turns.Quarter;
		}
		if (Mathf.Approximately(y, 180f))
		{
			return Turns.Half;
		}
		if (Mathf.Approximately(y, 270f))
		{
			return Turns.ThreeQuarter;
		}
		UnityEngine.Debug.LogWarningFormat("Unable to convert rotation {0} to Turns, returning Turns.Full", y);
		return Turns.Full;
	}

	public Decoration GetDecorationPrefabWithProperties()
	{
		Decoration decorationPrefab = DecorationPrefab;
		if ((bool)decorationPrefab)
		{
			return decorationPrefab.GetPrefabWithProperties(this);
		}
		return null;
	}
}
public class DecorationSlot : SceneBehaviour
{
	[SerializeField]
	private SpriteRenderer _outlineRenderer;

	[SerializeField]
	private HierarchicalNodeMarker _hierarchicalNodeMarker;

	[SerializeField]
	private int _populatedPenalty = 1000000;

	[SerializeField]
	private bool _blocked;

	private Color _defaultOutlineColor;

	public DecorationProperties Decoration { get; private set; }

	public DecorationProperties Border { get; private set; }

	public int Visual { get; private set; }

	public Quaternion Rotation { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if (_outlineRenderer != null)
		{
			_defaultOutlineColor = _outlineRenderer.color;
		}
	}

	public void Populate(DecorationProperties decorationProperties)
	{
		if (decorationProperties.DecorationType == DecorationType.Border)
		{
			Border = decorationProperties;
		}
		else
		{
			Decoration = decorationProperties;
		}
		if (_outlineRenderer != null)
		{
			_outlineRenderer.enabled = false;
		}
		UpdatePenalty();
	}

	public void Clear(DecorationProperties decorationProperties)
	{
		if (decorationProperties.DecorationType == DecorationType.Border)
		{
			Border = null;
		}
		else
		{
			Decoration = null;
		}
		UpdatePenalty();
	}

	public void SetOutlineActive(bool value)
	{
		if (_outlineRenderer != null)
		{
			_outlineRenderer.gameObject.SetActive(value);
			_outlineRenderer.enabled = value;
		}
	}

	public void SetOutlineActive(bool value, Color color)
	{
		if (_outlineRenderer != null)
		{
			_outlineRenderer.color = color;
			_outlineRenderer.gameObject.SetActive(value);
			_outlineRenderer.enabled = value;
		}
	}

	public void EnablePlacementOutline(DecorationProperties decorationProperties)
	{
		if (_outlineRenderer != null)
		{
			_outlineRenderer.gameObject.SetActive(value: true);
			_outlineRenderer.enabled = IsAvailable(decorationProperties);
		}
	}

	public void SetOutlineColor(Color color)
	{
		if (_outlineRenderer != null)
		{
			_outlineRenderer.color = color;
		}
	}

	public void ResetOutlineColor()
	{
		if (_outlineRenderer != null)
		{
			_outlineRenderer.color = _defaultOutlineColor;
		}
	}

	private void UpdatePenalty()
	{
		if (!(_hierarchicalNodeMarker == null))
		{
			if (Border == null && Decoration == null)
			{
				_hierarchicalNodeMarker.ClearPenalty();
			}
			else
			{
				_hierarchicalNodeMarker.SetPenalty(Mathf.Max(ReturnDecorationPropertiesPenalty(Border), ReturnDecorationPropertiesPenalty(Decoration)));
			}
		}
	}

	private int ReturnDecorationPropertiesPenalty(DecorationProperties decorationProperties)
	{
		if (decorationProperties == null)
		{
			return 0;
		}
		if (decorationProperties.OverrideHierarchicalNodePanelty)
		{
			return decorationProperties.HierarchicalNodePanelty;
		}
		return _populatedPenalty;
	}

	public bool IsAvailable(DecorationProperties decorationProperties)
	{
		if (!_blocked)
		{
			if (decorationProperties.DecorationType != DecorationType.Border)
			{
				return Decoration == null;
			}
			return Border == null;
		}
		return false;
	}
}
public class DecorationSlots : SceneBehaviour, IBuildableExtendable, IPersistentReference
{
	[Serializable]
	public class PersistentData : BuildableExtendablePersistentData<DecorationSlots>
	{
		[Serializable]
		private struct Slot
		{
			public int Index;

			public int DecorationIndex;

			[OptionalField(VersionAdded = 2)]
			public int Visual;

			public Quaternion Rotation;

			public Slot(DecorationSlot slot, int index)
			{
				Index = index;
				DecorationIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(slot.Decoration);
				Visual = slot.Visual;
				Rotation = slot.Rotation;
			}

			public void Restore(DecorationSlots decorationSlots)
			{
				if (Index >= 0 && decorationSlots.Slots.Length > Index && GameManager.PersistenceManager.TryReturnPropertiesReference<DecorationProperties>(DecorationIndex, out var reference))
				{
					decorationSlots.AddDecoration(reference, reference.RotationToTurn(Rotation), Visual, new int[1] { Index });
				}
			}
		}

		[Serializable]
		public class DecorationPersistentData : PersistentReference<Decoration>
		{
			public int PropertiesIndex;

			public DecorationProperties.Turns Turn;

			public int Visual;

			public int[] SlotIndices;

			public SubInventoryPersistentData Composition;

			[OptionalField(VersionAdded = 4)]
			private readonly string _customName;

			[OptionalField(VersionAdded = 3)]
			private readonly IDecoBehaviourPersistentData _behaviourData;

			[OptionalField(VersionAdded = 5)]
			private readonly BuildPhase _buildPhase = BuildPhase.Finished;

			[OptionalField(VersionAdded = 5)]
			private readonly PersistentReference<Project>.Reference _assignedProject;

			[OptionalField(VersionAdded = 5)]
			private readonly int _assignmentLimit = 1;

			[OptionalField(VersionAdded = 5)]
			private readonly InventoryPersistentData _inventory;

			[OptionalField(VersionAdded = 2)]
			public SubInventoryPersistentData Export;

			[OptionalField(VersionAdded = 2)]
			public float WaterConsumed;

			public DecorationPersistentData(Decoration decoration)
				: base(decoration)
			{
				PropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(decoration.Properties);
				Turn = decoration.Turn;
				Visual = decoration.Visual;
				SlotIndices = decoration.SlotIndices;
				Composition = SubInventoryPersistentData.Get(decoration.Inventory, SubInventoryType.Composition);
				_buildPhase = decoration.ConstructionHandler.BuildPhase;
				_assignedProject = decoration.ConstructionHandler.AssignedProject;
				_assignmentLimit = decoration.AssignmentLimit;
				_inventory = new InventoryPersistentData(decoration.Inventory);
				_customName = decoration.CustomName;
				if (base.Instance.Behaviour != null)
				{
					_behaviourData = base.Instance.Behaviour.GetPersistentData();
				}
			}

			public void Restore(DecorationSlots decorationSlots)
			{
				base.Restore();
				if (!GameManager.PersistenceManager.TryReturnPropertiesReference<DecorationProperties>(PropertiesIndex, out var reference))
				{
					return;
				}
				base.Instance = UnityEngine.Object.Instantiate(reference.DecorationPrefab, decorationSlots._decorationParent);
				base.Instance.Restore(decorationSlots, reference, Turn, Visual, SlotIndices);
				if (Composition != null)
				{
					Composition.Restore(base.Instance.Inventory);
				}
				decorationSlots.AddDecoration(base.Instance, SlotIndices);
				if (!_customName.IsNullOrEmpty())
				{
					base.Instance.Name = _customName;
				}
				if (_behaviourData != null && base.Instance.TryGetComponent<IDecorationBehaviour>(out var component))
				{
					_behaviourData.Restore(component, reference);
				}
				else if (PersistenceManager.DoesSaveInfoVersionComeBefore(0, 8, 6))
				{
					if (Export != null)
					{
						Export.Restore(base.Instance.Inventory);
					}
					if (base.Instance.TryGetComponent<CropDecorationBehaviour>(out var component2))
					{
						component2.Initialize();
						component2.RestoreCrop(WaterConsumed);
					}
				}
				if (_inventory != null)
				{
					_inventory.Restore(base.Instance.Inventory, base.Instance.gameObject);
				}
				BuildPhase buildPhase = _buildPhase;
				float progress = base.Instance.Inventory.ReturnCompositionProgress();
				base.Instance.RestoreConstruction(_assignmentLimit, buildPhase, progress);
			}

			public void RestoreReferences()
			{
				if (_behaviourData != null)
				{
					_behaviourData.RestoreReferences();
				}
				if (_assignedProject != null && _assignedProject.TryReturnInstance(out var reference))
				{
					base.Instance.RestoreConstructionReferences(reference);
				}
			}

			public void PopulateReferences()
			{
				if (_behaviourData != null)
				{
					_behaviourData.PopulateReferences();
				}
			}
		}

		private Slot[] _decorationSlots;

		[OptionalField(VersionAdded = 3)]
		private DecorationPersistentData[] _decorations;

		public PersistentData(DecorationSlots reference)
			: base(reference)
		{
			base.Instance = reference;
			_decorations = ReturnDecorationPersistentData();
		}

		public override void RestoreData(Buildable buildable)
		{
			if (!buildable.TryGetComponent<DecorationSlots>(out var component))
			{
				return;
			}
			base.Instance = component;
			if (!((IReadOnlyCollection<Slot>)(object)_decorationSlots).IsNullOrEmpty())
			{
				Slot[] decorationSlots = _decorationSlots;
				foreach (Slot slot in decorationSlots)
				{
					slot.Restore(base.Instance);
				}
			}
			if (!((IReadOnlyCollection<DecorationPersistentData>)(object)_decorations).IsNullOrEmpty())
			{
				DecorationPersistentData[] decorations = _decorations;
				for (int i = 0; i < decorations.Length; i++)
				{
					decorations[i].Restore(base.Instance);
				}
			}
		}

		public override void RestoreReferences()
		{
			if (!((IReadOnlyCollection<DecorationPersistentData>)(object)_decorations).IsNullOrEmpty())
			{
				DecorationPersistentData[] decorations = _decorations;
				for (int i = 0; i < decorations.Length; i++)
				{
					decorations[i].RestoreReferences();
				}
			}
		}

		public override void PopulateReferences()
		{
			if (!((IReadOnlyCollection<DecorationPersistentData>)(object)_decorations).IsNullOrEmpty())
			{
				DecorationPersistentData[] decorations = _decorations;
				for (int i = 0; i < decorations.Length; i++)
				{
					decorations[i].PopulateReferences();
				}
			}
		}

		private DecorationPersistentData[] ReturnDecorationPersistentData()
		{
			if (base.Instance.Decorations.Count == 0)
			{
				return null;
			}
			using ListPool<DecorationPersistentData>.List list = ListPool<DecorationPersistentData>.Get(32);
			int count = base.Instance.Decorations.Count;
			for (int i = 0; i < count; i++)
			{
				Decoration decoration = base.Instance.Decorations[i];
				if ((bool)decoration && (bool)decoration.Properties)
				{
					list.Add(new DecorationPersistentData(decoration));
				}
			}
			return list.IsNullOrEmpty() ? null : list.ToArray();
		}
	}

	[SerializeField]
	private DecorationType _acceptedDecorationTypes;

	[SerializeField]
	private int _width = 1;

	[SerializeField]
	private int _height = 1;

	[SerializeField]
	[Tooltip("The DecorationSlot instances linked to this DecorationSlots component. When the list is empty the DecorationSlot instances will be retrieved from the VisualPrfab using GetComponentsInChildren.")]
	private DecorationSlot[] _decorationSlots;

	[SerializeField]
	private Transform _decorationParent;

	[SerializeField]
	[Tooltip("If it is not guaranteed that all decoration slots are connected to the construction graph toggle this on. (e.g. houses)")]
	private bool _slotsAreOutOfBounds;

	public Action<Decoration> OnDecorationAdded;

	public Action<Decoration> OnDecorationRemoved;

	private static readonly InventoryAuditor s_auditor = new InventoryAuditor();

	private bool _decorationInventoryUpdated;

	private bool _isPlacementAllowed = true;

	public UnityEvent DecorationInventoryUpdated { get; } = new UnityEvent();

	public Buildable Buildable { get; private set; }

	public bool Active { get; private set; }

	public int PersistentIndex { get; set; }

	public int Width => _width;

	public int Height => _height;

	public DecorationSlot[] Slots { get; private set; }

	public List<Decoration> Decorations { get; } = new List<Decoration>();

	public int BeautyScore { get; private set; }

	public Decoration SelectedDecoration { get; private set; }

	public bool SlotsAreOutOfBounds => _slotsAreOutOfBounds;

	private void Start()
	{
		DisablePlacementMode();
		OnRemoveDecoToolDisabled();
	}

	private void Update()
	{
		foreach (InventoryAuditor.CountedItem countedItem in ReturnAuditorCount().CountedItems)
		{
			if (countedItem.UnreservedCount != 0 && !Buildable.Community.Inventory.ReturnFitsItemWithProperties(countedItem.ItemProperties))
			{
				Buildable.AddMalfunction(GameManager.Settings.BuildableSettings.ErrorResourceProviderBlocked);
				return;
			}
		}
		Buildable.RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorResourceProviderBlocked);
	}

	private void LateUpdate()
	{
		if (_decorationInventoryUpdated)
		{
			_decorationInventoryUpdated = false;
			DecorationInventoryUpdated.Invoke();
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.RemoveDecorationToolEnabled, OnRemoveDecoToolEnabled);
		GameEventDispatcher.RemoveListener(GameEventType.RemoveDecorationToolDisabled, OnRemoveDecoToolDisabled);
	}

	public void Initialize(Buildable buildable, bool restored = false)
	{
		Buildable = buildable;
		if (((IReadOnlyCollection<DecorationSlot>)(object)_decorationSlots).IsNullOrEmpty())
		{
			Slots = buildable.SpawnedVisual.GetComponentsInChildren<DecorationSlot>(includeInactive: true);
		}
		else
		{
			Slots = _decorationSlots;
		}
		GameEventDispatcher.AddListener(GameEventType.RemoveDecorationToolEnabled, OnRemoveDecoToolEnabled);
		GameEventDispatcher.AddListener(GameEventType.RemoveDecorationToolDisabled, OnRemoveDecoToolDisabled);
	}

	public void SetPlacementAllowed(bool allowed)
	{
		_isPlacementAllowed = allowed;
	}

	public bool TryEnablePlacementMode(DecorationProperties decorationProperties)
	{
		if (ReturnCanPlaceDecoration(decorationProperties))
		{
			DecorationSlot[] slots = Slots;
			for (int i = 0; i < slots.Length; i++)
			{
				slots[i].EnablePlacementOutline(decorationProperties);
			}
			return true;
		}
		return false;
	}

	public void DisablePlacementMode()
	{
		DecorationSlot[] slots = Slots;
		for (int i = 0; i < slots.Length; i++)
		{
			slots[i].SetOutlineActive(value: false);
		}
	}

	public void DisconnectEnergyPoles()
	{
		if (Decorations.IsNullOrEmpty())
		{
			return;
		}
		using ListPool<EnergyGridConnector>.List list = ListPool<EnergyGridConnector>.Get(Decorations.Count);
		foreach (Decoration decoration in Decorations)
		{
			if (decoration.TryGetExtendable<EnergyGridPole>(out var extendable) && extendable.Connector != null)
			{
				list.Add(extendable.Connector);
			}
		}
		foreach (EnergyGridConnector item in list)
		{
			for (int num = item.Connections.Length - 1; num >= 0; num--)
			{
				EnergyGridConnector energyGridConnector = item.Connections[num];
				if (energyGridConnector != null && !list.Contains(energyGridConnector))
				{
					EnergyGrid.Disconnect(item, energyGridConnector);
				}
			}
		}
	}

	public void SetSlotsOutlineColor(List<int> indices, Color color)
	{
		foreach (int index in indices)
		{
			Slots[index].SetOutlineColor(color);
		}
	}

	public void ResetSlotsOutlineColor()
	{
		DecorationSlot[] slots = Slots;
		for (int i = 0; i < slots.Length; i++)
		{
			slots[i].ResetOutlineColor();
		}
	}

	public Decoration AddDecoration(DecorationProperties decorationProperties, DecorationProperties.Turns turn, int visual, List<int> slotIndices, bool instantFreeBuild = false)
	{
		AudioManager.PlayOneShot(decorationProperties.FMODEventReference_Place);
		return AddDecoration(decorationProperties, turn, visual, slotIndices.ToArray(), instantFreeBuild);
	}

	public Decoration AddDecoration(DecorationProperties decorationProperties, DecorationProperties.Turns turn, int visual, int[] slotIndices, bool instantFreeBuild = false)
	{
		Decoration decoration = UnityEngine.Object.Instantiate(decorationProperties.DecorationPrefab);
		decoration.Initialize(this, decorationProperties, turn, visual, slotIndices, instantFreeBuild);
		AddDecoration(decoration, slotIndices);
		return decoration;
	}

	private void AddDecoration(Decoration decoration, int[] slotIndices)
	{
		decoration.transform.SetParent(ReturnDecorationParent(slotIndices));
		decoration.transform.Reset();
		decoration.transform.position = ReturnPositionFromBoundsIndices(slotIndices);
		decoration.RotateVisualPrefab();
		decoration.AddToConstructionGraph();
		decoration.Inventory.InventoryUpdatedEvent.AddListener(OnDecorationInventoryUpdated);
		foreach (int num in slotIndices)
		{
			Slots[num].Populate(decoration.Properties);
		}
		Decorations.Add(decoration);
		BeautyScore += decoration.Properties.BeautyScore;
		Buildable.Community.UpdateBeautyScore();
		OnDecorationAdded.SafeInvoke(decoration);
	}

	public void RefreshDecorationGraphNodes()
	{
		foreach (Decoration decoration in Decorations)
		{
			decoration.RemoveFromConstructionGraph();
			decoration.AddToConstructionGraph();
		}
	}

	public void RemoveDecoration(Decoration decoration, bool immediately = false)
	{
		if (decoration.ConstructionHandler.BuildPhase == BuildPhase.Finished)
		{
			decoration.OnSalvageDone = (Action<Decoration>)Delegate.Combine(decoration.OnSalvageDone, new Action<Decoration>(RemoveDecorationImmediate));
			decoration.Remove(immediately);
		}
	}

	public void RemoveDecorationImmediate(Decoration decoration)
	{
		if (Decorations.Remove(decoration))
		{
			int[] slotIndices = decoration.SlotIndices;
			foreach (int num in slotIndices)
			{
				Slots[num].Clear(decoration.Properties);
			}
			decoration.Inventory.InventoryUpdatedEvent.RemoveListener(OnDecorationInventoryUpdated);
			BeautyScore -= decoration.Properties.BeautyScore;
			Buildable.Community.UpdateBeautyScore();
			OnDecorationRemoved.SafeInvoke(decoration);
			DecorationEvent.DispatchRemoved(decoration);
		}
	}

	public void CancelDecorationRemoval(Decoration decoration)
	{
		decoration.ConstructionHandler.CancelSalvaging();
		decoration.OnSalvageDone = (Action<Decoration>)Delegate.Remove(decoration.OnSalvageDone, new Action<Decoration>(RemoveDecorationImmediate));
	}

	public void SetSelectedDecoration(Decoration decoration)
	{
		SelectedDecoration = decoration;
		if (!GameManager.UIManager.IsPanelOpen(PanelID.BuildablePanel))
		{
			GameManager.UIManager.DisplayPanel(Buildable);
		}
	}

	private void OnDecorationInventoryUpdated()
	{
		_decorationInventoryUpdated = true;
	}

	private void OnRemoveDecoToolEnabled(GameEvent gameEvent)
	{
		foreach (Decoration decoration in Decorations)
		{
			if (!decoration.Properties.IsSelectable)
			{
				decoration.SetColliderActive(active: true);
			}
		}
	}

	private void OnRemoveDecoToolDisabled(GameEvent gameEvent = null)
	{
		foreach (Decoration decoration in Decorations)
		{
			if (!decoration.Properties.IsSelectable)
			{
				decoration.SetColliderActive(active: false);
			}
		}
	}

	public bool AcceptsDecorationType(DecorationType decorationType)
	{
		return (_acceptedDecorationTypes & decorationType) != 0;
	}

	public bool HasAvailableSlots()
	{
		if (_isPlacementAllowed)
		{
			return Decorations.Count < Slots.Length;
		}
		return false;
	}

	public bool ReturnCanPlaceDecoration(DecorationProperties decorationProperties)
	{
		if (_isPlacementAllowed && (decorationProperties.DecorationType & _acceptedDecorationTypes) == decorationProperties.DecorationType && Buildable.BuildPhase == BuildPhase.Finished && decorationProperties.Width <= Width)
		{
			return decorationProperties.Depth <= Height;
		}
		return false;
	}

	public bool TryPopulateClosestSlotIndices(List<int> indices, Vector3 position, out Vector3 closesetPosition, DecorationProperties decorationProperties, DecorationProperties.Turns turn)
	{
		if (!ReturnCanPlaceDecoration(decorationProperties))
		{
			closesetPosition = default(Vector3);
			return false;
		}
		using ListPool<int>.List list = ListPool<int>.Get();
		using ListPool<int>.List list2 = ListPool<int>.Get();
		float num = float.MaxValue;
		bool result = false;
		closesetPosition = default(Vector3);
		for (int i = 0; i < Slots.Length; i++)
		{
			list.Clear();
			list2.Clear();
			if (!decorationProperties.ReturnCanPlaceOnSlot(this, i, turn, list, list2))
			{
				continue;
			}
			result = true;
			Vector3 vector = ReturnPositionFromBoundsIndices(list2);
			float num2 = position.DistanceToSquared(vector);
			if (!(num2 < num))
			{
				continue;
			}
			num = num2;
			indices.Clear();
			foreach (int item in list)
			{
				indices.Add(item);
			}
			closesetPosition = vector;
		}
		return result;
	}

	private Vector3 ReturnPositionFromBoundsIndices(List<int> boundsIndices)
	{
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < boundsIndices.Count; i++)
		{
			zero += Slots[boundsIndices[i]].transform.position;
		}
		return zero / boundsIndices.Count;
	}

	private Vector3 ReturnPositionFromBoundsIndices(int[] boundsIndices)
	{
		Vector3 zero = Vector3.zero;
		for (int i = 0; i < boundsIndices.Length; i++)
		{
			zero += Slots[boundsIndices[i]].transform.position;
		}
		return zero / boundsIndices.Length;
	}

	private bool TryReturnDecorationSlot(int[] slotIndices, out DecorationSlot decorationSlot)
	{
		decorationSlot = null;
		if (((IReadOnlyCollection<int>)(object)slotIndices).IsNullOrEmpty() || !_isPlacementAllowed)
		{
			return false;
		}
		foreach (int num in slotIndices)
		{
			if (0 <= num && num < Slots.Length)
			{
				decorationSlot = Slots[num];
				return true;
			}
		}
		return false;
	}

	public Transform ReturnDecorationParent(int[] slotIndices)
	{
		Transform decorationParent = _decorationParent;
		if (decorationParent == null && TryReturnDecorationSlot(slotIndices, out var decorationSlot))
		{
			decorationParent = decorationSlot.transform;
		}
		return decorationParent;
	}

	public InventoryAuditor ReturnAuditorCount()
	{
		s_auditor.Reset();
		foreach (Decoration decoration in Decorations)
		{
			decoration.Inventory.Count(s_auditor, SubInventoryType.Export);
		}
		return s_auditor;
	}

	public bool IsDraggable()
	{
		foreach (Decoration decoration in Decorations)
		{
			if (!decoration.IsDraggable())
			{
				return false;
			}
		}
		return true;
	}

	public void GetBlockingNeighbours(ref ListPool<VisualPrefab>.List blockingConstructions)
	{
		foreach (Decoration decoration in Decorations)
		{
			if (!decoration.IsDraggable())
			{
				blockingConstructions.Add(decoration.SpawnedVisual);
			}
		}
	}

	public void Activate()
	{
		Active = true;
		Buildable.Community.AddDecorationSlots(this);
	}

	public void Deactivate()
	{
		Active = false;
	}

	public bool CanBeDeconstructed()
	{
		return Decorations.Count == 0;
	}

	public bool CanBeUpgraded()
	{
		return true;
	}

	public bool CanBeSalvaged()
	{
		return Decorations.Count == 0;
	}

	public void Finish(bool restored = false)
	{
	}

	public bool IsEnabled()
	{
		if (base.enabled)
		{
			return Active;
		}
		return false;
	}

	public void OnDeconstruct()
	{
	}

	public void PopulateReferences(IBuildableExtendablePersistentData persistentData)
	{
		UnityEngine.Debug.LogWarning("TODO: Implement DecorationSlots.PopulateReferences");
	}

	public void Remove()
	{
	}

	public string ReturnDescription(string text)
	{
		return text;
	}

	public float ReturnWeight()
	{
		float num = 0f;
		foreach (Decoration decoration in Decorations)
		{
			num += decoration.Properties.Weight;
		}
		return num;
	}

	public void ShowResearchInfo(RectTransform parent)
	{
		UnityEngine.Debug.LogWarning("TODO: Implement DecorationSlots.ShowResearchInfo");
	}

	public void Shutdown()
	{
		Buildable.Community.RemoveDecorationSlots(this);
		DisablePlacementMode();
		if (Buildable.BuildPhase != BuildPhase.SalvageShutdown || Decorations.Count == 0)
		{
			return;
		}
		for (int num = Decorations.Count - 1; num >= 0; num--)
		{
			Decoration decoration = Decorations[num];
			if (decoration.ConstructionHandler.Progress < 1f)
			{
				if (decoration.Properties is CropDecorationProperties cropDecorationProperties && (float)cropDecorationProperties.Yield.Amount > 0f)
				{
					SalvageCompositionItems(decoration);
				}
				RemoveDecoration(decoration);
			}
		}
		GraphManager.RefreshNavigatorPaths();
	}

	private void SalvageCompositionItems(Decoration decoration)
	{
		foreach (Item item in decoration.Inventory.ReturnAllItems(SubInventoryType.Composition))
		{
			if (decoration.Inventory.TryTakeItem(item, out var takenItem))
			{
				Buildable.Inventory.AddItem(takenItem, SubInventoryType.Resources);
			}
		}
	}

	public void ShutdownImmediately()
	{
	}

	public void Upgrade(Buildable buildable)
	{
		if (Decorations.Count == 0 || !buildable.TryReturnBuildableExtendable<DecorationSlots>(out var buildableExtendable))
		{
			return;
		}
		if (buildableExtendable._width != _width || buildableExtendable.Height != _height)
		{
			UnityEngine.Debug.LogError("Upgrading is not currently not supported for DecorationSlots that don't have the same width and height!");
			return;
		}
		for (int i = 0; i < Decorations.Count; i++)
		{
			buildableExtendable.UpgradeDecoration(Decorations[i]);
		}
	}

	private void UpgradeDecoration(Decoration decoration)
	{
		int num = ((decoration.SlotIndices.Length == 1) ? decoration.SlotIndices[0] : (-1));
		if (num >= 0 && Slots.Length > num)
		{
			decoration.Upgrade(this);
			AddDecoration(decoration, decoration.SlotIndices);
		}
	}

	public IBuildableExtendablePersistentData ReturnPersistentData()
	{
		return new PersistentData(this);
	}

	public void Restore(IBuildableExtendablePersistentData persistentData)
	{
	}

	public void RestoreReferences(IBuildableExtendablePersistentData persistentData)
	{
	}
}
