[Serializable]
public class BuildSlots
{
	public Transform Parent;

	public BuildSlot[] Slots;

	private Transform _child;

	private float _progress;

	public void Attach(Transform transform)
	{
		_child = transform;
		transform.SetParent(Parent, worldPositionStays: true);
		SetProgress(_progress);
	}

	public void SetProgress(float progress)
	{
		_progress = progress;
		if (!(_child == null) && Slots.Length != 0)
		{
			int num = 0;
			for (int i = 0; i < Slots.Length && !(Slots[i].Threshold > progress); i++)
			{
				num = i;
			}
			Slots[num].TransformData.Apply(_child);
		}
	}

	public void Detach(Transform newParent)
	{
		if (_child == null)
		{
			UnityEngine.Debug.LogWarning("Detach was called on BuildSlots when no Child was present.");
			return;
		}
		_child.SetParent(newParent, worldPositionStays: true);
		_child.localScale = Vector3.one;
		_child.localRotation = Quaternion.identity;
		_child = null;
	}

	public void FillTransforms()
	{
		if (!(Parent == null))
		{
			Slots = new BuildSlot[Parent.childCount];
			for (int num = Parent.childCount - 1; num >= 0; num--)
			{
				Transform child = Parent.GetChild(num);
				Slots[num] = new BuildSlot(0f, new TransformData(child.localPosition, child.eulerAngles, child.localScale));
				UnityEngine.Object.DestroyImmediate(child.gameObject);
			}
			PrefabHelper.SavePrefab();
		}
	}
}
[Serializable]
public class FarmSlots : Slots
{
	private RecipeVisual[] _farmVisualSlots;

	public void Initialize()
	{
		_farmVisualSlots = new RecipeVisual[TransformData.Length];
	}

	public void Display(int farmQueueIndex, QueuedRecipe queuedRecipe)
	{
		if (TryGetRecipeVisual(farmQueueIndex, out var recipeVisual))
		{
			if ((bool)recipeVisual)
			{
				PrefabPool.Repool(recipeVisual);
			}
			recipeVisual = PrefabPool.GetInstance(FlotsamGame.Random(queuedRecipe.Recipe.Properties.RecipeVisualPrefabs));
			recipeVisual.Initialize(queuedRecipe);
			if (queuedRecipe.Progress < queuedRecipe.ProductionTime)
			{
				recipeVisual.StartRecipe(queuedRecipe.Progress);
			}
			else
			{
				recipeVisual.FinishRecipe();
			}
			_farmVisualSlots[farmQueueIndex] = recipeVisual;
			recipeVisual.transform.SetParent(Parent);
			TransformData[farmQueueIndex].Apply(recipeVisual.transform);
		}
	}

	public void Update(int farmQueueIndex, float progress)
	{
		if (TryGetRecipeVisual(farmQueueIndex, out var recipeVisual) && (bool)recipeVisual)
		{
			recipeVisual.UpdateRecipe(progress);
		}
	}

	public void Finish(int farmQueueIndex)
	{
		if (TryGetRecipeVisual(farmQueueIndex, out var recipeVisual) && (bool)recipeVisual)
		{
			recipeVisual.FinishRecipe();
		}
	}

	public void Remove(int farmQueueIndex)
	{
		if (TryGetRecipeVisual(farmQueueIndex, out var recipeVisual))
		{
			if ((bool)recipeVisual)
			{
				recipeVisual.Repool();
			}
			_farmVisualSlots[farmQueueIndex] = null;
		}
	}

	private bool TryGetRecipeVisual(int index, out RecipeVisual recipeVisual)
	{
		if (index < 0 || index >= _farmVisualSlots.Length)
		{
			recipeVisual = null;
			return false;
		}
		recipeVisual = _farmVisualSlots[index];
		return true;
	}
}
[Serializable]
public class InventorySlots : Slots
{
	[SerializeField]
	private bool _canGenerateSlots;

	[SerializeField]
	[ConditionalHide("_canGenerateSlots", true)]
	private int _topLayerVisualAmount = 1;

	private List<StorageVisual> _activeVisuals = new List<StorageVisual>();

	private Inventory _inventory;

	private SubInventoryType _inventoryType;

	private OutlineRendererComponent _outlineRenderer;

	private static Dictionary<ItemProperties, Queue<StorageVisual>> _cachedVisuals;

	private static Transform _cachedVisualParent;

	public void Initialize(Inventory inventory, SubInventoryType inventoryType, OutlineRendererComponent outlineRenderer)
	{
		if (!(Parent == null))
		{
			_inventory = inventory;
			_inventoryType = inventoryType;
			_inventory.InventoryUpdatedEvent.AddListener(UpdateSlot);
			_outlineRenderer = outlineRenderer;
			if (_canGenerateSlots)
			{
				GenerateSlots();
			}
			GameEventDispatcher.AddListener(GameEventType.DevTools_UpdateResourceVisuals, DevTools_UpdateResourceVisuals);
		}
	}

	public void Remove()
	{
		if (!(Parent == null) && !(_inventory == null))
		{
			_inventory.InventoryUpdatedEvent.RemoveListener(UpdateSlot);
			GameEventDispatcher.RemoveListener(GameEventType.DevTools_UpdateResourceVisuals, DevTools_UpdateResourceVisuals);
		}
	}

	private void GenerateSlots()
	{
		int num = 0;
		int num2 = _inventory.ReturnCapacity(_inventoryType);
		if (num2 > TransformData.Length && TransformData.Length != 0)
		{
			_topLayerVisualAmount = Mathf.Clamp(_topLayerVisualAmount, 1, TransformData.Length);
			num = Mathf.CeilToInt((float)(num2 - TransformData.Length) / (float)_topLayerVisualAmount);
			AddGeneratedSlotTransforms(num);
		}
	}

	private void AddGeneratedSlotTransforms(int levelsToAdd)
	{
		for (int i = 0; i < levelsToAdd; i++)
		{
			Array.Resize(ref TransformData, TransformData.Length + _topLayerVisualAmount);
			for (int j = 0; j < _topLayerVisualAmount; j++)
			{
				TransformData transformData = TransformData[TransformData.Length - 1 - _topLayerVisualAmount - j];
				TransformData[TransformData.Length - 1 - j] = new TransformData(transformData.Position, transformData.Rotation, transformData.Scale);
				TransformData[TransformData.Length - 1 - j].Position.y += 0.72f;
				TransformData[TransformData.Length - 1 - j].Rotation.y += UnityEngine.Random.Range(-180, 180);
			}
		}
	}

	public void UpdateSlot()
	{
		if (GeneralDevTools.ResourceVisualsDisabled)
		{
			return;
		}
		List<Item> list = _inventory.ReturnAllItems(_inventoryType);
		foreach (StorageVisual activeVisual in _activeVisuals)
		{
			_outlineRenderer.UpdateStorageVisual(activeVisual);
			activeVisual.gameObject.SetActive(value: false);
		}
		for (int i = 0; i < list.Count; i++)
		{
			Item item = list[i];
			if (i >= TransformData.Length)
			{
				break;
			}
			StorageVisual storageVisual = ReturnVisual(item.Properties);
			storageVisual.gameObject.SetActive(value: true);
			_outlineRenderer.UpdateStorageVisual(storageVisual, addToConstructionOutline: true);
			storageVisual.transform.SetParent(Parent);
			TransformData[i].Apply(storageVisual.transform);
		}
		for (int num = _activeVisuals.Count - 1; num >= 0; num--)
		{
			StorageVisual storageVisual = _activeVisuals[num];
			if (!storageVisual.gameObject.activeSelf)
			{
				CacheVisual(storageVisual);
				_activeVisuals.RemoveAt(num);
			}
		}
	}

	public static void CacheVisual(StorageVisual visual)
	{
		if (_cachedVisuals == null)
		{
			_cachedVisuals = new Dictionary<ItemProperties, Queue<StorageVisual>>();
		}
		if (!_cachedVisuals.TryGetValue(visual.ItemProperties, out var value))
		{
			value = new Queue<StorageVisual>();
			_cachedVisuals.Add(visual.ItemProperties, value);
		}
		if (_cachedVisualParent == null)
		{
			_cachedVisualParent = new GameObject("CachedInventorySlotsParent").transform;
		}
		visual.transform.SetParent(_cachedVisualParent);
		value.Enqueue(visual);
	}

	public static void ClearCachedVisuals()
	{
		if (_cachedVisuals != null)
		{
			_cachedVisuals.Clear();
		}
	}

	private StorageVisual ReturnVisual(ItemProperties properties)
	{
		foreach (StorageVisual activeVisual in _activeVisuals)
		{
			if (activeVisual.ItemProperties == properties && !activeVisual.gameObject.activeSelf)
			{
				return activeVisual;
			}
		}
		StorageVisual storageVisual = ReturnOrCreateCachedVisual(properties);
		_activeVisuals.Add(storageVisual);
		return storageVisual;
	}

	private static StorageVisual ReturnOrCreateCachedVisual(ItemProperties properties)
	{
		StorageVisual storageVisual = null;
		if (_cachedVisuals == null)
		{
			_cachedVisuals = new Dictionary<ItemProperties, Queue<StorageVisual>>();
		}
		if (_cachedVisuals.TryGetValue(properties, out var value) && value.Count > 0)
		{
			storageVisual = value.Dequeue();
		}
		else
		{
			storageVisual = UnityEngine.Object.Instantiate(properties.StorageVisualPrefab);
			storageVisual.Initialize(properties);
		}
		return storageVisual;
	}

	private void DevTools_UpdateResourceVisuals(GameEvent gameEvent)
	{
		if (GeneralDevTools.ResourceVisualsDisabled)
		{
			foreach (StorageVisual activeVisual in _activeVisuals)
			{
				_outlineRenderer.UpdateStorageVisual(activeVisual);
				activeVisual.gameObject.SetActive(value: false);
			}
			return;
		}
		UpdateSlot();
	}
}
[Serializable]
public class ReservableAttachableSlots : AttachableSlots
{
	private int _reservedCount;

	private Transform[] _reservingTransforms;

	public override bool Attach(Transform transform)
	{
		if (AttachReserved(transform) || base.Attach(transform))
		{
			return true;
		}
		UnityEngine.Debug.LogWarning($"Tried attaching {transform.name} to reservable slot, which was not reserved.");
		return false;
	}

	public override void Detach(Transform transform, Transform newParent)
	{
		if (!Unreserve(transform))
		{
			base.Detach(transform, newParent);
		}
	}

	public bool Reserve(Transform transform, out Vector3 worldPosition)
	{
		int i;
		return Reserve(transform, out i, out worldPosition);
	}

	public bool Reserve(Transform transform, out int index)
	{
		Vector3 worldPosition;
		return Reserve(transform, out index, out worldPosition);
	}

	public bool Unreserve(Transform transform)
	{
		if (Unreserve(transform, out var _))
		{
			return true;
		}
		UnityEngine.Debug.LogWarning("Tried unreserving " + transform.name + " from reservable slot, which was not reserved.");
		return false;
	}

	protected override void Initialize()
	{
		base.Initialize();
		if (_reservingTransforms == null)
		{
			_reservingTransforms = new Transform[base.Count];
		}
	}

	private bool Reserve(Transform transform, out int i, out Vector3 worldPosition)
	{
		worldPosition = Parent.position;
		Initialize();
		for (i = 0; i < base.Count; i++)
		{
			if (_children[i] == null && _reservingTransforms[i] == null)
			{
				_reservingTransforms[i] = transform;
				_reservedCount++;
				worldPosition = Parent.position + TransformData[i].Position;
				return true;
			}
		}
		UnityEngine.Debug.LogWarning("Tried reserving " + transform.name + " to reservable slot, which has no available slots.");
		return false;
	}

	private bool Unreserve(Transform transform, out int i)
	{
		if (_reservingTransforms != null)
		{
			for (i = 0; i < base.Count; i++)
			{
				if (_reservingTransforms[i] == transform)
				{
					_reservingTransforms[i] = null;
					_reservedCount--;
					return true;
				}
			}
		}
		i = -1;
		return false;
	}

	private bool AttachReserved(Transform transform)
	{
		if (Unreserve(transform, out var i))
		{
			return Attach(transform, i);
		}
		return false;
	}

	public override bool AreSlotsAvailable()
	{
		return base.ChildCount + _reservedCount < TransformData.Length;
	}
}
[Serializable]
public abstract class Slots
{
	public Transform Parent;

	public TransformData[] TransformData;

	public int Count => TransformData.Length;
}
