public class Gizmo : MonoBehaviour
{
	public enum Type
	{
		Cube,
		Sphere,
		Mesh,
		WireCube,
		WireSphere,
		WireMesh
	}

	[Tooltip("Enable the gizmo drawing.")]
	public bool Enabled = true;

	[Header("Properties")]
	[SerializeField]
	[Tooltip("Color of the gizmo.")]
	private Color _color = Color.red;

	[SerializeField]
	[Tooltip("Size of the gizmo.")]
	private Vector3 _size = Vector3.one;

	[SerializeField]
	[Tooltip("Type of the gizmo to draw.")]
	private Type _type;

	[SerializeField]
	[Tooltip("Mesh gizmo to draw.")]
	private Mesh _mesh;

	private Vector3 _position = Vector3.zero;

	private void OnDrawGizmos()
	{
		if (Enabled)
		{
			Gizmos.color = _color;
			switch (_type)
			{
			default:
				Gizmos.DrawCube(new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), _size);
				break;
			case Type.Sphere:
				Gizmos.DrawSphere(new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), _size.x);
				break;
			case Type.Mesh:
				Gizmos.DrawMesh(_mesh, new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), base.transform.rotation, _size);
				break;
			case Type.WireCube:
				Gizmos.DrawWireCube(new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), _size);
				break;
			case Type.WireSphere:
				Gizmos.DrawWireSphere(new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), _size.x);
				break;
			case Type.WireMesh:
				Gizmos.DrawWireMesh(_mesh, new Vector3(base.transform.position.x + _position.x, base.transform.position.y + _position.y, base.transform.position.z + _position.z), base.transform.rotation, _size);
				break;
			}
		}
	}

	public void SetColor(Color newColor)
	{
		_color = newColor;
	}

	public void SetGizmoProperties(Type gizmoType, Vector3 gizmoSize)
	{
		_type = gizmoType;
		_size = gizmoSize;
	}
}
public class EnergyGrid : IPersistentReference
{
	public List<EnergyGridConnector> Links { get; private set; }

	public List<IEnergyGridComponent> Components { get; private set; }

	public List<IEnergyGridStorage> Storages { get; private set; }

	public List<IEnergyGridConsumer> Consumers { get; private set; }

	public List<IEnergyGridProducer> Producers { get; private set; }

	public float GridEfficiency { get; private set; } = 1f;

	public bool HasEnergy
	{
		get
		{
			if (!(ReturnStorageEnergy() > 0f))
			{
				return ReturnEnergyProduction() > 0f;
			}
			return true;
		}
	}

	public bool IsFull => ReturnStorageEnergy() >= ReturnStorageCapacity();

	public bool IsEmpty => ReturnStorageEnergy() <= 0f;

	public EnergyGridObjectOfInterest ObjectOfInterest { get; private set; }

	public bool IsTownheartGrid { get; private set; }

	public int PersistentIndex { get; set; }

	public EnergyGrid()
	{
		Links = new List<EnergyGridConnector>();
		Components = new List<IEnergyGridComponent>();
		Storages = new List<IEnergyGridStorage>();
		Consumers = new List<IEnergyGridConsumer>();
		Producers = new List<IEnergyGridProducer>();
		ObjectOfInterest = new EnergyGridObjectOfInterest(this);
	}

	public EnergyGrid(EnergyGridPersistentData data)
		: this()
	{
	}

	public void CalculateEfficiency()
	{
		float deltaTime = Time.deltaTime;
		bool num = Mathf.Approximately(GridEfficiency, 1f);
		float num2 = ReturnEnergyConsumption() * deltaTime;
		float num3 = ReturnEnergyProduction() * deltaTime;
		float num4 = Mathf.Clamp(num2 - num3, 0f, ReturnStorageEnergy());
		float num5 = num3 + num4;
		float num6 = num3 - num2;
		float num7 = Mathf.Min(num2, num3);
		float num8 = num7;
		if (num2 <= 0f)
		{
			GridEfficiency = 1f;
		}
		else
		{
			GridEfficiency = (Mathf.Approximately(num5, num2) ? 1f : Mathf.Clamp(num5 / num2, 0f, 1f));
		}
		if (num != Mathf.Approximately(GridEfficiency, 1f))
		{
			new EnergyGridEvent(GameEventType.EnergyGridEfficiencyUpdated, this).Dispatch();
		}
		if (num4 > 0f)
		{
			RequestStorageEnergy(num4);
		}
		if (num6 > 0f)
		{
			num8 += FillStorageEnergy(num6);
		}
		if (num7 > 0f)
		{
			new EnergyEvent(GameEventType.EnergyConsumed, num7).Dispatch();
		}
		if (num8 > 0f)
		{
			new EnergyEvent(GameEventType.EnergyProduced, num8).Dispatch();
		}
	}

	public bool AddConnector(EnergyGridConnector connector)
	{
		if (Links.AddUnique(connector))
		{
			if (connector.IsTownheart)
			{
				IsTownheartGrid = true;
			}
			return true;
		}
		return false;
	}

	public bool RemoveConnector(EnergyGridConnector connector)
	{
		if (Links.Remove(connector))
		{
			if (connector.IsTownheart)
			{
				IsTownheartGrid = false;
			}
			return true;
		}
		return false;
	}

	public void AddComponent(IEnergyGridComponent component)
	{
		if (Components.AddUnique(component))
		{
			new EnergyGridEvent(GameEventType.EnergyGridEfficiencyUpdated, this).Dispatch();
		}
	}

	public void RemoveComponent(IEnergyGridComponent component)
	{
		if (Components.Remove(component))
		{
			if (Components.Count == 0)
			{
				EnergyGridManager.RemoveGrid(this);
			}
			new EnergyGridEvent(GameEventType.EnergyGridEfficiencyUpdated, this).Dispatch();
		}
	}

	public void AddProducer(IEnergyGridProducer producer)
	{
		if (Producers.AddUnique(producer))
		{
			Sorting.SlowSort(Producers);
		}
	}

	public void RemoveProducer(IEnergyGridProducer producer)
	{
		if (Producers.Remove(producer))
		{
			Sorting.SlowSort(Producers);
		}
	}

	public void UpdateGrids()
	{
		List<HashSet<EnergyGridConnector>> list = ListPool<HashSet<EnergyGridConnector>>.Get();
		HashSet<EnergyGridConnector> visited = new HashSet<EnergyGridConnector>();
		foreach (EnergyGridConnector link in Links)
		{
			if (!visited.Contains(link))
			{
				HashSet<EnergyGridConnector> components = new HashSet<EnergyGridConnector>();
				link.PopulateEnergyGridConnections(ref components, ref visited);
				list.Add(components);
			}
		}
		if (list.Count <= 0)
		{
			return;
		}
		foreach (EnergyGridConnector item in list[0])
		{
			if (!Links.Contains(item))
			{
				item.ClearEnergyGrid();
			}
		}
		list.RemoveAt(0);
		foreach (HashSet<EnergyGridConnector> item2 in list)
		{
			EnergyGrid energyGrid = EnergyGridManager.AddGrid();
			foreach (EnergyGridConnector item3 in item2)
			{
				item3.ClearEnergyGrid();
				item3.SetEnergyGrid(energyGrid);
			}
		}
		ListPool<HashSet<EnergyGridConnector>>.Add(list);
	}

	public float RequestStorageEnergy(float requestedAmount)
	{
		float num = 0f;
		int num2 = ReturnAvailableStorageCount();
		if (num2 <= 0)
		{
			return num;
		}
		float b = ReturnStorageEnergy();
		requestedAmount = Mathf.Min(requestedAmount, b);
		float energyAmount = requestedAmount / (float)num2;
		Sorting.SlowSort(Storages);
		for (int num3 = Storages.Count - 1; num3 >= 0; num3--)
		{
			IEnergyGridStorage energyGridStorage = Storages[num3];
			if (!energyGridStorage.IsEmpty)
			{
				if (energyGridStorage.TryRequestEnergy(energyAmount, out var returnedAmount))
				{
					requestedAmount -= returnedAmount;
					num += returnedAmount;
				}
				else
				{
					requestedAmount -= returnedAmount;
					num += returnedAmount;
					num2--;
					energyAmount = requestedAmount / (float)num2;
				}
			}
		}
		new EnergyEvent(GameEventType.EnergyConsumed, num).Dispatch();
		return num;
	}

	public float FillStorageEnergy(float amountToStore)
	{
		int num = ReturnNonFullStorageCount();
		if (num <= 0)
		{
			return 0f;
		}
		float energyAmount = amountToStore / (float)num;
		float num2 = 0f;
		Sorting.SlowSort(Storages);
		foreach (IEnergyGridStorage storage in Storages)
		{
			if (!storage.IsFull)
			{
				storage.TryAddEnergy(energyAmount, out var addedAmount);
				amountToStore -= addedAmount;
				num2 += addedAmount;
				num--;
				energyAmount = amountToStore / (float)num;
			}
		}
		return num2;
	}

	public bool IsHighestPriority(IEnergyGridProducer producer)
	{
		if (Storages.Count > 0)
		{
			return true;
		}
		int num = 0;
		foreach (IEnergyGridProducer producer2 in Producers)
		{
			if (producer2 != null && !producer2.IsGenerating && producer2.ReturnCanRun() && producer2.EnergyGrid.ReturnRequiresEnergyFromProducer(producer2) && producer2.Priority > num)
			{
				num = producer2.Priority;
			}
		}
		return producer.Priority >= num;
	}

	public float ReturnEnergyRequirement()
	{
		float num = 0f;
		foreach (IEnergyGridConsumer consumer in Consumers)
		{
			num += consumer.EnergyRequirement;
		}
		return num;
	}

	public float ReturnEnergyConsumption()
	{
		float num = 0f;
		foreach (IEnergyGridConsumer consumer in Consumers)
		{
			num += consumer.CurrentEnergyConsumption;
		}
		return num;
	}

	public float ReturnEnergyProduction()
	{
		float num = 0f;
		foreach (IEnergyGridProducer producer in Producers)
		{
			num += producer.Production;
		}
		return num;
	}

	public float ReturnEnergyProductionExcludingProducer(IEnergyGridProducer excludedProducer)
	{
		float num = 0f;
		foreach (IEnergyGridProducer producer in Producers)
		{
			if (producer != excludedProducer)
			{
				num += producer.Production;
			}
		}
		return num;
	}

	public bool ReturnRequiresEnergyFromProducer(IEnergyGridProducer producer)
	{
		if (Storages.Count > 0)
		{
			if (IsFull)
			{
				return false;
			}
			float num = ReturnStorageEnergy();
			float num2 = ReturnStorageCapacity();
			return num / num2 <= producer.EnergyFillPercentage;
		}
		return ReturnEnergyProductionExcludingProducer(producer) < ReturnEnergyRequirement();
	}

	public float ReturnStorageEnergy()
	{
		float num = 0f;
		foreach (IEnergyGridStorage storage in Storages)
		{
			num += storage.EnergyAmount;
		}
		return num;
	}

	public float ReturnStorageCapacity()
	{
		float num = 0f;
		foreach (IEnergyGridStorage storage in Storages)
		{
			num += storage.EnergyCapacity;
		}
		return num;
	}

	public int ReturnNonFullStorageCount()
	{
		int num = 0;
		foreach (IEnergyGridStorage storage in Storages)
		{
			if (!storage.IsFull)
			{
				num++;
			}
		}
		return num;
	}

	public int ReturnAvailableStorageCount()
	{
		int num = 0;
		foreach (IEnergyGridStorage storage in Storages)
		{
			if (!storage.IsEmpty)
			{
				num++;
			}
		}
		return num;
	}

	public void Merge(EnergyGrid other)
	{
		if (other != this)
		{
			for (int num = other.Links.Count - 1; num >= 0; num--)
			{
				other.Links[num].SetEnergyGrid(this);
			}
			EnergyGridManager.RemoveGrid(other);
		}
	}

	public static void Connect(EnergyGridConnector from, EnergyGridConnector to)
	{
		from.Connect(to);
		to.Connect(from);
		from.EnergyGrid.Merge(to.EnergyGrid);
		new EnergyGridConnectionEvent(GameEventType.EnergyGridConnectionAdded, from, to).Dispatch();
	}

	public static void ConnectWithIndex(EnergyGridConnector from, uint fromIndex, EnergyGridConnector to)
	{
		from.Connect(to, fromIndex);
		to.Connect(from);
		from.EnergyGrid.Merge(to.EnergyGrid);
		EnergyGridConnectionEvent.Dispatch(GameEventType.EnergyGridConnectionAdded, from, to);
	}

	public static void Disconnect(EnergyGridConnector componentA, EnergyGridConnector componentB)
	{
		componentA.Disconnect(componentB);
		componentB.Disconnect(componentA);
		if (componentA.EnergyGrid != componentB.EnergyGrid)
		{
			UnityEngine.Debug.LogError("Energy grids did not match.");
		}
		componentA.EnergyGrid.UpdateGrids();
		new EnergyGridConnectionEvent(GameEventType.EnergyGridConnectionRemoved, componentA, componentB).Dispatch();
	}

	public static void DisconnectWithIndex(EnergyGridConnector componentA, uint index)
	{
		if (componentA.TryGetConnectedComponent(out var connectedComponent, index))
		{
			Disconnect(componentA, connectedComponent);
		}
	}
}
[RequireComponent(typeof(MeshFilter), typeof(MeshRenderer))]
public class EnergyGridConnection : MonoBehaviour
{
	[SerializeField]
	private MeshFilter _meshFilter;

	private EnergyGridConnector _parent;

	private EnergyGridConnector _other;

	private float _generatedLength;

	public void Initialize(EnergyGridConnector parent, EnergyGridConnector other)
	{
		_parent = parent;
		_other = other;
		base.transform.localPosition = Vector3.zero;
		_generatedLength = (_parent.ConnectionTransform.position - _other.ConnectionTransform.position).magnitude;
		_meshFilter.mesh = EnergyGridConnectionVisualizer.GenerateCable(_generatedLength);
	}

	private void Update()
	{
		base.transform.position = Vector3.Lerp(_parent.ConnectionTransform.position, _other.ConnectionTransform.position, 0.5f);
		base.transform.rotation = FlotsamGame.PointsToRotation(_parent.ConnectionTransform.position, _other.ConnectionTransform.position, level: false);
		float magnitude = (_parent.ConnectionTransform.position - _other.ConnectionTransform.position).magnitude;
		_meshFilter.transform.localScale = _meshFilter.transform.localScale.SetZ(magnitude / _generatedLength);
	}

	public bool HasConnection(EnergyGridConnector a, EnergyGridConnector b)
	{
		if (_parent == a && _other == b)
		{
			return true;
		}
		if (_other == a && _parent == b)
		{
			return true;
		}
		return false;
	}
}
public class EnergyGridConnectionVisualizer : SceneBehaviour
{
	[SerializeField]
	[FormerlySerializedAs("_linkPrefab")]
	private EnergyGridConnection _connectionPrefab;

	private readonly List<EnergyGridConnection> _connections = new List<EnergyGridConnection>();

	private void Start()
	{
		GameEventDispatcher.AddListener(GameEventType.EnergyGridConnectionAdded, OnConnectionAdded);
		GameEventDispatcher.AddListener(GameEventType.EnergyGridConnectionRemoved, OnConnectionRemoved);
		foreach (EnergyGrid grid in EnergyGridManager.Grids)
		{
			foreach (EnergyGridConnector link in grid.Links)
			{
				if (link.Connections != null)
				{
					EnergyGridConnector[] connections = link.Connections;
					foreach (EnergyGridConnector b in connections)
					{
						AddConnection(link, b);
					}
				}
			}
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridConnectionAdded, OnConnectionAdded);
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridConnectionRemoved, OnConnectionRemoved);
	}

	private void OnConnectionAdded(GameEvent gameEvent)
	{
		EnergyGridConnectionEvent energyGridConnectionEvent = gameEvent as EnergyGridConnectionEvent;
		AddConnection(energyGridConnectionEvent.ComponentA, energyGridConnectionEvent.ComponentB);
	}

	private void OnConnectionRemoved(GameEvent gameEvent)
	{
		EnergyGridConnectionEvent energyGridConnectionEvent = gameEvent as EnergyGridConnectionEvent;
		RemoveConnection(energyGridConnectionEvent.ComponentA, energyGridConnectionEvent.ComponentB);
	}

	private void RemoveConnection(EnergyGridConnector a, EnergyGridConnector b)
	{
		if (TryReturnConnection(a, b, out var connection))
		{
			_connections.Remove(connection);
			UnityEngine.Object.Destroy(connection.gameObject);
		}
	}

	private void AddConnection(EnergyGridConnector a, EnergyGridConnector b)
	{
		if (!(a == null) && !(b == null) && !TryReturnConnection(a, b, out var _))
		{
			EnergyGridConnection energyGridConnection = UnityEngine.Object.Instantiate(_connectionPrefab);
			energyGridConnection.Initialize(a, b);
			_connections.Add(energyGridConnection);
		}
	}

	private bool TryReturnConnection(EnergyGridConnector a, EnergyGridConnector b, out EnergyGridConnection connection)
	{
		foreach (EnergyGridConnection connection2 in _connections)
		{
			if (connection2.HasConnection(a, b))
			{
				connection = connection2;
				return true;
			}
		}
		connection = null;
		return false;
	}

	public static Mesh GenerateCable(float height)
	{
		int cableSideAmount = GameManager.Settings.BuildableSettings.CableSideAmount;
		float cableSegmentLength = GameManager.Settings.BuildableSettings.CableSegmentLength;
		float cableRadius = GameManager.Settings.BuildableSettings.CableRadius;
		Mesh mesh = new Mesh();
		int num = cableSideAmount;
		int num2 = (int)(height / cableSegmentLength);
		num2 = Mathf.Clamp(num2, 1, num2);
		float num3 = height / (float)num2;
		int num4 = num * (num2 + 1);
		Vector3[] array = new Vector3[num4];
		Vector2[] array2 = new Vector2[num4];
		Color[] array3 = new Color[num4];
		int[] array4 = new int[num * num2 * 6];
		float num5 = MathF.PI * 2f / (float)cableSideAmount;
		float num6 = 0f;
		for (int i = 0; i <= num2; i++)
		{
			for (int j = 0; j < num; j++)
			{
				num6 = (float)j * num5;
				int num7 = i * num;
				array[num7 + j] = new Vector3(cableRadius * Mathf.Sin(num6), cableRadius * Mathf.Cos(num6), (float)i * num3 - height / 2f);
				array2[num7 + j] = Vector3.one * i;
				float num8 = Mathf.Clamp(Mathf.Sin(MathF.PI * ((float)i / (float)num2)), 0f, 1f);
				array3[num7 + j] = new Color(num8, num8, num8, 1f);
				if (i != num2)
				{
					int num9 = num * 6 * i + j * 6;
					array4[num9] = num7 + j;
					array4[num9 + 1] = num7 + j + cableSideAmount;
					array4[num9 + 2] = num7 + (j + 1) % cableSideAmount + cableSideAmount;
					array4[num9 + 3] = num7 + j;
					array4[num9 + 4] = num7 + (j + 1) % cableSideAmount + cableSideAmount;
					array4[num9 + 5] = num7 + (j + 1) % cableSideAmount;
				}
			}
		}
		mesh.vertices = array;
		mesh.uv = array2;
		mesh.triangles = array4;
		mesh.colors = array3;
		mesh.RecalculateNormals();
		return mesh;
	}
}
public class EnergyGridConnector : SceneBehaviour, IPersistentReference
{
	[SerializeField]
	[FormerlySerializedAs("LinkTransform")]
	[FormerlySerializedAs("_linkTransform")]
	private Transform _connectionTransform;

	[SerializeField]
	[FormerlySerializedAs("LinkCapacity")]
	[FormerlySerializedAs("_linkCapacity")]
	private int _connectionsCapacity = 2;

	[SerializeField]
	private bool _showUnconnectedWarning = true;

	[SerializeField]
	private bool _isTownheart;

	private readonly List<IEnergyGridComponent> _components = new List<IEnergyGridComponent>();

	private readonly List<PlaceableAlertProperties> _malfunctions = new List<PlaceableAlertProperties>();

	private int _connectionsCount;

	public virtual Transform ConnectionTransform => _connectionTransform;

	public int ConnectionsCapacity
	{
		get
		{
			if (Connections == null)
			{
				return 0;
			}
			return _connectionsCapacity;
		}
	}

	public bool IsTownheart => _isTownheart;

	public EnergyGrid EnergyGrid { get; private set; }

	public EnergyGridConnector[] Connections { get; private set; }

	public virtual string Name => "";

	public virtual Sprite IconSprite => null;

	public virtual OutlineRendererComponent OutlineRenderer => null;

	public int PersistentIndex { get; set; } = -1;

	private void Start()
	{
		if (EnergyGrid != null || Connections == null)
		{
			return;
		}
		EnergyGridConnector[] connections = Connections;
		foreach (EnergyGridConnector energyGridConnector in connections)
		{
			if (!(energyGridConnector == null))
			{
				Disconnect(energyGridConnector);
				energyGridConnector.Disconnect(this);
				new EnergyGridConnectionEvent(GameEventType.EnergyGridConnectionRemoved, this, energyGridConnector).Dispatch();
			}
		}
	}

	public void InitializeConnections(int capacity = -1)
	{
		if (capacity < 0)
		{
			capacity = _connectionsCapacity;
		}
		if (Connections == null)
		{
			Connections = new EnergyGridConnector[capacity];
		}
		else if (Connections.Length < capacity)
		{
			EnergyGridConnector[] connections = Connections;
			Connections = new EnergyGridConnector[capacity];
			int i = 0;
			for (int num = connections.Length; i < num; i++)
			{
				Connections[i] = connections[i];
			}
		}
		_connectionsCount = 0;
	}

	public void AddComponent(IEnergyGridComponent component)
	{
		if (_components.AddUnique(component) && EnergyGrid != null)
		{
			component.AddToEnergyGrid(EnergyGrid);
		}
	}

	public void RemoveComponent(IEnergyGridComponent component)
	{
		if (_components.Remove(component) && EnergyGrid != null)
		{
			component.RemoveFromEnergyGrid(EnergyGrid);
		}
	}

	public void PopulateEnergyGridConnections(ref HashSet<EnergyGridConnector> components, ref HashSet<EnergyGridConnector> visited)
	{
		if (!visited.Add(this) || !components.Add(this))
		{
			return;
		}
		EnergyGridConnector[] connections = Connections;
		foreach (EnergyGridConnector energyGridConnector in connections)
		{
			if (energyGridConnector != null)
			{
				energyGridConnector.PopulateEnergyGridConnections(ref components, ref visited);
			}
		}
	}

	public virtual bool Connect(EnergyGridConnector component, uint index)
	{
		if (index < Connections.Length && Connections[index] == null)
		{
			Connections[index] = component;
			_connectionsCount++;
			return true;
		}
		return false;
	}

	public virtual bool Connect(EnergyGridConnector component)
	{
		if (IsConnected(component))
		{
			return false;
		}
		for (int i = 0; i < Connections.Length; i++)
		{
			if (Connections[i] == null)
			{
				Connections[i] = component;
				_connectionsCount++;
				return true;
			}
		}
		return false;
	}

	public virtual bool Disconnect(EnergyGridConnector component)
	{
		for (int i = 0; i < Connections.Length; i++)
		{
			if (Connections[i] == component)
			{
				Connections[i] = null;
				_connectionsCount--;
				return true;
			}
		}
		return false;
	}

	public void SetEnergyGrid(EnergyGrid grid)
	{
		if (!grid.AddConnector(this))
		{
			return;
		}
		EnergyGrid?.RemoveConnector(this);
		EnergyGrid = grid;
		foreach (IEnergyGridComponent component in _components)
		{
			component.AddToEnergyGrid(grid);
		}
		new EnergyGridEvent(GameEventType.EnergyGridsUpdated, grid).Dispatch();
	}

	public void ClearEnergyGrid()
	{
		if (EnergyGrid == null || !EnergyGrid.RemoveConnector(this))
		{
			return;
		}
		foreach (IEnergyGridComponent component in _components)
		{
			component.RemoveFromEnergyGrid(EnergyGrid);
		}
		EnergyGrid = null;
	}

	protected void UpdateConnectionMalfunction()
	{
		if (_showUnconnectedWarning)
		{
			if (HasConnections())
			{
				RemoveMalfunction(GameManager.Settings.BuildableSettings.ErrorNotLinkedToEnergyGridProperties);
			}
			else
			{
				AddMalfunction(GameManager.Settings.BuildableSettings.ErrorNotLinkedToEnergyGridProperties);
			}
		}
	}

	public void AddMalfunction(PlaceableAlertProperties properties)
	{
		if (_malfunctions.AddUnique(properties))
		{
			MalfunctionAdded(properties);
		}
	}

	public void RemoveMalfunction(PlaceableAlertProperties properties)
	{
		_malfunctions.Remove(properties);
		MalfunctionRemoved(properties);
	}

	protected void RemoveAllMalfunctions()
	{
		foreach (PlaceableAlertProperties malfunction in _malfunctions)
		{
			MalfunctionRemoved(malfunction);
		}
		_malfunctions.Clear();
	}

	protected virtual void MalfunctionAdded(PlaceableAlertProperties properties)
	{
	}

	protected virtual void MalfunctionRemoved(PlaceableAlertProperties properties)
	{
	}

	public bool IsInRange(Vector3 position)
	{
		return Vector3.Distance(base.transform.position.Leveled(), position.Leveled()) < GameManager.Settings.BuildableSettings.CableLinkRange;
	}

	public bool HasConnections()
	{
		if (((IReadOnlyCollection<EnergyGridConnector>)(object)Connections).IsNullOrEmpty())
		{
			return false;
		}
		EnergyGridConnector[] connections = Connections;
		for (int i = 0; i < connections.Length; i++)
		{
			if (!(connections[i] == null))
			{
				return true;
			}
		}
		return false;
	}

	public bool IsConnected(EnergyGridConnector component)
	{
		if (((IReadOnlyCollection<EnergyGridConnector>)(object)Connections).IsNullOrEmpty())
		{
			return false;
		}
		EnergyGridConnector[] connections = Connections;
		for (int i = 0; i < connections.Length; i++)
		{
			if (connections[i] == component)
			{
				return true;
			}
		}
		return false;
	}

	public bool CanConnect(uint index)
	{
		if (Connections != null && index < Connections.Length)
		{
			return Connections[index] == null;
		}
		return false;
	}

	public virtual bool CanConnect()
	{
		return _connectionsCount < _connectionsCapacity;
	}

	public bool TryGetConnectedComponent(out EnergyGridConnector connectedComponent, uint index)
	{
		connectedComponent = null;
		if (Connections != null && index < Connections.Length)
		{
			connectedComponent = Connections[index];
		}
		return connectedComponent;
	}

	public void RestoreReferences(IEnergyGridComponentPersistentData persistentData)
	{
		Connections = persistentData.GetEnergyLinks();
		_connectionsCount = 0;
		if (Connections != null)
		{
			InitializeConnections(Connections.Length);
			EnergyGridConnector[] connections = Connections;
			foreach (EnergyGridConnector energyGridConnector in connections)
			{
				if ((bool)energyGridConnector)
				{
					_connectionsCount++;
					if (EnergyGrid != null && energyGridConnector.EnergyGrid != null && energyGridConnector.EnergyGrid != EnergyGrid)
					{
						EnergyGrid.Merge(energyGridConnector.EnergyGrid);
					}
				}
			}
		}
		else
		{
			InitializeConnections();
		}
		UpdateConnectionMalfunction();
	}
}
public class EnergyGridManager : SceneBehaviour
{
	private static readonly List<EnergyGrid> _grids = new List<EnergyGrid>();

	public static IReadOnlyList<EnergyGrid> Grids => _grids;

	private void LateUpdate()
	{
		foreach (EnergyGrid grid in _grids)
		{
			grid.CalculateEfficiency();
		}
	}

	private void OnDestroy()
	{
		_grids.Clear();
	}

	public static EnergyGrid AddGrid()
	{
		EnergyGrid energyGrid = new EnergyGrid();
		_grids.Add(energyGrid);
		new EnergyGridEvent(GameEventType.EnergyGridsUpdated, energyGrid).Dispatch();
		return energyGrid;
	}

	public static void RemoveGrid(EnergyGrid grid)
	{
		_grids.Remove(grid);
		new EnergyGridEvent(GameEventType.EnergyGridsUpdated, grid).Dispatch();
	}

	public static void RestoreReferences()
	{
		List<KeyValuePair<EnergyGridConnector, EnergyGridConnector>> list = new List<KeyValuePair<EnergyGridConnector, EnergyGridConnector>>();
		foreach (EnergyGrid grid in Grids)
		{
			foreach (EnergyGridConnector link in grid.Links)
			{
				EnergyGridConnector[] connections = link.Connections;
				foreach (EnergyGridConnector energyGridConnector in connections)
				{
					if (energyGridConnector != null && !energyGridConnector.Connections.Contains(link))
					{
						list.Add(new KeyValuePair<EnergyGridConnector, EnergyGridConnector>(energyGridConnector, link));
					}
				}
			}
		}
		foreach (KeyValuePair<EnergyGridConnector, EnergyGridConnector> item in list)
		{
			item.Key.Connect(item.Value);
			if (_grids.Contains(item.Value.EnergyGrid))
			{
				item.Key.EnergyGrid.Merge(item.Value.EnergyGrid);
			}
		}
	}
}
