public class QuickConnecting : MonoBehaviour
{
	[SerializeField]
	private EnergyGridConnectCursorProperties _cursorProperties;

	private static readonly List<QuickConnecting> _quickConnectors = new List<QuickConnecting>();

	private GameObject _connectingParticle;

	public EnergyGridConnector Component { get; private set; }

	public static IReadOnlyList<QuickConnecting> QuickConnectors => _quickConnectors;

	private void Awake()
	{
		Component = base.transform.GetComponentInParent<EnergyGridConnector>();
		_connectingParticle = base.transform.GetComponentInChildren<ParticleSystem>().gameObject;
		_quickConnectors.Add(this);
		DisableParticle();
	}

	private void OnDestroy()
	{
		_quickConnectors.Remove(this);
	}

	public void EnableParticle()
	{
		if (Component.CanConnect())
		{
			_connectingParticle.SetActive(value: true);
		}
	}

	public void DisableParticle()
	{
		_connectingParticle.SetActive(value: false);
	}

	public void StartLinking()
	{
		if (Component.CanConnect() && !(GameManager.CursorManager.Properties == _cursorProperties))
		{
			_cursorProperties.Initialize(Component);
			GameManager.CursorManager.Activate(_cursorProperties);
		}
	}
}
public abstract class ActorEvent : GameEvent
{
	private GameEventType _actorEventType;

	public ActorDescriptor ActorDescriptor { get; private set; }

	public ActorEvent(ActorDescriptor actorDescriptor, GameEventType eventType)
		: base(eventType)
	{
		Initialize(actorDescriptor, eventType);
	}

	public virtual void Initialize(ActorDescriptor actorDescriptor, GameEventType eventType)
	{
		base.EventType = eventType;
		ActorDescriptor = actorDescriptor;
		_actorEventType = ToActorEventType(eventType);
	}

	protected override void DispatchEvent()
	{
		base.DispatchEvent();
		if (base.EventType != _actorEventType)
		{
			base.EventType = _actorEventType;
			base.DispatchEvent();
		}
	}

	private GameEventType ToActorEventType(GameEventType eventType)
	{
		return eventType switch
		{
			GameEventType.AgentRescue => GameEventType.ActorRescue, 
			GameEventType.BirdRescue => GameEventType.ActorRescue, 
			GameEventType.AgentDeath => GameEventType.ActorDeath, 
			GameEventType.BirdRemovedFromCommunity => GameEventType.ActorDeath, 
			_ => eventType, 
		};
	}
}
public class AgentEvent : ActorEvent
{
	private static AgentEvent s_instance;

	public Agent Agent { get; protected set; }

	public AgentDescriptor AgentDescriptor { get; private set; }

	public DrifterAttributes.AttributeType Attribute { get; private set; }

	public AssignmentType AssignmentType { get; private set; }

	public ItemProperties ItemProperties { get; protected set; }

	public AgentEvent(GameEventType eventType, Agent agent)
		: base(agent.Descriptor, eventType)
	{
		Agent = agent;
		AgentDescriptor = agent.Descriptor;
	}

	public static void Dispatch(GameEventType eventType, Agent agent)
	{
		GetInstance(eventType, agent).Dispatch();
	}

	public static void Dispatch(GameEventType eventType, AgentDescriptor agentDescriptor)
	{
		GetInstance(eventType, agentDescriptor.Agent, agentDescriptor).Dispatch();
	}

	public static void Dispatch(Agent agent, DrifterAttributes.AttributeType attribute)
	{
		AgentEvent instance = GetInstance(GameEventType.AgentAttributeInfo, agent);
		instance.Attribute = attribute;
		instance.Dispatch();
	}

	public static void Dispatch(Agent agent, AssignmentType assignment)
	{
		AgentEvent instance = GetInstance(GameEventType.AgentAssignmentInfo, agent);
		instance.AssignmentType = assignment;
		instance.Dispatch();
	}

	public static void Dispatch(Agent agent, Assignment assignment)
	{
		AgentEvent instance = GetInstance(GameEventType.AgentAssignmentUpdated, agent);
		instance.AssignmentType = assignment.Type;
		instance.Dispatch();
	}

	public static void Dispatch(Agent agent, ItemProperties itemProperties)
	{
		AgentEvent instance = GetInstance(GameEventType.AgentDietInfo, agent);
		instance.ItemProperties = itemProperties;
		instance.Dispatch();
	}

	private static AgentEvent GetInstance(GameEventType eventType, Agent agent, AgentDescriptor descriptor = null)
	{
		if (s_instance == null)
		{
			s_instance = new AgentEvent(eventType, agent);
		}
		else
		{
			if ((bool)agent)
			{
				s_instance.Initialize(agent.Descriptor, eventType);
			}
			else
			{
				s_instance.Initialize(descriptor, eventType);
			}
			s_instance.Agent = agent;
			s_instance.AgentDescriptor = ((descriptor != null) ? descriptor : ((agent != null) ? agent.Descriptor : null));
			s_instance.Attribute = DrifterAttributes.AttributeType.None;
			s_instance.AssignmentType = AssignmentType.None;
		}
		return s_instance;
	}
}
