public class ExpertiseManager : MonoBehaviour
{
	[SerializeField]
	private ExpertiseProperties _properties;

	private float _researchPointRequirement;

	private float _previousResearchPointThreshold;

	private float _nextResearchPointThreshold;

	public static ExpertiseManager Instance { get; private set; }

	public static float Experience { get; private set; }

	public static int ResearchPoints { get; private set; }

	public static float ResearchPointProgress { get; private set; }

	public void Initialize()
	{
		Instance = this;
		GameEventDispatcher.AddListener(GameEventType.AgentActionRecipeProduced, OnRecipeProduced);
		GameEventDispatcher.AddListener(GameEventType.AgentActionCompositionAdded, OnCompositionAdded);
		GameEventDispatcher.AddListener(GameEventType.AgentActionCompositionRemoved, OnCompositionRemoved);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedSalvagerItem, OnSalvagerItemSalvaged);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedLandmarkItem, OnLandmarkItemSalvaged);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedMarkerItem, OnMarkerItemSalvaged);
		GameEventDispatcher.AddListener(GameEventType.AgentActionItemHauled, OnItemHauled);
		GameEventDispatcher.AddListener(GameEventType.AgentActionResearched, OnResearched);
		GameEventDispatcher.AddListener(GameEventType.AgentActionGeneratedEnergy, OnEnergyGenerated);
		Experience = 0f;
		ResearchPoints = 0;
		_researchPointRequirement = _properties.ReturnCommunityLevelRequirement(ResearchPoints);
		_previousResearchPointThreshold = 0f;
		_nextResearchPointThreshold = _researchPointRequirement;
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionRecipeProduced, OnRecipeProduced);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionCompositionAdded, OnCompositionAdded);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionCompositionRemoved, OnCompositionRemoved);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedSalvagerItem, OnSalvagerItemSalvaged);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedLandmarkItem, OnLandmarkItemSalvaged);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedMarkerItem, OnMarkerItemSalvaged);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionItemHauled, OnItemHauled);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionResearched, OnResearched);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionGeneratedEnergy, OnEnergyGenerated);
	}

	public void IncreaseExperience(Agent agent, float experience, bool applyMoraleEffect = true)
	{
		if (applyMoraleEffect && agent.Morale.TryReturnCurrentCategory(out var category))
		{
			experience *= category.ExperienceMultiplier;
		}
		agent.Attributes.AddTotalExperience(experience, addResearchPoints: false);
		IncreaseCommunityExperience(experience);
	}

	private void IncreaseCommunityExperience(float experience)
	{
		Experience += experience;
		int num = 0;
		while (_nextResearchPointThreshold < Experience)
		{
			ResearchPoints++;
			num++;
			_researchPointRequirement = _properties.ReturnCommunityLevelRequirement(ResearchPoints);
			_previousResearchPointThreshold = _nextResearchPointThreshold;
			_nextResearchPointThreshold = _previousResearchPointThreshold + _researchPointRequirement;
		}
		if (0 < num)
		{
			Community.PlayerCommunity.Research.AddResearchPoints(num);
		}
		ResearchPointProgress = (Experience - _previousResearchPointThreshold) / _researchPointRequirement;
		GameEventDispatcher.Dispatch(GameEventType.CommunityExperienceUpdated);
	}

	private void OnRecipeProduced(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionRecipeEvent agentActionRecipeEvent)
		{
			IncreaseExperience(agentActionRecipeEvent.Agent, _properties.ReturnProductionExperience(agentActionRecipeEvent.Recipe, agentActionRecipeEvent.AttributeType));
		}
	}

	private void OnCompositionAdded(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent)
		{
			IncreaseExperience(agentActionItemPropertiesEvent.Agent, _properties.ConstructionExperience);
		}
	}

	private void OnCompositionRemoved(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent)
		{
			IncreaseExperience(agentActionItemPropertiesEvent.Agent, _properties.ConstructionExperience);
		}
	}

	private void OnSalvagerItemSalvaged(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent)
		{
			float num = 0f;
			IncreaseExperience(experience: agentActionItemPropertiesEvent.AttributeType switch
			{
				DrifterAttributes.AttributeType.Fishing => _properties.ReturnFishingExperience(agentActionItemPropertiesEvent.ItemProperties, isFishingFromBoat: false), 
				DrifterAttributes.AttributeType.Salvaging => _properties.SalvageExperience, 
				_ => throw new NotImplementedException(), 
			}, agent: agentActionItemPropertiesEvent.Agent);
		}
	}

	private void OnMarkerItemSalvaged(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent { AttributeType: var attributeType } agentActionItemPropertiesEvent)
		{
			IncreaseExperience(experience: attributeType switch
			{
				DrifterAttributes.AttributeType.Fishing => _properties.ReturnFishingExperience(agentActionItemPropertiesEvent.ItemProperties, isFishingFromBoat: true), 
				DrifterAttributes.AttributeType.Salvaging => _properties.SalvageExperience, 
				_ => throw new NotImplementedException(), 
			}, agent: agentActionItemPropertiesEvent.Agent);
		}
	}

	private void OnLandmarkItemSalvaged(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent)
		{
			IncreaseExperience(agentActionItemPropertiesEvent.Agent, _properties.SalvageExperience);
		}
	}

	private void OnItemHauled(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent)
		{
			IncreaseExperience(agentActionItemPropertiesEvent.Agent, _properties.HaulExperience);
		}
	}

	private void OnResearched(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionEvent agentActionEvent)
		{
			IncreaseExperience(agentActionEvent.Agent, _properties.ResearchExperience);
		}
	}

	private void OnEnergyGenerated(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionEvent agentActionEvent)
		{
			IncreaseExperience(agentActionEvent.Agent, _properties.EnergyGeneratedExperience);
		}
	}

	public static float ReturnDrifterLevelRequirement(int level)
	{
		if (Instance == null)
		{
			return 0f;
		}
		return Instance._properties.ReturnDrifterLevelRequirement(level);
	}
}
[CreateAssetMenu(menuName = "Flotsam/Expertise/Properties")]
public class ExpertiseProperties : ScriptableObject
{
	public enum Mode
	{
		PerSecond,
		PerItem
	}

	[Serializable]
	public struct FishExperience
	{
		public ItemProperties Fish;

		public float Experience;
	}

	[SerializeField]
	private int _maximumLevel = 15;

	[Header("Experience Requirements")]
	[SerializeField]
	private float _communityBaseExperienceRequirement = 300f;

	[SerializeField]
	private float _communityPerLevelExperienceRequirement = 100f;

	[SerializeField]
	private float _drifterBaseExperienceRequirement = 300f;

	[SerializeField]
	private float _drifterPerLevelExperienceRequirement = 100f;

	[Header("Salvaging")]
	[SerializeField]
	[Tooltip("Per item salvaged.")]
	private float _salvageExperience = 10f;

	[Header("Fishing")]
	[SerializeField]
	private List<FishExperience> _fishingChairExperiences = new List<FishExperience>();

	[SerializeField]
	private List<FishExperience> _fishingBoatExperiences = new List<FishExperience>();

	[Header("Construction")]
	[SerializeField]
	[Tooltip("Per item built / salvaged of a construction.")]
	private float _constructionExperience = 10f;

	[Header("Hauling")]
	[SerializeField]
	[Tooltip("Per item put in / taken out of an inventory.")]
	private float _haulExperience = 10f;

	[Header("Production")]
	[SerializeField]
	private Mode _productionExperienceMode;

	[SerializeField]
	[Tooltip("Per second worked")]
	[ConditionalEnumHide("_productionExperienceMode", 0, false, HideInInspector = true)]
	private float _productionExperiencePerSecond = 10f;

	[SerializeField]
	[Tooltip("Per recipe produced.")]
	[ConditionalEnumHide("_productionExperienceMode", 1, false, HideInInspector = true)]
	private float _recycleExperience = 10f;

	[SerializeField]
	[Tooltip("Per recipe produced.")]
	[ConditionalEnumHide("_productionExperienceMode", 1, false, HideInInspector = true)]
	private float _cookingExperience = 10f;

	[SerializeField]
	[Tooltip("Per recipe produced.")]
	[ConditionalEnumHide("_productionExperienceMode", 1, false, HideInInspector = true)]
	private float _liquidsExperience = 10f;

	[Header("Research")]
	[SerializeField]
	[Tooltip("Per research unlocked.")]
	private float _researchExperience = 10f;

	[Header("Energy")]
	[SerializeField]
	[Tooltip("Per second energy generated.")]
	private float _energyGeneratedExperience = 0.1f;

	public int MaximumLevel => _maximumLevel;

	public float CommunityBaseExperienceRequirement => _communityBaseExperienceRequirement;

	public float CommunityPerLevelExperienceRequirement => _communityPerLevelExperienceRequirement;

	public float DrifterBaseExperienceRequirement => _drifterBaseExperienceRequirement;

	public float DrifterPerLevelExperienceRequirement => _drifterPerLevelExperienceRequirement;

	public float SalvageExperience => _salvageExperience;

	public float ConstructionExperience => _constructionExperience;

	public float HaulExperience => _haulExperience;

	public float ResearchExperience => _researchExperience;

	public float EnergyGeneratedExperience => _energyGeneratedExperience;

	public float ReturnCommunityLevelRequirement(int level)
	{
		return CommunityBaseExperienceRequirement + CommunityPerLevelExperienceRequirement * (float)level;
	}

	public float ReturnDrifterLevelRequirement(int level)
	{
		return DrifterBaseExperienceRequirement + DrifterPerLevelExperienceRequirement * (float)level;
	}

	public float ReturnFishingExperience(ItemProperties fish, bool isFishingFromBoat)
	{
		if ((isFishingFromBoat ? _fishingBoatExperiences : _fishingChairExperiences).TryFind(out var foundItem, (FishExperience item) => item.Fish == fish))
		{
			return foundItem.Experience;
		}
		UnityEngine.Debug.LogException(new NotImplementedException("Fish of type \"" + fish.name + "\" is not present in Fishing " + (isFishingFromBoat ? "Boat" : "Chair") + " experience table and therefore cannot award experience!"));
		return 0f;
	}

	public float ReturnProductionExperience(ProductionRecipeProperties recipe, DrifterAttributes.AttributeType attribute)
	{
		return _productionExperienceMode switch
		{
			Mode.PerSecond => recipe.ProductionTime * _productionExperiencePerSecond + recipe.ProductionExperience, 
			Mode.PerItem => ReturnAttributeExperience(attribute), 
			_ => throw new NotImplementedException(), 
		};
	}

	private float ReturnAttributeExperience(DrifterAttributes.AttributeType attribute)
	{
		return attribute switch
		{
			DrifterAttributes.AttributeType.Recycling => _recycleExperience, 
			DrifterAttributes.AttributeType.Cooking => _cookingExperience, 
			DrifterAttributes.AttributeType.Liquids => _liquidsExperience, 
			_ => throw new NotImplementedException(), 
		};
	}
}
public class TypewriterAudio : MonoBehaviour
{
	[Serializable]
	private struct CharacterEvent
	{
		public string Characters;

		public EventReference Event;

		public bool Play(char character)
		{
			if (Characters.Contains(character))
			{
				AudioManager.PlayOneShot(Event);
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	private TypewriterCore _typewriter;

	[Header("FMOD Events")]
	[SerializeField]
	private EventReference _defaultEvent;

	[SerializeField]
	private CharacterEvent[] _characterEvents;

	[SerializeField]
	private string _noEventCharacters;

	private void Awake()
	{
		if (_typewriter == null)
		{
			_typewriter = base.gameObject.GetComponentInChildren<TypewriterCore>(includeInactive: true);
		}
	}

	private void OnEnable()
	{
		_typewriter.onCharacterVisible.AddListener(OnCharactVisible);
	}

	private void OnDisable()
	{
		_typewriter.onCharacterVisible.RemoveListener(OnCharactVisible);
	}

	private void OnCharactVisible(char character)
	{
		if (_noEventCharacters.Contains(character))
		{
			return;
		}
		CharacterEvent[] characterEvents = _characterEvents;
		foreach (CharacterEvent characterEvent in characterEvents)
		{
			if (characterEvent.Play(character))
			{
				return;
			}
		}
		AudioManager.PlayOneShot(_defaultEvent);
	}
}
public class Math3d
{
	private static Transform tempChild;

	private static Transform tempParent;

	private static Vector3[] positionRegister;

	private static float[] posTimeRegister;

	private static int positionSamplesTaken;

	private static Quaternion[] rotationRegister;

	private static float[] rotTimeRegister;

	private static int rotationSamplesTaken;

	public static void Init()
	{
		tempChild = new GameObject("Math3d_TempChild").transform;
		tempParent = new GameObject("Math3d_TempParent").transform;
		tempChild.gameObject.hideFlags = HideFlags.HideAndDontSave;
		UnityEngine.Object.DontDestroyOnLoad(tempChild.gameObject);
		tempParent.gameObject.hideFlags = HideFlags.HideAndDontSave;
		UnityEngine.Object.DontDestroyOnLoad(tempParent.gameObject);
		tempChild.parent = tempParent;
	}

	public static Vector3 AddVectorLength(Vector3 vector, float size)
	{
		float num = Vector3.Magnitude(vector);
		float num2 = (num + size) / num;
		return vector * num2;
	}

	public static Vector3 SetVectorLength(Vector3 vector, float size)
	{
		return Vector3.Normalize(vector) * size;
	}

	public static Quaternion FlattenQuaternion(Quaternion a)
	{
		return Quaternion.Euler(0f, a.eulerAngles.y, 0f);
	}

	public static Quaternion SubtractRotation(Quaternion B, Quaternion A)
	{
		return Quaternion.Inverse(A) * B;
	}

	public static Quaternion AddRotation(Quaternion A, Quaternion B)
	{
		return A * B;
	}

	public static Vector3 TransformDirectionMath(Quaternion rotation, Vector3 vector)
	{
		return rotation * vector;
	}

	public static Vector3 InverseTransformDirectionMath(Quaternion rotation, Vector3 vector)
	{
		return Quaternion.Inverse(rotation) * vector;
	}

	public static Vector3 RotateVectorFromTo(Quaternion from, Quaternion to, Vector3 vector)
	{
		Quaternion quaternion = SubtractRotation(to, from);
		Vector3 vector2 = InverseTransformDirectionMath(from, vector);
		Vector3 vector3 = quaternion * vector2;
		return TransformDirectionMath(from, vector3);
	}

	public static bool PlanePlaneIntersection(out Vector3 linePoint, out Vector3 lineVec, Vector3 plane1Normal, Vector3 plane1Position, Vector3 plane2Normal, Vector3 plane2Position)
	{
		linePoint = Vector3.zero;
		lineVec = Vector3.zero;
		lineVec = Vector3.Cross(plane1Normal, plane2Normal);
		Vector3 vector = Vector3.Cross(plane2Normal, lineVec);
		float num = Vector3.Dot(plane1Normal, vector);
		if (Mathf.Abs(num) > 0.006f)
		{
			Vector3 rhs = plane1Position - plane2Position;
			float num2 = Vector3.Dot(plane1Normal, rhs) / num;
			linePoint = plane2Position + num2 * vector;
			return true;
		}
		return false;
	}

	public static bool LinePlaneIntersection(out Vector3 intersection, Vector3 linePoint, Vector3 lineVec, Vector3 planeNormal, Vector3 planePoint)
	{
		intersection = Vector3.zero;
		float num = Vector3.Dot(planePoint - linePoint, planeNormal);
		float num2 = Vector3.Dot(lineVec, planeNormal);
		if (num2 != 0f)
		{
			float size = num / num2;
			Vector3 vector = SetVectorLength(lineVec, size);
			intersection = linePoint + vector;
			return true;
		}
		return false;
	}

	public static bool LineLineIntersection(out Vector3 intersection, Vector3 linePoint1, Vector3 lineVec1, Vector3 linePoint2, Vector3 lineVec2)
	{
		intersection = Vector3.zero;
		Vector3 lhs = linePoint2 - linePoint1;
		Vector3 rhs = Vector3.Cross(lineVec1, lineVec2);
		Vector3 lhs2 = Vector3.Cross(lhs, lineVec2);
		float num = Vector3.Dot(lhs, rhs);
		if (num >= 1E-05f || num <= -1E-05f)
		{
			return false;
		}
		float num2 = Vector3.Dot(lhs2, rhs) / rhs.sqrMagnitude;
		if (num2 >= 0f && num2 <= 1f)
		{
			intersection = linePoint1 + lineVec1 * num2;
			return true;
		}
		return false;
	}

	public static bool ClosestPointsOnTwoLines(out Vector3 closestPointLine1, out Vector3 closestPointLine2, Vector3 linePoint1, Vector3 lineVec1, Vector3 linePoint2, Vector3 lineVec2)
	{
		closestPointLine1 = Vector3.zero;
		closestPointLine2 = Vector3.zero;
		float num = Vector3.Dot(lineVec1, lineVec1);
		float num2 = Vector3.Dot(lineVec1, lineVec2);
		float num3 = Vector3.Dot(lineVec2, lineVec2);
		float num4 = num * num3 - num2 * num2;
		if (num4 != 0f)
		{
			Vector3 rhs = linePoint1 - linePoint2;
			float num5 = Vector3.Dot(lineVec1, rhs);
			float num6 = Vector3.Dot(lineVec2, rhs);
			float num7 = (num2 * num6 - num5 * num3) / num4;
			float num8 = (num * num6 - num5 * num2) / num4;
			closestPointLine1 = linePoint1 + lineVec1 * num7;
			closestPointLine2 = linePoint2 + lineVec2 * num8;
			return true;
		}
		return false;
	}

	public static Vector3 ProjectPointOnLine(Vector3 linePoint, Vector3 lineVec, Vector3 point)
	{
		float num = Vector3.Dot(point - linePoint, lineVec);
		return linePoint + lineVec * num;
	}

	public static Vector3 ProjectPointOnLineSegment(Vector3 linePoint1, Vector3 linePoint2, Vector3 point)
	{
		Vector3 vector = ProjectPointOnLine(linePoint1, (linePoint2 - linePoint1).normalized, point);
		return PointOnWhichSideOfLineSegment(linePoint1, linePoint2, vector) switch
		{
			0 => vector, 
			1 => linePoint1, 
			2 => linePoint2, 
			_ => Vector3.zero, 
		};
	}

	public static bool TryProjectPointOnLineSegment(out Vector3 projectedPoint, Vector3 linePoint1, Vector3 linePoint2, Vector3 point)
	{
		projectedPoint = ProjectPointOnLine(linePoint1, (linePoint2 - linePoint1).normalized, point);
		return PointOnWhichSideOfLineSegment(linePoint1, linePoint2, projectedPoint) == 0;
	}

	public static Vector3 ProjectPointOnPlane(Vector3 planeNormal, Vector3 planePoint, Vector3 point)
	{
		float num = SignedDistancePlanePoint(planeNormal, planePoint, point);
		num *= -1f;
		Vector3 vector = SetVectorLength(planeNormal, num);
		return point + vector;
	}

	public static Vector3 ProjectVectorOnPlane(Vector3 planeNormal, Vector3 vector)
	{
		return vector - Vector3.Dot(vector, planeNormal) * planeNormal;
	}

	public static float SignedDistancePlanePoint(Vector3 planeNormal, Vector3 planePoint, Vector3 point)
	{
		return Vector3.Dot(planeNormal, point - planePoint);
	}

	public static float SignedDotProduct(Vector3 vectorA, Vector3 vectorB, Vector3 normal)
	{
		return Vector3.Dot(Vector3.Cross(normal, vectorA), vectorB);
	}

	public static float SignedVectorAngle(Vector3 referenceVector, Vector3 otherVector, Vector3 normal)
	{
		Vector3 lhs = Vector3.Cross(normal, referenceVector);
		return Vector3.Angle(referenceVector, otherVector) * Mathf.Sign(Vector3.Dot(lhs, otherVector));
	}

	public static float AngleVectorPlane(Vector3 vector, Vector3 normal)
	{
		float num = (float)System.Math.Acos(Vector3.Dot(vector, normal));
		return MathF.PI / 2f - num;
	}

	public static float DotProductAngle(Vector3 vec1, Vector3 vec2)
	{
		double num = Vector3.Dot(vec1, vec2);
		if (num < -1.0)
		{
			num = -1.0;
		}
		if (num > 1.0)
		{
			num = 1.0;
		}
		return (float)System.Math.Acos(num);
	}

	public static void PlaneFrom3Points(out Vector3 planeNormal, out Vector3 planePoint, Vector3 pointA, Vector3 pointB, Vector3 pointC)
	{
		planeNormal = Vector3.zero;
		planePoint = Vector3.zero;
		Vector3 vector = pointB - pointA;
		Vector3 vector2 = pointC - pointA;
		planeNormal = Vector3.Normalize(Vector3.Cross(vector, vector2));
		Vector3 vector3 = pointA + vector / 2f;
		Vector3 vector4 = pointA + vector2 / 2f;
		Vector3 lineVec = pointC - vector3;
		Vector3 lineVec2 = pointB - vector4;
		ClosestPointsOnTwoLines(out planePoint, out var _, vector3, lineVec, vector4, lineVec2);
	}

	public static Vector3 GetForwardVector(Quaternion q)
	{
		return q * Vector3.forward;
	}

	public static Vector3 GetUpVector(Quaternion q)
	{
		return q * Vector3.up;
	}

	public static Vector3 GetRightVector(Quaternion q)
	{
		return q * Vector3.right;
	}

	public static Quaternion QuaternionFromMatrix(Matrix4x4 m)
	{
		return Quaternion.LookRotation((Vector3)m.GetColumn(2), (Vector3)m.GetColumn(1));
	}

	public static Vector3 PositionFromMatrix(Matrix4x4 m)
	{
		Vector4 column = m.GetColumn(3);
		return new Vector3(column.x, column.y, column.z);
	}

	public static void LookRotationExtended(ref GameObject gameObjectInOut, Vector3 alignWithVector, Vector3 alignWithNormal, Vector3 customForward, Vector3 customUp)
	{
		Quaternion quaternion = Quaternion.LookRotation(alignWithVector, alignWithNormal);
		Quaternion rotation = Quaternion.LookRotation(customForward, customUp);
		gameObjectInOut.transform.rotation = quaternion * Quaternion.Inverse(rotation);
	}

	public static void TransformWithParent(out Quaternion childRotation, out Vector3 childPosition, Quaternion parentRotation, Vector3 parentPosition, Quaternion startParentRotation, Vector3 startParentPosition, Quaternion startChildRotation, Vector3 startChildPosition)
	{
		childRotation = Quaternion.identity;
		childPosition = Vector3.zero;
		tempParent.rotation = startParentRotation;
		tempParent.position = startParentPosition;
		tempParent.localScale = Vector3.one;
		tempChild.rotation = startChildRotation;
		tempChild.position = startChildPosition;
		tempChild.localScale = Vector3.one;
		tempParent.rotation = parentRotation;
		tempParent.position = parentPosition;
		childRotation = tempChild.rotation;
		childPosition = tempChild.position;
	}

	public static void PreciseAlign(ref GameObject gameObjectInOut, Vector3 alignWithVector, Vector3 alignWithNormal, Vector3 alignWithPosition, Vector3 triangleForward, Vector3 triangleNormal, Vector3 trianglePosition)
	{
		LookRotationExtended(ref gameObjectInOut, alignWithVector, alignWithNormal, triangleForward, triangleNormal);
		Vector3 vector = gameObjectInOut.transform.TransformPoint(trianglePosition);
		Vector3 translation = alignWithPosition - vector;
		gameObjectInOut.transform.Translate(translation, Space.World);
	}

	public static void VectorsToTransform(ref GameObject gameObjectInOut, Vector3 positionVector, Vector3 directionVector, Vector3 normalVector)
	{
		gameObjectInOut.transform.position = positionVector;
		gameObjectInOut.transform.rotation = Quaternion.LookRotation(directionVector, normalVector);
	}

	public static int PointOnWhichSideOfLineSegment(Vector3 linePoint1, Vector3 linePoint2, Vector3 point)
	{
		Vector3 rhs = linePoint2 - linePoint1;
		Vector3 lhs = point - linePoint1;
		float num = Vector3.Dot(lhs, rhs);
		if (Mathf.Approximately(num, 0f))
		{
			return 0;
		}
		if (num > 0f)
		{
			if (lhs.magnitude <= rhs.magnitude)
			{
				return 0;
			}
			return 2;
		}
		return 1;
	}

	public static float MouseDistanceToLine(Vector3 linePoint1, Vector3 linePoint2)
	{
		Camera main = Camera.main;
		Vector3 mousePosition = UnityEngine.Input.mousePosition;
		Vector3 linePoint3 = main.WorldToScreenPoint(linePoint1);
		Vector3 linePoint4 = main.WorldToScreenPoint(linePoint2);
		Vector3 vector = ProjectPointOnLineSegment(linePoint3, linePoint4, mousePosition);
		vector = new Vector3(vector.x, vector.y, 0f);
		return (vector - mousePosition).magnitude;
	}

	public static float MouseDistanceToCircle(Vector3 point, float radius)
	{
		Camera main = Camera.main;
		Vector3 mousePosition = UnityEngine.Input.mousePosition;
		Vector3 vector = main.WorldToScreenPoint(point);
		vector = new Vector3(vector.x, vector.y, 0f);
		return (vector - mousePosition).magnitude - radius;
	}

	public static bool IsLineInRectangle(Vector3 linePoint1, Vector3 linePoint2, Vector3 rectA, Vector3 rectB, Vector3 rectC, Vector3 rectD)
	{
		bool flag = false;
		bool num = IsPointInRectangle(linePoint1, rectA, rectC, rectB, rectD);
		if (!num)
		{
			flag = IsPointInRectangle(linePoint2, rectA, rectC, rectB, rectD);
		}
		if (!num && !flag)
		{
			bool num2 = AreLineSegmentsCrossing(linePoint1, linePoint2, rectA, rectB);
			bool flag2 = AreLineSegmentsCrossing(linePoint1, linePoint2, rectB, rectC);
			bool flag3 = AreLineSegmentsCrossing(linePoint1, linePoint2, rectC, rectD);
			bool flag4 = AreLineSegmentsCrossing(linePoint1, linePoint2, rectD, rectA);
			if (num2 || flag2 || flag3 || flag4)
			{
				return true;
			}
			return false;
		}
		return true;
	}

	public static bool IsPointInRectangle(Vector3 point, Vector3 rectA, Vector3 rectC, Vector3 rectB, Vector3 rectD)
	{
		Vector3 vector = rectC - rectA;
		float size = 0f - vector.magnitude / 2f;
		vector = AddVectorLength(vector, size);
		Vector3 linePoint = rectA + vector;
		Vector3 vector2 = rectB - rectA;
		float num = vector2.magnitude / 2f;
		Vector3 vector3 = rectD - rectA;
		float num2 = vector3.magnitude / 2f;
		float magnitude = (ProjectPointOnLine(linePoint, vector2.normalized, point) - point).magnitude;
		if ((ProjectPointOnLine(linePoint, vector3.normalized, point) - point).magnitude <= num && magnitude <= num2)
		{
			return true;
		}
		return false;
	}

	public static bool AreLineSegmentsCrossing(Vector3 pointA1, Vector3 pointA2, Vector3 pointB1, Vector3 pointB2)
	{
		Vector3 vector = pointA2 - pointA1;
		Vector3 vector2 = pointB2 - pointB1;
		if (ClosestPointsOnTwoLines(out var closestPointLine, out var closestPointLine2, pointA1, vector.normalized, pointB1, vector2.normalized))
		{
			int num = PointOnWhichSideOfLineSegment(pointA1, pointA2, closestPointLine);
			int num2 = PointOnWhichSideOfLineSegment(pointB1, pointB2, closestPointLine2);
			if (num == 0 && num2 == 0)
			{
				return true;
			}
			return false;
		}
		return false;
	}

	public static bool LinearAcceleration(out Vector3 vector, Vector3 position, int samples)
	{
		Vector3 zero = Vector3.zero;
		vector = Vector3.zero;
		if (samples < 3)
		{
			samples = 3;
		}
		if (positionRegister == null)
		{
			positionRegister = new Vector3[samples];
			posTimeRegister = new float[samples];
		}
		for (int i = 0; i < positionRegister.Length - 1; i++)
		{
			positionRegister[i] = positionRegister[i + 1];
			posTimeRegister[i] = posTimeRegister[i + 1];
		}
		positionRegister[positionRegister.Length - 1] = position;
		posTimeRegister[posTimeRegister.Length - 1] = Time.time;
		positionSamplesTaken++;
		if (positionSamplesTaken >= samples)
		{
			for (int j = 0; j < positionRegister.Length - 2; j++)
			{
				Vector3 vector2 = positionRegister[j + 1] - positionRegister[j];
				float num = posTimeRegister[j + 1] - posTimeRegister[j];
				if (num == 0f)
				{
					return false;
				}
				Vector3 vector3 = vector2 / num;
				vector2 = positionRegister[j + 2] - positionRegister[j + 1];
				num = posTimeRegister[j + 2] - posTimeRegister[j + 1];
				if (num == 0f)
				{
					return false;
				}
				Vector3 vector4 = vector2 / num;
				zero += vector4 - vector3;
			}
			zero /= (float)(positionRegister.Length - 2);
			float num2 = posTimeRegister[posTimeRegister.Length - 1] - posTimeRegister[0];
			vector = zero / num2;
			return true;
		}
		return false;
	}

	public static bool AngularAcceleration(out Vector3 vector, Quaternion rotation, int samples)
	{
		Vector3 zero = Vector3.zero;
		vector = Vector3.zero;
		if (samples < 3)
		{
			samples = 3;
		}
		if (rotationRegister == null)
		{
			rotationRegister = new Quaternion[samples];
			rotTimeRegister = new float[samples];
		}
		for (int i = 0; i < rotationRegister.Length - 1; i++)
		{
			rotationRegister[i] = rotationRegister[i + 1];
			rotTimeRegister[i] = rotTimeRegister[i + 1];
		}
		rotationRegister[rotationRegister.Length - 1] = rotation;
		rotTimeRegister[rotTimeRegister.Length - 1] = Time.time;
		rotationSamplesTaken++;
		if (rotationSamplesTaken >= samples)
		{
			for (int j = 0; j < rotationRegister.Length - 2; j++)
			{
				Quaternion rotation2 = SubtractRotation(rotationRegister[j + 1], rotationRegister[j]);
				float num = rotTimeRegister[j + 1] - rotTimeRegister[j];
				if (num == 0f)
				{
					return false;
				}
				Vector3 vector2 = RotDiffToSpeedVec(rotation2, num);
				rotation2 = SubtractRotation(rotationRegister[j + 2], rotationRegister[j + 1]);
				num = rotTimeRegister[j + 2] - rotTimeRegister[j + 1];
				if (num == 0f)
				{
					return false;
				}
				Vector3 vector3 = RotDiffToSpeedVec(rotation2, num);
				zero += vector3 - vector2;
			}
			zero /= (float)(rotationRegister.Length - 2);
			float num2 = rotTimeRegister[rotTimeRegister.Length - 1] - rotTimeRegister[0];
			vector = zero / num2;
			return true;
		}
		return false;
	}

	public static float LinearFunction2DBasic(float x, float Qx, float Qy)
	{
		return x * (Qy / Qx);
	}

	public static float LinearFunction2DFull(float x, float Px, float Py, float Qx, float Qy)
	{
		float num = Qy - Py;
		float num2 = Qx - Px;
		float num3 = num / num2;
		return Py + num3 * (x - Px);
	}

	private static Vector3 RotDiffToSpeedVec(Quaternion rotation, float deltaTime)
	{
		float num = ((!(rotation.eulerAngles.x <= 180f)) ? (rotation.eulerAngles.x - 360f) : rotation.eulerAngles.x);
		float num2 = ((!(rotation.eulerAngles.y <= 180f)) ? (rotation.eulerAngles.y - 360f) : rotation.eulerAngles.y);
		return new Vector3(z: ((!(rotation.eulerAngles.z <= 180f)) ? (rotation.eulerAngles.z - 360f) : rotation.eulerAngles.z) / deltaTime, x: num / deltaTime, y: num2 / deltaTime);
	}
}
public abstract class AchievementBase : ScriptableObject, IPanelContext
{
	[SerializeField]
	private AchievementId _id;

	[SerializeField]
	private LocalizedString _name;

	[SerializeField]
	private LocalizedString _description;

	[SerializeField]
	private Sprite _icon;

	[SerializeField]
	private Sprite _iconLocked;

	public PlayerProfile PlayerProfile { get; private set; }

	public AchievementId Id => _id;

	public AchievementProgress Progress { get; protected set; }

	public virtual bool ItIsAchieved { get; protected set; }

	public LocalizedString Name => _name;

	public LocalizedString Description => _description;

	public Sprite Icon => _icon;

	protected virtual AchievementId DefaultId => AchievementId.None;

	public PanelID PanelID => PanelID.Achievement;

	public void Initialize(PlayerProfile player)
	{
		PlayerProfile = player;
		ItIsAchieved = PlayerProfile.IsAchievementUnlocked(this);
		if (!ItIsAchieved)
		{
			Initialize();
		}
	}

	protected abstract void Initialize();

	public abstract void Uninitialize();

	public virtual void UnlockAchievement(PlayerProfile playerProfile)
	{
	}

	protected bool UnlockAchievement()
	{
		if (ItIsAchieved || !UnlockAchievementSpecific())
		{
			return false;
		}
		PlayerProfile.UnlockAchievement(this);
		ItIsAchieved = true;
		return true;
	}

	protected virtual bool UnlockAchievementSpecific()
	{
		return true;
	}
}
