public enum FileSystemActionResult
{
	Succes,
	Failed
}
public interface IPlatformPausable
{
	bool ItBlocksPlatformUnpause { get; }

	bool ItBlocksUnpause { get; }
}
public class StorageActionResult
{
	public string Filename { get; private set; }

	public bool Succes { get; private set; }

	public byte[] Data { get; private set; }

	public StorageActionResult(string filename, bool succes, byte[] data = null)
	{
		Filename = filename;
		Succes = succes;
		Data = data;
	}

	public string GetDataAsNoneEncodedString()
	{
