			return false;
		default:
			return false;
		}
	}

	private Vector2 GetMousePosition()
	{
		Vector2 axis2DRaw = _player.GetAxis2DRaw(85, 86);
		switch (_mode)
		{
		case Mode.Mapped:
			_mousePosition = GetMousePosition(axis2DRaw);
			break;
		case Mode.Cumulative:
		{
			float num = Time.unscaledDeltaTime * _speed;
			_mousePosition.x = Mathf.Clamp(_mousePosition.x + axis2DRaw.x * num, 0f, Screen.width);
			_mousePosition.y = Mathf.Clamp(_mousePosition.y + axis2DRaw.y * num, 0f, Screen.height);
			break;
		}
		}
		return _mousePosition;
	}

	private void TryUpdate()
	{
		if (Time.frameCount != _lastUpdatedFrame)
		{
			_lastUpdatedFrame = Time.frameCount;
			if (_player.GetButtonUp(91))
			{
				_enabled = !_enabled;
			}
			if (_enabled)
			{
				_mousePositionPrevious = _mousePosition;
				_mousePosition = GetMousePosition();
			}
		}
	}

	public static Vector2 GetMousePosition(Vector2 axis2D)
	{
		bool flag = Mathf.Approximately(0f, axis2D.x);
		bool flag2 = Mathf.Approximately(0f, axis2D.y);
		Vector2 vector;
		if (flag && flag2)
		{
			vector = Vector2.zero;
		}
		else if (flag)
		{
			vector = new Vector2(0f, axis2D.y);
		}
		else if (flag2)
		{
			vector = new Vector2(axis2D.x, 0f);
		}
		else
		{
			Vector2 vector2 = new Vector2(Mathf.Abs(axis2D.x), Mathf.Abs(axis2D.y));
			float num = Mathf.Clamp01(axis2D.magnitude);
			float num2 = ((!(vector2.y < vector2.x)) ? (num / vector2.y) : (num / vector2.x));
			vector = axis2D * num2;
		}
		vector += Vector2.one;
		vector /= 2f;
		float num3 = Screen.width;
		float num4 = Screen.height;
		return new Vector2(Mathf.Clamp(num3 * vector.x, 0f, num3), Mathf.Clamp(num4 * vector.y, 0f, num4));
	}
}
public class RewiredStandaloneInputModuleMap : MonoBehaviour
{
	[SerializeField]
	private RewiredStandaloneInputModule _inputModule;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _horizontalActionId;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _verticalActionId;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _horizontalRestrictedActionId;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _verticalRestrictedActionId;

	private void Awake()
	{
		GameEventDispatcher.AddListener(GameEventType.GameStartedLoading, OnGameStartedLoading);
		if (LoadingScreen.IsLoading)
		{
			GameEventDispatcher.AddListener(GameEventType.GameStart, OnGameStart);
		}
		else
		{
			OnGameStart();
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStartedLoading, OnGameStartedLoading);
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnGameStart);
		GameEventDispatcher.RemoveListener(GameEventType.UIFlagsUpdated, OnUIFlagsUpdated);
	}

	public void Restrict()
	{
		_inputModule.HorizontalActionId = _horizontalRestrictedActionId;
		_inputModule.VerticalActionId = _verticalRestrictedActionId;
	}

	public void Unrestrict()
	{
		_inputModule.HorizontalActionId = _horizontalActionId;
		_inputModule.VerticalActionId = _verticalActionId;
	}

	private void OnGameStartedLoading(GameEvent gameEvent)
	{
		Unrestrict();
		FinalUpdate.RegisterOneShot(delegate
		{
			GameEventDispatcher.AddListener(GameEventType.GameStartedLoading, OnGameStartedLoading);
			GameEventDispatcher.AddListener(GameEventType.GameStart, OnGameStart);
		});
	}

	private void OnGameStart(GameEvent gameEvent = null)
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnGameStart);
		GameEventDispatcher.AddListener(GameEventType.UIFlagsUpdated, OnUIFlagsUpdated);
		OnUIFlagsUpdated();
	}

	private void OnUIFlagsUpdated(GameEvent gameEvent = null)
	{
		if (UIManager.HasFlagsSet(PanelContainerFlags.RestrictUINavigation))
		{
			Restrict();
		}
		else
		{
			Unrestrict();
		}
	}
}
[DisallowMultipleComponent]
public class SteamManager : MonoBehaviour
{
	protected static bool s_EverInitialized;

	protected static SteamManager s_instance;

	protected bool m_bInitialized;

	protected SteamAPIWarningMessageHook_t m_SteamAPIWarningMessageHook;

	private PlatformSteam m_Platform;

	protected static SteamManager Instance
	{
		get
		{
			if (s_instance == null)
			{
				return new GameObject("SteamManager").AddComponent<SteamManager>();
			}
			return s_instance;
		}
	}

	public static bool Initialized => Instance.m_bInitialized;

	[MonoPInvokeCallback(typeof(SteamAPIWarningMessageHook_t))]
	protected static void SteamAPIDebugTextHook(int nSeverity, StringBuilder pchDebugText)
	{
		UnityEngine.Debug.LogWarning(pchDebugText);
	}

	[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
	private static void InitOnPlayMode()
	{
		s_EverInitialized = false;
		s_instance = null;
	}

	protected virtual void Awake()
	{
		if (s_instance != null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		s_instance = this;
		if (s_EverInitialized)
		{
			throw new Exception("Tried to Initialize the SteamAPI twice in one session!");
		}
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
		if (!Packsize.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Packsize Test returned false, the wrong version of Steamworks.NET is being run in this platform.", this);
		}
		if (!DllCheck.Test())
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] DllCheck Test returned false, One or more of the Steamworks binaries seems to be the wrong version.", this);
		}
		try
		{
			if (SteamAPI.RestartAppIfNecessary(AppId_t.Invalid))
			{
				Application.Quit();
				return;
			}
		}
		catch (DllNotFoundException ex)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] Could not load [lib]steam_api.dll/so/dylib. It's likely not in the correct location. Refer to the README for more details.\n" + ex, this);
			Application.Quit();
			return;
		}
		m_bInitialized = SteamAPI.Init();
		if (!m_bInitialized)
		{
			UnityEngine.Debug.LogError("[Steamworks.NET] SteamAPI_Init() failed. Refer to Valve's documentation or the comment above this line for more information.", this);
		}
		else
		{
			s_EverInitialized = true;
		}
	}

	protected virtual void OnEnable()
	{
		if (s_instance == null)
		{
			s_instance = this;
		}
		if (m_bInitialized)
		{
			if (m_SteamAPIWarningMessageHook == null)
			{
				m_SteamAPIWarningMessageHook = SteamAPIDebugTextHook;
				SteamClient.SetWarningMessageHook(m_SteamAPIWarningMessageHook);
			}
			m_Platform?.InitializeCallbacks();
		}
	}

	protected virtual void OnDestroy()
	{
		if (!(s_instance != this))
		{
			s_instance = null;
			if (m_bInitialized)
			{
				SteamAPI.Shutdown();
			}
		}
	}

	protected virtual void Update()
	{
		if (m_bInitialized)
		{
			SteamAPI.RunCallbacks();
		}
	}

	public static bool SetPlatform(PlatformSteam platform)
	{
		if (Initialized)
		{
			s_instance.m_Platform = platform;
			return true;
		}
		return false;
	}
}
