[AddComponentMenu("Flotsam/Particle Controller")]
public class ParticleController : MonoBehaviour
{
	[SerializeField]
	private bool _ignoreChildren;

	private bool _poolingEnaled;

	private bool _isPooled;

	private ParticleController _prefab;

	private ParticleSystem _particleSystem;

	private bool _trackTransform;

	private Transform _trackedTransform;

	private Vector3 _offset;

	private static Dictionary<ParticleController, List<ParticleController>> _pool = new Dictionary<ParticleController, List<ParticleController>>(8);

	public bool IsAlive => _particleSystem.IsAlive(!_ignoreChildren);

	private void Reset()
	{
		if (_particleSystem == null)
		{
			_particleSystem = GetComponent<ParticleSystem>();
		}
	}

	private void Awake()
	{
		_poolingEnaled = true;
		_isPooled = false;
		if (_particleSystem == null)
		{
			_particleSystem = GetComponentInChildren<ParticleSystem>();
		}
	}

	private void Update()
	{
		if (!_isPooled)
		{
			if (_trackTransform)
			{
				base.transform.position = _trackedTransform.position + _trackedTransform.rotation * _offset;
			}
			if (_poolingEnaled && !IsAlive)
			{
				Pool();
			}
		}
	}

	private void OnDestroy()
	{
		if (base.gameObject.scene.isLoaded)
		{
			UnityEngine.Debug.LogFormat("ParticleController '{0}' was destroyed", base.name);
		}
	}

	public void Initialize(Transform transformToTrack = null, Vector3 offset = default(Vector3))
	{
		if (_particleSystem == null)
		{
			_particleSystem = GetComponentInChildren<ParticleSystem>();
		}
		if (transformToTrack != null)
		{
			_trackTransform = true;
			_trackedTransform = transformToTrack;
			_offset = offset;
		}
	}

	public ParticleSystem DisablePooling()
	{
		_poolingEnaled = false;
		if (_particleSystem == null)
		{
			_particleSystem = GetComponent<ParticleSystem>();
		}
		ParticleSystem.MainModule main = _particleSystem.main;
		main.playOnAwake = false;
		return _particleSystem;
	}

	public void Play()
	{
		_particleSystem.Play();
	}

	private void Pool()
	{
		if (_prefab == null)
		{
			UnityEngine.Debug.LogErrorFormat("Unable to pool ParticleController '{0}' because it has now reference to its prefab", base.name);
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		_particleSystem.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmittingAndClear);
		_trackTransform = false;
		_trackedTransform = null;
		_isPooled = true;
		if (_pool.TryGetValue(_prefab, out var value))
		{
			value.AddUnique(this);
			return;
		}
		_pool.Add(_prefab, new List<ParticleController> { this });
	}

	public static ParticleController Spawn(ParticleController prefab, Transform transform, Vector3 offset)
	{
		ParticleController instance = GetInstance(prefab, transform.position, transform.rotation);
		instance.Initialize(transform, offset);
		return instance;
	}

	public static ParticleController Spawn(ParticleController prefab, Vector3 position, Quaternion rotation)
	{
		ParticleController instance = GetInstance(prefab, position, rotation);
		instance.Initialize();
		return instance;
	}

	private static ParticleController GetInstance(ParticleController prefab, Vector3 position, Quaternion rotation)
	{
		ParticleController particleController;
		if (_pool.TryGetValue(prefab, out var value) && 0 < value.Count)
		{
			int num = value.Count - 1;
			while (0 <= num)
			{
				particleController = value[num];
				value.RemoveAt(num--);
				if ((bool)particleController)
				{
					particleController._isPooled = false;
					particleController.transform.SetPositionAndRotation(position, rotation);
					if (particleController._particleSystem.main.playOnAwake)
					{
						particleController.Play();
					}
					return particleController;
				}
			}
		}
		particleController = UnityEngine.Object.Instantiate(prefab, position, rotation);
		particleController._prefab = prefab;
		return particleController;
	}
}
[Serializable]
public class ParticleEffect : IEffect
{
	[Tooltip("The trigger that activates this particle effect.")]
	public EffectTrigger Trigger;

	[Tooltip("The particle controller that is used as the prefab for this effect.")]
	public ParticleController Controller;

	[Tooltip("The number of instances that should be spawned when the ParticleEffect is initialized.")]
	public int MinimumCount;

	[Tooltip("The maximum amount of instances that can be spawned of this ParticleEffect (Currently only used for capacity).")]
	public int MaximumCount = 5;

	private int _instanceCount;

	private Queue<ParticleController> _idleControllers;

	private Queue<ParticleController> _activeControllers;

	public void Initialize()
	{
		_idleControllers = new Queue<ParticleController>(MaximumCount);
		_activeControllers = new Queue<ParticleController>(MaximumCount);
		LoadingScreen.AddEnumeratorTask(InstantiateMinimum, MinimumCount);
	}

	public void Update()
	{
		if (0 < _activeControllers.Count && !_activeControllers.Peek().IsAlive)
		{
			_idleControllers.Enqueue(_activeControllers.Dequeue());
		}
	}

	private void InstantiateMinimum(int index)
	{
		_idleControllers.Enqueue(InstantiateController());
	}

	public bool Activate(EffectTrigger trigger, Transform parent, Vector3 localPosition)
	{
		if (Trigger == trigger)
		{
			ParticleController particleController = ((0 < _idleControllers.Count) ? _idleControllers.Dequeue() : ((_instanceCount >= MaximumCount) ? InstantiateController() : InstantiateController()));
			particleController.transform.SetParent(parent);
			particleController.transform.localPosition = localPosition;
			particleController.Initialize(parent, localPosition);
			particleController.Play();
			_activeControllers.Enqueue(particleController);
			return true;
		}
		return false;
	}

	private ParticleController InstantiateController()
	{
		ParticleController particleController = UnityEngine.Object.Instantiate(Controller);
		particleController.DisablePooling();
		_instanceCount++;
		return particleController;
	}

	private void DestroyController(ParticleController controller)
	{
		UnityEngine.Object.Destroy(controller.gameObject);
		_instanceCount--;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Plop Properties")]
public class PlopProperties : ScriptableObject
{
	[Tooltip("Height curve that the transform will follow.")]
	[SerializeField]
	private AnimationCurve _movementCurve;

	public void Initiate(Transform transformToMove)
	{
		GameManager.Instance.StartCoroutine(StartPlopCoroutine(transformToMove));
	}

	private IEnumerator StartPlopCoroutine(Transform transformToMove)
	{
		float plopTimer = 0f;
		if (_movementCurve.keys.Length != 0)
		{
			float maximumAnimationTime = _movementCurve.keys[_movementCurve.keys.Length - 1].time;
			while (plopTimer >= 0f && plopTimer < maximumAnimationTime)
			{
				plopTimer += GameSpeedManager.PausableUnscaledDeltaTime;
				plopTimer = Mathf.Clamp(plopTimer, 0f, maximumAnimationTime);
				transformToMove.position = transformToMove.position.SetY(_movementCurve.Evaluate(plopTimer));
				yield return null;
			}
		}
	}
}
[RequireComponent(typeof(LineRenderer))]
public class PolygonLineRenderer : MonoBehaviour
{
