[CreateAssetMenu(menuName = "Flotsam/Flotsam/Composited Flotsam Properties")]
public class CompositedFlotsamProperties : FlotsamProperties
{
	[Header("Description")]
	[Tooltip("Localized name of the flotsam to display in-game.")]
	public LocalizedString LocalizedName = "";

	[Tooltip("Localized description of the flotsam to display in-game.")]
	public LocalizedString LocalizedDescription = "";

	[Header("Items")]
	[SerializeField]
	[Tooltip("Items that make up the composition of this flotsam.")]
	private CountedItemProperty[] _composition;

	public CountedItemProperty[] Composition => _composition;

	public float ReturnCompositionMatch(List<CountedItemProperty> countedItems)
	{
		int num = 0;
		int num2 = 0;
		CountedItemProperty[] composition = Composition;
		foreach (CountedItemProperty countedItemProperty in composition)
		{
			num += countedItemProperty.Amount;
			foreach (CountedItemProperty countedItem in countedItems)
			{
				if (countedItemProperty.ItemProperties == countedItem.ItemProperties)
				{
					num2 = ((countedItem.Amount >= countedItemProperty.Amount) ? (num2 + countedItemProperty.Amount) : (num2 + countedItem.Amount));
				}
			}
		}
		return (num > 0) ? (num2 / num) : 0;
	}

	public bool Contains(FlotsamProperties properties)
	{
		CountedItemProperty[] composition = _composition;
		for (int i = 0; i < composition.Length; i++)
		{
			if (composition[i].ItemProperties.FlotsamProperties == properties)
			{
				return true;
			}
		}
		return false;
	}
}
[SelectionBase]
public class Flotsam : FlotsamBehaviour, ISelectable, IPersistentReference
{
	[Header("HACK")]
	[SerializeField]
	public NonInteractableFlotsam NonInteractablePrefab;

	[Header("References")]
	[SerializeField]
	private FlotsamInventory _inventory;

	[SerializeField]
	private Target _target;

	public string LocalizedName { get; private set; } = "";

	public bool Initialized { get; protected set; }

	public bool IsPointOfInterest { get; private set; }

	public int PersistentIndex { get; set; } = -1;

	public Vector3 Position { get; private set; }

	public ObjectType ObjectType => ObjectType.None;

	public GameObject RelatedGameObject => base.gameObject;

	public override bool Interactable => true;

	public FlotsamInventory Inventory => _inventory;

	public override bool Initialize(FlotsamProperties properties, int visualPrefabIndex)
	{
		if (!base.Initialize(properties, visualPrefabIndex))
		{
			return false;
		}
		Inventory.TransferAnimationCycles = properties.AnimationCycles;
		Inventory.Pickup = properties.SalvageActivity;
		Inventory.Dropoff = properties.SalvageActivity;
		InitializeVisual();
		AddFlotsamToWorldlist();
		base.transform.rotation = base.VisualPrefab.ReturnRandomRotation();
		if (base.transform.parent == null)
		{
			base.transform.SetParent(GameManager.WorldManager.FlotsamParent, worldPositionStays: true);
		}
		if (!base.Properties.Static)
		{
			_target.Radius = base.Properties.TargetRadius;
		}
		Initialized = true;
		return true;
	}

	public override void InitializeComposition(CompositionInventory compositionInventory)
	{
		_inventory.Initialize(compositionInventory);
		_inventory.CompositionUpdatedEvent += OnCompositionUpdated;
		Item item = compositionInventory.PeekAtFirstItem();
		base.gameObject.name = item.Properties.name;
		LocalizedName = item.Properties.LocalizedName;
		if (compositionInventory.ReturnProgress() < 1f)
		{
			OnCompositionUpdated(compositionInventory.ReturnProgress());
		}
	}

	protected virtual void LateUpdate()
	{
		Position = base.transform.position;
	}

	private void OnDestroy()
	{
		if (_inventory != null)
		{
			_inventory.CompositionUpdatedEvent -= OnCompositionUpdated;
		}
		SafelyDestroy(clearProject: true, release: false);
	}

	public override void UpdatePositionAndRotation(Vector3 position, Quaternion rotation)
	{
		base.UpdatePositionAndRotation(position, rotation);
		Position = position;
	}

	public override void Throw(ThrowProperties throwProperties)
	{
		StartCoroutine(ThrowCoroutine(throwProperties));
	}

	protected virtual IEnumerator ThrowCoroutine(ThrowProperties throwProperties)
	{
		RemoveFlotsamFromWorldlist();
		yield return ThrowMovementCoroutine(throwProperties);
		base.transform.localScale = Vector3.one;
		AddFlotsamToWorldlist();
		GameManager.WorldManager.AddFlotsam(this);
	}

	public void AddFlotsamToWorldlist()
	{
		Position = base.transform.position;
		GameManager.WorldManager.FlotsamInWorld.AddUnique(this);
	}

	public void RemoveFlotsamFromWorldlist()
	{
		GameManager.WorldManager.FlotsamInWorld.RemoveSafely(this);
	}

	public void SafelyDestroy(bool clearProject = true, bool release = true)
	{
		Remove(clearProject);
		if (release)
		{
			FlotsamPool.Instance.Release(this);
		}
	}

	private void Remove(bool removeForAgents = true)
	{
		RemoveFlotsamFromWorldlist();
		if (!removeForAgents)
		{
			return;
		}
		List<Item> list = Inventory.ReturnAllItems();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].Project != null)
			{
				list[i].Project.RemoveItem(list[i]);
			}
		}
	}

	private void OnCompositionUpdated(float progress)
	{
		if (progress == 0f)
		{
			SafelyDestroy(clearProject: false);
			FlotsamEvent.Dispatch(GameEventType.FlotsamSalvage, this);
			base.OnSalvage.Invoke();
			return;
		}
		if (base.VisualPrefab == null)
		{
			throw new NotSupportedException();
		}
		base.VisualPrefab.SetProgress(progress);
	}

	public override void Activate(Vector3 position)
	{
		base.Activate(position);
		AddFlotsamToWorldlist();
	}

	public override void Deactivate()
	{
		base.Deactivate();
		RemoveFlotsamFromWorldlist();
		if ((bool)_inventory)
		{
			_inventory.CompositionUpdatedEvent -= OnCompositionUpdated;
		}
	}

	public FlotsamProperties ReturnProperties()
	{
		return base.Properties;
	}

	public override float ReturnCompositionProgress()
	{
		return _inventory.ReturnCompositionProgress();
	}
}
public abstract class FlotsamBehaviour : MonoBehaviour
{
	public FlotsamProperties Properties { get; private set; }

	public int VisualPrefabIndex { get; private set; }

	public VisualPrefab VisualPrefab { get; private set; }

	public abstract bool Interactable { get; }

	public bool Pooled { get; private set; }

	public UnityEvent OnSalvage { get; private set; } = new UnityEvent();

	public virtual bool Initialize(FlotsamProperties properties, int visualPrefabIndex = -1)
	{
		if (properties == null)
		{
			PajamaLlama.Debugs.Debugger.Error($"No flotsam properties set for {base.gameObject.name}.", this);
			return false;
		}
		Properties = properties;
		VisualPrefabIndex = visualPrefabIndex;
		Pooled = false;
		return true;
	}

	public void InitializeVisual(bool removeCollider = false)
	{
		int num = VisualPrefabIndex;
		int count = Properties.VisualPrefabs.Count;
		if (num < 0 || num <= count)
		{
			num = UnityEngine.Random.Range(0, count);
		}
		VisualPrefab = UnityEngine.Object.Instantiate(Properties.VisualPrefabs[num]);
		VisualPrefab.transform.SetParent(base.transform, worldPositionStays: true);
		VisualPrefab.transform.localPosition = Vector3.zero;
		VisualPrefab.transform.localRotation = Quaternion.identity;
		VisualPrefab.tag = "FlotsamVisual";
		Collider component = VisualPrefab.GetComponent<Collider>();
		if ((bool)component)
		{
			if (removeCollider)
			{
				UnityEngine.Object.Destroy(component);
			}
			else
			{
				component.enabled = true;
			}
		}
		VisualPrefabIndex = num;
	}

	public abstract void InitializeComposition(CompositionInventory composition);

	public virtual void UpdatePositionAndRotation(Vector3 position, Quaternion rotation)
	{
		base.transform.position = position;
		base.transform.rotation = rotation;
	}

	public abstract void Throw(ThrowProperties throwProperties);

	protected IEnumerator ThrowMovementCoroutine(ThrowProperties throwProperties)
	{
		Vector3 startPosition = base.transform.position;
		float timer = 0f;
		base.transform.rotation = throwProperties.Rotation;
		Vector3 target;
		float height;
		if (throwProperties.TargetTransform == null)
		{
			target = throwProperties.TargetPosition;
			height = Vector3.Distance(startPosition, throwProperties.TargetPosition);
		}
		else
		{
			target = throwProperties.TargetTransform.position;
			height = Vector3.Distance(startPosition, throwProperties.TargetTransform.position);
		}
		while (timer < throwProperties.Duration)
		{
			float num = timer / throwProperties.Duration;
			if (throwProperties.TargetTransform != null)
			{
				target = throwProperties.TargetTransform.position;
			}
			height = Mathf.Min(Vector3.Distance(startPosition, target) * 0.49f, height);
			base.transform.position = AnimationTween.SphericalPositionLerp(startPosition, target, num, height);
			if (throwProperties.ScaleUp)
			{
				base.transform.localScale = Mathf.Lerp(throwProperties.MinimumScale, throwProperties.MaximumScale, num) * Vector3.one;
			}
			else
			{
				base.transform.localScale = Mathf.Lerp(throwProperties.MaximumScale, throwProperties.MinimumScale, num) * Vector3.one;
			}
			timer += Time.deltaTime;
			yield return null;
		}
		throwProperties.Dispose();
	}

	public virtual void Activate(Vector3 position)
	{
		base.transform.position = position;
		if ((bool)VisualPrefab)
		{
			VisualPrefab.enabled = true;
		}
		Pooled = false;
	}

	public virtual void Deactivate()
	{
		base.transform.SetParent(FlotsamPool.PooledParent, worldPositionStays: true);
		if ((bool)VisualPrefab)
		{
			VisualPrefab.enabled = false;
		}
		Pooled = true;
	}

	public abstract float ReturnCompositionProgress();
}
public class FlotsamPool
{
	private List<FlotsamPropertiesPool> _pools;

	private Transform _pooledParent;

	private static FlotsamPool _instance;

	public static Transform PooledParent => Instance.ReturnPooledParent();

	public static FlotsamPool Instance
	{
		get
		{
			if (_instance == null)
			{
				_instance = new FlotsamPool();
			}
			return _instance;
		}
	}

	private FlotsamPool()
	{
		_pools = new List<FlotsamPropertiesPool>();
		SceneManager.sceneUnloaded += OnSceneUnloaded;
	}

	~FlotsamPool()
	{
		SceneManager.sceneUnloaded -= OnSceneUnloaded;
	}

	public int Aquire(out FlotsamBehaviour flotsam, FlotsamProperties properties, Vector3 position, bool interactable, int preferredIndex = -1)
	{
		if (properties == null)
		{
			UnityEngine.Debug.Log("Unable to aquire interactable flotsam because the properties are null.");
			flotsam = null;
			return -1;
		}
		if (interactable)
		{
			return ReturnPool(properties).AquireInteractable(out flotsam, position, preferredIndex);
		}
		return ReturnPool(properties).AquireNonInteractable(out flotsam, position, preferredIndex);
	}

	public void Release(FlotsamBehaviour flotsam)
	{
		if (flotsam.Pooled)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' is being released to the FlotsamPool, but it is already pooled!", flotsam.name);
		}
		else
		{
			ReturnPool(flotsam.Properties).Release(flotsam);
		}
	}

	private void OnSceneUnloaded(Scene scene)
	{
		foreach (FlotsamPropertiesPool pool in _pools)
		{
			pool.RemoveDestroyed();
		}
	}

	public FlotsamPropertiesPool ReturnPool(FlotsamProperties properties)
	{
		int count = _pools.Count;
		FlotsamPropertiesPool flotsamPropertiesPool;
		for (int i = 0; i < count; i++)
		{
			flotsamPropertiesPool = _pools[i];
			if (flotsamPropertiesPool.Properties == properties)
			{
				return flotsamPropertiesPool;
			}
		}
		flotsamPropertiesPool = new FlotsamPropertiesPool(properties);
		_pools.Add(flotsamPropertiesPool);
		return flotsamPropertiesPool;
	}

	private Transform ReturnPooledParent()
	{
		if ((bool)_pooledParent)
		{
			return _pooledParent;
		}
		_pooledParent = new GameObject().transform;
		_pooledParent.name = "Pool";
		_pooledParent.transform.SetParent(GameManager.WorldManager.FlotsamParent);
		_pooledParent.position = Vector3.zero;
		return _pooledParent;
	}
}
