public abstract class AgentReferenceUIElement : SceneBehaviour
{
	[SerializeField]
	private AgentReference _agentReference;

	protected Agent _agent;

	protected virtual void OnEnable()
	{
		if ((bool)_agentReference)
		{
			_agentReference.OnAgentUpdated.AddListener(OnAgentUpdated);
			OnAgentUpdated();
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Agent reference not set on '{0}'", base.transform.HierarchyPathToString());
		}
	}

	protected virtual void OnDisable()
	{
		if ((bool)_agentReference)
		{
			_agentReference.OnAgentUpdated.RemoveListener(OnAgentUpdated);
			if (_agent != null)
			{
				Unsubscribe(_agent);
				_agent = null;
			}
		}
	}

	protected abstract void Subscribe(Agent agent);

	protected abstract void Unsubscribe(Agent agent);

	private void OnAgentUpdated()
	{
		if (_agentReference.Agent != null && _agentReference.Agent.Initialized)
		{
			UpdateAgent(_agentReference.Agent);
		}
	}

	protected virtual void UpdateAgent(Agent agent)
	{
		if (_agent != null)
		{
			Unsubscribe(_agent);
		}
		_agent = agent;
		Subscribe(_agent);
	}
}
public class ArchitectBottomBar : Panel, ICancelable
{
	[SerializeField]
	private MoveBuildableCursorProperties _cursorProperties;

	[SerializeField]
	private RewiredComponent _applyComponent;

	[SerializeField]
	private Button _revertButton;

	[SerializeField]
	private TextMeshProUGUI _counter;

	[SerializeField]
	private GameObject[] _gameObjectsToDisable;

	[SerializeField]
	private DPad _dPad;

	[SerializeField]
	private DPadProperties _dPadProperties;

	[SerializeField]
	[FormerlySerializedAs("_applyDialogProperties")]
	private DialogProperties _applyStoredDialogProperties;

	[SerializeField]
	private DialogProperties _applyPlacingDialogProperties;

	[SerializeField]
	private DialogProperties _revertDialogProperties;

	private Community _community;

	private CursorManager _cursorManager;

	private int StoredBuildableCount
	{
		get
		{
			if (_community == null)
			{
				return 0;
			}
			return _community.ReturnStoredBuildablesCount();
		}
	}

	private void OnEnable()
	{
		_revertButton.interactable = PersistenceManager.TryTakeSnapShot();
		_community = Community.PlayerCommunity;
		_community.OnStoredBuildableAdded.AddListener(OnStoredBuildableAdded);
		_community.OnStoredBuildableRemoved.AddListener(OnStoredBuildableRemoved);
		_counter.text = StoredBuildableCount.ToString();
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		DisableGameObjects();
		if ((bool)_dPad)
		{
			_dPad.OverrideDPadProperties(_dPadProperties);
		}
		_cursorManager = GameManager.CursorManager;
		_cursorManager?.Activate(_cursorProperties);
		FlotsamInputManager.PushCancelable(this);
	}

	private void Update()
	{
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		GameObject[] gameObjectsToDisable = _gameObjectsToDisable;
		for (int i = 0; i < gameObjectsToDisable.Length; i++)
		{
			gameObjectsToDisable[i].SetActive(value: true);
		}
		if ((bool)_dPad)
		{
			_dPad.RemoveOverrideDPadProperties(_dPadProperties);
		}
		_cursorManager?.Deactivate();
		FlotsamInputManager.RemoveCancelable(this);
	}

	private void OnActiveInputUpdated(GameEvent gameEvent)
	{
		FinalUpdate.RegisterOneShot(DisableGameObjects);
	}

	private void DisableGameObjects()
	{
		GameObject[] gameObjectsToDisable = _gameObjectsToDisable;
		for (int i = 0; i < gameObjectsToDisable.Length; i++)
		{
			gameObjectsToDisable[i].SetActive(value: false);
		}
	}

	private void OnStoredBuildableAdded(IPlaceable placeable, bool toggleCategory)
	{
		_counter.text = StoredBuildableCount.ToString();
	}

	private void OnStoredBuildableRemoved(IPlaceable placeable)
	{
		_counter.text = StoredBuildableCount.ToString();
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (UIManager.AllowArchitectMode)
		{
			return base.Open(id, context);
		}
		return false;
	}

	public override void Close()
	{
		base.Close();
		GameManager.UIManager.ClosePanel(PanelID.ArchitectBuildableCreation);
		GameManager.UIManager.ClosePanel(PanelID.BuildableCreation);
	}

	public void Apply()
	{
		if (!_applyComponent.IsMappedToUICancel() || (!GameManager.UIManager.IsPanelOpen(PanelID.ArchitectBuildableCreation) && !GameManager.UIManager.IsPanelOpen(PanelID.BuildableCreation)))
		{
			if (_cursorProperties.BlocksApply)
			{
				PopUpDialog.Instance.TryOpenPopUpDialog(_applyPlacingDialogProperties);
			}
			else if (_community.ReturnStoredBuildablesCount(onlyBuildings: true) <= 0)
			{
				GameManager.UIManager.ClosePanel(PanelID.ArchitectBottomBar);
				GameManager.CursorManager.Deactivate(cancelled: true);
				PersistenceManager.ClearSnapShot();
			}
			else if (PopUpDialog.Instance.TryOpenPopUpDialog(_applyStoredDialogProperties))
			{
				PopUpDialog.Instance.DialogFeedbackEvent.AddListener(OnRevertDialogFeedback);
			}
		}
	}

	public void Revert()
	{
		if (PopUpDialog.Instance.TryOpenPopUpDialog(_revertDialogProperties))
		{
			PopUpDialog.Instance.DialogFeedbackEvent.AddListener(OnRevertDialogFeedback);
		}
	}

	private void OnRevertDialogFeedback(bool revert)
	{
		PopUpDialog.Instance.DialogFeedbackEvent.RemoveListener(OnRevertDialogFeedback);
		if (revert)
		{
			if (PersistenceManager.SetRestoreSnapShot())
			{
				_cursorProperties.OnRevert();
				LoadingScreen.LoadScene("_02_GameWorld");
			}
			else
			{
				UnityEngine.Debug.LogError("Unable to restore Snap Shot!");
			}
		}
	}

	public bool TryCancel()
	{
		return false;
	}
}
public class CharacterPreview : MonoBehaviour, ILocalizationGenderProvider, ILocalizationParamsManager
{
	[Header("Portrait")]
	[SerializeField]
	private RawImage _portrait;

	[SerializeField]
	private Camera _cameraPrefab;

	[SerializeField]
	private Vector3 _cameraOffset;

	[Header("Information")]
	[SerializeField]
	private TextMeshProUGUI _name;

	[SerializeField]
	private TextMeshProUGUI _pastBackgroundName;

	[SerializeField]
	private TextMeshProUGUI _pastBackgroundDescription;

	[SerializeField]
	private Image _pastBackgroundIcon;

	[SerializeField]
	private TextMeshProUGUI _presentBackgroundName;

	[SerializeField]
	private TextMeshProUGUI _presentBackgroundDescription;

	[SerializeField]
	private Image _presentBackgroundIcon;

	[Space]
	[SerializeField]
	private DrifterAttributeTooltipElement _attributePrefab;

	[SerializeField]
	private RectTransform _pastAttributeParent;

	[SerializeField]
	private RectTransform _presentAttributeParent;

	[Header("Header")]
	[SerializeField]
	private Color _textColor = Color.white;

	[Header("Navigation")]
	[SerializeField]
	private Selectable _rerollButton;

	[SerializeField]
	private Selectable _preferenceDropdown;

	[SerializeField]
	private ScrollRectAxisScroller _scroller;

	[Header("Animation")]
	[SerializeField]
	private Animator _animator;

	[SerializeField]
	private string _animatorPropertySelected = "Selected";

	private DrifterRig _rig;

	private List<DrifterAttributeTooltipElement> _pastAttributes = new List<DrifterAttributeTooltipElement>();

	private List<DrifterAttributeTooltipElement> _presentAttributes = new List<DrifterAttributeTooltipElement>();

	private DrifterAttributes.AttributeType _attributeBias;

	private List<DrifterAttributeTooltipElement> _activeAttributes = new List<DrifterAttributeTooltipElement>();

	private CharacterPreview _leftNeighbor;

	private CharacterPreview _rightNeighbor;

	public AgentDescriptor AgentDescriptor { get; private set; }

	public Camera Camera { get; private set; }

	Agent.EGender ILocalizationGenderProvider.LocalizationGender => AgentDescriptor.Gender;

	private void OnEnable()
	{
		LocalizationManager.ParamManagers.AddUnique(this);
		FocusManager.CurrentSelectedGameObjectChanged.AddListener(OnSelectableGameObjectChanged);
	}

	private void OnDisable()
	{
		LocalizationManager.ParamManagers.Remove(this);
		FocusManager.CurrentSelectedGameObjectChanged.RemoveListener(OnSelectableGameObjectChanged);
	}

	public void Initialize(Transform cameraParent, Vector3 position)
	{
		AgentDescriptor = AgentDescriptor.CreateInstance();
		Camera = UnityEngine.Object.Instantiate(_cameraPrefab, cameraParent);
		Camera.transform.localPosition = position;
		RenderTexture renderTexture = new RenderTexture(1024, 1024, 24, GraphicsFormat.R8G8B8A8_UNorm);
		renderTexture.Create();
		Camera.targetTexture = renderTexture;
		_portrait.texture = renderTexture;
		GenerateCharacterMesh(AgentDescriptor, Camera.transform, _cameraOffset);
		SetInfo();
	}

	public void InitializeHorizontalNavigation(CharacterPreview leftNeighbor, CharacterPreview rightNeighbor)
	{
		_leftNeighbor = leftNeighbor;
		_rightNeighbor = rightNeighbor;
		InitializeLeftToRightNavigation(this, _rightNeighbor);
	}

	public void Reroll()
	{
		ListPool<DrifterAttributesEffect>.List list = ListPool<DrifterAttributesEffect>.List.Get();
		ListPool<DrifterAttributesEffect>.List list2 = ListPool<DrifterAttributesEffect>.List.Get();
		DrifterAttributes.AttributeType bias = DrifterAttributes.AttributeType.None;
		DrifterAttributes.AttributeType bias2 = DrifterAttributes.AttributeType.None;
		int num = UnityEngine.Random.Range(0, 100);
		if (num < 45)
		{
			bias = _attributeBias;
		}
		else if (num < 90)
		{
			bias2 = _attributeBias;
		}
		else
		{
			bias = (bias2 = _attributeBias);
		}
		PopulateBackgrounds(AgentDescriptor.Properties.PastBackgrounds, list, bias);
		PopulateBackgrounds(AgentDescriptor.Properties.PresentBackgrounds, list2, bias2);
		AgentDescriptor.Reroll(list.GetRandom(), list2.GetRandom());
		list.Dispose();
		list2.Dispose();
		GenerateCharacterMesh(AgentDescriptor, Camera.transform, _cameraOffset);
		SetInfo();
		InitializeLeftToRightNavigation(_leftNeighbor, this);
		InitializeLeftToRightNavigation(this, _rightNeighbor);
	}

	private void PopulateBackgrounds(IReadOnlyList<DrifterAttributesEffect> source, List<DrifterAttributesEffect> target, DrifterAttributes.AttributeType bias = DrifterAttributes.AttributeType.None)
	{
		if (bias == DrifterAttributes.AttributeType.None)
		{
			target.AddRange(source);
			return;
		}
		foreach (DrifterAttributesEffect item in source)
		{
			if (item.ReturnContainsAttributeType(bias))
			{
				target.Add(item);
			}
		}
	}

	public void SetAttributeBias(DrifterAttributes.AttributeType attributeBias)
	{
		_attributeBias = attributeBias;
	}

	private DrifterRig GenerateCharacterMesh(AgentDescriptor agentDescriptor, Transform parent, Vector3 position)
	{
		if (_rig == null || _rig.Gender != agentDescriptor.Gender)
		{
			UnityEngine.Object.Destroy(_rig);
			_rig = DrifterRig.Instantiate(agentDescriptor);
		}
		Transform obj = _rig.transform;
		obj.parent = parent;
		obj.localPosition = position;
		obj.localRotation = Quaternion.Euler(new Vector3(0f, 180f, 0f));
		agentDescriptor.ApplyLooksForPortrait(_rig, DrifterLookCamera.DynamicPortrait, applyAlternativeLook: false);
		_rig.SetShadows(active: false);
		_rig.SetPortraitLayer();
		_rig.MeshAnimator.Initialize();
		_rig.MeshAnimator.UpdatePortraitAnimator(AgentDescriptor, Activity.CrewScreenPortrait);
		_rig.MeshAnimator.Animator.updateMode = AnimatorUpdateMode.UnscaledTime;
		_rig.MeshAnimator.Animator.SetTrigger("Transition Trigger");
		return _rig;
	}

	private void SetInfo()
	{
		_name.text = AgentDescriptor.Name;
		_pastBackgroundName.text = AgentDescriptor.PastBackground.Name;
		_pastBackgroundDescription.text = AgentDescriptor.PastBackground.Description;
		_pastBackgroundIcon.sprite = AgentDescriptor.PastBackground.IconProperties.Sprite;
		_presentBackgroundName.text = AgentDescriptor.PresentBackground.Name;
		_presentBackgroundDescription.text = AgentDescriptor.PresentBackground.Description;
		_presentBackgroundIcon.sprite = AgentDescriptor.PresentBackground.IconProperties.Sprite;
		_activeAttributes.Clear();
		SetModifiers(AgentDescriptor.PastBackground.Modifiers, _pastAttributeParent, ref _pastAttributes);
		SetModifiers(AgentDescriptor.PresentBackground.Modifiers, _presentAttributeParent, ref _presentAttributes);
		if (0 < _activeAttributes.Count)
		{
			DrifterAttributeTooltipElement drifterAttributeTooltipElement = _activeAttributes[0];
			_preferenceDropdown.SetSelectOnUp(drifterAttributeTooltipElement.Selectable);
			_rerollButton.SetSelectOnUp(drifterAttributeTooltipElement.Selectable);
			drifterAttributeTooltipElement.Selectable.SetSelectOnDown(_preferenceDropdown);
			for (int i = 1; i < _activeAttributes.Count; i++)
			{
				DrifterAttributeTooltipElement drifterAttributeTooltipElement2 = drifterAttributeTooltipElement;
				drifterAttributeTooltipElement = _activeAttributes[i];
				drifterAttributeTooltipElement2.Selectable.SetSelectOnUp(drifterAttributeTooltipElement.Selectable);
				drifterAttributeTooltipElement.Selectable.SetSelectOnDown(drifterAttributeTooltipElement2.Selectable);
			}
		}
	}

	private void SetModifiers(DrifterAttributeModifier[] modifiers, RectTransform parent, ref List<DrifterAttributeTooltipElement> previews)
	{
		foreach (DrifterAttributeTooltipElement preview in previews)
		{
			preview.Selectable.ClearNavigation();
			preview.gameObject.SetActive(value: false);
		}
		for (int i = 0; i < modifiers.Length; i++)
		{
			DrifterAttributeModifier modifier = modifiers[i];
			DrifterAttributeTooltipElement drifterAttributeTooltipElement;
			if (i >= previews.Count)
			{
				drifterAttributeTooltipElement = UnityEngine.Object.Instantiate(_attributePrefab, parent);
				previews.Add(drifterAttributeTooltipElement);
			}
			else
			{
				drifterAttributeTooltipElement = previews[i];
				drifterAttributeTooltipElement.gameObject.SetActive(value: true);
			}
			drifterAttributeTooltipElement.SetModifier(AgentDescriptor.Properties.AttributeProperties, modifier, _textColor);
			_activeAttributes.Insert(0, drifterAttributeTooltipElement);
		}
	}

	private void InitializeLeftToRightNavigation(CharacterPreview left, CharacterPreview right)
	{
		if (left == null || right == null)
		{
			return;
		}
		int num = Mathf.Max(left._activeAttributes.Count, right._activeAttributes.Count);
		bool flag = true;
		bool flag2 = true;
		DrifterAttributeTooltipElement drifterAttributeTooltipElement = null;
		DrifterAttributeTooltipElement drifterAttributeTooltipElement2 = null;
		for (int i = 0; i < num; i++)
		{
			if (i < left._activeAttributes.Count)
			{
				drifterAttributeTooltipElement = left._activeAttributes[i];
			}
			else
			{
				flag = false;
			}
			if (i < right._activeAttributes.Count)
			{
				drifterAttributeTooltipElement2 = right._activeAttributes[i];
			}
			else
			{
				flag2 = false;
			}
			if (flag)
			{
				drifterAttributeTooltipElement.Selectable.SetSelectOnRight(drifterAttributeTooltipElement2.Selectable);
			}
			if (flag2)
			{
				drifterAttributeTooltipElement2.Selectable.SetSelectOnLeft(drifterAttributeTooltipElement.Selectable);
			}
		}
	}

	private void OnSelectableGameObjectChanged(GameObject gameObject)
	{
		bool value = HasGameObject(gameObject);
		if ((bool)_animator)
		{
			_animator.SetBool(_animatorPropertySelected, value);
		}
		if ((bool)_scroller)
		{
			_scroller.enabled = value;
		}
	}

	private bool HasGameObject(GameObject gameObject)
	{
		if (_rerollButton.gameObject == gameObject || _preferenceDropdown.gameObject == gameObject)
		{
			return true;
		}
		foreach (DrifterAttributeTooltipElement activeAttribute in _activeAttributes)
		{
			if (activeAttribute.gameObject == gameObject)
			{
				return true;
			}
		}
		return false;
	}
}
public class CharacterSelector : MonoBehaviour
{
	[SerializeField]
	private CrewExpertisePanel _expertisePanel;

	[SerializeField]
	private CharacterPreview[] _previews;

	[SerializeField]
	private float _previewOffset = 10f;

	[SerializeField]
	private Vector3 _previewCameraParentPosition = new Vector3(0f, -1000f, 0f);

	private Transform _cameraParent;

	public CharacterPreview[] AgentPreviews => _previews;

	public void Initialize()
	{
		if (GameManager.Settings.SessionSettings.StartingScenario.Inhabitants != _previews.Length)
		{
			throw new ArgumentException("Character selector preview count does not match the player community agent count.");
		}
		_cameraParent = new GameObject().transform;
		_cameraParent.name = "StartMessage Camera Parent";
		_cameraParent.position = _previewCameraParentPosition;
		for (int i = 0; i < _previews.Length; i++)
		{
			_previews[i].Initialize(_cameraParent, Vector3.right * (_previewOffset * (float)i));
		}
		if (_previews.Length != 0)
		{
			CharacterPreview leftNeighbor = null;
			CharacterPreview characterPreview = _previews[0];
			int num = _previews.Length - 1;
			for (int j = 0; j <= num; j++)
			{
				CharacterPreview characterPreview2 = ((j == num) ? null : _previews[j + 1]);
				characterPreview.InitializeHorizontalNavigation(leftNeighbor, characterPreview2);
				leftNeighbor = characterPreview;
				characterPreview = characterPreview2;
			}
		}
		if (_expertisePanel != null)
		{
			_expertisePanel.Initialize();
		}
	}

	private void OnEnable()
	{
		if ((bool)_cameraParent)
		{
			_cameraParent.gameObject.SetActive(value: true);
		}
	}

	private void OnDisable()
	{
		if ((bool)_cameraParent)
		{
			_cameraParent.gameObject.SetActive(value: false);
		}
	}

	private void OnDestroy()
	{
		if ((bool)_cameraParent)
		{
			UnityEngine.Object.Destroy(_cameraParent);
		}
	}
}
public class CrewExpertisePanel : MonoBehaviour
{
	[SerializeField]
	private AgentReference[] _agentReferences = new AgentReference[0];

	[SerializeField]
	private CrewExpertisePanelEntry _expertisePrefab;

	[SerializeField]
	private Transform _expertiseParent;

	private Agent[] _agents;

	private List<CrewExpertisePanelEntry> _crewExpertiseEntries;

	public void Initialize()
	{
		_agents = new Agent[_agentReferences.Length];
		_crewExpertiseEntries = new List<CrewExpertisePanelEntry>();
		AgentReference[] agentReferences = _agentReferences;
		for (int i = 0; i < agentReferences.Length; i++)
		{
			agentReferences[i].OnAgentUpdated.AddListener(OnAgentUpdated);
		}
		OnAgentUpdated();
	}

	private void OnDestroy()
	{
		AgentReference[] agentReferences = _agentReferences;
		for (int i = 0; i < agentReferences.Length; i++)
		{
			agentReferences[i].OnAgentUpdated.RemoveListener(OnAgentUpdated);
		}
	}

	protected void Subscribe(Agent agent)
	{
		agent.Attributes.AttributesUpdatedEvent.AddListener(UpdatePanel);
		UpdatePanel();
	}

	protected void Unsubscribe(Agent agent)
	{
		agent.Attributes.AttributesUpdatedEvent.RemoveListener(UpdatePanel);
	}

	private void OnAgentUpdated()
	{
		for (int i = 0; i < _agentReferences.Length; i++)
		{
			UpdateAgent(_agentReferences[i].Agent, i);
		}
	}

	protected virtual void UpdateAgent(Agent agent, int index)
	{
		Agent agent2 = _agents[index];
		if (agent2 != null)
		{
			Unsubscribe(agent2);
		}
		_agents[index] = agent;
		Subscribe(agent);
	}

	private void UpdatePanel()
	{
		DrifterAttributes.AttributeType[] array = DrifterAttributes.ReturnAttributeTypes();
		foreach (DrifterAttributes.AttributeType attributeType in array)
		{
			if (attributeType != DrifterAttributes.AttributeType.None)
			{
				int num = 0;
				int num2 = 0;
				AgentReference[] agentReferences = _agentReferences;
				foreach (AgentReference agentReference in agentReferences)
				{
					num += agentReference.Agent.Attributes.ReturnAttributeExpertise(attributeType);
					num2 += agentReference.Agent.Attributes.ReturnAffinityAmount(attributeType);
				}
				ReturnEntry(attributeType).Initialize(attributeType, num, num2);
			}
		}
	}

	private CrewExpertisePanelEntry ReturnEntry(DrifterAttributes.AttributeType type)
	{
		foreach (CrewExpertisePanelEntry crewExpertiseEntry in _crewExpertiseEntries)
		{
			if (crewExpertiseEntry.Type == type)
			{
				return crewExpertiseEntry;
			}
		}
		CrewExpertisePanelEntry crewExpertisePanelEntry = UnityEngine.Object.Instantiate(_expertisePrefab, _expertiseParent);
		_crewExpertiseEntries.Add(crewExpertisePanelEntry);
		return crewExpertisePanelEntry;
	}
}
