public class DrifterOverview : SceneBehaviour, IComparer<DrifterOverviewPortrait>
{
	public enum Filters
	{
		Morale = 0,
		MortalDanger = 1,
		Disease = 2,
		Thirst = 3,
		Hunger = 4,
		Message = 5,
		Leveled = 6,
		Homeless = 7,
		Pollution = 8,
		RadioMessage = 9,
		None = 256
	}

	[Serializable]
	public struct FilterToggle
	{
		public Filters Filter;

		public Toggle Toggle;
	}

	[SerializeField]
	private ChildBehaviourCache<DrifterOverviewPortrait> _drifterPortraits;

	[SerializeField]
	private ChildBehaviourCache<RadioMessageSenderPortrait> _radioMessagePortraits;

	[SerializeField]
	private SelectableGroup _portraitSelectableGroup;

	[SerializeField]
	private FilterToggle[] _toggles;

	[SerializeField]
	private SelectableGroup _toggleSelectalbeGroup;

	private readonly List<DrifterOverviewPortrait> _sortedPortraits = new List<DrifterOverviewPortrait>();

	private bool _updateFilter;

	private bool _sortPortraits;

	public bool Minimized { get; private set; } = true;

	public Filters Filter { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnAgentPortraitAdded);
		GameEventDispatcher.AddListener(GameEventType.AgentRemovedFromPlayerCommunity, OnAgentRemoved);
		GameEventDispatcher.AddListener(GameEventType.RadioMessageReceived, OnRadioMessageReceived);
		GameEventDispatcher.AddListener(GameEventType.RadioMessageRead, OnRadioMessageRead);
		FilterToggle[] toggles = _toggles;
		for (int i = 0; i < toggles.Length; i++)
		{
			toggles[i].Toggle.onValueChanged.AddListener(ToggleFilter);
		}
	}

	private void Start()
	{
		if (Community.PlayerCommunity == null)
		{
			return;
		}
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent != null)
			{
				OnAgentAddedToCommunity(agent);
			}
		}
	}

	private void LateUpdate()
	{
		if (_updateFilter)
		{
			Filter = Filters.None;
			FilterToggle[] toggles = _toggles;
			for (int i = 0; i < toggles.Length; i++)
			{
				FilterToggle filterToggle = toggles[i];
				if (filterToggle.Toggle.isOn)
				{
					Filter = filterToggle.Filter;
				}
			}
			_sortPortraits = true;
			_updateFilter = false;
		}
		if (_sortPortraits)
		{
			SortPortraits();
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnAgentPortraitAdded);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRemovedFromPlayerCommunity, OnAgentRemoved);
		GameEventDispatcher.RemoveListener(GameEventType.RadioMessageReceived, OnRadioMessageReceived);
		GameEventDispatcher.RemoveListener(GameEventType.RadioMessageRead, OnRadioMessageRead);
		FilterToggle[] toggles = _toggles;
		for (int i = 0; i < toggles.Length; i++)
		{
			toggles[i].Toggle.onValueChanged.RemoveAllListeners();
		}
	}

	public void ToggleFilter(bool value)
	{
		_updateFilter = true;
	}

	public void ShowOverview()
	{
		_portraitSelectableGroup.gameObject.SetActive(value: true);
		_portraitSelectableGroup.Initialize(clearSelected: true);
	}

	public void HideOverview()
	{
		_portraitSelectableGroup.gameObject.SetActive(value: false);
	}

	private void OnAgentAddedToCommunity(Agent agent)
	{
		if (AddAgentPortrait(agent))
		{
			_sortPortraits = true;
			agent.Morale.UpdatedEvent.AddListener(OnAgentMoraleUpdated);
		}
	}

	private void OnAgentPortraitAdded(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent)
		{
			OnAgentAddedToCommunity(agentEvent.Agent);
		}
	}

	private void OnRadioMessageReceived(GameEvent gameEvent)
	{
		if (gameEvent is RadioMessageEvent radioMessageEvent)
		{
			AddRadioMessagePortrait(radioMessageEvent.Message);
		}
	}

	private void OnRadioMessageRead(GameEvent gameEvent)
	{
		RadioMessageEvent radioEvent = gameEvent as RadioMessageEvent;
		if (radioEvent != null && _radioMessagePortraits.TryFind((RadioMessageSenderPortrait message) => message.Message == radioEvent.Message, out var instance))
		{
			_radioMessagePortraits.Remove(instance);
		}
	}

	private void OnAgentRemoved(GameEvent gameEvent)
	{
		AgentEvent agentEvent = gameEvent as AgentEvent;
		if (agentEvent != null && _drifterPortraits.TryFind((DrifterOverviewPortrait portrait) => portrait.Drifter == agentEvent.Agent, out var instance))
		{
			agentEvent.Agent.Morale.UpdatedEvent.RemoveListener(OnAgentMoraleUpdated);
			instance.Clear();
			_drifterPortraits.Remove(instance);
		}
	}

	private bool AddAgentPortrait(Agent agent)
	{
		if (agent.Community.CommunityType != Community.Type.Player || _drifterPortraits.TryFind((DrifterOverviewPortrait portrait) => portrait.gameObject.activeSelf && portrait.Drifter == agent, out var _))
		{
			return false;
		}
		_drifterPortraits.Get().Initialize(agent, this);
		return true;
	}

	private void AddRadioMessagePortrait(RadioMessage message)
	{
		_radioMessagePortraits.Get(Filter == Filters.RadioMessage).Initialize(message);
	}

	private void SortPortraits()
	{
		_sortedPortraits.Clear();
		_sortedPortraits.AddRange(_drifterPortraits.Instances);
		Sorting.SlowSort(_sortedPortraits, this);
		for (int i = 0; i < _sortedPortraits.Count; i++)
		{
			DrifterOverviewPortrait drifterOverviewPortrait = _sortedPortraits[i];
			drifterOverviewPortrait.transform.SetSiblingIndex(i);
			drifterOverviewPortrait.EvaluateEnabled(Filter);
		}
		bool active = Filter == Filters.RadioMessage;
		foreach (RadioMessageSenderPortrait instance in _radioMessagePortraits.Instances)
		{
			instance.gameObject.SetActive(active);
		}
		_portraitSelectableGroup.Initialize(clearSelected: true);
		_sortPortraits = false;
	}

	private void OnAgentMoraleUpdated()
	{
		_sortPortraits = true;
	}

	public int Compare(DrifterOverviewPortrait x, DrifterOverviewPortrait y)
	{
		bool flag = x.Drifter;
		bool flag2 = y.Drifter;
		if (flag && flag2)
		{
			switch (Filter)
			{
			case Filters.Morale:
				return x.Drifter.Morale.CurrentMorale - y.Drifter.Morale.CurrentMorale;
			case Filters.Thirst:
				return y.Drifter.Vitals.Thirst.Amount - x.Drifter.Vitals.Thirst.Amount;
			case Filters.Hunger:
				return y.Drifter.Vitals.Hunger.Amount - x.Drifter.Vitals.Hunger.Amount;
			case Filters.Leveled:
				return y.Drifter.Attributes.SpendablePoints - x.Drifter.Attributes.SpendablePoints;
			case Filters.Pollution:
			{
				float num = y.Drifter.Vitals.Pollution.Level - x.Drifter.Vitals.Pollution.Level;
				if (num < 0f)
				{
					return -1;
				}
				if (0f < num)
				{
					return 1;
				}
				return 0;
			}
			default:
				return 0;
			}
		}
		if (flag == flag2)
		{
			return 0;
		}
		if (flag)
		{
			return -1;
		}
		return 1;
	}
}
public class DrifterOverviewDiet : AgentReferenceUIElement
{
	[SerializeField]
	private VitalType _vital;

	[SerializeField]
	private ChildBehaviourCache<InventoryPanelItemSlot> _itemSlotPrefab;

	[SerializeField]
	[Tooltip("The base size used for the slots other than the slot for the current day.\r\n NOTE: Previous Day Slot Size and Previous Day Slot Size Decrease are applied to all slots other than the first slot, which is the slot for the current day.")]
	private float _previousDaySlotSize = 42f;

	[SerializeField]
	[Tooltip("The amount by which the slots other than the slot for the current day are decreased.\r\n NOTE: Previous Day Slot Size and Previous Day Slot Size Decrease are applied to all slots other than the first slot, which is the slot for the current day.")]
	private float _previousDaySlotSizeDecrease = 2f;

	private Diet _diet;

	protected override void Subscribe(Agent agent)
	{
		if (agent.Vitals.TryReturnDiet(VitalType.Hunger, out _diet))
		{
			UpdateItemSlots();
		}
	}

	protected override void Unsubscribe(Agent agent)
	{
	}

	private void UpdateItemSlots()
	{
		_itemSlotPrefab.Reset();
		if (0 < _diet.ConsumedItems.Count)
		{
			_itemSlotPrefab.Get(active: true).Initialize(_diet.ReturnItemConsumedToday());
			for (int i = 1; i < _diet.ConsumedItems.Count; i++)
			{
				InventoryPanelItemSlot inventoryPanelItemSlot = _itemSlotPrefab.Get(active: true);
				inventoryPanelItemSlot.Initialize(_diet.ConsumedItems[i]);
				inventoryPanelItemSlot.SetSize(i, _previousDaySlotSize, _previousDaySlotSizeDecrease);
			}
		}
		_itemSlotPrefab.Trim();
	}
}
public class DrifterOverviewPortrait : SceneBehaviour, IAgentReference
{
	[SerializeField]
	private OutlinedImage _drifterImage;

	[SerializeField]
	private Image _statusImage;

	[SerializeField]
	private GameObject _mortalDangerWarning;

	[SerializeField]
	private TextMeshProUGUI _nameText;

	[SerializeField]
	private GameObject _pollutionBar;

	[SerializeField]
	private Slider _pollutionSlider;

	[SerializeField]
	private Image _moraleImage;

	[SerializeField]
	private Color _selectedColor = Color.white;

	private DrifterOverview _overview;

	public Agent Drifter { get; private set; }

	public Agent AgentReference => Drifter;

	public UnityEvent OnAgentUpdated { get; private set; } = new UnityEvent();

	public void Initialize(Agent drifter, DrifterOverview overview)
	{
		RemoveListeners();
		Drifter = drifter;
		UpdatePortrait(Drifter.Descriptor);
		OnAgentUpdated.Invoke();
		_overview = overview;
		AddListeners();
		base.gameObject.SetActive(value: true);
	}

	private void OnDestroy()
	{
		RemoveListeners();
		OnAgentUpdated.RemoveAllListeners();
	}

	public void EvaluateEnabled(DrifterOverview.Filters filter)
	{
		base.gameObject.SetActive((bool)Drifter && ReturnIsEnabledWithFilter(filter));
		_moraleImage.gameObject.SetActive(filter == DrifterOverview.Filters.Morale);
		_pollutionBar.gameObject.SetActive(filter == DrifterOverview.Filters.Pollution);
	}

	public void Clear()
	{
		RemoveListeners();
		Drifter = null;
		base.gameObject.SetActive(value: false);
	}

	private void UpdateMortalDanger()
	{
		_mortalDangerWarning.SetActive((bool)Drifter && Drifter.Vitals.IsInMortalDanger());
	}

	private void AddListeners()
	{
		GameEventDispatcher.AddListener(GameEventType.AgentPortraitGenerated, UpdatePortrait);
		if ((bool)Drifter)
		{
			Drifter.OnAssignmentUpdatedEvent.AddListener(UpdateProject);
			UpdateProject();
			Drifter.Descriptor.UpdatedEvent.AddListener(UpdateName);
			UpdateName(Drifter.Descriptor);
			Drifter.Vitals.Pollution.Updated.AddListener(UpdatePollution);
			UpdatePollution();
			Drifter.Morale.UpdatedEvent.AddListener(UpdateMorale);
			UpdateMorale();
			Drifter.Vitals.Hunger.Updated.AddListener(UpdateMortalDanger);
			Drifter.Vitals.Thirst.Updated.AddListener(UpdateMortalDanger);
			UpdateMortalDanger();
		}
	}

	private void RemoveListeners()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentPortraitGenerated, UpdatePortrait);
		if (!(Drifter == null))
		{
			Drifter.OnAssignmentUpdatedEvent.RemoveListener(UpdateProject);
			Drifter.Descriptor.UpdatedEvent.RemoveListener(UpdateName);
			Drifter.Vitals.Pollution.Updated.RemoveListener(UpdatePollution);
			Drifter.Vitals.Hunger.Updated.RemoveListener(UpdateMortalDanger);
			Drifter.Vitals.Thirst.Updated.RemoveListener(UpdateMortalDanger);
			Drifter.Morale.UpdatedEvent.RemoveListener(UpdateMorale);
		}
	}

	private void UpdateProject(Agent agent = null)
	{
		if (Drifter.Assignment == null || Drifter.Assignment.Project == null)
		{
			_statusImage.gameObject.SetActive(value: false);
			return;
		}
		_statusImage.gameObject.SetActive(value: true);
		_statusImage.sprite = Drifter.Assignment.Project.Properties.Icon;
	}

	private void UpdatePollution()
	{
		_pollutionSlider.value = Drifter.Vitals.Pollution.LevelNormalized;
	}

	private void UpdatePortrait(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent)
		{
			UpdatePortrait(agentEvent.AgentDescriptor);
		}
	}

	private void UpdatePortrait(AgentDescriptor descriptor)
	{
		if (descriptor == Drifter.Descriptor && PortraitGenerator.HasStaticPortrait(descriptor))
		{
			_drifterImage.Initialize(PortraitGenerator.ReturnStaticPortrait(descriptor));
		}
	}

	private void UpdateMorale()
	{
		if (Drifter.Morale.TryReturnCurrentCategory(out var category))
		{
			_moraleImage.sprite = category.Icon;
		}
	}

	public void LockDrifter()
	{
		if (!(Drifter == null) && UIManager.State == UIState.Normal)
		{
			switch (_overview.Filter)
			{
			case DrifterOverview.Filters.Leveled:
				GameManager.UIManager.DisplayPanel(PanelID.ExpertisePanel, Drifter);
				break;
			case DrifterOverview.Filters.Morale:
				Selector.Select(Drifter.gameObject, ObjectType.CommunityMember);
				UIEvent.Dispatch(UIEvent.Type.ToggleAgentPanelMoraleTab);
				break;
			default:
				Selector.Select(Drifter.gameObject, ObjectType.CommunityMember);
				break;
			}
		}
	}

	public void Select()
	{
		_drifterImage.OverrideOutlineColor(_selectedColor);
	}

	public void Deselect()
	{
		_drifterImage.RestoreOutlineColor();
	}

	private void UpdateName(ActorDescriptor actorDescriptor)
	{
		_nameText.text = Drifter.Name;
	}

	private bool ReturnIsEnabledWithFilter(DrifterOverview.Filters filter)
	{
		switch (filter)
		{
		case DrifterOverview.Filters.Morale:
			return true;
		case DrifterOverview.Filters.MortalDanger:
			return Drifter.Vitals.IsInMortalDanger();
		case DrifterOverview.Filters.Disease:
			return Drifter.Vitals.Pollution.CurrentDisease != null;
		case DrifterOverview.Filters.Thirst:
			return 0 < Drifter.Vitals.Thirst.Amount;
		case DrifterOverview.Filters.Hunger:
			return 0 < Drifter.Vitals.Hunger.Amount;
		case DrifterOverview.Filters.Message:
			return Drifter.ReturnHasMessageQueued();
		case DrifterOverview.Filters.Leveled:
			return 0 < Drifter.Attributes.SpendablePoints;
		case DrifterOverview.Filters.Homeless:
			return Drifter.ReservedHouse == null;
		case DrifterOverview.Filters.Pollution:
			return 0f < Drifter.Vitals.Pollution.Level;
		case DrifterOverview.Filters.RadioMessage:
		case DrifterOverview.Filters.None:
			return false;
		default:
			throw new NotImplementedException();
		}
	}
}
