public class DrifterExpertiseRow : MonoBehaviour, IAgentReference, IPointerEnterHandler, IEventSystemHandler
{
	[SerializeField]
	private TextMeshProUGUI _levelField;

	[SerializeField]
	private Slider _levelProgressField;

	[SerializeField]
	private ChildBehaviourCache<DrifterExpertiseField> _expertiseFieldCache;

	[SerializeField]
	private Transition _transition;

	private DrifterExpertiseField _selectedExpertise;

	private int _selectedExpertiseIndex = -1;

	private int _spendPoints;

	public Agent AgentReference { get; private set; }

	public UnityEvent OnAgentUpdated { get; private set; } = new UnityEvent();

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentExperienceGained, OnDrifterEvent);
	}

	public void Initialize(Agent drifter, List<DrifterAttributes.AttributeType> attributes)
	{
		AgentReference = drifter;
		OnAgentUpdated.Invoke();
		_spendPoints = 0;
		_expertiseFieldCache.Reset();
		foreach (DrifterAttributes.AttributeType attribute in attributes)
		{
			_expertiseFieldCache.Get(active: true).Initialize(drifter, attribute);
		}
		_expertiseFieldCache.Trim();
		GameEventDispatcher.RemoveListener(GameEventType.AgentExperienceGained, OnDrifterEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentExperienceGained, OnDrifterEvent);
		UpdateFields();
	}

	public int Select(int index)
	{
		SelectBox(index);
		_transition.SetSelected();
		return _selectedExpertiseIndex;
	}

	public int SelectLeft(int index)
	{
		return SelectBox(index - 1);
	}

	public int SelectRight(int index)
	{
		return SelectBox(index + 1);
	}

	public void Deselect()
	{
		if ((bool)_selectedExpertise)
		{
			_selectedExpertise.OnDeselect();
			_selectedExpertise = null;
		}
		_selectedExpertiseIndex = -1;
		_transition.SetNormal();
	}

	public void IncreaseSelected()
	{
		if (0 < AgentReference.Attributes.SpendablePoints && (bool)_selectedExpertise && _selectedExpertise.Increase())
		{
			_spendPoints++;
			UpdateFields();
		}
	}

	public void DecreaseSelected()
	{
		if (0 < _spendPoints && (bool)_selectedExpertise && _selectedExpertise.Decrease())
		{
			_spendPoints--;
			UpdateFields();
		}
	}

	public void Apply()
	{
		foreach (DrifterExpertiseField instance in _expertiseFieldCache.Instances)
		{
			instance.Apply();
		}
		_spendPoints = 0;
	}

	private int SelectBox(int index)
	{
		index = Mathf.Clamp(index, 0, _expertiseFieldCache.Instances.Count - 1);
		if (index == _selectedExpertiseIndex)
		{
			return index;
		}
		DrifterExpertiseField drifterExpertiseField = _expertiseFieldCache.Instances[index];
		if (drifterExpertiseField == null)
		{
			return _selectedExpertiseIndex;
		}
		if ((bool)_selectedExpertise)
		{
			_selectedExpertise.OnDeselect();
		}
		_selectedExpertiseIndex = index;
		_selectedExpertise = drifterExpertiseField;
		_selectedExpertise.OnSelect();
		return index;
	}

	private void OnDrifterEvent(GameEvent gameEvent)
	{
		if (gameEvent is AgentFloatEvent agentFloatEvent && agentFloatEvent.Agent == AgentReference)
		{
			UpdateFields();
		}
	}

	private void UpdateFields()
	{
		_levelField.text = AgentReference.Attributes.Level.ToString();
		_levelProgressField.value = AgentReference.Attributes.ReturnNormalizedExperience();
	}

	public void OnPointerEnter(PointerEventData pointerEventData)
	{
		AgentEvent.Dispatch(GameEventType.AgentFullscreenPanelRefresh, AgentReference);
	}
}
public class DrifterFieldInfo : MonoBehaviour
{
	[SerializeField]
	private Image _icon;

	[SerializeField]
	private TextMeshProUGUI _title;

	[SerializeField]
	private TextMeshProUGUI _description;

	[SerializeField]
	private TextMeshProUGUI _tooltip;

	private bool _initialized;

	private void Awake()
	{
		Initialize();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentAttributeInfo, OnInfoEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentAssignmentInfo, OnInfoEvent);
	}

	public void Initialize()
	{
		if (!_initialized)
		{
			GameEventDispatcher.AddListener(GameEventType.AgentAttributeInfo, OnInfoEvent);
			GameEventDispatcher.AddListener(GameEventType.AgentAssignmentInfo, OnInfoEvent);
			GameEventDispatcher.AddListener(GameEventType.AgentDietInfo, OnInfoEvent);
			_initialized = true;
		}
	}

	private void OnInfoEvent(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent { EventType: var eventType } agentEvent)
		{
			switch (eventType)
			{
			case GameEventType.AgentAttributeInfo:
				SetAttributeInfo(agentEvent.Agent, agentEvent.Attribute);
				break;
			case GameEventType.AgentAssignmentInfo:
				SetAssignmentInfo(agentEvent.Agent, agentEvent.AssignmentType);
				break;
			case GameEventType.AgentDietInfo:
				SetDietInfo(agentEvent.ItemProperties);
				break;
			}
		}
	}

	private void SetAttributeInfo(Agent agent, DrifterAttributes.AttributeType attributeType)
	{
		DrifterAttributes.Attribute attribute = agent.Attributes.ReturnAttribute(attributeType);
		if (attribute != null)
		{
			_icon.sprite = attribute.Icon;
			_title.text = $"{attribute.Name} - {agent.Attributes.ReturnTotalAttributePoints(attributeType)}";
			_description.text = attribute.Description;
			_tooltip.text = DrifterAttributes.ReturnDetailedTooltipText(agent.Attributes, attribute, attributeType);
		}
	}

	private void SetAssignmentInfo(Agent agent, AssignmentType assignmentType)
	{
		AssignmentSetting assignmentSetting = GameManager.Settings.ProjectSettings.ReturnAssignmentSetting(assignmentType);
		if (!(assignmentSetting == null))
		{
			_icon.sprite = assignmentSetting.Sprite;
			_title.text = assignmentSetting.Name;
			_description.text = assignmentSetting.Description;
			_tooltip.text = assignmentSetting.GetTooltip((agent != null) ? agent.Attributes : AgentDescriptor.GetProperties().AttributeProperties);
		}
	}

	private void SetDietInfo(ItemProperties itemProperties)
	{
		_icon.sprite = itemProperties.InventorySprite;
		_title.text = itemProperties.LocalizedName;
		_description.text = itemProperties.ReturnCategory();
		_tooltip.text = itemProperties.ReturnStats();
	}
}
