[RequireComponent(typeof(Selectable))]
public class SelectionStateManager : MonoBehaviour, ISelectHandler, IEventSystemHandler, IDeselectHandler, IPointerEnterHandler, IPointerExitHandler, IPointerDownHandler, IPointerUpHandler
{
	public enum SelectionState
	{
		Normal,
		Highlighted,
		Pressed,
		Selected,
		Disabled
	}

	private Selectable _selectable;

	private SelectionState _selectionState;

	private bool _interactable;

	private bool _selected;

	private bool _highlighted;

	private bool _pressed;

	public UnityEvent<SelectionState> SelectionStateChangedEvent { get; private set; } = new UnityEvent<SelectionState>();

	private void Awake()
	{
		_selectable = GetComponent<Selectable>();
		_interactable = IsInteractable();
		UpdateSelectionState();
	}

	private void LateUpdate()
	{
		bool flag = IsInteractable();
		if (flag != _interactable)
		{
			_interactable = flag;
			UpdateSelectionState();
		}
	}

	public void OnSelect(BaseEventData eventData)
	{
		_selected = true;
		UpdateSelectionState();
	}

	public void OnDeselect(BaseEventData eventData)
	{
		_selected = false;
		UpdateSelectionState();
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		_highlighted = true;
		UpdateSelectionState();
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		_highlighted = false;
		UpdateSelectionState();
	}

	public void OnPointerDown(PointerEventData eventData)
	{
		_pressed = true;
		UpdateSelectionState();
	}

	public void OnPointerUp(PointerEventData eventData)
	{
		_pressed = false;
		UpdateSelectionState();
	}

	private void UpdateSelectionState()
	{
		if (_interactable)
		{
			if (_highlighted)
			{
				if (_pressed)
				{
					SetSelectionState(SelectionState.Pressed);
				}
				else
				{
					SetSelectionState(SelectionState.Highlighted);
				}
			}
			else if (_selected)
			{
				SetSelectionState(SelectionState.Selected);
			}
			else
			{
				SetSelectionState(SelectionState.Normal);
			}
		}
		else
		{
			SetSelectionState(SelectionState.Disabled);
		}
	}

	private void SetSelectionState(SelectionState selectionStateToSet)
	{
		if (selectionStateToSet != _selectionState)
		{
			_selectionState = selectionStateToSet;
			SelectionStateChangedEvent.Invoke(_selectionState);
			UnityEngine.Debug.LogFormat("Selection State change to: {0}", _selectionState);
		}
	}

	private bool IsInteractable()
	{
		if (_selectable.enabled)
		{
			return _selectable.interactable;
		}
		return false;
	}
}
[RequireComponent(typeof(Graphic))]
public class SelectionStates : MonoBehaviour
{
	[SerializeField]
	private ColorBlock _colorBlock;

	private SelectionStateManager _manager;

	private Graphic _target;

	private void Awake()
	{
		_manager = GetComponentInParent<SelectionStateManager>();
		if (_manager == null)
		{
			UnityEngine.Debug.LogWarning("SelectionStates component is not nested under a SelectionStateManager!");
			return;
		}
		_manager.SelectionStateChangedEvent.AddListener(OnSelectionStateChanged);
		_target = GetComponent<Graphic>();
	}

	private void OnDestroy()
	{
		if ((bool)_manager)
		{
			_manager.SelectionStateChangedEvent.RemoveListener(OnSelectionStateChanged);
		}
	}

	private void OnSelectionStateChanged(SelectionStateManager.SelectionState selectionState)
	{
		switch (selectionState)
		{
		case SelectionStateManager.SelectionState.Normal:
			_target.color = _colorBlock.normalColor;
			break;
		case SelectionStateManager.SelectionState.Highlighted:
			_target.color = _colorBlock.highlightedColor;
			break;
		case SelectionStateManager.SelectionState.Pressed:
			_target.color = _colorBlock.pressedColor;
			break;
		case SelectionStateManager.SelectionState.Selected:
			_target.color = _colorBlock.selectedColor;
			break;
		case SelectionStateManager.SelectionState.Disabled:
			_target.color = _colorBlock.disabledColor;
			break;
		}
	}

	public void SetSelectionState(SelectionStateManager.SelectionState selectionState)
	{
	}
}
