public class SliderInteractions : MonoBehaviour
{
	private enum State
	{
		Stopped,
		Increase,
		Decrease
	}

	[SerializeField]
	private Slider _slider;

	[SerializeField]
	private int _progressInteractionThreshold = 10;

	[SerializeField]
	private float _regressInterval = 1f;

	[SerializeField]
	private float[] _values = new float[4] { 1f, 10f, 100f, 1000f };

	private State _state;

	private int _valueIndex;

	private int _interactCount;

	private float _stoppedTimestamp;

	private void LateUpdate()
	{
		float realtimeSinceStartup = Time.realtimeSinceStartup;
		if (_state == State.Stopped && 0 < _valueIndex && _regressInterval < realtimeSinceStartup - _stoppedTimestamp)
		{
			_valueIndex--;
			_stoppedTimestamp = realtimeSinceStartup;
		}
	}

	public void Increase()
	{
		SetState(State.Increase);
		AddValue(GetValue());
	}

	public void Decrease()
	{
		SetState(State.Decrease);
		AddValue(0f - GetValue());
	}

	public void Stop()
	{
		SetState(State.Stopped);
		_stoppedTimestamp = Time.realtimeSinceStartup;
	}

	private void SetState(State state)
	{
		if (_state != state)
		{
			_state = state;
			_interactCount = 0;
		}
	}

	private void AddValue(float amount)
	{
		_slider.value = Mathf.Clamp(MathExtensions.AddAndRoundToMultiple(_slider.value, amount), 0f, _slider.maxValue);
		_interactCount++;
		if (_progressInteractionThreshold <= _interactCount && _valueIndex < _values.Length - 1)
		{
			_valueIndex++;
			_interactCount = 0;
		}
	}

	private float GetValue()
	{
		if (_valueIndex < _values.Length)
		{
			return _values[_valueIndex];
		}
		return 0f;
	}
}
public class TMP_InputFieldNavigationWrapper : Selectable, ISubmitHandler, IEventSystemHandler
{
	[Header("Input Field Navigation Wrapper")]
	[SerializeField]
	private TMP_InputField _inputField;

	[SerializeField]
	private LocalizedString _description;

	[SerializeField]
	[Tooltip("Should the InputField no longer be selected after the player has stopped editing?")]
	private bool _deselectOnEndEdit;

	private RewiredStandaloneInputModule _inputModule;

	private bool _isFocused;

	private UIState _uiState;

	public bool IsBeingEdited { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if (Application.isPlaying)
		{
			_inputModule = EventSystem.current.currentInputModule as RewiredStandaloneInputModule;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		_inputField.onSelect.AddListener(InputField_OnSelect);
	}

	private void LateUpdate()
	{
		if (_isFocused)
		{
			if (FlotsamInputManager.GetButtonDown(_inputModule.SubmitActionId))
			{
				Finish(wasCanceled: false);
			}
			else if (FlotsamInputManager.GetButtonDown(_inputModule.CancelActionId))
			{
				Finish(wasCanceled: true);
			}
		}
		_isFocused = _inputField.isFocused;
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		_inputField.onSelect.AddListener(InputField_OnSelect);
		_inputField.onDeselect.RemoveListener(InputField_OnDeselect);
		_inputField.onEndEdit.RemoveListener(OnEndEdit);
	}

	private void Finish(bool wasCanceled)
	{
		if (!wasCanceled)
		{
			_inputField.onSubmit.Invoke(_inputField.text);
		}
		_inputField.DeactivateInputField(_deselectOnEndEdit);
		if (_deselectOnEndEdit)
		{
			Deselect();
		}
		FinalUpdate.RegisterEndOfFrameOneShot(ResetUIState);
	}

	private void InputField_OnSelect(string value)
	{
		if (UIManager.State != UIState.Typing)
		{
			SetUIStateTyping();
			_inputField.onDeselect.AddListener(InputField_OnDeselect);
		}
	}

	private void InputField_OnDeselect(string value)
	{
		_inputField.onDeselect.RemoveListener(InputField_OnDeselect);
		ResetUIState();
	}

	public void SetText(string text)
	{
		if (IsBeingEdited)
		{
			Finish(wasCanceled: false);
		}
		_inputField.text = text;
	}

	public void OnSubmit(BaseEventData eventData)
	{
		if (Session.Platform.ItHandlesTextInput)
		{
			TextInputRequest.SingleLine(_description, (uint)_inputField.characterLimit, _inputField.text, OnTextInputCompleted);
			return;
		}
		_inputField.Select();
		_inputField.onEndEdit.AddListener(OnEndEdit);
		SetUIStateTyping();
	}

	private void OnTextInputCompleted(TextInputRequest input)
	{
		if (input.Succes)
		{
			_inputField.text = input.Text;
		}
	}

	private void OnEndEdit(string text)
	{
		_inputField.onEndEdit.RemoveListener(OnEndEdit);
		_isFocused = false;
		if (_deselectOnEndEdit)
		{
			Deselect();
		}
		else
		{
			Select();
		}
		FinalUpdate.RegisterEndOfFrameOneShot(ResetUIState);
	}

	private void Deselect()
	{
		EventSystem current = EventSystem.current;
		if ((bool)current && current.currentSelectedGameObject == _inputField.gameObject)
		{
			current.SetSelectedGameObject(null);
		}
	}

	private void SetUIStateTyping()
	{
		if (UIManager.State != UIState.Typing)
		{
			IsBeingEdited = true;
			_uiState = UIManager.State;
			UIManager.SetState(UIState.Typing);
		}
	}

	private void ResetUIState()
	{
		IsBeingEdited = false;
		if (UIManager.State == UIState.Typing)
		{
			UIManager.SetState(_uiState);
		}
	}
}
public class AnimatedToggle : PLToggle
{
	[Header("Animated Toggle")]
	[Tooltip("The name of the bool parameter that is set on the Animator.")]
	[SerializeField]
	private string _isOnParameter = "IsOn";

	[SerializeField]
	[Tooltip("The name of the bool parameter that is set on the Animator.")]
	private string _interactableParameter = "Interactable";

	[SerializeField]
	[Tooltip("The name of the bool parameter that is set on the Animator.")]
	private string _completedParameter = "Completed";

	private bool _animatorIsOn;

	protected override void OnEnable()
	{
		base.OnEnable();
		SetAnimatorBool();
	}

	protected override void LateUpdate()
	{
		base.LateUpdate();
		if (_animatorIsOn != base.isOn)
		{
			SetAnimatorBool();
		}
		UpdateParameters();
	}

	public override void Initialize(IToggleable toggleable)
	{
		base.Initialize(toggleable);
		SetAnimatorBool();
		UpdateParameters();
	}

	public void SetCompleted()
	{
		if (!(base.animator == null) && !base.animator.GetBool(_completedParameter))
		{
			base.animator?.SetBool(_completedParameter, value: true);
		}
	}

	protected override void OnValueChanged(bool value)
	{
		base.OnValueChanged(value);
		SetAnimatorBool();
	}

	private void SetAnimatorBool()
	{
		_animatorIsOn = base.isOn;
		if (base.transition == Transition.Animation)
		{
			base.animator?.SetBool(_isOnParameter, base.isOn);
		}
	}

	private void UpdateParameters()
	{
		if (base.Toggleable != null)
		{
			if (base.Toggleable.IsCompleted)
			{
				SetCompleted();
			}
			base.animator?.SetBool(_interactableParameter, base.Toggleable.IsInteractable);
		}
	}

	public override void OnSelect(BaseEventData eventData)
	{
		if (FlotsamInputManager.IsJoystick)
		{
			base.OnSelect(eventData);
		}
	}

	public override void OnDeselect(BaseEventData eventData)
	{
		if (FlotsamInputManager.IsJoystick)
		{
			base.OnDeselect(eventData);
		}
	}
}
public interface IToggleable
{
	bool IsInteractable { get; }

	bool IsCompleted { get; }

	bool IsToggled { get; }

	void Toggle();
}
public class PLToggle : Toggle
{
	[Serializable]
	private struct SettingsBlock
	{
		public InputFlags Inputs;

		public bool ToggleOnSeleced;

		public bool StopSelectPropagation;

		public bool BlockSubmit;
	}

	[Header("Pajama Llama Toggle")]
	[SerializeField]
	[NamedArrayElement(new string[] { "Inputs" })]
	private SettingsBlock[] _settings;

	[SerializeField]
	private ActionBase _isOnAction;

	[SerializeField]
	[Tooltip("Enable this to invoke onValueChanged when the Toggle is enabled. This is usefull to make sure gameObjects that are set active/inactive on value changed are in the right state. ")]
	private bool _onEnableInvokeValueChanged;

	public IToggleable Toggleable { get; private set; }

	public bool ToggleOnSelected
	{
		get
		{
			if (TryGetSettings(FlotsamInputManager.ActiveInput, out var settings))
			{
				return settings.ToggleOnSeleced;
			}
			return false;
		}
	}

	public bool StopSelectPropagation
	{
		get
		{
			if (TryGetSettings(FlotsamInputManager.ActiveInput, out var settings))
			{
				return settings.StopSelectPropagation;
			}
			return false;
		}
	}

	public bool BlockSubmit
	{
		get
		{
			if (TryGetSettings(FlotsamInputManager.ActiveInput, out var settings))
			{
				return settings.BlockSubmit;
			}
			return false;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (_onEnableInvokeValueChanged)
		{
			onValueChanged.Invoke(base.isOn);
		}
		onValueChanged?.AddListener(OnValueChanged);
	}

	protected virtual void LateUpdate()
	{
		if (_isOnAction != null && _isOnAction.IsSelected && !base.isOn)
		{
			SetIsOnWithoutNotify(value: true);
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		onValueChanged?.RemoveListener(OnValueChanged);
	}

	public override void OnSubmit(BaseEventData eventData)
	{
		if (!BlockSubmit)
		{
			base.OnSubmit(eventData);
		}
	}

	public override void OnSelect(BaseEventData eventData)
	{
		if (!StopSelectPropagation)
		{
			base.OnSelect(eventData);
		}
		if (ToggleOnSelected)
		{
			base.isOn = true;
		}
	}

	public virtual void Initialize(IToggleable toggleable)
	{
		Toggleable = toggleable;
		if (Toggleable != null)
		{
			SetIsOnWithoutNotify(Toggleable.IsToggled);
			if (Toggleable.IsToggled && (bool)_isOnAction)
			{
				_isOnAction.Trigger();
			}
		}
	}

	public void ToggleIfInteractable()
	{
		if (base.interactable)
		{
			base.isOn = !base.isOn;
		}
	}

	public void SetIsOnIfInteractable(bool value)
	{
		if (base.interactable && base.isOn != value)
		{
			base.isOn = value;
		}
	}

	protected virtual void OnValueChanged(bool value)
	{
		Toggleable?.Toggle();
		if (value && (bool)_isOnAction)
		{
			_isOnAction.Trigger();
		}
	}

	private bool TryGetSettings(InputFlags inputFlags, out SettingsBlock settings)
	{
		for (int i = 0; i < _settings.Length; i++)
		{
			settings = _settings[i];
			if ((settings.Inputs & inputFlags) != InputFlags.None)
			{
				return true;
			}
		}
		settings = default(SettingsBlock);
		return false;
	}
}
