	private Toggle _target;

	[SerializeField]
	private SelectableGroup _targetSelectableGroup;

	[SerializeField]
	private bool _withoutNotify = true;

	private void OnEnable()
	{
		if ((bool)_target)
		{
			if (_withoutNotify)
			{
				_target.SetIsOnWithoutNotify(value: true);
			}
			else
			{
				_target.isOn = true;
