public class UIComponent : UIBehaviour, IMoveHandler, IEventSystemHandler, IPointerDownHandler, IPointerUpHandler, IPointerEnterHandler, IPointerExitHandler, ISelectHandler, IDeselectHandler
{
	[SerializeField]
	private bool _interactable = true;

	[SerializeField]
	private Transition _transition;

	[SerializeField]
	private PointerEventData.InputButton _mouseButton;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _inputActionId = -1;

	[Tooltip("The input modes in which the component can be selected")]
	[SerializeField]
	private InputFlags _selectableInputs = InputFlags.All;

	private int _inputActionIdOverride = -1;

	private bool _hasPointer;

	private bool _hasPointerDown;

	private bool _hasButton;

	private bool _hasSelection;

	public bool Interactable
	{
		get
		{
			if (base.isActiveAndEnabled)
			{
				return _interactable;
			}
			return false;
		}
		set
		{
			if (_interactable != value)
			{
				_interactable = value;
				UpdateTransition();
			}
		}
	}

	public int InputActionId
	{
		get
		{
			if (_inputActionIdOverride != -1)
			{
				return _inputActionIdOverride;
			}
			return _inputActionId;
		}
	}

	public bool Selectable => (FlotsamInputManager.ActiveInput & _selectableInputs) != 0;

	protected override void OnEnable()
	{
		base.OnEnable();
		UpdateTransition();
		if (_selectableInputs != InputFlags.All)
		{
			GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		}
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		_hasPointer = false;
		_hasPointerDown = false;
		_hasButton = false;
		_hasSelection = false;
		if (_selectableInputs != InputFlags.All)
		{
			GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		}
	}

	private void LateUpdate()
	{
		bool button = FlotsamInputManager.GetButton(InputActionId);
		if (button != _hasButton)
		{
			_hasButton = button;
			UpdateTransition();
		}
	}

	public void UpdateTransition()
	{
		if (!Interactable)
		{
			_transition.SetDisabled();
		}
		else if ((_hasSelection && _hasButton) || (_hasPointer && _hasPointerDown))
		{
			_transition.SetPressed();
		}
		else if (Selectable && _hasSelection)
		{
			_transition.SetSelected();
		}
		else if (_hasPointer)
		{
			_transition.SetHighlighted();
		}
		else
		{
			_transition.SetNormal();
		}
	}

	public void SetAnimatorTrigger(string trigger)
	{
		_transition.SetAnimatorTrigger(trigger);
	}

	public void SetAnimatorBool(string name, bool value)
	{
		_transition.SetAnimatorBool(name, value);
	}

	public void SetAnimatorInteger(string name, int value)
	{
		_transition.SetAnimatorInteger(name, value);
	}

	private void OnActiveInputUpdated(GameEvent gameEvent)
	{
		UpdateTransition();
	}

	public void OnMove(AxisEventData eventData)
	{
		throw new NotImplementedException();
	}

	public virtual void OnPointerEnter(PointerEventData eventData)
	{
		_hasPointer = true;
		UpdateTransition();
	}

	public virtual void OnPointerExit(PointerEventData eventData)
	{
		_hasPointer = false;
		UpdateTransition();
	}

	public void OnPointerDown(PointerEventData eventData)
	{
		if (eventData.button == _mouseButton)
		{
			_hasPointerDown = true;
			UpdateTransition();
		}
	}

	public void OnPointerUp(PointerEventData eventData)
	{
		if (eventData.button == _mouseButton)
		{
			_hasPointerDown = false;
			UpdateTransition();
		}
	}

	public virtual void OnSelect(BaseEventData eventData = null)
	{
		_hasSelection = true;
		UpdateTransition();
	}

	public virtual void OnDeselect(BaseEventData eventData = null)
	{
		_hasSelection = false;
		UpdateTransition();
	}
}
public class UIFlagSetter : MonoBehaviour, IUIFlagsProvider
{
	public enum ReleaseCondition
	{
		None,
		Delay,
		LeftStickRelease,
		RightStickRelese
	}

	[SerializeField]
	private InputFlags _activeInputs = InputFlags.All;

	[SerializeField]
	private PanelContainerFlags _panelContainerFlags;

	[SerializeField]
	private bool _blockRewired;

	[SerializeField]
	private bool _blockCancel;

	[SerializeField]
	private ReleaseCondition _releaseCondition;

	[SerializeField]
	[ConditionalEnumHide("_releaseCondition", 1, false, HideInInspector = true)]
	private float _delay;

	[SerializeField]
	[ConditionalEnumHide("_releaseCondition", 2, false, EnumValue2 = 3, HideInInspector = true)]
	private float _threshold = 0.1f;

	private bool _isDelayedRelease;

	private float _delayTime;

	public PanelContainerFlags Flags => _panelContainerFlags;

	public bool BlockCancel => _blockCancel;

	private void OnEnable()
	{
		OnActiveInputUpdated();
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
	}

	private void OnDisable()
	{
		if (_releaseCondition == ReleaseCondition.None)
		{
			if (_blockRewired)
			{
				RewiredComponent.Unblock();
			}
			UIManager.RemoveFlagsProvider(this);
		}
		else
		{
			_isDelayedRelease = true;
			_delayTime = 0f - Time.unscaledDeltaTime;
			FinalUpdate.Register(OnUpdateDelay);
		}
		GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
	}

	private void OnUpdateDelay()
	{
		switch (_releaseCondition)
		{
		case ReleaseCondition.Delay:
			_delayTime += Time.unscaledDeltaTime;
			if (_delay <= _delayTime)
			{
				Release();
			}
			break;
		case ReleaseCondition.LeftStickRelease:
			if (FlotsamInputManager.GetLeftStick().magnitude <= _threshold)
			{
				Release();
			}
			break;
		case ReleaseCondition.RightStickRelese:
			if (FlotsamInputManager.GetRightStick().magnitude <= _threshold)
			{
				Release();
			}
			break;
		}
	}

	private void Release()
	{
		FinalUpdate.Unregister(OnUpdateDelay);
		if (_blockRewired)
		{
			RewiredComponent.Unblock();
		}
		UIManager.RemoveFlagsProvider(this);
		_isDelayedRelease = false;
	}

	private void OnActiveInputUpdated(GameEvent gameEvent = null)
	{
		if (base.isActiveAndEnabled && FlotsamInputManager.HasActiveInput(_activeInputs))
		{
			if (_isDelayedRelease)
			{
				Release();
			}
			if (_blockRewired)
			{
				RewiredComponent.Block();
			}
			if (FlotsamInputManager.HasActiveInput(_activeInputs))
			{
				UIManager.AddFlagsProvider(this);
			}
		}
		else
		{
			Release();
		}
	}
}
public class Crosshair : MonoBehaviour
{
	[SerializeField]
	private string _hoverTrigger = "Hover";

	[SerializeField]
	private string _normalTrigger = "Normal";

	[SerializeField]
	private Image _iconImage;

	[SerializeField]
	[NamedArrayElement(new string[] { "CursorState" })]
	private CursorStateSprite[] _cursorStateSprites;

	private static Crosshair _instance;

	private bool _active;

	private bool _blocked;

	private CursorState _cursorState;

	private Animator _animator;

	private CursorContext _context;

	private void Awake()
	{
		if ((bool)_instance && _instance != this)
		{
			UnityEngine.Object.Destroy(this);
			return;
		}
		_instance = this;
		_animator = GetComponent<Animator>();
		GameEventDispatcher.AddListener(GameEventType.GameStartedLoading, OnGameStartedLoading);
		GameEventDispatcher.AddListener(GameEventType.GameStart, OnGameStart);
		if (LoadingScreen.IsLoading)
		{
			OnGameStartedLoading();
		}
	}

	private void OnEnable()
	{
		i_SetContext(_context);
	}

	private void LateUpdate()
	{
		if (!(_context == null) && !(_iconImage.sprite == _context.CrosshairIcon))
		{
			SetCrosshairIcon(_context.CrosshairIcon);
		}
	}

	private void OnDisable()
	{
		i_SetContext(null);
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStartedLoading, OnGameStartedLoading);
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnGameStart);
	}

	private void OnGameStartedLoading(GameEvent gameEvent = null)
	{
		base.gameObject.SetActive(value: false);
	}

	private void OnGameStart(GameEvent gameEvent)
	{
		SetActive(_active);
	}

	private void i_SetContext(CursorContext context)
	{
		if (!(context == _context))
		{
			_context = context;
			_cursorState = CursorState.Normal;
			if ((bool)_context)
			{
				SetCrosshairIcon(context.CrosshairIcon);
				SetAnimatorTrigger(_hoverTrigger);
			}
			else
			{
				SetAnimatorTrigger(_normalTrigger);
			}
		}
	}

	private void i_SetCursorState(CursorState cursorState)
	{
		if (_cursorState == cursorState)
		{
			return;
		}
		_cursorState = cursorState;
		CursorStateSprite[] cursorStateSprites = _cursorStateSprites;
		for (int i = 0; i < cursorStateSprites.Length; i++)
		{
			CursorStateSprite cursorStateSprite = cursorStateSprites[i];
			if (cursorStateSprite.CursorState == cursorState)
			{
				SetCrosshairIcon(cursorStateSprite.Sprite);
				SetAnimatorTrigger(_hoverTrigger);
				return;
			}
		}
		SetCrosshairIcon(null);
		SetAnimatorTrigger(_normalTrigger);
	}

	private void SetActive(bool value)
	{
		_active = value;
		base.gameObject.SetActive(value && !_blocked && !LoadingScreen.IsLoading);
	}

	private void i_SetBlocked(bool value)
	{
		if (_blocked != value)
		{
			_blocked = value;
			SetActive(_active);
		}
	}

	private void SetCrosshairIcon(Sprite icon)
	{
		if ((bool)icon)
		{
			_iconImage.sprite = icon;
			_iconImage.enabled = true;
		}
		else
		{
			_iconImage.sprite = null;
			_iconImage.enabled = false;
		}
	}

	private void SetAnimatorTrigger(string name)
	{
		_animator.ResetTrigger(_normalTrigger);
		_animator.ResetTrigger(_hoverTrigger);
		_animator.SetTrigger(name);
	}

	public static void Enable()
	{
		_instance?.SetActive(value: true);
	}

	public static void SetBlocked(bool value)
	{
		_instance?.i_SetBlocked(value);
	}

	public static void SetContext(CursorContext context)
	{
		_instance?.i_SetContext(context);
	}

	public static void SetCursorState(CursorState cursorState)
	{
		_instance?.i_SetCursorState(cursorState);
	}

	public static void Disable()
	{
		_instance?.SetActive(value: false);
	}
}
