public abstract class SegmentBar<T> : MonoBehaviour where T : UIBehaviour
{
	[SerializeField]
	private T _segmentPrefab;

	private List<T> _segments;

	public void SetValue(int value, int max)
	{
		UpdateBar(value, max);
	}

	private void UpdateBar(int value, int max)
	{
		if (_segments == null)
		{
			_segments = new List<T>();
		}
		foreach (T segment in _segments)
		{
			segment.gameObject.SetActive(value: false);
		}
		for (int i = 0; i < max; i++)
		{
			T val = ReturnSegment();
			InitializeSegment(val, i);
			if (i < value)
			{
				SetActive(val);
			}
			else
			{
				SetInactive(val);
			}
		}
	}

	protected virtual void InitializeSegment(T segment, int index)
	{
		segment.gameObject.SetActive(value: true);
	}

	protected abstract void SetActive(T segment);

	protected abstract void SetInactive(T segment);

	private T ReturnSegment()
	{
		if (_segments == null)
		{
			_segments = new List<T>();
		}
		foreach (T segment in _segments)
		{
			if (!segment.gameObject.activeSelf)
			{
				return segment;
			}
		}
		T val = UnityEngine.Object.Instantiate(_segmentPrefab, base.transform);
		_segments.Add(val);
		return val;
	}
}
public class ImageThresholdBar : ThresholdBar<Image>
{
}
public abstract class ThresholdBar<T> : UIBehaviour where T : UIBehaviour
{
	[SerializeField]
	private T _segmentPrefab;

	[UnityEngine.UI.Extensions.ReadOnly]
	[SerializeField]
	private float _barWidth;

	private List<Tuple<T, float>> _segmentSizes = new List<Tuple<T, float>>();

	private float _totalWidth;

	private List<T> _segments = new List<T>();

	protected override void OnRectTransformDimensionsChange()
	{
		_barWidth = (base.transform as RectTransform).rect.width;
		UpdateSegmentSizes();
	}

	public T Add(float size)
	{
		_totalWidth += size;
		T val = ReturnSegment();
		_segmentSizes.Add(new Tuple<T, float>(val, size));
		UpdateSegmentSizes();
		return val;
	}

	public void Clear()
	{
		_totalWidth = 0f;
		foreach (T segment in _segments)
		{
			segment.gameObject.SetActive(value: false);
		}
	}

	private void UpdateSegmentSizes()
	{
		foreach (Tuple<T, float> segmentSize in _segmentSizes)
		{
			RectTransform rectTransform = segmentSize.Item1.transform as RectTransform;
			if (rectTransform == null)
			{
				UnityEngine.Debug.LogError("Thresholdbar tried to get rect transform of prefab but was unable. Make sure prefab has rect transform.");
				continue;
			}
			Vector2 sizeDelta = rectTransform.sizeDelta;
			sizeDelta.x = segmentSize.Item2 / _totalWidth * _barWidth;
			rectTransform.sizeDelta = sizeDelta;
		}
	}

	private T ReturnSegment()
	{
		foreach (T segment in _segments)
		{
			if (!segment.gameObject.activeSelf)
			{
				segment.gameObject.SetActive(value: true);
				return segment;
			}
		}
		T val = UnityEngine.Object.Instantiate(_segmentPrefab, base.transform);
		val.name = "Segment";
		_segments.Add(val);
		return val;
	}
}
