public class ItemCounter : SceneBehaviour
{
	[Header("Properties")]
	[Tooltip("Item properties this counter will use to count. If null the tags will be used for counting")]
	[SerializeField]
	private ItemProperties _itemToCount;

	[Tooltip("Tag this counter will count.")]
	[EnumFlag(1)]
	[SerializeField]
	private Item.Tags _tagToCount;

	[Tooltip("The threshold will be multiplied with the agent count to make sure every agent has enough items.")]
	[SerializeField]
	private bool _thresholdPerAgent;

	[Tooltip("Amount threshold to show warning.")]
	[SerializeField]
	private int _warningThreshold = 5;

	[Header("Components")]
	[Tooltip("Text component for the counter.")]
	[SerializeField]
	private TextMeshProUGUI _text;

	private float _amount = -1f;

	private Animator _animator;

	private void Start()
	{
		_animator = GetComponentInChildren<Animator>();
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.AddListener(UpdateCounter);
		UpdateCounter();
	}

	private void OnDestroy()
	{
		if (Community.PlayerCommunity != null)
		{
			Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.RemoveListener(UpdateCounter);
		}
	}

	private void UpdateCounter()
	{
		bool flag = false;
		UpdateAmount();
		flag = ((!_thresholdPerAgent) ? (_amount < (float)_warningThreshold) : (_amount < (float)(Community.PlayerCommunity.Agents.Count * _warningThreshold)));
		if (_animator != null)
		{
			_animator.SetBool("Warning", flag);
		}
	}

	private void UpdateAmount()
	{
		float num = ((((_tagToCount & Item.Tags.Drink) | Item.Tags.Liquid) != Item.Tags.None) ? Community.PlayerCommunity.Inventory.ReturnNutritionalValue(_tagToCount) : (((_tagToCount & Item.Tags.Food) != Item.Tags.None) ? Community.PlayerCommunity.Inventory.ReturnNutritionalValue(_tagToCount) : ((!(_itemToCount == null)) ? ((float)Community.PlayerCommunity.Inventory.ReturnCount(_itemToCount)) : ((float)Community.PlayerCommunity.Inventory.ReturnItemContainingTagCount(_tagToCount)))));
		if (num != _amount)
		{
			_amount = num;
			_text.text = _amount.ToString();
		}
	}
}
public class NewGamePanel : Panel
{
	[SerializeField]
	private TownheartSelector _townheartSelector;

	[SerializeField]
	private CharacterSelector _characterSelector;

	public override void Initialize()
	{
		base.gameObject.SetActive(value: true);
		GameManager.UIManager.DisableUI();
		GameManager.UIManager.PauseGame(UIState.GameTimePaused);
		if ((bool)_townheartSelector && _townheartSelector.Activate())
		{
			TownheartSelector townheartSelector = _townheartSelector;
			townheartSelector.TownheartSelected = (UnityAction)Delegate.Combine(townheartSelector.TownheartSelected, new UnityAction(OnTownheartSelected));
		}
		else
		{
			OnTownheartSelected();
		}
		CameraController.Instance.LoadPreset();
	}

	public void StartGame()
	{
		base.gameObject.SetActive(value: false);
		GameManager.UIManager.EnableUI();
		GameManager.UIManager.UnpauseGame();
		CharacterPreview[] agentPreviews = _characterSelector.AgentPreviews;
		foreach (CharacterPreview characterPreview in agentPreviews)
		{
			GameManager.AgentManager.SpawnStartingAgent(characterPreview.AgentDescriptor);
		}
		Community.PlayerCommunity?.QueueGlobalProjects(GameSettings.Instance.ProjectSettings);
		GameEventDispatcher.Dispatch(GameEventType.NewGamePanelClosed);
	}

	private void OnTownheartSelected()
	{
		if ((bool)_townheartSelector)
		{
			TownheartSelector townheartSelector = _townheartSelector;
			townheartSelector.TownheartSelected = (UnityAction)Delegate.Remove(townheartSelector.TownheartSelected, new UnityAction(OnTownheartSelected));
		}
		_characterSelector.gameObject.SetActive(value: true);
		_characterSelector.Initialize();
	}
}
