[RequireComponent(typeof(RectTransform), typeof(Image))]
public class SelectionFrame : MonoBehaviour
{
	private RectTransform _rectTransform;

	private Image _image;

	private Vector3 _anchor = Vector3.zero;

	private Rect _rect = Rect.zero;

	private bool _selectionFrameActive;

	private void Awake()
	{
		_rectTransform = GetComponentInChildren<RectTransform>();
		_image = GetComponentInChildren<Image>(includeInactive: true);
	}

	private void LateUpdate()
	{
		if (_selectionFrameActive && UnityEngine.Input.GetMouseButtonUp(0))
		{
			GameManager.UIManager.SelectionFrame.HideFrame();
			PajamaLlama.Debugs.Debugger.Warning("Selection frame should have been hidden. failsafe activated.");
		}
	}

	public void InitializeFrame(Vector3 anchor)
	{
		_anchor = anchor;
		_selectionFrameActive = true;
	}

	public void DrawSelectionFrame(Vector3 mousePosition)
	{
		Vector2 vector = _anchor;
		Vector2 vector2 = mousePosition;
		float num = mousePosition.x - _anchor.x;
		float num2 = mousePosition.y - _anchor.y;
		if (num < 0f)
		{
			vector.x = mousePosition.x;
			vector2.x = _anchor.x;
		}
		if (num2 < 0f)
		{
			vector.y = mousePosition.y;
			vector2.y = _anchor.y;
		}
		_rect.min = base.transform.InverseTransformVector(vector);
		_rect.max = base.transform.InverseTransformVector(vector2);
		_rectTransform.position = (_anchor + mousePosition) / 2f;
		_rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rect.width);
		_rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _rect.height);
		_image.enabled = Vector3.Distance(_anchor, mousePosition) > 12f;
	}

	public void HideFrame()
	{
		if (_selectionFrameActive)
		{
			_image.enabled = false;
			_selectionFrameActive = false;
		}
	}
}
public class StoredBuildableCreation : BuildableCreation
{
	public override void Initialize(GameEvent gameEvent = null)
	{
		base.Initialize(gameEvent);
		Community.PlayerCommunity.OnStoredBuildableAdded.AddListener(IncrementStoredBuildableToggle);
		Community.PlayerCommunity.OnStoredBuildableRemoved.AddListener(DecrementStoredBuildableToggle);
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		Community.PlayerCommunity.OnStoredBuildableAdded.RemoveListener(IncrementStoredBuildableToggle);
		Community.PlayerCommunity.OnStoredBuildableRemoved.RemoveListener(DecrementStoredBuildableToggle);
	}

	protected override void MakeCreationToggles()
	{
		for (int i = 0; i < GameManager.Settings.BuildableSettings.Buildables.Length; i++)
		{
			MakeStoredBuildableToggle(GameManager.Settings.BuildableSettings.Buildables[i]);
		}
		foreach (KeyValuePair<BuildableProperties, List<Buildable>> storedBuildable in Community.PlayerCommunity.StoredBuildables)
		{
			IncrementStoredBuildableToggle(storedBuildable.Key, storedBuildable.Value.Count);
		}
		foreach (KeyValuePair<DecorationProperties, List<Decoration>> storedDecoration in Community.PlayerCommunity.StoredDecorations)
		{
			if (storedDecoration.Key is EnergyPoleDecorationProperties)
			{
				IncrementStoredBuildableToggle(storedDecoration.Key, storedDecoration.Value.Count);
			}
		}
	}

	private void MakeStoredBuildableToggle(IPlaceable placeable)
	{
		if (!placeable.Category)
		{
			return;
		}
		using List<BuildableCreationCategoryToggle>.Enumerator enumerator = _categoryToggles.GetEnumerator();
		while (enumerator.MoveNext() && !enumerator.Current.TryAddStoredBuildableToggle(placeable))
		{
		}
	}

	public void IncrementStoredBuildableToggle(IPlaceable placeable, bool toggleCategory = true)
	{
		IncrementStoredBuildableToggle(placeable, 1, toggleCategory);
	}

	public void IncrementStoredBuildableToggle(IPlaceable placeable, int amount, bool toggleCategory = true)
	{
		if (!TryReturnCategoryToggle(placeable.Category, out var categoryToggle))
		{
			return;
		}
		if (placeable is BuildableProperties buildableProperties && buildableProperties == GameManager.Settings.BuildableSettings.EnergyPoleBuildableProperties)
		{
			placeable = GameManager.Settings.BuildableSettings.EnergyPoleDecorationProperties;
		}
		foreach (BuildableToggle buildableToggle in categoryToggle.BuildableToggles)
		{
			if (buildableToggle.Placeable == placeable)
			{
				if (buildableToggle is StoredBuildableToggle storedBuildableToggle)
				{
					storedBuildableToggle.Add(amount);
				}
				if (toggleCategory)
				{
					categoryToggle.SetEnabled(enabled: true, isOn: true);
				}
				UpdateCategories();
				break;
			}
		}
	}

	public void DecrementStoredBuildableToggle(IPlaceable placeable)
	{
		DecrementStoredBuildableToggle(placeable, 1);
	}

	public void DecrementStoredBuildableToggle(IPlaceable placeable, int amount)
	{
		if (!TryReturnCategoryToggle(placeable.Category, out var categoryToggle))
		{
			return;
		}
		if (placeable is BuildableProperties buildableProperties && buildableProperties == GameManager.Settings.BuildableSettings.EnergyPoleBuildableProperties)
		{
			placeable = GameManager.Settings.BuildableSettings.EnergyPoleDecorationProperties;
		}
		bool flag = true;
		foreach (BuildableToggle buildableToggle in categoryToggle.BuildableToggles)
		{
			if (buildableToggle is StoredBuildableToggle storedBuildableToggle)
			{
				if (storedBuildableToggle.Placeable == placeable)
				{
					storedBuildableToggle.Remove(amount);
				}
				if (storedBuildableToggle.Count > 0)
				{
					flag = false;
				}
			}
		}
		if (flag)
		{
			categoryToggle.isOn = false;
			UpdateCategories();
		}
	}
}
public class IntField : MonoBehaviour
{
	private enum Sign
	{
		NegativeOnly,
		NegativeAndPositive,
		NegativeAndPositiveZeroExcluded,
		None
	}

	private enum RangeType
	{
		Range,
		SmallerThen,
		LargerThen
	}

	[Serializable]
	private struct ColorRange
	{
		public RangeType RangeType;

		public int from;

		[ConditionalEnumHide("RangeType", 0, false)]
		public int to;

		public Color Color;

		public bool IsInRange(int value)
		{
			switch (RangeType)
			{
			case RangeType.Range:
				if (from <= value)
				{
					return value <= to;
				}
				return false;
			case RangeType.SmallerThen:
				return value < from;
			case RangeType.LargerThen:
				return from < value;
			default:
				throw new NotImplementedException();
			}
		}
	}

	[SerializeField]
	protected TextMeshProUGUI _text;

	[SerializeField]
	private Sign _sign;

	[SerializeField]
	private ColorRange[] _colorRanges;

	public void SetInt(int value, bool activate = true)
	{
		switch (_sign)
		{
		case Sign.NegativeOnly:
			_text.text = value.ToString();
			break;
		case Sign.NegativeAndPositive:
			_text.text = ((value < 0) ? value.ToString() : $"+{value}");
			break;
		case Sign.NegativeAndPositiveZeroExcluded:
			_text.text = ((value <= 0) ? value.ToString() : $"+{value}");
			break;
		case Sign.None:
			_text.text = Mathf.Abs(value).ToString();
			break;
		}
		if (activate)
		{
			base.gameObject.SetActive(value: true);
		}
		if (((IReadOnlyCollection<ColorRange>)(object)_colorRanges).IsNullOrEmpty())
		{
			return;
		}
		ColorRange[] colorRanges = _colorRanges;
		for (int i = 0; i < colorRanges.Length; i++)
		{
			ColorRange colorRange = colorRanges[i];
			if (colorRange.IsInRange(value))
			{
				_text.color = colorRange.Color;
			}
		}
	}

	public void SetFloat(float value)
	{
		SetInt(Mathf.RoundToInt(value));
	}
}
public class TextField : MonoBehaviour
{
	public enum States
	{
		Neutral,
		Positive,
		Negative
	}

	[Serializable]
	private struct StateColor
	{
		public States State;

		public Color Color;
	}

	[SerializeField]
	protected TextMeshProUGUI _text;

	[NamedArrayElement(new string[] { "State" })]
	[SerializeField]
	private StateColor[] _stateColors;

	private Color _defaultColor;

	private void Awake()
	{
		_defaultColor = _text.color;
	}

	public void SetText(string text, bool activate = true)
	{
		_text.text = text;
		if (activate)
		{
			base.gameObject.SetActive(value: true);
		}
	}

	public void SetText(string text, States state, bool activate = true)
	{
		SetText(text, activate);
		StateColor[] stateColors = _stateColors;
		for (int i = 0; i < stateColors.Length; i++)
		{
			StateColor stateColor = stateColors[i];
			if (stateColor.State == state)
			{
				_text.color = stateColor.Color;
				return;
			}
		}
		UnityEngine.Debug.LogWarningFormat("No color defined for State '{0}'", state);
		_text.color = _defaultColor;
	}
}
