public class TownEnergySliderTracker : TownEnergyTracker
{
	[SerializeField]
	private Slider _energySlider;

	[SerializeField]
	private TextMeshProUGUI _energyAmountText;

	[SerializeField]
	private bool _showEnergyAsPercentage = true;

	[SerializeField]
	private Image _border;

	[SerializeField]
	private Color _borderColorCooldown;

	[SerializeField]
	[Range(1f, 100f)]
	private float _borderColorLerpSpeed = 5f;

	[SerializeField]
	private Image _bar;

	[SerializeField]
	private Color _barColorCooldown;

	private Color _borderColorDefault;

	private Color _barColorDefault;

	private float _currentValue;

	private float _currentValueMax;

	protected override void Awake()
	{
		base.Awake();
		_borderColorDefault = _border.color;
		_barColorDefault = _bar.color;
	}

	protected override void Update()
	{
		base.Update();
		if (Engine.IsCoolingDown)
		{
			float num = Engine.CooldownStartTime - Time.realtimeSinceStartup;
			_border.color = Color.Lerp(_borderColorDefault, _borderColorCooldown, (Mathf.Cos(num * _borderColorLerpSpeed) + 1f) / 2f);
		}
		else
		{
			_border.color = _borderColorDefault;
		}
	}

	public override void SetValue(float value, float valueMax)
	{
		if (_currentValue != value || _currentValueMax != valueMax)
		{
			_currentValue = value;
			_currentValueMax = valueMax;
			float num = ((valueMax > 0f) ? (value / valueMax) : 0f);
			_energySlider.value = num;
			_energyAmountText.text = (_showEnergyAsPercentage ? $"{num:0%}" : $"{value:F0}/{valueMax:F0}");
		}
	}
}
public abstract class TownEnergyTracker : SceneBehaviour
{
	private enum Mode
	{
		Energy,
		Distance
	}

	[SerializeField]
	private Mode _mode;

	protected virtual void Update()
	{
		Engine engine = Community.PlayerCommunity.Engine;
		if ((bool)engine)
		{
			float num = engine.EnergyGrid.ReturnStorageEnergy();
			float num2 = engine.EnergyGrid.ReturnStorageCapacity();
			switch (_mode)
			{
			case Mode.Energy:
				SetValue(num, num2);
				break;
			case Mode.Distance:
				SetValue(engine.ReturnEnergyRange(num), engine.ReturnEnergyRange(num2));
				break;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				break;
			}
		}
	}

	public abstract void SetValue(float value, float maxValue);
}
[RequireComponent(typeof(Animator))]
public class TownEnergyTrackerAnimationHandler : SceneBehaviour
{
	[SerializeField]
	private float _lowEnergyThreshold = 2000f;

	[SerializeField]
	private Image _border;

	[SerializeField]
	private Color _borderColorCooldown;

	[Range(1f, 100f)]
	[SerializeField]
	private float _borderColorLerpSpeed = 5f;

	private Animator _animator;

	private bool _isLowEnergy;

	private Color _borderColorDefault;

	protected override void Awake()
	{
		base.Awake();
		_borderColorDefault = _border.color;
	}

	private void Update()
	{
		float num = Community.PlayerCommunity.Engine.EnergyGrid.ReturnStorageEnergy();
		if (_isLowEnergy && num > _lowEnergyThreshold)
		{
			_isLowEnergy = false;
			_animator.SetBool("Is Low", _isLowEnergy);
		}
		else if (!_isLowEnergy && num <= _lowEnergyThreshold)
		{
			_isLowEnergy = true;
			_animator.SetBool("Is Low", _isLowEnergy);
		}
		if (Engine.IsCoolingDown)
		{
			float num2 = Engine.CooldownStartTime - Time.realtimeSinceStartup;
			_border.color = Color.Lerp(_borderColorDefault, _borderColorCooldown, (Mathf.Cos(num2 * _borderColorLerpSpeed) + 1f) / 2f);
		}
		else
		{
			_border.color = _borderColorDefault;
		}
	}

	private void OnEnable()
	{
		_animator = GetComponent<Animator>();
		float num = Community.PlayerCommunity.Engine.EnergyGrid.ReturnStorageEnergy();
		_isLowEnergy = num <= _lowEnergyThreshold;
		_animator.SetBool("Is Low", _isLowEnergy);
	}
}
