public class UIInteractableBuildableCategoryUnlockedRequirement : UIInteractableRequirementBase
{
	[SerializeField]
	private BuildableCreation.PlaceableFlags _categories;

	protected override void Awake()
	{
		base.Awake();
		GameEventDispatcher.AddListener(GameEventType.UnlockableUnlocked, UpdateInteractable);
	}

	private void Start()
	{
		UpdateInteractable();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.UnlockableUnlocked, UpdateInteractable);
	}

	private void UpdateInteractable(GameEvent gameEvent = null)
	{
		base.IsMet = ReturnIsMet();
		if (base.IsMet)
		{
			GameEventDispatcher.RemoveListener(GameEventType.UnlockableUnlocked, UpdateInteractable);
		}
	}

	public override bool ReturnIsMet()
	{
		if ((!_categories.HasFlag(BuildableCreation.PlaceableFlags.Buildables) || !(GameManager.Settings.BuildableSettings.Buildables.Find((BuildableProperties buildable) => buildable != null && buildable.IsUnlocked()) != null)) && (!_categories.HasFlag(BuildableCreation.PlaceableFlags.Decorations) || !(GameManager.Settings.BuildableSettings.Decorations.Find((DecorationProperties decoration) => decoration != null && decoration.IsUnlocked()) != null)))
		{
			if (_categories.HasFlag(BuildableCreation.PlaceableFlags.Utilities))
			{
				return GameManager.Settings.BuildableSettings.Utilties.Find((PlaceableUtilityProperties utility) => utility != null && utility.ReturnCanBePlaced(Community.PlayerCommunity)) != null;
			}
			return false;
		}
		return true;
	}
}
public class UIInteractableBuildableRequirement : UIInteractableRequirementBase
{
	public enum BuildableType
	{
		PropertiesList,
		Producer,
		ResearchStation
	}

	[SerializeField]
	private BuildableType _type;

	[SerializeField]
	[ConditionalEnumHide("_type", 0, false)]
	private List<BuildableProperties> _buildableProperties;

	private Selectable _selectable;

	protected override void Awake()
	{
		base.Awake();
		_selectable = GetComponent<Selectable>();
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, UpdateInteractable);
		GameEventDispatcher.AddListener(GameEventType.BuildableSalvaged, UpdateInteractable);
	}

	private void Start()
	{
		UpdateInteractable();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, UpdateInteractable);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableSalvaged, UpdateInteractable);
	}

	private void UpdateInteractable(GameEvent gameEvent = null)
	{
		base.IsMet = ReturnIsMet();
	}

	public override bool ReturnIsMet()
	{
		switch (_type)
		{
		case BuildableType.PropertiesList:
		{
			List<Buildable> buildables = Community.PlayerCommunity.Buildables;
			if (_buildableProperties.IsNullOrEmpty())
			{
				return true;
			}
			foreach (Buildable item in buildables)
			{
				if (_buildableProperties.Contains(item.Properties) && item.BuildPhase == BuildPhase.Finished)
				{
					return true;
				}
			}
			return false;
		}
		case BuildableType.Producer:
			return !Community.PlayerCommunity.Producers.IsNullOrEmpty();
		case BuildableType.ResearchStation:
