public class ListSelectableGroup<T> : SelectableGroup where T : Selectable
{
	public enum Orientation
	{
		Horizontal,
		Vertical
	}

	[Header("List Selectable Group")]
	[SerializeField]
	private Orientation _orientation = Orientation.Vertical;

	[SerializeField]
	private bool _invert;

	public List<T> List { get; private set; }

	public void Initialize(List<T> list)
	{
		List = list;
		base.Initialize();
	}

	public override void Initialize(bool clearSelected = false)
	{
		UnityEngine.Debug.LogException(new NotSupportedException("Use Initialize(List<T>) instead."));
	}

	protected override void SetFirstSelected()
	{
		if (!List.IsNullOrEmpty())
		{
			if (_invert)
			{
				Select(List[List.Count - 1]);
			}
			else
			{
				Select(List[0]);
			}
		}
	}

	protected override Selectable FindSelectableOnUp()
	{
		if (_orientation == Orientation.Vertical)
		{
			return FindSelectable(_invert ? 1 : (-1));
		}
		return null;
	}

	protected override Selectable FindSelectableOnRight()
	{
		if (_orientation == Orientation.Horizontal)
		{
			return FindSelectable((!_invert) ? 1 : (-1));
		}
		return null;
	}

	protected override Selectable FindSelectableOnDown()
	{
		if (_orientation == Orientation.Vertical)
		{
			return FindSelectable((!_invert) ? 1 : (-1));
		}
		return null;
	}

	protected override Selectable FindSelectableOnLeft()
	{
		if (_orientation == Orientation.Horizontal)
		{
			return FindSelectable(_invert ? 1 : (-1));
		}
		return null;
	}

	private Selectable FindSelectable(int direction)
	{
		if (List.IsNullOrEmpty() || !(base.Selected is T item))
		{
			return null;
		}
		int num = List.IndexOf(item) + direction;
		if (num < 0 || List.Count <= num)
		{
			return null;
		}
		return List[num];
	}
}
public class Notification : MonoBehaviour, IPointerClickHandler, IEventSystemHandler
{
	[Tooltip("Displayed image component for notification icon.")]
	[SerializeField]
	private Image _icon;

	[Tooltip("Text component of this notification.")]
	[SerializeField]
	private TextMeshProUGUI _text;

	[Tooltip("Time text component of this notification.")]
	[SerializeField]
	private TextMeshProUGUI _timeText;

	private bool _enabled = true;

	private Button _button;

	private Tooltip _tooltip;

	private UnityEvent _onLeftClick = new UnityEvent();

	private UnityEvent _onMiddleClick = new UnityEvent();

	private UnityEvent _onRightClick = new UnityEvent();

	public NotificationData Data { get; private set; }

	public bool InGameCanvas { get; private set; }

	public float TimeStamp { get; private set; }

	public static List<Notification> Notifications { get; private set; } = new List<Notification>();

	public void Initialize(NotificationData data, bool inGameCanvas)
	{
		_button = GetComponent<Button>();
		_tooltip = GetComponent<Tooltip>();
		Data = data;
		_icon.sprite = data.Properties.Icon;
		InGameCanvas = inGameCanvas;
		TimeStamp = data.Timestamp;
		if (_tooltip != null)
		{
			_tooltip.LocalizedText = Data.Properties.LocalizedDescription;
		}
		_text.text = Data.ToString();
		_timeText.text = GameManager.TimeManager.ReturnTimeInHoursMinutes(TimeStamp, includeUnits: false);
		_onLeftClick.AddListener(delegate
		{
			LeftClick();
		});
		_onRightClick.AddListener(delegate
		{
			RightClick();
		});
		AudioManager.Play(Data.Properties.Audio);
		_enabled = true;
		Notifications.Add(this);
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (_enabled)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				_onLeftClick.Invoke();
			}
			else if (eventData.button == PointerEventData.InputButton.Middle)
			{
				_onMiddleClick.Invoke();
			}
			else if (eventData.button == PointerEventData.InputButton.Right)
			{
				_onRightClick.Invoke();
			}
		}
	}

	public void Remove()
	{
		_enabled = false;
		UnityEngine.Object.Destroy(base.gameObject);
	}

	private void OnDestroy()
	{
		Notifications.Remove(this);
	}

	public void LeftClick()
	{
		if (!(Data.ObjectOfInterest.ToString() == "null"))
		{
			Data.ObjectOfInterest.NotificationLeftClick();
		}
	}

	public void RightClick()
	{
	}

	public void Enter()
	{
		_ = _enabled;
	}

	public void Exit()
	{
		_ = _enabled;
	}

	public void SetActive(bool active)
	{
		_button.interactable = active;
	}

	private void DeactivateButton(bool deactivate)
	{
		SetActive(!deactivate);
	}

	public static bool Exists(NotificationProperties properties, INotificationObjectOfInterest objectOfInterest)
	{
		List<Notification> notifications = Notifications;
		int count = notifications.Count;
		for (int i = 0; i < count; i++)
		{
			Notification notification = notifications[i];
			if (notification.Data.Properties == properties && notification.Data.ObjectOfInterest.IsMatch(objectOfInterest))
			{
				return true;
			}
		}
		return false;
	}
}
public abstract class NotificationBase : MonoBehaviour, IPointerClickHandler, IEventSystemHandler, ISelectHandler, IDeselectHandler
{
	[Header("Notification Base")]
	[SerializeField]
	protected TextMeshProUGUI _text;

	public static List<NotificationBase> ActiveNotifications = new List<NotificationBase>(8);

	public static NotificationBase SelectedNotification;

	private void OnEnable()
	{
		if (ActiveNotifications.AddUnique(this))
		{
			GameEventDispatcher.Dispatch(GameEventType.NotificationsUpdated);
		}
	}

	private void OnDisable()
	{
		if (ActiveNotifications.Remove(this))
		{
			GameEventDispatcher.Dispatch(GameEventType.NotificationsUpdated);
		}
	}

	public abstract void OnLeftClick();

	public abstract void OnRightClick();

	public void OnPointerClick(PointerEventData eventData)
	{
		switch (eventData.button)
		{
		case PointerEventData.InputButton.Left:
			OnLeftClick();
			break;
		case PointerEventData.InputButton.Right:
			OnRightClick();
			break;
		}
	}

	public void OnSelect(BaseEventData eventData)
	{
		SelectedNotification = this;
	}

	public void OnDeselect(BaseEventData eventData)
	{
		if (SelectedNotification == this)
		{
			SelectedNotification = null;
		}
	}
}
[Serializable]
public class NotificationData : IDisposable
{
	private static Queue<NotificationData> _instancePool = new Queue<NotificationData>();

	public NotificationProperties Properties { get; private set; }

	public INotificationObjectOfInterest ObjectOfInterest { get; private set; }

	public float Timestamp { get; private set; }

	public static List<NotificationData> Notifications { get; private set; } = new List<NotificationData>();

	private NotificationData()
	{
	}

	public static NotificationData Get(NotificationProperties notificationProperties, INotificationObjectOfInterest objectOfInterest, float timestamp)
	{
		if (!_instancePool.TryDequeue(out var result))
		{
			result = new NotificationData();
		}
		result.Properties = notificationProperties;
		result.ObjectOfInterest = objectOfInterest;
		result.Timestamp = timestamp;
		Notifications.Add(result);
		return result;
	}

	public static void Clear()
	{
		for (int num = Notifications.Count - 1; num >= 0; num--)
		{
			Notifications[num].Dispose();
		}
	}

	public void Dispose()
	{
		Notifications.Remove(this);
		_instancePool.Enqueue(this);
	}

	public override string ToString()
	{
		if (ObjectOfInterest != null)
		{
			return ObjectOfInterest.NotificationReplaceVariables(Properties.LocalizedDescription);
		}
		return Properties.LocalizedDescription;
	}
}
public class NotificationHandler : MonoBehaviour
{
	[Serializable]
	public class PersistentData
	{
		private readonly List<int> _notifiedNotificationsIDs;

		public PersistentData()
		{
			NotificationHandler notificationHandler = GameManager.UIManager.NotificationHandler;
			_notifiedNotificationsIDs = new List<int>((notificationHandler._notifiedNotifications.Count > 0) ? notificationHandler._notifiedNotifications.Count : 8);
			foreach (NotificationProperties notifiedNotification in notificationHandler._notifiedNotifications)
			{
				_notifiedNotificationsIDs.Add(GameManager.PersistenceManager.ReturnPropertiesIndex(notifiedNotification));
			}
		}

		public void Restore()
		{
			if (_notifiedNotificationsIDs.IsNullOrEmpty())
			{
				return;
			}
			NotificationHandler notificationHandler = GameManager.UIManager.NotificationHandler;
			notificationHandler._notifiedNotifications.Clear();
			foreach (int notifiedNotificationsID in _notifiedNotificationsIDs)
			{
				if (GameManager.PersistenceManager.TryReturnPropertiesReference<NotificationProperties>(notifiedNotificationsID, out var reference))
				{
					notificationHandler._notifiedNotifications.Add(reference);
				}
			}
		}
	}

	[Header("Notification Log")]
	[SerializeField]
	private NotificationLog _log;

	private readonly HashSet<NotificationProperties> _notifiedNotifications = new HashSet<NotificationProperties>();

	private void Start()
	{
		GameEventDispatcher.AddListener(GameEventType.MarkerDestroyed, AddMarkerFinishedNotification);
		GameEventDispatcher.AddListener(GameEventType.LandmarkActionCompleted, AddLandmarkActionCompletedNotification);
		GameEventDispatcher.AddListener(GameEventType.ResearchStationBuilt, AddResearchStationNotification);
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, AddSalvageRadiusIncreasedNotification);
		_notifiedNotifications.Remove(GameManager.Settings.UISettings.ResearchUnlockedNotification);
	}

	public void Clear()
	{
		_notifiedNotifications.Clear();
		NotificationData.Clear();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.MarkerDestroyed, AddMarkerFinishedNotification);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkActionCompleted, AddLandmarkActionCompletedNotification);
		GameEventDispatcher.RemoveListener(GameEventType.ResearchStationBuilt, AddResearchStationNotification);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, AddSalvageRadiusIncreasedNotification);
	}

	public void AddNotification(NotificationProperties properties, GameObject objectOfInterest, ObjectType objectOfInterestType)
	{
		AddNotification(properties, new DefaultObjectOfInterest(objectOfInterest, objectOfInterestType));
	}

	public void AddNotification(NotificationProperties properties, INotificationObjectOfInterest objectOfInterest)
	{
		if (!(properties == null) && !Notification.Exists(properties, objectOfInterest))
		{
			_notifiedNotifications.Add(properties);
			if (!properties.AudioOnly)
			{
				_log.AddNotification(properties, objectOfInterest, GameManager.TimeManager.ReturnTotalTimePlayed());
			}
			AudioManager.Play(properties.Audio);
		}
	}

	public void RestoreNotification(NotificationProperties properties, INotificationObjectOfInterest objectOfInterest, bool addCanvasNotification, float timeStamp)
	{
		_log.AddNotification(properties, objectOfInterest, timeStamp);
	}

	private void AddLandmarkActionCompletedNotification(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && (bool)landmarkNotificationEvent.LandmarkAction.CompletedNotification)
		{
			AddNotification(landmarkNotificationEvent.LandmarkAction.CompletedNotification, new LandmarkObjectOfInterest(landmarkNotificationEvent.LandmarkBehaviour));
		}
	}

	private void AddMarkerFinishedNotification(GameEvent gameEvent)
	{
		MarkerEvent markerEvent = gameEvent as MarkerEvent;
		if (!markerEvent.Marker.ManuallyRemoved)
		{
			if ((markerEvent.Marker.MarkerCursorProperties.AllowedItemTags & Item.Tags.FishMarker) != Item.Tags.None)
			{
				AddNotification(GameManager.Settings.UISettings.FishingMarkerFinishedNotification, markerEvent.Marker.gameObject, ObjectType.Marker);
			}
			else
			{
				AddNotification(GameManager.Settings.UISettings.SalvageMarkerFinishedNotification, markerEvent.Marker.gameObject, ObjectType.Marker);
			}
		}
	}

	private void AddResearchStationNotification(GameEvent gameEvent)
	{
		if (!_notifiedNotifications.Contains(GameManager.Settings.UISettings.ResearchUnlockedNotification))
		{
			_notifiedNotifications.Add(GameManager.Settings.UISettings.ResearchUnlockedNotification);
			AddNotification(GameManager.Settings.UISettings.ResearchUnlockedNotification, new DefaultObjectOfInterest(Community.PlayerCommunity.Research.ResearchStations[0].gameObject, ObjectType.Research));
		}
	}

	private void AddSalvageRadiusIncreasedNotification(GameEvent gameEvent)
	{
		if ((gameEvent as BuildableEvent).BuildableProperties.RequiresMooringPoint && Community.PlayerCommunity.ReturnAllBoats().Count == 1)
		{
			AddNotification(GameManager.Settings.UISettings.SalvageRadiusIncreasedNotification, new DefaultObjectOfInterest(Community.PlayerCommunity.ReturnAllBoats()[0].gameObject, ObjectType.None));
		}
	}
}
public class NotificationLog : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler, ScrollRectSelectionScroller.IProvider, IUIFlagsProvider, ICancelable
{
	[SerializeField]
	private int _lineHeight = 36;

	[SerializeField]
	private ScrollRect _scrollRect;

	[SerializeField]
	private LayoutElement _scrollRectLayoutElement;

	[SerializeField]
	private int _scrollRectMaxLines = 5;

	[SerializeField]
	private ChildBehaviourCache<NotificationLogLine> _lineCache;

	[SerializeField]
	private NotificationLogSelectableGroup _selectableGroup;

	[SerializeField]
	private float _maximumNotificationExpirationTime = 300f;

	[Header("UI Flags")]
	[SerializeField]
	private PanelContainerFlags _uiFlags;

	[SerializeField]
	private InputFlags _uiFlagsInputs = InputFlags.Joystick;

	private List<NotificationProperties> _propertiesList = new List<NotificationProperties>();

	private List<NotificationData> _notifications = new List<NotificationData>();

	private List<NotificationLogLine> _lines = new List<NotificationLogLine>();

	private float _scrollRectHeightMax;

	private float _scrollRectHeight;

	private HorizontalOrVerticalLayoutGroup _contentLayoutGroup;

	private LayoutElementTweener _layoutElementTweener;

	private Coroutine _openCloseCoroutine;

	private Scrollbar _verticalScrollBar;

	private bool _updateLines;

	public GameObject SelectedGameObject
	{
		get
		{
			if (!_selectableGroup || !_selectableGroup.Selected)
			{
				return null;
			}
			return _selectableGroup.Selected.gameObject;
		}
	}

	public bool IsOpen { get; private set; }

	public PanelContainerFlags Flags => _uiFlags;

	public bool BlockCancel => false;

	public float MaximumNotificationExpirationTime => _maximumNotificationExpirationTime;

	private void Awake()
	{
		_contentLayoutGroup = _scrollRect.content.GetComponent<HorizontalOrVerticalLayoutGroup>();
		_scrollRectHeightMax = GetLineCountHeight(_scrollRectMaxLines);
		_layoutElementTweener.SetTarget(_scrollRectLayoutElement);
		_verticalScrollBar = _scrollRect.verticalScrollbar;
		_verticalScrollBar.gameObject.SetActive(value: false);
		_scrollRect.verticalScrollbar = null;
		_scrollRectLayoutElement.minHeight = _lineHeight;
		_selectableGroup.Initialize(_lines);
	}

	private void LateUpdate()
	{
		float now = GameManager.TimeManager.ReturnTotalTimePlayed();
		int count = _notifications.Count;
		while (0 < count--)
		{
			NotificationData notificationData = _notifications[count];
			if (IsNotificationExpired(notificationData.Timestamp, notificationData.Properties.Expiration, now))
			{
				notificationData.Dispose();
				_notifications.RemoveAt(count);
				_updateLines = true;
			}
		}
		if (_updateLines)
		{
			UpdateLines();
		}
	}

	public bool AddNotification(NotificationProperties properties, INotificationObjectOfInterest objectOfInterest, float timestamp)
	{
		if (objectOfInterest.ObjectOfInterestType == ObjectType.Day && objectOfInterest is DayObjectOfInterest dayObjectOfInterest)
		{
			if (dayObjectOfInterest.DayIndex >= GameManager.TimeManager.Days.Count)
			{
				UnityEngine.Debug.LogException(new Exception($"Trying to restore a daily report for a day that did not happen ({dayObjectOfInterest.DayIndex + 1})!"));
				return false;
			}
			foreach (NotificationData notification in _notifications)
			{
				if (notification.ObjectOfInterest is DayObjectOfInterest dayObjectOfInterest2 && dayObjectOfInterest2.DayIndex == dayObjectOfInterest.DayIndex)
				{
					if (!LoadingScreen.IsLoading)
					{
						UnityEngine.Debug.LogException(new Exception($"A duplicate notification is being added for daily report {dayObjectOfInterest.DayIndex + 1}, this is a bug!"));
					}
					return false;
				}
			}
		}
		float num = GameManager.TimeManager.ReturnTotalTimePlayed();
		if (num < timestamp)
		{
			UnityEngine.Debug.LogException(new Exception($"A notification with timestamp {timestamp}, which is larger than the current play time ({num}), is being added tot the notfication log." + "Clamping it to the current play time"));
			timestamp = num;
		}
		if (properties == null || IsNotificationExpired(timestamp, properties.Expiration, num))
		{
			return false;
		}
		if (_propertiesList.AddUnique(properties))
		{
			UnityEngine.Debug.Log($"'{properties.name}' has expiration: {properties.Expiration}");
		}
		if (!base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: true);
		}
		_notifications.Add(NotificationData.Get(properties, objectOfInterest, timestamp));
		_updateLines = true;
		if (IsOpen)
		{
			Open();
		}
		else
		{
			_scrollRect.verticalNormalizedPosition = 1f;
		}
		return true;
	}

	public void RemoveNotification(NotificationData notification)
	{
		if (_notifications.Remove(notification))
		{
			notification.Dispose();
			_updateLines = true;
		}
	}

	public bool TryCancel()
	{
		Close();
		return true;
	}

	private void UpdateLines()
	{
		_lineCache.Reset();
		_lines.Clear();
		foreach (NotificationData notification in _notifications)
		{
			NotificationLogLine notificationLogLine = _lineCache.Get();
			notificationLogLine.Initialize(notification, this);
			notificationLogLine.interactable = IsOpen;
			_lines.Add(notificationLogLine);
		}
		_lineCache.Trim();
		_scrollRectHeight = Mathf.Min(GetLineCountHeight(_lines.Count), _scrollRectHeightMax);
		_updateLines = false;
		if (_notifications.Count == 0)
		{
			Close();
		}
	}

	private float GetLineCountHeight(int lineCount)
	{
		return Mathf.Max(_lineHeight, lineCount * _lineHeight);
	}

	private void SetLinesInteractable(bool interactable)
	{
		for (int i = 0; i < _lineCache.Count; i++)
		{
			_lineCache.Instances[i].interactable = interactable;
		}
	}

	public void Open()
	{
		if (_openCloseCoroutine != null)
		{
			StopCoroutine(_openCloseCoroutine);
		}
		_openCloseCoroutine = StartCoroutine(OpenRoutine());
	}

	public void Close()
	{
		if (_openCloseCoroutine != null)
		{
			StopCoroutine(_openCloseCoroutine);
		}
		_openCloseCoroutine = StartCoroutine(CloseRoutine());
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		_scrollRect.verticalNormalizedPosition = 1f;
		_scrollRect.gameObject.SetActive(value: true);
		Open();
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		Close();
	}

	private IEnumerator CloseRoutine()
	{
		IsOpen = false;
		_scrollRect.verticalScrollbar = null;
		_verticalScrollBar.gameObject.SetActive(value: false);
		_selectableGroup.enabled = false;
		FlotsamInputManager.RemoveCancelable(this);
		SetLinesInteractable(interactable: false);
		UIManager.RemoveFlagsProvider(this);
		_layoutElementTweener.InitializeProperty(LayoutElementTweener.Properties.PreferrredHeight, _lineHeight);
		yield return Tweener.TweenRoutine(0.1f, Easing.SineOut, true, _layoutElementTweener);
		_scrollRect.verticalNormalizedPosition = 1f;
	}

	private IEnumerator OpenRoutine()
	{
		SetLinesInteractable(interactable: true);
		_layoutElementTweener.InitializeProperty(LayoutElementTweener.Properties.PreferrredHeight, _scrollRectHeight);
		yield return Tweener.TweenRoutine(0.25f, Easing.SineIn, true, _layoutElementTweener);
		if (_scrollRectMaxLines < _lines.Count)
		{
			_scrollRect.verticalScrollbar = _verticalScrollBar;
		}
		_selectableGroup.enabled = true;
		FlotsamInputManager.PushCancelable(this);
		if (FlotsamInputManager.HasActiveInput(_uiFlagsInputs))
		{
			UIManager.AddFlagsProvider(this);
		}
		IsOpen = true;
	}

	private bool IsNotificationExpired(float timeStamp, float expirationTime, float now)
	{
		expirationTime = ((expirationTime <= 0f) ? _maximumNotificationExpirationTime : Mathf.Min(expirationTime, _maximumNotificationExpirationTime));
		return expirationTime < now - timeStamp;
	}
}
public class NotificationLogLine : Button
{
	[Header("Notification Log Line")]
	[SerializeField]
	private Image _icon;

	[SerializeField]
	private TextMeshProUGUI _label;

	public NotificationData Data { get; private set; }

	public NotificationLog Log { get; private set; }

	public void Initialize(NotificationData notification, NotificationLog log)
	{
		Data = notification;
		Log = log;
		if (Data == null)
		{
			_icon.overrideSprite = null;
			_label.gameObject.SetActive(value: false);
		}
		else
		{
			_icon.overrideSprite = notification.Properties.Icon;
			_label.gameObject.SetActive(value: true);
			_label.text = notification.ToString();
		}
		base.gameObject.SetActive(value: true);
	}

	public void Initialize(LocalizedString label)
	{
		_icon.overrideSprite = null;
		_label.text = label;
		base.gameObject.SetActive(value: true);
	}

	public override void OnSubmit(BaseEventData eventData)
	{
		if (base.currentSelectionState == SelectionState.Selected)
		{
			Data?.ObjectOfInterest?.NotificationLeftClick();
			base.OnSubmit(eventData);
			if (Data.Properties.CloseOnInteraction)
			{
				Log.RemoveNotification(Data);
			}
		}
	}

	public override void OnPointerClick(PointerEventData eventData)
	{
		if (Data != null)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				Data?.ObjectOfInterest?.NotificationLeftClick();
				if (Data.Properties.CloseOnInteraction)
				{
					Log.RemoveNotification(Data);
				}
			}
			else if (eventData.button == PointerEventData.InputButton.Right)
			{
				Log.RemoveNotification(Data);
			}
		}
		base.OnPointerClick(eventData);
	}
}
