		}
		return false;
	}
}
public class OutlinedImage : MonoBehaviour
{
	private const string MATERIAL_PROPERTY_OUTLINE_COLOR = "_OutlineColor";

	private const string MATERIAL_PROPERTY_OUTLINE_SIZE = "_OutlineSize";

	[SerializeField]
	private RawImage _mainImage;

	[SerializeField]
	private RawImage _outlineImage;

	private Material _outlineMaterial;

	private Color _outlineColor;

	private float _outlineSize;

	private IEnumerator _blinkRoutine;

	public Material OutlineMaterial
	{
		get
		{
			if (_outlineMaterial == null)
			{
				_outlineMaterial = UnityEngine.Object.Instantiate(_outlineImage.material);
				_outlineImage.material = _outlineMaterial;
			}
			return _outlineMaterial;
		}
	}

	private void Awake()
	{
		_outlineColor = OutlineMaterial.GetColor("_OutlineColor");
		_outlineSize = OutlineMaterial.GetFloat("_OutlineSize");
	}

	public void Initialize(Texture2D texture)
	{
		_mainImage.texture = texture;
		_outlineImage.texture = texture;
	}

	public void RestoreOutlineColor()
	{
		StopBlinkRoutine();
		SetOutlineColor(_outlineColor);
	}

	public void OverrideOutlineColor(Color color)
	{
		StopBlinkRoutine();
		SetOutlineColor(color);
	}

	public void Blink(Color color, float duration)
	{
		StopBlinkRoutine();
		_blinkRoutine = BlinkRoutine(color, duration);
		StartCoroutine(_blinkRoutine);
	}

	private IEnumerator BlinkRoutine(Color color, float duration)
	{
		float time = 0f;
		Color from = _outlineColor;
		Color to = color;
		while (true)
		{
			SetOutlineColor(Color.Lerp(from, to, time / duration));
			if (duration < time)
			{
				time = 0f;
				Color color2 = from;
				from = to;
				to = color2;
			}
			yield return null;
			time += Time.deltaTime;
		}
	}

	public void Glow(Color toColor, float toSize, float duration, int count = 1)
	{
		StartCoroutine(GlowRoutine(toColor, toSize, duration, count));
	}

	private IEnumerator GlowRoutine(Color toColor, float toSize, float duration, int count)
	{
		Color fromColor = toColor;
		toColor.a = 0f;
		for (int i = 0; i < count; i++)
		{
			float time = 0f;
			float num = 0f;
			while (num < 1f)
			{
				yield return null;
				time += Time.deltaTime;
				num = time / duration;
				SetOutlineColor(Color.Lerp(fromColor, toColor, num));
				SetOutlineSize(Mathf.Lerp(_outlineSize, toSize, num));
			}
		}
		yield return null;
		SetOutlineColor(fromColor);
		SetOutlineSize(_outlineSize);
	}

	private void StopBlinkRoutine()
	{
		if (_blinkRoutine != null)
		{
			StopCoroutine(_blinkRoutine);
			_blinkRoutine = null;
		}
	}

	private void SetOutlineColor(Color color)
	{
		OutlineMaterial.SetColor("_OutlineColor", color);
	}

	private void SetOutlineSize(float size)
	{
		OutlineMaterial.SetFloat("_OutlineSize", size);
	}
}
public class AchievementPanel : Panel, IPointerClickHandler, IEventSystemHandler
{
	[SerializeField]
	private QuestCompletedPopup _questCompletedPopup;

	[SerializeField]
	private float _questCompletedDuration;

	[SerializeField]
	private AchievementUnlockedPopup _achievementUnlockedPopup;

	[SerializeField]
	private float _achievementUnlockedDuration;

	private float _openDuration;

	private float _openTime;

	private Queue<Quest> _questQueue = new Queue<Quest>();

	private Queue<AchievementBase> _achievementQueue = new Queue<AchievementBase>();

	private void LateUpdate()
	{
		_openTime += GameSpeedManager.UnscaledDeltaTime;
		if (_openTime > _openDuration)
		{
			GameManager.UIManager.ClosePanel(ID);
		}
	}

	private void OnDisable()
	{
		if (_questQueue.Count > 0 || _achievementQueue.Count > 0)
		{
			FinalUpdate.RegisterOneShot(DequeueAchievement);
		}
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (context is Quest quest)
		{
			return OpenQuest(quest);
		}
		if (context is AchievementBase achievement)
		{
			return OpenAchievement(achievement);
		}
		return false;
	}

	private bool OpenQuest(Quest quest)
	{
		if (IsOpen())
		{
			_questQueue.Enqueue(quest);
			return true;
		}
		if (base.Open(quest.PanelID, quest))
		{
			_openDuration = _questCompletedDuration;
			_openTime = 0f;
			_questCompletedPopup.Activate(quest);
		}
		return false;
	}

	private bool OpenAchievement(AchievementBase achievement)
	{
		if (IsOpen())
		{
			_achievementQueue.Enqueue(achievement);
			return true;
		}
		if (base.Open(achievement.PanelID, achievement))
		{
			_openDuration = _achievementUnlockedDuration;
			_openTime = 0f;
			_achievementUnlockedPopup.Activate(achievement);
			return true;
		}
		return false;
	}

	private void DequeueAchievement()
	{
		if (_questQueue.TryDequeue(out var result))
		{
			GameManager.UIManager.DisplayPanel(result);
		}
		if (_achievementQueue.TryDequeue(out var result2))
		{
			GameManager.UIManager.DisplayPanel(result2);
		}
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		GameManager.UIManager.ClosePanel(ID);
	}
}
