public class FullscreenDrifterPanel : Panel, IAgentReference, IMoveHandler, IEventSystemHandler, ScrollRectSelectionScroller.IProvider
{
	[SerializeField]
	private DrifterPanelBase[] _drifterPanels;

	[SerializeField]
	private ChildBehaviourCache<DrifterListItem> _drifterListItemCache;

	[SerializeField]
	private TextMeshProUGUI _name;

	[SerializeField]
	private PortraitDynamic _portrait;

	private DrifterPanelBase _activePanel;

	private Agent _selectedDrifter;

	private int _selectedDrifterIndex;

	private DrifterListItem _selectedDrifterListItem;

	private List<Agent> _drifters;

	public override PanelID ID
	{
		get
		{
			if (!(_activePanel != null))
			{
				return PanelID.None;
			}
			return _activePanel.ID;
		}
	}

	public Agent AgentReference => _selectedDrifter;

	public UnityEvent OnAgentUpdated { get; private set; } = new UnityEvent();

	public override LocalizedString Title
	{
		get
		{
			if (!_activePanel)
			{
				return base.Title;
			}
			return _activePanel.Title;
		}
	}

	public GameObject SelectedGameObject
	{
		get
		{
			if (!_selectedDrifterListItem)
			{
				return null;
			}
			return _selectedDrifterListItem.gameObject;
		}
	}

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnDrifterEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentRemovedFromPlayerCommunity, OnDrifterEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentDeath, OnDrifterEvent);
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		GameEventDispatcher.AddListener(GameEventType.AgentFullscreenPanelRefresh, OnAgentPanelRefresh);
		OnActiveInputUpdated();
		UpdateDrifterList();
		_portrait.Enable(_selectedDrifter);
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnDrifterEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRemovedFromPlayerCommunity, OnDrifterEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, OnDrifterEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.AgentFullscreenPanelRefresh, OnAgentPanelRefresh);
		_portrait.Disable(_selectedDrifter);
		if (_activePanel != null)
		{
			_activePanel.Close();
		}
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (((IReadOnlyCollection<DrifterPanelBase>)(object)_drifterPanels).IsNullOrEmpty())
		{
			return base.Open(id, context);
		}
		if (context is Agent { IsAlive: not false } agent)
		{
			_selectedDrifter = agent;
		}
		DrifterPanelBase[] drifterPanels = _drifterPanels;
		foreach (DrifterPanelBase drifterPanelBase in drifterPanels)
		{
			if (drifterPanelBase.Open(id, context))
			{
				if ((bool)_activePanel && drifterPanelBase != _activePanel)
				{
					_activePanel.Close();
				}
				_activePanel = drifterPanelBase;
				base.gameObject.SetActive(value: true);
				UpdateDrifterList();
				return true;
			}
		}
		return false;
	}

	private void UpdateDrifterList()
	{
		Agent agent = _selectedDrifter;
		_drifters = Community.PlayerCommunity.Agents;
		_drifterListItemCache.Reset();
		if (!_drifters.IsNullOrEmpty())
		{
			if (agent == null || !agent.IsAlive)
			{
				agent = _drifters[0];
			}
			for (int i = 0; i < _drifters.Count; i++)
			{
				DrifterListItem drifterListItem = _drifterListItemCache.Get(active: true);
				drifterListItem.Initialize(_drifters[i]);
				drifterListItem.OnClick.AddListener(OnDrifterListItemClick);
				if (drifterListItem.Drifter == agent)
				{
					_selectedDrifterIndex = i;
					_selectedDrifterListItem = drifterListItem;
				}
			}
			_drifterListItemCache.Trim();
		}
		if ((bool)_activePanel)
		{
			_activePanel.UpdateDrifters(_drifters);
		}
		SelectDrifterListItem(_selectedDrifterListItem, _selectedDrifterIndex);
	}

	private void TrySelectDrifter(int index)
	{
		if (_drifterListItemCache.TryGetAtIndex(index, out var instance) && instance.gameObject.activeInHierarchy)
		{
			SelectDrifterListItem(instance, index);
		}
	}

	private void OnDrifterEvent(GameEvent gameEvent)
	{
		UpdateDrifterList();
	}

	private void OnDrifterListItemClick(DrifterListItem sender)
	{
		if (_drifterListItemCache.TryGetIndex(sender, out var index))
		{
			SelectDrifterListItem(sender, index);
		}
	}

	private void SelectDrifterListItem(DrifterListItem item, int index)
	{
		if ((bool)_selectedDrifterListItem)
		{
			_selectedDrifterListItem.OnDeselect();
		}
		_selectedDrifterIndex = index;
		_selectedDrifterListItem = item;
		_selectedDrifterListItem.OnSelect();
		SelectDrifter(item.Drifter);
	}

	private void SelectDrifter(Agent drifter)
	{
		_selectedDrifter = drifter;
		_name.text = _selectedDrifter.Name;
		_portrait.Enable(_selectedDrifter);
		if ((bool)_activePanel)
		{
			_activePanel.SetSelectedDrifter(_selectedDrifter);
		}
		OnAgentUpdated.Invoke();
	}

	private void OnActiveInputUpdated(GameEvent gameEvent = null)
	{
		if (FlotsamInputManager.ActiveInput == InputFlags.Joystick)
		{
			EventSystem.current.SetSelectedGameObject(base.gameObject);
		}
	}

	private void OnAgentPanelRefresh(GameEvent gameEvent)
	{
		if (!(gameEvent is AgentEvent agentEvent))
		{
			return;
		}
		for (int i = 0; i < _drifterListItemCache.Count; i++)
		{
			DrifterListItem drifterListItem = _drifterListItemCache[i];
			if (drifterListItem.Drifter == agentEvent.Agent)
			{
				SelectDrifterListItem(drifterListItem, i);
			}
		}
	}

	public override bool CanBeOpened(PanelID id, IPanelContext context = null)
	{
		DrifterPanelBase[] drifterPanels = _drifterPanels;
		for (int i = 0; i < drifterPanels.Length; i++)
		{
			if (drifterPanels[i].CanBeOpened(id, context))
			{
				return true;
			}
		}
		return false;
	}

	public void OnMove(AxisEventData axisEventData)
	{
		switch (axisEventData.moveDir)
		{
		case MoveDirection.Up:
			TrySelectDrifter(_selectedDrifterIndex - 1);
			break;
		case MoveDirection.Down:
			TrySelectDrifter(_selectedDrifterIndex + 1);
			break;
		default:
			_activePanel.OnMove(axisEventData);
			break;
		}
	}
}
public class BirdPanel : Panel
{
	[Tooltip("Image component for the birds portrait.")]
	public Image ImagePortrait;

	[Space]
	[Tooltip("Localized text when the bird needs to be rescued.")]
	[SerializeField]
	private LocalizedString _needsRescuingText = "";

	[Header("Buttons")]
	[SerializeField]
	[Tooltip("Button which focuses the camera on the selected bird.")]
	private Button _focusButton;

	[SerializeField]
	[Tooltip("Button which focuses the camera on the house of the selected bird.")]
	private Button _houseButton;

	[SerializeField]
	[Tooltip("Button to release the selected bird.")]
	private Button _releaseButton;

	[Header("Other")]
	[Tooltip("Reference to the panels inventory view.")]
	public InventoryView InventoryView;

	[Header("Happiness Bar")]
	[SerializeField]
	private Slider _happinessBar;

	[SerializeField]
	private Tooltip _happinessBarTooltip;

	[SerializeField]
	private Image _happinessBarIcon;

	[SerializeField]
	private ChildGameObjectCache _happinessBarDividerPrefab;

	[Header("Sprites")]
	[SerializeField]
	private Image _happinessIcon;

	[Header("Text Labels")]
	[SerializeField]
	[Tooltip("Text component for the birds name.")]
	private TextMeshProUGUI _textName;

	[SerializeField]
	[Tooltip("Text component for the birds task description.")]
	private TextMeshProUGUI _taskText;

	[HideInInspector]
	public Bird Bird { get; private set; }

	private void Update()
	{
		if ((bool)Bird)
		{
			UpdatePanel();
		}
		else
		{
			Close();
		}
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (context is Bird bird && base.Open(id, context))
		{
			Bird = bird;
			UpdatePanel();
			InventoryView.Initialize(bird.Inventory);
			ImagePortrait.sprite = bird.Descriptor.Portrait;
			return true;
		}
		return false;
	}

	private void UpdateName(string name, bool dialogFeedback)
	{
		PopUpDialog.Instance.InputEvent -= UpdateName;
		if (dialogFeedback)
		{
			Bird.Descriptor.SetName(name);
		}
	}

	private void UpdatePanel()
	{
		if (base.gameObject.activeInHierarchy)
		{
			IconProperties iconProperties = Bird.ReturnHappinessIcon();
			_textName.text = Bird.Name;
			_happinessBar.maxValue = Bird.HappinessMaxValue;
			_happinessBar.value = Mathf.Max(0, Bird.Happiness);
			_happinessBarDividerPrefab.Reset();
			for (int i = 0; (float)i < _happinessBar.maxValue; i++)
			{
				_happinessBarDividerPrefab.Get(active: true);
			}
			_happinessBarDividerPrefab.Trim();
			_happinessBarIcon.sprite = iconProperties.Sprite;
			_happinessBarTooltip.LocalizedText = iconProperties.TooltipText;
			_happinessIcon.sprite = Bird.HappinessIcon;
			_houseButton.interactable = Bird.BirdHouse != null;
			_releaseButton.interactable = Bird.Community.IsPlayerCommunity();
			if (Bird.Community != null)
			{
				string text = "";
				text = ((!Bird.Community.IsPlayerCommunity() && Bird.CanBeRescued) ? ((string)_needsRescuingText) : ((string)Bird.ReturnTaskDescription()));
				_taskText.text = text;
			}
		}
	}

	public override void Close()
	{
		if (base.gameObject.activeSelf)
		{
			if ((bool)Bird)
			{
				Selector.Deselect(Bird.gameObject);
			}
			base.Close();
		}
	}

	public void LockOnDrifter()
	{
		if ((bool)Bird && GameManager.WorldManager.IsInBoatRadius(Bird.transform.position))
		{
			CameraController.Instance.Lock(Bird.gameObject);
		}
	}

	public void PopUpNameChange()
	{
		if (Bird.Community.IsPlayerCommunity() && PopUpDialog.Instance.TryPopUpInput(GameManager.Settings.UISettings.InputNameChangeAgent))
		{
			PopUpDialog.Instance.InputEvent += UpdateName;
		}
	}

	public void LockOnHouse()
	{
		if (Bird.BirdHouse != null)
		{
			CameraController.Instance.Lock(Bird.BirdHouse.gameObject);
			Selector.Select(Bird.BirdHouse.gameObject, ObjectType.Buildable);
		}
	}

	public void PopUpFreeBirdDialog()
	{
		Bird.AskToFreeBird();
	}
}
public class BirdEntry : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private Button _button;

	[SerializeField]
	[Tooltip("This is an empty entry. Used as blueprint for new birds in the birdhouse panel.")]
	private TextMeshProUGUI _nameText;

	[SerializeField]
	[Tooltip("Image that shows current state of bird.")]
	private Image _stateImage;

	[SerializeField]
	[Tooltip("Tooltip for state icon of bird entry.")]
	private Tooltip _taskTooltip;

	[Space]
	[SerializeField]
	[Tooltip("Image that shows happiness of bird.")]
	private Image _happinessImage;

	[SerializeField]
	[Tooltip("Tooltip for happiness icon of bird.")]
	private Tooltip _happinessTooltip;

	[Header("Animation")]
	[SerializeField]
	private Animator _animator;

	[SerializeField]
	private string _animatorParameterEnabled = "Enabled";

	public Bird Bird { get; private set; }

	public void Initialize(Bird bird)
	{
		Bird = bird;
		_taskTooltip.Bird = Bird;
		_happinessTooltip.Bird = Bird;
		UpdateEntry();
	}

	public void UpdateEntry()
	{
		if (Bird == null)
		{
			_button.interactable = false;
			_nameText.text = string.Empty;
			SetIconAndTooltip(null, _stateImage, _taskTooltip);
			SetIconAndTooltip(null, _happinessImage, _happinessTooltip);
			if (_animator != null)
			{
				_animator.SetBool(_animatorParameterEnabled, value: false);
			}
		}
		else
		{
			_button.interactable = true;
			_nameText.text = Bird.Name;
			SetIconAndTooltip(Bird.ReturnStateIcon(), _stateImage, _taskTooltip);
			SetIconAndTooltip(Bird.ReturnHappinessIcon(), _happinessImage, _happinessTooltip);
			if (_animator != null)
			{
				_animator.SetBool(_animatorParameterEnabled, value: true);
			}
		}
	}

	public void SelectBird()
	{
		if (Selector.ReturnIsSelected(Bird.gameObject))
		{
			CameraController.Instance.Lock(Bird.gameObject);
		}
		else
		{
			GameManager.UIManager.DisplayPanel(Bird);
		}
	}

	private void SetIconAndTooltip(IconProperties icon, Image image, Tooltip tooltip)
	{
		if (icon == null)
		{
			image.gameObject.SetActive(value: false);
			return;
		}
		image.gameObject.SetActive(value: true);
		image.sprite = icon.Sprite;
		tooltip.enabled = (string)icon.TooltipText != null;
		tooltip.LocalizedText = icon.TooltipText;
	}
}
