public class MedPodPanel : MonoBehaviour, IBuildablePanelElement
{
	[SerializeField]
	private DrifterSlot _drifterSlot;

	[SerializeField]
	private InventoryPanelItemSlot _medicationSlot;

	[SerializeField]
	private Slider _progressSlider;

	[SerializeField]
	private ChildBehaviourCache<CommunityInventoryItemSlot> _medicinesSlotCache;

	[Header("Status")]
	[SerializeField]
	private PlaceableAlertProperties _waitingForPatient;

	[SerializeField]
	private PlaceableAlertProperties _waitingForDoctor;

	[SerializeField]
	private PlaceableAlertProperties _treatingPatient;

	private MedPod _medPod;

	private List<ItemProperties> _medicines;

	public BuildablePanelElementId Id => BuildablePanelElementId.MedPod;

	private void OnDisable()
	{
		RemoveListeners();
		_medPod = null;
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		Deactivate();
		if (finished && buildable.TryReturnBuildableExtendable<MedPod>(out _medPod))
		{
			_ = _medicines;
			_medicines = buildable.Community.Inventory.ReturnItemPropertiesWithTags(Item.Tags.Medicine);
			_medicinesSlotCache.Reset();
			foreach (ItemProperties medicine in _medicines)
			{
				_medicinesSlotCache.Get(active: true).Initialize(medicine);
			}
			_medicinesSlotCache.Trim();
			_medPod.OnUpdated += UpdateState;
			UpdateState(_medPod);
			base.gameObject.SetActive(value: true);
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		RemoveListeners();
		base.gameObject.SetActive(value: false);
	}

	private void UpdateState(MedPod medPod)
	{
		if (!(_medPod == null))
		{
			_drifterSlot.SetDrifter(_medPod.OccupyingPatient);
			_progressSlider.value = _medPod.Progress;
			if (_medPod.Medication == null)
			{
				_medicationSlot.Initialize(null, 0, showCounter: false);
			}
			else
			{
				_medicationSlot.Initialize(_medPod.Medication.Properties, 1, showCounter: false);
			}
			if (_medPod.OccupyingPatient == null)
			{
				_medPod.Buildable.SetStatus(_waitingForPatient);
			}
			else if (_medPod.Doctor == null)
			{
				_medPod.Buildable.SetStatus(_waitingForDoctor);
			}
			else
			{
				_medPod.Buildable.SetStatus(_treatingPatient);
			}
		}
	}

	private void RemoveListeners()
	{
		if ((bool)_medPod)
		{
			_medPod.OnUpdated -= UpdateState;
		}
	}
}
public class ModulePanel : MonoBehaviour, IBuildablePanelElement
{
	[SerializeField]
	[FormerlySerializedAs("_buttonCache")]
	private ChildBehaviourCache<ModuleOption> _optionCache;

	[SerializeField]
	private Button _launchButton;

	private Buildable _buildable;

	private ModuleManager _moduleManager;

	private int _selectedIndex;

	public BuildablePanelElementId Id => BuildablePanelElementId.Workshop;

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.CommunityInventoryUpdated, UpdateOptions);
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.CommunityInventoryUpdated, UpdateOptions);
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		_buildable = buildable;
		if (IsActive(buildable) && (_buildable.TryReturnBuildableExtendable<ModuleManager>(out _moduleManager) || buildable.Properties.Upgrade != null))
		{
			if ((bool)_moduleManager && _moduleManager.HasLaunchedRocket())
			{
				return false;
			}
			UpdateOptions();
			base.gameObject.SetActive(value: true);
			GameEventDispatcher.AddListener(GameEventType.ModuleActivated, UpdateOptions);
			if ((bool)_moduleManager && _moduleManager.IsRocket())
			{
				GameEventDispatcher.AddListener(GameEventType.QuestUpdated, UpdateOptions);
				GameEventDispatcher.AddListener(GameEventType.PanelClosed, UpdateOptions);
			}
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		ClearButtons();
		base.gameObject.SetActive(value: false);
		GameEventDispatcher.RemoveListener(GameEventType.ModuleActivated, UpdateOptions);
		GameEventDispatcher.RemoveListener(GameEventType.QuestUpdated, UpdateOptions);
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, UpdateOptions);
	}

	private void UpdateOptions(GameEvent gameEvent = null)
	{
		ClearButtons();
		_optionCache.Reset();
		if ((bool)_buildable.Properties.Upgrade)
		{
			ModuleOption moduleOption = _optionCache.Get(active: true);
			moduleOption.Initialize(_buildable);
			moduleOption.OnClicked.AddListener(OnButtonClick);
		}
		if ((bool)_moduleManager)
		{
			if (_moduleManager.CanLaunchRocket())
			{
				_launchButton.gameObject.SetActive(value: true);
				_launchButton.onClick.AddListener(Launch);
				_launchButton.Select();
			}
			else if (_moduleManager.Modules != null)
			{
				using ListPool<ModuleProperties>.List list = ListPool<ModuleProperties>.Get(_moduleManager.Modules);
				Sorting.SlowSort(list, SortModules);
				foreach (ModuleProperties item in list)
				{
					ModuleOption moduleOption2 = _optionCache.Get(active: true);
					moduleOption2.Initialize(_moduleManager, item);
					moduleOption2.OnClicked.AddListener(OnButtonClick);
				}
			}
		}
		_optionCache.Trim();
		if (!_optionCache.TryGetAtIndex(_selectedIndex, out var instance) || !instance.Select())
		{
			_selectedIndex = -1;
			SelectNextOption();
		}
	}

	private void ClearButtons()
	{
		_launchButton.gameObject.SetActive(value: false);
		_launchButton.onClick.RemoveListener(Launch);
		foreach (ModuleOption instance in _optionCache.Instances)
		{
			instance.OnClicked.RemoveListener(OnButtonClick);
		}
	}

	private int SortModules(ModuleProperties lhs, ModuleProperties rhs)
	{
		bool num = _moduleManager.IsActiveModule(lhs);
		bool flag = _moduleManager.IsActiveModule(rhs);
		if (num == flag)
		{
			return 0;
		}
		if ((bool)rhs)
		{
			return -1;
		}
		return 1;
	}

	private bool IsActive(Buildable buildable)
	{
		if (buildable.BuildPhase != BuildPhase.Finished && buildable.BuildPhase != BuildPhase.UpgradeShutdown && buildable.BuildPhase != BuildPhase.UpgradeHaulTo)
		{
			return buildable.BuildPhase == BuildPhase.UpgradeHaulFrom;
		}
		return true;
	}

	public void SelectPreviousOption()
	{
		int num = _selectedIndex;
		ModuleOption instance;
		while (_optionCache.TryGetAtIndex(--num, out instance))
		{
			if (instance.Select())
			{
				_selectedIndex = num;
				break;
			}
		}
	}

	public void SelectNextOption()
	{
		int num = _selectedIndex;
		ModuleOption instance;
		while (_optionCache.TryGetAtIndex(++num, out instance))
		{
			if (instance.Select())
			{
				_selectedIndex = num;
				break;
			}
		}
	}

	private void SelectOption(int index)
	{
		if (_optionCache.TryGetAtIndex(index, out var instance) && instance.Select())
		{
			_selectedIndex = index;
		}
	}

	private void Launch()
	{
		GameManager.UIManager.CloseAllPanels();
		GameEventDispatcher.Dispatch(GameEventType.LaunchSpaceship);
	}

	private void OnButtonClick(ModuleOption upgradeButton)
	{
		if (!upgradeButton)
		{
			return;
		}
		if ((bool)upgradeButton.ModuleProperties)
		{
			_moduleManager?.PlaceModule(upgradeButton.ModuleProperties);
		}
		else if ((bool)upgradeButton.BuildableProperties)
		{
			if (upgradeButton.IsCancel)
			{
				_buildable.CancelUpgrade();
			}
			else
			{
				_buildable.Upgrade();
			}
		}
		UpdateOptions();
		SelectOption(_selectedIndex);
	}
}
public class MooringPointPanel : SceneBehaviour, IBuildablePanelElement
{
	[SerializeField]
	private GameObject _emptyBoat;

	[SerializeField]
	private BoatEntry _linkedBoat;

	private MooringPoint _mooringPoint;

	public BuildablePanelElementId Id => BuildablePanelElementId.MooringPoint;

	private void OnDisable()
	{
		_mooringPoint.OnBoatLinkUpdatedEvent.RemoveListener(UpdateLinkedBoat);
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		Deactivate();
		if (finished && buildable.TryReturnBuildableExtendable<MooringPoint>(out _mooringPoint))
		{
			base.gameObject.SetActive(value: true);
			UpdateLinkedBoat();
			_mooringPoint.OnBoatLinkUpdatedEvent.AddListener(UpdateLinkedBoat);
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		if ((bool)_mooringPoint)
		{
			_mooringPoint.OnBoatLinkUpdatedEvent.RemoveListener(UpdateLinkedBoat);
		}
		base.gameObject.SetActive(value: false);
	}

	private void UpdateLinkedBoat()
	{
		bool flag = _mooringPoint.LinkedBoat != null;
		_emptyBoat.SetActive(!flag);
		_linkedBoat.gameObject.SetActive(flag);
		if (flag)
		{
			_linkedBoat.Initialize(_mooringPoint.LinkedBoat);
		}
	}
}
public class PanelTabContainer : MonoBehaviour
{
	[Serializable]
	private struct TabPage
	{
		public AnimatedToggle Tab;

		public Transform Page;
	}

	[SerializeField]
	[NamedArrayElement(new string[] { "Tab" })]
	private TabPage[] _tabs;

	[SerializeField]
	private SelectableGroup _selectableGroup;

	private List<TabPage> _activeTabs = new List<TabPage>();

	private List<TabPage> _inactiveTabs = new List<TabPage>();

	public void Initialize()
	{
		bool flag = false;
		_activeTabs.Clear();
		_inactiveTabs.Clear();
		TabPage[] tabs = _tabs;
		for (int i = 0; i < tabs.Length; i++)
		{
			TabPage item = tabs[i];
			if (HasActiveChild(item.Page))
			{
				_activeTabs.Add(item);
				item.Tab.gameObject.SetActive(value: true);
				if (item.Tab.isOn)
				{
					if (flag)
					{
						item.Tab.SetIsOnWithoutNotify(value: false);
						item.Page.gameObject.SetActive(value: false);
					}
					else
					{
						flag = true;
						item.Page.gameObject.SetActive(value: true);
					}
				}
			}
			else
			{
				item.Tab.gameObject.SetActive(value: false);
				item.Tab.isOn = false;
				item.Page.gameObject.SetActive(value: false);
				_inactiveTabs.Add(item);
			}
		}
		if (_activeTabs.Count <= 1)
		{
			base.gameObject.SetActive(value: false);
			return;
		}
		base.gameObject.SetActive(value: true);
		_selectableGroup.Initialize();
		if (!flag)
		{
			_activeTabs[0].Tab.isOn = true;
			_activeTabs[0].Page.gameObject.SetActive(value: true);
		}
	}

	public void ToggleFirstTab()
	{
		if (_activeTabs.Count > 1)
		{
			_activeTabs[0].Tab.isOn = true;
		}
	}

	private bool HasActiveChild(Transform transform)
	{
		int childCount = transform.childCount;
		while (0 < childCount--)
		{
			if (transform.GetChild(childCount).gameObject.activeSelf)
			{
				return true;
			}
		}
		return false;
	}
}
public class ProductionPanel : MonoBehaviour, IBuildablePanelElement, ILocalizationParamsManager
{
	[Header("Production")]
	[Tooltip("Slider to display the production progress.")]
	[SerializeField]
	private Slider _productionProgressSlider;

	[Header("Queue")]
	[Tooltip("List of all the displays in the queue.")]
	[SerializeField]
	private List<RecipeItemDisplay> _queueDisplays = new List<RecipeItemDisplay>();

	[Tooltip("Continuous production toggle")]
	[SerializeField]
	private Toggle _continuousToggle;

	[Header("Recipes")]
	[Tooltip("Toggle group of all the recipes.")]
	[SerializeField]
	private ToggleGroup _recipeToggleGroup;

	[Tooltip("Prefab for the recipe display. Ensure this has a toggle on it as well.")]
	[SerializeField]
	private ChildBehaviourCache<ProductionPanelRecipeToggle> _recipeToggleCache;

	[Tooltip("The selectable group that manages the recipes")]
	[SerializeField]
	private SelectableGroup _recipeSelectableGroup;

	[Header("Priority")]
	[SerializeField]
	private TextMeshProUGUI _priorityDividerLabel;

	[SerializeField]
	private LocalizedString _priorityDividerLabelPostfix;

	[SerializeField]
	private TextMeshProUGUI _priorityText;

	[Header("Inventory")]
	[Tooltip("The import inventory view.")]
	[SerializeField]
	private InventoryView _importView;

	[Tooltip("The export inventory view.")]
	[SerializeField]
	private InventoryView _exportView;

	private RecipeDisplay _recipeDisplay;

	private Producer _producer;

	private int _maximumQueuedRecipes;

	private AssignmentType _assignmentType;

	public BuildablePanelElementId Id => BuildablePanelElementId.Workshop;

	private void Awake()
	{
		_maximumQueuedRecipes = GameManager.Settings.BuildableSettings.MaximumQueuedRecipes;
		if (_maximumQueuedRecipes != _queueDisplays.Count)
		{
			PajamaLlama.Debugs.Debugger.Error($"The production panel has {_queueDisplays.Count} slots, but the maximum amount of queued recipes is {_maximumQueuedRecipes}. Please make sure these sizes match.");
		}
	}

	private void OnEnable()
	{
		UpdateToggles();
	}

	private void Update()
	{
		_productionProgressSlider.value = _producer.ReturnProgressNormalized();
	}

	private void OnDestroy()
	{
		RemoveListeners();
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		Deactivate();
		if (finished && buildable.TryReturnBuildableExtendable<Producer>(out _producer) && _producer.ProductionProperties.Type == Producer.Type.Workshop)
		{
			ProductionPanelRecipeToggle productionPanelRecipeToggle = null;
			base.gameObject.SetActive(value: true);
			if (_recipeDisplay == null)
			{
				_recipeDisplay = GetComponentInChildren<RecipeDisplay>(includeInactive: true);
			}
			_recipeDisplay.Initialize(_producer.SelectedRecipe, _producer.HasEnergyCost);
			_producer.MalfunctionsUpdated += UpdateToggles;
			_producer.QueueUpdatedEvent += UpdateQueue;
			LocalizationManager.ParamManagers.AddUnique(this);
			UpdatePanel();
			_recipeToggleGroup.allowSwitchOff = true;
			_recipeToggleCache.Reset();
			for (int i = 0; i < _producer.Recipes.Count; i++)
			{
				Producer.Recipe recipe = _producer.Recipes[i];
				ProductionPanelRecipeToggle productionPanelRecipeToggle2 = _recipeToggleCache.Get(active: true);
				productionPanelRecipeToggle2.Initialize(_producer, recipe);
				productionPanelRecipeToggle2.group = _recipeToggleGroup;
				if (_producer.SelectedRecipeIndex == i)
				{
					productionPanelRecipeToggle = productionPanelRecipeToggle2;
				}
				productionPanelRecipeToggle2.onValueChanged.AddListener(OnToggleValueChanged);
			}
			_recipeToggleCache.Trim();
			_recipeToggleGroup.allowSwitchOff = false;
			_recipeSelectableGroup.Initialize(clearSelected: true);
			if (!_recipeSelectableGroup.TrySelect(productionPanelRecipeToggle))
			{
				productionPanelRecipeToggle.isOn = true;
			}
			_importView.Initialize(_producer.Buildable.Inventory, SubInventoryType.Import);
			_exportView.Initialize(_producer.Buildable.Inventory, SubInventoryType.Export);
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		LocalizationManager.ParamManagers.Remove(this);
		RemoveListeners();
		base.gameObject.SetActive(value: false);
	}

	private void RemoveListeners()
	{
		if (_producer != null)
		{
			_producer.MalfunctionsUpdated -= UpdateToggles;
			_producer.QueueUpdatedEvent -= UpdateQueue;
		}
		for (int i = 0; i < _recipeToggleCache.Count; i++)
		{
			_recipeToggleCache[i].onValueChanged.RemoveListener(OnToggleValueChanged);
		}
	}

	private void SelectRecipe(int recipeIndex)
	{
		_producer.SetSelectedRecipe(recipeIndex);
		UpdatePanel();
	}

	private void UpdatePanel()
	{
		_recipeDisplay.SetRecipe(_producer.SelectedRecipe);
		_priorityText.text = _producer.Priority.Label;
		UpdateToggles();
		UpdateQueue();
		UpdateAssignmentType();
	}

	private void UpdateQueue()
	{
		for (int i = 0; i < _queueDisplays.Count; i++)
		{
			RecipeItemDisplay recipeItemDisplay = _queueDisplays[i];
			if (_producer.QueuedRecipes.Count <= i)
			{
				recipeItemDisplay.Initialize();
				continue;
			}
			QueuedRecipe queuedRecipe = _producer.QueuedRecipes[i];
			bool flag = queuedRecipe.RecipeStage == QueuedRecipe.Stage.WaitingToReserveItems;
			if (recipeItemDisplay.Recipe != queuedRecipe.Recipe || recipeItemDisplay.ItemDisabled != flag)
			{
				recipeItemDisplay.Initialize(queuedRecipe.Recipe, queuedRecipe.ReturnFirstProducedItemProperties(), flag);
			}
		}
		_continuousToggle.SetIsOnWithoutNotify(_producer.SelectedRecipe.IsContinuous);
	}

	private void UpdateToggles()
	{
		_recipeDisplay.UpdateAmountToProduce();
		_recipeToggleGroup.allowSwitchOff = true;
		for (int i = 0; i < _recipeToggleCache.Count; i++)
		{
			_recipeToggleCache[i].UpdateState();
		}
		_recipeToggleGroup.allowSwitchOff = false;
	}

	private void UpdateAssignmentType()
	{
		if ((bool)_producer && _assignmentType != _producer.ProductionProperties.ProductionProject.AssignmentType)
		{
			_assignmentType = _producer.ProductionProperties.ProductionProject.AssignmentType;
			_priorityDividerLabel.text = _priorityDividerLabelPostfix;
		}
	}

	private void OnToggleValueChanged(bool isOn)
	{
		if (!isOn)
		{
			return;
		}
		for (int i = 0; i < _recipeToggleCache.Count; i++)
		{
			if (_recipeToggleCache[i].isOn)
			{
				SelectRecipe(i);
			}
		}
	}

	public string GetParameterValue(string Param)
	{
		if (Param == "ASSIGNMENT_TYPE" && ProjectSettings.TryGetAssignmentSettings(out var settings, _assignmentType))
		{
			return settings.Name;
		}
		return null;
	}

	public void IncreaseAmountToProduce()
	{
		_producer.IncreaseSelectedRecipeAmountToProduce();
		UpdateToggles();
	}

	public void DecreaseAmountToProduce()
	{
		_producer.SelectedRecipe.DecreaseAmountToProduce();
		UpdateToggles();
	}

	public void ToggleContinuous(bool continuous)
	{
		_producer.SelectedRecipe.ToggleContinuous();
		UpdateToggles();
	}

	public void CancelQueueItem(int index)
	{
		_producer.CancelRecipe(index);
		UpdateQueue();
	}

	public void DecreasePriority()
	{
		_producer.DecreasePriority();
		_priorityText.text = _producer.Priority.Label;
	}

	public void IncreasePriority()
	{
		_producer.IncreasePriority();
		_priorityText.text = _producer.Priority.Label;
	}

	public void SelectQueuedRecipe(int index)
	{
		throw new NotImplementedException();
	}

	public void SelectContinuousRecipe()
	{
		throw new NotImplementedException();
	}

	public void CancelSelectedRecipe()
	{
		throw new NotImplementedException();
	}

	public void CancelContinuousRecipe()
	{
		throw new NotImplementedException();
	}
}
public class ResearchBuildingPanel : MonoBehaviour, IBuildablePanelElement
{
	[SerializeField]
	private GameObject _researchParent;

	[SerializeField]
	private GameObject _noResearchParent;

	[SerializeField]
	private Image _researchImage;

	[SerializeField]
	private Animator _researchAnimator;

	[SerializeField]
	private TextMeshProUGUI _researchName;

	[SerializeField]
	private LocalizedString _defaultTitleText = null;

	[SerializeField]
	private Slider _progressSlider;

	private ResearchStation _researchStation;

	public BuildablePanelElementId Id => BuildablePanelElementId.Research;

	private void OnDestroy()
	{
		if (_researchStation != null)
		{
			_researchStation.OnStartResearching.RemoveListener(UpdateStationResearching);
			_researchStation.OnStopResearching.RemoveListener(UpdateStationResearching);
		}
		GameEventDispatcher.RemoveListener(GameEventType.ResearchStarted, UpdatePanel);
		GameEventDispatcher.RemoveListener(GameEventType.ResearchFinished, UpdatePanel);
		GameEventDispatcher.RemoveListener(GameEventType.ResearchCancelled, UpdatePanel);
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		Deactivate();
		if (finished && buildable.TryReturnBuildableExtendable<ResearchStation>(out _researchStation))
		{
			base.gameObject.SetActive(value: true);
			_researchStation.OnStartResearching.AddListener(UpdateStationResearching);
			_researchStation.OnStopResearching.AddListener(UpdateStationResearching);
			_researchStation.OnResearch.AddListener(UpdateResearchProgress);
			UpdateStationResearching();
			UpdateResearchProgress();
			UpdatePanel();
			GameEventDispatcher.AddListener(GameEventType.ResearchStarted, UpdatePanel);
			GameEventDispatcher.AddListener(GameEventType.ResearchFinished, UpdatePanel);
			GameEventDispatcher.AddListener(GameEventType.ResearchCancelled, UpdatePanel);
			return true;
		}
		return false;
	}

