public abstract class CounterBase : MonoBehaviour
{
	public int Count { get; private set; }

	public int Min { get; private set; }

	public int Max { get; private set; }

	public UnityEvent<int> OnValueChanged { get; private set; } = new UnityEvent<int>();

	public void Initialize(int min, int max, int count)
	{
		Min = Mathf.Min(min, max);
		Max = Mathf.Max(min, max);
		Count = Mathf.Clamp(count, Min, Max);
		UpdateState();
	}

	public void Decrease()
	{
		SetCount(Count - 1);
	}

	public void Increase()
	{
		SetCount(Count + 1);
	}

	protected virtual void SetCount(int countToSet)
	{
		countToSet = Mathf.Clamp(countToSet, Min, Max);
		if (Count != countToSet)
		{
			Count = countToSet;
			UpdateState();
			OnValueChanged.Invoke(Count);
		}
	}

	protected abstract void UpdateState();
}
public class DrifterCounter : CounterBase
{
	[SerializeField]
	private ChildBehaviourCache<Toggle> _toggleCache;

	[SerializeField]
	private Sprite _isOnSprite;

	private List<Toggle> _toggles = new List<Toggle>(8);

	protected override void UpdateState()
	{
		foreach (Toggle toggle2 in _toggles)
		{
			toggle2.onValueChanged.RemoveListener(OnToggleValueChanged);
		}
		_toggles.Clear();
		_toggleCache.Reset();
		for (int i = base.Min; i <= base.Max; i++)
		{
			Toggle toggle = _toggleCache.Get(active: true);
			toggle.isOn = i <= base.Count;
			toggle.onValueChanged.AddListener(OnToggleValueChanged);
			if (toggle.targetGraphic is Image image)
			{
				image.overrideSprite = (toggle.isOn ? _isOnSprite : null);
			}
			_toggles.Add(toggle);
		}
		_toggleCache.Trim();
	}

	private void OnToggleValueChanged(bool value)
	{
		int num = base.Min;
		foreach (Toggle toggle in _toggles)
		{
			if (toggle.isOn != num <= base.Count)
			{
				if (num == base.Count)
				{
					UpdateState();
				}
				else
				{
					SetCount(num);
				}
				break;
			}
			num++;
		}
	}
}
