public abstract class NonInteractableTooltipBase : UIBehaviour, IPointerClickHandler, IEventSystemHandler, IPointerEnterHandler, IPointerExitHandler
{
	[SerializeField]
	private TooltipButtonTooltip _tooltip;

	[SerializeField]
	private LocalizedString _message;

	private bool _pointerIsOver;

	protected abstract bool Interactable { get; }

	public void OnPointerClick(PointerEventData eventData)
	{
		if (!Interactable && _pointerIsOver)
		{
			_tooltip.Display(TryGetMessage(out var message) ? message : _message, this, eventData.position);
		}
	}

	public void OnPointerEnter(PointerEventData eventData)
	{
		_pointerIsOver = true;
	}

	public void OnPointerExit(PointerEventData eventData)
	{
		_pointerIsOver = false;
		_tooltip.Close(this);
	}

	protected virtual bool TryGetMessage(out LocalizedString message)
	{
		message = null;
		return false;
	}
}
public class ProjectMalfunctionPanel : MonoBehaviour
{
	[SerializeField]
	private ChildBehaviourCache<PlaceableAlertIcon> _malfunctionIconCache;

	private Project _project;

	private List<PlaceableAlertProperties> _malfunctions = new List<PlaceableAlertProperties>();

	public void Initialize(Project project)
	{
		Uninitialize(update: false);
		_project = project;
		_project.MalfunctionsUpdated += OnMalfunctionsUpdated;
		OnMalfunctionsUpdated();
	}

	public void Uninitialize(bool update = true)
	{
		if (_project != null)
		{
			_project.MalfunctionsUpdated -= OnMalfunctionsUpdated;
			_project = null;
		}
		if (update)
		{
			OnMalfunctionsUpdated();
		}
	}

	private void OnMalfunctionsUpdated()
	{
		_malfunctions.Clear();
		_malfunctionIconCache.Reset();
		if (_project != null)
		{
			_project.PopulateMalfunctions(_malfunctions);
		}
		foreach (PlaceableAlertProperties malfunction in _malfunctions)
		{
			_malfunctionIconCache.Get(active: true).Initialize(malfunction, _project.Properties.name);
		}
		_malfunctionIconCache.Trim();
		base.gameObject.SetActive(_malfunctions.Count > 0);
	}
}
