public class TooltipButton : RewiredButtonDeprecated, IGraphicStatesProvider
{
	private readonly string[] STATES = new string[5] { "Normal", "Highlighted", "Pressed", "Selected", "Disabled" };

	[Header("Tooltip")]
	[SerializeField]
	private TooltipButtonTooltip _tooltipPrefab;

	[SerializeField]
	protected LocalizedString _tooltipMessage = null;

	private bool _pointerIsOver;

	private GraphicStates[] _graphicStates;

	private SelectionState _graphicState;

	public string[] States => STATES;

	protected override void Awake()
	{
		base.Awake();
		_graphicStates = GetComponentsInChildren<GraphicStates>();
		SetGraphicState(base.currentSelectionState, initialize: true);
	}

	protected override void LateUpdate()
	{
		base.LateUpdate();
		if (Application.isPlaying && base.interactable)
		{
			_tooltipPrefab.Close(this);
		}
		SetGraphicState(base.currentSelectionState);
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		if (Application.isPlaying)
		{
			_tooltipPrefab.Close(this);
		}
	}

	public override void OnPointerClick(PointerEventData eventData)
	{
		base.OnPointerClick(eventData);
		if (!base.interactable && _pointerIsOver)
		{
			_tooltipPrefab.Display(ReturnTooltip(), this, eventData.position);
		}
	}

	public override void OnPointerEnter(PointerEventData eventData)
	{
		base.OnPointerEnter(eventData);
		_pointerIsOver = true;
	}

	public override void OnPointerExit(PointerEventData eventData)
	{
		base.OnPointerExit(eventData);
		_pointerIsOver = false;
		_tooltipPrefab.Close(this);
	}

	public void SetTooltipMessage(LocalizedString message)
	{
		_tooltipMessage = message;
	}

	public virtual string ReturnTooltip()
	{
		return _tooltipMessage;
	}

	public void PreviewState(string state)
	{
		GraphicStates[] componentsInChildren = GetComponentsInChildren<GraphicStates>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].PreviewState(state, propagate: false);
		}
	}

	private void SetGraphicState(SelectionState selectionState, bool initialize = false)
	{
		if (_graphicState != selectionState || initialize)
		{
			string state = STATES[(int)selectionState];
			GraphicStates[] graphicStates = _graphicStates;
			for (int i = 0; i < graphicStates.Length; i++)
			{
				graphicStates[i].SetState(state);
			}
			_graphicState = selectionState;
		}
	}
}
public class TooltipButtonTooltip : MonoBehaviour
{
	[SerializeField]
	private Canvas _root;

	[SerializeField]
	private TextMeshProUGUI _messageText;

	[SerializeField]
	private ChildBehaviourCache<IconWithLabel> _bullitPrefab;

	[SerializeField]
	private float _offsetY = 12f;

	[SerializeField]
	[Tooltip("Since the a tooltip cannor be 'closed' by moving the cursor we set a maximum duration for the tooltip.")]
	private float _joystickMaximumDuration = 5f;

	private object _owner;

	private float _duration = -1f;

	private void Awake()
	{
		if (_root == null)
		{
			_root = GetComponentInParent<Canvas>();
		}
	}

	private void LateUpdate()
	{
		if (0f < _duration)
		{
			_duration -= Time.deltaTime;
			if (_duration <= 0f || FlotsamInputManager.GetUICancel())
			{
				Close(_owner);
			}
		}
	}

	public void Display(string message, object owner, Vector2 position)
	{
		if ((bool)_root)
		{
			_messageText.text = message;
			_messageText.gameObject.SetActive(value: true);
			_bullitPrefab.Reset();
			_bullitPrefab.Trim();
			Display(owner, position);
		}
		else
		{
			TooltipPanel.DisplayErrorTooltip(owner, position, message);
		}
	}

	public void Display(List<LocalizedString> errors, object owner, Vector2 position)
	{
		if (_root == null)
		{
			throw new NotSupportedException("This method should never be called from a prefab!");
		}
		_messageText.gameObject.SetActive(value: false);
		_bullitPrefab.Reset();
		foreach (LocalizedString error in errors)
		{
			_bullitPrefab.Get(active: true).Initialize(null, error);
		}
		_bullitPrefab.Trim();
		Display(owner, position);
	}

	private void Display(object owner, Vector2 position)
	{
		_owner = owner;
		_duration = (FlotsamInputManager.HasActiveInput(InputFlags.Joystick) ? _joystickMaximumDuration : 0f);
		position.y += _offsetY * _root.scaleFactor;
		base.transform.SetParent(_root.transform, worldPositionStays: false);
		base.transform.position = position;
		base.gameObject.SetActive(value: true);
		StopAllCoroutines();
		StartCoroutine(DisplayCoroutine());
	}

	private IEnumerator DisplayCoroutine()
	{
		base.transform.localScale = Vector3.zero;
		yield return Tweener.TweenRoutine(0.5f, EasingFunctions.ElasticOut, true, new TransformScaleTweener(base.transform, 1f));
	}

	public void Close(object owner)
	{
		if (_root == null)
		{
			TooltipPanel.CloseErrorTooltip(owner);
		}
		else if (base.gameObject.activeSelf && _owner == owner)
		{
			StopAllCoroutines();
			StartCoroutine(CloseCoroutine());
			_owner = null;
			_duration = 0f;
		}
	}

	private IEnumerator CloseCoroutine()
	{
		yield return Tweener.TweenRoutine(0.15f, EasingFunctions.SineIn, true, new TransformScaleTweener(base.transform, 0f));
		base.gameObject.SetActive(value: false);
	}
}
