	[Header("Settings")]
	[SerializeField]
	[Tooltip("Does this bar use an item tag as filter?")]
	private bool _useInventoryTag = true;

	[SerializeField]
	[Tooltip("The item tag used to toggle this bar on or off.")]
	[EnumFlag(1)]
	private Item.Tags _inventoryTag;

	[SerializeField]
	[Range(0f, 1f)]
	[Tooltip("The threshold for the capacity warning as a percentage of the total capacity.")]
	private float _warningThreshold = 0.9f;

	[Header("UI Components")]
	[SerializeField]
	[Tooltip("Reference to the slider used for display the amount of items that are currently in the inventory.")]
	private Slider _inInventorySlider;

	[SerializeField]
	[Tooltip("Reference to the slider used for display the amount of items that are currently reserved to go to the inventory.")]
	private Slider _reservedSlider;

	[SerializeField]
	[Tooltip("Reference to the text used for displaying the usage/capacity in plain text.")]
	private TextMeshProUGUI _text;

	[SerializeField]
	[Tooltip("Reference to the image used for the capacity warning.")]
	private Image _warning;

	[SerializeField]
	private Animator _animator;

	[SerializeField]
	[Tooltip("Boolean that decides whether we need to look at the liquid subinventory or not.")]
	private bool _isLiquid;

	public void OnDisable()
	{
		if (_inventory != null)
		{
			_inventory.InventoryUpdatedEvent.RemoveListener(UpdateCapacity);
			_inventory = null;
		}
	}

	public bool Initialize(ICommunalInventory inventory, Item.Tags filter)
	{
		if ((_inventoryTag & filter) != Item.Tags.None || _inventoryTag == Item.Tags.None)
		{
			base.gameObject.SetActive(value: true);
			Initialize(inventory);
			if (filter != Item.Tags.None)
			{
				return filter == _inventoryTag;
			}
			return false;
		}
		base.gameObject.SetActive(value: false);
		return false;
	}

	public override void UpdateCapacity()
	{
		SubInventoryType subInventory = (_isLiquid ? SubInventoryType.Liquid : SubInventoryType.Storage);
		int num;
		int num2;
		int num3;
		if (_useInventoryTag)
		{
			num = _inventory.ReturnCapacity(_inventoryTag);
			num2 = _inventory.ReturnCount(_inventoryTag, includeReserved: true);
			num3 = _inventory.ReturnIncomingItemsAmount(_inventoryTag);
		}
		else
		{
			num = _inventory.ReturnCapacity(subInventory);
			num2 = _inventory.ReturnCount(subInventory, includeReserved: true);
			num3 = _inventory.ReturnIncomingItemsAmount(subInventory);
		}
		float num4 = (float)num2 / (float)num;
		float num5 = (float)num3 / (float)num;
		if (num == 0)
		{
			num4 = (num5 = 0f);
		}
		else
		{
			num4 = (float)num2 / (float)num;
			num5 = (float)num3 / (float)num;
		}
		_text.text = $"{num2 + num3} / {num}";
		_inInventorySlider.value = (_inInventorySlider.maxValue - _inInventorySlider.minValue) * num4;
		if (num3 == 0)
		{
			_reservedSlider.value = 0f;
		}
		else
		{
			_reservedSlider.value = (_reservedSlider.maxValue - _reservedSlider.minValue) * (num4 + num5);
		}
		if ((bool)_warning && !_isLiquid)
		{
			_warning.enabled = _warningThreshold <= num4 + num5;
		}
		if ((bool)_animator && !_isLiquid)
		{
			_animator.SetBool("Is Low", _warningThreshold <= num4 + num5);
		}
	}
}
[RequireComponent(typeof(Tooltip))]
public class InventoryPanelItemSlot : MonoBehaviour, IPointerClickHandler, IEventSystemHandler, GUIItemSlot
{
	[Header("Background")]
	[SerializeField]
	private bool _applyBackgroundColor = true;

	[SerializeField]
	[Tooltip("The default background sprite.")]
	private Sprite _defaultBackground;

	[Header("References")]
	[SerializeField]
	[Tooltip("The image used for the background of the slot.")]
	protected Image _background;

	[SerializeField]
	[Tooltip("The text used for displaying the item count.")]
	protected TextMeshProUGUI _counter;

	[SerializeField]
	[Tooltip("The image used for the icon of the item.")]
	protected Image _icon;

	[SerializeField]
	[Tooltip("Should the icon be disabled when the ItemProperties are null?")]
	protected bool _disableIcon;

	[SerializeField]
	[Tooltip("An optional label to display the items name")]
	private TextMeshProUGUI _label;

	protected IInventoryView _inventoryView;

	protected ItemTooltip _tooltip;

	private int _count = int.MinValue;

	public ItemProperties ItemProperties { get; private set; }

	private void Awake()
	{
		if (_inventoryView == null)
		{
			_inventoryView = GetComponentInParent<IInventoryView>();
		}
	}

	public void Initialize(ItemProperties itemProperties)
	{
		Initialize(itemProperties, 0, showCounter: false);
	}

	public void Initialize(InventoryAuditor.CountedItem countedItem)
	{
		Initialize(countedItem.ItemProperties, countedItem.UnreservedCount);
	}

	public virtual void Initialize(ItemProperties itemProperties, int itemCount, bool showCounter = true)
	{
		if (ItemProperties != itemProperties)
		{
			bool flag = itemProperties != null;
			ItemProperties = itemProperties;
			if (_tooltip == null)
			{
				_tooltip = GetComponent<ItemTooltip>();
			}
			if ((bool)_tooltip)
			{
				_tooltip.Initialize(itemProperties);
			}
			_icon.enabled = flag || !_disableIcon;
			_icon.overrideSprite = (flag ? itemProperties.InventorySprite : null);
			if ((bool)_label)
			{
				_label.text = (flag ? itemProperties.LocalizedName : string.Empty);
			}
		}
		if ((bool)_counter)
		{
			_counter.gameObject.SetActive(showCounter);
			if (showCounter)
			{
				SetCount(itemCount);
			}
		}
		SetBackground(itemCount, itemProperties);
		if (!base.gameObject.activeSelf)
		{
			base.gameObject.SetActive(value: true);
		}
	}

	public void OnPointerClick(PointerEventData eventData)
	{
		if (eventData.button == PointerEventData.InputButton.Right && _inventoryView != null && !ItemProperties.IsQuestItem)
		{
			_inventoryView.ThrowItem(ItemProperties);
		}
	}

	protected void SetBackground(int itemCount, ItemProperties properties)
	{
		_background.sprite = _defaultBackground;
		if (_applyBackgroundColor)
		{
			_background.color = ((itemCount == 0) ? GameManager.Settings.ItemSettings.DisabledColor : properties.ItemType.Color);
		}
	}

	public void SetCount(int count)
	{
		if (_count != count)
		{
			_count = count;
			_counter.text = count.ToString();
			SetBackground(count, ItemProperties);
		}
	}

	public void SetSize(int index, float size, float padding)
	{
		RectTransform obj = base.transform as RectTransform;
		float size2 = size - padding * (float)index;
		obj.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, size2);
		obj.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, size2);
	}

	GameObject GUIItemSlot.get_gameObject()
	{
		return base.gameObject;
	}

	Transform GUIItemSlot.get_transform()
	{
		return base.transform;
	}
}
