public class MarkerOrderPanel : Panel
{
	[Tooltip("The parent transform under which we will spawn all the entries.")]
	public Transform EntryParent;

	[Tooltip("A reference to the draggableScrollRect on the scrollrect component.")]
	public DraggableScrollRect MarkerScrollRect;

	private List<MarkerOrderPanelEntry> _entries = new List<MarkerOrderPanelEntry>();

	private bool _scrollRectLinked;

	private MarkerOrderPanelEntry[] _previousProjectOrder;

	[HideInInspector]
	public UnityEvent OnEntryChangedPositionEvent;

	private void Start()
	{
		GameEventDispatcher.AddListener(GameEventType.MarkerDestroyed, RemoveMarkerEntry);
		GameEventDispatcher.AddListener(GameEventType.MarkerManuallyRemoved, RemoveMarkerEntry);
		GameEventDispatcher.AddListener(GameEventType.MarkerPlaced, AddMarkerEntry);
		UpdatePanel();
		if (OnEntryChangedPositionEvent == null)
		{
			OnEntryChangedPositionEvent = new UnityEvent();
		}
	}

	private void Update()
	{
		if (MarkerScrollRect.Initialized && !_scrollRectLinked)
		{
			MarkerScrollRect.OnDraggableChangedPositionEvent.AddListener(UpdateMarkerEntriesProjectOrder);
			_scrollRectLinked = true;
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.MarkerDestroyed, RemoveMarkerEntry);
		GameEventDispatcher.RemoveListener(GameEventType.MarkerManuallyRemoved, RemoveMarkerEntry);
		GameEventDispatcher.RemoveListener(GameEventType.MarkerPlaced, AddMarkerEntry);
		MarkerScrollRect.OnDraggableChangedPositionEvent.RemoveListener(UpdateMarkerEntriesProjectOrder);
	}

	private void UpdatePanel()
	{
		IEnumerable<Marker> enumerable = _entries.Select((MarkerOrderPanelEntry markerEntry) => markerEntry.Marker);
		List<Marker> markers = Community.PlayerCommunity.Markers;
		foreach (Marker item in markers.Except(enumerable))
		{
			CreateEntry(item);
		}
		foreach (Marker item2 in enumerable.Except(markers))
		{
			RemoveEntry(item2);
		}
		UpdateEntriesProjectIndexes();
	}

	private void UpdateMarkerEntriesProjectOrder()
	{
		OnEntryChangedPositionEvent.Invoke();
		UpdateEntriesProjectIndexes();
	}

	private void AddMarkerEntry(GameEvent gameEvent)
	{
		Marker marker = (gameEvent as MarkerEvent).Marker;
		CreateEntry(marker);
		UpdateEntriesProjectIndexes();
	}

	private void RemoveMarkerEntry(GameEvent gameEvent)
	{
		Marker marker = (gameEvent as MarkerEvent).Marker;
		RemoveEntry(marker);
		UpdateEntriesProjectIndexes();
	}

	private void CreateEntry(Marker marker)
	{
		MarkerOrderPanelEntry markerOrderPanelEntry = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.MarkerOrderPanelEntryPrefab, EntryParent);
		markerOrderPanelEntry.Initialize(marker, this);
		_entries.Add(markerOrderPanelEntry);
	}

	private void RemoveEntry(Marker marker)
	{
		MarkerOrderPanelEntry markerOrderPanelEntry = _entries.Find((MarkerOrderPanelEntry entry) => entry.Marker == marker);
		if (!(markerOrderPanelEntry == null))
		{
			markerOrderPanelEntry.transform.GetSiblingIndex();
			_entries.Remove(markerOrderPanelEntry);
			markerOrderPanelEntry.UnsubscribeAll();
			markerOrderPanelEntry.transform.SetParent(null);
			UnityEngine.Object.Destroy(markerOrderPanelEntry.gameObject);
		}
	}

	private void UpdateEntriesProjectIndexes()
	{
		_previousProjectOrder = new MarkerOrderPanelEntry[_entries.Count];
		for (int i = 0; i < _entries.Count; i++)
		{
			_previousProjectOrder[_entries[i].ReturnPanelIndex()] = _entries[i];
		}
	}

	public int ReturnProjectOrderFromPanelIndex(int panelIndex)
	{
		return Community.PlayerCommunity.Projects.FindIndex((Project x) => x == _previousProjectOrder[panelIndex].Marker.Project);
	}
}
[RequireComponent(typeof(Draggable))]
public class MarkerOrderPanelEntry : UIInteractable
{
	[Space]
	[Header("Visuals")]
	[Tooltip("The parent under which we spawn the markerIcons.")]
	[SerializeField]
	private Transform _itemIconParent;

	[Tooltip("The text component that we use to display the amount of drifters.")]
	[SerializeField]
	private TextMeshProUGUI _drifterCount;

	[Tooltip("The image component that we use to display the type of the marker.")]
	[SerializeField]
	private Image _markerIcon;

	[Tooltip("GameObject that we turn on when object is selected.")]
	[SerializeField]
	private GameObject _border;

	[Tooltip("GameObject that we turn on when object is selected and/or hovered.")]
	[SerializeField]
	private GameObject _highlight;

	private MarkerOrderPanel _markerOrderPanel;

	private Dictionary<ItemProperties, MarkerIcon> _generatedIcons = new Dictionary<ItemProperties, MarkerIcon>();

	private DoubleClickDetector _doubleClickDetector = new DoubleClickDetector();

	private Draggable _dragElement;

	private List<ItemProperties> _activeIcons = new List<ItemProperties>();

	private bool _updateDrifterCount;

	public Marker Marker { get; private set; }

	public void Initialize(Marker marker, MarkerOrderPanel markerOrderPanel)
	{
		Marker = marker;
		_markerOrderPanel = markerOrderPanel;
		UpdateIcons();
		UpdateDrifterCount();
		GameEventDispatcher.AddListener(GameEventType.AgentStartAssignment, UpdateDrifterCount);
		GameEventDispatcher.AddListener(GameEventType.AgentFinishAssignment, UpdateDrifterCount);
		_markerOrderPanel.OnEntryChangedPositionEvent.AddListener(UpdateProjectOrder);
		Marker.UpdatedItemsInRadius.AddListener(UpdateIcons);
		_markerIcon.sprite = marker.MarkerCursorProperties.AgentIconSprite;
		_dragElement = GetComponent<Draggable>();
		_dragElement.BeginDrag.AddListener(SelectMarker);
		_dragElement.UseHoverSprites = true;
		Selector.SelectedObjectsUpdatedEvent += CheckHighlightEntry;
	}

	protected override void Start()
	{
		base.Start();
		CheckHighlightEntry();
	}

	private void LateUpdate()
	{
		if (_updateDrifterCount)
		{
			_drifterCount.text = $"{Marker.Project.Assignments.Count}/{Marker.Project.AssignmentLimit}";
			_updateDrifterCount = false;
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		GameEventDispatcher.RemoveListener(GameEventType.AgentStartAssignment, UpdateDrifterCount);
		GameEventDispatcher.RemoveListener(GameEventType.AgentFinishAssignment, UpdateDrifterCount);
	}

	public void SelectMarker()
	{
		Selector.Select(Marker.gameObject, ObjectType.CommunityMember);
		if (_doubleClickDetector.IsDoubleClick())
		{
			CameraController.Instance.Lock(Marker.gameObject);
		}
	}

	public void FocusMarker()
	{
		CameraController.Instance.Lock(Marker.gameObject);
	}

	private void UpdateIcons()
	{
		List<ItemProperties> list = _generatedIcons.Keys.ToList();
		foreach (ItemProperties item in Marker.ItemTypesInRange)
		{
			MarkerIcon markerIcon = (_generatedIcons.ContainsKey(item) ? _generatedIcons[item] : CreateIcon(item));
			Marker.ItemFilter.TryGetValue(item, out var value);
			if (value)
			{
				markerIcon.gameObject.SetActive(value: true);
				list.Remove(item);
			}
		}
		foreach (ItemProperties item2 in list)
		{
			_generatedIcons[item2].gameObject.SetActive(value: false);
		}
	}

	private void UpdateDrifterCount(GameEvent gameEvent = null)
	{
		_updateDrifterCount = gameEvent == null || gameEvent.EventType == GameEventType.AgentStartAssignment || gameEvent.EventType == GameEventType.AgentFinishAssignment;
	}

	private MarkerIcon CreateIcon(ItemProperties itemProperties)
	{
		MarkerIcon markerIcon = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.MarkerIconPrefab, _itemIconParent);
		markerIcon.Initialize(itemProperties);
		_generatedIcons.Add(itemProperties, markerIcon);
		markerIcon.gameObject.SetActive(value: false);
		return markerIcon;
	}

	private void CheckHighlightEntry()
	{
		_ = Color.white;
		if (Selector.Selection != null)
		{
			SelectionLink selection = Selector.Selection;
			if (selection.Type == ObjectType.Marker && !(selection.ObjectToSelect != Marker.gameObject))
			{
				_border.SetActive(value: true);
				_highlight.SetActive(value: true);
				_dragElement.CanExitHover = false;
			}
		}
		else
		{
			_border.SetActive(value: false);
			_highlight.SetActive(value: false);
			_dragElement.CanExitHover = true;
		}
	}

	private void UpdateProjectOrder()
	{
		int index = _markerOrderPanel.ReturnProjectOrderFromPanelIndex(ReturnPanelIndex());
		Community.PlayerCommunity.Projects[index] = Marker.Project;
	}

	public void UnsubscribeAll()
	{
		Marker.UpdatedItemsInRadius.RemoveListener(UpdateIcons);
		_dragElement.BeginDrag.RemoveListener(SelectMarker);
		_markerOrderPanel.OnEntryChangedPositionEvent.RemoveListener(UpdateProjectOrder);
		Selector.SelectedObjectsUpdatedEvent -= CheckHighlightEntry;
	}

	public int ReturnPanelIndex()
	{
		return base.transform.GetSiblingIndex();
	}
}
public class MarkerPanel : Panel
{
	[Header("Project settings")]
	[SerializeField]
	private ProjectMalfunctionPanel _projectMalfunctionPanel;

	[Tooltip("The minimum limit of assignees that can be assigned to the marker project.")]
	[SerializeField]
	private int _assignLimitMinimum;

	[Tooltip("The maximum limit of assignees that can be assigned to the marker project.")]
	[SerializeField]
	private int _assignLimitMaximum = 5;

	[Header("Marker Panel Settings")]
	[SerializeField]
	private DrifterCounter _drifterCounter;

	[SerializeField]
	private RadiusResizer _radiusResizer;

	[SerializeField]
	[Tooltip("Prefab used to display items.")]
	private MarkerPanelItemSlot _itemSlotPrefab;

	[SerializeField]
	[Tooltip("The parent for the displayed item slots.")]
	private RectTransform _itemSlotParent;

	private Marker _marker;

	private Community _playerCommunity;

	private InventoryAuditor _auditor;

	private List<MarkerPanelItemSlot> _itemSlots;

	private void Update()
	{
		UpdateItemSlots();
		if (_marker == null)
		{
			Close();
		}
	}

	private void OnDestroy()
	{
		foreach (MarkerPanelItemSlot itemSlot in _itemSlots)
		{
			itemSlot.OnToggleEvent.RemoveListener(OnItemSlotToggle);
			UnityEngine.Object.Destroy(itemSlot);
		}
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (context is Marker marker && base.Open(id, context))
		{
			if (_auditor == null)
			{
				_auditor = new InventoryAuditor();
			}
			if (_playerCommunity == null)
			{
				_playerCommunity = Community.PlayerCommunity;
			}
			if (_itemSlots == null)
			{
				_itemSlots = new List<MarkerPanelItemSlot>();
			}
			_marker = marker;
			_projectMalfunctionPanel.Initialize(_marker.Project);
			_drifterCounter.Initialize(_assignLimitMinimum, _assignLimitMaximum, marker.Project.AssignmentLimit);
			_drifterCounter.OnValueChanged.AddListener(OnAgentUpdate);
			_radiusResizer.Initialize(marker.CurrentRadiusIntervalIndex);
			_radiusResizer.OnValueChanged.AddListener(OnRadiusResized);
			UpdateItemSlots();
			_playerCommunity.ShowMarkerHighlights(enabled: true);
			_marker.ShowMarkerHighlight(enable: true, selected: true);
			return true;
		}
		return false;
	}

	public override void Close()
	{
		base.Close();
		if (!(_marker == null))
		{
			_drifterCounter.OnValueChanged.RemoveListener(OnAgentUpdate);
			_radiusResizer.OnValueChanged.RemoveListener(OnRadiusResized);
			Selector.Deselect(_marker.gameObject);
			_playerCommunity.ShowMarkerHighlights(enabled: false);
			_projectMalfunctionPanel.Uninitialize();
			_marker = null;
		}
	}

	private void OnAgentUpdate(int count)
	{
		_marker.SetAgentAmount(_drifterCounter.Count);
	}

	private void OnRadiusResized(int index)
	{
		_marker.SetSizeIndex(index);
	}

	public void RemoveMarker()
	{
		MarkerEvent.Dispatch(GameEventType.MarkerManuallyRemoved, _marker);
		_marker.Remove();
		Close();
	}

	private void OnItemSlotToggle(ItemProperties properties)
	{
		_marker.ToggleItemFilter(properties);
	}

	private void UpdateItemSlots()
	{
		int i = 0;
		_auditor.Reset();
		_auditor.CountItems(_marker.AllowedItemsInRadius);
		foreach (InventoryAuditor.CountedItem countedItem in _auditor.CountedItems)
		{
			if (countedItem.UnreservedCount == 0)
			{
				continue;
			}
			MarkerPanelItemSlot markerPanelItemSlot;
			if (i < _itemSlots.Count)
			{
				markerPanelItemSlot = _itemSlots[i];
				if (!markerPanelItemSlot.gameObject.activeSelf)
				{
					markerPanelItemSlot.gameObject.SetActive(value: true);
				}
			}
			else
			{
				markerPanelItemSlot = UnityEngine.Object.Instantiate(_itemSlotPrefab, _itemSlotParent);
				_itemSlots.Add(markerPanelItemSlot);
			}
			markerPanelItemSlot.Initialize(countedItem.ItemProperties, countedItem.UnreservedCount, _marker.ReturnIsItemFilterToggled(countedItem.ItemProperties));
			markerPanelItemSlot.OnToggleEvent.AddListener(OnItemSlotToggle);
			i++;
		}
		for (; i < _itemSlots.Count; i++)
		{
			_itemSlots[i].gameObject.SetActive(value: false);
		}
	}

	public void CycleMarker(int indexAddition)
	{
		List<Marker> markers = _playerCommunity.Markers;
		int num = markers.IndexOf(_marker);
		int count = markers.Count;
		num += indexAddition;
		if (num < 0)
		{
			num = count - 1;
		}
		else if (num >= count)
		{
			num = 0;
		}
		GameObject gameObject = markers[num].gameObject;
		CameraController.Instance.Lock(gameObject, CameraController.Instance.CurrentZoomLevel);
		Selector.Select(gameObject, ObjectType.Marker);
	}
}
public class MarkerPanelItemSlot : MonoBehaviour
{
	[SerializeField]
	[Tooltip("The item slot used to display the item.")]
	public InventoryPanelItemSlot _itemSlot;

	[SerializeField]
	[Tooltip("The toggle used to toggle between the item being salvaged or not.")]
	private MarkerPanelToggle _toggle;

	private bool _initializedToggle;

	public ItemProperties Properties { get; private set; }

	public bool IsOn
	{
		get
		{
			if (_toggle.enabled)
			{
				return _toggle.IsOn;
			}
			return false;
		}
	}

	public UnityItemPropertiesEvent OnToggleEvent { get; private set; }

	public void Initialize(ItemProperties properties, int markerCount, bool isEnabled, bool hideToggle = false, bool showCounter = true)
	{
		Properties = properties;
		_itemSlot.Initialize(properties, markerCount, showCounter);
		if (OnToggleEvent == null)
		{
			OnToggleEvent = new UnityItemPropertiesEvent();
		}
		else
		{
			OnToggleEvent.RemoveAllListeners();
		}
		if (hideToggle)
		{
			_toggle.enabled = false;
		}
		else
		{
			if (!_initializedToggle)
			{
				_toggle.OnToggleEvent.AddListener(OnToggle);
				_initializedToggle = true;
			}
			_toggle.enabled = true;
			_toggle.Toggle(isEnabled, invokeOnToggleEvent: false);
		}
		base.gameObject.SetActive(value: true);
	}

	private void OnDestroy()
	{
		_toggle.OnToggleEvent.RemoveListener(OnToggle);
	}

	private void OnToggle()
	{
		OnToggleEvent.Invoke(Properties);
	}

	public void SetMarkerCount(int markerCount)
	{
		_itemSlot.SetCount(markerCount);
	}
}
public class MarkerPanelToggle : UIBehaviour, IPointerDownHandler, IEventSystemHandler
{
	[SerializeField]
	[Tooltip("The image that displays the toggle on/off icon.")]
	private Image _target;

	[SerializeField]
	[Tooltip("The sprite displayed when the toggle is on.")]
	private Sprite _on;

	[SerializeField]
	[Tooltip("The sprite displayed when the toggle is off.")]
	private Sprite _off;

	[SerializeField]
	[Tooltip("Is the toggle interactable?")]
	private bool _interactable;

	private UnityEvent _onToggleEvent = new UnityEvent();

	public bool IsOn { get; private set; }

	public UnityEvent OnToggleEvent => _onToggleEvent;

	protected override void OnEnable()
	{
		base.OnEnable();
		_target.enabled = true;
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		_target.enabled = false;
	}

	public void Toggle(bool isOn, bool invokeOnToggleEvent = true)
	{
		if (isOn)
		{
			_target.sprite = _on;
		}
		else
		{
			_target.sprite = _off;
		}
		IsOn = isOn;
		if (invokeOnToggleEvent)
		{
			_onToggleEvent.Invoke();
		}
	}

	public void OnPointerDown(PointerEventData eventData)
	{
		if (_interactable && eventData.button == PointerEventData.InputButton.Left)
		{
			Toggle(!IsOn);
		}
	}
}
public class TextBoxCounter : CounterBase
{
