public class ProductionPanelRecipeToggle : PLToggle
{
	[Header("Recipe Toggle")]
	[SerializeField]
	private Image _itemImage;

	[SerializeField]
	private Image _malfunctionImage;

	[SerializeField]
	private Image _continuousImage;

	[SerializeField]
	private TextMeshProUGUI _amountField;

	[Header("Animator")]
	[SerializeField]
	private Animator _animator;

	[SerializeField]
	private string _animatorSelectedParameter = "Selected";

	[SerializeField]
	private string _animatorContinuousParameter = "Continuous";

	private ItemTooltip _tooltip;

	private bool _isToProduce;

	private int _amount = int.MinValue;

	public Producer Producer { get; private set; }

	public Producer.Recipe Recipe { get; private set; }

	public ItemProperties ItemProperties { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if ((bool)base.animator)
		{
			base.animator.keepAnimatorStateOnDisable = true;
		}
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		if (Producer != null)
		{
			UpdateState();
		}
	}

	protected override void LateUpdate()
	{
		base.LateUpdate();
		UpdateToProduce();
	}

	public void Initialize(Producer producer, Producer.Recipe recipe)
	{
		Producer = producer;
		Recipe = recipe;
		if (recipe.IsUnlocked())
		{
			ItemProperties = recipe.GetFirstProducedItemProperties();
			_itemImage.overrideSprite = recipe.GetIcon(ItemProperties);
			if (_tooltip == null)
			{
				_tooltip = this.GetOrAddComponent<ItemTooltip>();
			}
			_tooltip.IsEnabled = true;
			_tooltip.Initialize(ItemProperties);
		}
		else
		{
			base.isOn = false;
			base.gameObject.SetActive(value: false);
		}
	}

	public void UpdateState()
	{
		if (base.isActiveAndEnabled && Recipe != null)
		{
			base.isOn = Producer.SelectedRecipe == Recipe;
			_malfunctionImage.overrideSprite = null;
			if (0 < Recipe.Malfunctions.Count)
			{
				_malfunctionImage.gameObject.SetActive(value: true);
				_continuousImage.gameObject.SetActive(value: false);
				_amountField.gameObject.SetActive(value: false);
				_malfunctionImage.overrideSprite = Recipe.Malfunctions[0].UIIconProperties.Sprite;
			}
			else if (Recipe.IsContinuous)
			{
				_malfunctionImage.gameObject.SetActive(value: false);
				_continuousImage.gameObject.SetActive(value: true);
				_amountField.gameObject.SetActive(value: false);
			}
			else
			{
				_malfunctionImage.gameObject.SetActive(value: false);
				_continuousImage.gameObject.SetActive(value: false);
				_amountField.gameObject.SetActive(value: true);
			}
			_animator?.SetBool(_animatorSelectedParameter, base.isOn);
			UpdateToProduce();
		}
	}

	private void UpdateToProduce()
	{
		if (base.isActiveAndEnabled && Recipe != null)
		{
			bool flag = Recipe.IsContinuous || Recipe.AmountToProduce > 0;
			if (flag != _isToProduce)
			{
				_isToProduce = flag;
				_animator?.SetBool(_animatorContinuousParameter, _isToProduce);
			}
			if (_amount != Recipe.AmountToProduce)
			{
				_amount = Recipe.AmountToProduce;
				_amountField.text = _amount.ToString();
			}
		}
	}

	public void SetSelected(bool selected)
	{
		_animator?.SetBool(_animatorSelectedParameter, selected);
	}
}
[Serializable]
public class QuestCategory : IPage, IComparable<IPage>, ICategoryPage
{
	[SerializeField]
	private QuestType[] _questTypes;

	[SerializeField]
	private LocalizedString _name;

	[SerializeField]
	private Sprite _icon;

	public string ID => null;

	public string Name => _name;

	public Sprite Icon => _icon;

	public string CompareString => null;

	public List<IPage> SubPages { get; private set; } = new List<IPage>();

	public void Populate(List<Quest> quests)
	{
		SubPages.Clear();
		foreach (Quest quest in quests)
		{
			if (_questTypes.Contains(quest.Properties.QuestType))
			{
				SubPages.Add(quest);
			}
		}
	}

	public void PopulateQuestType(List<QuestType> questTypes)
	{
		questTypes.AddRange(_questTypes);
	}

	public int CompareTo(IPage other)
	{
		throw new NotImplementedException();
	}
}
public class QuestLog : Panel, ISelectableGroupFirstSelectedProvider
{
	[SerializeField]
	private QuestCategory[] _categories;

	[SerializeField]
	private ChildBehaviourCache<CategoryPageIndex> _categoryPrefab;

	[SerializeField]
	private QuestLogPage _questLogPage;

	[SerializeField]
	private SelectableGroup _selectableGroup;

	[SerializeField]
	private Accordion _accordion;

	private QuestLogIndex _selectedIndex;

	private List<QuestType> _loggedQuestTypes = new List<QuestType>();

	private Transform _transform;

	private void LateUpdate()
	{
		if ((bool)_transform)
		{
			_accordion.ToggleParent(_transform, instantTransition: true);
			_transform = null;
		}
	}

	public override bool Open(PanelID id, IPanelContext context = null)
	{
		if (!base.Open(id, context))
		{
			return false;
		}
		_selectableGroup.Initialize(clearSelected: true);
		_accordion.SelectableGroup.RemoveChildren();
		_accordion.Initialize();
		if (TryGetSelectedQuestIndex(out var selectedIndex))
		{
			SetSelectedIndex(selectedIndex);
			_transform = selectedIndex.transform;
		}
		GameEventDispatcher.AddListener(GameEventType.OpenQuestLogPage, OnOpenQuestLogPage);
		return true;
	}

	protected override void OnOpen(IPanelContext context)
	{
		_categoryPrefab.Reset();
		if (StoryManager.TryGetLogQuests(out var logQuests, GetLoggedQuestTypes()))
		{
			QuestCategory[] categories = _categories;
			foreach (QuestCategory questCategory in categories)
			{
				questCategory.Populate(logQuests);
				if (0 < questCategory.SubPages.Count)
				{
					_categoryPrefab.Get(active: true).Initialize(questCategory);
				}
			}
		}
		_categoryPrefab.Trim();
	}

	public override void Close()
	{
		GameEventDispatcher.RemoveListener(GameEventType.OpenQuestLogPage, OnOpenQuestLogPage);
		base.Close();
	}

	public bool TryGetFirstSelected(out Selectable selectable)
	{
		if (TryGetSelectedQuestIndex(out var selectedIndex))
		{
			selectable = selectedIndex.Selectable;
			return true;
		}
		selectable = null;
		return false;
	}

	private bool TryGetSelectedQuestIndex(out QuestLogIndex selectedIndex)
	{
		if ((bool)_selectedIndex)
		{
			selectedIndex = _selectedIndex;
			return true;
		}
		if (StoryManager.TryGetQuestLogQuest(out var quest))
		{
			for (int i = 0; i < _categoryPrefab.Count; i++)
			{
				if (_categoryPrefab[i].TryGetPageIndex<QuestLogIndex>(out selectedIndex, quest))
				{
					return true;
				}
			}
		}
		selectedIndex = null;
		return false;
	}

	private void OnOpenQuestLogPage(GameEvent gameEvent)
	{
		if (gameEvent is PageEvent { Index: QuestLogIndex index })
		{
			SetSelectedIndex(index);
		}
	}

	private void SetSelectedIndex(QuestLogIndex index)
	{
		if (!(index == null))
		{
			if ((bool)_selectedIndex)
			{
				_selectedIndex.SetActivePageIndex(active: false);
			}
			_questLogPage.Initialize(index.Quest);
			_selectedIndex = index;
			_selectedIndex.SetActivePageIndex(active: true);
		}
	}

	public override bool CanBeOpened(PanelID panelID, IPanelContext context = null)
	{
		List<Quest> logQuests;
		if (base.CanBeOpened(panelID, context))
		{
			return StoryManager.TryGetLogQuests(out logQuests, GetLoggedQuestTypes());
		}
		return false;
	}

	private List<QuestType> GetLoggedQuestTypes()
	{
		_loggedQuestTypes.Clear();
		QuestCategory[] categories = _categories;
		for (int i = 0; i < categories.Length; i++)
		{
			categories[i].PopulateQuestType(_loggedQuestTypes);
		}
		return _loggedQuestTypes;
	}
}
public class QuestLogIndex : PageIndex
{
	[Header("Quest Log Index")]
	[SerializeField]
	private Image _questIcon;

	[SerializeField]
	private Image _trackedIcon;

	[Header("Animator Parameters")]
	[SerializeField]
	private string _trackedParameter = "QuestLog_Tracked";

	[SerializeField]
	private string _completedParameter = "QuestLog_Completed";

	public Quest Quest { get; private set; }

	protected override void OnEnable()
	{
		FocusManager.CurrentSelectedGameObjectChanged.AddListener(OnCurrentSelectedGameObjectChanged);
		base.OnEnable();
	}

	private void OnDisable()
	{
		FocusManager.CurrentSelectedGameObjectChanged.RemoveListener(OnCurrentSelectedGameObjectChanged);
		RemoveListeners();
	}

	internal override void Initialize(IPage page)
	{
		base.Initialize(page);
		if (page is Quest quest)
		{
			Quest = quest;
			if ((bool)_questIcon)
			{
				_questIcon.overrideSprite = quest.Properties.IndexIcon;
			}
			OnQuestUpdated();
			RemoveListeners();
			AddListeners();
			UpdateAnimatorState();
		}
	}

	protected override void UpdateAnimatorState()
	{
		if (!(base.Animator == null))
		{
			base.Animator.SetBool(_trackedParameter, Quest.Tracked);
			base.Animator.SetBool(_completedParameter, Quest.IsCompleted);
			base.UpdateAnimatorState();
		}
	}

	private void AddListeners()
	{
		GameEventDispatcher.AddListener(GameEventType.QuestStarted, OnQuestUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestUpdated, OnQuestUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestCompleted, OnQuestUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestFailed, OnQuestUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestAbandoned, OnQuestUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestTracked, OnQuestUpdated);
	}

	private void RemoveListeners()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestStarted, OnQuestUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestUpdated, OnQuestUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestCompleted, OnQuestUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestFailed, OnQuestUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestAbandoned, OnQuestUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestTracked, OnQuestUpdated);
	}

	private void OnQuestUpdated(GameEvent gameEvent = null)
	{
		UpdateAnimatorState();
		if ((bool)_trackedIcon)
		{
			_trackedIcon.gameObject.SetActive(Quest != null && StoryManager.IsActiveQuest(Quest));
		}
	}

	private void OnCurrentSelectedGameObjectChanged(GameObject gameObject)
	{
		if (base.Selectable.gameObject == gameObject)
		{
			Select();
		}
	}
}
