public class RadioPanel : TMP_DropdownItemFormatter, IBuildablePanelElement
{
	[Header("Radio Panel")]
	[SerializeField]
	private Slider _progressSlider;

	[SerializeField]
	private Button _button;

	[Header("Debug")]
	[SerializeField]
	private bool _alwaysInteractable;

	private Radio _radio;

	private Dictionary<TMP_DropdownFormatableItem, AgentProfile> _dropdownItems;

	public BuildablePanelElementId Id => BuildablePanelElementId.Radio;

	public bool Activate(Buildable buildable, bool finished)
	{
		if (finished && buildable.TryReturnBuildableExtendable<Radio>(out _radio))
		{
			base.gameObject.SetActive(value: true);
			_progressSlider.value = Mathf.Lerp(_progressSlider.minValue, _progressSlider.maxValue, 0f);
			InitializeDropdown();
			_button.onClick.AddListener(OnButtonClick);
			UpdateButtonState(base.SelectedIndex);
			OnUpdateInteractable();
			GameEventDispatcher.AddListener(GameEventType.RadioMessageManagerStateUpdated, OnUpdateInteractable);
			GameEventDispatcher.AddListener(GameEventType.PanelClosed, OnUpdateInteractable);
			GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnGameEvent);
			GameEventDispatcher.AddListener(GameEventType.AgentRemovedFromPlayerCommunity, OnGameEvent);
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		_button.onClick.RemoveListener(OnButtonClick);
		GameEventDispatcher.RemoveListener(GameEventType.RadioMessageManagerStateUpdated, OnUpdateInteractable);
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnUpdateInteractable);
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnGameEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRemovedFromPlayerCommunity, OnGameEvent);
		base.gameObject.SetActive(value: false);
	}

	private void InitializeDropdown()
	{
		if (!_dropdownItems.IsNullOrEmpty())
		{
			return;
		}
		using ListPool<string>.List list = ListPool<string>.Get();
		AgentProfile[] specialists = _radio.Specialists;
		foreach (AgentProfile agentProfile in specialists)
		{
			list.Add(agentProfile.PastBackground.Name);
		}
		Initialize(list);
	}

	private void UpdateButtonState(int selectedIndex)
	{
	}

	private void OnButtonClick()
	{
		if (!(_radio == null))
		{
			GameManager.UIManager.ClosePanel(PanelID.BuildablePanel);
			GameManager.UIManager.DisplayPanel(PanelID.RadioMessagePanel);
		}
	}

	protected override void AddItem(TMP_DropdownFormatableItem item)
	{
		if (_dropdownItems == null)
		{
			_dropdownItems = new Dictionary<TMP_DropdownFormatableItem, AgentProfile>();
		}
		AgentProfile agentProfile = ReturnSpecialist(_dropdownItems.Count);
		FormatDropdownItem(item, agentProfile, _dropdownItems.Count);
		_dropdownItems.Add(item, agentProfile);
	}

	protected override void RemoveItem(TMP_DropdownFormatableItem item)
	{
		if (!_dropdownItems.IsNullOrEmpty())
		{
			_dropdownItems.Remove(item);
		}
	}

	protected override void OnSelectedIndexChanged(int selectedIndex)
	{
		UpdateButtonState(selectedIndex);
	}

	private void FormatDropdownItem(TMP_DropdownFormatableItem item, AgentProfile specialist, int index)
	{
		if (IsInteractable(specialist))
		{
			item.Interactable = true;
			return;
		}
		item.Interactable = false;
		if (base.SelectedIndex == index)
		{
			ClearSelectedIndex();
		}
	}

	private AgentProfile ReturnSpecialist(int index)
	{
		return _radio.Specialists[index];
	}

	private void OnGameEvent(GameEvent gameEvent)
	{
		if (-1 < base.SelectedIndex && !IsInteractable(ReturnSpecialist(base.SelectedIndex)))
		{
			ClearSelectedIndex();
		}
	}

	private void OnUpdateInteractable(GameEvent gameEvent = null)
	{
		_button.interactable = ((Application.isEditor && _alwaysInteractable) || GameManager.RadioMessagesManager.IsReceivingRadioSignals) && !IsBlockedByPanel();
	}

	private bool IsInteractable(AgentProfile specialist)
	{
		if ((bool)specialist.PastBackground && !HasBackgroundInCommunity(specialist.PastBackground))
		{
			return !WorldMapCompass.HasBearingTo(specialist.PastBackground.ScoutingId);
		}
		return false;
	}

	private bool HasBackgroundInCommunity(DrifterAttributesEffect background)
	{
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent.Descriptor.PastBackground == background)
			{
				return true;
			}
		}
		return false;
	}

	private bool IsBlockedByPanel()
	{
		if (!GameManager.UIManager.IsPanelOpen(PanelID.DialoguePanel))
		{
			return GameManager.UIManager.IsPanelOpen(PanelID.RadioMessagePanel);
		}
		return true;
	}
}
public class RescuePanel : MonoBehaviour
{
	[Tooltip("Prefab used to spawn the rescueable drifter' information.")]
	[SerializeField]
	private RescueableDrifterInfo _rescueableDrifterInfoPrefab;

	[Tooltip("Prefab used to spawn the rescueable seagull' information.")]
	[SerializeField]
	private RescueableSeagullInfo _rescueableSeagullInfoPrefab;

	[Tooltip("Parent of the spawned Rescueable Agent Info elements.")]
	[SerializeField]
	private RectTransform _rescueableAgentInfoParent;

	private List<RescueableDrifterInfo> _rescuableDrifterEntries;

	private List<RescueableSeagullInfo> _rescuableSeagullEntries;

	private int _activeEntriesCount;

	public void Enable()
	{
		if (0 < _activeEntriesCount)
		{
			ResetPanel();
		}
	}

	public virtual void ResetPanel()
	{
		_activeEntriesCount = 0;
		if (_rescuableDrifterEntries != null)
		{
			foreach (RescueableDrifterInfo rescuableDrifterEntry in _rescuableDrifterEntries)
			{
				rescuableDrifterEntry.gameObject.SetActive(value: false);
			}
		}
		if (_rescuableSeagullEntries == null)
		{
			return;
		}
		foreach (RescueableSeagullInfo rescuableSeagullEntry in _rescuableSeagullEntries)
		{
			rescuableSeagullEntry.gameObject.SetActive(value: false);
		}
	}

	public void AddRescuable(ActorDescriptor actorDescriptor)
	{
		if (actorDescriptor is AgentDescriptor agentDescriptor)
		{
			AddRescuableAgentInfo(agentDescriptor);
		}
		else if (actorDescriptor is AnimalDescriptor descriptor)
		{
			AddRescuableAnimalInfo(descriptor);
		}
	}

	public void AddRescuableAgentInfo(AgentDescriptor agentDescriptor)
	{
		if (_rescuableDrifterEntries == null)
		{
			_rescuableDrifterEntries = new List<RescueableDrifterInfo>();
		}
		RescueableDrifterInfo rescueableDrifterInfo;
		if (_activeEntriesCount < _rescuableDrifterEntries.Count)
		{
			rescueableDrifterInfo = _rescuableDrifterEntries[_activeEntriesCount];
		}
		else
		{
			rescueableDrifterInfo = UnityEngine.Object.Instantiate(_rescueableDrifterInfoPrefab);
			_rescuableDrifterEntries.Add(rescueableDrifterInfo);
		}
		rescueableDrifterInfo.transform.SetParent(_rescueableAgentInfoParent, worldPositionStays: false);
		rescueableDrifterInfo.Initialize(agentDescriptor);
		rescueableDrifterInfo.gameObject.SetActive(value: true);
		_activeEntriesCount++;
	}

	public void AddRescuableAnimalInfo(AnimalDescriptor descriptor)
	{
		if (_rescuableSeagullEntries == null)
		{
			_rescuableSeagullEntries = new List<RescueableSeagullInfo>();
		}
		RescueableSeagullInfo rescueableSeagullInfo;
		if (_activeEntriesCount < _rescuableSeagullEntries.Count)
		{
			rescueableSeagullInfo = _rescuableSeagullEntries[_activeEntriesCount];
		}
		else
		{
			rescueableSeagullInfo = UnityEngine.Object.Instantiate(_rescueableSeagullInfoPrefab);
			_rescuableSeagullEntries.Add(rescueableSeagullInfo);
		}
		rescueableSeagullInfo.transform.SetParent(_rescueableAgentInfoParent, worldPositionStays: false);
		rescueableSeagullInfo.Initialize(descriptor);
		rescueableSeagullInfo.gameObject.SetActive(value: true);
		_activeEntriesCount++;
	}
}
public class SalvagePanel : MonoBehaviour
{
	[SerializeField]
	[Tooltip("Prefab used to display items.")]
	private MarkerPanelItemSlot _itemSlotPrefab;

	[SerializeField]
	[Tooltip("The parent for the displayed item slots.")]
	private RectTransform _itemSlotParent;

	[SerializeField]
	[Tooltip("If enabled, all the available items toggles will always be shown.")]
	private bool _showAllToggles = true;

	public ItemProperties.Event ItemSlotToggleEvent;

	private Project _project;

	private List<MarkerPanelItemSlot> _itemSlots;

	private int _activeItemSlotCount;

	public void Enable(Project project)
	{
		if (0 < _activeItemSlotCount)
		{
			OnDisable();
		}
		_project = project;
		if (ItemSlotToggleEvent == null)
		{
			ItemSlotToggleEvent = new ItemProperties.Event();
		}
	}

	protected virtual void OnDisable()
	{
		_activeItemSlotCount = 0;
		if (_itemSlots == null)
		{
			return;
		}
		foreach (MarkerPanelItemSlot itemSlot in _itemSlots)
		{
			itemSlot.OnToggleEvent.RemoveAllListeners();
			itemSlot.gameObject.SetActive(value: false);
		}
		ItemSlotToggleEvent.RemoveAllListeners();
	}

	public void AddItemSlot(ItemProperties itemProperties, int itemCount, bool enabled = true, bool hideToggle = false)
	{
		if (_showAllToggles || 0 < itemCount)
		{
			if (_itemSlots == null)
			{
				_itemSlots = new List<MarkerPanelItemSlot>();
			}
			MarkerPanelItemSlot markerPanelItemSlot;
			if (_activeItemSlotCount < _itemSlots.Count)
			{
				markerPanelItemSlot = _itemSlots[_activeItemSlotCount];
			}
			else
			{
				markerPanelItemSlot = UnityEngine.Object.Instantiate(_itemSlotPrefab);
				_itemSlots.Add(markerPanelItemSlot);
			}
			markerPanelItemSlot.Initialize(itemProperties, itemCount, enabled, hideToggle);
			markerPanelItemSlot.OnToggleEvent.AddListener(OnItemSlotToggle);
			markerPanelItemSlot.transform.SetParent(_itemSlotParent, worldPositionStays: false);
			markerPanelItemSlot.gameObject.SetActive(value: true);
			_activeItemSlotCount++;
		}
	}

	private void OnItemSlotToggle(ItemProperties itemProperties)
	{
		if (ItemSlotToggleEvent != null)
		{
			ItemSlotToggleEvent.Invoke(itemProperties);
		}
	}
}
