public class TownNamingPanel : InputPanel
{
	[Header("Town Naming Panel")]
	[SerializeField]
	private string _townNameRegex = "";

	[SerializeField]
	private TMP_InputField _townNameInputField;

	[SerializeField]
	private Button _startButton;

	private PlayerRun _activeRun;

	private void OnEnable()
	{
		_activeRun = Session.Profile.ActiveRun;
		_townNameInputField.characterLimit = GameManager.Settings.DataSettings.CommunityCharacterLimit;
		if (string.IsNullOrEmpty(_activeRun.CommunityName) || Session.Profile.HasInactiveRunWithCommunityName(_activeRun.CommunityName))
		{
			RandomizeName();
		}
		else
		{
			SetText(_activeRun.CommunityName);
		}
	}

	public void UI_StartGame()
	{
		if (IsBeingEdited())
		{
			return;
		}
		GameManager.WorldMapManager.WorldMap.ActivateForwardInputWait();
		string text = _townNameInputField.text.Trim();
		if (!Session.Profile.HasInactiveRunWithCommunityName(text))
		{
			if (!_activeRun.SetCommunityName(text))
			{
				UnityEngine.Debug.LogException(new Exception("Unable to change community name from '" + _activeRun.CommunityName + "' to '" + text + "'. It seens the active run already has saved games."));
			}
			new GameEvent(GameEventType.NewGameStart).Dispatch();
			Close();
		}
	}

	public void Sanitize(string text)
	{
		_townNameInputField.text = Regex.Replace(text, _townNameRegex, "");
	}

	public void CheckValidity(string text)
	{
		bool flag = !Session.Profile.HasInactiveRunWithCommunityName(text.Trim());
		bool flag2 = text.IndexOfAny(Path.GetInvalidFileNameChars()) < 0;
		_startButton.interactable = Application.isEditor || (flag && flag2);
	}

	public void OnCommunityNameUpdated(string text)
	{
		text = text.Trim();
		text = text.SanitizePath();
		_townNameInputField.text = text;
		_startButton.interactable = Application.isEditor || !Session.Profile.HasInactiveRunWithCommunityName(text);
	}

	public void RandomizeName()
	{
		SetText(Session.Profile.TryGetCommunityName(out var communityName) ? communityName : "You Broke our Generator");
	}
}
[RequireComponent(typeof(Canvas), typeof(GraphicRaycaster))]
public class UIElementsLayer : MonoBehaviour
{
	[SerializeField]
	[GeneratedEnum]
	private UIElementsLayerID _layerID;

	[SerializeField]
	private Canvas _canvas;

	[SerializeField]
	private GraphicRaycaster _graphicRaycaster;

	private readonly List<PanelContainer> _panels = new List<PanelContainer>(16);

	public IReadOnlyList<PanelContainer> Panels => _panels;

	public UIElementsLayerID LayerID => _layerID;

	private void OnValidate()
	{
		if (_canvas == null)
		{
			_canvas = GetComponent<Canvas>();
		}
		if (_graphicRaycaster == null)
		{
			_graphicRaycaster = GetComponent<GraphicRaycaster>();
		}
	}

	private void Awake()
	{
		DetectPanels();
	}

	private void DetectPanels()
	{
		_panels.Clear();
		_panels.AddRange(GetComponentsInChildren<PanelContainer>(includeInactive: false));
	}

	public void SetInputsActive(bool active)
	{
		_graphicRaycaster.enabled = active;
	}
}
public class PortraitDrifter : MonoBehaviour
{
	public enum PortraitType
	{
		Dynamic,
		Static
	}

	[SerializeField]
	private PortraitType _type;

	[SerializeField]
	private DrifterRig _maleDrifter;

	[SerializeField]
	private DrifterRig _femaleDrifter;

	private DrifterLookCamera _currentCamera;

	private DrifterRig _currentRig;

	private Agent.EGender _currentGender;

	private DrifterLookProperties.Indices _currentLook;

	private bool _updateLook;

	private bool _shouldBeEnabled;

	private bool _isEnabledStateDirty;

	private AgentDescriptor _agentToActivate;

	private Activity _agentActivityToSet = Activity.DynamicPortrait;

	private DrifterLookCamera _cameraToActivate;

	public AgentDescriptor CurrentAgent { get; private set; }

	private void Awake()
	{
		InitializeRig(_maleDrifter);
		InitializeRig(_femaleDrifter);
		DisableInternal();
	}

	private void LateUpdate()
	{
		if (_updateLook && CurrentAgent != null)
		{
			CurrentAgent.ApplyLooksForPortrait(_currentRig, _currentCamera, _currentCamera == DrifterLookCamera.DynamicPortrait);
			_updateLook = false;
		}
		if (_isEnabledStateDirty)
		{
			if (_shouldBeEnabled)
			{
				EnableInternal();
			}
			else
			{
				DisableInternal();
			}
			_isEnabledStateDirty = false;
		}
	}

	public void Enable(AgentDescriptor descriptor, DrifterLookCamera camera, Activity activity = Activity.DynamicPortrait)
	{
		_shouldBeEnabled = true;
		_isEnabledStateDirty = true;
		_agentToActivate = descriptor;
		_agentActivityToSet = activity;
		_cameraToActivate = camera;
		GameEventDispatcher.Dispatch(GameEventType.DrifterPortraitEnabled);
	}

	public bool Disable()
	{
		_shouldBeEnabled = false;
		_isEnabledStateDirty = true;
		_agentToActivate = null;
		GameEventDispatcher.Dispatch(GameEventType.DrifterPortraitDisabled);
		return !_shouldBeEnabled;
	}

	public bool IsEnabled()
	{
		return _shouldBeEnabled;
	}

	private void EnableInternal()
	{
		if (CurrentAgent == _agentToActivate && _currentGender == _agentToActivate.Gender && IsCurrentLook(_agentToActivate.LookIndices))
		{
			if (_currentRig.CurrentActivity != _agentActivityToSet && _type == PortraitType.Dynamic)
			{
				_currentRig.UpdatePortraitActivity(_agentToActivate, _agentActivityToSet, forceUpdate: true);
			}
			return;
		}
		DisableInternal();
		_currentRig = ((_agentToActivate.Gender == Agent.EGender.Male) ? _maleDrifter : _femaleDrifter);
		_currentGender = _agentToActivate.Gender;
		_currentLook = _agentToActivate.LookIndices;
		_currentCamera = _cameraToActivate;
		CurrentAgent = _agentToActivate;
		CurrentAgent.ApplyLooksForPortrait(_currentRig, _currentCamera, _currentCamera == DrifterLookCamera.DynamicPortrait);
		CurrentAgent.OnLookUpdated.AddListener(OnDrifterLookUpdated);
		_currentRig.gameObject.SetActive(value: true);
		if (_type == PortraitType.Dynamic)
		{
			_currentRig.SetPortraitLayer();
			_currentRig.UpdatePortraitActivity(_agentToActivate, _agentActivityToSet, forceUpdate: true);
		}
		else
		{
			_currentRig.SetHeadPortraitLayer();
		}
	}

	private void DisableInternal()
	{
		if (CurrentAgent != null)
		{
			CurrentAgent.OnLookUpdated.RemoveListener(OnDrifterLookUpdated);
			CurrentAgent = null;
		}
		if (_maleDrifter.gameObject.activeSelf || _femaleDrifter.gameObject.activeSelf)
		{
			_maleDrifter.gameObject.SetActive(value: false);
			_femaleDrifter.gameObject.SetActive(value: false);
		}
	}

	public void SetPortraitActivity(Activity activity)
	{
		if (CurrentAgent != null)
		{
			_currentRig.UpdatePortraitActivity(CurrentAgent, activity);
		}
		else if (_agentToActivate != null)
		{
			_agentActivityToSet = activity;
		}
	}

	private void InitializeRig(DrifterRig rig)
	{
		rig.SetShadows(active: false);
		switch (_type)
		{
		case PortraitType.Dynamic:
			rig.MeshAnimator.Initialize();
			rig.SetPortraitLayer();
			break;
		case PortraitType.Static:
			rig.SetHeadPortraitLayer();
			break;
		}
	}

	private void OnDrifterLookUpdated()
	{
		_updateLook = true;
	}

	private bool IsCurrentLook(DrifterLookProperties.Indices look)
	{
		if (_currentLook.BodyMaterial == look.BodyMaterial && _currentLook.EyesMaterial == look.EyesMaterial && _currentLook.MouthMaterial == look.MouthMaterial && _currentLook.Head == look.Head && _currentLook.Ears == look.Ears && _currentLook.Eyes == look.Eyes && _currentLook.Nose == look.Nose && _currentLook.Mouth == look.Mouth && _currentLook.Body == look.Body && _currentLook.HairMaterial == look.HairMaterial && _currentLook.Haircut == look.Haircut && _currentLook.Eyebrows == look.Eyebrows && _currentLook.Moustache == look.Moustache && _currentLook.Beard == look.Beard && _currentLook.TopMaterial == look.TopMaterial && _currentLook.PantsMaterial == look.PantsMaterial && _currentLook.ShoesMaterial == look.ShoesMaterial && _currentLook.Top == look.Top && _currentLook.Pants == look.Pants)
		{
			return _currentLook.Shoes == look.Shoes;
		}
		return false;
	}
}
public class PortraitGenerator : MonoBehaviour
{
	[Header("Dynamic")]
	[SerializeField]
	private Camera _dynamicPortraitCamera;

	[SerializeField]
	private PortraitDrifter _dynamicPortraitDrifter;

	[Tooltip("The render texture to where the camera renders the portraits.")]
	[SerializeField]
	private RenderTexture _dynamicPortraitRenderTexture;

	[Header("Static")]
	[SerializeField]
	private Camera _staticPortraitCamera;

	[SerializeField]
	private PortraitDrifter _staticPortraitDrifter;

	[Tooltip("The render texture to where the camera renders the portraits.")]
	[SerializeField]
	private RenderTexture _staticPortraitRenderTexture;

	private static PortraitGenerator _instance;

	private static readonly Queue<AgentDescriptor> _portraitGenerationQueue = new Queue<AgentDescriptor>();

	private readonly Dictionary<AgentDescriptor, Texture2D> _portraits = new Dictionary<AgentDescriptor, Texture2D>();

	private void Awake()
	{
		if (_instance == null || _instance == this)
		{
			_instance = this;
			_dynamicPortraitCamera.enabled = false;
			_staticPortraitCamera.enabled = false;
		}
		else
		{
			UnityEngine.Debug.LogError("Multiple PortraitManager instances detected in scene!");
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void OnDisable()
	{
		_dynamicPortraitRenderTexture.Release();
		_staticPortraitRenderTexture.Release();
	}

	private void OnDestroy()
	{
		_portraits.Clear();
		_portraitGenerationQueue.Clear();
	}

	private void Update()
	{
		if (_portraitGenerationQueue.Count > 0 && Time.frameCount > 1 && _portraitGenerationQueue.TryDequeue(out var result))
		{
			StartCoroutine(GenerateStaticPortraitCoroutine(result));
		}
	}

	public static void EnableDynamicPortraitDrifter(AgentDescriptor descriptor, Activity activity = Activity.DynamicPortrait)
	{
		if ((bool)_instance)
		{
			_instance._dynamicPortraitCamera.enabled = true;
			_instance._dynamicPortraitDrifter.Enable(descriptor, DrifterLookCamera.DynamicPortrait, activity);
		}
	}

	public static bool DisableDynamicPortraitDrifter(AgentDescriptor descriptor)
	{
		if (_instance == null || descriptor == null || (_instance._dynamicPortraitDrifter.CurrentAgent == descriptor && _instance._dynamicPortraitDrifter.Disable()))
		{
			_instance._dynamicPortraitCamera.enabled = false;
			return true;
		}
		return false;
	}

	public static bool IsDynamicPortraitDrifterEnabled()
	{
		return _instance._dynamicPortraitDrifter.IsEnabled();
	}

	public static void SetDynamicPortraitActivity(Activity activity)
	{
		_instance._dynamicPortraitDrifter.SetPortraitActivity(activity);
	}

	public static Texture2D ReturnStaticPortrait(AgentDescriptor descriptor)
	{
		if ((bool)_instance && _instance.TryReturnPortrait(descriptor, out var portrait))
		{
			return portrait;
		}
		PajamaLlama.Debugs.Debugger.Error("No character portrait found for " + descriptor.Name + ".");
		return null;
	}

	public static bool HasStaticPortrait(AgentDescriptor descriptor)
	{
		Texture2D portrait;
		if ((bool)_instance)
		{
			return _instance.TryReturnPortrait(descriptor, out portrait);
		}
		return false;
	}

	public static void GeneratePortrait(AgentDescriptor descriptor)
	{
		if (!_portraitGenerationQueue.Contains(descriptor))
		{
			_portraitGenerationQueue.Enqueue(descriptor);
		}
	}

	public static void RemovePortrait(AgentDescriptor descriptor)
	{
		if (_instance != null)
		{
			_instance.I_RemovePortrait(descriptor);
		}
	}

	private bool TryReturnPortrait(AgentDescriptor descriptor, out Texture2D portrait)
	{
		return _portraits.TryGetValue(descriptor, out portrait);
	}

	private void I_RemovePortrait(AgentDescriptor descriptor)
	{
		if (_dynamicPortraitDrifter.CurrentAgent == descriptor)
		{
			_dynamicPortraitDrifter.Disable();
		}
		_portraits.Remove(descriptor);
		_portraitGenerationQueue.Remove(descriptor);
	}

	private IEnumerator GenerateStaticPortraitCoroutine(AgentDescriptor descriptor)
	{
		_staticPortraitCamera.enabled = true;
		_staticPortraitDrifter.Enable(descriptor, DrifterLookCamera.StaticPortrait);
		yield return new WaitForEndOfFrame();
		RenderTexture active = RenderTexture.active;
		RenderTexture.active = _staticPortraitRenderTexture;
		Texture2D texture2D = ReturnPortraitTexture(descriptor);
		texture2D.ReadPixels(new Rect(0f, 0f, _staticPortraitRenderTexture.width, _staticPortraitRenderTexture.height), 0, 0);
		texture2D.Apply();
		RenderTexture.active = active;
		_staticPortraitRenderTexture.Release();
		AgentEvent.Dispatch(GameEventType.AgentPortraitGenerated, descriptor);
		if (_staticPortraitDrifter.Disable())
		{
			_staticPortraitCamera.enabled = false;
		}
	}

	private Texture2D ReturnPortraitTexture(AgentDescriptor descriptor)
	{
		if (_portraits.TryGetValue(descriptor, out var value))
		{
			return value;
		}
		value = new Texture2D(_staticPortraitRenderTexture.width, _staticPortraitRenderTexture.height, TextureFormat.RGBA32, mipChain: true, linear: true)
		{
			anisoLevel = 1
		};
		_portraits.Add(descriptor, value);
		return value;
	}
}
