[RequireComponent(typeof(LayoutElement))]
public class DotScaler : MonoBehaviour
{
	[SerializeField]
	[Tooltip("This is the increments by which the object will scale it's preferred width, this needs to be equal to the monospace+character width to work")]
	private float _incrementStep = 17.5f;

	[SerializeField]
	private LayoutElement _layoutElement;

	[SerializeField]
	private TextMeshProUGUI _textComponent;

	private void OnEnable()
	{
		FinalUpdate.RegisterEndOfFrameOneShot(AdjustPreferredWidth);
	}

	private void AdjustPreferredWidth()
	{
		if (_textComponent != null && _layoutElement != null)
		{
			_layoutElement.preferredWidth = Mathf.Ceil(_textComponent.preferredWidth / _incrementStep) * _incrementStep;
		}
	}
}
public class TabGroup : MonoBehaviour
{
	private List<TabGroupButton> _tabButtons;

	public void Subscribe(TabGroupButton button)
	{
		if (_tabButtons == null)
		{
			_tabButtons = new List<TabGroupButton>();
		}
		if (button.IsSelected)
		{
			button.Activate();
		}
		else
		{
			button.Deactivate();
		}
		_tabButtons.Add(button);
	}

	public void Select(TabGroupButton button)
	{
		foreach (TabGroupButton tabButton in _tabButtons)
		{
			if (tabButton == button)
			{
				tabButton.Activate();
			}
			else
			{
				tabButton.Deactivate();
			}
		}
	}
}
public class TabGroupButton : CustomButton
{
	public bool IsSelected;

	[Space]
	[SerializeField]
	private TabGroup _tabGroup;

	[SerializeField]
	private GameObject _content;

	protected override void Awake()
	{
		base.Awake();
		if (_tabGroup != null)
		{
			_tabGroup.Subscribe(this);
		}
	}

	public void Deactivate()
	{
		IsSelected = false;
		base.targetGraphic.color = base.colors.normalColor;
		_content.SetActive(value: false);
	}

	public void Activate()
	{
		IsSelected = true;
		base.targetGraphic.color = base.colors.pressedColor;
		_content.SetActive(value: true);
	}

	public override void OnPointerClick(PointerEventData eventData)
	{
		base.OnPointerClick(eventData);
		_tabGroup.Select(this);
	}
