public class Table : MonoBehaviour
{
	public struct Row
	{
		public Transform EntryParent;

		public List<TableEntry> Entries;

		public Row(string rowName, GameObject prefab, Transform rowParent)
		{
			EntryParent = UnityEngine.Object.Instantiate(prefab, rowParent).transform;
			EntryParent.name = rowName;
			EntryParent.SetParent(rowParent);
			EntryParent.localPosition = Vector3.zero;
			Entries = new List<TableEntry>();
		}

		public void AddEntry(TableEntry entry)
		{
			if (Entries == null)
			{
				Entries = new List<TableEntry> { entry };
			}
		}

		public void RemoveEntry(TableEntry entry)
		{
			if (Entries != null)
			{
				Entries.Remove(entry);
			}
		}
	}

	[SerializeField]
	private TableEntry.Style[] _styles = new TableEntry.Style[0];

	[SerializeField]
	private GameObject _rowPrefab;

	public List<Row> Rows { get; private set; } = new List<Row>();

	public Row AddRow()
	{
		Row row = new Row("Row " + Rows.Count, _rowPrefab, base.transform);
		Rows.Add(row);
		return row;
	}

	public bool TryAddEntry(Row row, string styleID, string term, float width, out TableEntry entry)
	{
		if (TryReturnStyle(styleID, out var style))
		{
			entry = UnityEngine.Object.Instantiate(style.Prefab, row.EntryParent);
			entry.Initialize(style, term, width);
			row.AddEntry(entry);
			return true;
		}
		entry = null;
		return false;
	}

	public bool TryAddEntry(Row row, string styleID, Sprite sprite, Color spriteColor, float width, out TableEntry entry)
	{
		if (TryReturnStyle(styleID, out var style))
		{
			entry = UnityEngine.Object.Instantiate(style.Prefab, row.EntryParent);
			entry.Initialize(style, sprite, spriteColor, width);
			row.AddEntry(entry);
			return true;
		}
		entry = null;
		return false;
	}

	private bool TryReturnStyle(string id, out TableEntry.Style style)
	{
		TableEntry.Style[] styles = _styles;
		for (int i = 0; i < styles.Length; i++)
		{
			TableEntry.Style style2 = styles[i];
			if (style2.Equals(id))
			{
				style = style2;
				return true;
			}
		}
		style = default(TableEntry.Style);
		return false;
	}
}
public class TableEntry : MonoBehaviour
{
	[Serializable]
	public struct Style
	{
		public string ID;

		public TableEntry Prefab;

		public bool Equals(string id)
		{
			return ID.Equals(id, StringComparison.OrdinalIgnoreCase);
		}
	}

	[SerializeField]
	private TextMeshProUGUI _text;

	[SerializeField]
	private Image _image;

	public UnityEvent OnValueChanged = new UnityEvent();

	public Style EntryStyle { get; private set; }

	public void Initialize(Style style, string text, float width)
	{
		EntryStyle = style;
		if (_text != null)
		{
			_text.text = text;
			_text.enabled = true;
		}
		if (_image != null)
		{
			_image.enabled = false;
		}
		RectTransform rectTransform = base.transform as RectTransform;
		rectTransform.sizeDelta = new Vector2(width, rectTransform.sizeDelta.y);
		OnValueChanged.Invoke();
	}

	public void Initialize(Style style, Sprite sprite, Color spriteColor, float size)
	{
		EntryStyle = style;
		if (_image != null)
		{
			_image.sprite = sprite;
			_image.color = spriteColor;
			_image.enabled = true;
		}
		if (_text != null)
		{
			_text.enabled = false;
		}
		RectTransform rectTransform = base.transform as RectTransform;
		rectTransform.sizeDelta = new Vector2(size, rectTransform.sizeDelta.y);
		OnValueChanged.Invoke();
	}
}
[DisallowMultipleComponent]
public class AssignmentTooltip : Tooltip
{
	[SerializeField]
	private DrifterAttributes _drifterAttributes;

	private AssignmentSetting _setting;

	public void Initialize(AssignmentSetting setting)
	{
		_setting = setting;
		LocalizedText = setting.Name;
	}

	public override string ParsedText()
	{
		string text = (((string)LocalizedText == null) ? LocalizedText.mTerm : LocalizedText.ToString());
		text = "<style=\"Tooltip Name\">" + text + "</style>";
		if (_setting != null)
		{
			text = text + "\n" + _setting.Description;
			_setting.GetTooltip(_drifterAttributes, text);
		}
		return text;
	}

	private string ReturnUsedInProperties(string joiner, BuildableProperties[] properties)
	{
		string text = "";
		bool flag = false;
		foreach (BuildableProperties buildableProperties in properties)
		{
			if (flag)
			{
				text += joiner;
			}
			text += buildableProperties.Name;
			flag = true;
		}
		return text;
	}
}
public class BuildablePreviewTooltip : MonoBehaviour
{
	[Tooltip("How high the tooltip floats above the cursor.")]
	public float VerticalOffset = 5f;

	[SerializeField]
	[Tooltip("The parent of the slot icons.")]
	private RectTransform _slotParent;

	[SerializeField]
	[Tooltip("Prefab for the mooring point slot.")]
	private BuildableTooltipItemSlot _tooltipItemSlotPrefab;

	[SerializeField]
	[Tooltip("The icon to indicate if the construction is intersecting anything.")]
	private GameObject _overlappingIcon;

	private Buildable _buildable;

	private List<BuildableTooltipItemSlot> _slots = new List<BuildableTooltipItemSlot>();

	private CountedItemProperty[] _slotItems;

	private List<CountedItemProperty> _countedSlotItems = new List<CountedItemProperty>();

	private int _amount;

	private void Start()
	{
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.AddListener(UpdateSlots);
	}

	private void OnDestroy()
	{
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.RemoveListener(UpdateSlots);
	}

	public void EnableTooltip(Buildable buildable, int amount = 1)
	{
		_buildable = buildable;
		base.gameObject.SetActive(value: true);
		CreateItemSlots();
	}

	public void DisableTooltip()
	{
		_buildable = null;
		base.gameObject.SetActive(value: false);
		ClearSlots();
	}

	private void CreateItemSlots()
	{
		_slotItems = _buildable.Properties.RequiredResources;
		for (int i = 0; i < _slotItems.Length; i++)
		{
			_slots.Add(UnityEngine.Object.Instantiate(_tooltipItemSlotPrefab, _slotParent));
			CountedItemProperty item = new CountedItemProperty(_slotItems[i].ItemProperties, _slotItems[i].Amount);
			_countedSlotItems.Add(item);
			_slots[i].Initialize(_countedSlotItems[i], showAvailable: false);
			_slots[i].DisableRaycasts();
		}
	}

	public void SetBuildableAmount(int amount)
	{
		_amount = amount;
		for (int i = 0; i < _slots.Count; i++)
		{
			_slots[i].SetBuildableAmount(amount);
		}
	}

	public void SetLocation(Vector3 position)
	{
		base.transform.position = position + Vector3.up * VerticalOffset;
	}

	public void SetOverlapping(bool isOverlapping)
	{
		_overlappingIcon.SetActive(isOverlapping);
	}

	private void UpdateSlots()
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			_slots[i].UpdateSlot();
		}
	}

	private void ClearSlots()
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			UnityEngine.Object.Destroy(_slots[i].gameObject);
		}
		_slots.Clear();
		_countedSlotItems.Clear();
	}
}
public class BuildableTooltip : MonoBehaviour
{
	[Tooltip("Vertical offset for the tooltip to display it above the buttons, instead of on it.")]
	public float VerticalOffset = 30f;

	[Space]
	[SerializeField]
	[Tooltip("Prefab for the item slot.")]
	private ChildBehaviourCache<BuildableTooltipItemSlot> _itemSlotPrefab;

	[SerializeField]
	[Tooltip("Prefab for the mooring point slot.")]
	private BuildableTooltipMooringPointSlot _mooringPointSlot;

	[Space(15f)]
	[SerializeField]
	[Tooltip("Text component for the construction name.")]
	private TextMeshProUGUI _nameText;

	[SerializeField]
	[Tooltip("Text component for the construction description.")]
	private TextMeshProUGUI _descriptionText;

	[SerializeField]
	private TextField _footprint;

	[SerializeField]
	private IntField _beauty;

	[SerializeField]
	private IntField _energyRequirement;

	[SerializeField]
	private TextField _weight;

	[SerializeField]
	private GameObject _buildableInfoContainer;

	[SerializeField]
	private GameObject _constructionCostsContainer;

	private bool _tooltipActive;

	private IPlaceable _placeable;

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.UIStateChanged, OnUIStateChanged);
	}

	private void OnDisable()
	{
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.RemoveListener(UpdateSlots);
		Community.PlayerCommunity.MooringPointsUpdatedEvent -= UpdateSlots;
		GameEventDispatcher.RemoveListener(GameEventType.UIStateChanged, OnUIStateChanged);
	}

	public void DisplayTooltip(IPlaceable placeable, bool upgradeResources = false)
	{
		_placeable = placeable;
		IPlaceable placeable2;
		if (!upgradeResources)
		{
			placeable2 = placeable;
		}
		else
		{
			IPlaceable upgrade = ((BuildableProperties)placeable).Upgrade;
			placeable2 = upgrade;
		}
		IPlaceable placeable3 = placeable2;
		if (placeable3.RequiresMooringPoint)
		{
			Community.PlayerCommunity.MooringPointsUpdatedEvent += UpdateSlots;
		}
		_nameText.text = placeable3.Name;
		_descriptionText.text = placeable3.GetDescription();
		if (placeable3 is PlaceableProperties placeableProperties)
		{
			_buildableInfoContainer.gameObject.SetActive(value: true);
			_footprint.SetText($"{placeableProperties.Width}x{placeableProperties.Depth}");
			_beauty.SetInt(placeableProperties.ReturnBuildableTooltipBeautyScore());
			if (placeableProperties.TryGetEnergyCost(out var energyCost))
			{
				_energyRequirement.SetFloat(energyCost);
			}
			else
			{
				_energyRequirement.gameObject.SetActive(value: false);
			}
			_weight.SetText($"{placeableProperties.GetWeightModeWeight()}/{Engine.TownAvailableTugCapacity}", Engine.CanTug(placeableProperties) ? TextField.States.Positive : TextField.States.Negative);
		}
		else
		{
			_buildableInfoContainer.gameObject.SetActive(value: false);
		}
		DisplayTooltip(upgradeResources);
	}

	private void DisplayTooltip(bool upgradeResources = false)
	{
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.AddListener(UpdateSlots);
		_tooltipActive = true;
		CreateSlots(_placeable as PlaceableProperties, upgradeResources);
	}

	public void HideTooltip()
	{
		_tooltipActive = false;
		GameManager.HighlightManager.ClearHighlights();
		base.gameObject.SetActive(value: false);
	}

	private void CreateSlots(PlaceableProperties placeableProperties, bool upgradeResources = false)
	{
		if (placeableProperties == null)
		{
			_constructionCostsContainer.SetActive(value: false);
			return;
		}
		_constructionCostsContainer.SetActive(value: true);
		_mooringPointSlot.gameObject.SetActive(placeableProperties.RequiresMooringPoint);
		_itemSlotPrefab.Reset();
		CountedItemProperty[] array = placeableProperties.ReturnTooltipRequiredResources(upgradeResources);
		foreach (CountedItemProperty slotItem in array)
		{
			_itemSlotPrefab.Get(active: true).Initialize(slotItem);
		}
		_itemSlotPrefab.Trim();
	}

	private void UpdateSlots()
	{
		if (_tooltipActive && _constructionCostsContainer.activeInHierarchy)
		{
			for (int i = 0; i < _itemSlotPrefab.Count; i++)
			{
				_itemSlotPrefab[i].UpdateSlot();
			}
		}
	}

	private void OnUIStateChanged(GameEvent gameEvent)
	{
		if (UIManager.State != UIState.Normal)
		{
			HideTooltip();
		}
	}
}
public class BuildableTooltipItemSlot : BuildableTooltipSlot, GUIItemSlot
{
	[SerializeField]
	private InventoryIcon _inventoryIcon;

	[SerializeField]
	private TextMeshProUGUI _label;

	private CountedItemProperty _slotItem;

	private int _multiplier;

	private bool _showAvailable = true;

	public void Initialize(ItemProperties itemProperties, int amount, bool showCounter)
	{
		GetInventoryIcon().Initialize(itemProperties);
		_showAvailable = false;
		_multiplier = 1;
		if (showCounter)
		{
			base.Counter.gameObject.SetActive(value: true);
			base.Counter.text = amount.ToString();
			ResetColor();
		}
		else
		{
			base.Counter.gameObject.SetActive(value: false);
		}
	}

	public void Initialize(CountedItemProperty slotItem, bool showAvailable = true)
	{
		_showAvailable = showAvailable;
		_slotItem = slotItem;
		_multiplier = 1;
		base.Counter.gameObject.SetActive(value: true);
		UpdateSlot();
	}

	public override void UpdateSlot()
	{
		int num = Community.PlayerCommunity.Inventory.ReturnCount(_slotItem.ItemProperties);
		GetInventoryIcon().Initialize(_slotItem.ItemProperties);
		if (_showAvailable)
		{
			base.Counter.text = $"{num}/{_slotItem.Amount * _multiplier}";
		}
		else
		{
			base.Counter.text = (_slotItem.Amount * _multiplier).ToString();
		}
		OverrideColor(num >= _slotItem.Amount * _multiplier);
		if ((bool)_label)
		{
			_label.text = _slotItem.ItemProperties.LocalizedName;
		}
	}

	public override void OverrideColor(bool validColor)
	{
		base.OverrideColor(validColor);
		if (validColor)
		{
			GetInventoryIcon().SetValid(validColor);
		}
		else
		{
			GetInventoryIcon().SetValid(valid: false);
		}
	}

	public void SetBuildableAmount(int amount)
	{
		_multiplier = amount;
		UpdateSlot();
	}

	public void DisableRaycasts()
	{
		Image[] componentsInChildren = GetComponentsInChildren<Image>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].raycastTarget = false;
		}
	}

	private void Reset()
	{
	}

	public static void InitializeItemListInfo<T>(List<CountedItemProperty> countedItems, T slotPrefab, List<GUIItemSlot> slotInstances, RectTransform parent, bool showCounter = false) where T : UnityEngine.Component, GUIItemSlot
	{
		int i = 0;
		foreach (CountedItemProperty countedItem in countedItems)
		{
			GUIItemSlot gUIItemSlot;
			if (i == slotInstances.Count)
			{
				gUIItemSlot = UnityEngine.Object.Instantiate(slotPrefab);
				gUIItemSlot.transform.SetParent(parent);
				gUIItemSlot.transform.localScale = Vector3.one;
				slotInstances.Add(gUIItemSlot);
			}
			else
			{
				gUIItemSlot = slotInstances[i];
			}
			gUIItemSlot.Initialize(countedItem.ItemProperties, countedItem.Amount, showCounter);
			gUIItemSlot.gameObject.SetActive(value: true);
			i++;
		}
		for (; i < slotInstances.Count; i++)
		{
			slotInstances[i].gameObject.SetActive(value: false);
		}
	}

	private InventoryIcon GetInventoryIcon()
	{
		if (_inventoryIcon == null)
		{
			_inventoryIcon = GetComponent<InventoryIcon>();
		}
		return _inventoryIcon;
	}

	GameObject GUIItemSlot.get_gameObject()
	{
		return base.gameObject;
	}

	Transform GUIItemSlot.get_transform()
	{
		return base.transform;
	}
}
