	private TextMeshProUGUI _title;

	[SerializeField]
	private ChildBehaviourCache<QuestObjectiveDisplay> _objectivesDisplays;

	[SerializeField]
	private GameObject _reopenQuestDialogueButton;

	private Quest _currentQuest;

	private readonly Dictionary<IQuestObjective, int> _objectivesIndices = new Dictionary<IQuestObjective, int>();

	protected override void Awake()
	{
		base.Awake();
		GameEventDispatcher.AddListener(GameEventType.QuestUpdated, OnQuestDisplayRefresh);
		GameEventDispatcher.AddListener(GameEventType.QuestTracked, OnQuestDisplayRefresh);
		GameEventDispatcher.AddListener(GameEventType.QuestObjectiveUpdated, OnObjectiveUpdated);
		GameEventDispatcher.AddListener(GameEventType.QuestAbandoned, OnQuestFailed);
		GameEventDispatcher.AddListener(GameEventType.QuestFailed, OnQuestFailed);
		SetActive(active: false);
	}

	private void Start()
	{
		SetActive(active: true);
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestUpdated, OnQuestDisplayRefresh);
		GameEventDispatcher.RemoveListener(GameEventType.QuestTracked, OnQuestDisplayRefresh);
		GameEventDispatcher.RemoveListener(GameEventType.QuestObjectiveUpdated, OnObjectiveUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.QuestAbandoned, OnQuestFailed);
		GameEventDispatcher.RemoveListener(GameEventType.QuestFailed, OnQuestFailed);
	}

	public void ReopenQuestDialogue()
	{
		if (_currentQuest != null && !GameManager.UIManager.IsPanelOpen(PanelID.DialoguePanel))
		{
			_currentQuest.RepeatLastDialogue();
		}
	}

	private void SetActive(bool active)
	{
		base.gameObject.SetActive(active);
		_reopenQuestDialogueButton.SetActive(active && _currentQuest != null && _currentQuest.DialogueProperties != null);
	}

	private void OnQuestDisplayRefresh(GameEvent gameEvent)
	{
		_objectivesDisplays.Reset();
		_objectivesIndices.Clear();
		if (StoryManager.TryGetActiveQuest(out var quest) && quest.HasActiveVisibleObjectives())
		{
			_currentQuest = quest;
			SetActive(PopulateObjectives());
		}
		else
		{
			_currentQuest = null;
			_reopenQuestDialogueButton.SetActive(value: false);
			SetActive(active: false);
		}
		_objectivesDisplays.Trim();
	}

	private bool PopulateObjectives()
	{
		using ListPool<IQuestObjective>.List list = ListPool<IQuestObjective>.Get();
		_currentQuest.PopulateVisibleObjectives(list);
		if (list.Count == 0)
		{
			return false;
		}
		_title.text = _currentQuest.Properties.QuestTitle;
		foreach (IQuestObjective item in list)
		{
			if (!_objectivesIndices.TryGetValue(item, out var value))
			{
				_objectivesDisplays.Get(active: true, out value);
				_objectivesIndices.Add(item, value);
			}
			_objectivesDisplays[value].InitializeDisplay(item, _currentQuest.Objectives);
		}
		return true;
	}

	private void OnObjectiveUpdated(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent { Objective: not null } questEvent && _objectivesIndices.TryGetValue(questEvent.Objective, out var value))
		{
			_objectivesDisplays[value].UpdateDisplay(questEvent.Objective);
		}
	}

	private void OnQuestFailed(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent && questEvent.Quest == _currentQuest)
		{
			SetActive(active: false);
		}
	}
}
public class QuestObjectiveDisplay : MonoBehaviour
{
	[SerializeField]
	private TextMeshProUGUI _objectiveText;

	[SerializeField]
	private Toggle _objectiveCompleteToggle;

	[SerializeField]
	private QuestTimerHandler _questTimerHandler;

	public void InitializeDisplay(IQuestObjective objective, QuestObjectives objectives)
	{
		UpdateDisplay(objective);
		if (objective.DaysTimeLimit > 0)
		{
			_questTimerHandler.SetActive(active: true, objectives.GetRemainingDaysCount(objective));
		}
		else
		{
			_questTimerHandler.SetActive(active: false);
		}
	}

	public void UpdateDisplay(IQuestObjective objective)
	{
		_objectiveText.text = objective.ToString();
		_objectiveCompleteToggle.isOn = objective.IsCompleted();
	}
}
[Serializable]
public class QuestTimerHandler : ILocalizationParamsManager
{
	[SerializeField]
	private GameObject _timer;

	[SerializeField]
	private Localize _timerValue;

	private int _remainingDaysCount;

	~QuestTimerHandler()
	{
		GameEventDispatcher.RemoveListener(GameEventType.DayEnded, UpdateDisplay);
	}

	public bool IsActive()
	{
		return _timer.activeSelf;
	}

	public void SetActive(bool active, int remainingDaysCount = 0)
	{
		if (active != _timer.activeSelf)
		{
			if (active)
			{
				LocalizationManager.ParamManagers.Add(this);
				_remainingDaysCount = remainingDaysCount;
				_timer.SetActive(value: true);
				GameEventDispatcher.AddListener(GameEventType.DayEnded, UpdateDisplay);
			}
			else
			{
				LocalizationManager.ParamManagers.Remove(this);
				_timer.SetActive(value: false);
				GameEventDispatcher.RemoveListener(GameEventType.DayEnded, UpdateDisplay);
			}
		}
	}

	string ILocalizationParamsManager.GetParameterValue(string Param)
	{
		if (!(Param == "DAYSREMAINING"))
		{
			if (Param == "HOURSREMAINING")
			{
				return "0";
			}
			return null;
		}
		return _remainingDaysCount.ToString();
	}

	private void UpdateDisplay(GameEvent gameEvent = null)
	{
		if (--_remainingDaysCount > 0)
		{
			_timerValue.OnLocalize(Force: true);
		}
		else
		{
			SetActive(active: false);
		}
	}
}
public class Tutorial : MonoBehaviour
{
	[Serializable]
	private class PageCollection
	{
		public InputFlags InputFlags = InputFlags.All;

		public GameObject[] Pages;

		public void DeactivateAll()
		{
			GameObject[] pages = Pages;
			foreach (GameObject gameObject in pages)
			{
				if ((bool)gameObject)
				{
					gameObject.SetActive(value: false);
				}
			}
		}
	}

	public const string NO_PAGE_STRING = "0/0";

	[SerializeField]
	[GeneratedEnum]
	private TutorialID _id;

	[SerializeField]
	private LocalizedString _title;

	[SerializeField]
	private PageCollection[] _pageCollections;

	private PageCollection _activePageCollection;

	private int _pageIndex;

	private static List<Tutorial> s_tutorials = new List<Tutorial>();

	public TutorialID ID => _id;

	public LocalizedString Title => _title;

	private void Awake()
	{
		PageCollection[] pageCollections = _pageCollections;
		for (int i = 0; i < pageCollections.Length; i++)
		{
			pageCollections[i].DeactivateAll();
		}
	}

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
		OnActiveInputUpdated();
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
	}

	public void Initialize()
	{
		int count = s_tutorials.Count;
		while (0 < count--)
		{
			Tutorial tutorial = s_tutorials[count];
			if (tutorial == null)
			{
				s_tutorials.RemoveAt(count);
			}
			else if (tutorial.ID == ID)
			{
				return;
			}
		}
		s_tutorials.Add(this);
	}

	public bool NextPage()
	{
		if (HasNextPage())
		{
			_activePageCollection.Pages[_pageIndex].SetActive(value: false);
			_activePageCollection.Pages[++_pageIndex].SetActive(value: true);
			return true;
		}
		return false;
	}

	public bool PreviousPage()
	{
		if (HasPreviousPage())
		{
			_activePageCollection.Pages[_pageIndex].SetActive(value: false);
			_activePageCollection.Pages[--_pageIndex].SetActive(value: true);
			return true;
		}
		return false;
	}

	private void OnActiveInputUpdated(GameEvent gameEvent = null)
	{
		for (int i = 0; i < _pageCollections.Length; i++)
		{
			PageCollection pageCollection = _pageCollections[i];
			if (FlotsamInputManager.HasActiveInput(pageCollection.InputFlags))
			{
				if (_activePageCollection != null)
				{
					_activePageCollection.Pages[_pageIndex].SetActive(value: false);
				}
				_pageIndex = 0;
				_activePageCollection = pageCollection;
				if (_activePageCollection.Pages.Length != 0)
				{
					_activePageCollection.Pages[0].SetActive(value: true);
				}
				else
				{
					UnityEngine.Debug.LogException(new NotSupportedException($"Tutorial '{ID}' has no pages set for InputFlags '{_activePageCollection.InputFlags}'!"));
				}
			}
		}
	}

	public bool HasNextPage()
	{
		if (_activePageCollection != null)
		{
			return _pageIndex < _activePageCollection.Pages.Length - 1;
		}
		return false;
	}

	public bool HasPreviousPage()
	{
		if (_activePageCollection != null)
		{
			return 0 < _pageIndex;
		}
		return false;
	}

	public string GetPageString()
	{
		if (_activePageCollection == null)
		{
			return "0/0";
		}
		return $"{_pageIndex + 1}/{_activePageCollection.Pages.Length}";
	}

	public static string GetTitle(TutorialID id)
	{
		foreach (Tutorial s_tutorial in s_tutorials)
		{
			if (s_tutorial.ID == id)
			{
				return s_tutorial.Title;
			}
		}
		return null;
	}
}
public class TutorialIDProvider : MonoBehaviour
