public class VideoSettingsPanel : SettingsPanel
{
	internal class ResolutionOption : TMP_Dropdown.OptionData
	{
		public Resolution Resolution;

		public ResolutionOption(Resolution resolution)
			: base(resolution.ToString())
		{
			Resolution = resolution;
		}
	}

	[Header("Components")]
	[Tooltip("Dropdown for full-screen modes.")]
	[SerializeField]
	private TMP_Dropdown _fullScreenModesDropdown;

	[Tooltip("Dropdown to choose the game's resolution.")]
	[SerializeField]
	private TMP_Dropdown _resolutionDropDown;

	[Tooltip("Dropdown to choose the texture quality.")]
	[SerializeField]
	private TMP_Dropdown _graphicsQualityDropdown;

	[Tooltip("Slider to set UI scale.")]
	[SerializeField]
	private InteractableSlider _uiSlider;

	[Tooltip("Toggle vSync.")]
	[SerializeField]
	private Toggle _vSyncToggle;

	[Header("Localization")]
	[Tooltip("The full screen option to populate the video panel with.")]
	[SerializeField]
	private List<FullScreenOption> _fullScreenOptions = new List<FullScreenOption>();

	[Tooltip("Localized strings for the graphics quality options.")]
	[SerializeField]
	private List<LocalizedString> _graphicsQualityOptions = new List<LocalizedString>();

	private bool _initialized;

	private int _fullScreenModeIndex;

	private int _resolutionIndex;

	private int _graphicsQualityIndex;

	[HideInInspector]
	private GraphicsPlayerData _graphicsPlayerData;

	protected override void OnEnable()
	{
		base.OnEnable();
		_fullScreenModesDropdown.onValueChanged.AddListener(OnValueChanged);
		_resolutionDropDown.onValueChanged.AddListener(OnValueChanged);
		_graphicsQualityDropdown.onValueChanged.AddListener(OnValueChanged);
		_vSyncToggle.onValueChanged.AddListener(OnVSyncChanged);
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		_fullScreenModesDropdown.onValueChanged.RemoveListener(OnValueChanged);
		_resolutionDropDown.onValueChanged.RemoveListener(OnValueChanged);
		_graphicsQualityDropdown.onValueChanged.RemoveListener(OnValueChanged);
		_vSyncToggle.onValueChanged.RemoveListener(OnVSyncChanged);
		_fullScreenModesDropdown.value = _fullScreenModeIndex;
		_resolutionDropDown.value = _resolutionIndex;
		_graphicsQualityDropdown.value = _graphicsQualityIndex;
		UpdateApplyButton();
	}

	public override void Load(Settings playerData)
	{
		_graphicsPlayerData = playerData.GraphicsPlayerData;
		if (!_initialized)
		{
			SetFullScreenOptions();
			SetResolutionOptions();
			SetQualityOptions();
			_initialized = true;
		}
		_fullScreenModesDropdown.value = (_fullScreenModeIndex = ReturnFullScreenModeIndex());
		_resolutionDropDown.value = (_resolutionIndex = ReturnResolutionDropDownIndex(ReturnCurrentResolution()));
		_graphicsQualityDropdown.value = (_graphicsQualityIndex = QualitySettings.GetQualityLevel());
		_vSyncToggle.isOn = QualitySettings.vSyncCount == 1;
		SetValues(_graphicsPlayerData);
	}

	public override void ApplyChanges()
	{
		ApplyGraphicsQualityChanges();
		ApplyResolutionChanges();
		UpdateApplyButton();
	}

	protected override void Reset()
	{
		_graphicsPlayerData.ResetSettings();
		SetValues(_graphicsPlayerData);
		_fullScreenModesDropdown.value = (_fullScreenModeIndex = 0);
		_graphicsQualityDropdown.value = (_graphicsQualityIndex = Mathf.Min(4, _graphicsQualityDropdown.options.Count));
		_resolutionDropDown.value = (_resolutionIndex = 0);
		QualitySettings.SetQualityLevel(_graphicsQualityIndex, applyExpensiveChanges: false);
		SetResolution(_resolutionIndex, _fullScreenModeIndex);
	}

	private void SetValues(GraphicsPlayerData data)
	{
		_fullScreenModesDropdown.value = _fullScreenModeIndex;
		_resolutionDropDown.value = _resolutionIndex;
		_graphicsQualityDropdown.value = _graphicsQualityIndex;
		_uiSlider.SetValue(data.UIScale);
	}

	private void SetResolutionOptions()
	{
		if (0 >= _resolutionDropDown.options.Count)
		{
			Resolution[] resolutions = Screen.resolutions;
			List<TMP_Dropdown.OptionData> list = new List<TMP_Dropdown.OptionData>(resolutions.Length);
			for (int num = resolutions.Length - 1; num >= 0; num--)
			{
				list.Add(new ResolutionOption(resolutions[num]));
			}
			_resolutionDropDown.AddOptions(list);
		}
	}

	private void SetFullScreenOptions()
	{
		_fullScreenModesDropdown.options.Clear();
		using ListPool<string>.List list = ListPool<string>.Get();
		for (int i = 0; i < _fullScreenOptions.Count; i++)
		{
			list.Add(_fullScreenOptions[i].FullScreenOptionText);
		}
		_fullScreenModesDropdown.AddOptions(list);
	}

	private void ApplyResolutionChanges()
	{
		if (SetResolution(_resolutionDropDown.value, _fullScreenModesDropdown.value) && PopUpDialog.Instance.TryOpenPopUpDialog(GameManager.Settings.UISettings.RevertChangesDialogProperties))
		{
			PopUpDialog.Instance.DialogFeedbackEvent.AddListener(OnApplyResolutionChangesDialogResult);
		}
	}

	private void OnApplyResolutionChangesDialogResult(bool result)
	{
		PopUpDialog.Instance.DialogFeedbackEvent.RemoveListener(OnApplyResolutionChangesDialogResult);
		if (result)
		{
			_resolutionIndex = _resolutionDropDown.value;
			_fullScreenModeIndex = _fullScreenModesDropdown.value;
		}
		else
		{
			_resolutionDropDown.value = _resolutionIndex;
			_fullScreenModesDropdown.value = _fullScreenModeIndex;
			SetResolution(_resolutionIndex, _fullScreenModeIndex);
		}
		UpdateApplyButton();
	}

	private bool SetResolution(int resolutionIndex, int fullScreenModeIndex)
	{
		ResolutionOption resolutionOption = _resolutionDropDown.options[resolutionIndex] as ResolutionOption;
		FullScreenMode fullScreenMode = _fullScreenOptions[fullScreenModeIndex].FullScreenMode;
		if (Screen.fullScreenMode == fullScreenMode && AreIdenticalResolutions(Screen.currentResolution, resolutionOption.Resolution))
		{
			return false;
		}
		Screen.SetResolution(resolutionOption.Resolution.width, resolutionOption.Resolution.height, fullScreenMode, resolutionOption.Resolution.refreshRateRatio);
		return true;
	}

	private void SetQualityOptions()
	{
		using ListPool<string>.List options = ListPool<string>.Get(QualitySettings.names);
		_graphicsQualityDropdown.ClearOptions();
		_graphicsQualityDropdown.AddOptions(options);
	}

	private void ApplyGraphicsQualityChanges()
	{
		if (_graphicsQualityDropdown.value == _graphicsQualityIndex)
		{
			QualitySettings.vSyncCount = (_vSyncToggle.isOn ? 1 : 0);
			return;
		}
		QualitySettings.SetQualityLevel(_graphicsQualityDropdown.value, applyExpensiveChanges: false);
		_graphicsQualityIndex = _graphicsQualityDropdown.value;
		_vSyncToggle.SetIsOnWithoutNotify(QualitySettings.vSyncCount == 1);
	}

	public void UpdateUIScale()
	{
		float num = (float)System.Math.Round(_uiSlider.ReturnValue(), 2);
		if (Mathf.Approximately(num, 1f))
		{
			num = 1f;
		}
		_graphicsPlayerData.UIScale = num;
		_uiSlider.SetValue(num);
		SettingsEvent.DispatchUIScaleChangedEvent(_graphicsPlayerData.UIScale);
	}

	public override bool HasChanges()
	{
		if (!HasWindowChanges())
		{
			return HasQualitityChanges();
		}
		return true;
	}

	public bool HasWindowChanges()
	{
		if (_fullScreenModesDropdown.value == _fullScreenModeIndex)
		{
			return _resolutionDropDown.value != _resolutionIndex;
		}
		return true;
	}

	public bool HasQualitityChanges()
	{
		return _graphicsQualityDropdown.value != _graphicsQualityIndex;
	}

	private int ReturnFullScreenModeIndex()
	{
		for (int i = 0; i < _fullScreenOptions.Count; i++)
		{
			if (_fullScreenOptions[i].FullScreenMode == Screen.fullScreenMode)
			{
				return i;
			}
		}
		return 0;
	}

	private int ReturnResolutionDropDownIndex(Resolution resolution)
	{
		int result = 0;
		int num = int.MaxValue;
		for (int i = 0; i < _resolutionDropDown.options.Count; i++)
		{
			Resolution resolution2 = (_resolutionDropDown.options[i] as ResolutionOption).Resolution;
			if (resolution2.width == resolution.width && resolution2.height == resolution.height)
			{
				int num2 = Mathf.Abs((int)resolution.refreshRateRatio.value - (int)resolution2.refreshRateRatio.value);
				if (num2 < num)
				{
					result = i;
					num = num2;
				}
			}
		}
		return result;
	}

	private int ReturnCurrentResolutionIndex()
	{
		return ReturnResolutionDropDownIndex(ReturnCurrentResolution());
	}

	private Resolution ReturnCurrentResolution()
	{
		if (Screen.fullScreenMode == FullScreenMode.Windowed)
		{
			return new Resolution
			{
				height = Screen.height,
				width = Screen.width
			};
		}
		return Screen.currentResolution;
	}

	private bool AreIdenticalResolutions(Resolution x, Resolution y)
	{
		if (x.width == y.width && x.height == y.height && x.refreshRateRatio.numerator == y.refreshRateRatio.numerator)
		{
			return x.refreshRateRatio.denominator == y.refreshRateRatio.denominator;
		}
		return false;
	}

	private void OnValueChanged(int index)
	{
		UpdateApplyButton();
	}

	private void OnVSyncChanged(bool value)
	{
		QualitySettings.vSyncCount = (value ? 1 : 0);
	}
}
public interface IInventoryView
{
	void ThrowItem(ItemProperties itemProperties);
}
public class InventoryView : MonoBehaviour, IBuildablePanelElement, IInventoryView
{
	[Header("Settings")]
	[Tooltip("Should all known items be shown or only items that are held by the inventory?")]
	[SerializeField]
	private bool _displayKnownItems;

	[Header("UI Components")]
	[Tooltip("Prefab for the inventory slots.")]
	public InventoryPanelItemSlot slotPrefab;

	[Tooltip("Transform containing the inventory slots.")]
	public Transform inventoryGrid;

	[Tooltip("List of capacity bars for this inventory panel.")]
	[SerializeField]
	private InventoryPanelCapacityBar[] _capacityBars = new InventoryPanelCapacityBar[0];

	[Tooltip("If enabled, you can eject items from the inventory view.")]
	[FormerlySerializedAs("_allowEject")]
	public bool AllowEject;

	[SerializeField]
	[Tooltip("What sub-inventory should be audited.")]
	private SubInventoryType _subInventoryType;

	[Header("Buildable Panel Element")]
	[SerializeField]
	private BuildablePanelElementId _buildablePanelElementId;

	[Header("Navigation")]
	[SerializeField]
	private bool _navigable;

	[SerializeField]
	[ConditionalHide("_navigable", true)]
	private SelectableGroup _selectableGroup;

	[SerializeField]
	[ConditionalHide("_navigable", true)]
	private RewiredAction _throw;

	private bool _initialized;

	private Inventory _inventory;

	private List<InventoryPanelItemSlot> _slots;

	private bool _shouldUpdateItemCount;

	private List<InventoryAuditor.CountedItem> _countedItems;

	public BuildablePanelElementId Id => _buildablePanelElementId;

	public void Initialize()
	{
		if (!_initialized)
		{
			_slots = new List<InventoryPanelItemSlot>();
			_initialized = true;
		}
	}

	public void Initialize(Inventory inventory, Item.Tags filter = Item.Tags.None)
	{
		Initialize();
		if (_inventory != inventory)
		{
			if (_inventory != null)
			{
				_inventory.InventoryUpdatedEvent.RemoveListener(QueueUpdateItemCount);
			}
			_inventory = inventory;
			_inventory.InventoryUpdatedEvent.AddListener(QueueUpdateItemCount);
			for (int i = 0; i < _capacityBars.Length && !_capacityBars[i].Initialize(inventory, filter); i++)
			{
			}
			_shouldUpdateItemCount = true;
			base.gameObject.SetActive(value: true);
		}
	}

	public void Initialize(Inventory inventory, SubInventoryType subInventoryToView)
	{
		Initialize(inventory);
		_subInventoryType = subInventoryToView;
	}

	private void OnEnable()
	{
		_shouldUpdateItemCount = true;
	}

	private void LateUpdate()
	{
		if (_shouldUpdateItemCount && _inventory != null)
		{
			_countedItems = _inventory.ReturnInventoryCount(_subInventoryType).CountedItems;
			UpdateVisuals(_countedItems);
			_shouldUpdateItemCount = false;
			if (_navigable)
			{
				_selectableGroup.Initialize();
			}
		}
		UpdateNavigation();
	}

	public bool Activate(Buildable buildable, bool finished)
	{
		if (finished && ((buildable.TryReturnBuildableExtendable<Storage>(out var buildableExtendable) && buildableExtendable.ShowInventoryView) || buildable.Properties.ReturnShowElement(this, finished)))
		{
			Item.Tags filter = Item.Tags.None;
			if ((bool)buildableExtendable)
			{
				filter = buildableExtendable.FilterTags;
				Item.Tags filterTags = buildableExtendable.FilterTags;
				if (filterTags == Item.Tags.Drink || filterTags == Item.Tags.Liquid || filterTags == (Item.Tags.Drink | Item.Tags.Liquid))
				{
					_subInventoryType = SubInventoryType.Liquid;
				}
				else
				{
					_subInventoryType = SubInventoryType.Storage;
				}
			}
			DeactivateCapacityBars();
			Initialize(buildable.Inventory, filter);
			AllowEject = buildable.Properties.CanEjectFromStorage;
			return true;
		}
		return false;
	}

	public void Deactivate()
	{
		if (_inventory != null)
		{
			_inventory.InventoryUpdatedEvent.RemoveListener(QueueUpdateItemCount);
			_inventory = null;
		}
		DeactivateCapacityBars();
		base.gameObject.SetActive(value: false);
	}

	private void DeactivateCapacityBars()
	{
		for (int i = 0; i < _capacityBars.Length; i++)
		{
			_capacityBars[i].gameObject.SetActive(value: false);
		}
	}

	private void QueueUpdateItemCount()
	{
		_shouldUpdateItemCount = true;
	}

	public void UpdateVisuals(List<InventoryAuditor.CountedItem> countedItems)
	{
		if (countedItems == null)
		{
			return;
		}
		int count = countedItems.Count;
		int count2 = _slots.Count;
		int i = 0;
		Sorting.SlowSort(countedItems);
		for (int j = 0; j < count; j++)
		{
			InventoryAuditor.CountedItem countedItem = countedItems[j];
			if (_displayKnownItems || 0 < countedItem.ReservedCount + countedItem.UnreservedCount)
			{
				if (i < count2)
				{
					InitializeSlot(_slots[i], countedItem);
				}
				else
				{
					InventoryPanelItemSlot inventoryPanelItemSlot = UnityEngine.Object.Instantiate(slotPrefab, inventoryGrid);
					InitializeSlot(inventoryPanelItemSlot, countedItem);
					_slots.Add(inventoryPanelItemSlot);
				}
				i++;
			}
		}
		for (; i < count2; i++)
		{
			_slots[i].gameObject.SetActive(value: false);
		}
	}

	private void InitializeSlot(InventoryPanelItemSlot slot, InventoryAuditor.CountedItem countedItem)
	{
		slot.Initialize(countedItem.ItemProperties, countedItem.UnreservedCount + countedItem.ReservedCount);
	}

	public void ThrowItem(ItemProperties itemProperties)
	{
		if (AllowEject)
		{
			UIEvent.Dispatch(UIEvent.Type.EjectItem);
			Item item = _inventory.ReturnItem(itemProperties, SubInventoryType.Storage);
			item?.Inventory.TakeItem(item);
		}
	}

	private void UpdateNavigation()
	{
		if (_navigable && !(_selectableGroup == null) && _throw.GetButtonUp() && _selectableGroup.Selected is InventoryViewSelectable inventoryViewSelectable)
		{
			ThrowItem(inventoryViewSelectable.ItemProperties);
		}
	}
}
public class InventoryViewSelectable : Selectable
{
	[Header("Inventory View Selectable")]
	[SerializeField]
	private InventoryPanelItemSlot _slot;

	public ItemProperties ItemProperties
	{
		get
		{
			if (!_slot)
			{
				return null;
			}
			return _slot.ItemProperties;
		}
	}
}
public class BirdLeavingWarningBubble : WarningBubble
{
	protected override void Start()
	{
		base.Start();
		foreach (Bird bird in Community.PlayerCommunity.Birds)
		{
			UpdateBirdLeaving(bird);
		}
	}

	protected override void Subscribe()
	{
		GameEventDispatcher.AddListener(GameEventType.BirdAddedToCommunity, OnBirdEvent);
		GameEventDispatcher.AddListener(GameEventType.BirdRemovedFromCommunity, OnBirdEvent);
		GameEventDispatcher.AddListener(GameEventType.BirdVitalsUpdated, OnBirdEvent);
	}

	protected override void Unsubscribe()
	{
		GameEventDispatcher.RemoveListener(GameEventType.BirdAddedToCommunity, OnBirdEvent);
		GameEventDispatcher.RemoveListener(GameEventType.BirdRemovedFromCommunity, OnBirdEvent);
		GameEventDispatcher.RemoveListener(GameEventType.BirdVitalsUpdated, OnBirdEvent);
	}

	private void OnBirdEvent(GameEvent gameEvent)
	{
		BirdEvent birdEvent = gameEvent as BirdEvent;
		UpdateBirdLeaving(birdEvent.Bird);
	}

	private void UpdateBirdLeaving(Bird bird)
	{
		if (bird.IsInPlayerCommunity() && bird.IsLeaving)
		{
			AddBirdLeaving(bird);
		}
		else
		{
			RemoveBirdLeaving(bird);
		}
	}

	private void AddBirdLeaving(Bird bird)
	{
		if (AddObjectOfInterest(new DefaultObjectOfInterest(bird.gameObject, ObjectType.Bird)))
		{
			if (_objectOfInterestContainer.ObjectsOfInterest.Count == 1)
			{
				StartCoroutine(BounceOutTweenCoroutine(_background));
			}
			else if (_objectOfInterestContainer.ObjectsOfInterest.Count > 1)
			{
				StartCoroutine(BounceOutTweenCoroutine(_counter));
			}
		}
	}

	private void RemoveBirdLeaving(Bird bird)
	{
		RemoveObjectOfInterest(bird.gameObject);
	}
}
public class DiseasedDriftersWarningBubble : DrifterWarningBubble
{
