			return;
		}
		if (!_efficiencyImage.gameObject.activeSelf)
		{
			_efficiencyImage.gameObject.SetActive(value: true);
		}
		_efficiencyImage.sprite = ((num < 0) ? _badEfficiencySprite : _goodEfficiencySprite);
	}

