public class OverlayBehaviour : MonoBehaviour
{
	private enum Modes
	{
		Single,
		Multiple
	}

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, false, HideInInspector = true)]
	private Overlays.Type _overlay;

	[SerializeField]
	[ConditionalEnumHide("_mode", 1, false, HideInInspector = true)]
	[NamedArrayElement(new string[] { "" })]
	private Overlays.Type[] _overlays;

	protected virtual void Awake()
	{
		OnOverlayUpdated();
		GameEventDispatcher.AddListener(GameEventType.OverlayUpdate, OnOverlayUpdated);
	}

	protected virtual void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.OverlayUpdate, OnOverlayUpdated);
	}

	private void OnOverlayUpdated(GameEvent gameEvent = null)
	{
		base.gameObject.SetActive(HasActiveOverlay());
	}

	public bool HasActiveOverlay()
	{
		if (((IReadOnlyCollection<Overlays.Type>)(object)_overlays).IsNullOrEmpty())
		{
			return _overlay == Overlays.OverlayType;
		}
		Overlays.Type[] overlays = _overlays;
		for (int i = 0; i < overlays.Length; i++)
		{
			if (overlays[i] == Overlays.OverlayType)
			{
				return true;
			}
		}
		return false;
	}
}
public class OverlayScore : OverlayBehaviour
{
	[Serializable]
	public struct OverlayScoreFormatter
	{
		public Overlays.Type Overlay;

		public IntFormatter Formatter;
	}

	[SerializeField]
	private TextMeshProUGUI _scoreField;

	[SerializeField]
	private Buildable _buildable;

	[SerializeField]
	[NamedArrayElement(new string[] { "Overlay" })]
	private OverlayScoreFormatter[] _formatters;

	private int _score = int.MinValue;

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.OverlayUpdate, OnOverlayUpdate);
		OnOverlayUpdate();
	}

	private void Update()
	{
		switch (Overlays.OverlayType)
		{
		case Overlays.Type.Beauty:
			SetScore(_buildable.ReturnBeautyScore());
			break;
		case Overlays.Type.Weight:
			SetScore(Mathf.RoundToInt(_buildable.ReturnWeight()));
			break;
		}
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.OverlayUpdate, OnOverlayUpdate);
	}

	private void OnOverlayUpdate(GameEvent gameEvent = null)
	{
		_score = int.MinValue;
	}

	private void SetScore(int score)
	{
		if (score == _score)
		{
			return;
		}
		_score = score;
		OverlayScoreFormatter[] formatters = _formatters;
		for (int i = 0; i < formatters.Length; i++)
		{
			OverlayScoreFormatter overlayScoreFormatter = formatters[i];
			if (overlayScoreFormatter.Overlay == Overlays.OverlayType)
			{
				IntFormatter formatter = overlayScoreFormatter.Formatter;
				formatter.Format(_scoreField, _score);
			}
		}
	}
}
