public class WorldIconHandler : WorldInteractable, IUpdateManagerUpdateTarget
{
	[SerializeField]
	private ChildOffsetter _childOffsetter;

	[SerializeField]
	[Tooltip("Prefab used for displaying icons in-game, for example above a characters head.")]
	private WorldIcon _iconPrefab;

	private List<WorldIcon> _icons = new List<WorldIcon>();

	private bool _isRegisteredToUpdateManager;

	public void UpdateManager_Update(float deltaTime, int frame)
	{
		if (HasActiveOverlay())
		{
			ScaleToCamera();
			FaceCamera();
		}
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		UnregisterFromUpdateManager();
	}

	public void ClearAllIcons()
	{
		foreach (WorldIcon icon in _icons)
		{
			if ((bool)icon)
			{
				icon.gameObject.SetActive(value: false);
			}
		}
		UnregisterFromUpdateManager();
	}

	public void AddIcon(IconProperties properties)
	{
		GetIcon(properties).Initialize(properties);
		if (_childOffsetter != null)
		{
			_childOffsetter.UpdateChildren();
		}
		RegisterToUpdateManager();
	}

	public void AddIcon(PlaceableAlertProperties malfunction)
	{
		if (malfunction.WorldIconProperties == null)
		{
			UnityEngine.Debug.LogException(new Exception("Unable to add world icon for malfunction '" + malfunction.name + "', because it is NULL!"));
		}
		else
		{
			AddIcon(malfunction.WorldIconProperties);
		}
	}

	public void RemoveIcon(IconProperties properties)
	{
		foreach (WorldIcon icon in _icons)
		{
			if ((bool)icon && icon.Properties == properties && (bool)icon.gameObject && icon.gameObject.activeSelf)
			{
				icon.gameObject.SetActive(value: false);
				if ((bool)_childOffsetter)
				{
					_childOffsetter.UpdateChildren();
				}
				if (!HasActiveIcons())
				{
					UnregisterFromUpdateManager();
				}
				break;
			}
		}
	}

	private WorldIcon GetIcon(IconProperties iconProperties)
	{
		WorldIcon worldIcon = null;
		int count = _icons.Count;
		while (0 < count--)
		{
			WorldIcon worldIcon2 = _icons[count];
			if (worldIcon2 == null || worldIcon2.gameObject == null)
			{
				_icons.RemoveAt(count);
				continue;
			}
			if (worldIcon2.Properties == iconProperties)
			{
				return worldIcon2;
			}
			if (worldIcon == null && !worldIcon2.gameObject.activeSelf)
			{
				worldIcon = worldIcon2;
			}
		}
		if (worldIcon == null)
		{
			worldIcon = UnityEngine.Object.Instantiate(_iconPrefab, base.transform);
			_icons.Add(worldIcon);
		}
		return worldIcon;
	}

	private void RegisterToUpdateManager()
	{
		if (!_isRegisteredToUpdateManager)
		{
			GameManager.UpdateManager.RegisterUpdateTarget(this);
			_isRegisteredToUpdateManager = true;
		}
	}

	private void UnregisterFromUpdateManager()
	{
		if (_isRegisteredToUpdateManager)
		{
			GameManager.UpdateManager.UnregisterUpdateTarget(this);
			_isRegisteredToUpdateManager = false;
		}
	}

	private bool HasActiveIcons()
	{
		foreach (WorldIcon icon in _icons)
		{
			if ((bool)icon && (bool)icon.gameObject && icon.gameObject.activeSelf)
			{
				return true;
			}
		}
		return false;
	}
}
public class WorldInteractable : OverlayBehaviour
{
	[SerializeField]
	[Tooltip("Scale the interactable to the game camera.")]
	private bool _scaleToCamera = true;

	[SerializeField]
	[ConditionalHide("_scaleToCamera")]
	[Tooltip("Height of the interactable to use when scaling to camera.")]
	private float _height = 38f;

	[SerializeField]
	private bool _clip = true;

	[ConditionalHide("_clip")]
	[SerializeField]
	[Tooltip("Distance at which interactable is made invisible.")]
	private float _clipDistance = 50f;

	private Camera _targetCamera;

	private bool _runningTween;

	protected override void Awake()
	{
		base.Awake();
		_targetCamera = CameraController.Instance.UICamera;
	}

	public void FaceCamera()
	{
		if (_clip)
		{
			float num = Vector3.Distance(base.transform.position, _targetCamera.transform.position);
			if (!_runningTween)
			{
				if (num > _clipDistance + 2f && base.gameObject.activeInHierarchy)
				{
					StartCoroutine(DisappearCoroutine());
					return;
				}
				if (num < _clipDistance - 2f && !base.gameObject.activeInHierarchy)
				{
					base.gameObject.SetActive(value: true);
					StartCoroutine(AppearCoroutine());
				}
			}
		}
		base.gameObject.transform.forward = _targetCamera.transform.forward;
	}

	public void ScaleToCamera()
	{
		if (_scaleToCamera)
		{
			Vector3 vector = _targetCamera.WorldToScreenPoint(base.transform.position);
			Vector3 position = new Vector3(vector.x, vector.y + _height, vector.z);
			Vector3 vector2 = _targetCamera.ScreenToWorldPoint(position);
			base.transform.localScale = Vector3.one * (base.transform.position - vector2).magnitude;
		}
	}

	private IEnumerator DisappearCoroutine()
	{
		_runningTween = true;
		yield return Tweener.TweenRoutine(0.2f, EasingFunctions.SineIn, true, new TransformScaleTweener(base.transform, 0f, is2D: true));
		base.gameObject.SetActive(value: false);
		_runningTween = false;
	}

	private IEnumerator AppearCoroutine()
	{
		_runningTween = true;
		yield return Tweener.TweenRoutine(0.3f, EasingFunctions.SineOut, true, new TransformScaleTweener(base.transform, 1f, is2D: true));
		_runningTween = false;
	}
}
public class Scr_GuiCollider : MonoBehaviour
{
	public string colliderTag = "GuiCollider";

	public bool canConstructionBePlaced = true;

	private List<GameObject> collidedObjects = new List<GameObject>();

	private List<Renderer> colliderMaterials = new List<Renderer>();

	private void Start()
	{
		InitializeReferences();
		if (canConstructionBePlaced)
		{
			SetColor(Color.green);
		}
		else
		{
			SetColor(Color.red);
		}
		GetComponent<Renderer>().material.mainTextureScale = new Vector2(base.gameObject.transform.localScale.x, base.gameObject.transform.localScale.y);
	}

	private void InitializeReferences()
	{
		colliderMaterials.Add(GetComponent<Renderer>());
		colliderMaterials.AddRange(GetComponentsInChildren<Renderer>().ToList());
	}

	private void OnTriggerEnter(Collider other)
	{
		if (other.tag == colliderTag)
		{
			SetColor(Color.red);
			canConstructionBePlaced = false;
			if (!collidedObjects.Contains(other.gameObject))
			{
				collidedObjects.Add(other.gameObject);
			}
		}
	}

	private void OnTriggerExit(Collider other)
	{
		if (other.tag == colliderTag && collidedObjects.Contains(other.gameObject))
		{
			collidedObjects.Remove(other.gameObject);
		}
		if (collidedObjects.Count == 0)
		{
			SetColor(Color.green);
			canConstructionBePlaced = true;
		}
	}

	private void SetColor(Color newColor)
	{
		Color color = new Color(newColor.r, newColor.g, newColor.b, 1f);
		for (int i = 0; i < colliderMaterials.Count; i++)
		{
			colliderMaterials[i].material.color = color;
		}
	}
}
public static class Extensions
