	public static bool Remove<T>(this Queue<T> queue, T itemToRemove)
	{
		int num = 0;
		int i = 0;
		for (int count = queue.Count; i < count; i++)
		{
			T item = queue.Dequeue();
			if (item.Equals(itemToRemove))
			{
				num++;
			}
			else
			{
				queue.Enqueue(item);
			}
		}
		return num > 0;
	}

