	public static string ToByteString(this ulong bytes)
	{
		string[] array = new string[5] { "B", "KB", "MB", "GB", "TB" };
		int num = 0;
		while (bytes >= 1024 && num < array.Length - 1)
		{
			num++;
			bytes /= 1024;
		}
		return $"{bytes:0.##} {array[num]}";
	}

