public abstract class CancelTriggerBase : SceneBehaviour, ICancelable
{
	[SerializeField]
	private InputFlags _activeInputs = InputFlags.All;

	private bool _push;

	private void OnEnable()
	{
		if (FlotsamInputManager.GetUICancel())
		{
			_push = true;
		}
		else
		{
			FlotsamInputManager.PushCancelable(this);
		}
	}

	private void Update()
	{
		if (_push && !FlotsamInputManager.GetUICancel())
		{
			FlotsamInputManager.PushCancelable(this);
			_push = false;
		}
	}

	private void OnDisable()
	{
		FlotsamInputManager.RemoveCancelable(this);
		_push = false;
	}

	public abstract bool TryCancel();

	protected bool HasActiveInput()
	{
		return FlotsamInputManager.HasActiveInput(_activeInputs);
	}
}
public abstract class RewiredJoystickGlyphs<T> : RewiredControllerGlyphs where T : Enum
{
	[Serializable]
	private struct ElementSprite
	{
		[JoystickElement]
		public int Element;

		[HideInInspector]
		public string ElementName;

		public Sprite Sprite;
	}

	[SerializeField]
	private RewiredJoystickStick[] _sticks;

	[SerializeField]
	[NamedArrayElement(new string[] { "ElementName" })]
	private ElementSprite[] _buttons;

	public abstract Guid Guid { get; }

	public override bool SupportsGuid(Guid guid)
	{
		return Guid == guid;
	}

	public override bool TryGetActionNameAndIcon(Controller controller, int actionId, out string name, out Sprite icon, bool skipDisabledMaps = true)
	{
		ActionElementMap firstElementMapWithAction = FlotsamInputManager.GetFirstElementMapWithAction(controller, actionId, skipDisabledMaps);
		if (firstElementMapWithAction != null && TryGetElementGlyph(firstElementMapWithAction, out var glyph))
		{
			name = firstElementMapWithAction.actionDescriptiveName;
			icon = glyph;
			return true;
		}
		name = null;
		icon = null;
		return false;
	}

	public override bool TryGetActionsParameterValue(Controller controller, List<int> actionIds, out string value, bool skipDisabledMaps)
	{
		using ListPool<object>.List list = ListPool<object>.Get();
		foreach (int actionId in actionIds)
		{
			ActionElementMap firstElementMapWithAction = FlotsamInputManager.GetFirstElementMapWithAction(controller, actionId, skipDisabledMaps);
			if (firstElementMapWithAction != null && !TryAddStick(firstElementMapWithAction, list) && TryGetElementGlyph(firstElementMapWithAction, out var glyph))
			{
				list.Add($"<sprite=\"{glyph.texture.name}\" sprite name=\"{glyph.name}\">");
			}
		}
		value = (list.IsNullOrEmpty() ? null : (value = string.Concat(list)));
		ResetSticks();
		return !string.IsNullOrEmpty(value);
	}

	private bool TryGetElementGlyph(ActionElementMap aem, out Sprite glyph)
	{
		ElementSprite[] buttons = _buttons;
		for (int i = 0; i < buttons.Length; i++)
		{
			ElementSprite elementSprite = buttons[i];
			if (elementSprite.Element == aem.elementIdentifierId)
			{
				glyph = elementSprite.Sprite;
				return true;
			}
		}
		glyph = null;
		return false;
	}

	private bool TryAddStick(ActionElementMap aem, List<object> actions)
	{
		RewiredJoystickStick[] sticks = _sticks;
		foreach (RewiredJoystickStick rewiredJoystickStick in sticks)
		{
			if (rewiredJoystickStick.TryAddAction(aem))
			{
				actions.AddUnique(rewiredJoystickStick);
				return true;
			}
		}
		return false;
	}

	private void ResetSticks()
	{
		RewiredJoystickStick[] sticks = _sticks;
		for (int i = 0; i < sticks.Length; i++)
		{
			sticks[i].Reset();
		}
	}
}
[CreateAssetMenu(menuName = "Pajama Llama/Rewired/Stick")]
public class RewiredJoystickStick : ScriptableObject
{
	[Flags]
	public enum Actions
	{
		None = 0,
		AxisXNegative = 1,
		AxisXPositive = 2,
		AxisYNegative = 4,
		AxisYPositive = 8
	}

	[Serializable]
	public struct Sprites
	{
		public Sprite AxisXNegative;

		public Sprite AxisXPositive;

		public Sprite AxisYNegative;

		public Sprite AxisYPositive;

		public Sprite AxisX;

		public Sprite AxisY;

		public Sprite All;
	}

	[SerializeField]
	private int _identifierX;

	[SerializeField]
	private int _identifierY = 1;

	[SerializeField]
	private Sprites _icons;

	[SerializeField]
	private Sprites _glyphs;

	[NonSerialized]
	private Actions _actions;

	public void Reset()
	{
		_actions = Actions.None;
	}

	public bool TryAddAction(ActionElementMap aem)
	{
		if (aem.elementIdentifierId == _identifierX)
		{
			AddAction(aem, Actions.AxisXNegative, Actions.AxisXPositive);
		}
		else
		{
			if (aem.elementIdentifierId != _identifierY)
			{
				return false;
			}
			AddAction(aem, Actions.AxisYNegative, Actions.AxisYPositive);
		}
		return true;
	}

	public override string ToString()
	{
		Sprite sprite = _actions switch
		{
			Actions.AxisXNegative => _glyphs.AxisXNegative, 
			Actions.AxisXPositive => _glyphs.AxisXPositive, 
			Actions.AxisYNegative => _glyphs.AxisYNegative, 
			Actions.AxisYPositive => _glyphs.AxisYPositive, 
			Actions.AxisXNegative | Actions.AxisXPositive => _glyphs.AxisX, 
			Actions.AxisYNegative | Actions.AxisYPositive => _glyphs.AxisY, 
			Actions.None => null, 
			_ => _glyphs.All, 
		};
		if ((bool)sprite)
		{
			return $"<sprite=\"{sprite.texture.name}\" sprite name=\"{sprite.name}\">";
		}
		return "WHOOPS!";
	}

	private void AddAction(ActionElementMap aem, Actions negative, Actions positive)
	{
		switch (aem.axisRange)
		{
		case AxisRange.Negative:
			_actions |= negative;
			break;
		case AxisRange.Positive:
			_actions |= positive;
			break;
		case AxisRange.Full:
			_actions |= negative | positive;
			break;
		default:
			throw new NotImplementedException();
		}
	}
}
public abstract class RewiredControllerGlyphs : ScriptableObject
{
	public const string SPRITE_TAG_FORMAT = "<sprite=\"{0}\" sprite name=\"{1}\">";

	public abstract bool SupportsGuid(Guid guid);

	public abstract bool TryGetActionNameAndIcon(Controller controller, int actionId, out string name, out Sprite icon, bool skipDisabledMaps);

	public abstract bool TryGetActionsParameterValue(Controller controller, List<int> actionIds, out string value, bool skipDisabledMaps);
}
