			{
				return true;
			}
		}
		return _fallback.TryGetActionsParameterValue(controller, actionIds, out value, skipDisabledMaps);
	}
}
[CreateAssetMenu(menuName = "Pajama Llama/Rewired/Rewired Glyphs")]
public class RewiredGlyphProvider : ScriptableObject
{
	[SerializeField]
	[FormerlySerializedAs("_joysticks")]
	private RewiredControllerGlyphs[] _controllerGlyphs;

	[SerializeField]
	private RewiredControllerGlyphs _fallbackControllerGlyphs;

	public bool SupportsJoystick(Joystick joystick)
	{
		if (_fallbackControllerGlyphs.SupportsGuid(joystick.hardwareTypeGuid))
		{
			return true;
		}
		RewiredControllerGlyphs[] controllerGlyphs = _controllerGlyphs;
		for (int i = 0; i < controllerGlyphs.Length; i++)
		{
			if (controllerGlyphs[i].SupportsGuid(joystick.hardwareTypeGuid))
			{
				return true;
			}
		}
		return false;
	}

	public bool TryGetActiveControllerActionNameAndIcon(out string name, out Sprite icon, int actionId, bool skipDisabledMaps = true)
	{
		Controller activeController = FlotsamInputManager.GetActiveController();
		if (TryGetActionNameAndIcon(activeController, actionId, out name, out icon, skipDisabledMaps))
		{
			return true;
		}
		if (_fallbackControllerGlyphs.TryGetActionNameAndIcon(activeController, actionId, out name, out icon, skipDisabledMaps))
		{
			return true;
		}
		name = null;
		icon = null;
		return false;
	}

	private bool TryGetActionNameAndIcon(Controller controller, int actionId, out string name, out Sprite icon, bool skipDisabledMaps = true)
	{
		if (controller != null)
		{
			RewiredControllerGlyphs[] controllerGlyphs = _controllerGlyphs;
			foreach (RewiredControllerGlyphs rewiredControllerGlyphs in controllerGlyphs)
			{
				if (rewiredControllerGlyphs.SupportsGuid(controller.hardwareTypeGuid))
				{
					return rewiredControllerGlyphs.TryGetActionNameAndIcon(controller, actionId, out name, out icon, skipDisabledMaps);
				}
			}
		}
		name = null;
		icon = null;
		return false;
	}

	public bool TryGetActionsParameterValue(List<int> actionIds, out string value, bool skipDisabledMaps = true)
	{
		Controller activeController = FlotsamInputManager.GetActiveController();
		if (TryGetActionParameterValue(activeController, actionIds, out value, skipDisabledMaps))
		{
			return true;
		}
		if (_fallbackControllerGlyphs.TryGetActionsParameterValue(activeController, actionIds, out value, skipDisabledMaps))
		{
			return true;
		}
		value = null;
		return false;
	}

	private bool TryGetActionParameterValue(Controller controller, List<int> actionIds, out string value, bool skipDisabledMaps = true)
	{
		if (controller != null)
		{
			RewiredControllerGlyphs[] controllerGlyphs = _controllerGlyphs;
			foreach (RewiredControllerGlyphs rewiredControllerGlyphs in controllerGlyphs)
			{
				if (rewiredControllerGlyphs.SupportsGuid(controller.hardwareTypeGuid))
				{
					return rewiredControllerGlyphs.TryGetActionsParameterValue(controller, actionIds, out value, skipDisabledMaps);
				}
			}
		}
		value = null;
		return false;
	}
}
[CreateAssetMenu(menuName = "Pajama Llama/Rewired/KeyboardAndMouse")]
public class RewiredKeyboardAndMouse : RewiredControllerGlyphs
{
	public enum MouseButtonElementIds
	{
		None = -1,
		MouseHorizontal,
		MouseVertical,
		MouseWheel,
		LeftMouseButton,
		RightMouseButton,
		MouseButton3,
		MouseButton4,
		MouseButton5
	}

	[Serializable]
	public struct KeyboardGlyph
	{
		public KeyboardKeyCode KeyCode;

		public Sprite Glyph;
	}

	[Serializable]
	public struct MouseGlyph
	{
		public MouseButtonElementIds[] ElementIds;

		public LocalizedString Description;

		public Sprite Glyph;

		public bool IsMatch(ActionElementMap aem)
		{
			if (ElementIds.Length == 1)
			{
				return ElementIds[0] == (MouseButtonElementIds)aem.elementIdentifierId;
			}
			return false;
		}

		public bool IsMatch(List<ActionElementMap> aems)
		{
			try
			{
				if (aems.Count == ElementIds.Length)
				{
					foreach (ActionElementMap aem in aems)
					{
						if (!HasElementId(aem))
						{
							return false;
						}
					}
					return true;
				}
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
			return false;
		}

		private bool HasElementId(ActionElementMap aem)
		{
			for (int i = 0; i < ElementIds.Length; i++)
			{
				if (ElementIds[i] == (MouseButtonElementIds)aem.elementIdentifierId)
				{
					return true;
				}
			}
			return false;
		}
	}

	public static readonly Guid KEYBOARD_GUID = new Guid("ae4830f9-63db-4d4c-90b3-1beb46ecaf49");

	public static readonly Guid MOUSE_GUID = new Guid("ad60107c-ea39-4d9c-b906-56d39d07be95");

	[SerializeField]
	[NamedArrayElement(new string[] { "Glyph" })]
	private MouseGlyph[] _mouseGlyphs;

	[SerializeField]
	[NamedArrayElement(new string[] { "KeyCode" })]
	private KeyboardGlyph[] _keyboardGlyphs;

	public override bool SupportsGuid(Guid guid)
	{
		if (!(guid == KEYBOARD_GUID))
		{
			return guid == MOUSE_GUID;
		}
		return true;
	}

	public override bool TryGetActionNameAndIcon(Controller controller, int actionId, out string name, out Sprite icon, bool skipDisabledMaps)
	{
		if (!TryGetMouseAction(actionId, out name, out icon, skipDisabledMaps))
		{
			return TryGetKeyboardAction(actionId, out name, out icon, skipDisabledMaps);
		}
		return true;
	}

	private bool TryGetMouseAction(int actionId, out string name, out Sprite icon, bool skipDisabledMaps)
	{
		ActionElementMap firstMouseMapWithAction = FlotsamInputManager.GetFirstMouseMapWithAction(actionId, skipDisabledMaps);
		if (firstMouseMapWithAction != null && TryGetSingleActionMouseGlyph(firstMouseMapWithAction, out var mouseGlyph))
		{
			name = firstMouseMapWithAction.actionDescriptiveName;
			icon = mouseGlyph.Glyph;
			return true;
		}
		name = null;
		icon = null;
		return false;
	}

	private bool TryGetKeyboardAction(int actionId, out string name, out Sprite icon, bool skipDisabledMaps)
	{
		ActionElementMap firstKeyboardMapWithAction = FlotsamInputManager.GetFirstKeyboardMapWithAction(actionId, skipDisabledMaps);
		if (firstKeyboardMapWithAction != null)
		{
			KeyboardGlyph[] keyboardGlyphs = _keyboardGlyphs;
			for (int i = 0; i < keyboardGlyphs.Length; i++)
			{
				KeyboardGlyph keyboardGlyph = keyboardGlyphs[i];
				if (keyboardGlyph.KeyCode == firstKeyboardMapWithAction.keyboardKeyCode)
				{
					name = firstKeyboardMapWithAction.actionDescriptiveName;
					icon = keyboardGlyph.Glyph;
					return true;
				}
			}
		}
		name = null;
		icon = null;
		return false;
	}

	public override bool TryGetActionsParameterValue(Controller controller, List<int> actionIds, out string value, bool skipDisabledMaps)
	{
		value = GetMouseParameterValue(actionIds, skipDisabledMaps);
		foreach (int actionId in actionIds)
		{
			if (TryGetKeyboardActionString(actionId, out var action, skipDisabledMaps))
			{
				value += action;
			}
		}
		if (string.IsNullOrEmpty(value))
		{
			return false;
		}
		return !string.IsNullOrEmpty(value);
	}

	private string GetMouseParameterValue(List<int> actionIds, bool skipDisabledMaps)
	{
		using ListPool<ActionElementMap>.List list = ListPool<ActionElementMap>.Get();
		bool flag = true;
		string text = string.Empty;
		int count = actionIds.Count;
		while (0 < count--)
		{
			ActionElementMap firstMouseMapWithAction = FlotsamInputManager.GetFirstMouseMapWithAction(actionIds[count], skipDisabledMaps);
			if (firstMouseMapWithAction != null)
			{
				actionIds.RemoveAt(count);
				list.Insert(0, firstMouseMapWithAction);
			}
		}
		if (TryGetMultipleActionMouseGlyph(list, out var mouseGlyph))
		{
			flag = false;
			text += GetTextGlyph(mouseGlyph.Glyph);
		}
		foreach (ActionElementMap item in list)
		{
			if (TryGetSingleActionMouseGlyph(item, out mouseGlyph))
			{
				if (flag)
				{
					text += GetTextGlyph(mouseGlyph.Glyph);
				}
				if (!string.IsNullOrEmpty(mouseGlyph.Description.mTerm))
				{
					text += $"[{mouseGlyph.Description}]";
					continue;
				}
			}
			text = text + "[" + item.elementIdentifierName + "]";
		}
		return text;
	}

	private bool TryGetMultipleActionMouseGlyph(List<ActionElementMap> aems, out MouseGlyph mouseGlyph)
	{
		mouseGlyph = default(MouseGlyph);
		for (int i = 0; i < _mouseGlyphs.Length; i++)
		{
			mouseGlyph = _mouseGlyphs[i];
			if (mouseGlyph.IsMatch(aems))
			{
				return true;
			}
		}
		return false;
	}

	private bool TryGetSingleActionMouseGlyph(ActionElementMap aem, out MouseGlyph mouseGlyph)
	{
		mouseGlyph = default(MouseGlyph);
		for (int i = 0; i < _mouseGlyphs.Length; i++)
		{
			mouseGlyph = _mouseGlyphs[i];
			if (mouseGlyph.IsMatch(aem))
			{
				return true;
			}
		}
		return false;
	}

	private bool TryGetKeyboardActionString(int actionId, out string action, bool skipDisabledMaps)
	{
		ActionElementMap firstKeyboardMapWithAction = FlotsamInputManager.GetFirstKeyboardMapWithAction(actionId, skipDisabledMaps);
		if (firstKeyboardMapWithAction != null)
		{
			if (TryGetKeyboardGlyph(firstKeyboardMapWithAction, out var keyboardGlyph))
			{
				action = GetTextGlyph(keyboardGlyph.Glyph);
			}
			else
			{
				action = $"[{firstKeyboardMapWithAction.keyCode}]";
			}
			return true;
		}
		action = null;
		return false;
	}

	private bool TryGetKeyboardGlyph(ActionElementMap aem, out KeyboardGlyph keyboardGlyph)
	{
		keyboardGlyph = default(KeyboardGlyph);
		for (int i = 0; i < _keyboardGlyphs.Length; i++)
		{
			keyboardGlyph = _keyboardGlyphs[i];
			if (keyboardGlyph.KeyCode == aem.keyboardKeyCode)
			{
				return true;
			}
		}
		return false;
	}

	private string GetTextGlyph(Sprite glyph)
	{
		return $"<sprite=\"{glyph.texture.name}\" sprite name=\"{glyph.name}\">";
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Strategies/Energy Pole")]
public class EnergyPolePreviewStrategy : BuildableCursorProperties, IMoveBuildablePreviewStrategy
{
	[SerializeField]
	[Tooltip("The buildable version of energy poles should not be able to be built anymore, so we want to build the decoration version instead")]
	private DecorationProperties _decorationVersionCursorProperties;

	[SerializeField]
	private float _snappingDistance = 10f;

	[SerializeField]
	private Color _selectedDecoSlotColor = Color.red;

	[Header("Rotation")]
	[SerializeField]
	private RewiredAction _rotateRewiredAction;

	[SerializeField]
	private RewiredAction _variationRewiredAction;

	[NonSerialized]
	private Dictionary<VisualPrefab, VisualPrefab> _previewPool;

	[NonSerialized]
	private VisualPrefab _polePreview;

	[NonSerialized]
	private DecorationSlots _closestDecoSlots;

	[NonSerialized]
	private Quaternion _rotation = Quaternion.identity;

	[NonSerialized]
	private DecorationProperties.Turns _turn;

	[NonSerialized]
	private List<int> _slotIndices;

	[NonSerialized]
	private List<int> _previousSlotIndicesCache;

	public override void Activate()
	{
		base.Activate();
		if (_previewPool == null)
		{
			_previewPool = new Dictionary<VisualPrefab, VisualPrefab>(8);
		}
		_visualIndex = _buildable.ReturnVisualIndex(_visualIndex);
		if (_visualIndex < 0 || _visualIndex >= _decorationVersionCursorProperties.VisualPrefabs.Length)
		{
			_visualIndex = 0;
		}
		_polePreview = ReturnPreview();
		if (!_buildable.TryGetComponent<EnergyGridPole>(out var _))
		{
			UnityEngine.Debug.LogError("Passed a buildable to " + base.name + " that does not have a energy pole component.");
		}
	}

	public IMoveBuildablePreviewStrategy Activate(Buildable buildable, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Buildable buildableOut)
	{
		preview = IMoveBuildablePreviewStrategy.CreateConstructionVisual(buildable.Properties.Prefab, visualIndex, previewSettings, isHooked: false, createMarkerProxy: true);
		buildableOut = SetBuildable(buildable);
		ActivateInternal(visualIndex);
		return this;
	}

	public IMoveBuildablePreviewStrategy Activate(Decoration decoration, DecorationProperties decorationProperties, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Decoration decorationOut)
	{
		preview = IMoveBuildablePreviewStrategy.CreateConstructionVisual(GameManager.Settings.BuildableSettings.EnergyPoleBuildableProperties.Prefab, visualIndex, previewSettings, isHooked: false, createMarkerProxy: true);
		decorationOut = SetDecoration(decoration, decorationProperties);
		ActivateInternal(visualIndex);
		return this;
	}

	private void ActivateInternal(int visualIndex)
	{
		if (_previewPool == null)
		{
			_previewPool = new Dictionary<VisualPrefab, VisualPrefab>(8);
		}
		_visualIndex = visualIndex;
		if (_visualIndex < 0 || _visualIndex >= _decorationVersionCursorProperties.VisualPrefabs.Length)
		{
			_visualIndex = 0;
		}
		_polePreview = ReturnPreview();
		UIManager.AddRewiredActionInfoToContext(this, _rotateRewiredAction, _variationRewiredAction, base.Interact, base.Cancel);
		if (_slotIndices == null)
		{
			_slotIndices = new List<int>();
		}
		else
		{
			_slotIndices.Clear();
		}
	}

	public override void DeactivateImmediately()
	{
		base.DeactivateImmediately();
		_polePreview.gameObject.SetActive(value: false);
		foreach (QuickConnecting quickConnector in QuickConnecting.QuickConnectors)
		{
			quickConnector.DisableParticle();
		}
		foreach (DecorationSlots decorationSlot in Community.PlayerCommunity.DecorationSlots)
		{
			decorationSlot.DisablePlacementMode();
		}
		UIManager.DisableRewiredActionInfoContext(this);
	}

	public override void UpdateCursor(CursorManager cursor)
	{
	}

	public void UpdateConstructionPreview(ref ConstructionPreview preview)
	{
		if (_variationRewiredAction.GetButtonUp())
		{
			_visualIndex = PajamaLlama.Math.Math.IncrementIndexWrapped(_visualIndex, _decorationVersionCursorProperties.VisualPrefabs.Length);
			if (_polePreview != null)
			{
				_polePreview.gameObject.SetActive(value: false);
			}
			_polePreview = ReturnPreview();
		}
		if (_rotateRewiredAction.GetButtonUp())
		{
			UpdateRotation();
		}
		UpdateTransform();
		ShowVisualizersInRange();
		bool flag = _closestDecoSlots != null;
		preview.SetCanPlace(flag);
		preview.SetValid(flag);
	}

	public bool MoveBuildable(ref Buildable buildable, ConstructionPreview preview)
	{
		Decoration decoration = _closestDecoSlots.AddDecoration(_decorationVersionCursorProperties, _turn, _visualIndex, _slotIndices, instantFreeBuild: true);
		if (!buildable.CustomName.IsNullOrEmpty())
		{
			decoration.Name = buildable.CustomName;
		}
		buildable.Remove();
		DeactivateImmediately();
		return true;
	}

	public bool MoveDecoration(Decoration decoration, ConstructionPreview preview)
	{
		Decoration decoration2 = _closestDecoSlots.AddDecoration(decoration.Properties, _turn, _visualIndex, _slotIndices, instantFreeBuild: true);
		if (!decoration.CustomName.IsNullOrEmpty())
		{
			decoration2.Name = decoration.CustomName;
		}
		decoration.Remove(immediately: true);
		DeactivateImmediately();
		return true;
	}

	public Buildable SetBuildable(Buildable buildable)
	{
		if (buildable.TryReturnBuildableExtendable<EnergyGridPole>(out var buildableExtendable))
		{
			if (buildable.TryGetComponentInParent<WalkwayPonton>(out var componentInParent) && componentInParent.EnergyPole == buildableExtendable)
			{
				componentInParent.DetachEnergyPole(buildable);
				buildable.transform.SetParent(null);
			}
			if (buildable.TryReturnBuildableExtendable<EnergyGridBuildableComponent>(out var buildableExtendable2))
			{
				buildableExtendable2.DisconnectAll();
			}
			buildable.gameObject.SetActive(value: false);
			return buildable;
		}
		return buildable.Properties.Prefab;
	}

	public Decoration SetDecoration(Decoration decoration, DecorationProperties decorationProperties)
	{
		if (decoration.TryGetExtendable<EnergyGridPole>(out var _))
		{
			if (decoration.TryGetExtendable<EnergyGridDecorationComponent>(out var extendable2))
			{
				extendable2.DisconnectAll();
			}
			if ((bool)decoration.Parent)
			{
				decoration.Parent.RemoveDecorationImmediate(decoration);
			}
			decoration.transform.SetParent(null);
			decoration.gameObject.SetActive(value: false);
			return decoration;
		}
		return decorationProperties.DecorationPrefab;
	}

	public void StoreBuildable(Buildable buildable, bool toggleCategory)
	{
		DeactivateImmediately();
		Community.PlayerCommunity.AddStoredBuildable(buildable.Properties, buildable, toggleCategory);
	}

	public void StoreDecoration(Decoration decoration, bool toggleCategory)
	{
		DeactivateImmediately();
		Community.PlayerCommunity.AddStoredDecoration(decoration.Properties, decoration, toggleCategory);
	}

	public void ContinuousBuilding()
	{
	}

	private void UpdateTransform()
	{
		Quaternion quaternion = Quaternion.identity;
		Vector3 buildingPosition = CursorManager.BuildingPosition;
		DecorationSlots closestDecoSlots = _closestDecoSlots;
		_slotIndices.CopyTo(ref _previousSlotIndicesCache);
		if (TryReturnClosestAvailableSlots(buildingPosition, out var decorationPosition))
		{
			quaternion = _closestDecoSlots.transform.rotation;
			buildingPosition = decorationPosition;
			_closestDecoSlots.SetSlotsOutlineColor(_slotIndices, _selectedDecoSlotColor);
		}
		else
		{
			buildingPosition = WorldManager.WaterAdjustedPosition(buildingPosition);
		}
		if (closestDecoSlots != null && (closestDecoSlots != _closestDecoSlots || (!_previousSlotIndicesCache.IsNullOrEmpty() && !_previousSlotIndicesCache.IsEqual(_slotIndices))))
		{
			closestDecoSlots.SetSlotsOutlineColor(_previousSlotIndicesCache, Color.white);
		}
		_polePreview.transform.SetPositionAndRotation(buildingPosition, quaternion * _rotation);
	}

	private bool TryReturnClosestAvailableSlots(Vector3 position, out Vector3 decorationPosition)
	{
		_closestDecoSlots = null;
		decorationPosition = Vector3.zero;
		float num = _snappingDistance * _snappingDistance;
		using ListPool<int>.List list = ListPool<int>.Get();
		foreach (DecorationSlots decorationSlot in Community.PlayerCommunity.DecorationSlots)
		{
			if (!decorationSlot.TryEnablePlacementMode(_decorationVersionCursorProperties) || !decorationSlot.TryPopulateClosestSlotIndices(list, position, out var closesetPosition, _decorationVersionCursorProperties, _turn))
			{
				continue;
			}
			float num2 = position.DistanceToSquared(closesetPosition);
			if (!(num2 < num))
			{
				continue;
			}
			num = num2;
			_closestDecoSlots = decorationSlot;
			decorationPosition = closesetPosition;
			_slotIndices.Clear();
			foreach (int item in list)
			{
				_slotIndices.Add(item);
			}
		}
		return _closestDecoSlots != null;
	}

	private void ShowVisualizersInRange()
	{
		foreach (QuickConnecting quickConnector in QuickConnecting.QuickConnectors)
		{
			if (quickConnector.Component.IsInRange(_polePreview.transform.position))
			{
				quickConnector.EnableParticle();
			}
			else
			{
				quickConnector.DisableParticle();
			}
		}
	}

	private void UpdateRotation()
	{
		switch (_turn)
		{
		case DecorationProperties.Turns.Full:
			_turn = DecorationProperties.Turns.Quarter;
			_rotation = DecorationProperties.ROTATION_QUARTER;
			break;
		case DecorationProperties.Turns.Quarter:
			_turn = DecorationProperties.Turns.Half;
			_rotation = DecorationProperties.ROTATION_HALF;
			break;
		case DecorationProperties.Turns.Half:
			_turn = DecorationProperties.Turns.ThreeQuarter;
			_rotation = DecorationProperties.ROTATION_THREE_QUARTER;
			break;
		case DecorationProperties.Turns.ThreeQuarter:
			_turn = DecorationProperties.Turns.Full;
			_rotation = DecorationProperties.ROTATION_FULL;
			break;
		}
	}

	private VisualPrefab ReturnPreview()
	{
		bool flag = false;
		VisualPrefab visualPrefab = _decorationVersionCursorProperties.VisualPrefabs[_visualIndex];
		if (_previewPool.TryGetValue(visualPrefab, out var value))
		{
			if ((bool)value)
			{
				value.gameObject.SetActive(value: true);
				return value;
			}
			flag = true;
		}
		value = _previewSettings.InstantiatePreview(visualPrefab);
		value.name = "[PREVIEW] " + value.name;
		if (flag)
		{
			_previewPool[visualPrefab] = value;
		}
		else
		{
			_previewPool.Add(visualPrefab, value);
		}
		return value;
	}
}
public interface IMoveBuildablePreviewStrategy
{
	IMoveBuildablePreviewStrategy Activate(Buildable buildable, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Buildable buildableOut);

	void UpdateConstructionPreview(ref ConstructionPreview preview);

	void StoreBuildable(Buildable buildable, bool toggleCategory);

	bool MoveBuildable(ref Buildable buildable, ConstructionPreview preview);

	void ContinuousBuilding();

	IMoveBuildablePreviewStrategy Activate(Decoration decoration, DecorationProperties decorationProperties, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Decoration decorationOut)
	{
		preview = null;
		decorationOut = null;
		return null;
	}

	void StoreDecoration(Decoration decoration, bool toggleCategory)
	{
	}

	bool MoveDecoration(Decoration decoration, ConstructionPreview preview)
	{
		return false;
	}

	static ConstructionPreview CreateConstructionVisual(Buildable buildable, int visualIndex, VisualPrefabPreviewSettings previewSettings, bool isHooked = false, bool createMarkerProxy = false)
	{
		return new ConstructionPreview(buildable, previewSettings, visualIndex, createMarkerProxy, isHooked);
	}

	static void DisconnectEnergyConnections(Buildable buildable)
	{
		if (!buildable.TryReturnBuildableExtendable<EnergyGridBuildableComponent>(out var buildableExtendable) || !buildableExtendable.HasConnections())
		{
			return;
		}
		EnergyGridConnector[] connections = buildableExtendable.Connections;
		foreach (EnergyGridConnector energyGridConnector in connections)
		{
			if ((bool)energyGridConnector)
			{
				EnergyGrid.Disconnect(buildableExtendable, energyGridConnector);
			}
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Strategies/Line Construction")]
public class LineConstructionPreviewStrategy : LineConstructionCursorProperties, IMoveBuildablePreviewStrategy
{
	[NonSerialized]
	private Hookable _nextWaypoint;

	[NonSerialized]
	private BuildableProperties _pontonProperties;

	public IMoveBuildablePreviewStrategy Activate(Buildable buildable, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Buildable buildableOut)
	{
		return Activate(buildable, GetWalkwayPontonProperties(buildable), visualIndex, previewSettings, out preview, out buildableOut);
	}

	public IMoveBuildablePreviewStrategy Activate(Buildable buildable, BuildableProperties pontonProperties, int visualIndex, VisualPrefabPreviewSettings previewSettings, out ConstructionPreview preview, out Buildable buildableOut)
	{
		_pontonProperties = pontonProperties;
		Buildable prefab = _pontonProperties.Prefab;
		Vector3 b = (_pontonProperties.Outline[0].Vector3TopDown() + _pontonProperties.Outline[_pontonProperties.Outline.Length - 1].Vector3TopDown()) * 0.5f;
		float hookDistance = Vector3.Distance(prefab.transform.position, b);
		preview = IMoveBuildablePreviewStrategy.CreateConstructionVisual(prefab, visualIndex, previewSettings, isHooked: false, createMarkerProxy: true);
		_startWaypointPreview = IMoveBuildablePreviewStrategy.CreateConstructionVisual(prefab, visualIndex, previewSettings);
		_endWaypointPreview = IMoveBuildablePreviewStrategy.CreateConstructionVisual(prefab, visualIndex, previewSettings);
		_endWaypointPreview.Disable();
		_segments = (_pontonProperties.PlacementCursorProperties as LineConstructionCursorProperties).Segments;
		_previewSettings = previewSettings;
		_hookDistance = hookDistance;
		buildableOut = GetBuildablePrefab(buildable);
		_buildable = buildableOut;
		InitializeSegments();
		return this;
	}

	public void UpdateConstructionPreview(ref ConstructionPreview preview)
	{
		bool canBePlaced = true;
		bool snapBuilding = Settings.Instance.GameplayPlayerData.SnapBuilding;
		switch (_iteration)
		{
		case Iteration.StartPreview:
			UpdatePreviewPlacingConstruction(_startWaypointPreview, out _startPosition, out canBePlaced, _maximumLength / 2, _maximumLength / 2, _requiredResources);
			break;
		case Iteration.LinePreview:
			UpdateLinePreview(snapBuilding, out canBePlaced);
			break;
		}
		preview.SetCanPlace(canBePlaced);
	}

	public bool MoveBuildable(ref Buildable buildable, ConstructionPreview preview)
	{
		return Iterate();
	}

	public Buildable GetBuildablePrefab(Buildable buildable)
	{
		BuildableProperties buildableProperties = buildable.Properties;
		WalkwayPonton buildableExtendable2;
		if (buildable.TryReturnBuildableExtendable<WalkwaySegment>(out var _) && buildableProperties is WalkwaySegmentProperties walkwaySegmentProperties)
		{
			buildable.Deactivate();
			buildable.Remove();
			buildableProperties = walkwaySegmentProperties.walkwayPontonProperties;
		}
		else if (buildable.TryReturnBuildableExtendable<WalkwayPonton>(out buildableExtendable2))
		{
			buildableExtendable2.RemoveAttachedWalkwaySegment();
		}
		return buildableProperties.Prefab;
	}

	public void StoreBuildable(Buildable buildable, bool toggleCategory)
	{
		Community.PlayerCommunity.AddStoredBuildable(_pontonProperties, buildable, toggleCategory);
		Remove();
	}

	private void Remove()
	{
		RemoveConstructionPreview(ref _startWaypointPreview);
		RemoveConstructionPreview(ref _endWaypointPreview);
		RemoveConstructionPreview(ref _segmentPreview);
		Reset();
	}

	private bool Iterate()
	{
		switch (_iteration)
		{
		case Iteration.StartPreview:
			_iteration++;
			_startWaypointPreview.Disable();
			_endWaypointPreview.Enable();
			break;
		case Iteration.LinePreview:
		{
			PlaceLine(_currentSegment, out var waypoint, hookNext: false, storedBuildable: true);
			_nextWaypoint = waypoint;
			Remove();
			return true;
		}
		}
		return false;
	}

	private BuildableProperties GetWalkwayPontonProperties(Buildable buildable)
	{
		if (buildable.Properties is WalkwaySegmentProperties walkwaySegmentProperties)
		{
			return walkwaySegmentProperties.walkwayPontonProperties;
		}
		if (buildable.TryReturnBuildableExtendable<WalkwayPonton>(out var buildableExtendable) && buildableExtendable.NeighbouringWalkwaySegments.Count == 1 && buildableExtendable.NeighbouringWalkwaySegments[0].Buildable.Properties is WalkwaySegmentProperties walkwaySegmentProperties2)
		{
			return walkwaySegmentProperties2.walkwayPontonProperties;
		}
		return buildable.Properties;
	}

	public void ContinuousBuilding()
	{
		_iteration = Iteration.LinePreview;
		_startWaypointPreview.IsHooked = true;
		ContinuousBuilding(_nextWaypoint, useWaypointPosition: true);
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Move Buildable")]
public class MoveBuildableCursorProperties : ConstructionCursorProperties, ITooltipProvider, IPanelContext
{
	private enum Interaction
	{
		None,
		Pickup,
		Store
	}

	[Header("Move Construction")]
	[SerializeField]
	private LayerMask _layerMask;

	[SerializeField]
	private CursorState _selectCursor;

	[SerializeField]
	private CursorState _blockedCursor;

	[SerializeField]
	private CursorState _linkCursor;

	[SerializeField]
	private float _blinkRedDuration;

	[SerializeField]
	private int _blinkRedTimes;

	[SerializeField]
	private LocalizedString _blockingText;

	[SerializeField]
	private Color _blockingColor;

	[SerializeField]
	private SingleConstructionPreviewStrategy _singleConstructionPreviewStrategy;

	[SerializeField]
	private EnergyPolePreviewStrategy _energyPolePreviewStrategy;

	[SerializeField]
	private LineConstructionPreviewStrategy _lineConstructionPreviewStrategy;

	[SerializeField]
	private MoveBuildableEnergyConnectionCursorProperties _energyGridLinkCursorProperties;

	[SerializeField]
	public AssignmentType _achtitectAssignmentType;

	[SerializeField]
	private Material _architectWaterMaterial;

	[SerializeField]
	private DialogProperties _exitPanelProperties;

	[NonSerialized]
	protected Decoration _decoration;

	[NonSerialized]
	private Buildable _mouseOverBuildable;

	[NonSerialized]
	private Decoration _mouseOverDecoration;

	[NonSerialized]
	private Coroutine _blockingCoroutine;

	[NonSerialized]
	private List<Material> _blockingMaterials = new List<Material>();

	[NonSerialized]
	private ConstructionPreview _constructionPreview;

	[NonSerialized]
	private IMoveBuildablePreviewStrategy _buildablePreviewStrategy;

	[NonSerialized]
	private bool _changeLayout;

	[NonSerialized]
	private bool _restoreGameSpeed;

	[NonSerialized]
	private bool _connectingEnegryGridInProgress;

	[NonSerialized]
	private Agent _architect;

	[NonSerialized]
	private Material _defaultWaterMaterial;

	[NonSerialized]
	private Vector3 _cancelDownCameraPosition;

	public PanelID PanelID => PanelID.ArchitectExit;

	public bool BlocksApply
	{
		get
		{
			if (_constructionPreview == null)
			{
				return _connectingEnegryGridInProgress;
			}
			return true;
		}
	}

	public override void Activate()
	{
		RemoveSelectedBuildable();
		_defaultWaterMaterial = WaterManager.ReturnMaterial();
		WaterManager.SetMaterial(_architectWaterMaterial);
		if (GameSpeedManager.GameSpeed != GameSpeed.Zero)
		{
			_restoreGameSpeed = true;
			GameSpeedManager.ToggleGameSpeedZero();
			GameEventDispatcher.AddListener(GameEventType.GameSpeedChange, OnSpeedChanged);
		}
		Overlays.OverlayType = Overlays.Type.Architect;
		GameEventDispatcher.AddListener(GameEventType.OverlayUpdate, OnOverlayUpdate);
		GameEventDispatcher.AddListener(GameEventType.BuildableMenuToggled, OnBuildMenuToggled);
		_changeLayout = true;
		_connectingEnegryGridInProgress = false;
		if (GameManager.WorldManager != null)
		{
			GameManager.WorldManager.ShowConstructionBorder(enabled: true);
		}
		if (UIManager.TryReturnInstance(out var instance))
		{
			UIManager.SetState(UIState.Architect);
			instance.CloseAllPanels();
			if (Community.PlayerCommunity.ReturnAgentWithAssigmentType(_achtitectAssignmentType, out var agentOut))
			{
				_architect = agentOut;
				instance.EnableDynamicPortrait(_architect);
			}
			else
			{
				UnityEngine.Debug.LogError("Activated Architect Mode without and Architect!");
			}
		}
		VisualBoundary.Display(display: true);
		_canBeDeactivated = true;
		GameManager.UIManager.DisplayPanel(PanelID.ArchitectBottomBar);
		UIManager.AddRewiredActionInfoToContext(this, base.Interact, base.Cancel);
	}

	private void OnSpeedChanged(GameEvent gameEvent)
	{
		if (!(gameEvent is GameSpeedChangedEvent { GameSpeed: GameSpeed.Zero }))
		{
			_restoreGameSpeed = false;
			GameManager.CursorManager.Deactivate(cancelled: true);
		}
	}

	private void OnBuildMenuToggled(GameEvent gameEvent)
	{
		GameManager.CursorManager.Deactivate();
	}

	private void OnOverlayUpdate(GameEvent gameEvent)
	{
		_changeLayout = false;
		GameManager.CursorManager.Deactivate(cancelled: true);
	}

	public override void DeactivateImmediately()
	{
		WaterManager.SetMaterial(_defaultWaterMaterial);
		StopFlashRed();
		if (GameManager.WorldManager != null)
		{
			GameManager.WorldManager.ShowConstructionBorder(enabled: false);
		}
		if (UIManager.TryReturnInstance(out var instance))
		{
			if (UIManager.State == UIState.Architect)
			{
				UIManager.SetState(UIState.Normal);
			}
			if ((bool)_architect)
			{
				instance.DisableDynamicPortrait(_architect);
			}
		}
		VisualBoundary.Display(display: false);
		_mouseOverBuildable = null;
		_mouseOverDecoration = null;
		RemoveSelectedBuildable(store: true);
		GameEventDispatcher.RemoveListener(GameEventType.GameSpeedChange, OnSpeedChanged);
		GameEventDispatcher.RemoveListener(GameEventType.OverlayUpdate, OnOverlayUpdate);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableMenuToggled, OnBuildMenuToggled);
		if (_changeLayout)
		{
			Overlays.OverlayType = Overlays.Type.None;
		}
		if (_restoreGameSpeed && GameSpeedManager.GameSpeed == GameSpeed.Zero)
		{
			GameSpeedManager.ToggleGameSpeedZero();
		}
		GameManager.UIManager.ClosePanel(PanelID.ArchitectBottomBar);
		UIManager.DisableRewiredActionInfoContext(this);
	}

	public void OnRevert()
	{
		GameManager.CursorManager.Deactivate(cancelled: true);
		_constructionPreview = null;
		_buildable = null;
		_decoration = null;
	}

	public override void UpdateCursor(CursorManager cursorManager)
	{
		if (_connectingEnegryGridInProgress)
		{
			if (_energyGridLinkCursorProperties.GetCancel())
			{
				DeactivateEnergyConnection();
			}
			else
			{
				_energyGridLinkCursorProperties.UpdateCursor(cursorManager);
			}
			return;
		}
		if (_constructionPreview != null)
		{
			if (WasCanceled())
			{
				RemoveSelectedBuildable(store: true);
			}
			else if (GetInteract())
			{
				MoveSelectedBuildable();
			}
			else
			{
				UpdateConstuctionPreview();
			}
			return;
		}
		if ((bool)cursorManager.SelectionLink)
		{
			if (!AcquireMouseOverEnergyPoleDecoration(cursorManager))
			{
				AcquireMouseOverBuildable(cursorManager);
			}
		}
		else
		{
			_mouseOverBuildable = null;
			_mouseOverDecoration = null;
			base.Cursor = _defaultCursor;
		}
		if ((_mouseOverBuildable != null || _mouseOverDecoration != null) && TryReturnInteraction(out var interaction))
		{
			StopFlashRed();
			if (_mouseOverBuildable != null)
			{
				UpdateBuildableCursor(cursorManager, interaction);
			}
			else
			{
				UpdateDecorationCursor(interaction);
			}
		}
	}

	private bool AcquireMouseOverBuildable(CursorManager cursorManager)
	{
		if (cursorManager.SelectionLink.TryGetComponentInParent<Buildable>(out var componentInParent))
		{
			if (componentInParent != _mouseOverBuildable)
			{
				_mouseOverBuildable = componentInParent;
			}
			_mouseOverDecoration = null;
			base.Cursor = (cursorManager.SelectionLink.gameObject.TryGetComponent<QuickConnecting>(out var _) ? _linkCursor : (componentInParent.IsDraggable() ? _selectCursor : _blockedCursor));
			return true;
		}
		_mouseOverBuildable = null;
		base.Cursor = _blockedCursor;
		return false;
	}

	private bool AcquireMouseOverEnergyPoleDecoration(CursorManager cursorManager)
	{
		QuickConnecting component;
		if (cursorManager.SelectionLink.TryGetComponentInParent<EnergyPoleDecorationBehaviour>(out var componentInParent))
		{
			if (componentInParent.Deco != _mouseOverDecoration)
			{
				_mouseOverDecoration = componentInParent.Deco;
			}
			_mouseOverBuildable = null;
			base.Cursor = ((!componentInParent.Deco.IsDraggable()) ? _blockedCursor : (cursorManager.SelectionLink.gameObject.TryGetComponent<QuickConnecting>(out component) ? _linkCursor : _selectCursor));
			return true;
		}
		if (cursorManager.SelectionLink.TryGetComponentInParent<DecorationSlots>(out var componentInParent2))
		{
			if (componentInParent2.Buildable != _mouseOverBuildable)
			{
				_mouseOverBuildable = componentInParent2.Buildable;
			}
			_mouseOverDecoration = null;
			base.Cursor = (cursorManager.SelectionLink.gameObject.TryGetComponent<QuickConnecting>(out component) ? _linkCursor : (componentInParent2.Buildable.IsDraggable() ? _selectCursor : _blockedCursor));
			return true;
		}
		_mouseOverDecoration = null;
		base.Cursor = _blockedCursor;
		return false;
	}

	private void UpdateBuildableCursor(CursorManager cursorManager, Interaction interaction)
	{
		if (base.Cursor == _linkCursor && _mouseOverBuildable.TryReturnBuildableExtendable<EnergyGridBuildableComponent>(out var buildableExtendable))
		{
			_energyGridLinkCursorProperties.Initialize(buildableExtendable);
			_energyGridLinkCursorProperties.InitializeCursorState();
			_energyGridLinkCursorProperties.Activate(this);
			_connectingEnegryGridInProgress = true;
			return;
		}
		base.Cursor = _defaultCursor;
		if (_mouseOverBuildable.IsDraggable())
		{
			SetSelectedBuildable(_mouseOverBuildable);
			if (interaction == Interaction.Store)
			{
				RemoveSelectedBuildable(store: true);
			}
			return;
		}
		ListPool<VisualPrefab>.List blockingConstructions = ListPool<VisualPrefab>.Get();
		WalkwayPonton buildableExtendable3;
		Hookable buildableExtendable4;
		if (_mouseOverBuildable.TryReturnBuildableExtendable<WalkwaySegment>(out var buildableExtendable2))
		{
			buildableExtendable2.ReturnBlockingNeighbours(ref blockingConstructions);
		}
		else if (_mouseOverBuildable.TryReturnBuildableExtendable<WalkwayPonton>(out buildableExtendable3))
		{
			buildableExtendable3.ReturnBlockingNeighbours(ref blockingConstructions);
		}
		else if (_mouseOverBuildable.TryReturnBuildableExtendable<Hookable>(out buildableExtendable4))
		{
			buildableExtendable4.ReturnBlockingNeighbours(ref blockingConstructions);
		}
		if (_mouseOverBuildable.TryReturnBuildableExtendable<DecorationSlots>(out var buildableExtendable5))
		{
			buildableExtendable5.GetBlockingNeighbours(ref blockingConstructions);
		}
		if (blockingConstructions.Count > 0)
		{
			_blockingCoroutine = CoroutineMotor.StartRoutine(FlashRed(cursorManager, blockingConstructions, _blinkRedDuration, _blinkRedTimes));
		}
		blockingConstructions.Dispose();
	}

	private void SetSelectedBuildable(Buildable selected)
	{
		RemoveSelectedBuildable();
		if (selected.TryReturnBuildableExtendable<EnergyGridPole>(out var _))
		{
			_buildablePreviewStrategy = _energyPolePreviewStrategy.Activate(selected, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
			return;
		}
		if (selected.TryReturnBuildableExtendable<WalkwaySegment>(out var _) || selected.TryReturnBuildableExtendable<WalkwayPonton>(out var _))
		{
			_buildablePreviewStrategy = _lineConstructionPreviewStrategy.Activate(selected, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
			return;
		}
		_buildablePreviewStrategy = _singleConstructionPreviewStrategy.Activate(selected, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
		UpdateCanBeDeactivated(canBeDeactivated: false);
	}

	private void UpdateDecorationCursor(Interaction interaction)
	{
		if (base.Cursor == _linkCursor && _mouseOverDecoration.TryGetExtendable<EnergyGridDecorationComponent>(out var extendable))
		{
			_energyGridLinkCursorProperties.Initialize(extendable);
			_energyGridLinkCursorProperties.InitializeCursorState();
			_energyGridLinkCursorProperties.Activate(this);
			_connectingEnegryGridInProgress = true;
			return;
		}
		base.Cursor = _defaultCursor;
		if (_mouseOverDecoration.IsDraggable())
		{
			SetSelectedDecoration(_mouseOverDecoration);
			if (interaction == Interaction.Store)
			{
				RemoveSelectedBuildable(store: true);
			}
		}
	}

	private void SetSelectedDecoration(Decoration selected)
	{
		RemoveSelectedBuildable();
		if (selected.TryGetExtendable<EnergyGridPole>(out var _))
		{
			_buildablePreviewStrategy = _energyPolePreviewStrategy.Activate(selected, selected.Properties, _visualIndex, _previewSettings, out _constructionPreview, out _decoration);
		}
	}

	public void SetSelectedPlaceableProperties(IPlaceable placeable)
	{
		if (placeable is BuildableProperties properties)
		{
			SetSelectedBuildableProperties(properties);
		}
		else if (placeable is DecorationProperties properties2)
		{
			SetSelectedDecorationProperties(properties2);
		}
	}

	public void SetSelectedBuildableProperties(BuildableProperties properties, bool continuous = false)
	{
		RemoveSelectedBuildable(store: true, toggleCategory: false);
		if (Community.PlayerCommunity.GetStoredBuildable(properties, out var buildable))
		{
			if (properties.PlacementCursorProperties is EnergyPoleCursorProperties)
			{
				_buildablePreviewStrategy = _energyPolePreviewStrategy.Activate(buildable, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
			}
			else if (properties.Prefab.GetComponent<WalkwayPonton>() != null)
			{
				_buildablePreviewStrategy = _lineConstructionPreviewStrategy.Activate(buildable, properties, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
			}
			else
			{
				_buildablePreviewStrategy = _singleConstructionPreviewStrategy.Activate(buildable, _visualIndex, _previewSettings, out _constructionPreview, out _buildable);
				UpdateCanBeDeactivated(canBeDeactivated: false);
			}
			if (continuous && RewiredActions.IsContinuousBuilding())
			{
				_buildablePreviewStrategy.ContinuousBuilding();
			}
		}
	}

	public void SetSelectedDecorationProperties(DecorationProperties properties, bool continuous = false)
	{
		RemoveSelectedBuildable(store: true, toggleCategory: false);
		if (!Community.PlayerCommunity.GetStoredDecoration(properties, out var decoration))
		{
			if (properties is EnergyPoleDecorationProperties)
			{
				SetSelectedBuildableProperties(GameManager.Settings.BuildableSettings.EnergyPoleBuildableProperties, continuous);
			}
			return;
		}
		_buildablePreviewStrategy = _energyPolePreviewStrategy.Activate(decoration, properties, _visualIndex, _previewSettings, out _constructionPreview, out _decoration);
		if (continuous && RewiredActions.IsContinuousBuilding())
		{
			_buildablePreviewStrategy.ContinuousBuilding();
		}
	}

	private void RemoveSelectedBuildable(bool store = false, bool toggleCategory = true)
	{
		BuildingGrid.Disable();
		if ((bool)_buildable)
		{
			if (store)
			{
				_buildablePreviewStrategy.StoreBuildable(_buildable, toggleCategory);
			}
			_buildable = null;
		}
		else if (_decoration != null)
		{
			if (store)
			{
				_buildablePreviewStrategy.StoreDecoration(_decoration, toggleCategory);
			}
			_decoration = null;
		}
		if (_constructionPreview != null)
		{
			RemoveConstructionPreview(ref _constructionPreview);
		}
		_buildablePreviewStrategy = null;
	}

	private void MoveSelectedBuildable()
	{
		if (!_constructionPreview.CanPlace)
		{
			return;
		}
		if (_buildable != null)
		{
			BuildableProperties properties = _buildable.Properties;
			if (_buildablePreviewStrategy.MoveBuildable(ref _buildable, _constructionPreview))
			{
				RemoveSelectedBuildable();
				UpdateCanBeDeactivated(Community.PlayerCommunity.ReturnStoredBuildablesCount(onlyBuildings: true) == 0);
				SetSelectedBuildableProperties(properties, continuous: true);
			}
		}
		else if (_decoration != null)
		{
			DecorationProperties properties2 = _decoration.Properties;
			if (_buildablePreviewStrategy.MoveDecoration(_decoration, _constructionPreview))
			{
				RemoveSelectedBuildable();
				UpdateCanBeDeactivated(Community.PlayerCommunity.ReturnStoredBuildablesCount(onlyBuildings: true) == 0);
				SetSelectedDecorationProperties(properties2, continuous: true);
			}
		}
	}

	private void UpdateConstuctionPreview()
	{
		_buildablePreviewStrategy.UpdateConstructionPreview(ref _constructionPreview);
	}

	public override bool TryToDeactivate(CursorManager cursor)
	{
		return false;
	}

	public override bool DisplayExitPanel()
	{
		return false;
	}

	private void UpdateCanBeDeactivated(bool canBeDeactivated)
	{
		_canBeDeactivated = canBeDeactivated;
		OnChangeCanBeDeactivated.Invoke();
	}

	public void UpdateCanBeDeactivated()
	{
		UpdateCanBeDeactivated(Community.PlayerCommunity.ReturnStoredBuildablesCount(onlyBuildings: true) == 0);
	}

	public void DeactivateEnergyConnection()
	{
		_energyGridLinkCursorProperties.DeactivateImmediately();
		base.Cursor = _defaultCursor;
		_connectingEnegryGridInProgress = false;
	}

	public IEnumerator FlashRed(CursorManager cursor, List<VisualPrefab> constructions, float duration, int blinks)
	{
		TooltipPanel.ShowTooltip(this, delayed: false);
		SelectionLink tooltipSelectionLink = cursor.SelectionLink;
		ListPool<MeshRenderer>.List list = ListPool<MeshRenderer>.Get();
		VisualPrefab spawnedVisual = Construction.Townheart.Buildable.SpawnedVisual;
		foreach (VisualPrefab construction in constructions)
		{
			if (construction == spawnedVisual)
			{
				continue;
			}
			construction.GetComponentsInChildren(list);
			foreach (MeshRenderer item2 in list)
			{
				Material[] materials = item2.materials;
				foreach (Material item in materials)
				{
					_blockingMaterials.Add(item);
				}
			}
		}
		list.Dispose();
		for (int j = 0; j < 2 * blinks; j++)
		{
			foreach (Material blockingMaterial in _blockingMaterials)
			{
				ToggleMaterialColor(blockingMaterial, (j % 2 == 0) ? Color.red : Color.white);
			}
			yield return new WaitForSecondsRealtime(duration / (float)blinks);
		}
		_blockingCoroutine = null;
		_blockingMaterials.Clear();
		while ((bool)tooltipSelectionLink && cursor.SelectionLink == tooltipSelectionLink)
		{
			yield return null;
		}
		TooltipPanel.HideTooltip();
	}

	private void StopFlashRed()
	{
		if (_blockingCoroutine != null)
		{
			CoroutineMotor.StopRoutine(_blockingCoroutine);
		}
		_blockingCoroutine = null;
		foreach (Material blockingMaterial in _blockingMaterials)
		{
			ToggleMaterialColor(blockingMaterial, Color.white);
		}
		_blockingMaterials.Clear();
		TooltipPanel.HideTooltip();
	}

	private void ToggleMaterialColor(Material material, Color color)
	{
		material.color = color;
		if (material.HasColor("_DiffuseXColor"))
		{
			material.SetColor("_DiffuseXColor", color);
		}
		if (material.HasColor("_DiffuseRColor"))
		{
			material.SetColor("_DiffuseRColor", color);
		}
		if (material.HasColor("_DiffuseGColor"))
		{
			material.SetColor("_DiffuseGColor", color);
		}
		if (material.HasColor("_DiffuseBColor"))
		{
			material.SetColor("_DiffuseBColor", color);
		}
		if (material.HasColor("_Color1"))
		{
			material.SetColor("_Color1", color);
		}
	}

	public string GetTooltip(TooltipBuilder tooltipBuilder)
	{
		return _blockingText;
	}

	public Color GetColor(TooltipBuilder tooltipBuilder)
	{
		return _blockingColor;
	}

	private bool TryReturnInteraction(out Interaction interaction)
	{
		if (GetInteract())
		{
			interaction = Interaction.Pickup;
		}
		else if (WasCanceled())
		{
			interaction = Interaction.Store;
		}
		else
		{
			interaction = Interaction.None;
		}
		return interaction != Interaction.None;
	}

	private bool WasCanceled()
	{
		if (GetCancelDown())
		{
			_cancelDownCameraPosition = Camera.main.transform.position;
		}
		else if (GetCancel())
		{
			return Mathf.Approximately(Vector3.Distance(_cancelDownCameraPosition, Camera.main.transform.position), 0f);
		}
		return false;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Move Buildable Energy Connection")]
public class MoveBuildableEnergyConnectionCursorProperties : EnergyGridConnectCursorProperties
{
