[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Boat Movement")]
public class BoatMovementCursorProperties : BuildableCursorProperties
{
	[SerializeField]
	private float _snappingDistance = 10f;

	private BoatPreview _boatPreview;

