	public override void Activate()
	{
		base.Activate();
		_boatPreview = CreateBoatPreview(_buildable, _visualIndex);
		_boat = _buildable.GetComponent<Boat>();
		if (_boat == null)
		{
			PajamaLlama.Debugs.Debugger.Error($"Passed a buildable to {base.name} that does not have a boat component.");
