[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Contexts/PointOfInterestCursorContext")]
public class PointOfInterestCursorContext : CursorContext
{
	[Serializable]
	public struct ItemTagSettings
	{
		public Item.Tags ItemTag;

		public Sprite Sprite;

		public CursorState CursorState;
	}

	[SerializeField]
	private float _range = 10f;

	[SerializeField]
	private MarkerAction[] _actions;

	[SerializeField]
	private InputFlags _interactableInputs = InputFlags.Joystick;

	[SerializeField]
	[NamedArrayElement(new string[] { "ItemTag" })]
	private ItemTagSettings[] _settings;

	[SerializeField]
	private RewiredAction _interactAction = new RewiredAction(93, null);

	private Sprite _crosshairSprite;

	public override bool Interactable => FlotsamInputManager.HasActiveInput(_interactableInputs);

	public override Sprite CrosshairIcon => _crosshairSprite;

	public override SelectionLink SelectionLink => null;

	public override ActionBase[] Actions => _actions;

	public override void EnableRadialMenu()
	{
		if (_interactAction.GetButtonDown())
		{
			if (FlotsamInputManager.HasActiveInput(InputFlags.Joystick))
			{
				EnableJoystickRadialMenu();
			}
			else if (FlotsamInputManager.HasActiveInput(InputFlags.MouseAndKeyboard))
			{
				EnableMouseAndKeybiardRadialMenu();
			}
		}
	}

	public override bool TryActivate(CursorManager cursorManager)
	{
		if (Interactable && WorldManager.TryReturnClosestFlotsamItemProperties(CursorManager.BuildingPosition, _range, out var itemProperties))
		{
			GetSettings(_settings, itemProperties, out _crosshairSprite, out var cursorState);
			CursorManager.SetCursorState(cursorState);
			UIManager.AddRewiredActionInfoToContext(this, _interactAction);
			return true;
		}
		Deactivate();
		return false;
	}

	public override void Deactivate()
	{
		UIManager.DisableRewiredActionInfoContext(this);
		_crosshairSprite = null;
	}

	private void EnableJoystickRadialMenu()
	{
		RadialMenu.Enable(this);
	}

	private void EnableMouseAndKeybiardRadialMenu()
	{
		throw new NotImplementedException();
	}

	private void GetSettings(ItemTagSettings[] settingsList, ItemProperties itemProperties, out Sprite sprite, out CursorState cursorState)
	{
		for (int i = 0; i < settingsList.Length; i++)
		{
			ItemTagSettings itemTagSettings = settingsList[i];
			if ((itemTagSettings.ItemTag & itemProperties.Tags) != Item.Tags.None)
			{
				sprite = itemTagSettings.Sprite;
				cursorState = itemTagSettings.CursorState;
				return;
			}
		}
		sprite = null;
		cursorState = CursorState.Normal;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Contexts/SelectionLinkCursorContext")]
public class SelectionLinkCursorContext : CursorContext
{
	[Serializable]
	public class ObjectTypeActions
	{
		public ObjectType ObjectType;

		public Sprite Sprite;

		public SelectionLinkActionBase[] Actions;

		public void SetContext(SelectionLink selectionLink)
		{
			if (!((IReadOnlyCollection<SelectionLinkActionBase>)(object)Actions).IsNullOrEmpty())
			{
				SelectionLinkActionBase[] actions = Actions;
				for (int i = 0; i < actions.Length; i++)
				{
					actions[i].SetContext(selectionLink);
				}
			}
		}
	}

	[SerializeField]
	[FormerlySerializedAs("_objectTypeActions")]
	[NamedArrayElement(new string[] { "ObjectType" })]
	private ObjectTypeActions[] _objectTypeSettings;

	[SerializeField]
	private RewiredAction _selectAction = new RewiredAction(93, null);

	[SerializeField]
	private RewiredAction _contextMenuAction = new RewiredAction(93, null);

	private SelectionLink _selectionLink;

	private ObjectTypeActions _actions;

	private SelectionLink _interactSelectionLink;

	public override SelectionLink SelectionLink => _selectionLink;

	public override ActionBase[] Actions => (_actions == null) ? null : _actions.Actions;

	public override Sprite CrosshairIcon
	{
		get
		{
			if (_actions != null)
			{
				return _actions.Sprite;
			}
			return null;
		}
	}

	public override bool TryActivate(CursorManager cursorManager)
	{
		if ((bool)cursorManager.SelectionLink)
		{
			if (_selectionLink != cursorManager.SelectionLink)
			{
				if ((bool)_selectionLink)
				{
					_selectionLink.UpdateCursor(hasHit: false);
				}
				_selectionLink = cursorManager.SelectionLink;
				_actions = ReturnObjectTypeSettings(_selectionLink);
				if (GameManager.UIManager.UIState == UIState.Architect)
				{
					_actions = null;
				}
				else
				{
					cursorManager.StartCoroutine(TooltipCoroutine(_selectionLink, cursorManager.Settings.TooltipDelay));
				}
				GameManager.HighlightManager.ResetOutlineHover();
				GameManager.HighlightManager.AddOutlineHover(_selectionLink);
			}
			if (((IReadOnlyCollection<ActionBase>)(object)Actions).IsNullOrEmpty())
			{
				UIManager.AddRewiredActionInfoToContext(this, _selectAction);
			}
			else
			{
				UIManager.AddRewiredActionInfoToContext(this, _selectAction, _contextMenuAction);
			}
			_selectionLink.UpdateCursor(hasHit: true);
			return true;
		}
		ClearSelectionLink();
		_interactSelectionLink = null;
		return false;
	}

	public override void Deactivate()
	{
		ClearSelectionLink();
	}

	public override void EnableRadialMenu()
	{
		if (!RadialMenu.IsEnabled)
		{
			if (_selectAction.GetButtonDown())
			{
				_interactSelectionLink = SelectionLink;
			}
			else if (FlotsamInputManager.GetButtonShortPress(93))
			{
				RadialMenu.Enable(this);
			}
			else if (_selectAction.GetButtonUp() && (bool)_interactSelectionLink && _interactSelectionLink == SelectionLink)
			{
				Selector.Select(SelectionLink);
			}
		}
	}

	private IEnumerator TooltipCoroutine(SelectionLink tooltipSelectionLink, float delay)
	{
		yield return new WaitForSecondsRealtime(delay);
		if ((bool)tooltipSelectionLink && _selectionLink == tooltipSelectionLink)
		{
			tooltipSelectionLink.ShowTooltip();
			while ((bool)tooltipSelectionLink && _selectionLink == tooltipSelectionLink)
			{
				yield return null;
			}
			TooltipPanel.HideTooltip();
		}
	}

	private void ClearSelectionLink()
	{
		if ((bool)_selectionLink)
		{
			_selectionLink.UpdateCursor(hasHit: false);
			_selectionLink = null;
			_actions = null;
			UIManager.DisableRewiredActionInfoContext(this);
			GameManager.HighlightManager.ResetOutlineHover();
		}
	}

	public ObjectTypeActions ReturnObjectTypeSettings(SelectionLink selectionLink)
	{
		ObjectTypeActions[] objectTypeSettings = _objectTypeSettings;
		foreach (ObjectTypeActions objectTypeActions in objectTypeSettings)
		{
			if (objectTypeActions.ObjectType == selectionLink.Type)
			{
				objectTypeActions.SetContext(selectionLink);
				return objectTypeActions;
			}
		}
		return null;
	}
}
public class CursorManager : SceneBehaviour
{
	public delegate void CursorEvent(CursorProperties cursorProperties, bool cancelled);

	[SerializeField]
	private CursorContext[] _contextsPrefabs;

	[SerializeField]
	private float _raycastDistance = 500f;

	private CursorState _cursorState;

	private bool _cursorStateLocked;

	private Selector _selector;

	private bool _hasCursorProperties;

	private CursorEvent OnCursorDeactivation;

	private CursorContext[] _contexts;

	private SelectionLinkCursorContext _selectionLinkContext;

	private bool _wasActiveThisFrame;

	public CursorSettings Settings { get; private set; }

	public CursorProperties Properties { get; private set; }

	public Vector3 Position { get; private set; }

	public Ray Ray { get; private set; }

	public float RaycastDistance => _raycastDistance;

	public static Vector3 BuildingPosition { get; private set; } = Vector3.zero;

	public CursorContext Context { get; private set; }

	public SelectionLink SelectionLink { get; private set; }

	public void Initialize()
	{
		Settings = GameManager.Settings.CursorSettings;
		_contexts = new CursorContext[_contextsPrefabs.Length];
		for (int i = 0; i < _contexts.Length; i++)
		{
			CursorContext cursorContext = UnityEngine.Object.Instantiate(_contextsPrefabs[i]);
			if (cursorContext is SelectionLinkCursorContext selectionLinkContext)
			{
				_selectionLinkContext = selectionLinkContext;
			}
			_contexts[i] = cursorContext;
		}
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputUpdated);
	}

	private void Start()
	{
		_selector = Selector.CreateInstance();
		OnActiveInputUpdated();
	}

	private void Update()
	{
		Position = FlotsamInputManager.MousePosition;
		Ray = CameraController.MainCamera.ScreenPointToRay(FlotsamInputManager.MousePosition);
		if (Physics.Raycast(Ray, out var hitInfo, RaycastDistance, Settings.BuildingPositionMask))
		{
			BuildingPosition = hitInfo.point.Vector3TopDown();
		}
		if (Physics.Raycast(Ray, out var hitInfo2, RaycastDistance, Settings.SelectionMask))
		{
			SelectionLink = hitInfo2.collider.GetComponentInChildren<SelectionLink>();
		}
		else
		{
			SelectionLink = null;
		}
		UpdateCursorContext();
		if ((bool)Context && Context.Interactable)
		{
			Context.EnableRadialMenu();
		}
		if (FlotsamInputManager.HasActiveInput(InputFlags.MouseAndKeyboard))
		{
			_selector.Update(Position, _selectionLinkContext.SelectionLink);
		}
		UpdateCursorProperties();
	}

	private void OnDrawGizmos()
	{
		if (_hasCursorProperties)
		{
			Properties.DrawGizmos();
		}
	}

	private void OnDestroy()
	{
		Selector.DestroyInstance();
	}

	public void Activate(CursorProperties properties, CursorEvent deactivatedEvent = null, bool checkProperties = false)
	{
		if (checkProperties && properties == Properties)
		{
			OnCursorDeactivation?.Invoke(Properties, cancelled: false);
			OnCursorDeactivation = null;
			if (deactivatedEvent != null)
			{
				OnCursorDeactivation = (CursorEvent)Delegate.Combine(OnCursorDeactivation, deactivatedEvent);
			}
			return;
		}
		if (_hasCursorProperties)
		{
			Deactivate(cancelled: true);
		}
		Properties = properties;
		Properties.InitializeCursorState();
		Properties.ActivateRewiredActions();
		Properties.Activate();
		SetCursorState(properties._defaultCursor);
		_cursorStateLocked = true;
		_hasCursorProperties = true;
		_wasActiveThisFrame = true;
		if (deactivatedEvent != null)
		{
			OnCursorDeactivation = (CursorEvent)Delegate.Combine(OnCursorDeactivation, deactivatedEvent);
		}
	}

	private void UpdateCursorContext()
	{
		bool flag = UIManager.HasFlagsSet(PanelContainerFlags.BlockCursorContext);
		Crosshair.SetBlocked(flag);
		if (_hasCursorProperties || EventSystem.current.IsPointerOverGameObject() || flag)
		{
			SetCursorContext(null);
			return;
		}
		CursorContext[] contexts = _contexts;
		foreach (CursorContext cursorContext in contexts)
		{
			if (cursorContext.TryActivate(this))
			{
				SetCursorContext(cursorContext);
				return;
			}
		}
		SetCursorContext(null);
	}

	private void SetCursorContext(CursorContext cursorContext)
	{
		if (!(Context == cursorContext))
		{
			if ((bool)Context)
			{
				Context.Deactivate();
			}
			Context = cursorContext;
			Crosshair.SetContext(cursorContext);
			if (Context == null)
			{
				SetCursorState(CursorState.Normal);
			}
		}
	}

	public void UpdateBuildPosition(Ray ray, float maxDistance)
	{
		if (Physics.Raycast(ray, out var hitInfo, maxDistance, Settings.BuildingPositionMask))
		{
			BuildingPosition = hitInfo.point.Vector3TopDown();
		}
	}

	private void UpdateCursorProperties()
	{
		if (_hasCursorProperties)
		{
			_wasActiveThisFrame = true;
			if (!Properties.TryToDeactivate(this))
			{
				Properties.UpdateCursor(this);
				if (!(Properties == null))
				{
					SetCursorState(Properties.Cursor, ignoreLock: true);
				}
			}
		}
		else
		{
			_wasActiveThisFrame = false;
		}
	}

	public void Deactivate(bool cancelled = false)
	{
		if (_hasCursorProperties)
		{
			_hasCursorProperties = false;
			Properties.DeactivateImmediately();
			OnCursorDeactivation?.Invoke(Properties, cancelled);
			OnCursorDeactivation = null;
			Properties = null;
			_cursorStateLocked = false;
			SetCursorState(CursorState.Normal);
		}
	}

	private void SetCursorState(CursorState cursorState, bool ignoreLock = false)
	{
		if (_cursorState != cursorState && (!_cursorStateLocked || ignoreLock))
		{
			_cursorState = cursorState;
			SetCursorVisual(cursorState);
		}
	}

	private void SetCursorVisual(CursorState cursorState)
	{
		Texture2D texture2D = Settings.ReturnCursorTexture(cursorState);
		if (texture2D == null)
		{
			UnityEngine.Debug.LogWarningFormat("No texture found for cursor state '{0}'!", cursorState);
		}
		Cursor.SetCursor(texture2D, Settings.CursorHotSpot, CursorMode.Auto);
		JoystickCursor.SetCursor(texture2D);
		Crosshair.SetCursorState(cursorState);
	}

	private void OnActiveInputUpdated(GameEvent gameEvent = null)
	{
		if (FlotsamInputManager.ActiveInput == InputFlags.Joystick)
		{
			Cursor.lockState = CursorLockMode.Locked;
			Cursor.visible = false;
			Crosshair.Enable();
		}
		else
		{
			Cursor.lockState = CursorLockMode.None;
			Cursor.visible = true;
			Crosshair.Disable();
		}
	}

	public bool TryDisplayExitPanel()
	{
		if ((bool)Properties && !Properties.CanBeDeactivated)
		{
			return Properties.DisplayExitPanel();
		}
		return false;
	}

	public static void RaycastBuildPosition(Ray ray, float maxDistance = float.MaxValue)
	{
		if (TryReturnInstance(out var instance))
		{
			instance.UpdateBuildPosition(ray, maxDistance);
		}
	}

	public static void SetCursorState(CursorState cursorState)
	{
		if (TryReturnInstance(out var instance))
		{
			instance.SetCursorState(cursorState, ignoreLock: false);
		}
	}

	public static void LockCursorState()
	{
		if (TryReturnInstance(out var instance))
		{
			instance._cursorStateLocked = true;
		}
	}

	public static void UnlockCursorState()
	{
		if (TryReturnInstance(out var instance))
		{
			instance._cursorStateLocked = false;
		}
	}

	public static bool WasActiveThisFrame()
	{
		if (TryReturnInstance(out var instance))
		{
			return instance._wasActiveThisFrame;
		}
		return false;
	}

	private static bool TryReturnInstance(out CursorManager instance)
	{
		instance = GameManager.CursorManager;
		return instance != null;
	}
}
public abstract class CursorProperties : PersistentProperties
{
	private const int MAXIMUM_BUTTON_COUNT = 5;

	[SerializeField]
	[Tooltip("The type of the cursor.")]
	[FormerlySerializedAs("Cursor")]
	public CursorState _defaultCursor = CursorState.Salvage;

	[SerializeField]
	private RewiredAction _interact = new RewiredAction(93, "UI_Interact");

	[SerializeField]
	private RewiredAction _cancel = new RewiredAction(102, "UI_Cancel");

	[SerializeField]
	private bool _dialogBlocksInteraction;

	public UnityEvent OnChangeCanBeDeactivated;

	[NonSerialized]
	private float[] clickTimes;

	[NonSerialized]
	protected bool _canBeDeactivated = true;

	public override Types Type => Types.CursorProperties;

	public CursorState Cursor { get; protected set; }

	public bool CanBeDeactivated => _canBeDeactivated;

	public RewiredAction Interact => _interact;

	public RewiredAction Cancel => _cancel;

	public virtual void ActivateRewiredActions()
	{
		_interact.ActivateWait();
		_cancel.ActivateWait();
	}

	public abstract void Activate();

	public abstract void UpdateCursor(CursorManager cursor);

	public abstract void DeactivateImmediately();

	public virtual bool TryToDeactivate(CursorManager cursor)
	{
		if (GetCancel())
		{
			cursor.Deactivate(cancelled: true);
			return true;
		}
		return false;
	}

	public virtual bool DisplayExitPanel()
	{
		return false;
	}

	public void InitializeCursorState()
	{
		Cursor = _defaultCursor;
	}

	public bool GetInteract()
	{
		if (!EventSystem.current.IsPointerOverGameObject() && _interact.GetButtonUp())
		{
			return IsBlockedByDialog();
		}
		return false;
	}

	public bool GetCancelDown()
	{
		if (_cancel.GetButtonDown())
		{
			return IsBlockedByDialog();
		}
		return false;
	}

	public bool GetCancel()
	{
		if (_cancel.GetButtonUp())
		{
			return IsBlockedByDialog();
		}
		return false;
	}

	private bool IsBlockedByDialog()
	{
		if (_dialogBlocksInteraction)
		{
			return PopUpDialog.Instance.CanPopup;
		}
		return true;
	}

	public virtual void DrawGizmos()
	{
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Decoration")]
public class DecorationCursorProperties : CursorProperties
{
	[SerializeField]
	private VisualPrefabPreviewSettings _previewSettings;

	[SerializeField]
	private float _snapRange = 5f;

	[Tooltip("Layer mask used to get the building position that is under the cursor")]
	[SerializeField]
	private LayerMask _raycastMask;

	[SerializeField]
	private Color _selectedSlotColor = Color.red;

	[Header("Rotation")]
	[SerializeField]
	private RewiredAction _rotateRewiredAction;

	[SerializeField]
	private RewiredAction _variationRewiredAction;

	private DecorationProperties _decorationProperties;

	private int _visual;

	private Quaternion _rotation;

	private VisualPrefab _preview;

	private Dictionary<VisualPrefab, VisualPrefab> _previewPool;

	private DecorationProperties.Turns _turn;

	private List<int> _slotIndices;

	private DecorationSlots _decorationSlots;

	private List<int> _decorationSlotIndices;

	private Quaternion _decorationSlotsRotation = Quaternion.identity;

	public void Initialize(DecorationProperties decorationProperties)
	{
		_decorationProperties = decorationProperties;
		_visual = 0;
		_rotation = Quaternion.identity;
		_turn = DecorationProperties.Turns.Full;
		if (_previewPool == null)
		{
			_previewPool = new Dictionary<VisualPrefab, VisualPrefab>(32);
		}
		if (_slotIndices == null)
		{
			_slotIndices = new List<int>();
		}
		if (_decorationSlotIndices == null)
		{
			_decorationSlotIndices = new List<int>();
		}
	}

	public override void Activate()
	{
		_preview = ReturnPreview(_decorationProperties.VisualPrefabs[_visual]);
		UIManager.AddRewiredActionInfoToContext(this, _rotateRewiredAction, _variationRewiredAction, base.Interact, base.Cancel);
	}

	public override void DeactivateImmediately()
	{
		foreach (DecorationSlots decorationSlot in Community.PlayerCommunity.DecorationSlots)
		{
			decorationSlot.DisablePlacementMode();
		}
		_preview.gameObject.SetActive(value: false);
		UIManager.DisableRewiredActionInfoContext(this);
	}

	public override void UpdateCursor(CursorManager cursor)
	{
		bool flag = false;
		if (_variationRewiredAction.GetButtonUp())
		{
			_visual = PajamaLlama.Math.Math.IncrementIndexWrapped(_visual, _decorationProperties.VisualPrefabs.Length);
			if ((bool)_preview)
			{
				_preview.gameObject.SetActive(value: false);
			}
			_preview = ReturnPreview(_decorationProperties.VisualPrefabs[_visual]);
			AudioManager.PlayOneShot(_decorationProperties.FMODEventReference_Variation);
		}
		if (_rotateRewiredAction.GetButtonUp())
		{
			UpdateRotation();
		}
		RaycastHit hitInfo;
		Vector3 position = ((!Physics.Raycast(CameraController.MainCamera.ScreenPointToRay(FlotsamInputManager.MousePosition), out hitInfo, 500f, _raycastMask)) ? CursorManager.BuildingPosition : hitInfo.point);
		if ((bool)_decorationSlots)
		{
			_decorationSlots.TryEnablePlacementMode(_decorationProperties);
		}
		if ((bool)_decorationSlots)
		{
			_decorationSlots.ResetSlotsOutlineColor();
		}
		if (TryReturnClosestAvailableSlots(out _decorationSlots, _decorationSlotIndices, position, out var decorationPosition, _snapRange))
		{
			_decorationSlotsRotation = _decorationSlots.transform.rotation;
			_preview.transform.position = decorationPosition;
			_decorationSlots.SetSlotsOutlineColor(_decorationSlotIndices, _selectedSlotColor);
			flag = true;
		}
		else
		{
			_preview.transform.position = CursorManager.BuildingPosition;
		}
		_preview.transform.rotation = _decorationSlotsRotation * _rotation;
		if (flag && _decorationProperties.ReturnCanBePlaced(Community.PlayerCommunity))
		{
			_previewSettings.SetValid(_preview, isValid: true);
			if (!EventSystem.current.IsPointerOverGameObject() && GetInteract() && BuildingDevTools.TryAutoSpawnResources(_decorationProperties.RequiredResources))
			{
				_decorationSlots.AddDecoration(_decorationProperties, _turn, _visual, _decorationSlotIndices);
			}
		}
		else
		{
			_previewSettings.SetValid(_preview, isValid: false);
		}
	}

	private void UpdateRotation()
	{
		switch (_turn)
		{
		case DecorationProperties.Turns.Full:
			_turn = DecorationProperties.Turns.Quarter;
			_rotation = DecorationProperties.ROTATION_QUARTER;
			break;
		case DecorationProperties.Turns.Quarter:
			_turn = DecorationProperties.Turns.Half;
			_rotation = DecorationProperties.ROTATION_HALF;
			break;
		case DecorationProperties.Turns.Half:
			_turn = DecorationProperties.Turns.ThreeQuarter;
			_rotation = DecorationProperties.ROTATION_THREE_QUARTER;
			break;
		case DecorationProperties.Turns.ThreeQuarter:
			_turn = DecorationProperties.Turns.Full;
			_rotation = DecorationProperties.ROTATION_FULL;
			break;
		}
		AudioManager.PlayOneShot(_decorationProperties.FMODEventReference_Rotate);
	}

	private bool TryReturnClosestAvailableSlots(out DecorationSlots closestSlots, List<int> indices, Vector3 position, out Vector3 decorationPosition, float range)
	{
		float num = range * range;
		closestSlots = null;
		decorationPosition = default(Vector3);
		foreach (DecorationSlots decorationSlot in Community.PlayerCommunity.DecorationSlots)
		{
			if (!decorationSlot.TryEnablePlacementMode(_decorationProperties) || !decorationSlot.TryPopulateClosestSlotIndices(_slotIndices, position, out var closesetPosition, _decorationProperties, _turn))
			{
				continue;
			}
			float num2 = position.DistanceToSquared(closesetPosition);
			if (!(num2 < num))
			{
				continue;
			}
			num = num2;
			closestSlots = decorationSlot;
			decorationPosition = closesetPosition;
			indices.Clear();
			foreach (int slotIndex in _slotIndices)
			{
				indices.Add(slotIndex);
			}
		}
		return closestSlots != null;
	}

	private VisualPrefab ReturnPreview(VisualPrefab prefab)
	{
		bool flag = false;
		if (_previewPool.TryGetValue(prefab, out var value))
		{
			if ((bool)value)
			{
				value.gameObject.SetActive(value: true);
				return value;
			}
			flag = true;
		}
		value = _previewSettings.InstantiatePreview(prefab);
		value.name = "[PREVIEW] " + value.name;
		if (flag)
		{
			_previewPool[prefab] = value;
		}
		else
		{
			_previewPool.Add(prefab, value);
		}
		return value;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Cursor Properties/Energy Connection")]
public class EnergyGridConnectCursorProperties : CursorProperties
{
	[SerializeField]
	private int _lowestPoint = 10;

	[Tooltip("Make sure both numbers are uneven so that the middle point is in the actual middle")]
	[SerializeField]
	[MinMaxRangeInt(1, 51)]
	private RangedInt _segmentSize = new RangedInt(11, 21);

	[SerializeField]
	private LineRenderer _lineRendererPrefab;

	[SerializeField]
	private Color _outOfRangeColor = Color.white;

	[SerializeField]
	private Color _inRangeColor = Color.white;

	[Header("FMOD Events")]
	[SerializeField]
	private EventReference _connectEvent;

	[NonSerialized]
	protected EnergyGridConnector _component;

	[NonSerialized]
	private uint _componentConnectIndex;

	[NonSerialized]
	private LineRenderer _lineRenderer;

	[NonSerialized]
	protected List<EnergyGridConnector> _componentsInRadius;

	[NonSerialized]
	private EnergyGridConnector _selectedComponent;

	[NonSerialized]
	private Camera _camera;

	[NonSerialized]
	private bool _connectWithIndex;

	public void Initialize(EnergyGridConnector component, uint index)
	{
		Initialize(component);
		_connectWithIndex = true;
		_componentConnectIndex = index;
	}

	public void Initialize(EnergyGridConnector component)
	{
		_component = component;
		_camera = CameraController.Instance.Camera;
		_componentsInRadius = new List<EnergyGridConnector>();
		if (_lineRenderer == null)
		{
			_lineRenderer = UnityEngine.Object.Instantiate(_lineRendererPrefab);
		}
		GameEventDispatcher.AddListener(GameEventType.EnergyGridsUpdated, OnEnergyGridsUpdated);
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridsUpdated, OnEnergyGridsUpdated);
	}

	public override void Activate()
	{
		if (!_lineRenderer.enabled)
		{
			UpdateLineRenderer(out var _);
			_lineRenderer.enabled = true;
		}
		DisableHighlights();
		UpdateComponentsInRange();
		HighlightComponentsInRange();
	}

	public override void UpdateCursor(CursorManager cursor)
	{
		UpdateLineRenderer(out var cableEndPos);
		if (IsHoverValid() && _component.IsInRange(cableEndPos))
		{
			_lineRenderer.material.SetColor("_BaseColor", _inRangeColor);
			if (GetInteract())
			{
				Connect(_selectedComponent, cursor);
			}
		}
		else
		{
			_lineRenderer.material.SetColor("_BaseColor", _outOfRangeColor);
		}
	}

	public override void DeactivateImmediately()
	{
		if (_lineRenderer != null)
		{
			_lineRenderer.enabled = false;
		}
		DisableHighlights();
		GameEventDispatcher.RemoveListener(GameEventType.EnergyGridsUpdated, OnEnergyGridsUpdated);
	}

	protected virtual void Connect(EnergyGridConnector other, CursorManager cursor)
	{
		if (!(other == null) && !(other == _component) && _componentsInRadius.Contains(other) && _component.CanConnect() && other.CanConnect() && !_component.IsConnected(other))
		{
			if (_connectWithIndex)
			{
				EnergyGrid.ConnectWithIndex(_component, _componentConnectIndex, other);
			}
			else
			{
				EnergyGrid.Connect(_component, other);
			}
			AudioManager.PlayOneShot(_connectEvent);
			DisableHighlights();
			if (other.CanConnect())
			{
				_component = other;
				Activate();
			}
			else
			{
				cursor.Deactivate();
			}
		}
	}

	private void OnEnergyGridsUpdated(GameEvent gameEvent)
	{
		DisableHighlights();
		UpdateComponentsInRange();
		HighlightComponentsInRange();
	}

	protected void DisableHighlights()
	{
		_component.OutlineRenderer.ResetHighlightOutline();
		foreach (EnergyGridConnector item in _componentsInRadius)
		{
			item.OutlineRenderer.ResetHighlightOutline();
		}
	}

	private void HighlightComponentsInRange()
	{
		foreach (EnergyGridConnector item in _componentsInRadius)
		{
			GameManager.HighlightManager.HighlightObject(item.OutlineRenderer);
		}
	}

	private void UpdateLineRenderer(out Vector3 cableEndPos)
	{
		Vector3 position = _component.ConnectionTransform.position;
		Vector3 mousePosition = FlotsamInputManager.MousePosition;
		float z = Vector3.Distance(_camera.transform.position, position);
		mousePosition.z = z;
		Vector3 targetPos = _camera.ScreenToWorldPoint(mousePosition);
		Vector3 endPos = ReturnTargetPosition(targetPos);
		UpdateLineSegments(position, endPos, out cableEndPos);
	}

	private void UpdateLineSegments(Vector3 startPos, Vector3 endPos, out Vector3 cableEndPos)
	{
		Vector3 vector = endPos - startPos;
		float f = startPos.y - Mathf.Max(0f, endPos.y);
		float cableLinkRange = GameManager.Settings.BuildableSettings.CableLinkRange;
		float num = Mathf.Min((endPos.Leveled() - startPos.Leveled()).magnitude, cableLinkRange);
		if (num >= cableLinkRange)
		{
			float num2 = Mathf.Sqrt(Mathf.Pow(f, 2f) + Mathf.Pow(cableLinkRange, 2f));
			vector = vector.normalized * num2;
		}
		cableEndPos = startPos + vector;
		float t = num / cableLinkRange;
		float num3 = Mathf.Lerp(_lowestPoint, 0f, t);
		Vector3 middlePoint = (startPos + cableEndPos) / 2f + Vector3.down * num3;
		int num4 = Mathf.Clamp(Mathf.RoundToInt(cableLinkRange - vector.magnitude), _segmentSize.Minimum, _segmentSize.Maximum);
		if (num4 % 2 == 0)
		{
			num4++;
		}
		_lineRenderer.positionCount = num4;
		Vector3[] array = new Vector3[num4];
		for (int i = 0; i < num4; i++)
		{
			float t2 = (float)i / (float)num4;
			array[i] = Bezier.CalculateQuadraticBezierPoint(t2, startPos, middlePoint, cableEndPos);
		}
		array[num4 - 1] = Bezier.CalculateQuadraticBezierPoint(1f, startPos, middlePoint, cableEndPos);
		_lineRenderer.SetPositions(array);
	}

	private void UpdateComponentsInRange()
	{
		_componentsInRadius.Clear();
		float cableLinkRange = GameManager.Settings.BuildableSettings.CableLinkRange;
		foreach (EnergyGrid grid in EnergyGridManager.Grids)
		{
			foreach (EnergyGridConnector link in grid.Links)
			{
				if (!(link == null) && !(link == _component) && Vector3.Distance(_component.ConnectionTransform.position.Leveled(), link.ConnectionTransform.position.Leveled()) < cableLinkRange && link.CanConnect() && !link.IsConnected(_component))
				{
					_componentsInRadius.Add(link);
				}
			}
		}
	}

	private Vector3 ReturnTargetPosition(Vector3 targetPos)
	{
		if (Physics.Raycast(_camera.ScreenPointToRay(FlotsamInputManager.MousePosition), out var hitInfo))
		{
			EnergyGridConnector componentInParent = hitInfo.transform.GetComponentInParent<EnergyGridConnector>();
			if (componentInParent != null && _componentsInRadius.Contains(componentInParent))
			{
				_selectedComponent = componentInParent;
				return componentInParent.ConnectionTransform.position;
			}
		}
		return targetPos;
	}

	private bool IsHoverValid()
	{
		if (Physics.Raycast(_camera.ScreenPointToRay(FlotsamInputManager.MousePosition), out var hitInfo))
		{
			EnergyGridConnector componentInParent = hitInfo.transform.GetComponentInParent<EnergyGridConnector>();
			if (componentInParent != null && _componentsInRadius.Contains(componentInParent))
			{
				_selectedComponent = componentInParent;
				return true;
			}
		}
		return false;
	}
}
