public class RewiredActions
{
	private static Rewired.Player _player;

	public static Vector2 ReturnWorldCameraMovementInput()
	{
		if (HasNoValidPlayer())
		{
			return default(Vector2);
		}
		return new Vector2(0f - _player.GetAxisRaw(31) + _player.GetAxisRaw(32), 0f - _player.GetAxisRaw(1) + _player.GetAxisRaw(0));
	}

	public static Vector2 ReturnMapCameraMovementInput()
	{
		if (HasNoValidPlayer())
		{
			return default(Vector2);
		}
		return new Vector2(0f - _player.GetAxisRaw(81) + _player.GetAxisRaw(82), 0f - _player.GetAxisRaw(80) + _player.GetAxisRaw(79));
	}

	public static float ReturnCameraRotation()
	{
		if (HasNoValidPlayer())
		{
			return 0f;
		}
		return ApplyDeadzone(_player.GetAxisRaw(2) - _player.GetAxisRaw(33), 0.3f);
	}

	public static float ReturnCameraZoom()
	{
		if (HasNoValidPlayer())
		{
			return 0f;
		}
		return ApplyDeadzone(_player.GetAxisRaw(89), 0.5f);
	}

	public static Vector2 ReturnTownheartMovementInput()
	{
		if (HasNoValidPlayer())
		{
			return default(Vector2);
		}
		return new Vector2(0f - _player.GetAxisRaw(71) + _player.GetAxisRaw(72), 0f - _player.GetAxisRaw(70) + _player.GetAxisRaw(69));
	}

	public static bool ReturnToggleMapInput()
	{
		if (!HasNoValidPlayer())
		{
			return _player.GetButtonDown(83);
		}
		return false;
	}

	public static bool ReturnHasTownheartInput()
	{
		if (!_player.GetButton(69))
		{
			return _player.GetButton(70);
		}
		return true;
	}

	public static bool IsContinuousBuilding()
	{
		return _player.GetButton(75);
	}

	private static float ApplyDeadzone(float value, float deadzone)
	{
		deadzone = Mathf.Clamp01(deadzone);
		if (deadzone < 1f)
		{
			float num = 1f - deadzone;
			if (value > deadzone)
			{
				return Mathf.Clamp01(value - deadzone) / num;
			}
			if (value < 0f - deadzone)
			{
				return Mathf.Clamp(value + deadzone, -1f, 0f) / num;
			}
		}
		return 0f;
	}

	private static bool HasNoValidPlayer()
	{
		if (_player == null)
		{
			_player = FlotsamInputManager.RewiredPlayer;
			if (_player == null)
			{
				return true;
			}
		}
		return false;
	}
}
public class Selector
{
	private static Selector _instance;

	private readonly UIManager _uiManager;

	private Vector3 _anchor;

	private Vector3 _cursor;

	private SelectionLink _cursorSelectionLink;

	public SelectionLink SelectedObject { get; private set; }

	public ObjectType SelectedObjectType { get; private set; }

	public static SelectionLink Selection
	{
		get
		{
			if (_instance != null)
			{
				return _instance.SelectedObject;
			}
			return null;
		}
	}

	public static ObjectType SelectedType
	{
		get
		{
			if (_instance != null)
			{
				return _instance.SelectedObjectType;
			}
			return ObjectType.None;
		}
	}

	public static event UnityAction SelectedObjectsUpdatedEvent;

	private Selector()
	{
		_uiManager = GameManager.UIManager;
	}

	public void Update(Vector3 cursor, SelectionLink cursorSelectionLink)
	{
		_cursor = cursor;
		_cursorSelectionLink = cursorSelectionLink;
		if (FlotsamInputManager.GetButtonDown(93) && _uiManager.UIState == UIState.Normal && !EventSystem.current.IsPointerOverGameObject())
		{
			_anchor = FlotsamInputManager.MousePosition;
			_uiManager.SelectionFrame.InitializeFrame(_anchor);
			UIManager.SetState(UIState.Selecting);
		}
		if (_uiManager.UIState != UIState.Selecting)
		{
			return;
		}
		if (FlotsamInputManager.GetButton(93))
		{
			_cursor = FlotsamInputManager.MousePosition;
			_uiManager.SelectionFrame.DrawSelectionFrame(_cursor);
		}
		if (!FlotsamInputManager.GetButtonDown(43) && !FlotsamInputManager.GetButtonUp(93))
		{
			return;
		}
		_uiManager.SelectionFrame.HideFrame();
		UIManager.SetState(UIState.Normal);
		if (TryToSelectObjectInFrame())
		{
			if (Selector.SelectedObjectsUpdatedEvent != null)
			{
				Selector.SelectedObjectsUpdatedEvent();
			}
		}
		else if (TryToSelectSingleObjectFromRaycast())
		{
			if (Selector.SelectedObjectsUpdatedEvent != null)
			{
				Selector.SelectedObjectsUpdatedEvent();
			}
		}
		else
		{
			DeselectAll();
		}
	}

	public void Destroy()
	{
		Selector.SelectedObjectsUpdatedEvent = null;
	}

	private bool TryToSelectObjectInFrame()
	{
		if (TryToSelectDriftersInFrame())
		{
			return true;
		}
		if (TryToSelectCommunityMembersInFrame())
		{
			return true;
		}
		if (TryToSelectBirdsInFrame())
		{
			return true;
		}
		if (TryToSelectMarkerInFrame())
		{
			return true;
		}
		if (TryToSelectBuildablesInFrame())
		{
			return true;
		}
		if (TryToSelectLandmarkInFrame())
		{
			return true;
		}
		return false;
	}

	private bool TryToSelectObjectInFrame(ObjectType objectType)
	{
		SelectionLink selectionLink = ReturnFirstSelectionLinkInFrame(_anchor, _cursor, objectType);
		if (selectionLink == null)
		{
			return false;
		}
		if (SelectedObject == selectionLink)
		{
			return true;
		}
		if (selectionLink.Type == ObjectType.None)
		{
			return false;
		}
		SelectObject(selectionLink, objectType);
		return true;
	}

	private bool TryToSelectCommunityMembersInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.CommunityMember);
	}

	private bool TryToSelectBuildablesInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.Buildable);
	}

	private bool TryToSelectMarkerInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.Marker);
	}

	private bool TryToSelectLandmarkInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.Landmark);
	}

	private bool TryToSelectDriftersInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.Agent);
	}

	private bool TryToSelectBirdsInFrame()
	{
		return TryToSelectObjectInFrame(ObjectType.Bird);
	}

	public void SelectObject(SelectionLink selectionLink)
	{
		SelectObject(selectionLink, selectionLink.Type);
	}

	public void SelectObject(SelectionLink selectionLink, ObjectType selectedType, bool playSelectionSound = true)
	{
		if (!(selectionLink == null) && !(selectionLink == SelectedObject) && selectedType != ObjectType.None)
		{
			DeselectObject(SelectedObject);
			SelectedObject = selectionLink;
			SelectedObjectType = selectedType;
			selectionLink.Select(playSelectionSound);
			GameManager.HighlightManager.HighlightObject(selectionLink.OutlineRenderer);
			if (Selector.SelectedObjectsUpdatedEvent != null)
			{
				Selector.SelectedObjectsUpdatedEvent();
			}
		}
	}

	public void DeselectObject(SelectionLink objectToDeselect)
	{
		if (!(objectToDeselect == null) && SelectedObject == objectToDeselect)
		{
			SelectedObject = null;
			SelectedObjectType = ObjectType.None;
			objectToDeselect.Deselect();
			if (Selector.SelectedObjectsUpdatedEvent != null)
			{
				Selector.SelectedObjectsUpdatedEvent();
			}
		}
	}

	public void DeselectSelection()
	{
		DeselectObject(SelectedObject);
		if (Selector.SelectedObjectsUpdatedEvent != null)
		{
			Selector.SelectedObjectsUpdatedEvent();
		}
	}

	private bool TryToSelectSingleObjectFromRaycast()
	{
		if (_cursorSelectionLink == null)
		{
			return false;
		}
		if (_cursorSelectionLink.Type == ObjectType.None)
		{
			return false;
		}
		SelectedObjectType = _cursorSelectionLink.Type;
		SelectObject(_cursorSelectionLink, _cursorSelectionLink.Type);
		return true;
	}

	public static Selector CreateInstance()
	{
		if (_instance == null)
		{
			_instance = new Selector();
		}
		else
		{
			UnityEngine.Debug.LogWarning("An instance of Selector has already been instantiated! Did you forget to call Selector.DestroyInstance()?");
		}
		return _instance;
	}

	public static void DestroyInstance()
	{
		if (_instance != null)
		{
			_instance.Destroy();
			_instance = null;
		}
	}

	public static void Select(SelectionLink selectionLink)
	{
		_instance?.SelectObject(selectionLink, selectionLink.Type);
	}

	public static void Select(GameObject objectToSelect, ObjectType objectType, bool playSelectionSound = true)
	{
		if (_instance != null && objectType != ObjectType.None)
		{
			_instance.SelectObject(objectToSelect.GetComponentInChildren<SelectionLink>(), objectType, playSelectionSound);
		}
	}

	public static void Deselect(SelectionLink selectionLink)
	{
		if (_instance != null)
		{
			_instance.DeselectObject(selectionLink);
		}
	}

	public static void Deselect(GameObject gameObject)
	{
		if (_instance != null && !(gameObject == null))
		{
			_instance.DeselectObject(gameObject.GetComponentInChildren<SelectionLink>());
		}
	}

	public static void Deselect(SelectionLink[] selectionLinks)
	{
		if (_instance != null && !((IReadOnlyCollection<SelectionLink>)(object)selectionLinks).IsNullOrEmpty())
		{
			foreach (SelectionLink objectToDeselect in selectionLinks)
			{
				_instance.DeselectObject(objectToDeselect);
			}
		}
	}

	public static void DeselectAll()
	{
		if (_instance != null)
		{
			_instance.DeselectSelection();
		}
	}

	private SelectionLink ReturnFirstSelectionLinkInFrame(Vector3 startPos, Vector3 endPos, ObjectType objectType)
	{
		Camera main = Camera.main;
		Vector3 vector = new Vector3(Mathf.Min(startPos.x, endPos.x), Mathf.Min(startPos.y, endPos.y), Mathf.Min(startPos.z, endPos.z));
		Vector3 vector2 = new Vector3(Mathf.Max(startPos.x, endPos.x), Mathf.Max(startPos.y, endPos.y), Mathf.Max(startPos.z, endPos.z));
		List<SelectionLink> selectionLinks = SelectionLink.SelectionLinks;
		int count = selectionLinks.Count;
		for (int i = 0; i < count; i++)
		{
			SelectionLink selectionLink = selectionLinks[i];
			if (selectionLink.Type == objectType && selectionLink.IsSelectable)
			{
				Vector3 vector3 = main.WorldToScreenPoint(selectionLink.transform.position);
				if (vector3.z > 0f && vector3.x > vector.x && vector3.x < vector2.x && vector3.y > vector.y && vector3.y < vector2.y)
				{
					return selectionLink;
				}
			}
		}
		return null;
	}

	public static bool ReturnIsSelected(GameObject gameObject)
	{
		if (_instance == null)
		{
			return false;
		}
		SelectionLink componentInChildren = gameObject.GetComponentInChildren<SelectionLink>();
		if (componentInChildren == null)
		{
			return false;
		}
		return _instance.SelectedObject == componentInChildren;
	}

	public static T ReturnSelectedObjectComponent<T>(ObjectType objectType) where T : UnityEngine.Component
	{
		if (_instance == null || _instance.SelectedObject == null)
		{
			return null;
		}
		if (_instance.SelectedObjectType != objectType && objectType != ObjectType.None)
		{
			return null;
		}
		if (_instance.SelectedObject.ObjectToSelect.TryGetComponent<T>(out var component))
		{
			return component;
		}
		return null;
	}
}
public class CommunityInventory : ICommunalInventory, IInventorySpaceLimiter
{
	private bool _hasUpdates;

	private readonly List<Storage> _storages = new List<Storage>();

	private readonly List<ResourceProvider> _resourceProviders = new List<ResourceProvider>();

	private readonly SortedDictionary<int, List<ResourceProvider>> _prioritizedResourceProviders = new SortedDictionary<int, List<ResourceProvider>>();

	private int _storageCount;

	private int _resourceProviderCount;

	private readonly SortInventoriesByDistance _distanceSorter = new SortInventoriesByDistance();

	private int _updateIndex;

	private ItemData[] _itemData;

	public UnityEvent InventoryUpdatedEvent { get; } = new UnityEvent();

	public CommunityInventory()
	{
		InitializeItemData();
	}

	public void LateUpdate()
	{
		if (_hasUpdates)
		{
			if (InventoryUpdatedEvent != null)
			{
				InventoryUpdatedEvent.Invoke();
			}
			GameEventDispatcher.Dispatch(GameEventType.CommunityInventoryUpdated);
			_hasUpdates = false;
		}
		if (_updateIndex < _resourceProviderCount)
		{
			_resourceProviders[_updateIndex++].Update();
		}
		else
		{
			_updateIndex = 0;
		}
	}

	private void InitializeItemData()
	{
		using ListPool<ItemProperties>.List list = ListPool<ItemProperties>.Get(192);
		_itemData = new ItemData[192];
		GameManager.PersistenceManager.PopulateReferences(PersistentProperties.Types.ItemProperties, list);
		foreach (ItemProperties item in list)
		{
			if (_itemData[item.Id] == null)
			{
				_itemData[item.Id] = new ItemData(item);
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception($"'{_itemData[item.Id].ItemProperties}' and '{item}' have the same ID! PersistentProperties is up-to-date and the ItemProperties.Ids are validated."));
			}
		}
	}

	public void AddItemProvider(ItemDataItemProvider itemProvider)
	{
		if (itemProvider != null)
		{
			ItemData[] itemData = _itemData;
			for (int i = 0; i < itemData.Length; i++)
			{
				itemData[i]?.AddItemProvider(itemProvider);
			}
		}
	}

	public void RemoveItemProvier(ItemDataItemProvider itemProvider)
	{
		ItemData[] itemData = _itemData;
		for (int i = 0; i < itemData.Length; i++)
		{
			itemData[i]?.RemoveItemProvider(itemProvider);
		}
	}

	public HashSet<ItemProperties> ReturnItemFilter(Item.Tags tags)
	{
		HashSet<ItemProperties> hashSet = new HashSet<ItemProperties>();
		ItemData[] itemData = _itemData;
		foreach (ItemData itemData2 in itemData)
		{
			if (itemData2 != null && (itemData2.ItemProperties.Tags & tags) != Item.Tags.None)
			{
				hashSet.Add(itemData2.ItemProperties);
			}
		}
		return hashSet;
	}

	public void AddStorage(Storage storage)
	{
		ItemData[] itemData = _itemData;
		for (int i = 0; i < itemData.Length; i++)
		{
			itemData[i]?.AddStorage(storage);
		}
		if (_storages.AddUnique(storage))
		{
			storage.Updated += OnStorageUpdated;
			_storageCount++;
			OnStorageUpdated();
		}
	}

	public void AddResourceProvider(ResourceProvider provider)
	{
		ItemData[] itemData = _itemData;
		for (int i = 0; i < itemData.Length; i++)
		{
			itemData[i]?.AddItemProvider(provider);
		}
		if (_resourceProviders.AddUnique(provider))
		{
			provider.InventoryUpdated += OnResourceProviderUpdated;
			_resourceProviderCount++;
			OnResourceProviderUpdated();
		}
	}

	public void RemoveStorage(Storage storage)
	{
		ItemData[] itemData = _itemData;
		for (int i = 0; i < itemData.Length; i++)
		{
			itemData[i]?.RemoveStorage(storage);
		}
		if (_storages.Remove(storage))
		{
			storage.Updated += OnStorageUpdated;
			_storageCount--;
			OnStorageUpdated();
		}
	}

	public void RemoveResourceProvider(ResourceProvider provider)
	{
		ItemData[] itemData = _itemData;
		for (int i = 0; i < itemData.Length; i++)
		{
			itemData[i]?.RemoveItemProvider(provider);
		}
		if (_resourceProviders.Remove(provider))
		{
			provider.InventoryUpdated -= OnResourceProviderUpdated;
			_resourceProviderCount--;
			OnResourceProviderUpdated();
		}
	}

	private void OnStorageUpdated()
	{
		_hasUpdates = true;
	}

	private void OnResourceProviderUpdated(ItemDataItemProvider itemProvider = null)
	{
		_hasUpdates = true;
	}

	public bool ReturnContainsItems(IEnumerable<CountedItemProperty> countedItems, SubInventoryType subInventory = SubInventoryType.Storage)
	{
		foreach (CountedItemProperty countedItem in countedItems)
		{
			if (!ReturnContainsItem(countedItem.ItemProperties, countedItem.Amount))
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnContainsItem(ItemProperties itemProperties, int amount, bool includeReserved = false)
	{
		return amount <= _itemData[itemProperties.Id].ReturnItemCount();
	}

	public bool TryReturnReserveClosestItems(IPathfindingNodeProvider destination, IReadOnlyList<CountedItemProperty> countedItems, out List<Item> reservedItems)
	{
		if (countedItems.Count == 1)
		{
			return TryReserveClosestItems(destination, countedItems[0], out reservedItems);
		}
		return TryReturnReserveClosestItems_ItemData(destination, countedItems, out reservedItems);
	}

	public bool TryReturnReserveClosestItems(IPathfindingNodeProvider destination, CountedItemProperty[] countedItems, out List<Item> reservedItems)
	{
		if (countedItems.Length == 1)
		{
			return TryReserveClosestItems(destination, countedItems[0], out reservedItems);
		}
		return TryReturnReserveClosestItems_ItemData(destination, countedItems, out reservedItems);
	}

	private bool TryReserveClosestItems(IPathfindingNodeProvider destination, CountedItemProperty countedItem, out List<Item> reservedItems)
	{
		return TryReserveClosestItems(destination, countedItem.ItemProperties, countedItem.Amount, out reservedItems);
	}

	private bool TryReturnReserveClosestItems_ItemData(IPathfindingNodeProvider destination, IEnumerable<CountedItemProperty> countedItems, out List<Item> reservedItems)
	{
		using ListPool<ItemDataItemProvider>.List list = ListPool<ItemDataItemProvider>.Get();
		foreach (CountedItemProperty countedItem in countedItems)
		{
			countedItem.ReservedAmount = 0;
			_itemData[countedItem.ItemProperties.Id].PopulateItemProviders(destination, list);
		}
		Sorting.SlowSort(list, _distanceSorter);
		reservedItems = new List<Item>();
		foreach (ItemDataItemProvider item in list)
		{
			if (item.ReserveItems(countedItems, reservedItems))
			{
				return true;
			}
		}
		throw new NotSupportedException("Items could not be reserved!");
	}

	public bool TryReserveClosestItems(IPathfindingNodeProvider destination, ItemProperties itemProperties, int amount, out List<Item> reservedItems)
	{
		using ListPool<ItemDataItemProvider>.List list = ListPool<ItemDataItemProvider>.Get();
		reservedItems = new List<Item>();
		foreach (ItemDataItemProvider itemProvider in _itemData[itemProperties.Id].ItemProviders)
		{
			if (0 < itemProvider.ReturnItemCount(itemProperties))
			{
				list.Add(itemProvider);
			}
		}
		while (0 < list.Count && reservedItems.Count < amount)
		{
			ItemDataItemProvider itemDataItemProvider = TownQueryCache.ReturnClosestDestination(destination, list);
			itemDataItemProvider.ReserveItems(itemProperties, amount, reservedItems);
			list.Remove(itemDataItemProvider);
		}
		return reservedItems.Count == amount;
	}

	public bool TryReserveItems(ItemProperties itemProperties, int amount, out List<Item> reservedItems)
	{
		ItemData itemData = _itemData[itemProperties.Id];
		reservedItems = null;
		if (itemData.ReturnItemCount() < amount)
		{
			return false;
		}
		reservedItems = new List<Item>();
		foreach (ItemDataItemProvider itemProvider in itemData.ItemProviders)
		{
			itemProvider.ReserveItems(itemProperties, amount, reservedItems);
			if (reservedItems.Count == amount)
			{
				return true;
			}
		}
		UnityEngine.Debug.LogException(new Exception($"Unable to reserve {amount} '{itemProperties.name}'"));
		return false;
	}

	public bool TryReserveItem(ItemProperties itemProperties, out Item item)
	{
		ItemData itemData = _itemData[itemProperties.Id];
		if (0 < itemData.ReturnItemCount())
		{
			using ListPool<Item>.List list = ListPool<Item>.Get();
			foreach (ItemDataItemProvider itemProvider in itemData.ItemProviders)
			{
				itemProvider.ReserveItems(itemProperties, 1, list);
				if (list.Count == 1)
				{
					item = list[0];
					return true;
				}
			}
			UnityEngine.Debug.LogException(new Exception("Unable to reserve '" + itemProperties.name + "'"));
		}
		item = null;
		return false;
	}

