public class InfiniteInventorySlot
{
	public ItemProperties ItemProperties;

	public int Count;

	public bool IsEmpty = true;

	private SubInventory _inventory;

	private List<Item> _items;

	public InfiniteInventorySlot(SubInventory inventory)
	{
		_inventory = inventory;
		_items = new List<Item>();
	}

	public bool AddItem(Item item)
	{
		if (IsEmpty)
		{
			ItemProperties = item.Properties;
			IsEmpty = false;
		}
		_items.Add(item);
		Count++;
		return true;
	}

	public bool AddItems(List<Item> items)
	{
		int count = items.Count;
		if (count == 0)
		{
			return true;
		}
		if (IsEmpty)
		{
			ItemProperties = items[0].Properties;
			IsEmpty = false;
		}
		_items.AddRange(items);
		Count += count;
		return true;
	}

	public bool RemoveItem(Item item)
	{
		if (_items.Remove(item))
		{
			Count--;
			IsEmpty = Count == 0;
			return true;
		}
		return false;
	}

	public Item TakeItem()
	{
		if (IsEmpty)
		{
			return null;
		}
		int index = Count - 1;
		Item result = _items[index];
		_items.RemoveAt(index);
		Count--;
		IsEmpty = Count == 0;
		return result;
	}
}
[Serializable]
public class InventorySlot : IInventorySlot
{
	private List<Item> _unreservedItems;

	private List<Item> _reservedItems;

	private int _simulationCount;

	public ItemProperties ItemProperties { get; private set; }

	public bool IsEmpty => Count == 0;

	public bool HasCapacity => Count < Capacity;

	public bool IsFull => Count == Capacity;

	public int Capacity { get; private set; }

	public int Count => _unreservedItems.Count + _reservedItems.Count;

	public int UnreservedCount => _unreservedItems.Count;

	public int ReservedCount => _reservedItems.Count;

	public event UnityAction<IInventorySlot> OnReservationUpdated;

	private void OnReservationUpdate()
	{
		if (this.OnReservationUpdated != null)
		{
			this.OnReservationUpdated(this);
		}
	}

	public InventorySlot(ItemProperties itemProperties, int capacity)
	{
		ItemProperties = itemProperties;
		_unreservedItems = new List<Item>();
		_reservedItems = new List<Item>();
		Capacity = capacity;
	}

	public InventorySlot(Item item)
		: this(item.Properties, item.Properties.StackLimit)
	{
		_unreservedItems.Capacity = Capacity;
		_unreservedItems.Add(item);
	}

	public InventorySlot(InventorySlot inventorySlot)
	{
		ItemProperties = inventorySlot.ItemProperties;
		_reservedItems = new List<Item>(inventorySlot._reservedItems);
		_unreservedItems = new List<Item>(inventorySlot._unreservedItems);
		Capacity = inventorySlot.Capacity;
	}

	public void Clear()
	{
		int count = _unreservedItems.Count;
		for (int i = 0; i < count; i++)
		{
			_unreservedItems[i].OnReserved -= ReserveItem;
		}
		_unreservedItems.Clear();
		count = _reservedItems.Count;
		for (int j = 0; j < count; j++)
		{
			Item item = _reservedItems[j];
			item.OnReservationCanceled -= CancelItemReservation;
			item.CancelReservation();
		}
		_reservedItems.Clear();
	}

	public bool AddItem(Item item)
	{
		if (ItemProperties != item.Properties || IsFull)
		{
			return false;
		}
		_unreservedItems.Add(item);
		item.OnReserved += ReserveItem;
		if (item.IsReserved)
		{
			ReserveItem(item);
		}
		return true;
	}

	public bool SimulateAddItem(Item item)
	{
		if (item.Properties == ItemProperties && Count + _simulationCount < Capacity)
		{
			_simulationCount++;
			return true;
		}
		return false;
	}

	public bool CanAddItem(Item item)
	{
		if (HasCapacity)
		{
			return item.Properties == ItemProperties;
		}
		return false;
	}

	public bool CanAddCountedItemProperty(CountedItemProperty countedItemProperty)
	{
		if (Count + countedItemProperty.Amount <= Capacity)
		{
			return countedItemProperty.ItemProperties == ItemProperties;
		}
		return false;
	}

	public Item PeekItem()
	{
		int count = _unreservedItems.Count;
		if (count == 0)
		{
			return null;
		}
		return _unreservedItems[count - 1];
	}

	public Item TakeItem(Item item)
	{
		if (item.IsReserved)
		{
			if (_reservedItems.Contains(item))
			{
				item.CancelReservation();
			}
			else
			{
				UnityEngine.Debug.LogError("Trying to take reserved item that is not in the _reservedItems list.");
			}
		}
		if (_unreservedItems.Remove(item))
		{
			item.OnReserved -= ReserveItem;
			return item;
		}
		UnityEngine.Debug.LogException(new Exception("Unable to take item!"));
		return null;
	}

	public bool TryTakeItem(out Item item, bool allowReserved = false)
	{
		if (TryTakeItem(_unreservedItems, out item))
		{
			item.OnReserved -= ReserveItem;
			return true;
		}
		if (allowReserved && TryTakeItem(_reservedItems, out item))
		{
			return true;
		}
		return false;
	}

	private bool TryTakeItem(List<Item> items, out Item item)
	{
		int count = items.Count;
		if (count == 0)
		{
			item = null;
			return false;
		}
		int index = count - 1;
		item = items[index];
		items.RemoveAt(index);
		if (item.IsReserved)
		{
			item.OnReservationCanceled -= CancelItemReservation;
			item.CancelReservation();
		}
		else
		{
			item.OnReserved -= ReserveItem;
		}
		return true;
	}

	public bool ReserveItem(ItemProperties itemProperties, List<Item> reservedItems)
	{
		int count = _unreservedItems.Count;
		if (count == 0 || ItemProperties != itemProperties)
		{
			return false;
		}
		int index = count - 1;
		Item item = _unreservedItems[index];
		item.Reserve();
		reservedItems.Add(item);
		return true;
	}

	public bool ContainsTag(Item.Tags tag)
	{
		return (ItemProperties.Tags & tag) == tag;
	}

	public Item ReturnFirstItem()
	{
		if (_unreservedItems.Count == 0)
		{
			return null;
		}
		return _unreservedItems[0];
	}

	public float ReturnFilling()
	{
		if (ItemProperties.StackLimit == 0)
		{
			return 0f;
		}
		return (float)Count / (float)ItemProperties.StackLimit;
	}

	public void PopulateItemList(List<Item> itemList, bool includeReserved)
	{
		itemList.AddRange(_unreservedItems);
		if (includeReserved)
		{
			itemList.AddRange(_reservedItems);
		}
	}

	public void Trim()
	{
		Capacity = Count;
	}

	public void StartSimulation()
	{
		_simulationCount = 0;
	}

	private void ReserveItem(Item item)
	{
		if (_unreservedItems.Remove(item))
		{
			_reservedItems.Add(item);
			item.OnReserved -= ReserveItem;
			item.OnReservationCanceled += CancelItemReservation;
			OnReservationUpdate();
			return;
		}
		throw new NotSupportedException("Trying to reserve an item that is not held by this slot!");
	}

	private void CancelItemReservation(Item item)
	{
		if (_reservedItems.Remove(item))
		{
			_unreservedItems.Add(item);
			item.OnReservationCanceled -= CancelItemReservation;
			item.OnReserved += ReserveItem;
			OnReservationUpdate();
			return;
		}
		throw new NotSupportedException("Canceling reservation of item that is not reserved!");
	}

	public bool TryReturnFirstAvailableItem(SubInventoryType subInventory, out Item item, IInventorySpaceLimiter limiter = null)
	{
		bool flag = limiter == null;
		int count = _unreservedItems.Count;
		for (int i = 0; i < count; i++)
		{
			item = _unreservedItems[i];
			if (item.Project == null)
			{
				if (!flag)
				{
					return limiter.FitsItem(item);
				}
				return true;
			}
		}
		item = null;
		return false;
	}

	public bool ReturnHasUnreservedItem()
	{
		if (IsEmpty)
		{
			return false;
		}
		int count = _unreservedItems.Count;
		for (int i = 0; i < count; i++)
		{
			Item item = _unreservedItems[i];
			if (item.Project == null && item.MoveToInventory == null)
			{
				return true;
			}
		}
		return false;
	}
}
public class SortInventoriesByDistance : IComparer<Inventory>, IComparer<ItemDataInventory>
{
	public Vector3 Position;

	public int Compare(Inventory x, Inventory y)
	{
		float num = Vector3.Distance(Position, x.transform.position);
		float num2 = Vector3.Distance(Position, y.transform.position);
		if (num < num2)
		{
			return -1;
		}
		return 1;
	}

	public int Compare(ItemDataInventory x, ItemDataInventory y)
	{
		float num = x.Path.ReturnDistance();
		float num2 = y.Path.ReturnDistance();
		if (num < num2)
		{
			return -1;
		}
		return 1;
	}
}
public class SubInventory
{
	public class SubInventoryEvent : UnityEvent<SubInventory>
	{
	}

	private List<IInventorySlot> _slots;

	public SubInventoryEvent OnSlotReservationUpdated { get; private set; }

	public UnityEvent<Item> ItemTakenEvent { get; private set; }

	public SubInventoryType Type { get; private set; }

	public bool IsEmpty { get; private set; }

	public bool HasCapacity { get; private set; }

	public int Capacity { get; private set; }

	public int AvailableCapacity { get; private set; }

	public int Count { get; private set; }

	public float Weight { get; private set; }

	public List<IInventorySlot> Slots => _slots;

	public List<Item> IncomingItems { get; private set; }

	public event UnityAction Updated;

	public SubInventory(SubInventoryType type, int capacity)
	{
		Type = type;
		IsEmpty = true;
		HasCapacity = capacity > 0;
		Capacity = capacity;
		AvailableCapacity = capacity;
		Count = 0;
		Weight = 0f;
		_slots = new List<IInventorySlot>();
		IncomingItems = new List<Item>(Mathf.Min(capacity, 32));
		OnSlotReservationUpdated = new SubInventoryEvent();
		ItemTakenEvent = new UnityEvent<Item>();
	}

	public SubInventory(SubInventory other)
	{
		Type = other.Type;
		IsEmpty = other.IsEmpty;
		HasCapacity = other.HasCapacity;
		Capacity = other.Capacity;
		AvailableCapacity = other.AvailableCapacity;
		Count = other.Count;
		Weight = other.Weight;
		_slots = other._slots;
	}

	public virtual bool AddItem(Item item, bool ignoreCapacity = false)
	{
		if (HasCapacity || item.IsQuestItem || ignoreCapacity)
		{
			AddItemIgnoreCapacity(item);
			return true;
		}
		return false;
	}

	private void AddItemIgnoreCapacity(Item item)
	{
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			if (_slots[i].AddItem(item))
			{
				OnItemAdded(item);
				return;
			}
		}
		IInventorySlot inventorySlot = new InventorySlot(item.Properties, int.MaxValue);
		inventorySlot.AddItem(item);
		inventorySlot.OnReservationUpdated += OnSlotReservationUpdate;
		_slots.Add(inventorySlot);
		OnItemAdded(item);
	}

	private void OnItemAdded(Item item)
	{
		IncreaseItemCount(1);
		Weight += item.Properties.Weight;
		this.Updated?.Invoke();
	}

	public bool CanAddCountedItemProperties(CountedItemProperty countedItemProperties)
	{
		return countedItemProperties.Amount + Count <= Capacity;
	}

	public virtual Item TakeItem(Item item)
	{
		if (TryReturnSlot(item.Properties, out var slot))
		{
			Item item2 = slot.TakeItem(item);
			if (item2 == item)
			{
				OnItemTaken(item2);
				return item2;
			}
		}
		return null;
	}

	public virtual Item TakeItem(ItemProperties itemProperties)
	{
		if (TryReturnSlot(itemProperties, out var slot))
		{
			Item item = slot.PeekItem();
			if (item == null)
			{
				return null;
			}
			slot.TakeItem(item);
			if (item.Properties == itemProperties)
			{
				OnItemTaken(item);
				return item;
			}
		}
		return null;
	}

	private void OnItemTaken(Item item)
	{
		DecreaseItemCount(1);
		Weight -= item.Properties.Weight;
		ItemTakenEvent.Invoke(item);
		this.Updated?.Invoke();
	}

	public virtual Item ReturnItemFromProperties(ItemProperties itemProperties)
	{
		if (TryReturnSlot(itemProperties, out var slot))
		{
			return slot.PeekItem();
		}
		return null;
	}

	public bool TryTakeRandomItem(out Item item, bool allowReserved)
	{
		if (0 < Count)
		{
			int count = _slots.Count;
			int num = UnityEngine.Random.Range(0, count);
			for (int i = 0; i < count; i++)
			{
				if (_slots[(num + i) % count].TryTakeItem(out item, allowReserved))
				{
					DecreaseItemCount(1);
					return true;
				}
			}
		}
		item = null;
		return false;
	}

	public void ReserveItems(ItemProperties itemProperties, int amount, List<Item> reservedItems)
	{
		if (TryReturnSlot(itemProperties, out var slot))
		{
			while (reservedItems.Count < amount && slot.ReserveItem(itemProperties, reservedItems))
			{
			}
		}
	}

	public void ReserveItems(CountedItemProperty countedItem, List<Item> reservedItems)
	{
		if (TryReturnSlot(countedItem.ItemProperties, out var slot))
		{
			while (countedItem.ReservedAmount < countedItem.Amount && slot.ReserveItem(countedItem.ItemProperties, reservedItems))
			{
				countedItem.ReservedAmount++;
			}
		}
	}

	public bool AddIncomingItem(Item item)
	{
		if (IncomingItems.AddUnique(item))
		{
			this.Updated?.Invoke();
			return true;
		}
		return false;
	}

	public bool RemoveIncomingItem(Item item)
	{
		if (IncomingItems.Remove(item))
		{
			this.Updated?.Invoke();
			return true;
		}
		return false;
	}

	public bool HasIncomingItem(Item item)
	{
		return IncomingItems.Contains(item);
	}

	public Item PeekAtFirstItem()
	{
		if (IsEmpty)
		{
			return null;
		}
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (!inventorySlot.IsEmpty)
			{
				return inventorySlot.PeekItem();
			}
		}
		return null;
	}

	public bool ContainsSlotForItem(Item item)
	{
		IInventorySlot slot;
		return TryReturnSlot(item.Properties, out slot);
	}

	public void StartSimulation()
	{
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			_slots[i].StartSimulation();
		}
	}

	public virtual void Clear()
	{
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			_slots[i].Clear();
		}
		_slots.Clear();
		Count = 0;
		AvailableCapacity = Capacity;
		IsEmpty = true;
		HasCapacity = true;
	}

	private bool TryReturnSlot(ItemProperties itemProperties, out IInventorySlot slot)
	{
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			slot = _slots[i];
			if (slot.ItemProperties == itemProperties)
			{
				return true;
			}
		}
		slot = null;
		return false;
	}

	private void IncreaseItemCount(int amount)
	{
		Count += amount;
		AvailableCapacity -= amount;
		IsEmpty = false;
		HasCapacity = Count < Capacity;
	}

	private void DecreaseItemCount(int amount)
	{
		Count -= amount;
		AvailableCapacity += amount;
		IsEmpty = Count == 0;
		HasCapacity = true;
	}

	protected virtual void OnSlotReservationUpdate(IInventorySlot slot)
	{
		if (OnSlotReservationUpdated != null)
		{
			OnSlotReservationUpdated.Invoke(this);
		}
		this.Updated?.Invoke();
	}

	public void PopulateCountedItemPropertyArray(CountedItemProperty[] countedItems)
	{
		if (countedItems == null)
		{
			throw new NotSupportedException("The counted item property array cannot be null");
		}
		int num = countedItems.Length;
		for (int i = 0; i < num; i++)
		{
			CountedItemProperty countedItemProperty = countedItems[i];
			countedItemProperty.Amount = ReturnItemCount(countedItemProperty.ItemProperties);
		}
	}

	public List<Item> ReturnAllItems(List<Item> listToPopulate = null, bool includeReserved = true)
	{
		int count = _slots.Count;
		List<Item> list = ((listToPopulate == null) ? new List<Item>(Count) : listToPopulate);
		for (int i = 0; i < count; i++)
		{
			_slots[i].PopulateItemList(list, includeReserved);
		}
		return list;
	}

	public List<Item> ReturnItemsWithTags(Item.Tags tags, List<Item> listToPopulate = null, bool includeReserved = true)
	{
		List<Item> list = listToPopulate ?? new List<Item>(Count);
		foreach (IInventorySlot slot in _slots)
		{
			if (slot.ItemProperties.Tags.HasFlag(tags))
			{
				slot.PopulateItemList(list, includeReserved);
			}
		}
		return list;
	}

	public bool TryReturnItemContainingTag(Item.Tags tag, out Item item)
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (!inventorySlot.IsEmpty && (inventorySlot.ItemProperties.Tags & tag) == tag)
			{
				item = inventorySlot.PeekItem();
				return true;
			}
		}
		item = null;
		return false;
	}

	public bool TryReturnItem(ItemProperties itemProperties, out Item item)
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (!inventorySlot.IsEmpty && inventorySlot.ItemProperties == itemProperties)
			{
				item = inventorySlot.PeekItem();
				return true;
			}
		}
		item = null;
		return false;
	}

	public bool ReturnFirstAvailableItem(SubInventoryType subInventory, out Item item, IInventorySpaceLimiter limiter = null)
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			if (_slots[i].TryReturnFirstAvailableItem(subInventory, out item, limiter))
			{
				return true;
			}
		}
		item = null;
		return false;
	}

	public bool ReturnContainsItems(IEnumerable<CountedItemProperty> countedItems)
	{
		foreach (CountedItemProperty countedItem in countedItems)
		{
			if (!ReturnContainsItems(countedItem.ItemProperties, countedItem.Amount))
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnContainsItems(ItemProperties itemProperties, int amount = 1)
	{
		int count = _slots.Count;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (inventorySlot.ItemProperties == itemProperties)
			{
				num += inventorySlot.UnreservedCount;
				if (amount <= num)
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool ReturnHasCapacity()
	{
		return 0 < AvailableCapacity - IncomingItems.Count;
	}

	public int ReturnItemCount(bool includeReserved = false)
	{
		int count = _slots.Count;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			num += _slots[i].UnreservedCount;
			if (includeReserved)
			{
				num += _slots[i].ReservedCount;
			}
		}
		return num;
	}

	public int ReturnItemCount(ItemProperties itemProperties, bool includeReserved = false)
	{
		int count = _slots.Count;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (inventorySlot.ItemProperties == itemProperties)
			{
				num += inventorySlot.UnreservedCount;
				if (includeReserved)
				{
					num += inventorySlot.ReservedCount;
				}
			}
		}
		return num;
	}

	public int ReturnItemContainingTagCount(Item.Tags tag, bool includeReserved = false)
	{
		int count = _slots.Count;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if ((inventorySlot.ItemProperties.Tags & tag) != Item.Tags.None)
			{
				num += inventorySlot.UnreservedCount;
				if (includeReserved)
				{
					num += inventorySlot.ReservedCount;
				}
			}
		}
		return num;
	}

	public float ReturnItemContainingTagNutritionalValue(Item.Tags tag, bool includeReserved = false)
	{
		int count = _slots.Count;
		float num = 0f;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if ((inventorySlot.ItemProperties.Tags & tag) != Item.Tags.None)
			{
				num += (float)inventorySlot.UnreservedCount * inventorySlot.ItemProperties.NutritionalValue;
				if (includeReserved)
				{
					num += (float)inventorySlot.ReservedCount * inventorySlot.ItemProperties.NutritionalValue;
				}
			}
		}
		return num;
	}

	public int ReturnItemMatchingTagsCount(Item.Tags tags)
	{
		int count = _slots.Count;
		int num = 0;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			if (inventorySlot.ItemProperties.Tags == tags)
			{
				num += inventorySlot.UnreservedCount;
			}
		}
		return num;
	}

	public CountedItemProperty[] ReturnAsCounteItemPropertyArray()
	{
		int count = Slots.Count;
		CountedItemProperty[] array = new CountedItemProperty[Slots.Count];
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = Slots[i];
			array[i] = new CountedItemProperty(inventorySlot.ItemProperties, inventorySlot.Count);
		}
		return array;
	}

	public float ReturnWeight()
	{
		float num = 0f;
		int count = _slots.Count;
		for (int i = 0; i < count; i++)
		{
			IInventorySlot inventorySlot = _slots[i];
			num += inventorySlot.ItemProperties.Weight * (float)inventorySlot.Count;
		}
		return num;
	}

	public string ReturnFormattedInventorySlotList()
	{
		string text = string.Empty;
		foreach (IInventorySlot slot in _slots)
		{
			text += $"{slot.ItemProperties.name} ({slot.Count}/{slot.Capacity}).{System.Environment.NewLine}";
		}
		return text;
	}
}
public enum SubInventoryType
{
	Storage = 0,
	Resources = 1,
	Composition = 2,
	Import = 3,
	Export = 4,
	Liquid = 6,
	Modules = 7
}
public class ILandmarkActionEvent : UnityEvent<ILandmarkAction>
{
}
public enum ILandmarkActionStates
{
	Hidden,
	Inactive,
	Active,
	Completed
}
public interface ILandmarkAction
{
	ILandmarkActionStates State { get; }

	Project Project { get; }

	bool UseBoat { get; set; }

	int MooringPointCount { get; }

	int AssignmentLimitMinimum { get; }

	int AssignmentLimitMaximum { get; }

	int AssignmentLimit { get; }

	bool IsCompleted { get; }

	bool WasCompleted { get; }

	ILandmarkActionEvent UpdatedEvent { get; }

	LocalizedString Title { get; }

	LocalizedString ActivateText { get; }

	void SetAssignmentLimit(int limit);

	void UpdateState();

	void Activate();

	void Deactivate();

	bool ReturnIsInteractable();

	bool TryReturnInteractableTooltip(out LocalizedString tooltip);

	float ReturnProgress();
}
public interface ILandmarkActionToggleable : IToggleable
{
	string Label { get; }

	bool Unlocked { get; }

	IEnumerator Unlock();

	bool TryReturnRequiredItemAndCost(out ItemProperties requiredItem, out int cost);
}
public abstract class LandmarkAction : ScriptableObject, ILandmarkAction
{
	[Tooltip("Title for the action panel.")]
	[SerializeField]
	[FormerlySerializedAs("Title")]
	private LocalizedString _title;

	[Tooltip("Interaction text to display on button.")]
	[SerializeField]
	[FormerlySerializedAs("ActivateText")]
	private LocalizedString _activateText;

	public Sprite Icon;

	public int MarkerPriority;

	public bool RequiresRowBoat;

	public bool RequiresScouting;

	public NotificationProperties CompletedNotification;

	[Header("Projects")]
	public ProjectProperties SwimmingProjectProperties;

	public ProjectProperties BoatingProjectProperties;

	public RangedInt AssignmentLimitRange = new RangedInt(1, 1);

	[NonSerialized]
	protected LandmarkBehaviour _landmarkBehaviour;

	[NonSerialized]
	private bool _enabled;

	[NonSerialized]
	private bool _wasCompleted;

	[NonSerialized]
	private bool _useBoat;

	public ILandmarkActionStates State { get; private set; }

	public Project Project { get; private set; }

	public bool UseBoat
	{
		get
		{
			return _useBoat;
		}
		set
		{
			if (_useBoat != value)
			{
				_useBoat = value;
				SetAssignmentLimit(Mathf.Clamp(AssignmentLimit, AssignmentLimitMinimum, AssignmentLimitMaximum));
				if (State == ILandmarkActionStates.Active)
				{
					Deactivate();
					Activate();
				}
			}
		}
	}

	public int MooringPointCount => _landmarkBehaviour.ReturnMooringPointCount();

	public virtual int AssignmentLimitMinimum => AssignmentLimitRange.Minimum;

	public virtual int AssignmentLimitMaximum
	{
		get
		{
			if (!UseBoat)
			{
				return AssignmentLimitRange.Maximum;
			}
			return MooringPointCount;
		}
	}

	public int AssignmentLimit { get; private set; }

	public bool HasProject => Project != null;

	public bool IsCompleted => State == ILandmarkActionStates.Completed;

	public bool WasCompleted
	{
		get
		{
			if (State == ILandmarkActionStates.Completed && !_wasCompleted)
			{
				_wasCompleted = true;
				return true;
			}
			return false;
		}
	}

	public ILandmarkActionEvent UpdatedEvent { get; private set; }

	public LocalizedString Title => _title;

	public LocalizedString ActivateText => _activateText;

	public abstract GameEventType InteractableEventType { get; }

	public virtual bool RequiresPersistence => false;

	public virtual void Initialize(LandmarkBehaviour landmarkBehaviour)
	{
		_landmarkBehaviour = landmarkBehaviour;
		_enabled = true;
		_wasCompleted = false;
	}

	public virtual void Restore(LandmarkPersistentData landmarkPersistentData)
	{
	}

	public virtual void OnLandmarkSpawned(LandmarkActionPersistentData persistentData = null)
	{
		if (State == ILandmarkActionStates.Hidden)
		{
			if (RequiresScouting)
			{
				_landmarkBehaviour.UpdatedEvent.AddListener(OnLandmarkBehaviourUpdate);
			}
			else
			{
				State = ILandmarkActionStates.Inactive;
			}
		}
		if (UpdatedEvent == null)
		{
			UpdatedEvent = new ILandmarkActionEvent();
		}
	}

	public virtual void OnLandmarkSelected()
	{
	}

	public virtual void OnLandmarkDeselected()
	{
	}

	public virtual void Uninitialize()
	{
		if (!(_landmarkBehaviour == null) && _landmarkBehaviour.UpdatedEvent != null)
		{
			_landmarkBehaviour.UpdatedEvent.RemoveListener(OnLandmarkBehaviourUpdate);
		}
	}

	private void OnDisable()
	{
		_enabled = false;
		if (UpdatedEvent != null)
		{
			UpdatedEvent.RemoveAllListeners();
		}
	}

	public virtual void UpdateState()
	{
	}

	public void Activate()
	{
		if (!_enabled)
		{
			throw new NotSupportedException("LandmarkAction '" + base.name + "' was activated before it was instantiated. This is not supported!");
		}
		if (State != ILandmarkActionStates.Inactive)
		{
			return;
		}
		if (Project == null)
		{
			Project project = ReturnProject();
			if (project != null && Community.PlayerCommunity.QueueProject(project))
			{
				Project = project;
				Project.FinishedEvent.AddListener(OnProjectFinished);
				SetState(ILandmarkActionStates.Active);
			}
		}
		else if (Community.PlayerCommunity.QueueProject(Project))
		{
			Project.FinishedEvent.AddListener(OnProjectFinished);
			SetState(ILandmarkActionStates.Active);
		}
	}

	public void Deactivate()
	{
		if (State == ILandmarkActionStates.Active)
		{
			if (Project != null)
			{
				Project.FinishedEvent.RemoveListener(OnProjectFinished);
				Project.Stop(ProjectFlags.Cancelled);
				Project = null;
			}
			SetState(ILandmarkActionStates.Inactive);
		}
	}

	public void SetAssignmentLimit(int limit)
	{
		AssignmentLimit = Mathf.Clamp(limit, AssignmentLimitMinimum, AssignmentLimitMaximum);
		if (Project != null)
		{
			Project.AssignmentLimit = limit;
		}
	}

	protected void SetState(ILandmarkActionStates state, bool dispatchEvent = true)
	{
		if (state == State)
		{
			return;
		}
		ILandmarkActionStates state2 = State;
		State = state;
		if (!dispatchEvent)
		{
			return;
		}
		if (UpdatedEvent != null)
		{
			UpdatedEvent.Invoke(this);
		}
		switch (state)
		{
		case ILandmarkActionStates.Active:
			OnActivated();
			LandmarkNotificationEvent.Working(_landmarkBehaviour, this);
			break;
		case ILandmarkActionStates.Inactive:
			OnDeactivated();
			if (state2 == ILandmarkActionStates.Hidden)
			{
				LandmarkNotificationEvent.Update(_landmarkBehaviour, this);
			}
			else
			{
				LandmarkNotificationEvent.Idle(_landmarkBehaviour, this);
			}
			break;
		case ILandmarkActionStates.Completed:
			OnCompleted();
			LandmarkNotificationEvent.Completed(_landmarkBehaviour, this);
			break;
		}
	}

	private void OnLandmarkBehaviourUpdate(LandmarkBehaviour landmarkBehaviour, object trigger)
	{
		if (State == ILandmarkActionStates.Hidden)
		{
			if (!landmarkBehaviour.IsScouted)
			{
				return;
			}
			SetState(ILandmarkActionStates.Inactive);
		}
		landmarkBehaviour.UpdatedEvent.RemoveListener(OnLandmarkBehaviourUpdate);
	}

	protected virtual void OnProjectFinished(Project project, bool success)
	{
		if (Project != null)
		{
			Project.FinishedEvent.RemoveListener(OnProjectFinished);
			Project = null;
		}
		if (success)
		{
			SetState(ILandmarkActionStates.Completed);
		}
		else
		{
			SetState(ILandmarkActionStates.Inactive);
		}
	}

	protected virtual void OnActivated()
	{
	}

	protected virtual void OnDeactivated()
	{
	}

	protected virtual void OnCompleted()
	{
	}

	public virtual void CountItems(InventoryAuditor auditor, Landmark landmark)
	{
	}

	public virtual Project ReturnProject()
	{
		return new Project(UseBoat ? BoatingProjectProperties : SwimmingProjectProperties, _landmarkBehaviour.Landmark.gameObject);
	}

	public virtual bool ReturnIsInteractable()
	{
		if ((State == ILandmarkActionStates.Active || State == ILandmarkActionStates.Inactive) && (bool)_landmarkBehaviour)
		{
			if (!_landmarkBehaviour.IsReachableByBoat())
			{
				return _landmarkBehaviour.IsInSwimmingRadius();
			}
			return true;
		}
		return false;
	}

	public virtual bool TryReturnInteractableTooltip(out LocalizedString tooltip)
	{
		tooltip = default(LocalizedString);
		return false;
	}

	public abstract void InitializeUI(LandmarkPanel landmarkPanel);

	public virtual Sprite ReturnBearingIcon()
	{
		return null;
	}

	public virtual float ReturnProgress()
	{
		return IsCompleted ? 1 : 0;
	}

	public virtual LandmarkActionPersistentData ReturnLandmarkActionPersistentData()
	{
		return new LandmarkActionPersistentData(this);
	}

	public virtual void Restore(LandmarkActionPersistentData data, LandmarkBehaviour landmarkBehaviour)
	{
		State = data.State;
		_useBoat = data.UseBoat;
		Initialize(landmarkBehaviour);
		OnLandmarkSpawned(data);
	}

	public virtual void RestoreReferences(LandmarkActionPersistentData data)
	{
		if (State == ILandmarkActionStates.Active && data.Project == null)
		{
			TryToFixMissingProjectReference(data);
		}
		if (data.Project.TryReturn(out var instance))
		{
			Project = instance;
			Project.FinishedEvent.AddListener(OnProjectFinished);
		}
	}

	private void TryToFixMissingProjectReference(LandmarkActionPersistentData data)
	{
		string projectTargetName = _landmarkBehaviour.name;
		data.Project = Community.PlayerCommunity.Projects.Find((Project project) => project.Target != null && project.Target.name == projectTargetName);
		if (data.Project == null)
		{
			UnityEngine.Debug.LogError($"The current save has an active landmark action ({data.Id} action with target {projectTargetName}) but no project associated with it. Deactivating the action.");
			State = ILandmarkActionStates.Inactive;
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Landmarks/Actions/Animal Rescue")]
public class LandmarkActionAnimalRescue : LandmarkAction
{
	[SerializeField]
	private LandmarkActionAnimalRescueUI _uiPrefab;

	[HideInInspector]
	public List<LandmarkRescueable> Rescueables = new List<LandmarkRescueable>();

	public override GameEventType InteractableEventType => GameEventType.LandmarkActionAnimalRescueInteractable;

	public override void OnLandmarkSpawned(LandmarkActionPersistentData persistentData = null)
	{
		base.OnLandmarkSpawned(persistentData);
		LandmarkRescueable[] componentsInChildren = _landmarkBehaviour.Landmark.GetComponentsInChildren<LandmarkRescueable>();
		Rescueables = new List<LandmarkRescueable>();
		LandmarkRescueable[] array = componentsInChildren;
		foreach (LandmarkRescueable landmarkRescueable in array)
		{
			if (!(landmarkRescueable.Agent == null) || !(landmarkRescueable.Bird == null))
			{
				landmarkRescueable.IsInteractable = true;
				Rescueables.Add(landmarkRescueable);
			}
		}
		if (base.State == ILandmarkActionStates.Active)
		{
			GameEventDispatcher.AddListener(GameEventType.BirdRescue, OnBirdRescued);
		}
		if (base.State != ILandmarkActionStates.Completed)
		{
			_landmarkBehaviour.Landmark.StartCoroutine(PlayAttentionSoundCoroutine());
		}
	}

	public override void Uninitialize()
	{
		base.Uninitialize();
		GameEventDispatcher.RemoveListener(GameEventType.BirdRescue, OnBirdRescued);
	}

	protected override void OnProjectFinished(Project project, bool success)
	{
		base.OnProjectFinished(project, Rescueables.Count == 0);
	}

	protected override void OnActivated()
	{
		GameEventDispatcher.AddListener(GameEventType.BirdRescue, OnBirdRescued);
	}

	protected override void OnDeactivated()
	{
		GameEventDispatcher.RemoveListener(GameEventType.BirdRescue, OnBirdRescued);
	}

	protected override void OnCompleted()
	{
		GameEventDispatcher.RemoveListener(GameEventType.BirdRescue, OnBirdRescued);
	}

	private void OnBirdRescued(GameEvent gameEvent)
	{
		BirdEvent birdEvent = gameEvent as BirdEvent;
		if (Rescueables.RemoveAll((LandmarkRescueable rescuable) => rescuable.Bird == birdEvent.Bird) != 0 && Rescueables.Count == 0)
		{
			OnProjectFinished(base.Project, success: true);
		}
	}

	private IEnumerator PlayAttentionSoundCoroutine()
	{
		while (true)
		{
			float seconds = UnityEngine.Random.Range(GameManager.Settings.AudioSettings.AttentionVoiceInterval.Minimum, GameManager.Settings.AudioSettings.AttentionVoiceInterval.Maximum);
			yield return new WaitForSeconds(seconds);
			Rescueables.RemoveAll((LandmarkRescueable rescuable) => !rescuable.HasValidRescueables());
			if (Rescueables.Count != 0)
			{
				Agent agent = Rescueables[UnityEngine.Random.Range(0, Rescueables.Count - 1)].Agent;
				if (!(agent == null))
				{
					AudioManager.Play(agent.Descriptor.VoicePack.AttentionSounds, agent.transform);
					continue;
				}
				break;
			}
			break;
		}
	}

	public override Project ReturnProject()
	{
		return new Project(base.UseBoat ? GameManager.Settings.ProjectSettings.RescueAnimalLandmark : GameManager.Settings.ProjectSettings.RescueAnimalLandmarkSwimming, _landmarkBehaviour.Landmark.ProjectTarget.gameObject);
	}

	public override void InitializeUI(LandmarkPanel landmarkPanel)
	{
		landmarkPanel.ReturnLandmarkActionUI<LandmarkActionRescueUI>().Initialize(this);
	}
}
