[CreateAssetMenu(menuName = "Flotsam/Landmarks/Actions/Rescue")]
public class LandmarkActionRescue : LandmarkAction
{
	public class Rescueable : ILandmarkActionToggleable, IToggleable, IDialogueInteractable
	{
		private LandmarkAction _action;

		private LandmarkRescueable _rescueable;

		private bool _rescueOnDialogueEnd;

		private bool _hasStartedDialogue;

		public string Label
		{
			get
			{
				if (!(Actor != null))
				{
					return "NULL";
				}
				return Actor.Name;
			}
		}

		public bool IsInteractable => _action.ReturnIsInteractable();

		public bool IsCompleted
		{
			get
			{
				if (!(_rescueable == null))
				{
					return _rescueable.IsRescued;
				}
				return true;
			}
		}

		public bool IsToggled { get; private set; }

		public ActorDescriptor Descriptor { get; private set; }

		public ActorBehaviour Actor { get; private set; }

		public Agent Agent { get; private set; }

		public DialogueTreeProperties DialogueProperties { get; private set; }

		public bool Unlocked { get; set; }

		public Rescueable(LandmarkAction action, LandmarkRescueable rescueable, bool unlocked = false)
		{
			_action = action;
			_rescueable = rescueable;
			Unlocked = !TryReturnRequiredItemAndCost(out var _, out var _) || unlocked;
			if ((bool)_rescueable)
			{
				Descriptor = _rescueable.Descriptor;
				Actor = _rescueable.Actor;
				Agent = _rescueable.Agent;
				if ((bool)Descriptor.ActorProfile)
				{
					DialogueProperties = Descriptor.ActorProfile.DialogueProperties;
				}
				if ((bool)_rescueable.Unlockable)
				{
					_rescueable.Unlockable.Initialize(this);
				}
			}
		}

		public IEnumerator Unlock()
		{
			Unlocked = true;
			if ((bool)_rescueable && (bool)_rescueable.Unlockable)
			{
				yield return _rescueable.Unlockable.Unlock();
			}
		}

		public void Toggle()
		{
			IsToggled = !IsToggled;
			_action.UpdateState();
		}

		public void SetActive(bool active)
		{
			IsToggled = active;
			_action.UpdateState();
		}

		public void SeekAttention()
		{
			if ((bool)_rescueable && (bool)_rescueable.Agent && (bool)_rescueable.Agent.Descriptor.VoicePack)
			{
				AudioManager.Play(_rescueable.Agent.Descriptor.VoicePack.AttentionSounds, _rescueable.Agent.transform);
			}
		}

		public bool IsSeekingAttention()
		{
			if ((bool)_rescueable)
			{
				return _rescueable.Actor.Community != Community.PlayerCommunity;
			}
			return false;
		}

		public bool IsAgent(Agent agent)
		{
			if ((bool)_rescueable)
			{
				return _rescueable.Actor == agent;
			}
			return false;
		}

		public bool TriggerDialogue()
		{
			if (!_hasStartedDialogue && IsInteractable && !IsCompleted && !IsToggled && (bool)Agent && TryGetEntryPoint(out var _))
			{
				DialogueGameEvent.DispatchDialogueStartRequest(this);
				_hasStartedDialogue = true;
				if (_rescueable.Agent != null)
				{
					_rescueable.Agent.UpdateActivity(Activity.Landmark_Speaking);
				}
				return true;
			}
			return false;
		}

		public void OnDialogueResponse(DialogueResponseType response, Dialogue dialogue)
		{
			switch (response)
			{
			case DialogueResponseType.Yes:
				_rescueOnDialogueEnd = true;
				if ((bool)_rescueable.Agent)
				{
					_rescueable.Agent.UpdateActivity(Activity.Landmark_RescueAccepted);
				}
				break;
			case DialogueResponseType.No:
				if ((bool)_rescueable.Agent)
				{
					_rescueable.Agent.UpdateActivity(Activity.Landmark_RescueRefused);
				}
				break;
			case DialogueResponseType.EndOfDialogue:
				if (_rescueOnDialogueEnd)
				{
					_rescueable.Rescue();
					_action.UpdateState();
				}
				else if ((bool)_rescueable.Agent)
				{
					_rescueable.Agent.UpdateActivity(Activity.Idling);
				}
				break;
			}
			if (response != DialogueResponseType.None)
			{
				_hasStartedDialogue = false;
			}
		}

		public bool TryGetEntryPoint(out DialogueNodeProperties entryPoint)
		{
			entryPoint = null;
			if ((bool)DialogueProperties)
			{
				entryPoint = DialogueProperties.ReturnBranchEntryNode(DialogueBranchType.Rescue);
			}
			return entryPoint != null;
		}

		public bool TryGetMainSpeaker(out AgentDescriptor mainSpeaker)
		{
			if ((bool)Agent)
			{
				mainSpeaker = Agent.Descriptor;
				return true;
			}
			mainSpeaker = null;
			return false;
		}

		public bool TryReturnRequiredItemAndCost(out ItemProperties itemProperties, out int cost)
		{
			itemProperties = _rescueable.RequiredItem;
			cost = _rescueable.RequiredItemCost;
			if ((bool)itemProperties)
			{
				return 0 < cost;
			}
			return false;
		}
	}

	[Serializable]
	public class PersistentData : LandmarkActionPersistentData
	{
		[OptionalField(VersionAdded = 3)]
		private readonly ActorType _actorType;

		[OptionalField(VersionAdded = 4)]
		private readonly ushort[] _rescuableDescriptors;

		[OptionalField(VersionAdded = 4)]
		private readonly ushort[] _unlockedRescuables;

		[OptionalField(VersionAdded = 2)]
		private readonly int _associatedQuestIndex = -1;

		private readonly int _forcedBackgroundIndex = -1;

		[OptionalField(VersionAdded = 2)]
		private readonly ushort _forcedDescriptorID;

		public ushort[] UnlockedRescuables => _unlockedRescuables;

		public PersistentData(LandmarkActionRescue instance)
			: base(instance)
		{
			_actorType = instance.ActorType;
			if (instance._rescuableDescriptors != null)
			{
				_rescuableDescriptors = new ushort[instance._rescuableDescriptors.Count];
				for (int i = 0; i < instance._rescuableDescriptors.Count; i++)
				{
					_rescuableDescriptors[i] = instance._rescuableDescriptors[i].UniqueID;
				}
			}
			if (instance.Rescueables != null)
			{
				using ListPool<ushort>.List list = ListPool<ushort>.Get();
				foreach (Rescueable rescueable in instance.Rescueables)
				{
					if (rescueable.Unlocked)
					{
						list.Add(rescueable.Descriptor.UniqueID);
					}
				}
				if (0 < list.Count)
				{
					_unlockedRescuables = list.ToArray();
				}
			}
			_associatedQuestIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(instance._associatedQuest);
		}

		public ActorType ReturnActorType()
		{
			return _actorType;
		}

		public List<ActorDescriptor> ReturnRescuableDescriptors()
		{
			if (((IReadOnlyCollection<ushort>)(object)_rescuableDescriptors).IsNullOrEmpty())
			{
				return null;
			}
			List<ActorDescriptor> list = new List<ActorDescriptor>(_rescuableDescriptors.Length);
			ushort[] rescuableDescriptors = _rescuableDescriptors;
			foreach (ushort id in rescuableDescriptors)
			{
				if (ActorDescriptor.TryGet<ActorDescriptor>(out var actorDescriptor, id))
				{
					list.Add(actorDescriptor);
				}
			}
			return list;
		}

		public bool TryReturnFirstRescuableDescriptor(out ActorDescriptor rescuableDescriptor)
		{
			rescuableDescriptor = null;
			if (((IReadOnlyCollection<ushort>)(object)_rescuableDescriptors).IsNullOrEmpty())
			{
				return false;
			}
			ushort[] rescuableDescriptors = _rescuableDescriptors;
			foreach (ushort id in rescuableDescriptors)
			{
				if (ActorDescriptor.TryGet<ActorDescriptor>(out rescuableDescriptor, id))
				{
					break;
				}
			}
			return rescuableDescriptor != null;
		}

		public QuestProperties ReturnAssociatedQuest()
		{
			if (_associatedQuestIndex == -1 || !GameManager.PersistenceManager.TryReturnPropertiesReference<QuestProperties>(_associatedQuestIndex, out var reference))
			{
				return null;
			}
			return reference;
		}

		public ActorDescriptor ReturnForcedDescriptor()
		{
			if (ActorDescriptor.TryGet<ActorDescriptor>(out var actorDescriptor, _forcedDescriptorID))
			{
				return actorDescriptor;
			}
			if (0 <= _forcedBackgroundIndex && GameManager.PersistenceManager.TryReturnPropertiesReference<DrifterAttributesEffect>(_forcedBackgroundIndex, out var reference))
			{
				return AgentDescriptor.CreateInstance(reference);
			}
			return null;
		}
	}

	private List<ActorDescriptor> _rescuableDescriptors;

	private QuestProperties _associatedQuest;

	private ushort[] _unlockedRescuables;

	public override GameEventType InteractableEventType => GameEventType.LandmarkActionRescueInteractable;

	public ActorType ActorType { get; private set; }

	public List<Rescueable> Rescueables { get; private set; }

	public override bool RequiresPersistence => !_rescuableDescriptors.IsNullOrEmpty();

	public override void OnLandmarkSpawned(LandmarkActionPersistentData persistentData = null)
	{
		base.OnLandmarkSpawned(persistentData);
		PopulateRescuables();
		if (base.State != ILandmarkActionStates.Completed)
		{
			_landmarkBehaviour.Landmark.StartCoroutine(PlayAttentionSoundCoroutine());
		}
	}

	public override void OnLandmarkSelected()
	{
		if (Rescueables.IsNullOrEmpty())
		{
			return;
		}
		foreach (Rescueable rescueable in Rescueables)
		{
			if (rescueable.TriggerDialogue() || CameraDevTools.DebugCinematicLock)
			{
				CameraController.Instance.CinematicLock(rescueable.Agent.transform, 0f, CameraController.TargetFocusOrientationType.FaceTarget);
				GameEventDispatcher.AddListener(GameEventType.DialogueEnded, OnDialogueEnded);
				break;
			}
		}
	}

	public override void Uninitialize()
	{
		base.Uninitialize();
		UnregisterQuestEvents();
	}

	private void UnregisterQuestEvents()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentRescue, OnRescueableRescued);
		GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnDialogueEnded);
		GameEventDispatcher.RemoveListener(GameEventType.QuestAbandoned, OnQuestFailed);
		GameEventDispatcher.RemoveListener(GameEventType.QuestFailed, OnQuestFailed);
	}

	protected override void OnActivated()
	{
		if (Rescueables.IsNullOrEmpty())
		{
			return;
		}
		foreach (Rescueable rescueable in Rescueables)
		{
			rescueable.SetActive(active: true);
		}
		GameEventDispatcher.AddListener(GameEventType.AgentRescue, OnRescueableRescued);
	}

	protected override void OnDeactivated()
	{
		if (Rescueables.IsNullOrEmpty())
		{
			return;
		}
		foreach (Rescueable rescueable in Rescueables)
		{
			rescueable.SetActive(active: false);
		}
		GameEventDispatcher.RemoveListener(GameEventType.AgentRescue, OnRescueableRescued);
	}

	private void OnRescueableRescued(GameEvent gameEvent)
	{
		AgentEvent agentEvent = gameEvent as AgentEvent;
		if (agentEvent != null && Rescueables.Find((Rescueable rescueable) => rescueable.Agent == agentEvent.Agent) != null)
		{
			UnregisterQuestEvents();
		}
	}

	private void OnDialogueEnded(GameEvent gameEvent)
	{
		if (gameEvent is DialogueGameEvent { IsToBeContinued: false })
		{
			GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnDialogueEnded);
			if (_landmarkBehaviour.IsSelected() && _landmarkBehaviour is ActionsBehaviour context)
			{
				GameManager.UIManager.DisplayPanel(context);
			}
		}
	}

	private void PopulateRescuables()
	{
		using ListPool<LandmarkRescueable>.List list = ListPool<LandmarkRescueable>.Get();
		if (_rescuableDescriptors == null)
		{
			_rescuableDescriptors = new List<ActorDescriptor>();
		}
		_landmarkBehaviour.Landmark.GetComponentsInChildren(list);
		if (Rescueables == null)
		{
			Rescueables = new List<Rescueable>();
		}
		else
		{
			Rescueables.Clear();
		}
		foreach (ActorDescriptor rescuableDescriptor in _rescuableDescriptors)
		{
			for (int i = 0; i < list.Count; i++)
			{
				LandmarkRescueable landmarkRescueable = list[i];
				if (landmarkRescueable.Spawn(rescuableDescriptor))
				{
					Rescueables.Add(new Rescueable(this, landmarkRescueable, _unlockedRescuables.Contains(rescuableDescriptor.UniqueID)));
					list.RemoveAt(i);
					break;
				}
			}
		}
		for (int j = 0; j < list.Count; j++)
		{
			LandmarkRescueable landmarkRescueable = list[j];
			_rescuableDescriptors.Add(landmarkRescueable.Spawn());
			Rescueables.Add(new Rescueable(this, landmarkRescueable));
		}
		if (base.State != ILandmarkActionStates.Completed)
		{
			return;
		}
		foreach (Rescueable rescueable in Rescueables)
		{
			if (!rescueable.IsCompleted)
			{
				SetState(ILandmarkActionStates.Inactive, dispatchEvent: false);
				break;
			}
		}
	}

	public override void UpdateState()
	{
		if (base.State == ILandmarkActionStates.Hidden || base.State == ILandmarkActionStates.Completed)
		{
			return;
		}
		bool flag = true;
		foreach (Rescueable rescueable in Rescueables)
		{
			if (!rescueable.IsCompleted)
			{
				flag = false;
				if (rescueable.IsInteractable && rescueable.IsToggled)
				{
					Activate();
					return;
				}
			}
		}
		if (flag)
		{
			SetState(ILandmarkActionStates.Completed);
		}
		else
		{
			Deactivate();
		}
	}

	protected override void OnProjectFinished(Project project, bool success)
	{
		success = true;
		foreach (Rescueable rescueable in Rescueables)
		{
			if (!rescueable.IsCompleted)
			{
				success = false;
				break;
			}
		}
		base.OnProjectFinished(project, success);
	}

	private IEnumerator PlayAttentionSoundCoroutine()
	{
		while (base.State != ILandmarkActionStates.Completed)
		{
			float seconds = UnityEngine.Random.Range(GameManager.Settings.AudioSettings.AttentionVoiceInterval.Minimum, GameManager.Settings.AudioSettings.AttentionVoiceInterval.Maximum);
			yield return new WaitForSeconds(seconds);
			using ListPool<Rescueable>.List list = ListPool<Rescueable>.Get();
			foreach (Rescueable rescueable in Rescueables)
			{
				if (rescueable.IsSeekingAttention())
				{
					list.Add(rescueable);
				}
			}
			if (list.Count == 0)
			{
				break;
			}
			list.GetRandom().SeekAttention();
		}
	}

	public void SetLandmarkRescueableActorType(ActorType rescueableActorType)
	{
		ActorType = rescueableActorType;
	}

	public void AddDescriptor(ActorDescriptor descriptor)
	{
		if (descriptor != null)
		{
			ActorType = descriptor.ActorType;
			if (_rescuableDescriptors == null)
			{
				_rescuableDescriptors = new List<ActorDescriptor>();
			}
			_rescuableDescriptors.Add(descriptor);
			_landmarkBehaviour.ScoutingId |= descriptor.ScoutingId;
		}
	}

	public void AssignDrifterQuest(QuestProperties quest)
	{
		if (_associatedQuest == null)
		{
			GameEventDispatcher.AddListener(GameEventType.QuestAbandoned, OnQuestFailed);
			GameEventDispatcher.AddListener(GameEventType.QuestFailed, OnQuestFailed);
		}
		_associatedQuest = quest;
	}

	private void OnQuestFailed(GameEvent gameEvent)
	{
		if (!(gameEvent is QuestEvent questEvent) || questEvent.Quest.Properties != _associatedQuest)
		{
			return;
		}
		GameEventDispatcher.RemoveListener(GameEventType.QuestAbandoned, OnQuestFailed);
		GameEventDispatcher.RemoveListener(GameEventType.QuestFailed, OnQuestFailed);
		_associatedQuest = null;
		if (!Rescueables.IsNullOrEmpty())
		{
			foreach (Rescueable rescueable in Rescueables)
			{
				rescueable.Agent.KillAgent();
				UnityEngine.Object.Destroy(rescueable.Agent.gameObject);
			}
			Rescueables.Clear();
		}
		if (_landmarkBehaviour is ActionsBehaviour actionsBehaviour)
		{
			actionsBehaviour.Actions.Remove(this);
		}
	}

	public override Project ReturnProject()
	{
		return new Project(base.UseBoat ? GameManager.Settings.ProjectSettings.RescueLandmark : GameManager.Settings.ProjectSettings.RescueLandmarkSwiming, _landmarkBehaviour.Landmark.ProjectTarget.gameObject);
	}

	public override void InitializeUI(LandmarkPanel landmarkPanel)
	{
		landmarkPanel.ReturnLandmarkActionUI<LandmarkActionRescueUI>().Initialize(this);
	}

	public override Sprite ReturnBearingIcon()
	{
		if ((bool)_associatedQuest)
		{
			return GameSettings.Instance.LandmarkSettings.DistressSignalBearingIcon;
		}
		if (_rescuableDescriptors.IsNullOrEmpty())
		{
			return null;
		}
		return _rescuableDescriptors[0].GetBearingIcon();
	}

	public override void Restore(LandmarkPersistentData landmarkPersistentData)
	{
		base.Restore(landmarkPersistentData);
		if (landmarkPersistentData.Behaviour.TryGetActionPersistentData<PersistentData>(out var data))
		{
			ActorType = data.ReturnActorType();
			_rescuableDescriptors = data.ReturnRescuableDescriptors();
			_associatedQuest = data.ReturnAssociatedQuest();
			_unlockedRescuables = data.UnlockedRescuables;
			AddDescriptor(data.ReturnForcedDescriptor());
		}
	}

	public override void RestoreReferences(LandmarkActionPersistentData data)
	{
		base.RestoreReferences(data);
		if (base.State != ILandmarkActionStates.Active)
		{
			return;
		}
		foreach (Rescueable rescueable in Rescueables)
		{
			if (!rescueable.IsToggled)
			{
				rescueable.Toggle();
			}
		}
	}

	public override LandmarkActionPersistentData ReturnLandmarkActionPersistentData()
	{
		return new PersistentData(this);
	}

	public bool TryGetFirstRescuableAgent(out Agent agent)
	{
		if (Rescueables != null)
		{
			foreach (Rescueable rescueable in Rescueables)
			{
				if (!rescueable.IsCompleted && rescueable.Agent != null)
				{
					agent = rescueable.Agent;
					return true;
				}
			}
		}
		agent = null;
		return false;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Landmarks/Actions/Reveal Map")]
public class LandmarkActionRevealMap : LandmarkAction, ILandmarkActionToggleable, IToggleable
{
	public string Label => base.Title;

	public override GameEventType InteractableEventType => GameEventType.LandmarkActionRevealMapInteractable;

	public bool IsInteractable => ReturnIsInteractable();

	public bool IsToggled => base.State == ILandmarkActionStates.Active;

	public bool Unlocked { get; set; } = true;

	public override void OnLandmarkSpawned(LandmarkActionPersistentData persistentData = null)
	{
		base.OnLandmarkSpawned(persistentData);
		LandmarkLookout[] componentsInChildren = _landmarkBehaviour.Landmark.GetComponentsInChildren<LandmarkLookout>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			componentsInChildren[i].IsInteractable = true;
		}
	}

	public IEnumerator Unlock()
	{
		yield break;
	}

	protected override void OnActivated()
	{
		GameEventDispatcher.AddListener(GameEventType.RegionScouted, OnMapRegionScouted);
	}

	protected override void OnDeactivated()
	{
		GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnMapRegionScouted);
	}

	protected override void OnProjectFinished(Project project, bool success)
	{
		base.OnProjectFinished(project, success);
		UnityEngine.Debug.Log("Reveal Map Option 2!");
	}

	public override void InitializeUI(LandmarkPanel landmarkPanel)
	{
		landmarkPanel.ReturnLandmarkActionUI<LandmarkActionScoutUI>().Initialize(this);
	}

	public void Toggle()
	{
		ILandmarkActionStates state = base.State;
		if (state != ILandmarkActionStates.Hidden && state != ILandmarkActionStates.Completed)
		{
			if (!IsToggled)
			{
				Activate();
			}
			else
			{
				Deactivate();
			}
		}
	}

	public bool TryReturnRequiredItemAndCost(out ItemProperties itemProperties, out int cost)
	{
		itemProperties = null;
		cost = 0;
		return false;
	}

	private void OnMapRegionScouted(GameEvent gameEvent)
	{
		GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnMapRegionScouted);
		SetState(ILandmarkActionStates.Completed);
	}
}
[CreateAssetMenu(menuName = "Flotsam/Landmarks/Actions/Salvage")]
public class LandmarkActionSalvage : LandmarkAction, ISalvageTarget
{
	public class Category : ILandmarkActionToggleable, IToggleable
	{
		private LandmarkActionSalvage _action;

		private LandmarkActionSalvageableUnlockable _unlockable;

		public string Label
		{
			get
			{
				if (!CategoryAsset)
				{
					return "No Category assigned!";
				}
				return CategoryAsset.Description;
			}
		}

		public LandmarkSalvageableCategory CategoryAsset { get; private set; }

		public List<Salvageable> Members { get; private set; }

		public bool Unlocked { get; set; }

		public bool IsInteractable => _action.ReturnIsInteractable();

		public bool IsToggled { get; private set; }

		public bool RequiresItem
		{
			get
			{
				if ((bool)CategoryAsset)
				{
					return CategoryAsset.ReturnRequiresItem();
				}
				return false;
			}
		}

		public bool RequiresAssignmentType
		{
			get
			{
				if ((bool)CategoryAsset)
				{
					return CategoryAsset.ReturnRequiresAssignmentType();
				}
				return false;
			}
		}

		public bool RequiresBuildable
		{
			get
			{
				if ((bool)CategoryAsset)
				{
					return CategoryAsset.ReturnRequiresBuildable();
				}
				return false;
			}
		}

		public bool CanBeSalvaged
		{
			get
			{
				if (Unlocked && !RequiresAssignmentType)
				{
					return !RequiresBuildable;
				}
				return false;
			}
		}

		public bool MarkedForSalvage
		{
			get
			{
				if (IsToggled)
				{
					return CanBeSalvaged;
				}
				return false;
			}
		}

		public bool IsCompleted => ReturnIsCompleted();

		public Dictionary<ItemProperties, bool> ItemFilter { get; private set; }

		public int TotalItemCount { get; private set; }

		public Category(LandmarkActionSalvage Action, Salvageable salvageable)
		{
			CategoryAsset = salvageable.CategoryAsset;
			Members = new List<Salvageable>(1);
			Unlocked = !RequiresItem;
			ItemFilter = new Dictionary<ItemProperties, bool>();
			IsToggled = false;
			_action = Action;
			TryAddMember(salvageable);
		}

		public bool TryAddMember(Salvageable salvageable)
		{
			if (CategoryAsset == salvageable.CategoryAsset)
			{
				Members.Add(salvageable);
				salvageable.Category = this;
				TotalItemCount += salvageable.ReturnCompositionCount();
				return true;
			}
			return false;
		}

		public void CountItems(InventoryAuditor auditor)
		{
			foreach (Salvageable member in Members)
			{
				member.CountItemsInComposition(auditor);
			}
		}

		public void CountSalvageableItems(InventoryAuditor auditor)
		{
			if (CanBeSalvaged)
			{
				CountItems(auditor);
			}
		}

		public void PopulateSalvageableItems(List<Item> salvageableItems, bool includeReserved)
		{
			foreach (Salvageable member in Members)
			{
				member.Instance?.Inventory.ReturnAllItems(SubInventoryType.Composition, salvageableItems, includeReserved);
			}
		}

		public bool ReturnIsCompleted()
		{
			if (!CanBeSalvaged)
			{
				return false;
			}
			foreach (Salvageable member in Members)
			{
				if (!member.Instance || !member.Instance.Inventory.ReturnIsEmpty(SubInventoryType.Composition))
				{
					return false;
				}
			}
			return true;
		}

		public List<InventoryAuditor.CountedItem> ReturnCountedItems()
		{
			InventoryAuditor global = InventoryAuditor.Global;
			global.Reset();
			foreach (Salvageable member in Members)
			{
				member.CountItemsInComposition(global);
			}
			return global.CountedItems;
		}

		public bool TryReturnRequiredItemCost(out int cost)
		{
			ItemProperties requiredItem;
			return TryReturnRequiredItemAndCost(out requiredItem, out cost);
		}

		public bool TryReturnRequiredItemAndCost(out ItemProperties requiredItem, out int cost)
		{
			requiredItem = null;
			cost = 0;
			if (CategoryAsset == null || CategoryAsset.RequiredItem.IsNullOrEmpty())
			{
				return false;
			}
			requiredItem = CategoryAsset.RequiredItem.ItemProperties;
			cost = Mathf.CeilToInt(CategoryAsset.RequiredItem.Amount * (float)Members.Count);
			return true;
		}

		public bool TryReturnSalvageItemExperience(Item item, out float experience)
		{
			if ((bool)CategoryAsset)
			{
				foreach (Salvageable member in Members)
				{
					if ((bool)member.Instance && item.Inventory == member.Instance.Inventory)
					{
						experience = CategoryAsset.SalvageItemExperience;
						return true;
					}
				}
			}
			experience = 0f;
			return false;
		}

		public void InitializeUnlockables(LandmarkActionSalvageableUnlockable[] unlockables)
		{
			foreach (LandmarkActionSalvageableUnlockable landmarkActionSalvageableUnlockable in unlockables)
			{
				if (landmarkActionSalvageableUnlockable.Initialize(this))
				{
					_unlockable = landmarkActionSalvageableUnlockable;
				}
			}
		}

		public IEnumerator Unlock()
		{
			Unlocked = true;
			if ((bool)_unlockable)
			{
				yield return _unlockable.Unlock();
			}
		}

		public void Toggle()
		{
			IsToggled = !IsToggled;
		}

		public void ToggleItemFilter(ItemProperties itemProperties)
		{
			if (ItemFilter.TryGetValue(itemProperties, out var value))
			{
				ItemFilter[itemProperties] = !value;
			}
		}

		public bool IsItemFilterToggled(ItemProperties itemProperties)
		{
			bool value;
			return ItemFilter.TryGetValue(itemProperties, out value) && value;
		}
	}

	public class Salvageable
	{
		public LandmarkSalvageableCategory CategoryAsset;

		public Category Category;

		public LandmarkSalvageable Instance;

		public int VariationIndex;

		public CountedItemProperty[] Composition;

		public CountedItemProperty[] CompositionItems;

		public Salvageable(LandmarkSalvageable landmarkSalvageable)
		{
			VariationIndex = landmarkSalvageable.ReturnRandomVariationIndex();
			CategoryAsset = landmarkSalvageable.ReturnCategoryAsset(VariationIndex);
			Composition = landmarkSalvageable.ReturnAssetComposition(VariationIndex).ToArray();
			CompositionItems = Composition;
		}

		public Salvageable(LandmarkSalvageable landmarkSalvageable, int variationIndex, CountedItemProperty[] compositionItems)
		{
			CategoryAsset = landmarkSalvageable.Category;
			VariationIndex = variationIndex;
			Composition = landmarkSalvageable.ReturnAssetComposition(variationIndex).ToArray();
			CompositionItems = compositionItems;
		}

		public void CountItemsInComposition(InventoryAuditor auditor)
		{
			if ((bool)Instance)
			{
				Instance.CountItemsInComposition(auditor);
			}
			else
			{
				auditor.CountItemProperties(CompositionItems);
			}
		}

		public int ReturnCompositionCount()
		{
			if (((IReadOnlyCollection<CountedItemProperty>)(object)Composition).IsNullOrEmpty())
			{
				return 0;
			}
			int num = 0;
			CountedItemProperty[] composition = Composition;
			foreach (CountedItemProperty countedItemProperty in composition)
			{
				num += countedItemProperty.Amount;
			}
			return num;
		}
	}

	[SerializeField]
	private LandmarkActionSalvageUINew _uiPrefab;

	[SerializeField]
	private LocalizedString _categoriesLockedTooltip;

	private InventoryAuditor _auditor;

	private List<Salvageable> _salvageables;

	private Coroutine _compositionUpdatedCoroutine;

	public UnityEvent CompositionUpdated { get; private set; }

	public int AgentLimit { get; private set; } = 1;

	public Dictionary<ItemProperties, bool> ItemFilter { get; private set; }

	public override GameEventType InteractableEventType => GameEventType.LandmarkActionSalvageInteractable;

	public List<Category> Categories { get; private set; }

	public override void Initialize(LandmarkBehaviour landmarkBehaviour)
	{
		base.Initialize(landmarkBehaviour);
		_salvageables = new List<Salvageable>();
		Categories = new List<Category>();
	}

	public override void Restore(LandmarkPersistentData landmarkPersistentData)
	{
		if (!landmarkPersistentData.TryReturnLandmarkInteractablePersistentData<LandmarkSalvageablePersistentData>(out var persistentData))
		{
			return;
		}
		using ListPool<LandmarkSalvageable>.List list = ListPool<LandmarkSalvageable>.Get();
		_landmarkBehaviour.LandmarkPrefabGameObject.GetComponentsInChildren(list);
		for (int i = 0; i < list.Count; i++)
		{
			LandmarkSalvageable landmarkSalvageable = list[i];
			int variationIndex;
			CountedItemProperty[] compositionItems;
			Salvageable salvageable = ((!persistentData.TryReturnVariationIndexAndCompositionItems(i, out variationIndex, out compositionItems)) ? new Salvageable(landmarkSalvageable) : new Salvageable(landmarkSalvageable, variationIndex, compositionItems));
			_salvageables.Add(salvageable);
			AddSalvageableToCategory(salvageable);
		}
	}

	public override void OnLandmarkSpawned(LandmarkActionPersistentData persistentData = null)
	{
		base.OnLandmarkSpawned(persistentData);
		using ListPool<LandmarkSalvageable>.List list = ListPool<LandmarkSalvageable>.Get();
		_landmarkBehaviour.Landmark.GetComponentsInChildren(list);
		ItemFilter = new Dictionary<ItemProperties, bool>();
		int count = list.Count;
		InventoryAuditor.Global.Reset();
		for (int i = 0; i < count; i++)
		{
			LandmarkSalvageable landmarkSalvageable = list[i];
			Salvageable salvageable = ((i >= _salvageables.Count) ? AddSalvageable(landmarkSalvageable) : _salvageables[i]);
			salvageable.Instance = landmarkSalvageable;
			landmarkSalvageable.InitializeComposition(salvageable.VariationIndex, salvageable.CompositionItems);
			landmarkSalvageable.IsInteractable = true;
			landmarkSalvageable.CompositionUpdatedEvent += SalvageableCompositionUpdatedEvent;
			landmarkSalvageable.InitializeItemFilter(salvageable.Category.ItemFilter);
			landmarkSalvageable.CountComposition(InventoryAuditor.Global);
		}
		Sorting.SlowSort(Categories, CompareCategories);
		if (persistentData == null)
		{
			foreach (Category category in Categories)
			{
				category.InitializeUnlockables(_landmarkBehaviour.Landmark.Unlockables);
			}
		}
		CompositionUpdated = new UnityEvent();
	}

	private Salvageable AddSalvageable(LandmarkSalvageable landmarkSalvageable)
	{
		Salvageable salvageable = new Salvageable(landmarkSalvageable);
		_salvageables.Add(salvageable);
		AddSalvageableToCategory(salvageable);
		return salvageable;
	}

	public override void Uninitialize()
	{
		base.Uninitialize();
		if (_salvageables == null)
		{
			return;
		}
		foreach (Salvageable salvageable in _salvageables)
		{
			if (!(salvageable.Instance == null))
			{
				salvageable.Instance.CompositionUpdatedEvent -= SalvageableCompositionUpdatedEvent;
				salvageable.CompositionItems = salvageable.Instance.ReturnComposition();
			}
		}
	}

	public override void UpdateState()
	{
		using ListPool<Item>.List list = ReturnSalvageableItems();
		bool flag = 0 < list.Count;
		if (base.State == ILandmarkActionStates.Inactive && flag)
		{
			Activate();
		}
		else if (base.State == ILandmarkActionStates.Active && !flag)
		{
			Deactivate();
		}
		else if (flag)
		{
			AssignItemsToHaul();
		}
	}

	protected override void OnCompleted()
	{
		foreach (Salvageable salvageable in _salvageables)
		{
			if (!(salvageable.Instance == null))
			{
				salvageable.Instance.CompositionUpdatedEvent -= SalvageableCompositionUpdatedEvent;
			}
		}
	}

	private void SalvageableCompositionUpdatedEvent(float progress)
	{
		if (_compositionUpdatedCoroutine == null)
		{
			_compositionUpdatedCoroutine = _landmarkBehaviour.Landmark.StartCoroutine(CompositionUpdatedCoroutine());
		}
	}

	private IEnumerator CompositionUpdatedCoroutine()
	{
		yield return new WaitForEndOfFrame();
		CompositionUpdated.Invoke();
		base.UpdatedEvent.Invoke(this);
		if (IsLandmarkSalvaged())
		{
			OnProjectFinished(base.Project, success: true);
		}
		_compositionUpdatedCoroutine = null;
	}

	public override void CountItems(InventoryAuditor auditor, Landmark landmark)
	{
		foreach (Salvageable salvageable in _salvageables)
		{
			salvageable.CountItemsInComposition(auditor);
		}
	}

	private void AddSalvageableToCategory(Salvageable salvageable)
	{
		foreach (Category category in Categories)
		{
			if (category.TryAddMember(salvageable))
			{
				return;
			}
		}
		Categories.Add(new Category(this, salvageable));
	}

	private int CompareCategories(Category left, Category right)
	{
		if (left.CategoryAsset == null)
		{
			return 1;
		}
		if (right.CategoryAsset == null)
		{
			return -1;
		}
		return left.CategoryAsset.UIOrder - right.CategoryAsset.UIOrder;
	}

	private void AssignItemsToHaul()
	{
		if (base.Project == null)
		{
			return;
		}
		foreach (ProjectAssignment assignment in base.Project.Assignments)
		{
			if ((assignment.Flags & ProjectAssignmentFlags.Salvaging) != ProjectAssignmentFlags.None)
			{
				PopulateItemsToHaul(assignment);
			}
		}
	}

	public override Project ReturnProject()
	{
		return new Project(base.UseBoat ? GameManager.Settings.ProjectSettings.SalvagePOIProperties : GameManager.Settings.ProjectSettings.SalvagePOISwimProperties, _landmarkBehaviour.Landmark.gameObject, this)
		{
			AssignmentLimit = base.AssignmentLimit
		};
	}

	protected override void OnProjectFinished(Project project, bool success)
	{
		success = AreAllCategoriesUnlocked() && ReturnIsCompleted();
		base.OnProjectFinished(project, success);
	}

	public override void InitializeUI(LandmarkPanel landmarkPanel)
	{
		landmarkPanel.ReturnLandmarkActionUI<LandmarkActionSalvageUINew>().Initialize(this);
	}

	public List<InventoryAuditor.CountedItem> ReturnCountedSalvageableItems()
	{
		if (_auditor == null)
		{
			_auditor = new InventoryAuditor();
		}
		else
		{
			_auditor.Reset();
		}
		foreach (Category category in Categories)
		{
			category.CountSalvageableItems(_auditor);
		}
		return _auditor.CountedItems;
	}

	public bool IsLandmarkSalvaged()
	{
		foreach (Category category in Categories)
		{
			if (!category.Unlocked)
			{
				return false;
			}
		}
		List<InventoryAuditor.CountedItem> list = ReturnCountedSalvageableItems();
		for (int i = 0; i < list.Count; i++)
		{
			if (list[i].UnreservedCount + list[i].ReservedCount > 0)
			{
				return false;
			}
		}
		return true;
	}

	private ListPool<Item>.List ReturnSalvageableItems(bool includeReserved = true, bool markedForSalvageOnly = true)
	{
		ListPool<Item>.List list = ListPool<Item>.Get();
		foreach (Category category in Categories)
		{
			if (!markedForSalvageOnly || category.MarkedForSalvage)
			{
				category.PopulateSalvageableItems(list, includeReserved);
			}
		}
		return list;
	}

	private bool ReturnIsCompleted()
	{
		foreach (Category category in Categories)
		{
			if (!category.ReturnIsCompleted())
			{
				return false;
			}
		}
		return true;
	}

	public override bool TryReturnInteractableTooltip(out LocalizedString tooltip)
	{
		if (ReturnIsInteractable() || AreAllCategoriesUnlocked())
		{
			tooltip = default(LocalizedString);
		}
		else
		{
			tooltip = _categoriesLockedTooltip;
		}
		return (string)tooltip != null;
	}

	public bool AreAllCategoriesUnlocked()
	{
		foreach (Category category in Categories)
		{
			if (!category.Unlocked)
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnIsAnyCategoryToggled()
	{
		foreach (Category category in Categories)
		{
			if (category.IsToggled)
			{
				return true;
			}
		}
		return false;
	}

	public void PopulateItemsToHaul(ProjectAssignment assignment)
	{
		Item itemToSalvage;
		while (TryReturnClosestSalvageableItem(out itemToSalvage, assignment) && assignment.AddItemToHaul(itemToSalvage))
		{
		}
	}

	public int PopulateItemList(Itemlist itemlist)
	{
		int num = 0;
		foreach (InventoryAuditor.CountedItem item in ReturnCountedSalvageableItems())
		{
			if (item.UnreservedCount != 0 && itemlist.TryAddUniqueItemSlot(num, item.ItemProperties))
			{
				num++;
			}
		}
		return num;
	}

	private bool TryReturnClosestSalvageableItem(out Item itemToSalvage, ProjectAssignment assignment)
	{
		ListPool<Item>.List list = ReturnSalvageableItems(includeReserved: false);
		itemToSalvage = null;
		using (list)
		{
			if (list.Count == 0)
			{
				return false;
			}
			ReserveFillInventory.SortedItemsByDistanceFromMooringpoint(assignment.Agent, assignment.Project, list);
			if (assignment.RequiresStorageSpace)
			{
				foreach (Item item in list)
				{
					if (assignment.Agent.Community.Inventory.FitsItem(item))
					{
						itemToSalvage = item;
						break;
					}
				}
			}
			else
			{
				itemToSalvage = list[0];
			}
			return itemToSalvage != null;
		}
	}

	public void ToggleItemFilter(ItemProperties itemProperties)
	{
		if (ItemFilter.TryGetValue(itemProperties, out var value))
		{
			ItemFilter[itemProperties] = !value;
		}
	}

	public ProjectBlocker ReturnProjectBlockers(Project project)
	{
		CommunityInventory inventory = Community.PlayerCommunity.Inventory;
		bool requiresGeneralStorageSpace = project.Properties.RequiresGeneralStorageSpace;
		int num = 0;
		foreach (InventoryAuditor.CountedItem item in ReturnCountedSalvageableItems())
		{
			if (item.UnreservedCount != 0)
			{
				if (!requiresGeneralStorageSpace || inventory.ReturnFitsItemWithProperties(item.ItemProperties))
				{
					return ProjectBlocker.None;
				}
				num += item.UnreservedCount;
			}
		}
		if (0 >= num)
		{
			return ProjectBlocker.SharableEmptyItemList;
		}
		return ProjectBlocker.StorageSpace;
	}

	public bool ReturnIsSalvageableItem(Item item)
	{
		using ListPool<Item>.List list = ReturnSalvageableItems();
		return list.Contains(item);
	}

	public bool ReturnIsSalvageableItem(ItemProperties itemProperties)
	{
		using (ListPool<Item>.List list = ReturnSalvageableItems())
		{
			foreach (Item item in list)
			{
				if (item.Properties == itemProperties)
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool ReturnIsItemFilterToggled(ItemProperties itemProperties)
	{
		if (ItemFilter.TryGetValue(itemProperties, out var value))
		{
			return value;
		}
		return false;
	}

	public bool ReturnHasSalvageableItems(Project project, Agent agent)
	{
		using ListPool<Item>.List list = ReturnSalvageableItems(includeReserved: false);
		return 0 < list.Count && (!project.Properties.RequiresGeneralStorageSpace || agent.Community.Inventory.ReturnFitsAnyItem(list));
	}

	public bool ReturnHasCompletedCategory()
	{
		if (Categories.IsNullOrEmpty())
		{
			return true;
		}
		foreach (Category category in Categories)
		{
			if (category.IsCompleted)
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnIsSalvaged()
	{
		foreach (Category category in Categories)
		{
			if (category.IsToggled && !category.ReturnIsCompleted())
			{
				return false;
			}
		}
		return true;
	}

	public float ReturnSalvageItemExperience(Item item)
	{
		foreach (Category category in Categories)
		{
			if (category.TryReturnSalvageItemExperience(item, out var experience))
			{
				return experience;
			}
		}
		return 0f;
	}

	public override float ReturnProgress()
	{
		if (Categories.IsNullOrEmpty())
		{
			return 0f;
		}
		InventoryAuditor.Global.Reset();
		float num = 0f;
		foreach (Category category in Categories)
		{
			if (!category.RequiresAssignmentType && !category.RequiresBuildable)
			{
				num += (float)category.TotalItemCount;
				category.CountItems(InventoryAuditor.Global);
			}
		}
		if (num != 0f)
		{
			return 1f - (float)InventoryAuditor.Global.TotalItemCount / num;
		}
		return 1f;
	}

	public override LandmarkActionPersistentData ReturnLandmarkActionPersistentData()
	{
		return new LandmarkActionSalvagePersistentData(this);
	}

	public override void Restore(LandmarkActionPersistentData data, LandmarkBehaviour landmarkBehaviour)
	{
		base.Restore(data, landmarkBehaviour);
		LandmarkActionSalvagePersistentData landmarkActionSalvagePersistentData = data as LandmarkActionSalvagePersistentData;
		SetAssignmentLimit(landmarkActionSalvagePersistentData.AgentLimit);
	}

	public override void RestoreReferences(LandmarkActionPersistentData data)
	{
		base.RestoreReferences(data);
		if (!(data is LandmarkActionSalvagePersistentData landmarkActionSalvagePersistentData))
		{
			return;
		}
		if (base.Project != null)
		{
			base.Project.SalvageTarget = this;
		}
		SetAssignmentLimit(base.AssignmentLimit);
		if (landmarkActionSalvagePersistentData.ItemFilter != null)
		{
			landmarkActionSalvagePersistentData.ItemFilter.Restore(ItemFilter);
		}
		foreach (Category category in Categories)
		{
			category.Unlocked = category.Unlocked || landmarkActionSalvagePersistentData.IsCategoryUnlocked(category.CategoryAsset);
			category.InitializeUnlockables(_landmarkBehaviour.Landmark.Unlockables);
			if (category.IsToggled != landmarkActionSalvagePersistentData.IsCategoryToggled(category.CategoryAsset))
			{
				category.Toggle();
			}
			landmarkActionSalvagePersistentData.RestoreCategoryItemFilter(category.CategoryAsset, category.ItemFilter);
			if (!category.IsCompleted && base.State == ILandmarkActionStates.Completed)
			{
				SetState(ILandmarkActionStates.Inactive, dispatchEvent: false);
				UnityEngine.Debug.LogException(new Exception("LandmarkActionSalavge for landmark " + _landmarkBehaviour.name + " state was persisted as 'Completed', but category '" + category.Label + "' is not yet completed. Setting LandmarkAction state to 'Inactive'"));
			}
		}
	}
}
