[CreateAssetMenu(menuName = "Flotsam/Landmarks/ActionsBehaviour")]
public class ActionsBehaviour : LandmarkBehaviour, IPanelContext, IWorldMapMarkerTarget
{
	[Header("Actions")]
	[SerializeField]
	private LandmarkAction[] _actions;

	private LandmarkAction _markerAction;

	public List<LandmarkAction> Actions { get; private set; }

	public bool UseBoat
	{
		get
		{
			foreach (LandmarkAction action in Actions)
			{
				if (!action.UseBoat)
				{
					return false;
				}
			}
			return true;
		}
		set
		{
			foreach (LandmarkAction action in Actions)
			{
				action.UseBoat = value;
			}
		}
	}

	public int AssignmentLimitMinimum
	{
		get
		{
			int num = int.MaxValue;
			foreach (LandmarkAction action in Actions)
			{
				num = Mathf.Min(num, action.AssignmentLimitMinimum);
			}
			return num;
		}
	}

	public int AssignmentLimitMaximum
	{
		get
		{
			int num = 0;
			foreach (LandmarkAction action in Actions)
			{
				num = Mathf.Max(num, action.AssignmentLimitMaximum);
			}
			return num;
		}
	}

	public int AssignmentLimit
	{
		get
		{
			int num = 0;
			foreach (LandmarkAction action in Actions)
			{
				num = Mathf.Max(num, action.AssignmentLimit);
			}
			return num;
		}
	}

	public PanelID PanelID => PanelID.LandmarkPanel;

	Vector3 IWorldMapMarkerTarget.LocalPosition
	{
		get
		{
			if (!base.Landmark)
			{
				return Vector3.zero;
			}
			return base.Landmark.transform.position;
		}
	}

	Sprite IWorldMapMarkerTarget.Icon
	{
		get
		{
			if (!(_markerAction != null))
			{
				return null;
			}
			return _markerAction.Icon;
		}
	}

	public override void Initialize()
	{
		base.Initialize();
		Actions = new List<LandmarkAction>(_actions.Length);
		LandmarkAction[] actions = _actions;
		foreach (LandmarkAction landmarkAction in actions)
		{
			if (landmarkAction is LandmarkActionScout || landmarkAction is LandmarkActionRevealMap)
			{
				base.RequiresScouting = true;
			}
			LandmarkAction landmarkAction2 = UnityEngine.Object.Instantiate(landmarkAction);
			landmarkAction2.Initialize(this);
			Actions.Add(landmarkAction2);
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
	}

	public override void Restore(LandmarkPersistentData landmarkPersistentData)
	{
		foreach (LandmarkAction action in Actions)
		{
			action.Restore(landmarkPersistentData);
		}
	}

	public override void SpawnLandmark(Vector3 position, Quaternion rotation, Transform parent = null)
	{
		base.SpawnLandmark(position, rotation, parent);
		foreach (LandmarkAction action in Actions)
		{
			action.OnLandmarkSpawned();
		}
	}

	public override void OnLandmarkSpawnedOrRestored()
	{
		foreach (LandmarkAction action in Actions)
		{
			action.UpdatedEvent?.AddListener(OnActionUpdated);
		}
	}

	public override void DestroyLandmark()
	{
		base.DestroyLandmark();
		foreach (LandmarkAction action in Actions)
		{
			action.UpdatedEvent?.RemoveListener(OnActionUpdated);
			action.Uninitialize();
		}
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
	}

	protected override bool DispatchInteractableEvent()
	{
		if (!base.DispatchInteractableEvent())
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			GameEventDispatcher.Dispatch(action.InteractableEventType);
		}
		return true;
	}

	protected override void BeginInteraction()
	{
		throw new NotImplementedException();
	}

	public override void OnSelected(bool playSelectionSound)
	{
		foreach (LandmarkAction action in Actions)
		{
			action.OnLandmarkSelected();
		}
		FinalUpdate.RegisterEndOfFrameOneShot(TryOpenLandmarkPanel);
	}

	private void TryOpenLandmarkPanel()
	{
		if (GameManager.UIManager.IsPanelOpen(PanelID.DialoguePanel))
		{
			GameEventDispatcher.AddListener(GameEventType.PanelClosed, OnPanelClosed);
		}
		else
		{
			OnPanelClosed();
		}
	}

	private void OnPanelClosed(GameEvent gameEvent = null)
	{
		if (gameEvent == null || gameEvent is PanelEvent { ID: PanelID.DialoguePanel })
		{
			GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
			GameManager.UIManager.DisplayPanel(this);
		}
	}

	public override void OnDeselected()
	{
		GameManager.UIManager.ClosePanel(PanelID);
		foreach (LandmarkAction action in Actions)
		{
			action.OnLandmarkDeselected();
		}
	}

	private void OnActionUpdated(ILandmarkAction action)
	{
		if (base.UpdatedEvent != null)
		{
			base.UpdatedEvent.Invoke(this, action);
		}
		UpdateMarkerAction();
	}

	public override void CountItems(InventoryAuditor auditor, Landmark landmark)
	{
		LandmarkAction[] actions = _actions;
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].CountItems(auditor, landmark);
		}
	}

	public void SetAssignmentLimit(int limit)
	{
		foreach (LandmarkAction action in Actions)
		{
			action.SetAssignmentLimit(limit);
		}
	}

	public void Activate()
	{
		foreach (LandmarkAction action in Actions)
		{
			action.Activate();
		}
	}

	public void Deactivate()
	{
		foreach (LandmarkAction action in Actions)
		{
			action.Deactivate();
		}
	}

	public bool TrySetActionActive(GameEventType actionToActivate, bool active)
	{
		foreach (LandmarkAction action in Actions)
		{
			if (action.InteractableEventType == actionToActivate)
			{
				if (active)
				{
					action.Activate();
				}
				else
				{
					action.Deactivate();
				}
				return true;
			}
		}
		return false;
	}

	private void UpdateMarkerAction()
	{
		_markerAction = null;
		foreach (LandmarkAction action in Actions)
		{
			if (action.State == ILandmarkActionStates.Active && (_markerAction == null || _markerAction.MarkerPriority < action.MarkerPriority))
			{
				_markerAction = action;
			}
		}
		if (_markerAction == null)
		{
			WorldMapManager.DestroyMarker(this);
		}
		else
		{
			WorldMapManager.InstantiateMarker(this);
		}
	}

	public override bool ReturnIsInteractable()
	{
		if (Actions.IsNullOrEmpty())
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (!action.ReturnIsInteractable())
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnHasInactiveActions()
	{
		if (Actions == null)
		{
			return true;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (action.State == ILandmarkActionStates.Inactive)
			{
				return true;
			}
		}
		return false;
	}

	public override bool ReturnIsActive()
	{
		if (Actions == null)
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (action.State != ILandmarkActionStates.Active)
			{
				return false;
			}
		}
		return true;
	}

	public override bool ReturnIsCompleted()
	{
		if (Actions.IsNullOrEmpty())
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (!action.IsCompleted)
			{
				return false;
			}
		}
		return true;
	}

	public override float ReturnProgress()
	{
		if (Actions == null)
		{
			return 0f;
		}
		float num = 1f / (float)Actions.Count;
		float num2 = 0f;
		foreach (LandmarkAction action in Actions)
		{
			num2 += num * ((ILandmarkAction)action).ReturnProgress();
		}
		return num2;
	}

	public bool ReturnHasAction<T>() where T : LandmarkAction
	{
		if (Actions == null)
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (!action.IsCompleted && action is T)
			{
				return true;
			}
		}
		return false;
	}

	public bool TryReturnAction<T>(out T action, bool includeCompleted = false) where T : LandmarkAction
	{
		if (TryReturnAction(out var action2, typeof(T), includeCompleted))
		{
			action = action2 as T;
			return true;
		}
		action = null;
		return false;
	}

	public bool TryReturnAction(out LandmarkAction action, Type actionType, bool includeCompleted = false)
	{
		action = null;
		if (Actions == null)
		{
			return false;
		}
		foreach (LandmarkAction action2 in Actions)
		{
			if (action2.GetType() == actionType && (includeCompleted || !action2.IsCompleted))
			{
				action = action2;
				return true;
			}
		}
		return false;
	}

	public override Sprite ReturnBearingIcon()
	{
		foreach (LandmarkAction action in Actions)
		{
			Sprite sprite = action.ReturnBearingIcon();
			if (sprite != null)
			{
				return sprite;
			}
		}
		return base.ReturnBearingIcon();
	}

	public bool ReturnHasLandmarkAction(LandmarkAction action)
	{
		LandmarkAction action2;
		return TryReturnAction(out action2, action.GetType());
	}

	public bool ReturnHasLandmarkAction(GameEventType actionType)
	{
		if (Actions == null)
		{
			return false;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (action.InteractableEventType == actionType && !action.IsCompleted)
			{
				return true;
			}
		}
		return false;
	}

	public override bool ReturnHasLandmarkActionReference<T>()
	{
		LandmarkAction[] actions = _actions;
		for (int i = 0; i < actions.Length; i++)
		{
			if (actions[i] is T)
			{
				return true;
			}
		}
		return false;
	}

	public override bool RequiresPersistence()
	{
		if ((bool)base.Landmark)
		{
			return true;
		}
		foreach (LandmarkAction action in Actions)
		{
			if (action.RequiresPersistence)
			{
				return true;
			}
		}
		return false;
	}
}
public interface ILandmarkBehaviourProvider
{
	string Name { get; }

	string EditorName { get; }

	Sprite EditorIcon { get; }

	float Radius { get; }

	LandmarkBehaviour ReturnLandmarkBehaviour(WorldRegionType region);

	MooringPointBase[] ReturnMooringPoints();

	bool ReturnIsInteractable();

	bool ReturnHasLandmarkActionReference<T>() where T : LandmarkAction;

	bool ReturnIsLandmarkBehaviour(LandmarkBehaviour behaviour);
}
public abstract class LandmarkBehaviour : PersistentProperties, ILandmarkBehaviourProvider, ITooltipProvider
{
	public class Event : UnityEvent<LandmarkBehaviour, object>
	{
	}

	private const float CLEARANCE_BUFFER = 10f;

	[Header("Landmark")]
	[SerializeField]
	[FormerlySerializedAs("Name")]
	private LocalizedString _name = "";

	public LocalizedString Description = "";

	[SerializeField]
	private Landmark _landmarkPrefab;

	[SerializeField]
	private LandmarkFeature _primaryLandmarkFeature;

	[SerializeField]
	internal Sprite _uiIcon;

	public float MapAvoidanceRadius = 75f;

	[Header("Audio")]
	public AudioClipProperties landmarkMusic;

	[Header("Misc")]
	public WorldMapLandmark MapPrefab;

	[Header("Scouting")]
	public WorldMapScoutingId ScoutingId;

	[FormerlySerializedAs("BearingIcon")]
	[SerializeField]
	private Sprite _bearingIcon;

	[Header("Pollution")]
	[SerializeField]
	[Min(0f)]
	private float _pollutionPerDay;

	protected SelectionLink _selectionLink;

	private Vector3 _spawnPosition;

	private bool _isScouted;

	public override Types Type => Types.LandmarkBehaviour;

	public string Name => _name;

	public LandmarkBehaviour Prefab { get; private set; }

	public Landmark Landmark { get; private set; }

	public bool RequiresScouting { get; protected set; }

	public bool IsScouted
	{
		get
		{
			if (RequiresScouting)
			{
				return _isScouted;
			}
			return true;
		}
	}

	public bool IsInteracting { get; private set; }

	public bool IsPanelOpen { get; set; }

	public static bool IsCameraLocked { get; set; }

	public Agent Actor { get; private set; }

	public Event UpdatedEvent { get; private set; }

	public LandmarkFeature PrimaryLandmarkFeature => _primaryLandmarkFeature;

	public float Radius => _landmarkPrefab.ScoutRadius;

	public GameObject LandmarkPrefabGameObject => _landmarkPrefab.gameObject;

	public string EditorName => base.name;

	public Sprite EditorIcon => null;

	public float PollutionPerDay => _pollutionPerDay;

	private void Awake()
	{
		_isScouted = false;
	}

	public virtual void Initialize()
	{
		if (UpdatedEvent == null)
		{
			UpdatedEvent = new Event();
		}
		else
		{
			UpdatedEvent.RemoveAllListeners();
		}
	}

	public virtual void Restore(LandmarkPersistentData persistentData)
	{
	}

	protected Landmark InstantiateLandmark(Vector3 position, Quaternion rotation, Transform parent = null)
	{
		Landmark = UnityEngine.Object.Instantiate(_landmarkPrefab, position, rotation, parent);
		Landmark.Initialize(this);
		if (Landmark.IsInteractable)
		{
			_selectionLink = Landmark.GetComponentInChildren<SelectionLink>(includeInactive: true);
			_selectionLink.SetObjectToSelect(Landmark.gameObject, ObjectType.Landmark);
			_selectionLink.SetOnCursorStayListener(OnUnderCursor);
			_selectionLink.SetOnShowTooltipListener(OnShowTooltip);
			_selectionLink.SetOnSelectedListener(OnSelected);
			_selectionLink.SetOnDeselectedListener(OnDeselected);
		}
		IsInteracting = false;
		IsPanelOpen = false;
		IsCameraLocked = false;
		return Landmark;
	}

	public virtual void OnLandmarkSpawnedOrRestored()
	{
	}

	public virtual void DestroyLandmark()
	{
		Selector.Deselect(_selectionLink);
		if (Landmark == null)
		{
			return;
		}
		LandmarkMooringPoint[] mooringPoints = Landmark.MooringPoints;
		foreach (LandmarkMooringPoint landmarkMooringPoint in mooringPoints)
		{
			if ((bool)landmarkMooringPoint.MooredBoat)
			{
				UnityEngine.Debug.LogErrorFormat("'{0}' is moored at a Landmark '{1}' that is being destroyed. This is a whale of a bug!", landmarkMooringPoint.MooredBoat.Buildable.Name, Name);
				landmarkMooringPoint.MooredBoat.ResetToTown();
			}
		}
		LandmarkNotificationEvent.Remove(this);
		UnityEngine.Object.Destroy(Landmark.gameObject);
	}

	private void OnDestroy()
	{
		if (UpdatedEvent != null)
		{
			UpdatedEvent.RemoveAllListeners();
		}
	}

	public bool Validate()
	{
		if ((bool)_landmarkPrefab)
		{
			return true;
		}
		UnityEngine.Debug.LogErrorFormat("Landmark Prefab for LandmarkBehaviour '{0}' is null!", base.name);
		return false;
	}

	public virtual void SpawnLandmark(Vector3 position, Quaternion rotation, Transform parent = null)
	{
		InstantiateLandmark(position, rotation, parent);
		Landmark.InitializeInteractables();
		if (0f < _pollutionPerDay)
		{
			Landmark.gameObject.AddComponent<LandmarkPollution>();
		}
		DispatchInteractableEvent();
	}

	public Landmark RestoreLandmark(LandmarkPersistentData persistentData, Vector3 position, Quaternion rotation, Transform parent = null)
	{
		InstantiateLandmark(position, rotation, parent);
		if (persistentData.Interactables != null)
		{
			ILandmarkInteractablePersistentData[] interactables = persistentData.Interactables;
			for (int i = 0; i < interactables.Length; i++)
			{
				interactables[i].Restore(Landmark);
			}
		}
		else
		{
			Landmark.InitializeRescueables();
		}
		if (persistentData.Behaviour != null)
		{
			persistentData.Behaviour.Restore(this as ActionsBehaviour);
		}
		return Landmark;
	}

	public void SetPositionAndRotation(Vector3 position, Quaternion rotation)
	{
		if (!(Landmark == null))
		{
			Landmark.transform.position = position + Landmark.PositionOffset;
			Landmark.transform.rotation = rotation;
			DispatchInteractableEvent();
		}
	}

	protected virtual bool DispatchInteractableEvent()
	{
		if ((bool)Landmark && WorldManager.IsInInteractionRadius(Landmark.transform.position))
		{
			GameEventDispatcher.Dispatch(GameEventType.LandmarkInteractable);
			return true;
		}
		return false;
	}

	public bool Interact(Agent agent)
	{
		if (!IsPanelOpen && IsInteracting && Actor != null)
		{
			BeginInteraction();
			IsPanelOpen = true;
			return false;
		}
		if (IsInteracting)
		{
			return false;
		}
		IsInteracting = true;
		Actor = agent;
		Landmark.StartCoroutine(InteractCoroutine(agent));
		return true;
	}

	private IEnumerator InteractCoroutine(Agent agent)
	{
		while (Selector.Selection != agent.SelectionLink && Selector.Selection != _selectionLink)
		{
			yield return null;
		}
		BeginInteraction();
	}

	protected abstract void BeginInteraction();

	public virtual void EndInteraction()
	{
		Actor = null;
		IsInteracting = false;
	}

	public void SetScouted()
	{
		_isScouted = true;
		UpdatedEvent.Invoke(this, this);
	}

	public void CountItems(InventoryAuditor auditor)
	{
		CountItems(auditor, _landmarkPrefab);
	}

	public abstract void CountItems(InventoryAuditor auditor, Landmark landmark);

	public int ReturnMooringPointCount()
	{
		if ((bool)Landmark)
		{
			return Landmark.MooringPoints.Length;
		}
		UnityEngine.Debug.LogError("This line should never be reached...");
		return _landmarkPrefab.GetComponentsInChildren<LandmarkMooringPoint>(includeInactive: true).Length;
	}

