	}

	public bool ReturnMatchesScoutingFilter(WorldMapScoutingId filter)
	{
		if (ScoutingId == WorldMapScoutingId.None)
		{
			return false;
		}
		if (filter == WorldMapScoutingId.None)
		{
			return true;
		}
		return (ScoutingId & filter) == ScoutingId;
	}

