public class LandmarkSalvageable : LandmarkInteractableWithComposition
{
	[Header("Visual Prefab")]
	[SerializeField]
	[NestedReference]
	private VisualPrefab _visualPrefab;

	[SerializeField]
	private bool _destroyOnEmpty = true;

	[SerializeField]
	private LandmarkSalvageableCategory _category;

	[SerializeField]
	private LandmarkSalvageable[] _variations;

	public VisualPrefab VisualPrefab { get; private set; }

	public LandmarkSalvageableCategory Category { get; private set; }

	public int VariationIndex { get; private set; }

	public void InitializeComposition(int variationIndex, CountedItemProperty[] composition = null)
	{
		SetVariationIndex(variationIndex);
		InitializeInventory(composition);
		InitializeVisualPrefab();
	}

	public void Restore(InventoryPersistentData inventoryToPersist, int variationIndex)
	{
		SetVariationIndex((((IReadOnlyCollection<LandmarkSalvageable>)(object)_variations).IsNullOrEmpty() || _variations.Length <= variationIndex) ? (-1) : variationIndex);
		RestoreInventory(inventoryToPersist);
		InitializeVisualPrefab();
	}

	protected override void OnDestroy()
	{
		base.OnDestroy();
		if ((bool)base.Inventory)
		{
			base.Inventory.CompositionUpdatedEvent -= OnCompositionUpdated;
		}
	}

	public void InitializeItemFilter(Dictionary<ItemProperties, bool> itemFilter)
	{
		foreach (Item item in _compositionInventory.ReturnAllItems())
		{
			if (!itemFilter.ContainsKey(item.Properties))
			{
				itemFilter.Add(item.Properties, value: true);
			}
		}
	}

	protected override void OnCompositionUpdated(float progress)
	{
		if ((bool)VisualPrefab)
		{
			VisualPrefab.SetProgress(progress);
			if (_destroyOnEmpty && progress == 0f)
			{
				if (_visualPrefab.gameObject.scene.isLoaded)
				{
					UnityEngine.Object.Destroy(VisualPrefab.gameObject);
				}
				else
				{
					UnityEngine.Debug.LogErrorFormat("LandmarkSalvageable '{0}' its VisualPrefabs is referencing an asset instead of the nested GameObject. Please FIX NOW!", base.name);
				}
			}
		}
		base.OnCompositionUpdated(progress);
	}

	private void SetVariationIndex(int variationIndex)
	{
		VariationIndex = variationIndex;
		if (variationIndex < 0)
		{
			VisualPrefab = _visualPrefab;
			Category = _category;
			Initialize(null);
			return;
		}
		_visualPrefab.gameObject.SetActive(value: false);
		LandmarkSalvageable landmarkSalvageable = _variations[variationIndex];
		VisualPrefab = UnityEngine.Object.Instantiate(landmarkSalvageable._visualPrefab, _visualPrefab.transform.parent);
		VisualPrefab.transform.localPosition = _visualPrefab.transform.localPosition;
		VisualPrefab.transform.localRotation = _visualPrefab.transform.localRotation;
		VisualPrefab.transform.localScale = _visualPrefab.transform.localScale;
		Category = landmarkSalvageable._category;
		base.Composition = landmarkSalvageable.ReturnAssetComposition();
	}

	private void InitializeVisualPrefab()
	{
		if ((bool)VisualPrefab)
		{
			OnCompositionUpdated(_compositionInventory.ReturnProgress());
			base.Inventory.CompositionUpdatedEvent += OnCompositionUpdated;
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Salvageable '{0}' with Landmark path '{1}' has no visual prefab set.", base.gameObject.name, PajamaLlama.Debugs.Debugger.ReturnPathFromComponentInParent<Landmark>(this));
		}
	}

	public int ReturnRandomVariationIndex()
	{
		if (!((IReadOnlyCollection<LandmarkSalvageable>)(object)_variations).IsNullOrEmpty())
		{
			return UnityEngine.Random.Range(-1, _variations.Length);
		}
		return -1;
	}

	public LandmarkSalvageableCategory ReturnCategoryAsset(int variationIndex)
	{
		if (variationIndex <= -1 || _variations.Length <= variationIndex)
		{
			return _category;
		}
		return _variations[variationIndex]._category;
	}

	public List<CountedItemProperty> ReturnAssetComposition(int variationIndex)
	{
		if (((IReadOnlyCollection<LandmarkSalvageable>)(object)_variations).IsNullOrEmpty() || variationIndex < 0 || _variations.Length <= variationIndex)
		{
			return ReturnAssetComposition();
		}
		return _variations[variationIndex].ReturnAssetComposition();
	}
}
[CreateAssetMenu(fileName = "Landmark Salvageable Category", menuName = "Flotsam/Landmarks/Assets/Landmark Salvageable Category")]
public class LandmarkSalvageableCategory : PersistentProperties
{
	[Serializable]
	public struct Requirement
	{
		public ItemProperties ItemProperties;

		public float Amount;

		public bool IsNullOrEmpty()
		{
			if (!(ItemProperties == null))
			{
				return Amount <= 0f;
			}
			return true;
		}
	}

	[Tooltip("Dictates the order the categories are dislayed in the UI, lower value is higher in the list")]
	[SerializeField]
	private int _uiOrder;

	[SerializeField]
	private LocalizedString _description;

	[SerializeField]
	[Tooltip("The item(s) required for each salvageable that falls into this category")]
	private Requirement _requiredItem;

	[SerializeField]
	[Tooltip("The AssignmentTypes required for each salvageable that falls into this category")]
	private AssignmentType _requiredAssignmentType;

	[SerializeField]
	[Tooltip("Buildable required for each salvageable that falls into this category")]
	private BuildableProperties _requiredBuildable;

	[SerializeField]
	[Tooltip("The item(s) required for each salvageable that falls into this category")]
	private float _salvageItemExperience;

	public int UIOrder => _uiOrder;

	public LocalizedString Description => _description;

	public Requirement RequiredItem => _requiredItem;

	public float SalvageItemExperience => _salvageItemExperience;

	public override Types Type => Types.LandmarkSalvageableCategory;

	public bool ReturnRequiresItem()
	{
		if (_requiredItem.ItemProperties != null)
		{
			return 0f < _requiredItem.Amount;
		}
		return false;
	}

	public bool ReturnRequiresAssignmentType()
	{
		if (_requiredAssignmentType == AssignmentType.None)
		{
			return false;
		}
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent.ReturnAcceptsAssignmentType(_requiredAssignmentType))
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnRequiresBuildable()
	{
		if (_requiredBuildable == null)
		{
			return false;
		}
		return !Community.PlayerCommunity.ReturnHasBuildable(_requiredBuildable);
	}
}
public class LandmarkScavengeable : LandmarkInteractableWithComposition
{
	[SerializeField]
	private Target _scavengeTarget;

	[SerializeField]
	private RotationShaker _main;

	[SerializeField]
	private RotationShaker[] _secondaries;

	public bool IsBeingScavenged { get; private set; }

	public override void Initialize(LandmarkBehaviour landmarkBehaviour)
	{
	}

	public IEnumerator ScavengeCoroutine(Agent agent, Project project, List<Item> itemsToScavenge)
	{
		IsBeingScavenged = true;
		Navigator navigator = agent.ReturnNavigator();
		navigator.enabled = false;
		agent.UpdateActivity(Activity.Moving);
		agent.LookAtObject(_scavengeTarget.transform);
		yield return MoveAgentToTargetCoroutine(agent, _scavengeTarget, navigator.ReturnSpeed());
		agent.UpdateActivity(Activity.Scavenge);
		yield return _main.ShakeCoroutine(5f);
		if (_secondaries != null)
		{
			RotationShaker[] secondaries = _secondaries;
			foreach (RotationShaker rotationShaker in secondaries)
			{
				yield return rotationShaker.ShakeCoroutine(5f);
				yield return _main.ShakeCoroutine(1f);
			}
		}
		if (0 < itemsToScavenge.Count)
		{
			Item item = itemsToScavenge[0];
			while (item.Inventory == base.Inventory && 0 < agent.Inventory.ReturnAvailableStorageCapacity())
			{
				if (agent.Inventory.FitsInInventory(item))
				{
					base.Inventory.TakeItem(item);
					itemsToScavenge.Remove(item);
					throw new NotImplementedException("TODO: Implement method adds item to agent inventory and handles it state in ProjectAssignment!");
				}
				if (0 >= itemsToScavenge.Count)
				{
					break;
				}
				item = itemsToScavenge[0];
			}
		}
		yield return MoveAgentToTargetCoroutine(agent, Target, navigator.ReturnSpeed());
		navigator.enabled = true;
		IsBeingScavenged = false;
	}

	private IEnumerator MoveAgentToTargetCoroutine(Agent agent, Target target, float speed)
	{
		Vector3 startPosition = agent.transform.position;
		Vector3 targetPosition = target.transform.position;
		float time = 0f;
		float duration = Vector3.Distance(startPosition, targetPosition) / speed;
		agent.LookAtObject(target.transform);
		agent.UpdateActivity(Activity.Moving);
		while (time < duration)
		{
			yield return null;
			time += Time.deltaTime;
			agent.transform.position = Vector3.Lerp(startPosition, targetPosition, time / duration);
		}
		agent.transform.position = targetPosition;
	}

	public void InterruptScavenging()
	{
		IsBeingScavenged = false;
		StopAllCoroutines();
		_main.InterruptShaking();
		RotationShaker[] secondaries = _secondaries;
		for (int i = 0; i < secondaries.Length; i++)
		{
			secondaries[i].InterruptShaking();
		}
	}

	public void CountScavengedItems(InventoryAuditor auditor)
	{
		foreach (IInventorySlot slot in _compositionInventory.Slots)
		{
			int num = slot.Capacity - slot.Count;
			if (num != 0)
			{
				auditor.CountItemProperties(slot.ItemProperties, num);
			}
		}
	}

	public List<Item> ReturnAllItems()
	{
		return _compositionInventory.ReturnAllItems();
	}
}
