public interface ILoadingTask
{
	int Weight { get; }

	string DebugId { get; }

	bool YieldReturnNull => false;

	bool Run();
}
public class LoadingTask : ILoadingTask
{
	private UnityAction _action;

	private bool _completed;

	public int Weight => 1;

	public string DebugId { get; private set; }

	public LoadingTask(UnityAction action, string debugId)
	{
		_action = action;
		DebugId = debugId;
		_completed = false;
	}

	public bool Run()
	{
		if (_completed)
		{
			return false;
		}
		_action();
		_completed = true;
		return true;
	}
}
public class LoadingTaskEnumerator : ILoadingTask
{
	private UnityAction<int> _callback;

	private int _index;

	public int Weight { get; private set; }

	public string DebugId => null;

	public LoadingTaskEnumerator(UnityAction<int> callback, int length)
	{
		_callback = callback;
		Weight = length;
		_index = 0;
	}

	public bool Run()
	{
		if (_index < Weight)
		{
			_callback(_index++);
			return true;
		}
		return false;
	}
}
public class LoadingTaskUpdateLabel : ILoadingTask
{
	private string _label;

	public int Weight => 0;

	public string DebugId => null;

	public LoadingTaskUpdateLabel(string label)
	{
		_label = label;
	}

	public bool Run()
	{
		new LoadingEvent(_label).Dispatch();
		return false;
	}
}
public interface ILocalizationGenderProvider : ILocalizationParamsManager
{
	private const string GENDER_KEY = "GENDER:";

	protected Agent.EGender LocalizationGender { get; }

	string ILocalizationParamsManager.GetParameterValue(string param)
	{
		if (!param.StartsWith("GENDER:"))
		{
			return null;
		}
		int length = "GENDER:".Length;
		return SelectGenderedText(param.Substring(length, param.Length - length), LocalizationGender);
	}

	private static string SelectGenderedText(string values, Agent.EGender gender)
	{
		int num = values.IndexOf('/');
		if (num == -1)
		{
			UnityEngine.Debug.LogException(new IndexOutOfRangeException("Could not find '/' separator in values of gender localization key! Values are " + values));
			return values;
		}
		switch (gender)
		{
		case Agent.EGender.Male:
			return values.Substring(0, num);
		case Agent.EGender.Female:
		{
			int num2 = num + 1;
			return values.Substring(num2, values.Length - num2);
		}
		default:
			return values;
		}
	}
}
