public class RewiredLocalizationParamsManager : MonoBehaviour, ILocalizationParamsManager
{
	public const string REWIRED_PREFIX = "RWRD:";

	[SerializeField]
	private RewiredGlyphProvider _glyphProvider;

	private void OnEnable()
	{
		LocalizationManager.ParamManagers.Add(this);
	}

	private void OnDisable()
	{
		LocalizationManager.ParamManagers.Remove(this);
	}

	public string GetParameterValue(string param)
	{
		if (param.StartsWith("RWRD:"))
		{
			using ListPool<int>.List list = ListPool<int>.Get();
			param.Replace("RWRD:", string.Empty).SplitInt(',', list);
			if (_glyphProvider.TryGetActionsParameterValue(list, out var value))
			{
				return value;
			}
		}
		return null;
	}
}
public class AgentManager : MonoBehaviour
{
	private AgentSettings _settings;

	private bool _sendVitalsUpdatedEvent;

	private bool _sendDiseasesUpdatedEvent;

	private readonly List<Agent> _diseasedAgents = new List<Agent>(50);

	private readonly List<ItemProperties> _unavailableMedication = new List<ItemProperties>(4);

	public bool Initialized { get; private set; }

	public Transform AgentParent { get; private set; }

	public Dictionary<AssignmentType, AssignmentPriority> AssignmentPriorityTemplates { get; } = new Dictionary<AssignmentType, AssignmentPriority>();

	public float AgentInventoryCapacity { get; private set; }

	public void Initialize()
	{
		if (AgentParent == null)
		{
			AgentParent = new GameObject("AgentParent").transform;
		}
		foreach (AssignmentSetting assignmentSetting in GameManager.Settings.ProjectSettings.AssignmentSettings)
		{
			AssignmentPriorityTemplates.Add(assignmentSetting.Type, AssignmentPriority.Lowest);
		}
		GameEventDispatcher.AddListener(GameEventType.DaytimeStarted, OnDayStart);
		AgentInventoryCapacity = AgentDescriptor.GetProperties().Prefab.GetComponentInChildren<Inventory>().StorageCapacity;
		Initialized = true;
	}

	public void LateUpdate()
	{
		if (_sendVitalsUpdatedEvent)
		{
			new GameEvent(GameEventType.VitalsUpdated).Dispatch();
			_sendVitalsUpdatedEvent = false;
		}
		if (_sendDiseasesUpdatedEvent)
		{
			new GameEvent(GameEventType.DiseasesUpdated).Dispatch();
			_sendDiseasesUpdatedEvent = false;
		}
		int count = _diseasedAgents.Count;
		while (0 < count--)
		{
			Agent agent = _diseasedAgents[count];
			Disease currentDisease = agent.Vitals.Pollution.CurrentDisease;
			if (currentDisease == null)
			{
				_diseasedAgents.RemoveAt(count);
			}
			else if (!_unavailableMedication.Contains(currentDisease.Medication) && !currentDisease.TryReserveMedPod(agent))
			{
				_unavailableMedication.Add(currentDisease.Medication);
			}
		}
		_unavailableMedication.Clear();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.DaytimeStarted, OnDayStart);
	}

	public void SendVitalsEvent()
	{
		_sendVitalsUpdatedEvent = true;
	}

	public void SendDiseaseEvent()
	{
		_sendDiseasesUpdatedEvent = true;
	}

	public void SpawnStartingAgent(AgentDescriptor agentDescriptor)
	{
		agentDescriptor.Spawn(Community.PlayerCommunity, GameManager.Settings.SessionSettings.StartingScenario.PositionTownheart + SpawnPoint(GameManager.Settings.SessionSettings.StartingScenario.InhabitantSpawnRadius));
	}

	public void RegisterDiseasedAgent(Agent agent)
	{
		if ((bool)agent.Vitals.Pollution.CurrentDisease)
		{
			_diseasedAgents.AddUnique(agent);
		}
		SendDiseaseEvent();
	}

	public void UnregisterDiseasedAgent(Agent agent)
	{
		_diseasedAgents.Remove(agent);
		SendDiseaseEvent();
	}

	private Vector3 SpawnPoint(float radius)
	{
		return (UnityEngine.Random.insideUnitSphere * radius).Leveled();
	}

	private void OnDayStart(GameEvent gameEvent)
	{
		if (GameManager.TimeManager.Days.Count == 0)
		{
			return;
		}
		DistributeConsumables(isSimulation: false);
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			agent.Vitals.OnDayStarted(gameEvent);
		}
	}

	public void DistributeConsumables(bool isSimulation)
	{
		DistributeConsumables();
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (isSimulation)
			{
				agent.Vitals.UnreserveItemToConsume(VitalType.Hunger, VitalType.Thirst);
			}
			else
			{
				agent.Vitals.TryAddConsumeProject(VitalType.Hunger);
				agent.Vitals.TryAddConsumeProject(VitalType.Thirst);
			}
		}
	}

	public void DistributeConsumables(Agent targetAgent)
	{
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent == targetAgent)
			{
				agent.Vitals.TryAddConsumeProject(VitalType.Hunger);
				agent.Vitals.TryAddConsumeProject(VitalType.Thirst);
			}
			else
			{
				agent.Vitals.UnreserveItemToConsume(VitalType.Hunger, VitalType.Thirst);
			}
		}
	}

	private void DistributeConsumables()
	{
		using ListPool<Agent>.List list = ListPool<Agent>.Get(Community.PlayerCommunity.Agents);
		foreach (Agent item in list)
		{
			item.Vitals.ClearLastReservedItemToConsume(VitalType.Hunger);
		}
		Sorting.SlowSort(list, Agent.SortByHunger);
		DistributeFood(list);
		Sorting.SlowSort(list, Agent.SortByThirst);
		DistributeWater(list);
	}

	private void DistributeFood(List<Agent> agents)
	{
		using ListPool<Agent>.List list = ListPool<Agent>.Get(agents);
		using ListPool<Agent>.List list2 = ListPool<Agent>.Get();
		RemoveAgentsWithVitalProject(list, VitalType.Hunger);
		foreach (Agent item in list)
		{
			if (0 < item.Vitals.Hunger.Amount)
			{
				list2.Add(item);
			}
		}
		DistributeFood(list, list2);
		if (0 < list2.Count)
		{
			Sorting.SlowSort(list2, Agent.SortByHunger);
			int count = list2.Count;
			while (0 < count--)
			{
				list2[count].Vitals.TryReserveItemToConsume(VitalType.Hunger, AssignmentPriority.Lowest);
			}
		}
	}

	private void DistributeFood(List<Agent> unfedAgents, List<Agent> hungryAgents)
	{
		int num = Community.PlayerCommunity.Inventory.ReturnItemContainingTagCount(Item.Tags.Food);
		if (num <= hungryAgents.Count)
		{
			return;
		}
		AssignmentPriority assignmentPriority = AssignmentPriority.Highest;
		while (AssignmentPriority.None < assignmentPriority)
		{
			int count = unfedAgents.Count;
			while (0 < count--)
			{
				Agent agent = unfedAgents[count];
				if (agent.Vitals.TryReserveItemToConsume(VitalType.Hunger, assignmentPriority))
				{
					unfedAgents.Remove(agent);
					hungryAgents.Remove(agent);
					if (--num <= hungryAgents.Count)
					{
						return;
					}
				}
			}
			assignmentPriority--;
		}
	}

	private void DistributeWater(List<Agent> agents)
	{
		using ListPool<Agent>.List list = ListPool<Agent>.Get(agents);
		RemoveAgentsWithVitalProject(list, VitalType.Thirst);
		Sorting.SlowSort(list, Agent.SortByThirst);
		using List<Agent>.Enumerator enumerator = list.GetEnumerator();
		while (enumerator.MoveNext() && enumerator.Current.Vitals.TryReserveItemToConsume(VitalType.Thirst, AssignmentPriority.Lowest))
		{
		}
	}

	private void RemoveAgentsWithVitalProject(List<Agent> agents, VitalType vital)
	{
		int count = agents.Count;
		while (0 < count--)
		{
			if (agents[count].Vitals.ReturnHasProject(vital))
			{
				agents.RemoveAt(count);
			}
		}
	}
}
public class AnalyticsManager : MonoBehaviour
{
	private enum BuildableAction
	{
		Built,
		Salvaged,
		Researched
	}

	private enum AgentType
	{
		Drifter,
		Bird
	}

	private class DayMarkedEvent : Unity.Services.Analytics.Event
	{
		public DayMarkedEvent(string eventName)
			: base(eventName)
		{
			Initialize();
		}

		public void Initialize()
		{
			SetParameter("day", GameManager.TimeManager.Days.Count);
		}
	}

	private class SessionEvent : Unity.Services.Analytics.Event
	{
		public SessionEvent()
			: base("SessionInfo")
		{
			GameVersion version = GameManager.Settings.Version;
			SetParameter("majorVersion", version.Major);
			SetParameter("minorVersion", version.Minor);
			SetParameter("patchVersion", version.Patch);
			SetParameter("additionalVersionModifiers", version.AdditionalModifiers);
			SetParameter("saveVersion", version.Save);
			SetParameter("tileProperties", (WorldManager.TileProperties != null) ? WorldManager.TileProperties.name : "Unknown");
		}
	}

	private class PerformanceEvent : Unity.Services.Analytics.Event
	{
		public PerformanceEvent()
			: base("Performance")
		{
		}

		public void SetFPS(float fps)
		{
			SetParameter("fps", fps);
		}
	}

	private class BuildableActionEvent : DayMarkedEvent
	{
		public BuildableActionEvent()
			: base("BuildableAction")
		{
		}

		public void Initialize(string buildableName, BuildableAction action)
		{
			Initialize();
			SetParameter("buildableName", buildableName);
			SetParameter("buildableAction", action.ToString());
		}
	}

	private class MarkerPlacementEvent : DayMarkedEvent
	{
		public MarkerPlacementEvent()
			: base("MarkerPlacement")
		{
		}

		public void Initialize(string resourceName)
		{
			Initialize();
			SetParameter("resourceName", resourceName);
		}
	}

	private class AgentRescuedEvent : DayMarkedEvent
	{
		public AgentRescuedEvent()
			: base("AgentRescued")
		{
		}

		public void Initialize(AgentType agentType)
		{
			Initialize();
			SetParameter("agentType", agentType.ToString());
		}
	}

	private class AgentDiedEvent : DayMarkedEvent
	{
		public AgentDiedEvent()
			: base("AgentDied")
		{
		}
	}

	private class DrifterleveledEvent : DayMarkedEvent
	{
		public DrifterleveledEvent()
			: base("DrifterLeveled")
		{
		}

		public void Initialize(int drifterLevel)
		{
			Initialize();
			SetParameter("level", drifterLevel);
		}
	}

	private bool _initialized;

	private bool _readyToSendEvents;

	private float _averageFPS;

	private int _performanceFrameQuantity;

	private float _currentPooledAnalyticsTime;

	private float _pooledAnalyticsMaximumTime;

	private readonly PerformanceEvent _performanceEvent = new PerformanceEvent();

	private readonly Queue<Unity.Services.Analytics.Event> _queuedEvents = new Queue<Unity.Services.Analytics.Event>();

	private readonly Dictionary<Type, Queue<Unity.Services.Analytics.Event>> _eventsPools = new Dictionary<Type, Queue<Unity.Services.Analytics.Event>>();

	public void Initialize()
	{
		GameEventDispatcher.AddListener(GameEventType.GameStart, SendSessionEvent);
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, TrackBuildableBuilt);
		GameEventDispatcher.AddListener(GameEventType.BuildableSalvaged, TrackBuildableSalvage);
		GameEventDispatcher.AddListener(GameEventType.ResearchFinished, TrackBuildableResearched);
		GameEventDispatcher.AddListener(GameEventType.MarkerPlaced, TrackMarkerPlaced);
		GameEventDispatcher.AddListener(GameEventType.AgentRescue, TrackDrifterRescued);
		GameEventDispatcher.AddListener(GameEventType.BirdRescue, TrackBirdRescued);
		GameEventDispatcher.AddListener(GameEventType.AgentDeath, TrackDrifterDied);
		GameEventDispatcher.AddListener(GameEventType.AgentLevelGained, TrackDrifterLeveled);
		if (!_initialized)
		{
			_pooledAnalyticsMaximumTime = GameManager.Settings.DataSettings.PooledAnalyticsCallIntervalTime;
			_initialized = true;
		}
	}

	private async void InitializeDataCollection()
	{
		_readyToSendEvents = false;
		await UnityServices.InitializeAsync();
		ConsentState consentState = new ConsentState();
		consentState.AnalyticsIntent = ConsentStatus.Granted;
		EndUserConsent.SetConsentState(consentState);
		_readyToSendEvents = true;
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, SendSessionEvent);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, TrackBuildableBuilt);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableSalvaged, TrackBuildableSalvage);
		GameEventDispatcher.RemoveListener(GameEventType.ResearchFinished, TrackBuildableResearched);
		GameEventDispatcher.RemoveListener(GameEventType.MarkerPlaced, TrackMarkerPlaced);
		GameEventDispatcher.RemoveListener(GameEventType.AgentRescue, TrackDrifterRescued);
		GameEventDispatcher.RemoveListener(GameEventType.BirdRescue, TrackBirdRescued);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, TrackDrifterDied);
		GameEventDispatcher.RemoveListener(GameEventType.AgentAttributeLeveled, TrackDrifterLeveled);
		if (_readyToSendEvents)
		{
			SendEvents();
		}
		_initialized = false;
		_readyToSendEvents = false;
	}

	private void Update()
	{
		if (_readyToSendEvents)
		{
			_currentPooledAnalyticsTime += Time.unscaledDeltaTime;
			_performanceFrameQuantity++;
			float num = 1f / Time.unscaledDeltaTime;
			_averageFPS += (num - _averageFPS) / (float)_performanceFrameQuantity;
			if (_currentPooledAnalyticsTime > _pooledAnalyticsMaximumTime)
			{
				SendEvents();
				_currentPooledAnalyticsTime = 0f;
				_averageFPS = 0f;
				_performanceFrameQuantity = 0;
			}
		}
	}

	private EventType GetEvent<EventType>() where EventType : Unity.Services.Analytics.Event, new()
	{
		if (!_eventsPools.TryGetValue(typeof(EventType), out var value) || value.Count <= 0)
		{
			return new EventType();
		}
		return value.Dequeue() as EventType;
	}

	private void SendEvents()
	{
		if (UnityServices.State == ServicesInitializationState.Initialized)
		{
			SendPerformanceEvents();
			while (_queuedEvents.Count > 0)
			{
				Unity.Services.Analytics.Event obj = _queuedEvents.Dequeue();
				AnalyticsService.Instance.RecordEvent(obj);
				_eventsPools.GetOrCreate(obj.GetType()).Enqueue(obj);
			}
		}
	}

	public void SendSessionEvent(GameEvent gameEvent)
	{
		if (!GameManager.Instance.IntroScene)
		{
			_queuedEvents.Enqueue(new SessionEvent());
		}
	}

	private void SendPerformanceEvents()
	{
		_performanceEvent.SetFPS(_averageFPS);
		_queuedEvents.Enqueue(_performanceEvent);
	}

	private void TrackBuildableBuilt(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent)
		{
			BuildableActionEvent buildableActionEvent = GetEvent<BuildableActionEvent>();
			buildableActionEvent.Initialize(buildableEvent.BuildableProperties.name, BuildableAction.Built);
			_queuedEvents.Enqueue(buildableActionEvent);
		}
	}

	private void TrackBuildableSalvage(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent)
		{
			BuildableActionEvent buildableActionEvent = GetEvent<BuildableActionEvent>();
			buildableActionEvent.Initialize(buildableEvent.BuildableProperties.name, BuildableAction.Salvaged);
			_queuedEvents.Enqueue(buildableActionEvent);
		}
	}

	private void TrackBuildableResearched(GameEvent gameEvent)
	{
		if (!(gameEvent is ResearchEvent { EventType: GameEventType.ResearchFinished } researchEvent))
		{
			return;
		}
		foreach (ResearchUnlockable unlockable in researchEvent.Research.TechTreeNode.Unlockables)
		{
			if (unlockable is BuildableProperties buildableProperties)
			{
				BuildableActionEvent buildableActionEvent = GetEvent<BuildableActionEvent>();
				buildableActionEvent.Initialize(buildableProperties.name, BuildableAction.Researched);
				_queuedEvents.Enqueue(buildableActionEvent);
			}
		}
	}

	private void TrackMarkerPlaced(GameEvent gameEvent)
	{
		if (gameEvent is MarkerEvent markerEvent)
		{
			MarkerPlacementEvent markerPlacementEvent = GetEvent<MarkerPlacementEvent>();
			markerPlacementEvent.Initialize(markerEvent.Marker.MarkerCursorProperties.name);
			_queuedEvents.Enqueue(markerPlacementEvent);
		}
	}

	private void TrackDrifterRescued(GameEvent gameEvent)
	{
		AgentRescuedEvent agentRescuedEvent = GetEvent<AgentRescuedEvent>();
		agentRescuedEvent.Initialize(AgentType.Drifter);
		_queuedEvents.Enqueue(agentRescuedEvent);
	}

	private void TrackBirdRescued(GameEvent gameEvent)
	{
		AgentRescuedEvent agentRescuedEvent = GetEvent<AgentRescuedEvent>();
		agentRescuedEvent.Initialize(AgentType.Bird);
		_queuedEvents.Enqueue(agentRescuedEvent);
	}

	private void TrackDrifterDied(GameEvent gameEvent)
	{
		AgentDiedEvent agentDiedEvent = GetEvent<AgentDiedEvent>();
		agentDiedEvent.Initialize();
		_queuedEvents.Enqueue(agentDiedEvent);
	}

	private void TrackDrifterLeveled(GameEvent gameEvent)
	{
		DrifterleveledEvent drifterleveledEvent = GetEvent<DrifterleveledEvent>();
		drifterleveledEvent.Initialize(0);
		_queuedEvents.Enqueue(drifterleveledEvent);
	}
}
public enum AudioType
{
	UI,
	Music,
	Stinger,
	Diegetic,
	UILong,
	Imperative,
	LoadSafe
}
public class AudioManager : MonoBehaviour
{
	[Header("FMOD Globals")]
	[SerializeField]
	private FMODParameter _dayTime;

	[SerializeField]
	private FMODParameter _gameSpeed;

	[SerializeField]
	private FMODParameter _zoomLevel;

	public void Initialize()
	{
		FMODManager.ApplyAudioPlayerData(Settings.Instance.AudioPlayerData);
		SubscribeToAgentEvents();
		StartCoroutine(PlayMusicCoroutine());
		StartCoroutine(PlayIdlingSoundCoroutine());
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, LaunchStinger);
		GameEventDispatcher.AddListener(GameEventType.GameSpeedChange, PauseAudio);
	}

	private void OnDestroy()
	{
		UnsubscribeAgentEvents();
	}

	public static void Play(AudioClipProperties clipProperties)
	{
		if (!(GameManager.AudioManager == null))
		{
			GameManager.AudioManager.Play2D(clipProperties);
		}
	}

	public static void Play(AudioClipProperties clipProperties, Transform source)
	{
		if (!(GameManager.AudioManager == null) && !(source == null))
		{
			GameManager.AudioManager.Play3D(clipProperties, source.position);
		}
	}

	public static void PlayMusic(AudioClipProperties musicProperties)
	{
		if (!(GameManager.AudioManager == null))
		{
			GameManager.AudioManager.Play2D(musicProperties, returnIfLoading: false);
		}
	}

	public static void PlayOneShot(string path, Transform sourceTransform = null)
	{
		if (!string.IsNullOrEmpty(path))
		{
			if (sourceTransform == null)
			{
				RuntimeManager.PlayOneShot(path);
			}
			else
			{
				RuntimeManager.PlayOneShot(path, sourceTransform.position);
			}
		}
	}

	public static void PlayOneShot(EventReference eventReference, Transform sourceTransform = null)
	{
		if (!eventReference.IsNull)
		{
			if ((bool)sourceTransform)
			{
				RuntimeManager.PlayOneShot(eventReference, sourceTransform.position);
			}
			else
			{
				RuntimeManager.PlayOneShot(eventReference);
			}
		}
	}

	public static void PlayOneShotAttached(string path, GameObject source)
	{
		if (!string.IsNullOrEmpty(path))
		{
			RuntimeManager.PlayOneShotAttached(path, source);
		}
	}

	public static void PlayOneShotAttached(EventReference eventReference, GameObject source)
	{
		if (!eventReference.IsNull)
		{
			RuntimeManager.PlayOneShotAttached(eventReference, source);
		}
	}

	public static void SetDayTimeParameter(float value)
	{
		if (!(GameManager.AudioManager == null))
		{
			GameManager.AudioManager._dayTime.SetValue(value);
		}
	}

	public static void SetZoomLevelParameter(float value)
	{
		if (!(GameManager.AudioManager == null))
		{
			GameManager.AudioManager._zoomLevel.SetValue(1f - value);
		}
	}

	private IEnumerator PlayMusicCoroutine()
	{
		while (LoadingScreen.IsLoading)
		{
			yield return null;
		}
		if (GameManager.Settings.PlayMusic)
		{
			if (PersistenceManager.ReturnIsRestoredGame())
			{
				Play2D(GameManager.Settings.AudioSettings.DefaultMusic);
			}
			else
			{
				Play2D(GameManager.Settings.AudioSettings.StingerNewGame);
			}
			Play2D(GameManager.Settings.AudioSettings.DefaultAmbience);
		}
	}

	private void Play2D(AudioClipProperties clipProperties, bool returnIfLoading = true)
	{
		if (!returnIfLoading || !LoadingScreen.IsLoading)
		{
			if (clipProperties == null)
			{
				PajamaLlama.Debugs.Debugger.Warning($"No clip received to play!", null, onlyShowInEditor: true);
			}
			else if (!clipProperties.TryFMODOneShot())
			{
				UnityEngine.Debug.LogWarningFormat("AudioClipProperties '{0}' has no FMODEvent set!", clipProperties.name);
			}
		}
	}

	private void Play3D(AudioClipProperties clipProperties, Vector3 position)
	{
		if (clipProperties == null)
		{
			PajamaLlama.Debugs.Debugger.Warning($"No clip received to play!", null, onlyShowInEditor: true);
		}
		else if (!clipProperties.TryFMODOneShot(position))
		{
			UnityEngine.Debug.LogWarningFormat("AudioClipProperties '{0}' has no FMODEvent set!", clipProperties.name);
		}
	}

	public void LaunchStinger(GameEvent gameEvent)
	{
		string text = (gameEvent as BuildableEvent).BuildableProperties.name;
		if (!(text == "SalvagingBoat"))
		{
			if (text == "Sails")
			{
				Play2D(GameManager.Settings.AudioSettings.StingerSails);
			}
		}
		else
		{
			Play2D(GameManager.Settings.AudioSettings.StingerFirstBoat);
		}
	}

	public static void EnableMapAudio(AudioClipProperties adioClipProperties)
	{
		if (GameManager.AudioManager != null)
		{
			GameManager.AudioManager.ToggleMapAudio(active: true, adioClipProperties);
		}
	}

	public static void DisableMapAudio(AudioClipProperties adioClipProperties)
	{
		if (GameManager.AudioManager != null)
		{
			GameManager.AudioManager.ToggleMapAudio(active: false, adioClipProperties);
		}
	}

	private void ToggleMapAudio(bool active, AudioClipProperties audioClipProperties)
	{
		GameManager.WorldMapManager.WorldMap.WorldCameraController.SetAudioListenerEnabled(active);
		CameraController.Instance.SetAudioListenerEnabled(!active);
		Play2D(audioClipProperties);
	}

	public void PauseAudio(GameEvent gameEvent)
	{
		switch (GameSpeedManager.GameSpeed)
		{
		case GameSpeed.Paused:
		case GameSpeed.Zero:
			_gameSpeed.SetValue(0f);
			AudioListener.pause = true;
			return;
		case GameSpeed.One:
			_gameSpeed.SetValue(1f);
			break;
		case GameSpeed.Two:
			_gameSpeed.SetValue(2f);
			break;
		case GameSpeed.Three:
			_gameSpeed.SetValue(3f);
			break;
		case GameSpeed.Four:
			_gameSpeed.SetValue(4f);
			break;
		default:
			throw new NotImplementedException();
		}
		AudioListener.pause = false;
	}

	private void SubscribeToAgentEvents()
	{
		GameEventDispatcher.AddListener(GameEventType.AgentStartProject, PlayOnStartProjectSound);
		GameEventDispatcher.AddListener(GameEventType.AgentDeath, PlayOnAgentDeathSound);
	}

	private void UnsubscribeAgentEvents()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentStartProject, PlayOnStartProjectSound);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, PlayOnAgentDeathSound);
	}

	private void PlayOnAgentDeathSound(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent)
		{
			Play3D(agentEvent.Agent.Descriptor.VoicePack.OnDeathSounds, agentEvent.Agent.transform.position);
		}
	}

	private void PlayOnStartProjectSound(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent)
		{
			Play3D(agentEvent.Agent.Descriptor.VoicePack.StartTaskSounds, agentEvent.Agent.transform.position);
		}
	}

	private IEnumerator PlayIdlingSoundCoroutine()
	{
		while (true)
		{
			float seconds = UnityEngine.Random.Range(GameManager.Settings.AudioSettings.IdleVoiceInterval.Minimum, GameManager.Settings.AudioSettings.IdleVoiceInterval.Maximum);
			yield return new WaitForSeconds(seconds);
			IEnumerable<Agent> source = Community.PlayerCommunity.Agents.Where((Agent agent2) => agent2.CurrentActivity == Activity.Idling && agent2.IsAlive);
			int num = source.Count();
			if (num != 0)
			{
				Agent agent = source.ElementAt(UnityEngine.Random.Range(0, num));
				Play3D(agent.Descriptor.VoicePack.IdlingSounds, agent.transform.position);
			}
		}
	}
}
public class EffectsManager : MonoBehaviour
{
	public void Initialize()
	{
		ParticleEffect[] particleEffects = GameManager.Settings.FXSettings.ParticleEffects;
		for (int i = 0; i < particleEffects.Length; i++)
		{
			particleEffects[i].Initialize();
		}
	}

	public static bool ActivateEffect(EffectTrigger trigger, Transform parent, Vector3 localPosition)
	{
		ParticleEffect[] particleEffects = GameManager.Settings.FXSettings.ParticleEffects;
		for (int i = 0; i < particleEffects.Length; i++)
		{
			if (particleEffects[i].Activate(trigger, parent, localPosition))
			{
				return true;
			}
		}
		return false;
	}
}
public class FlotsamInputManager : MonoBehaviour
{
	public enum Layouts
	{
		World,
		Map
	}

	public const float CLICK_INTERVAL = 0.15f;

	[SerializeField]
	private RewiredStandaloneInputModule _inputModule;

	[Header("Joystick")]
	[SerializeField]
	private JoystickMouseInputSource.Mode _joystickMouseMode = JoystickMouseInputSource.Mode.Cumulative;

	[SerializeField]
	private float _joystickMouseCumulativeMultiplier = 1920f;

	[Header("Camera Input Settings")]
	[Tooltip("The horizontal rotation speed for keyboard and joystick.")]
	[SerializeField]
	private float _horizontalRotationSpeed = 400f;

	[Tooltip("The horizontal rotation speed for mouse")]
	private float _horizontalRotationSpeedMouse = 60f;

	[Header("Hotkey Actions")]
	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _gameMenuAction;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _cycleDriftersAction;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _leftShiftAction;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _mouseCancelActionID;

	[SerializeField]
	private float _mouseCancelActionTabExpireIn = 0.7f;

	[SerializeField]
	private RewiredGlyphProvider _glyphProvider;

	[Header("Debug")]
	[SerializeField]
	private bool _forceGamePad;

	private static FlotsamInputManager _instance;

	private bool _mapCameraToTownheartMovementInput;

	private JoystickMouseInputSource _joystickMouseInputSource;

	private Controller _activeController;

	private List<ICancelable> _cancelStack = new List<ICancelable>(4);

	private bool _forceMouseAndKeyboard;

	private Vector3 _mouseCancelDownCameraPosition;

	public static bool Initialized { get; private set; } = false;

	public static Rewired.Player RewiredPlayer { get; private set; }

	public static InputFlags ActiveInput { get; private set; } = InputFlags.MouseAndKeyboard;

	public static Vector3 MousePosition
	{
		get
		{
			if (IsJoystickMouse)
			{
				return _instance._joystickMouseInputSource.screenPosition;
			}
			if (IsJoystick)
			{
				return new Vector3(Screen.width / 2, Screen.height / 2, 0f);
			}
			return UnityEngine.Input.mousePosition;
		}
	}

	public static bool IsJoystick => (ActiveInput & InputFlags.Joystick) != 0;

	public static bool IsJoystickMouse => false;

	public static bool MapCameraToTownheartMovementInput
	{
		get
		{
			if ((bool)_instance)
			{
				return _instance._mapCameraToTownheartMovementInput;
			}
			return false;
		}
	}

	public static float RepeatDelay
	{
		get
		{
			if (!(_instance == null))
			{
				return _instance._inputModule.repeatDelay;
			}
			return 0f;
		}
	}

	public static float InputActionsPerSecond
	{
		get
		{
			if (!(_instance == null))
			{
				return _instance._inputModule.inputActionsPerSecond;
			}
			return 0f;
		}
	}

	public static bool HasKeyboard
	{
		get
		{
			if (RewiredPlayer != null)
			{
				return RewiredPlayer.controllers.hasKeyboard;
			}
			return true;
		}
	}

	private void Awake()
	{
		if (_instance == null)
		{
			_instance = this;
			Initialize();
		}
		base.enabled = _instance == this;
	}

	private void Start()
	{
		i_SetForceMouseAndKeyboard(Settings.Instance.GameplayPlayerData.ForceMouseAndKeyboard, force: true);
	}

	private void Update()
	{
		GameManager instance = GameManager.Instance;
		if (instance == null || instance.IntroScene || LoadingScreen.IsLoading || !instance.InitializeEnvironment || GameManager.UIManager == null || GameManager.UIManager.UIState == UIState.Typing || GUIUtility.hotControl != 0)
		{
			return;
		}
		HotkeyControls();
		bool flag = GetButtonDown(_gameMenuAction);
		if (GetUICancel())
		{
			int count = _cancelStack.Count;
			if (0 < count)
			{
				ICancelable cancelable = _cancelStack[--count];
				if (cancelable.TryCancel())
				{
					_cancelStack.Remove(cancelable);
				}
				flag = false;
			}
		}
		if (flag)
		{
			GameManager.UIManager.OpenGameMenu();
		}
	}

	private void OnDestroy()
	{
		if (RewiredPlayer != null)
		{
			RewiredPlayer.controllers.RemoveLastActiveControllerChangedDelegate(SetActiveController);
		}
	}

	public void Initialize()
	{
		RewiredPlayer = ReInput.players.GetPlayer(0);
		Controller firstControllerWithTemplate = RewiredPlayer.controllers.GetFirstControllerWithTemplate(GamepadTemplate.typeGuid);
		if (firstControllerWithTemplate == null)
		{
			SetActiveController(RewiredPlayer, RewiredPlayer.controllers.Keyboard);
		}
		else
		{
			SetActiveController(RewiredPlayer, firstControllerWithTemplate);
		}
		Initialized = true;
	}

	public static void SetForceMouseAndKeyboard(bool forceMouseAndKeyboard)
	{
		if ((bool)_instance)
		{
			_instance.i_SetForceMouseAndKeyboard(forceMouseAndKeyboard);
		}
	}

	private void i_SetForceMouseAndKeyboard(bool forceMouseAndKeyboard, bool force = false)
	{
		forceMouseAndKeyboard = forceMouseAndKeyboard && HasKeyboard;
		if (_forceMouseAndKeyboard != forceMouseAndKeyboard || force)
		{
			_forceMouseAndKeyboard = forceMouseAndKeyboard;
			if (_forceMouseAndKeyboard)
			{
				RewiredPlayer.controllers.RemoveLastActiveControllerChangedDelegate(SetActiveController);
				ReInput.ControllerConnectedEvent -= ReInput_ControllerConnectedEvent;
				ReInput.ControllerDisconnectedEvent -= ReInput_ControllerDisconnectedEvent;
				SetActiveController(RewiredPlayer, RewiredPlayer.controllers.Keyboard);
			}
			else
			{
				RewiredPlayer.controllers.AddLastActiveControllerChangedDelegate(SetActiveController);
				ReInput.ControllerConnectedEvent += ReInput_ControllerConnectedEvent;
				ReInput.ControllerDisconnectedEvent += ReInput_ControllerDisconnectedEvent;
			}
		}
	}

	private void SetActiveController(Rewired.Player player, Controller controller)
	{
		if (controller == null || controller == _activeController || UIManager.State == UIState.Typing)
		{
			return;
		}
		InputFlags activeInput = InputFlags.None;
		switch (controller.type)
		{
		case ControllerType.Keyboard:
		case ControllerType.Mouse:
			controller = RewiredPlayer.controllers.Keyboard;
			activeInput = InputFlags.MouseAndKeyboard;
			EventSystem.current?.SetSelectedGameObject(null);
			Cursor.lockState = CursorLockMode.None;
			break;
		case ControllerType.Joystick:
			if (!controller.ImplementsTemplate(GamepadTemplate.typeGuid))
			{
				controller = _activeController;
			}
			Cursor.lockState = CursorLockMode.Locked;
			activeInput = InputFlags.Joystick;
			break;
		}
		if (_activeController != controller)
		{
			_activeController = controller;
			ActiveInput = activeInput;
			GameEventDispatcher.Dispatch(GameEventType.ActiveInputUpdated);
		}
	}

	private void ReInput_ControllerConnectedEvent(ControllerStatusChangedEventArgs obj)
	{
		if (ActiveInput != InputFlags.Joystick && TryGetActiveJoystickWithTemplate(GamepadTemplate.typeGuid, out var joystick))
		{
			SetActiveController(RewiredPlayer, joystick);
		}
	}

	private void ReInput_ControllerDisconnectedEvent(ControllerStatusChangedEventArgs obj)
	{
		if (ActiveInput == InputFlags.Joystick && !TryGetActiveJoystickWithTemplate(GamepadTemplate.typeGuid, out var _))
		{
			SetActiveController(RewiredPlayer, RewiredPlayer.controllers.Keyboard);
		}
	}

	private IEnumerator AddJoystickMouseInputSource()
	{
		if (_joystickMouseInputSource == null)
		{
			EventSystem current = EventSystem.current;
			while (current == null || current.currentInputModule == null || !ReInput.isReady)
			{
				yield return null;
			}
			_joystickMouseInputSource = new JoystickMouseInputSource(_joystickMouseMode, _joystickMouseCumulativeMultiplier);
		}
		if (EventSystem.current.currentInputModule is RewiredStandaloneInputModule rewiredStandaloneInputModule)
		{
			rewiredStandaloneInputModule.AddMouseInputSource(_joystickMouseInputSource);
			ActiveInput = InputFlags.Joystick;
			GameEventDispatcher.Dispatch(GameEventType.ActiveInputUpdated);
			Settings.Instance.GameplayPlayerData.SnapBuilding = true;
			Settings.Instance.GameplayPlayerData.ShowBuildingGrid = true;
		}
	}

	private void RemoveJoystickMouseInputSource()
	{
		if (_joystickMouseInputSource != null && EventSystem.current.currentInputModule is RewiredStandaloneInputModule rewiredStandaloneInputModule)
		{
			rewiredStandaloneInputModule.RemoveMouseInputSource(_joystickMouseInputSource);
			ActiveInput = InputFlags.MouseAndKeyboard;
			EventSystem.current.SetSelectedGameObject(null);
			GameEventDispatcher.Dispatch(GameEventType.ActiveInputUpdated);
		}
	}

	private void HotkeyControls()
	{
		if (!GameManager.Gamepaused && RewiredPlayer.GetButtonDown(_cycleDriftersAction))
		{
			Community.PlayerCommunity.CycleAgents(RewiredPlayer.GetButton(_leftShiftAction));
		}
	}

	private Vector4 Internal_GetCameraInput(Layouts layout)
	{
		Vector4 result = layout switch
		{
			Layouts.World => RewiredActions.ReturnWorldCameraMovementInput(), 
			Layouts.Map => (!_mapCameraToTownheartMovementInput && !UIManager.HasFlagsSet(PanelContainerFlags.BlockCameraInput)) ? ((Vector4)RewiredActions.ReturnMapCameraMovementInput()) : default(Vector4), 
			_ => throw new NotImplementedException(), 
		};
		result.z = Internal_GetCameraRotation() * _horizontalRotationSpeed;
		if (GetButton(150))
		{
			result.z += GetAxis(145) * _horizontalRotationSpeedMouse;
			result.w = GetAxis(146);
		}
		return result;
	}

	private float Internal_GetCameraRotation()
	{
		float num = RewiredPlayer.GetAxisRaw(2) - RewiredPlayer.GetAxisRaw(33);
		if (IsJoystick)
		{
			return ApplyDeadzone(num, 0.3f);
		}
		return num;
	}

	private float Internal_GetCameraZoom()
	{
		float axisRaw = RewiredPlayer.GetAxisRaw(89);
		if (HasActiveInput(InputFlags.Joystick))
		{
			return ApplyDeadzone(axisRaw, 0.5f);
		}
		return axisRaw;
	}

	private float ApplyDeadzone(float value, float deadzone)
	{
		deadzone = Mathf.Clamp01(deadzone);
		if (deadzone < 1f)
		{
			float num = 1f - deadzone;
			if (value > deadzone)
			{
				return Mathf.Clamp01(value - deadzone) / num;
			}
			if (value < 0f - deadzone)
			{
				return Mathf.Clamp(value + deadzone, -1f, 0f) / num;
			}
		}
		return 0f;
	}

	private bool TryGetActiveJoystickWithTemplate(Guid templateGuid, out Joystick joystick)
	{
		joystick = RewiredPlayer.controllers.GetLastActiveController<Joystick>() as Joystick;
		if (joystick != null && joystick.ImplementsTemplate(templateGuid))
		{
			return true;
		}
		if (RewiredPlayer.controllers.GetFirstControllerWithTemplate(templateGuid) is Joystick joystick2)
		{
			joystick = joystick2;
		}
		return joystick != null;
	}

	public static void PushCancelable(ICancelable cancelable)
	{
		if ((bool)_instance)
		{
			_instance._cancelStack.AddUnique(cancelable);
		}
	}

	public static void RemoveCancelable(ICancelable cancelable)
	{
		if ((bool)_instance)
		{
			_instance._cancelStack.Remove(cancelable);
		}
	}

	public static bool HasActiveInput(InputFlags inputFlags)
	{
		return (ActiveInput & inputFlags) != 0;
	}

	public static Controller GetActiveController()
	{
		if (_instance == null || RewiredPlayer == null)
		{
			return null;
		}
		return _instance._activeController;
	}

	public static bool GetAnyButtonUp()
	{
		if (!GetAnyButtonUp(GetActiveController()) && !GetAnyButtonUp(RewiredPlayer.controllers.Keyboard))
		{
			return GetAnyButtonUp(RewiredPlayer.controllers.Mouse);
		}
		return true;
	}

	private static bool GetAnyButtonUp(Controller controller)
	{
		return controller?.GetAnyButtonUp() ?? false;
