		private readonly List<int> _placedMarkerCounts = new List<int>();

		private int _driftersRescuedCount;

		private int _birdsRescuedCount;

		private readonly int _deadDriftersCount;

		public PersistentData()
		{
			GameStatsManager gameStatsManager = GameManager.GameStatsManager;
			_actorStats = gameStatsManager._actorStats;
			_regionsScoutedCount = gameStatsManager.RegionsScoutedCount;
			_totalCameraMovedDistance = gameStatsManager.TotalCameraMovedDistance;
			_totalCameraRotationChanges = gameStatsManager.TotalCameraRotationChanges;
			_totalCameraZoomChanges = gameStatsManager.TotalCameraZoomChanges;
			_hasEverResetCamera = gameStatsManager.HasEverResetCamera;
			SaveItems(gameStatsManager._landmarkActionsInProgress, _landmarkActionsInProgressActionNames, _landmarkActionsInProgressCounts);
			SaveItems(gameStatsManager._salvagedMarkerItems, _salvagedMarkerItemPropertiesIDs, _salvagedMarkerItemCounts);
			SaveItems(gameStatsManager._salvagedLandmarkItems, _salvagedLandmarkItemPropertiesIDs, _salvagedLandmarkItems);
			SaveItems(gameStatsManager._salvagedSalvagerItems, _salvagedSalvagerItemPropertiesIDs, _salvagedSalvagerItems);
			SaveItems(gameStatsManager._itemProductionsQueued, _itemProductionsQueuedPropertiesIDs, _itemProductionsQueuedCounts);
			SaveItems(gameStatsManager._itemsProduced, _producedItemPropertiesIDs, _producedItemCounts);
			SaveItems(gameStatsManager._itemsFarmed, _farmedItemPropertiesIDs, _farmedItemCounts);
			SaveItems(gameStatsManager._buildablesBuilt, _builtBuildablePropertiesIDs, _builtBuildableCounts);
			SaveItems(gameStatsManager._markersPlaced, _placedMarkerPropertiesIDs, _placedMarkerCounts);
		}

		private static void SaveItems(IReadOnlyDictionary<string, int> items, List<string> names, List<int> counts)
		{
			foreach (KeyValuePair<string, int> item in items)
			{
				names.Add(item.Key);
				counts.Add(item.Value);
			}
		}

		private static void SaveItems<TKey>(IReadOnlyDictionary<TKey, int> items, List<int> ids, List<int> counts) where TKey : PersistentProperties
		{
			foreach (KeyValuePair<TKey, int> item in items)
			{
				ids.Add(GameManager.PersistenceManager.ReturnPropertiesIndex(item.Key));
				counts.Add(item.Value);
			}
		}

		public void Restore()
		{
			if (_placedMarkerPropertiesIDs.Count == 0 && _builtBuildablePropertiesIDs.Count == 0)
			{
				AssessDataFromCurrentWorldState();
			}
			GameStatsManager gameStatsManager = GameManager.GameStatsManager;
			gameStatsManager.Clear();
			if (!_actorStats.IsNullOrEmpty())
			{
				foreach (KeyValuePair<ActorType, ActorStats> actorStat in _actorStats)
				{
					gameStatsManager._actorStats.Add(actorStat.Key, actorStat.Value);
				}
			}
			gameStatsManager.RegionsScoutedCount = _regionsScoutedCount;
			gameStatsManager.TotalCameraMovedDistance = _totalCameraMovedDistance;
			gameStatsManager.TotalCameraRotationChanges = _totalCameraRotationChanges;
			gameStatsManager.TotalCameraZoomChanges = _totalCameraZoomChanges;
			gameStatsManager.HasEverResetCamera = _hasEverResetCamera;
			if (!_landmarkActionsInProgressActionNames.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._landmarkActionsInProgress, _landmarkActionsInProgressActionNames, _landmarkActionsInProgressCounts);
			}
			if (!_salvagedMarkerItemPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._salvagedMarkerItems, _salvagedMarkerItemPropertiesIDs, _salvagedMarkerItemCounts);
			}
			if (!_salvagedLandmarkItemPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._salvagedLandmarkItems, _salvagedLandmarkItemPropertiesIDs, _salvagedLandmarkItems);
			}
			if (!_salvagedSalvagerItemPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._salvagedSalvagerItems, _salvagedSalvagerItemPropertiesIDs, _salvagedSalvagerItems);
			}
			if (!_itemProductionsQueuedPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._itemProductionsQueued, _itemProductionsQueuedPropertiesIDs, _itemProductionsQueuedCounts);
			}
			if (!_producedItemPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._itemsProduced, _producedItemPropertiesIDs, _producedItemCounts);
			}
			if (!_farmedItemPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._itemsFarmed, _farmedItemPropertiesIDs, _farmedItemCounts);
			}
			if (!_builtBuildablePropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._buildablesBuilt, _builtBuildablePropertiesIDs, _builtBuildableCounts);
			}
			if (!_placedMarkerPropertiesIDs.IsNullOrEmpty())
			{
				RestoreDictionary(gameStatsManager._markersPlaced, _placedMarkerPropertiesIDs, _placedMarkerCounts);
			}
		}

		private void AssessDataFromCurrentWorldState()
		{
			Community playerCommunity = Community.PlayerCommunity;
			_regionsScoutedCount = GameManager.WorldManager.World.GetScoutedRegionsCount();
			foreach (Item item in (IEnumerable<Item>)playerCommunity.Inventory.GetAllItems(SubInventoryType.Storage))
			{
				if (item.ContainsTagSet(Item.Tags.Resource))
				{
					AddOrIncrement(item.Properties, _salvagedMarkerItemPropertiesIDs, _salvagedMarkerItemCounts);
				}
				else
				{
					AddOrIncrement(item.Properties, _producedItemPropertiesIDs, _producedItemCounts);
				}
			}
			List<Buildable> buildables = playerCommunity.Buildables;
			BuildableProperties properties = GameManager.Settings.SessionSettings.StartingScenario.Townheart.Properties;
			foreach (Buildable item2 in (IEnumerable<Buildable>)buildables)
			{
				if (item2.Properties != properties)
				{
					AddOrIncrement(item2.Properties, _builtBuildablePropertiesIDs, _builtBuildableCounts);
				}
			}
		}

		private static void AddOrIncrement<TKey>(TKey key, List<int> ids, List<int> counts) where TKey : PersistentProperties
		{
			int item = GameManager.PersistenceManager.ReturnPropertiesIndex(key);
			int num = ids.IndexOf(item);
			if (num == -1)
			{
				ids.Add(item);
				counts.Add(1);
			}
			else
			{
				counts[num]++;
			}
		}

		private static void RestoreDictionary(Dictionary<string, int> dictionary, IReadOnlyList<string> names, IReadOnlyList<int> counts)
		{
			int i = 0;
			for (int count = names.Count; i < count; i++)
			{
				dictionary.Add(names[i], counts[i]);
			}
		}

		private static void RestoreDictionary<TKey>(Dictionary<TKey, int> dictionary, IReadOnlyList<int> ids, IReadOnlyList<int> counts) where TKey : PersistentProperties
		{
			int i = 0;
			for (int count = ids.Count; i < count; i++)
			{
				if (GameManager.PersistenceManager.TryReturnPropertiesReference<TKey>(ids[i], out var reference))
				{
					dictionary.Add(reference, counts[i]);
				}
			}
		}
	}

	private readonly Dictionary<ActorType, ActorStats> _actorStats = new Dictionary<ActorType, ActorStats>();

	private readonly Dictionary<string, int> _landmarkActionsInProgress = new Dictionary<string, int>();

	private readonly Dictionary<ItemProperties, int> _salvagedMarkerItems = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<ItemProperties, int> _salvagedLandmarkItems = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<ItemProperties, int> _salvagedSalvagerItems = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<ItemProperties, int> _itemProductionsQueued = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<ItemProperties, int> _itemsProduced = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<ItemProperties, int> _itemsFarmed = new Dictionary<ItemProperties, int>();

	private readonly Dictionary<BuildableProperties, int> _buildablesBuilt = new Dictionary<BuildableProperties, int>();

	private readonly Dictionary<MarkerCursorProperties, int> _markersPlaced = new Dictionary<MarkerCursorProperties, int>();

	public GameData GameData { get; } = new GameData();

	public int RegionsScoutedCount { get; private set; }

	public float TotalCameraMovedDistance { get; private set; }

	public float TotalCameraRotationChanges { get; private set; }

	public float TotalCameraZoomChanges { get; private set; }

	public bool HasEverResetCamera { get; private set; }

	public void Initialize()
	{
		GameEventDispatcher.AddListener(GameEventType.LandmarkSpawned, OnLandmarkSpawned);
		GameEventDispatcher.AddListener(GameEventType.ActorRescue, OnActorEvent);
		GameEventDispatcher.AddListener(GameEventType.ActorDeath, OnActorEvent);
		GameEventDispatcher.AddListener(GameEventType.RegionScouted, OnRegionScouted);
		GameEventDispatcher.AddListener(GameEventType.ManualCameraMovement, OnCameraMovement);
		GameEventDispatcher.AddListener(GameEventType.ManualCameraRotation, OnCameraRotation);
		GameEventDispatcher.AddListener(GameEventType.ManualCameraZoom, OnCameraZoom);
		GameEventDispatcher.AddListener(GameEventType.CameraReset, OnCameraReset);
		GameEventDispatcher.AddListener(GameEventType.LandmarkNotificationWorking, OnLandmarkActionStarted);
		GameEventDispatcher.AddListener(GameEventType.LandmarkNotificationIdle, OnLandmarkActionStopped);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedMarkerItem, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedLandmarkItem, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedSalvagerItem, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.ProducerItemQueued, OnItemProductionQueued);
		GameEventDispatcher.AddListener(GameEventType.ProducerItemProduced, OnItemProduced);
		GameEventDispatcher.AddListener(GameEventType.ItemFarmed, OnItemFarmed);
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, OnBuildableBuilt);
		GameEventDispatcher.AddListener(GameEventType.MarkerPlaced, OnMarkerPlaced);
	}

	~GameStatsManager()
	{
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSpawned, OnLandmarkSpawned);
		GameEventDispatcher.RemoveListener(GameEventType.ActorRescue, OnActorEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ActorDeath, OnActorEvent);
		GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnRegionScouted);
		GameEventDispatcher.RemoveListener(GameEventType.ManualCameraMovement, OnCameraMovement);
		GameEventDispatcher.RemoveListener(GameEventType.ManualCameraRotation, OnCameraRotation);
		GameEventDispatcher.RemoveListener(GameEventType.ManualCameraZoom, OnCameraZoom);
		GameEventDispatcher.RemoveListener(GameEventType.CameraReset, OnCameraReset);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkNotificationWorking, OnLandmarkActionStarted);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkNotificationIdle, OnLandmarkActionStopped);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedMarkerItem, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedLandmarkItem, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedSalvagerItem, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ProducerItemQueued, OnItemProductionQueued);
		GameEventDispatcher.RemoveListener(GameEventType.ProducerItemProduced, OnItemProduced);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, OnBuildableBuilt);
		GameEventDispatcher.RemoveListener(GameEventType.MarkerPlaced, OnMarkerPlaced);
	}

	public void Clear()
	{
		_actorStats.Clear();
		RegionsScoutedCount = 0;
		_landmarkActionsInProgress.Clear();
		_salvagedMarkerItems.Clear();
		_salvagedLandmarkItems.Clear();
		_salvagedSalvagerItems.Clear();
		_itemProductionsQueued.Clear();
		_itemsProduced.Clear();
		_itemsFarmed.Clear();
		_buildablesBuilt.Clear();
		_markersPlaced.Clear();
	}

	public static int GetActorStat(ActorType type, ActorStat stat)
	{
		if (GameManager.GameStatsManager == null)
		{
			return 0;
		}
		return GameManager.GameStatsManager.GetActorStatValue(type, stat);
	}

	private ActorStats GetActorStats(ActorType type)
	{
		if (_actorStats.TryGetValue(type, out var value))
		{
			return value;
		}
		value = new ActorStats();
		_actorStats.Add(type, value);
		return value;
	}

	private int GetActorStatValue(ActorType type, ActorStat stat)
	{
		if (!_actorStats.TryGetValue(type, out var value))
		{
			return 0;
		}
		return value.GetValue(stat);
	}

	public int GetLandmarkActionsInProgressCount(LandmarkAction action)
	{
		if ((string)action.Title == null)
		{
			return 0;
		}
		return GetCount(_landmarkActionsInProgress, action.Title.mTerm);
	}

	public int GetSalvagedMarkerItemsCount(ItemProperties itemProperties)
	{
		return GetCount(_salvagedMarkerItems, itemProperties);
	}

	public int GetSalvagedLandmarkItemsCount(ItemProperties itemProperties)
	{
		return GetCount(_salvagedLandmarkItems, itemProperties);
	}

	public int GetSalvagedSalvagerItemCount(ItemProperties itemProperties)
	{
		return GetCount(_salvagedSalvagerItems, itemProperties);
	}

	public int GetItemProductionsQueuedCount(ItemProperties itemProperties)
	{
		return GetCount(_itemProductionsQueued, itemProperties);
	}

	public int GetProducedItemsCount(ItemProperties itemProperties)
	{
		return GetCount(_itemsProduced, itemProperties);
	}

	public int GetProducedItemsCount(ItemType itemType)
	{
		return GetItemCount(_itemsProduced, itemType);
	}

	public int GetFarmedItemCount(ItemProperties itemProperties)
	{
		return GetCount(_itemsFarmed, itemProperties);
	}

	public int GetBuildablesBuiltCount(BuildableProperties buildableProperties)
	{
		return GetCount(_buildablesBuilt, buildableProperties);
	}

	public int GetMarkersPlacedCount(ItemProperties itemProperties)
	{
		int num = 0;
		foreach (KeyValuePair<MarkerCursorProperties, int> item in _markersPlaced)
		{
			if ((item.Key.AllowedItemTags & itemProperties.Tags) != Item.Tags.None)
			{
				num += item.Value;
			}
		}
		return num;
	}

	private int GetItemCount(Dictionary<ItemProperties, int> countedItems, ItemType itemType)
	{
		Dictionary<ItemProperties, int>.Enumerator enumerator = countedItems.GetEnumerator();
		int num = 0;
		while (enumerator.MoveNext())
		{
			if (enumerator.Current.Key.ItemType == itemType)
			{
				num += enumerator.Current.Value;
			}
		}
		return num;
	}

	private void OnActorEvent(GameEvent gameEvent)
	{
		if (gameEvent is ActorEvent actorEvent)
		{
			ActorStats actorStats = GetActorStats(actorEvent.ActorDescriptor.ActorType);
			switch (gameEvent.EventType)
			{
			case GameEventType.ActorRescue:
				actorStats.RescuedCount++;
				actorStats.LastRescuedDay = GameManager.TimeManager.Days.Count;
				break;
			case GameEventType.ActorDeath:
				actorStats.DeathCount++;
				break;
			}
		}
	}

	private void OnRegionScouted(GameEvent gameEvent)
	{
		int regionsScoutedCount = RegionsScoutedCount + 1;
		RegionsScoutedCount = regionsScoutedCount;
	}

	private void OnCameraMovement(GameEvent gameEvent)
	{
		if (gameEvent is CameraGameEvent cameraGameEvent)
		{
			TotalCameraMovedDistance += cameraGameEvent.DistanceMoved;
		}
	}

	private void OnCameraRotation(GameEvent gameEvent)
	{
		if (gameEvent is CameraGameEvent cameraGameEvent)
		{
			TotalCameraRotationChanges += Mathf.Abs(cameraGameEvent.Rotation);
		}
	}

	private void OnCameraZoom(GameEvent gameEvent)
	{
		if (gameEvent is CameraGameEvent cameraGameEvent)
		{
			TotalCameraZoomChanges += Mathf.Abs(cameraGameEvent.Zoom);
		}
	}

	private void OnCameraReset(GameEvent gameEvent)
	{
		GameEventDispatcher.RemoveListener(GameEventType.CameraReset, OnCameraReset);
		HasEverResetCamera = true;
	}

	private void OnLandmarkSpawned(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent { LandmarkBehaviour: ActionsBehaviour landmarkBehaviour } && landmarkBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false))
		{
			int count = GameManager.TimeManager.Days.Count;
			ActorStats actorStats = GetActorStats(action.ActorType);
			actorStats.SpawnedCount++;
			actorStats.LastSpawnedDay = count;
		}
	}

	private void OnLandmarkActionStarted(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && landmarkNotificationEvent.LandmarkAction != null && (string)landmarkNotificationEvent.LandmarkAction.Title != null)
		{
			IncrementCount(_landmarkActionsInProgress, landmarkNotificationEvent.LandmarkAction.Title.mTerm);
		}
	}

	private void OnLandmarkActionStopped(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && landmarkNotificationEvent.LandmarkAction != null && (string)landmarkNotificationEvent.LandmarkAction.Title != null && _landmarkActionsInProgress.ContainsKey(landmarkNotificationEvent.LandmarkAction.Title.mTerm))
		{
			DecrementCount(_landmarkActionsInProgress, landmarkNotificationEvent.LandmarkAction.Title.mTerm);
		}
	}

	private void OnItemEvent(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent { ItemProperties: var itemProperties } agentActionItemPropertiesEvent)
		{
			switch (agentActionItemPropertiesEvent.EventType)
			{
			case GameEventType.AgentActionSalvagedMarkerItem:
				IncrementCount(_salvagedMarkerItems, itemProperties);
				break;
			case GameEventType.AgentActionSalvagedLandmarkItem:
				IncrementCount(_salvagedLandmarkItems, itemProperties);
				break;
			case GameEventType.AgentActionSalvagedSalvagerItem:
				IncrementCount(_salvagedSalvagerItems, itemProperties);
				break;
			}
		}
	}

	private void OnItemProductionQueued(GameEvent gameEvent)
	{
		if (gameEvent is ItemEvent itemEvent && itemEvent.ItemProperties != null)
		{
			IncrementCount(_itemProductionsQueued, itemEvent.ItemProperties);
		}
	}

	private void OnItemProduced(GameEvent gameEvent)
	{
		if (gameEvent is ItemEvent { Item: not null } itemEvent && itemEvent.Item.Properties != null)
		{
			IncrementCount(_itemsProduced, itemEvent.Item.Properties);
			DecrementCount(_itemProductionsQueued, itemEvent.Item.Properties);
		}
	}

	private void OnItemFarmed(GameEvent gameEvent)
	{
		if (gameEvent is ItemEvent { Item: not null } itemEvent && (bool)itemEvent.Item.Properties)
		{
			IncrementCount(_itemsFarmed, itemEvent.Item.Properties);
		}
	}

	private void OnBuildableBuilt(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent)
		{
			IncrementCount(_buildablesBuilt, buildableEvent.BuildableProperties);
		}
	}

	private void OnMarkerPlaced(GameEvent gameEvent)
	{
		if (gameEvent is MarkerEvent markerEvent)
		{
			IncrementCount(_markersPlaced, markerEvent.Marker.MarkerCursorProperties);
		}
	}

	private static void IncrementCount<TKey>(Dictionary<TKey, int> dictionary, TKey key)
	{
		if (!dictionary.ContainsKey(key))
		{
			dictionary[key] = 1;
		}
		else
		{
			dictionary[key]++;
		}
	}

	private static void DecrementCount<TKey>(Dictionary<TKey, int> dictionary, TKey key)
	{
		if (dictionary.ContainsKey(key) && dictionary[key] > 0)
		{
			dictionary[key]--;
		}
	}

	private static int GetCount<TKey>(Dictionary<TKey, int> dictionary, TKey key)
	{
		if (!dictionary.TryGetValue(key, out var value))
		{
			return 0;
		}
		return value;
	}
}
public class GraphManager : SceneBehaviour
{
	[Tooltip("Grid for the water surface.")]
	public Grid WaterSurfaceGraph;

	[Tooltip("NavMesh for the constructions.")]
	public NavMesh ConstructionGraph;

	[SerializeField]
	private int _openNodeHeapSize = 4096;

	public int OpenNodeHeapSize => _openNodeHeapSize;

	public int ClosedNodeListSize => WaterSurfaceGraph.MaximumSize + ConstructionGraph.MaximumSize;

	public void Initialize()
	{
		LoadingScreen.AddTask(WaterSurfaceGraph.Initialize);
		LoadingScreen.AddTask(ConstructionGraph.Initialize);
	}

	private void Update()
	{
		if (GameManager.Instance.InitializeEnvironment && GameSpeedManager.GameSpeed != GameSpeed.Zero)
		{
			Pathfinder.ProcessQueue();
		}
	}

	private void LateUpdate()
	{
		if (!GameManager.Instance.IntroScene)
		{
			ConstructionGraph.UpdateRootPosition();
		}
		PathfindingEvent.TryDispatch();
	}

	private void OnDrawGizmos()
	{
		DrawGraph(WaterSurfaceGraph);
		DrawGraph(ConstructionGraph);
	}

	private void OnDestroy()
	{
		WaterSurfaceGraph.Dispose();
		ConstructionGraph.Dispose();
	}

	public static void RefreshNavigatorPaths()
	{
	}

	private void DrawGraph(GraphBase graph)
	{
		if (graph != null && graph.DisplayGraph)
		{
			graph.Draw();
		}
	}

	public PathfindingNode ReturnNode(Target target, Navigator navigator, int deepestLevel = 16, bool onlyUnblocked = true, bool hasLineOfSight = false)
	{
		List<PathfindingNode> list = ListPool<PathfindingNode>.Get();
		if (Graph.TypesMatch(navigator.TargetGraphType, WaterSurfaceGraph.GraphType))
		{
			PathfindingNode pathfindingNode = WaterSurfaceGraph.ReturnNode(target, navigator, deepestLevel, onlyUnblocked, hasLineOfSight);
			if (pathfindingNode != null)
			{
				list.Add(pathfindingNode);
			}
		}
		if (Graph.TypesMatch(navigator.TargetGraphType, ConstructionGraph.GraphType))
		{
			PathfindingNode pathfindingNode2 = ConstructionGraph.ReturnNode(target, navigator, deepestLevel, onlyUnblocked, hasLineOfSight);
			if (pathfindingNode2 != null)
			{
				list.Add(pathfindingNode2);
			}
		}
		PathfindingNode result = ReturnClosestNode(list, target.transform.position);
		ListPool<PathfindingNode>.Add(list);
		return result;
	}

	public PathfindingNode ReturnNode(Vector3 position, Graph.Type graphType)
	{
		if (!TryReturnGraph(graphType, out var graph))
		{
			return null;
		}
		return graph.ReturnNode(position);
	}

	private PathfindingNode ReturnClosestNode(List<PathfindingNode> nodes, Vector3 position)
	{
		int count = nodes.Count;
		float num = float.MaxValue;
		PathfindingNode result = null;
		for (int i = 0; i < count; i++)
		{
			PathfindingNode pathfindingNode = nodes[i];
			float num2 = position.DistanceToLeveledSquared(pathfindingNode.RootPosition);
			if (num2 < num)
			{
				result = pathfindingNode;
				num = num2;
			}
		}
		return result;
	}

	private bool TryReturnGraph(Graph.Type graphType, out GraphBase graph)
	{
		switch (graphType)
		{
		case Graph.Type.WaterSurface:
			graph = WaterSurfaceGraph;
			return true;
		case Graph.Type.Constructions:
			graph = ConstructionGraph;
			return true;
		default:
			UnityEngine.Debug.LogErrorFormat("Returning a graph of Graph.type '{0}' is currently not implemented.", graphType);
			graph = null;
			return false;
		}
	}
}
public class HighlightManager : MonoBehaviour
{
	private HashSet<OutlineRendererComponent> _highlightedFlotsam = new HashSet<OutlineRendererComponent>();

	private OutlineRendererComponent _previousOutlineComponent;

	public void ClearHighlight(OutlineRendererComponent outlineRendererComponent)
	{
		if (!(outlineRendererComponent == null) && _highlightedFlotsam.Contains(outlineRendererComponent))
		{
			_highlightedFlotsam.Remove(outlineRendererComponent);
		}
	}

	public void ClearHighlights()
	{
		for (int i = 0; i < _highlightedFlotsam.Count; i++)
		{
			_highlightedFlotsam.ElementAt(i).GetComponentInParent<OutlineRendererComponent>().ResetOutline();
		}
		_highlightedFlotsam.Clear();
	}

	public void HighlightObject(OutlineRendererComponent outlineRendererComponent)
	{
		if (outlineRendererComponent != null)
		{
			outlineRendererComponent.UpdateSelectedObject();
		}
	}

	public void ResetOutlineHover()
	{
		if (_previousOutlineComponent != null)
		{
			_previousOutlineComponent.ResetOutline();
			_previousOutlineComponent = null;
		}
	}

	public void AddOutlineHover(SelectionLink selectionLink)
	{
		if ((bool)selectionLink.OutlineRenderer)
		{
			selectionLink.OutlineRenderer.UpdateHoverObject();
			_previousOutlineComponent = selectionLink.OutlineRenderer;
		}
	}

	public void DeselectAll(bool resetSelectedType = true)
	{
		OutlineRendererComponent componentInParent = Selector.Selection.GetComponentInParent<OutlineRendererComponent>();
		if (componentInParent != null)
		{
			componentInParent.ResetHighlightOutline();
		}
	}
}
public class PhysicsManager : MonoBehaviour
{
	[SerializeField]
	[Tooltip("The water plane in the world.")]
	private GameObject _waterPlane;

	[HideInInspector]
	public Vector3 MovingWorldDirection = Vector3.forward;

	[HideInInspector]
	public Vector3 MovingFlotsamDirection = Vector3.forward;

	[HideInInspector]
	public float MovingWorldForce;

	[HideInInspector]
	public float MovingFlotsamForce = 500f;

	[HideInInspector]
	public float FixedDeltaTime;

	[HideInInspector]
	public Vector3 MainForce;

	private Material _waterMaterial;

	private Vector2 _surfacePanSpeed1;

	private Vector2 _surfacePanSpeed2;

	private Vector2 _surfacePanBlendSpeed2;

	private Vector2 _surfaceNormalPanSpeed1;

	private Vector2 _surfaceNormalPanSpeed2;

	private Vector2 _distortionPanSpeed;

	public void Initialize()
	{
		MovingWorldForce = 0f;
		_waterMaterial = null;
		UpdateWorldMovement();
	}

	private void FixedUpdate()
	{
		MainForce = MovingFlotsamDirection * MovingFlotsamForce * Time.fixedUnscaledDeltaTime;
	}

	public void UpdateWorldMovement()
	{
		Vector3 relativeFlotsamDirection = GameManager.Settings.GameplaySettings.WorldPhysics.RelativeFlotsamDirection;
		Vector3 vector = relativeFlotsamDirection.normalized * (MovingWorldForce + GameManager.Settings.GameplaySettings.WorldPhysics.RelativeFlotsamSpeed);
		MovingFlotsamForce = vector.magnitude;
		if (MovingFlotsamForce > GameManager.Settings.GameplaySettings.WorldPhysics.MaximumFlotsamForce)
		{
			MovingFlotsamForce = GameManager.Settings.GameplaySettings.WorldPhysics.MaximumFlotsamForce;
		}
		MovingFlotsamDirection = vector.normalized;
	}

	private void CacheShaderSpeed()
	{
		_surfacePanSpeed1.x = _waterMaterial.GetFloat("_SurfacePanSpeedX");
		_surfacePanSpeed1.y = _waterMaterial.GetFloat("_SurfacePanSpeedY");
		_surfacePanSpeed2.x = _waterMaterial.GetFloat("_Surface2PanSpeedX");
		_surfacePanSpeed2.y = _waterMaterial.GetFloat("_Surface2PanSpeedY");
		_surfacePanBlendSpeed2.x = _waterMaterial.GetFloat("_Surface2BlendPanSpeedX");
		_surfacePanBlendSpeed2.y = _waterMaterial.GetFloat("_Surface2BlendPanSpeedY");
		_surfaceNormalPanSpeed1.x = _waterMaterial.GetFloat("_SurfaceNormalPanSpeed1X");
		_surfaceNormalPanSpeed1.y = _waterMaterial.GetFloat("_SurfaceNormalPanSpeed1Y");
		_surfaceNormalPanSpeed2.x = _waterMaterial.GetFloat("_SurfaceNormalPanSpeed2X");
		_surfaceNormalPanSpeed2.y = _waterMaterial.GetFloat("_SurfaceNormalPanSpeed2Y");
		_distortionPanSpeed.x = _waterMaterial.GetFloat("_DistortionPanSpeedX");
		_distortionPanSpeed.y = _waterMaterial.GetFloat("_DistortionPanSpeedY");
	}

	private void SetShaderSpeed(float speed)
	{
		_waterMaterial.SetFloat("_SurfacePanSpeedX", RotateWithWorld(_surfacePanSpeed1).x * speed);
		_waterMaterial.SetFloat("_SurfacePanSpeedY", RotateWithWorld(_surfacePanSpeed1).y * speed);
		_waterMaterial.SetFloat("_Surface2PanSpeedX", RotateWithWorld(_surfacePanSpeed2).x * speed);
		_waterMaterial.SetFloat("_Surface2PanSpeedY", RotateWithWorld(_surfacePanSpeed2).y * speed);
		_waterMaterial.SetFloat("_Surface2BlendPanSpeedX", RotateWithWorld(_surfacePanBlendSpeed2).x * speed);
		_waterMaterial.SetFloat("_Surface2BlendPanSpeedY", RotateWithWorld(_surfacePanBlendSpeed2).y * speed);
		_waterMaterial.SetFloat("_SurfaceNormalPanSpeed1X", RotateWithWorld(_surfaceNormalPanSpeed1).x * speed);
		_waterMaterial.SetFloat("_SurfaceNormalPanSpeed1Y", RotateWithWorld(_surfaceNormalPanSpeed1).y * speed);
		_waterMaterial.SetFloat("_SurfaceNormalPanSpeed2X", RotateWithWorld(_surfaceNormalPanSpeed2).x * speed);
		_waterMaterial.SetFloat("_SurfaceNormalPanSpeed2Y", RotateWithWorld(_surfaceNormalPanSpeed2).y * speed);
		_waterMaterial.SetFloat("_DistortionPanSpeedX", RotateWithWorld(_distortionPanSpeed).x * speed);
		_waterMaterial.SetFloat("_DistortionPanSpeedY", RotateWithWorld(_distortionPanSpeed).y * speed);
	}

	private Vector2 RotateWithWorld(Vector2 direction)
	{
		float num = Vector2.SignedAngle(new Vector2(0f, 1f), new Vector2(MovingWorldDirection.x, MovingWorldDirection.z));
		float num2 = Mathf.Sin(num * (MathF.PI / 180f));
		float num3 = Mathf.Cos(num * (MathF.PI / 180f));
		float x = direction.x;
		float y = direction.y;
		direction.x = num3 * x - num2 * y;
		direction.y = num2 * x + num3 * y;
		return direction;
	}
}
public class PrefabManager : MonoBehaviour
{
	public enum PrefabId
	{
		MarkerRangeHighlighter
	}

	[Serializable]
	private class ManagedPrefab
	{
		[SerializeField]
		private PrefabId _id;

		[SerializeField]
		private GameObject _prefab;

		[NonSerialized]
		private GameObject _instance;

		[NonSerialized]
		private UnityEngine.Component _component;

		public PrefabId Id => _id;

		public void Initialize()
		{
			_instance = UnityEngine.Object.Instantiate(_prefab);
			_instance.gameObject.SetActive(value: false);
		}

		public T GetInstance<T>() where T : UnityEngine.Component
		{
			T val;
			if (!(_component == null))
			{
				val = _component as T;
				if ((object)val != null)
				{
					goto IL_003f;
				}
			}
			val = (T)(_component = _instance.GetComponent<T>());
			goto IL_003f;
			IL_003f:
			return val;
		}

		public bool TryGetInstance<T>(out T instance) where T : UnityEngine.Component
		{
			instance = GetInstance<T>();
			return instance != null;
		}
	}

	[SerializeField]
	private ManagedPrefab[] _prefabs;

	public void Initialize()
	{
		ManagedPrefab[] prefabs = _prefabs;
		for (int i = 0; i < prefabs.Length; i++)
		{
			prefabs[i].Initialize();
		}
	}

	public bool TryGetInstance<T>(PrefabId id, out T instance) where T : UnityEngine.Component
	{
		ManagedPrefab[] prefabs = _prefabs;
		foreach (ManagedPrefab managedPrefab in prefabs)
		{
			if (managedPrefab.Id == id && managedPrefab.TryGetInstance<T>(out instance))
			{
				return true;
			}
		}
		instance = null;
		return false;
	}
}
public enum RadioMessageManagerState
{
	WaitingForRadioStation,
	WaitingForRadioSignals,
	ReceivingRadioSignals,
	ProcessingRadioSignal
}
public class RadioMessagesManager : IDialogueInteractable
{
	[Serializable]
	public class PersistentData
	{
		[OptionalField(VersionAdded = 2)]
		private readonly RadioMessageManagerState _state;

		[OptionalField(VersionAdded = 3)]
		private readonly RadioMessage.PersistentData[] _radioMessages;

		[OptionalField(VersionAdded = 2)]
		private readonly RadioMessage.PersistentData _activeRadioMessage;

		[OptionalField]
		private readonly int _activeRadionMessageDayReceived;

		[OptionalField(VersionAdded = 3)]
		private readonly int _radioBuiltDay;

		[OptionalField(VersionAdded = 2)]
		private readonly List<int> _pendingRadioMessages;

		[OptionalField(VersionAdded = 2)]
		private readonly List<int> _activeRadioMessages;

		[OptionalField(VersionAdded = 2)]
		private readonly List<int> _receivedRadioMessages;

		private readonly List<RadioMessage.PersistentData> _unreadRadioMessages;

		public PersistentData()
		{
			RadioMessagesManager radioMessagesManager = GameManager.RadioMessagesManager;
			if (radioMessagesManager != null)
			{
				_state = radioMessagesManager.State;
				_activeRadioMessage = RadioMessage.GetPersistentData(radioMessagesManager._activeRadioMessage);
				_activeRadionMessageDayReceived = radioMessagesManager._activeRadioMessageDayReceived;
				_radioBuiltDay = radioMessagesManager.RadioBuiltDay;
				_radioMessages = new RadioMessage.PersistentData[radioMessagesManager._radioMessages.Count];
				for (int i = 0; i < _radioMessages.Length; i++)
				{
					_radioMessages[i] = RadioMessage.GetPersistentData(radioMessagesManager._radioMessages[i]);
				}
			}
		}

		public void RestoreReferences()
		{
			RadioMessagesManager radioMessagesManager = GameManager.RadioMessagesManager;
			_ = GameManager.PersistenceManager;
			if (_radioMessages != null)
			{
				RadioMessage.PersistentData[] radioMessages = _radioMessages;
				for (int i = 0; i < radioMessages.Length; i++)
				{
					if (radioMessages[i].TryRestore(out var radioMessage))
					{
						radioMessagesManager.RestoreRadioMessage(radioMessage);
					}
				}
			}
			_activeRadioMessage?.TryRestore(out radioMessagesManager._activeRadioMessage);
			if (GameManager.TimeManager.Days.Count < _activeRadionMessageDayReceived)
			{
				UnityEngine.Debug.LogException(new Exception($"A game was restored where the last radio message was received in the future. Current day: {GameManager.TimeManager.Days.Count}, Received Day {_activeRadionMessageDayReceived}"));
				radioMessagesManager._activeRadioMessageDayReceived = 0;
			}
			else
			{
				radioMessagesManager._activeRadioMessageDayReceived = _activeRadionMessageDayReceived;
			}
			if (_radioBuiltDay == 0 && !radioMessagesManager.HasRadioStation())
			{
				radioMessagesManager.RadioBuiltDay = -1;
			}
			else
			{
				radioMessagesManager.RadioBuiltDay = _radioBuiltDay;
			}
			radioMessagesManager.SetState(_state);
		}
	}

	private readonly List<RadioMessage> _radioMessages = new List<RadioMessage>();

	private GameplaySettings _settings;

	private RadioMessage _activeRadioMessage;

	private int _activeRadioMessageDayReceived = -1;

	private bool _regionWasEntered;

	public RadioMessageManagerState State { get; private set; }

	public bool IsReceivingRadioSignals
	{
		get
		{
			if (CanReceiveRadioMessages() && State == RadioMessageManagerState.ReceivingRadioSignals)
			{
				return ReturnPendingRadioMessages().Count > 0;
			}
			return false;
		}
	}

	public DialogueTreeProperties DialogueProperties
	{
		get
		{
			if (!TryGetReceivingDialogue(out var dialogue))
			{
				return null;
			}
			return dialogue.Dialogue;
		}
	}

	public int RadioBuiltDay { get; private set; } = -1;

	public void Initialize()
	{
		Clear();
		_settings = GameManager.Settings.GameplaySettings;
		GameEventDispatcher.AddListener(GameEventType.RegionEntered, OnRegionEntered);
		GameEventDispatcher.AddListener(GameEventType.TransitionedFromMapView, OnTransitionedFromMapView);
		if ((bool)_settings.RadioQuest)
		{
			GameEventDispatcher.AddListener(GameEventType.QuestCompleted, OnQuestCompleted);
		}
		GameEventDispatcher.AddListener(GameEventType.BuildableBuilt, OnUpdateWaitingForRadioStation);
		GameEventDispatcher.AddListener(GameEventType.RadioMessageReceived, OnRadioMessageReceived);
		GameEventDispatcher.AddListener(GameEventType.GameStart, OnActiveRadioMessageEvent);
		GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnActiveRadioMessageEvent);
		GameEventDispatcher.AddListener(GameEventType.QuestUpdated, OnActiveRadioMessageEvent);
	}

	public void Clear()
	{
		State = RadioMessageManagerState.WaitingForRadioStation;
		RadioBuiltDay = -1;
		_radioMessages.Clear();
		_activeRadioMessage = null;
		_activeRadioMessageDayReceived = -1;
		GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
		GameEventDispatcher.RemoveListener(GameEventType.TransitionedFromMapView, OnTransitionedFromMapView);
		GameEventDispatcher.RemoveListener(GameEventType.QuestCompleted, OnQuestCompleted);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableBuilt, OnUpdateWaitingForRadioStation);
		GameEventDispatcher.RemoveListener(GameEventType.RadioMessageReceived, OnRadioMessageReceived);
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnActiveRadioMessageEvent);
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnActiveRadioMessageEvent);
		GameEventDispatcher.RemoveListener(GameEventType.QuestCompleted, OnActiveRadioMessageEvent);
	}

	public void OnDestroy()
	{
		Clear();
	}

	private IEnumerator UpdateWaitingForRadioStation(float delay)
	{
		yield return new WaitForSeconds(delay);
		OnUpdateWaitingForRadioStation(null);
	}

	private void OnUpdateWaitingForRadioStation(GameEvent gameEvent)
	{
		ReturnPendingRadioMessages();
		if (State == RadioMessageManagerState.WaitingForRadioStation && HasRadioStation() && StoryManager.IsQuestCompleted(_settings.RadioQuest) && HasPendingRadioMessages())
		{
			if (RadioBuiltDay < 0)
			{
				RadioBuiltDay = GameManager.TimeManager.Days.Count;
			}
			SetState((_activeRadioMessageDayReceived >= 0) ? RadioMessageManagerState.WaitingForRadioSignals : RadioMessageManagerState.ReceivingRadioSignals);
		}
	}

	private void OnQuestCompleted(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent && questEvent.Quest.Properties == _settings.RadioQuest)
		{
			CoroutineMotor.StartRoutine(UpdateWaitingForRadioStation(_settings.RadioQuestCompletedDelay));
		}
	}

	private void OnRadioMessageReceived(GameEvent gameEvent)
	{
		if (gameEvent is RadioMessageEvent { Message: not null } radioMessageEvent)
		{
			OnRadioMessageReceived(radioMessageEvent.Message);
		}
	}

	private void OnRadioMessageReceived(RadioMessage radioMessage)
	{
		if (_radioMessages.Remove(radioMessage))
		{
			_activeRadioMessage = radioMessage;
			_activeRadioMessage.Trigger();
			_activeRadioMessageDayReceived = _activeRadioMessage.DayReceived;
			SetState(RadioMessageManagerState.ProcessingRadioSignal);
		}
		else if (radioMessage != null)
		{
			string text = ((radioMessage != null) ? radioMessage.Properties.name : "NULL");
			UnityEngine.Debug.LogException(new Exception("Unable to removed received radio message '" + text + "'"));
		}
	}

	private void OnActiveRadioMessageEvent(GameEvent gameEvent = null)
	{
		if (State == RadioMessageManagerState.ProcessingRadioSignal)
		{
			if (_activeRadioMessage == null || _activeRadioMessage.IsCompleted())
			{
				SetState(HasRadioStation() ? RadioMessageManagerState.WaitingForRadioSignals : RadioMessageManagerState.WaitingForRadioStation);
			}
			else if (_activeRadioMessage.IsFailed())
			{
				UnityEngine.Debug.LogException(new Exception($"Radio message '{_activeRadioMessage.Properties}' has failed, adding it back to pending radio messages."));
				SetState(HasRadioStation() ? RadioMessageManagerState.WaitingForRadioSignals : RadioMessageManagerState.WaitingForRadioStation);
			}
			else
			{
				_activeRadioMessage.EvaluateOutOfRange(GameManager.WorldManager.World.TownheartWorldPosition, _settings.RadioMessageFailDistance);
			}
		}
	}

	private void OnRegionEntered(GameEvent gameEvent)
	{
		_regionWasEntered = CanReceiveRadioMessages();
	}

	private void OnTransitionedFromMapView(GameEvent gameEvent)
	{
		if (_regionWasEntered && CanReceiveRadioMessages())
		{
			OnActiveRadioMessageEvent();
			if (State == RadioMessageManagerState.WaitingForRadioSignals && _settings.RadioMessageDayInterval <= GameManager.TimeManager.Days.Count - _activeRadioMessageDayReceived && HasPendingRadioMessages())
			{
				SetState(RadioMessageManagerState.ReceivingRadioSignals);
			}
		}
		_regionWasEntered = false;
	}

	private void SetState(RadioMessageManagerState state, bool sendEvent = true)
	{
		if (State != state)
		{
			State = state;
			if (IsReceivingRadioSignals && sendEvent && TryGetReceivingDialogue(out var _))
			{
				DialogueGameEvent.DispatchDialogueStartRequest(this);
			}
			if (sendEvent)
			{
				GameEventDispatcher.Dispatch(GameEventType.RadioMessageManagerStateUpdated);
			}
		}
	}

	public List<RadioMessage> ReturnPendingRadioMessages()
	{
		RadioMessageProperties[] array = _settings.ReturnRadioMessages();
		foreach (RadioMessageProperties radioMessageProperties in array)
		{
			if (radioMessageProperties.IsAvailable() && !HasRadioMessage(radioMessageProperties))
			{
				_radioMessages.Insert(0, new RadioMessage(radioMessageProperties));
			}
		}
		return _radioMessages;
	}

	private bool HasRadioStation()
	{
		foreach (Buildable buildable in Community.PlayerCommunity.Buildables)
		{
			if (buildable.BuildPhase == BuildPhase.Finished && IsRadioStation(buildable))
			{
				return true;
			}
		}
		return false;
	}

	private bool IsRadioStation(Buildable buildable)
	{
		if ((bool)_settings)
		{
			return _settings.RadioStations.Contains(buildable.Properties);
		}
		return false;
	}

	public bool CanReceiveRadioMessages()
	{
		if (HasRadioStation() && WorldManager.CanAddNextTile())
		{
			foreach (WorldTileSpawningBlocker spawningBlocker in WorldManager.SpawningBlockers)
			{
				if (spawningBlocker.BlocksRadioMessages())
				{
					return false;
				}
			}
			return true;
		}
		return false;
	}

	private bool HasPendingRadioMessages()
	{
		if (CanReceiveRadioMessages())
		{
			return 0 < ReturnPendingRadioMessages().Count;
		}
		return false;
	}

	private bool HasRadioMessage(RadioMessageProperties properties)
	{
		foreach (RadioMessage radioMessage in _radioMessages)
		{
			if (radioMessage.Properties == properties)
			{
				return true;
			}
		}
		return false;
	}

	private bool TryGetReceivingDialogue(out DialogueBranchReference dialogue)
	{
		foreach (RadioMessage radioMessage in _radioMessages)
		{
			if (radioMessage.TryGetReceivingDialogue(out dialogue))
			{
				return true;
			}
		}
		if (_settings != null)
		{
			dialogue = _settings.RadioMessageReceivingDialogue;
			return true;
		}
		dialogue = default(DialogueBranchReference);
		return false;
	}

	public bool TryGetActiveRadioMessageQuest(out Quest quest)
	{
		if (_activeRadioMessage == null || _activeRadioMessage.IsFailed() || _activeRadioMessage.IsCompleted())
		{
			quest = null;
		}
		else
		{
			quest = _activeRadioMessage.Quest;
		}
		return quest != null;
	}

	public void OnDialogueResponse(DialogueResponseType response, Dialogue dialogue)
	{
	}

	public bool TryGetEntryPoint(out DialogueNodeProperties entryPoint)
	{
		entryPoint = null;
		if (TryGetReceivingDialogue(out var dialogue))
		{
			return dialogue.TryGetReference(out entryPoint);
		}
		return false;
	}

	public bool TryGetMainSpeaker(out AgentDescriptor mainSpeaker)
	{
		if ((bool)_settings && (bool)_settings.RadioTechnician)
		{
			mainSpeaker = _settings.RadioTechnician.GetDescriptor();
			if ((bool)mainSpeaker.Agent && mainSpeaker.Agent.IsAlive && mainSpeaker.Agent.Community == Community.PlayerCommunity)
			{
				return true;
			}
		}
		return StoryManager.DialogueContext.TryGetActor(DialogueContext.ActorType.FirstMate, out mainSpeaker);
	}

	private void RestoreRadioMessage(RadioMessage radioMessage)
	{
		if (radioMessage.Properties.IsAvailable())
		{
			foreach (RadioMessage radioMessage2 in _radioMessages)
			{
				if (radioMessage2.Properties == radioMessage.Properties)
				{
					UnityEngine.Debug.LogException(new Exception($"A Duplicate RadioMessage '{radioMessage.Properties}' was persisted."));
					return;
				}
			}
			_radioMessages.Add(radioMessage);
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception($"RadioMessage '{radioMessage.Properties}' was persisted, but it it is not available."));
		}
	}
}
public class ResourceManager : SceneBehaviour, IInventorySpaceLimiter
{
	private static Community _community;

	private static CommunityInventory _communityInventory;

	private Dictionary<ItemProperties, int> _resourceLimits = new Dictionary<ItemProperties, int>();

	private Dictionary<ItemProperties, int> _resourceCapacties = new Dictionary<ItemProperties, int>();

	private void Start()
	{
		Dictionary<ItemProperties, int>.Enumerator enumerator = _resourceLimits.GetEnumerator();
		while (enumerator.MoveNext())
		{
			if (0 < enumerator.Current.Value)
			{
				UpdateResourceCapacity(enumerator.Current.Key);
			}
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ItemFarmed, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ItemSalvagered, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ItemsProduced, OnItemEvent);
		GameEventDispatcher.RemoveListener(GameEventType.StoredItemTaken, OnItemEvent);
	}

	public void Initialize()
	{
		_community = Community.PlayerCommunity;
		_communityInventory = _community.Inventory;
		GameEventDispatcher.AddListener(GameEventType.ItemFarmed, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.ItemSalvagered, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.ItemsProduced, OnItemEvent);
		GameEventDispatcher.AddListener(GameEventType.StoredItemTaken, OnItemEvent);
	}

	public static bool AreItemsAvailable(ItemProperties itemProperties, int amount)
	{
		return _communityInventory.ReturnContainsItem(itemProperties, amount);
	}

	public static bool AreItemsAvailable(CountedItemProperty countedItem)
	{
		return _communityInventory.ReturnContainsItem(countedItem.ItemProperties, countedItem.Amount);
	}

	public static bool AreItemsAvailable(IEnumerable<CountedItemProperty> countedItems)
	{
		return _communityInventory.ReturnContainsItems(countedItems);
	}

	public static bool AreCommunityResourcesAvailable(CountedItemProperty[] resources)
	{
		if (!BuildingDevTools.InstantBuild && !BuildingDevTools.AutoSpawnResources)
		{
			return Community.PlayerCommunity.Inventory.ReturnContainsItems(resources);
		}
		return true;
	}

	public static bool TryReserveItems(ItemProperties itemProperties, int amount, out List<Item> reservedItems)
	{
		reservedItems = null;
		if (AreItemsAvailable(itemProperties, amount))
		{
			return _communityInventory.TryReserveItems(itemProperties, amount, out reservedItems);
		}
		return false;
	}

	public static bool TryReserveClosestItems(IPathfindingNodeProvider destination, ItemProperties itemProperties, int amount, out List<Item> reservedItems)
	{
		reservedItems = null;
		if (AreItemsAvailable(itemProperties, amount))
		{
			return _communityInventory.TryReserveClosestItems(destination, itemProperties, amount, out reservedItems);
		}
		return false;
	}

	public static List<Item> ReserveClosestItems(IPathfindingNodeProvider destination, IReadOnlyList<CountedItemProperty> requiredResources)
	{
		if (requiredResources.IsNullOrEmpty())
		{
			return new List<Item>();
		}
		if (Community.PlayerCommunity.Inventory.TryReturnReserveClosestItems(destination, requiredResources, out var reservedItems))
		{
			return reservedItems;
		}
		throw new NotImplementedException();
	}

	public static List<Item> ReserveClosestItems(IPathfindingNodeProvider destination, CountedItemProperty[] requiredResources)
	{
		if (Community.PlayerCommunity.Inventory.TryReturnReserveClosestItems(destination, requiredResources, out var reservedItems))
		{
			return reservedItems;
		}
		throw new NotImplementedException();
	}

	public static int CountAvailableItems(ItemProperties itemProperties)
	{
		return Community.PlayerCommunity.Inventory.ReturnCount(itemProperties);
	}

	public void SpawnItemToInventory(Inventory inventory, Item item)
	{
		if (inventory == null)
		{
			PajamaLlama.Debugs.Debugger.Warning($"Could not spawn item {item.Properties.name} because no valid inventory was passed.");
		}
		else
		{
			inventory.AddItem(item, SubInventoryType.Storage);
		}
	}

	public void RestoreResourceLimits(Dictionary<ItemProperties, int> limits)
	{
		int defaultProductionLimit = GameManager.Settings.ItemSettings.DefaultProductionLimit;
		_communityInventory = Community.PlayerCommunity.Inventory;
		foreach (KeyValuePair<ItemProperties, int> limit in limits)
		{
			if (limit.Value != defaultProductionLimit)
			{
				if (_resourceLimits.ContainsKey(limit.Key))
				{
					_resourceLimits[limit.Key] = limit.Value;
				}
				else
				{
					_resourceLimits.Add(limit.Key, limit.Value);
				}
			}
		}
	}

	public void AddResourceLimit(ItemProperties resource)
	{
		int defaultProductionLimit = GameManager.Settings.ItemSettings.DefaultProductionLimit;
		_resourceLimits.TryAdd(resource, defaultProductionLimit);
	}

	public void AddProductionLimits(IItemProducer producer)
	{
		if (producer.ProducedItems.IsNullOrEmpty())
		{
			return;
		}
		foreach (ItemProperties producedItem in producer.ProducedItems)
		{
			AddResourceLimit(producedItem);
		}
	}

	public void UpdateResourceLimit(ItemProperties resource, int limit)
	{
		if (_resourceLimits.ContainsKey(resource))
		{
			_resourceLimits[resource] = limit;
			UpdateResourceCapacity(resource);
		}
	}

	public bool IsResourceCapacityReached(ItemProperties properties)
	{
		if (_resourceCapacties.TryGetValue(properties, out var value))
		{
			return value <= 0;
		}
		return false;
	}

	public bool IsProductionLimitReached(ItemProperties itemProperties, int amount = 1)
	{
		if (_resourceCapacties.TryGetValue(itemProperties, out var value))
		{
			foreach (IItemProducer producer in _community.Producers)
			{
				value -= producer.GetItemsInProductionCount(itemProperties);
			}
			return value < amount;
		}
		return false;
	}

	private void UpdateResourceCapacity(ItemProperties itemProperties)
	{
		if (itemProperties == null || !_resourceLimits.TryGetValue(itemProperties, out var value))
		{
			return;
		}
		if (value < 0)
		{
			_resourceCapacties.Remove(itemProperties);
			return;
		}
		int num = _communityInventory.ReturnStoredItemCount(itemProperties);
		int value2 = value - num;
		if (!_resourceCapacties.TryAdd(itemProperties, value2))
		{
			_resourceCapacties[itemProperties] = value2;
		}
		ItemEvent.Dispatch(GameEventType.ItemResourceLimitUpdated, itemProperties);
	}

	public bool FitsItem(Item item)
	{
		if (!_resourceCapacties.TryGetValue(item.Properties, out var value) || 0 < value)
		{
			return _communityInventory.FitsItem(item);
		}
		return false;
	}

	public bool FitsItem(ItemProperties itemProperties)
	{
		if (!_resourceCapacties.TryGetValue(itemProperties, out var value) || 0 < value)
		{
			return _communityInventory.FitsItem(itemProperties);
		}
		return false;
	}

	public int GetCapacity(ItemProperties itemProperties)
	{
		return ReturnItemCapacity(itemProperties);
	}

	public bool HasResourceLimit()
	{
		return 0 < _resourceLimits.Count;
	}

	public Dictionary<ItemProperties, int> ReturnResourceLimits()
	{
		return _resourceLimits;
	}

	public int ReturnResourceLimit(ItemProperties resource)
	{
		if (_resourceLimits.TryGetValue(resource, out var value))
		{
			return value;
		}
		return -1;
	}

	public int ReturnItemCapacity(ItemProperties itemProperties)
	{
		if (_resourceCapacties.TryGetValue(itemProperties, out var value))
		{
			return Mathf.Min(value, _communityInventory.ReturnItemCapacity(itemProperties));
		}
		return _communityInventory.ReturnItemCapacity(itemProperties);
	}

	private void OnItemEvent(GameEvent gameEvent)
	{
		if (!(gameEvent is ItemEvent { EventType: var eventType } itemEvent))
		{
			return;
		}
		switch (eventType)
		{
		case GameEventType.ItemFarmed:
		case GameEventType.ItemSalvagered:
		case GameEventType.StoredItemTaken:
			UpdateResourceCapacity(itemEvent.ItemProperties);
			break;
		case GameEventType.ItemsProduced:
		{
			foreach (ItemProperties producedItem in itemEvent.ProducedItems)
			{
				_ = producedItem;
				UpdateResourceCapacity(itemEvent.ItemProperties);
			}
			break;
		}
		}
	}
}
