public class StoryManager : SceneBehaviour
{
	[Serializable]
	public class PersistentData
	{
		[OptionalField(VersionAdded = 2)]
		private readonly List<ushort> _activeDistressSignalSenderIDs = new List<ushort>();

		[OptionalField(VersionAdded = 3)]
		private readonly List<Quest.PersistentData> _pendingQuests = new List<Quest.PersistentData>();

		private readonly List<Quest.PersistentData> _questsData = new List<Quest.PersistentData>();

		[OptionalField(VersionAdded = 4)]
		private readonly List<Quest.PersistentData> _restartedQuests = new List<Quest.PersistentData>();

		[OptionalField(VersionAdded = 2)]
		private readonly List<int> _triggeredTutorialNotificationIDs = new List<int>();

		[OptionalField(VersionAdded = 3)]
		private readonly IScenarioPersistentData _scenarioPersistentData;

		private readonly int _currentTutorialIndex = -1;

		public PersistentData()
		{
			StoryManager storyManager = GameManager.StoryManager;
			if (storyManager._activeDistressSignalQuests.Count > 0)
			{
				_activeDistressSignalSenderIDs = new List<ushort>(storyManager._activeDistressSignalQuests.Count);
				foreach (AgentDescriptor key in storyManager._activeDistressSignalQuests.Keys)
				{
					_activeDistressSignalSenderIDs.Add(key.UniqueID);
				}
			}
			foreach (Quest pendingQuest in storyManager._pendingQuests)
			{
				PersistQuest(pendingQuest, _pendingQuests);
			}
			using ListPool<Quest>.List list = ListPool<Quest>.Get();
			list.AddRange(storyManager._activeQuests);
			list.AddRange(storyManager._completedQuests);
			list.AddRange(storyManager._failedQuests);
			foreach (Quest item in list)
			{
				PersistQuest(item, _questsData);
			}
			foreach (Quest restartedQuest in storyManager._restartedQuests)
			{
				PersistQuest(restartedQuest, _restartedQuests);
			}
			storyManager._trigger.PopulateTriggeredTutorials(_triggeredTutorialNotificationIDs);
			if ((bool)storyManager._scenarioInstance)
			{
				_scenarioPersistentData = storyManager._scenarioInstance.GetPersistentData();
			}
		}

		private void PersistQuest(Quest quest, List<Quest.PersistentData> questDataList)
		{
			if (quest == null)
			{
				UnityEngine.Debug.LogException(new NullReferenceException("Unable to persist NULL quest reference"));
			}
			else
			{
				questDataList.Add(new Quest.PersistentData(quest));
			}
		}

		public void Restore()
		{
			StoryManager storyManager = GameManager.StoryManager;
			foreach (Quest.PersistentData questsDatum in _questsData)
			{
				questsDatum.Restore();
			}
			RestoreRestartedQuests(storyManager._restartedQuests);
			if (!_triggeredTutorialNotificationIDs.IsNullOrEmpty())
			{
				storyManager._trigger.RestoreTriggeredTutorials(_triggeredTutorialNotificationIDs);
			}
		}

		public void RestoreReferences()
		{
			StoryManager storyManager = GameManager.StoryManager;
			if (_activeDistressSignalSenderIDs != null)
			{
				foreach (ushort activeDistressSignalSenderID in _activeDistressSignalSenderIDs)
				{
					if (ActorDescriptor.TryGet<AgentDescriptor>(out var actorDescriptor, activeDistressSignalSenderID))
					{
						Quest quest = new Quest(storyManager._distressSignalQuest);
						storyManager._activeDistressSignalQuests.Add(actorDescriptor, quest);
						quest.Start(actorDescriptor);
					}
				}
			}
			RestorePendingQuests(storyManager._pendingQuests);
			foreach (Quest.PersistentData questsDatum in _questsData)
			{
				questsDatum.RestoreReferences();
			}
			if (_scenarioPersistentData != null)
			{
				storyManager._scenarioInstance = _scenarioPersistentData.Restore(storyManager._prototypeScenario);
			}
			else
			{
				storyManager.InstantiateScenario(storyManager._prototypeScenario);
			}
		}

		private void RestoreRestartedQuests(List<Quest> restoredQuests)
		{
			if (_restartedQuests == null)
			{
				return;
			}
			foreach (Quest.PersistentData restartedQuest in _restartedQuests)
			{
				if (restartedQuest.TryRestore(out var instance))
				{
					restoredQuests.Add(instance);
				}
			}
		}

		private void RestorePendingQuests(List<Quest> restoredQuests)
		{
			if (_pendingQuests == null)
			{
				return;
			}
			foreach (Quest.PersistentData pendingQuest in _pendingQuests)
			{
				if (ActorDescriptor.TryGet<AgentDescriptor>(out var actorDescriptor, pendingQuest.QuestGiverID))
				{
					restoredQuests.Add(new Quest(actorDescriptor.AgentProfile.Quest, actorDescriptor));
				}
			}
		}
	}

	[Header("Game Start")]
	[Header("Tutorials")]
	[SerializeField]
	private ScenarioBase _tutorialScenario;

	[SerializeField]
	private TutorialTrigger _trigger;

	[Header("Main Narrative")]
	[SerializeField]
	private QuestProperties _distressSignalQuest;

	[SerializeField]
	private ScenarioBase _storyModeScenario;

	[Header("Persistence")]
	[SerializeField]
	[Tooltip("A reference to the PrototypeScenario to restore games that were saved before scenario's were split up (0.9.0e9")]
	private PrototypeScenario _prototypeScenario;

	private readonly List<Quest> _pendingDistressSignals = new List<Quest>();

	private readonly Dictionary<AgentDescriptor, Quest> _activeDistressSignalQuests = new Dictionary<AgentDescriptor, Quest>();

	private readonly List<Quest> _pendingQuests = new List<Quest>();

	private readonly List<Quest> _activeQuests = new List<Quest>();

	private readonly List<Quest> _completedQuests = new List<Quest>();

	private readonly List<Quest> _failedQuests = new List<Quest>();

	private readonly List<Quest> _restartedQuests = new List<Quest>();

	private readonly List<Quest> _logQuests = new List<Quest>();

	private ScenarioBase _scenarioInstance;

	private static Quest _lastStartedQuest = null;

	private bool _started;

	public IReadOnlyList<Quest> ActiveQuests => _activeQuests;

	public static DialogueContext DialogueContext { get; } = new DialogueContext();

	public static int LastRegionScoutedDay { get; private set; }

	public static Quest TrackedQuest { get; set; }

	private void Start()
	{
		DialogueContext.Initialize();
		ScenarioBase successor;
		if (_scenarioInstance == null)
		{
			if (Session.Profile.ActiveRun.IsTutorial && _tutorialScenario != null)
			{
				InstantiateScenario(_tutorialScenario);
			}
			else if (_storyModeScenario != null)
			{
				InstantiateScenario(_storyModeScenario);
			}
		}
		else if (_scenarioInstance.TryGetSuccessor(out successor))
		{
			InstantiateScenario(successor);
		}
		GameEventDispatcher.AddListener(GameEventType.QuestStarted, OnQuestStarted);
		GameEventDispatcher.AddListener(GameEventType.QuestFailed, OnQuestFailed);
		GameEventDispatcher.AddListener(GameEventType.QuestAbandoned, OnQuestAbandoned);
		if ((bool)_scenarioInstance)
		{
			_scenarioInstance.Start();
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception("StoryManager could not start scenario, because the scenario is NULL!"));
		}
		StartActiveQuests();
		_started = true;
		GameEventDispatcher.Dispatch(GameEventType.StoryManagerStart);
	}

	private void Update()
	{
		for (int num = _activeQuests.Count - 1; num >= 0; num--)
		{
			Quest quest = _activeQuests[num];
			switch (quest.QuestState)
			{
			case Quest.State.Completed:
				_activeQuests.RemoveAt(num);
				_completedQuests.Add(quest);
				GameEvent.Dispatch(GameEventType.CompletedQuestsUpdated);
				break;
			case Quest.State.Failed:
			case Quest.State.Abandoned:
				_activeQuests.Remove(quest);
				_failedQuests.Add(quest);
				GameEvent.Dispatch(GameEventType.FailedQuestsUpdated);
				break;
			}
		}
		_trigger.Update();
	}

	private void OnDestroy()
	{
		Clear();
		DialogueContext.Uninitialize();
		if ((bool)_scenarioInstance)
		{
			_scenarioInstance.Destroy();
		}
	}

	public void Initialize()
	{
		_pendingQuests.Clear();
		_activeQuests.Clear();
		_completedQuests.Clear();
		_trigger.Initialize();
	}

	private void InstantiateScenario(ScenarioBase scenario)
	{
		if (_scenarioInstance != null)
		{
			_scenarioInstance.Destroy();
		}
		_scenarioInstance = scenario.GetInstance();
	}

	private void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnRegionScouted);
		GameEventDispatcher.RemoveListener(GameEventType.QuestFailed, OnQuestFailed);
		GameEventDispatcher.RemoveListener(GameEventType.QuestAbandoned, OnQuestAbandoned);
	}

	public void Clear()
	{
		TrackedQuest = null;
		_activeDistressSignalQuests.Clear();
		_activeQuests.Clear();
		_completedQuests.Clear();
		DialogueContext.Clear();
		Uninitialize();
		_trigger.Reset();
	}

	protected override void OnGameStart()
	{
	}

	private void StartActiveQuests()
	{
		for (int num = _activeQuests.Count - 1; num >= 0; num--)
		{
			Quest quest = _activeQuests[num];
			Quest.State questState = quest.QuestState;
			if ((uint)questState <= 1u)
			{
				quest.Start();
			}
		}
	}

	private bool HasDistressSignal(AgentDescriptor actorDescriptor)
	{
		foreach (Quest pendingDistressSignal in _pendingDistressSignals)
		{
			if (pendingDistressSignal.QuestGiver == actorDescriptor)
			{
				return true;
			}
		}
		return _activeDistressSignalQuests.ContainsKey(actorDescriptor);
	}

	private void PopulateLogQuests(List<QuestType> questLogTypes)
	{
		_logQuests.Clear();
		PopulateLogQuests(_activeQuests, questLogTypes);
		PopulateLogQuests(_completedQuests, questLogTypes);
	}

	private void PopulateLogQuests(IEnumerable<Quest> quests, List<QuestType> questLogTypes)
	{
		foreach (Quest quest in quests)
		{
			if (questLogTypes.Contains(quest.Properties.QuestType))
			{
				_logQuests.Add(quest);
			}
		}
	}

	private Quest p_StartQuest(QuestProperties questProperties, AgentDescriptor questGiver, float delay)
	{
		if (!_started)
		{
			return null;
		}
		if (p_TryGetQuest(out var quest, questProperties))
		{
			switch (quest.QuestState)
			{
			case Quest.State.Completed:
				if (questProperties.IsRestartable)
				{
					_completedQuests.Remove(quest);
					_restartedQuests.Add(quest);
					quest = new Quest(questProperties);
					break;
				}
				UnityEngine.Debug.LogException(new Exception($"Unable to restart Quest '{questProperties}'. Could you have forgotten to toggle the 'Is Restartable' flag on the QuestProperties?"));
				return null;
			default:
				UnityEngine.Debug.LogException(new Exception($"Unable to start Quest '{questProperties}' in QuestState.{quest.QuestState}. Not implemented"));
				return null;
			case Quest.State.NotStarted:
				break;
			}
		}
		else
		{
			quest = new Quest(questProperties);
		}
		_activeQuests.AddUnique(quest);
		if (delay > 0f)
		{
			StartCoroutine(quest.DelayedStart(questGiver, delay));
		}
		else
		{
			quest.Start(questGiver);
		}
		return quest;
	}

	private Construction SpawnTownheart()
	{
		Vector3 positionTownheart = GameManager.Settings.SessionSettings.StartingScenario.PositionTownheart;
		Buildable buildable = ((!Session.Profile.ActiveRun.TownheartProperties) ? GameManager.Settings.SessionSettings.StartingScenario.Townheart : Session.Profile.ActiveRun.TownheartProperties.Prefab);
		Buildable buildable2 = Buildable.Place(buildable, positionTownheart, Quaternion.identity, 0, instantPlacement: true);
		if (buildable2.TryReturnBuildableExtendable<MooringPoint>(out var buildableExtendable))
		{
			buildableExtendable.SpawnStartingBoat();
		}
		return buildable2.ReturnExtendable<Construction>();
	}

	public bool IsActiveQuest(QuestProperties questProperties)
	{
		int count = _activeQuests.Count;
		while (0 < count--)
		{
			if (_activeQuests[count].Properties == questProperties)
			{
				return true;
			}
		}
		return false;
	}

	private bool p_TryGetQuest(out Quest quest, QuestProperties properties)
	{
		quest = _pendingQuests.Find((Quest pendingQuest) => pendingQuest.Properties == properties);
		if (quest == null)
		{
			quest = _activeQuests.Find((Quest activeQuest) => activeQuest.Properties == properties);
		}
		if (quest == null)
		{
			quest = _completedQuests.Find((Quest completedQuest) => completedQuest.Properties == properties);
		}
		return quest != null;
	}

	public static void StartScenario(ScenarioBase scenario)
	{
		if (TryGetInstance(out var instance))
		{
			instance.InstantiateScenario(scenario);
			instance._scenarioInstance.Start();
		}
	}

	public static bool StartDistressSignal(AgentDescriptor signalSender)
	{
		if (signalSender.DialogueProperties == null || !signalSender.DialogueProperties.HasDialogueBranchType(DialogueBranchType.DistressSignal) || !TryGetInstance(out var instance) || instance.HasDistressSignal(signalSender))
		{
			return false;
		}
		Quest quest = new Quest(instance._distressSignalQuest, signalSender);
		if (quest.TryStart())
		{
			instance._pendingDistressSignals.Add(quest);
			return true;
		}
		return false;
	}

	public static bool TryStartPendingQuest(Agent agent)
	{
		if (!TryGetInstance(out var instance))
		{
			return false;
		}
		foreach (Quest pendingQuest in instance._pendingQuests)
		{
			if (pendingQuest.QuestGiver == agent.Descriptor)
			{
				pendingQuest.TryStart();
				return true;
			}
		}
		return false;
	}

	public static void StartQuest(Quest quest)
	{
		if (TryGetInstance(out var instance))
		{
			if (instance._pendingQuests.Remove(quest))
			{
				quest.Start(quest.QuestGiver);
				instance._activeQuests.Add(quest);
			}
			else if (instance._pendingDistressSignals.Remove(quest))
			{
				quest.Start(quest.QuestGiver);
				instance._activeDistressSignalQuests.Add(quest.QuestGiver, quest);
			}
		}
	}

	public static Quest StartQuest(QuestProperties questProperties, AgentDescriptor questGiver = null, float delay = 0f)
	{
		if (!TryGetInstance(out var instance))
		{
			return null;
		}
		return instance.p_StartQuest(questProperties, questGiver, delay);
	}

	public static void RestoreQuest(Quest quest)
	{
		if (TryGetInstance(out var instance))
		{
			switch (quest.QuestState)
			{
			case Quest.State.NotStarted:
			case Quest.State.Started:
				instance._activeQuests.Add(quest);
				break;
			case Quest.State.Completed:
				instance._completedQuests.Add(quest);
				break;
			case Quest.State.Failed:
			case Quest.State.Abandoned:
				instance._failedQuests.Add(quest);
				break;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException($"Unable to restore quest with Quest.State '{quest.QuestState}'"));
				break;
			}
		}
	}

	public static bool TryGetQuest(QuestProperties properties, out Quest questInstance)
	{
		questInstance = null;
		if (TryGetInstance(out var instance))
		{
			return instance.p_TryGetQuest(out questInstance, properties);
		}
		return false;
	}

	public static bool HasAnyActiveQuest()
	{
		if (TryGetInstance(out var instance))
		{
			return instance._activeQuests.Count > 0;
		}
		return false;
	}

	public static bool IsQuestActiveOrCompleted(QuestProperties questProperties)
	{
		if (TryGetInstance(out var instance))
		{
			foreach (Quest activeQuest in instance._activeQuests)
			{
				if (activeQuest.Properties == questProperties)
				{
					return true;
				}
			}
			foreach (Quest completedQuest in instance._completedQuests)
			{
				if (completedQuest.Properties == questProperties)
				{
					return true;
				}
			}
		}
		return false;
	}

	public static bool IsQuestActive(QuestProperties questProperties)
	{
		if (TryGetInstance(out var instance))
		{
			return instance.IsActiveQuest(questProperties);
		}
		return false;
	}

	public static bool IsQuestCompleted(QuestProperties questProperties)
	{
		if (!TryGetInstance(out var instance) || instance._completedQuests.IsNullOrEmpty())
		{
			return false;
		}
		foreach (Quest completedQuest in instance._completedQuests)
		{
			if (completedQuest.Properties == questProperties)
			{
				return true;
			}
		}
		return false;
	}

	public static void QueueWorldTile(TileGeneratorBase tile, int indexOffset = 0, int minimumIndex = 0)
	{
		if (TryGetScenarioInstance(out var scenario))
		{
			scenario.QueueWorldTile(tile, indexOffset, minimumIndex);
		}
	}

	private static bool TryGetInstance(out StoryManager instance)
	{
		instance = GameManager.StoryManager;
		return instance;
	}

	private static bool TryGetScenarioInstance(out ScenarioBase scenario)
	{
		scenario = (GameManager.StoryManager ? GameManager.StoryManager._scenarioInstance : null);
		return scenario;
	}

	public static bool TryGetLogQuests(out List<Quest> logQuests, List<QuestType> questLogTypes)
	{
		if (TryGetInstance(out var instance))
		{
			instance.PopulateLogQuests(questLogTypes);
			logQuests = instance._logQuests;
			return logQuests.Count > 0;
		}
		logQuests = null;
		return false;
	}

	public static bool IsActiveQuest(Quest quest)
	{
		if (!quest.IsCompleted)
		{
			if (TrackedQuest != null || _lastStartedQuest != quest)
			{
				return TrackedQuest == quest;
			}
			return true;
		}
		return false;
	}

	public static bool TryGetActiveQuest(out Quest quest)
	{
		quest = null;
		if (TryGetInstance(out var _))
		{
			if (TrackedQuest != null && !TrackedQuest.IsCompleted)
			{
				quest = TrackedQuest;
			}
			else
			{
				quest = _lastStartedQuest;
			}
		}
		if (quest != null)
		{
			return !quest.IsCompleted;
		}
		return false;
	}

	public static bool TryGetQuestLogQuest(out Quest quest)
	{
		if (TryGetActiveQuest(out quest))
		{
			return true;
		}
		quest = null;
		if (TryGetInstance(out var instance))
		{
			if (instance._activeQuests.Count > 0)
			{
				List<Quest> activeQuests = instance._activeQuests;
				quest = activeQuests[activeQuests.Count - 1];
			}
			else if (instance._completedQuests.Count > 0)
			{
				List<Quest> completedQuests = instance._completedQuests;
				quest = completedQuests[completedQuests.Count - 1];
			}
		}
		return quest != null;
	}

	private void OnRegionScouted(GameEvent gameEvent)
	{
		LastRegionScoutedDay = GameManager.TimeManager.Days.Count;
	}

	private void OnQuestStarted(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent)
		{
			_lastStartedQuest = questEvent.Quest;
			if (_activeQuests.AddUnique(questEvent.Quest))
			{
				_failedQuests.Remove(questEvent.Quest);
				_completedQuests.Remove(questEvent.Quest);
			}
		}
	}

	private void OnQuestFailed(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent)
		{
			if (_pendingDistressSignals.Remove(questEvent.Quest))
			{
				UnityEngine.Debug.LogWarning(string.Format("Pending distriss signal quest for actor '{0}' failed!", (questEvent.Quest.QuestGiver == null) ? "NULL" : questEvent.Quest.QuestGiver.Name));
			}
			if (questEvent.Quest.QuestGiver != null && _activeDistressSignalQuests.Remove(questEvent.Quest.QuestGiver))
			{
				UnityEngine.Debug.LogWarning(string.Format("Active distriss signal quest for actor '{0}' failed!", (questEvent.Quest.QuestGiver == null) ? "NULL" : questEvent.Quest.QuestGiver.Name));
			}
			if (_pendingQuests.Remove(questEvent.Quest))
			{
				UnityEngine.Debug.LogWarning($"Pending quest '{questEvent.Quest.Properties}' failed!");
			}
			if (_activeQuests.Remove(questEvent.Quest))
			{
				UnityEngine.Debug.LogWarning($"Active quest '{questEvent.Quest.Properties}' failed!");
			}
			_failedQuests.Add(questEvent.Quest);
		}
	}

	private void OnQuestAbandoned(GameEvent gameEvent)
	{
		OnQuestFailed(gameEvent);
	}

	public void EndGame()
	{
		GameManager.UIManager.DisplayPanel(PanelID.GameOver);
	}
}
public class TerrainManager : SceneBehaviour
{
	private struct RegionTile
	{
		public WorldRegionType RegionType;

		public GameObject Tile;

		public RegionTile(WorldRegionType regionType, GameObject tile)
		{
			RegionType = regionType;
			Tile = tile;
		}
	}

	private readonly Dictionary<WorldRegionType, List<GameObject>> _pooledRegionTiles = new Dictionary<WorldRegionType, List<GameObject>>();

	private RegionTile[,] _tiles = new RegionTile[1, 1];

	private int _gridWidth;

	private int _gridHeight = 1;

	private float _tileWidth;

	private float _tileHeight;

	private float _horizontalGridOffset;

	private float _verticalGridOffset;

	private int _cameraOffsetX;

	private int _cameraOffsetY;

	private Vector3 _townheartWorldPosition;

	private Quaternion _townheartWorldRotation;

	private void Start()
	{
		World world = GameManager.WorldManager.World;
		if (world != null)
		{
			_townheartWorldPosition = world.TownheartWorldPosition;
			_townheartWorldRotation = world.TownheartRotation;
			OnTownheartMoved();
			GameEventDispatcher.AddListener(GameEventType.TownheartMoved, OnTownheartMoved);
		}
	}

	private void Update()
	{
		if (!GameManager.Instance.InitializeEnvironment)
		{
			return;
		}
		Vector3 cameraPosition = CameraController.Instance.CameraPosition;
		int num = (int)cameraPosition.x / (int)(_horizontalGridOffset * 0.5f);
		int num2 = (int)cameraPosition.z / (int)(_verticalGridOffset * 0.5f);
		if (num != _cameraOffsetX)
		{
			int cameraOffsetX = _cameraOffsetX;
			_cameraOffsetX = num;
			if (num > cameraOffsetX)
			{
				ShiftTilesLeft();
			}
			else
			{
				ShiftTilesRight();
			}
		}
		if (num2 != _cameraOffsetY)
		{
			int cameraOffsetY = _cameraOffsetY;
			_cameraOffsetY = num2;
			if (num2 > cameraOffsetY)
			{
				ShiftTilesDown();
			}
			else
			{
				ShiftTilesUp();
			}
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.TownheartMoved, OnTownheartMoved);
	}

	public void Initialize()
	{
		_tileWidth = GameManager.Settings.GameplaySettings.TerrainProperties.TileWidth;
		_tileHeight = GameManager.Settings.GameplaySettings.TerrainProperties.TileLength;
		_gridWidth = Mathf.CeilToInt(GameManager.Settings.GameplaySettings.TerrainProperties.GridSize / _tileWidth);
		_gridHeight = Mathf.CeilToInt(GameManager.Settings.GameplaySettings.TerrainProperties.GridSize / _tileHeight);
		_horizontalGridOffset = (float)(_gridWidth - 1) * _tileWidth * 0.5f;
		_verticalGridOffset = (float)(_gridHeight - 1) * _tileHeight * 0.5f;
		_tiles = new RegionTile[_gridWidth, _gridHeight];
	}

	private void OnTownheartMoved(GameEvent gameEvent = null)
	{
		if (gameEvent is MovementEvent movementEvent)
		{
			_townheartWorldPosition = movementEvent.PositionTo;
			_townheartWorldRotation = movementEvent.RotationTo;
		}
		for (int i = 0; i < _gridWidth; i++)
		{
			for (int j = 0; j < _gridHeight; j++)
			{
				InitializeTileAtPosition(i, j);
			}
		}
	}

	private void InitializeTileAtPosition(int x, int y)
	{
		Vector3 tileSpawnPosition = GetTileSpawnPosition(x, y);
		WorldRegionType regionFromTileSpawnPositon = GetRegionFromTileSpawnPositon(tileSpawnPosition);
		if (_tiles[x, y].Tile != null)
		{
			PoolTile(_tiles[x, y]);
		}
		_tiles[x, y] = new RegionTile(regionFromTileSpawnPositon, GetNewRegionTile(x, y, tileSpawnPosition, regionFromTileSpawnPositon));
	}

	private Vector3 GetTileSpawnPosition(int x, int y)
	{
		return new Vector3((float)(x + _cameraOffsetX) * _tileWidth - _horizontalGridOffset, 0f, (float)(y + _cameraOffsetY) * _tileHeight - _verticalGridOffset);
	}

	private GameObject GetNewRegionTile(int x, int y, Vector3 worldPosition, WorldRegionType regionType)
	{
		if (!_pooledRegionTiles.ContainsKey(regionType))
		{
			SpawnRegionTiles(regionType);
		}
		if (!_pooledRegionTiles.TryGetValue(regionType, out var value))
		{
			return null;
		}
		System.Random random = new System.Random(x * 10 + y);
		int index = random.Next(value.Count);
		GameObject obj = value[index];
		value.RemoveAt(index);
		obj.transform.SetPositionAndRotation(worldPosition, Quaternion.Euler(0f, (float)random.Next(4) * 90f, 0f));
		obj.SetActive(value: true);
		return obj;
	}

	private void ShiftTilesUp()
	{
		for (int i = 0; i < _gridWidth; i++)
		{
			RegionTile tileToShift = _tiles[i, _gridHeight - 1];
			for (int num = _gridHeight - 1; num > 0; num--)
			{
				_tiles[i, num] = _tiles[i, num - 1];
				UpdateTilePosition(i, num);
			}
			ShiftOrReplaceTile(i, 0, tileToShift);
		}
	}

	private void ShiftTilesDown()
	{
		for (int i = 0; i < _gridWidth; i++)
		{
			RegionTile tileToShift = _tiles[i, 0];
			for (int j = 0; j < _gridHeight - 1; j++)
			{
				_tiles[i, j] = _tiles[i, j + 1];
				UpdateTilePosition(i, j);
			}
			ShiftOrReplaceTile(i, _gridHeight - 1, tileToShift);
		}
	}

	private void ShiftTilesRight()
	{
		for (int i = 0; i < _gridHeight; i++)
		{
			RegionTile tileToShift = _tiles[_gridWidth - 1, i];
			for (int num = _gridWidth - 1; num > 0; num--)
			{
				_tiles[num, i] = _tiles[num - 1, i];
				UpdateTilePosition(num, i);
			}
			ShiftOrReplaceTile(0, i, tileToShift);
		}
	}

	private void ShiftTilesLeft()
	{
		for (int i = 0; i < _gridHeight; i++)
		{
			RegionTile tileToShift = _tiles[0, i];
			for (int j = 0; j < _gridWidth - 1; j++)
			{
				_tiles[j, i] = _tiles[j + 1, i];
				UpdateTilePosition(j, i);
			}
			ShiftOrReplaceTile(_gridWidth - 1, i, tileToShift);
		}
	}

	private void ShiftOrReplaceTile(int x, int y, RegionTile tileToShift)
	{
		Vector3 tileSpawnPosition = GetTileSpawnPosition(x, y);
		WorldRegionType regionFromTileSpawnPositon = GetRegionFromTileSpawnPositon(tileSpawnPosition);
		if (regionFromTileSpawnPositon != tileToShift.RegionType)
		{
			PoolTile(tileToShift);
			_tiles[x, y] = new RegionTile(regionFromTileSpawnPositon, GetNewRegionTile(x, y, tileSpawnPosition, regionFromTileSpawnPositon));
		}
		else
		{
			tileToShift.Tile.transform.position = tileSpawnPosition;
			_tiles[x, y] = tileToShift;
		}
	}

	private void UpdateTilePosition(int x, int y)
	{
		_tiles[x, y].Tile.transform.position = GetTileSpawnPosition(x, y);
	}

	private WorldRegionType GetRegionFromTileSpawnPositon(Vector3 tileSpawnPosition)
	{
		Vector3 worldPosition = _townheartWorldRotation * tileSpawnPosition + _townheartWorldPosition;
		if (!WorldManager.TryReturnRegionContainingWorldPosition(out var region, worldPosition))
		{
			return WorldRegionType.Rural;
		}
		return region.Type;
	}

	private void PoolTile(RegionTile tile)
	{
		tile.Tile.SetActive(value: false);
		_pooledRegionTiles[tile.RegionType].Add(tile.Tile);
	}

	private List<GameObject> SpawnRegionTiles(WorldRegionType regionType)
	{
		IReadOnlyList<GameObject> regionTiles = GetRegionTiles(regionType);
		if (regionTiles.IsNullOrEmpty())
		{
			UnityEngine.Debug.LogException(new NullReferenceException("Tiles are improperly setup in TerrainProperties."));
			_pooledRegionTiles.Add(regionType, null);
			return null;
		}
		int num = _gridWidth * _gridHeight;
		List<GameObject> list = new List<GameObject>(num);
		for (int i = 0; i < num; i++)
		{
			GameObject gameObject = UnityEngine.Object.Instantiate(regionTiles.GetRandom(), GameManager.WorldManager.WorldParent);
			gameObject.SetActive(value: false);
			list.Add(gameObject);
		}
		_pooledRegionTiles.Add(regionType, list);
		return list;
	}

	private IReadOnlyList<GameObject> GetRegionTiles(WorldRegionType regionType)
	{
		IReadOnlyList<TerrainProperties.RegionTiles> tiles = GameManager.Settings.GameplaySettings.TerrainProperties.Tiles;
		foreach (TerrainProperties.RegionTiles item in tiles)
		{
			if (item.RegionType == regionType)
			{
				return item.Prefabs;
			}
		}
		if (tiles.Count > 0)
		{
			UnityEngine.Debug.LogException(new ArgumentException($"No terrain tiles found for region type \"{regionType}\", defaulting to \"{tiles[0].RegionType}\"."));
			return tiles[0].Prefabs;
		}
		UnityEngine.Debug.LogException(new ArgumentException($"No terrain tiles found for region type \"{regionType}\"."));
		return null;
	}
}
public class TextManager : MonoBehaviour, ILocalizationParamsManager
{
	private string _hungerLimit;

	private string _thirstLimit;

	public string HungerLimit
	{
		get
		{
			if (_hungerLimit == null)
			{
				_hungerLimit = AgentDescriptor.GetProperties().VitalProperties.HungerLimit.ToString();
			}
			return _hungerLimit;
		}
	}

	public string ThirstLimit
	{
		get
		{
			if (_thirstLimit == null)
			{
				_thirstLimit = AgentDescriptor.GetProperties().VitalProperties.ThirstLimit.ToString();
			}
			return _thirstLimit;
		}
	}

	private void Awake()
	{
		LocalizationManager.ParamManagers.Add(this);
	}

	private void OnDestroy()
	{
		LocalizationManager.ParamManagers.Remove(this);
	}

	string ILocalizationParamsManager.GetParameterValue(string param)
	{
		if (ActorDescriptor.TryGet<ActorDescriptor>(out var actorDescriptor, param))
		{
			return actorDescriptor.Name;
		}
		return param switch
		{
			"COMMUNITYNAME" => (Community.PlayerCommunity != null) ? Community.PlayerCommunity.Name : null, 
			"CURRENTDAY" => (GameManager.TimeManager != null) ? GameManager.TimeManager.Days.Count.ToString() : null, 
			"HUNGERDAYSLIMIT" => HungerLimit, 
			"THIRSTDAYSLIMIT" => ThirstLimit, 
			_ => null, 
		};
	}

	public static string ReplaceVariables(string text, Vitals vitals = null)
	{
		if (GameManager.WorldMapManager != null && GameManager.WorldMapManager.WorldMap != null)
		{
			text = Regex.Replace(text, "%BIOME_COST%", string.Format("<b>{0}</b>", GameplaySettings.ReturnNextBiomeEnergyCost().ToString("F0")), RegexOptions.IgnoreCase);
		}
		if (vitals == null)
		{
			return text;
		}
		if ((bool)vitals.Agent)
		{
			text = Regex.Replace(text, "%NAME%", $"<b>{vitals.Agent.Name}</b>", RegexOptions.IgnoreCase);
			text = Regex.Replace(text, "%FIRSTNAME%", $"<b>{vitals.Agent.Name}</b>", RegexOptions.IgnoreCase);
			text = Regex.Replace(text, "%LASTNAME%", $"<b>{vitals.Agent.Name}</b>", RegexOptions.IgnoreCase);
			text = Regex.Replace(text, "%NICKNAME%", $"<b>{vitals.Agent.Name}</b>", RegexOptions.IgnoreCase);
		}
		if (vitals.Agent.Community != null)
		{
			text = Regex.Replace(text, "%COMMUNITY%", vitals.Agent.Community.Name, RegexOptions.IgnoreCase);
		}
		return text;
	}

	public static string ReplaceVariables(string text, Bird bird = null)
	{
		if (bird == null)
		{
			return text;
		}
		text = Regex.Replace(text, "%NAME%", $"<b>{bird.Name}</b>", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%FIRSTNAME%", $"<b>{bird.Name}</b>", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%LASTNAME%", $"<b>{bird.Name}</b>", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%NICKNAME%", $"<b>{bird.Name}</b>", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%COMMUNITY%", bird.Community.Name, RegexOptions.IgnoreCase);
		return text;
	}

	public static string ReplaceVariables(string text, Buildable buildable = null)
	{
		if (buildable == null)
		{
			return text;
		}
		text = Regex.Replace(text, "%SALVAGERETURNS%", ReturnStringfromCountedItemProptertyList(buildable.Properties.RequiredResources), RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%HEALTHVITAL%", $"{buildable.Health:P2}", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%HEALTHVITAL%", $"{buildable.Health:P2}", RegexOptions.IgnoreCase);
		text = ReplaceVariables(text, buildable.Properties);
		return text;
	}

	public static string ReplaceVariables(string text, Decoration decoration)
	{
		if (decoration == null)
		{
			return text;
		}
		text = Regex.Replace(text, "%SALVAGERETURNS%", ReturnStringfromCountedItemProptertyList(decoration.Properties.RequiredResources), RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%NAME%", $"<b>{decoration.Properties.Name}</b>", RegexOptions.IgnoreCase);
		return text;
	}

	public static string ReplaceVariables(string text, BuildableProperties buildableProperties)
	{
		text = Regex.Replace(text, "%NAME%", $"<b>{buildableProperties.Name}</b>", RegexOptions.IgnoreCase);
		text = Regex.Replace(text, "%RESEARCH%", buildableProperties.ResearchCost.ToString(), RegexOptions.IgnoreCase);
		if (text.Contains("%STORAGEAMOUNT%") || text.Contains("%storageamount%") || text.Contains("%WATERSTORAGEAMOUNT%") || text.Contains("%waterstorageamount%"))
		{
			Inventory component = buildableProperties.Prefab.GetComponent<Inventory>();
			text = Regex.Replace(text, "%STORAGEAMOUNT%", component.StorageCapacity.ToString(), RegexOptions.IgnoreCase);
			text = Regex.Replace(text, "%WATERSTORAGEAMOUNT%", component.LiquidCapacity.ToString(), RegexOptions.IgnoreCase);
		}
		return text;
	}

	public static string ReplaceVariables(string text, ProductionRecipeProperties recipeProperties)
	{
		text = Regex.Replace(text, "%RECIPE%", $"<b>{recipeProperties.LocalizedName}</b>", RegexOptions.IgnoreCase);
		return text;
	}

	public static string ReplaceVariables(string text, LandmarkBehaviour landmarkBehaviour)
	{
		text = Regex.Replace(text, "%LANDMARKNAME%", $"<b>{landmarkBehaviour.Name}</b>", RegexOptions.IgnoreCase);
		return text;
	}

	public static string ReturnStringfromCountedItemProptertyList(CountedItemProperty[] items)
	{
		if (items.Length == 0)
		{
			return "";
		}
		string text = "";
		for (int i = 0; i < items.Length; i++)
		{
			if (items[i].Amount != 0)
			{
				text += items[i].ReturnLocalizedString();
				if (i < items.Length - 1)
				{
					text += ",";
				}
			}
		}
		return text;
	}

	public static string ReplaceVariables(string text, ActionElementMap rewiredKey)
	{
		text = ((rewiredKey != null) ? Regex.Replace(text, "%HOTKEY%", $"[{rewiredKey.keyCode}]", RegexOptions.IgnoreCase) : Regex.Replace(text, "%HOTKEY%", "", RegexOptions.IgnoreCase));
		return text;
	}

	public static string ReplaceVariablesWithEmptyString(string text)
	{
		if (!string.IsNullOrEmpty(text))
		{
			text = Regex.Replace(text, "%HOTKEY%", string.Empty, RegexOptions.IgnoreCase);
		}
		return text;
	}
}
public class ThreadPoolManager : MonoBehaviour
{
	public interface ITask
	{
		bool Completed { get; }

		void ThreadPoolWaitCallback(object state);

		void UnityCompletedCallback();
	}

	private static ThreadPoolManager _instance;

	private Queue<ITask> _taskQueue;

	private List<ITask> _queuedTasks;

	private void Awake()
	{
		if (_instance == null || _instance == this)
		{
			_instance = this;
			_taskQueue = new Queue<ITask>();
			_queuedTasks = new List<ITask>();
		}
		else
		{
			UnityEngine.Object.Destroy(this);
		}
	}

	private void Update()
	{
		while (0 < _taskQueue.Count)
		{
			ITask task = _taskQueue.Peek();
			if (task.Completed || ThreadPool.QueueUserWorkItem(task.ThreadPoolWaitCallback))
			{
				_queuedTasks.Add(_taskQueue.Dequeue());
				continue;
			}
			break;
		}
	}

	private void LateUpdate()
	{
		int count = _queuedTasks.Count;
		while (0 < count--)
		{
			ITask task = _queuedTasks[count];
			if (task.Completed)
			{
				task.UnityCompletedCallback();
				_queuedTasks.RemoveAt(count);
			}
		}
	}

	public static bool QueueTask(ITask task)
	{
		if (_instance == null)
		{
			_instance = new GameObject().AddComponent<ThreadPoolManager>();
		}
		return _instance.AddTaskToQueue(task);
	}

	public bool AddTaskToQueue(ITask task)
	{
		if (_taskQueue.Contains(task))
		{
			return false;
		}
		_taskQueue.Enqueue(task);
		return true;
	}
}
public class TimeManager : MonoBehaviour
{
	private readonly int UNSCALED_TIME = Shader.PropertyToID("_UNSCALED_TIME");

	[SerializeField]
	private AnimationCurve _dayNightCycle;

	[SerializeField]
	private RangedFloat _dayRange = new RangedFloat(0.5f, 1f);

	[SerializeField]
	private bool _forceMiddayStart = true;

	[SerializeField]
	private CircadianVisuals _environmentVisuals;

	[SerializeField]
	private int _hoursInDay = 24;

	[Header("Night Light Settings")]
	[SerializeField]
	private float _sleepTimeScale = 20f;

	[SerializeField]
	private UnityEngine.Gradient _nightLightColor;

	[SerializeField]
	private RangedFloat _nightLightActive = new RangedFloat(0.5f, 1f);

	[SerializeField]
	private float _nightLightTransitionTime = 0.1f;

	[SerializeField]
	private RangedFloat _nightLightDelayRange = new RangedFloat(0.1f, 0.25f);

	[SerializeField]
	[Range(0f, 100f)]
	private int _nightLightDelayChance;

	private float _cycleDuration;

	private float _dayDuration;

	private float _nightDuration;

	private float _middayValue;

	private bool _hasReachedMidday;

	private List<NightLight> _nightLights;

	private bool _nightLightsEnabled;

	private bool _applySleepSpeed;

	public List<Day> Days { get; } = new List<Day>();

	public Day CurrentDay { get; private set; }

	public float CurrentPlayTime { get; private set; }

	public float LastSavedPlayTime { get; set; }

	public CircadianVisuals CycleVisuals => _environmentVisuals;

	public bool Initialized { get; private set; }

	public float DeltaTime { get; private set; }

	public static float CycleDuration
	{
		get
		{
			if (!GameManager.TimeManager)
			{
				return 0f;
			}
			return GameManager.TimeManager._cycleDuration;
		}
	}

	public static float DayDuration
	{
		get
		{
			if (!GameManager.TimeManager)
			{
				return 0f;
			}
			return GameManager.TimeManager._dayDuration;
		}
	}

	private void Awake()
	{
		GameEventDispatcher.AddListener(GameEventType.NighttimeStarted, OnNightStart);
	}

	public void Initialize()
	{
		InitializeCycleData();
		NextDay();
		InitializeNightLights();
	}

	public void Restore(DayPersistentData[] daysToRestore)
	{
		int num = daysToRestore.Length;
		InitializeCycleData();
		Days.Clear();
		foreach (DayPersistentData dayPersistentData in daysToRestore)
		{
			Days.Add(dayPersistentData.ReturnRestored(_dayDuration, _nightDuration));
		}
		List<Day> days = Days;
		CurrentDay = days[days.Count - 1];
		CurrentDay.Report.Start();
		CurrentDay.ProgressCycle(Time.deltaTime);
		_hasReachedMidday = 1 < num || _dayDuration < CurrentDay.CurrentTime || _dayNightCycle.Evaluate(CurrentDay.CurrentTime) == _middayValue;
		InitializeNightLights();
	}

	private void InitializeNightLights()
	{
		_nightLights = new List<NightLight>();
		_nightLightsEnabled = ReturnEvaluateNightLightsEnabled();
		Initialized = true;
	}

	private void Update()
	{
		Shader.SetGlobalFloat(UNSCALED_TIME, Time.unscaledTime);
		if (!Initialized)
		{
			return;
		}
		TrackPlayTime();
		if (CurrentDay != null && UIManager.State != UIState.GameTimePaused)
		{
			if (CurrentDay.DayTime == Day.E_DayTime.Night)
			{
				if (CanApplySleepSpeed())
				{
					_applySleepSpeed = true;
				}
			}
			else
			{
				_applySleepSpeed = false;
			}
			DeltaTime = (_applySleepSpeed ? (Time.unscaledDeltaTime * _sleepTimeScale) : Time.deltaTime);
			if (CurrentDay.ProgressCycle(DeltaTime))
			{
				NextDay();
			}
		}
		bool flag = ReturnEvaluateNightLightsEnabled();
		if (flag != _nightLightsEnabled)
		{
			_nightLightsEnabled = flag;
			StartCoroutine(SetNightLightsEnabledRoutine(_nightLightsEnabled));
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.NighttimeStarted, OnNightStart);
	}

	private void InitializeCycleData(float increment = 1f)
	{
		if (_dayNightCycle.length < 2)
		{
			return;
		}
		float num = _dayNightCycle[0].time;
		float time = _dayNightCycle[_dayNightCycle.length - 1].time;
		float num2 = float.NaN;
		float num3 = float.NaN;
		_cycleDuration = time - num;
		_middayValue = 0f;
		for (; num <= time; num += increment)
		{
			float num4 = _dayNightCycle.Evaluate(num);
			if (_dayRange.ReturnContainsValue(num4))
			{
				if (float.IsNaN(num2))
				{
					num2 = num;
				}
			}
			else if (float.IsNaN(num3))
			{
				num3 = num - increment;
			}
			if (_middayValue < num4)
			{
				_middayValue = num4;
			}
		}
		_dayDuration = num3 - num2;
		_nightDuration = _cycleDuration - _dayDuration;
	}

	private void OnNightStart(GameEvent gameEvent)
	{
		GameManager.UIManager.NotificationHandler.AddNotification(GameManager.Settings.UISettings.DailyReportAvailableNotification, new DayObjectOfInterest(Days.Count - 1));
	}

	public void NextDay()
	{
		if (CurrentDay != null)
		{
			CurrentDay.Finish();
			DayEvent.Dispatch(GameEventType.DayEnded, CurrentDay, Days);
		}
		CurrentDay = new Day(_dayDuration, _nightDuration, _hoursInDay);
		Days.Add(CurrentDay);
		DayEvent.Dispatch(GameEventType.DayStarted, CurrentDay, Days);
	}

	public void RegisterNightLight(NightLight nightlight)
	{
		if (_nightLights.AddUnique(nightlight))
		{
			nightlight.SetColor(_nightLightColor.Evaluate(UnityEngine.Random.Range(0, 1)));
			nightlight.SetEnabled(_nightLightsEnabled);
		}
	}

	public void UnregiserNightLight(NightLight nightLight)
	{
		if (_nightLights != null && _nightLights.Remove(nightLight))
		{
			nightLight.SetEnabled(enabled: false);
		}
	}

	private IEnumerator SetNightLightsEnabledRoutine(bool enabled)
	{
		foreach (NightLight nightLight in _nightLights)
		{
			nightLight.SetEnabled(enabled, _nightLightTransitionTime);
			if (UnityEngine.Random.Range(0, 100) < _nightLightDelayChance)
			{
				yield return new WaitForSeconds(_nightLightDelayRange.ReturnRandom());
			}
		}
	}

	private void TrackPlayTime()
	{
		CurrentPlayTime += Time.unscaledDeltaTime;
	}

	public float ReturnTotalTimePlayed()
	{
		return CurrentPlayTime + LastSavedPlayTime;
	}

	public string ReturnTimeInHoursMinutes(float timeToConvert, bool includeUnits = true)
	{
		int num = Mathf.FloorToInt(timeToConvert / 3600f);
		int num2 = Mathf.FloorToInt((timeToConvert - (float)(num * 3600)) / 60f);
		if (includeUnits)
		{
			return $"{num}h:{num2:00}m";
		}
		return $"{num}:{num2:00}";
	}

	public string ReturnTimeInHoursMinutes(bool includeUnits = true)
	{
		return ReturnTimeInHoursMinutes(ReturnTotalTimePlayed(), includeUnits);
	}

	public float ReturnDayNightBlend()
	{
		float num = _dayNightCycle.Evaluate(CurrentDay.CurrentTime);
		if (_forceMiddayStart && !_hasReachedMidday)
		{
			_hasReachedMidday = num == _middayValue;
			num = _middayValue;
		}
		AudioManager.SetDayTimeParameter(num);
		return num;
	}

	private bool ReturnEvaluateNightLightsEnabled()
	{
		return _nightLightActive.ReturnContainsValue(_dayNightCycle.Evaluate(CurrentDay.CurrentTime));
	}

	private bool CanApplySleepSpeed(float threshold = 0.75f)
	{
		List<Agent> agents = Community.PlayerCommunity.Agents;
		float num = 0f;
		foreach (Agent agent in Community.PlayerCommunity.Agents)
		{
			if (agent.CurrentActivity == Activity.Sleeping)
			{
				num += 1f;
			}
		}
		return threshold < num / (float)agents.Count;
	}

	public static float GetDeltaTime()
	{
		if (TryReturnInstance(out var instance))
		{
			return instance.DeltaTime;
		}
		return Time.deltaTime;
	}

	public static bool ReturnIsDayTime()
	{
		if (TryReturnInstance(out var instance) && instance.CurrentDay != null)
		{
			return instance.CurrentDay.DayTime == Day.E_DayTime.Day;
		}
		return true;
	}

	private static bool TryReturnInstance(out TimeManager instance)
	{
		instance = GameManager.TimeManager;
		return instance != null;
	}
}
