	public bool CanDisplayPanel(PanelID panelID, IPanelContext context = null)
	{
		foreach (PanelContainer panel in _panels)
		{
			if ((bool)panel && panel.CanOpen(panelID, context))
			{
				return true;
			}
		}
		return false;
