	public static bool CanPruneWorldTile(WorldTile worldTile)
	{
		foreach (WorldTileSpawningBlocker spawningBlocker in SpawningBlockers)
		{
			if (spawningBlocker.BlocksPruning(worldTile))
			{
				return false;
			}
		}
		return true;
