	public void CreateWorldParent()
	{
		if (!(WorldParent != null))
		{
			WorldParent = new GameObject().transform;
			WorldParent.name = "WorldParent";
			_terrainRigidBody = WorldParent.gameObject.AddComponent<Rigidbody>();
			_terrainRigidBody.mass = GameManager.Settings.GameplaySettings.WorldPhysics.WorldMass;
			_terrainRigidBody.linearDamping = GameManager.Settings.GameplaySettings.WorldPhysics.WorldDrag;
			_terrainRigidBody.angularDamping = GameManager.Settings.GameplaySettings.WorldPhysics.WorldAngularDrag;
			_terrainRigidBody.useGravity = false;
		}
	}

	public void SetWorldDistanceTravelled(float distanceTravelled)
	{
		Vector3 position = _terrainRigidBody.transform.position;
		position.z = distanceTravelled;
		_terrainRigidBody.transform.position = position;
	}

	private void MoveWorld()
	{
		Vector3 force = GameManager.PhysicsManager.MovingWorldDirection * GameManager.PhysicsManager.MovingWorldForce * Time.fixedDeltaTime;
		_terrainRigidBody.AddForce(force);
		_gameData.DistanceTravelled = _terrainRigidBody.transform.position.z;
		_gameData.CurrentVelocity = _terrainRigidBody.linearVelocity.magnitude;
	}

	public void StopWorldMovement()
	{
		_terrainRigidBody.linearVelocity = Vector3.zero;
	}
}
[CreateAssetMenu(menuName = "Flotsam/Agent/Morale/Effects/Acid Gass Morale Effect")]
public class AcidGassMoraleEfect : MoraleEffect
{
	[Serializable]
	private struct ModifierDrifterCount
	{
		public int DrifterCount;

		public int Modifier;
	}

	[Serializable]
	public class PersistentData : BasePersistentData
	{
		public bool IsActive;

		public float Time;

		public PersistentData(AcidGassMoraleEfect effect)
			: base(effect)
		{
			IsActive = effect._isActive;
			Time = 0f;
		}
	}

	[Tooltip("The index indicates the morale penlaty, the value is the number of agents with the acid gass disease needed to trigger the morale penalty")]
	[SerializeField]
	private ModifierDrifterCount[] _modifierDrifterCounts;

	[SerializeField]
	private LocalizedString _description;

	[SerializeField]
	private Sprite _icon;

	private bool _isActive;

	private int _count;

	private int _modifier;

	public override void Initialize(Agent agent, MoraleEffect properties)
	{
		base.Initialize(agent, properties);
		GameEventDispatcher.AddListener(GameEventType.DiseasesUpdated, OnDiseaseUpdated);
		OnDiseaseUpdated();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.AddListener(GameEventType.DiseasesUpdated, OnDiseaseUpdated);
	}

	public new void Activate()
	{
		_isActive = true;
		base.Activate();
	}

	protected override void Deactivate()
	{
		_isActive = false;
		base.Deactivate();
	}

	public void OnEncounter(Agent agent)
	{
	}

	private void OnDiseaseUpdated(GameEvent gameEvent = null)
	{
		if (_agent.Community == null)
		{
			return;
		}
		_count = 0;
		foreach (Agent agent in _agent.Community.Agents)
		{
			Pollution pollution = agent.Vitals.Pollution;
			if (pollution.CurrentDisease is AcidGass && (pollution.CurrentDiseaseMedPod == null || pollution.CurrentDiseaseMedPod.OccupyingPatient != agent))
			{
				_count++;
			}
		}
		_modifier = 0;
		for (int i = 0; i < _modifierDrifterCounts.Length; i++)
		{
			ModifierDrifterCount modifierDrifterCount = _modifierDrifterCounts[i];
			if (modifierDrifterCount.DrifterCount > _count)
			{
				break;
			}
			_modifier = modifierDrifterCount.Modifier;
		}
		if (0 < _modifier)
		{
			if (!_isActive)
			{
				Activate();
			}
		}
		else if (_isActive)
		{
			Deactivate();
		}
	}

	public override bool IsActive()
	{
		return _isActive;
	}

	public override string ReturnDescription()
	{
		return _description;
	}

	public override int ReturnModifier()
	{
		return -_modifier;
	}

	public override BasePersistentData ReturnPersistentData()
	{
		return new PersistentData(this);
	}

	public override Sprite ReturnSprite()
	{
		return _icon;
	}

	public override bool TryReturnAttributeEffect(out DrifterAttributesEffect effect)
	{
		effect = null;
		return false;
	}

	public override void Restore(BasePersistentData persistentData)
	{
		OnDiseaseUpdated();
	}
}
[CreateAssetMenu(menuName = "Flotsam/Name/Combination Generator")]
public class CombinationNameGenerator : NameGenerator
{
	[SerializeField]
	private string _joiner = " ";

	[SerializeField]
	private NameList[] _names;

	private StringBuilder _nameBuilder;

	public override string ReturnName()
	{
		string text = "";
		for (int i = 0; i < _names.Length; i++)
		{
			if (i != 0)
			{
				text += _joiner;
			}
			text += _names[i].ReturnRandomName();
		}
		return text;
	}

	public override void AddAllNames(List<string> names)
	{
		string item;
		while (NextName(out item))
		{
			names.Add(item);
		}
	}

	private bool NextName(out string name)
	{
		if (_nameBuilder == null)
		{
			_nameBuilder = new StringBuilder();
		}
		else
		{
			_nameBuilder.Clear();
		}
		for (int i = 0; i < _names.Length; i++)
		{
			if (i != 0)
			{
				_nameBuilder.Append(_joiner);
			}
			_nameBuilder.Append(_names[i].ReturnNameAtIndex());
		}
		name = _nameBuilder.ToString();
		int num = _names.Length;
		while (0 < num--)
		{
			if (_names[num].NextIndex())
			{
				return true;
			}
		}
		return false;
	}
}
