public class ScrollRectAxisScroller : MonoBehaviour
{
	[SerializeField]
	private ScrollRect _scrollRect;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _horizontalAction = -1;

	[SerializeField]
	[ActionIdProperty(typeof(RewiredConsts.Action))]
	private int _verticalAction = -1;

	[SerializeField]
	[Tooltip("the scroll speed in pixels per second")]
	private float _scrollSpeed = 512f;

	[SerializeField]
	private InputFlags _activeInputs = InputFlags.Joystick;

	private int _horizontalNumberOfSteps;

	private int _verticalNumberOfSteps;

	private void OnEnable()
	{
		if ((bool)_scrollRect.horizontalScrollbar)
		{
			_horizontalNumberOfSteps = _scrollRect.horizontalScrollbar.numberOfSteps;
		}
		if ((bool)_scrollRect.verticalScrollbar)
		{
			_verticalNumberOfSteps = _scrollRect.verticalScrollbar.numberOfSteps;
		}
		GameEventDispatcher.AddListener(GameEventType.ActiveInputUpdated, OnActiveInputChanged);
		OnActiveInputChanged();
	}

	private void Update()
	{
		if ((bool)_scrollRect.horizontalScrollbar)
		{
			float num = ReturnScrollDistance(_scrollRect.content.rect.width, _scrollRect.viewport.rect.width);
			_scrollRect.horizontalScrollbar.value = Mathf.Clamp01(_scrollRect.horizontalScrollbar.value + num * FlotsamInputManager.GetAxis(_horizontalAction));
		}
		if ((bool)_scrollRect.verticalScrollbar)
		{
			float num = ReturnScrollDistance(_scrollRect.content.rect.height, _scrollRect.viewport.rect.height);
			_scrollRect.verticalScrollbar.value = Mathf.Clamp01(_scrollRect.verticalScrollbar.value + num * FlotsamInputManager.GetAxis(_verticalAction));
		}
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActiveInputUpdated, OnActiveInputChanged);
		RestoreNumberOfSteps();
	}

	public void ScrollHorizontal(float value)
	{
		if ((bool)_scrollRect.horizontalScrollbar)
		{
			float num = ReturnNormalizedScrollDistance(value, _scrollRect.content.rect.width, _scrollRect.viewport.rect.width);
			_scrollRect.horizontalScrollbar.value = Mathf.Clamp01(_scrollRect.horizontalScrollbar.value + num);
		}
	}

	public void ScrollVertical(float value)
	{
		if ((bool)_scrollRect.verticalScrollbar)
		{
			float num = ReturnNormalizedScrollDistance(value, _scrollRect.content.rect.height, _scrollRect.viewport.rect.height);
			_scrollRect.verticalScrollbar.value = Mathf.Clamp01(_scrollRect.verticalScrollbar.value + num);
		}
	}

	private void OnActiveInputChanged(GameEvent gameEvent = null)
	{
		if (FlotsamInputManager.HasActiveInput(_activeInputs))
		{
			if ((bool)_scrollRect.horizontalScrollbar)
			{
				_scrollRect.horizontalScrollbar.numberOfSteps = 0;
			}
			if ((bool)_scrollRect.verticalScrollbar)
			{
				_scrollRect.verticalScrollbar.numberOfSteps = 0;
			}
		}
		else
		{
			RestoreNumberOfSteps();
		}
	}

	private void RestoreNumberOfSteps()
	{
		if ((bool)_scrollRect.horizontalScrollbar)
		{
			_scrollRect.horizontalScrollbar.numberOfSteps = _horizontalNumberOfSteps;
		}
		if ((bool)_scrollRect.verticalScrollbar)
		{
			_scrollRect.verticalScrollbar.numberOfSteps = _verticalNumberOfSteps;
		}
	}

	private float ReturnScrollDistance(float content, float viewport)
	{
		if (content <= viewport)
		{
			return 0f;
		}
		return _scrollSpeed / (content - viewport) * Time.unscaledDeltaTime;
	}

	private float ReturnNormalizedScrollDistance(float distance, float content, float viewport)
	{
		if (content <= viewport)
		{
			return 0f;
		}
		return distance / (content - viewport);
	}
}
[Serializable]
public class Transition
{
	[SerializeField]
	private Selectable.Transition m_Transition = Selectable.Transition.ColorTint;

	[SerializeField]
	[ConditionalEnumHide("m_Transition", 1, 2, false, HideInInspector = true)]
	private Graphic m_TargetGraphic;

	[SerializeField]
	[ConditionalEnumHide("m_Transition", 3, false, HideInInspector = true)]
	private Animator m_TargetAnimator;

	[SerializeField]
	[ConditionalEnumHide("m_Transition", 1, false, HideInInspector = true)]
	private ColorBlock m_Colors = ColorBlock.defaultColorBlock;

	[SerializeField]
	[ConditionalEnumHide("m_Transition", 2, false, HideInInspector = true)]
	private SpriteState m_SpriteState;

	[SerializeField]
	[ConditionalEnumHide("m_Transition", 3, false, HideInInspector = true)]
	private AnimationTriggers m_AnimationTriggers = new AnimationTriggers();

	private string _customAnimationTrigger;

	public Selectable.Transition Type => m_Transition;

	public void SetNormal()
	{
		switch (m_Transition)
		{
		case Selectable.Transition.ColorTint:
			StartColorTween(m_Colors.normalColor);
			break;
		case Selectable.Transition.SpriteSwap:
			DoSpriteSwap(null);
			break;
		case Selectable.Transition.Animation:
			TriggerAnimation(m_AnimationTriggers.normalTrigger);
			break;
		}
	}

	public void SetHighlighted()
	{
		switch (m_Transition)
		{
		case Selectable.Transition.ColorTint:
			StartColorTween(m_Colors.highlightedColor);
			break;
		case Selectable.Transition.SpriteSwap:
			DoSpriteSwap(m_SpriteState.highlightedSprite);
			break;
		case Selectable.Transition.Animation:
			TriggerAnimation(m_AnimationTriggers.highlightedTrigger);
			break;
		}
	}

	public void SetPressed()
	{
		switch (m_Transition)
		{
		case Selectable.Transition.ColorTint:
			StartColorTween(m_Colors.pressedColor);
			break;
		case Selectable.Transition.SpriteSwap:
			DoSpriteSwap(m_SpriteState.pressedSprite);
			break;
		case Selectable.Transition.Animation:
			TriggerAnimation(m_AnimationTriggers.pressedTrigger);
			break;
		}
	}

	public void SetSelected()
	{
		switch (m_Transition)
		{
		case Selectable.Transition.ColorTint:
			StartColorTween(m_Colors.selectedColor);
			break;
		case Selectable.Transition.SpriteSwap:
			DoSpriteSwap(m_SpriteState.selectedSprite);
			break;
		case Selectable.Transition.Animation:
			TriggerAnimation(m_AnimationTriggers.selectedTrigger);
			break;
		}
	}

	public void SetDisabled()
	{
		switch (m_Transition)
		{
		case Selectable.Transition.ColorTint:
			StartColorTween(m_Colors.disabledColor);
			break;
		case Selectable.Transition.SpriteSwap:
			DoSpriteSwap(m_SpriteState.disabledSprite);
			break;
		case Selectable.Transition.Animation:
			TriggerAnimation(m_AnimationTriggers.disabledTrigger);
			break;
		}
	}

	public void SetAnimatorBool(string name, bool value)
	{
		if (m_TargetAnimator.isActiveAndEnabled && m_Transition == Selectable.Transition.Animation)
		{
			m_TargetAnimator.SetBool(name, value);
		}
	}

	public void SetAnimatorInteger(string name, int value)
	{
		if (m_TargetAnimator.isActiveAndEnabled && m_Transition == Selectable.Transition.Animation)
		{
			m_TargetAnimator.SetInteger(name, value);
		}
	}

	public void SetAnimatorTrigger(string trigger)
	{
		TriggerAnimation(trigger);
		_customAnimationTrigger = trigger;
	}

	private void StartColorTween(Color targetColor)
	{
		if ((bool)m_TargetGraphic)
		{
			m_TargetGraphic.CrossFadeColor(targetColor, m_Colors.fadeDuration, ignoreTimeScale: true, useAlpha: true);
		}
	}

	private void DoSpriteSwap(Sprite newSprite)
	{
		if (m_TargetGraphic is Image image)
		{
			image.overrideSprite = newSprite;
		}
	}

	private void TriggerAnimation(string triggername)
	{
		if (m_Transition == Selectable.Transition.Animation && !(m_TargetAnimator == null) && m_TargetAnimator.isActiveAndEnabled && m_TargetAnimator.hasBoundPlayables && !string.IsNullOrEmpty(triggername))
		{
			m_TargetAnimator.ResetTrigger(m_AnimationTriggers.normalTrigger);
			m_TargetAnimator.ResetTrigger(m_AnimationTriggers.highlightedTrigger);
			m_TargetAnimator.ResetTrigger(m_AnimationTriggers.pressedTrigger);
			m_TargetAnimator.ResetTrigger(m_AnimationTriggers.selectedTrigger);
			m_TargetAnimator.ResetTrigger(m_AnimationTriggers.disabledTrigger);
			if (!string.IsNullOrEmpty(_customAnimationTrigger))
			{
				m_TargetAnimator.ResetTrigger(_customAnimationTrigger);
			}
			m_TargetAnimator.SetTrigger(triggername);
		}
	}
}
public class PooledList<T> : List<T>, IDisposable
{
	private static Stack<PooledList<T>> _stack = new Stack<PooledList<T>>(16);

	private bool _isPooled;

	private PooledList()
	{
	}

	private PooledList(int capacity)
		: base(capacity)
	{
	}

	private PooledList(IEnumerable<T> collection)
		: base(collection)
	{
	}

	public static PooledList<T> Get()
	{
		if (_stack.Count == 0)
		{
			return new PooledList<T>();
		}
		PooledList<T> pooledList = _stack.Pop();
		pooledList._isPooled = false;
		return pooledList;
	}

	public static PooledList<T> Get(int minimumCapacity)
	{
		if (_stack.Count == 0)
		{
			return new PooledList<T>(minimumCapacity);
		}
		PooledList<T> pooledList = _stack.Pop();
		pooledList._isPooled = false;
		if (pooledList.Capacity < minimumCapacity)
		{
			pooledList.Capacity = minimumCapacity;
		}
		return pooledList;
	}

	public static PooledList<T> Get(IEnumerable<T> collection)
	{
		if (_stack.Count == 0)
		{
			return new PooledList<T>(collection);
		}
		PooledList<T> pooledList = _stack.Pop();
		pooledList._isPooled = false;
		pooledList.AddRange(collection);
		return pooledList;
	}

	public static PooledList<T> Get(params T[] items)
	{
		if (_stack.Count == 0)
		{
			return new PooledList<T>(items);
		}
		PooledList<T> pooledList = _stack.Pop();
		pooledList._isPooled = false;
		pooledList.AddRange(items);
		return pooledList;
	}

	public new void Add(T item)
	{
		if (_isPooled)
		{
			throw new NotSupportedException($"Adding items to a pooled list of type {typeof(T).ToString()} is not support!");
		}
		base.Add(item);
	}

	public new void AddRange(IEnumerable<T> collection)
	{
		if (_isPooled)
		{
			throw new NotSupportedException($"Adding items to a pooled list of type {typeof(T).ToString()} is not support!");
		}
		base.AddRange(collection);
	}

	public void Dispose()
	{
		if (_isPooled)
		{
			UnityEngine.Debug.LogWarning("A PooledList.List that is pooled cannot be pooled again!");
			return;
		}
		Clear();
		_stack.Push(this);
		_isPooled = true;
	}

	public static bool IsPooled(PooledList<T> pooledList)
	{
		return _stack.Contains(pooledList);
	}
}
public class Heap<T> where T : IHeapItem<T>
{
	public delegate void ClearItem(T item);

	private T[] _items;

	private int _currentItemCount;

	public int Count => _currentItemCount;

	public T[] Items => _items;

	public Heap(int maximumHeapSize)
	{
		_items = new T[maximumHeapSize];
	}

	public void Dispose()
	{
		_items = null;
	}

	public void Add(T item)
	{
		if (_currentItemCount == _items.Length)
		{
			T[] array = new T[_items.Length * 2];
			Array.Copy(_items, array, _items.Length);
			_items = array;
		}
		item.HeapIndex = _currentItemCount;
		_items[_currentItemCount] = item;
		SortUp(item);
		_currentItemCount++;
	}

	public T RemoveFirst()
	{
		T result = _items[0];
		_currentItemCount--;
		T val = _items[_currentItemCount];
		val.HeapIndex = 0;
		_items[0] = val;
		_items[_currentItemCount] = null;
		SortDown(val);
		return result;
	}

	public void Remove(T item)
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			if (_items[i].Equals(item))
			{
				_currentItemCount--;
				_items[i] = _items[_currentItemCount];
				_items[i].HeapIndex = i;
				SortDown(_items[i]);
				break;
			}
		}
	}

	private void SortDown(T item)
	{
		while (true)
		{
			int num = item.HeapIndex * 2 + 1;
			if (num >= _currentItemCount)
			{
				break;
			}
			T val = _items[num];
			int num2 = item.HeapIndex * 2 + 2;
			if (num2 < _currentItemCount)
			{
				T val2 = _items[num2];
				if (val.CompareTo(val2) < 0)
				{
					num = num2;
					val = val2;
				}
			}
			if (item.CompareTo(val) < 0)
			{
				Swap(item, val, num);
				continue;
			}
			break;
		}
	}

	private void SortUp(T item)
	{
		int num = item.HeapIndex;
		while (true)
		{
			num = (num - 1) / 2;
			T val = _items[num];
			if (0 < item.CompareTo(val))
			{
				Swap(item, val, num);
				continue;
			}
			break;
		}
	}

	private void ValidateItem(T item)
	{
		if (_items[item.HeapIndex].CompareTo(item) != 0)
		{
			UnityEngine.Debug.LogWarning("Invalid heap item! Heap index mismatch");
		}
	}

	private void ValidateSorting(int parentIndex = 0)
	{
		T parent = _items[parentIndex];
		int num = parentIndex * 2 + 1;
		if (TryReturnCorrectlySortedChild(parent, num, out var _))
		{
			int num2 = parentIndex * 2 + 2;
			if (TryReturnCorrectlySortedChild(parent, num2, out var _))
			{
				ValidateSorting(num);
				ValidateSorting(num2);
			}
			else if (num2 < _currentItemCount)
			{
				UnityEngine.Debug.LogWarning("Heap not correctly sorted!");
			}
		}
		else if (num < _currentItemCount)
		{
			UnityEngine.Debug.LogWarning("Heap not correctly sorted!");
		}
	}

	private bool TryReturnCorrectlySortedChild(T parent, int childIndex, out T child)
	{
		if (childIndex < _currentItemCount)
		{
			child = _items[childIndex];
			return 0 <= parent.CompareTo(child);
		}
		child = null;
		return false;
	}

	private void Swap(T firstItem, T secondItem, int secondIndex)
	{
		int heapIndex = firstItem.HeapIndex;
		firstItem.HeapIndex = secondIndex;
		secondItem.HeapIndex = heapIndex;
		_items[heapIndex] = secondItem;
		_items[secondIndex] = firstItem;
	}

	public void UpdateItem(T item)
	{
		SortUp(item);
	}

	public bool Contains(T item)
	{
		return object.Equals(_items[item.HeapIndex], item);
	}

	public T[] ReturnTrimmedArray()
	{
		T[] array = new T[_currentItemCount];
		Array.Copy(_items, array, _currentItemCount);
		return array;
	}

	public void Clear()
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			_items[i] = null;
		}
		_currentItemCount = 0;
	}

	public void Clear(ClearItem callback)
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			callback(_items[i]);
			_items[i] = null;
		}
		_currentItemCount = 0;
	}
}
public abstract class IHeapItem<T> : IComparable<T>
{
	public int HeapIndex;

	public abstract int CompareTo(T other);
}
public class Heap2<HEAP_ITEM_TYPE, HEAP_ITEM_GENERIC_TYPE> where HEAP_ITEM_TYPE : HeapItem<HEAP_ITEM_GENERIC_TYPE>, new()
{
	private List<HEAP_ITEM_TYPE> _items;

	private int _currentItemCount;

	public int Count => _currentItemCount;

	public List<HEAP_ITEM_TYPE> Items => _items;

	public Heap2(int capacity = 0)
	{
		_items = new List<HEAP_ITEM_TYPE>(capacity);
	}

	public HEAP_ITEM_TYPE Add(HEAP_ITEM_GENERIC_TYPE item)
	{
		HEAP_ITEM_TYPE val = new HEAP_ITEM_TYPE
		{
			Reference = item,
			Index = _currentItemCount
		};
		if (_items.Count == _currentItemCount)
		{
			_items.Add(val);
			_currentItemCount++;
		}
		else
		{
			_items[_currentItemCount++] = val;
		}
		SortUp(val);
		return val;
	}

	public HEAP_ITEM_TYPE RemoveFirst()
	{
		HEAP_ITEM_TYPE result = _items[0];
		_currentItemCount--;
		HEAP_ITEM_TYPE val = _items[_currentItemCount];
		val.Index = 0;
		_items[0] = val;
		_items[_currentItemCount] = null;
		SortDown(val);
		return result;
	}

	public void Remove(HEAP_ITEM_TYPE item)
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			if (_items[i].Equals(item))
			{
				_currentItemCount--;
				_items[i] = _items[_currentItemCount];
				_items[i].Index = i;
				SortDown(_items[i]);
				break;
			}
		}
	}

	public void Clear()
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			_items[i] = null;
		}
		_currentItemCount = 0;
	}

	private void SortDown(HEAP_ITEM_TYPE item)
	{
		while (true)
		{
			int num = item.Index * 2 + 1;
			if (num >= _currentItemCount)
			{
				break;
			}
			HEAP_ITEM_TYPE val = _items[num];
			int num2 = item.Index * 2 + 2;
			if (num2 < _currentItemCount)
			{
				HEAP_ITEM_TYPE val2 = _items[num2];
				if (val.CompareTo(val2) < 0)
				{
					num = num2;
					val = val2;
				}
			}
			if (item.CompareTo(val) < 0)
			{
				Swap(item, val, num);
				continue;
			}
			break;
		}
	}

	private void SortUp(HEAP_ITEM_TYPE item)
	{
		int num = item.Index;
		while (true)
		{
			num = (num - 1) / 2;
			HEAP_ITEM_TYPE val = _items[num];
			if (0 < item.CompareTo(val))
			{
				Swap(item, val, num);
				continue;
			}
			break;
		}
	}

	private void ValidateItem(HEAP_ITEM_TYPE item)
	{
		if (_items[item.Index].CompareTo(item) != 0)
		{
			PajamaLlama.Debugs.Debugger.Warning("Invalid heap item! Heap index mismatch");
		}
	}

	private void ValidateSorting(int parentIndex = 0)
	{
		HEAP_ITEM_TYPE parent = _items[parentIndex];
		int num = parentIndex * 2 + 1;
		if (TryReturnCorrectlySortedChild(parent, num, out var _))
		{
			int num2 = parentIndex * 2 + 2;
			if (TryReturnCorrectlySortedChild(parent, num2, out var _))
			{
				ValidateSorting(num);
				ValidateSorting(num2);
			}
			else if (num2 < _currentItemCount)
			{
				PajamaLlama.Debugs.Debugger.Warning("Heap not correctly sorted!");
			}
		}
		else if (num < _currentItemCount)
		{
			PajamaLlama.Debugs.Debugger.Warning("Heap not correctly sorted!");
		}
	}

	private bool TryReturnCorrectlySortedChild(HEAP_ITEM_TYPE parent, int childIndex, out HEAP_ITEM_TYPE child)
	{
		if (childIndex < _currentItemCount)
		{
			child = _items[childIndex];
			return 0 <= parent.CompareTo(child);
		}
		child = null;
		return false;
	}

	private void Swap(HEAP_ITEM_TYPE firstItem, HEAP_ITEM_TYPE secondItem, int secondIndex)
	{
		int index = firstItem.Index;
		firstItem.Index = secondIndex;
		secondItem.Index = index;
		_items[index] = secondItem;
		_items[secondIndex] = firstItem;
	}

	public void UpdateItem(HEAP_ITEM_TYPE item)
	{
		SortUp(item);
	}

	public bool Contains(HEAP_ITEM_TYPE item)
	{
		return object.Equals(_items[item.Index], item);
	}

	public bool Contains(HEAP_ITEM_GENERIC_TYPE item)
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			ref HEAP_ITEM_GENERIC_TYPE reference = ref _items[i].Reference;
			object obj = item;
			if (reference.Equals(obj))
			{
				return true;
			}
		}
		return false;
	}

	public bool TryReturnExistingHeapItem(HEAP_ITEM_GENERIC_TYPE item, out HEAP_ITEM_TYPE heapItem)
	{
		for (int i = 0; i < _currentItemCount; i++)
		{
			heapItem = _items[i];
			ref HEAP_ITEM_GENERIC_TYPE reference = ref heapItem.Reference;
			object obj = item;
			if (reference.Equals(obj))
			{
				return true;
			}
		}
		heapItem = null;
		return false;
	}
}
