[Serializable]
public class NavigationTransition
{
	public enum TransitionType
	{
		Teleport,
		Arc,
		Linear,
		Cubic
	}

	[Tooltip("Type of transition.")]
	public TransitionType Type;

	[Tooltip("Graph to start transition from.")]
	public Graph.Type StartingGraph = Graph.Type.WaterSurface;

	[Tooltip("Graph to end transition at.")]
	public Graph.Type TargetGraph = Graph.Type.Constructions;

	[FormerlySerializedAs("IntroTransition")]
	[Tooltip("Should the target position be offset? (Used to make drifters fall deeper into the water)")]
	public bool ApplyOffsetToTargetPosition;

	[Tooltip("The offset that should be applied to the TargetPosition.")]
	public Vector3 TargetPositionOffset = Vector3.zero;

	[Tooltip("Distance threshold at which to start the transition.")]
	public float ThresholdDistance = 5f;

	[Tooltip("Duration of the transition.")]
	public float Duration = 0.5f;

	[Tooltip("Height of the transition arc.")]
	public float Height = 2.4f;

	[Tooltip("Animation ID for the navigation. Use 'TransitionID' in the animator controller to acces this property.")]
	public int AnimationID;

	[Tooltip("Whether the navigator needs to adjust its rotation to look at the target.")]
	public bool LookAtTarget;

	[Tooltip("The curvature of the cubic intermediate points (mirrored). Relative to the start/end points.")]
	public Vector3 Curvature = new Vector3(0f, 0f, 0f);

	[Tooltip("The curve to determine the position of the agent to the time.")]
	public AnimationCurve AnimationCurve;

	private Vector3 _targetPosition;

	public float TimePassed { get; private set; }

	public Vector3 StartPosition { get; private set; }

	public PathfindingNode TargetNode { get; private set; }

	public Vector3 TargetPosition
	{
		get
		{
			if (!ApplyOffsetToTargetPosition)
			{
				return TargetNode.RootPosition;
			}
			return _targetPosition;
		}
		set
		{
			_targetPosition = value;
		}
	}

	public bool IsCompleted => Duration <= TimePassed;

	private NavigationTransition(NavigationTransition navigationTransition)
	{
		Type = navigationTransition.Type;
		StartingGraph = navigationTransition.StartingGraph;
		TargetGraph = navigationTransition.TargetGraph;
		ApplyOffsetToTargetPosition = navigationTransition.ApplyOffsetToTargetPosition;
		ThresholdDistance = navigationTransition.ThresholdDistance;
		Duration = navigationTransition.Duration;
		Height = navigationTransition.Height;
		AnimationID = navigationTransition.AnimationID;
		LookAtTarget = navigationTransition.LookAtTarget;
		Curvature = navigationTransition.Curvature;
		AnimationCurve = navigationTransition.AnimationCurve;
	}

	public bool TryGetInstance(out NavigationTransition navigationTransition, Navigator navigator, PathfindingNode targetNode)
	{
		if (navigator.IsOnGraph(StartingGraph) && targetNode != null && targetNode.Graph != null && targetNode.Graph.GraphType == TargetGraph && Vector3.Distance(navigator.transform.position, targetNode.RootPosition) <= ThresholdDistance)
		{
			navigationTransition = new NavigationTransition(this);
			navigationTransition.StartPosition = navigator.transform.position;
			navigationTransition.TargetNode = targetNode;
			navigationTransition._targetPosition = targetNode.RootPosition + TargetPositionOffset;
			return true;
		}
		navigationTransition = null;
		return false;
	}

	public void Progress(Transform transform, float RotationSpeed, float deltaTime)
	{
		TimePassed += deltaTime;
		TransitionType type = Type;
		if (type == TransitionType.Teleport || (uint)(type - 1) > 2u)
		{
			transform.position = TargetPosition;
		}
		else
		{
			LerpPositionAndRotation(Type, transform, RotationSpeed);
		}
	}

	public void FastForward(Transform transform)
	{
		TimePassed = Duration;
		transform.position = TargetPosition;
	}

	private void LerpPositionAndRotation(TransitionType transitionType, Transform transform = null, float rotationSpeed = 1f)
	{
		float progress = TimePassed / Duration;
		transform.position = ReturnLerpedPosition(transitionType, progress);
		switch (transitionType)
		{
		case TransitionType.Arc:
		case TransitionType.Linear:
			if (LookAtTarget)
			{
				Quaternion to = Quaternion.LookRotation(TargetPosition - StartPosition);
				transform.rotation = Quaternion.RotateTowards(transform.rotation, to, rotationSpeed * Time.deltaTime);
			}
			break;
		case TransitionType.Cubic:
		{
			AnimationTween.Cubic cubic = AnimationTween.CubicLerp(StartPosition, TargetPosition, progress, Curvature, AnimationCurve);
			if (LookAtTarget)
			{
				transform.rotation = Quaternion.LookRotation(new Vector3(cubic.Derivative.x, 0f, cubic.Derivative.z));
			}
			break;
		}
		}
	}

	private Vector3 ReturnLerpedPosition(TransitionType transitionType, float progress)
	{
		switch (transitionType)
		{
		case TransitionType.Arc:
			return AnimationTween.SphericalPositionLerp(StartPosition, TargetPosition, progress, Height);
		case TransitionType.Linear:
			return AnimationTween.LinearPositionLerp(StartPosition, TargetPosition, progress);
		case TransitionType.Cubic:
			return AnimationTween.CubicLerp(StartPosition, TargetPosition, progress, Curvature, AnimationCurve).Position;
		default:
			UnityEngine.Debug.LogWarning($"Tried to do a transition but the transition type was invalid: {transitionType}");
			return TargetPosition;
		}
	}
}
public class NavigatorLineRenderer
{
	private Navigator _navigator;

	private LineRenderer _lineRenderer;

	private ITarget _target;

	private bool _displayPath;

	private List<Vector3> _linePath = new List<Vector3>();

	public NavigatorLineRenderer(Navigator navigator)
	{
		_navigator = navigator;
		_lineRenderer = _navigator.GetComponent<LineRenderer>();
	}

	public void UpdateLineRenderer(ITarget target, NavigatorPathBase path)
	{
		_target = target;
		if (_navigator.State != NavigatorState.Navigating && _navigator.State != NavigatorState.Transitioning)
		{
			if (_lineRenderer.positionCount > 0)
			{
				ClearLineRenderer();
			}
		}
		else if (_displayPath && _target != null && path != null)
		{
			_linePath.Clear();
			_linePath.Add(_navigator.transform.position + Vector3.up * 0.25f);
			path.PopulateLineRenderer(_linePath, Vector3.up);
			if (_target.tag != "Construction")
			{
				_linePath.Add(_target.ReturnPosition() + Vector3.up * 0.25f);
			}
			_lineRenderer.positionCount = _linePath.Count;
			for (int i = 0; i < _linePath.Count; i++)
			{
				_lineRenderer.SetPosition(i, _linePath[i]);
			}
		}
	}

	private void ClearLineRenderer()
	{
		_lineRenderer.positionCount = 0;
	}

	public void EnablePathVisuals(bool enabled = true)
	{
		_lineRenderer.enabled = enabled;
		_displayPath = enabled;
		if (!enabled)
		{
			ClearLineRenderer();
		}
	}
}
public enum NavigatorPathState
{
	None,
	Queued,
	Dequeued,
	Processing,
	Processed,
	Navigating,
	Navigated,
	Canceled,
	Interupted,
	Recalculate
}
public abstract class NavigatorPathBase
{
	private NavigatorPathState _state;

	private ProjectFlags _flags;

	private bool _wasProcessed;

	private bool _recalculateOnProcessed;

	public System.Action NavigationFinished;

	public Navigator Navigator { get; private set; }

	public ITarget Target { get; protected set; }

	public abstract int Length { get; }

	public bool Processed => NavigatorPathState.Processed <= State;

	public bool NoPathFound { get; set; }

	public bool IncompletePath { get; set; }

	public NavigatorPathState State
	{
		get
		{
			return _state;
		}
		protected set
		{
			bool num = _state == NavigatorPathState.Processing;
			_state = value;
			if (num && NavigatorPathState.Processing <= _state)
			{
				if (_recalculateOnProcessed)
				{
					Recalculate();
				}
				else
				{
					_wasProcessed = true;
				}
			}
		}
	}

	public bool WasProcessed
	{
		get
		{
			if (NavigatorPathState.Processed <= State && _wasProcessed)
			{
				_wasProcessed = false;
				return true;
			}
			_wasProcessed = false;
			return false;
		}
	}

	public NavigatorPathBase(Navigator navigator)
	{
		if (navigator == null)
		{
			UnityEngine.Debug.LogException(new Exception("Tried queuing a path without a navigator!"));
		}
		else
		{
			Navigator = navigator;
		}
	}

	public virtual void SetTarget(ITarget target)
	{
		if (target == null)
		{
			UnityEngine.Debug.LogException(new Exception("Tried queuing a path without a target!"));
			return;
		}
		Reset();
		Target = target;
		Target.AddQueuedPath(this);
	}

	public bool ValidateTarget()
	{
		if (Target.IsNull())
		{
			NoPathFound = true;
			State = NavigatorPathState.Processed;
			return false;
		}
		return true;
	}

	public abstract void SetState(NavigatorPathState state);

	public void FinishPath(ProjectFlags flags)
	{
		_flags = flags;
		if (flags.IsFlagSet(ProjectFlags.Success))
		{
			SetState(NavigatorPathState.Navigated);
		}
		else if (flags.IsFlagSet(ProjectFlags.Cancelled))
		{
			SetState(NavigatorPathState.Canceled);
		}
		else
		{
			SetState(NavigatorPathState.Interupted);
		}
		if (Target != null)
		{
			Target.RemoveQueuedPath(this);
		}
		Dequeue();
		if (NavigationFinished != null)
		{
			NavigationFinished();
		}
	}

	public abstract void ClearNodes();

	public void Recalculate()
	{
		if (State < NavigatorPathState.Processing)
		{
			UnityEngine.Debug.LogException(new NotSupportedException("There is no need to recalculate a Path that is not being processed yet."));
		}
		else if (State == NavigatorPathState.Processing)
		{
			UnityEngine.Debug.LogException(new NotImplementedException("Recalculate when processing has completed."));
			_recalculateOnProcessed = true;
		}
		else
		{
			ClearNodes();
			State = NavigatorPathState.Recalculate;
			_recalculateOnProcessed = false;
		}
	}

	public abstract void PopulateLineRenderer(List<Vector3> line, Vector3 offset);

	protected virtual void Dequeue()
	{
	}

	private void Reset()
	{
		Target = null;
		NoPathFound = false;
		IncompletePath = false;
		_recalculateOnProcessed = false;
		_wasProcessed = false;
		SetState(NavigatorPathState.None);
	}

	public virtual bool TryGetNextNode<T>(out T nextNode) where T : PathfindingNode
	{
		nextNode = null;
		return false;
	}

	public virtual void OnDrawGizmos(Navigator navigator)
	{
	}
}
public interface INavigator
{
	byte RequiredClearance { get; }

	byte PreferredClearance { get; }

	int TransitionCost { get; }

	float ReturnTerrainPenalty(Navigator.TerrainType terrain);
}
public enum NavigatorState
{
	Idling,
	Calculating,
	Navigating,
	Transitioning
}
[RequireComponent(typeof(LineRenderer), typeof(PathfinderNavigator))]
public class Navigator : Target, INavigator, IPathfindingNodeDisposedListener, IPathfindingNodeProvider
{
	public enum TerrainType
	{
		WaterSurface,
		Construction,
		Vessel,
		Underwater,
		Sky,
		OutOfBounds,
		UnityNavMesh
	}

	[Serializable]
	public struct TerrainMovementValues
	{
		public TerrainType Type;

		public float Speed;

		public float Penalty;
	}

	[Header("Pathfinding Properties")]
	[Tooltip(" Multiplier for the width to decide on what the optimal width is.")]
	public float PreferredWidthMultiplier = 1f;

	[Header("Navigator Properties")]
	[Tooltip(" Width of this navigator object.")]
	public float Width = 5f;

	[Range(0f, 1f)]
	[Tooltip("The speed at which the navigator should accelerate.")]
	public float AccelerationSpeed = 1f;

	[Tooltip("The distance at which the navigator should start to decelerate.")]
	public float DecelerateDistance = 1f;

	[Range(0f, 1f)]
	[Tooltip("The minimum value for the speed multiplier.")]
	public float MinimumSpeedMultiplier = 1f;

	[Tooltip("The speed at which the navigator will rotate towards the target.")]
	public float RotationSpeed = 30f;

	[Space]
	[Tooltip("Enter one element per terrain type you want to have particular values for, default values if a terrain is not listed here will be a speed of 0 and a penalty of 9999.")]
	public List<TerrainMovementValues> _terrainMovementValues = new List<TerrainMovementValues>();

	[Tooltip("The transition cost for going from the construction graph to a grid")]
	[SerializeField]
	[FormerlySerializedAs("TransitionCost")]
	private int _transitionCost;

	[Space]
	[Tooltip("Possible transitions for this navigator.")]
	[SerializeField]
	private List<NavigationTransition> _transitions = new List<NavigationTransition>();

	private Agent _agent;

	private NavigationTransition _activeTransition;

	private Vector3 _lastTargetPosition = Vector3.zero;

	private GraphBase _currentGraph;

	private PathfindingNode _currentNode;

	private PathfinderNavigator _pathfinderNavigator;

	private UnityNavMeshNavigator _unityNavMeshNavigator;

	[HideInInspector]
	public bool MovingToFreeNode;

	private bool _parentNodeDisposed;

	public static List<Navigator> Navigators = new List<Navigator>();

	public NavigatorState State { get; private set; }

	public TerrainType Terrain { get; private set; }

	public NavigatorPathBase Path { get; private set; }

	public HierarchicalNode IdleNode { get; private set; }

	public NavigatorLineRenderer LineRenderer { get; private set; }

	public byte PreferredClearance { get; private set; }

	public byte RequiredClearance { get; private set; }

	public int TransitionCost => _transitionCost;

	public ITarget Target { get; private set; }

	public PathfinderNavigator PathfinderNavigator => _pathfinderNavigator;

	public bool AllowIncompletePath { get; private set; }

	protected override void Awake()
	{
		base.Awake();
		if (_isVessel)
		{
			_boat = GetComponent<Boat>();
		}
		else
		{
			_agent = GetComponent<Agent>();
		}
		Navigators.AddUnique(this);
		SetupNavigationModes();
	}

	private void OnEnable()
	{
		bool flag = Terrain == TerrainType.UnityNavMesh;
		_pathfinderNavigator.enabled = !flag;
		if (_unityNavMeshNavigator != null)
		{
			_unityNavMeshNavigator.enabled = flag;
		}
	}

	private void Start()
	{
		RequiredClearance = ComputeRequiredClearance();
		PreferredClearance = (byte)Mathf.CeilToInt(Width * PreferredWidthMultiplier);
		if (_pathfinderNavigator.enabled)
		{
			UpdateGraph(GameManager.GraphManager.ReturnNode(this, this, 16, onlyUnblocked: false));
		}
		LineRenderer = new NavigatorLineRenderer(this);
	}

	private void Update()
	{
		UpdateState();
		switch (State)
		{
		case NavigatorState.Navigating:
			if (_pathfinderNavigator.enabled)
			{
				_pathfinderNavigator.FollowPath(_currentGraph, Time.deltaTime);
			}
			break;
		case NavigatorState.Transitioning:
			_activeTransition?.Progress(base.transform, RotationSpeed, Time.deltaTime);
			break;
		}
		LineRenderer.UpdateLineRenderer(Target, Path);
	}

	private void LateUpdate()
	{
		if (_parentNodeDisposed)
		{
			UpdateTerrain(TerrainType.OutOfBounds);
			_parentNodeDisposed = false;
		}
	}

	private void OnDisable()
	{
		_pathfinderNavigator.enabled = false;
		if (_unityNavMeshNavigator != null)
		{
			_unityNavMeshNavigator.enabled = false;
		}
	}

	private void OnDrawGizmos()
	{
		if (_debug && Path != null && !Target.IsNull())
		{
			if (Path.Length == 0)
			{
				DrawPathSegment(base.transform.position, Target.Position, Color.cyan);
			}
			else
			{
				Path.OnDrawGizmos(this);
			}
		}
	}

	public bool StartNavigation(ITarget target, bool allowIncompletePath = false)
	{
		Target = target.ReturnTarget();
		AllowIncompletePath = allowIncompletePath;
		if (_pathfinderNavigator.enabled)
		{
			_pathfinderNavigator.StopAllCoroutines();
			if (_activeTransition != null)
			{
				_activeTransition.FastForward(base.transform);
				UpdateState();
				_activeTransition = null;
			}
			if (ReturnPathfindingNode(null) == null)
			{
				UnityEngine.Debug.LogException(new Exception($"StartNavigation was called for '{this}' which was out of bounds (ReturnPathfindingNode() == null)! It is being reset to the town."));
				return false;
			}
		}
		StopIdling();
		ClearPath();
		Path = (_pathfinderNavigator.enabled ? _pathfinderNavigator.GetNewPathfinderPath(Target) : _unityNavMeshNavigator.SetDestination(Target));
		UpdateState();
		return true;
	}

	public void RestartNavigation()
	{
		NavigatorState state = State;
		if ((uint)state > 1u)
		{
			if (Target.IsNull())
			{
				UnityEngine.Debug.LogException(new Exception("Navigator cannot be restarted when it has no MoveTarget!"));
			}
			else
			{
				StartNavigation(Target, AllowIncompletePath);
			}
		}
	}

	public void StopNavigation(ProjectFlags flags)
	{
		Path?.FinishPath(flags);
		ClearPath();
		UpdateState();
		base.transform.localRotation = Quaternion.Euler(0f, base.transform.localRotation.eulerAngles.y, 0f);
		if (_unityNavMeshNavigator != null && _unityNavMeshNavigator.UnityNavMeshAgent.isOnNavMesh)
		{
			_unityNavMeshNavigator.UnityNavMeshAgent.velocity = Vector3.zero;
			_unityNavMeshNavigator.UnityNavMeshAgent.isStopped = true;
		}
	}

	public void BeginIdling(PathfindingNode node)
	{
		IdleNode = node as HierarchicalNode;
		if (IdleNode != null)
		{
			if (IdleNode.Marker == null)
			{
				IdleNode = null;
			}
			else
			{
				IdleNode.Marker.SetIdlingAgent(_agent);
			}
		}
	}

	public void StopIdling()
	{
		if (IdleNode != null)
		{
			IdleNode.Marker?.RemoveIdlingAgent(_agent);
			IdleNode = null;
		}
	}

	private void UpdateState()
	{
		if (Path == null)
		{
			SetState(NavigatorState.Idling);
		}
		else if (!Path.Processed)
		{
			SetState(NavigatorState.Calculating);
		}
		else if (Path.NoPathFound)
		{
			StopNavigation(ProjectFlags.InValid);
		}
		else if (State == NavigatorState.Transitioning)
		{
			if (Path.Length == 0)
			{
				SetState(NavigatorState.Navigating);
				_activeTransition = null;
			}
			else if (_activeTransition.IsCompleted)
			{
				UpdateGraph(_activeTransition.TargetNode);
				SetState(NavigatorState.Navigating);
				if (_pathfinderNavigator.isActiveAndEnabled)
				{
					_pathfinderNavigator.RemoveNodeFromPath(_activeTransition.TargetNode);
				}
				_activeTransition = null;
			}
		}
		else if (_activeTransition == null && TransitionNeeded(out _activeTransition))
		{
			SetState(NavigatorState.Transitioning);
		}
		else
		{
			SetState(NavigatorState.Navigating);
		}
	}

	private void SetState(NavigatorState stateToSet)
	{
		if (State != stateToSet)
		{
			State = stateToSet;
			switch (stateToSet)
			{
			case NavigatorState.Navigating:
				UpdateAgentActivity(Activity.Moving);
				break;
			case NavigatorState.Transitioning:
				UpdateAgentActivity(Activity.Transitioning);
				break;
			}
		}
	}

	public void OnParentNodeDisposed()
	{
		base.transform.SetParent(null, worldPositionStays: true);
		_parentNodeDisposed = true;
	}

	public void Reset()
	{
		PlaceAt(base.transform.position, overrideCheck: true);
	}

	private void ClearPath()
	{
		Path?.ClearNodes();
		Path = null;
	}

	public void UpdateTerrain(TerrainType terrain, bool overrideUpdate = false)
	{
		if (Terrain == terrain && !overrideUpdate)
		{
			return;
		}
		if (terrain == TerrainType.UnityNavMesh)
		{
			if (_unityNavMeshNavigator == null)
			{
				throw new NotSupportedException("Cannot set Navigator.Terrain = UnityNavMesh on Navigator that cannot use the Unity navmesh.");
			}
			ClearPath();
			_pathfinderNavigator.enabled = false;
			_unityNavMeshNavigator.enabled = true;
			_unityNavMeshNavigator.UnityNavMeshAgent.speed = ReturnSpeed(TerrainType.UnityNavMesh);
			if (_unityNavMeshNavigator.UnityNavMeshAgent.speed == 0f)
			{
				PajamaLlama.Debugs.Debugger.Warning($"There is no TerrainMovementValues associated to UnityNavMesh for this agent, its speed on Unity NavMesh has been set to zero.");
			}
		}
		else
		{
			if (Terrain == TerrainType.UnityNavMesh)
			{
				ClearPath();
			}
			_pathfinderNavigator.enabled = true;
			if (_unityNavMeshNavigator != null)
			{
				_unityNavMeshNavigator.enabled = false;
			}
		}
		Terrain = terrain;
		if (_agent != null)
		{
			_agent.UpdateAgentTerrain(Terrain);
		}
	}

	private void UpdateAgentActivity(Activity activity)
	{
		Agent agent = (_isVessel ? _boat.Captain : _agent);
		if (!(agent == null) && agent.IsAlive && agent.CurrentActivity != Activity.Drowning)
		{
			agent.UpdateActivity(activity);
		}
	}

	public void UpdateGraph(PathfindingNode node, bool updateParent = true)
	{
		if (node != null)
		{
			_currentNode = node;
			_currentGraph = node.Graph;
			switch (_currentGraph.GraphType)
			{
			case Graph.Type.WaterSurface:
				UpdateTerrain(TerrainType.WaterSurface);
				break;
			case Graph.Type.Constructions:
				UpdateTerrain(TerrainType.Construction);
				break;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				break;
			}
			if (updateParent)
			{
				UpdateParent();
			}
		}
	}

	public void UpdateParent()
	{
		Transform agentParent = _currentNode.GetAgentParent();
		if (base.transform.parent != agentParent)
		{
			base.transform.SetParent(agentParent);
		}
	}

	public void DrawPathSegment(Vector3 startPoint, Vector3 endPoint, Color color)
	{
		Vector3 vector = endPoint - startPoint;
		Gizmos.color = color;
		Gizmos.DrawLine(startPoint, endPoint);
		Vector3 normalized = Vector3.Cross(vector, Vector3.up).normalized;
		Gizmos.color = color * 0.75f;
		Gizmos.DrawLine(startPoint + normalized * Width * 0.5f, startPoint + normalized * Width * 0.5f + vector);
		Gizmos.DrawLine(startPoint - normalized * Width * 0.5f, startPoint - normalized * Width * 0.5f + vector);
	}

	public void SetupNavigationModes()
	{
		_pathfinderNavigator = GetComponent<PathfinderNavigator>();
		_pathfinderNavigator.Navigator = this;
		_pathfinderNavigator.Radius = Radius;
		_pathfinderNavigator.Agent = _agent;
		if (Graph.TypesMatch(TargetGraphType, Graph.Type.UnityNavMesh))
		{
			_unityNavMeshNavigator = GetComponent<UnityNavMeshNavigator>();
			_unityNavMeshNavigator.Navigator = this;
		}
	}

	public void PlaceAt(Vector3 position, bool overrideCheck = false, bool placeOnObstacle = true)
	{
		if (!placeOnObstacle || !TryGetObstacle(out var obstacle, position))
		{
			AttachToNode(GameManager.GraphManager.ReturnNode(this, this), position, overrideCheck);
			return;
		}
		if (!Graph.TypesMatch(TargetGraphType, Graph.Type.Constructions) || !Graph.TypesMatch(obstacle.TargetGraphType, Graph.Type.Constructions))
		{
			UnityEngine.Debug.LogException(new NotImplementedException($"Needs additional code to place navigator the position of {position} that's blocked by {obstacle}"));
		}
		AttachToTarget(obstacle, overrideCheck);
	}

	public void AttachToNode(PathfindingNode node, Vector3 position = default(Vector3), bool overrideCheck = false)
	{
		if (node == null)
		{
			PajamaLlama.Debugs.Debugger.Warning("No node given to attach to. Moved to out of bounds terrain.", this);
			UpdateTerrain(TerrainType.OutOfBounds);
			return;
		}
		node.UpdateRootPosition();
		if (node.Graph is Grid)
		{
			if (position == default(Vector3))
			{
				base.transform.position = node.RootPosition;
			}
			else
			{
				base.transform.position = position.SetY(node.Graph.Height);
			}
		}
		else
		{
			base.transform.position = node.RootPosition;
			BeginIdling(node);
		}
		UpdateGraph(node);
	}

	public bool AttachToTarget(Target target, bool overrideCheck = false)
	{
		if (target.PrimaryMarker == null || target.PrimaryMarker.Node == null)
		{
			PajamaLlama.Debugs.Debugger.Warning("No node given to attach to.", this);
			return false;
		}
		HierarchicalNode node = (HierarchicalNode)target.PrimaryMarker.Node.ReturnNode(this, this, onlyUnblocked: true, leaf: true, 16, hasLineOfSight: false, onlyInRange: false);
		bool overrideCheck2 = overrideCheck;
		AttachToNode(node, default(Vector3), overrideCheck2);
		return true;
	}

	private bool TransitionNeeded(out NavigationTransition navigationTransition)
	{
		navigationTransition = null;
		if (Path.TryGetNextNode<PathfindingNode>(out var nextNode))
		{
			foreach (NavigationTransition transition in _transitions)
			{
				if (transition.TryGetInstance(out navigationTransition, this, nextNode))
				{
					return true;
				}
			}
		}
		return false;
	}

	public void OnPathfindingNodeDisposed(PathfindingNode node)
	{
		if (IdleNode == node)
		{
			IdleNode = null;
		}
		Path?.Recalculate();
	}

	public bool Validate()
	{
		if (Terrain == TerrainType.UnityNavMesh)
		{
			return _unityNavMeshNavigator.UnityNavMeshAgent.isOnNavMesh;
		}
		return true;
	}

	public bool IsOnGraph(GraphBase graph)
	{
		return graph == _currentGraph;
	}

	public bool IsOnGraph(Graph.Type graphType)
	{
		if (_currentGraph != null)
		{
			return _currentGraph.TypesMatch(graphType);
		}
		return false;
	}

	public override PathfindingNode ReturnPathfindingNode(Navigator navigator = null)
	{
		if (_currentGraph == null)
		{
			return null;
		}
		UpdatePosition();
		PathfindingNode pathfindingNode = _currentGraph.ReturnNode(this, this, 16);
		if (pathfindingNode == null || pathfindingNode.IsOutOfBounds)
		{
			UpdateTerrain(TerrainType.OutOfBounds);
			UpdatePosition();
			pathfindingNode = _currentGraph.ReturnNode(this, this, 16);
		}
		return pathfindingNode;
	}

	public float ReturnSpeed()
	{
		return ReturnSpeed(Terrain);
	}

	public float ReturnSpeed(TerrainType terrain)
	{
		float num = 1f;
		float result = 0f;
		if (_agent != null && _agent.Attributes != null)
		{
			num = _agent.Attributes.ReturnAttributeModifier(DrifterAttributes.AttributeType.Athletics);
		}
		for (int i = 0; i < _terrainMovementValues.Count; i++)
		{
			if (_terrainMovementValues[i].Type == terrain)
			{
				result = _terrainMovementValues[i].Speed;
				return result * num;
			}
		}
		return result;
	}

	public float ReturnTerrainPenalty(TerrainType terrain)
	{
		foreach (TerrainMovementValues terrainMovementValue in _terrainMovementValues)
		{
			if (terrainMovementValue.Type == terrain)
			{
				return terrainMovementValue.Penalty;
			}
		}
		return 9999f;
	}

	public bool ReturnIsOutOfBounds()
	{
		if (WorldManager.IsInInteractionRadius(base.transform.position))
		{
			return false;
		}
		NavigatorState state = State;
		if (state == NavigatorState.Calculating || state == NavigatorState.Transitioning)
		{
			return false;
		}
		return Terrain switch
		{
			TerrainType.UnityNavMesh => _unityNavMeshNavigator.ReturnIsOutOfBounds(), 
			TerrainType.OutOfBounds => true, 
			_ => GameManager.GraphManager.WaterSurfaceGraph.ReturnNode(this, this, 16, onlyUnblocked: false) == null, 
		};
	}

	public bool TryReturnNavMeshOwnerComponent<T>(out T component) where T : UnityEngine.Component
	{
		component = null;
		if (Terrain == TerrainType.UnityNavMesh && _unityNavMeshNavigator.UnityNavMeshAgent.navMeshOwner is NavMeshSurface navMeshSurface)
		{
			return navMeshSurface.TryGetComponent<T>(out component);
		}
		return false;
	}

	public byte ComputeRequiredClearance()
	{
		return (byte)Mathf.CeilToInt(Width);
	}

	public override string ToString()
	{
		if ((bool)_agent)
		{
			return _agent.Name;
		}
		if ((bool)_boat)
		{
			return _boat.Buildable.Name;
		}
		return base.ToString();
	}

	public bool IsInRange(ITarget target)
	{
		if (target != null && !(base.transform == null))
		{
			return Vector3.Distance(base.transform.position, target.Position) < Radius + target.Range;
		}
		return true;
	}

	private bool TryGetObstacle(out Obstacle obstacle, Vector3 point)
	{
		for (int i = 0; i < Obstacle.AllObstacles.Count; i++)
		{
			obstacle = Obstacle.AllObstacles[i];
			if ((bool)obstacle && Graph.TypesMatch(TargetGraphType, obstacle.ObstacleGraphType) && Vector3.Distance(point, obstacle.transform.position) < Radius + obstacle.Radius)
			{
				return true;
			}
		}
		obstacle = null;
		return false;
	}

	public static TerrainType ReturnTerrainTypeFromGraphType(Graph.Type graphType)
	{
		switch (graphType)
		{
		case Graph.Type.WaterSurface:
			return TerrainType.WaterSurface;
		case Graph.Type.Constructions:
			return TerrainType.Construction;
		case Graph.Type.UnityNavMesh:
			return TerrainType.UnityNavMesh;
		default:
			UnityEngine.Debug.LogException(new NotImplementedException());
			return TerrainType.WaterSurface;
		}
	}

	Transform IPathfindingNodeProvider.get_transform()
	{
		return base.transform;
	}
}
public class PathfinderNavigator : MonoBehaviour
{
	[SerializeField]
	private float _fixedDeltaTime = 1f / 30f;

	[SerializeField]
	[Tooltip("The amount of times per frame line of sight is tested against the path. Every time there is line of sight the first node in the path is removed.")]
	[Range(1f, 10f)]
	private int _lineOfSightItterations = 3;

	private Navigator.TerrainType _terrain;

	private PathfinderPath _path;

	private float _accelerationMultiplier;

	private bool _canNavigateLineOffSight;

	private Construction _startingConstruction;

	private ITarget _target;

	private Transform _transform;

	private Rect _lineOfSightBounds;

	private Vector3 _lineOfSightPadding;

	[HideInInspector]
	public Navigator Navigator { get; set; }

	[HideInInspector]
	public float Radius { get; set; }

	[HideInInspector]
	public Agent Agent { get; set; }

	private void Awake()
	{
		_transform = base.transform;
	}

	private void LateUpdate()
	{
		_lineOfSightPadding = new Vector3(Navigator.Width * 2f, 0f, Navigator.Width * 2f);
		ClearLineOfSight(_lineOfSightItterations);
	}

	private IEnumerator GetPathCoroutine()
	{
		Pathfinder.QueuePath(_path);
		while (_path != null && !_path.Processed)
		{
			yield return null;
		}
		Navigator.LineRenderer.UpdateLineRenderer(_target, _path);
	}

	public NavigatorPathBase GetNewPathfinderPath(ITarget target)
	{
		_path = new PathfinderPath(Navigator, target);
		_target = target;
		if (_path == null)
		{
			PajamaLlama.Debugs.Debugger.Warning($"Queued path is null.");
		}
		StartCoroutine(GetPathCoroutine());
		return _path;
	}

	private bool HasLineOfSight(Vector3 startPosition, Vector3 endPosition)
	{
		_lineOfSightBounds.min = (Vector3.Min(startPosition, endPosition) - _lineOfSightPadding).Vector2TopDown();
		_lineOfSightBounds.max = (Vector3.Max(startPosition, endPosition) + _lineOfSightPadding).Vector2TopDown();
		Vector3 direction = endPosition - startPosition;
		for (int i = 0; i < Obstacle.LineOfSightObstables.Count; i++)
		{
			Obstacle obstacle = Obstacle.LineOfSightObstables[i];
			if (_lineOfSightBounds.Overlaps(obstacle.Polygon.Bounds) && obstacle.ReturnIsLineIntersecting(startPosition, direction, Navigator.Width))
			{
				return false;
			}
		}
		return true;
	}

	public void FollowPath(GraphBase currentGraph, float deltaTime)
	{
		if (_target.IsNull() || _path == null || currentGraph == null)
		{
			Navigator.StopNavigation(ProjectFlags.Exception);
			return;
		}
		if (_path.State == NavigatorPathState.Processed)
		{
			if (_path.NoPathFound)
			{
				Navigator.StopNavigation(ProjectFlags.Exception);
				return;
			}
			_path.SetState(NavigatorPathState.Navigating);
		}
		if (RecalculateIfNeeded() || _path.State != NavigatorPathState.Navigating)
		{
			return;
		}
		for (float num = deltaTime; num > 0f; num -= _fixedDeltaTime)
		{
			if (num <= _fixedDeltaTime)
			{
				FollowPathFixedDeltaTime(currentGraph, num);
			}
			else
			{
				FollowPathFixedDeltaTime(currentGraph, _fixedDeltaTime);
			}
		}
		Navigator.UpdateParent();
		UpdateOutline();
	}

	public void FollowPathFixedDeltaTime(GraphBase currentGraph, float deltaTime)
	{
		if (!_path.TryGetNextNode<PathfindingNode>(out var nextNode) && Navigator.IsInRange(_target))
		{
			if (!Graph.TypesMatch(_target.GraphType, currentGraph.GraphType))
			{
				UnityEngine.Debug.LogException(new Exception($"Navigator should have reached it's destination (on graph {_target.GraphType}) but is on the wrong graph({currentGraph.GraphType})!"));
			}
			Navigator.StopNavigation(ProjectFlags.Success);
			return;
		}
		Vector3 position = _transform.position;
		_accelerationMultiplier += Navigator.AccelerationSpeed * deltaTime;
		float num = Vector3.Distance(position, _target.Position) - (Radius + _target.Range);
		if (nextNode == null && num <= Navigator.DecelerateDistance)
		{
			_accelerationMultiplier = num / Navigator.DecelerateDistance;
		}
		_accelerationMultiplier = Mathf.Clamp(_accelerationMultiplier, Navigator.MinimumSpeedMultiplier, 1f);
		Vector3 vector = ((nextNode == null) ? _target.ReturnPosition() : ReturnRootPosition(nextNode, position));
		Vector3 vector2 = (vector - position).normalized * Navigator.ReturnSpeed() * _accelerationMultiplier;
		float num2 = 1f;
		if (_terrain != Navigator.TerrainType.Vessel)
		{
			if (Vector3.Distance(position, vector2) >= 1f)
			{
				Vector3 vector3 = vector - position;
				Quaternion quaternion = ((vector3 == Vector3.zero) ? Quaternion.identity : Quaternion.LookRotation(vector3));
				_transform.rotation = Quaternion.RotateTowards(_transform.rotation, quaternion, Navigator.RotationSpeed * deltaTime);
				float num3 = Quaternion.Angle(quaternion, _transform.rotation);
				if (num3 > 10f)
				{
					num2 = (180f - num3) / 180f;
					_accelerationMultiplier *= num2;
				}
			}
		}
		else if (Vector3.Distance(position, vector) >= 1f)
		{
			_transform.LookAt(vector);
		}
		if (_terrain != Navigator.TerrainType.Construction && _terrain != Navigator.TerrainType.Vessel)
		{
			Vector3 zero = Vector3.zero;
			zero = GameManager.PhysicsManager.MovingWorldDirection * GameManager.PhysicsManager.MovingWorldForce;
			if (zero == Vector3.zero)
			{
				zero = -GameManager.PhysicsManager.MovingFlotsamDirection * GameManager.PhysicsManager.MovingFlotsamForce;
			}
			Vector3 vector4 = vector2 + zero * GameManager.Settings.GameplaySettings.WorldPhysics.NavigatorWorldSpeedMultiplier * Radius;
			_transform.Translate(vector4 * deltaTime * num2, Space.World);
		}
		else
		{
			_transform.Translate(vector2 * deltaTime, Space.World);
		}
		if (nextNode != null && ReturnDistanceToNode(position, nextNode) < Radius)
		{
			Navigator.UpdateGraph(nextNode, updateParent: false);
			RemoveNodeFromPath(nextNode);
		}
	}

	private void ClearLineOfSight(int itterations = 1)
	{
		if (Navigator.State != NavigatorState.Navigating || Navigator.IsOnGraph(Graph.Type.Constructions))
		{
			return;
		}
		for (int i = 0; i < itterations; i++)
		{
			if (1 >= _path.Length)
			{
				break;
			}
			PathfindingNode pathfindingNode = _path.Nodes[0];
			PathfindingNode pathfindingNode2 = _path.Nodes[1];
			if (pathfindingNode.IsGridNode && pathfindingNode.Graph == pathfindingNode2.Graph && HasLineOfSight(base.transform.position, pathfindingNode2.RootPosition))
			{
				RemoveNodeFromPath(pathfindingNode);
				continue;
			}
			break;
		}
	}

	private bool RecalculateIfNeeded()
	{
		if (_path.State == NavigatorPathState.Recalculate)
		{
			UnityEngine.Debug.Log("Recalculating path. (target changed)");
			StartCoroutine(GetPathCoroutine());
			return true;
		}
		return false;
	}

	public void RemoveNodeFromPath(PathfindingNode node)
	{
		node.UnsubscribeDisposedListener(Navigator);
		_path.Nodes.Remove(node);
	}

	private void UpdateOutline()
	{
		Construction construction = null;
		if (_path.TryGetNextNode<HierarchicalNode>(out var nextNode))
		{
			if ((bool)nextNode.Marker)
			{
				if (_startingConstruction == null)
				{
					_startingConstruction = nextNode.Marker.Construction;
				}
				construction = nextNode.Marker.Construction;
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception("[LOG] Unable to update PathfinderNavigator outline, HierarchicalNode.Marker == NULL."), this);
			}
		}
		if (_startingConstruction == construction && construction != null && Navigator.IsOnGraph(Graph.Type.Constructions))
		{
			_startingConstruction.Buildable.OutlineRenderer.UpdateAgent(Agent, AddToConstructionOutline: true);
		}
		if (_startingConstruction != construction && _startingConstruction != null)
		{
			_startingConstruction.Buildable.OutlineRenderer.UpdateAgent(Agent);
			_startingConstruction = null;
		}
	}

	private float ReturnDistanceToNode(Vector3 position, PathfindingNode node)
	{
		if (node.IsGridNode)
		{
			return Vector2.Distance(position.Vector2TopDown(), node.RootPosition2D);
		}
		return Vector3.Distance(position, node.RootPosition);
	}

	private Vector3 ReturnRootPosition(PathfindingNode node, Vector3 position)
	{
		if (node.IsGridNode)
		{
			Vector3 rootPosition = node.RootPosition;
			rootPosition.y = position.y;
			return rootPosition;
		}
		return node.RootPosition;
	}
}
public class PathfinderPath : NavigatorPathBase
{
	public List<PathfindingNode> Nodes { get; private set; }

	public override int Length
	{
		get
		{
			if (Nodes == null)
			{
				return 0;
			}
			return Nodes.Count;
		}
	}

	public PathfinderPath(Navigator navigator, ITarget target)
		: base(navigator)
	{
		SetTarget(target);
	}

	public override void SetState(NavigatorPathState newState)
	{
		if (base.State == newState)
		{
			return;
		}
		switch (base.State)
		{
		case NavigatorPathState.None:
			if (newState == NavigatorPathState.Queued)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Recalculate:
			if (newState == NavigatorPathState.Queued)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Queued:
			if (newState == NavigatorPathState.Processing || newState == NavigatorPathState.Processed)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Processing:
			if (newState == NavigatorPathState.Processed)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Processed:
			if (newState == NavigatorPathState.Navigating || newState == NavigatorPathState.Canceled)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Navigating:
			if (newState == NavigatorPathState.Navigated || newState == NavigatorPathState.Canceled)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Dequeued:
		case NavigatorPathState.Navigated:
		case NavigatorPathState.Canceled:
		case NavigatorPathState.Interupted:
			if (newState == NavigatorPathState.None)
			{
				break;
			}
			goto default;
		default:
			UnityEngine.Debug.LogException(new Exception($"'{base.Navigator}' its PathfinderPath with target '{base.Target}' is changing its State from '{base.State}' to '{newState}'. This is unexpected behaviour!"));
			break;
		}
		base.State = newState;
		if (newState == NavigatorPathState.Navigating)
		{
			GameEventDispatcher.AddListener(GameEventType.PathfindingNodeUpdated, OnPathfindingNodeUpdated);
		}
		else
		{
			GameEventDispatcher.RemoveListener(GameEventType.PathfindingNodeUpdated, OnPathfindingNodeUpdated);
		}
	}

	public void SetNodes(List<PathfindingNode> nodes, bool incompletePath = false)
	{
		Nodes = nodes;
		base.IncompletePath = incompletePath;
	}

	public override void ClearNodes()
	{
		if (!Nodes.IsNullOrEmpty())
		{
			for (int i = 0; i < Nodes.Count; i++)
			{
				Nodes[i].UnsubscribeDisposedListener(base.Navigator);
			}
			Nodes.Clear();
			Nodes = null;
		}
	}

	public override void PopulateLineRenderer(List<Vector3> linePath, Vector3 offset)
	{
		int length = Length;
		for (int i = 0; i < length; i++)
		{
			linePath.Add(Nodes[i].RootPosition + offset);
		}
	}

	protected override void Dequeue()
	{
		if (Pathfinder.DequeuePath(this))
		{
			SetState(NavigatorPathState.Dequeued);
		}
	}

	public override bool TryGetNextNode<T>(out T nextNode)
	{
		nextNode = null;
		if (base.State == NavigatorPathState.Navigating && 0 < Length)
		{
			nextNode = Nodes[0] as T;
		}
		return nextNode != null;
	}

	private void OnPathfindingNodeUpdated(GameEvent gameEvent)
	{
		if (base.State == NavigatorPathState.Navigating)
		{
			if (gameEvent is PathfindingEvent pathfindingEvent && pathfindingEvent.HasNodeUpdatedOnPath(Nodes))
			{
				Recalculate();
			}
		}
		else
		{
			GameEventDispatcher.RemoveListener(GameEventType.PathfindingNodeUpdated, OnPathfindingNodeUpdated);
		}
	}

	public override void OnDrawGizmos(Navigator navigator)
	{
		if (base.NoPathFound || base.State < NavigatorPathState.Processed || Length == 0)
		{
			return;
		}
		PathfindingNode pathfindingNode = null;
		navigator.DrawPathSegment(navigator.transform.position, Nodes[0].RootPosition, Color.cyan);
		List<PathfindingNode> nodes = Nodes;
		navigator.DrawPathSegment(nodes[nodes.Count - 1].RootPosition, base.Target.Position, Color.cyan);
		foreach (PathfindingNode node in Nodes)
		{
			if (pathfindingNode != null)
			{
				navigator.DrawPathSegment(pathfindingNode.RootPosition, node.RootPosition, Color.magenta);
			}
			Gizmos.DrawCube(node.RootPosition, new Vector3(0.5f, 1f, 0.5f));
			pathfindingNode = node;
		}
	}
}
[RequireComponent(typeof(NavMeshAgent))]
public class UnityNavMeshNavigator : MonoBehaviour
{
	private UnityNavMeshPath _path;

	private ITarget _target;

	private Vector3 _targetDestination;

	private NavMeshSurface _navMeshSurface;

	private Vector3 _lastValidNavMeshSurfacePosition;

	private bool _townheartMoved;

	public Navigator Navigator { get; set; }

	public NavMeshAgent UnityNavMeshAgent { get; private set; }

	private void Awake()
	{
		UnityNavMeshAgent = GetComponent<NavMeshAgent>();
		if ((bool)UnityNavMeshAgent)
		{
			if (UnityNavMeshAgent.stoppingDistance < UnityNavMeshAgent.radius)
			{
				UnityEngine.Debug.LogWarning("NavMeshAgent stopping distance is smaller than its (collision avoidence) radius! This could cause problems when 2 NavMeshAgents reach the same destination around the same time!");
			}
		}
		else
		{
			PajamaLlama.Debugs.Debugger.Warning("A NavMesh Agent component needs to be attached to this agent.", this);
		}
	}

	private void OnEnable()
	{
		UnityNavMeshAgent.enabled = true;
		_navMeshSurface = UnityNavMeshAgent.navMeshOwner as NavMeshSurface;
		if (!CacheNavMeshSurfacePosition())
		{
			UnityEngine.Debug.LogErrorFormat("Navigator '{0}' was enabled while not being on a NavMesh!", base.name);
		}
		GameEventDispatcher.AddListener(GameEventType.TownheartMoved, OnTownheartMoved);
	}

	private void Update()
	{
		if (_path == null)
		{
			return;
		}
		if (_path.State == NavigatorPathState.Navigating)
		{
			if (!_path.NoPathFound)
			{
				float num = Vector3.Distance(base.transform.position, _target.ReturnPosition());
				float num2 = UnityNavMeshAgent.stoppingDistance + _target.Range;
				if (num < num2)
				{
					Navigator.StopNavigation(ProjectFlags.Success);
				}
				else if (UnityNavMeshAgent.pathStatus == NavMeshPathStatus.PathInvalid || UnityNavMeshAgent.remainingDistance < num2)
				{
					Navigator.StopNavigation(ProjectFlags.Exception);
				}
			}
		}
		else if (_path.State == NavigatorPathState.Processing && !UnityNavMeshAgent.pathPending)
		{
			_path.SetState(NavigatorPathState.Navigating);
			switch (UnityNavMeshAgent.path.status)
			{
			case NavMeshPathStatus.PathPartial:
				_path.IncompletePath = true;
				break;
			case NavMeshPathStatus.PathInvalid:
				_path.NoPathFound = true;
				Navigator.StopNavigation(ProjectFlags.InValid);
				return;
			}
			_path.Nodes.Clear();
			_path.Nodes.AddRange(UnityNavMeshAgent.path.corners);
			Navigator.LineRenderer.UpdateLineRenderer(_target, _path);
		}
	}

	private void LateUpdate()
	{
		if (_target == null)
		{
			return;
		}
		if (_townheartMoved)
		{
			if (UnityNavMeshAgent.isOnNavMesh)
			{
				UnityNavMeshAgent.ResetPath();
				SetDestination(_target);
				_townheartMoved = false;
			}
		}
		else if (!CacheNavMeshSurfacePosition())
		{
			UnityEngine.Debug.LogException(new Exception($"UnityNavMeshNavigator '{Navigator}' is no longer on a NavMeshSurface!"));
		}
	}

	private void OnDisable()
	{
		if (UnityNavMeshAgent.isOnNavMesh)
		{
			UnityNavMeshAgent.isStopped = true;
		}
		UnityNavMeshAgent.enabled = false;
		GameEventDispatcher.RemoveListener(GameEventType.TownheartMoved, OnTownheartMoved);
	}

	public NavigatorPathBase SetDestination(ITarget target)
	{
		UnityNavMeshAgent.isStopped = false;
		if (_path == null)
		{
			_path = new UnityNavMeshPath(this);
		}
		_path.SetTarget(target);
		_path.SetState(NavigatorPathState.Processing);
		_target = target;
		_targetDestination = _target.ReturnPosition();
		if (!UnityNavMeshAgent.SetDestination(_targetDestination))
		{
			_path.NoPathFound = true;
		}
		return _path;
	}

	private void OnTownheartMoved(GameEvent gameEvent)
	{
		UnityNavMeshAgent.Warp(_navMeshSurface.transform.TransformPoint(_lastValidNavMeshSurfacePosition));
		_townheartMoved = true;
	}

	private bool CacheNavMeshSurfacePosition()
	{
		if (UnityNavMeshAgent.isOnNavMesh && (bool)_navMeshSurface && UnityNavMeshAgent.navMeshOwner == _navMeshSurface)
		{
			_lastValidNavMeshSurfacePosition = _navMeshSurface.transform.InverseTransformPoint(base.transform.position);
			return true;
		}
		return false;
	}

	public bool ReturnIsOutOfBounds()
	{
		if (!(UnityNavMeshAgent == null) && UnityNavMeshAgent.enabled)
		{
			return !UnityNavMeshAgent.isOnNavMesh;
		}
		return true;
	}
}
public class UnityNavMeshPath : NavigatorPathBase
{
	public List<Vector3> Nodes { get; private set; }

	public override int Length
	{
		get
		{
			if (Nodes == null)
			{
				return 0;
			}
			return Nodes.Count;
		}
	}

	public UnityNavMeshPath(UnityNavMeshNavigator navMeshNavigator)
		: base(navMeshNavigator.Navigator)
	{
		Nodes = new List<Vector3>();
	}

	public override void SetTarget(ITarget target)
	{
		base.SetTarget(target);
		SetState(NavigatorPathState.Processing);
	}

	public override void SetState(NavigatorPathState state)
	{
		if (base.State == state)
		{
			return;
		}
		switch (base.State)
		{
		case NavigatorPathState.None:
		case NavigatorPathState.Recalculate:
			if (state == NavigatorPathState.Processing)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Processing:
			if (state == NavigatorPathState.Navigating)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Navigating:
			if (state == NavigatorPathState.Navigated || state == NavigatorPathState.Canceled)
			{
				break;
			}
			goto default;
		case NavigatorPathState.Navigated:
		case NavigatorPathState.Canceled:
		case NavigatorPathState.Interupted:
			if (state == NavigatorPathState.None)
			{
				break;
			}
			goto default;
		default:
			UnityEngine.Debug.LogException(new Exception($"'{base.Navigator}' its NavMeshPath with target '{base.Target}' is changing State from '{base.State}' to '{state}'. This is unexpected behaviour!"));
			break;
		}
		base.State = state;
	}

	public override void ClearNodes()
	{
		Nodes.Clear();
	}

	public override void PopulateLineRenderer(List<Vector3> linePath, Vector3 offset)
	{
		for (int i = 0; i < Nodes.Count; i++)
		{
			linePath.Add(Nodes[i] + offset);
		}
	}
}
public class WaterSurfaceNode : GridNode
{
	private static Grid _grid;

	public override GraphBase Graph => _grid;

	public WaterSurfaceNode(Grid grid, Vector2 rootPosition)
		: base(grid, rootPosition)
	{
		_grid = grid;
	}
}
public abstract class GridNode : PathfindingNode
{
	private const int CLEARANCE_PENALTY = 30;

	private Vector2 _boundsMin;

	private Vector2 _boundsMax;

	private ushort _obstacleCount;

	private byte _clearance = byte.MaxValue;

	public override bool IsGridNode => true;

	public override byte Level => 0;

	public byte Clearance => _clearance;

	public override Vector3 RootPosition => new Vector3(Center.x, Graph.Height, Center.y);

	public override Vector2 RootPosition2D => Center;

	public override Vector3 LeveledRootPosition => new Vector3(Center.x, 0f, Center.y);

	public Vector2 Center { get; private set; }

	public override float Diameter => 1f;

	public override int Penalty => 0;

	public GridNode(GraphBase graph, Vector2 rootPosition)
	{
		Center = rootPosition;
		Vector2 vector = graph.NodeSize / 2f;
		_boundsMin = Center - vector;
		_boundsMax = Center + vector;
		SetIsBlocked();
	}

	public static GridNode Get(Grid grid, Vector2 rootPosition)
	{
		if (grid.GraphType == global::Graph.Type.WaterSurface)
		{
			return new WaterSurfaceNode(grid, rootPosition);
		}
		throw new NotImplementedException();
	}

	public override void UpdateRootPosition()
	{
	}

	public override void PopulateNeighbors(List<PathfindingNode> neighbors)
	{
		base.PopulateNeighbors(neighbors);
		GameManager.GraphManager.WaterSurfaceGraph.PopulateNeighbors(this, neighbors);
	}

	public void AddNeighbor(PathfindingNode node)
	{
		if (Neighbors == null)
		{
			Neighbors = new List<PathfindingNode> { node };
		}
		else
		{
			Neighbors.Add(node);
		}
	}

	public override bool RemoveNeighbor(PathfindingNode node)
	{
		if (Neighbors == null)
		{
			return false;
		}
		return Neighbors.Remove(node);
	}

	public void IncreaseObstacleCount()
	{
		_obstacleCount++;
		SetIsBlocked();
	}

	public void DecreaseObstacleCount()
	{
		_obstacleCount--;
		SetIsBlocked();
	}

	public void ResetClearance()
	{
		_clearance = byte.MaxValue;
		PathfindingEvent.AddUpdatedPathfindingNode(this);
	}

	public void SetClearance(byte clearance)
	{
		if (clearance < _clearance)
		{
			_clearance = clearance;
		}
	}

	protected override void SetIsBlocked()
	{
		bool flag = 0 < _obstacleCount;
		if (flag != base.IsBlocked)
		{
			PathfindingEvent.AddUpdatedPathfindingNode(this);
		}
		base.IsBlocked = flag;
	}

	public override void UpdateNode(bool setNeighbors)
	{
		throw new NotImplementedException();
	}

	public override void SetPenalty(int penalty)
	{
		UnityEngine.Debug.LogException(new NotImplementedException());
	}

	public override void ClearPenalty()
	{
		UnityEngine.Debug.LogException(new NotImplementedException());
	}

	public bool ReturnIsPolygonOverlapping(Polygon polygon)
	{
		Vector2[] vertices = polygon.ReturnPolygon();
		if (ReturnAreProjectionsOverlapping(vertices, Vector2.up, _boundsMin.y, _boundsMax.y) && ReturnAreProjectionsOverlapping(vertices, Vector2.right, _boundsMin.x, _boundsMax.x))
		{
			return polygon.ReturnIsAxisAllignedRectangleOverlapping(_boundsMin, _boundsMax);
		}
		return false;
	}

	private bool ReturnAreProjectionsOverlapping(Vector2[] vertices, Vector2 axis, float min, float max)
	{
		Vector2 vector = vertices[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int num4 = vertices.Length;
		for (int i = 1; i < num4; i++)
		{
			vector = vertices[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}

	public override bool CanFitNavigator(INavigator navigator)
	{
		return navigator.RequiredClearance <= Clearance;
	}

	public override Transform GetAgentParent()
	{
		return GameManager.AgentManager.AgentParent;
	}

	public override int ReturnPenalty(INavigator navigator)
	{
		int num = 0;
		byte clearance = Clearance;
		byte preferredClearance = navigator.PreferredClearance;
		if (clearance == byte.MaxValue)
		{
			return 0;
		}
		if (clearance < preferredClearance)
		{
			byte requiredClearance = navigator.RequiredClearance;
			num = ((clearance >= requiredClearance) ? ((preferredClearance - clearance) * 30) : ((requiredClearance - clearance) * 100 * 30));
		}
		return base.ReturnPenalty(navigator) + num;
	}

	public bool TryReturnClosedNodeWithClearance(out GridNode nodeWithClearence, byte Clearance, float range)
	{
		Grid obj = (Grid)Graph;
		float num = float.MaxValue;
		nodeWithClearence = null;
		PathfindingNode[] array = obj.ReturnNeighborhood(RootPosition2D.x, RootPosition2D.y, 10);
		for (int i = 0; i < array.Length; i++)
		{
			GridNode gridNode = (GridNode)array[i];
			if (gridNode != null && gridNode.Clearance >= Clearance)
			{
				float num2 = gridNode.RootPosition2D.DistanceToSquared(RootPosition2D);
				if (num2 < num)
				{
					num = num2;
					nodeWithClearence = gridNode;
				}
			}
		}
		return nodeWithClearence != null;
	}

	public override PathfindingNodeData GetData()
	{
		return GridNodeData.Get(this);
	}

	public void DrawGizmo(bool wire = false)
	{
		DrawGizmo(Gizmos.color, wire);
	}

	public override void DrawGizmo(Color color, bool wire = false, float radius = 0.5f, Vector3 offset = default(Vector3))
	{
		Vector3 center = LeveledRootPosition + offset;
		Vector3 size = default(Vector3);
		size.x = _boundsMax.x - _boundsMin.x;
		size.y = size.x;
		size.z = _boundsMax.y - _boundsMin.y;
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		if (wire)
		{
			Gizmos.DrawWireCube(center, size);
		}
		else
		{
			Gizmos.DrawCube(center, size);
		}
		Gizmos.color = color2;
	}
}
public struct GridNodePolygon
{
	public static Vector2 NormalUp = Vector2.up;

	public static Vector2 NormalRight = Vector2.right;

	public Vector2 Center;

	private Vector2 _boundsMin;

	private Vector2 _boundsMax;

	private Vector2[] _vertices;

	public GridNodePolygon(Vector2 center, Vector2 size)
	{
		Center = center;
		Vector2 vector = size / 2f;
		_boundsMin = center - vector;
		_boundsMax = center + vector;
		_vertices = new Vector2[4]
		{
			new Vector2(_boundsMin.x, _boundsMax.y),
			_boundsMax,
			new Vector2(_boundsMax.x, _boundsMin.y),
			_boundsMin
		};
	}

	public bool ReturnIsPolygonOverlapping(Polygon polygon)
	{
		Vector2[] vertices = polygon.ReturnPolygon();
		if (ReturnAreProjectionsOverlapping(vertices, NormalUp, _boundsMin.y, _boundsMax.y) && ReturnAreProjectionsOverlapping(vertices, NormalRight, _boundsMin.x, _boundsMax.x))
		{
			return polygon.ReturnIsPolygonOverlapping(_vertices);
		}
		return false;
	}

	private bool ReturnAreProjectionsOverlapping(Vector2[] vertices, Vector2 axis, float min, float max)
	{
		Vector2 vector = vertices[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int num4 = vertices.Length;
		for (int i = 1; i < num4; i++)
		{
			vector = vertices[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}
}
public class HierarchicalNode : PathfindingNode
{
	public bool Leaf;

	public HierarchicalNode ParentNode;

	public List<HierarchicalNode> Children = new List<HierarchicalNode>();

	public HierarchicalNodeMarker Marker;

	public static int DeepestLevel;

	public Color GizmoColor;

	private byte _level;

	private bool _updateAllChildren;

	private List<HierarchicalNode> _allChildren;

	private bool _updateLeafChildren;

	private List<HierarchicalNode> _leafChildren;

	private Vector3 _rootPosition;

	private float _diameter;

	protected List<IPathfindingNodeDisposedListener> _subscribedDisposedListeners = new List<IPathfindingNodeDisposedListener>();

	private Transform _markerTransform;

	private int _childCount;

	private int _penalty;

	private NavMesh _navMesh;

	private string _markerPath;

	public override bool IsGridNode => false;

	public override byte Level => _level;

	public override Vector3 RootPosition => _rootPosition;

	public override Vector2 RootPosition2D => new Vector2(_rootPosition.x, _rootPosition.z);

	public override Vector3 LeveledRootPosition => new Vector3(_rootPosition.x, 0f, _rootPosition.z);

	public override float Diameter => _diameter;

	public float Range { get; private set; }

	public override int Penalty => _penalty;

	public override GraphBase Graph => _navMesh;

	public override bool IsOutOfBounds
	{
		get
		{
			if (Marker != null)
			{
				return Marker.IsOutOfBounds;
			}
			return false;
		}
	}

	public HierarchicalNode(HierarchicalNodeMarker marker, byte level, NavMesh navMesh, HierarchicalNode parent = null)
	{
		Marker = marker;
		Marker.SetNode(this);
		_markerTransform = Marker.transform;
		_markerPath = Marker.HierarchyPathToString();
		_rootPosition = Marker.transform.position;
		_level = level;
		_navMesh = navMesh;
		ParentNode = parent;
		Neighbors = new List<PathfindingNode>();
		_diameter = Marker.Diameter;
		Range = Marker.Range;
		GizmoColor = Color.HSVToRGB(UnityEngine.Random.Range(0f, 1f), 1f, 1f);
		if (Level > DeepestLevel)
		{
			DeepestLevel = Level;
		}
		AddNavMeshNeighbors(navMesh);
		AddGridNeighbors();
		navMesh.AddChild(this);
		AddChildrenFromMarker(Marker.GetComponentsInChildren<HierarchicalNodeMarker>(), navMesh);
		_allChildren = new List<HierarchicalNode>();
		_updateAllChildren = true;
		_leafChildren = new List<HierarchicalNode>();
		_updateLeafChildren = true;
	}

	public void SetDirty()
	{
		_updateAllChildren = true;
		_updateLeafChildren = true;
		int count = Children.Count;
		for (int i = 0; i < count; i++)
		{
			Children[i].SetDirty();
		}
	}

	public void Dispose()
	{
		int count = Children.Count;
		while (0 < count--)
		{
			Children[count].Dispose();
		}
		PathfindingEvent.AddUpdatedPathfindingNode(this);
		if (_subscribedDisposedListeners != null)
		{
			int count2 = _subscribedDisposedListeners.Count;
			while (0 < count2--)
			{
				_subscribedDisposedListeners[count2]?.OnPathfindingNodeDisposed(this);
			}
		}
		if (Neighbors != null)
		{
			foreach (PathfindingNode neighbor in Neighbors)
			{
				neighbor.RemoveNeighbor(this);
			}
		}
		_navMesh?.RemoveChild(this);
		_navMesh = null;
		ParentNode?.RemoveChild(this);
		ParentNode = null;
		if ((bool)Marker && Marker.gameObject.scene.isLoaded)
		{
			Navigator[] componentsInChildren = Marker.GetComponentsInChildren<Navigator>();
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				componentsInChildren[i].OnParentNodeDisposed();
			}
			Marker.SetNode(null);
			Marker = null;
		}
		Neighbors?.Clear();
		Neighbors = null;
		Children?.Clear();
		Children = null;
		_childCount = 0;
		_allChildren?.Clear();
		_allChildren = null;
		_leafChildren?.Clear();
		_leafChildren = null;
		_subscribedDisposedListeners?.Clear();
		_subscribedDisposedListeners = null;
	}

	public override void SetPenalty(int penalty)
	{
		_penalty = penalty;
		PathfindingEvent.AddUpdatedPathfindingNode(this);
	}

	public override void ClearPenalty()
	{
		_penalty = 0;
		PathfindingEvent.AddUpdatedPathfindingNode(this);
	}

	private void AddNavMeshNeighbors(NavMesh navMesh)
	{
		List<HierarchicalNode> list = navMesh.ReturnAllNodes();
		Vector3 leveledRootPosition = LeveledRootPosition;
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			HierarchicalNode hierarchicalNode = list[i];
			if (CanBeNavMeshNeighbor(hierarchicalNode, leveledRootPosition))
			{
				Neighbors.Add(hierarchicalNode);
				hierarchicalNode.Neighbors.Add(this);
			}
		}
	}

	private bool CanBeNavMeshNeighbor(HierarchicalNode node, Vector3 leveledRootPosition)
	{
		if (node == this)
		{
			return false;
		}
		if (leveledRootPosition.IsInRange(node.LeveledRootPosition, Mathf.Max(Range, node.Range)) && (Neighbors == null || !Neighbors.Contains(node)))
		{
			if (!(Graph is Grid))
			{
				return HasLineOfSightAt(node, Diameter);
			}
			return HasLineOfSightAt(node, 0f);
		}
		return false;
	}

	private void AddGridNeighbors()
	{
		if ((Graph.ValidNeighborTypes & global::Graph.Type.WaterSurface) == global::Graph.Type.WaterSurface)
		{
			AddGridNeighbors(GameManager.GraphManager.WaterSurfaceGraph);
		}
	}

	private void AddGridNeighbors(Grid grid)
	{
		if (grid == null)
		{
			PajamaLlama.Debugs.Debugger.Warning("No valid graph found to get neighbors from.");
		}
		else
		{
			if (!Graph.CanLinkWith(grid))
			{
				return;
			}
			List<GridNode> list = ListPool<GridNode>.Get();
			grid.PopulateNeighborhood(RootPosition.x, RootPosition.z, Mathf.FloorToInt(Range), list);
			foreach (GridNode item in list)
			{
				Neighbors.Add(item);
				item.AddNeighbor(this);
			}
			ListPool<GridNode>.Add(list);
		}
	}

	public override bool RemoveNeighbor(PathfindingNode node)
	{
		if (Neighbors == null)
		{
			return false;
		}
		return Neighbors.Remove(node);
	}

	private void ClearNeighbors()
	{
		if (Neighbors == null)
		{
			return;
		}
		foreach (PathfindingNode neighbor in Neighbors)
		{
			neighbor.RemoveNeighbor(this);
		}
		Neighbors.Clear();
	}

	public override void UpdateRootPosition()
	{
		_rootPosition = _markerTransform.position;
		for (int i = 0; i < _childCount; i++)
		{
			Children[i].UpdateRootPosition();
		}
	}

	public override void UpdateNode(bool setNeigbors = true)
	{
		Leaf = Children.Count == 0;
		SetIsBlocked();
	}

	protected override void SetIsBlocked()
	{
		base.IsBlocked = false;
		for (int i = 0; i < Obstacle.AllObstacles.Count; i++)
		{
			Obstacle obstacle = Obstacle.AllObstacles[i];
			if (obstacle.ObstacleGraphType == global::Graph.Type.Constructions && Vector3.Distance(RootPosition, obstacle.transform.position) < Diameter + obstacle.Radius)
			{
				base.IsBlocked = true;
				break;
			}
		}
	}

	public void AddChild(HierarchicalNodeMarker marker)
	{
		AddChild(new HierarchicalNode(marker, (byte)(Level + 1), Graph as NavMesh, this));
	}

	public void AddChild(HierarchicalNode node, bool resetNeighbors = true)
	{
		node.UpdateNode(setNeigbors: false);
		Children.Add(node);
		Leaf = false;
		HierarchicalNode root = (Graph as NavMesh).Root;
		root._updateAllChildren = true;
		root._updateLeafChildren = true;
		_childCount++;
	}

	public void AddChildrenFromMarker(HierarchicalNodeMarker[] childmarkers, NavMesh navMesh)
	{
		int num = childmarkers.Length;
		byte level = _level.Add(1);
		Transform transform = Marker.transform;
		for (int i = 0; i < num; i++)
		{
			HierarchicalNodeMarker hierarchicalNodeMarker = childmarkers[i];
			if (!(hierarchicalNodeMarker == Marker) && transform == hierarchicalNodeMarker.transform.parent)
			{
				AddChild(new HierarchicalNode(hierarchicalNodeMarker, level, navMesh, this), resetNeighbors: false);
			}
		}
	}

	public bool RemoveChild(HierarchicalNode node)
	{
		if (Children.IsNullOrEmpty())
		{
			return false;
		}
		if (Children.Remove(node))
		{
			node.Dispose();
			Leaf = Children.Count == 0;
			_updateAllChildren = true;
			_updateLeafChildren = true;
			_childCount--;
			return true;
		}
		foreach (HierarchicalNode child in Children)
		{
			if (child.RemoveChild(node))
			{
				_updateAllChildren = true;
				_updateLeafChildren = true;
				return true;
			}
		}
		return false;
	}

	public List<HierarchicalNode> ReturnAllChildren(bool onlyLeaves = false, int level = -1)
	{
		if (onlyLeaves)
		{
			if (_updateLeafChildren)
			{
				_leafChildren.Clear();
				if (Leaf)
				{
					_leafChildren.Add(this);
				}
				else
				{
					PopulateChildren(_leafChildren, this, addNonLeaves: false);
				}
				_updateLeafChildren = false;
			}
			return _leafChildren;
		}
		if (_updateAllChildren)
		{
			_allChildren.Clear();
			_allChildren.Add(this);
			PopulateChildren(_allChildren, this, addNonLeaves: true);
			_updateAllChildren = false;
		}
		return _allChildren;
	}

	private void PopulateChildren(List<HierarchicalNode> family, HierarchicalNode parent, bool addNonLeaves)
	{
		int count = parent.Children.Count;
		for (int i = 0; i < count; i++)
		{
			HierarchicalNode hierarchicalNode = parent.Children[i];
			if (hierarchicalNode.Leaf)
			{
				family.Add(hierarchicalNode);
				continue;
			}
			if (addNonLeaves)
			{
				family.Add(hierarchicalNode);
			}
			PopulateChildren(family, hierarchicalNode, addNonLeaves);
		}
	}

	public PathfindingNode ReturnNode(Target target, Navigator navigator, bool onlyUnblocked = true, bool leaf = true, int maximumDepth = 16, bool hasLineOfSight = true, bool onlyInRange = true)
	{
		if (!Graph.TypesMatch(target.TargetGraphType))
		{
			return null;
		}
		HierarchicalNode result = null;
		List<HierarchicalNode> list = ReturnAllChildren(leaf);
		list.Add(this);
		float num = 3f;
		Vector3 position = target.Position;
		float num2 = float.MaxValue;
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			HierarchicalNode hierarchicalNode = list[i];
			if (maximumDepth < hierarchicalNode.Level || !hierarchicalNode.CanFitNavigator(navigator) || (onlyUnblocked && hierarchicalNode.IsBlocked))
			{
				continue;
			}
			if (onlyInRange)
			{
				num = hierarchicalNode.Range + target.Radius;
				if (!hierarchicalNode.RootPosition.IsInRange(position, num))
				{
					continue;
				}
			}
			if ((!hasLineOfSight && !(navigator != null)) || hierarchicalNode.HasLineOfSightAt(position, navigator.Width))
			{
				float num3 = Vector3.Distance(position, hierarchicalNode.RootPosition);
				if (num3 < num2)
				{
					result = hierarchicalNode;
					num2 = num3;
				}
			}
		}
		return result;
	}

	public bool ReturnHasNodeInRange(Vector3 position, float range)
	{
		if (_rootPosition.IsInRange(position, Mathf.Min(Range, range) * 0.95f))
		{
			return true;
		}
		if (!Leaf)
		{
			int count = Children.Count;
			for (int i = 0; i < count; i++)
			{
				if (Children[i].ReturnHasNodeInRange(position, range))
				{
					return true;
				}
			}
		}
		return false;
	}

	public bool HasLineOfSightAt(Vector3 position, float width)
	{
		Vector3 direction = position - RootPosition;
		foreach (Obstacle allObstacle in Obstacle.AllObstacles)
		{
			if (allObstacle.ObstacleGraphType == global::Graph.Type.Constructions && allObstacle.ReturnIsLineIntersecting(RootPosition, direction, width))
			{
				return false;
			}
		}
		return true;
	}

	public bool HasLineOfSightAt(HierarchicalNode node, float width)
	{
		return HasLineOfSightAt(node.RootPosition, width);
	}

	public override bool CanFitNavigator(INavigator navigator)
	{
		return true;
	}

	public override Transform GetAgentParent()
	{
		if (Leaf && ParentNode != null && (bool)ParentNode.Marker)
		{
			Transform transform = ParentNode.Marker.transform;
			if (transform.parent != null)
			{
				return transform;
			}
		}
		if ((bool)Marker)
		{
			return Marker.transform;
		}
		UnityEngine.Debug.LogException(new Exception());
		return GameManager.AgentManager.AgentParent;
	}

	public HierarchicalNode ReturnClosestNode(Vector3 position)
	{
		if (Leaf)
		{
			return this;
		}
		if (ReturnClosestDescendant(position, out var closestDescendant, out var distanceToDescendant) && distanceToDescendant < position.DistanceToSquared(RootPosition))
		{
			return closestDescendant;
		}
		return this;
	}

	private bool ReturnClosestDescendant(Vector3 position, out HierarchicalNode closestDescendant, out float distanceToDescendant)
	{
		closestDescendant = null;
		distanceToDescendant = float.MaxValue;
		foreach (HierarchicalNode child in Children)
		{
			if (child != this)
			{
				float distanceToDescendant2 = position.DistanceToSquared(child.RootPosition);
				if (distanceToDescendant2 < distanceToDescendant)
				{
					closestDescendant = child;
					distanceToDescendant = distanceToDescendant2;
				}
				if (!child.Leaf && child.ReturnClosestDescendant(position, out var closestDescendant2, out distanceToDescendant2) && distanceToDescendant2 < distanceToDescendant)
				{
					closestDescendant = closestDescendant2;
					distanceToDescendant = distanceToDescendant2;
				}
			}
		}
		return closestDescendant != null;
	}

	public override PathfindingNodeData GetData()
	{
		return HierarchicalNodeData.Get(this);
	}

	public override void SubscribeDisposedListener(IPathfindingNodeDisposedListener disposedListener)
	{
		_subscribedDisposedListeners?.AddUnique(disposedListener);
	}

	public override void UnsubscribeDisposedListener(IPathfindingNodeDisposedListener disposedListener)
	{
		_subscribedDisposedListeners?.Remove(disposedListener);
	}

	public override void DrawGizmo(Color color, bool wire = false, float radius = 0.5f, Vector3 offset = default(Vector3))
	{
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		if (wire)
		{
			Gizmos.DrawWireSphere(RootPosition, radius);
		}
		else
		{
			Gizmos.DrawSphere(RootPosition, radius);
		}
		Gizmos.color = color2;
	}
}
public class HierarchicalNodeBaseMarker : HierarchicalNodeMarker
{
	private void Awake()
	{
	}

	private void Update()
	{
	}

	private void OnDrawGizmosSelected()
	{
	}

	[ContextMenu("Set neighbors")]
	public new void SetNeighbors()
