public abstract class PathfindingNode
{
	public List<PathfindingNode> Neighbors;

	public PathfindingFlags Flags;

	public abstract GraphBase Graph { get; }

	public abstract bool IsGridNode { get; }

	public abstract byte Level { get; }

	public bool IsBlocked { get; protected set; }

	public virtual bool IsOutOfBounds => false;

	public abstract int Penalty { get; }

	public abstract Vector3 RootPosition { get; }

	public abstract Vector3 LeveledRootPosition { get; }

	public abstract Vector2 RootPosition2D { get; }

	public abstract float Diameter { get; }

	protected virtual void SetIsBlocked()
	{
	}

	public abstract void SetPenalty(int penalty);

	public abstract void ClearPenalty();

	public abstract bool RemoveNeighbor(PathfindingNode node);

	public virtual void PopulateNeighbors(List<PathfindingNode> neighbors)
	{
		if (Neighbors != null)
		{
			neighbors.AddRange(Neighbors);
		}
	}

	public virtual void PopulateNeighbors(List<PathfindingNode> listToPopulate, Graph.Type acceptedGraphs)
	{
		int count = Neighbors.Count;
		for (int i = 0; i < count; i++)
		{
			PathfindingNode pathfindingNode = Neighbors[i];
			if ((pathfindingNode.Graph.GraphType & acceptedGraphs) != 0)
			{
				listToPopulate.Add(pathfindingNode);
			}
		}
	}

	public abstract void UpdateNode(bool setNeighbors = true);

	public abstract void UpdateRootPosition();

	public abstract bool CanFitNavigator(INavigator navigator);

	public abstract Transform GetAgentParent();

	public virtual int ReturnPenalty(INavigator navigator)
	{
		return Penalty;
	}

	public abstract PathfindingNodeData GetData();

	public virtual void SubscribeDisposedListener(IPathfindingNodeDisposedListener disposedListener)
	{
	}

	public virtual void UnsubscribeDisposedListener(IPathfindingNodeDisposedListener disposedListener)
	{
	}

	public abstract void DrawGizmo(Color color, bool wire = false, float radius = 0.5f, Vector3 offset = default(Vector3));
}
public class Pathfinder : SceneBehaviour
{
	public const int QUERY_SLOTS = 8;

	[SerializeField]
	[Range(1f, 4f)]
	[Tooltip("The number of threads reserved for agent pathfinding")]
	private int _pathThreads = 3;

	[SerializeField]
	[Tooltip("Should all pathfinding queries be stored or only the ones that failed?")]
	private bool _debugAllPathfindingQueries;

	[SerializeField]
	[Tooltip("Should all boat queries be stored or only the ones that failed?")]
	private bool _debugAllBoatQueries;

	[SerializeField]
	private DebugPathfinder _pathDebugger;

	public List<PathfindingQueryBase> QueriesToDebug;

	private static Pathfinder _instance;

	private PathfinderQuery _query;

	private PathfindingQueryBase[] _querySlots = new PathfindingQueryBase[8];

	private LinkedList<PathfindingQueryBase> _queryQueue = new LinkedList<PathfindingQueryBase>();

	private bool _showDebugDialog = true;

	public static bool HasInstance => _instance != null;

	public List<PathfinderPath> PathQueue { get; private set; } = new List<PathfinderPath>();

	protected override void Awake()
	{
		base.Awake();
		if (_instance == null)
		{
			_instance = this;
		}
		else if (_instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void OnDestroy()
	{
		_instance = null;
	}

	public static bool TryQueuePath(out PathfinderPath path, Navigator navigator, ITarget target)
	{
		if ((bool)_instance)
		{
			path = new PathfinderPath(navigator, target);
			path.SetState(NavigatorPathState.Queued);
			_instance.PathQueue.Add(path);
			return true;
		}
		path = null;
		return false;
	}

	public static bool QueuePath(PathfinderPath path)
	{
		if ((bool)_instance && (path.State == NavigatorPathState.None || path.State == NavigatorPathState.Recalculate))
		{
			_instance.PathQueue.Add(path);
			path.SetState(NavigatorPathState.Queued);
			return true;
		}
		UnityEngine.Debug.LogException(new NotSupportedException("Trying to queue a path that is not marked for (re)calculation."));
		return false;
	}

	public static bool DequeuePath(PathfinderPath path)
	{
		if ((bool)_instance && _instance.PathQueue.Remove(path))
		{
			return true;
		}
		return false;
	}

	public static bool QueueQuery(PathfindingQueryBase query)
	{
		if (_instance == null)
		{
			return false;
		}
		if (!_instance.TryExecuteQuery(query))
		{
			_instance._queryQueue.AddLast(query);
		}
		return true;
	}

	private bool TryExecuteQuery(PathfindingQueryBase query)
	{
		for (int i = _pathThreads; i < 8; i++)
		{
			PathfindingQueryBase pathfindingQueryBase = _querySlots[i];
			if (pathfindingQueryBase == null || pathfindingQueryBase.Completed)
			{
				if (query.Execute(i))
				{
					_querySlots[i] = query;
					return true;
				}
				return false;
			}
		}
		return false;
	}

	public static void ProcessQueue()
	{
		if ((bool)_instance)
		{
			_instance.Internal_ProcessQueue();
		}
	}

	private void Internal_ProcessQueue()
	{
		LinkedListNode<PathfindingQueryBase> linkedListNode = _queryQueue.First;
		while (linkedListNode != null)
		{
			LinkedListNode<PathfindingQueryBase> next = linkedListNode.Next;
			if (TryExecuteQuery(linkedListNode.Value))
			{
				_queryQueue.Remove(linkedListNode);
			}
			linkedListNode = next;
		}
		if ((!(_pathDebugger != null) || !_pathDebugger.IsDebugging) && TryReturnAvailableQueuedPathSlotIndex(out var i) && TryReturnQueuedPath(out var path))
		{
			PathfinderQuery pathfinderQuery = PathfinderQuery.Get();
			pathfinderQuery.Initialize(path);
			if (pathfinderQuery.Execute(i))
			{
				_querySlots[i] = pathfinderQuery;
				return;
			}
			UnityEngine.Debug.LogException(new Exception($"Unable to execute QueuedPath for '{path.Navigator}' haeding to '{path.Target}'"));
			RequeueQueuedPath(path);
			pathfinderQuery.Return();
		}
	}

	private bool TryReturnQueuedPath(out PathfinderPath path)
	{
		while (0 < PathQueue.Count)
		{
			path = PathQueue[0];
			PathQueue.RemoveAt(0);
			if (path != null)
			{
				path.ClearNodes();
				if (path.ValidateTarget())
				{
					return true;
				}
			}
		}
		path = null;
		return false;
	}

	private bool TryReturnAvailableQueuedPathSlotIndex(out int i)
	{
		for (i = 0; i < _pathThreads; i++)
		{
			PathfindingQueryBase pathfindingQueryBase = _querySlots[i];
			if (pathfindingQueryBase == null || pathfindingQueryBase.Completed)
			{
				return true;
			}
		}
		i = -1;
		return false;
	}

	private void RequeueQueuedPath(PathfinderPath path)
	{
		PathQueue.Insert(0, path);
	}

	public void LogWarning(string message)
	{
	}

	public void LogError(string message)
	{
	}

	public static bool AddQueryToDebug(PathfindingQueryBase pathfindingQuery)
	{
		return false;
	}

	private string GetNoPathFoundMessage(PathfindingQueryBase pathfindingQuery)
	{
		if (pathfindingQuery is PathfinderQuery pathfinderQuery)
		{
			return $"Pathfinder was unable to find a path to '{pathfinderQuery.Target}' for '{pathfinderQuery.PathfinderPath.Navigator}'";
		}
		return "Pathfinder was unable to find a path.";
	}

	public void RemoveQueryToDebug(int index)
	{
		if (index < QueriesToDebug.Count)
		{
			QueriesToDebug[index].Return();
			QueriesToDebug.RemoveAt(index);
		}
	}

	public void DebugPathfindingQuery(int index)
	{
		if (index < QueriesToDebug.Count)
		{
			ReturnDebugPathfinder().DebugQuery(QueriesToDebug[index]);
		}
	}

	public DebugPathfinder ReturnDebugPathfinder()
	{
		if (_pathDebugger == null)
		{
			_pathDebugger = new GameObject().AddComponent<DebugPathfinder>();
			_pathDebugger.name = "Path Debugger";
			_pathDebugger.transform.SetParent(base.transform.parent);
		}
		return _pathDebugger;
	}
}
public static class PathfindingHelper
{
	public static float ReturnUnityNavMeshPathDistance(Target from, Target to)
	{
		NavMeshPath navMeshPath = new NavMeshPath();
		if (!UnityEngine.AI.NavMesh.CalculatePath(from.Position, to.Position, -1, navMeshPath) && UnityEngine.AI.NavMesh.SamplePosition(to.Position, out var hit, 3f, -1))
		{
			UnityEngine.AI.NavMesh.CalculatePath(from.Position, hit.position, -1, navMeshPath);
		}
		Vector3[] corners = navMeshPath.corners;
		float num = 0f;
		for (int i = 1; i < corners.Length; i++)
		{
			num += Vector3.Distance(corners[i], corners[i - 1]);
		}
		return num;
	}
}
public class PolygonBehaviour : MonoBehaviour
{
	[SerializeField]
	private Polygon _polygon;

	[SerializeField]
	private GridBehaviour _grid;

	[SerializeField]
	private PolygonBehaviour _overlapPolygon;

	private Rect _lastBounds;

	private List<GridNode> _blockedNodes;

	private IEnumerator Start()
	{
		_polygon.Initialize(base.transform);
		_blockedNodes = new List<GridNode>();
		yield return null;
		UpdateBlockedNodes();
	}

	private void Update()
	{
		_polygon.Update();
	}

	private void UpdateBlockedNodes()
	{
		int count = _blockedNodes.Count;
		for (int i = 0; i < count; i++)
		{
			_blockedNodes[i].DecreaseObstacleCount();
		}
		_grid.Grid.UpdateBlockedNodes(_polygon, _polygon.Bounds, _blockedNodes);
	}

	private void OnDrawGizmos()
	{
		_polygon.DrawGizmos();
		if (!Application.isPlaying || _overlapPolygon == null)
		{
			return;
		}
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get();
		if (_polygon.PopulateOverlap(_overlapPolygon._polygon, list))
		{
			Polygon2DBase.SortVertices(list);
			Gizmos.color = Color.black;
			for (int i = 0; i < list.Count; i++)
			{
				Gizmos.DrawSphere(list[i].Vector3TopDown(), 0.01f);
			}
		}
	}
}
public class GridNodeData : PathfindingNodeData
{
	private const int G_COST_STRAIGHT_COST = 10;

	private const int G_COST_DIAGONAL_COST = 14;

	private const int H_COST_STRAIGHT_COST = 10;

	private const int H_COST_DIAGONAL_COST = 14;

	private const int CLEARANCE_PENALTY = 30;

	private GridNode _node;

	private Vector3 _rootPosition;

	private Vector2 _rootPosition2D;

	private int _referenceCount;

	private static PajamaLlama.ObjectPool<GridNodeData> _instancePool;

	public override PathfindingNode Node => _node;

	public override Vector3 RootPosition => _rootPosition;

	public override Vector2 RootPosition2D => _rootPosition2D;

	public override bool IsGridNode => true;

	private GridNodeData()
	{
	}

	private void SetNode(GridNode node)
	{
		_node = node;
		_rootPosition = _node.RootPosition;
		_rootPosition2D = _node.RootPosition2D;
	}

	public override void Clear(PathfindingFlags openFlag, PathfindingFlags closedFlag)
	{
		base.Clear(openFlag, closedFlag);
		_node = null;
	}

	public override bool CanFitNavigator(INavigator navigator)
	{
		return navigator.RequiredClearance <= _node.Clearance;
	}

	public override bool ReturnIgnoreClearane(INavigator navigator)
	{
		return _node.Clearance < navigator.RequiredClearance;
	}

	public override int ReturnClearancePenalty(INavigator navigator)
	{
		byte clearance = _node.Clearance;
		byte requiredClearance = navigator.RequiredClearance;
		if (clearance < requiredClearance)
		{
			return (requiredClearance - clearance) * 100 * 30;
		}
		return 0;
	}

	public override float ReturnGCost(PathfindingNodeData antecede, INavigator navigator)
	{
		int num2;
		float num;
		if (antecede.IsGridNode)
		{
			Vector2 rootPosition2D = antecede.RootPosition2D;
			num = ((rootPosition2D.x != _rootPosition2D.x && rootPosition2D.y != _rootPosition2D.y) ? 14f : 10f);
			num2 = 0;
		}
		else
		{
			num = (int)antecede.RootPosition.DistanceToSquared(new Vector3(_rootPosition2D.x, 0f, _rootPosition2D.y));
			num2 = navigator.TransitionCost;
		}
		num += (float)_node.Penalty;
		num += (float)ReturnClearancePenalty(navigator);
		num *= navigator.ReturnTerrainPenalty(_node.Graph.TerrainType);
		num += (float)num2;
		return antecede.GCost + num;
	}

	public override float ReturnHCost(PathfindingNode target, INavigator navigator)
	{
		float num = navigator.ReturnTerrainPenalty(_node.Graph.TerrainType);
		float num2 = System.Math.Abs(_rootPosition2D.x - target.RootPosition2D.x);
		float num3 = System.Math.Abs(_rootPosition2D.y - target.RootPosition2D.y);
		if (num2 < num3)
		{
			return (int)((num3 - num2) * num * 10f + num2 * num * 14f);
		}
		return (int)((num2 - num3) * num * 10f + num3 * num * 14f);
	}

	public static GridNodeData Get(GridNode node)
	{
		if (_instancePool == null)
		{
			_instancePool = new PajamaLlama.ObjectPool<GridNodeData>(Instantiate);
		}
		GridNodeData gridNodeData = _instancePool.Get();
		gridNodeData.SetNode(node);
		gridNodeData._referenceCount++;
		return gridNodeData;
	}

	private static GridNodeData Instantiate()
	{
		return new GridNodeData();
	}

	protected override void Return()
	{
		if (_referenceCount > 0)
		{
			_instancePool.Return(this);
			_referenceCount = 0;
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception("Return() was invoked on GridNodeData which is already pooled"));
		}
	}
}
public class HierarchicalNodeData : PathfindingNodeData
{
	private HierarchicalNode _node;

	private static PajamaLlama.ObjectPool<HierarchicalNodeData> _instancePool;

	public override PathfindingNode Node => _node;

	public override bool IsGridNode => false;

	public override Vector3 RootPosition => _node.RootPosition;

	public override Vector2 RootPosition2D => _node.RootPosition2D;

	private HierarchicalNodeData()
