}
public class MooringPointBlockedQuery : PathfindingQueryBase, INavigator
{
	private Data _data;

	private List<PathfindingNode> _neighbors;

	private static PajamaLlama.ObjectPool<MooringPointBlockedQuery> _instancePool;

	private static PajamaLlama.ObjectPool<Data> _dataPool;

	private float _constructionRadiusSquared;

	public MooringPoint MooringPoint { get; private set; }

	public bool IsBlocked { get; private set; }

	public byte RequiredClearance { get; private set; }

	public byte PreferredClearance { get; private set; }

	public int TransitionCost { get; private set; }

	private MooringPointBlockedQuery()
	{
	}

	~MooringPointBlockedQuery()
	{
		if (_dataPool != null)
		{
			_dataPool.Return(_data);
		}
	}

	private void Initialize(MooringPoint mooringPoint, byte minimumRequiredClearance = 3)
	{
		MooringPoint = mooringPoint;
		base.IsExecuting = true;
		IsBlocked = true;
		if ((bool)mooringPoint.LinkedBoat)
		{
			RequiredClearance = mooringPoint.LinkedBoat.Navigator.RequiredClearance;
			PreferredClearance = mooringPoint.LinkedBoat.Navigator.PreferredClearance;
			TransitionCost = mooringPoint.LinkedBoat.Navigator.TransitionCost;
		}
		else
		{
			byte requiredClearance = (PreferredClearance = minimumRequiredClearance);
			RequiredClearance = requiredClearance;
			TransitionCost = 1000;
		}
		_constructionRadiusSquared = Mathf.Pow(GameManager.Settings.GameplaySettings.ConstructionRadius, 2f);
	}

	public override bool Execute(int index, bool async = true)
	{
		PathfindingNode pathfindingNode = (((bool)MooringPoint && (bool)MooringPoint.MooringTarget) ? MooringPoint.MooringTarget.ReturnNode(Graph.Type.WaterSurface) : null);
		if (pathfindingNode == null)
		{
			base.IsExecuting = false;
			base.Completed = true;
			return true;
		}
		if (_dataPool == null)
		{
			_dataPool = new PajamaLlama.ObjectPool<Data>(CreateDataInstance, 4);
		}
		if (_dataPool.TryGet(out _data))
		{
			_nodes = _data.Nodes;
			_nodes.Clear();
			_openNodes = _data.OpenNodes;
			_openNodes.Clear();
			AddOpenNode(pathfindingNode.GetData());
			_neighbors = _data.Neighbors;
			return base.Execute(index, async);
		}
		return false;
	}

	protected override void Execute()
	{
		if (_openNodes.Count == 0)
		{
			LogErrorFormat("Blocked mooring point because it is out of bounds!");
			return;
		}
		while (ProcessNextNode())
		{
		}
		base.PathFound = !IsBlocked;
	}

	public override bool ProcessNextNode()
	{
		if (_openNodes.Count == 0)
		{
			return false;
		}
		PathfindingNodeData pathfindingNodeData = _openNodes.RemoveFirst();
		pathfindingNodeData.SetClosed(base.OpenFlag, base.ClosedFlag);
		if (pathfindingNodeData.Node.CanFitNavigator(this) && _constructionRadiusSquared < pathfindingNodeData.RootPosition.sqrMagnitude)
		{
			IsBlocked = false;
			return false;
		}
		_neighbors.Clear();
		pathfindingNodeData.PopulateNeighbors(_neighbors);
		foreach (PathfindingNode neighbor in _neighbors)
		{
			if (neighbor.Graph.GraphType != Graph.Type.WaterSurface || (neighbor.Flags & base.ClosedFlag) == base.ClosedFlag || neighbor.IsBlocked || !neighbor.CanFitNavigator(this))
			{
				continue;
			}
			if (TryReturnOpenNodeData(neighbor, out var openNode))
			{
				float num = openNode.ReturnGCost(pathfindingNodeData, this);
				if (num < openNode.GCost)
				{
					openNode.SetGCost(num);
					openNode.Parent = pathfindingNodeData;
					_openNodes.UpdateItem(openNode);
				}
			}
			else
			{
				openNode = neighbor.GetData();
				float num = openNode.ReturnGCost(pathfindingNodeData, this);
				float hCost = _constructionRadiusSquared - openNode.RootPosition.sqrMagnitude;
				openNode.SetFCost(num, hCost);
				openNode.SetOpen(base.OpenFlag);
				openNode.Parent = pathfindingNodeData;
				AddOpenNode(openNode);
			}
		}
		return true;
	}

	protected override void Clear()
	{
		_openNodes = null;
		if (_nodes != null)
		{
			ClearNodes(_nodes.Values);
			_nodes = null;
		}
		if (_data != null)
		{
			_dataPool.Return(_data);
			_data = null;
		}
	}

	public float ReturnTerrainPenalty(Navigator.TerrainType terrain)
	{
		if (terrain == Navigator.TerrainType.WaterSurface)
		{
			return 1f;
		}
		return 10000f;
	}

	private bool TryReturnOpenNodeData(PathfindingNode node, out PathfindingNodeData openNode)
	{
		openNode = null;
		if ((node.Flags & base.OpenFlag) != base.OpenFlag)
		{
			return false;
		}
		int count = _openNodes.Count;
		for (int i = 0; i < count; i++)
		{
			openNode = _openNodes.Items[i];
			if (openNode.Node == node)
			{
				return true;
			}
		}
		return false;
	}

	public override void OnDrawGizmos()
	{
		base.OnDrawGizmos();
	}

	public static MooringPointBlockedQuery Get(MooringPoint mooringPoint, byte minimumRequiredClearance = 3)
	{
		if (_instancePool == null)
		{
			_instancePool = new PajamaLlama.ObjectPool<MooringPointBlockedQuery>(CreateInstance);
		}
		MooringPointBlockedQuery mooringPointBlockedQuery = _instancePool.Get();
		mooringPointBlockedQuery.Initialize(mooringPoint, minimumRequiredClearance);
		return mooringPointBlockedQuery;
	}

	protected override void ReturnToPool()
	{
		Clear();
		_instancePool?.Return(this);
	}

	private static MooringPointBlockedQuery CreateInstance()
	{
		return new MooringPointBlockedQuery();
	}

	private static Data CreateDataInstance()
	{
		int num = (int)Mathf.Pow(GameManager.Settings.GameplaySettings.ConstructionRadius, 2f);
		return new Data
		{
			Nodes = new Dictionary<PathfindingNode, PathfindingNodeData>(num),
			OpenNodes = new Heap<PathfindingNodeData>(num),
			Neighbors = new List<PathfindingNode>(128)
		};
	}
}
public abstract class PathQuery : PathfindingQueryBase
{
	private Data _data;

	public abstract PathfindingNode StartNode { get; }

	public PathfindingNodeData StartNodeData { get; private set; }

	public abstract PathfindingNode TargetNode { get; }

	public PathfindingNodeData TargetNodeData { get; protected set; }

	public List<PathfindingNode> Path { get; protected set; }

	protected List<PathfindingNode> Neighbors { get; private set; }

	public UnityEvent<PathQuery> CompletedEvent { get; private set; } = new UnityEvent<PathQuery>();

	~PathQuery()
	{
		Clear();
	}

	public override bool Execute(int index, bool async = true)
	{
		if (Data.TryGet(out _data, this))
		{
			_nodes = _data.Nodes;
			_nodes.Clear();
			_openNodes = _data.OpenNodes;
			_openNodes.Clear();
			Neighbors = _data.Neighbors;
			StartNodeData = StartNode.GetData();
			AddOpenNode(StartNodeData);
			return base.Execute(index, async);
		}
		return false;
	}

	protected override void Execute()
	{
		while (ProcessNextNode())
		{
		}
	}

	protected override void Clear()
	{
		TargetNodeData = null;
		_openNodes = null;
		if (_nodes != null)
		{
			ClearNodes(_nodes.Values);
			_nodes = null;
		}
		if (_data != null)
		{
			_data.Return();
			_data = null;
		}
	}

	public bool CanExecute()
	{
		return Data.CanGet();
	}

	private List<PathfindingNode> ReturnRetracedPath(PathfindingNodeData startNode, PathfindingNodeData targetNode)
	{
		List<PathfindingNode> list = new List<PathfindingNode>();
		for (PathfindingNodeData pathfindingNodeData = targetNode; pathfindingNodeData != startNode; pathfindingNodeData = pathfindingNodeData.Parent)
		{
			list.Add(pathfindingNodeData.Node);
		}
		list.Add(startNode.Node);
		list.Reverse();
		return list;
	}

	public override void OnDrawGizmos()
	{
		StartNode?.DrawGizmo(Color.green);
		TargetNode?.DrawGizmo(Color.red);
	}
}
public class PathfinderQuery : PathQuery
{
	private static PajamaLlama.ObjectPool<PathfinderQuery> _instancePool = new PajamaLlama.ObjectPool<PathfinderQuery>(CreateInstance);

	private PathfindingNode _startNode;

	private PathfindingNode _targetNode;

	private List<PathfindingNode> _endNodes;

	private PathfindingNodeData _closestNodeData;

	private int _closestNodeItterations;

	private int _closestNodeItterationMax;

	private bool _ignoreClearance;

	public PathfinderPath PathfinderPath { get; private set; }

	public Navigator Navigator => PathfinderPath.Navigator;

	public ITarget Target => PathfinderPath.Target;

	public override PathfindingNode StartNode => _startNode;

	public override PathfindingNode TargetNode => _targetNode;

	public static PathfinderQuery Get()
	{
		return _instancePool.Get();
	}

	private static PathfinderQuery CreateInstance()
	{
		return new PathfinderQuery();
	}

	protected override void ReturnToPool()
	{
		Clear();
		_instancePool?.Return(this);
	}

	public void Initialize(PathfinderPath pathfinderPath)
	{
		PathfinderPath = pathfinderPath;
	}

	public override bool Execute(int index, bool async = true)
	{
		if (index < 0)
		{
			Clear();
		}
		else
		{
			_startNode = PathfinderPath.Navigator.ReturnPathfindingNode(null);
			_targetNode = Target.ReturnPathfindingNode(Navigator);
			if (_startNode == null || _targetNode == null)
			{
				if (_startNode == null)
				{
					UnityEngine.Debug.LogException(new NotSupportedException($"[Pathfinder] No valid starting node found for {Navigator}."), Navigator);
				}
				if (_targetNode == null)
				{
					UnityEngine.Debug.LogError(new NotSupportedException($"[Pathfinder] No valid target node found for {Target}."), Target.gameObject);
				}
				base.IsExecuting = false;
				base.Completed = true;
				return true;
			}
			if (CanNavigateByLineOfSight(Navigator, Target, _startNode, _targetNode))
			{
				PathfinderPath.SetState(NavigatorPathState.Processed);
				base.Completed = true;
				return true;
			}
		}
		if (!TryReturnEndNodes(Navigator, Target, _targetNode, out _endNodes))
		{
			LogWarning($"No target nodes found for target '{Target.name}' that fit navigator '{Navigator.name}, this needs to be fixed!. Generating partial path as fallback.");
		}
		if (base.Execute(index, async))
		{
			PathfinderPath.SetState(NavigatorPathState.Processing);
			_closestNodeData = base.StartNodeData;
			_closestNodeItterations = 0;
			_closestNodeItterationMax = Mathf.CeilToInt(Mathf.Pow(GameManager.Settings.GameplaySettings.ConstructionRadius * 2, 2f));
			return true;
		}
		return false;
	}

	public override bool ProcessNextNode()
	{
		if (_openNodes.Count == 0 || _closestNodeItterationMax <= _closestNodeItterations)
		{
			return false;
		}
		PathfindingNodeData pathfindingNodeData = _openNodes.RemoveFirst();
		pathfindingNodeData.SetClosed(base.OpenFlag, base.ClosedFlag);
		if (_endNodes.Contains(pathfindingNodeData.Node))
		{
			base.TargetNodeData = pathfindingNodeData;
			base.PathFound = true;
			return false;
		}
		base.Neighbors.Clear();
		pathfindingNodeData.PopulateNeighbors(base.Neighbors);
		int count = base.Neighbors.Count;
		_ignoreClearance = _ignoreClearance && pathfindingNodeData.ReturnIgnoreClearane(Navigator);
		for (int i = 0; i < count; i++)
		{
			ReturnAddNeighborToOpenNodes(pathfindingNodeData, base.Neighbors[i], _openNodes, Navigator, base.StartNodeData.Node, TargetNode, _ignoreClearance);
		}
		if (pathfindingNodeData.HCost < _closestNodeData.HCost || _closestNodeData == base.StartNodeData)
		{
			_closestNodeData = pathfindingNodeData;
			_closestNodeItterations = 0;
		}
		else
		{
			_closestNodeItterations++;
		}
		return true;
	}

	public override void UnityCompletedCallback()
	{
		if (base.TargetNodeData == null)
		{
			UnityEngine.Debug.LogException(new Exception($"<color=red><b>Incomplete path found...</b></color>\nNavigator: {Navigator} -> Target: {Target}\r\n" + $"Closed node count: {_nodes.Count}\r\n" + $"Open node count: {_openNodes.Count}"));
			if (PathfinderPath.Navigator.AllowIncompletePath)
			{
				PathfinderPath.SetNodes(ReturnRetracedPath(base.StartNodeData, _closestNodeData), incompletePath: true);
			}
			else
			{
				PathfinderPath.NoPathFound = true;
			}
		}
		else
		{
			List<PathfindingNode> list = ReturnRetracedPath(base.StartNodeData, base.TargetNodeData);
			if (list.IsNullOrEmpty())
			{
				UnityEngine.Debug.LogException(new Exception($"<color=red><b>Looping path found...</b></color>\nNavigator: {Navigator} -> Target: {Target}"));
				PathfinderPath.NoPathFound = true;
			}
			else
			{
				PathfinderPath.SetNodes(list);
			}
		}
		PathfinderPath.SetState(NavigatorPathState.Processed);
		if (!Pathfinder.AddQueryToDebug(this))
		{
			base.UnityCompletedCallback();
			Return();
		}
	}

	protected override void Clear()
	{
		_endNodes?.Dispose();
		_endNodes = null;
		base.Clear();
	}

	private bool TryReturnEndNodes(Navigator navigator, ITarget target, PathfindingNode targetNode, out List<PathfindingNode> endNodes)
	{
		if (targetNode == null)
		{
			LogError($"Target node is null for target '{target.name}' and navigator '{navigator.name}'.");
			endNodes = null;
			return false;
		}
		if (navigator == null)
		{
			LogError("Navigator is null.");
			endNodes = null;
			return false;
		}
		endNodes = ListPool<PathfindingNode>.Get();
		if (targetNode.CanFitNavigator(navigator))
		{
			endNodes.Add(targetNode);
		}
		if (targetNode.IsGridNode)
		{
			Grid obj = (targetNode.Graph as Grid) ?? throw new NotSupportedException("Grid == null! Could it be the GraphManager has not yet been initialized");
			Vector2 vector = target.ReturnPosition().Vector2TopDown();
			PathfindingNode[] array = obj.ReturnNeighborhood(vector.x, vector.y, Mathf.CeilToInt(target.Range));
			int num = array.Length;
			for (int i = 0; i < num; i++)
			{
				PathfindingNode pathfindingNode = array[i];
				if (pathfindingNode != null && pathfindingNode != targetNode && array[i].CanFitNavigator(navigator))
				{
					endNodes.Add(pathfindingNode);
				}
			}
		}
		if (0 < endNodes.Count)
		{
			if (!endNodes.Contains(targetNode))
			{
				LogWarning($"Target node for target '{target.name}' does not fit navigator '{navigator.name}', this should be fixed! However a node in the targets range does fit the navigator.");
			}
			return true;
		}
		return false;
	}

	public bool ReturnAddNeighborToOpenNodes(PathfindingNodeData currentNode, PathfindingNode neighbor, Heap<PathfindingNodeData> openNodes, Navigator navigator, PathfindingNode startNode, PathfindingNode targetNode, bool ignoreClearance, bool displayDebugs = false)
	{
		if (!neighbor.IsBlocked && neighbor.Graph.TypesMatch(navigator.TargetGraphType) && (ignoreClearance || neighbor.CanFitNavigator(navigator)))
		{
			PathfindingNodeData pathfindingNodeData = GetPathfindingNodeData(neighbor);
			float num = pathfindingNodeData.ReturnGCost(currentNode, navigator);
			if (num < pathfindingNodeData.GCost)
			{
				pathfindingNodeData.Parent = currentNode;
				pathfindingNodeData.SetGCost(num);
				if (pathfindingNodeData.IsFlagSet(base.OpenFlag))
				{
					openNodes.UpdateItem(pathfindingNodeData);
				}
			}
			if (pathfindingNodeData.IsFlagSet(base.OpenFlag | base.ClosedFlag))
			{
				return false;
			}
			pathfindingNodeData.Parent = currentNode;
			pathfindingNodeData.SetFCost(num, pathfindingNodeData.ReturnHCost(targetNode, navigator));
			AddOpenNode(pathfindingNodeData);
			pathfindingNodeData.SetOpen(base.OpenFlag);
			return true;
		}
		return false;
	}

	private List<PathfindingNode> ReturnRetracedPath(PathfindingNodeData startNode, PathfindingNodeData targetNode)
	{
		List<PathfindingNode> list = new List<PathfindingNode>();
		PathfindingNodeData pathfindingNodeData = targetNode;
		while (pathfindingNodeData != startNode)
		{
			if (list.AddUnique(pathfindingNodeData.Node))
			{
				pathfindingNodeData = pathfindingNodeData.Parent;
				continue;
			}
			return null;
		}
		list.Add(startNode.Node);
		list.Reverse();
		return list;
	}

	private bool CanNavigateByLineOfSight(Navigator navigator, ITarget target, PathfindingNode startNode, PathfindingNode targetNode)
	{
		if (startNode is GridNode && startNode.Graph == targetNode.Graph && navigator.IsOnGraph(startNode.Graph))
		{
			return HasLineOfSightAt(navigator, startNode.RootPosition, targetNode.RootPosition, target, 2.1474836E+09f);
		}
		return false;
	}

	private bool HasLineOfSightAt(Navigator navigator, Vector3 originPosition, Vector3 targetPosition, ITarget target, float range)
	{
		if (Vector3.Distance(originPosition, targetPosition) > range)
		{
			return false;
		}
		Vector3 direction = targetPosition - originPosition;
		for (int i = 0; i < Obstacle.AllObstacles.Count; i++)
		{
			Obstacle obstacle = Obstacle.AllObstacles[i];
			if (obstacle != target && (target == null || Graph.TypesMatch(target.GraphType, obstacle.ObstacleGraphType)) && obstacle.ReturnIsLineIntersecting(originPosition, direction, navigator.Width))
			{
				UnityEngine.Debug.Log($"{navigator} its line of sight was blocked by obstacle {obstacle.name}.");
				return false;
			}
		}
		return true;
	}

	private PathfindingNodeData GetPathfindingNodeData(PathfindingNode pathfindingNode)
	{
		if ((pathfindingNode.Flags & (base.OpenFlag | base.ClosedFlag)) != PathfindingFlags.None && _nodes.TryGetValue(pathfindingNode, out var value))
		{
			return value;
		}
		return pathfindingNode.GetData();
	}

	public override void DebugGCost(PathfindingNodeData pathfindingNodeData)
	{
		pathfindingNodeData.ReturnGCost(pathfindingNodeData.Parent, Navigator);
	}

	public void LogWarning(string message)
	{
	}

	public void LogError(string message)
	{
	}
}
public abstract class PathfindingNodeData : IHeapItem<PathfindingNodeData>
{
	public abstract PathfindingNode Node { get; }

	public PathfindingNodeData Parent { get; set; }

	public PathfindingFlags Flags => Node.Flags;

	public abstract Vector3 RootPosition { get; }

	public abstract Vector2 RootPosition2D { get; }

	public abstract bool IsGridNode { get; }

	public float GCost { get; protected set; }

	public float HCost { get; protected set; }

	public float FCost { get; protected set; }

	public void SetOpen(PathfindingFlags openFlag)
	{
		Node.Flags |= openFlag;
	}

	public void SetClosed(PathfindingFlags openFlag, PathfindingFlags closedFlag)
	{
		Node.Flags &= ~openFlag;
		Node.Flags |= closedFlag;
	}

	public abstract bool CanFitNavigator(INavigator navigator);

	public abstract bool ReturnIgnoreClearane(INavigator navigator);

	public abstract int ReturnClearancePenalty(INavigator navigator);

	public void SetGCost(float gCost)
	{
		GCost = gCost;
		FCost = gCost + HCost;
	}

	public abstract float ReturnGCost(PathfindingNodeData antecede, INavigator navigator);

	public abstract float ReturnHCost(PathfindingNode target, INavigator navigator);

	public void SetFCost(float gCost, float hCost)
	{
		GCost = gCost;
		HCost = hCost;
		FCost = gCost + hCost;
	}

	public void PopulateNeighbors(List<PathfindingNode> neighbors)
	{
		Node.PopulateNeighbors(neighbors);
	}

	public virtual void Clear(PathfindingFlags openFlag, PathfindingFlags closedFlag)
	{
		if (Node != null)
		{
			Node.Flags &= ~openFlag;
			Node.Flags &= ~closedFlag;
		}
		HeapIndex = 0;
		Parent = null;
		GCost = 0f;
		HCost = 0f;
		FCost = 0f;
		Return();
	}

	public override int CompareTo(PathfindingNodeData node)
	{
		if (FCost == node.FCost)
		{
			return (int)(node.HCost - HCost);
		}
		return (int)(node.FCost - FCost);
	}

	protected abstract void Return();

	public bool IsFlagSet(PathfindingFlags flags)
	{
		return (Node.Flags & flags) != 0;
	}
}
public abstract class PathfindingQueryBase : ThreadPoolManager.ITask
{
	protected class Data
	{
		public PathfindingQueryBase Owner;

		public Dictionary<PathfindingNode, PathfindingNodeData> Nodes;

		public Heap<PathfindingNodeData> OpenNodes;

		public List<PathfindingNode> Neighbors;

		private static PajamaLlama.ObjectPool<Data> Pool = new PajamaLlama.ObjectPool<Data>(CreateInstance, 8);

		public static bool CanGet()
		{
			return Pool.CanGet();
		}

		public static bool TryGet(out Data instance, PathfindingQueryBase owner)
		{
			if (Pool.TryGet(out instance))
			{
				instance.Owner = owner;
				return true;
			}
			UnityEngine.Debug.LogException(new Exception($"Unable to get Data object for '{owner}'"));
			instance = null;
			return false;
		}

		public void Return()
		{
			Owner = null;
			Pool.Return(this);
		}

		private static Data CreateInstance()
		{
			Mathf.Pow(GameManager.Settings.GameplaySettings.ConstructionRadius, 2f);
			return new Data
			{
				Nodes = new Dictionary<PathfindingNode, PathfindingNodeData>(GameManager.GraphManager.ClosedNodeListSize),
				OpenNodes = new Heap<PathfindingNodeData>(GameManager.GraphManager.OpenNodeHeapSize),
				Neighbors = new List<PathfindingNode>(128)
			};
		}
	}

	protected Dictionary<PathfindingNode, PathfindingNodeData> _nodes;

	protected Heap<PathfindingNodeData> _openNodes;

	private bool _taskCompleted;

	private Exception _exception;

	private bool _queuedForDebug;

	public int Index { get; private set; }

	public bool IsExecuting { get; protected set; }

	bool ThreadPoolManager.ITask.Completed => _taskCompleted;

	public bool Completed { get; protected set; }

	public bool PathFound { get; protected set; }

	public Dictionary<PathfindingNode, PathfindingNodeData> Nodes => _nodes;

	public Heap<PathfindingNodeData> OpenNodes => _openNodes;

	public List<string> Errors { get; private set; }

	public PathfindingFlags OpenFlag { get; private set; }

	public PathfindingFlags ClosedFlag { get; private set; }

	public virtual bool Execute(int index, bool async = true)
	{
		SetIndex(index);
		IsExecuting = true;
		Completed = false;
		PathFound = false;
		if (Errors != null)
		{
			Errors.Clear();
		}
		if (async)
		{
			_taskCompleted = false;
			ThreadPoolManager.QueueTask(this);
		}
		else if (index > 0)
		{
			ThreadPoolWaitCallback(null);
			UnityCompletedCallback();
		}
		return true;
	}

	protected abstract void Execute();

	public abstract bool ProcessNextNode();

	protected void AddOpenNode(PathfindingNodeData data)
	{
		if (_nodes.TryAdd(data.Node, data))
		{
			_openNodes.Add(data);
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception("Unable to add open node!"));
		}
	}

	protected abstract void Clear();

	protected void ClearNode(PathfindingNodeData node)
	{
		node?.Clear(OpenFlag, ClosedFlag);
	}

	protected void ClearNodes(IEnumerable<PathfindingNodeData> nodes)
	{
		int num = 0;
		foreach (PathfindingNodeData node in nodes)
		{
			ClearNode(node);
			num++;
		}
	}

	protected void LogErrorFormat(string format, params object[] args)
	{
		if (Errors == null)
		{
			Errors = new List<string>();
		}
		Errors.Add(string.Format(format, args));
	}

	public void ThreadPoolWaitCallback(object state)
	{
		try
		{
			Execute();
		}
		catch (Exception exception)
		{
			_exception = exception;
		}
		finally
		{
			_taskCompleted = true;
		}
	}

	public virtual void UnityCompletedCallback()
	{
		IsExecuting = false;
		Completed = true;
		if (_exception != null)
		{
			UnityEngine.Debug.LogException(_exception);
		}
		Clear();
	}

	private void SetIndex(int index)
	{
		if (index < 0)
		{
			Index = index;
			OpenFlag = PathfindingFlags.DebugQuery_Open;
			ClosedFlag = PathfindingFlags.DebugQuery_Closed;
			return;
		}
		if (index < 8)
		{
			int num = 1 << index + index;
			int closedFlag = num << 1;
			Index = index;
			OpenFlag = (PathfindingFlags)num;
			ClosedFlag = (PathfindingFlags)closedFlag;
			return;
		}
		throw new NotSupportedException("Currently only 8 concurrent pathfinding queries are supported.");
	}

	public virtual void OnDrawGizmos()
	{
	}

	public void DrawOpenNodes()
	{
		for (int i = 0; i < _openNodes.Count; i++)
		{
			_ = Color.cyan;
			PathfindingNode node = _openNodes.Items[i].Node;
			switch (node.Graph.GraphType)
			{
			case Graph.Type.Constructions:
				node.DrawGizmo(Color.yellow);
				break;
			case Graph.Type.WaterSurface:
				node.DrawGizmo(Color.blue);
				break;
			}
		}
	}

	public void DrawClosedNodes()
	{
		foreach (PathfindingNodeData value in _nodes.Values)
		{
			if (value.IsFlagSet(ClosedFlag))
			{
				value.Node.DrawGizmo(Color.black);
			}
		}
	}

	public void DrawPath()
	{
		if (_openNodes != null && !((IReadOnlyCollection<PathfindingNodeData>)(object)_openNodes.Items).IsNullOrEmpty())
		{
			PathfindingNodeData pathfindingNodeData = _openNodes.Items[0];
			Gizmos.color = Color.white;
			while (pathfindingNodeData.Parent != null)
			{
				pathfindingNodeData = pathfindingNodeData.Parent;
				Gizmos.DrawSphere(pathfindingNodeData.RootPosition + Vector3.up, 0.1f);
			}
		}
	}

	public virtual void DebugGCost(PathfindingNodeData pathfindingNodeData)
	{
	}

	public void Return()
	{
		_queuedForDebug = false;
		ReturnToPool();
	}

	protected abstract void ReturnToPool();
}
public class TownQuery : PathfindingQueryBase
{
	private PathfindingNode _startNode;

	private PathfindingNodeData _startNodeData;

	private PathfindingNode _targetNode;

	private PathfindingNodeData _targetNodeData;

	private Data _data;

	private List<PathfindingNode> _neighbors;

	private static PajamaLlama.ObjectPool<TownQuery> _instancePool;

	public IPathfindingNodeProvider From { get; private set; }

	public IPathfindingNodeProvider To { get; private set; }

	public List<PathfindingNode> Path { get; private set; }

	public UnityEvent<TownQuery> CompletedEvent { get; private set; }

	private TownQuery()
	{
		CompletedEvent = new UnityEvent<TownQuery>();
	}

	~TownQuery()
	{
		_data?.Return();
	}

	private void Initialize(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
	{
		From = from;
		To = to;
		Path = null;
		base.IsExecuting = true;
	}

	public override bool Execute(int index, bool async = true)
	{
		try
		{
			_startNode = From.ReturnPathfindingNode();
			_targetNode = To.ReturnPathfindingNode();
		}
		catch (Exception exception)
		{
			UnityEngine.Debug.LogException(exception);
			_startNode = null;
			_targetNode = null;
		}
		if (_startNode == null || _targetNode == null)
		{
			base.IsExecuting = false;
			base.Completed = true;
			return true;
		}
		if (Data.TryGet(out _data, this))
		{
			_nodes = _data.Nodes;
			_nodes.Clear();
			_openNodes = _data.OpenNodes;
			_openNodes.Clear();
			_neighbors = _data.Neighbors;
			_startNodeData = _startNode.GetData();
			AddOpenNode(_startNodeData);
			return base.Execute(index, async);
		}
		return false;
	}

	protected override void Execute()
	{
		while (ProcessNextNode())
		{
		}
		if (_targetNodeData != null)
		{
			Path = ReturnRetracedPath(_startNodeData, _targetNodeData);
		}
		else
		{
			UnityEngine.Debug.LogWarning("TownQuery: No path found!");
		}
	}

	public override bool ProcessNextNode()
	{
		if (_openNodes.Count == 0)
		{
			return false;
		}
		PathfindingNodeData pathfindingNodeData = _openNodes.RemoveFirst();
		pathfindingNodeData.SetClosed(base.OpenFlag, base.ClosedFlag);
		if (pathfindingNodeData.Node == _targetNode)
		{
			_targetNodeData = pathfindingNodeData;
			base.PathFound = true;
			return false;
		}
		_neighbors.Clear();
		pathfindingNodeData.PopulateNeighbors(_neighbors);
		foreach (PathfindingNode neighbor in _neighbors)
		{
			if (neighbor.Graph.GraphType != Graph.Type.Constructions || (neighbor.Flags & base.ClosedFlag) != PathfindingFlags.None || neighbor.IsBlocked)
			{
				continue;
			}
			if (TryReturnNodeData(neighbor, out var nodeData))
			{
				float num = ReturnGCost(nodeData, pathfindingNodeData);
				if (num < nodeData.GCost)
				{
					nodeData.SetGCost(num);
					nodeData.Parent = pathfindingNodeData;
					if (nodeData.IsFlagSet(base.OpenFlag))
					{
						_openNodes.UpdateItem(nodeData);
					}
				}
			}
			else
			{
				nodeData = neighbor.GetData();
				float num = ReturnGCost(nodeData, pathfindingNodeData);
				float hCost = Vector3.Distance(nodeData.RootPosition, _targetNode.RootPosition);
				nodeData.SetFCost(num, hCost);
				nodeData.SetOpen(base.OpenFlag);
				nodeData.Parent = pathfindingNodeData;
				AddOpenNode(nodeData);
			}
		}
		return true;
	}

	public override void UnityCompletedCallback()
	{
		if (_targetNodeData != null)
		{
			Path = ReturnRetracedPath(_startNodeData, _targetNodeData);
			_targetNodeData = null;
		}
		base.UnityCompletedCallback();
		CompletedEvent.Invoke(this);
		CompletedEvent.RemoveAllListeners();
		Return();
	}

	protected override void Clear()
	{
		_targetNodeData = null;
		_openNodes = null;
		if (_nodes != null)
		{
			ClearNodes(_nodes.Values);
			_nodes = null;
		}
		if (_data != null)
		{
			_data.Return();
			_data = null;
		}
	}

	private bool TryReturnNodeData(PathfindingNode node, out PathfindingNodeData nodeData)
	{
		nodeData = null;
		if ((node.Flags & (base.OpenFlag | base.ClosedFlag)) != PathfindingFlags.None)
		{
			return _nodes.TryGetValue(node, out nodeData);
		}
		return false;
	}

	private float ReturnGCost(PathfindingNodeData node, PathfindingNodeData antecede)
	{
		return antecede.GCost + Vector3.Distance(node.RootPosition, antecede.RootPosition);
	}

	private List<PathfindingNode> ReturnRetracedPath(PathfindingNodeData startNode, PathfindingNodeData targetNode)
	{
		List<PathfindingNode> list = new List<PathfindingNode>();
		for (PathfindingNodeData pathfindingNodeData = targetNode; pathfindingNodeData != startNode; pathfindingNodeData = pathfindingNodeData.Parent)
		{
			list.Add(pathfindingNodeData.Node);
		}
		list.Add(startNode.Node);
		list.Reverse();
		return list;
	}

	public static TownQuery Get(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
	{
		if (_instancePool == null)
		{
			_instancePool = new PajamaLlama.ObjectPool<TownQuery>(CreateInstance);
		}
		TownQuery townQuery = _instancePool.Get();
		townQuery.Initialize(from, to);
		return townQuery;
	}

	protected override void ReturnToPool()
	{
		Clear();
		_instancePool?.Return(this);
	}

	private static TownQuery CreateInstance()
	{
		return new TownQuery();
	}
}
public class TownQueryCache : MonoBehaviour
{
	public class Path : IPathfindingNodeDisposedListener
	{
		private float _leveledDistanceSquared;

		public IPathfindingNodeProvider From { get; private set; }

		public IPathfindingNodeProvider To { get; private set; }

		public TownQuery Query { get; private set; }

		public ListPool<PathfindingNode>.List Nodes { get; private set; }

		public Path(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
		{
			From = from;
			To = to;
			_leveledDistanceSquared = From.transform.position.DistanceToLeveledSquared(To.transform.position);
			TryQueueQuery();
		}

		public void OnPathfindingNodeDisposed(PathfindingNode disposedNode)
		{
			if (Nodes == null)
			{
				UnityEngine.Debug.LogException(new Exception("TownQueryCache.Path.Nodes == NULL"));
			}
			else
			{
				ClearNodes();
			}
		}

		public void Dispose()
		{
			Query?.CompletedEvent.RemoveListener(OnQueryCompleted);
			ClearNodes();
		}

		private bool TryQueueQuery()
		{
			if (IsDead() || Query != null)
			{
				return false;
			}
			Query = TownQuery.Get(From, To);
			Query.CompletedEvent.AddListener(OnQueryCompleted);
			Pathfinder.QueueQuery(Query);
			return true;
		}

		private void OnQueryCompleted(TownQuery query)
		{
			query.CompletedEvent.RemoveListener(OnQueryCompleted);
			if (Query == query)
			{
				if (query.PathFound)
				{
					Nodes = ListPool<PathfindingNode>.Get(query.Path);
					foreach (PathfindingNode node in Nodes)
					{
						node.SubscribeDisposedListener(this);
					}
				}
				Query = null;
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception("TownQueryCache.Path.OnQueryCompleted queries do not match!"));
			}
		}

		private void ClearNodes()
		{
			if (Nodes == null)
			{
				return;
			}
			foreach (PathfindingNode node in Nodes)
			{
				if (node == null)
				{
					UnityEngine.Debug.LogException(new Exception("TownQueryCache.Path is subscribed to PathfindingNode == NULL"));
				}
				else
				{
					node.UnsubscribeDisposedListener(this);
				}
			}
			Nodes.Dispose();
			Nodes = null;
		}

		public bool IsMatch(IPathfindingNodeProvider fromToMatch, IPathfindingNodeProvider toToMatch)
		{
			if (fromToMatch != From || toToMatch != To)
			{
				if (fromToMatch == To)
				{
					return toToMatch == From;
				}
				return false;
			}
			return true;
		}

		public bool IsDead()
		{
			if (From != null)
			{
				return To == null;
			}
			return true;
		}

		public float ReturnDistance()
		{
			if (Nodes.IsNullOrEmpty())
			{
				TryQueueQuery();
				return _leveledDistanceSquared;
			}
			return Nodes.Count;
		}
	}

	private static TownQueryCache _instance;

	private Dictionary<IPathfindingNodeProvider, List<Path>> _paths = new Dictionary<IPathfindingNodeProvider, List<Path>>();

	private void Awake()
	{
		if (_instance == null)
		{
			_instance = this;
		}
	}

	private void OnDestroy()
	{
		if (_instance == this)
		{
			_instance = null;
		}
		Dictionary<IPathfindingNodeProvider, List<Path>>.Enumerator enumerator = _paths.GetEnumerator();
		while (enumerator.MoveNext())
		{
			foreach (Path item in enumerator.Current.Value)
			{
				item.Dispose();
			}
		}
		_paths.Clear();
	}

	private Path AddPath(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
	{
		Path path = new Path(from, to);
		if (_paths.TryGetValue(from, out var value))
		{
			value.Add(path);
		}
		else
		{
			_paths.Add(from, new List<Path> { path });
		}
		if (_paths.TryGetValue(to, out value))
		{
			value.Add(path);
		}
		else
		{
			_paths.Add(to, new List<Path> { path });
		}
		return path;
	}

	public static Path ReturnPath(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
	{
		if (_instance == null)
		{
			return null;
		}
		return _instance.i_ReturnPath(from, to);
	}

	public static T ReturnClosestDestination<T>(IPathfindingNodeProvider from, List<T> destinations) where T : IPathfindingNodeProvider
	{
		float num = float.MaxValue;
		T result = default(T);
		foreach (T destination in destinations)
		{
			float num2 = ReturnPath(from, destination).ReturnDistance();
			if (num2 < num)
			{
				num = num2;
				result = destination;
			}
		}
		return result;
	}

	private Path i_ReturnPath(IPathfindingNodeProvider from, IPathfindingNodeProvider to)
	{
		if (!_paths.TryGetValue(from, out var value) || !TryReturnCachedPath(value, from, to, out var path))
		{
			return AddPath(from, to);
		}
		return path;
	}

	private bool TryReturnCachedPath(List<Path> cachedPaths, IPathfindingNodeProvider from, IPathfindingNodeProvider to, out Path path)
	{
		int count = cachedPaths.Count;
		while (0 < count--)
		{
			Path path2 = cachedPaths[count];
			if (path2.IsDead())
			{
				cachedPaths.RemoveAt(count);
			}
			else if (path2.IsMatch(from, to))
			{
				path = path2;
				return true;
			}
		}
		path = null;
		return false;
	}
}
[Serializable]
public abstract class GraphBase
{
	[Tooltip("Graph type that this graph handles.")]
	[EnumFlag(0)]
	public Graph.Type GraphType;

	[Tooltip("Graph types that the nodes of this graph can link with.")]
	[EnumFlag(0)]
	public Graph.Type ValidNeighborTypes;

	[Space]
	[Tooltip("This graph is a standard grid node.")]
	public bool IsGridNode = true;

	[Tooltip("Maximum depth for the grid node.")]
	[ConditionalHide("IsGridNode", true)]
	public int MaximumDepth = 6;

	[Tooltip("Height of this graph in the world.")]
	public float Height;

	[Tooltip("Rules for navigating this graph.")]
	public NavigationMethod NavigationMethod;

	[Header("Debugging")]
	[Tooltip("Displays grid gizmos for the graph when enabled.")]
	public bool DisplayGraph;

	[Tooltip("The colors to give to the debug gizmos for this graph.")]
	public UnityEngine.Gradient GizmoColors;

	[Tooltip("Show all the nodes at once of this graph.")]
	public bool ShowAllNodes = true;

	[Tooltip("Level of gizmos to show for this graph.")]
	[Range(0f, 1f)]
	public float DisplayLevel = 1f;

	protected bool _isDirty;

	public int MaximumSize { get; protected set; }

	public Navigator.TerrainType TerrainType { get; protected set; } = Navigator.TerrainType.Construction;

	public Vector2 NodeSize => Vector2.one;

	public abstract void Initialize();

	public abstract PathfindingNode ReturnNode(Target target, Navigator navigator, int deepestLevel, bool onlyUnblocked = true, bool hasLineOfSight = true);

	public abstract PathfindingNode ReturnNode(Vector3 position);

	public bool CanLinkWith(GraphBase graph)
	{
		return (ValidNeighborTypes & GraphType) != 0;
	}

	public static bool TypesMatch(Graph.Type firstGraphType, Graph.Type secondGraphType)
	{
		return (firstGraphType & secondGraphType) != 0;
	}

	public bool TypesMatch(Graph.Type graphType)
	{
		return (GraphType & graphType) != 0;
	}

	private bool TypesMatchCompletely(Graph.Type firstGraphType, Graph.Type secondGraphType)
	{
		if (firstGraphType != 0)
		{
			return firstGraphType == secondGraphType;
		}
		return false;
	}

	public abstract void Draw();
}
