		int num2 = Mathf.RoundToInt(rootPosition2D.y + _offset.z);
		int num3 = num - 1;
		int num4 = num + 1;
		int num5 = num2 - 1;
		int num6 = num2 + 1;
		bool num7 = 0 < num;
		bool flag = num < _maxIndex;
		bool flag2 = 0 < num2;
		bool flag3 = num2 < _maxIndex;
		if (num7)
		{
			if (flag2)
