			}
		}
		if (flag2)
		{
			neighbors.Add(_grid[num, num5]);
		}
		if (node.Graph != this)
		{
			neighbors.Add(_grid[num, num2]);
		}
		if (flag3)
		{
			neighbors.Add(_grid[num, num6]);
		}
		if (flag)
