		int num2 = Mathf.RoundToInt(y + _offset.z);
		int num3 = num - range;
		int num4 = num2 - range;
		int num5 = num + range + 1;
		int num6 = num2 + range + 1;
		int num7 = 3 + (range - 1) * 2;
		int num8 = num7 * num7;
		if (neighborhood.Capacity < num8)
		{
			neighborhood.Capacity = num8;
		}
		for (int i = num4; i < num6; i++)
		{
			for (int j = num3; j < num5; j++)
			{
				if (ReturnNode(j, i) != null)
				{
					neighborhood.Add(ReturnNode(j, i));
				}
			}
		}
	}

	public override PathfindingNode ReturnNode(Target target, Navigator navigator = null, int deepestLevel = 0, bool onlyUnblocked = true, bool hasLineOfSight = true)
	{
		if (TypesMatch(target.TargetGraphType))
		{
			Vector3 position = target.transform.position;
			return ReturnNode(position.x, position.z, onlyUnblocked);
		}
		return null;
	}

	public override PathfindingNode ReturnNode(Vector3 position)
	{
		return ReturnNode(position.x, position.z);
	}

	public GridNode ReturnNode(Vector2 point)
	{
		return ReturnNode(point.x, point.y);
	}

	private GridNode ReturnNode(float posX, float posY, bool onlyUnblocked = false)
	{
		int num = Mathf.RoundToInt(posX + _offset.x);
		int num2 = Mathf.RoundToInt(posY + _offset.z);
		if (-1 >= num || num >= _size || -1 >= num2 || num2 >= _size)
		{
			return null;
		}
		GridNode gridNode = _grid[num, num2];
		if (onlyUnblocked && gridNode != null && gridNode.IsBlocked)
		{
			return ReturnClosestUnblockedNode(num, num2);
		}
		return gridNode;
	}

	private GridNode ReturnClosestUnblockedNode(int indexX, int indexY)
	{
		int num = ((0 <= indexX) ? indexX : 0);
		int num2 = ((0 <= indexY) ? (indexY - 1) : 0);
		int num3 = ((indexX + 1 >= _size) ? (_size - 1) : (indexX + 1));
		int num4 = ((indexY + 1 >= _size) ? (_size - 1) : (indexY + 1));
		int num5 = 0;
		while (num > -1 && num3 < _size && num2 > -1 && num4 < _size)
		{
			for (num5 = num2 + 1; num5 <= num4 && num5 < _size; num5++)
			{
				if (num < 0)
				{
					break;
				}
				if (!_grid[num, num5].IsBlocked)
				{
					return _grid[num, num5];
				}
			}
			num--;
			for (num5 = num + 2; num5 <= num3 && num5 < _size; num5++)
			{
				if (num4 >= _size)
				{
					break;
				}
				if (!_grid[num5, num4].IsBlocked)
				{
					return _grid[num5, num4];
				}
			}
			num4++;
			num5 = num4 - 2;
			while (num5 >= num2 && num5 >= 0 && num3 < _size)
			{
				if (!_grid[num3, num5].IsBlocked)
				{
					return _grid[num3, num5];
				}
				num5--;
			}
			num3++;
			num5 = num3 - 2;
			while (num5 > num && num5 >= 0 && num2 >= 0)
			{
				if (!_grid[num5, num2].IsBlocked)
				{
					return _grid[num5, num2];
				}
				num5--;
			}
			num2--;
		}
		return null;
	}

	private GridNode ReturnNode(int indexX, int indexY)
	{
		if (-1 < indexX && indexX < _size && -1 < indexY && indexY < _size)
		{
			return _grid[indexX, indexY];
		}
		return null;
	}

	public PathfindingNode[] ReturnNeighborhood(float x, float y, int range)
	{
		int num = Mathf.RoundToInt(x + _offset.x);
		int num2 = Mathf.RoundToInt(y + _offset.z);
		int num3 = num - range;
		int num4 = num2 - range;
		int num5 = num + range + 1;
		int num6 = num2 + range + 1;
		int num7 = 0;
		int num8 = 3 + (range - 1) * 2;
		if (ReturnNode(num, num2) == null)
		{
			return null;
		}
		PathfindingNode[] array = new PathfindingNode[num8 * num8];
		for (int i = num4; i < num6; i++)
		{
			for (int j = num3; j < num5; j++)
			{
				array[num7++] = ReturnNode(j, i);
			}
		}
		return array;
	}

	private int ReturnSafeIndex(int index)
	{
		return Mathf.Min(_maxIndex, Mathf.Max(0, index));
	}

	public override void Draw()
	{
		for (int i = 0; i < _size; i++)
		{
			for (int j = 0; j < _size; j++)
			{
				GridNode gridNode = _grid[j, i];
				if (_displayBlockedNodes && gridNode.IsBlocked)
				{
					Gizmos.color = Color.red;
					gridNode.DrawGizmo();
				}
				if (_displayClearance && gridNode.Clearance < byte.MaxValue)
				{
					Gizmos.color = new Color(0f, (float)(int)gridNode.Clearance * 0.125f, 0.25f);
					gridNode.DrawGizmo();
				}
				if (!_displayBlockedNodes && !_displayClearance)
				{
					Gizmos.color = Color.magenta;
					gridNode.DrawGizmo();
				}
			}
		}
	}
}
[Serializable]
public class NavMesh : GraphBase
{
	private List<HierarchicalNode> _children;

	private HierarchicalNode _root;

	public HierarchicalNode Root => _root;

	public override void Initialize()
	{
		HierarchicalNodeBaseMarker hierarchicalNodeBaseMarker = UnityEngine.Object.FindAnyObjectByType<HierarchicalNodeBaseMarker>();
		if (!(hierarchicalNodeBaseMarker == null))
		{
			_children = new List<HierarchicalNode>();
			_root = new HierarchicalNode(hierarchicalNodeBaseMarker, 0, this);
			_root.UpdateNode(setNeigbors: false);
			base.TerrainType = Navigator.ReturnTerrainTypeFromGraphType(Graph.Type.Constructions);
		}
	}

	public void Dispose()
	{
		_root?.Dispose();
	}

	public void UpdateRootPosition()
	{
		_root.UpdateRootPosition();
	}

	public void AddNode(HierarchicalNodeMarker nodeMarker)
	{
		_root.AddChild(nodeMarker);
	}

	public bool RemoveNode(HierarchicalNode node)
	{
		return _root.RemoveChild(node);
	}

	public void AddChild(HierarchicalNode child)
	{
		if (!_children.AddUnique(child))
		{
			UnityEngine.Debug.LogError("Trying to add a child to the NavMesh which is already in the _children list!");
		}
	}

	public void RemoveChild(HierarchicalNode child)
	{
		if (!_children.Remove(child))
		{
			UnityEngine.Debug.LogError("Trying to remove a child of the NavMEsh that is not in the _children list!");
		}
	}

	public override PathfindingNode ReturnNode(Target target, Navigator navigator, int deepestLevel, bool onlyUnblocked = true, bool hasLineOfSight = true)
	{
		if (target.PrimaryMarker == null)
		{
			if (_root != null)
			{
				return _root.ReturnNode(target, navigator, onlyUnblocked, leaf: false, deepestLevel, hasLineOfSight);
			}
			return null;
		}
		return target.PrimaryMarker.Node;
	}

	public override PathfindingNode ReturnNode(Vector3 position)
	{
		return null;
	}

	public List<HierarchicalNode> ReturnAllNodes()
	{
		return _children;
	}

	public bool ReturnHasNodeInRange(MarkerProxy marker)
	{
		return _root.ReturnHasNodeInRange(marker.Position, marker.Range);
	}

	public PathfindingNode ReturnClosestNode(Vector3 position)
	{
		return _root.ReturnClosestNode(position);
	}

	public override void Draw()
	{
		if (_root == null)
		{
			return;
		}
		DrawNode(_root, onlyNeighborsOnSameGraph: true);
		List<HierarchicalNode> list = _root.ReturnAllChildren();
		if (ShowAllNodes)
		{
			for (int i = 0; i < list.Count; i++)
			{
				DrawNode(list[i], onlyNeighborsOnSameGraph: true);
			}
			return;
		}
		int num = Mathf.RoundToInt(DisplayLevel * 2f);
		for (int j = 0; j < list.Count; j++)
		{
			PathfindingNode pathfindingNode = list[j];
			if (pathfindingNode.Level == num)
			{
				DrawNode(pathfindingNode as HierarchicalNode, onlyNeighborsOnSameGraph: true);
			}
		}
	}

	private void DrawNode(HierarchicalNode node, bool onlyNeighborsOnSameGraph = false)
	{
		if (node == null)
		{
			return;
		}
		if (node.ParentNode != null)
		{
			Gizmos.color = Color.cyan * 0.5f;
			Gizmos.DrawLine(node.RootPosition, node.ParentNode.RootPosition);
		}
		float num = ((float)(int)node.Level + 1f) / ((float)HierarchicalNode.DeepestLevel + 1f);
		if (node.Leaf)
		{
			num = 1f;
			Gizmos.color = node.GizmoColor;
			if (node.IsBlocked)
			{
				Gizmos.DrawSphere(node.RootPosition, node.Diameter * 0.5f * num);
			}
			Gizmos.color = node.GizmoColor;
			Gizmos.DrawWireSphere(node.RootPosition, node.Diameter * 0.5f * num);
		}
		else
		{
			Gizmos.color = node.GizmoColor * 0.5f;
			Gizmos.DrawSphere(node.RootPosition, node.Diameter * 0.5f * num);
			Gizmos.DrawWireSphere(node.RootPosition, node.Diameter * 0.5f * num);
			if (node.Level > 0)
			{
				Vector3 vector = Vector3.one * 999f;
				Vector3 vector2 = Vector3.zero;
				for (int i = 0; i < node.Children.Count; i++)
				{
					Vector3 rootPosition = node.Children[i].RootPosition;
					if (rootPosition.x < vector.x)
					{
						vector = vector.SetX(rootPosition.x);
					}
					if (rootPosition.x > vector2.x)
					{
						vector2 = vector2.SetX(rootPosition.x);
					}
					if (rootPosition.y < vector.y)
					{
						vector = vector.SetY(rootPosition.y);
					}
					if (rootPosition.y > vector2.y)
					{
						vector2 = vector2.SetY(rootPosition.y);
					}
					if (rootPosition.z < vector.z)
					{
						vector = vector.SetZ(rootPosition.z);
					}
					if (rootPosition.z > vector2.z)
					{
						vector2 = vector2.SetZ(rootPosition.z);
					}
				}
				Vector3 vector3 = vector2 - vector;
				Vector3 center = (vector2 + vector) / 2f;
				vector3 = new Vector3(vector3.x + node.Diameter, vector3.x + node.Diameter, vector3.z + node.Diameter);
				Gizmos.DrawWireCube(center, vector3);
			}
		}
		Gizmos.color = new Color(255f, 69f, 0f) * 0.5f;
		if (node.Neighbors == null)
		{
			return;
		}
		foreach (PathfindingNode neighbor in node.Neighbors)
		{
			if (!onlyNeighborsOnSameGraph || neighbor.Graph == node.Graph)
			{
				Gizmos.DrawLine(node.RootPosition, neighbor.RootPosition);
			}
		}
	}
}
public class NavMeshPathDebugger : MonoBehaviour
{
	[SerializeField]
	private float _markerRadius = 0.5f;

	private void OnDrawGizmos()
	{
		using ListPool<HierarchicalNodeMarker>.List list = ListPool<HierarchicalNodeMarker>.Get(GetComponentsInChildren<HierarchicalNodeMarker>());
		using ListPool<HierarchicalNodeMarker>.List list2 = ListPool<HierarchicalNodeMarker>.Get();
		foreach (HierarchicalNodeMarker item in list)
		{
			if (item.DoDebug)
			{
				list2.Add(item);
			}
			else
			{
				DrawNeighbors(item, list, Color.black);
			}
		}
		foreach (HierarchicalNodeMarker item2 in list2)
		{
			DrawNeighbors(item2, list, Color.green);
		}
	}

	private void DrawNeighbors(HierarchicalNodeMarker marker, List<HierarchicalNodeMarker> markers, Color color)
	{
		Vector3 position = marker.transform.position;
		float range = marker.Range;
		Gizmos.color = Color.red;
		foreach (HierarchicalNodeMarker marker2 in markers)
		{
			if (!(marker == marker2))
			{
				Vector3 position2 = marker2.transform.position;
				if (position.IsInRange(position2, range))
				{
					Gizmos.color = color;
					Gizmos.DrawLine(position, position2);
				}
			}
		}
		Gizmos.DrawWireSphere(position, _markerRadius);
	}

	private void AddMarkerNeighborsToPath(HierarchicalNodeMarker marker, List<HierarchicalNodeMarker> markers, List<HierarchicalNodeMarker> path)
	{
		using ListPool<HierarchicalNodeMarker>.List list = ListPool<HierarchicalNodeMarker>.Get();
		Vector3 position = marker.transform.position;
		float range = marker.Range;
		for (int i = 0; i < markers.Count; i++)
		{
			HierarchicalNodeMarker hierarchicalNodeMarker = markers[i];
			if (position.IsInRange(hierarchicalNodeMarker.transform.position, range))
			{
				markers.RemoveAt(i--);
				path.Add(hierarchicalNodeMarker);
				list.Add(hierarchicalNodeMarker);
			}
		}
		foreach (HierarchicalNodeMarker item in list)
		{
			AddMarkerNeighborsToPath(item, markers, path);
			Gizmos.DrawLine(marker.transform.position, item.transform.position);
		}
	}
}
