public class PathfindingPolygon : Polygon
{
	private Obstacle _obstacle;

	private Rect _lastBounds;

	private Dictionary<Graph.Type, List<GridNode>> _blockedNodesPerGrid = new Dictionary<Graph.Type, List<GridNode>>();

	private int _clearanceDistance;

	private GridNode _clearanceCenter;

	private Rect _clearanceRect;

	private Grid _watersurfaceGraph;

	private static List<PathfindingPolygon> _allPathfindingPolygons = new List<PathfindingPolygon>();

	public PathfindingPolygon(Obstacle obstacle, Polygon prefabPolygon)
	{
		_allPathfindingPolygons.Add(this);
		_obstacle = obstacle;
		_watersurfaceGraph = GameManager.GraphManager.WaterSurfaceGraph;
		Initialize(obstacle.transform, prefabPolygon);
	}

	public PathfindingPolygon(Obstacle obstacle, Vector2Polygon prefabPolygon)
	{
		Transform transform = obstacle.transform;
		_allPathfindingPolygons.Add(this);
		_obstacle = obstacle;
		_watersurfaceGraph = GameManager.GraphManager.WaterSurfaceGraph;
		Initialize(transform);
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get();
		Vector2[] vertices = prefabPolygon.Vertices;
		foreach (Vector2 vector in vertices)
		{
			list.Add(transform.TransformPoint(vector.Vector3TopDown()).Vector2TopDown());
		}
		Update(list);
	}

	public void OnDestroy()
	{
		_allPathfindingPolygons.Remove(this);
		ClearBlockedNodes();
		ClearClearance();
		foreach (PathfindingPolygon allPathfindingPolygon in _allPathfindingPolygons)
		{
			if (allPathfindingPolygon._clearanceCenter != null && _clearanceRect.Overlaps(allPathfindingPolygon._clearanceRect))
			{
				allPathfindingPolygon.SetClearance(allPathfindingPolygon._lastBounds);
			}
		}
	}

	public void InitializeGraphs()
	{
		_watersurfaceGraph = GameManager.GraphManager.WaterSurfaceGraph;
	}

	public void UpdateGraphs()
	{
		Update(checkPosition: true);
		ClearBlockedNodes();
		SetBlockedNodesForGraph(GameManager.GraphManager.WaterSurfaceGraph, Bounds);
		ClearClearance();
		SetClearance(Bounds);
	}

	public void ResetClearance()
	{
		SetClearance(_lastBounds);
	}

	public void Clear()
	{
		ClearBlockedNodes();
		ClearClearance();
	}

	private void ClearBlockedNodes()
	{
		if (_blockedNodesPerGrid == null)
		{
			return;
		}
		foreach (List<GridNode> value in _blockedNodesPerGrid.Values)
		{
			foreach (GridNode item in value)
			{
				item.DecreaseObstacleCount();
			}
			ListPool<GridNode>.Add(value);
		}
		_blockedNodesPerGrid.Clear();
	}

	private void SetBlockedNodesForGraph(Grid grid, Rect bounds)
	{
		if ((_obstacle.ObstacleGraphType & grid.GraphType) == grid.GraphType)
		{
			if (_blockedNodesPerGrid.ContainsKey(grid.GraphType))
			{
				throw new NotSupportedException();
			}
			List<GridNode> list = ListPool<GridNode>.Get();
			grid.UpdateBlockedNodes(this, bounds, list);
			_blockedNodesPerGrid.Add(grid.GraphType, list);
		}
	}

	private void ClearClearance()
	{
		if (_clearanceCenter != null && _watersurfaceGraph != null)
		{
			_watersurfaceGraph.ResetClearance(_clearanceCenter, _clearanceDistance);
			_clearanceCenter = null;
		}
	}

	private void SetClearance(Rect bounds)
	{
		if (_watersurfaceGraph == null)
		{
			throw new NotSupportedException("Obstacle.SetClearance can not be called before the Obstalce is initialized.");
		}
		if (!_watersurfaceGraph.WasDisposed)
		{
			_clearanceDistance = Mathf.CeilToInt(Mathf.Max(bounds.size.x, bounds.size.y) / 2f) + _obstacle.ClearanceRange;
			_clearanceCenter = _watersurfaceGraph.ReturnNode(bounds.center);
			_clearanceRect = new Rect(Mathf.Floor(bounds.center.x - (float)_clearanceDistance), Mathf.Floor(bounds.center.y - (float)_clearanceDistance), _clearanceDistance * 2 + 1, _clearanceDistance * 2 + 1);
			_watersurfaceGraph.SetClearance(_clearanceCenter, _clearanceDistance);
			_lastBounds = bounds;
		}
	}

	public void DrawBoundsGizmo(Color color)
	{
		Vector3 center = new Vector3(_lastBounds.center.x, 0f, _lastBounds.center.y);
		Vector3 size = new Vector3(_lastBounds.size.x, 3f, _lastBounds.size.y);
		Gizmos.color = Color.black;
		Gizmos.DrawCube(center, size);
	}
}
[Serializable]
public class AxisAllignedRectangle
{
	public static Vector2 NormalUp = Vector2.up;

	public static Vector2 NormalRight = Vector2.right;

	public Vector2 _center;

	private Vector2 _boundsMin;

	private Vector2 _boundsMax;

	public Vector2 Position => _center;

	public AxisAllignedRectangle(Vector2 center, Vector2 size)
	{
		_center = center;
		Vector2 vector = size / 2f;
		_boundsMin = _center - vector;
		_boundsMax = _center + vector;
	}

	public bool ReturnIsPolygonOverlapping(Polygon polygon)
	{
		Vector2[] vertices = polygon.ReturnPolygon();
		if (ReturnAreProjectionsOverlapping(vertices, NormalUp, _boundsMin.y, _boundsMax.y) && ReturnAreProjectionsOverlapping(vertices, NormalRight, _boundsMin.x, _boundsMax.x))
		{
			return polygon.ReturnIsAxisAllignedRectangleOverlapping(_boundsMin, _boundsMax);
		}
		return false;
	}

	public bool ReturnIsSphereOverlapping(Vector2 center, float radius)
	{
		if (ReturnIsSphereProjectionOverlapping(center, radius, NormalUp, _boundsMin.y, _boundsMax.y) && ReturnIsSphereProjectionOverlapping(center, radius, NormalRight, _boundsMin.x, _boundsMax.x))
		{
			Vector2 normalized = (ReturnClosestVertex(center) - center).normalized;
			Vector2 vector = ReturnProjectionOnAxis(normalized);
			return ReturnIsSphereProjectionOverlapping(center, radius, normalized, vector.x, vector.y);
		}
		return false;
	}

	public bool ReturnIsContainedBySphere(Vector2 center, float radius)
	{
		float num = radius * radius;
		if (center.DistanceToSquared(_boundsMin.x, _boundsMax.y) < num && center.DistanceToSquared(_boundsMax.x, _boundsMax.y) < num && center.DistanceToSquared(_boundsMax.x, _boundsMin.y) < num)
		{
			return center.DistanceToSquared(_boundsMin.x, _boundsMin.y) < num;
		}
		return false;
	}

	private bool ReturnAreProjectionsOverlapping(Vector2[] vertices, Vector2 axis, float min, float max)
	{
		Vector2 vector = vertices[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int num4 = vertices.Length;
		for (int i = 1; i < num4; i++)
		{
			vector = vertices[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}

	private bool ReturnIsSphereProjectionOverlapping(Vector2 sphereCenter, float sphereRadius, Vector2 axis, float min, float max)
	{
		float num = axis.x * sphereCenter.x + axis.y * sphereCenter.y;
		min -= sphereRadius;
		max += sphereRadius;
		if (!(num < min))
		{
			return !(max < num);
		}
		return false;
	}

	private Vector2 ReturnClosestVertex(Vector2 point)
	{
		Vector2 vector = new Vector2(_boundsMin.x, _boundsMax.y);
		float num = point.DistanceToSquared(vector);
		float num2 = num;
		num = point.DistanceToSquared(_boundsMax.x, _boundsMax.y);
		if (num < num2)
		{
			num2 = num;
			vector.x = _boundsMax.x;
			vector.y = _boundsMax.y;
		}
		num = point.DistanceToSquared(_boundsMax.x, _boundsMin.y);
		if (num < num2)
		{
			num2 = num;
			vector.x = _boundsMax.x;
			vector.y = _boundsMin.y;
		}
		num = point.DistanceToSquared(_boundsMin.x, _boundsMin.y);
		if (num < num2)
		{
			num2 = num;
			vector.x = _boundsMin.x;
			vector.y = _boundsMin.y;
		}
		return vector;
	}

	private Vector2 ReturnProjectionOnAxis(Vector2 axis)
	{
		float num = axis.x * _boundsMin.x + axis.y * _boundsMax.y;
		float num2 = num;
		float num3 = num;
		num = axis.x * _boundsMax.x + axis.y * _boundsMax.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		num = axis.x * _boundsMax.x + axis.y * _boundsMin.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		num = axis.x * _boundsMin.x + axis.y * _boundsMin.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		return new Vector2(num2, num3);
	}
}
public class ListBasedPolygon : Polygon2DBase
{
	private int _vertexCount;

	private int _projectionCount;

	private List<Vector2> _vertices;

	private List<Polygon2DLine> _sides;

	private List<Polygon2DProjection> _projections;

	public Vector2 Position { get; private set; }

	public override Rect Bounds { get; protected set; }

	public float Radius { get; private set; }

	public List<Vector2> Vertices => _vertices;

	public List<Polygon2DLine> Sides => _sides;

	public List<Polygon2DProjection> Projections => _projections;

	public override int VertexCount => _vertexCount;

	protected override int SideCount => _vertexCount;

	protected override int ProjectionCount => _projectionCount;

	public override Vector2 GetVertex(int index)
	{
		return _vertices[index];
	}

	protected override Polygon2DLine GetSide(int index)
	{
		return _sides[index];
	}

	protected override Polygon2DProjection GetProjection(int index)
	{
		return _projections[index];
	}

	public ListBasedPolygon()
	{
		_vertices = new List<Vector2>();
		_sides = new List<Polygon2DLine>();
		_projections = new List<Polygon2DProjection>();
	}

	public ListBasedPolygon(List<Vector2> vertices)
		: this()
	{
		SetVertices(vertices);
	}

	public void SetVertices(List<Vector2> vertices)
	{
		_vertices.Clear();
		_sides.Clear();
		_projections.Clear();
		foreach (Vector2 vertex in vertices)
		{
			_vertices.Add(vertex);
		}
		_vertexCount = _vertices.Count;
		_projectionCount = ((IsRegular() && _vertexCount % 2 == 0) ? (_vertexCount / 2) : _vertexCount);
		UpdateBoundsAndRadius();
		UpdateSidesNormalsAndProjections();
	}

	private void UpdateBoundsAndRadius()
	{
		if (_vertices.IsNullOrEmpty())
		{
			return;
		}
		Rect bounds = new Rect(_vertices[0], Vector2.zero);
		foreach (Vector2 vertex in _vertices)
		{
			if (vertex.x < bounds.xMin)
			{
				bounds.xMin = vertex.x;
			}
			else if (vertex.x > bounds.xMax)
			{
				bounds.xMax = vertex.x;
			}
			if (vertex.y < bounds.yMin)
			{
				bounds.yMin = vertex.y;
			}
			else if (vertex.y > bounds.yMax)
			{
				bounds.yMax = vertex.y;
			}
		}
		Bounds = bounds;
		Radius = (bounds.size / 2f).magnitude;
	}

	private void UpdateSidesNormalsAndProjections()
	{
		Vector2 vector = _vertices[_vertexCount - 1];
		_sides.Clear();
		_projections.Clear();
		for (int i = 0; i < _vertexCount; i++)
		{
			Vector2 pointA = vector;
			vector = _vertices[i];
			_sides.Add(new Polygon2DLine(pointA, vector));
			if (i < _projectionCount)
			{
				Vector2 vector2 = new Vector2(0f - (vector.y - pointA.y), vector.x - pointA.x);
				_projections.Add(GetProjectionOnAxis(vector2.normalized));
			}
		}
	}
}
public interface IPolygonProvider
{
	Polygon Polygon { get; }

	bool TryGetPathfindingPolygons(out Polygon[] pathfindingPolygons);
}
[Serializable]
public class Polygon : Polygon2DBase
{
	[Tooltip("The vertices that makeup this polygon.")]
	[SerializeField]
	private List<Transform> Vertices = new List<Transform>();

	[Header("Debug")]
	[Tooltip("Enable additional debug information.")]
	public bool Debug = true;

	public bool DebugPolygon;

	private static uint _count;

	private Transform _parent;

	private bool _initialized;

	private int _vertexCount;

	private int _normalCount;

	private Vector2[] _polygon;

	private Polygon2DLine[] _sides;

	private Polygon2DProjection[] _projections;

	private bool _isRegular;

	private bool _hit;

	private Vector2 _origin;

	private Vector2 _direction;

	private float _width;

	private Vector2[] _rectangle;

	private Polygon2DProjection[] _rectangleProjections;

	public Vector2 Position2D { get; protected set; }

	public override Rect Bounds { get; protected set; }

	public float Radius { get; private set; }

	public uint Id { get; private set; }

	public Vector2[] Polygon2D => _polygon;

	public Polygon2DLine[] Sides => _sides;

	public override int VertexCount => _vertexCount;

	protected override int SideCount => _sides.Length;

	protected override int ProjectionCount => _normalCount;

	public override Vector2 GetVertex(int index)
	{
		return _polygon[index];
	}

	protected override Polygon2DLine GetSide(int index)
	{
		return _sides[index];
	}

	protected override Polygon2DProjection GetProjection(int index)
	{
		return _projections[index];
	}

	public Polygon()
	{
	}

	public Polygon(Vector2 center, float halfSize)
	{
		_vertexCount = 4;
		_normalCount = 2;
		_polygon = new Vector2[4]
		{
			center + new Vector2(0f - halfSize, halfSize),
			center + new Vector2(halfSize, halfSize),
			center + new Vector2(halfSize, 0f - halfSize),
			center + new Vector2(0f - halfSize, 0f - halfSize)
		};
		_sides = new Polygon2DLine[4];
		_projections = new Polygon2DProjection[_normalCount];
		_rectangle = new Vector2[4];
		UpdateSidesNormalsAndProjections();
	}

	public Polygon(List<Vector2> vertices)
	{
		SetVertices(vertices);
		UpdateBoundsAndRadius();
		UpdateSidesNormalsAndProjections();
	}

	public Polygon(Polygon other, Vector3 position, Quaternion rotation)
	{
		using ListPool<Vector2>.List vertices = ListPool<Vector2>.Get();
		other.PopulateTransformedVertices(vertices, position, rotation);
		SetVertices(vertices);
		UpdateBoundsAndRadius();
		UpdateSidesNormalsAndProjections();
	}

	public void Initialize(Transform parent, Polygon prefabPolygon = null)
	{
		Id = _count++;
		Position2D = new Vector2(float.NaN, float.NaN);
		_parent = parent;
		IPolygonProvider componentInChildren;
		if (prefabPolygon != null)
		{
			SetVertices(prefabPolygon.Vertices);
		}
		else if (parent.TryGetComponentInChildren<IPolygonProvider>(out componentInChildren))
		{
			SetVertices(componentInChildren.Polygon.Vertices);
		}
		else
		{
			SetVertices(Vertices);
		}
		_rectangleProjections = new Polygon2DProjection[2];
		_initialized = true;
		Update();
	}

	public void Initialize(Transform parent, List<Transform> vertices)
	{
		_parent = parent;
		SetVertices(vertices);
		_initialized = true;
	}

	public void Update(bool checkPosition = false)
	{
		if (!_initialized)
		{
			return;
		}
		Vector2 vector = _parent.position.Vector2TopDown();
		if (checkPosition && vector == Position2D)
		{
			return;
		}
		Position2D = vector;
		if (Vertices.Count == 0)
		{
			return;
		}
		Vector2 vector2 = Vertices[0].position.Vector2TopDown();
		Vector2 vector3 = vector2;
		Vector2 vector4 = vector2;
		_polygon[0] = vector2;
		for (int i = 1; i < _vertexCount; i++)
		{
			vector2 = Vertices[i].position.Vector2TopDown();
			_polygon[i] = vector2;
			if (vector2.x < vector3.x)
			{
				vector3.x = vector2.x;
			}
			else if (vector4.x < vector2.x)
			{
				vector4.x = vector2.x;
			}
			if (vector2.y < vector3.y)
			{
				vector3.y = vector2.y;
			}
			else if (vector4.y < vector2.y)
			{
				vector4.y = vector2.y;
			}
		}
		UpdateSidesNormalsAndProjections();
		Bounds = new Rect(vector3, vector4 - vector3);
		Radius = (Bounds.size / 2f).magnitude;
	}

	public void FastUpdate()
	{
		if (_polygon == null || _polygon.Length != _vertexCount)
		{
			_polygon = new Vector2[_vertexCount];
		}
		for (int i = 0; i < _vertexCount; i++)
		{
			_polygon[i] = Vertices[i].position.Vector2TopDown();
		}
		UpdateSidesNormalsAndProjections();
	}

	public void Update(Vector2[] vertices)
	{
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get();
		list.AddRange(vertices);
		Update(list);
	}

	public void Update(List<Vector2> vertices)
	{
		SetVertices(vertices);
		UpdateBoundsAndRadius();
		UpdateSidesNormalsAndProjections();
	}

	private void TryCopyVertexTransforms(IPolygonProvider polygonProvider)
	{
		if (polygonProvider != null)
		{
			Vertices = new List<Transform>(polygonProvider.Polygon.Vertices);
		}
	}

	public void PopulateTransformedVertices(List<Vector2> vertices, Vector3 position, Quaternion rotation)
	{
		List<Transform> list = ReturnVertices();
		Matrix4x4 matrix4x = Matrix4x4.TRS(position, rotation, Vector3.one);
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			vertices.Add(matrix4x.MultiplyPoint3x4(list[i].position).Vector2TopDown());
		}
	}

	public bool ReturnShouldInitialize()
	{
		if (_polygon != null && _sides != null)
		{
			return _projections == null;
		}
		return true;
	}

	public float ReturnBoundingRadius()
	{
		float num = 0f;
		foreach (Transform vertex in Vertices)
		{
			float sqrMagnitude = vertex.localPosition.sqrMagnitude;
			if (num < sqrMagnitude)
			{
				num = sqrMagnitude;
			}
		}
		return Mathf.Sqrt(num);
	}

	public List<Transform> ReturnVertices()
	{
		return Vertices;
	}

	public Vector2[] ReturnPolygon()
	{
		return _polygon;
	}

	public bool ReturnIsLineIntersecting(Vector3 origin, Vector3 direction, float width = 0f)
	{
		return ReturnIsLineIntersecting(origin.Vector2TopDown(), direction.Vector2TopDown(), width);
	}

	public bool ReturnIsLineIntersecting(Vector2 origin, Vector2 direction, float width = 0f)
	{
		_width = width;
		if (width == 0f)
		{
			_origin = origin;
			_direction = direction;
			_hit = ReturnIsIntersecting(_origin, _direction);
		}
		else
		{
			_hit = ReturnIsOverlapping(origin, direction, width);
		}
		return _hit;
	}

	public bool ReturnIsLineIntersecting(Vector2 origin, Vector2 end)
	{
		Vector2 closestIntersection;
		return ReturnIsLineIntersecting(origin, end, out closestIntersection);
	}

	public bool ReturnIsLineIntersecting(Vector2 origin, Vector2 end, out Vector2 closestIntersection)
	{
		_hit = false;
		closestIntersection = Vector2.zero;
		float num = float.MaxValue;
		for (int i = 0; i < _sides.Length; i++)
		{
			if (PajamaLlama.Math.Math.LineLineIntersection(out var intersection, origin, end, _sides[i].Point, _sides[i].Point + _sides[i].Vector))
			{
				float num2 = Vector2.Distance(origin, intersection);
				if (num2 < num)
				{
					closestIntersection = intersection;
					num = num2;
					_hit = true;
				}
			}
		}
		return _hit;
	}

	public bool ReturnPointIsOverlapping(Vector3 point)
	{
		_hit = ReturnPointIsOverlapping(point.Vector2TopDown());
		return _hit;
	}

	public bool ReturnArePolygonsOverlapping(Polygon polygon, bool includeTolerance = false)
	{
		_hit = ReturnPolygonIsOverlapping(polygon._polygon, includeTolerance) && polygon.ReturnPolygonIsOverlapping(_polygon, includeTolerance);
		return _hit;
	}

	public bool ReturnArePolygonsOverlapping(Vector2[] vertices, bool includeTolerance = false)
	{
		_hit = ReturnPolygonIsOverlapping(vertices, includeTolerance);
		return _hit;
	}

	public bool ReturnIsPolygonOverlapping(Vector2[] vertices, bool includeTolerance = false)
	{
		return ReturnPolygonIsOverlapping(vertices, includeTolerance);
	}

	public bool ReturnIsAxisAllignedRectangleOverlapping(Vector2 min, Vector2 max)
	{
		for (int i = 0; i < _normalCount; i++)
		{
			if (!_projections[i].ReturnOverlap(min, max))
			{
				return false;
			}
		}
		return true;
	}

	public float ReturnPointDistanceToBorder(Vector2 point, out Vector2 projection)
	{
		projection = Vector2.zero;
		if (_sides == null)
		{
			return 0f;
		}
		int num = _sides.Length;
		float num2 = float.MaxValue;
		for (int i = 0; i < num; i++)
		{
			Vector2 vector = _sides[i].ReturnProjection(point);
			float num3 = point.DistanceToSquared(vector);
			if (num3 < num2)
			{
				projection = vector;
				num2 = num3;
			}
		}
		return Mathf.Sqrt(num2);
	}

	private void UpdatePolygonSides(Vector2[] polygon, List<Polygon2DLine> lines, bool clear = true)
	{
		int num = polygon.Length;
		if (clear)
		{
			lines.Clear();
			lines.Capacity = num;
		}
		for (int i = 0; i < num; i++)
		{
			Vector2 pointA = ((i != 0) ? polygon[i - 1] : polygon[num - 1]);
			Vector2 pointB = polygon[i];
			lines.Add(new Polygon2DLine(pointA, pointB));
		}
	}

	private Vector2[] ReturnPolygonNormals(Vector2[] polygon)
	{
		int num = polygon.Length;
		Vector2[] array = new Vector2[num];
		for (int i = 0; i < num; i++)
		{
			Vector2 vector = ((i != 0) ? polygon[i - 1] : polygon[num - 1]);
			Vector2 vector2 = polygon[i];
			array[i] = new Vector2(0f - (vector2.y - vector.y), vector2.x - vector.x);
		}
		return array;
	}

	private bool ContainsNormal(List<Vector2> computedNormals, Vector2 normal)
	{
		int count = computedNormals.Count;
		for (int i = 0; i < count; i++)
		{
			Vector2 vector = computedNormals[i];
			if (normal == vector || normal == -vector)
			{
				return true;
			}
		}
		return false;
	}

	public float ReturnClosestDistance(Vector3 point)
	{
		float num = float.MaxValue;
		foreach (Transform vertex in Vertices)
		{
			float num2 = Vector3.Distance(vertex.position, point);
			if (num2 < num)
			{
				num = num2;
			}
		}
		return num;
	}

	public static Polygon ReturnFromLine(Vector2 from, Vector2 to, float width)
	{
		Vector2 vector = to - from;
		Vector2 vector2 = new Vector2(0f - vector.y, vector.x).normalized * width;
		Vector2 vector3 = from + vector2;
		Vector2 vector4 = from - vector2;
		Polygon polygon = new Polygon();
		polygon._polygon = new Vector2[4]
		{
			vector3,
			vector3 + vector,
			vector4 + vector,
			vector4
		};
		polygon._vertexCount = 4;
		polygon._normalCount = 2;
		polygon._sides = new Polygon2DLine[4];
		polygon._projections = new Polygon2DProjection[2];
		polygon._rectangle = new Vector2[4];
		polygon.UpdateSidesNormalsAndProjections();
		return polygon;
	}

	public static bool ReturnIsConvex(List<Vector2> vertices)
	{
		int count = vertices.Count;
		if (count < 3)
		{
			return false;
		}
		Vector2 vector = vertices[count - 2];
		Vector2 vector2 = vertices[count - 1];
		float num = 0f;
		for (int i = 0; i < count; i++)
		{
			Vector2 vector3 = vertices[i];
			Vector2 vector4 = vector - vector2;
			Vector2 to = vector3 - vector2;
			float num2 = Vector2.SignedAngle(vector4, to);
			if (num == 0f)
			{
				num = num2;
			}
			else
			{
				if (num < 0f && 0f <= num2)
				{
					return false;
				}
				if (0f < num && num2 <= 0f)
				{
					return false;
				}
			}
			vector = vector2;
			vector2 = vector3;
		}
		return true;
	}

	public void SetVertices(List<Transform> vertices)
	{
		Vertices = vertices;
		using PooledList<Vector2> pooledList = PooledList<Vector2>.Get(vertices.Count);
		foreach (Transform vertex in vertices)
		{
			pooledList.Add(vertex.position.Vector2TopDown());
		}
		SetVertices(pooledList);
	}

	public void SetVertices(List<Vector2> vertices)
	{
		int count = vertices.Count;
		if (count != 0)
		{
			if (_vertexCount != count)
			{
				_vertexCount = count;
				_polygon = new Vector2[_vertexCount];
				_sides = new Polygon2DLine[_vertexCount];
			}
			vertices.CopyTo(_polygon, 0);
			_isRegular = ReturnIsRegularPolygon(_polygon);
			_normalCount = ((_isRegular && _vertexCount % 2 == 0) ? (_vertexCount / 2) : _vertexCount);
			if (_projections == null || _projections.Length != _normalCount)
			{
				_projections = new Polygon2DProjection[_normalCount];
			}
		}
	}

	public void AddVertex(Transform vertex)
	{
		Vertices.Add(vertex);
	}

	public void AddVertices(List<Transform> additionalVertices)
	{
		Vertices.AddRange(additionalVertices);
		SetVertices(Vertices);
	}

	public override void PopulateVertices(List<Vector2> vertices)
	{
		if (((IReadOnlyCollection<Vector2>)(object)_polygon).IsNullOrEmpty())
		{
			if (!Vertices.IsNullOrEmpty())
			{
				for (int i = 0; i < Vertices.Count; i++)
				{
					vertices.Add(Vertices[i].position.Vector2TopDown());
				}
			}
		}
		else
		{
			base.PopulateVertices(vertices);
		}
	}

	private void UpdateBoundsAndRadius()
	{
		if (((IReadOnlyCollection<Vector2>)(object)_polygon).IsNullOrEmpty())
		{
			return;
		}
		Rect bounds = new Rect(_polygon[0], Vector2.zero);
		Vector2[] polygon = _polygon;
		for (int i = 0; i < polygon.Length; i++)
		{
			Vector2 vector = polygon[i];
			if (vector.x < bounds.xMin)
			{
				bounds.xMin = vector.x;
			}
			else if (vector.x > bounds.xMax)
			{
				bounds.xMax = vector.x;
			}
			if (vector.y < bounds.yMin)
			{
				bounds.yMin = vector.y;
			}
			else if (vector.y > bounds.yMax)
			{
				bounds.yMax = vector.y;
			}
		}
		Bounds = bounds;
		Radius = (bounds.size / 2f).magnitude;
	}

	private void UpdateSidesNormalsAndProjections()
	{
		Vector2 vector = _polygon[_vertexCount - 1];
		for (int i = 0; i < _vertexCount; i++)
		{
			Vector2 pointA = vector;
			vector = _polygon[i];
			_sides[i] = new Polygon2DLine(pointA, vector);
			if (i < _normalCount)
			{
				Vector2 vector2 = new Vector2(0f - (vector.y - pointA.y), vector.x - pointA.x);
				_projections[i] = ProjectPolygonOnAxis(vector2.normalized, _polygon);
			}
		}
	}

	private void UpdateRectangleNormalsAndProjections()
	{
		Vector2 vector = _rectangle[3];
		Vector2 vector2 = _rectangle[0];
		Vector2 vector3 = new Vector2(0f - (vector2.y - vector.y), vector2.x - vector.x);
		_rectangleProjections[0] = ProjectPolygonOnAxis(vector3.normalized, _rectangle);
		vector3 = new Vector2(vector3.y, 0f - vector3.x);
		_rectangleProjections[1] = ProjectPolygonOnAxis(vector3.normalized, _rectangle);
	}

	private new bool ReturnIsIntersecting(Vector2 origin, Vector2 direction)
	{
		Polygon2DLine[] sides = _sides;
		for (int i = 0; i < sides.Length; i++)
		{
			Polygon2DLine polygon2DLine = sides[i];
			float num = ReturnIntersectionScalar(origin, direction, polygon2DLine.Point, polygon2DLine.Vector);
			if (!(num < 0f) && !(1f < num))
			{
				Vector2 point = origin + num * direction;
				if (ReturnPointIsOverlapping(point, 0.01f))
				{
					return true;
				}
			}
		}
		return false;
	}

	private new float ReturnIntersectionScalar(Vector2 pointA, Vector2 vectorA, Vector2 pointB, Vector2 vectorB)
	{
		return (pointB.Cross(vectorB) - pointA.Cross(vectorB)) / vectorA.Cross(vectorB);
	}

	private bool ReturnIsOverlapping(Vector2 origin, Vector2 direction, float width)
	{
		Vector2 vector = new Vector2(0f - direction.y, direction.x).normalized * width;
		Vector2 vector2 = origin + vector;
		Vector2 vector3 = origin - vector;
		if (_rectangle == null)
		{
			_rectangle = new Vector2[4];
		}
		_rectangle[0] = vector2;
		_rectangle[1] = vector2 + direction;
		_rectangle[2] = vector3 + direction;
		_rectangle[3] = vector3;
		if (ReturnPolygonIsOverlapping(_rectangle))
		{
			UpdateRectangleNormalsAndProjections();
			return ReturnPolygonsAreOverlapping(_rectangleProjections, _polygon);
		}
		return false;
	}

	public new bool ReturnPointIsOverlapping(Vector2 point, float marginOffError = 0f)
	{
		for (int i = 0; i < _normalCount; i++)
		{
			Polygon2DProjection polygon2DProjection = _projections[i];
			float scalar = Vector2.Dot(polygon2DProjection.axis, point);
			if (!polygon2DProjection.ReturnOverlap(scalar, marginOffError))
			{
				return false;
			}
		}
		return true;
	}

	private bool ReturnPolygonIsOverlapping(Vector2[] other, bool includeTolerance = false)
	{
		for (int i = 0; i < _normalCount; i++)
		{
			if (!_projections[i].ReturnOverlap(other, includeTolerance))
			{
				return false;
			}
		}
		return true;
	}

	private bool ReturnPolygonsAreOverlapping(Polygon2DProjection[] projections, Vector2[] other)
	{
		int num = projections.Length;
		for (int i = 0; i < num; i++)
		{
			if (!projections[i].ReturnOverlap(other))
			{
				return false;
			}
		}
		return true;
	}

	private Polygon2DProjection ProjectPolygonOnAxis(Vector2 axis, Vector2[] polygon)
	{
		Vector2 vector = polygon[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int num4 = polygon.Length;
		for (int i = 1; i < num4; i++)
		{
			vector = polygon[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		return new Polygon2DProjection(axis, num2, num3);
	}

	private bool ReturnIsRegularPolygon(Vector2[] polygon)
	{
		int num = polygon.Length;
		Vector2 vector = polygon[num - 1];
		Vector2 vector2 = polygon[0];
		Vector2 vector3 = vector - polygon[num - 2];
		Vector2 vector4 = vector2 - vector;
		float b = vector3.Angle(vector4);
		for (int i = 1; i < num; i++)
		{
			vector = vector2;
			vector2 = polygon[i];
			vector3 = vector4;
			vector4 = vector2 - vector;
			if (!Mathf.Approximately(vector3.Angle(vector4), b))
			{
				return false;
			}
		}
		return true;
	}

	public void ResetIfRequired(Transform parent, bool required = false)
	{
		if (!Application.isPlaying)
		{
			bool flag = _vertexCount != Vertices.Count || _polygon == null || _sides == null || _projections == null;
			if (required || flag)
			{
				_vertexCount = -1;
				Initialize(parent);
			}
		}
	}

	public void DrawDebugPolygon(Color color, Vector3 offset)
	{
		int num = 0;
		while (_polygon != null && num < _polygon.Length)
		{
			int num2 = (int)Mathf.Repeat(num + 1, _polygon.Length);
			UnityEngine.Debug.DrawLine(_polygon[num].Vector3TopDown(), _polygon[num2].Vector3TopDown(), color, 1f, depthTest: false);
			num++;
		}
	}

	public void DrawDebugRectangle(Color color, Vector3 offset)
	{
		int num = 0;
		while (_rectangle != null && num < _rectangle.Length)
		{
			int num2 = (int)Mathf.Repeat(num + 1, _rectangle.Length);
			UnityEngine.Debug.DrawLine(_rectangle[num].Vector3TopDown(), _rectangle[num2].Vector3TopDown(), color, 1f, depthTest: false);
			num++;
		}
	}

	public void DrawGizmos()
	{
		Color color = Gizmos.color;
		if (Debug)
		{
			Gizmos.color = Color.red;
			Gizmos.DrawCube(new Vector3(Bounds.center.x, 0f, Bounds.center.y), new Vector3(Bounds.size.x, 1f, Bounds.size.y));
			Gizmos.color = Color.white;
			if (_width == 0f)
			{
				Gizmos.DrawRay(_origin.Vector3TopDown(), _direction.Vector3TopDown());
			}
			else if (_rectangle != null)
			{
				for (int i = 0; i < _rectangle.Length; i++)
				{
					Vector3 vector = ((i != 0) ? _rectangle[i - 1].Vector3TopDown() : _rectangle[_rectangle.Length - 1].Vector3TopDown());
					Gizmos.DrawLine(vector, _rectangle[i].Vector3TopDown());
				}
				Gizmos.color = Color.magenta;
				DrawNormals(_projections);
				if (_rectangleProjections != null)
				{
					Gizmos.color = Color.cyan;
					DrawNormals(_rectangleProjections);
				}
			}
		}
		if (DebugPolygon)
		{
			DrawPolygon();
			if (_hit)
			{
				DrawPolygon(Color.red);
			}
			else
			{
				DrawPolygon(Color.yellow);
			}
		}
		Gizmos.color = color;
	}

	public void DrawPolygon(Color color)
	{
		Color color2 = Gizmos.color;
		Gizmos.color = color;
		int num = 0;
		while (_polygon != null && num < _polygon.Length)
		{
			int num2 = (int)Mathf.Repeat(num + 1, _polygon.Length);
			Gizmos.DrawLine(_polygon[num].Vector3TopDown(), _polygon[num2].Vector3TopDown());
			num++;
		}
		Gizmos.color = color2;
	}

	public void DrawVertices(Color color)
	{
		if (DebugPolygon)
		{
			Color color2 = Gizmos.color;
			Gizmos.color = color;
			int num = 0;
			while (Vertices != null && num < Vertices.Count)
			{
				int index = (int)Mathf.Repeat(num + 1, Vertices.Count);
				Gizmos.DrawLine(Vertices[num].position, Vertices[index].position);
				num++;
			}
			Gizmos.color = color2;
		}
	}

	private void DrawPolygon()
	{
		Gizmos.color = Color.white;
		if (Vertices.Count == 2)
		{
			Gizmos.DrawLine(Vertices[0].transform.position, Vertices[1].transform.position);
		}
		else if (2 < Vertices.Count)
		{
			for (int i = 0; i < Vertices.Count; i++)
			{
				Vector3 vector = ((i != 0) ? Vertices[i - 1].position : Vertices[Vertices.Count - 1].position);
				Gizmos.DrawLine(vector, Vertices[i].position);
			}
		}
	}

	private void DrawNormals(Polygon2DProjection[] projections)
	{
		for (int i = 0; i < projections.Length; i++)
		{
			Vector3 vector = projections[i].axis.Vector3TopDown();
			Gizmos.DrawLine(Vector3.zero - 100f * vector, Vector3.zero + 100f * vector);
		}
	}
}
public abstract class Polygon2DBase
{
	public abstract Rect Bounds { get; protected set; }

	public abstract int VertexCount { get; }

	protected abstract int SideCount { get; }

	protected abstract int ProjectionCount { get; }

	public Vector2 GetClosestPointOnPolygon(out Polygon2DLine closestSide, out float distance, Vector2 position, float range = float.MaxValue)
	{
		int sideCount = SideCount;
		Vector2 result = default(Vector2);
		closestSide = default(Polygon2DLine);
		distance = range;
		for (int i = 0; i < sideCount; i++)
		{
			Polygon2DLine side = GetSide(i);
			Vector2 vector = side.ReturnClosesPointOnLineSegment(position);
			float num = Vector2.Distance(position, vector);
			if (num < distance)
			{
				result = vector;
				closestSide = side;
				distance = num;
			}
		}
		return result;
	}

	public abstract Vector2 GetVertex(int index);

	protected abstract Polygon2DLine GetSide(int index);

	protected abstract Polygon2DProjection GetProjection(int index);

	public virtual void PopulateVertices(List<Vector2> vertices)
	{
		for (int i = 0; i < VertexCount; i++)
		{
			vertices.Add(GetVertex(i));
		}
	}

	public bool TryPopulateExpandedVertices(List<Vector2> expandedVertices, float amount)
	{
		for (int i = 0; i < VertexCount; i++)
		{
			Polygon2DLine side = GetSide(i);
			side.Point = MoveSideOutwards(side, amount);
			Polygon2DLine side2 = GetSide((i + 1).ToWrappedIndex(VertexCount));
			side2.Point = MoveSideOutwards(side2, amount);
			if (side.TryReturnIntersection(side2, out var intersection))
			{
				expandedVertices.Add(intersection);
				continue;
			}
			return false;
		}
		return true;
	}

	private Vector2 MoveSideOutwards(Polygon2DLine side, float amount)
	{
		Vector2 vector = new Vector2(0f - side.Vector.y, side.Vector.x);
		vector.Normalize();
		return side.Point + vector * amount;
	}

	public bool IsOverlapping(Polygon2DBase other, bool includeTolerance = false)
	{
		if (!Bounds.Overlaps(other.Bounds))
		{
			return false;
		}
		if (includeTolerance)
		{
			if (IsPolygonOverlappingWithTolerance(other))
			{
				return other.IsPolygonOverlappingWithTolerance(this);
			}
			return false;
		}
		if (IsPolygonOverlapping(other))
		{
			return other.IsPolygonOverlapping(this);
		}
		return false;
	}

	public bool IsOverlapping(Vector2 point, float marginOffError = 0f)
	{
		int projectionCount = ProjectionCount;
		for (int i = 0; i < projectionCount; i++)
		{
			Polygon2DProjection projection = GetProjection(i);
			float scalar = Vector2.Dot(projection.axis, point);
			if (!projection.ReturnOverlap(scalar, marginOffError))
			{
				return false;
			}
		}
		return true;
	}

	public bool TryGetOverlap(Polygon2DBase polygon, out float overlap)
	{
		using ListPool<Vector2>.List vertices = ListPool<Vector2>.Get();
		if (Bounds.Overlaps(polygon.Bounds) && PopulateOverlap(polygon, vertices))
		{
			SortVertices(vertices);
			overlap = ComputeSurface(vertices);
			return true;
		}
		overlap = 0f;
		return false;
	}

	public bool PopulateOverlap(Polygon2DBase polygon, List<Vector2> vertices)
	{
		PopulateOverllapingPoints(polygon, vertices);
		polygon.PopulateOverllapingPoints(this, vertices);
		PopulateIntersectionPoints(polygon, vertices);
		return 2 < vertices.Count;
	}

	private void PopulateOverllapingPoints(Polygon2DBase polygon, List<Vector2> vertices)
	{
		for (int i = 0; i < polygon.VertexCount; i++)
		{
			Vector2 vertex = polygon.GetVertex(i);
			if (IsOverlapping(vertex))
			{
				vertices.Add(vertex);
			}
		}
	}

	private void PopulateIntersectionPoints(Polygon2DBase polygon, List<Vector2> vertices)
	{
		for (int i = 0; i < SideCount; i++)
		{
			Polygon2DLine side = GetSide(i);
			for (int j = 0; j < polygon.SideCount; j++)
			{
				Polygon2DLine side2 = polygon.GetSide(j);
				if (side.TryReturnIntersectionOnLine(side2, out var intersection))
				{
					vertices.Add(intersection);
				}
			}
		}
	}

	private bool IsPolygonOverlapping(Polygon2DBase polygon)
	{
		for (int i = 0; i < ProjectionCount; i++)
		{
			if (!GetProjection(i).ReturnOverlap(polygon))
			{
				return false;
			}
		}
		return true;
	}

	private bool IsPolygonOverlappingWithTolerance(Polygon2DBase polygon)
	{
		for (int i = 0; i < ProjectionCount; i++)
		{
			if (!GetProjection(i).ReturnOverlapWithTolerance(polygon))
			{
				return false;
			}
		}
		return true;
	}

	protected bool ReturnIsIntersecting(Vector2 origin, Vector2 direction)
	{
		int sideCount = SideCount;
		for (int i = 0; i < sideCount; i++)
		{
			Polygon2DLine side = GetSide(i);
			float num = ReturnIntersectionScalar(origin, direction, side.Point, side.Vector);
			if (!(num < 0f) && !(1f < num))
			{
				Vector2 point = origin + num * direction;
				if (ReturnPointIsOverlapping(point, 0.01f))
				{
					return true;
				}
			}
		}
		return false;
	}

	protected float ReturnIntersectionScalar(Vector2 pointA, Vector2 vectorA, Vector2 pointB, Vector2 vectorB)
	{
		return (pointB.Cross(vectorB) - pointA.Cross(vectorB)) / vectorA.Cross(vectorB);
	}

	protected bool ReturnPointIsOverlapping(Vector2 point, float marginOffError = 0f)
	{
		int projectionCount = ProjectionCount;
		for (int i = 0; i < projectionCount; i++)
		{
			Polygon2DProjection projection = GetProjection(i);
			float scalar = Vector2.Dot(projection.axis, point);
			if (!projection.ReturnOverlap(scalar, marginOffError))
			{
				return false;
			}
		}
		return true;
	}

	protected Polygon2DProjection GetProjectionOnAxis(Vector2 axis)
	{
		Vector2 vertex = GetVertex(0);
		float num = axis.x * vertex.x + axis.y * vertex.y;
		float num2 = num;
		float num3 = num;
		int vertexCount = VertexCount;
		for (int i = 1; i < vertexCount; i++)
		{
			vertex = GetVertex(i);
			num = axis.x * vertex.x + axis.y * vertex.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		return new Polygon2DProjection(axis, num2, num3);
	}

	protected bool IsRegular()
	{
		int vertexCount = VertexCount;
		Vector2 vertex = GetVertex(vertexCount - 1);
		Vector2 vertex2 = GetVertex(0);
		Vector2 vector = vertex - GetVertex(vertexCount - 2);
		Vector2 vector2 = vertex2 - vertex;
		float b = vector.Angle(vector2);
		for (int i = 1; i < vertexCount; i++)
		{
			vertex = vertex2;
			vertex2 = GetVertex(i);
			vector = vector2;
			vector2 = vertex2 - vertex;
			if (!Mathf.Approximately(vector.Angle(vector2), b))
			{
				return false;
			}
		}
		return true;
	}

	public static void SortVertices(List<Vector2> vertices)
	{
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get(vertices);
		vertices.Clear();
		SortFirstVertices(list, vertices);
		Vector2 vector = vertices[vertices.Count - 1];
		Vector2 vector2 = vertices[vertices.Count - 2] - vector;
		while (list.Count > 1)
		{
			int nextSortedVertexIndex = GetNextSortedVertexIndex(vector, vector2, list);
			Vector2 vector3 = list[nextSortedVertexIndex];
			vector2 = vector - vector3;
			vector = vector3;
			vertices.Add(vector);
			list.RemoveAt(nextSortedVertexIndex);
		}
		if (list.Count == 1)
		{
			vertices.Add(list[0]);
		}
	}

	private static void SortFirstVertices(List<Vector2> unsortedVertices, List<Vector2> sortedVertices)
	{
		Vector2 vector = unsortedVertices[0];
		unsortedVertices.RemoveAt(0);
		GetFirstSortedVertexIndices(vector, unsortedVertices, out var indexA, out var indexB);
		Vector2 vector2 = unsortedVertices[indexA];
		Vector2 vector3 = unsortedVertices[indexB];
		Vector2 vector4 = vector2 - vector;
		Vector2 to = vector3 - vector;
		if (Vector2.SignedAngle(vector4, to) < 0f)
		{
			sortedVertices.Add(vector3);
			sortedVertices.Add(vector);
			sortedVertices.Add(vector2);
		}
		else
		{
			sortedVertices.Add(vector2);
			sortedVertices.Add(vector);
			sortedVertices.Add(vector3);
		}
		if (indexA < indexB)
		{
			unsortedVertices.RemoveAt(indexB);
			unsortedVertices.RemoveAt(indexA);
		}
		else
		{
			unsortedVertices.RemoveAt(indexA);
			unsortedVertices.RemoveAt(indexB);
		}
	}

	private static void GetFirstSortedVertexIndices(Vector2 vertex, List<Vector2> unsorted, out int indexA, out int indexB)
	{
		float num = 0f;
		indexA = -1;
		indexB = -1;
		for (int i = 0; i < unsorted.Count - 1; i++)
		{
			Vector2 vector = unsorted[i] - vertex;
			for (int j = i + 1; j < unsorted.Count; j++)
			{
				Vector2 to = unsorted[j] - vertex;
				float num2 = Vector2.Angle(vector, to);
				if (num < num2)
				{
					num = num2;
					indexA = i;
					indexB = j;
				}
			}
		}
	}

	private static int GetNextSortedVertexIndex(Vector2 vertex, Vector2 vector, List<Vector2> vertices)
	{
		float num = -1f;
		int result = -1;
		for (int i = 0; i < vertices.Count; i++)
		{
			float num2 = Vector2.Angle(vector, vertices[i] - vertex);
			if (num < num2)
			{
				num = num2;
				result = i;
			}
		}
		return result;
	}

	public static Vector2 ComputeCentroid(List<Vector2> vertices)
	{
		Vector2 zero = Vector2.zero;
		foreach (Vector2 vertex in vertices)
		{
			zero += vertex;
		}
		return zero / vertices.Count;
	}

	public static float ComputeSurface(List<Vector2> vertices)
	{
		if (vertices.Count - 2 < 1)
		{
			return 0f;
		}
		Vector2 vector = vertices[0];
		Vector2 vector2 = vertices[1];
		float num = 0f;
		for (int i = 2; i < vertices.Count; i++)
		{
			Vector2 vector3 = vertices[i];
			float magnitude = (vector2 - vector).magnitude;
			float magnitude2 = (vector3 - vector2).magnitude;
			float magnitude3 = (vector - vector3).magnitude;
			float num2 = (magnitude + magnitude2 + magnitude3) / 2f;
			num += Mathf.Sqrt(num2 * (num2 - magnitude) * (num2 - magnitude2) * (num2 - magnitude3));
			vector2 = vector3;
		}
		return num;
	}
}
public struct Polygon2DLine
{
	internal Vector2 Point;

	internal Vector2 Vector;

	public Polygon2DLine(Vector2 pointA, Vector2 pointB)
	{
		Point = pointA;
		Vector = new Vector2(pointB.x - pointA.x, pointB.y - pointA.y);
	}

	public Vector2 ReturnProjection(Vector2 pointToProject)
	{
		Vector2 vector = pointToProject - Point;
		float num = Vector.normalized.x * vector.x + Vector.normalized.y * vector.y;
		return Point + Vector.normalized * num;
	}

	public Vector2 ReturnClosesPointOnLineSegment(Vector2 pointToProject)
	{
		Vector2 normalized = Vector.normalized;
		Vector2 vector = pointToProject - Point;
		float num = normalized.x * vector.x + normalized.y * vector.y;
		float magnitude = Vector.magnitude;
		if (0f <= num && num <= magnitude)
		{
			return Point + Vector.normalized * num;
		}
		if (num < 0f)
		{
			return Point;
		}
		return Point + Vector;
	}

	public bool TryReturnProjectionInBounds(Vector2 pointToProject, out Vector2 projection)
	{
		Vector2 normalized = Vector.normalized;
		Vector2 vector = pointToProject - Point;
		float num = normalized.x * vector.x + normalized.y * vector.y;
		float magnitude = Vector.magnitude;
		if ((0f < num && num < magnitude) || Mathf.Approximately(num, 0f) || Mathf.Approximately(num, magnitude))
		{
			projection = Point + Vector.normalized * num;
			return true;
		}
		projection = default(Vector2);
		return false;
	}

	public bool TryReturnIntersectionOnLine(Polygon2DLine lineToIntersect, out Vector2 intersection)
	{
		float a = Vector.Cross(lineToIntersect.Vector);
		intersection = default(Vector2);
		if (Mathf.Approximately(a, 0f))
		{
			return false;
		}
		float num = (lineToIntersect.Point.Cross(lineToIntersect.Vector) - Point.Cross(lineToIntersect.Vector)) / Vector.Cross(lineToIntersect.Vector);
		if (num < 0f || num > 1f)
		{
			return false;
		}
		intersection = Point + num * Vector;
		Vector2 lhs = intersection - lineToIntersect.Point;
		if (Vector2.Dot(lhs, lineToIntersect.Vector) > 0f)
		{
			return lhs.magnitude < lineToIntersect.Vector.magnitude;
		}
		return false;
	}

	public bool TryReturnIntersection(Polygon2DLine lineToIntersect, out Vector2 intersection)
	{
		float a = Vector.Cross(lineToIntersect.Vector);
		intersection = default(Vector2);
		if (Mathf.Approximately(a, 0f))
		{
			return false;
		}
		float num = (lineToIntersect.Point.Cross(lineToIntersect.Vector) - Point.Cross(lineToIntersect.Vector)) / Vector.Cross(lineToIntersect.Vector);
		intersection = Point + num * Vector;
		return true;
	}

	public Rect ReturnMarginRect(float margin)
	{
		Vector2 vector = Vector.normalized * margin;
		Vector2 vector2 = Vector2.Perpendicular(vector);
		Vector2 lhs = Point - vector - vector2;
		Vector2 rhs = Point + Vector + vector + vector2;
		Vector2 vector3 = Vector2.Min(lhs, rhs);
		Vector2 vector4 = Vector2.Max(lhs, rhs);
		return new Rect(vector3, vector4 - vector3);
	}
}
public struct Polygon2DProjection
{
	internal Vector2 axis;

	internal float min;

	internal float max;

	internal Polygon2DProjection(Vector2 axis, float min, float max)
	{
		this.axis = axis;
		this.min = min;
		this.max = max;
	}

	internal bool ReturnOverlap(Polygon2DProjection other)
	{
		if (!(other.max < min))
		{
			return !(max < other.min);
		}
		return false;
	}

	internal bool ReturnOverlap(int other_min, int other_max)
	{
		if (!((float)other_max < min))
		{
			return !(max < (float)other_min);
		}
		return false;
	}

	internal bool ReturnOverlap(float scalar)
	{
		if (!(scalar < min))
		{
			return !(max < scalar);
		}
		return false;
	}

	internal bool ReturnOverlap(float scalar, float marginOfError)
	{
		float num = min - marginOfError;
		float num2 = max + marginOfError;
		if (!(scalar < num))
		{
			return !(num2 < scalar);
		}
		return false;
	}

	internal bool ReturnOverlap(Polygon2DBase polygon)
	{
		Vector2 vertex = polygon.GetVertex(0);
		float num = axis.x * vertex.x + axis.y * vertex.y;
		float num2 = num;
		float num3 = num;
		int vertexCount = polygon.VertexCount;
		for (int i = 1; i < vertexCount; i++)
		{
			vertex = polygon.GetVertex(i);
			num = axis.x * vertex.x + axis.y * vertex.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}

	internal bool ReturnOverlapWithTolerance(Polygon2DBase polygon)
	{
		Vector2 vertex = polygon.GetVertex(0);
		float num = axis.x * vertex.x + axis.y * vertex.y;
		float num2 = num;
		float num3 = num;
		int vertexCount = polygon.VertexCount;
		for (int i = 1; i < vertexCount; i++)
		{
			vertex = polygon.GetVertex(i);
			num = axis.x * vertex.x + axis.y * vertex.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		bool num4 = num3 <= min || MathExtensions.Approximately(num3, min);
		bool flag = max < num2 || MathExtensions.Approximately(max, num2);
		return !(num4 || flag);
	}

	internal bool ReturnOverlap(List<Vector2> polygon, bool includeTolerance = false)
	{
		Vector2 vector = polygon[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int count = polygon.Count;
		for (int i = 1; i < count; i++)
		{
			vector = polygon[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (includeTolerance)
		{
			bool num4 = num3 <= min || MathExtensions.Approximately(num3, min);
			bool flag = max < num2 || MathExtensions.Approximately(max, num2);
			return !(num4 || flag);
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}

	internal bool ReturnOverlap(Vector2[] polygon, bool includeTolerance = false)
	{
		Vector2 vector = polygon[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int num4 = polygon.Length;
		for (int i = 1; i < num4; i++)
		{
			vector = polygon[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		if (includeTolerance)
		{
			bool num5 = num3 <= min || MathExtensions.Approximately(num3, min);
			bool flag = max < num2 || MathExtensions.Approximately(max, num2);
			return !(num5 || flag);
		}
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}

	internal bool ReturnOverlap(Vector2 vertexMin, Vector2 vertexMax)
	{
		float num = axis.x * vertexMin.x + axis.y * vertexMax.y;
		float num2 = num;
		float num3 = num;
		num = axis.x * vertexMax.x + axis.y * vertexMax.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		num = axis.x * vertexMax.x + axis.y * vertexMin.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		num = axis.x * vertexMin.x + axis.y * vertexMin.y;
		num2 = ((num < num2) ? num : num2);
		num3 = ((num3 < num) ? num : num3);
		if (!(num3 < min))
		{
			return !(max < num2);
		}
		return false;
	}
}
public class Rectangle : Polygon2DBase
{
	private Rect _bounds;

	private Vector2[] _vertices = new Vector2[4];

	private Polygon2DLine[] _sides = new Polygon2DLine[4];

	private Polygon2DProjection[] _projections = new Polygon2DProjection[2];

	public override Rect Bounds
	{
		get
		{
			return _bounds;
		}
		protected set
		{
			_bounds = value;
		}
	}

	public override int VertexCount => 4;

	protected override int SideCount => 4;

	protected override int ProjectionCount => 2;

	public void Set(Rect rect)
	{
		SetVertices(rect.min, new Vector2(rect.xMin, rect.yMax), rect.max, new Vector2(rect.xMax, rect.yMin));
		_bounds = rect;
	}

	public void Set(Vector2 origin, Vector2 direction, float width)
	{
		Vector2 vector = new Vector2(0f - direction.y, direction.x).normalized * width / 2f;
		Vector2 vector2 = origin + vector;
		Vector2 vector3 = origin - vector;
		SetVertices(vector2, vector2 + direction, vector3 + direction, vector3);
		UpdateBounds();
	}

	private void SetVertices(Vector2 vertex0, Vector2 vertex1, Vector2 vertex2, Vector2 vertex3)
	{
		_vertices[0] = vertex0;
		_vertices[1] = vertex1;
		_vertices[2] = vertex2;
		_vertices[3] = vertex3;
		_sides[0] = new Polygon2DLine(vertex3, vertex0);
		_sides[1] = new Polygon2DLine(vertex0, vertex1);
		_sides[2] = new Polygon2DLine(vertex1, vertex2);
		_sides[3] = new Polygon2DLine(vertex2, vertex3);
		UpdateProjections(vertex3, vertex0);
	}

	private void SetVertex(Vector2 vertex, int index)
	{
		_vertices[index] = vertex;
		if (vertex.x < _bounds.xMin)
		{
			_bounds.xMin = vertex.x;
		}
		else if (vertex.x > _bounds.xMax)
		{
			_bounds.xMax = vertex.x;
		}
		if (vertex.y < _bounds.yMin)
		{
			_bounds.yMin = vertex.y;
		}
		else if (vertex.y > _bounds.yMax)
		{
			_bounds.yMax = vertex.y;
		}
	}

	private void UpdateBounds()
	{
		Vector2 vector = _vertices[0];
		_bounds.Set(vector.x, vector.y, 0f, 0f);
		for (int i = 0; i < VertexCount; i++)
		{
			vector = _vertices[i];
			if (vector.x < _bounds.xMin)
			{
				_bounds.xMin = vector.x;
			}
			else if (vector.x > _bounds.xMax)
			{
				_bounds.xMax = vector.x;
			}
			if (vector.y < _bounds.yMin)
			{
				_bounds.yMin = vector.y;
			}
			else if (vector.y > _bounds.yMax)
			{
				_bounds.yMax = vector.y;
			}
		}
	}

	private void UpdateProjections(Vector2 from, Vector2 to)
	{
		Vector2 vector = new Vector2(0f - (to.y - from.y), to.x - from.x);
		_projections[0] = GetProjectionOnAxis(vector.normalized, _vertices);
		vector = new Vector2(vector.y, 0f - vector.x);
		_projections[1] = GetProjectionOnAxis(vector.normalized, _vertices);
	}

	public override Vector2 GetVertex(int index)
	{
		return _vertices[index];
	}

	protected override Polygon2DProjection GetProjection(int index)
	{
		return _projections[index];
	}

	protected override Polygon2DLine GetSide(int index)
	{
		return _sides[index];
	}

	private Polygon2DProjection GetProjectionOnAxis(Vector2 axis, Vector2[] polygon)
	{
		Vector2 vector = polygon[0];
		float num = axis.x * vector.x + axis.y * vector.y;
		float num2 = num;
		float num3 = num;
		int vertexCount = VertexCount;
		for (int i = 1; i < vertexCount; i++)
		{
			vector = polygon[i];
			num = axis.x * vector.x + axis.y * vector.y;
			if (num < num2)
			{
				num2 = num;
			}
			else if (num3 < num)
			{
				num3 = num;
			}
		}
		return new Polygon2DProjection(axis, num2, num3);
	}
}
