[Serializable]
public class MarkerPersistentData : PersistentReference<Marker>
{
	public int PropertiesIndex;

	public Vector3 Position;

	public int ProjectPersistentIndex;

	public int CurrentRadiusIntervalIndex;

	private Dictionary<int, bool> _allowedItemPropertyIndices;

	public MarkerPersistentData(Marker marker)
		: base(marker)
	{
		PropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(marker.MarkerCursorProperties);
		Position = marker.transform.position;
		CurrentRadiusIntervalIndex = marker.CurrentRadiusIntervalIndex;
		PopulateAllowedItemPropertyIndices();
	}

	public void PopulateReferences()
	{
		ProjectPersistentIndex = base.Instance.Project.PersistentIndex;
	}

	private void PopulateAllowedItemPropertyIndices()
	{
		_allowedItemPropertyIndices = new Dictionary<int, bool>();
		foreach (KeyValuePair<ItemProperties, bool> item in base.Instance.ItemFilter)
		{
			int key = GameManager.PersistenceManager.ReturnPropertiesIndex(item.Key);
			_allowedItemPropertyIndices.Add(key, item.Value);
		}
		base.Instance.UpdatedAllowedItemPropertiesEvent.Invoke();
	}

	public override void Restore()
	{
		CursorProperties reference = null;
		if (GameManager.PersistenceManager.TryReturnPropertiesReference<CursorProperties>(PropertiesIndex, out reference))
		{
			MarkerCursorProperties markerCursorProperties = (MarkerCursorProperties)reference;
			Marker markerPrefab = markerCursorProperties.MarkerPrefab;
			base.Instance = UnityEngine.Object.Instantiate(markerPrefab, Position, Quaternion.identity);
			base.Instance.Restore(markerCursorProperties, CurrentRadiusIntervalIndex, ReturnAllowedItemPropertyIndices());
			Community.PlayerCommunity.Markers.Add(base.Instance);
			base.Instance.Community = Community.PlayerCommunity;
			base.Restore();
		}
	}

	private Dictionary<ItemProperties, bool> ReturnAllowedItemPropertyIndices()
	{
		Dictionary<ItemProperties, bool> dictionary = new Dictionary<ItemProperties, bool>();
		foreach (KeyValuePair<int, bool> allowedItemPropertyIndex in _allowedItemPropertyIndices)
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(allowedItemPropertyIndex.Key, out var reference))
			{
				dictionary.Add(reference, allowedItemPropertyIndex.Value);
			}
		}
		return dictionary;
	}

	public void RestoreReferences()
	{
		PersistentReference<Project>.TryReturnReference(ProjectPersistentIndex, out var reference);
		if (reference == null)
		{
			PajamaLlama.Debugs.Debugger.Error("The projectReference in MarkerPersistentData is not found!");
		}
		else
		{
			base.Instance.LinkProject(reference);
		}
	}
}
[Flags]
public enum ProjectAssignmentFlags
{
	None = 0,
	Salvaging = 1
}
[Serializable]
public class ProjectAssignmentPersistentData
{
	[Serializable]
	public struct ItemToHaulData
	{
		public PersistentReference<Item>.Reference Item;

		public SubInventoryType TargetSubInventory;

		[OptionalField(VersionAdded = 2)]
		public bool IsGeneralItem;
	}

	public PersistentReference<Agent>.Reference Agent;

	public int TaskIndex;

	[OptionalField(VersionAdded = 3)]
	public ProjectAssignmentFlags Flags;

	[OptionalField(VersionAdded = 4)]
	public bool IsIdleProject;

	public ItemToHaulData[] ItemsToHaul;

	[OptionalField(VersionAdded = 3)]
	private readonly PersistentReference<Item>.Reference _reservedItem;

	[OptionalField(VersionAdded = 2)]
	public PersistentReference<Boat>.Reference Boat;

	[OptionalField(VersionAdded = 2)]
	public PersistentReference<MooringPoint>.Reference ReservedDisembarkMooringPoint;

	[OptionalField(VersionAdded = 2)]
	public PersistentReference<LandmarkMooringPoint>.Reference ReservedDisembarkLandmarkMooringPoint;

	public ProjectAssignmentPersistentData(ProjectAssignment assignment)
	{
		Agent = assignment.Agent;
		TaskIndex = assignment.ActiveTaskIndex;
		Flags = assignment.Flags;
		IsIdleProject = assignment.IsIdleProject;
		ItemsToHaul = ReturnItemToHaulPersistentData(assignment);
		_reservedItem = assignment.ReservedItem;
		Boat = assignment.Boat;
		PopulateReservedDisembarkMooringPointPersistentData(assignment.ReservedDisembarkMooringPoint);
	}

	private void PopulateReservedDisembarkMooringPointPersistentData(MooringPointBase mooringPoint)
	{
		ReservedDisembarkMooringPoint = mooringPoint as MooringPoint;
		if (ReservedDisembarkMooringPoint.IsNull())
		{
			ReservedDisembarkLandmarkMooringPoint = mooringPoint as LandmarkMooringPoint;
		}
	}

	public void Restore(Project project)
	{
		Agent agent = Agent;
		if (agent == null)
		{
			UnityEngine.Debug.LogException(new Exception($"Unable to restore agent reference for a ProjectAssignement for project '{project.Properties}'"));
			return;
		}
		ProjectAssignment projectAssignment = new ProjectAssignment(project, Agent, TaskIndex, IsIdleProject);
		projectAssignment.SetFlags(Flags);
		Restore(projectAssignment);
		if (project.RestoreAssignment(projectAssignment))
		{
			if (agent.Assignment != null)
			{
				UnityEngine.Debug.LogErrorFormat("'{0}' its assignment to project '{1}' is stopped in favor of its assignment to project '{2}'", agent.Name, agent.Assignment.Project.Properties.name, project.Properties.name);
				agent.Assignment.Stop(ProjectFlags.BugFix);
			}
			agent.Assignment = projectAssignment;
			agent.StartCoroutine(RestoreCoroutine(projectAssignment));
		}
	}

	private void Restore(ProjectAssignment assignment)
	{
		if (Boat != null)
		{
			assignment.RestoreBoat(Boat);
			if (!ReservedDisembarkLandmarkMooringPoint.IsNull())
			{
				assignment.ReserveDisembarkMooringPoint((LandmarkMooringPoint)ReservedDisembarkLandmarkMooringPoint);
			}
		}
		RestoreItemsToHaul(assignment);
		if (_reservedItem != null)
		{
			assignment.RestoreReservedItem(_reservedItem);
		}
	}

	private void RestoreItemsToHaul(ProjectAssignment assignment)
	{
		if (ItemsToHaul == null)
		{
			return;
		}
		ItemToHaulData[] itemsToHaul = ItemsToHaul;
		for (int i = 0; i < itemsToHaul.Length; i++)
		{
			ItemToHaulData itemToHaulData = itemsToHaul[i];
			if (itemToHaulData.Item.IsNull())
			{
				UnityEngine.Debug.LogErrorFormat("Unable to restore ItemToHaul for '{0}' working on project '{1}' because the items persistent reference is 'null'!", assignment.Agent.Name, assignment.Project.Properties.name);
				continue;
			}
			Item item = itemToHaulData.Item;
			if (item == null || item.Owner == null)
			{
				UnityEngine.Debug.LogException(new Exception("Unable to restore ItemToHaul for '" + assignment.Agent.Name + "' working on project '" + assignment.Project.Properties.name + "' because the item could not be restored!"));
			}
			else if (item.Owner.GetComponent<WalkwayPonton>() != null)
			{
				UnityEngine.Debug.LogWarningFormat("Unable to restore ItemToHaul for '{0}' working on project '{1}' because the item was being hauled from WalkwayPonton!", assignment.Agent.Name, assignment.Project.Properties.name);
			}
			else
			{
				assignment.RestoreItemToHaul(item, itemToHaulData.TargetSubInventory, itemToHaulData.IsGeneralItem);
			}
		}
	}

	private IEnumerator RestoreCoroutine(ProjectAssignment assignment)
	{
		while (LoadingScreen.IsLoading)
		{
			yield return null;
		}
		assignment.Agent.UpdateActivity(Activity.Working);
		yield return null;
		yield return new WaitForEndOfFrame();
		if (assignment.Agent.Assignment == assignment && !assignment.Start())
		{
			assignment.Stop(ProjectFlags.BugFix);
		}
	}

	public ItemToHaulData[] ReturnItemToHaulPersistentData(ProjectAssignment assignment)
	{
		if (assignment.ItemsToHaul == null || assignment.ItemsToHaul.Count == 0)
		{
			return null;
		}
		ItemToHaulData[] array = new ItemToHaulData[assignment.ItemsToHaul.Count];
		for (int i = 0; i < array.Length; i++)
		{
			ItemToHaul itemToHaul = assignment.ItemsToHaul[i];
			array[i] = new ItemToHaulData
			{
				Item = itemToHaul.Item,
				TargetSubInventory = itemToHaul.TargetSubInventory,
				IsGeneralItem = itemToHaul.IsGeneralListItem
			};
		}
		return array;
	}
}
[Serializable]
public class ProjectPersistentData : PersistentReference<Project>
{
	[Serializable]
	public struct ItemProjectLink
	{
		public int ItemIndex;

		public ProjectLinkType Link;

		public bool Activated;
	}

	[Serializable]
	public enum ProjectLinkType
	{
		None,
		Single,
		Combined
	}

	public int PropertiesIndex;

	public ProjectTargetPersistentData Target;

	public ProjectAssignmentPersistentData[] Assignments;

	public ItemProjectLink[] GeneralItems;

	[OptionalField(VersionAdded = 1)]
	public ItemProjectLink[] ReservedItems;

	[OptionalField(VersionAdded = 1)]
	public ItemProjectLink[] FinishedItems;

	public int AgentLimit;

	public VitalType Vital;

	[OptionalField(VersionAdded = 2)]
	public AssignmentType AdditionlAssignmentTypes;

	public bool Locked;

	public ProjectPersistentData(Project project)
		: base(project)
	{
		PropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(project.Properties);
		Target = new ProjectTargetPersistentData(project.Target, project.Properties.AllowTargetTypeNull);
		GeneralItems = ReturnItemProjectLinks(project, project.GeneralItems);
		AgentLimit = project.AssignmentLimit;
		Vital = project.Vital;
		AdditionlAssignmentTypes = project.Properties.AssignmentType ^ project.AssignmentTypes;
		int count = project.Assignments.Count;
		Assignments = new ProjectAssignmentPersistentData[count];
		for (int i = 0; i < count; i++)
		{
			Assignments[i] = new ProjectAssignmentPersistentData(project.Assignments[i]);
		}
	}

	public void PopulateReferences()
	{
		if (Target.IsNull())
		{
			Target = new ProjectTargetPersistentData(base.Instance.Target, base.Instance.Properties.AllowTargetTypeNull);
		}
	}

	public bool TryRestore(out Project project, bool communityProject)
	{
		project = null;
		if (!GameManager.PersistenceManager.TryReturnPropertiesReference<ProjectProperties>(PropertiesIndex, out var reference))
		{
			UnityEngine.Debug.LogError("Unable to find reference to project properties!");
			return false;
		}
		return TryRestore(out project, reference, communityProject);
	}

	public bool TryRestore(out Project project, ProjectProperties properties, bool communityProject)
	{
		base.Restore();
		project = null;
		if (communityProject && properties.AssignmentType == AssignmentType.None && AdditionlAssignmentTypes == AssignmentType.None)
		{
			UnityEngine.Debug.LogException(new Exception($"Project '{properties}' with assignment type 'NONE' was persisted as part of the communities project queue, this should no longer be possible post 0.3.1e5!"));
			return false;
		}
		if (!Target.TryRestore(out var target, properties.AllowTargetTypeNull))
		{
			UnityEngine.Debug.LogException(new Exception($"Unable to restore target for project '{properties}'!"));
			return false;
		}
		base.Instance = new Project(properties, target, RestoreItemList(GeneralItems));
		base.Instance.SalvageTarget = RestoreSalvageTarget(target);
		base.Instance.AssignmentLimit = AgentLimit;
		base.Instance.AddAssignmentType(AdditionlAssignmentTypes);
		base.Instance.Vital = ((Vital == VitalType.Pollution) ? VitalType.None : Vital);
		RestoreAssignments(base.Instance);
		project = base.Instance;
		return true;
	}

	public void RestoreAssignments(Project project)
	{
		ProjectAssignmentPersistentData[] assignments = Assignments;
		for (int i = 0; i < assignments.Length; i++)
		{
			assignments[i].Restore(project);
		}
	}

	private ItemProjectLink[] ReturnItemProjectLinks(Project project, List<Item> items)
	{
		int count = items.Count;
		ItemProjectLink[] array = new ItemProjectLink[count];
		for (int i = 0; i < count; i++)
		{
			Item item = items[i];
			array[i] = new ItemProjectLink
			{
				ItemIndex = item.PersistentIndex
			};
		}
		return array;
	}

	private List<Item> RestoreItemList(ItemProjectLink[] links)
	{
		int num = links.Length;
		List<Item> list = new List<Item>(num);
		for (int i = 0; i < num; i++)
		{
			if (PersistentReference<Item>.TryReturnReference(links[i].ItemIndex, out var reference))
			{
				list.Add(reference);
			}
		}
		return list;
	}

	private ISalvageTarget RestoreSalvageTarget(GameObject target)
	{
		if ((bool)target)
		{
			ISalvageTarget componentInChildren = target.GetComponentInChildren<ISalvageTarget>();
			if (componentInChildren != null)
			{
				return componentInChildren;
			}
			Landmark componentInChildren2 = target.GetComponentInChildren<Landmark>();
			if ((bool)componentInChildren2 && componentInChildren2.Behaviour is ActionsBehaviour actionsBehaviour && actionsBehaviour.TryReturnAction<LandmarkActionSalvage>(out var action, includeCompleted: true))
			{
				return action;
			}
		}
		return null;
	}
}
[Serializable]
public class ProjectTargetPersistentData
{
	public enum TargetType
	{
		None,
		Null,
		Flotsam,
		Construction,
		Boat,
		Agent,
		Marker,
		Landmark,
		Decoration
	}

	public TargetType Type;

	public int CommunityPersistentIndex;

	public int PersistentIndex;

	public ProjectTargetPersistentData(GameObject target, bool allowTargetTypeNull)
	{
		PersistentIndex = ReturnTargetPersistentIndex(target, allowTargetTypeNull, out Type, out CommunityPersistentIndex);
	}

	public bool TryRestore(out GameObject target, bool allowTargetTypeNull)
	{
		target = null;
		switch (Type)
		{
		case TargetType.Null:
			if (!allowTargetTypeNull)
			{
				UnityEngine.Debug.LogException(new NotImplementedException("A null reference was persisted as project target!"));
			}
			return allowTargetTypeNull;
		case TargetType.Flotsam:
		{
			if (PersistentReference<Flotsam>.TryReturnReference(PersistentIndex, out var reference7))
			{
				target = reference7.gameObject;
				return true;
			}
			UnityEngine.Debug.LogException(new NotImplementedException($"Unable to restore {Type} as project target!"));
			return false;
		}
		default:
		{
			if (Type != TargetType.Landmark && !Community.Communities.TryGetValueAtIndex(CommunityPersistentIndex, out var _))
			{
				UnityEngine.Debug.LogException(new NotImplementedException("Unable to restore project target, community could not be found!"));
				return false;
			}
			target = Type switch
			{
				TargetType.Boat => PersistentReference<Boat>.TryReturnReference(PersistentIndex, out var reference) ? reference.gameObject : null, 
				TargetType.Construction => PersistentReference<Construction>.TryReturnReference(PersistentIndex, out var reference2) ? reference2.gameObject : null, 
				TargetType.Agent => PersistentReference<Agent>.TryReturnReference(PersistentIndex, out var reference3) ? reference3.gameObject : null, 
				TargetType.Marker => PersistentReference<Marker>.TryReturnReference(PersistentIndex, out var reference4) ? reference4.gameObject : null, 
				TargetType.Landmark => PersistentReference<Landmark>.TryReturnReference(PersistentIndex, out var reference5) ? reference5.gameObject : null, 
				TargetType.Decoration => PersistentReference<Decoration>.TryReturnReference(PersistentIndex, out var reference6) ? reference6.gameObject : null, 
				_ => null, 
			};
			if (target == null)
			{
				UnityEngine.Debug.LogException(new NotImplementedException($"Unable to restore {Type} as project target!"));
				return false;
			}
			return true;
		}
		}
	}

	public int ReturnTargetPersistentIndex(GameObject target, bool allowTargetTypeNull, out TargetType type, out int communityPersistentIndex)
	{
		type = TargetType.None;
		communityPersistentIndex = -1;
		int num = -1;
		Flotsam component;
		Boat component2;
		Construction component3;
		Agent component4;
		Marker component5;
		Landmark component6;
		Decoration component7;
		if (target == null)
		{
			type = TargetType.Null;
		}
		else if (target.TryGetComponent<Flotsam>(out component))
		{
			type = TargetType.Flotsam;
			num = component.PersistentIndex;
		}
		else if (target.TryGetComponent<Boat>(out component2))
		{
			type = TargetType.Boat;
			communityPersistentIndex = Community.ReturnCommunityIndex(component2.Buildable.Community);
			num = component2.PersistentIndex;
		}
		else if (target.TryGetComponent<Construction>(out component3))
		{
			type = TargetType.Construction;
			communityPersistentIndex = Community.ReturnCommunityIndex(component3.Buildable.Community);
			num = component3.PersistentIndex;
		}
		else if (target.TryGetComponent<Agent>(out component4))
		{
			type = TargetType.Agent;
			communityPersistentIndex = Community.ReturnCommunityIndex(component4.Community);
			num = component4.PersistentIndex;
		}
		else if (target.TryGetComponent<Marker>(out component5))
		{
			type = TargetType.Marker;
			communityPersistentIndex = Community.ReturnCommunityIndex(component5.Community);
			num = component5.PersistentIndex;
		}
		else if (target.TryGetComponent<Landmark>(out component6))
		{
			type = TargetType.Landmark;
			communityPersistentIndex = -1;
			num = component6.PersistentIndex;
		}
		else if (target.TryGetComponent<Decoration>(out component7))
		{
			type = TargetType.Decoration;
			communityPersistentIndex = Community.ReturnCommunityIndex(component7.Community);
			num = component7.PersistentIndex;
		}
		if (num == -1 && !allowTargetTypeNull)
		{
			UnityEngine.Debug.LogException(new NotImplementedException($"Target \"{target}\" does not have a valid target component; persistence will not work as intended!"));
		}
		return num;
	}
}
