[Serializable]
public struct CountedItemPersistentData
{
	public int Count;

	private int _propertiesIndex;

	public CountedItemPersistentData(ItemProperties itemProperties, int count)
	{
		Count = count;
		_propertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(itemProperties);
	}

	public CountedItemPersistentData(InventoryAuditor.CountedItem countedItem)
		: this(countedItem.ItemProperties, countedItem.ReturnCount(InventoryAuditor.CountType.All))
	{
	}

	public CountedItemPersistentData(KeyValuePair<ItemProperties, int> countedItem)
		: this(countedItem.Key, countedItem.Value)
	{
	}

	public bool TryRestoreItemProperties(out ItemProperties itemProperties)
	{
		return GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(_propertiesIndex, out itemProperties);
	}

	public static CountedItemPersistentData[] GenerateFromInventoryAuditor(InventoryAuditor auditor)
	{
		using ListPool<CountedItemPersistentData>.List list = ListPool<CountedItemPersistentData>.Get();
		foreach (InventoryAuditor.CountedItem countedItem in auditor.CountedItems)
		{
			if (countedItem.ReturnCount(InventoryAuditor.CountType.All) != 0)
			{
				list.Add(new CountedItemPersistentData(countedItem));
			}
		}
		return list.ToArray();
	}

	public static CountedItemPersistentData[] FromDictionary(Dictionary<ItemProperties, int> countedItemDictionary)
	{
		if (countedItemDictionary.IsNullOrEmpty())
		{
			return null;
		}
		CountedItemPersistentData[] array = new CountedItemPersistentData[countedItemDictionary.Count];
		int num = 0;
		foreach (KeyValuePair<ItemProperties, int> item in countedItemDictionary)
		{
			array[num++] = new CountedItemPersistentData(item);
		}
		return array;
	}

	public static Dictionary<ItemProperties, int> ToDictionary(CountedItemPersistentData[] persistentData)
	{
		Dictionary<ItemProperties, int> dictionary;
		if (((IReadOnlyCollection<CountedItemPersistentData>)(object)persistentData).IsNullOrEmpty())
		{
			dictionary = new Dictionary<ItemProperties, int>();
		}
		else
		{
			dictionary = new Dictionary<ItemProperties, int>(persistentData.Length);
			for (int i = 0; i < persistentData.Length; i++)
			{
				CountedItemPersistentData countedItemPersistentData = persistentData[i];
				if (countedItemPersistentData.TryRestoreItemProperties(out var itemProperties))
				{
					dictionary.Add(itemProperties, countedItemPersistentData.Count);
				}
			}
		}
		return dictionary;
	}
}
[Serializable]
public class InventoryPersistentData
{
	[OptionalField]
	private SubInventoryPersistentData[] _subInventories;

	public ItemPersistentData[] Storage;

	public int[] IncomingStorage;

	public ItemPersistentData[] Composition;

	public int[] IncomingComposition;

	public ItemPersistentData[] Resources;

	public int[] IncomingResources;

	public ItemPersistentData[] Import;

	public int[] IncomingImport;

	public ItemPersistentData[] Export;

	public int[] IncomingExport;

	public ItemPersistentData[] Liquid;

	public int[] IncomingLiquid;

	public ItemPersistentData[] Upgrade;

	public int[] IncomingUpgrade;

	public int[] FilterItemPropertyIndices;

	[NonSerialized]
	private Inventory _instance;

	public static List<InventoryPersistentData> RestoredInventories;

	public static UnityEvent RestoreReferencesEvent;

	public static List<InventoryPersistentData> SavedInventories;

	public static UnityEvent PopulateReferencesEvent;

	public static void InitializeRestoredInventories()
	{
		if (RestoredInventories == null)
		{
			RestoredInventories = new List<InventoryPersistentData>();
		}
		else
		{
			RestoredInventories.Clear();
		}
		if (RestoreReferencesEvent == null)
		{
			RestoreReferencesEvent = new UnityEvent();
		}
		else
		{
			RestoreReferencesEvent.RemoveAllListeners();
		}
	}

	public static void InitialzeSavedInventories()
	{
		if (SavedInventories == null)
		{
			SavedInventories = new List<InventoryPersistentData>();
		}
		else
		{
			SavedInventories.Clear();
		}
		if (PopulateReferencesEvent == null)
		{
			PopulateReferencesEvent = new UnityEvent();
		}
		else
		{
			PopulateReferencesEvent.RemoveAllListeners();
		}
	}

	public InventoryPersistentData(Inventory inventory)
	{
		if (inventory == null)
		{
			return;
		}
		_instance = inventory;
		using ListPool<SubInventoryPersistentData>.List list = ListPool<SubInventoryPersistentData>.Get(8);
		foreach (SubInventoryType subInventoryType in inventory.SubInventoryTypes)
		{
			SubInventoryPersistentData subInventoryPersistentData = SubInventoryPersistentData.Get(inventory, subInventoryType);
			if (subInventoryPersistentData != null)
			{
				list.Add(subInventoryPersistentData);
			}
		}
		_subInventories = list.ToArray();
	}

	public static void PopulateAllReferences()
	{
		PopulateReferencesEvent?.Invoke();
	}

	public void Restore(Inventory inventory, GameObject owner)
	{
		_instance = inventory;
		if (_subInventories == null)
		{
			RestoreList(inventory, SubInventoryType.Storage, Storage);
			RestoreList(inventory, SubInventoryType.Composition, Composition);
			RestoreList(inventory, SubInventoryType.Resources, Resources);
			RestoreList(inventory, SubInventoryType.Import, Import);
			RestoreList(inventory, SubInventoryType.Export, Export);
			RestoreList(inventory, SubInventoryType.Liquid, Liquid);
		}
		else
		{
			SubInventoryPersistentData[] subInventories = _subInventories;
			for (int i = 0; i < subInventories.Length; i++)
			{
				subInventories[i].Restore(inventory);
			}
		}
		if (RestoredInventories != null)
		{
			RestoredInventories.Add(this);
		}
	}

	public static void RestoreAllReferences()
	{
		for (int i = 0; i < RestoredInventories.Count; i++)
		{
			RestoredInventories[i].RestoreReferences();
		}
		RestoreReferencesEvent?.Invoke();
	}

	private void RestoreReferences()
	{
		if (_subInventories == null)
		{
			RestoreIncomingReferences(_instance, IncomingStorage, SubInventoryType.Storage);
			RestoreIncomingReferences(_instance, IncomingComposition, SubInventoryType.Composition);
			RestoreIncomingReferences(_instance, IncomingResources, SubInventoryType.Resources);
			RestoreIncomingReferences(_instance, IncomingImport, SubInventoryType.Import);
			RestoreIncomingReferences(_instance, IncomingExport, SubInventoryType.Export);
			RestoreIncomingReferences(_instance, IncomingLiquid, SubInventoryType.Liquid);
		}
	}

	private void RestoreList(Inventory inventory, SubInventoryType subInventory, ItemPersistentData[] items)
	{
		inventory.GetOrAddSubInventory(subInventory);
		if (items == null)
		{
			return;
		}
		int num = items.Length;
		int num2 = 0;
		for (int i = 0; i < num; i++)
		{
			if (items[i].TryRestore(subInventory != SubInventoryType.Composition, inventory, subInventory, out var item))
			{
				inventory.AddItem(item, subInventory);
				num2++;
			}
		}
		if (num2 != num)
		{
			PajamaLlama.Debugs.Debugger.Warning("Not all items could be restored to inventory: " + inventory.name);
		}
	}

	private void RestoreIncomingReferences(Inventory inventory, int[] indices, SubInventoryType type)
	{
		if (indices == null)
		{
			return;
		}
		for (int i = 0; i < indices.Length; i++)
		{
			if (PersistentReference<Item>.TryReturnReference(indices[i], out var reference))
			{
				_instance.RestoreIncomingItem(reference, type);
			}
		}
	}

	public CountedItemProperty[] ReturnCountedItems(SubInventoryType subInventoryType)
	{
		if (_subInventories == null)
		{
			if (subInventoryType == SubInventoryType.Composition)
			{
				return ReturnCountedItems(Composition);
			}
		}
		else
		{
			SubInventoryPersistentData[] subInventories = _subInventories;
			foreach (SubInventoryPersistentData subInventoryPersistentData in subInventories)
			{
				if (subInventoryPersistentData.SubInventoryType == subInventoryType)
				{
					return ReturnCountedItems(subInventoryPersistentData.Items);
				}
			}
		}
		UnityEngine.Debug.LogException(new NotImplementedException());
		return null;
	}

	private CountedItemProperty[] ReturnCountedItems(ItemPersistentData[] items)
	{
		using ListPool<int>.List list = ListPool<int>.Get();
		if (!((IReadOnlyCollection<ItemPersistentData>)(object)items).IsNullOrEmpty())
		{
			ItemPersistentData[] array = items;
			foreach (ItemPersistentData itemPersistentData in array)
			{
				if (!list.Contains(itemPersistentData.PropertiesIndex))
				{
					list.Add(itemPersistentData.PropertiesIndex);
				}
			}
		}
		CountedItemProperty[] array2 = new CountedItemProperty[list.Count];
		for (int j = 0; j < list.Count; j++)
		{
			int num = list[j];
			if (!GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(num, out var reference))
			{
				UnityEngine.Debug.LogError("Unable to count ItemPersistentData, because ItemProperties could not be restored!");
				continue;
			}
			int num2 = 0;
			ItemPersistentData[] array = items;
			for (int i = 0; i < array.Length; i++)
			{
				if (array[i].PropertiesIndex == num)
				{
					num2++;
				}
			}
			array2[j] = new CountedItemProperty(reference, num2);
		}
		return array2;
	}
}
[Serializable]
public class InventorySlotPersistentData
{
	public int ItemPropertiesIndex;

	public int Count;

	public InventorySlotPersistentData(InventorySlot inventorySlot)
	{
		if (inventorySlot.ItemProperties == null || inventorySlot.Count == 0)
		{
			ItemPropertiesIndex = -1;
			Count = 0;
		}
		else
		{
			ItemPropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(inventorySlot.ItemProperties);
			Count = inventorySlot.Count;
		}
	}

	public void Restore(InventorySlot inventorySlot)
	{
		if (ItemPropertiesIndex == -1)
		{
			return;
		}
		if (!GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(ItemPropertiesIndex, out var reference))
		{
			PajamaLlama.Debugs.Debugger.Warning("ItemPropertiesIndex is out of bounds. Save game mismatch!");
			return;
		}
		for (int i = 0; i < Count; i++)
		{
			if (!inventorySlot.AddItem(new Item(reference)))
			{
				PajamaLlama.Debugs.Debugger.Warning("Item could not be added to InventorySlot!");
			}
		}
	}
}
[Serializable]
public class ItemFilterPersistentData
{
	private Dictionary<int, bool> _itemFilter;

	[OptionalField(VersionAdded = 2)]
	private int _categoryIndex;

	public int CategoryIndex => _categoryIndex;

	public ItemFilterPersistentData(Dictionary<ItemProperties, bool> itemFilter, int categoryIndex = 0)
	{
		Dictionary<ItemProperties, bool>.Enumerator enumerator = itemFilter.GetEnumerator();
		_itemFilter = new Dictionary<int, bool>(itemFilter.Count);
		_categoryIndex = categoryIndex;
		while (enumerator.MoveNext())
		{
			int num = GameManager.PersistenceManager.ReturnPropertiesIndex(enumerator.Current.Key);
			if (num != -1)
			{
				_itemFilter.Add(num, enumerator.Current.Value);
			}
		}
	}

	public void Restore(Dictionary<ItemProperties, bool> itemFilter)
	{
		if (_itemFilter == null)
		{
			return;
		}
		Dictionary<int, bool>.Enumerator enumerator = _itemFilter.GetEnumerator();
		while (enumerator.MoveNext())
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(enumerator.Current.Key, out var reference) && itemFilter.ContainsKey(reference))
			{
				itemFilter[reference] = enumerator.Current.Value;
			}
		}
	}
}
[Serializable]
public class ItemPersistentData : PersistentReference<Item>
{
	public int PropertiesIndex;

	public bool IsReserved;

	public bool IsSalvageAble;

	public ItemPersistentData(Item item)
		: base(item)
	{
		PropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(item.Properties);
		IsReserved = item.IsReserved;
		IsSalvageAble = item.IsSalvageAble;
	}

	public bool TryRestore(bool filterSuperItems, out Item item)
	{
		if (GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(PropertiesIndex, out var reference))
		{
			if (filterSuperItems && reference.IsSuperItem && reference.TryReturnSubItemProperties(out var subItemProperties))
			{
				reference = subItemProperties;
			}
			item = new Item(reference);
			base.Instance = item;
			if (IsReserved)
			{
				base.Instance.Reserve();
			}
			item.IsSalvageAble = IsSalvageAble;
			base.Restore();
			return true;
		}
		item = null;
		return false;
	}

	public bool TryRestore(bool filterSuperItems, Inventory inventory, SubInventoryType subInventoryType, out Item item)
	{
		if (GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(PropertiesIndex, out var reference))
		{
			if (filterSuperItems && reference.IsSuperItem && reference.TryReturnSubItemProperties(out var subItemProperties))
			{
				reference = subItemProperties;
			}
			item = new Item(reference);
			if (!inventory.FitsInInventory(item, subInventoryType))
			{
				item = null;
				return false;
			}
			base.Instance = item;
			if (IsReserved)
			{
				base.Instance.Reserve();
			}
			item.IsSalvageAble = IsSalvageAble;
			base.Restore();
			return true;
		}
		item = null;
		return false;
	}

	public static ItemPersistentData[] FromItems(List<Item> items)
	{
		if (items.IsNullOrEmpty())
		{
			return null;
		}
		int count = items.Count;
		ItemPersistentData[] array = new ItemPersistentData[count];
		for (int i = 0; i < count; i++)
		{
			array[i] = new ItemPersistentData(items[i]);
		}
		return array;
	}

	public static ListPool<Item>.List ToItems(ItemPersistentData[] data)
	{
		if (((IReadOnlyCollection<ItemPersistentData>)(object)data).IsNullOrEmpty())
		{
			return null;
		}
		ListPool<Item>.List list = ListPool<Item>.Get(data.Length);
		for (int i = 0; i < data.Length; i++)
		{
			if (data[i].TryRestore(filterSuperItems: true, out var item))
			{
				list.Add(item);
			}
		}
		return list;
	}

	public static int[] ToIndices(List<Item> items)
	{
		if (items.IsNullOrEmpty())
		{
			return null;
		}
		int count = items.Count;
		int[] array = new int[count];
		for (int i = 0; i < count; i++)
		{
			array[i] = items[i].PersistentIndex;
		}
		return array;
	}

	public static ListPool<Item>.List ToItems(int[] indices)
	{
		if (indices == null)
		{
			return null;
		}
		ListPool<Item>.List list = ListPool<Item>.Get(indices.Length);
		for (int i = 0; i < indices.Length; i++)
		{
			if (PersistentReference<Item>.TryReturnReference(indices[i], out var reference))
			{
				list.Add(reference);
			}
		}
		return list;
	}
}
[Serializable]
public class SubInventoryPersistentData
{
	public SubInventoryType SubInventoryType;

	public ItemPersistentData[] Items;

	public int[] IncomingItems;

	[NonSerialized]
	private Inventory _inventory;

	[NonSerialized]
	private SubInventory _subInventory;

	private SubInventoryPersistentData(SubInventory subInventory)
	{
		_subInventory = subInventory;
		SubInventoryType = subInventory.Type;
		using ListPool<Item>.List list = ListPool<Item>.Get(subInventory.Count);
		subInventory.ReturnAllItems(list);
		Items = ItemPersistentData.FromItems(list);
		if (!subInventory.IncomingItems.IsNullOrEmpty())
		{
			InventoryPersistentData.PopulateReferencesEvent.AddListener(PopulateReferences);
		}
	}

	public void Restore(Inventory inventory)
	{
		_inventory = inventory;
		_subInventory = _inventory.GetOrAddSubInventory(SubInventoryType);
		if (_subInventory == null)
		{
			UnityEngine.Debug.LogErrorFormat("Unable to restore subInventory '{0}', because it was not initialized.", SubInventoryType);
			return;
		}
		using ListPool<Item>.List list = ItemPersistentData.ToItems(Items);
		if (list != null)
		{
			if (list.Count > _subInventory.Capacity)
			{
				UnityEngine.Debug.LogException(new Exception($"Inventory '{inventory}' is being restored with an amount of items ({list.Count}) exceeding its capacity ({_subInventory.Capacity})."), inventory);
			}
			foreach (Item item in list)
			{
				inventory.RestoreItem(item, _subInventory);
			}
		}
		if (!((IReadOnlyCollection<int>)(object)IncomingItems).IsNullOrEmpty())
		{
			InventoryPersistentData.RestoreReferencesEvent.AddListener(RestoreReferences);
		}
	}

	private void PopulateReferences()
	{
		InventoryPersistentData.PopulateReferencesEvent.RemoveListener(PopulateReferences);
		if (_subInventory != null)
		{
			IncomingItems = ItemPersistentData.ToIndices(_subInventory.IncomingItems);
		}
	}

	private void RestoreReferences()
	{
		InventoryPersistentData.RestoreReferencesEvent.RemoveListener(RestoreReferences);
		if (_inventory == null)
		{
			return;
		}
		using ListPool<Item>.List list = ItemPersistentData.ToItems(IncomingItems);
		if (list == null)
		{
			return;
		}
		foreach (Item item in list)
		{
			_inventory.RestoreIncomingItem(item, SubInventoryType);
		}
	}

	public static SubInventoryPersistentData Get(Inventory inventory, SubInventoryType subInventoryType)
	{
		SubInventory subInventory = inventory.ReturnInventory(subInventoryType);
		if (subInventory == null)
		{
			return null;
		}
		return new SubInventoryPersistentData(subInventory);
	}
}
[Serializable]
public class LandmarkActionPersistentData
{
	public enum LandmarkActionId
	{
		None,
		Salvage,
		RevealMap,
		Rescue,
		AnimalRescue
	}

	public LandmarkActionId Id;

	public ILandmarkActionStates State;

	public PersistentReference<Project>.Reference Project;

	[OptionalField(VersionAdded = 3)]
	public bool UseBoat;

	[OptionalField(VersionAdded = 2)]
	public int Version;

	[NonSerialized]
	protected LandmarkAction _action;

	public LandmarkActionPersistentData(LandmarkAction action)
	{
		_action = action;
		Id = ReturnId(action);
		State = _action.State;
		UseBoat = action.UseBoat;
		Version = 1;
	}

	public virtual void PopulateReferences()
	{
		if ((bool)_action)
		{
			Project = _action.Project;
		}
		else
		{
			UnityEngine.Debug.LogWarning("Unable to PopulateReferences, reference to LandmarkAction is NULL!");
		}
	}

	public bool Restore(LandmarkAction action, LandmarkBehaviour landmarkBehaviour)
	{
		if (Version == 0)
		{
			return RestoreVersion0(action, landmarkBehaviour);
		}
		if (Id == LandmarkActionId.AnimalRescue)
		{
			Id = LandmarkActionId.Rescue;
		}
		if (ReturnId(action) == Id)
		{
			_action = action;
			_action.Restore(this, landmarkBehaviour);
			return true;
		}
		return false;
	}

	public void RestoreReferences()
	{
		_action?.RestoreReferences(this);
	}

	protected LandmarkActionId ReturnId(LandmarkAction action)
	{
		if (action is LandmarkActionSalvage)
		{
			return LandmarkActionId.Salvage;
		}
		if (action is LandmarkActionRescue)
		{
			return LandmarkActionId.Rescue;
		}
		if (action is LandmarkActionAnimalRescue)
		{
			return LandmarkActionId.AnimalRescue;
		}
		if (action is LandmarkActionRevealMap)
		{
			return LandmarkActionId.RevealMap;
		}
		UnityEngine.Debug.LogErrorFormat("No LandmarkActionId defined for '{0}'.", action.GetType().Name);
		return LandmarkActionId.None;
	}

	private bool RestoreVersion0(LandmarkAction action, LandmarkBehaviour landmarkBehaviour)
	{
		if (ReturnIdVersion0(action) == Id)
		{
			_action = action;
			_action.Restore(this, landmarkBehaviour);
			return true;
		}
		return false;
	}

	protected LandmarkActionId ReturnIdVersion0(LandmarkAction action)
	{
		if (action is LandmarkActionSalvage)
		{
			return LandmarkActionId.Salvage;
		}
		if (action is LandmarkActionRescue)
		{
			return LandmarkActionId.Rescue;
		}
		return LandmarkActionId.None;
	}
}
[Serializable]
public class LandmarkActionSalvagePersistentData : LandmarkActionPersistentData
{
	public int AgentLimit;

	[OptionalField(VersionAdded = 3)]
	public List<int> UnlockedCategories;

	[OptionalField(VersionAdded = 5)]
	public List<int> ToggledCategories;

	[OptionalField(VersionAdded = 4)]
	public List<ItemFilterPersistentData> CategoryItemFilters;

	[OptionalField(VersionAdded = 2)]
	public ItemFilterPersistentData ItemFilter;

	public LandmarkActionSalvagePersistentData(LandmarkAction action)
		: base(action)
	{
		LandmarkActionSalvage landmarkActionSalvage = action as LandmarkActionSalvage;
		AgentLimit = landmarkActionSalvage.AssignmentLimit;
		ItemFilter = ((landmarkActionSalvage.ItemFilter == null) ? null : new ItemFilterPersistentData(landmarkActionSalvage.ItemFilter));
		CategoryItemFilters = new List<ItemFilterPersistentData>();
		for (int i = 0; i < landmarkActionSalvage.Categories.Count; i++)
		{
			LandmarkActionSalvage.Category category = landmarkActionSalvage.Categories[i];
			int num = GameManager.PersistenceManager.ReturnPropertiesIndex(category.CategoryAsset);
			if (category.RequiresItem && category.Unlocked)
			{
				if (UnlockedCategories == null)
				{
					UnlockedCategories = new List<int>();
				}
				UnlockedCategories.Add(num);
			}
			if (category.IsToggled)
			{
				if (ToggledCategories == null)
				{
					ToggledCategories = new List<int>();
				}
				ToggledCategories.Add(num);
			}
			CategoryItemFilters.Add(new ItemFilterPersistentData(category.ItemFilter, num));
		}
	}

	public void RestoreCategoryItemFilter(LandmarkSalvageableCategory category, Dictionary<ItemProperties, bool> itemFilter)
	{
		if (CategoryItemFilters.IsNullOrEmpty())
		{
			return;
		}
		int num = GameManager.PersistenceManager.ReturnPropertiesIndex(category);
		foreach (ItemFilterPersistentData categoryItemFilter in CategoryItemFilters)
		{
			if (categoryItemFilter.CategoryIndex == num)
			{
				categoryItemFilter.Restore(itemFilter);
				break;
			}
		}
	}

	public bool IsCategoryUnlocked(LandmarkSalvageableCategory category)
	{
		if (!UnlockedCategories.IsNullOrEmpty())
		{
			return UnlockedCategories.Contains(GameManager.PersistenceManager.ReturnPropertiesIndex(category));
		}
		return false;
	}

	public bool IsCategoryToggled(LandmarkSalvageableCategory category)
	{
		if (!ToggledCategories.IsNullOrEmpty())
		{
			return ToggledCategories.Contains(GameManager.PersistenceManager.ReturnPropertiesIndex(category));
		}
		return false;
	}
}
[Serializable]
public class LandmarkActionsBehaviourPersistentData
{
	private LandmarkActionPersistentData[] _actions;

	public LandmarkActionsBehaviourPersistentData(ActionsBehaviour behaviour)
	{
		_actions = new LandmarkActionPersistentData[behaviour.Actions.Count];
		for (int i = 0; i < _actions.Length; i++)
		{
			_actions[i] = behaviour.Actions[i].ReturnLandmarkActionPersistentData();
		}
	}

	public void PopulateReferences()
	{
		for (int i = 0; i < _actions.Length; i++)
		{
			_actions[i].PopulateReferences();
		}
	}

	public void Restore(ActionsBehaviour behaviour)
	{
		if (behaviour == null)
		{
			return;
		}
		foreach (LandmarkAction action in behaviour.Actions)
		{
			if (!RestoreLandmarkAction(action, behaviour))
			{
				action.OnLandmarkSpawned();
			}
		}
	}

	private bool RestoreLandmarkAction(LandmarkAction action, ActionsBehaviour behaviour)
	{
		LandmarkActionPersistentData[] actions = _actions;
		for (int i = 0; i < actions.Length; i++)
		{
			if (actions[i].Restore(action, behaviour))
			{
				return true;
			}
		}
		return false;
	}

	public void RestoreReferences()
	{
		LandmarkActionPersistentData[] actions = _actions;
		for (int i = 0; i < actions.Length; i++)
		{
			actions[i].RestoreReferences();
		}
	}

	public bool TryGetActionPersistentData<T>(out T data) where T : LandmarkActionPersistentData
	{
		LandmarkActionPersistentData[] actions = _actions;
		for (int i = 0; i < actions.Length; i++)
		{
			if (actions[i] is T val)
			{
				data = val;
				return true;
			}
		}
		data = null;
		return false;
	}
}
