public class LandmarkRescueablePersistentData : ILandmarkInteractablePersistentData
{
	private AgentPersistentData[] _agents;

	private BirdPersistentData[] _birds;

	public void Restore(Landmark landmark)
	{
		LandmarkRescueable[] componentsInChildren = landmark.GetComponentsInChildren<LandmarkRescueable>();
		for (int i = 0; i < componentsInChildren.Length; i++)
		{
			if (_agents != null && i < _agents.Length)
			{
				AgentPersistentData agentPersistentData = _agents[i];
				if (agentPersistentData != null)
				{
					agentPersistentData.Restore(null);
					componentsInChildren[i].Restore(agentPersistentData.Instance);
					continue;
				}
			}
			if (_birds != null && i < _birds.Length)
			{
				BirdPersistentData birdPersistentData = _birds[i];
				if (birdPersistentData != null)
				{
					birdPersistentData.Restore(null);
					componentsInChildren[i].Restore(birdPersistentData.Instance);
				}
			}
		}
	}
}
[Serializable]
public class LandmarkSalvageablePersistentData : ILandmarkInteractablePersistentData
{
	private InventoryPersistentData[] _inventories;

	[OptionalField(VersionAdded = 2)]
	private int[] _variationIndices;

	public LandmarkSalvageablePersistentData()
	{
	}

	public LandmarkSalvageablePersistentData(Landmark landmark)
	{
		LandmarkSalvageable[] componentsInChildren = landmark.GetComponentsInChildren<LandmarkSalvageable>();
		int num = componentsInChildren.Length;
		if (componentsInChildren == null || num == 0)
		{
			_inventories = null;
			_variationIndices = null;
			return;
		}
		_inventories = new InventoryPersistentData[num];
		_variationIndices = new int[num];
		for (int i = 0; i < num; i++)
		{
			LandmarkSalvageable landmarkSalvageable = componentsInChildren[i];
			_inventories[i] = new InventoryPersistentData(landmarkSalvageable.Inventory);
			_variationIndices[i] = landmarkSalvageable.VariationIndex;
		}
	}

	public void Restore(Landmark landmark)
	{
		LandmarkSalvageable[] componentsInChildren = landmark.GetComponentsInChildren<LandmarkSalvageable>();
		int i = 0;
		if (_inventories == null)
		{
			return;
		}
		if (_variationIndices != null)
		{
			for (; i < _inventories.Length; i++)
			{
				if (i < componentsInChildren.Length)
				{
					componentsInChildren[i].Restore(_inventories[i], _variationIndices[i]);
				}
			}
			return;
		}
		for (; i < _inventories.Length; i++)
		{
			if (i < componentsInChildren.Length)
			{
				componentsInChildren[i].Restore(_inventories[i], -1);
			}
		}
	}

	public bool TryReturnVariationIndexAndCompositionItems(int index, out int variationIndex, out CountedItemProperty[] compositionItems)
	{
		compositionItems = null;
		variationIndex = -1;
		if (((IReadOnlyCollection<InventoryPersistentData>)(object)_inventories).IsNullOrEmpty() || ((IReadOnlyCollection<int>)(object)_variationIndices).IsNullOrEmpty())
		{
			return false;
		}
		if (0 <= index && index < _inventories.Length && index < _variationIndices.Length)
		{
			compositionItems = _inventories[index].ReturnCountedItems(SubInventoryType.Composition);
			variationIndex = _variationIndices[index];
		}
		return compositionItems != null;
	}
}
[Serializable]
public class LandmarkScavengeablePersistentData : ILandmarkInteractablePersistentData
{
	private InventoryPersistentData[] _inventories;

	private int[] _researchPoints;

	public LandmarkScavengeablePersistentData()
	{
	}

	public LandmarkScavengeablePersistentData(Landmark landmark)
	{
		LandmarkScavengeable[] componentsInChildren = landmark.GetComponentsInChildren<LandmarkScavengeable>();
		if (componentsInChildren == null || componentsInChildren.Length == 0)
		{
			_inventories = null;
			return;
		}
		_inventories = new InventoryPersistentData[componentsInChildren.Length];
		_researchPoints = new int[componentsInChildren.Length];
		for (int i = 0; i < _inventories.Length; i++)
		{
			_inventories[i] = new InventoryPersistentData(componentsInChildren[i].Inventory);
		}
	}

	public void Restore(Landmark landmark)
	{
		LandmarkScavengeable[] componentsInChildren = landmark.GetComponentsInChildren<LandmarkScavengeable>();
		int i = 0;
		if (_inventories == null)
		{
			return;
		}
		for (; i < _inventories.Length; i++)
		{
			if (i < componentsInChildren.Length)
			{
				componentsInChildren[i].RestoreInventory(_inventories[i]);
			}
		}
		for (; i < componentsInChildren.Length; i++)
		{
			UnityEngine.Object.Destroy(componentsInChildren[i].gameObject);
		}
	}
}
[Serializable]
public class LandmarkPersistentData : PersistentReference<Landmark>
{
	private int _behaviourIndex;

	private Vector3 _position;

	private Quaternion _rotation;

	private ILandmarkInteractablePersistentData[] _interactables;

	private LandmarkMooringPointPersistentData[] _mooringPoints;

	private LandmarkActionsBehaviourPersistentData _behaviour;

	[NonSerialized]
	private ActionsBehaviour _behaviourInstance;

	public int BehaviourIndex => _behaviourIndex;

	public Vector3 Position => _position;

	public Quaternion Rotation => _rotation;

	public ILandmarkInteractablePersistentData[] Interactables => _interactables;

	public LandmarkMooringPointPersistentData[] MooringPoints => _mooringPoints;

	public LandmarkActionsBehaviourPersistentData Behaviour => _behaviour;

	private LandmarkPersistentData(LandmarkBehaviour landmarkBehaviour)
		: base((landmarkBehaviour == null) ? null : landmarkBehaviour.Landmark)
	{
		if (landmarkBehaviour == null)
		{
			UnityEngine.Debug.LogException(new Exception("No landmark behaviour!"));
		}
		_behaviourInstance = landmarkBehaviour as ActionsBehaviour;
		_behaviourIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(landmarkBehaviour.Prefab);
		PopulateBehaviourData(landmarkBehaviour);
		PopulateLandmarkData(landmarkBehaviour.Landmark);
		PopulateInteractables(landmarkBehaviour.Landmark);
		PopulateMooringPoints(landmarkBehaviour.Landmark);
	}

	public void InitializePersistentReference()
	{
		if (-1 < PersistentIndex)
		{
			throw new NotSupportedException("The persistent index is already set and should not be overriden!");
		}
		if ((bool)_behaviourInstance)
		{
			Initialize(_behaviourInstance.Landmark);
		}
	}

	public void PopulateReferences()
	{
		if (_mooringPoints != null)
		{
			LandmarkMooringPointPersistentData[] mooringPoints = _mooringPoints;
			for (int i = 0; i < mooringPoints.Length; i++)
			{
				mooringPoints[i].PopulateReferences();
			}
		}
		if (_behaviour != null)
		{
			_behaviour.PopulateReferences();
		}
	}

	public void RestoreLandmark(LandmarkBehaviour landmarkBehaviour)
	{
		RestoreLandmark(landmarkBehaviour, _position, _rotation);
	}

	public void RestoreLandmark(LandmarkBehaviour landmarkBehaviour, Vector3 position, Quaternion rotation, Transform parent = null)
	{
		base.Instance = landmarkBehaviour.RestoreLandmark(this, position, rotation, parent);
		if (_mooringPoints != null)
		{
			LandmarkMooringPoint[] componentsInChildren = base.Instance.GetComponentsInChildren<LandmarkMooringPoint>();
			LandmarkMooringPointPersistentData[] mooringPoints = _mooringPoints;
			for (int i = 0; i < mooringPoints.Length; i++)
			{
				mooringPoints[i].Restore(componentsInChildren);
			}
		}
	}

	public void RestoreReferences()
	{
		if (_behaviour != null)
		{
			_behaviour.RestoreReferences();
		}
	}

	private void PopulateBehaviourData(LandmarkBehaviour behaviour)
	{
		ActionsBehaviour actionsBehaviour = behaviour as ActionsBehaviour;
		if (!(actionsBehaviour == null) && actionsBehaviour.Actions != null)
		{
			_behaviour = new LandmarkActionsBehaviourPersistentData(actionsBehaviour);
		}
	}

	private void PopulateLandmarkData(Landmark landmark)
	{
		if (!(landmark == null))
		{
			_position = landmark.transform.position;
			_rotation = landmark.transform.rotation;
		}
	}

	private void PopulateInteractables(Landmark landmark)
	{
		if (!(landmark == null))
		{
			List<ILandmarkInteractablePersistentData> list = ListPool<ILandmarkInteractablePersistentData>.Get();
			list.Add(new LandmarkSalvageablePersistentData(landmark));
			list.Add(new LandmarkScavengeablePersistentData(landmark));
			_interactables = list.ToArray();
		}
	}

	private void PopulateMooringPoints(Landmark landmark)
	{
		if (!landmark)
		{
			return;
		}
		using ListPool<LandmarkMooringPoint>.List list = ListPool<LandmarkMooringPoint>.Get();
		using ListPool<LandmarkMooringPointPersistentData>.List list2 = ListPool<LandmarkMooringPointPersistentData>.Get();
		landmark.GetComponentsInChildren(list);
		for (int i = 0; i < list.Count; i++)
		{
			LandmarkMooringPoint landmarkMooringPoint = list[i];
			if ((bool)landmarkMooringPoint && (bool)landmarkMooringPoint.MooredBoat)
			{
				list2.Add(new LandmarkMooringPointPersistentData(landmarkMooringPoint, i));
			}
		}
		_mooringPoints = (list2.IsNullOrEmpty() ? null : list2.ToArray());
	}

	public bool TryReturnLandmarkInteractablePersistentData<T>(out T persistentData) where T : ILandmarkInteractablePersistentData
	{
		persistentData = default(T);
		if (((IReadOnlyCollection<ILandmarkInteractablePersistentData>)(object)_interactables).IsNullOrEmpty())
		{
			return false;
		}
		ILandmarkInteractablePersistentData[] interactables = _interactables;
		for (int i = 0; i < interactables.Length; i++)
		{
			if (interactables[i] is T val)
			{
				persistentData = val;
				return true;
			}
		}
		return false;
	}

	public static bool TryReturnLandmarkPersistentData(out LandmarkPersistentData data, LandmarkBehaviour landmarkBehaviour)
	{
		if (landmarkBehaviour != null && landmarkBehaviour.RequiresPersistence())
		{
			data = new LandmarkPersistentData(landmarkBehaviour);
			return true;
		}
		data = null;
		return false;
	}
}
[Serializable]
public class LimitPersistentData
{
	private Dictionary<int, int> _limitDictionary = new Dictionary<int, int>();

	public LimitPersistentData()
	{
		foreach (KeyValuePair<ItemProperties, int> item in GameManager.ResourceManager.ReturnResourceLimits())
		{
			_limitDictionary.Add(GameManager.PersistenceManager.ReturnPropertiesIndex(item.Key), item.Value);
		}
	}

	public void Restore()
	{
		Dictionary<ItemProperties, int> dictionary = new Dictionary<ItemProperties, int>();
		foreach (KeyValuePair<int, int> item in _limitDictionary)
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<ItemProperties>(item.Key, out var reference))
			{
				dictionary.Add(reference, item.Value);
			}
		}
		GameManager.ResourceManager.RestoreResourceLimits(dictionary);
	}
}
[Serializable]
public class GameWorldPersistentData : PersistentReference<World>
{
	[OptionalField(VersionAdded = 3)]
	private WorldTilePersistentData[] _tiles;

	private Vector3 _townheartPosition;

	private Quaternion _townheartRotation;

	[OptionalField(VersionAdded = 2)]
	private int _tilePropertiesIndex;

	[OptionalField(VersionAdded = 4)]
	private int _salvagedItemCount;

	[OptionalField(VersionAdded = 5)]
	private float _firstTileOffsetX;

	private WorldTilePersistentData _tile;

	public GameWorldPersistentData(World world)
		: base(world)
	{
		_tilePropertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(world.TileProperties);
		_salvagedItemCount = world.SalvagedItemCount;
		_firstTileOffsetX = 0f;
		if (world.Tiles.IsNullOrEmpty())
		{
			UnityEngine.Debug.LogError("Unable to serialized world because there are no WorldTiles to serialize");
			return;
		}
		if (world.Tiles.Count == 1 && (bool)world.Tiles[0].Properties)
		{
			_tile = new WorldTilePersistentData(world.Tiles[0]);
			_townheartPosition = world.TownheartWorldPosition;
			_townheartRotation = world.TownheartRotation;
			return;
		}
		_firstTileOffsetX = world.FirstTileOffsetX + world.Tiles[0].WorldPosition.x;
		_tiles = new WorldTilePersistentData[world.Tiles.Count];
		for (int i = 0; i < world.Tiles.Count; i++)
		{
			_tiles[i] = new WorldTilePersistentData(world.Tiles[i]);
		}
		_townheartPosition = world.TownheartWorldPosition - world.Tiles[0].Offset.Vector3TopDown();
		_townheartRotation = world.TownheartRotation;
	}

	public void PopulateReferences()
	{
		_tile?.PopulateReferences();
		if (!((IReadOnlyCollection<WorldTilePersistentData>)(object)_tiles).IsNullOrEmpty())
		{
			WorldTilePersistentData[] tiles = _tiles;
			for (int i = 0; i < tiles.Length; i++)
			{
				tiles[i].PopulateReferences();
			}
		}
	}

	public override void Restore()
	{
		if (GameManager.PersistenceManager.TryReturnPropertiesReference<TileProperties>(_tilePropertiesIndex, out var reference))
		{
			base.Instance = new World(reference, _salvagedItemCount, _firstTileOffsetX);
		}
		else
		{
			base.Instance = new World(GameSettings.Instance.WorldSettings.DefaultTileProperties, _salvagedItemCount, _firstTileOffsetX);
		}
		if (((IReadOnlyCollection<WorldTilePersistentData>)(object)_tiles).IsNullOrEmpty())
		{
			_tile.Restore(base.Instance);
			base.Instance.RestoreTile(_tile.Instance);
		}
		else
		{
			WorldTilePersistentData[] tiles = _tiles;
			foreach (WorldTilePersistentData worldTilePersistentData in tiles)
			{
				worldTilePersistentData.Restore(base.Instance);
				base.Instance.RestoreTile(worldTilePersistentData.Instance);
			}
		}
		GameManager.WorldManager.SetWorld(base.Instance);
	}

	public void RepositionLandmarks()
	{
		if (base.Instance.RepositionTownheart(_townheartPosition, _townheartRotation))
		{
			return;
		}
		int count = base.Instance.Tiles.Count;
		while (0 < count--)
		{
			if (base.Instance.Tiles[count].TryReturnTownheartResetPosition(out var position) && base.Instance.RepositionTownheart(position, Quaternion.identity))
			{
				UnityEngine.Debug.LogException(new Exception("An out of bounds position was persisted for the town, the town position was reset."));
				return;
			}
		}
		UnityEngine.Debug.LogException(new Exception("An out of bounds position was persisted for the town, the town position could not be reset!"));
	}

	public void RestoreReferences()
	{
		_tile?.RestoreReferences();
		if (!((IReadOnlyCollection<WorldTilePersistentData>)(object)_tiles).IsNullOrEmpty())
		{
			WorldTilePersistentData[] tiles = _tiles;
			for (int i = 0; i < tiles.Length; i++)
			{
				tiles[i].RestoreReferences();
			}
		}
	}
}
[Serializable]
public class WorldTilePersistentData : PersistentReference<WorldTile>
{
	[OptionalField(VersionAdded = 8)]
	private int _index;

	[OptionalField(VersionAdded = 7)]
	private int _tileGeneratorPrefabIndex = -1;

	[OptionalField(VersionAdded = 7)]
	private int _subTileGeneratorPrefabIndex = -1;

	private LandmarkSpawnerPersistentData[] _landmarkSpawners;

	private PointOfInterestSpawner.PersistentData[] _pointOfInterestSpawners;

	[OptionalField(VersionAdded = 8)]
	private WorldRegionFlags[] _regionFlags;

	[OptionalField(VersionAdded = 6)]
	private WorldMapFogOfWar.PersistentData _fogOfWarPersistentData;

	[OptionalField(VersionAdded = 4)]
	private float _scale;

	private int _propertiesIndex = -1;

	[OptionalField(VersionAdded = 2)]
	private byte[] _fogOfWarAlphas;

	[OptionalField(VersionAdded = 3)]
	private int _salvagedItemCount;

	public LandmarkSpawnerPersistentData[] LandmarkSpawners => _landmarkSpawners;

	public PointOfInterestSpawner.PersistentData[] PointOfInterestSpawners => _pointOfInterestSpawners;

	public int SalvagedItemCount => _salvagedItemCount;

	public WorldTilePersistentData(WorldTile tile)
		: base(tile)
	{
		_index = tile.Index;
		if ((bool)tile.Properties)
		{
			_propertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(tile.Properties);
		}
		else
		{
			_tileGeneratorPrefabIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(tile.TileGeneratorPrefab);
			_subTileGeneratorPrefabIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(tile.SubTileGeneratorPrefab);
		}
		_fogOfWarPersistentData = GameManager.WorldMapManager.WorldMap.ReturnFogOfWarPersistentData(tile);
		_salvagedItemCount = tile.SalvagedItemCount;
		_scale = tile.Scale;
		PopulateLandmarkSpawnerData(tile.Landmarks);
		PopulatePointOfInterestSpawnerData(tile.PointsOfInterest);
		PopulateRegionData(tile.Regions);
	}

	private void PopulateLandmarkSpawnerData(IReadOnlyList<LandmarkSpawner> landmarkSpawners)
	{
		_landmarkSpawners = new LandmarkSpawnerPersistentData[landmarkSpawners.Count];
		for (int i = 0; i < _landmarkSpawners.Length; i++)
		{
			_landmarkSpawners[i] = new LandmarkSpawnerPersistentData(landmarkSpawners[i]);
		}
	}

	private void PopulatePointOfInterestSpawnerData(IReadOnlyList<PointOfInterestSpawner> pointOfInterestSpawners)
	{
		List<PointOfInterestSpawner.PersistentData> list = ListPool<PointOfInterestSpawner.PersistentData>.Get(pointOfInterestSpawners.Count);
		foreach (PointOfInterestSpawner pointOfInterestSpawner in pointOfInterestSpawners)
		{
			list.Add(new PointOfInterestSpawner.PersistentData(pointOfInterestSpawner));
		}
		_pointOfInterestSpawners = list.ToArray();
		ListPool<PointOfInterestSpawner.PersistentData>.Add(list);
	}

	private void PopulateRegionData(IReadOnlyList<IWorldRegion> regions)
	{
		int count = regions.Count;
		_regionFlags = new WorldRegionFlags[count];
		for (int i = 0; i < count; i++)
		{
			_regionFlags[i] = regions[i].Flags;
		}
	}

	public void PopulateReferences()
	{
		LandmarkSpawnerPersistentData[] landmarkSpawners = _landmarkSpawners;
		for (int i = 0; i < landmarkSpawners.Length; i++)
		{
			landmarkSpawners[i].PopulateReferences();
		}
	}

	public void Restore(World world)
	{
		base.Restore();
		if (RestoreInstance())
		{
			base.Instance.Restore(_index);
			base.Instance.SalvagedItemCount = _salvagedItemCount;
			base.Instance.Scale = _scale;
			RestoreLandmarkSpawners(base.Instance);
			RestorePointOfInterestSpawners(base.Instance);
			RestoreRegions(base.Instance);
			if (_fogOfWarPersistentData == null)
			{
				base.Instance.RestoreFogOfWar(_fogOfWarAlphas);
			}
			else
			{
				base.Instance.RestoreFogOfWar(_fogOfWarPersistentData);
			}
		}
	}

	private bool RestoreInstance()
	{
		if (-1 < _propertiesIndex && GameManager.PersistenceManager.TryReturnPropertiesReference<TileProperties>(_propertiesIndex, out var reference))
		{
			base.Instance = new WorldTile(reference);
			return true;
		}
		if (GameManager.PersistenceManager.TryReturnPropertiesReference<TileGenerator>(_tileGeneratorPrefabIndex, out var reference2))
		{
			TileGeneratorBase reference3 = null;
			if (-1 < _tileGeneratorPrefabIndex)
			{
				GameManager.PersistenceManager.TryReturnPropertiesReference<TileGeneratorBase>(_subTileGeneratorPrefabIndex, out reference3);
			}
			base.Instance = new WorldTile(reference2, reference3);
			return true;
		}
		return false;
	}

	public override void Restore()
	{
		throw new NotSupportedException();
	}

	private void RestoreLandmarkSpawners(WorldTile tile)
	{
		LandmarkSpawnerPersistentData[] landmarkSpawners = _landmarkSpawners;
		for (int i = 0; i < landmarkSpawners.Length; i++)
		{
			landmarkSpawners[i].Restore(tile);
		}
	}

	private void RestorePointOfInterestSpawners(WorldTile tile)
	{
		PointOfInterestSpawner.PersistentData[] pointOfInterestSpawners = _pointOfInterestSpawners;
		for (int i = 0; i < pointOfInterestSpawners.Length; i++)
		{
			if (pointOfInterestSpawners[i].TryRestore(out var spawner))
			{
				tile.AddPointOfInterestSpawner(spawner, initialize: false);
			}
		}
	}

	private void RestoreRegions(WorldTile tile)
	{
		int count = tile.Regions.Count;
		if (_regionFlags == null)
		{
			return;
		}
		if (_regionFlags.Length != count)
		{
			UnityEngine.Debug.LogException(new Exception("Unable to restore region flags, there is a region count mismatch!"));
			return;
		}
		for (int i = 0; i < count; i++)
		{
			tile.Regions[i].Restore(_regionFlags[i]);
		}
	}

	private bool ValidateIndices(int[] indices, int indexCount)
	{
		if (indices == null)
		{
			return false;
		}
		foreach (int num in indices)
		{
			if (0 > num || num >= indexCount)
			{
				return false;
			}
		}
		return true;
	}

	public void RestoreReferences()
	{
		LandmarkSpawnerPersistentData[] landmarkSpawners = _landmarkSpawners;
		for (int i = 0; i < landmarkSpawners.Length; i++)
		{
			landmarkSpawners[i].RestoreReferences();
		}
	}
}
[Serializable]
public class PersistentGameObjectPeristentReference
{
	public PersistentReference<Agent>.Reference AgentReference;

	public PersistentReference<Bird>.Reference BirdReference;

	public PersistentReference<Boat>.Reference BoatReference;

	[OptionalField(VersionAdded = 2)]
	public PersistentReference<Buildable>.Reference BuildableReference;

	private PersistentGameObjectPeristentReference()
	{
	}

	private bool Initialize(GameObject gameObject)
	{
		if (gameObject == null)
		{
			return true;
		}
		if (!TryPopulatePersistentReferenceComponent(gameObject, out AgentReference) && !TryPopulatePersistentReferenceComponent(gameObject, out BirdReference) && !TryPopulatePersistentReferenceComponent(gameObject, out BoatReference))
		{
			return TryPopulatePersistentReferenceComponent(gameObject, out BuildableReference);
		}
		return true;
	}

	public bool TryRestore(out GameObject gameObject)
	{
		if (!TryRestore(AgentReference, out gameObject) && !TryRestore(BirdReference, out gameObject) && !TryRestore(BoatReference, out gameObject))
		{
			return TryRestore(BuildableReference, out gameObject);
		}
		return true;
	}

	public bool TryRestoreAgent(out Agent agent)
	{
		return AgentReference.TryReturn(out agent);
	}

	private bool TryPopulatePersistentReferenceComponent<T>(GameObject gameObject, out PersistentReference<T>.Reference persistentReference) where T : IPersistentReference
	{
		T component = gameObject.GetComponent<T>();
		if (component == null)
		{
			persistentReference = null;
			return false;
		}
		persistentReference = new PersistentReference<T>.Reference(component);
		return true;
	}

	private bool TryRestore<T>(PersistentReference<T>.Reference persistentReference, out GameObject gameObject) where T : MonoBehaviour, IPersistentReference
	{
		if (persistentReference.TryReturn(out var instance))
		{
			gameObject = instance.gameObject;
			return true;
		}
		gameObject = null;
		return false;
	}

	public static implicit operator PersistentGameObjectPeristentReference(GameObject gameObject)
	{
		PersistentGameObjectPeristentReference persistentGameObjectPeristentReference = new PersistentGameObjectPeristentReference();
		if (persistentGameObjectPeristentReference.Initialize(gameObject))
		{
			return persistentGameObjectPeristentReference;
		}
		UnityEngine.Debug.LogFormat("Reference to GameObject '{0}' could not be persisted!", gameObject.name);
		return persistentGameObjectPeristentReference;
	}

	public static implicit operator GameObject(PersistentGameObjectPeristentReference data)
	{
		if (data.TryRestore(out var gameObject))
		{
			return gameObject;
		}
		return null;
	}
}
[Serializable]
public class PlayerRunPersistentData
{
	private Guid _id;

	private string _communityName;

	private List<SaveInfo> _saves;

	private bool _tutorial;

	public Guid Id => _id;

	public string CommunityName => _communityName;

	public List<SaveInfo> Saves => _saves;

	public bool Tutorial => _tutorial;

	public PlayerRunPersistentData(string communityName, bool tutorial = false)
	{
		_communityName = communityName;
		_saves = new List<SaveInfo>();
		_tutorial = tutorial;
		Sorting.SlowSort(_saves);
	}

	public bool SetCommunityName(string name)
	{
		if (Saves.IsNullOrEmpty())
		{
			_communityName = name;
			return true;
		}
		return false;
	}

	public bool TryGetSave(out SaveInfo save, string name, SaveType type = SaveType.Manual)
	{
		for (int i = 0; i < _saves.Count; i++)
		{
			save = _saves[i];
			if (save != null && save.Type == type && save.Name.Equals(name))
			{
				return true;
			}
		}
		save = null;
		return false;
	}
}
[Serializable]
public class QueuedRecipePersistentData
{
	public int RecipeIndex = -1;

	public QueuedRecipe.Stage RecipeStage;

	public float Progress;

	public bool HasReservedFuel;

	public int[] ItemIndices;

	public QueuedRecipePersistentData(QueuedRecipe queuedRecipe)
	{
		RecipeIndex = ((queuedRecipe.Recipe != null) ? queuedRecipe.Recipe.Index : (-1));
		RecipeStage = queuedRecipe.RecipeStage;
		Progress = queuedRecipe.Progress;
		ItemIndices = ((queuedRecipe.RecipeItems == null) ? null : ReturnItemIndices(queuedRecipe.RecipeItems));
	}

	public List<Item> ReturnItems()
	{
		List<Item> list = new List<Item>();
		if (((IReadOnlyCollection<int>)(object)ItemIndices).IsNullOrEmpty())
		{
			return list;
		}
		for (int i = 0; i < ItemIndices.Length; i++)
		{
			if (PersistentReference<Item>.TryReturnReference(ItemIndices[i], out var reference))
			{
				list.Add(reference);
			}
		}
		return list;
	}

	private int[] ReturnItemIndices(List<Item> items)
	{
		int[] array = new int[items.Count];
		for (int i = 0; i < items.Count; i++)
		{
			array[i] = items[i].PersistentIndex;
		}
		return array;
	}
}
[Serializable]
public class LandmarkSpawnerPersistentData
{
	private int _landmarkBehaviourIndex;

	private LandmarkPersistentData _persistentData;

	private Vector3 _position;

	private Quaternion _rotation;

	[OptionalField(VersionAdded = 2)]
	private ScoutingState _scoutingState;

	[OptionalField(VersionAdded = 4)]
	private BearingFeatures _bearingFeatures;

	[OptionalField(VersionAdded = 4)]
	private BearingIconType _bearingIconOverride;

	[OptionalField(VersionAdded = 3)]
	private bool _isBearingActive;

	[NonSerialized]
	private LandmarkSpawner _instance;

	public LandmarkSpawner Instance => _instance;

	public LandmarkSpawnerPersistentData(LandmarkSpawner landmarkSpawner)
	{
		if ((bool)landmarkSpawner.LandmarkBehaviour)
		{
			_landmarkBehaviourIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(landmarkSpawner.LandmarkBehaviour.Prefab);
			if (!LandmarkPersistentData.TryReturnLandmarkPersistentData(out _persistentData, landmarkSpawner.LandmarkBehaviour))
			{
				_persistentData = landmarkSpawner.PersistentData;
				if (_persistentData != null)
				{
					_persistentData.InitializePersistentReference();
				}
			}
		}
		else
		{
			_landmarkBehaviourIndex = -1;
		}
		_position = landmarkSpawner.TilePosition.Vector3TopDown();
		_rotation = landmarkSpawner.Rotation;
		_scoutingState = landmarkSpawner.ScoutingState;
		_bearingFeatures = landmarkSpawner.BearingFeatures;
		_bearingIconOverride = landmarkSpawner.BearingIconOverride;
		_instance = landmarkSpawner;
	}

	~LandmarkSpawnerPersistentData()
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, RestoreBearingFeatures);
	}

	public void PopulateReferences()
	{
		if (_persistentData != null && !(_instance.LandmarkBehaviour.Landmark == null))
		{
			_persistentData.PopulateReferences();
		}
	}

	public void Restore(WorldTile worldTile)
	{
		LandmarkBehaviour reference = null;
		if (_landmarkBehaviourIndex == -1 || GameManager.PersistenceManager.TryReturnPropertiesReference<LandmarkBehaviour>(_landmarkBehaviourIndex, out reference))
		{
			if (_persistentData != null)
			{
				_persistentData.Restore();
			}
			_instance = new LandmarkSpawner(reference, _position, _rotation, _persistentData);
			_instance.SetScoutingState(_scoutingState, _isBearingActive);
			if (_isBearingActive)
			{
				GameEventDispatcher.AddListener(GameEventType.GameStart, RestoreBearingFeatures);
			}
			worldTile.AddLandmarkSpawner(_instance);
		}
	}

	private void RestoreBearingFeatures(GameEvent gameEvent)
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, RestoreBearingFeatures);
		if (_bearingFeatures != BearingFeatures.None)
		{
			_instance.SetBearingFeatures(_bearingFeatures, _bearingIconOverride);
		}
		else if (_isBearingActive)
		{
			_instance.SetScoutingState(_scoutingState, _isBearingActive);
		}
	}

	public void RestoreReferences()
	{
		if (_persistentData != null)
		{
			_persistentData.RestoreReferences();
		}
	}
}
[Serializable]
public class UINotificationPersistentData
{
	public int PropertiesPersistentIndex;

	public PersistentGameObjectPeristentReference ObjectOfInterest;

	public ObjectType ObjectOfInterestType;

	[OptionalField(VersionAdded = 2)]
	public bool InGameCanvas;

	[OptionalField(VersionAdded = 2)]
	public float TimeStamp;

	public int BuildablePropertiesPersistentIndex;

	[OptionalField(VersionAdded = 4)]
	public string ResearchGuid;

	public int LandmarkBehaviourPersistentIndex;

	public int DayIndex;

	[OptionalField(VersionAdded = 5)]
	public TutorialID TutorialID;

	public UINotificationPersistentData(NotificationData notification)
	{
		PropertiesPersistentIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(notification.Properties);
		ObjectOfInterest = notification.ObjectOfInterest.GameObjectOfInterest;
		ObjectOfInterestType = notification.ObjectOfInterest.ObjectOfInterestType;
		TimeStamp = notification.Timestamp;
		switch (ObjectOfInterestType)
		{
		case ObjectType.Research:
			if (notification.ObjectOfInterest is ResearchObjectOfInterest researchObjectOfInterest)
			{
				ResearchGuid = researchObjectOfInterest.Research.Guid;
			}
			break;
		case ObjectType.Buildable:
			if (notification.ObjectOfInterest is BuildableObjectOfInterest buildableObjectOfInterest)
			{
				BuildablePropertiesPersistentIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(buildableObjectOfInterest.BuildableProperties);
			}
			break;
		case ObjectType.Landmark:
			if (notification.ObjectOfInterest is LandmarkObjectOfInterest landmarkObjectOfInterest)
			{
				LandmarkBehaviourPersistentIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(landmarkObjectOfInterest.ReturnPersistentLandmarkBehaviour());
			}
			break;
		case ObjectType.Day:
			if (notification.ObjectOfInterest is DayObjectOfInterest dayObjectOfInterest)
			{
				DayIndex = dayObjectOfInterest.DayIndex;
			}
			break;
		case ObjectType.Tutorial:
			if (notification.ObjectOfInterest is TutorialObjectOfInterest tutorialObjectOfInterest)
			{
				TutorialID = tutorialObjectOfInterest.TutorialID;
			}
			break;
		}
	}

	public void Restore(UIManager uiManager)
	{
		if (!((!PersistenceManager.DoesSaveInfoVersionComeBefore(0, 3, 4)) ? GameManager.PersistenceManager.TryReturnPropertiesReference<NotificationProperties>(PropertiesPersistentIndex, out var reference) : GameManager.Settings.UISettings.NotificationProperties.TryReturnReference(PropertiesPersistentIndex, out reference)))
		{
			return;
		}
		INotificationObjectOfInterest notificationObjectOfInterest = null;
		GameObject gameObject;
		switch (ObjectOfInterestType)
		{
		case ObjectType.Research:
		{
			if (CommunityResearch.Research.TryInstantiateFromGuid(ResearchGuid, out var research))
			{
				notificationObjectOfInterest = new ResearchObjectOfInterest(research);
			}
			break;
		}
		case ObjectType.Buildable:
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<BuildableProperties>(BuildablePropertiesPersistentIndex, out var reference2) && ObjectOfInterest.TryRestore(out gameObject))
			{
				notificationObjectOfInterest = new BuildableObjectOfInterest(gameObject, reference2);
			}
			break;
		}
		case ObjectType.Landmark:
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<LandmarkBehaviour>(LandmarkBehaviourPersistentIndex, out var reference3))
			{
				notificationObjectOfInterest = new LandmarkObjectOfInterest(reference3);
			}
			break;
		}
		case ObjectType.Day:
			notificationObjectOfInterest = new DayObjectOfInterest(DayIndex);
			break;
		case ObjectType.Agent:
		{
			if (ObjectOfInterest.TryRestoreAgent(out var agent))
			{
				notificationObjectOfInterest = new AgentObjectOfInterest(agent);
			}
			break;
		}
		case ObjectType.Marker:
			notificationObjectOfInterest = new DefaultObjectOfInterest(null, ObjectOfInterestType);
			break;
		case ObjectType.Tutorial:
			if (TutorialID != TutorialID.None)
			{
				notificationObjectOfInterest = new TutorialObjectOfInterest(TutorialID);
			}
			break;
		}
		if (notificationObjectOfInterest == null)
		{
			if (!ObjectOfInterest.TryRestore(out gameObject))
			{
				UnityEngine.Debug.LogWarningFormat("An object of interest of type '{0}' could not be restored!", ObjectOfInterestType);
				return;
			}
			notificationObjectOfInterest = new DefaultObjectOfInterest(gameObject, ObjectOfInterestType);
		}
