			instance.SetPersistentProperties(persistentPropertiesData);
			return true;
		}
		catch (Exception innerException)
		{
			UnityEngine.Debug.LogException(new PersistenceException("Failed to create WorldPersistentData instance!", innerException));
			PersistenceLifeCycle.OnPostPersistenceAction();
			instance = null;
			return false;
		}
