[Serializable]
public class PersistentPropertiesData
{
	private readonly List<string> _persistentPropertiesGuids = new List<string>();

	[NonSerialized]
	private PersistentPropertiesReferences _properties;

	public PersistentPropertiesData(PersistentPropertiesReferences properties)
	{
		_properties = properties;
	}

	public void Restore(PersistentPropertiesReferences properties)
	{
		_properties = properties;
	}

	public int PersistReference(PersistentProperties reference)
	{
		if (_properties.TryReturnGuid(reference, out var guid))
		{
			for (int i = 0; i < _persistentPropertiesGuids.Count; i++)
			{
				if (guid == _persistentPropertiesGuids[i])
				{
					return i;
				}
			}
			int count = _persistentPropertiesGuids.Count;
			_persistentPropertiesGuids.Add(guid);
			return count;
		}
		return -1;
	}

	public bool TryReturnPersistedIndex(PersistentProperties reference, out int index)
	{
		if (_properties.TryReturnGuid(reference, out var guid))
		{
			for (int i = 0; i < _persistentPropertiesGuids.Count; i++)
			{
				if (guid == _persistentPropertiesGuids[i])
				{
					index = i;
					return true;
				}
			}
		}
		index = -1;
		return false;
	}

	public bool TryReturnReference<T>(int index, out T reference) where T : PersistentProperties
	{
		reference = null;
		if (index < 0)
		{
			return false;
		}
		if (index >= _persistentPropertiesGuids.Count)
		{
			return false;
		}
		return _properties.TryReturnReference<T>(_persistentPropertiesGuids[index], out reference);
	}
}
[CreateAssetMenu(menuName = "Flotsam/PeristentScriptableObjects")]
public class PersistentPropertiesReferences : ScriptableObject
{
	[Serializable]
	internal class PersistentReference
	{
		[SerializeField]
		internal string Name;

		[SerializeField]
		internal string Type;

		[SerializeField]
		internal PersistentProperties Reference;

		[SerializeField]
		internal string Guid;
	}

	[SerializeField]
	internal PersistentReference[] _persistentReferences;

	[NonSerialized]
	private Dictionary<PersistentProperties.Types, IList<PersistentReference>> _persistentReferencesByType;

	public void Initialize()
	{
		if (_persistentReferencesByType != null)
		{
			return;
		}
		_persistentReferencesByType = new Dictionary<PersistentProperties.Types, IList<PersistentReference>>();
		PersistentReference[] persistentReferences = _persistentReferences;
		foreach (PersistentReference persistentReference in persistentReferences)
		{
			if (_persistentReferencesByType.TryGetValue(persistentReference.Reference.Type, out var value))
			{
				value.Add(persistentReference);
				continue;
			}
			value = new List<PersistentReference>(32);
			value.Add(persistentReference);
			_persistentReferencesByType.Add(persistentReference.Reference.Type, value);
		}
	}

	public bool TryReturnReference<T>(string Guid, out T reference) where T : PersistentProperties
	{
		PersistentReference[] persistentReferences = _persistentReferences;
		foreach (PersistentReference persistentReference in persistentReferences)
		{
			if (persistentReference.Guid == Guid)
			{
				reference = persistentReference.Reference as T;
				return reference != null;
			}
		}
		reference = null;
		return false;
	}

	public bool TryReturnGuid(PersistentProperties reference, out string guid)
	{
		if (reference.IsNull())
		{
			guid = null;
			return false;
		}
		if (_persistentReferencesByType == null || !_persistentReferencesByType.TryGetValue(reference.Type, out var value))
		{
			value = _persistentReferences;
		}
		int count = value.Count;
		for (int i = 0; i < count; i++)
		{
			PersistentReference persistentReference = value[i];
			if (persistentReference.Reference.IsEqual(reference))
			{
				guid = persistentReference.Guid;
				return true;
			}
		}
		guid = null;
		return false;
	}

	public void PopulateReferences<T>(PersistentProperties.Types type, List<T> references) where T : PersistentProperties
	{
		if (!_persistentReferencesByType.TryGetValue(type, out var value))
		{
			return;
		}
		foreach (PersistentReference item2 in value)
		{
			if (item2.Reference is T item)
			{
				references.Add(item);
			}
		}
	}
}
[Serializable]
public abstract class PersistentReference<T> where T : IPersistentReference
{
	[Serializable]
	public class Reference : ISerializable
	{
		public delegate void RestoreReferenceCallback(T reference);

		public int PersistentIndex = -1;

		[NonSerialized]
		private T _reference;

		public Reference(T reference)
		{
			_reference = reference;
			if (_reference == null)
			{
				PersistentIndex = -1;
			}
			else
			{
				PersistentIndex = reference.PersistentIndex;
			}
		}

		public Reference(SerializationInfo info, StreamingContext context)
		{
			PersistentIndex = info.GetInt32("PersistentIndex");
		}

		public void GetObjectData(SerializationInfo info, StreamingContext context)
		{
			if (_reference == null)
			{
				info.AddValue("PersistentIndex", -1);
			}
			else
			{
				info.AddValue("PersistentIndex", _reference.PersistentIndex);
			}
		}

		public void Restore(RestoreReferenceCallback restoreCallback)
		{
			if (PersistentReference<T>.TryReturnReference(PersistentIndex, out T reference))
			{
				restoreCallback(reference);
			}
		}

		public bool TryReturnInstance(out T reference)
		{
			return PersistentReference<T>.TryReturnReference(PersistentIndex, out reference);
		}

		public static implicit operator Reference(T reference)
		{
			if (reference == null)
			{
				return null;
			}
			return new Reference(reference);
		}

		public static implicit operator T(Reference field)
		{
			if (field == null)
			{
				return default(T);
			}
			if (PersistentReference<T>.TryReturnReference(field.PersistentIndex, out T reference))
			{
				return reference;
			}
			return default(T);
		}
	}

	public delegate void OnReferenceRestored(T reference);

	[OptionalField]
	public int PersistentIndex;

	public static int _referenceCount;

	public static List<PersistentReference<T>> _references;

	[NonSerialized]
	private T _instance;

	public T Instance
	{
		get
		{
			return _instance;
		}
		protected set
		{
			_instance = value;
		}
	}

	public PersistentReference(T reference)
	{
		Initialize(reference);
	}

	protected virtual void Initialize(T reference)
	{
		if (reference == null)
		{
			PersistentIndex = -1;
			return;
		}
		Instance = reference;
		T instance = Instance;
		instance.PersistentIndex = (PersistentIndex = _referenceCount++);
		if (_references == null)
		{
			_references = new List<PersistentReference<T>>();
		}
		_references.Add(this);
	}

	public virtual void Restore()
	{
		if (PersistentIndex >= 0)
		{
			if (_references == null)
			{
				_references = new List<PersistentReference<T>>();
			}
			_references.Add(this);
		}
	}

	public static void OnPrePersistenceOperation()
	{
		_referenceCount = 0;
		if (_references == null)
		{
			_references = ListPool<PersistentReference<T>>.Get();
		}
		else
		{
			ClearReferences();
		}
	}

	public static void OnPostPersistenceOperation()
	{
		if (_references != null)
		{
			ClearReferences();
			ListPool<PersistentReference<T>>.Add(_references);
			_references = null;
		}
	}

	private static void ClearReferences()
	{
		foreach (PersistentReference<T> reference in _references)
		{
			reference.PersistentIndex = -1;
			if (reference.Instance != null)
			{
				T instance = reference.Instance;
				instance.PersistentIndex = -1;
				reference.Instance = default(T);
			}
		}
		_references.Clear();
	}

	public static bool TryReturnReference(int persistentIndex, out T reference)
	{
		if (_references == null)
		{
			throw new NotSupportedException("Persistent reference for type '" + typeof(T)?.ToString() + "' has not been initialized! Are you missing a call to OnPreLoad()?");
		}
		int count = _references.Count;
		if (-1 < persistentIndex)
		{
			if (persistentIndex < _references.Count)
			{
				PersistentReference<T> persistentReference = _references[persistentIndex];
				if (persistentReference.PersistentIndex == persistentIndex)
				{
					reference = persistentReference.Instance;
					return reference != null;
				}
			}
			for (int i = 0; i < count; i++)
			{
				PersistentReference<T> persistentReference = _references[i];
				if (persistentReference.PersistentIndex == persistentIndex)
				{
					reference = persistentReference.Instance;
					return reference != null;
				}
			}
		}
		reference = default(T);
		return false;
	}
}
[Serializable]
public class PersistentScriptableObjectReferenceArray<T> where T : ScriptableObject
{
	[SerializeField]
	private T[] _references;

	public int ReturnReferenceIndex(T reference)
	{
		int num = _references.Length;
		for (int i = 0; i < num; i++)
		{
			if (_references[i] == reference)
			{
				return i;
			}
		}
		return -1;
	}

	public bool TryReturnReferenceIndex(T reference, out int index)
	{
		int num = _references.Length;
		for (int i = 0; i < num; i++)
		{
			if (_references[i] == reference)
			{
				index = i;
				return true;
			}
		}
		index = -1;
		return false;
	}

	public T ReturnReference(int index)
	{
		if (-1 < index && index < _references.Length)
		{
			return _references[index];
		}
		return null;
	}

	public bool TryReturnReference(int index, out T reference)
	{
		if (-1 < index && index < _references.Length)
		{
			reference = _references[index];
			return true;
		}
		reference = null;
		return false;
	}
}
[Serializable]
public class PersistentNotificationProperties : PersistentScriptableObjectReferenceArray<NotificationProperties>
{
}
public interface IPersistentReferenceLifeCycle
{
	void OnPrePersistenceAction();

	void OnPostPersistenceAction();
}
public class PersistentReferenceLifeCycle<T> : IPersistentReferenceLifeCycle where T : IPersistentReference
{
	public void OnPrePersistenceAction()
	{
		PersistentReference<T>.OnPrePersistenceOperation();
	}

	public void OnPostPersistenceAction()
	{
		PersistentReference<T>.OnPostPersistenceOperation();
	}
}
public class Buoyancy : MonoBehaviour, IUpdateManagerFixedUpdateTarget, IUpdateManagerUpdateTarget, IUpdateManagerLateUpdateTarget
{
	public enum QualityLevel
	{
		None,
		Low,
		Medium,
		High
	}

	public bool _buoyancyEnabled = true;

	public PhysicsProperties _properties;

	public bool IsFalling;

	public bool DrawGizmos;

	[Range(0f, 1f)]
	public float WaterLevelLerp = 0.75f;

	private const float DAMPFER = 0.1f;

	private const float WATER_DENSITY = 1000f;

	private float voxelHalfHeight;

	private Vector3 localArchimedesForce;

	private bool isMeshCollider;

	private List<Vector3[]> forces;

	private float _dampferXmass;

	private float _voxelHeight;

	private float _margin;

	private PhysicsController _physicsController;

	private Rigidbody _rigidBody;

	private Vector3 _centerOfMass;

	private float waterLevel;

	private float k;

	private Vector3 wp;

	private Vector3 velocity;

	private Vector3 localDampingForce;

	private Vector3 force;

	private bool _allowsLevelOfDetail;

	protected bool _isInWaterCached;

	protected bool _isFullySubmerged;

	protected float _colliderVerticalBoundsSize = 1f;

	private QualityLevel _setting;

	private WaterManager _waterManager;

	private bool _hasWaterLevels;

	private float _myWaterLevel;

	private WaterManager.WaterHeightCalculation _waterHeightCalculation;

	private float[] _voxelWaterLevels;

	private CameraController _cameraController;

	private float _levelOfDetailCameraDistance = float.MaxValue;

	private Transform _transform;

	private Renderer _renderer;

	private bool _updateBuoyancy;

	public bool IsInWater => _isInWaterCached;

	public bool IsFullySubmerged => _isFullySubmerged;

	private void Start()
	{
		InitializeReferences();
	}

	private void OnEnable()
	{
		switch (_setting)
		{
		case QualityLevel.None:
			return;
		case QualityLevel.Low:
			GameManager.UpdateManager.RegisterUpdateTarget(this);
			break;
		case QualityLevel.Medium:
		case QualityLevel.High:
			GameManager.UpdateManager.RegisterFixedUpdateTarget(this);
			break;
		}
		GameManager.UpdateManager.RegisterLateUpdateTarget(this);
	}

	private void OnDisable()
	{
		switch (_setting)
		{
		case QualityLevel.None:
			return;
		case QualityLevel.Low:
			GameManager.UpdateManager.UnregisterUpdateTarget(this);
			break;
		case QualityLevel.Medium:
		case QualityLevel.High:
			GameManager.UpdateManager.UnregisterFixedUpdateTarget(this);
			break;
		}
		GameManager.UpdateManager.UnregisterLateUpdateTarget(this);
	}

	public void Initialize(PhysicsController controller, float spawnHeight = 0f)
	{
		InitializeReferences(controller);
		if (controller == null)
		{
			PajamaLlama.Debugs.Debugger.Error("No physics properties assigned", this);
		}
		else
		{
			_properties = controller.Properties;
			_allowsLevelOfDetail = _properties.AllowsBuoyancyLevelOfDetail && _renderer != null;
			_levelOfDetailCameraDistance = _properties.BuoyancyLevelOfDetailCameraDistance;
		}
		forces = new List<Vector3[]>();
		Quaternion rotation = _transform.rotation;
		Vector3 position = _transform.position;
		_transform.rotation = Quaternion.identity;
		_transform.position = Vector3.zero;
		Collider collider = controller.PrimaryCollider;
		if (collider == null)
		{
			collider = base.gameObject.AddComponent<MeshCollider>();
			isMeshCollider = false;
			UnityEngine.Debug.LogWarning($"[Buoyancy.cs] Object \"{base.name}\" had no collider. MeshCollider has been added.");
		}
		else
		{
			isMeshCollider = collider is MeshCollider;
		}
		Bounds bounds = collider.bounds;
		Vector3 size = bounds.size;
		_colliderVerticalBoundsSize = size.y;
		if (size.x < size.y)
		{
			voxelHalfHeight = size.x;
		}
		else
		{
			voxelHalfHeight = size.y;
		}
		if (size.z < voxelHalfHeight)
		{
			voxelHalfHeight = size.z;
		}
		voxelHalfHeight /= 2f * _properties.Slices.y;
		_centerOfMass = new Vector3(0f, (0f - bounds.extents.y) * 0f, 0f) + _transform.InverseTransformPoint(bounds.center);
		List<Vector3> voxels = SliceIntoVoxels(bounds.min, size, bounds.center, isMeshCollider && _properties.IsConcave);
		_waterHeightCalculation = new WaterManager.WaterHeightCalculation(_transform, voxels, UpdateWaterLevels);
		_voxelWaterLevels = new float[_waterHeightCalculation.VoxelCount];
		_transform.rotation = rotation;
		float num = _properties.Mass / _properties.Density;
		float y = 1000f * Mathf.Abs(Physics.gravity.y) * num;
		localArchimedesForce = new Vector3(0f, y, 0f) / _waterHeightCalculation.VoxelCount;
		Vector3 zero = Vector3.zero;
		zero = ((spawnHeight != 0f) ? new Vector3(position.x, spawnHeight, position.z) : ((!_properties.SpawnBeneathWaterSurface) ? WorldManager.WaterAdjustedPosition(position) : (WorldManager.WaterAdjustedPosition(position) + Vector3.down * 10f)));
		_transform.position = zero;
		_dampferXmass = 0f - 0.1f * _properties.Mass;
		_voxelHeight = voxelHalfHeight * 2f;
		_margin = 0.2f;
		_physicsController.PhysicsActive(active: true);
		if (_allowsLevelOfDetail)
		{
			StartCoroutine(WaitForCameraCoroutine());
		}
		_waterHeightCalculation.Queue(update: true);
		GameManager.UpdateManager.RegisterLateUpdateTarget(this);
		SetQualityLevel(_properties.BuoyancySetting);
	}

	private void InitializeReferences(PhysicsController controller = null)
	{
		_transform = base.transform;
		if (_physicsController == null)
		{
			_physicsController = ((controller == null) ? GetComponent<PhysicsController>() : controller);
		}
		if (_waterManager == null)
		{
			_waterManager = WaterManager.Instance;
		}
		if (_renderer == null)
		{
			_renderer = GetComponentInChildren<Renderer>();
		}
	}

	public void UpdateManager_FixedUpdate()
	{
		if (!_updateBuoyancy)
		{
			return;
		}
		Vector3 position = _waterHeightCalculation.UpdatePosition();
		if (_waterHeightCalculation.ApplyForces)
		{
			PerformWaterTest(position.y, _myWaterLevel);
			for (int i = 0; i < _waterHeightCalculation.VoxelCount; i++)
			{
				wp = _waterHeightCalculation.UpdateVoxelPosition(i);
				waterLevel = _voxelWaterLevels[i];
				if (wp.y - voxelHalfHeight < waterLevel - _margin)
				{
					k = Mathf.Clamp((waterLevel - wp.y) / _voxelHeight + 0.5f, 0f, 1f);
					_rigidBody.AddForceAtPosition(CalculateForce(_rigidBody.GetPointVelocity(wp), Mathf.Sqrt(k)), wp);
				}
			}
			_waterHeightCalculation.Queue();
		}
		else
		{
			position.y = Mathf.Lerp(position.y, _myWaterLevel, _properties.WaterLevelLerp);
			_rigidBody.MovePosition(position);
			_waterHeightCalculation.Queue(position);
		}
	}

	public void UpdateManager_Update(float deltaTime, int frame)
	{
		if (_hasWaterLevels)
		{
			Vector3 position = _transform.position;
			position.y = Mathf.Lerp(position.y, _myWaterLevel, _properties.WaterLevelLerp);
			_transform.position = position;
			_waterHeightCalculation.Queue(position);
		}
	}

	public void UpdateManager_LateUpdate()
	{
		Vector3 position = _transform.position;
		if (_setting == QualityLevel.High && _allowsLevelOfDetail)
		{
			bool flag = position.IsInRange(_cameraController.CameraPosition, _levelOfDetailCameraDistance);
			if (_waterHeightCalculation.ApplyForces)
			{
				if (!_renderer.isVisible || !flag)
				{
					_waterHeightCalculation.ApplyForces = false;
				}
			}
			else if (flag && _renderer.isVisible)
			{
				_rigidBody.linearVelocity = -Physics.gravity * Time.deltaTime;
				_waterHeightCalculation.ApplyForces = true;
			}
		}
		if (_properties.FloatUpright && _buoyancyEnabled)
		{
			Quaternion b = Quaternion.FromToRotation(_transform.up, Vector3.up) * _transform.rotation;
			_transform.rotation = Quaternion.Slerp(_transform.rotation, b, Time.deltaTime * _properties.UprightRotationalSpeed);
		}
		_updateBuoyancy = _buoyancyEnabled && _hasWaterLevels;
	}

	private void SetQualityLevel(QualityLevel level)
	{
		if (_setting != level)
		{
			UpdateManager updateManager = GameManager.UpdateManager;
			updateManager.UnregisterFixedUpdateTarget(this);
			updateManager.UnregisterUpdateTarget(this);
			switch (level)
			{
			case QualityLevel.High:
				_rigidBody = ReturnRigidbody();
				_rigidBody.isKinematic = false;
				_rigidBody.detectCollisions = true;
				_rigidBody.useGravity = true;
				_waterHeightCalculation.ApplyForces = true;
				updateManager.RegisterFixedUpdateTarget(this);
				break;
			case QualityLevel.Medium:
				_rigidBody = ReturnRigidbody();
				_rigidBody.isKinematic = false;
				_rigidBody.detectCollisions = true;
				_rigidBody.useGravity = false;
				_waterHeightCalculation.ApplyForces = false;
				updateManager.RegisterFixedUpdateTarget(this);
				break;
			default:
				_physicsController.DestroyRigidbody();
				_waterHeightCalculation.ApplyForces = false;
				updateManager.RegisterUpdateTarget(this);
				break;
			}
			_setting = level;
		}
	}

	private Rigidbody ReturnRigidbody()
	{
		Rigidbody rigidbody = _physicsController.InitializeRigidbody();
		rigidbody.centerOfMass = _centerOfMass;
		return rigidbody;
	}

	private void OnDrawGizmos()
	{
		if (!DrawGizmos || _waterHeightCalculation == null || forces == null)
		{
			return;
		}
		Gizmos.color = Color.yellow;
		Vector3[] voxelPositions = _waterHeightCalculation.VoxelPositions;
		foreach (Vector3 position in voxelPositions)
		{
			Gizmos.DrawCube(_transform.TransformPoint(position), new Vector3(0.05f, 0.05f, 0.05f));
		}
		Gizmos.color = Color.cyan;
		foreach (Vector3[] force in forces)
		{
			Gizmos.DrawCube(force[0], new Vector3(0.05f, 0.05f, 0.05f));
			Gizmos.DrawLine(force[0], force[0] + force[1] / GetComponent<Rigidbody>().mass);
		}
	}

	private void OnMouseUp()
	{
		if (GameSpeedManager.GameSpeed != GameSpeed.Paused && GameSpeedManager.GameSpeed != GameSpeed.Zero)
		{
			Vector3 position = _transform.position.SetY(WorldManager.WaterHeight(_transform.position.x, _transform.position.z)) + Vector3.up * 0.25f;
			ParticleController.Spawn(GameManager.Settings.FXSettings.Splash, position, Quaternion.identity);
			if ((bool)_rigidBody)
			{
				_rigidBody.AddForce(Vector3.down * GameManager.Settings.PokeForce, ForceMode.Impulse);
			}
		}
	}

	private void OnDestroy()
	{
		if (_setting == QualityLevel.High || _setting == QualityLevel.Medium)
		{
			GameManager.UpdateManager.UnregisterFixedUpdateTarget(this);
		}
		else
		{
			GameManager.UpdateManager.UnregisterUpdateTarget(this);
		}
		GameManager.UpdateManager.UnregisterLateUpdateTarget(this);
	}

	private void UpdateFalling()
	{
		if (IsFalling && _isFullySubmerged)
		{
			_rigidBody.linearVelocity = Vector3.zero;
			_rigidBody.linearDamping = _properties.Drag;
			EffectsManager.ActivateEffect(EffectTrigger.Splash, null, base.transform.position);
			IsFalling = false;
		}
	}

	private IEnumerator WaitForCameraCoroutine()
	{
		_allowsLevelOfDetail = false;
		while (CameraController.Instance.Camera == null)
		{
			yield return null;
		}
		_cameraController = CameraController.Instance;
		_allowsLevelOfDetail = true;
	}

	private List<Vector3> SliceIntoVoxels(Vector3 boundsMin, Vector3 boundsSize, Vector3 boundsCenter, bool concave)
	{
		List<Vector3> list = new List<Vector3>((int)_properties.Slices.x * (int)_properties.Slices.y * (int)_properties.Slices.z);
		float x = boundsMin.x;
		float y = boundsMin.y;
		float z = boundsMin.z;
		float num = boundsSize.x / _properties.Slices.x;
		float num2 = boundsSize.y / _properties.Slices.y;
		float num3 = boundsSize.z / _properties.Slices.z;
		if (concave)
		{
			MeshCollider component = GetComponent<MeshCollider>();
			bool convex = component.convex;
			component.convex = false;
			for (int i = 0; (float)i < _properties.Slices.x; i++)
			{
				float x2 = x + num * (0.5f + (float)i);
				for (int j = 0; (float)j < _properties.Slices.y; j++)
				{
					float y2 = y + num2 * (0.5f + (float)j);
					for (int k = 0; (float)k < _properties.Slices.z; k++)
					{
						float z2 = y + num2 * (0.5f + (float)k);
						Vector3 vector = _transform.InverseTransformPoint(new Vector3(x2, y2, z2));
						if (PointIsInsideMeshCollider(component, vector))
						{
							list.Add(vector);
						}
					}
				}
			}
			if (list.Count == 0)
			{
				list.Add(boundsCenter);
			}
			component.convex = convex;
		}
		else
		{
			for (int l = 0; (float)l < _properties.Slices.x; l++)
			{
				float x2 = x + num * (0.5f + (float)l);
				for (int m = 0; (float)m < _properties.Slices.y; m++)
				{
					float y2 = y + num2 * (0.5f + (float)m);
					for (int n = 0; (float)n < _properties.Slices.z; n++)
					{
						float z2 = z + num3 * (0.5f + (float)n);
						Vector3 item = _transform.InverseTransformPoint(new Vector3(x2, y2, z2));
						list.Add(item);
					}
				}
			}
		}
		WeldPoints(list, _properties.VoxelsLimit);
		return list;
	}

	private static bool PointIsInsideMeshCollider(Collider c, Vector3 p)
	{
		Vector3[] array = new Vector3[6]
		{
			Vector3.up,
			Vector3.down,
			Vector3.left,
			Vector3.right,
			Vector3.forward,
			Vector3.back
		};
		foreach (Vector3 vector in array)
		{
			if (!c.Raycast(new Ray(p - vector * 1000f, vector), out var _, 1000f))
			{
				return false;
			}
		}
		return true;
	}

	private static void FindClosestPoints(IList<Vector3> list, out int firstIndex, out int secondIndex)
	{
		float num = float.MaxValue;
		float num2 = float.MinValue;
		firstIndex = 0;
		secondIndex = 1;
		for (int i = 0; i < list.Count - 1; i++)
		{
			for (int j = i + 1; j < list.Count; j++)
			{
				float num3 = Vector3.Distance(list[i], list[j]);
				if (num3 < num)
				{
					num = num3;
					firstIndex = i;
					secondIndex = j;
				}
				if (num3 > num2)
				{
					num2 = num3;
				}
			}
		}
	}

	private static void WeldPoints(IList<Vector3> list, int targetCount)
	{
		if (list.Count > 2 && targetCount >= 2)
		{
			while (list.Count > targetCount)
			{
				FindClosestPoints(list, out var firstIndex, out var secondIndex);
				Vector3 item = (list[firstIndex] + list[secondIndex]) * 0.5f;
				list.RemoveAt(secondIndex);
				list.RemoveAt(firstIndex);
				list.Add(item);
			}
		}
	}

	public bool InWater()
	{
		if (_transform.position.y <= WorldManager.WaterHeight(_transform.position.x, _transform.position.z) + 0.1f)
		{
			return true;
		}
		return false;
	}

	private void PerformWaterTest(float testHeight, float waterLevel)
	{
		if (testHeight - _colliderVerticalBoundsSize / 2f <= waterLevel)
		{
			_isInWaterCached = true;
			if (testHeight + _colliderVerticalBoundsSize / 2f <= waterLevel)
			{
				_isFullySubmerged = true;
			}
			else
			{
				_isFullySubmerged = false;
			}
		}
		else
		{
			_isInWaterCached = false;
			_isFullySubmerged = false;
		}
	}

	private void UpdateWaterLevels(WaterManager.WaterHeightCalculation calculation)
	{
		_hasWaterLevels = true;
		_myWaterLevel = calculation.PositionWaterHeight;
		if (calculation.ApplyForces)
		{
			calculation.CopyVoxelWaterHeights(_voxelWaterLevels);
		}
	}

	public void ForceWaterLevel(float waterLevel)
	{
		_myWaterLevel = waterLevel;
	}

	private Vector3 CalculateForce(Vector3 velocity, float kSqrt, float multiplier = 1f)
	{
		velocity.x = velocity.x * _dampferXmass + localArchimedesForce.x * kSqrt;
		velocity.y = velocity.y * _dampferXmass + localArchimedesForce.y * kSqrt;
		velocity.z = velocity.z * _dampferXmass + localArchimedesForce.z * kSqrt;
		return velocity;
	}
}
public class CranePhysics : MonoBehaviour
{
	[Tooltip("Multiplier for the poke force to the crane.")]
	[SerializeField]
	private float _pokeForceMultiplier = 0.1f;

	private Rigidbody _rigidbody;

	private void Awake()
	{
		_rigidbody = GetComponent<Rigidbody>();
	}

	private void OnMouseUp()
	{
		_rigidbody.AddForce(CameraController.Instance.transform.forward * GameManager.Settings.PokeForce * _pokeForceMultiplier, ForceMode.Impulse);
	}
}
[AddComponentMenu("Flotsam/Physics/Physics Controller")]
public class PhysicsController : MonoBehaviour, IUpdateManagerFixedUpdateTarget
{
	[Tooltip("Physical properties of this object.")]
	public PhysicsProperties Properties;

	[SerializeField]
	[Tooltip("Should the primary collider always be enabled (even if it is disabled on instantiation)?")]
	private bool _alwaysEnablePrimaryCollider = true;

	[SerializeField]
	[Tooltip("Secondary collider for switching to in certain cases. Mainly used for drifters when out of the water.")]
	private Collider _secondaryCollider;

	[HideInInspector]
	public bool ShouldApplyCurrent = true;

	private bool _initialized;

	private RigidbodyConstraints _originalConstraints;

	private Vector3 _mainForce;

	private Rigidbody _rigidBody;

	private Buoyancy _buoyancy;

	private Transform _transform;

	private PhysicsManager _physicsManager;

	private Vector3 _originalRotation;

	public Collider PrimaryCollider { get; private set; }

	private void Start()
	{
		Initialize(Properties);
	}

	private void OnEnable()
	{
		if ((bool)PrimaryCollider)
		{
			PrimaryCollider.enabled = true;
		}
		if ((bool)_buoyancy)
		{
			_buoyancy.enabled = true;
		}
	}

	private void OnDisable()
	{
		if ((bool)PrimaryCollider)
		{
			PrimaryCollider.enabled = false;
		}
		if ((bool)_buoyancy)
		{
			_buoyancy.enabled = false;
		}
	}

	public void Initialize(PhysicsProperties physicsProperties = null, float spawnHeight = 0f)
	{
		if (_initialized)
		{
			return;
		}
		if (physicsProperties != null)
		{
			Properties = physicsProperties;
		}
		InitializeReferences();
		_originalRotation = _transform.eulerAngles;
		if (PrimaryCollider != null)
		{
			PrimaryCollider.isTrigger = Properties.IsTrigger;
			if (_alwaysEnablePrimaryCollider)
			{
				PrimaryCollider.enabled = true;
			}
		}
		if (Properties == null)
		{
			PajamaLlama.Debugs.Debugger.Warning($"No physics properties set for {base.gameObject.name}.", this);
		}
		if (Properties.Buoyant)
		{
			_buoyancy = GetComponent<Buoyancy>();
			if (_buoyancy == null)
			{
				_buoyancy = base.gameObject.AddComponent<Buoyancy>();
			}
			_buoyancy.Initialize(this, spawnHeight);
		}
		else
		{
			SetKinematic(isKinematic: true, isTrigger: false);
			if (Properties.AttachToWorld)
			{
				base.transform.SetParent(GameManager.WorldManager.WorldParent);
			}
		}
		_initialized = true;
	}

	public void Initialize(GameObject visualPrefab, PhysicsProperties physicsProperties, float spawnHeight = 0f)
	{
		if (physicsProperties.CopyVisualPrefabCollider)
		{
			PrimaryCollider = FlotsamGame.CopyCollider(visualPrefab, base.gameObject);
		}
		else
		{
			PrimaryCollider = visualPrefab.GetComponent<Collider>();
			PrimaryCollider.gameObject.layer = base.gameObject.layer;
		}
		Initialize(physicsProperties, spawnHeight);
	}

	private void InitializeReferences()
	{
		_transform = base.transform;
		_physicsManager = GameManager.PhysicsManager;
		_rigidBody = InitializeRigidbody();
		if ((bool)_rigidBody)
		{
			ApplyPhysicsPropertiesToRigidbody(_rigidBody, Properties);
		}
		if (PrimaryCollider == null)
		{
			PrimaryCollider = GetComponent<Collider>();
		}
	}

	public void UpdateManager_FixedUpdate()
	{
		Vector3 eulerAngles = _transform.eulerAngles;
		if (Properties.FreezeRotationX)
		{
			eulerAngles.x = _originalRotation.x;
		}
		if (Properties.FreezeRotationY)
		{
			eulerAngles.y = _originalRotation.y;
		}
		if (Properties.FreezeRotationZ)
		{
			eulerAngles.z = _originalRotation.z;
		}
		_transform.rotation = Quaternion.Euler(eulerAngles);
	}

	private void OnDestroy()
	{
		GameManager.UpdateManager.UnregisterFixedUpdateTarget(this);
	}

	private void ApplyCurrent()
	{
		if (_physicsManager.MovingFlotsamForce == 0f)
		{
			return;
		}
		_mainForce = _physicsManager.MainForce;
		if (Properties.SlowDownNearTownheart)
		{
			float num = _transform.position.FastSquaredMagnitudeLeveled();
			float slowdownThreshold = GameManager.Settings.GameplaySettings.SlowdownThreshold;
			if (num < slowdownThreshold * slowdownThreshold)
			{
				float t = Mathf.Sqrt(num) / slowdownThreshold;
				t = Mathf.Lerp(GameManager.Settings.GameplaySettings.SlowedDownMultiplier, 1f, t);
				_mainForce *= t;
			}
		}
		_rigidBody.AddForce(_mainForce);
	}

	public void AddLocalForce(Vector3 localForce, float maxVelocity)
	{
		localForce *= Time.fixedDeltaTime;
		if (_rigidBody.linearVelocity.magnitude <= maxVelocity)
		{
			_rigidBody.AddRelativeForce(localForce);
		}
		else
		{
			_rigidBody.linearVelocity = _rigidBody.linearVelocity.normalized * maxVelocity;
		}
	}

	public void AddForce(Vector3 force, float maxVelocity = 9999f)
	{
		float magnitude = _rigidBody.linearVelocity.magnitude;
		if (magnitude <= maxVelocity)
		{
			_rigidBody.AddForce(force);
		}
		else
		{
			_rigidBody.linearVelocity = _rigidBody.linearVelocity.normalized * (maxVelocity / magnitude);
		}
	}

	public void AddTorque(Vector3 torque)
	{
		_rigidBody.AddTorque(torque);
	}

	public void SetKinematic(bool isKinematic, bool isTrigger)
	{
		if ((bool)_rigidBody)
		{
			_rigidBody.isKinematic = isKinematic;
			_rigidBody.useGravity = !isKinematic;
		}
		if ((bool)PrimaryCollider)
		{
			PrimaryCollider.isTrigger = isTrigger;
		}
		if ((bool)_secondaryCollider)
		{
			_secondaryCollider.isTrigger = isTrigger;
		}
	}

	public void SetKinematic(bool isKinematic)
	{
		SetKinematic(isKinematic, isKinematic);
	}

	public void PhysicsActive(bool active)
	{
		if ((bool)_rigidBody)
		{
			if (active)
			{
				_rigidBody.constraints = _originalConstraints;
			}
			else
			{
				_originalConstraints = _rigidBody.constraints;
				_rigidBody.constraints = RigidbodyConstraints.FreezeAll;
			}
		}
		if (Properties.Buoyant)
		{
			_buoyancy._buoyancyEnabled = active;
		}
		SetKinematic(!active);
	}

	public void EnableCollider(bool primaryEnabled)
	{
		PrimaryCollider.enabled = primaryEnabled;
	}

	public void EnableCollider(bool primaryEnabled, bool secondaryEnabled)
	{
		PrimaryCollider.enabled = primaryEnabled;
		_secondaryCollider.enabled = secondaryEnabled;
	}

	public void Sink(GameObject parent = null)
	{
		PhysicsActive(active: true);
		_rigidBody.useGravity = true;
		_rigidBody.isKinematic = false;
		_rigidBody.mass *= GameManager.Settings.GameplaySettings.WorldPhysics.MassMultiplier;
		_rigidBody.linearDamping = GameManager.Settings.GameplaySettings.WorldPhysics.NewDrag;
		PrimaryCollider.enabled = false;
		StartCoroutine(DestructionCoroutine(GameManager.Settings.GameplaySettings.WorldPhysics.DestructionHeight, parent));
	}

	private IEnumerator DestructionCoroutine(float destructionDepth, GameObject parent)
	{
		while (base.transform.position.y > destructionDepth)
		{
			yield return null;
		}
		if ((bool)parent)
		{
			UnityEngine.Object.Destroy(parent);
		}
		else
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	public void Teleport(Vector3 target)
	{
		_rigidBody.position = target;
	}

	public void TeleportToWaterLevel()
	{
		float y = WorldManager.WaterHeight(_rigidBody.transform.position.x, _rigidBody.transform.position.z);
		_rigidBody.position = new Vector3(_rigidBody.transform.position.x, y, _rigidBody.transform.position.z);
	}

	public Rigidbody InitializeRigidbody(bool attachedComponentOnly = false)
	{
		if ((bool)_rigidBody)
		{
			return _rigidBody;
		}
		_rigidBody = GetComponent<Rigidbody>();
		if (_rigidBody == null)
		{
			if (attachedComponentOnly)
			{
				return null;
			}
			_rigidBody = base.gameObject.AddComponent<Rigidbody>();
		}
		ApplyPhysicsPropertiesToRigidbody(_rigidBody, Properties);
		return _rigidBody;
	}

	private void ApplyPhysicsPropertiesToRigidbody(Rigidbody rigidbody, PhysicsProperties properties)
	{
		RigidbodyConstraints rigidbodyConstraints = RigidbodyConstraints.None;
		rigidbody.mass = Properties.Mass;
		rigidbody.linearDamping = Properties.Drag;
		rigidbody.angularDamping = Properties.AngularDrag;
		rigidbody.useGravity = Properties.UseGravity;
		rigidbody.isKinematic = Properties.IsKinematic;
		if (Properties.FreezePositionX)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezePositionX;
		}
		if (Properties.FreezePositionY)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezePositionY;
		}
		if (Properties.FreezePositionZ)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezePositionZ;
		}
		if (Properties.FreezeRotationX)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezeRotationX;
		}
		if (Properties.FreezeRotationY)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezeRotationY;
		}
		if (Properties.FreezeRotationZ)
		{
			rigidbodyConstraints |= RigidbodyConstraints.FreezeRotationZ;
		}
		rigidbody.constraints = (_originalConstraints = rigidbodyConstraints);
	}

	public void DestroyRigidbody()
	{
		if ((bool)_rigidBody)
		{
			UnityEngine.Object.Destroy(_rigidBody);
			GameManager.UpdateManager.UnregisterFixedUpdateTarget(this);
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Physics/Physics")]
