public interface IBlockingProjectProvider
{
	bool TryReturnBlockingProject(out Project blockingProject, Agent agent);
}
public class ProjectFinishedEvent : UnityEvent<Project, bool>
{
}
public class Project : IPersistentReference, IComparable<Project>
{
	[Header("Properties")]
	public ProjectProperties Properties;

	[Tooltip("Target items for this project.")]
	public List<Item> GeneralItems = new List<Item>();

	public float BlockedTime;

	private AssignmentType _assignmentTypeFlags;

	private int _assignmentLimit;

	private bool _isGlobalHaulingProject;

	private ProjectBlocker _blocker;

	private ProjectSettings _projectSettings;

	private int _priority;

	private IBlockingProjectProvider _blockingProjectProvider;

	private Dictionary<ProjectBlocker, PlaceableAlertProperties> _malfunctions = new Dictionary<ProjectBlocker, PlaceableAlertProperties>();

	private bool _intializedReturnAgentBlockersFields;

	private bool _needsInventorySpace;

	[Tooltip("Target game object of the project.")]
	public GameObject Target { get; private set; }

	public ISalvageTarget SalvageTarget { get; set; }

	public List<ProjectAssignment> Assignments { get; private set; }

	public int AssignmentLimit
	{
		get
		{
			return _assignmentLimit;
		}
		set
		{
			if (Properties == null || Properties.AllowAgentLimitOverride)
			{
				_assignmentLimit = value;
			}
		}
	}

	public bool IsCommunityProject => Community.PlayerCommunity.Projects.Contains(this);

	public bool IsBlocked => Blockers != ProjectBlocker.None;

	public ProjectBlocker Blockers { get; private set; }

	public bool Requeue { get; set; }

	public Target NavigationTarget { get; private set; }

	public VitalType Vital { get; set; } = VitalType.None;

	public AssignmentType AssignmentTypes => _assignmentTypeFlags;

	public Buildable TargetBuildable { get; private set; }

	public Inventory TargetInventory { get; private set; }

	public int AgentPriorityScore { get; private set; }

	public bool IsIdleProject => (AssignmentTypes & AssignmentType.Idle) != 0;

	public int PersistentIndex { get; set; } = -1;

	public ProjectFinishedEvent FinishedEvent { get; private set; } = new ProjectFinishedEvent();

	public UnityEvent ProjectAssignmentsUpdated { get; private set; } = new UnityEvent();

	public event UnityAction MalfunctionsUpdated;

	public Project(ProjectProperties properties, GameObject target)
	{
		if (properties == null)
		{
			PajamaLlama.Debugs.Debugger.Error("Can't create a new project without giving properties!");
			return;
		}
		Properties = properties;
		Assignments = ListPool<ProjectAssignment>.Get();
		_projectSettings = GameManager.Settings.ProjectSettings;
		_assignmentTypeFlags = properties.AssignmentType | properties.SecondaryAssignmentTypes;
		_assignmentLimit = properties.AgentLimit;
		_isGlobalHaulingProject = properties.ReturnIsGlobalHaulingProject();
		Target = target;
		if (Target == null)
		{
			PajamaLlama.Debugs.Debugger.Warning($"Target for {properties.name} project is null.");
		}
		else
		{
			NavigationTarget = Target.GetComponentInChildren<Target>();
			TargetBuildable = Target.GetComponentInChildren<Buildable>();
			TargetInventory = Target.GetComponent<Inventory>();
		}
		if (Properties.Shareable && AssignmentLimit == 1)
		{
			PajamaLlama.Debugs.Debugger.Error("A project can not be shareable and have an agent limit of 1!");
		}
		if (!properties.Shareable && AssignmentLimit == -1)
		{
			PajamaLlama.Debugs.Debugger.Error("A project can not have an agent limit of -1 and not be shareable!");
		}
	}

	public Project(ProjectProperties properties, GameObject target, List<Item> items)
		: this(properties, target)
	{
		if (items != null)
		{
			GeneralItems.Capacity = items.Count;
			AddItems(items);
		}
	}

	public Project(ProjectProperties properties, GameObject target, ISalvageTarget salvageTarget)
		: this(properties, target)
	{
		SalvageTarget = salvageTarget;
	}

	public void Destroy()
	{
		foreach (ProjectAssignment assignment in Assignments)
		{
			assignment.Destroy();
		}
		Assignments.Clear();
		RemoveAllGeneralItems();
		FinishedEvent.RemoveAllListeners();
		ProjectAssignmentsUpdated.RemoveAllListeners();
	}

	public void SetBlockingProjectProvider(IBlockingProjectProvider blockingProjectProvider)
	{
		_blockingProjectProvider = blockingProjectProvider;
	}

	public void AddAssignmentType(AssignmentType assignmentType)
	{
		_assignmentTypeFlags |= assignmentType;
	}

	public bool AssignAgent(Agent agent, bool isIdleProject = false)
	{
		ProjectAssignment assignment;
		return TryAssignAgent(out assignment, agent, isIdleProject);
	}

	public void SetPriority(int priority)
	{
		_priority = Mathf.Clamp(priority, -49, 49) * GameManager.Settings.ProjectSettings.ProjectPriorityWeight;
	}

	public void SetAgentPriority(Agent agent)
	{
		AgentPriorityScore = ReturnAgentPriority(agent);
	}

	public bool TryAssignAgent(out ProjectAssignment assignment, Agent agent, bool isIdleProject)
	{
		if (ReturnHasAgentAssigned(agent))
		{
			assignment = null;
			return false;
		}
		assignment = new ProjectAssignment(this, agent, isIdleProject);
		if (assignment.Start())
		{
			if (TryReturnDeprioritizedAssignment(out var assignmentToStop))
			{
				assignmentToStop.Stop(ProjectFlags.Priority);
			}
			Assignments.Add(assignment);
			AgentEvent.Dispatch(GameEventType.AgentStartAssignment, agent);
			if (ProjectAssignmentsUpdated != null)
			{
				ProjectAssignmentsUpdated.Invoke();
			}
			Requeue = Properties.RequeueTrigger == ProjectRequeueTrigger.AgentAssigned;
			return true;
		}
		return false;
	}

	public void UnassignAgent(Agent agent)
	{
		if (TryReturnAgentAssignment(agent, out var _))
		{
			throw new NotImplementedException("Cancel assignment");
		}
	}

	internal void OnAssignmentFinished(ProjectAssignment assignment)
	{
		if (Assignments.Remove(assignment))
		{
			AgentEvent.Dispatch(GameEventType.AgentFinishAssignment, assignment.Agent);
		}
		if (ReturnCanFinish())
		{
			Finish(success: true);
		}
		else if (Vital != VitalType.None)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' finished vitals project '{1}' unsuccesfully!", assignment.Agent.Name, Properties.name);
			RemoveAllGeneralItems();
			Finish(success: false);
		}
		if (ProjectAssignmentsUpdated != null)
		{
			ProjectAssignmentsUpdated.Invoke();
		}
	}

	public void Stop(ProjectFlags flags)
	{
		int count = Assignments.Count;
		while (0 < count--)
		{
			Assignments[count].Stop(flags);
		}
		foreach (Item generalItem in GeneralItems)
		{
			generalItem.CancelReservation();
			generalItem.UnreserveMoveToInventory();
			generalItem.Project = null;
		}
		GeneralItems.Clear();
		if (Assignments.Count == 0)
		{
			Finish(success: false);
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception($"Unable to stop '{Properties}' project, there are still {Assignments.Count} assignments active!"));
		}
	}

	private void Finish(bool success)
	{
		FinishedEvent.Invoke(this, success);
		FinishedEvent.RemoveAllListeners();
	}

	public void UpdateBlockedTime()
	{
		if (IsCommunityProject)
		{
			Blockers = ReturnProjectBlockers();
			if (Blockers == ProjectBlocker.None)
			{
				BlockedTime = 0f;
			}
			else
			{
				BlockedTime += Time.deltaTime;
			}
		}
	}

	public void AddItem(Item item)
	{
		if (item.Project == null || !item.Project.IsCommunityProject)
		{
			item.Project = this;
			GeneralItems.AddUnique(item);
		}
	}

	public void AddItems(List<Item> items)
	{
		int count = items.Count;
		for (int i = 0; i < count; i++)
		{
			AddItem(items[i]);
		}
	}

	public void RemoveItem(Item item)
	{
		if (item.Project != this)
		{
			return;
		}
		using (List<ProjectAssignment>.Enumerator enumerator = Assignments.GetEnumerator())
		{
			while (enumerator.MoveNext() && !enumerator.Current.RemoveItem(item))
			{
			}
		}
		item.Project = null;
		if (GeneralItems.Remove(item))
		{
			item.CancelReservation();
		}
	}

	public void RemoveAllGeneralItems()
	{
		for (int num = GeneralItems.Count - 1; num >= 0; num--)
		{
			RemoveItem(GeneralItems[num]);
		}
	}

	public int CompareTo(Project other)
	{
		if (other == null)
		{
			return 1;
		}
		if (Properties == null)
		{
			return 1;
		}
		return Properties.CompareTo(other.Properties);
	}

	public bool ReturnCanRun(Agent agent, ProjectBlocker blockersToIgnore = ProjectBlocker.None)
	{
		ProjectBlocker blockers;
		return ReturnCanRun(agent, out blockers, blockersToIgnore);
	}

	public bool ReturnCanRun(Agent agent, out ProjectBlocker blockers, ProjectBlocker blockersToIgnore = ProjectBlocker.None)
	{
		blockers = ReturnProjectBlockers() | ReturnAgentBlockers(agent);
		foreach (TaskBase item in Properties.TaskQueue.List)
		{
			blockers |= item.ReturnBlockers(agent);
			blockers |= item.ReturnBlockers(this);
		}
		return (blockers ^ blockersToIgnore) == ProjectBlocker.None;
	}

	public bool ReturnCanAgentRun(Agent agent, bool idle)
	{
		return ReturnAgentBlockers(agent, idle) == ProjectBlocker.None;
	}

	public bool ReturnHasAssignmentSlotsFree(Agent agent)
	{
		if (AssignmentLimit == -1 || Assignments.Count < AssignmentLimit)
		{
			return true;
		}
		if (Properties._allowPrioritization)
		{
			int num = ReturnAgentPriority(agent);
			foreach (ProjectAssignment assignment in Assignments)
			{
				if (assignment.Priority < num)
				{
					return true;
				}
			}
		}
		return false;
	}

	internal bool ReturnHasAgentAssigned(Agent agent)
	{
		foreach (ProjectAssignment assignment in Assignments)
		{
			if (assignment.Agent == agent)
			{
				return true;
			}
		}
		return false;
	}

	private bool TryReturnDeprioritizedAssignment(out ProjectAssignment assignmentToStop)
	{
		assignmentToStop = null;
		if (Properties.AllowPrioritization && Assignments.Count == Properties.AgentLimit)
		{
			List<ProjectAssignment> assignments = Assignments;
			assignmentToStop = assignments[assignments.Count - 1];
			int index = Assignments.Count - 1;
			while (0 < index--)
			{
				ProjectAssignment projectAssignment = Assignments[index];
				if (projectAssignment.Priority < assignmentToStop.Priority)
				{
					assignmentToStop = projectAssignment;
				}
			}
		}
		return assignmentToStop != null;
	}

	private bool TryReturnAgentAssignment(Agent agent, out ProjectAssignment assignment)
	{
		int count = Assignments.Count;
		for (int i = 0; i < count; i++)
		{
			assignment = Assignments[i];
			if (assignment.Agent == agent)
			{
				return true;
			}
		}
		assignment = null;
		return false;
	}

	public List<Agent> ReturnAssignedAgents(List<Agent> listToPopulate = null)
	{
		if (listToPopulate == null)
		{
			listToPopulate = new List<Agent>();
		}
		foreach (ProjectAssignment assignment in Assignments)
		{
			listToPopulate.AddUnique(assignment.Agent);
		}
		return listToPopulate;
	}

	private bool ReturnCanFinish()
	{
		if (0 < Assignments.Count)
		{
			return false;
		}
		if (!Properties.ReturnCanFinish(this))
		{
			return false;
		}
		foreach (TaskBase item in Properties.TaskQueue.List)
		{
			if (!item.ReturnCanFinish(this))
			{
				return false;
			}
		}
		if (GeneralItems.Count > 0)
		{
			return false;
		}
		if (Properties.Perpetual)
		{
			Requeue = Properties.RequeueTrigger == ProjectRequeueTrigger.CanFinish;
			return false;
		}
		return true;
	}

	public bool IsValid()
	{
		if (!Properties.AllowTargetTypeNull)
		{
			return Target != null;
		}
		return true;
	}

	public bool ReturnMatchesAssignmentType(AssignmentType assignmentType)
	{
		return _assignmentTypeFlags == assignmentType;
	}

	public bool ReturnContainsAssignmentType(AssignmentType assignmentType)
	{
		return (_assignmentTypeFlags & assignmentType) == assignmentType;
	}

	public AssignmentPriority ReturnAssignmentPriority(Agent agent)
	{
		AssignmentType assignmentType = _assignmentTypeFlags;
		AssignmentPriority assignmentPriority = AssignmentPriority.None;
		if (_isGlobalHaulingProject)
		{
			assignmentType |= Community.PlayerCommunity.Inventory.ReturnResourceProvidersAssignmentTypes();
		}
		foreach (Assignment assignment in agent.Assignments)
		{
			if ((assignmentType & assignment.Type) != AssignmentType.None && assignmentPriority < assignment.Priority)
			{
				assignmentPriority = assignment.Priority;
			}
		}
		return assignmentPriority;
	}

	public int ReturnAgentPriority(Agent agent)
	{
		int num = -1073741824;
		int projectPriority = _priority + Properties.Priority;
		foreach (Assignment assignment in agent.Assignments)
		{
			int num2 = assignment.ReturnPriority(this, projectPriority);
			if (num < num2)
			{
				num = num2;
			}
		}
		foreach (TaskBase item in Properties.TaskQueue.List)
		{
			if (item.TryReturnAgentPriority(out var priority, this, agent, _projectSettings.ProjectPrimaryAssignmentWeight) && num < priority)
			{
				num = priority + _priority;
			}
		}
		return num;
	}

	public int ReturnPriority(Agent agent)
	{
		AssignmentType assignmentType = _assignmentTypeFlags;
		int num = 0;
		if (_isGlobalHaulingProject)
		{
			assignmentType |= Community.PlayerCommunity.Inventory.ReturnResourceProvidersAssignmentTypes();
		}
		foreach (Assignment assignment in agent.Assignments)
		{
			if ((assignmentType & assignment.Type) != AssignmentType.None)
			{
				int num2 = assignment.ReturnPriority();
				if (num < num2)
				{
					num = num2;
				}
			}
		}
		return num;
	}

	public int ReturnItemCount(ItemProperties itemProperties)
	{
		int num = 0;
		foreach (Item generalItem in GeneralItems)
		{
			if (generalItem.Properties == itemProperties)
			{
				num++;
			}
		}
		foreach (ProjectAssignment assignment in Assignments)
		{
			foreach (ItemToHaul item in assignment.ItemsToHaul)
			{
				if (item.State != ItemToHaul.HaulState.Finished && item.Item.Properties == itemProperties)
				{
					num++;
				}
			}
		}
		return num;
	}

	public Item.Tags ReturnAllItemTags()
	{
		Item.Tags tags = Item.Tags.Resource;
		foreach (Item generalItem in GeneralItems)
		{
			tags |= generalItem.Properties.Tags;
		}
		foreach (ProjectAssignment assignment in Assignments)
		{
			if (assignment.ItemsToHaul == null)
			{
				continue;
			}
			foreach (ItemToHaul item in assignment.ItemsToHaul)
			{
				tags |= item.Item.Properties.Tags;
			}
		}
		return tags;
	}

	public bool ContainsItem(Item item)
	{
		if (GeneralItems.Contains(item))
		{
			return true;
		}
		foreach (ProjectAssignment assignment in Assignments)
		{
			if (assignment.ReturnIsItemToHaul(item))
			{
				return true;
			}
		}
		return false;
	}

	public ProjectBlocker ReturnProjectBlockers()
	{
		if (_blocker == ProjectBlocker.None)
		{
			_blocker = ReturnBlocker();
			UpdateMalfunctions();
		}
		return _blocker;
	}

	private ProjectBlocker ReturnBlocker()
	{
		if (Assignments.Count >= AssignmentLimit && AssignmentLimit > -1 && !Properties._allowDeprioritization)
		{
			return ProjectBlocker.AgentSlotsFull;
		}
		if (Properties.RequiresGeneralStorageSpace && !Community.PlayerCommunity.Inventory.ReturnFitsAnyItem(GeneralItems))
		{
			return ProjectBlocker.StorageSpace;
		}
		if (SalvageTarget != null)
		{
			ProjectBlocker projectBlocker = SalvageTarget.ReturnProjectBlockers(this);
			if (projectBlocker != ProjectBlocker.None)
			{
				return projectBlocker;
			}
		}
		if (Properties.Shareable && !Properties.CanHaveEmptyGeneralList && GeneralItems.Count <= 0)
		{
			return ProjectBlocker.SharableEmptyItemList;
		}
		foreach (TaskBase item in Properties.TaskQueue.List)
		{
			ProjectBlocker projectBlocker = item.ReturnBlockers(this);
			if (projectBlocker != ProjectBlocker.None)
			{
				return projectBlocker;
			}
		}
		return ProjectBlocker.None;
	}

	public void ClearBlockers()
	{
		_blocker = ProjectBlocker.None;
	}

	public ProjectBlocker ReturnAgentBlockers(Agent agent, bool idle = false)
	{
		ProjectBlocker projectBlocker = ProjectBlocker.None;
		InitializeReturnAgentBlockersFields();
		if (!agent.IsAlive)
		{
			projectBlocker |= ProjectBlocker.AgentIsDead;
		}
		if (agent.Assignment != null && agent.Assignment.KeepsPriorityOver(this, idle))
		{
			projectBlocker |= ProjectBlocker.AgentHasAssignment;
		}
		if (!ReturnHasAssignmentSlotsFree(agent))
		{
			projectBlocker |= ProjectBlocker.AgentSlotsFull;
		}
		foreach (ProjectRequirementBase item in Properties.Requirements.List)
		{
			if (!item.EvaluateCanRun(this, agent))
			{
				projectBlocker |= item.Blocker;
			}
		}
		foreach (TaskBase item2 in Properties.TaskQueue.List)
		{
			projectBlocker |= item2.ReturnBlockers(agent);
		}
		if (_needsInventorySpace && agent.ReturnInventory().ReturnIsFull())
		{
			projectBlocker |= ProjectBlocker.InventorySpace;
		}
		return projectBlocker;
	}

	public Vector3 ReturnStartPosition(Agent agent)
	{
		if (_isGlobalHaulingProject)
		{
			return agent.Community.Inventory.ReturnAvailableResourceProviderItem().Owner.transform.position;
		}
		if ((AssignmentTypes & AssignmentType.Hauling) != AssignmentType.None && GeneralItems.Count > 0)
		{
			return GeneralItems[0].Owner.transform.position;
		}
		return Target.transform.position;
	}

	public bool TryReturnBlockingProject(out Project blockingProject, Agent agent)
	{
		blockingProject = null;
		if (_blockingProjectProvider != null)
		{
			return _blockingProjectProvider.TryReturnBlockingProject(out blockingProject, agent);
		}
		return false;
	}

	public void PopulateMalfunctions(List<PlaceableAlertProperties> malfunctions)
	{
		foreach (PlaceableAlertProperties value in _malfunctions.Values)
		{
			if (!malfunctions.Contains(value))
			{
				malfunctions.Add(value);
			}
		}
	}

	private void UpdateMalfunctions()
	{
		ProjectMalfunction[] malfunctions = GameSettings.Instance.ProjectSettings.Malfunctions;
		if (_blocker == ProjectBlocker.None)
		{
			if (_malfunctions.Count > 0)
			{
				_malfunctions.Clear();
				this.MalfunctionsUpdated?.Invoke();
			}
			return;
		}
		bool flag = false;
		ProjectMalfunction[] array = malfunctions;
		for (int i = 0; i < array.Length; i++)
		{
			ProjectMalfunction projectMalfunction = array[i];
			flag = (((projectMalfunction.Blocker & _blocker) != ProjectBlocker.None) ? _malfunctions.TryAdd(projectMalfunction.Blocker, projectMalfunction.AlertProperties) : _malfunctions.Remove(projectMalfunction.Blocker));
		}
		if (flag)
		{
			this.MalfunctionsUpdated?.Invoke();
		}
	}

	private void InitializeReturnAgentBlockersFields()
	{
		if (!_intializedReturnAgentBlockersFields)
		{
			_needsInventorySpace = Properties.ReturnNeedsInventorySpace();
			_intializedReturnAgentBlockersFields = true;
		}
	}

	public bool RestoreAssignment(ProjectAssignment assignment)
	{
		if (ReturnHasAgentAssigned(assignment.Agent))
		{
			UnityEngine.Debug.LogErrorFormat("Unable to restore '{0}' assignment to project '{1}'! The agent is already assigned");
			return false;
		}
		Assignments.Add(assignment);
		return true;
	}
}
public class ProjectAssignment
{
	private bool _hasStarted;

	private IEnumerator _runCoroutine;

	private IEnumerator _isValidCoroutine;

	private IEnumerator _activeTaskCoroutine;

	private TaskBase _activeTask;

	private readonly List<ItemToHaul> _itemsToHaul = new List<ItemToHaul>();

	public Project Project { get; private set; }

	public Agent Agent { get; private set; }

	public int ActiveTaskIndex { get; private set; }

	public ProjectAssignmentFlags Flags { get; private set; }

	public bool AllowsDeprioritization { get; private set; }

	public bool IsIdleProject { get; private set; }

	public Boat Boat { get; private set; }

	public MooringPointBase ReservedEmbarkMooringPoint { get; private set; }

	public MooringPointBase ReservedDisembarkMooringPoint { get; private set; }

	public IReadOnlyList<ItemToHaul> ItemsToHaul => _itemsToHaul;

	public Item ReservedItem { get; private set; }

	public bool RequiresStorageSpace => Project.Properties.RequiresGeneralStorageSpace;

	public float Water { get; private set; }

	public int Priority { get; private set; }

	public ProjectAssignment(Project project, Agent agent, bool isIdleProject)
		: this(project, agent, 0, isIdleProject)
	{
		IsIdleProject = isIdleProject;
		AllowsDeprioritization |= isIdleProject;
	}

	public ProjectAssignment(Project project, Agent agent, int activeTaskIndex, bool isIdleProject)
	{
		Project = project;
		Agent = agent;
		ActiveTaskIndex = activeTaskIndex;
		AllowsDeprioritization = Project.Properties.AllowDeprioritization || isIdleProject;
		IsIdleProject = isIdleProject;
		_itemsToHaul = ListPool<ItemToHaul>.Get(10);
		if (_itemsToHaul.Count > 0)
		{
			UnityEngine.Debug.LogException(new NotSupportedException("List is not empty!"));
			_itemsToHaul.Dispose();
			_itemsToHaul.Clear();
		}
		_hasStarted = false;
	}

	public void Destroy()
	{
		if (_itemsToHaul == null)
		{
			return;
		}
		foreach (ItemToHaul item in _itemsToHaul)
		{
			item.Dispose();
		}
		_itemsToHaul.Dispose();
		_itemsToHaul.Clear();
		if (ReservedItem != null)
		{
			UnreserveItem(ReservedItem);
		}
	}

	public bool Start()
	{
		if (_hasStarted || (Agent.Assignment != null && !Agent.Assignment.AllowsDeprioritization && Agent.Assignment != this))
		{
			return false;
		}
		if (!Project.IsValid())
		{
			Project.Stop(ProjectFlags.InValid);
			return _hasStarted;
		}
		if (Agent.Assignment != null && Agent.Assignment != this && Agent.Assignment.AllowsDeprioritization && !Agent.Assignment.Stop(ProjectFlags.Priority | ProjectFlags.DoNotTryGoToTown))
		{
			UnityEngine.Debug.LogException(new Exception($"Agent '{Agent.Name}' is unable to stop idle project '{Agent.Assignment.Project.Properties}'"));
			return false;
		}
		_runCoroutine = RunCoroutine();
		Agent.StartCoroutine(_runCoroutine);
		_isValidCoroutine = IsValidCoroutine();
		Agent.StartCoroutine(_isValidCoroutine);
		if (Agent.Assignment == null)
		{
			Agent.Assignment = this;
		}
		else if (Agent.Assignment != this)
		{
			UnityEngine.Debug.LogException(new Exception($"It seems an exception occured while '{Agent.Descriptor.Name}' was starting its assignment for project '{Project.Properties}'"));
		}
		_hasStarted = true;
		return true;
	}

	public void SetFlags(ProjectAssignmentFlags flags)
	{
		Flags = flags;
	}

	public bool Stop(ProjectFlags flags)
	{
		if (Agent.Inventory.ReturnCount() > 0)
		{
			if (flags.IsFlagSet(ProjectFlags.InventoryMustBeEmpty))
			{
				return false;
			}
			if (HasItemsInTransitWithoutReservedStorageSpace())
			{
				UnityEngine.Debug.LogException(new Exception($"ProjectAssignment for project '{Project.Properties}' is being stopped, but '{Agent.Name}' has items in its inventory without reserved storage space."));
			}
		}
		if (_activeTask != null)
		{
			_activeTask.Stop();
		}
		Dispose(finished: false);
		Project.OnAssignmentFinished(this);
		Agent.ReturnNavigator().StopNavigation(flags);
		if (flags.IsFlagSet(ProjectFlags.NonInteractable) || flags.IsFlagSet(ProjectFlags.OutOfBounds))
		{
			if ((bool)Agent)
			{
				Agent.ResetToTown();
			}
			if ((bool)Boat)
			{
				Boat.ResetToTown(disembarkAll: true);
			}
		}
		else if (!flags.IsFlagSet(ProjectFlags.DoNotTryGoToTown))
		{
			Agent.TryGoToTown(Project);
		}
		return true;
	}

	public void Finish()
	{
		if (!Agent.Inventory.ReturnIsEmpty())
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' finished '{1}' project, but there are still items in it's inventory", Agent.Name, Project.Properties.name);
		}
		Dispose();
		Project.OnAssignmentFinished(this);
	}

	public void UpdatePriority()
	{
		Priority = ((!IsIdleProject) ? Project.ReturnAgentPriority(Agent) : 0);
	}

	private IEnumerator RunCoroutine()
	{
		while (LoadingScreen.IsLoading)
		{
			yield return null;
		}
		List<TaskBase> taskQueue = Project.Properties.TaskQueue.List;
		while (ActiveTaskIndex < taskQueue.Count)
		{
			_activeTask = UnityEngine.Object.Instantiate(taskQueue[ActiveTaskIndex]);
			_activeTask.Initialize(this);
			_activeTaskCoroutine = _activeTask.RunTaskCoroutine(Agent, Project);
			if (_activeTask.DoYieldReturn)
			{
				yield return Agent.StartCoroutine(_activeTaskCoroutine);
			}
			else if (_activeTaskCoroutine.MoveNext())
			{
				UnityEngine.Debug.LogException(new NotSupportedException("TaskBase.DoYieldReturn == false for task '" + _activeTask.name + "', but MoveNext() returns true!"));
			}
			ActiveTaskIndex++;
		}
		_activeTask = null;
		_activeTaskCoroutine = null;
		_runCoroutine = null;
		yield return WaitForAssignedToProject();
		Finish();
	}

	private IEnumerator IsValidCoroutine()
	{
		while (LoadingScreen.IsLoading)
		{
			yield return null;
		}
		while (Project.IsValid())
		{
			yield return null;
		}
		Project.Stop(ProjectFlags.InValid);
	}

	private IEnumerator WaitForAssignedToProject()
	{
		while (LoadingScreen.IsLoading)
		{
			yield return null;
		}
		for (int i = 0; i < 60; i++)
		{
			if (Project.Assignments.Contains(this))
			{
				yield break;
			}
			yield return null;
		}
		UnityEngine.Debug.LogErrorFormat("'{0}' its assignment to project '{1}' was never added to the projects assignments list, this is a bug!", Agent.Name, Project.Properties.name);
	}

	private void Dispose(bool finished = true)
	{
		if (_itemsToHaul.Count > 0)
		{
			if (finished)
			{
				UnityEngine.Debug.LogErrorFormat("'{0}' finished assignment for project '{1}', but there are still items ({2}) left to haul!", Agent.Name, Project.Properties.name, ReturnItemsToHaulString());
			}
			foreach (ItemToHaul item in _itemsToHaul)
			{
				item.Dispose(finished);
			}
			_itemsToHaul.Dispose();
			_itemsToHaul.Clear();
		}
		if (ReservedItem != null)
		{
			UnityEngine.Debug.LogError($"'{Agent.Name}' finished assignment for project '{Project.Properties.name}', but there are still reserved items left! ({ReservedItem})");
			UnreserveItem(ReservedItem);
		}
		if (UnreserveEmbarkMooringPoint() && finished)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' finished '{1}' project, but still had an embark mooring point reserved!", Agent.Name, Project.Properties.name);
		}
		if (UnreserveDisembarkMooringPoint() && finished)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' finished '{1}' project, but still had a disembark mooring point reserved!", Agent.Name, Project.Properties.name);
		}
		if (Agent.Assignment == this)
		{
			Agent.Assignment = null;
		}
		else
		{
			UnityEngine.Debug.LogException(new NotSupportedException($"Unable to clear project '{Project.Properties}' its assignment to agent '{Agent.Name}'." + $"The agent is currently assigned to project '{Agent.Assignment.Project.Properties}'"));
		}
		if (_runCoroutine != null)
		{
			Agent.StopCoroutine(_runCoroutine);
		}
		if (_isValidCoroutine != null)
		{
			Agent.StopCoroutine(_isValidCoroutine);
		}
		if (_activeTaskCoroutine != null)
		{
			Agent.StopCoroutine(_activeTaskCoroutine);
		}
	}

	public bool RemoveItem(Item item)
	{
		if (item.Project == Project)
		{
			return RemoveItemToHaul(item);
		}
		UnityEngine.Debug.LogErrorFormat("Item '{0}' is removed from project assignment with '{1}' for project '{3}'", item.Properties.LocalizedName, Agent.Name, Project.Properties.name);
		return false;
	}

	public void AddWater(Item item)
	{
		if (item.Inventory.TakeItem(item) == item)
		{
			Water += 1000f;
		}
		else
		{
			UnityEngine.Debug.LogError("Huh?");
		}
	}

	public void RemoveWater(float amount)
	{
		Water = Mathf.Max(0f, Water - amount);
	}

	public bool AddItemToPickup(Item item)
	{
		ItemToHaul itemToHaul;
		if (Project.Properties.PickupOnly && ReturnCanHaulItem(item))
		{
			return AddItemToHaulUnique(out itemToHaul, item, SubInventoryType.Storage);
		}
		return false;
	}

	public bool AddItemToHaul(Item item, SubInventoryType targetSubInventory = SubInventoryType.Storage)
	{
		if (ReturnCanHaulItem(item) && ((bool)Boat || (bool)item.MoveToInventory || Agent.Community.ReserveIncomingItems(item, targetSubInventory)))
		{
			if (AddItemToHaulUnique(out var _, item, targetSubInventory))
			{
				item.Reserve();
				return true;
			}
			item.UnreserveMoveToInventory();
		}
		return false;
	}

	public bool AddGeneralItemToHaul(Item item, SubInventoryType targetSubInventory = SubInventoryType.Storage)
	{
		ItemToHaul itemToHaul;
		return AddGeneralItemToHaul(out itemToHaul, item, targetSubInventory);
	}

	public bool AddGeneralItemToHaul(out ItemToHaul itemToHaul, Item item, SubInventoryType targetSubInventory = SubInventoryType.Storage)
	{
		if (ReturnCanHaulItem(item))
		{
			if (!Project.GeneralItems.Remove(item))
			{
				throw new NotSupportedException($"Item '{item.Properties.LocalizedName}' was being added as general item to haul for agent '{Agent.Name}' working on project '{Project.Properties.name}', but it is not in the projects general items list!");
			}
			if (AddItemToHaulUnique(out itemToHaul, item, targetSubInventory, isGeneralListItem: true))
			{
				return true;
			}
			Project.GeneralItems.Add(item);
		}
		itemToHaul = null;
		return false;
	}

	public bool RestoreItemToHaul(Item item, SubInventoryType targetSubInventory, bool isGeneralListItem)
	{
		ItemToHaul itemToHaul;
		return TryRestoreItemToHaul(out itemToHaul, item, targetSubInventory, isGeneralListItem);
	}

	public bool TryRestoreItemToHaul(out ItemToHaul itemToHaul, Item item, SubInventoryType targetSubInventory, bool isGeneralListItem)
	{
		if (ReturnIsItemToHaul(item))
		{
			itemToHaul = null;
			return false;
		}
		if (ItemToHaul.TryGet(out itemToHaul, this, item, targetSubInventory, isGeneralListItem))
		{
			ItemToHaul.HaulState state = itemToHaul.State;
			if ((uint)(state - 1) <= 1u)
			{
				_itemsToHaul.Add(itemToHaul);
			}
			return true;
		}
		UnityEngine.Debug.LogException(new Exception($"ItemToHaul '{item.Properties}' could not be restored for agent '{Agent.Name}' assigned to project '{Project.Properties}'"));
		return false;
	}

	private bool AddItemToHaulUnique(out ItemToHaul itemToHaul, Item item, SubInventoryType targetSubInventory, bool isGeneralListItem = false)
	{
		if (ReturnIsItemToHaul(item))
		{
			itemToHaul = null;
			return false;
		}
		if (ItemToHaul.TryGet(out itemToHaul, this, item, targetSubInventory, isGeneralListItem))
		{
			ItemToHaul.HaulState state = itemToHaul.State;
			if ((uint)(state - 1) <= 1u)
			{
				_itemsToHaul.Add(itemToHaul);
			}
			return true;
		}
		UnityEngine.Debug.LogException(new NotSupportedException("ItemToHaul is in state 'NONE'. this is a bug!"));
		return false;
	}

	public bool RemoveItemToHaul(ItemToHaul itemToHaul)
	{
		if (_itemsToHaul.Remove(itemToHaul))
		{
			itemToHaul.Dispose();
			return true;
		}
		return false;
	}

	public bool RemoveItemToHaul(Item item)
	{
		int count = _itemsToHaul.Count;
		while (0 < count--)
		{
			ItemToHaul itemToHaul = _itemsToHaul[count];
			if (itemToHaul.Item == item)
			{
				if (itemToHaul.State == ItemToHaul.HaulState.Transit)
				{
					UnityEngine.Debug.LogError("Item to haul should not be removed when it is in transit!");
				}
				itemToHaul.Dispose();
				_itemsToHaul.RemoveAt(count);
				return true;
			}
		}
		return false;
	}

	public void RemoveItemsToPickup()
	{
		int count = _itemsToHaul.Count;
		while (0 < count--)
		{
			ItemToHaul itemToHaul = _itemsToHaul[count];
			if (ItemToHaul.HaulState.Pickup >= itemToHaul.State)
			{
				itemToHaul.Dispose();
				_itemsToHaul.RemoveAt(count);
			}
		}
	}

	public void ReserveItem(Item item)
	{
		if (ReservedItem != item)
		{
			if (ReservedItem != null)
			{
				UnityEngine.Debug.LogError($"Adding a reserved item ({item}) to agent \"{Agent.Name}\" but it still had an associated reserved item ({ReservedItem})");
				ReservedItem.CancelReservation();
			}
			ReservedItem = item;
			item.Reserve();
		}
	}

	public void UnreserveItem(Item item)
	{
		if (ReservedItem == item)
		{
			item.CancelReservation();
			ReservedItem = null;
		}
		else
		{
			UnityEngine.Debug.LogError($"Trying to unreserve item \"{item}\" for agent \"{Agent.Name}\" but it was not reserved by this agent (currently reserved item by this agent is \"{ReservedItem}\")");
		}
	}

	public void RestoreReservedItem(Item item)
	{
		if (ReservedItem != null)
		{
			UnityEngine.Debug.LogError($"Restoring a reserved item ({item}) to agent \"{Agent.Name}\" but it still had an associated reserved item associated ({ReservedItem})");
			ReservedItem.CancelReservation();
		}
		ReservedItem = item;
	}

	public bool TryReturnItemToHaul(ItemToHaul.HaulState state, out ItemToHaul itemToHaul)
	{
		foreach (ItemToHaul item in _itemsToHaul)
		{
			if (item.State == state)
			{
				itemToHaul = item;
				return true;
			}
		}
		itemToHaul = null;
		return false;
	}

	private bool ReturnCanHaulItem(Item item)
	{
		if (item.Inventory == ReturnTransitInventory())
		{
			return true;
		}
		int num = ReturnRemainingItemToHaulCount();
		int num2 = ReturnItemHaulingCapacity();
		return num < num2;
	}

	private int ReturnRemainingItemToHaulCount()
	{
		int num = 0;
		foreach (ItemToHaul item in _itemsToHaul)
		{
			if (item.State != ItemToHaul.HaulState.Finished)
			{
				num++;
			}
		}
		return num;
	}

	private int ReturnItemHaulingCapacity()
	{
		if (Boat == null)
		{
			return Agent.Inventory.ReturnStorageCapacity();
		}
		return Boat.Buildable.Inventory.ReturnStorageCapacity();
	}

	public Inventory ReturnTransitInventory()
	{
		if (Agent.IsCaptain)
		{
			if (Agent.Boat == Boat)
			{
				return Boat.Buildable.Inventory;
			}
			UnityEngine.Debug.LogErrorFormat("'{0}' is a captain, but not of boat '{1}' referenced by the project assignment!", Agent.Name, (Boat == null) ? "null" : Boat.name);
		}
		return Agent.Inventory;
	}

	private bool HasItemsInTransitWithoutReservedStorageSpace()
	{
		foreach (ItemToHaul item in ItemsToHaul)
		{
			if (item.State == ItemToHaul.HaulState.Transit && !item.HasStorageSpaceReserved())
			{
				return true;
			}
		}
		return false;
	}

	public void ReserveBoat(Boat boat)
	{
		if (boat == null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve boat for project '{1}' because it is null!", Agent.Name, Project.Properties.name);
		}
		else if (Boat != null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve a boat '{1}' for project '{2}' because one is already reserved!", Agent.Name, boat.name, Project.Properties.name);
		}
		else if (boat.CurrentMooringPoint == null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve a boat '{1}' for project '{2}' because it is not moored!", Agent.Name, boat.name, Project.Properties.name);
		}
		else if (ReservedEmbarkMooringPoint != null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve a embark mooring point for project '{1}' because one is already reserved!", Agent.Name, Project.Properties.name);
		}
		else if (boat.CurrentMooringPoint.Reserve(Agent, Project))
		{
			Boat = boat;
			ReservedEmbarkMooringPoint = boat.CurrentMooringPoint;
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve embark mooring point for project '{1}'", Agent.Name, Project.Properties.name);
		}
	}

	public bool ReserveAgentBoat(Agent agent)
	{
		if (agent.IsCaptain && (bool)Agent.Boat)
		{
			if (Boat == null)
			{
				Boat = Agent.Boat;
				return true;
			}
			UnityEngine.Debug.LogErrorFormat("Unable to reserve agent '{0}' its boat for project '{1}', because a boat is already reserved", Agent.Name, Project.Properties.name);
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("Unable to 'Reserve' agent '{0}' its boat for project '{1}'! The agent is not a captain.", Agent.Name, Project.Properties.name);
		}
		return false;
	}

	public void RestoreBoat(Boat boat)
	{
		if (boat == null)
		{
			return;
		}
		if ((bool)boat.CurrentMooringPoint)
		{
			if (boat.CurrentMooringPoint.Reserve(Agent, Project))
			{
				ReservedEmbarkMooringPoint = boat.CurrentMooringPoint;
			}
			else
			{
				UnityEngine.Debug.LogWarningFormat("'{0}' could not restore embark mooring point reservation for project '{1}'", Agent.Name, Project.Properties.name);
			}
		}
		Boat = boat;
	}

	public bool UnreserveEmbarkMooringPoint()
	{
		bool result = UnreserveMoorinPoint(ReservedEmbarkMooringPoint);
		ReservedEmbarkMooringPoint = null;
		return result;
	}

	public bool ReserveDisembarkMooringPoint(MooringPointBase mooringPoint)
	{
		if (mooringPoint == null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve mooring point for project '{1}' because it is null!", Agent.Name, Project.Properties.name);
			return false;
		}
		if (mooringPoint.MooredBoat != null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve disembark mooring point for project '{1} because a boat is already moored", Agent.Name, Project.Properties.name);
			return false;
		}
		if (ReservedDisembarkMooringPoint != null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve a disembark mooring point for project '{1}' because one is already reserved!", Agent.Name, Project.Properties.name);
			return false;
		}
		if (mooringPoint.Reserve(Agent))
		{
			ReservedDisembarkMooringPoint = mooringPoint;
			return true;
		}
		UnityEngine.Debug.LogErrorFormat("'{0}' was unable to reserve a mooring point for project '{0}'", Agent.Name, Project.Properties.name);
		return false;
	}

	public void Disembark()
	{
		if (ReservedDisembarkMooringPoint == null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' is unable to disembark, because not disembark mooring point was reserved for project '{1}'", Agent.Name, Project.Properties.name);
		}
		else if (Boat == null)
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' is unable to disembark, because it is not using a boat for project '{1}'", Agent.Name, Project.Properties.name);
		}
		else if (ReservedDisembarkMooringPoint.MoorBoat(Boat))
		{
			ReservedDisembarkMooringPoint = null;
			Boat.Disembark(Agent);
			Boat = null;
		}
	}

	private bool UnreserveDisembarkMooringPoint()
	{
		bool result = UnreserveMoorinPoint(ReservedDisembarkMooringPoint);
		ReservedDisembarkMooringPoint = null;
		return result;
	}

	private bool UnreserveMoorinPoint(MooringPointBase mooringPoint)
	{
		if (mooringPoint == null)
		{
			return false;
		}
		if (mooringPoint.IsReserved)
		{
			return mooringPoint.Unreserve(Agent);
		}
		return false;
	}

	public bool RemainsPriority(bool assignmentPriorityOnly = false)
	{
		if (ItemsToHaul.Count > 0)
		{
			return true;
		}
		return Agent.Community.ProjectRemainsPriority(Project, Agent, assignmentPriorityOnly);
	}

	public bool KeepsPriorityOver(Project project, bool idle)
	{
		if (AllowsDeprioritization && Project != project && Priority < project.AgentPriorityScore)
		{
			if (idle)
			{
				return IsIdleProject;
			}
			return false;
		}
		return true;
	}

	public Inventory ReturnTargetInventory()
	{
		if (Project.Properties.PickupOnly)
		{
			return ReturnTransitInventory();
		}
		return Project.TargetInventory;
	}

	public bool ReturnIsItemToHaul(Item item)
	{
		foreach (ItemToHaul item2 in _itemsToHaul)
		{
			if (item2.Item == item)
			{
				return true;
			}
		}
		return false;
	}

	private string ReturnItemsToHaulString()
	{
		StringBuilder stringBuilder = new StringBuilder();
		for (int i = 0; i < ItemsToHaul.Count; i++)
		{
			if (i > 0)
			{
				stringBuilder.Append(", ");
			}
			stringBuilder.Append("'").Append(ItemsToHaul[i].Item.Properties.LocalizedName).Append("'");
		}
		return stringBuilder.ToString();
	}

	public void OverrideActiveTaskIndex(int activeTaskIndex)
	{
		if (activeTaskIndex < 0 || Project.Properties.TaskQueue.Count <= activeTaskIndex)
		{
			throw new NotSupportedException("Active task index is out of bounds!");
		}
		ActiveTaskIndex = activeTaskIndex;
	}
}
