public class EmbarkBoat : TaskBase
{
	public bool BoatIsTarget;

	public override TaskType Type => TaskType.EmbarkBoat;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		if ((bool)_assignment.Boat && _assignment.Boat.Captain == agent)
		{
			UnityEngine.Debug.LogException(new Exception("'" + agent.Descriptor.Name + "' is trying to embark a boat of which it already is the captain"));
		}
		else if (BoatIsTarget)
		{
			Boat boatToReclaim = project.Target.GetComponent<Boat>();
			Target component = project.Target.GetComponent<Target>();
			if (boatToReclaim == null)
			{
				UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' assigned to '{project.Properties}' is unable to reclaim a boat because the project.Target is not a boat!"));
				_project.Stop(ProjectFlags.Exception);
			}
			else
			{
				yield return MoveAgentCoroutine(component);
				boatToReclaim.BoardCaptain(agent);
			}
		}
		else if ((bool)_assignment.ReservedEmbarkMooringPoint)
		{
			MooringPointBase mooringPoint = _assignment.ReservedEmbarkMooringPoint;
			yield return MoveAgentCoroutine(mooringPoint.EmbarkTarget);
			yield return mooringPoint.EmbarkCoroutine(agent);
			_assignment.UnreserveEmbarkMooringPoint();
		}
		else
		{
			_project.Stop(ProjectFlags.Exception);
			UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' assigned to '{project.Properties}' is trying to embark a boat, but does not have an embark mooring point reserved!"));
		}
	}

	protected override void OnGUI()
	{
		Header("Embark boat", 1, ReturnTypeColor());
		BoatIsTarget = EditorGUI_Toggle("Reclaim", BoatIsTarget);
		EditorGUI_HelpBox("Moves to and embarks a boat.");
	}
}
public class ReserveBoat : TaskBase, IComparer<MooringPointBase>
{
	public bool ReserveMooringPointAtTarget;

	public BoatType BoatType;

	public bool ReserveProjectTarget;

	private Vector3 _agentPosition;

	public override TaskType Type => TaskType.ReserveBoat;

	public override bool DoYieldReturn => false;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		if (agent.IsCaptain)
		{
			yield break;
		}
		if (ReserveProjectTarget)
		{
			Boat component = project.Target.GetComponent<Boat>();
			if (component == null)
			{
				UnityEngine.Debug.LogErrorFormat("'{0}' could not reserve boat because project target '{1}' is not a boat!", agent.Name, project.Target);
			}
			else if (component.CurrentMooringPoint == null)
			{
				UnityEngine.Debug.LogWarningFormat("'{0}' could not reserve boat for project '{1}'!", agent.Name, project.Properties.name);
			}
			else
			{
				_assignment.ReserveBoat(component);
			}
		}
		else if (ReserveMooringPointAtTarget)
		{
			Target navigationTarget = project.NavigationTarget;
			if (navigationTarget == null)
			{
				_project.Stop(ProjectFlags.Exception);
				UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' assigned to '{_project.Properties}' was unable to reserve a boat of type '{BoatType}' because the project.NavigationTarge is NULL!"));
			}
			else if (!TryReserveEmbarkAndDisembarkMooringPoint(agent, navigationTarget))
			{
				_project.Stop(ProjectFlags.Exception);
				UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' assigned to '{_project.Properties}' was unable to reserve a boat of type '{BoatType}' because none are available in its community or was unable to reserve a mooring point at target '{navigationTarget.transform.RetrieveHierarchyString()}'"));
			}
		}
		else if (!TryReserveEmbarkMoorinPoint(agent))
		{
			_project.Stop(ProjectFlags.Exception);
			UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' assigned to '{_project.Properties}' was unable to reserve a boat of type '{BoatType}' because none are available in its community"));
		}
	}

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		ProjectBlocker projectBlocker = ProjectBlocker.None;
		if (!ReserveProjectTarget)
		{
			if (ReserveMooringPointAtTarget)
			{
				if (!ReturnCommunityHasBoatAvailableForTarget(Community.PlayerCommunity, project.NavigationTarget))
				{
					projectBlocker |= ProjectBlocker.NoBoatAvailable;
				}
			}
			else if (!ReturnCommunityHasBoatAvailable(Community.PlayerCommunity))
			{
				projectBlocker |= ProjectBlocker.NoBoatAvailable;
			}
		}
		if (!GameManager.WorldManager.IsInBoatRadius(project.Target.transform.position))
		{
			projectBlocker |= ProjectBlocker.BoatOutOfRange;
		}
		return projectBlocker;
	}

	protected override void OnGUI()
	{
		Header("Reserve boat", 3, ReturnTypeColor());
		ReserveMooringPointAtTarget = EditorGUI_Toggle("Reserve mooring point at target?", ReserveMooringPointAtTarget);
		BoatType = (BoatType)(object)EditorGUI_EnumField("Required Boat Type", BoatType);
		ReserveProjectTarget = EditorGUI_Toggle("Reserve the project's target boat's mooring point instead of the closest mooring point.?", ReserveProjectTarget);
		EditorGUI_HelpBox("Reserves the closest available boat from a mooring point.");
	}

	public bool ReturnCommunityHasBoatAvailableForTarget(Community community, Target target)
	{
		if (target == null)
		{
			return false;
		}
		using ListPool<MooringPoint>.List list = ReturnEmbarMooringPoints(community);
		foreach (MooringPoint item in list)
		{
			if (target.TryReturnAvailableMooringPoint(item.MooredBoat, out var _))
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnCommunityHasBoatAvailable(Community community)
	{
		using ListPool<MooringPoint>.List list = ReturnEmbarMooringPoints(community);
		return 0 < list.Count;
	}

	private bool TryReserveEmbarkMoorinPoint(Agent agent)
	{
		using ListPool<MooringPoint>.List list = ReturnEmbarMooringPoints(agent.Community);
		if (0 < list.Count)
		{
			_assignment.ReserveBoat(list[0].MooredBoat);
			return true;
		}
		return false;
	}

	private bool TryReserveEmbarkAndDisembarkMooringPoint(Agent agent, Target target)
	{
		using ListPool<MooringPoint>.List list = ReturnEmbarMooringPoints(agent.Community);
		foreach (MooringPoint item in list)
		{
			if (target.TryReturnAvailableMooringPoint(item.MooredBoat, out var mooringPoint))
			{
				_assignment.ReserveBoat(item.MooredBoat);
				_assignment.ReserveDisembarkMooringPoint(mooringPoint);
				return true;
			}
		}
		return false;
	}

	private ListPool<MooringPoint>.List ReturnEmbarMooringPoints(Community community)
	{
		ListPool<MooringPoint>.List list = ListPool<MooringPoint>.Get();
		foreach (MooringPoint item in community.ReturnAllMooringPoints())
		{
			if (item.ReturnHasAvailableBoat(BoatType))
			{
				list.Add(item);
			}
		}
		if (_assignment != null)
		{
			_agentPosition = _assignment.Agent.transform.position;
			Sorting.SlowSort(list, this);
		}
		return list;
	}

	public int Compare(MooringPointBase x, MooringPointBase y)
	{
		float num = _agentPosition.DistanceToLeveledSquared(x.transform.position);
		float num2 = _agentPosition.DistanceToLeveledSquared(y.transform.position);
		return (int)(num - num2);
	}
}
public class TryReserveCaptainedBoat : TaskBase
{
	public override TaskType Type => TaskType.ReserveBoat;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		if (agent.IsCaptain)
		{
			_assignment.ReserveAgentBoat(agent);
		}
		yield break;
	}

	protected override void OnGUI()
	{
		Header("Try Reserve captained boat", 0, ReturnTypeColor());
		EditorGUI_HelpBox("Special task that tries to 'Reserve' the agents boat when it is a captain, if not nothing happens. This task should only be used for projects that do not have a ReserveBoat task but do have a Disembark task (e.g. GotToTowm).");
	}
}
public class MoveConstructionResource : TaskBase
{
	[SerializeField]
	private SubInventoryType _from = SubInventoryType.Resources;

	[SerializeField]
	private SubInventoryType _to = SubInventoryType.Composition;

	[SerializeField]
	private float _duration;

	[SerializeField]
	private GameEventType _movedEvent = GameEventType.AgentActionCompositionAdded;

	private Item _resourceToMove;

	public override TaskType Type => TaskType.CompleteComposition;

	public float Duration => _duration;

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		Inventory targetInventory = project.TargetInventory;
		if (targetInventory != null)
		{
			if (targetInventory.TryReturnFirstAvailableItem(_from, out var _))
			{
				return ProjectBlocker.None;
			}
		}
		else
		{
			project.Stop(ProjectFlags.Exception);
		}
		return ProjectBlocker.NoItemAvailable;
	}

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		Navigator navigator = agent.ReturnNavigator();
		Buildable buildable = project.TargetBuildable;
		Inventory inventory = project.TargetInventory;
		Day day = GameManager.TimeManager.CurrentDay;
		navigator.UpdateTerrain(Navigator.TerrainType.Construction, overrideUpdate: true);
		if (buildable != null)
		{
			buildable.BuildSlots.Attach(agent.transform);
		}
		agent.UpdateActivity(Activity.Building);
		new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, DrifterAttributes.AttributeType.Construction).Dispatch();
		float timer = 0f;
		while (TryReturnNextResource(project, day, out _resourceToMove))
		{
			_assignment.ReserveItem(_resourceToMove);
			while (timer < _duration && project.Assignments.Count <= project.AssignmentLimit)
			{
				timer += Time.deltaTime * agent.Attributes.ReturnAttributeModifier(DrifterAttributes.AttributeType.Construction);
				yield return null;
			}
			if (_duration <= timer)
			{
				inventory.MoveToSubInventory(_resourceToMove, _to);
				timer = 0f;
			}
			_assignment.UnreserveItem(_resourceToMove);
			new AgentActionItemPropertiesEvent(_movedEvent, agent, _resourceToMove.Properties, DrifterAttributes.AttributeType.Construction).Dispatch();
		}
		if (buildable != null)
		{
			buildable.BuildSlots.Detach(GameManager.AgentManager.AgentParent);
		}
		navigator.AttachToTarget(agent.ReturnClosestConstruction(onlyFinished: true).Target, overrideCheck: true);
		new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, DrifterAttributes.AttributeType.Construction).Dispatch();
	}

	public override void Stop()
	{
		if (_resourceToMove != null)
		{
			_assignment.UnreserveItem(_resourceToMove);
		}
	}

	public override bool ReturnCanFinish(Project project)
	{
		return project.TargetInventory.ReturnIsEmpty(_from);
	}

	protected override void OnGUI()
	{
		Header("Move Construction Resource", 4, ReturnTypeColor());
		EditorGUI_PropertyField("_from");
		EditorGUI_PropertyField("_to");
		EditorGUI_PropertyField("_duration");
		EditorGUI_PropertyField("_movedEvent");
		EditorGUI_HelpBox("Complete the composition list of an inventory.");
	}

	private bool TryReturnNextResource(Project project, Day day, out Item resource)
	{
		resource = null;
		if (project.Assignments.Count > project.AssignmentLimit || day.DayTime != Day.E_DayTime.Day)
		{
			return false;
		}
		if (_assignment.ReservedItem != null)
		{
			resource = RestoreReservedItemReference(project.TargetInventory);
			return true;
		}
		return project.TargetInventory.TryReturnFirstAvailableItem(_from, out resource);
	}

	private Item RestoreReservedItemReference(Inventory inventory)
	{
		Item reservedItem = _assignment.ReservedItem;
		foreach (Item item in (IEnumerable<Item>)inventory.ReturnAllItems(_from))
		{
			if (item.Properties == reservedItem.Properties)
			{
				_assignment.UnreserveItem(reservedItem);
				return item;
			}
		}
		return reservedItem;
	}
}
