public class ItemToHaul
{
	public enum HaulState
	{
		None,
		Pickup,
		Transit,
		Finished
	}

	private const float DRIFTER_RIG_EVENT_TIMEOUT = 10f;

	private ProjectAssignment _projectAssignment;

	private int _drifterEventAmount;

	private float _drifterFailsafeTimer;

	private DrifterRigEventType _drifterRigEventType;

	public Item Item { get; private set; }

	public HaulState State { get; private set; }

	public Inventory TargetInventory { get; private set; }

	public SubInventoryType TargetSubInventory { get; private set; }

	public Target MoveToTarget { get; private set; }

	public bool IsGeneralListItem { get; private set; }

	private ItemToHaul(ProjectAssignment projectAssignment, Item item, Inventory targetInventory, SubInventoryType targetSubInventory, bool isGeneralListItem)
	{
		_projectAssignment = projectAssignment;
		IsGeneralListItem = isGeneralListItem;
		Item = item;
		Item.Project = projectAssignment.Project;
		TargetInventory = targetInventory;
		TargetSubInventory = targetSubInventory;
		if (item.Inventory == TargetInventory && item.SubInventory == TargetSubInventory)
		{
			SetState(HaulState.Finished);
		}
		else if (item.Inventory == _projectAssignment.ReturnTransitInventory())
		{
			SetState(HaulState.Transit);
		}
		else
		{
			SetState(HaulState.Pickup);
		}
	}

	public static bool TryGet(out ItemToHaul itemToHaul, ProjectAssignment assignment, Item item, SubInventoryType targetSubInventory, bool isGeneralListItem)
	{
		Inventory inventory;
		if ((bool)item.MoveToInventory)
		{
			inventory = item.MoveToInventory;
			targetSubInventory = inventory.ReturnCorrectItemSubInventory(item, targetSubInventory);
		}
		else if ((bool)assignment.Boat)
		{
			inventory = assignment.Boat.Buildable.Inventory;
			targetSubInventory = SubInventoryType.Storage;
		}
		else
		{
			inventory = assignment.ReturnTargetInventory();
			if (inventory != null)
			{
				targetSubInventory = inventory.ReturnCorrectItemSubInventory(item, targetSubInventory);
			}
		}
		if (inventory == null)
		{
			itemToHaul = null;
			return false;
		}
		itemToHaul = new ItemToHaul(assignment, item, inventory, targetSubInventory, isGeneralListItem);
		return true;
	}

	public IEnumerator IncrementStateCoroutine(DrifterRigEventType rigEventType, DrifterAttributes.AttributeType modifierType = DrifterAttributes.AttributeType.None)
	{
		if (Item == null || Item.Owner == null || Item.Inventory == null || !HasValidProject())
		{
			yield break;
		}
		Agent agent = _projectAssignment.Agent;
		InventoryBase inventory = Item.Inventory;
		switch (State)
		{
		case HaulState.Pickup:
		{
			Inventory inventory2 = _projectAssignment.ReturnTransitInventory();
			if (!(inventory2 == TargetInventory))
			{
				yield return TransferItemCoroutine(agent, rigEventType, inventory.PickupActivity, inventory.AnimationCycles, modifierType, inventory2);
				if (HasValidProject())
				{
					SetState(HaulState.Transit);
				}
				break;
			}
			goto case HaulState.Transit;
		}
		case HaulState.Transit:
			yield return TransferItemCoroutine(agent, rigEventType, inventory.DropoffActivity, inventory.AnimationCycles, modifierType, TargetInventory, TargetSubInventory);
			if (HasValidProject())
			{
				SetState(HaulState.Finished);
			}
			break;
		}
	}

	public bool Consume()
	{
		if (State == HaulState.Pickup && Item.Inventory == null)
		{
			SetState(HaulState.Finished);
			return true;
		}
		return false;
	}

	public void Remove()
	{
		Item.TakeFromInventory();
		Item.Inventory = null;
		SetState(HaulState.Finished);
	}

	private IEnumerator TransferItemCoroutine(Agent agent, DrifterRigEventType rigEventType, Activity agentActivity, int animationCycles, DrifterAttributes.AttributeType modifierType, Inventory targetInventory, SubInventoryType targetSubInventory = SubInventoryType.Storage)
	{
		if (targetInventory.FitsInInventory(Item, targetSubInventory))
		{
			agent.UpdateActivity(agentActivity);
			if (targetInventory.Type == InventoryType.Boat || targetInventory.Type == InventoryType.Agent)
			{
				agent.LookAtObject(Item.Owner.transform);
			}
			else
			{
				agent.LookAtObject(targetInventory.ReturnDropOffTarget(targetSubInventory));
			}
			_drifterRigEventType = rigEventType;
			_drifterEventAmount = 0;
			float num = agent.Attributes.ReturnAttributeModifier(modifierType);
			AnimatorHelper.AddDrifterRigTypeEventListener(agent, OnDrifterEvent);
			AnimatorHelper.SetFloat(agent, "Speed Multiplier", num);
			bool flag = HasValidProject();
			float drifterRigEventTimeout = 10f / Mathf.Max(0.1f, num);
			_drifterFailsafeTimer = 0f;
			while (_drifterEventAmount < animationCycles && flag)
			{
				_drifterFailsafeTimer += Time.deltaTime;
				if (_drifterFailsafeTimer >= drifterRigEventTimeout)
				{
					UnityEngine.Debug.LogWarning($"DrifterRigEvent timed out after {_drifterFailsafeTimer} seconds for '{agent.Name}' trying to transfer item '{Item.Properties.LocalizedName}'");
					OnDrifterEvent(_drifterRigEventType);
				}
				yield return null;
				flag = HasValidProject();
			}
			AnimatorHelper.RemoveDrifterRigTypeEventListener(agent, OnDrifterEvent);
			AnimatorHelper.SetFloat(agent, "Speed Multiplier", 1f);
			if (flag)
			{
				GameManager.WorldManager.SpawnAndThrowFlotsam(ThrowProperties.ReturnTransferProperties(Item, targetInventory, targetSubInventory));
				AudioManager.Play(Item.Properties.FlotsamProperties.HaulingAudio, Item.Owner.transform);
				GameManager.Settings.AudioSettings.PlayInventoryTypeSound(Item.Inventory.Type, Item.Inventory.transform);
				TransferItemToInventory(targetInventory, targetSubInventory);
			}
		}
		else
		{
			UnityEngine.Debug.LogErrorFormat("'{0}' was unable to increment state of ItemToHaul '{1}' because it does not fit in the current states target inventory '{2}->{3}'!", agent.Name, Item.Properties.name, TargetInventory.name, TargetSubInventory);
		}
	}

	private void OnDrifterEvent(DrifterRigEventType evt)
	{
		if (evt == _drifterRigEventType)
		{
			_drifterEventAmount++;
			_drifterFailsafeTimer = 0f;
		}
	}

	private void TransferItemToInventory(Inventory transferToInventory, SubInventoryType transferToSubInventory)
	{
		Item item = Item.Inventory.TakeItem(Item);
		if (item == null || !transferToInventory.AddItem(item, transferToSubInventory))
		{
			UnityEngine.Debug.LogException(new Exception($"Unable to transfer item '{Item.Properties.name}' from inventory '{Item.Inventory.name}/{Item.SubInventory}' to inventory '{transferToInventory.name}/{transferToSubInventory}'"));
		}
	}

	private void SetState(HaulState state)
	{
		if (State != state)
		{
			State = state;
			switch (state)
			{
			case HaulState.Pickup:
				MoveToTarget = Item.Inventory.Target;
				break;
			case HaulState.Transit:
				MoveToTarget = TargetInventory.GetComponentInChildren<Target>();
				break;
			case HaulState.Finished:
				Dispose(finished: true);
				_projectAssignment.RemoveItemToHaul(this);
				MoveToTarget = null;
				break;
			}
		}
	}

	public void Dispose(bool finished = false)
	{
		HaulState state = State;
		if (state != HaulState.Pickup)
		{
			if (state == HaulState.Transit)
			{
				if (finished)
				{
					throw new NotSupportedException($"Assignment for project '{_projectAssignment.Project.Properties.name}' has finished, but ItemToHaul '{Item.Properties.LocalizedName}' is in transit state, this is a bug!");
				}
				goto IL_0128;
			}
		}
		else
		{
			if (finished)
			{
				UnityEngine.Debug.LogErrorFormat("ItemToHaul '{0}' was disposed in pickup state, but '{1}' its assignment for project '{2}' has already finished!", Item.Properties.LocalizedName, _projectAssignment.Agent.Name, _projectAssignment.Project.Properties.name);
			}
			if (IsGeneralListItem)
			{
				Item.Project.GeneralItems.Add(Item);
				return;
			}
		}
		if (Item.UnreserveMoveToInventory() && finished)
		{
			UnityEngine.Debug.LogWarningFormat("ItemToHaul '{0}' was disposed while it had a inventory space reserved!", Item.Properties.LocalizedName);
		}
		if (Item.CancelReservation() && finished)
		{
			UnityEngine.Debug.LogWarningFormat("ItemToHaul '{0}' was disposed while it was reserved!", Item.Properties.LocalizedName);
		}
		goto IL_0128;
		IL_0128:
		Item.Project = null;
	}

	public bool ReturnCanIncrementState()
	{
		return State switch
		{
			HaulState.Pickup => _projectAssignment.Agent.Inventory.FitsInInventory(Item), 
			HaulState.Transit => TargetInventory.FitsInInventory(Item, TargetSubInventory), 
			_ => false, 
		};
	}

	public bool HasValidProject()
	{
		return Item.Project?.IsValid() ?? false;
	}

	public bool HasStorageSpaceReserved()
	{
		if (TargetInventory.Type == InventoryType.Storage && (bool)TargetInventory.Storage)
		{
			return TargetInventory.Storage.HasItemIncoming(Item);
		}
		return false;
	}
}
public class PickupItems : TaskBase
{
	public DrifterRigEventType AnimationEventType;

	public override TaskType Type => TaskType.PickupItem;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		yield return RunHaulStateCoroutine(agent, ItemToHaul.HaulState.Pickup);
	}

	private IEnumerator RunHaulStateCoroutine(Agent agent, ItemToHaul.HaulState state)
	{
		ItemToHaul itemToHaul;
		while (_assignment.TryReturnItemToHaul(state, out itemToHaul))
		{
			yield return MoveAgentCoroutine(itemToHaul.MoveToTarget);
			new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
			yield return itemToHaul.IncrementStateCoroutine(AnimationEventType);
			new AgentActionItemPropertiesEvent(GameEventType.AgentActionItemHauled, agent, itemToHaul.Item.Properties, DrifterAttributes.AttributeType.Athletics).Dispatch();
			new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
		}
	}

	protected override void OnGUI()
	{
		Header("Pickup Items", 1, Color.magenta);
		EditorGUI_PropertyField("AnimationEventType", "Rig Animation Event Type");
		EditorGUI_HelpBox("Picks up the items reserved by the 'Reserve Items To Haul' task");
	}
}
public class ReserveGeneralItemsToHaul : TaskBase
{
	[SerializeField]
	private SubInventoryType _targetSubInventory;

	[SerializeField]
	private ReserveFillInventory.SortingMethod _sortingMethod;

	public override TaskType Type => TaskType.ReserveGeneralItemsToHaul;

	public override void Initialize(ProjectAssignment assignment)
	{
		base.Initialize(assignment);
		if (!_agent.Inventory.ReturnIsEmpty())
		{
			UnityEngine.Debug.LogWarningFormat("Initializing items to transfer for agent '{0}' assigned to project '{1}' that still has items in it's inventory!", assignment.Agent.Name, assignment.Project.Properties.name);
		}
	}

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		ListPool<Item>.List list = ListPool<Item>.Get(project.GeneralItems);
		SubInventoryType subInventoryType = _targetSubInventory;
		using (list)
		{
			switch (_sortingMethod)
			{
			case ReserveFillInventory.SortingMethod.Range:
				ItemDistanceComparer.SortByShortestDistance(agent.transform.position, list);
				break;
			case ReserveFillInventory.SortingMethod.UnityNavMeshPath:
				ReserveFillInventory.SortedItemsByDistanceFromMooringpoint(agent, project, list);
				break;
			}
			foreach (Item item in list)
			{
				if (item.Project != null && item.Project != project)
				{
					continue;
				}
				item.Reserve();
				if (project.Properties.RequiresGeneralStorageSpace)
				{
					if (item.MoveToInventory != null)
					{
						if (item.Inventory != _assignment.ReturnTransitInventory())
						{
							UnityEngine.Debug.LogException(new Exception("Cannot reserve storage space for an item that already has storage space reserved!"));
							item.UnreserveMoveToInventory();
						}
						if (item.TryGetMoveToSubInventoryType(out var subInventoryType2))
						{
							subInventoryType = subInventoryType2;
						}
						else
						{
							item.UnreserveMoveToInventory();
						}
					}
					if (item.MoveToInventory == null && !agent.Community.ReserveIncomingItems(item, subInventoryType))
					{
						continue;
					}
				}
				if (!_assignment.AddGeneralItemToHaul(item, subInventoryType))
				{
					if (project.Properties.RequiresGeneralStorageSpace)
					{
						item.UnreserveMoveToInventory();
					}
					break;
				}
			}
		}
		yield break;
	}

	protected override void OnGUI()
	{
		Header("Reserve General Items To Haul", 2, Color.cyan);
		_targetSubInventory = (SubInventoryType)(object)EditorGUI_EnumField("Target Subinventory", _targetSubInventory);
		_sortingMethod = (ReserveFillInventory.SortingMethod)(object)EditorGUI_EnumField("Sorting Method", _sortingMethod);
		EditorGUI_HelpBox("Reserve the amount of items that fit the assignments transit inventory from this projects general list and add them as items to haul.");
	}
}
public class ReserveResourceProviderItemsToHaul : TaskBase
{
	public override TaskType Type => TaskType.ReserveResourceProviderItemsToHaul;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		int haulingPriority = ReturnHaulingPriority(agent);
		using ListPool<ResourceProvider>.List list = ListPool<ResourceProvider>.Get();
		using ListPool<ResourceProvider>.List list2 = ListPool<ResourceProvider>.Get();
		agent.Community.Inventory.PopulateResourceProviders(agent, haulingPriority, applyCapacityPriority: true, list);
		foreach (ResourceProvider item2 in list)
		{
			item2.UpdatePriorityWithCapacity(agent, haulingPriority);
		}
		while (TryPopulatePrioritizedResourceProviders(list, list2))
		{
			foreach (ResourceProvider item3 in list2)
			{
				Item item;
				while (item3.TryReturnFirstExportableItem(out item) && agent.Community.ReserveIncomingItems(item, SubInventoryType.Storage))
				{
					if (_assignment.AddItemToHaul(item))
					{
						item.Reserve();
						continue;
					}
					item.UnreserveMoveToInventory();
					yield break;
				}
			}
			list.RemoveRange(list2);
			list2.Clear();
		}
	}

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		if (Community.PlayerCommunity.Inventory.ReturnHasResourceProviderWithExportableItems())
		{
			return ProjectBlocker.None;
		}
		return ProjectBlocker.StorageSpace;
	}

	public override bool TryReturnAgentPriority(out int priority, Project project, Agent agent, int weight)
	{
		int haulingPriority = ReturnHaulingPriority(agent);
		using ListPool<ResourceProvider>.List list = ListPool<ResourceProvider>.Get();
		using ListPool<ResourceProvider>.List list2 = ListPool<ResourceProvider>.Get();
		agent.Community.Inventory.PopulateResourceProviders(agent, haulingPriority, applyCapacityPriority: true, list);
		foreach (ResourceProvider item in list)
		{
			item.UpdatePriority(agent, haulingPriority);
		}
		while (TryPopulatePrioritizedResourceProviders(list, list2))
		{
			foreach (ResourceProvider item2 in list2)
			{
				if (item2.HasExportableItems())
				{
					priority = item2.Priority;
					return true;
				}
			}
			list.RemoveRange(list2);
			list2.Clear();
		}
		priority = 0;
		return false;
	}

	protected override void OnGUI()
	{
		Header("Reserve Resource Provider Items To Haul", 1, ReturnTypeColor());
		EditorGUI_PropertyField("_exportInventoryFullPriority");
		EditorGUI_HelpBox("Reserve items in resource providers that are ready to be hauled to a storage.");
	}

	private AssignmentType ReturnPrioritizedAssignmentTypes(Agent agent, out AssignmentPriority priority)
	{
		AssignmentType assignmentType = AssignmentType.Hauling | agent.Community.Inventory.ReturnResourceProvidersAssignmentTypes();
		AssignmentType assignmentType2 = AssignmentType.None;
		priority = AssignmentPriority.Lowest;
		foreach (Assignment assignment in agent.Assignments)
		{
			if ((assignmentType & assignment.Type) != AssignmentType.None)
			{
				if (priority == assignment.Priority)
				{
					assignmentType2 |= assignment.Type;
				}
				else if (priority < assignment.Priority)
				{
					priority = assignment.Priority;
					assignmentType2 = assignment.Type;
				}
			}
		}
		return assignmentType2;
	}

	private int ReturnHaulingPriority(Agent agent)
	{
		if (TryReturnAssignment(out var assignment, agent, AssignmentType.Hauling))
		{
			return assignment.PriorityWeight + assignment.OrderWeightSeconday;
		}
		return 0;
	}

	private bool TryReturnAssignment(out Assignment assignment, Agent agent, AssignmentType assignmentType)
	{
		for (int i = 0; i < agent.Assignments.Count; i++)
		{
			assignment = agent.Assignments[i];
			if (assignment.Type == assignmentType)
			{
				return assignment.Priority != AssignmentPriority.None;
			}
		}
		assignment = null;
		return false;
	}

	private int ReturnResourceProviderPriority(Agent agent, ResourceProvider resourceProvider, int primaryAssignmentWeight)
	{
		int num = 0;
		int count = agent.Assignments.Count;
		while (0 < count--)
		{
			Assignment assignment = agent.Assignments[count];
			if ((assignment.Type & resourceProvider.AssignmentType) != AssignmentType.None)
			{
				int num2 = assignment.PriorityWeight + assignment.OrderWeight * primaryAssignmentWeight;
				if (num < num2)
				{
					num = num2;
				}
			}
		}
		return num;
	}

	private bool TryReturnHaulableItem(AssignmentType assignmentType, out Item haulableItem)
	{
		haulableItem = _agent.Community.Inventory.ReturnAvailableResourceProviderItem(assignmentType);
		return haulableItem != null;
	}

	private bool TryPopulatePrioritizedResourceProviders(List<ResourceProvider> resourceProviders, List<ResourceProvider> prioritizedResourceProviders)
	{
		int num = 0;
		int count = resourceProviders.Count;
		while (0 < count--)
		{
			ResourceProvider resourceProvider = resourceProviders[count];
			int priority = resourceProvider.Priority;
			if (priority == num)
			{
				prioritizedResourceProviders.Add(resourceProvider);
			}
			else if (priority > num)
			{
				prioritizedResourceProviders.Clear();
				prioritizedResourceProviders.Add(resourceProvider);
				num = resourceProvider.Priority;
			}
		}
		return prioritizedResourceProviders.Count > 0;
	}
}
