[Serializable]
public class MoveToFreeNode : TaskBase
{
	public string taskName;

	public override TaskType Type => TaskType.RescueLandmark;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		while (!Pathfinder.HasInstance)
		{
			yield return null;
		}
		HierarchicalNodeMarker component = project.Target.GetComponent<HierarchicalNodeMarker>();
		using ListPool<HierarchicalNodeMarker>.List neighbours = GetNeighbours(component);
		HierarchicalNode newTargetNode = null;
		foreach (HierarchicalNodeMarker item in neighbours)
		{
			if (item.IsFree)
			{
				item.ReservedForIdling = true;
				newTargetNode = item.Node;
				break;
			}
		}
		if (newTargetNode == null)
		{
			newTargetNode = neighbours[neighbours.Count - 1].Node;
		}
		PathfindingNodeTarget target = new PathfindingNodeTarget(newTargetNode);
		yield return MoveAgentCoroutine(target);
		if (newTargetNode.Graph == null)
		{
			agent.ReturnNavigator().StopNavigation(ProjectFlags.Exception);
			yield break;
		}
		newTargetNode.Marker.ReservedForIdling = false;
		agent.ReturnNavigator().AttachToNode(newTargetNode);
	}

	private ListPool<HierarchicalNodeMarker>.List GetNeighbours(HierarchicalNodeMarker startNodeMarker)
	{
		ListPool<HierarchicalNodeMarker>.List list = ListPool<HierarchicalNodeMarker>.Get();
		foreach (PathfindingNode item in (IEnumerable<PathfindingNode>)startNodeMarker.Node.Neighbors.FindAll((PathfindingNode n) => n.Graph.GraphType == Graph.Type.Constructions))
		{
			AddMarkerToNeighbours(item, list);
			foreach (PathfindingNode item2 in (IEnumerable<PathfindingNode>)item.Neighbors.FindAll((PathfindingNode n) => n.Graph.GraphType == Graph.Type.Constructions))
			{
				if (item2 != startNodeMarker.Node)
				{
					AddMarkerToNeighbours(item2, list);
				}
			}
		}
		list.OrderBy((HierarchicalNodeMarker m) => Vector3.Distance(m.transform.position, startNodeMarker.transform.position));
		return list;
	}

	private void AddMarkerToNeighbours(PathfindingNode node, List<HierarchicalNodeMarker> neighboursList)
	{
		if (node is HierarchicalNode hierarchicalNode && !neighboursList.Contains(hierarchicalNode.Marker))
		{
			neighboursList.Add(hierarchicalNode.Marker);
		}
	}

	protected override void OnGUI()
	{
		Header("Move to free node", 0, Color.green);
		EditorGUI_HelpBox("Move towards closest free node on construction.");
	}
}
public class Research : TaskBase
{
	public override TaskType Type => TaskType.Research;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		CommunityResearch research = agent.Community.Research;
		ResearchStation station = research.ReturnClosestAvailableResearchStation(agent);
		if (station == null)
		{
			throw new NotImplementedException($"Cannot run research task for {agent.Name} as no station was available.");
		}
		CommunityResearch buildingResearch = station.Buildable.Community.Research;
		station.ReservingAgent = agent;
		Target component = station.GetComponent<Target>();
		yield return MoveAgentCoroutine(component);
		new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, DrifterAttributes.AttributeType.Research).Dispatch();
		station.StartResearch(agent);
		while (!station.Research(agent) && buildingResearch.RequiresMoreResearchStations(station) && buildingResearch.HasPointToResearch(station) && station.ReturnCanRun())
		{
			yield return null;
		}
		station.FinishResearch();
		new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, DrifterAttributes.AttributeType.Research).Dispatch();
	}

	public override void Stop()
	{
		ResearchStation researchStation = _agent.Community.Research.ReturnReservedResearchStation(_agent);
		if (researchStation != null)
		{
			researchStation.StopResearch();
		}
	}

	protected override void OnGUI()
	{
		Header("Research", 0, ReturnTypeColor());
		EditorGUI_HelpBox("Research the current research at all stations.");
	}

	public override bool ReturnCanFinish(Project project)
	{
		return !Community.PlayerCommunity.Research.IsResearching();
	}

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		ProjectBlocker projectBlocker = base.ReturnBlockers(project);
		CommunityResearch research = Community.PlayerCommunity.Research;
		if (research.CurrentResearch == null)
		{
			projectBlocker |= ProjectBlocker.NoResearch;
		}
		if (!research.HasAvailableResearchStation())
		{
			projectBlocker |= ProjectBlocker.NoResearch;
		}
		if (!research.RequiresMoreResearchStations(null))
		{
			return ProjectBlocker.BuildingNotAvailable;
		}
		if (!research.HasPointToResearch(null))
		{
			return ProjectBlocker.BuildingNotAvailable;
		}
		return projectBlocker;
	}
}
public class ReserveFillInventory : TaskBase
{
	public enum SortingMethod
	{
		None,
		Range,
		UnityNavMeshPath
	}

	internal struct SortedItem<T>
	{
		internal T Item;

		internal float Value;

		public SortedItem(T item, float value)
		{
			Item = item;
			Value = value;
		}
	}

	[SerializeField]
	private SortingMethod _sortingMethod;

	public override TaskType Type => TaskType.ReserveFillInventory;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		ListPool<Item>.List list = ListPool<Item>.Get(project.GeneralItems);
		using (list)
		{
			switch (_sortingMethod)
			{
			case SortingMethod.Range:
				ItemDistanceComparer.SortByShortestDistance(agent.transform.position, list);
				break;
			case SortingMethod.UnityNavMeshPath:
				SortedItemsByDistanceFromMooringpoint(agent, project, list);
				break;
			}
			foreach (Item item in list)
			{
				if (!_assignment.AddGeneralItemToHaul(item))
				{
					break;
				}
			}
		}
		yield break;
	}

	protected override void OnGUI()
	{
		Header("Reserve and fill inventory", 1, ReturnTypeColor());
		_sortingMethod = (SortingMethod)(object)EditorGUI_EnumField("Sorting Methods", _sortingMethod);
		EditorGUI_HelpBox("Reserve the amount of items that fit the assignments transit inventory from this projects general list and add them as items to haul.");
	}

	public static void SortedItemsByDistanceFromMooringpoint(Agent agent, Project project, List<Item> items)
	{
		MooringPointBase mooringPointBase = project.NavigationTarget.ReturnReservedMooringPoint(agent);
		if (mooringPointBase == null)
		{
			mooringPointBase = project.NavigationTarget.ReturnClosestMooringPoint(agent);
		}
		ListPool<InventoryBase>.List list = ListPool<InventoryBase>.Get();
		ListPool<SortedItem<InventoryBase>>.List list2 = ListPool<SortedItem<InventoryBase>>.Get();
		for (int i = 0; i < items.Count; i++)
		{
			InventoryBase inventory = items[i].Inventory;
			if (!list.Contains(inventory))
			{
				list.Add(inventory);
				Target target = inventory.Target;
				float num = PathfindingHelper.ReturnUnityNavMeshPathDistance(mooringPointBase.EmbarkTarget, target);
				int j;
				for (j = 0; j < list2.Count && list2[j].Value < num; j++)
				{
				}
				list2.Insert(j, new SortedItem<InventoryBase>(inventory, num));
			}
		}
		int num2 = items.Count;
		foreach (SortedItem<InventoryBase> item2 in list2)
		{
			for (int k = 0; k < num2; k++)
			{
				Item item = items[k];
				if (item.Inventory == item2.Item)
				{
					items.RemoveAt(k--);
					items.Add(item);
					num2--;
				}
			}
		}
		list.Dispose();
		list2.Dispose();
	}
}
