	public abstract TaskType Type { get; }

	public virtual bool DoYieldReturn => true;

	public virtual void Initialize(ProjectAssignment assignment)
	{
		_assignment = assignment;
		_project = assignment.Project;
		_agent = assignment.Agent;
		_agentInventory = _agent.ReturnInventory();
		_moveToTarget = null;
	}

	public virtual void Stop()
	{
	}

	public abstract IEnumerator RunTaskCoroutine(Agent agent, Project project);

	protected IEnumerator MoveAgentCoroutine(ITarget target, bool allowIncompletePath = false)
	{
		yield return MoveAgentCoroutine(target, (ITarget t) => true, allowIncompletePath);
	}

	protected IEnumerator MoveAgentCoroutine(ITarget target, ValidateTarget validateTarget, bool allowIncompletePath = false)
	{
		yield return MoveAgentCoroutine(_assignment.Agent, _assignment.Project, target, validateTarget, allowIncompletePath);
	}

	protected IEnumerator MoveAgentCoroutine(Agent agent, Project project, ITarget target, ValidateTarget validateTarget, bool allowIncompletePath = false)
	{
		if (target == null)
		{
			PajamaLlama.Debugs.Debugger.Error("No target given to move to!");
		}
		else
		{
			if (target == _moveToTarget)
			{
				yield break;
			}
			_moveToTarget = target;
			Navigator navigator = agent.ReturnNavigator();
			if (navigator.StartNavigation(target, allowIncompletePath))
			{
				while (navigator.State != NavigatorState.Idling && validateTarget(target))
				{
					yield return null;
				}
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception($"'{agent.Name}' was unable to start navigation to '{target}' while assigned to '{project.Properties}' project."));
			}
		}
	}

	protected IEnumerator RunHaulStateCoroutine(Agent agent, ItemToHaul.HaulState state, DrifterRigEventType animationEventType)
	{
		ItemToHaul itemToHaul;
		while (_assignment.TryReturnItemToHaul(state, out itemToHaul))
		{
			yield return MoveAgentCoroutine(itemToHaul.MoveToTarget);
			if (itemToHaul.HasValidProject())
			{
				new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
				yield return itemToHaul.IncrementStateCoroutine(animationEventType);
				new AgentActionItemPropertiesEvent(GameEventType.AgentActionItemHauled, agent, itemToHaul.Item.Properties, DrifterAttributes.AttributeType.Athletics).Dispatch();
				new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
			}
		}
	}

	public virtual ProjectBlocker ReturnBlockers(Agent agent)
	{
		return ProjectBlocker.None;
	}

	public virtual ProjectBlocker ReturnBlockers(Project project)
	{
		return ProjectBlocker.None;
	}

	public virtual bool ReturnCanFinish(Project project)
	{
		return true;
	}

	public virtual bool TryReturnAgentPriority(out int priority, Project project, Agent agent, int weight)
	{
		priority = 0;
		return false;
	}

	protected ITarget ReturnTarget(Agent agent, Project project, MoveTarget moveTarget, Item item = null)
	{
		switch (moveTarget)
		{
		default:
			return null;
		case MoveTarget.ProjectTarget:
		{
			if ((bool)project.Target && project.Target.TryGetComponent<Boat>(out var component))
			{
				if (component.CurrentMooringPoint != null)
				{
					return component.CurrentMooringPoint.EmbarkTarget;
				}
				return component.GetComponent<Target>();
			}
			return project.NavigationTarget;
		}
		case MoveTarget.ItemLocation:
			if (item == null)
			{
				PajamaLlama.Debugs.Debugger.Error($"Please define an item to search storage for: MoveTarget {moveTarget}.");
				return null;
			}
			if (item.Owner == null)
			{
				PajamaLlama.Debugs.Debugger.Error($"Item has no owner: MoveTarget {moveTarget}.");
				return null;
			}
			return item.Owner.GetComponentInChildren<Target>();
		case MoveTarget.NearestStorage:
		{
			if (item == null)
			{
				PajamaLlama.Debugs.Debugger.Error($"Please define an item to search storage for: MoveTarget {moveTarget}.");
				return null;
			}
			Storage storage = agent.ReturnClosestStorage(item);
			if (storage != null)
			{
				if (agent.Boat == storage.GetComponent<Target>())
				{
					PajamaLlama.Debugs.Debugger.Log("Found boat as target for NearestStorage ReturnWayPointSet().", null, 3);
				}
				return storage.GetComponentInChildren<Target>();
			}
			PajamaLlama.Debugs.Debugger.Warning("Found no available storage.");
			return null;
		}
		case MoveTarget.NearestConstruction:
		case MoveTarget.NearestCommunityConstruction:
		{
			Construction construction = agent.ReturnClosestConstruction(onlyFinished: true);
			if (construction == null)
			{
				UnityEngine.Debug.LogError("No construction available to move to!");
				return null;
			}
			return construction.ReturnGoToTownTarget(agent);
		}
		case MoveTarget.ProjectTargetMooringPoint:
			return project.NavigationTarget.ReturnClosestMooringPoint(agent).MooringTarget;
		}
	}

	protected ITarget ReturnTarget(MoveTarget moveTarget, Item item = null)
	{
		return ReturnTarget(_assignment.Agent, _assignment.Project, moveTarget, item);
	}

	protected bool TryReturnTargetBuildableExtendable<T>(Project project, out T buildableExtendable) where T : IBuildableExtendable
	{
		buildableExtendable = default(T);
		if ((bool)project.TargetBuildable)
		{
			return project.TargetBuildable.TryReturnBuildableExtendable<T>(out buildableExtendable);
		}
		return false;
	}

	public Color ReturnTypeColor()
	{
		if (!_typeColors.TryGetValue(Type, out var value))
		{
			value = UnityEngine.Random.ColorHSV();
			_typeColors.Add(Type, value);
		}
		return value;
	}
}
public class TaskListAttribute : PropertyAttribute
{
}
public class VariableHaulGeneralItems : TaskBase
{
	public TransferTarget TargetInventory;

	public SubInventoryType InventoryList;

	public MoveItemsTarget ItemsMoveTarget;

	public bool ReserveIncoming;

	public DrifterRigEventType AnimationEventType;

	public override TaskType Type => TaskType.VariableMoveItems;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		ItemToHaul itemToHaul;
		while (_assignment.TryReturnItemToHaul(ItemToHaul.HaulState.Pickup, out itemToHaul))
		{
			yield return IncrementItemToHaulState(itemToHaul, agent);
		}
		while (TryReturnGeneralItemToHaul(agent, project.GeneralItems, out itemToHaul))
		{
			if (itemToHaul.State == ItemToHaul.HaulState.Pickup)
			{
				yield return IncrementItemToHaulState(itemToHaul, agent);
				continue;
			}
			UnityEngine.Debug.LogErrorFormat("'{0}' added variable general item to haul '{1}' for project '{2}' which should be in 'Pickup' state but is in '{3}' state", agent.Name, itemToHaul.Item.Properties.LocalizedName, project.Properties.name, itemToHaul.State);
		}
		while (_assignment.TryReturnItemToHaul(ItemToHaul.HaulState.Transit, out itemToHaul))
		{
			yield return IncrementItemToHaulState(itemToHaul, agent);
		}
	}

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		ProjectBlocker projectBlocker = base.ReturnBlockers(project);
		if (ReserveIncoming && !Community.PlayerCommunity.Inventory.ReturnFitsAnyItem(project.GeneralItems))
		{
			projectBlocker |= ProjectBlocker.SharableEmptyItemList;
		}
		return projectBlocker;
	}

	protected override void OnGUI()
	{
		Header("Variable Haul General Items", 5, Color.blue);
		_itemTransferDuration = EditorGUI_FloatField("Duration", _itemTransferDuration);
		TargetInventory = (TransferTarget)(object)EditorGUI_EnumField("Target inventory", TargetInventory);
		InventoryList = (SubInventoryType)(object)EditorGUI_EnumField("Target SubInventory", InventoryList);
		ReserveIncoming = EditorGUI_Toggle("Reserve incoming", ReserveIncoming);
		EditorGUI_PropertyField("AnimationEventType", "Rig Animation Event Type");
		EditorGUI_HelpBox("Moves items from the projects general items the target subinventory. The items are not prereserved but each item is reserved individually after each item has been picked up (except the first item offcourse).This is mostly usefull for producers so an agent can pickup ingredients for multiple recipes that are manually queued");
	}

	private IEnumerator IncrementItemToHaulState(ItemToHaul itemToHaul, Agent agent)
	{
		yield return MoveAgentCoroutine(itemToHaul.MoveToTarget);
		new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
		yield return itemToHaul.IncrementStateCoroutine(AnimationEventType);
		new AgentActionItemPropertiesEvent(GameEventType.AgentActionItemHauled, agent, itemToHaul.Item.Properties, DrifterAttributes.AttributeType.Athletics).Dispatch();
		new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, DrifterAttributes.AttributeType.Athletics).Dispatch();
	}

	private bool TryReturnGeneralItemToHaul(Agent agent, List<Item> generalItems, out ItemToHaul itemToHaul)
	{
		int count = generalItems.Count;
		for (int i = 0; i < count; i++)
		{
			Item item = generalItems[i];
			if (ReserveIncoming && !agent.Community.ReserveIncomingItems(item, InventoryList))
			{
				continue;
			}
			if (_assignment.AddGeneralItemToHaul(out itemToHaul, item, InventoryList))
			{
				return true;
			}
			if (ReserveIncoming)
			{
				item.UnreserveMoveToInventory();
			}
			break;
		}
		itemToHaul = null;
		return false;
	}
}
public class ConsumeItem : TaskBase
{
	public float Duration;

	public override TaskType Type => TaskType.ConsumeItem;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		Target moveToTarget = null;
		ItemToHaul itemToHaul;
		while (_assignment.TryReturnItemToHaul(ItemToHaul.HaulState.Pickup, out itemToHaul))
		{
			if (itemToHaul.MoveToTarget != moveToTarget)
			{
				moveToTarget = itemToHaul.MoveToTarget;
				yield return MoveAgentCoroutine(moveToTarget);
			}
			yield return ConsumeCoroutine(itemToHaul.Item);
			itemToHaul.Consume();
		}
	}

	protected override void OnGUI()
	{
		Header("Consume Item", 1, ReturnTypeColor());
		Duration = EditorGUI_FloatField("Duration", Duration);
		EditorGUI_HelpBox("Consumes an item and applies its buffs.");
	}

	private IEnumerator ConsumeCoroutine(Item item)
	{
		_agent.UpdateActivity(GameSettings.Instance.ItemSettings.GetConsumeActivity(item));
		yield return new WaitForSeconds(Duration);
		_agent.Vitals.ConsumeItem(item);
		item.Inventory.TakeItem(item);
		item.Inventory = null;
	}
}
public class DiseaseSleep : TaskBase
{
	public override TaskType Type => TaskType.DiseaseSleep;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		Disease disease = agent.Vitals.Pollution.CurrentDisease;
		if (disease == null)
		{
			yield break;
		}
		Rejuvenator house = null;
		Target target;
		if (agent.ReservedHouse == null)
		{
			target = agent.ReturnClosestConstruction(onlyFinished: true).Target;
		}
		else
		{
			target = agent.ReservedHouse.GetComponentInChildren<Target>();
			house = agent.ReservedHouse.Rejuvenator;
		}
		yield return MoveAgentCoroutine(target);
		if (house != null)
		{
			house.AddAgent(agent);
		}
		agent.UpdateActivity(Activity.Sleeping);
		agent.WorldIconHandler.AddIcon(disease.Icon);
		while (!disease.Progress(agent, Time.deltaTime))
		{
			yield return null;
		}
		if (house != null)
		{
			house.RemoveAgent(agent, GameManager.AgentManager.AgentParent);
			if (!agent.ReturnNavigator().AttachToTarget(target))
			{
				agent.ReturnNavigator().AttachToTarget(agent.ReturnClosestWalkwayConstruction().Target);
			}
		}
		agent.WorldIconHandler.RemoveIcon(disease.Icon);
	}

	protected override void OnGUI()
	{
		Header("Disease - Sleep", 2, Color.cyan);
		EditorGUI_HelpBox("A disease that makes the drifter sleep for a while.");
	}
}
public class Rejuvenate : TaskBase
{
	public override TaskType Type => TaskType.Rejuvenate;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		if (!agent.Vitals.IsMarkedForDeath() && (bool)project.Target && project.Target.TryGetComponent<Rejuvenator>(out var rejuvenator))
		{
			rejuvenator.AddAgent(agent);
			agent.UpdateActivity(rejuvenator.Properties.Activity);
			rejuvenator.SetCurrentStage(Rejuvenator.Stage.Rejuvenating);
			yield return rejuvenator.RejuvenateCoroutine(agent);
			if (rejuvenator.RejuvenatesVital(VitalType.Rest))
			{
				new AgentEvent(GameEventType.AgentSleptInHouse, agent).Dispatch();
			}
			else
			{
				UnityEngine.Debug.LogException(new NotImplementedException("Rejuvenator '" + rejuvenator.Buildable.Name + "' does not rejuvenate 'Rest'."));
			}
			rejuvenator.SetCurrentStage(Rejuvenator.Stage.Idle);
			rejuvenator.RemoveAgent(agent, GameManager.AgentManager.AgentParent);
			if (!agent.ReturnNavigator().AttachToTarget(rejuvenator.GetComponent<Construction>().Target))
			{
				agent.ReturnNavigator().AttachToTarget(agent.ReturnClosestWalkwayConstruction().Target);
			}
		}
	}

	protected override void OnGUI()
	{
		Header("Rejuvenate", 0, ReturnTypeColor());
		EditorGUI_HelpBox("Rejuvenate at the project target.");
	}
}
public class ReserveRejuvenator : TaskBase
{
	public override TaskType Type => TaskType.ReserveRejuvenator;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		if ((bool)project.Target && project.Target.TryGetComponent<Rejuvenator>(out var component))
