public class ProduceItems : TaskBase
{
	private Producer _producer;

	public override TaskType Type => TaskType.ProduceItem;

	public override IEnumerator RunTaskCoroutine(Agent agent, Project project)
	{
		int itterations = 0;
		_producer = project.Target.GetComponent<Producer>();
		_producer.IsProducingItems = true;
		QueuedRecipe queuedRecipe;
		while (_producer.TryReturnRestoredProducingRecipe(out queuedRecipe) || (agent.Community.ProjectRemainsPriority(project, agent) && _producer.TryReturnNextRecipeToProduce(out queuedRecipe)))
		{
			itterations++;
			if (agent.CurrentActivity != queuedRecipe.Activity)
			{
				_producer.AttachWorker(agent);
				agent.UpdateActivity(queuedRecipe.Activity);
			}
			float modifier = agent.Attributes.ReturnAttributeModifier(queuedRecipe.Attribute);
			agent.DrifterRig.MeshAnimator.Animator.SetFloat("Transition Time", queuedRecipe.ProductionTime / modifier);
			_producer.StartProducing(queuedRecipe, modifier);
			new AgentActionEvent(GameEventType.AgentActionStartedWorking, agent, queuedRecipe.Attribute).Dispatch();
			bool flag = _producer.ReturnCanRun();
			while (queuedRecipe.RecipeStage == QueuedRecipe.Stage.Producing && flag && _producer.QueuedRecipes.Contains(queuedRecipe))
			{
				ProductionRecipeProperties properties = queuedRecipe.Recipe.Properties;
				DrifterAttributes.AttributeType attribute = queuedRecipe.Attribute;
				_producer.Produce(queuedRecipe, modifier);
				_producer.AdvanceQueuedRecipeStage(queuedRecipe, !queuedRecipe.RequiresPerson);
				if (!_producer.QueuedRecipes.Contains(queuedRecipe))
				{
					new AgentActionRecipeEvent(GameEventType.AgentActionRecipeProduced, agent, properties, attribute).Dispatch();
				}
				yield return null;
				flag = _producer.ReturnCanRun();
			}
			_producer.StopProducing();
			new AgentActionEvent(GameEventType.AgentActionStoppedWorking, agent, queuedRecipe.Attribute).Dispatch();
			if (agent.Vitals.ReturnHasProject() || !flag)
			{
				break;
			}
		}
		if (itterations == 0)
		{
			UnityEngine.Debug.LogException(new Exception("[BUG] ProduceItems task was started, but production loop was never entered!"));
		}
		_producer.DetachWorker(agent, GameManager.AgentManager.AgentParent);
		if (!agent.ReturnNavigator().AttachToTarget(project.Target.GetComponent<Construction>().Target))
		{
			agent.ReturnNavigator().AttachToTarget(agent.ReturnClosestWalkwayConstruction().Target);
		}
		_producer.IsProducingItems = false;
	}

	public override void Stop()
	{
		base.Stop();
		if (_producer != null && _agent != null)
		{
			_producer.IsProducingItems = false;
			_producer.StopProducing();
			_producer.DetachWorker(_agent, GameManager.AgentManager.AgentParent);
			_agent.transform.SetParent(GameManager.AgentManager.AgentParent);
			_agent.ReturnNavigator().AttachToTarget(_agent.ReturnClosestConstruction(onlyFinished: true).Target, overrideCheck: true);
		}
	}

	public override ProjectBlocker ReturnBlockers(Project project)
	{
		ProjectBlocker result = ProjectBlocker.None;
		if (!TryReturnTargetBuildableExtendable<Producer>(project, out var buildableExtendable))
		{
			return ProjectBlocker.BuildingNotAvailable;
		}
		if (!buildableExtendable.ReturnCanRun())
		{
			return ProjectBlocker.EnergyGridFull;
		}
		if (buildableExtendable.IsBlockedByImport || buildableExtendable.QueuedRecipes.IsNullOrEmpty() || !buildableExtendable.TryReturnNextRecipeToProduce(out var _))
		{
			return ProjectBlocker.UnableToProduce;
		}
		return result;
	}

	public override bool ReturnCanFinish(Project project)
	{
		if (TryReturnTargetBuildableExtendable<Producer>(project, out var buildableExtendable))
		{
			return buildableExtendable.ReturnCanRun();
		}
		return true;
	}

	protected override void OnGUI()
	{
		Header("Produce Items", 0, ReturnTypeColor());
		EditorGUI_HelpBox("Produces the recipes that are wait to be produced by the project target.");
	}
}
public enum VitalProjectPriority
{
	Normal = 0x10,
	High = 0x20
}
public class CommunityResearch
{
	public class Research
	{
		[Serializable]
		public class PersistentData
		{
			[OptionalField(VersionAdded = 2)]
			public string Guid;

			public int Progress;

			public int BuildablePropertiesIndex;

			public PersistentData(Research research)
			{
				Guid = research.TechTreeNode.Guid;
				Progress = research.Progress;
			}

			public bool TryRestore(out Research research)
			{
				if (GameManager.Settings.TechTree.FindTechTreeNodeByGuid(Guid, out var node))
				{
					research = new Research(node, Progress);
					return true;
				}
				UnityEngine.Debug.LogErrorFormat("Unable to restore research entry with GUID: {0}", Guid);
				research = null;
				return false;
			}
		}

		public TechTreeNode TechTreeNode;

		public int Cost;

		public int Progress;

		public string Guid => TechTreeNode.Guid;

		public string Name => TechTreeNode.Name;

		public int RemainingCost => Cost - Progress;

		public Research(TechTreeNode node, int progress)
		{
			TechTreeNode = node;
			Cost = node.GetRequirementAmount<KnowledgeRequirement>();
			Progress = progress;
		}

		public Research(TechTreeNode node)
			: this(node, 0)
		{
		}

		public static bool TryInstantiateFromGuid(string guid, out Research research)
		{
			if ((bool)GameManager.Settings && GameManager.Settings.TechTree.FindTechTreeNodeByGuid(guid, out var node))
			{
				research = new Research(node);
				return true;
			}
			research = null;
			return false;
		}
	}

	public int ResearchPoints;

	private Community _community;

	private GameplaySettings _settings;

	public HashSet<BuildableProperties> ResearchedBuildableProperties { get; private set; } = new HashSet<BuildableProperties>();

	public List<ResearchStation> ResearchStations { get; private set; } = new List<ResearchStation>();

	public Research CurrentResearch { get; private set; }

	public List<Research> ResearchProgresses { get; private set; }

	public Project ResearchProject { get; private set; }

	public bool HasPoints => ResearchPoints > 0;

	public int CurrentProgress
	{
		get
		{
			if (CurrentResearch != null)
			{
				return CurrentResearch.Progress;
			}
			return 0;
		}
	}

	public int CurrentCost
	{
		get
		{
			if (CurrentResearch != null)
			{
				return CurrentResearch.Cost;
			}
			return 0;
		}
	}

	public ItemProperties StudyItem => _settings.StudyItem;

	public float StudyTime { get; private set; }

	public CommunityResearch(Community community)
	{
		_community = community;
		_settings = GameSettings.Instance.GameplaySettings;
		ResearchProgresses = new List<Research>();
	}

	public void SetResearchProject(Project project)
	{
		if (project != null)
		{
			ResearchProject = project;
			project.FinishedEvent.AddListener(OnResearchProjectFinish);
		}
	}

	private void OnResearchProjectFinish(Project project, bool success)
	{
		project.FinishedEvent.RemoveListener(OnResearchProjectFinish);
		ResearchProject = null;
	}

	public void AddResearchPoints(int amount = 1)
	{
		ResearchPoints += amount;
		new GameEvent(GameEventType.ResearchPointsUpdated).Dispatch();
	}

	public bool RemoveResearchPoints(int amount = 1)
	{
		if (ResearchPoints < amount)
		{
			return false;
		}
		ResearchPoints -= amount;
		new GameEvent(GameEventType.ResearchPointsUpdated).Dispatch();
		return true;
	}

	public bool ResearchPoint()
	{
		if (CurrentResearch == null)
		{
			return true;
		}
		if (RemoveResearchPoints())
		{
			CurrentResearch.Progress++;
			new ResearchEvent(GameEventType.ResearchProgressPointsUpdated, CurrentResearch).Dispatch();
			if (CurrentResearch.Progress >= CurrentResearch.Cost)
			{
				FinishResearch();
				return true;
			}
		}
		return false;
	}

	public bool IsResearching()
	{
		return CurrentResearch != null;
	}

	public bool IsCurrentResearch(TechTreeNode node)
	{
		if (CurrentResearch != null)
		{
			return CurrentResearch.TechTreeNode == node;
		}
		return false;
	}

	public bool TryResearchGetProgress(TechTreeNode node, out int progress)
	{
		if (CurrentResearch != null && CurrentResearch.TechTreeNode == node)
		{
			progress = CurrentResearch.Progress;
			return true;
		}
		foreach (Research researchProgress in ResearchProgresses)
		{
			progress = researchProgress.Progress;
			if (researchProgress.TechTreeNode == node && 0 < progress && progress < node.Cost)
			{
				return true;
			}
		}
		progress = 0;
		return false;
	}

	public void AddResearchStation(ResearchStation station)
	{
		if (!ResearchStations.AddUnique(station))
		{
			PajamaLlama.Debugs.Debugger.Error("Could not add a research station since it already exists.", station);
		}
	}

	public void RemoveResearchStation(ResearchStation station)
	{
		if (!ResearchStations.RemoveSafely(station))
		{
			PajamaLlama.Debugs.Debugger.Error("Could not delete a research station since it didn't exist", station);
		}
	}

	public int GetActiveResearchStationCount()
	{
		int num = 0;
		if (ResearchStations.IsNullOrEmpty())
		{
			return num;
		}
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (researchStation.IsResearching)
			{
				num++;
			}
		}
		return num;
	}

	public void StartResearch(TechTreeNode node, Project project = null)
	{
		if (!TryReturnResearch(node, out var research))
		{
			research = new Research(node);
			ResearchProgresses.Add(research);
		}
		if (CurrentResearch == research)
		{
			return;
		}
		if (CurrentResearch != null)
		{
			CancelResearch();
		}
		CurrentResearch = research;
		if (project == null)
		{
			project = new Project(GameManager.Settings.ProjectSettings.ResearchProject, Construction.Townheart.gameObject);
			if (!_community.QueueProject(project))
			{
				UnityEngine.Debug.LogError("Unable to queue research project in community.");
			}
		}
		ResearchProject = project;
		ResearchProject.FinishedEvent.AddListener(OnResearchProjectFinish);
		new ResearchEvent(GameEventType.ResearchStarted, CurrentResearch).Dispatch();
	}

	public void FinishResearch()
	{
		if (CurrentResearch != null)
		{
			Research currentResearch = CurrentResearch;
			CurrentResearch = null;
			ResearchProgresses.Remove(currentResearch);
			currentResearch.TechTreeNode.Unlock();
			GameManager.UIManager.NotificationHandler.AddNotification(GameManager.Settings.UISettings.ResearchFinishedNotification, new ResearchObjectOfInterest(currentResearch));
			new ResearchEvent(GameEventType.ResearchFinished, currentResearch).Dispatch();
		}
	}

	public void CancelResearch()
	{
		Research currentResearch = CurrentResearch;
		if (ResearchProject == null)
		{
			UnityEngine.Debug.LogWarning("Research was canceled, but ResearchProject is NULL.");
		}
		else
		{
			ResearchProject?.Stop(ProjectFlags.Cancelled);
			ResearchProject = null;
		}
		CurrentResearch = null;
		if (currentResearch != null)
		{
			new ResearchEvent(GameEventType.ResearchCancelled, currentResearch).Dispatch();
		}
	}

	public void UnlockBuildable(BuildableProperties properties)
	{
		ResearchedBuildableProperties.Add(properties);
		properties.Unlock();
	}

	public bool RequiresMoreResearchStations(ResearchStation ignoredStation)
	{
		if (CurrentResearch == null)
		{
			return false;
		}
		int cost = CurrentResearch.Cost;
		int num = ReturnGeneratingPoints(ignoredStation);
		return cost > num;
	}

	public bool HasPointToResearch(ResearchStation ignoredStation)
	{
		if (CurrentResearch == null)
		{
			return false;
		}
		int num = ReturnGeneratingPoints(ignoredStation);
		int num2 = ResearchPoints - num;
		if (num < CurrentResearch.RemainingCost)
		{
			return 0 < num2;
		}
		return false;
	}

	private int ReturnGeneratingPoints(ResearchStation ignoredStation)
	{
		int num = 0;
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (!(ignoredStation == researchStation) && researchStation.ReservingAgent != null)
			{
				num++;
			}
		}
		return num;
	}

	public bool HasBuiltResearchStation()
	{
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (researchStation.Buildable.BuildPhase == BuildPhase.Finished)
			{
				return true;
			}
		}
		return false;
	}

	public bool HasAvailableResearchStation()
	{
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (researchStation.ReturnCanRun() && !(researchStation.ReservingAgent != null))
			{
				return true;
			}
		}
		return false;
	}

	public ResearchStation ReturnClosestAvailableResearchStation(Agent agent)
	{
		float num = float.MaxValue;
		ResearchStation result = null;
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (!researchStation.ReturnCanRun())
			{
				continue;
			}
			if (researchStation.ReservingAgent == agent)
			{
				return researchStation;
			}
			if (!(researchStation.ReservingAgent != null))
			{
				float num2 = Vector3.Distance(agent.transform.position, researchStation.transform.position);
				if (num2 < num)
				{
					num = num2;
					result = researchStation;
				}
			}
		}
		return result;
	}

	public ResearchStation ReturnReservedResearchStation(Agent agent)
	{
		foreach (ResearchStation researchStation in ResearchStations)
		{
			if (researchStation.ReservingAgent == agent)
			{
				return researchStation;
			}
		}
		return null;
	}

	public bool IsResearched(ResearchUnlockable properties)
	{
		if ((bool)properties)
		{
			if (!UnlockableManager.IsUnlocked(properties))
			{
				if (properties is BuildableProperties item)
				{
					return ResearchedBuildableProperties.Contains(item);
				}
				return false;
			}
			return true;
		}
		return false;
	}

	public bool TryReturnResearch(TechTreeNode node, out Research research)
	{
		research = null;
		foreach (Research researchProgress in ResearchProgresses)
		{
			if (researchProgress.TechTreeNode == node)
			{
				research = researchProgress;
				return true;
			}
		}
		return false;
	}

	public bool HasStudyTime()
	{
		if (!(StudyTime > 0f))
		{
			return _community.Inventory.ReturnCount(_settings.StudyItem) > 0;
		}
		return true;
	}

	public float RemainingStudyTimeNormalized()
	{
		return StudyTime / _settings.StudyTimePerItem;
	}

	public float GetStudyExperiencePerSecond()
	{
		return _settings.StudyExperiencePerItem / _settings.StudyTimePerItem;
	}

	public void RestoreStudyTime(float studyTime)
	{
		StudyTime = studyTime;
	}

	public float AllocateStudyTime(float deltaTime, Storage storage)
	{
		if (deltaTime <= StudyTime)
		{
			StudyTime -= deltaTime;
			return deltaTime;
		}
		GameplaySettings gameplaySettings = GameSettings.Instance.GameplaySettings;
		ItemProperties studyItem = gameplaySettings.StudyItem;
		if ((storage.TryReserveItem(studyItem, out var item) || _community.Inventory.TryReserveItem(studyItem, out item)) && item.TryTakeFromInventory(out var _))
		{
			StudyTime += gameplaySettings.StudyTimePerItem;
		}
		if (StudyTime < deltaTime)
		{
			deltaTime = StudyTime;
		}
		StudyTime -= deltaTime;
		return deltaTime;
	}
}
[Serializable]
public class CommunityResearchPersistentdata
{
	public int[] ResearchedBuildableIndices;

	[OptionalField(VersionAdded = 2)]
	public int ResearchPoints;

	[OptionalField(VersionAdded = 2)]
	public CommunityResearch.Research.PersistentData[] ResearchProgresses;

	[OptionalField(VersionAdded = 3)]
	public string CurrentResearchGuid;

	public PersistentReference<Project>.Reference ResearchProject;

	[OptionalField(VersionAdded = 4)]
	public float StudyTime;

	public int CurrentResearch;

	public float Progress;

	public CommunityResearchPersistentdata(CommunityResearch research)
	{
		ResearchedBuildableIndices = new int[research.ResearchedBuildableProperties.Count];
		int num = 0;
		foreach (BuildableProperties researchedBuildableProperty in research.ResearchedBuildableProperties)
		{
			ResearchedBuildableIndices[num] = GameManager.PersistenceManager.ReturnPropertiesIndex(researchedBuildableProperty);
			num++;
		}
		CurrentResearchGuid = ((research.CurrentResearch == null) ? null : research.CurrentResearch.Guid);
		ResearchPoints = research.ResearchPoints;
		int count = research.ResearchProgresses.Count;
		ResearchProgresses = new CommunityResearch.Research.PersistentData[count];
		for (int i = 0; i < count; i++)
		{
			ResearchProgresses[i] = new CommunityResearch.Research.PersistentData(research.ResearchProgresses[i]);
		}
		ResearchProject = research.ResearchProject;
		StudyTime = research.StudyTime;
	}

	public void Restore(Community community)
	{
		for (int i = 0; i < ResearchedBuildableIndices.Length; i++)
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<BuildableProperties>(ResearchedBuildableIndices[i], out var reference))
			{
				community.Research.UnlockBuildable(reference);
			}
		}
		community.Research.AddResearchPoints(ResearchPoints);
		community.Research.RestoreStudyTime(StudyTime);
		RestoreProgress(community);
	}

	private void RestoreProgress(Community community)
	{
		if (ResearchProgresses == null)
		{
			return;
		}
		CommunityResearch.Research.PersistentData[] researchProgresses = ResearchProgresses;
		for (int i = 0; i < researchProgresses.Length; i++)
		{
			if (researchProgresses[i].TryRestore(out var research))
			{
				community.Research.ResearchProgresses.Add(research);
			}
			else
			{
				UnityEngine.Debug.LogWarning("[TODO] Handle lost progress points because of reserach that could not be restored!");
			}
		}
	}

	public void RestoreReferences(Community community)
	{
		if (!ResearchProject.TryReturn(out var instance))
		{
			instance = null;
		}
		if (GameManager.Settings.TechTree.FindTechTreeNodeByGuid(CurrentResearchGuid, out var node))
		{
			community.Research.StartResearch(node, instance);
		}
	}
}
public class ResearchObjectOfInterest : INotificationObjectOfInterest
{
	public GameObject GameObjectOfInterest { get; private set; }

	public ObjectType ObjectOfInterestType => ObjectType.Research;

	public CommunityResearch.Research Research { get; private set; }

	public ResearchObjectOfInterest(CommunityResearch.Research research)
	{
		Research = research;
		GameObjectOfInterest = Construction.Townheart.gameObject;
	}

	public void NotificationLeftClick()
	{
		GameManager.UIManager.SelectResearch(Research);
	}

	public string NotificationReplaceVariables(string str)
	{
		return Regex.Replace(str, "%RESEARCH%", $"<b>{Research.Name}</b>", RegexOptions.IgnoreCase);
	}

	public bool IsMatch(INotificationObjectOfInterest objectOfInterest)
	{
		if (objectOfInterest.ObjectOfInterestType == ObjectType.Research)
		{
			ResearchObjectOfInterest researchObjectOfInterest = objectOfInterest as ResearchObjectOfInterest;
			if (GameObjectOfInterest == objectOfInterest.GameObjectOfInterest)
			{
				return Research == researchObjectOfInterest.Research;
			}
			return false;
		}
		return false;
	}
}
