public enum ISpawnerState
{
	Interactable,
	NonInteractable,
	DoNotSpawn
}
public enum ISpawnerType
{
	Flotsam,
	PointOfInterest,
	Landmark,
	Road
}
public class LandmarkSpawner : ISpawner, IWorldMapCompassBearingTarget
{
	[Serializable]
	public struct PersistentReference
	{
		private int _tileIndex;

		private int _spawnerIndex;

		private Vector2 _tilePosition;

		public PersistentReference(int tileIndex, int spawnerIndex, Vector2 tilePosition)
		{
			_tileIndex = tileIndex;
			_spawnerIndex = spawnerIndex;
			_tilePosition = tilePosition;
		}

		public bool TryGet(out LandmarkSpawner landmarkSpawner)
		{
			return WorldManager.TryReturnLandmarkSpawner(out landmarkSpawner, _tileIndex, _spawnerIndex);
		}
	}

	private Vector3 _worldTileOffset = Vector3.zero;

	private Vector3 _spawnPosition;

	private Quaternion _spawnRotation;

	private Polygon _prefabPolygon;

	private Sprite _bearingIconOverride;

	public ISpawnerType Type => ISpawnerType.Landmark;

	public bool Enabled => LandmarkBehaviour;

	public Sprite Icon => LandmarkBehaviour._uiIcon;

	public WorldTile WorldTile => Region.WorldTile;

	public Vector2 WorldPosition2D { get; private set; }

	public Vector2 TilePosition { get; private set; }

	internal HandmadeTileGenerator.Landmark LandmarkData { get; private set; }

	public LandmarkBehaviour LandmarkBehaviour { get; private set; }

	public LandmarkPersistentData PersistentData { get; private set; }

	public Vector3 WorldPosition { get; private set; }

	public Vector3 SpawnPosition => _spawnPosition;

	public Quaternion Rotation { get; private set; }

	public IWorldRegion Region { get; private set; }

	public WorldRegionType RegionType { get; private set; }

	public ScoutingState ScoutingState { get; private set; }

	public WorldMapScoutingId ScoutingId
	{
		get
		{
			if (!(LandmarkBehaviour == null))
			{
				return LandmarkBehaviour.ScoutingId;
			}
			return WorldMapScoutingId.None;
		}
	}

	public string Name => LandmarkBehaviour.Name;

	public Polygon TileSpacePolygon { get; private set; }

	public Sprite BearingIcon => GetBearingIcon();

	public BearingFeatures BearingFeatures { get; private set; }

	public BearingIconType BearingIconOverride { get; private set; }

	public ISpawnerEvent UpdatedEvent { get; private set; } = new ISpawnerEvent();

	public LandmarkSpawner(LandmarkBehaviour landmarkBehaviour, Vector3 tilePosition, bool hasBearing = false)
		: this(landmarkBehaviour, tilePosition, Quaternion.AngleAxis((float)UnityEngine.Random.Range(0, 360), Vector3.up))
	{
		if (hasBearing)
		{
			SetScoutingState(ScoutingState.Scouted);
		}
	}

	public LandmarkSpawner(LandmarkBehaviour landmarkBehaviour, Vector3 tilePosition, Quaternion rotation)
		: this(tilePosition, rotation)
	{
		if ((bool)landmarkBehaviour && (WorldManager.GameMode != GameMode.Narrative || !landmarkBehaviour.ReturnHasLandmarkActionReference<LandmarkActionRescue>()))
		{
			SetLandmarkBehaviour(landmarkBehaviour, null);
		}
	}

	public LandmarkSpawner(LandmarkBehaviour landmarkBehaviour, Vector3 tilePosition, Quaternion rotation, LandmarkPersistentData persistentData)
		: this(tilePosition, rotation)
	{
		if ((bool)landmarkBehaviour)
		{
			SetLandmarkBehaviour(landmarkBehaviour, persistentData);
		}
	}

	internal LandmarkSpawner(HandmadeTileGenerator.Landmark landmarkData, Vector3 tilePosition, Quaternion rotation)
		: this(tilePosition, rotation)
	{
		LandmarkData = landmarkData;
	}

	private LandmarkSpawner(Vector3 tilePosition, Quaternion rotation)
	{
		WorldPosition = (_spawnPosition = tilePosition);
		TilePosition = (WorldPosition2D = tilePosition.Vector2TopDown());
		Rotation = (_spawnRotation = rotation);
	}

	public void Initialize()
	{
		throw new NotImplementedException();
	}

	public void SetLandmarkBehaviour(LandmarkBehaviour landmarkBehaviour, LandmarkPersistentData persistentData)
	{
		LandmarkBehaviour = landmarkBehaviour.ReturnInstance();
		if ((bool)GameManager.WorldManager)
		{
			LandmarkBehaviour.Initialize();
			if (persistentData != null)
			{
				LandmarkBehaviour.Restore(persistentData);
			}
		}
		if (TryReturnPrefabPolygon(out var prefabPolygon))
		{
			TileSpacePolygon = new Polygon(prefabPolygon, TilePosition.Vector3TopDown(), Rotation);
		}
		PersistentData = persistentData;
	}

	public bool SetActorDescriptor(ActorDescriptor descriptor, QuestProperties questToAssign, ILandmarkBehaviourProvider landmarkBehaviourProvider)
	{
		if (landmarkBehaviourProvider != null)
		{
			SetLandmarkBehaviour(landmarkBehaviourProvider.ReturnLandmarkBehaviour(Region.Type), null);
		}
		if (LandmarkBehaviour is ActionsBehaviour actionsBehaviour && actionsBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false))
		{
			action.AddDescriptor(descriptor);
			if ((bool)questToAssign)
			{
				action.AssignDrifterQuest(questToAssign);
			}
			return true;
		}
		return false;
	}

	public void SetWorldTileOffset(Vector3 offset)
	{
		_worldTileOffset = offset;
		WorldPosition += offset;
		_spawnPosition = WorldPosition;
		WorldPosition2D = WorldPosition.Vector2TopDown();
	}

	public void SetRegion(IWorldRegion region)
	{
		Region = region;
		RegionType = region.Type;
	}

	public void ApplyScoutingState()
	{
		ScoutingState scoutingState = ScoutingState;
		ScoutingState = ScoutingState.None;
		SetScoutingState(scoutingState);
	}

	public void SetScoutingState(ScoutingState scoutingState)
	{
		SetScoutingState(scoutingState, setBearingActive: false);
	}

	public void SetScoutingState(ScoutingState scoutingState, bool setBearingActive)
	{
		if (ScoutingState < scoutingState)
		{
			ScoutingState = scoutingState;
			UpdatedEvent.Invoke(this);
		}
		else if (scoutingState < ScoutingState)
		{
			UnityEngine.Debug.LogWarningFormat("Trying to lower scouting state for for landmark '{0}'! This is not supported!", LandmarkBehaviour ? LandmarkBehaviour.name : "NULL");
		}
		if (setBearingActive)
		{
			SetBearingActive(active: true);
		}
	}

	public void SetBearingActive(bool active)
	{
		if (active)
		{
			if (!(LandmarkBehaviour is ActionsBehaviour actionsBehaviour))
			{
				return;
			}
			LandmarkActionSalvage action2;
			if (ScoutingId.IsFlagSet(WorldMapScoutingId.Drifter) || ScoutingId.IsFlagSet(WorldMapScoutingId.Seagull))
			{
				if (actionsBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false) && !action.IsCompleted)
				{
					SetBearingFeatures(BearingFeatures.Compass | BearingFeatures.Marker);
				}
			}
			else if (ScoutingId.IsFlagSet(WorldMapScoutingId.Cache) && actionsBehaviour.TryReturnAction<LandmarkActionSalvage>(out action2, includeCompleted: false) && !action2.ReturnHasCompletedCategory())
			{
				SetBearingFeatures(BearingFeatures.Compass | BearingFeatures.Marker);
			}
		}
		else
		{
			SetBearingFeatures(BearingFeatures.None);
		}
	}

	public void ClearFogOfWar()
	{
		WorldManager.ClearFogOfWar(this);
	}

	public void Dispose()
	{
		SetBearingFeatures(BearingFeatures.None);
		Despawn(destroyInstance: false);
		Region?.RemoveLandmarkSpawner(this);
		LandmarkNotificationEvent.Disposed(this);
	}

	public bool Despawn(bool destroyInstance)
	{
		if (LandmarkPersistentData.TryReturnLandmarkPersistentData(out var data, LandmarkBehaviour))
		{
			PersistentData = data;
		}
		if ((bool)LandmarkBehaviour)
		{
			LandmarkBehaviour.DestroyLandmark();
		}
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
		return true;
	}

	public void Spawn(Transform parent)
	{
		if (!Enabled || (bool)LandmarkBehaviour.Landmark || !GameManager.WorldManager.IsInSpawnRadius(_spawnPosition))
		{
			return;
		}
		if (PersistentData == null)
		{
			LandmarkBehaviour.SpawnLandmark(_spawnPosition, _spawnRotation, parent);
		}
		else
		{
			PersistentData.RestoreLandmark(LandmarkBehaviour, _spawnPosition, _spawnRotation, parent);
			if (PersistenceLifeCycle.State == PersistenceState.None)
			{
				PersistentData.RestoreReferences();
			}
		}
		LandmarkBehaviour.OnLandmarkSpawnedOrRestored();
		GameEventDispatcher.AddListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
	}

	public void Move(Vector3 movement)
	{
		_spawnPosition += movement;
		ApplyPositionAndRotation();
	}

	public void RepositionRelativeToTownheart(Vector3 townheartPosition, Quaternion townheartRotation)
	{
		_spawnPosition = WorldPosition - townheartPosition;
		_spawnPosition = Quaternion.Inverse(townheartRotation) * _spawnPosition;
		_spawnRotation = Rotation * Quaternion.Inverse(townheartRotation);
		ApplyPositionAndRotation();
	}

	private void ApplyPositionAndRotation()
	{
		if (!(LandmarkBehaviour == null))
		{
			if (GameManager.WorldManager.IsInSpawnRadius(_spawnPosition))
			{
				LandmarkBehaviour.SetPositionAndRotation(_spawnPosition, _spawnRotation);
			}
			else if ((bool)LandmarkBehaviour.Landmark)
			{
				Despawn(destroyInstance: false);
			}
		}
	}

	public void CountItems(InventoryAuditor auditor)
	{
		if ((bool)LandmarkBehaviour)
		{
			LandmarkBehaviour.CountItems(auditor);
		}
	}

	public void PopulateWorldSpaceOutlineVertices(List<Vector2> vertices)
	{
		if (!TryReturnPrefabPolygon(out var prefabPolygon))
		{
			UnityEngine.Debug.LogError("Unable to populate world space outline vertices");
		}
		else
		{
			prefabPolygon.PopulateTransformedVertices(vertices, WorldPosition2D.Vector3TopDown(), Rotation);
		}
	}

	public void SetBearingFeatures(BearingFeatures bearingFeatures, BearingIconType _iconOverride = BearingIconType.None)
	{
		if (BearingFeatures == BearingFeatures.Disabled)
		{
			if (bearingFeatures != BearingFeatures.Disabled)
			{
				UnityEngine.Debug.LogException(new NotSupportedException($"Trying to set BearingFeatures '{bearingFeatures}' on landmark '{LandmarkBehaviour}' for which bearings are Disabled."));
			}
		}
		else
		{
			BearingFeatures = bearingFeatures;
			BearingIconOverride = _iconOverride;
			_bearingIconOverride = GameManager.Settings.LandmarkSettings.ReturnBearingIcon(BearingIconOverride);
			MapEvent.DispatchCompassBearingTargetEvent(this);
		}
	}

	private void OnLandmarkSelected(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && landmarkNotificationEvent.LandmarkBehaviour == LandmarkBehaviour)
		{
			SetBearingFeatures(BearingFeatures.Disabled);
		}
	}

	public bool IsInSpawnRadius()
	{
		return GameManager.WorldManager.IsInSpawnRadius(_spawnPosition);
	}

	public bool IsBearingActive()
	{
		return BearingFeatures != BearingFeatures.None;
	}

	public bool IsBearingTo(WorldMapScoutingId scoutingId)
	{
		if (IsBearingActive())
		{
			return (LandmarkBehaviour.ScoutingId & scoutingId) != 0;
		}
		return false;
	}

	public bool IsBearingTo(ISpawner spawner)
	{
		return spawner == this;
	}

	private Sprite GetBearingIcon()
	{
		if ((bool)_bearingIconOverride)
		{
			return _bearingIconOverride;
		}
		if (LandmarkBehaviour != null)
		{
			return LandmarkBehaviour.ReturnBearingIcon();
		}
		return null;
	}

	public bool MatchesScoutingFilter(WorldMapScoutingId filter)
	{
		if ((bool)LandmarkBehaviour)
		{
			return LandmarkBehaviour.ReturnMatchesScoutingFilter(filter);
		}
		return false;
	}

	private bool TryReturnPrefabPolygon(out Polygon prefabPolygon)
	{
		prefabPolygon = _prefabPolygon;
		if (prefabPolygon != null)
		{
			return true;
		}
		if (LandmarkBehaviour == null)
		{
			return false;
		}
		IPolygonProvider componentInChildren = LandmarkBehaviour.LandmarkPrefabGameObject.GetComponentInChildren<IPolygonProvider>();
		if (componentInChildren == null)
		{
			if (LandmarkBehaviour.LandmarkPrefabGameObject.TryGetComponent<Obstacle>(out var component))
			{
				_prefabPolygon = component.Polygon;
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception("Unable to return Landmark prefab Polygon."));
			}
		}
		else
		{
			_prefabPolygon = componentInChildren.Polygon;
		}
		prefabPolygon = _prefabPolygon;
		return prefabPolygon != null;
	}

	public PersistentReference GetPersistentReference()
	{
		return new PersistentReference(Region.WorldTile.Index, Region.WorldTile.ReturnLandmarkIndex(LandmarkBehaviour), TilePosition);
	}
}
public class PointOfInterestSpawner : ISpawner, ISpawnPositionProvider
{
	[Serializable]
	public class PersistentData
	{
		private readonly int _propertiesIndex;

		private readonly Vector3 _worldPosition;

		private readonly FlotsamSpawner.PersistentData[] _flotsamSpawners;

		private readonly FlotsamSpawner.PersistentData[] _compositedFlotsamSpawner;

		[OptionalField(VersionAdded = 2)]
		private readonly CountedItemPersistentData[] _flotsamItems;

		[OptionalField(VersionAdded = 2)]
		private readonly CountedItemPersistentData[] _compositedItems;

		[OptionalField(VersionAdded = 3)]
		private readonly ScoutingState _scoutingState;

		public PersistentData(PointOfInterestSpawner spawner)
		{
			_propertiesIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(spawner.Properties);
			_worldPosition = spawner.TilePosition.Vector3TopDown();
			_scoutingState = spawner.ScoutingState;
			if (spawner.State == ISpawnerState.Interactable)
			{
				_flotsamSpawners = ReturnFlotsamSpawnerPersistentData(spawner._flotsamSpawners);
				_compositedFlotsamSpawner = ReturnFlotsamSpawnerPersistentData(spawner._compositedFlotsamSpawners);
			}
			else
			{
				_flotsamItems = ReturnCountedItems(spawner._flotsamSpawners);
				_compositedItems = ReturnCountedItems(spawner._compositedFlotsamSpawners);
			}
		}

		public bool TryRestore(out PointOfInterestSpawner spawner)
		{
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<PointOfInterestProperties>(_propertiesIndex, out var reference))
			{
				spawner = new PointOfInterestSpawner(reference, _worldPosition)
				{
					ScoutingState = _scoutingState
				};
				if (_flotsamItems == null)
				{
					spawner._flotsamSpawners = ReturnFlotsamSpawnerGroup(_flotsamSpawners, spawner);
					spawner._compositedFlotsamSpawners = ReturnFlotsamSpawnerGroup(_compositedFlotsamSpawner, spawner);
				}
				else
				{
					spawner._flotsamSpawners = ReturnFlotsamSpawnerGroup(_flotsamItems, spawner);
					spawner._compositedFlotsamSpawners = CompositeFlotsamSpawnerFactory.RestoreCompositeFlotsamSpawnerGroup(_compositedItems, spawner);
				}
				spawner._initialized = true;
				return true;
			}
			spawner = null;
			return false;
		}

		private FlotsamSpawner.PersistentData[] ReturnFlotsamSpawnerPersistentData(FlotsamSpawnerGroup flotsamSpawnerGroup)
		{
			List<FlotsamSpawner> spawners = flotsamSpawnerGroup.Spawners;
			if (spawners == null)
			{
				return null;
			}
			int count = spawners.Count;
			FlotsamSpawner.PersistentData[] array = new FlotsamSpawner.PersistentData[count];
			for (int i = 0; i < count; i++)
			{
				array[i] = new FlotsamSpawner.PersistentData(spawners[i]);
			}
			return array;
		}

		private CountedItemPersistentData[] ReturnCountedItems(FlotsamSpawnerGroup flotsamSpawnerGroup)
		{
			InventoryAuditor global = InventoryAuditor.Global;
			global.Reset();
			flotsamSpawnerGroup.CountItems(global);
			return CountedItemPersistentData.GenerateFromInventoryAuditor(global);
		}

		private FlotsamSpawnerGroup ReturnFlotsamSpawnerGroup(FlotsamSpawner.PersistentData[] persistentData, PointOfInterestSpawner spawner)
		{
			if (persistentData == null)
			{
				return null;
			}
			FlotsamSpawnerGroup flotsamSpawnerGroup = new FlotsamSpawnerGroup(persistentData.Length);
			for (int i = 0; i < persistentData.Length; i++)
			{
				if (persistentData[i].TryRestore(spawner, out var spawner2))
				{
					flotsamSpawnerGroup.AddSpawner(spawner2);
				}
			}
			flotsamSpawnerGroup.SpawnerOutOfRangeEvent.AddListener(spawner.OnSpawnerOutOfRange);
			flotsamSpawnerGroup.OnSalvaged.AddListener(spawner.OnSpawnerOutOfRange);
			return flotsamSpawnerGroup;
		}

		private FlotsamSpawnerGroup ReturnFlotsamSpawnerGroup(CountedItemPersistentData[] countedItems, PointOfInterestSpawner spawner)
		{
			if (countedItems == null)
			{
				return null;
			}
			FlotsamSpawnerGroup flotsamSpawnerGroup = new FlotsamSpawnerGroup(countedItems.Length);
			for (int i = 0; i < countedItems.Length; i++)
			{
				CountedItemPersistentData countedItemPersistentData = countedItems[i];
				if (countedItemPersistentData.TryRestoreItemProperties(out var itemProperties))
				{
					for (int j = 0; j < countedItemPersistentData.Count; j++)
					{
						flotsamSpawnerGroup.AddSpawner(FlotsamSpawner.CreateFromItemProperties(itemProperties, spawner));
					}
				}
			}
			flotsamSpawnerGroup.SpawnerOutOfRangeEvent.AddListener(spawner.OnSpawnerOutOfRange);
			flotsamSpawnerGroup.OnSalvaged.AddListener(spawner.OnSpawnerOutOfRange);
			return flotsamSpawnerGroup;
		}
	}

	private readonly List<FlotsamProperties> _allFlotsamProps = new List<FlotsamProperties>();

	private FlotsamSpawnerGroup _flotsamSpawners;

	private FlotsamSpawnerGroup _compositedFlotsamSpawners;

	private Vector3 _worldPosition;

	private Vector3 _spawnPosition;

	private bool _initialized;

	private static List<Transform> _rootTransforms;

	public WorldTile Tile { get; private set; }

	public ISpawnerType Type => ISpawnerType.PointOfInterest;

	public ISpawnerState State { get; private set; }

	public ISpawnerEvent SpawnerOutOfRangeEvent { get; } = new ISpawnerEvent();

	public ISpawnerEvent OnSalvaged { get; } = new ISpawnerEvent();

	public Transform RootTransform { get; private set; }

	public PointOfInterestProperties Properties { get; }

	public Sprite Icon => Properties.DebugIcon;

	public Sprite BearingIcon => Properties.BearingIcon;

	public WorldTile WorldTile { get; set; }

	public Vector3 WorldPosition => _worldPosition;

	public Vector2 WorldPosition2D => _worldPosition.Vector2TopDown();

	public Vector2 TilePosition { get; }

	public Vector3 SpawnPosition => _spawnPosition;

	public bool HasPosition { get; private set; }

	public WorldRegionType RegionType => WorldRegionType.None;

	public ScoutingState ScoutingState { get; private set; }

	public string Name => Properties.Title.GetOrDefault(Properties.name);

	public ISpawnerEvent UpdatedEvent { get; } = new ISpawnerEvent();

	public PointOfInterestSpawner(PointOfInterestProperties properties)
	{
		Properties = properties;
		HasPosition = false;
	}

	public PointOfInterestSpawner(PointOfInterestProperties properties, Vector3 position)
		: this(properties)
	{
		TilePosition = position.Vector2TopDown();
		_worldPosition = position;
		_spawnPosition = position;
		HasPosition = true;
	}

	public void Initialize()
	{
		if (!_initialized)
		{
			_flotsamSpawners = new FlotsamSpawnerGroup(Properties.ReturnItems());
			_compositedFlotsamSpawners = new FlotsamSpawnerGroup(Properties.ReturnCompositedFlotsam());
		}
	}

	public void AddSpawnerListeners()
	{
		_flotsamSpawners.SpawnerOutOfRangeEvent.AddListener(OnSpawnerOutOfRange);
		_flotsamSpawners.OnSalvaged.AddListener(OnSpawnerSalvage);
		_compositedFlotsamSpawners.SpawnerOutOfRangeEvent.AddListener(OnSpawnerOutOfRange);
		_compositedFlotsamSpawners.OnSalvaged.AddListener(OnSpawnerSalvage);
	}

	public void SetWorldTileOffset(Vector3 offset)
	{
		if (HasPosition)
		{
			_worldPosition = TilePosition.Vector3TopDown(_worldPosition.y) + offset;
		}
		_compositedFlotsamSpawners.SetWorldTileOffset(offset);
		_flotsamSpawners.SetWorldTileOffset(offset);
	}

	public void Spawn(Transform parent)
	{
		if (!FlotsamSpawner.IsInToolMode)
		{
			State = ReturnState();
			_compositedFlotsamSpawners.Spawn(this);
			_flotsamSpawners.Spawn(this);
		}
	}

	public bool Despawn(bool destroyInstance)
	{
		_compositedFlotsamSpawners.Despawn(destroyInstance);
		_flotsamSpawners.Despawn(destroyInstance);
		ReleaseRootTransform();
		return true;
	}

	public void Move(Vector3 movement)
	{
		_spawnPosition += movement;
		if ((bool)RootTransform)
		{
			RootTransform.transform.position = _spawnPosition;
		}
		State = ReturnState();
		_compositedFlotsamSpawners.Move(movement);
		_flotsamSpawners.Move(movement);
	}

	public void RepositionRelativeToTownheart(Vector3 townheartPosition, Quaternion townheartRotation)
	{
		_spawnPosition = _worldPosition - townheartPosition;
		_spawnPosition = Quaternion.Inverse(townheartRotation) * _spawnPosition;
		if ((bool)RootTransform)
		{
			RootTransform.transform.position = _spawnPosition;
		}
		State = ReturnState();
		_compositedFlotsamSpawners.RepositionRelativeToTownheart(townheartPosition, townheartRotation);
		_flotsamSpawners.RepositionRelativeToTownheart(townheartPosition, townheartRotation);
	}

	public void CountItems(InventoryAuditor auditor)
	{
		if (_flotsamSpawners == null)
		{
			auditor.CountItemProperties(Properties.ReturnItems());
		}
		else
		{
			_flotsamSpawners.CountItems(auditor);
		}
		if (_compositedFlotsamSpawners == null)
		{
			foreach (CompositedFlotsamProperties item in Properties.ReturnCompositedFlotsam())
			{
				auditor.CountItemProperties(item.Composition);
			}
			return;
		}
		_compositedFlotsamSpawners.CountItems(auditor);
	}

	public void CountInteractableItemsInRange(InventoryAuditor auditor, float range)
	{
		if (State == ISpawnerState.Interactable && _spawnPosition.IsInRange(Vector3.zero, range))
		{
			CountItems(auditor);
		}
	}

	public void OnSpawnerOutOfRange(ISpawner spawner)
	{
		foreach (FlotsamSpawner spawner2 in _flotsamSpawners.Spawners)
		{
			if (!spawner2.IsOutOfRange)
			{
				return;
			}
		}
		foreach (FlotsamSpawner spawner3 in _compositedFlotsamSpawners.Spawners)
		{
			if (!spawner3.IsOutOfRange)
			{
				return;
			}
		}
		HasPosition = false;
		SpawnerOutOfRangeEvent.Invoke(this);
	}

	private void OnSpawnerSalvage(ISpawner spawner)
	{
		OnSalvaged.Invoke(spawner);
	}

	public void SetScoutingState(ScoutingState scoutingState)
	{
		if (ScoutingState < scoutingState)
		{
			ScoutingState = scoutingState;
			UpdatedEvent.Invoke(this);
		}
		else
		{
			UnityEngine.Debug.LogWarning("Trying to lower scouting state for for point of interest '" + Name + "'! This is not supported!");
		}
	}

	private ISpawnerState ReturnState()
	{
		if (GameManager.WorldManager.IsInSpawnRadius(_spawnPosition))
		{
			AquireRootTransform();
			if (!GameManager.WorldManager.IsInteractable(_spawnPosition))
			{
				return ISpawnerState.NonInteractable;
			}
			return ISpawnerState.Interactable;
		}
		ReleaseRootTransform();
		return ISpawnerState.DoNotSpawn;
	}

	public Vector3 ReturnInitialSpawnPosition(bool dummy = false)
	{
		return ReturnSpawnPosition();
	}

	public Vector3 ReturnSpawnPosition()
	{
		return TilePosition.Vector3TopDown() + ReturnLocalSpawnPosition();
	}

	public Vector3 ReturnLocalSpawnPosition()
	{
		return FlotsamGame.RandomPosition(Vector3.zero, Properties.Radius, Properties.UseGaussianDistribution, Properties.ClearRadius);
	}

	public int ReturnSpawnerCount()
	{
		return _compositedFlotsamSpawners.Spawners.Count + _flotsamSpawners.Spawners.Count;
	}

	public FlotsamSpawner ReturnClosestFlotsamSpawner(Vector3 position, ref float shortestDistanceSquared, FlotsamSpawner closestSpawner)
	{
		if (State != ISpawnerState.Interactable)
		{
			return closestSpawner;
		}
		if (_flotsamSpawners != null)
		{
			closestSpawner = _flotsamSpawners.ReturnClosestFlotsamSpawner(position, ref shortestDistanceSquared, closestSpawner);
		}
		if (_compositedFlotsamSpawners != null)
		{
			closestSpawner = _compositedFlotsamSpawners.ReturnClosestFlotsamSpawner(position, ref shortestDistanceSquared, closestSpawner);
		}
		return closestSpawner;
	}

	public IReadOnlyList<FlotsamProperties> GetAllFlotsamProperties()
	{
		_allFlotsamProps.Clear();
		_allFlotsamProps.AddRange(_flotsamSpawners.GetAllFlotsamProperties());
		_allFlotsamProps.AddRange(_compositedFlotsamSpawners.GetAllFlotsamProperties());
		return _allFlotsamProps;
	}

	private void AquireRootTransform()
	{
		if (!RootTransform)
		{
			if (TryGetTransformInstance(out var instance))
			{
				RootTransform = instance;
			}
			else
			{
				RootTransform = new GameObject(Properties.name).transform;
				RootTransform.SetParent(GameManager.WorldManager.FlotsamParent);
			}
			RootTransform.position = _spawnPosition;
			RootTransform.gameObject.SetActive(value: true);
		}
	}

	private void ReleaseRootTransform()
	{
		if ((bool)RootTransform)
		{
			if (_rootTransforms == null)
			{
				_rootTransforms = new List<Transform>(16);
			}
			_rootTransforms.Add(RootTransform);
			RootTransform.gameObject.SetActive(value: false);
			RootTransform = null;
		}
	}

	private bool TryGetTransformInstance(out Transform instance)
	{
		instance = null;
		if (_rootTransforms.IsNullOrEmpty())
		{
			return false;
		}
		int count = _rootTransforms.Count;
		while (0 < count--)
		{
			instance = _rootTransforms[count];
			_rootTransforms.RemoveAt(count);
			if ((bool)instance)
			{
				return true;
			}
		}
		return false;
	}
}
public class SpawnGrid
{
	private int _tileCount;

	private float _worldToIndexMultiplier;

	private int[] _queryIndices;

	private int _queryCount;

	public int Width { get; private set; }

	public int Height { get; private set; }

	public SpawnGridTile[,] Grid { get; private set; }

	public SpawnGrid(int width, int height, float reachableRadius)
	{
		Width = width;
		Height = height;
		Grid = new SpawnGridTile[width, height];
		_tileCount = Width * height;
		_queryIndices = new int[_tileCount];
		float num = reachableRadius * 2f / (float)width;
		float num2 = reachableRadius * 2f / (float)height;
		_worldToIndexMultiplier = ((num < num2) ? (1f / num2) : (1f / num));
		Vector2 vector = new Vector2(0f - reachableRadius, 0f - reachableRadius);
		vector.x += num / 2f;
		vector.y += num2 / 2f;
		int num3 = width - 1;
		int num4 = height - 1;
		for (int i = 0; i < height; i++)
		{
			for (int j = 0; j < width; j++)
			{
				SpawnGridTile spawnGridTile = new SpawnGridTile(vector.x + num * (float)j, vector.y + num2 * (float)i, num, num2);
				if (j == 0 || i == 0 || j == num3 || i == num4)
				{
					spawnGridTile.ClearanceIndex = 0;
				}
				Grid[j, i] = spawnGridTile;
			}
		}
	}

	public void Reset(bool initialze = false)
	{
		int num = Width - 1;
		int num2 = Height - 1;
		for (int i = 0; i < Height; i++)
		{
			for (int j = 0; j < Width; j++)
			{
				SpawnGridTile spawnGridTile = Grid[j, i];
				spawnGridTile.Reset();
				if (j == 0 || i == 0 || j == num || i == num2)
				{
					spawnGridTile.ClearanceIndex = 0;
				}
			}
		}
	}

	public void BlockSphereInterior(Vector2 center, float radius)
	{
		for (int i = 0; i < Height; i++)
		{
			for (int j = 0; j < Width; j++)
			{
				Grid[j, i].SetBlockedWhenOverlappingSphere(center, radius);
			}
		}
		UpdateClearance();
	}

	public void BlockSphereExterior(Vector2 center, float radius)
	{
		for (int i = 0; i < Height; i++)
		{
			for (int j = 0; j < Width; j++)
			{
				Grid[j, i].SetBlockedWhenContainedBySphere(center, radius, invert: true);
			}
		}
		UpdateClearance();
	}

	public void UpdateClearance()
	{
		int num = Width - 1;
		int num2 = Height - 1;
		for (int i = 1; i < num; i++)
		{
			for (int j = 1; j < num2; j++)
			{
				SetTileClearanceIndex(Grid[j, i], j, i);
			}
		}
		int num3 = num2 - 1;
		while (0 < num3)
		{
			int num4 = num - 1;
			while (0 < num4)
			{
				SetTileClearanceIndex(Grid[num4, num3], num4, num3);
				num4--;
			}
			num3--;
		}
	}

	private void SetTileClearanceIndex(SpawnGridTile tile, int indexX, int indexY)
	{
		if (tile.IsBlocked)
		{
			tile.ClearanceIndex = 0;
			return;
		}
		int num = indexX + 2;
		int num2 = indexY + 2;
		int num3 = int.MaxValue;
		for (int i = indexY - 1; i < num2; i++)
		{
			for (int j = indexX - 1; j < num; j++)
			{
				if (j != indexX || i != indexY)
				{
					SpawnGridTile spawnGridTile = Grid[j, i];
					if (spawnGridTile.ClearanceIndex < num3)
					{
						num3 = spawnGridTile.ClearanceIndex;
					}
				}
			}
		}
		tile.ClearanceIndex = ((num3 != int.MaxValue) ? (num3 + 1) : 0);
	}

	public Vector2 ReturnRandomSpawnPosition(float requiredClearance)
	{
		int maxExclusive = ReturnAvailableIndexCount(Mathf.CeilToInt(requiredClearance * _worldToIndexMultiplier));
		int num = _queryIndices[UnityEngine.Random.Range(0, maxExclusive)];
		int num2 = num % Width;
		int num3 = num / Height;
		Vector2 center = Grid[num2, num3].Center;
		BlockSphereInterior(center, requiredClearance);
		return center;
	}

	private int ReturnAvailableIndexCount(int requiredClearance)
	{
		_queryCount = 0;
		for (int i = 0; i < Height; i++)
		{
			for (int j = 0; j < Width; j++)
			{
				if (requiredClearance < Grid[j, i].ClearanceIndex)
				{
					_queryIndices[_queryCount++] = i * Width + j;
				}
			}
		}
		return _queryCount;
	}
}
public class SpawnGridTile
{
	private AxisAllignedRectangle _rectangle;

	public bool IsBlocked { get; private set; }

	public int ClearanceIndex { get; set; } = int.MaxValue;

	public Vector2 Center => _rectangle._center;

	public float Width { get; private set; }

	public float Height { get; private set; }

	public SpawnGridTile(float centerX, float centerY, float width, float height)
	{
		_rectangle = new AxisAllignedRectangle(new Vector2(centerX, centerY), new Vector2(width, height));
		Width = width;
		Height = height;
	}

	public void Reset()
	{
		ClearanceIndex = int.MaxValue;
	}

	public void SetBlockedWhenOverlappingSphere(Vector2 sphereCenter, float sphereRadius, bool invert = false)
	{
		if (!IsBlocked)
		{
			IsBlocked = _rectangle.ReturnIsSphereOverlapping(sphereCenter, sphereRadius);
			if (invert)
			{
				IsBlocked = !IsBlocked;
			}
		}
	}

	public void SetBlockedWhenContainedBySphere(Vector2 sphereCenter, float sphereRadius, bool invert = false)
	{
		if (!IsBlocked)
		{
			IsBlocked = _rectangle.ReturnIsContainedBySphere(sphereCenter, sphereRadius);
			if (invert)
			{
				IsBlocked = !IsBlocked;
			}
		}
	}
}
[CreateAssetMenu(menuName = "Ferry/Spawn Position Providers/Activate Spawn Position Provider")]
public class ActivateSpawnPositionProvider : SpawnPositionProviderBase
{
	private GameplaySettings _settings;

	public override void Initialize(GameplaySettings settings, Vector3 current)
	{
		_settings = settings;
	}

	public override Vector3 ReturnInitialSpawnPosition(bool outsideConstructionRadius)
	{
		float range = (float)_settings.MapRadius - _settings.SpawnRadiusDeviation;
		float clearRadius = (outsideConstructionRadius ? ((float)_settings.ConstructionRadius) : 0f);
		return FlotsamGame.RandomPosition(Vector3.zero, range, useGaussian: false, clearRadius);
	}

	public override Vector3 ReturnSpawnPosition()
	{
		float range = (float)_settings.MapRadius - _settings.SpawnRadiusDeviation;
		return FlotsamGame.RandomPosition(Vector3.zero, range, useGaussian: false);
	}
}
[CreateAssetMenu(menuName = "Ferry/Spawn Position Providers/Active Spawn Position Provider")]
public class ActiveSpawnPositionProvider : SpawnPositionProviderBase
{
	[Range(0f, 1f)]
	[Tooltip("The range is a percentage of the distance between the reachable and destruction radii (0 = destructionRadius)")]
	public float DistanceRange;

	[Range(0f, 90f)]
	[Tooltip("The range in degrees of the angle at which the spawn position can be relative to the current in negative an positive direction")]
	public float AngleRange;

	private float _destructionRadius;

	private float _reachableRadius;

	private Vector3 _currentDirection;

	public override void Initialize(GameplaySettings settings, Vector3 currentDirection)
	{
		_destructionRadius = settings.DestructionRadius;
		_reachableRadius = settings.MapRadius;
		_currentDirection = currentDirection.normalized;
	}

	public override Vector3 ReturnInitialSpawnPosition(bool outsideConstructionRadius)
	{
		return ReturnSpawnPosition();
	}

	public override Vector3 ReturnSpawnPosition()
	{
		float num = Mathf.Lerp(_destructionRadius, _reachableRadius, DistanceRange);
		return Quaternion.AngleAxis(UnityEngine.Random.Range(0f - AngleRange, AngleRange), Vector3.up) * -_currentDirection * num;
	}
}
public interface ISpawnPositionProvider
{
	Vector3 ReturnInitialSpawnPosition(bool outsideConstructionRadius = false);

	Vector3 ReturnSpawnPosition();
}
public abstract class SpawnPositionProviderBase : ScriptableObject, ISpawnPositionProvider
{
	public abstract void Initialize(GameplaySettings settings, Vector3 current);

	public abstract Vector3 ReturnInitialSpawnPosition(bool outsideBuildradius);

	public abstract Vector3 ReturnSpawnPosition();
}
public class Spawnable : MonoBehaviour
{
	public class Event : UnityEvent<Spawnable, EventType>
	{
	}

	public enum EventType
	{
		Salvaged,
		OutOfRange,
		Unloaded
	}

	[NonSerialized]
	public Event OnDestroyed = new Event();

	private FlotsamBehaviour _flotsam;

	private IRangeTester _destructionRangeTester;

	private bool _isUI;

	public void Initialize(FlotsamBehaviour flotsam, IRangeTester destructionRangeTester)
	{
		_flotsam = flotsam;
		_destructionRangeTester = destructionRangeTester;
		_isUI = flotsam == null;
	}

	private void Update()
	{
		if (_isUI && !_destructionRangeTester.IsInRange(base.transform))
		{
			UnityEngine.Object.Destroy(base.gameObject);
		}
	}

	private void OnDestroy()
	{
		EventType arg = (_isUI ? ((!_destructionRangeTester.IsInRange(base.transform)) ? EventType.OutOfRange : EventType.Salvaged) : ((_flotsam.ReturnCompositionProgress() != 0f) ? ((!_destructionRangeTester.IsInRange(base.transform)) ? EventType.OutOfRange : EventType.Unloaded) : EventType.Salvaged));
		OnDestroyed.Invoke(this, arg);
		OnDestroyed.RemoveAllListeners();
	}
}
public static class SpawnerSorting
{
	private static Vector2 _townheartPosition;

	public static void ByDistanceToTownheart<T>(List<T> listToSort) where T : ISpawner
	{
		_townheartPosition = GameManager.WorldManager.World.TownheartMapPosition;
		Sorting.SlowSort(listToSort, DistanceToTownheart);
	}

	private static int DistanceToTownheart<T>(T lhs, T rhs) where T : ISpawner
	{
		if (_townheartPosition.DistanceToSquared(lhs.WorldPosition2D) - _townheartPosition.DistanceToSquared(rhs.WorldPosition2D) < 0f)
		{
			return -1;
		}
		return 1;
	}
}
public class CommunitySaveGroupOverview : MonoBehaviour
{
	[SerializeField]
	private CommunitySaveGroupOverviewSlot _slotPrefab;

	[SerializeField]
	private Transform _slotParent;

	[SerializeField]
	private TextMeshProUGUI _communityName;

	[SerializeField]
	private SelectableGroup _selectableGroup;

	[SerializeField]
	private GameObject _backButton;

	[Header("Actions")]
	[SerializeField]
	private RewiredAction _selectAction = new RewiredAction(29, null);

	[SerializeField]
	private RewiredAction _removeAction = new RewiredAction(85, null);

	private List<CommunitySaveGroupOverviewSlot> _slots = new List<CommunitySaveGroupOverviewSlot>();

	private PlayerRun _run;

	public UnityEvent OnCloseEvent { get; private set; } = new UnityEvent();

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.SaveAdded, OnSaveEvent);
		GameEventDispatcher.AddListener(GameEventType.SaveOverwritten, OnSaveEvent);
		GameEventDispatcher.AddListener(GameEventType.SaveRemoved, OnSaveEvent);
		RewiredAction.AddToActionInfoBar(_selectAction, _removeAction);
		_backButton.gameObject.SetActive(value: true);
	}

	private void LateUpdate()
	{
		if (_removeAction.GetButtonUp() && TryReturnSelectedSlot(out var slot))
		{
			slot.Remove();
		}
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.SaveAdded, OnSaveEvent);
		GameEventDispatcher.RemoveListener(GameEventType.SaveOverwritten, OnSaveEvent);
		GameEventDispatcher.RemoveListener(GameEventType.SaveRemoved, OnSaveEvent);
		RewiredAction.RemoveFromActionInfoBar(_selectAction, _removeAction);
		_backButton.gameObject.SetActive(value: false);
	}

	public void Open(PlayerRun run)
	{
		_run = run;
		_communityName.text = run.CommunityName;
		Sorting.SlowSort(run.Saves);
		int i;
		for (i = 0; i < run.Saves.Count; i++)
		{
			CommunitySaveGroupOverviewSlot communitySaveGroupOverviewSlot;
			if (i < _slots.Count)
			{
				communitySaveGroupOverviewSlot = _slots[i];
			}
			else
			{
				communitySaveGroupOverviewSlot = UnityEngine.Object.Instantiate(_slotPrefab, _slotParent);
				_slots.Add(communitySaveGroupOverviewSlot);
			}
			communitySaveGroupOverviewSlot.Activate(run, run.Saves[i]);
		}
		for (; i < _slots.Count; i++)
		{
			_slots[i].gameObject.SetActive(value: false);
		}
		base.gameObject.SetActive(value: true);
		_selectableGroup.Initialize();
	}

	public void Close()
	{
		base.gameObject.SetActive(value: false);
		OnCloseEvent.Invoke();
	}

	private void OnSaveEvent(GameEvent gameEvent)
	{
		if (gameEvent.EventType == GameEventType.SaveRemoved && _run.Saves.Count <= 0)
		{
			Close();
		}
		else
		{
			Open(_run);
		}
	}

	private bool TryReturnSelectedSlot(out CommunitySaveGroupOverviewSlot slot)
	{
		slot = null;
		if (_selectableGroup == null || _selectableGroup.Selected == null)
		{
			return false;
		}
		for (int i = 0; i < _slots.Count; i++)
		{
			slot = _slots[i];
			if (slot.gameObject == _selectableGroup.Selected.gameObject)
			{
				return true;
			}
		}
		return false;
	}
}
public class CommunitySaveGroupOverviewSlot : MonoBehaviour
{
	[SerializeField]
	private TextMeshProUGUI _saveName;

	[SerializeField]
	private TextMeshProUGUI _versionName;

	[SerializeField]
	private TextMeshProUGUI _date;

	[SerializeField]
	private TextMeshProUGUI _drifterCount;

	[SerializeField]
	private TextMeshProUGUI _dayCount;

	[SerializeField]
	private GameObject _autoSaveIndicator;

	[SerializeField]
	private GameObject _incompatibleVersion;

	[SerializeField]
	private DialogProperties _incompatibleSaveDialog;

	[SerializeField]
	private DialogProperties _removeConfirmationDialog;

	private PlayerRun _run;

	public SaveInfo Save { get; private set; }

	public void Activate(PlayerRun run, SaveInfo saveInfo)
	{
		base.gameObject.SetActive(value: true);
		Save = saveInfo;
		_run = run;
		if (saveInfo.Type == SaveType.Autosave && Application.isEditor)
		{
			_saveName.text = saveInfo.Name + " (" + run.CommunityName + ")";
		}
		else
		{
			_saveName.text = saveInfo.Name;
		}
		_versionName.text = saveInfo.GameVersion.ToString();
		_date.text = saveInfo.TimeStamp.ToString();
		_drifterCount.text = saveInfo.DrifterCount.ToString();
		_dayCount.text = saveInfo.Day.ToString();
		_autoSaveIndicator.SetActive(saveInfo.Type == SaveType.Autosave);
		_incompatibleVersion.SetActive(GameManager.Settings.Version.Save != saveInfo.GameVersion.Save);
	}

	public void Load()
	{
		if (GameManager.Settings.Version.Save == Save.GameVersion.Save)
		{
			LoadCurrentSave();
		}
		else if (PopUpDialog.Instance.TryOpenPopUpDialog(_incompatibleSaveDialog))
		{
			PopUpDialog.Instance.DialogFeedbackEvent.AddListener(HandleIncompatibleSaveDialog);
		}
	}

	public void Remove()
	{
		if (PopUpDialog.Instance.TryOpenPopUpDialog(_removeConfirmationDialog))
		{
			PopUpDialog.Instance.DialogFeedbackEvent.AddListener(HandleRemoveConfirmationDialog);
		}
	}

	private void HandleIncompatibleSaveDialog(bool result)
	{
		if (result)
		{
			LoadCurrentSave();
		}
	}

	private void HandleRemoveConfirmationDialog(bool result)
	{
		PopUpDialog.Instance.DialogFeedbackEvent.RemoveListener(HandleRemoveConfirmationDialog);
		if (result)
		{
			_run.RemoveSave(Save);
		}
	}

	private void LoadCurrentSave()
	{
		_run.Continue(Save);
	}
}
public class CommunitySavesOverview : MonoBehaviour
{
	[SerializeField]
	private ChildBehaviourCache<CommunitySavesOverviewSlot> _slots;

	[SerializeField]
	private SelectableGroup _selectableGroup;

	public PlayerRunEvent OnSelectedEvent { get; private set; } = new PlayerRunEvent();

	public void Open(List<PlayerRun> playerRuns)
	{
		Sorting.SlowSort(playerRuns);
		base.gameObject.SetActive(value: true);
		_slots.Reset();
		foreach (PlayerRun playerRun in playerRuns)
		{
			if (playerRun.MostRecentSave != null)
			{
				_slots.Get(active: true).Activate(this, playerRun);
			}
		}
		_slots.Trim();
		_selectableGroup.Initialize();
	}

	public void Select(PlayerRun playerRun)
	{
		OnSelectedEvent.Invoke(playerRun);
	}
}
public class CommunitySavesOverviewSlot : MonoBehaviour
{
	[SerializeField]
	private TextMeshProUGUI _name;

	[SerializeField]
	private TextMeshProUGUI _date;

	[SerializeField]
	private TextMeshProUGUI _extraInfo;

	[Space]
	[SerializeField]
	private LocalizedString _extraInfoTerm = null;

	private CommunitySavesOverview _overview;

	private PlayerRun _run;

	private int _saveAmount;

	private int _autoSaveAmount;

	private long _fileSize;

	public void Activate(CommunitySavesOverview overview, PlayerRun run)
	{
		base.gameObject.SetActive(value: true);
		_overview = overview;
		_run = run;
		_name.text = run.CommunityName;
		_date.text = run.MostRecentSave.TimeStamp.ToString();
		_saveAmount = 0;
		_autoSaveAmount = 0;
		_fileSize = 0L;
		foreach (SaveInfo safe in run.Saves)
		{
			_fileSize += safe.Size;
			if (safe.Type == SaveType.Autosave)
			{
				_autoSaveAmount++;
			}
			else
			{
				_saveAmount++;
			}
		}
		string input = Regex.Replace(_extraInfoTerm, "%SAVES%", _saveAmount.ToString());
		input = Regex.Replace(input, "%AUTOSAVES%", _autoSaveAmount.ToString());
		input = Regex.Replace(input, "%FILESIZE%", _fileSize.ToByteString());
		_extraInfo.text = input;
	}

	public void Select()
	{
		if (!(_overview == null))
		{
			_overview.Select(_run);
		}
	}
}
