public class SaveAsSlot : MonoBehaviour
{
	[SerializeField]
	private TextMeshProUGUI _name;

	[SerializeField]
	private TextMeshProUGUI _date;

	[SerializeField]
	private TextMeshProUGUI _version;

	[SerializeField]
	private TextMeshProUGUI _drifterCount;

	[SerializeField]
	private TextMeshProUGUI _dayCount;

	[SerializeField]
	private GameObject _autoSaveIndicator;

	[SerializeField]
	private GameObject _incompatibleVersion;

	private SaveInfo _save;

	public void Initialize(SaveInfo save)
	{
		base.gameObject.SetActive(value: true);
		_save = save;
		UpdateInfo(_save);
	}

	private void OnEnable()
	{
		GameEventDispatcher.AddListener(GameEventType.SaveOverwritten, OnSaveOverwrite);
	}

	private void OnDisable()
	{
		GameEventDispatcher.RemoveListener(GameEventType.SaveOverwritten, OnSaveOverwrite);
	}

	private void OnSaveOverwrite(GameEvent gameEvent)
	{
		if (gameEvent is SaveEvent saveEvent)
		{
			UpdateInfo(saveEvent.Save);
		}
	}

	private void UpdateInfo(SaveInfo save)
	{
		if (_save != null && _save == save)
		{
			_name.text = _save.Name;
			_date.text = _save.TimeStamp.ToString();
			_version.text = _save.GameVersion.ToString();
			_drifterCount.text = _save.DrifterCount.ToString();
			_dayCount.text = _save.Day.ToString();
			_autoSaveIndicator.SetActive(_save.Type == SaveType.Autosave);
			_incompatibleVersion.SetActive(GameManager.Settings.Version.Save != _save.GameVersion.Save);
		}
	}

	public void Overwrite()
	{
		SaveDialogProperties saveDialogProperties = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.OverwriteSaveProperties);
		saveDialogProperties.Initialize(_save);
		if (PopUpDialog.Instance.TryOpenPopUpDialog(saveDialogProperties))
		{
			PopUpDialog.Instance.DialogFeedbackEvent.AddListener(HandleOverwriteDialog);
		}
	}

	private void HandleOverwriteDialog(bool overwrite)
	{
		PopUpDialog.Instance.DialogFeedbackEvent.RemoveListener(HandleOverwriteDialog);
		Session.Profile.ActiveRun.Save(_save);
	}
}
public class SaveAsWindow : PauseMenuWindow
{
	[SerializeField]
	private SaveAsSlot _slotPrefab;

	[SerializeField]
	private Transform _slotParent;

	private List<SaveAsSlot> _slots = new List<SaveAsSlot>();

	private SaveInfo _saveToOverwrite;

	public void Open()
	{
		UpdateSaveFiles(Session.Profile.ActiveRun.Saves);
		base.gameObject.SetActive(value: true);
	}

	protected override void OnEnable()
	{
		base.OnEnable();
		GameEventDispatcher.AddListener(GameEventType.SaveAdded, OnSaveFilesUpdate);
		GameEventDispatcher.AddListener(GameEventType.SaveRemoved, OnSaveFilesUpdate);
		GameEventDispatcher.AddListener(GameEventType.SaveOverwritten, OnSaveFilesUpdate);
	}

	protected override void OnDisable()
	{
		base.OnDisable();
		GameEventDispatcher.RemoveListener(GameEventType.SaveAdded, OnSaveFilesUpdate);
		GameEventDispatcher.RemoveListener(GameEventType.SaveRemoved, OnSaveFilesUpdate);
		GameEventDispatcher.RemoveListener(GameEventType.SaveOverwritten, OnSaveFilesUpdate);
	}

	private void OnSaveFilesUpdate(GameEvent gameEvent)
	{
		base.gameObject.SetActive(value: false);
	}

	public void CreateNewSave()
	{
		if (PopUpDialog.Instance.TryPopUpInput(GameManager.Settings.UISettings.InputSaveName, Community.PlayerCommunity.Name))
		{
			PopUpDialog.Instance.InputEvent += HandleNewSaveDialog;
		}
	}

	private void HandleNewSaveDialog(string newSaveName, bool dialogFeedback)
	{
		PopUpDialog.Instance.InputEvent -= HandleNewSaveDialog;
		if (!dialogFeedback)
		{
			return;
		}
		if (Session.Profile.ActiveRun.TryGetSave(out _saveToOverwrite, newSaveName))
		{
			SaveDialogProperties saveDialogProperties = UnityEngine.Object.Instantiate(GameManager.Settings.UISettings.OverwriteSaveProperties);
			saveDialogProperties.Initialize(_saveToOverwrite);
			if (PopUpDialog.Instance.TryOpenPopUpDialog(saveDialogProperties))
			{
				PopUpDialog.Instance.DialogFeedbackEvent.AddListener(HandleOverwriteDialog);
			}
		}
		else
		{
			Session.Profile.ActiveRun.Save(newSaveName);
		}
	}

	private void HandleOverwriteDialog(bool overwrite)
	{
		PopUpDialog.Instance.DialogFeedbackEvent.RemoveListener(HandleOverwriteDialog);
		if (overwrite && _saveToOverwrite != null)
		{
			Session.Profile.ActiveRun.Save(_saveToOverwrite);
		}
	}

	private void UpdateSaveFiles(List<SaveInfo> saves)
	{
		for (int i = 0; i < _slots.Count; i++)
		{
			_slots[i].gameObject.SetActive(value: false);
		}
		for (int j = 0; j < saves.Count; j++)
		{
			SaveInfo saveInfo = saves[j];
			if (saveInfo.Type == SaveType.Manual)
			{
				SaveAsSlot saveAsSlot;
				if (j < _slots.Count)
				{
					saveAsSlot = _slots[j];
				}
				else
				{
					saveAsSlot = UnityEngine.Object.Instantiate(_slotPrefab, _slotParent);
					_slots.Add(saveAsSlot);
				}
				saveAsSlot.Initialize(saveInfo);
			}
		}
	}
}
public static class SaveFileMigration
{
	public static readonly string OLD_AUTOSAVES_DIRECTORY = Application.persistentDataPath + "/Saves/Autosaves/";

	private static List<SaveMetaInfo> _savesToMigrate;

	private static void Initialize()
	{
		if (_savesToMigrate == null)
		{
			_savesToMigrate = new List<SaveMetaInfo>(128);
			PopulateSavesToMigrate(SaveInfo.PLAYER_SAVES_DIRECTORY, "*.fs", _savesToMigrate);
			PopulateSavesToMigrate(OLD_AUTOSAVES_DIRECTORY, "*.fs", _savesToMigrate);
		}
	}

	private static void PopulateSavesToMigrate(string directory, string searchPattern, List<SaveMetaInfo> savesToMigrate)
	{
		if (!Directory.Exists(directory))
		{
			return;
		}
		string[] files = Directory.GetFiles(directory, searchPattern);
		foreach (string path in files)
		{
			if (TryLoad(out var instance, path))
			{
				savesToMigrate.Add(instance);
			}
		}
	}

	public static int ReturnSaveRequiredMigrationAmount()
	{
		Initialize();
		return _savesToMigrate.Count;
	}

	public static int MigrateFiles()
	{
		Initialize();
		int result = MigrateFiles(_savesToMigrate);
		Extensions.TryDeleteDirectory(OLD_AUTOSAVES_DIRECTORY);
		Session.Profile.OnSaveFilesMigrated();
		new GameEvent(GameEventType.SavesMigrated).Dispatch();
		Settings.Instance.HasMigratedSaves = true;
		Settings.Instance.Save();
		return result;
	}

	private static int MigrateFiles(List<SaveMetaInfo> savesToMigrate)
	{
		int num = 0;
		foreach (SaveMetaInfo item in savesToMigrate)
		{
			try
			{
				FileInfo fileInfo = new FileInfo(item.Path);
				if (!SaveMetaInfo.TryReturnDirectory(item.CommunityName, item.Type, out var directory))
				{
					Directory.CreateDirectory(directory);
				}
				directory += fileInfo.Name;
				if (File.Exists(directory))
				{
					UnityEngine.Debug.LogErrorFormat("Unable to Migrate '{0}' to '{1}' because a file already exists at that path.", item.Path, directory);
				}
				else
				{
					File.Move(item.Path, directory);
					num++;
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogErrorFormat("Unable to Migrate '{0}' because of exception '{1}'.", item.Path, ex.Message);
			}
		}
		return num;
	}

	private static bool TryLoad(out SaveMetaInfo instance, string path)
	{
		if (File.Exists(path) && SaveMetaInfo.TryDeserialize(path, File.ReadAllBytes(path), out instance))
		{
			return true;
		}
		UnityEngine.Debug.LogException(new Exception("Unable to load SaveMetaInfo for migartion: '" + path + "'"));
		instance = null;
		return false;
	}

	public static bool ReturnRequiresMigration()
	{
		if (Settings.Instance.HasMigratedSaves)
		{
			return false;
		}
		Initialize();
		return 0 < _savesToMigrate.Count;
	}
}
public class SaveHelper : MonoBehaviour
{
	[SerializeField]
	private SaveAsWindow _saveAsWindow;

	private SaveInfo _cachedSave;

	public void Save()
	{
