public class Deserializer<T> where T : SerializableBase, new()
{
	public T Root { get; private set; }

	public T Deserialize(string filename)
	{
		using (FileStream stream = File.OpenRead(filename))
		{
			Deserialize(stream);
		}
		return Root;
	}

	public T Deserialize(byte[] buffer)
	{
		using (MemoryStream stream = new MemoryStream(buffer))
		{
			Deserialize(stream);
		}
		return Root;
	}

	private void Deserialize(Stream stream)
	{
		BinaryReader reader = new BinaryReader(stream);
		Root = new T();
		Root.Deserialize(reader, isRoot: true);
	}
}
public class SerializableClass : SerializableBase
{
	public byte Byte;

	public bool Bool;

	public int Int;

	public float Float;

	public string String;

	public SerializableSubclass _subclass1;

	public SerializableSubclass _subclass2;

	public override SerializationMarkers Marker => SerializationMarkers.SerializableClass;

	public SerializableClass()
	{
	}

	public SerializableClass(byte bt, bool bl, string s, int i, float f)
	{
		Byte = bt;
		Bool = bl;
		String = s;
		Int = i;
		Float = f;
		_subclass1 = new SerializableSubclass("Hello Subclass!");
		_subclass2 = new SerializableSubclass("Bye Subclass!");
	}

	protected override void InternalSerialize()
	{
		WriteByte("byte", Byte);
		WriteBool("bool", Bool);
		WriteString("string", String);
		WriteInt("int", Int);
		WriteFloat("float", Float);
		WriteSerializable("sc1", _subclass1);
		WriteSerializable("sc2", _subclass2);
	}

	protected override void InternalDeserialize()
	{
		Byte = ReadByte("byte", 0);
		Bool = ReadBool("bool");
		String = ReadString("string");
		Int = ReadInt("int");
		Float = ReadFloat("float");
		_subclass1 = ReadSerializable<SerializableSubclass>("sc1");
		_subclass2 = ReadSerializable<SerializableSubclass>("sc2");
	}
}
public class SerializableRoot
{
	public static void Initialize()
	{
	}
}
public class SerializableSubclass : SerializableBase
{
	public string String;

	public override SerializationMarkers Marker => SerializationMarkers.SerializableSubclass;

	public SerializableSubclass()
	{
	}

	public SerializableSubclass(string s)
	{
		String = s;
	}

	protected override void InternalSerialize()
	{
		WriteString("string", String);
	}

	protected override void InternalDeserialize()
	{
		String = ReadString("string");
	}
}
public interface ISerializableInstantiator
{
	SerializableBase Instantiate();
}
public static class SerializableFactory
{
	private static Dictionary<SerializationMarkers, ISerializableInstantiator> _instantiators;

	public static void RegisterInstantiator<T>() where T : SerializableBase, new()
	{
		SerializationMarkers marker = new T().Marker;
		if (_instantiators == null)
		{
			_instantiators = new Dictionary<SerializationMarkers, ISerializableInstantiator>();
		}
		if (_instantiators.ContainsKey(marker))
		{
			PajamaLlama.Debugs.Debugger.Error("SerialiableInstantiators " + typeof(T)?.ToString() + " and " + _instantiators[marker]?.ToString() + " have duplicate serialization markers");
		}
		else
		{
			_instantiators.Add(marker, new SerializableInstantiator<T>());
		}
	}

	public static SerializableBase ReturnInstance(SerializationMarkers marker)
	{
		if (_instantiators == null)
		{
			throw new Exception("No serialiable instantiators have been registered with the SerialiableFactory.");
		}
		if (_instantiators.TryGetValue(marker, out var value))
		{
			return value.Instantiate();
		}
		PajamaLlama.Debugs.Debugger.Error("No serializable instantiator found for serialization marker (" + marker.ToString() + ")!");
		return null;
	}
}
public class SerializableInstantiator<T> : ISerializableInstantiator where T : SerializableBase, new()
{
	public SerializableBase Instantiate()
	{
		return new T();
	}
}
public abstract class SerializableBase
{
	private BinaryWriter _writer;

	private Dictionary<string, byte[]> _deserializedValueTypes;

	private Dictionary<string, string> _deserializedStrings;

	private Dictionary<string, SerializableBase> _deserializedSerializables;

	public abstract SerializationMarkers Marker { get; }

	public void Serialize(BinaryWriter writer)
	{
		_writer = writer;
		_writer.Write((byte)Marker);
		InternalSerialize();
		_writer.Write(byte.MaxValue);
		_writer = null;
	}

	public void Deserialize(BinaryReader reader, bool isRoot)
	{
		if (isRoot && reader.ReadByte() != 16)
		{
			PajamaLlama.Debugs.Debugger.Error("The root object for the serialization should always extend SerializableBase!");
			return;
		}
		SerializationMarkers serializationMarkers;
		while ((serializationMarkers = (SerializationMarkers)reader.ReadByte()) == SerializationMarkers.Key)
		{
			string key = reader.ReadString();
			SerializationMarkers serializationMarkers2 = (SerializationMarkers)reader.ReadByte();
			switch (serializationMarkers2)
			{
			case SerializationMarkers.Key:
			case SerializationMarkers.SerializableEnd:
				PajamaLlama.Debugs.Debugger.Error("Unexpected marker '" + serializationMarkers2.ToString() + "' encountered during deserialization!");
				serializationMarkers = serializationMarkers2;
				continue;
			case SerializationMarkers.Byte:
			case SerializationMarkers.Boolean:
				DeserializeValueType(reader, key, 1);
				continue;
			case SerializationMarkers.Integer:
			case SerializationMarkers.Float:
				DeserializeValueType(reader, key, 4);
				continue;
			case SerializationMarkers.String:
				if (_deserializedStrings == null)
				{
					_deserializedStrings = new Dictionary<string, string>();
				}
				_deserializedStrings.Add(key, reader.ReadString());
				continue;
			}
			if (_deserializedSerializables == null)
			{
				_deserializedSerializables = new Dictionary<string, SerializableBase>();
			}
			SerializableBase serializableBase = SerializableFactory.ReturnInstance(serializationMarkers2);
			serializableBase.Deserialize(reader, isRoot: false);
			_deserializedSerializables.Add(key, serializableBase);
		}
		if (serializationMarkers != SerializationMarkers.SerializableEnd)
		{
			PajamaLlama.Debugs.Debugger.Error(GetType()?.ToString() + " has finished serialization with marker '" + serializationMarkers.ToString() + "' instead of the 'SerializableEnd' marker!");
		}
		InternalDeserialize();
	}

	protected abstract void InternalSerialize();

	protected abstract void InternalDeserialize();

	protected void WriteByte(string key, byte value)
	{
		WriteKey(key);
		_writer.Write((byte)8);
		_writer.Write(value);
	}

	protected void WriteBool(string key, bool value)
	{
		WriteKey(key);
		_writer.Write((byte)9);
		_writer.Write(value);
	}

	protected void WriteInt(string key, int value)
	{
		WriteKey(key);
		_writer.Write((byte)10);
		_writer.Write(value);
	}

	protected void WriteFloat(string key, float value)
	{
		WriteKey(key);
		_writer.Write((byte)11);
		_writer.Write(value);
	}

	protected void WriteString(string key, string value)
	{
		WriteKey(key);
		_writer.Write((byte)12);
		_writer.Write(value);
	}

	protected void WriteSerializable(string key, SerializableBase serializable)
	{
		WriteKey(key);
		serializable.Serialize(_writer);
	}

	private void WriteKey(string key)
	{
		_writer.Write((byte)1);
		_writer.Write(key);
	}

	protected byte ReadByte(string key, byte defaultValue = 0)
	{
		if (TryReturnDeserializedBytes(key, out var bytes))
		{
			return bytes[0];
		}
		return defaultValue;
	}

	protected bool ReadBool(string key, bool defaultValue = false)
	{
		if (TryReturnDeserializedBytes(key, out var bytes))
		{
			return BitConverter.ToBoolean(bytes, 0);
		}
		return defaultValue;
	}

	protected int ReadInt(string key, int defaultValue = 0)
	{
		if (TryReturnDeserializedBytes(key, out var bytes))
		{
			return BitConverter.ToInt32(bytes, 0);
		}
		return defaultValue;
	}

	protected float ReadFloat(string key, float defaultValue = 0f)
	{
		if (TryReturnDeserializedBytes(key, out var bytes))
		{
			return BitConverter.ToSingle(bytes, 0);
		}
		return defaultValue;
	}

	protected string ReadString(string key, string defaultValue = null)
	{
		if (_deserializedStrings == null)
		{
			PajamaLlama.Debugs.Debugger.Error("No strings were deserialized!");
			return null;
		}
		if (_deserializedStrings.TryGetValue(key, out var value))
		{
			return value;
		}
		PajamaLlama.Debugs.Debugger.Error("No string was found for key: " + key + "!");
		return defaultValue;
	}

	protected T ReadSerializable<T>(string key) where T : SerializableBase
	{
		if (_deserializedSerializables == null)
		{
			PajamaLlama.Debugs.Debugger.Error("No serializables were deserialized!");
			return null;
		}
		if (_deserializedSerializables.TryGetValue(key, out var value))
		{
			T obj = value as T;
			if (obj == null)
			{
				PajamaLlama.Debugs.Debugger.Error("Serializable type mismatch between " + typeof(T)?.ToString() + " and " + value.GetType());
			}
			return obj;
		}
		PajamaLlama.Debugs.Debugger.Error("No serializable was found for key: " + key + "!");
		return null;
	}

	private void DeserializeValueType(BinaryReader reader, string key, int bytes)
	{
		if (_deserializedValueTypes == null)
		{
			_deserializedValueTypes = new Dictionary<string, byte[]>();
		}
		_deserializedValueTypes.Add(key, reader.ReadBytes(bytes));
	}

	private bool TryReturnDeserializedBytes(string key, out byte[] bytes)
	{
		if (_deserializedValueTypes == null)
		{
			PajamaLlama.Debugs.Debugger.Error("No value types were deserialized!");
			bytes = null;
			return false;
		}
		if (_deserializedValueTypes.TryGetValue(key, out bytes))
		{
			return true;
		}
		PajamaLlama.Debugs.Debugger.Error("No value type was found for key: " + key + "!");
		bytes = null;
		return false;
	}
}
