public class SerializationManager : MonoBehaviour
{
	private void Start()
	{
		SerializableFactory.RegisterInstantiator<SerializableClass>();
		SerializableFactory.RegisterInstantiator<SerializableSubclass>();
		byte[] buffer = new Serializer(new SerializableClass(254, bl: true, "Hello Serialization", 32, 3.14f)).Serialize();
		SerializableClass serializableClass = new Deserializer<SerializableClass>().Deserialize(buffer);
		UnityEngine.Debug.Log("Byte: " + serializableClass.Byte);
		UnityEngine.Debug.Log("Bool: " + serializableClass.Bool);
		UnityEngine.Debug.Log("String: " + serializableClass.String);
		UnityEngine.Debug.Log("Int: " + serializableClass.Int);
		UnityEngine.Debug.Log("Float: " + serializableClass.Float);
		UnityEngine.Debug.Log("SC1: " + serializableClass._subclass1.String);
		UnityEngine.Debug.Log("SC1: " + serializableClass._subclass2.String);
	}
}
public enum SerializationMarkers : byte
{
	Key = 1,
	Byte = 8,
	Boolean = 9,
	Integer = 10,
	Float = 11,
	String = 12,
	SerializableClass = 16,
	SerializableSubclass = 17,
	SerializableEnd = byte.MaxValue
}
public class Serializer : MonoBehaviour
{
	private SerializableBase _root;

	public Serializer(SerializableBase root)
	{
		_root = root;
	}

	public void Serialize(string filename)
	{
		using FileStream stream = File.OpenRead(filename);
		Serialize(stream);
	}

	public byte[] Serialize()
	{
		using MemoryStream memoryStream = new MemoryStream();
		Serialize(memoryStream);
		return memoryStream.ToArray();
	}

	private void Serialize(Stream stream)
	{
		BinaryWriter writer = new BinaryWriter(stream);
		_root.Serialize(writer);
	}
}
[CreateAssetMenu(menuName = "Flotsam/Settings/Agent Settings")]
public class AgentSettings : ScriptableObject
{
	[SerializeField]
	private ActorProperties[] _actors;

	[Header("Icons")]
	[Tooltip("Icon properties for a warning.")]
	public IconProperties WarningIconProperties;

	[Tooltip("Icon properties for not having a house.")]
	public IconProperties NoHousingIconProperties;

	public IconProperties IdlingIconProperties;

	[Space]
	public IconProperties SeagullIdleIconProperties;

	public IconProperties SeagullEatingIconProperties;

	public IconProperties SeagullSalvagingIconProperties;

	public IconProperties SeagullSleepingIconProperties;

	public IconProperties SeagullMovingIconProperties;

	public IconProperties SeagullHungryIconProperties;

	public IconProperties SeagullHappyIconProperties;

	public IconProperties SeagullNormalIconProperties;

	public IconProperties SeagullUnhappyIconProperties;

	[Space]
	public IconProperties DrifterMortalDangerIconProperties;

	public void Initialize()
	{
		ActorProperties[] actors = _actors;
		for (int i = 0; i < actors.Length; i++)
		{
			actors[i].Initialize();
		}
	}

	public T GetActorProperties<T>() where T : ActorProperties
	{
		T val = null;
		ActorProperties[] actors = _actors;
		for (int i = 0; i < actors.Length; i++)
		{
			val = actors[i] as T;
			if ((bool)val)
			{
				return val;
			}
		}
		UnityEngine.Debug.LogException(new Exception("Unable to find ActorProperties of Type '" + typeof(T).Name + "'. Add an ActorProperties for this Type to AgentSettings!"));
		return null;
	}

	public bool TryGetActorProperties<T>(out T properties) where T : ActorProperties
	{
		ActorProperties[] actors = _actors;
		foreach (ActorProperties actorProperties in actors)
		{
			properties = actorProperties as T;
			if ((bool)properties)
			{
				return true;
			}
		}
		properties = null;
		return false;
	}

	public bool TryGetActorProperties<T>(out T properties, ActorType actorType) where T : ActorProperties
	{
		int num = _actors.Length;
		while (0 < num--)
		{
			properties = _actors[num] as T;
			if ((bool)properties && properties.ActorType == actorType)
			{
				return true;
			}
		}
		properties = null;
		return false;
	}
}
