public class Dialogue : ILocalizationParamsManager
{
	public System.Action OnCanProgressDialogue;

	private AgentDescriptor _mainSpeaker;

	private AgentDescriptor _speakerOverride;

	private DialogueContext.ActorType _currentSpeakerOverrideType;

	private IDialogueNode _currentNode;

	public DialogueTreeProperties DialogueProperties { get; }

	public AgentDescriptor CurrentSpeaker
	{
		get
		{
			if (!(_speakerOverride != null))
			{
				return _mainSpeaker;
			}
			return _speakerOverride;
		}
	}

	public AgentDescriptor MainSpeaker => _mainSpeaker;

	public IDialogueNode CurrentNode => _currentNode;

	public DialoguePanelOptions CurrentDialoguePanelOptions
	{
		get
		{
			if (_currentNode == null)
			{
				return null;
			}
			return _currentNode.DialoguePanelOptions;
		}
	}

	public IDialogueInteractable Interactable { get; private set; }

	public bool IsInRepeat { get; private set; }

	public Dialogue(DialogueTreeProperties dialogueProperties)
	{
		DialogueProperties = dialogueProperties;
	}

	public void SetIsRepeat(bool isRepeat)
	{
		IsInRepeat = isRepeat;
	}

	public void RestartDialogue()
	{
		if (_currentNode != null)
		{
			IDialogueNode currentNode = _currentNode;
			currentNode.OnProgressConditionsMet = (System.Action)Delegate.Remove(currentNode.OnProgressConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
		}
		_currentNode = null;
		Interactable = null;
	}

	public bool CanProgressDialogue()
	{
		if (_currentNode != null)
		{
			return _currentNode.CanExitNode(IsInRepeat);
		}
		return true;
	}

	public bool ProgressDialogue(DialoguePanel dialoguePanel)
	{
		if (TryProgressInternal(dialoguePanel))
		{
			return true;
		}
		if (_currentNode != null)
		{
			IDialogueNode currentNode = _currentNode;
			currentNode.OnProgressConditionsMet = (System.Action)Delegate.Remove(currentNode.OnProgressConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
			_currentNode.ExitNode(dialoguePanel, this);
		}
		_currentNode = null;
		return false;
	}

	public bool PlayDialogueInteractable(IDialogueInteractable interactable, DialoguePanel dialoguePanel, DialogueNodeProperties entryNode = null)
	{
		Interactable = interactable;
		if (entryNode != null || interactable.TryGetEntryPoint(out entryNode))
		{
			return PlaySpecificDialogueBranch(entryNode, dialoguePanel);
		}
		return false;
	}

	public bool PlaySpecificDialogueBranch(DialogueNodeProperties branch, DialoguePanel dialoguePanel)
	{
		if (PlayBranch(branch, dialoguePanel))
		{
			return true;
		}
		if (_currentNode != null)
		{
			IDialogueNode currentNode = _currentNode;
			currentNode.OnProgressConditionsMet = (System.Action)Delegate.Remove(currentNode.OnProgressConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
			_currentNode.ExitNode(dialoguePanel, this);
		}
		_currentNode = null;
		return false;
	}

	public bool TryProgressToPlayerChoices(DialoguePanel dialoguePanel)
	{
		return TryProgressInternal(dialoguePanel, typeof(DialogueNodePlayerChoicesProperties));
	}

	private bool TryProgressInternal(DialoguePanel dialoguePanel, Type nodeTypeRestriction = null)
	{
		if (TryGetPlayableBranch(out var branchNodeProperties, nodeTypeRestriction))
		{
			return PlayBranch(branchNodeProperties, dialoguePanel);
		}
		return false;
	}

	private bool PlayBranch(DialogueNodeProperties branchNodeProperties, DialoguePanel dialoguePanel)
	{
		if (_currentNode != null)
		{
			IDialogueNode currentNode = _currentNode;
			currentNode.OnProgressConditionsMet = (System.Action)Delegate.Remove(currentNode.OnProgressConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
			_currentNode.ExitNode(dialoguePanel, this);
		}
		_currentNode = DialogueNodeFactory.GetNode(branchNodeProperties);
		AcquireSpeakerOverride();
		_currentNode.EnterNode(dialoguePanel, this);
		if (!IsInRepeat && branchNodeProperties.ProgressDialogueConditions != null && branchNodeProperties.ProgressDialogueConditions.SkipNodeIfConditionsAlreadyMet && _currentNode.AreProgressConditionsMet())
		{
			return ProgressDialogue(dialoguePanel);
		}
		IDialogueNode currentNode2 = _currentNode;
		currentNode2.OnProgressConditionsMet = (System.Action)Delegate.Combine(currentNode2.OnProgressConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
		return true;
	}

	public bool IsDialogueOver()
	{
		return _currentNode == null;
	}

	public bool IsNextNodePlayerChoices()
	{
		if (TryGetNextBranches(out var branches))
		{
			foreach (DialogueNodeProperties item in branches)
			{
				if (item is DialogueNodePlayerChoicesProperties)
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool TryGetNextBranches(out IReadOnlyList<DialogueNodeProperties> branches)
	{
		branches = ((_currentNode == null) ? DialogueProperties.Branches : _currentNode.Branches);
		return branches != null;
	}

	private bool TryGetPlayableBranch(out DialogueNodeProperties branchNodeProperties, Type nodeTypeRestriction = null)
	{
		if (TryGetNextBranches(out var branches))
		{
			for (int num = branches.Count - 1; num >= 0; num--)
			{
				DialogueNodeProperties dialogueNodeProperties = branches[num];
				if ((nodeTypeRestriction == null || dialogueNodeProperties.GetType().IsAssignableFrom(nodeTypeRestriction)) && dialogueNodeProperties.AreConditionsMet())
				{
					branchNodeProperties = dialogueNodeProperties;
					return true;
				}
			}
		}
		branchNodeProperties = null;
		return false;
	}

	public void AcquireMainSpeaker(IDialogueInteractable interactable)
	{
		Interactable = null;
		if (interactable == null || !interactable.TryGetMainSpeaker(out _mainSpeaker))
		{
			DialogueContext.ActorType actorType = ((DialogueProperties.Speaker == DialogueContext.ActorType.None) ? DialogueContext.ActorType.FirstMate : DialogueProperties.Speaker);
			StoryManager.DialogueContext.TryGetActor(actorType, out _mainSpeaker);
		}
	}

	private void AcquireSpeakerOverride()
	{
		DialogueContext.ActorType actorType = ((_currentNode != null && _currentNode.DialoguePanelOptions != null) ? _currentNode.DialoguePanelOptions.SpeakerOverride : DialogueContext.ActorType.None);
		if (actorType == _currentSpeakerOverrideType)
		{
			return;
		}
		_speakerOverride = null;
		if (actorType != DialogueContext.ActorType.None && !TryGetActorDescriptor(actorType, out _speakerOverride))
		{
			UnityEngine.Debug.LogException(new MissingReferenceException($"Could not find a speaker override of type {actorType} for current dialogue ({DialogueProperties})!"));
		}
		_currentSpeakerOverrideType = actorType;
		if (_mainSpeaker == null)
		{
			if (_speakerOverride != null)
			{
				_mainSpeaker = _speakerOverride;
				return;
			}
			UnityEngine.Debug.LogException(new MissingReferenceException($"Could not find a speaker of type {DialogueProperties.Speaker} for current dialogue ({DialogueProperties})! Falling back to {DialogueContext.ActorType.FirstMate} instead."));
			_mainSpeaker = StoryManager.DialogueContext.GetActor(DialogueContext.ActorType.FirstMate);
		}
	}

	private bool TryGetActorDescriptor(DialogueContext.ActorType actorType, out AgentDescriptor actorDescriptor)
	{
		if (Interactable == null)
		{
			return StoryManager.DialogueContext.TryGetActor(actorType, out actorDescriptor);
		}
		return Interactable.TryGetActorDescriptor(actorType, out actorDescriptor);
	}

	private void TriggerOnProgressConditionsMet()
	{
		if (OnCanProgressDialogue != null)
		{
			OnCanProgressDialogue();
		}
	}

	string ILocalizationParamsManager.GetParameterValue(string Param)
	{
		switch (Param)
		{
		case "NAME":
		case "CURRENT_SPEAKER":
			if (CurrentSpeaker != null)
			{
				return CurrentSpeaker.Name;
			}
			break;
		case "MAIN_SPEAKER":
			if (MainSpeaker != null)
			{
				return MainSpeaker.Name;
			}
			break;
		}
		return null;
	}
}
public enum DialogueBranchType
{
	None = 0,
	Reference = 1,
	DistressSignal = 2,
	Rescue = 3,
	QuestGiver = 4,
	QuestAccepted = 6,
	QuestCompleted = 5
}
[Serializable]
public class DialogueBranch : ICloneable
{
	[SerializeField]
	private DialogueBranchType _type;

	[SerializeField]
	[ConditionalEnumHide("_type", 1, false, HideInInspector = true)]
	private string _name;

	[SerializeField]
	private DialogueNodeProperties _entryNode;

	[SerializeField]
	private bool _isDefaultBranch;

	[SerializeReference]
	[SubclassSelector]
	private List<IQuestObjective> _triggerConditions = new List<IQuestObjective>();

	[SerializeField]
	[HideInInspector]
	private ushort _uniqueID;

	public Action<DialogueNodeProperties> OnBranchTriggered;

	public DialogueBranchType Type => _type;

	public string Name => _name;

	public string Label
	{
		get
		{
			if (_type != DialogueBranchType.Reference)
			{
				return _type.ToString().SplitCamelCase();
			}
			return _type.ToString().SplitCamelCase() + ": " + _name;
		}
	}

	public DialogueNodeProperties EntryNode => _entryNode;

	public bool IsDefaultBranch => _isDefaultBranch;

	public IReadOnlyList<IQuestObjective> TriggerConditions => _triggerConditions;

	public ushort UniqueID => _uniqueID;

	public DialogueBranch()
	{
	}

	public DialogueBranch(DialogueNodeProperties entryNode)
	{
		_entryNode = entryNode;
	}

	public DialogueBranch(DialogueBranch other)
	{
		_type = other._type;
		_name = other._name;
		_entryNode = other._entryNode;
		_isDefaultBranch = other._isDefaultBranch;
		_triggerConditions = other._triggerConditions.Clone();
	}

	public void AssignUniqueID(ushort uniqueID)
	{
		_uniqueID = uniqueID;
	}

	public void Initialize()
	{
		foreach (IQuestObjective triggerCondition in _triggerConditions)
		{
			triggerCondition.InitializeDialogueTriggers();
			triggerCondition.Initialize();
		}
		FinalUpdate.RegisterEndOfFrameOneShot(RegisterObjectivesUpdated);
	}

	public void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestObjectiveUpdated, CheckObjectivesCompletion);
		foreach (IQuestObjective triggerCondition in _triggerConditions)
		{
			triggerCondition.Uninitialize();
			triggerCondition.UninitializeDialogueTriggers();
		}
	}

	public object Clone()
	{
		return new DialogueBranch(this);
	}

	private void TriggerBranch()
	{
		Uninitialize();
		DialogueGameEvent.DispatchBranchConditionsTriggered(_entryNode);
	}

	private void RegisterObjectivesUpdated()
	{
		GameEventDispatcher.AddListener(GameEventType.QuestObjectiveUpdated, CheckObjectivesCompletion);
		CheckObjectivesCompletion();
	}

	private void CheckObjectivesCompletion(GameEvent gameEvent = null)
	{
		if (AreConditionsCompleted())
		{
			TriggerBranch();
		}
	}

	private bool AreConditionsCompleted()
	{
		foreach (IQuestObjective triggerCondition in _triggerConditions)
		{
			if (!triggerCondition.IsOptional && !triggerCondition.IsCompleted())
			{
				return false;
			}
		}
		return true;
	}
}
[Serializable]
public struct DialogueBranchReference
{
	public DialogueTreeProperties Dialogue;

	public DialogueBranchType Branch;

	[SerializeField]
	private DialogueNodeProperties _reference;

	public readonly bool TryGetReference(out DialogueNodeProperties reference, DialogueTreeProperties dialogueTreeProperties = null)
	{
		reference = null;
		dialogueTreeProperties = (dialogueTreeProperties ? dialogueTreeProperties : Dialogue);
		if (Branch == DialogueBranchType.None)
		{
			return false;
		}
		if (Branch == DialogueBranchType.Reference)
		{
			reference = _reference;
		}
		else if ((bool)dialogueTreeProperties)
		{
			reference = dialogueTreeProperties.ReturnBranchEntryNode(Branch);
		}
		return true;
	}

	public readonly bool ValidateReference(DialogueTreeProperties dialogueProperties = null)
	{
		if (Branch == DialogueBranchType.Reference)
		{
			return _reference;
		}
		if ((bool)dialogueProperties)
		{
			return dialogueProperties.ReturnBranchEntryNode(Branch);
		}
		if ((bool)Dialogue)
		{
			return Dialogue.ReturnBranchEntryNode(Branch);
		}
		return false;
	}
}
public class DialogueContext
{
	public enum ActorType
	{
		None,
		FirstMate,
		SelectedDrifter,
		BuildableDrifter,
		LandmarkDrifter,
		BoatCaptain,
		Doctor,
		Patient,
		QuestGiver,
		RadioMessageSender
	}

	private readonly Dictionary<ActorType, AgentDescriptor> _actors = new Dictionary<ActorType, AgentDescriptor>();

	private Buildable _currentBuildableContext;

	public void Initialize()
	{
		OnFirstMateUpdated();
		GameEventDispatcher.AddListener(GameEventType.GameStart, OnFirstMateUpdated);
		GameEventDispatcher.AddListener(GameEventType.NewGamePanelClosed, OnFirstMateUpdated);
		GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnFirstMateUpdated);
		GameEventDispatcher.AddListener(GameEventType.AgentDeath, OnFirstMateUpdated);
		GameEventDispatcher.AddListener(GameEventType.AgentSelected, OnAgentSelected);
		GameEventDispatcher.AddListener(GameEventType.AgentDeselected, OnAgentDeselected);
		GameEventDispatcher.AddListener(GameEventType.BuildableSelected, OnBuildableSelected);
		GameEventDispatcher.AddListener(GameEventType.BuildableDeselected, OnBuildableDeselected);
		GameEventDispatcher.AddListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
		GameEventDispatcher.AddListener(GameEventType.LandmarkDeselected, OnLandmarkDeselected);
		GameEventDispatcher.AddListener(GameEventType.QuestUpdated, OnQuestStarted);
		GameEventDispatcher.AddListener(GameEventType.QuestCompleted, OnQuestCompleted);
		GameEventDispatcher.AddListener(GameEventType.RadioMessageRead, OnRadioMessageRead);
	}

	public void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnFirstMateUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.NewGamePanelClosed, OnFirstMateUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnFirstMateUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, OnFirstMateUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.AgentSelected, OnAgentSelected);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeselected, OnAgentDeselected);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableSelected, OnBuildableSelected);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableDeselected, OnBuildableDeselected);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkDeselected, OnLandmarkDeselected);
		GameEventDispatcher.RemoveListener(GameEventType.QuestUpdated, OnQuestStarted);
		GameEventDispatcher.RemoveListener(GameEventType.QuestCompleted, OnQuestCompleted);
		GameEventDispatcher.RemoveListener(GameEventType.RadioMessageRead, OnRadioMessageRead);
	}

	public void Clear()
	{
		_actors.Clear();
	}

	public bool TryGetActor(ActorType actorType, out AgentDescriptor actor)
	{
		return _actors.TryGetValue(actorType, out actor);
	}

	public AgentDescriptor GetActor(ActorType actorType)
	{
		if (!_actors.TryGetValue(actorType, out var value))
		{
			SetActor(actorType, null);
		}
		return value;
	}

	public void SetActor(ActorType actorType, AgentDescriptor agent)
	{
		_actors[actorType] = agent;
	}

	private void OnFirstMateUpdated(GameEvent gameEvent = null)
	{
		if (!Community.PlayerCommunity.Agents.IsNullOrEmpty())
		{
			SetActor(ActorType.FirstMate, (Community.PlayerCommunity != null) ? Community.PlayerCommunity.Agents[0].Descriptor : null);
			GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnFirstMateUpdated);
		}
	}

	private void OnAgentSelected(GameEvent gameEvent)
	{
		SetActor(ActorType.SelectedDrifter, (gameEvent is AgentEvent agentEvent) ? agentEvent.AgentDescriptor : null);
	}

	private void OnAgentDeselected(GameEvent gameEvent)
	{
		SetActor(ActorType.SelectedDrifter, null);
	}

	private void OnBuildableSelected(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent)
		{
			_currentBuildableContext = buildableEvent.Buildable;
			if (_currentBuildableContext.TryReturnBuildableExtendable<Boat>(out var buildableExtendable))
			{
				UpdateBoatCaptain(buildableExtendable);
				Boat boat = buildableExtendable;
				boat.BoatUpdatedEvent = (UnityAction<Boat>)Delegate.Remove(boat.BoatUpdatedEvent, new UnityAction<Boat>(UpdateBoatCaptain));
				Boat boat2 = buildableExtendable;
				boat2.BoatUpdatedEvent = (UnityAction<Boat>)Delegate.Combine(boat2.BoatUpdatedEvent, new UnityAction<Boat>(UpdateBoatCaptain));
				return;
			}
			if (_currentBuildableContext.TryReturnBuildableExtendable<Clinic>(out var buildableExtendable2))
			{
				UpdateClinicActors(buildableExtendable2);
				buildableExtendable2.OnUpdated -= UpdateClinicActors;
				buildableExtendable2.OnUpdated += UpdateClinicActors;
				return;
			}
			if (_currentBuildableContext.TryReturnBuildableExtendable<MedPod>(out var buildableExtendable3))
			{
				UpdateMedPodActors(buildableExtendable3);
				buildableExtendable3.OnUpdated -= UpdateMedPodActors;
				buildableExtendable3.OnUpdated += UpdateMedPodActors;
				return;
			}
			if (_currentBuildableContext.TryReturnBuildableExtendable<Producer>(out var buildableExtendable4))
			{
				buildableExtendable4.OnStartProducing.AddListener(UpdateBuildableActor);
				buildableExtendable4.OnStopProducing.AddListener(UpdateBuildableActor);
			}
			UpdateBuildableActor(_currentBuildableContext);
			_currentBuildableContext.OnAssignedProjectUpdatedEvent.AddListener(UpdateBuildableActor);
		}
		else
		{
			SetActor(ActorType.BuildableDrifter, null);
		}
	}

	private void UpdateBuildableActor(Buildable buildable)
	{
		using ListPool<Agent>.List list = ListPool<Agent>.Get(8);
		if (buildable.AssignedProject != null)
		{
			buildable.AssignedProject.ReturnAssignedAgents(list);
		}
		else
		{
			buildable.ReturnAgentsOnBuildable(list);
		}
		SetActor(ActorType.BuildableDrifter, (list.Count > 0) ? list[0].Descriptor : null);
	}

	private void UpdateBoatCaptain(Boat boat)
	{
		SetActor(ActorType.BoatCaptain, (boat.Captain != null) ? boat.Captain.Descriptor : null);
	}

	private void UpdateClinicActors(Clinic clinic)
	{
		SetActor(ActorType.Doctor, (clinic.Doctor != null) ? clinic.Doctor.Descriptor : null);
		SetActor(ActorType.Patient, (clinic.Patient != null) ? clinic.Patient.Descriptor : null);
	}

	private void UpdateMedPodActors(MedPod medPod)
	{
		SetActor(ActorType.Doctor, medPod.GetDoctorDescriptor());
		SetActor(ActorType.Patient, medPod.GetPatientDescriptor());
	}

	private void OnBuildableDeselected(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent && buildableEvent.Buildable != null)
		{
			UnregisterFromBuildableEvents(buildableEvent.Buildable);
		}
		else
		{
			UnregisterFromBuildableEvents(_currentBuildableContext);
		}
		_currentBuildableContext = null;
		SetActor(ActorType.BuildableDrifter, null);
		SetActor(ActorType.BoatCaptain, null);
		SetActor(ActorType.Doctor, null);
		SetActor(ActorType.Patient, null);
	}

	private void UnregisterFromBuildableEvents(Buildable buildable)
	{
		Clinic buildableExtendable2;
		MedPod buildableExtendable3;
		Producer buildableExtendable4;
		if (buildable.TryReturnBuildableExtendable<Boat>(out var buildableExtendable))
		{
			Boat boat = buildableExtendable;
			boat.BoatUpdatedEvent = (UnityAction<Boat>)Delegate.Remove(boat.BoatUpdatedEvent, new UnityAction<Boat>(UpdateBoatCaptain));
		}
		else if (buildable.TryReturnBuildableExtendable<Clinic>(out buildableExtendable2))
		{
			buildableExtendable2.OnUpdated -= UpdateClinicActors;
		}
		else if (buildable.TryReturnBuildableExtendable<MedPod>(out buildableExtendable3))
		{
			buildableExtendable3.OnUpdated -= UpdateMedPodActors;
		}
		else if (buildable.TryReturnBuildableExtendable<Producer>(out buildableExtendable4))
		{
			buildableExtendable4.OnStartProducing.RemoveListener(UpdateBuildableActor);
			buildableExtendable4.OnStopProducing.RemoveListener(UpdateBuildableActor);
		}
		buildable.OnAssignedProjectUpdatedEvent.RemoveListener(UpdateBuildableActor);
	}

	private void OnLandmarkSelected(GameEvent gameEvent)
	{
		Agent agent = null;
		if (gameEvent is LandmarkNotificationEvent { LandmarkBehaviour: ActionsBehaviour landmarkBehaviour } && landmarkBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false))
		{
			action.TryGetFirstRescuableAgent(out agent);
		}
		SetActor(ActorType.LandmarkDrifter, (agent != null) ? agent.Descriptor : null);
	}

	private void OnLandmarkDeselected(GameEvent gameEvent)
	{
		SetActor(ActorType.LandmarkDrifter, null);
	}

	private void OnQuestStarted(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent)
		{
			SetActor(ActorType.QuestGiver, questEvent.Quest.QuestGiver);
		}
	}

	private void OnQuestCompleted(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent && questEvent.Quest.QuestGiver == GetActor(ActorType.QuestGiver))
		{
			SetActor(ActorType.QuestGiver, null);
		}
	}

	private void OnRadioMessageRead(GameEvent gameEvent)
	{
		if (gameEvent is RadioMessageEvent { Message: not null } radioMessageEvent)
		{
			SetActor(ActorType.RadioMessageSender, radioMessageEvent.Message.Sender);
		}
	}
}
