[CreateAssetMenu(menuName = "Flotsam/Narrative/Dialogue Tree Properties", fileName = "New Dialogue", order = 0)]
public class DialogueTreeProperties : PersistentProperties, IDialogueTreeNodeViewable
{
	[NamedArrayElement("_name", "_type")]
	[SerializeField]
	private List<DialogueBranch> _entryBranches = new List<DialogueBranch>();

	[SerializeField]
	private DialogueContext.ActorType _speaker = DialogueContext.ActorType.FirstMate;

	[SerializeField]
	[HideInInspector]
	private List<DialogueNodeProperties> _nodes = new List<DialogueNodeProperties>();

	public IReadOnlyList<DialogueNodeProperties> Nodes => _nodes;

	UnityEngine.Object IDialogueTreeNodeViewable.SerializeTarget => this;

	public IReadOnlyList<DialogueBranch> DialogueBranches => _entryBranches;

	public IReadOnlyList<DialogueNodeProperties> Branches
	{
		get
		{
			List<DialogueNodeProperties> list = new List<DialogueNodeProperties>(_entryBranches.Count);
			foreach (DialogueBranch entryBranch in _entryBranches)
			{
				if (entryBranch.IsDefaultBranch)
				{
					list.Clear();
					list.Add(entryBranch.EntryNode);
					break;
				}
				if (entryBranch.TriggerConditions.IsNullOrEmpty() && entryBranch.EntryNode != null)
				{
					list.Add(entryBranch.EntryNode);
				}
			}
			return list;
		}
	}

	public IReadOnlyList<DialogueBranch> EntryBranches => _entryBranches;

	public DialogueContext.ActorType Speaker => _speaker;

	string IDialogueTreeNodeViewable.Name => base.name;

	string IDialogueTreeNodeViewable.Guid => GetInstanceID().ToString();

	Vector2 IDialogueTreeNodeViewable.Position => Vector2.zero;

	public IReadOnlyList<IDialogueCondition> Conditions => null;

	public DialogueProgressConditions ProgressDialogueConditions => null;

	public override Types Type => Types.DialogueProperties;

	public void StartDialogue(DialogueNodeProperties specificBranchEntryNode = null, float delay = 0f, bool isRepeat = false, bool isRadioMessage = false)
	{
		DialogueGameEvent.DispatchDialogueStartRequest(this, specificBranchEntryNode, delay, isRepeat, isRadioMessage);
	}

	public bool HasDialogueBranchType(DialogueBranchType type)
	{
		return _entryBranches.Find((DialogueBranch branch) => branch.Type == type && branch.EntryNode != null) != null;
	}

	public DialogueNodeProperties ReturnBranchEntryNode(DialogueBranchType branchType)
	{
		if (branchType == DialogueBranchType.None || branchType == DialogueBranchType.Reference)
		{
			return null;
		}
		foreach (DialogueBranch entryBranch in _entryBranches)
		{
			if (entryBranch.Type == branchType)
			{
				return entryBranch.EntryNode;
			}
		}
		return null;
	}

	public DialogueBranch ReturnBranch(ushort id)
	{
		if (_entryBranches.IsNullOrEmpty() || id <= 0)
		{
			return null;
		}
		foreach (DialogueBranch entryBranch in _entryBranches)
		{
			if (entryBranch.UniqueID == id)
			{
				return entryBranch;
			}
		}
		return null;
	}

	public DialogueBranch ReturnBranch(DialogueNodeProperties entryNode)
	{
		if (_entryBranches.IsNullOrEmpty())
		{
			return null;
		}
		foreach (DialogueBranch entryBranch in _entryBranches)
		{
			if (entryBranch.EntryNode == entryNode)
			{
				return entryBranch;
			}
		}
		return null;
	}
}
public enum DialogueTriggerType
{
	None = 0,
	OnObjectiveActivated = 1,
	OnObjectiveShown = 2,
	OnObjectiveCompleted = 3,
	OnObjectivesGroupCompleted = 11,
	OnObjectiveTimedOut = 4,
	OnAgentSelected = 5,
	OnAgentFromPlayerCommunitySelected = 8,
	OnOutsiderAgentSelected = 9,
	OnLandmarkSelected = 6,
	OnLandmarkRegionEntered = 10,
	OnBuildableSelected = 7,
	OnFlotsamItemSalvaged = 12,
	OnSpawnerOutOfRange = 13
}
[Serializable]
public class DialogueTrigger : IDialogueInteractable
{
	[Serializable]
	private class ResponseHandler
	{
		[Serializable]
		public struct Path
		{
			[GeneratedEnum]
			public DialogueResponseType[] Array;
		}

		[SerializeField]
		[Tooltip("Use a response path instead of a single response to trigger this handler?")]
		public bool UseResponsePath;

		[ConditionalHide("UseResponsePath", true, true)]
		[GeneratedEnum]
		public DialogueResponseType Response;

		[ConditionalHide("UseResponsePath", true, false)]
		[Wrapper("Array")]
		public Path ResponsePath;

		[SerializeReference]
		[InstantiateSerializeReference]
		public IDialogueEvent Event;

		public bool HandlesResponse(DialogueResponseType response, List<DialogueResponseType> responsePath)
		{
			if (UseResponsePath)
			{
				if (responsePath.Count != ResponsePath.Array.Length)
				{
					return false;
				}
				for (int i = 0; i < responsePath.Count; i++)
				{
					if (responsePath[i] != ResponsePath.Array[i])
					{
						return false;
					}
				}
				return true;
			}
			return response == Response;
		}
	}

	[SerializeField]
	[FormerlySerializedAs("Trigger")]
	private DialogueTriggerType _trigger;

	[SerializeField]
	[FormerlySerializedAs("Dialogue")]
	private DialogueBranchReference _dialogue;

	[SerializeField]
	private bool _triggerOnlyOnce = true;

	[SerializeField]
	[Tooltip("Should this dialogue be queued if there is an active dialogue?")]
	private bool _enqueue = true;

	[SerializeField]
	private List<ResponseHandler> _responseHandlers = new List<ResponseHandler>();

	[SerializeField]
	[Min(0f)]
	private float _delay;

	[SerializeField]
	[HideInInspector]
	private ushort _uniqueID;

	private IDialogueContextProvider _context;

	private Action<DialogueResponseType, Dialogue> _responseCallback;

	private ListPool<DialogueResponseType>.List _responsePath;

	public DialogueTriggerType Type => _trigger;

	public DialogueTreeProperties DialogueProperties { get; private set; }

	public bool TriggerOnlyOnce => _triggerOnlyOnce;

	public bool EndOfDialogueReceived { get; private set; }

	public ushort UniqueID => _uniqueID;

	public bool Queue => _enqueue;

	public float Delay => _delay;

	public void Trigger()
	{
		_responsePath = ListPool<DialogueResponseType>.Get();
		if (SetDialogueProperties(_dialogue.Dialogue))
		{
			DialogueGameEvent.DispatchDialogueStartRequest(this);
		}
		else
		{
			OnDialogueResponse(DialogueResponseType.EndOfDialogue, null);
		}
	}

	public void Trigger(IDialogueContextProvider context, Action<DialogueResponseType, Dialogue> responseCallback = null)
	{
		_context = context;
		Trigger(responseCallback);
	}

	private void Trigger(Action<DialogueResponseType, Dialogue> responseCallback = null)
	{
		_responseCallback = responseCallback;
		_responsePath = ListPool<DialogueResponseType>.Get();
		if (_dialogue.Branch != DialogueBranchType.None && SetDialogueProperties(_dialogue.Dialogue))
		{
			DialogueGameEvent.DispatchDialogueStartRequest(this);
		}
		else
		{
			OnDialogueResponse(DialogueResponseType.EndOfDialogue, null);
		}
	}

	public IEnumerator TriggerRoutine(float fallbackWaitTime = 0f)
	{
		if (ValidateDialogue())
		{
			Trigger();
			while (!EndOfDialogueReceived)
			{
				yield return null;
			}
		}
		else if (0f < fallbackWaitTime)
		{
			yield return new WaitForSeconds(fallbackWaitTime);
		}
	}

	private bool SetDialogueProperties(DialogueTreeProperties dialogueProperties)
	{
		if ((bool)dialogueProperties)
		{
			DialogueProperties = dialogueProperties;
			return true;
		}
		return false;
	}

	public bool ValidateDialogue(DialogueTreeProperties dialogueProperties = null)
	{
		return _dialogue.ValidateReference(dialogueProperties);
	}

	public void AssignUniqueID(ushort id)
	{
		_uniqueID = id;
	}

	public bool TryGetEntryPoint(out DialogueNodeProperties entryPoint)
	{
		return _dialogue.TryGetReference(out entryPoint, DialogueProperties);
	}

	public bool TryGetMainSpeaker(out AgentDescriptor mainSpeaker)
	{
		if (_context != null)
		{
			return _context.TryGetMainSpeaker(out mainSpeaker);
		}
		mainSpeaker = null;
		return false;
	}

	public bool TryGetActorDescriptor(DialogueContext.ActorType actorType, out AgentDescriptor actorDescriptor)
	{
		if (_context != null)
		{
			return _context.TryGetActorDescriptor(actorType, out actorDescriptor);
		}
		return StoryManager.DialogueContext.TryGetActor(actorType, out actorDescriptor);
	}

	public bool TryGetLandmark(out LandmarkSpawner landmarkSpawner)
	{
		landmarkSpawner = null;
		if (_context != null)
		{
			return _context.TryGetLandmark(out landmarkSpawner);
		}
		return false;
	}

	public void OnDialogueResponse(DialogueResponseType response, Dialogue dialogue)
	{
		if (dialogue != null && dialogue.IsInRepeat)
		{
			return;
		}
		_responseCallback?.Invoke(response, dialogue);
		if (response == DialogueResponseType.None)
		{
			return;
		}
		if (_responsePath == null)
		{
			_responsePath = ListPool<DialogueResponseType>.Get();
		}
		_responsePath.Add(response);
		foreach (ResponseHandler responseHandler in _responseHandlers)
		{
			if (responseHandler.HandlesResponse(response, _responsePath))
			{
				responseHandler.Event.TriggerEvent(dialogue);
			}
		}
		if (response == DialogueResponseType.EndOfDialogue)
		{
			EndOfDialogueReceived = true;
			_responseCallback = null;
			_responsePath.Dispose();
			_responsePath = null;
		}
	}
}
[Serializable]
public class DialogueTriggers
{
	[Serializable]
	public class PersistentData
	{
		private readonly List<ushort> _triggeredTriggersIDs = new List<ushort>();

		public PersistentData(DialogueTriggers triggers)
		{
			foreach (DialogueTrigger triggeredDialogue in triggers._triggeredDialogues)
			{
				if (triggeredDialogue.TriggerOnlyOnce)
				{
					_triggeredTriggersIDs.Add(triggeredDialogue.UniqueID);
				}
			}
		}

		public void Restore(DialogueTriggers triggers)
		{
			triggers._triggeredDialogues.Clear();
			foreach (ushort id in _triggeredTriggersIDs)
			{
				DialogueTrigger dialogueTrigger = triggers._triggers.Find((DialogueTrigger trigger) => trigger.UniqueID == id);
				if (dialogueTrigger != null)
				{
					triggers._triggeredDialogues.Add(dialogueTrigger);
				}
			}
		}
	}

	[SerializeField]
	[NamedArrayElement(new string[] { "_trigger" })]
	private List<DialogueTrigger> _triggers = new List<DialogueTrigger>();

	private WeakReference<IDialogueContextProvider> _contextProvider;

	private readonly HashSet<DialogueTrigger> _triggeredDialogues = new HashSet<DialogueTrigger>();

	private bool _isListeningToDialogueEndEvent;

	public DialogueTriggers()
	{
	}

	public DialogueTriggers(DialogueTriggers other)
	{
		_triggers = new List<DialogueTrigger>(other._triggers);
		_contextProvider = other._contextProvider;
		_triggeredDialogues = new HashSet<DialogueTrigger>(other._triggeredDialogues);
	}

	~DialogueTriggers()
	{
		Uninitialize();
	}

	public void OnValidate()
	{
		if (_triggers.IsNullOrEmpty())
		{
			return;
		}
		HashSet<ushort> hashSet = CollectionPool<HashSet<ushort>, ushort>.Get();
		foreach (DialogueTrigger trigger in _triggers)
		{
			if (trigger.UniqueID != 0)
			{
				if (!hashSet.Contains(trigger.UniqueID))
				{
					hashSet.Add(trigger.UniqueID);
				}
				else
				{
					trigger.AssignUniqueID(0);
				}
			}
		}
		foreach (DialogueTrigger trigger2 in _triggers)
		{
			if (trigger2.UniqueID == 0)
			{
				ushort num;
				do
				{
					num = (ushort)UnityEngine.Random.Range(1, 65535);
				}
				while (hashSet.Contains(num));
				trigger2.AssignUniqueID(num);
			}
		}
		CollectionPool<HashSet<ushort>, ushort>.Release(hashSet);
	}

	public void Initialize(IDialogueContextProvider contextProvider)
	{
		_contextProvider = new WeakReference<IDialogueContextProvider>(contextProvider);
		if (contextProvider.SupportedTriggers.IsNullOrEmpty())
		{
			return;
		}
		foreach (DialogueTriggerType supportedTrigger in contextProvider.SupportedTriggers)
		{
			if (HasDialogueAssigned(supportedTrigger))
			{
				AttachTriggerEvent(supportedTrigger);
			}
		}
	}

	public void Uninitialize()
	{
		_contextProvider = null;
		if (_isListeningToDialogueEndEvent)
		{
			GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnAgentSelected);
		}
		_isListeningToDialogueEndEvent = false;
		GameEventDispatcher.RemoveListener(GameEventType.AgentSelected, OnAgentSelected);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
		GameEventDispatcher.RemoveListener(GameEventType.BuildableSelected, OnBuildableSelected);
		GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnLandmarkRegionEntered);
		GameEventDispatcher.RemoveListener(GameEventType.FlotsamItemSalvage, OnFlotsamItemSalvaged);
	}

	public bool TriggerDialogue(DialogueTriggerType trigger, Action<DialogueResponseType, Dialogue> responseCallback = null)
	{
		if (!TryGetDialogueContextOrUninitialize(out var contextProvider))
		{
			return false;
		}
		foreach (DialogueTrigger trigger2 in _triggers)
		{
			if (trigger2.Type != trigger)
			{
				continue;
			}
			if (!_triggeredDialogues.Contains(trigger2))
			{
				if (!_isListeningToDialogueEndEvent)
				{
					GameEventDispatcher.AddListener(GameEventType.DialogueEnded, OnDialogueEnded);
					_isListeningToDialogueEndEvent = true;
				}
				trigger2.Trigger(contextProvider, responseCallback);
				_triggeredDialogues.Add(trigger2);
			}
			return true;
		}
		return false;
	}

	public bool HasDialogueAssigned(DialogueTriggerType trigger)
	{
		IDialogueContextProvider target;
		DialogueTreeProperties dialogueProperties = (_contextProvider.TryGetTarget(out target) ? target.DialogueProperties : null);
		foreach (DialogueTrigger trigger2 in _triggers)
		{
			if (trigger2.Type == trigger)
			{
				return trigger2.ValidateDialogue(dialogueProperties);
			}
		}
		return false;
	}

	public bool TryFindTrigger(ushort uniqueID, out DialogueTrigger dialogueTrigger)
	{
		dialogueTrigger = _triggers.Find((DialogueTrigger trigger) => trigger.UniqueID == uniqueID);
		return dialogueTrigger != null;
	}

	private bool TryGetDialogueContextOrUninitialize(out IDialogueContextProvider contextProvider)
	{
		contextProvider = null;
		if (_contextProvider == null)
		{
			UnityEngine.Debug.LogWarning("Trying to trigger a dialogue while DialogueTriggers is uninitialized. If this is caused by the tutorial this warning can be ignored.");
			return false;
		}
		if (_contextProvider.TryGetTarget(out contextProvider))
		{
			return true;
		}
		UnityEngine.Debug.LogException(new ArgumentException("Context provider for dialogue triggers is null! Uninitializing DialogueTriggers to avoid further errors."));
		Uninitialize();
		contextProvider = null;
		return false;
	}

	private void AttachTriggerEvent(DialogueTriggerType trigger)
	{
		switch (trigger)
		{
		case DialogueTriggerType.OnAgentSelected:
		case DialogueTriggerType.OnAgentFromPlayerCommunitySelected:
		case DialogueTriggerType.OnOutsiderAgentSelected:
			GameEventDispatcher.AddListener(GameEventType.AgentSelected, OnAgentSelected);
			break;
		case DialogueTriggerType.OnLandmarkSelected:
			GameEventDispatcher.AddListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
			break;
		case DialogueTriggerType.OnBuildableSelected:
			GameEventDispatcher.AddListener(GameEventType.BuildableSelected, OnBuildableSelected);
			break;
		case DialogueTriggerType.OnLandmarkRegionEntered:
			GameEventDispatcher.AddListener(GameEventType.RegionEntered, OnLandmarkRegionEntered);
			break;
		case DialogueTriggerType.OnFlotsamItemSalvaged:
			GameEventDispatcher.AddListener(GameEventType.FlotsamItemSalvage, OnFlotsamItemSalvaged);
			break;
		case DialogueTriggerType.OnObjectivesGroupCompleted:
			break;
		}
	}

	public bool HasActiveDialogue()
	{
		if (GameManager.UIManager.TryGetPanel(PanelID.DialoguePanel, out var panel) && panel.isActiveAndEnabled && panel is DialoguePanel dialoguePanel)
		{
			foreach (DialogueTrigger trigger in _triggers)
			{
				if (dialoguePanel.IsInteractableActiveOrQueued(trigger))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void OnDialogueEnded(GameEvent gameEvent)
	{
		if (!(gameEvent is DialogueGameEvent dialogueGameEvent) || dialogueGameEvent.DialogueProperties == null)
		{
			return;
		}
		DialogueTrigger dialogueTrigger = null;
		bool flag = false;
		foreach (DialogueTrigger triggeredDialogue in _triggeredDialogues)
		{
			if (triggeredDialogue.DialogueProperties == dialogueGameEvent.DialogueProperties)
			{
				if (!triggeredDialogue.TriggerOnlyOnce)
				{
					dialogueTrigger = triggeredDialogue;
				}
				break;
			}
			if (!triggeredDialogue.TriggerOnlyOnce)
			{
				flag = false;
			}
		}
		if (dialogueTrigger != null)
		{
			_triggeredDialogues.Remove(dialogueTrigger);
		}
		if (flag)
		{
			GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnDialogueEnded);
			_isListeningToDialogueEndEvent = false;
		}
	}

	private void OnAgentSelected(GameEvent gameEvent)
	{
		VerifyAgentSelectedContext(gameEvent, DialogueTriggerType.OnAgentSelected);
	}

	private void VerifyAgentSelectedContext(GameEvent gameEvent, DialogueTriggerType triggerType)
	{
		if (TryGetDialogueContextOrUninitialize(out var contextProvider) && gameEvent is AgentEvent agentEvent && contextProvider.IsObjectInContext(agentEvent.Agent, triggerType))
		{
			TriggerDialogue(triggerType);
		}
	}

	private void OnLandmarkSelected(GameEvent gameEvent)
	{
		if (TryGetDialogueContextOrUninitialize(out var contextProvider) && gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && contextProvider.IsObjectInContext(landmarkNotificationEvent.LandmarkBehaviour, DialogueTriggerType.OnLandmarkSelected))
		{
			TriggerDialogue(DialogueTriggerType.OnLandmarkSelected);
		}
	}

	private void OnBuildableSelected(GameEvent gameEvent)
	{
		if (TryGetDialogueContextOrUninitialize(out var contextProvider) && gameEvent is BuildableEvent buildableEvent && contextProvider.IsObjectInContext(buildableEvent.Buildable, DialogueTriggerType.OnBuildableSelected))
		{
			TriggerDialogue(DialogueTriggerType.OnBuildableSelected);
		}
	}

	private void OnLandmarkRegionEntered(GameEvent gameEvent)
	{
		if (!TryGetDialogueContextOrUninitialize(out var contextProvider))
		{
			return;
		}
		IReadOnlyList<LandmarkSpawner> landmarks = GameManager.WorldManager.CurrentRegion.Landmarks;
		if (landmarks.IsNullOrEmpty())
		{
			return;
		}
		foreach (LandmarkSpawner item in landmarks)
		{
			if (contextProvider.IsObjectInContext(item.LandmarkBehaviour, DialogueTriggerType.OnLandmarkRegionEntered))
			{
				TriggerDialogue(DialogueTriggerType.OnLandmarkRegionEntered);
				break;
			}
		}
	}

	private void OnFlotsamItemSalvaged(GameEvent gameEvent)
	{
		if (TryGetDialogueContextOrUninitialize(out var contextProvider) && gameEvent is ItemEvent itemEvent && contextProvider.IsObjectInContext(itemEvent.ItemProperties, DialogueTriggerType.OnFlotsamItemSalvaged))
		{
			TriggerDialogue(DialogueTriggerType.OnFlotsamItemSalvaged);
		}
	}
}
