public interface IDialogueNode
{
	System.Action OnProgressConditionsMet { get; set; }

	DialogueNodeProperties Properties { get; }

	IReadOnlyList<DialogueNodeProperties> Branches { get; }

	DialoguePanelOptions DialoguePanelOptions { get; }

	void EnterNode(DialoguePanel dialoguePanel, Dialogue dialogue);

	void ExitNode(DialoguePanel dialoguePanel, Dialogue dialogue);

	bool CanExitNode(bool isInRepeat);

	bool AreProgressConditionsMet();
}
public abstract class DialogueNode<PropertiesType> : IDialogueNode where PropertiesType : DialogueNodeProperties
{
	protected readonly PropertiesType _properties;

	private readonly DialogueProgressConditions _progressDialogueConditions;

	private DialoguePanel _dialoguePanel;

	public System.Action OnProgressConditionsMet { get; set; }

	public DialogueNodeProperties Properties => _properties;

	public virtual IReadOnlyList<DialogueNodeProperties> Branches => _properties.Branches;

	public DialoguePanelOptions DialoguePanelOptions => _properties.DialoguePanelOptions;

	protected DialogueNode(PropertiesType properties)
	{
		_properties = properties;
		_progressDialogueConditions = properties.ProgressDialogueConditions.Clone() as DialogueProgressConditions;
	}

	public virtual void EnterNode(DialoguePanel dialoguePanel, Dialogue dialogue)
	{
		_dialoguePanel = dialoguePanel;
		_progressDialogueConditions.OnNodeEnter();
		DialogueProgressConditions progressDialogueConditions = _progressDialogueConditions;
		progressDialogueConditions.OnConditionsMet = (System.Action)Delegate.Combine(progressDialogueConditions.OnConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
		if (_progressDialogueConditions.AutoProgressOnConditionsMet)
		{
			DialogueProgressConditions progressDialogueConditions2 = _progressDialogueConditions;
			progressDialogueConditions2.OnConditionsMet = (System.Action)Delegate.Combine(progressDialogueConditions2.OnConditionsMet, new System.Action(ProgressDialogue));
		}
		_properties.TriggerStartDialogueEvents(dialogue);
	}

	public virtual void ExitNode(DialoguePanel dialoguePanel, Dialogue dialogue)
	{
		_progressDialogueConditions.OnNodeExit();
		DialogueProgressConditions progressDialogueConditions = _progressDialogueConditions;
		progressDialogueConditions.OnConditionsMet = (System.Action)Delegate.Remove(progressDialogueConditions.OnConditionsMet, new System.Action(TriggerOnProgressConditionsMet));
		DialogueProgressConditions progressDialogueConditions2 = _progressDialogueConditions;
		progressDialogueConditions2.OnConditionsMet = (System.Action)Delegate.Remove(progressDialogueConditions2.OnConditionsMet, new System.Action(ProgressDialogue));
		_properties.TriggerEndDialogueEvents(dialogue);
		_dialoguePanel = null;
	}

	public virtual bool CanExitNode(bool isInRepeat)
	{
		if (!isInRepeat && !_progressDialogueConditions.ManualInputIgnoresConditions)
		{
			return AreProgressConditionsMet();
		}
		return true;
	}

	public bool AreProgressConditionsMet()
	{
		if (_progressDialogueConditions != null)
		{
			return _progressDialogueConditions.AreConditionsMet();
		}
		return true;
	}

	protected void ProgressDialogue()
	{
		_dialoguePanel.ProgressDialogue();
	}

	private void TriggerOnProgressConditionsMet()
	{
		if (OnProgressConditionsMet != null)
		{
			OnProgressConditionsMet();
		}
	}
}
public class DialogueNodeDialogPopUp : DialogueNode<DialogueNodeDialogPopUpProperties>
{
	public DialogueNodeDialogPopUp(DialogueNodeDialogPopUpProperties properties)
		: base(properties)
	{
	}

	public override void EnterNode(DialoguePanel dialoguePanel, Dialogue dialogue)
	{
		base.EnterNode(dialoguePanel, dialogue);
		if (_properties.HideDialoguePanel && dialoguePanel.IsOpen())
		{
			dialoguePanel.Close();
		}
		if (_properties.IsInputDialog ? PopUpDialog.Instance.TryPopUpInput(_properties.PopUpProperties) : PopUpDialog.Instance.TryOpenPopUpDialog(_properties.PopUpProperties))
		{
			PopUpDialog instance = PopUpDialog.Instance;
			instance.OnPopUpClosed = (System.Action)Delegate.Combine(instance.OnPopUpClosed, new System.Action(OnPopUpClosed));
			return;
		}
		throw new NotImplementedException($"Failed to open popup {_properties.PopUpProperties} for some reason :(");
	}

	private void OnPopUpClosed()
	{
		PopUpDialog instance = PopUpDialog.Instance;
		instance.OnPopUpClosed = (System.Action)Delegate.Remove(instance.OnPopUpClosed, new System.Action(OnPopUpClosed));
		ProgressDialogue();
	}
}
