	private float _clampedCustomRadius;

	protected LandmarkSpawner _targetLandmark;

	public bool IsBearingAllowed { get; private set; }

	public MoveTownToLandmarkObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkSelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkRegionEntered);
	}

	public MoveTownToLandmarkObjective(MoveTownToLandmarkObjective other)
		: base(other)
	{
		_mode = other._mode;
		_specificLandmark = other._specificLandmark;
		_landmarkVariable = other._landmarkVariable;
		_landmarkPickerSettings = other._landmarkPickerSettings;
		_landmarkActionsThatCompleteObjective = new List<LandmarkAction>(other._landmarkActionsThatCompleteObjective);
		_bearing = new SpawnerObjectiveBearing(other._bearing);
		_logWarningIfLandmarkNotFound = other._logWarningIfLandmarkNotFound;
		_radiusMode = other._radiusMode;
		_clampedCustomRadius = other._clampedCustomRadius;
		_targetLandmark = other._targetLandmark;
	}

	public override void Initialize()
	{
		_targetLandmark = null;
		base.Initialize();
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		if (active)
		{
			if (TryFindTargetLandmark(out var targetLandmark))
			{
				SetTargetLandmark(targetLandmark);
			}
			else
			{
				GameEventDispatcher.AddListener(GameEventType.MapActivated, OnMapActivated);
			}
		}
		else
		{
			_bearing.SetActive(active: false);
			GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		}
	}

	private bool TryFindTargetLandmark(out LandmarkSpawner targetLandmark)
	{
		if (_targetLandmark != null)
		{
			targetLandmark = _targetLandmark;
			return true;
		}
		if (_mode == Mode.LandmarkVariable)
		{
			targetLandmark = base.Quest.GetVariableValue<LandmarkSpawner>(this, _landmarkVariable);
			return targetLandmark != null;
		}
		return TryFindTargetLandmark(_specificLandmark.Value, out targetLandmark);
	}

	private bool TryFindTargetLandmark(ILandmarkBehaviourProvider landmarkBehaviourProvider, out LandmarkSpawner targetLandmark)
	{
		targetLandmark = GameManager.WorldManager.World.GetNearestLandmarkOfType(landmarkBehaviourProvider);
		if (targetLandmark != null || _landmarkPickerSettings.Spawn(out targetLandmark, landmarkBehaviourProvider))
		{
			return true;
		}
		if (_logWarningIfLandmarkNotFound)
		{
			UnityEngine.Debug.LogWarning("No valid landmark \"" + ((landmarkBehaviourProvider != null) ? landmarkBehaviourProvider.Name : "NULL") + "\" found for objective MoveTownToLandmarkObjective! Will try again next time WorldMap is opened");
		}
		return false;
	}

	private void SetTargetLandmark(LandmarkSpawner targetLandmark)
	{
		if (_targetLandmark != targetLandmark)
		{
			if (_targetLandmark != null && (bool)_targetLandmark.LandmarkBehaviour)
			{
				_targetLandmark.LandmarkBehaviour.UpdatedEvent.RemoveListener(OnLandmarkActionUpdated);
			}
			_targetLandmark = targetLandmark;
			if ((bool)_targetLandmark.LandmarkBehaviour && !_landmarkActionsThatCompleteObjective.IsNullOrEmpty())
			{
				_targetLandmark.LandmarkBehaviour.UpdatedEvent.AddListener(OnLandmarkActionUpdated);
			}
			AddBlockingSpawner(targetLandmark);
			_bearing.Initialize(this, _targetLandmark);
			_bearing.SetActive(active: true);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		if (_targetLandmark != null && _targetLandmark.LandmarkBehaviour != null)
		{
			_targetLandmark.LandmarkBehaviour.UpdatedEvent.RemoveListener(OnLandmarkActionUpdated);
		}
		_bearing.Uninitialize();
		base.Uninitialize();
	}

	protected override bool IsArrived()
	{
		LandmarkSpawner landmarkSpawner = null;
		switch (_mode)
		{
		case Mode.LandmarkProvider:
			landmarkSpawner = ((_targetLandmark != null) ? _targetLandmark : GameManager.WorldManager.World.GetNearestLandmarkOfType(_specificLandmark.Value));
			break;
		case Mode.LandmarkVariable:
			landmarkSpawner = ((_targetLandmark != null) ? _targetLandmark : base.Quest.GetVariableValue<LandmarkSpawner>(this, _landmarkVariable));
			break;
		}
		if (landmarkSpawner == null)
		{
			return false;
		}
		Vector3 position = GameManager.WorldMapManager.WorldMap.Townheart.Position;
		return (landmarkSpawner.WorldPosition - position).sqrMagnitude <= GetSqrdRadius();
	}

	private void OnMapActivated(GameEvent gameEvent)
	{
		if (TryFindTargetLandmark(out var targetLandmark))
		{
			SetTargetLandmark(targetLandmark);
			GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		}
	}

	private void OnLandmarkActionUpdated(LandmarkBehaviour landmarkBehaviour, object action)
	{
		if (action is LandmarkAction landmarkAction && ShouldActionCompleteObjective(landmarkAction) && landmarkAction.IsCompleted)
		{
			SetCompleted(completed: true);
			Uninitialize();
		}
	}

	private bool ShouldActionCompleteObjective(LandmarkAction landmarkAction)
	{
		Type actionType = landmarkAction.GetType();
		return _landmarkActionsThatCompleteObjective.Find((LandmarkAction action) => action.GetType() == actionType) != null;
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Move To Landmark \"" + GetName() + "\"";
	}

	public override string GetParameterValue(string param)
	{
		if (param == "LANDMARK")
		{
			return GetName();
		}
		return base.GetParameterValue(param);
	}

	private string GetName()
	{
		if (_targetLandmark != null)
		{
			return _targetLandmark.Name;
		}
		if (_specificLandmark.Value != null)
		{
			return _specificLandmark.Value.Name;
		}
		return "Any";
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		if (dialogueTriggerType == DialogueTriggerType.OnLandmarkSelected || dialogueTriggerType == DialogueTriggerType.OnLandmarkRegionEntered)
		{
			return target is LandmarkBehaviour landmarkBehaviour && IsSpawnerInContext(landmarkBehaviour);
		}
		return false;
	}

	private bool IsSpawnerInContext(LandmarkBehaviour landmarkBehaviour)
	{
		if (_mode == Mode.LandmarkProvider)
		{
			return _specificLandmark.Value == null || _specificLandmark.Value.ReturnIsLandmarkBehaviour(landmarkBehaviour);
		}
		return _targetLandmark != null && landmarkBehaviour == _targetLandmark.LandmarkBehaviour;
	}

	public override object Clone()
	{
		return new MoveTownToLandmarkObjective(this);
	}

	private float GetSqrdRadius()
	{
		GameplaySettings gameplaySettings = GameSettings.Instance.GameplaySettings;
		float num = _radiusMode switch
		{
			RadiusMode.BoatRadius => gameplaySettings.InteractionRadius, 
			RadiusMode.ClampedCustomRadius => Mathf.Clamp(_clampedCustomRadius, gameplaySettings.SwimmingRadius, gameplaySettings.InteractionRadius), 
			_ => gameplaySettings.SwimmingRadius, 
		};
		return num * num;
	}
}
[Serializable]
public class MoveTownToPOIObjective : MoveTownObjective, ILocalizationParamsManager
{
	public enum Mode
	{
		POIProperties,
		POIVariable
	}

	[Header("Move Town To POI")]
	[SerializeField]
	private Mode _mode;

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, true)]
	private PointOfInterestProperties _poiProperties;

	[SerializeField]
	[ConditionalEnumHide("_mode", 1, true)]
	[QuestVariable(QuestVariableType.PointOfInterest)]
	private int _poiVariable;

	[SerializeField]
	private SpawnerObjectiveBearing _bearing;

	[SerializeField]
	private bool _logWarningIfPOINotFound = true;

	protected PointOfInterestSpawner _targetPOI;

	public bool IsBearingAllowed { get; private set; }

	public MoveTownToPOIObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnFlotsamItemSalvaged);
	}

	public MoveTownToPOIObjective(MoveTownToPOIObjective other)
		: base(other)
	{
		_mode = other._mode;
		_poiProperties = other._poiProperties;
		_poiVariable = other._poiVariable;
		_bearing = new SpawnerObjectiveBearing(other._bearing);
		_logWarningIfPOINotFound = other._logWarningIfPOINotFound;
		_targetPOI = other._targetPOI;
	}

	public override void Initialize()
	{
		_targetPOI = null;
		base.Initialize();
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		if (active)
		{
			if (TryFindTargetPOI(out var targetPOI))
			{
				SetTargetPOI(targetPOI);
			}
			else
			{
				GameEventDispatcher.AddListener(GameEventType.MapActivated, OnMapActivated);
			}
		}
		else
		{
			_bearing.SetActive(active: false);
			GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		}
	}

	private bool TryFindTargetPOI(out PointOfInterestSpawner targetPOI)
	{
		if (_targetPOI != null)
		{
			targetPOI = _targetPOI;
			return true;
		}
		if (_mode == Mode.POIVariable)
		{
			targetPOI = base.Quest.GetVariableValue<PointOfInterestSpawner>(this, _poiVariable);
			return targetPOI != null;
		}
		return TryFindTargetPOIWithProperties(out targetPOI);
	}

	private bool TryFindTargetPOIWithProperties(out PointOfInterestSpawner targetPOI)
	{
		targetPOI = GameManager.WorldManager.World.GetNearestPOIOfType(_poiProperties);
		if (targetPOI != null)
		{
			return true;
		}
		if (_logWarningIfPOINotFound)
		{
			UnityEngine.Debug.LogWarning("No valid poi \"" + _poiProperties.name + "\" found for objective MoveTownToPOIObjective! Will try again next time WorldMap is opened");
		}
		return false;
	}

	private void SetTargetPOI(PointOfInterestSpawner targetPOI)
	{
		if (_targetPOI != targetPOI)
		{
			_targetPOI = targetPOI;
			_bearing.Initialize(this, _targetPOI);
			_bearing.SetActive(active: true);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		_targetPOI = null;
		_bearing.Uninitialize();
		base.Uninitialize();
	}

	protected override bool IsArrived()
	{
		PointOfInterestSpawner pointOfInterestSpawner = null;
		switch (_mode)
		{
		case Mode.POIProperties:
			pointOfInterestSpawner = ((_targetPOI != null) ? _targetPOI : GameManager.WorldManager.World.GetNearestPOIOfType(_poiProperties));
			break;
		case Mode.POIVariable:
			pointOfInterestSpawner = ((_targetPOI != null) ? _targetPOI : base.Quest.GetVariableValue<PointOfInterestSpawner>(this, _poiVariable));
			break;
		}
		if (pointOfInterestSpawner == null)
		{
			return false;
		}
		float num = GameManager.Settings.GameplaySettings.SwimmingRadius;
		num *= num;
		Vector3 position = GameManager.WorldMapManager.WorldMap.Townheart.Position;
		return (pointOfInterestSpawner.WorldPosition - position).sqrMagnitude <= num;
	}

	private void OnMapActivated(GameEvent gameEvent)
	{
		if (TryFindTargetPOI(out var targetPOI))
		{
			SetTargetPOI(targetPOI);
			GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Move To Landmark \"" + GetName() + "\"";
	}

	public override string GetParameterValue(string param)
	{
		if (param == "POI")
		{
			return GetName();
		}
		return base.GetParameterValue(param);
	}

	private string GetName()
	{
		if (_targetPOI != null)
		{
			return _targetPOI.Name;
		}
		if (_poiProperties != null)
		{
			return _poiProperties.Title;
		}
		return "Any";
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		if (dialogueTriggerType == DialogueTriggerType.OnFlotsamItemSalvaged)
		{
			return target is ItemProperties itemProperties && IsItemInContext(itemProperties);
		}
		return false;
	}

	private bool IsItemInContext(ItemProperties itemProperties)
	{
		if (_mode == Mode.POIProperties)
		{
			return _poiProperties != null && _poiProperties.ReturnItems().Contains(itemProperties);
		}
		return _targetPOI != null && _targetPOI.GetAllFlotsamProperties().Contains(itemProperties.FlotsamProperties);
	}

	public override object Clone()
	{
		return new MoveTownToPOIObjective(this);
	}
}
[Serializable]
public class ORObjective : QuestObjectiveBase
{
	[SerializeField]
	[HideInInspector]
	private string _name = "OR";

	[SerializeReference]
	[SubclassSelector]
	private List<IQuestObjective> _objectives = new List<IQuestObjective>();

	public override bool IsOptional
	{
		get
		{
			if (!base.IsOptional)
			{
				return _objectives.Find((IQuestObjective objective) => objective.IsOptional) != null;
			}
			return true;
		}
	}

	public ORObjective()
	{
	}

	public ORObjective(ORObjective other)
		: base(other)
	{
		_objectives = other._objectives.Clone();
	}

	public override bool IsCompleted()
	{
		if (!base.IsCompleted())
		{
			return _objectives.Find((IQuestObjective objective) => objective.IsCompleted()) != null;
		}
		return true;
	}

	public override void SetOwningQuest(Quest owningQuest)
	{
		base.SetOwningQuest(owningQuest);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.SetOwningQuest(owningQuest);
		}
	}

	public override void Initialize()
	{
		foreach (IQuestObjective objective in _objectives)
		{
			objective.Initialize();
		}
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.QuestObjectiveUpdated, CheckObjectivesCompletion);
		}
	}

	public override void InitializeDialogueTriggers()
	{
		base.InitializeDialogueTriggers();
		foreach (IQuestObjective objective in _objectives)
		{
			objective.InitializeDialogueTriggers();
		}
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.SetActive(active);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestObjectiveUpdated, CheckObjectivesCompletion);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.Uninitialize();
		}
	}

	public override void UninitializeDialogueTriggers()
	{
		base.UninitializeDialogueTriggers();
		foreach (IQuestObjective objective in _objectives)
		{
			objective.UninitializeDialogueTriggers();
		}
	}

	private void CheckObjectivesCompletion(GameEvent gameEvent)
	{
		if (gameEvent is QuestEvent questEvent && _objectives.Contains(questEvent.Objective) && questEvent.Objective.IsCompleted())
		{
			SetCompleted(completed: true);
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		StringBuilder stringBuilder = new StringBuilder();
		int i = 0;
		for (int count = _objectives.Count; i < count; i++)
		{
			IQuestObjective questObjective = _objectives[i];
			if (!questObjective.IsHidden)
			{
				if (stringBuilder.Length != 0)
				{
					stringBuilder.Append(" or ");
				}
				if (questObjective is ORObjective || questObjective is ANDObjective)
				{
					stringBuilder.Append($"({questObjective})");
				}
				else
				{
					stringBuilder.Append(questObjective);
				}
			}
		}
		return stringBuilder.ToString();
	}

	public override object Clone()
	{
		return new ORObjective(this);
	}
}
public enum ObjectiveAmountInitialization
{
	Zero,
	Community,
	StatsManager
}
public enum ObjectiveInitialization
{
	Initialize,
	SetActive
}
