[Serializable]
public class ProduceObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	public enum Mode
	{
		ItemProperties,
		ItemType
	}

	[Serializable]
	public new class PersistentData : QuestObjectiveBase.PersistentData
	{
		private readonly int _producedAmount;

		public PersistentData(ProduceObjective objective)
			: base(objective)
		{
			_producedAmount = objective._producedAmount;
		}

		public override bool TryRestore(IQuestObjective objective)
		{
			if (base.TryRestore(objective) && objective is ProduceObjective produceObjective)
			{
				produceObjective._producedAmount = _producedAmount;
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Produce";

	[SerializeField]
	private Mode _mode;

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, true)]
	private ItemProperties _itemProperties;

	[SerializeField]
	[ConditionalEnumHide("_mode", 1, true)]
	private ItemType _itemType;

	[SerializeField]
	private int _amount;

	[SerializeField]
	[Tooltip("How should the produced amount be initialized")]
	private ObjectiveAmountInitialization _initialProducedAmount = ObjectiveAmountInitialization.StatsManager;

	private int _producedAmount;

	public ProduceObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnBuildableSelected);
	}

	public ProduceObjective(ProduceObjective other)
		: base(other)
	{
		_mode = other._mode;
		_itemProperties = other._itemProperties;
		_itemType = other._itemType;
		_amount = other._amount;
		_initialProducedAmount = other._initialProducedAmount;
		_producedAmount = other._producedAmount;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		return ((_producedAmount == 0) ? GetInitialProducedAmount() : _producedAmount) >= _amount;
	}

	public override void Initialize()
	{
		_producedAmount = GetInitialProducedAmount();
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.ProducerItemProduced, OnItemProduced);
			GameEventDispatcher.AddListener(GameEventType.ItemFarmed, OnItemProduced);
		}
	}

	public override void Uninitialize()
	{
		Community.PlayerCommunity.Inventory.InventoryUpdatedEvent.AddListener(OnInventoryUpdatedEvent);
		GameEventDispatcher.RemoveListener(GameEventType.ProducerItemProduced, OnItemProduced);
		GameEventDispatcher.RemoveListener(GameEventType.ItemFarmed, OnItemProduced);
	}

	private void OnItemProduced(GameEvent gameEvent)
	{
		if (gameEvent is ItemEvent itemEvent && itemEvent.ItemProperties != null)
		{
			IncrementProducedAmount(itemEvent.ItemProperties);
		}
	}

	private void OnInventoryUpdatedEvent()
	{
		_producedAmount = GetInitialProducedAmount();
	}

	private void IncrementProducedAmount(ItemProperties itemProperties)
	{
		switch (_mode)
		{
		case Mode.ItemProperties:
			if (!(itemProperties == _itemProperties))
			{
				return;
			}
			break;
		case Mode.ItemType:
			if (!(itemProperties.ItemType == _itemType))
			{
				return;
			}
			break;
		default:
			UnityEngine.Debug.LogException(new NotImplementedException());
			return;
		}
		if (++_producedAmount >= _amount)
		{
			SetCompleted(completed: true, sendEvent: false);
		}
		QuestEvent.DispatchQuestObjectiveUpdatedEvent(this);
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Produce: " + ((_itemProperties != null) ? _itemProperties.LocalizedName : "Any");
	}

	protected override bool TryGetProgressValues(out int currentValue, out int goalValue)
	{
		currentValue = _producedAmount;
		goalValue = _amount;
		return true;
	}

	public override string GetParameterValue(string param)
	{
		if (!(param == "ITEMTYPE"))
		{
			if (param == "ITEM")
			{
				return (_itemProperties != null) ? _itemProperties.LocalizedName : "Any";
			}
			return base.GetParameterValue(param);
		}
		return (_itemType != null) ? ((string)_itemType.Name) : "NULL";
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		Producer buildableExtendable;
		if (dialogueTriggerType == DialogueTriggerType.OnBuildableSelected)
		{
			return (target is Buildable buildable && buildable.TryReturnBuildableExtendable<Producer>(out buildableExtendable) && IsProducerInContext(buildableExtendable)) || (target is BuildableProperties buildableProperties && buildableProperties.Prefab.TryReturnBuildableExtendable<Producer>(out buildableExtendable) && IsProducerInContext(buildableExtendable));
		}
		return false;
	}

	private bool IsProducerInContext(Producer producer)
	{
		if (_mode == Mode.ItemProperties)
		{
			return producer.ProducedItems.Contains(_itemProperties);
		}
		return _itemType != null && producer.ProducedItems.Find((ItemProperties item) => item.ItemType == _itemType) != null;
	}

	public override object Clone()
	{
		return new ProduceObjective(this);
	}

	private int GetInitialProducedAmount()
	{
		switch (_initialProducedAmount)
		{
		case ObjectiveAmountInitialization.Community:
		{
			CommunityInventory inventory = Community.PlayerCommunity.Inventory;
			if (_mode != Mode.ItemProperties)
			{
				return inventory.ReturnCount(_itemType);
			}
			return inventory.ReturnCount(_itemProperties);
		}
		case ObjectiveAmountInitialization.StatsManager:
		{
			GameStatsManager gameStatsManager = GameManager.GameStatsManager;
			if (_mode != Mode.ItemProperties)
			{
				return gameStatsManager.GetProducedItemsCount(_itemType);
			}
			return gameStatsManager.GetProducedItemsCount(_itemProperties);
		}
		default:
			return 0;
		}
	}

	public override IQuestObjective.IPersistentData GetPersistentData()
	{
		return new PersistentData(this);
	}
}
public abstract class QuestObjectiveBase : IQuestObjective, ICloneable, IDialogueContextProvider, ILocalizationParamsManager
{
	[Serializable]
	public class PersistentData : IQuestObjective.IPersistentData
	{
		[OptionalField]
		private readonly bool _wasActivated;

		[OptionalField]
		private readonly bool _isCompleted;

		[OptionalField]
		private readonly bool _hasTriggeredGroupCompletedEvent;

		public int ObjectiveHashCode { get; }

		public PersistentData(QuestObjectiveBase objective)
		{
			ObjectiveHashCode = objective._uniqueID;
			_wasActivated = objective._wasActivated;
			_isCompleted = objective.IsCompleted();
			_hasTriggeredGroupCompletedEvent = objective._hasTriggeredGroupCompletedEvent;
		}

		public virtual bool TryRestore(IQuestObjective objective)
		{
			if (objective.UniqueID == ObjectiveHashCode && objective is QuestObjectiveBase questObjectiveBase)
			{
				questObjectiveBase._wasActivated = _wasActivated;
				if (_isCompleted)
				{
					questObjectiveBase.SetCompleted(sendEvent: false);
				}
				questObjectiveBase._hasTriggeredGroupCompletedEvent = _hasTriggeredGroupCompletedEvent;
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	protected LocalizedString _description;

	[SerializeField]
	[Wrapper("_localizationParameters")]
	private LocalizationParameters _localizationParameters = new LocalizationParameters();

	[SerializeField]
	private bool _isObjectiveOptional;

	[SerializeField]
	private bool _isHidden;

	[SerializeField]
	[Tooltip("List of Unlockables this objective requires, they will be unlocked when the objective is activated.")]
	private Unlockable[] _requiredUnlockables;

	[SerializeField]
	protected DialogueTriggers _dialogueTriggers = new DialogueTriggers();

	[SerializeField]
	[Tooltip("If there is an OnCompleted dialogue, completed will be set on EndOfDialogue. If for some reason that behaviour needs to be overriden, that can be done here. (None = completed is set when the dialogue is triggered)")]
	private DialogueResponseType _completeOnDialogueResponse = DialogueResponseType.EndOfDialogue;

	[SerializeField]
	[Tooltip("If the objective is not completed within this many days after being started, the quest will fail")]
	private int _daysTimeLimit;

	[SerializeField]
	private WorldTileSpawningBlocker _worldTileSpawningBlocker = new WorldTileSpawningBlocker();

	[SerializeField]
	[HideInInspector]
	private ushort _uniqueID;

	protected readonly List<DialogueTriggerType> _supportedDialogueTriggers = new List<DialogueTriggerType>
	{
		DialogueTriggerType.OnObjectiveShown,
		DialogueTriggerType.OnObjectiveCompleted,
		DialogueTriggerType.OnObjectiveTimedOut
	};

	private bool _wasActivated;

	private bool _isCompleted;

	private bool _hasTriggeredGroupCompletedEvent;

	public Quest Quest { get; protected set; }

	public bool IsActive { get; private set; }

	public virtual bool IsOptional => _isObjectiveOptional;

	public bool IsHidden => _isHidden;

	public virtual int DaysTimeLimit => _daysTimeLimit;

	public ushort UniqueID => _uniqueID;

	DialogueTreeProperties IDialogueContextProvider.DialogueProperties => null;

	IReadOnlyList<DialogueTriggerType> IDialogueContextProvider.SupportedTriggers => _supportedDialogueTriggers;

	public QuestObjectiveBase()
	{
	}

	public QuestObjectiveBase(QuestObjectiveBase other)
	{
		_description = other._description;
		_localizationParameters = other._localizationParameters;
		_isObjectiveOptional = other._isObjectiveOptional;
		_isHidden = other._isHidden;
		_requiredUnlockables = other._requiredUnlockables;
		_dialogueTriggers = new DialogueTriggers(other._dialogueTriggers);
		_daysTimeLimit = other._daysTimeLimit;
		_worldTileSpawningBlocker = new WorldTileSpawningBlocker(other._worldTileSpawningBlocker);
		_uniqueID = other._uniqueID;
		_supportedDialogueTriggers = new List<DialogueTriggerType>(other._supportedDialogueTriggers);
		Quest = other.Quest;
		_isCompleted = other._isCompleted;
		_hasTriggeredGroupCompletedEvent = other._hasTriggeredGroupCompletedEvent;
	}

	public void OnValidate()
	{
		if (_dialogueTriggers != null)
		{
			_dialogueTriggers.OnValidate();
		}
	}

	public virtual void SetActive(bool active)
	{
		IsActive = active;
		if (active)
		{
			if (!_wasActivated)
			{
				_dialogueTriggers.TriggerDialogue(DialogueTriggerType.OnObjectiveActivated);
				_wasActivated = true;
			}
			if (!((IReadOnlyCollection<Unlockable>)(object)_requiredUnlockables).IsNullOrEmpty())
			{
				Unlockable[] requiredUnlockables = _requiredUnlockables;
				for (int i = 0; i < requiredUnlockables.Length; i++)
				{
					requiredUnlockables[i].Unlock();
				}
			}
			_worldTileSpawningBlocker.SetQuestObjective(this);
		}
		else
		{
			_worldTileSpawningBlocker.Disable();
		}
	}

	public virtual bool IsCompleted()
	{
		return _isCompleted;
	}

	protected void SetCompleted(bool completed, bool sendEvent = true)
	{
		if (completed != _isCompleted && (!completed || !_dialogueTriggers.TriggerDialogue(DialogueTriggerType.OnObjectiveCompleted, OnObjectiveCompletedTriggerResponse) || _completeOnDialogueResponse == DialogueResponseType.None))
		{
			if (completed)
			{
				SetCompleted(sendEvent: false);
			}
			else
			{
				_isCompleted = false;
			}
			if (sendEvent)
			{
				QuestEvent.DispatchQuestObjectiveUpdatedEvent(this);
			}
		}
	}

	private void SetCompleted(bool sendEvent = true)
	{
		_isCompleted = true;
		Uninitialize();
		if (sendEvent)
		{
			QuestEvent.DispatchQuestObjectiveUpdatedEvent(this);
		}
	}

	private void OnObjectiveCompletedTriggerResponse(DialogueResponseType response, Dialogue dialogue)
	{
		if (_completeOnDialogueResponse != DialogueResponseType.None)
		{
			if (_completeOnDialogueResponse == DialogueResponseType.EndOfDialogue)
			{
				SetCompleted();
			}
			else if (response != DialogueResponseType.EndOfDialogue)
			{
				UnityEngine.Debug.LogException(new NotImplementedException($"QuestObjective '{this}' of Quest '{Quest.Properties}' should be completed on dialogue respone {_completeOnDialogueResponse}, but EndOfDialogue was received"));
				SetCompleted();
			}
		}
	}

	public virtual void SetOwningQuest(Quest owningQuest)
	{
		Quest = owningQuest;
	}

	public virtual void Initialize()
	{
		_isCompleted = IsCompleted();
	}

	protected bool InitializeIsCompleted()
	{
		_isCompleted = IsCompleted();
		return _isCompleted;
	}

	public virtual void Uninitialize()
	{
	}

	public virtual void InitializeDialogueTriggers()
	{
		_dialogueTriggers.Initialize(this);
	}

	public virtual void UninitializeDialogueTriggers()
	{
		_dialogueTriggers.Uninitialize();
	}

	public void TriggerDialogue(DialogueTriggerType dialogueTrigger)
	{
		_dialogueTriggers.TriggerDialogue(dialogueTrigger);
	}

	public void AssignUniqueID(ushort id)
	{
		_uniqueID = id;
	}

	public void TriggerObjectivesGroupCompleted()
	{
		if (!_hasTriggeredGroupCompletedEvent)
		{
			_dialogueTriggers.TriggerDialogue(DialogueTriggerType.OnObjectivesGroupCompleted);
			_hasTriggeredGroupCompletedEvent = true;
		}
	}

	public void TriggerShownToPlayer()
	{
		_dialogueTriggers.TriggerDialogue(DialogueTriggerType.OnObjectiveShown);
	}

	public void TriggerTimeOut()
	{
		_dialogueTriggers.TriggerDialogue(DialogueTriggerType.OnObjectiveTimedOut);
	}

	public void AddBlockingSpawner(ISpawner blockingSpawner)
	{
		_worldTileSpawningBlocker.AddBlockingSpawner(blockingSpawner);
	}

	public override string ToString()
	{
		string text;
		if ((string)_description != null)
		{
			LocalizationManager.ParamManagers.Add(this);
			text = _description;
			LocalizationManager.ParamManagers.Remove(this);
		}
		else
		{
			text = GetNonLocalizedDescription();
		}
		string objectiveProgressString = GetObjectiveProgressString();
		if (!objectiveProgressString.IsNullOrEmpty())
		{
			return text + " (" + objectiveProgressString + ")";
		}
		return text;
	}

	protected virtual string GetNonLocalizedDescription()
	{
		return "Missing quest description";
	}

	private string GetObjectiveProgressString()
	{
		if (!TryGetProgressValues(out var currentValue, out var goalValue))
		{
			return string.Empty;
		}
		goalValue = Mathf.Max(1, goalValue);
		return $"{Mathf.Clamp(currentValue, 0, goalValue)}/{goalValue}";
	}

	protected virtual bool TryGetProgressValues(out int currentValue, out int goalValue)
	{
		currentValue = 0;
		goalValue = 0;
		return false;
	}

	public abstract object Clone();

	public bool BlocksSpawning()
	{
		return _worldTileSpawningBlocker.Enabled;
	}

	public bool HasActiveDialogue()
	{
		return _dialogueTriggers.HasActiveDialogue();
	}

	public virtual bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		return false;
	}

	public bool TryGetActorDescriptor(DialogueContext.ActorType actorType, out AgentDescriptor actorDescriptor)
	{
		if (Quest != null)
		{
			return Quest.TryGetActorDescriptor(actorType, out actorDescriptor);
		}
		return StoryManager.DialogueContext.TryGetActor(actorType, out actorDescriptor);
	}

	public virtual string GetParameterValue(string param)
	{
		return _localizationParameters.GetParameterValue(param);
	}

	public bool TryFindDialogueTrigger(ushort uniqueID, out DialogueTrigger dialogueTrigger)
	{
		return _dialogueTriggers.TryFindTrigger(uniqueID, out dialogueTrigger);
	}

	public virtual IQuestObjective.IPersistentData GetPersistentData()
	{
		return new PersistentData(this);
	}
}
[Serializable]
public class RescueObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	public enum RescueType
	{
		QuestGiver,
		ReferenceProfile,
		Any,
		LandmarkVariable
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Rescue";

	[SerializeField]
	private RescueType _rescueType;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 2, true)]
	private ActorType _actorType;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 1, true)]
	private AgentProfile _specificActorToRescue;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 2, true)]
	private int _requiredCount = 1;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 2, true)]
	private ComparisonType _comparisonType = ComparisonType.EqualOrGreaterThan;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 3, true)]
	[QuestVariable(QuestVariableType.Landmark)]
	private int _rescueLandmarkVariable;

	[SerializeField]
	[ConditionalEnumHide("_rescueType", 3, true)]
	private SpawnerObjectiveBearing _bearing;

	private LandmarkSpawner _rescueLandmark;

	private AgentDescriptor _rescuableDescriptor;

	private readonly List<ActorDescriptor> _rescuedActors = new List<ActorDescriptor>();

	public RescueObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkSelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkRegionEntered);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnAgentSelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnAgentFromPlayerCommunitySelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnOutsiderAgentSelected);
	}

	public RescueObjective(RescueObjective other)
		: base(other)
	{
		_rescueType = other._rescueType;
		_actorType = other._actorType;
		_specificActorToRescue = other._specificActorToRescue;
		_requiredCount = other._requiredCount;
		_comparisonType = other._comparisonType;
		_rescueLandmarkVariable = other._rescueLandmarkVariable;
		_bearing = new SpawnerObjectiveBearing(other._bearing);
		_rescuedActors = new List<ActorDescriptor>(other._rescuedActors);
	}

	public override bool IsCompleted()
	{
		bool flag = base.IsCompleted();
		if (!flag)
		{
			flag = _rescueType switch
			{
				RescueType.QuestGiver => _rescuedActors.Contains(base.Quest.QuestGiver) || Community.PlayerCommunity.HasActor(base.Quest.QuestGiver), 
				RescueType.ReferenceProfile => _rescuedActors.Contains(_specificActorToRescue.GetDescriptor()) || Community.PlayerCommunity.HasActor(_specificActorToRescue.GetDescriptor()), 
				RescueType.LandmarkVariable => IsRescueActionCompleted(), 
				RescueType.Any => _rescuedActors.Count.Compare(_comparisonType, _requiredCount), 
				_ => false, 
			};
		}
		return flag;
	}

	public override void Initialize()
	{
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.ActorRescue, OnActorRescued);
		}
	}

	public override void SetActive(bool active)
	{
		if (_rescueType == RescueType.LandmarkVariable)
		{
			if (base.Quest.TryGetVariableValue<LandmarkSpawner>(this, _rescueLandmarkVariable, out _rescueLandmark))
			{
				base.Quest.TryGetVariableValue<AgentDescriptor>(this, _rescueLandmarkVariable, out _rescuableDescriptor);
				_bearing.Initialize(this, _rescueLandmark);
				_bearing.SetActive(active);
				base.SetActive(active);
				AddBlockingSpawner(_rescueLandmark);
			}
			else if (IsOptional)
			{
				QuestProperties arg = ((base.Quest == null) ? null : base.Quest.Properties);
				UnityEngine.Debug.LogException(new Exception($"Unable to initialize optional RescueObjective with RescueType.LandmarkVariable for quest '{arg}'."));
				SetCompleted(completed: false);
			}
			else
			{
				QuestProperties arg2 = ((base.Quest == null) ? null : base.Quest.Properties);
				UnityEngine.Debug.LogException(new Exception($"Unable to initialize RescueObjective with RescueType.LandmarkVariable for quest '{arg2}'. The quest failed!"));
				base.Quest.SetFailed();
			}
		}
		else
		{
			base.SetActive(active);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ActorRescue, OnActorRescued);
		_bearing.Uninitialize();
	}

	private void OnActorRescued(GameEvent gameEvent)
	{
		if (gameEvent is ActorEvent { ActorDescriptor: not null } actorEvent && DoesActorCount(actorEvent.ActorDescriptor))
		{
			_rescuedActors.Add(actorEvent.ActorDescriptor);
			if (IsCompleted())
			{
				SetCompleted(completed: true);
			}
		}
	}

	private bool DoesActorCount(ActorDescriptor actorDescriptor)
	{
		AgentDescriptor agentDescriptor = actorDescriptor as AgentDescriptor;
		return _rescueType switch
		{
			RescueType.QuestGiver => agentDescriptor == base.Quest.QuestGiver, 
			RescueType.ReferenceProfile => agentDescriptor == _specificActorToRescue.GetDescriptor(), 
			RescueType.LandmarkVariable => _rescuableDescriptor == null || agentDescriptor == _rescuableDescriptor, 
			RescueType.Any => actorDescriptor.ActorType == _actorType, 
			_ => true, 
		};
	}

	private bool IsRescueActionCompleted()
	{
		if (_rescuableDescriptor != null)
		{
			if (!_rescuedActors.Contains(_rescuableDescriptor))
			{
				return Community.PlayerCommunity.HasActor(_rescuableDescriptor);
			}
			return true;
		}
		if (_rescueLandmark != null && _rescueLandmark.LandmarkBehaviour is ActionsBehaviour actionsBehaviour && actionsBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false))
		{
			return action.IsCompleted;
		}
		return false;
	}

	protected override string GetNonLocalizedDescription()
	{
		RescueType rescueType = _rescueType;
		if ((uint)rescueType <= 1u)
		{
			return "Rescue " + GetTargetAgentName();
		}
		return $"Rescue drifters ({_comparisonType} {_requiredCount})";
	}

	public override string GetParameterValue(string param)
	{
		switch (param)
		{
		case "AGENT":
		case "DRIFTER":
			return GetTargetAgentName();
		case "LANDMARK":
			return (_rescueLandmark != null) ? _rescueLandmark.Name : "NULL";
		default:
			return base.GetParameterValue(param);
		}
	}

	private string GetTargetAgentName()
	{
		return _rescueType switch
		{
			RescueType.QuestGiver => (base.Quest != null && base.Quest.QuestGiver != null) ? base.Quest.QuestGiver.Name : "NULL", 
			RescueType.ReferenceProfile => (_specificActorToRescue != null) ? _specificActorToRescue.Name : "NULL", 
			RescueType.LandmarkVariable => (_rescuableDescriptor != null) ? _rescuableDescriptor.Name : "NULL", 
			_ => "Any", 
		};
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		switch (dialogueTriggerType)
		{
		case DialogueTriggerType.OnLandmarkSelected:
		case DialogueTriggerType.OnLandmarkRegionEntered:
			return target is ActionsBehaviour landmarkBehaviour && IsLandmarkBehaviourInContext(landmarkBehaviour);
		case DialogueTriggerType.OnAgentSelected:
		case DialogueTriggerType.OnAgentFromPlayerCommunitySelected:
		case DialogueTriggerType.OnOutsiderAgentSelected:
			return target is Agent agent && IsAgentInContext(agent, dialogueTriggerType);
		default:
			return false;
		}
	}

	private bool IsLandmarkBehaviourInContext(ActionsBehaviour landmarkBehaviour)
	{
		if (landmarkBehaviour.TryReturnAction<LandmarkActionRescue>(out var action, includeCompleted: false))
		{
			return action.Rescueables.Find(IsAgentInContextForLandmarkSelected) != null;
		}
		return false;
	}

	private bool IsAgentInContextForLandmarkSelected(LandmarkActionRescue.Rescueable rescueable)
	{
		if (rescueable != null && rescueable.Agent != null)
		{
			return DoesActorCount(rescueable.Agent.Descriptor);
		}
		return false;
	}

	private bool IsAgentInContext(Agent agent, DialogueTriggerType dialogueTriggerType)
	{
		bool flag = agent != null;
		if (flag)
		{
			flag = _rescueType switch
			{
				RescueType.QuestGiver => agent.Descriptor == base.Quest.QuestGiver, 
				RescueType.ReferenceProfile => agent.Descriptor == _specificActorToRescue.GetDescriptor(), 
				RescueType.LandmarkVariable => agent.Descriptor == _rescuableDescriptor, 
				RescueType.Any => dialogueTriggerType switch
				{
					DialogueTriggerType.OnAgentSelected => !agent.InPlayerCommunity() || (_rescuedActors != null && _rescuedActors.Contains(agent.Descriptor)), 
					DialogueTriggerType.OnAgentFromPlayerCommunitySelected => _rescuedActors != null && _rescuedActors.Contains(agent.Descriptor), 
					DialogueTriggerType.OnOutsiderAgentSelected => !agent.InPlayerCommunity(), 
					_ => false, 
				}, 
				_ => false, 
			};
		}
		return flag;
	}

	public override object Clone()
	{
		return new RescueObjective(this);
	}
}
[Serializable]
public class ResearchObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	[SerializeField]
	[HideInInspector]
	private string _name = "Research";

	[SerializeField]
	private ResearchUnlockable _buildingToUnlock;

	public ResearchObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnBuildableSelected);
	}

	public ResearchObjective(ResearchObjective other)
		: base(other)
	{
		_buildingToUnlock = other._buildingToUnlock;
	}

	public override bool IsCompleted()
	{
		if (!base.IsCompleted())
		{
			if (_buildingToUnlock != null)
			{
				return Community.PlayerCommunity.Research.IsResearched(_buildingToUnlock);
			}
			return false;
		}
		return true;
	}

	public override void Initialize()
	{
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.ResearchFinished, OnResearchFinished);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ResearchFinished, OnResearchFinished);
	}

	private void OnResearchFinished(GameEvent gameEvent)
	{
		if (_buildingToUnlock == null || Community.PlayerCommunity.Research.IsResearched(_buildingToUnlock))
		{
			SetCompleted(completed: true);
			Uninitialize();
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Research: " + ((_buildingToUnlock != null) ? _buildingToUnlock.GetName() : "Any");
	}

	public override string GetParameterValue(string param)
	{
		if (param == "RESEARCHABLE")
		{
			return (_buildingToUnlock != null) ? _buildingToUnlock.GetName() : "Any";
		}
		return base.GetParameterValue(param);
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		ResearchStation buildableExtendable;
		if (dialogueTriggerType == DialogueTriggerType.OnBuildableSelected)
		{
			return (target is Buildable buildable && buildable.TryReturnBuildableExtendable<ResearchStation>(out buildableExtendable)) || (target is BuildableProperties buildableProperties && buildableProperties.Prefab.TryReturnBuildableExtendable<ResearchStation>(out buildableExtendable));
		}
		return false;
	}

	public override object Clone()
	{
		return new ResearchObjective(this);
	}
}
[Serializable]
