[Serializable]
public class RotateCameraObjective : QuestObjectiveBase
{
	[SerializeField]
	[HideInInspector]
	private string _name = "Rotate Camera";

	[SerializeField]
	private float _minimumRotation = 45f;

	[SerializeField]
	private bool _includePreviousRotations;

	private float _totalRotation;

	public RotateCameraObjective()
	{
	}

	public RotateCameraObjective(RotateCameraObjective other)
		: base(other)
	{
		_minimumRotation = other._minimumRotation;
		_includePreviousRotations = other._includePreviousRotations;
		_totalRotation = other._totalRotation;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		return ((!_includePreviousRotations || _totalRotation != 0f) ? _totalRotation : GameManager.GameStatsManager.TotalCameraRotationChanges) >= _minimumRotation;
	}

	public override void Initialize()
	{
		_totalRotation = (_includePreviousRotations ? GameManager.GameStatsManager.TotalCameraRotationChanges : 0f);
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.ManualCameraRotation, OnCameraRotated);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ManualCameraRotation, OnCameraRotated);
	}

	private void OnCameraRotated(GameEvent gameEvent)
	{
		if (gameEvent is CameraGameEvent cameraGameEvent)
		{
			_totalRotation += Mathf.Abs(cameraGameEvent.Rotation);
			if (IsCompleted())
			{
				SetCompleted(completed: true);
			}
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Rotate Camera";
	}

	public override object Clone()
	{
		return new RotateCameraObjective(this);
	}
}
[Serializable]
public class SalvageLandmarkObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	[Serializable]
	public new class PersistentData : QuestObjectiveBase.PersistentData
	{
		private readonly int _salvagedAmount;

		public PersistentData(SalvageLandmarkObjective objective)
			: base(objective)
		{
			_salvagedAmount = objective._salvagedAmount;
		}

		public override bool TryRestore(IQuestObjective objective)
		{
			if (base.TryRestore(objective) && objective is SalvageLandmarkObjective salvageLandmarkObjective)
			{
				salvageLandmarkObjective._salvagedAmount = _salvagedAmount;
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Salvage landmark";

	[SerializeField]
	private ItemProperties _itemProperties;

	[SerializeField]
	private int _amount;

	[SerializeField]
	private ObjectiveAmountInitialization _salvagedAmountInitialization;

	[SerializeField]
	private bool _targetLandmarkVariable;

	[SerializeField]
	[ConditionalHide("_targetLandmarkVariable", true)]
	[QuestVariable(QuestVariableType.Landmark)]
	private int _landmarkVariable;

	[SerializeField]
	[ConditionalHide("_targetLandmarkVariable", true)]
	private SpawnerObjectiveBearing _bearing;

	private int _salvagedAmount;

	public SalvageLandmarkObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkSelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkRegionEntered);
	}

	public SalvageLandmarkObjective(SalvageLandmarkObjective other)
		: base(other)
	{
		_itemProperties = other._itemProperties;
		_amount = other._amount;
		_salvagedAmountInitialization = other._salvagedAmountInitialization;
		_salvagedAmount = other._salvagedAmount;
		_targetLandmarkVariable = other._targetLandmarkVariable;
		_landmarkVariable = other._landmarkVariable;
		_bearing = other._bearing;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		return _salvagedAmount >= _amount;
	}

	public override void Initialize()
	{
		switch (_salvagedAmountInitialization)
		{
		case ObjectiveAmountInitialization.Zero:
			_salvagedAmount = 0;
			break;
		case ObjectiveAmountInitialization.Community:
			_salvagedAmount = Community.PlayerCommunity.Inventory.ReturnCount(_itemProperties);
			break;
		default:
			_salvagedAmount = GameManager.GameStatsManager.GetSalvagedLandmarkItemsCount(_itemProperties);
			break;
		}
		if (TryGetTargetLandmark(out var targetLandmark))
		{
			_bearing.Initialize(this, targetLandmark);
		}
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedLandmarkItem, OnItemSalvaged);
		}
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		_bearing.SetActive(active);
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedLandmarkItem, OnItemSalvaged);
	}

	private void OnItemSalvaged(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent && !(agentActionItemPropertiesEvent.ItemProperties != _itemProperties))
		{
			if (++_salvagedAmount >= _amount)
			{
				SetCompleted(completed: true, sendEvent: false);
			}
			QuestEvent.DispatchQuestObjectiveUpdatedEvent(this);
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Salvage Landmark: " + ((_itemProperties != null) ? _itemProperties.LocalizedName : "Any");
	}

	protected override bool TryGetProgressValues(out int currentValue, out int goalValue)
	{
		currentValue = _salvagedAmount;
		goalValue = _amount;
		return true;
	}

	public override string GetParameterValue(string param)
	{
		if (param == "ITEM")
		{
			return (_itemProperties != null) ? _itemProperties.LocalizedName : "Any";
		}
		return base.GetParameterValue(param);
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		LandmarkActionSalvage action;
		if (dialogueTriggerType == DialogueTriggerType.OnLandmarkSelected || dialogueTriggerType == DialogueTriggerType.OnLandmarkRegionEntered)
		{
			return target is ActionsBehaviour actionsBehaviour && actionsBehaviour.TryReturnAction<LandmarkActionSalvage>(out action, includeCompleted: false) && action.ReturnIsSalvageableItem(_itemProperties);
		}
		return false;
	}

	public override object Clone()
	{
		return new SalvageLandmarkObjective(this);
	}

	private bool TryGetTargetLandmark(out LandmarkSpawner targetLandmark)
	{
		targetLandmark = (_targetLandmarkVariable ? base.Quest.GetVariableValue<LandmarkSpawner>(this, _landmarkVariable) : null);
		return targetLandmark != null;
	}

	public override IQuestObjective.IPersistentData GetPersistentData()
	{
		return new PersistentData(this);
	}
}
[Serializable]
public class SalvageMarkerObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	public enum Mode
	{
		ItemProperties,
		PointOfInterestVariable
	}

	[Serializable]
	public new class PersistentData : QuestObjectiveBase.PersistentData
	{
		private readonly int _salvagedAmount;

		private readonly Vector3 _worldPosition = Vector3.zero;

		public PersistentData(SalvageMarkerObjective objective)
			: base(objective)
		{
			_salvagedAmount = objective._salvagedAmount;
		}

		public override bool TryRestore(IQuestObjective objective)
		{
			if (base.TryRestore(objective) && objective is SalvageMarkerObjective salvageMarkerObjective)
			{
				salvageMarkerObjective._salvagedAmount = _salvagedAmount;
				return true;
			}
			return false;
		}
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Salvage marker";

	[SerializeField]
	private int _amount;

	[SerializeField]
	private ObjectiveAmountInitialization _amountInitialization = ObjectiveAmountInitialization.StatsManager;

	[SerializeField]
	[Tooltip("Do we include resources salvaged before this objective started?")]
	private bool _includePreSalvaged = true;

	[SerializeField]
	private Mode _mode;

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, true)]
	private ItemProperties _itemProperties;

	[SerializeField]
	[ConditionalEnumHide("_mode", 1, true)]
	[QuestVariable(QuestVariableType.PointOfInterest)]
	private int _pointOfInterestVariable;

	[SerializeField]
	private SpawnerObjectiveBearing _bearing;

	private ISpawner _spawner;

	private int _salvagedAmount;

	public SalvageMarkerObjective()
	{
	}

	public SalvageMarkerObjective(SalvageMarkerObjective other)
		: base(other)
	{
		_amount = other._amount;
		_includePreSalvaged = other._includePreSalvaged;
		_mode = other._mode;
		_itemProperties = other._itemProperties;
		_pointOfInterestVariable = other._pointOfInterestVariable;
		_bearing = new SpawnerObjectiveBearing(other._bearing);
		_salvagedAmount = other._salvagedAmount;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		return _salvagedAmount >= _amount;
	}

	public override void Initialize()
	{
		_salvagedAmount = (_includePreSalvaged ? GetInitialAmount() : 0);
		if (InitializeIsCompleted())
		{
			return;
		}
		GameEventDispatcher.AddListener(GameEventType.AgentActionSalvagedMarkerItem, OnItemSalvaged);
		if (_bearing.Enabled)
		{
			GameEventDispatcher.AddListener(GameEventType.MapActivated, OnMapOpened);
			if (GameManager.UIManager.UIState == UIState.Map)
			{
				OnMapOpened();
			}
		}
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		if (_spawner != null)
		{
			_bearing.SetActive(active);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentActionSalvagedMarkerItem, OnItemSalvaged);
		GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapOpened);
		_bearing.Uninitialize();
	}

	private void OnItemSalvaged(GameEvent gameEvent)
	{
		if (gameEvent is AgentActionItemPropertiesEvent agentActionItemPropertiesEvent && !(agentActionItemPropertiesEvent.ItemProperties != _itemProperties))
		{
			if (++_salvagedAmount >= _amount)
			{
				SetCompleted(completed: true, sendEvent: false);
			}
			QuestEvent.DispatchQuestObjectiveUpdatedEvent(this);
		}
	}

	private void OnMapOpened(GameEvent gameEvent = null)
	{
		_spawner = null;
		switch (_mode)
		{
		case Mode.ItemProperties:
		{
			WorldMapFlotsam nearestFlotsam = GetNearestFlotsam(_itemProperties);
			if ((bool)nearestFlotsam)
			{
				_spawner = nearestFlotsam.Spawner;
			}
			break;
		}
		case Mode.PointOfInterestVariable:
			if (base.Quest.TryGetVariableValue<ISpawner>(this, _pointOfInterestVariable, out _spawner))
			{
				AddBlockingSpawner(_spawner);
			}
			break;
		default:
			UnityEngine.Debug.LogException(new NotImplementedException());
			break;
		}
		if (_spawner == null)
		{
			UnityEngine.Debug.LogError("No valid flotsam found anywhere for SalvageMarkerObjective!");
			_bearing.SetActive(active: false);
		}
		else
		{
			_bearing.Initialize(this, _spawner);
			_bearing.SetActive(active: true);
		}
	}

	private WorldMapFlotsam GetNearestFlotsam(ItemProperties itemProperties)
	{
		using ListPool<WorldMapFlotsam>.List list = GetFlotsam(itemProperties.FlotsamProperties);
		Vector3 position = GameManager.WorldMapManager.WorldMap.Townheart.Position;
		float num = float.MaxValue;
		WorldMapFlotsam result = null;
		foreach (WorldMapFlotsam item in list)
		{
			Vector3 vector = item.transform.position - position;
			if (!(vector.x < -150f))
			{
				float sqrMagnitude = vector.sqrMagnitude;
				if (sqrMagnitude < num)
				{
					num = sqrMagnitude;
					result = item;
				}
			}
		}
		return result;
	}

	private ListPool<WorldMapFlotsam>.List GetFlotsam(FlotsamProperties flotsamProperties)
	{
		ListPool<WorldMapFlotsam>.List list = ListPool<WorldMapFlotsam>.Get();
		foreach (WorldMapFlotsam item in GameManager.WorldMapManager.WorldMap.GetAllFlotsam())
		{
			foreach (FlotsamProperties allFlotsamProperty in item.GetAllFlotsamProperties())
			{
				if (allFlotsamProperty == flotsamProperties || (allFlotsamProperty is CompositedFlotsamProperties compositedFlotsamProperties && compositedFlotsamProperties.Contains(flotsamProperties)))
				{
					list.Add(item);
					break;
				}
			}
		}
		return list;
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Salvage: " + ((_itemProperties != null) ? _itemProperties.LocalizedName : "Any");
	}

	protected override bool TryGetProgressValues(out int currentValue, out int goalValue)
	{
		currentValue = _salvagedAmount;
		goalValue = _amount;
		return true;
	}

	public override string GetParameterValue(string param)
	{
		if (param == "ITEM")
		{
			return (_itemProperties != null) ? _itemProperties.LocalizedName : "Any";
		}
		return base.GetParameterValue(param);
	}

	public override object Clone()
	{
		return new SalvageMarkerObjective(this);
	}

	private int GetInitialAmount()
	{
		return _amountInitialization switch
		{
			ObjectiveAmountInitialization.Community => Community.PlayerCommunity.Inventory.ReturnCount(_itemProperties), 
			ObjectiveAmountInitialization.StatsManager => GameManager.GameStatsManager.GetSalvagedMarkerItemsCount(_itemProperties), 
			_ => 0, 
		};
	}

	public override IQuestObjective.IPersistentData GetPersistentData()
	{
		return new PersistentData(this);
	}
}
[Serializable]
public class ScoutRegionObjective : QuestObjectiveBase
{
	public enum Mode
	{
		LandmarkVariable,
		AnyRegion
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Scout region";

	[SerializeField]
	private Mode _mode;

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, true)]
	[QuestVariable(QuestVariableType.Landmark)]
	private int _landmarkVariable;

	[SerializeField]
	[ConditionalEnumHide("_mode", 0, true)]
	private SpawnerObjectiveBearing _bearing;

	[SerializeField]
	private bool _reinitializeOnMapActivated = true;

	private LandmarkSpawner _targetLandmark;

	public ScoutRegionObjective()
	{
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkSelected);
		_supportedDialogueTriggers.Add(DialogueTriggerType.OnLandmarkRegionEntered);
	}

	public ScoutRegionObjective(ScoutRegionObjective other)
		: base(other)
	{
		_mode = other._mode;
		_landmarkVariable = other._landmarkVariable;
		_bearing = new SpawnerObjectiveBearing(other._bearing);
		_reinitializeOnMapActivated = other._reinitializeOnMapActivated;
		_targetLandmark = other._targetLandmark;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted() || (_mode == Mode.AnyRegion && GameManager.GameStatsManager.RegionsScoutedCount > 0))
		{
			return true;
		}
		if (_mode == Mode.LandmarkVariable && base.Quest != null)
		{
			LandmarkSpawner landmarkSpawner = ((_targetLandmark != null) ? _targetLandmark : base.Quest.GetVariableValue<LandmarkSpawner>(this, _landmarkVariable));
			if (landmarkSpawner != null && landmarkSpawner.ScoutingState == ScoutingState.Scouted)
			{
				return true;
			}
		}
		return false;
	}

	public override void Initialize()
	{
		if (InitializeIsCompleted())
		{
			return;
		}
		if (InitializeTargetLandmark())
		{
			GameEventDispatcher.AddListener(GameEventType.RegionScouted, OnScouted);
			if (_reinitializeOnMapActivated)
			{
				GameEventDispatcher.AddListener(GameEventType.MapActivated, OnMapActivated);
			}
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception($"Unable to find target landmark for ScoutRegionObjective in '{_mode}' mode."));
			SetCompleted(completed: true, sendEvent: false);
		}
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.MapActivated, OnMapActivated);
		GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnScouted);
		_bearing.Uninitialize();
	}

	private bool InitializeTargetLandmark()
	{
		_targetLandmark = null;
		switch (_mode)
		{
		case Mode.LandmarkVariable:
			_targetLandmark = base.Quest.GetVariableValue<LandmarkSpawner>(this, _landmarkVariable);
			break;
		case Mode.AnyRegion:
			return true;
		}
		if (_targetLandmark == null)
		{
			_bearing.SetActive(active: false);
			return false;
		}
		_bearing.Initialize(this, _targetLandmark);
		_bearing.SetActive(active: true);
		return true;
	}

	private void OnScouted(GameEvent gameEvent)
	{
		if (_mode == Mode.AnyRegion || _targetLandmark == null || (gameEvent is ScoutingEvent scoutingEvent && scoutingEvent.Region == _targetLandmark.Region))
		{
			SetCompleted(completed: true);
			Uninitialize();
		}
	}

	private void OnMapActivated(GameEvent gameEvent = null)
	{
		InitializeTargetLandmark();
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Scout a Region";
	}

	public override bool IsObjectInContext(object target, DialogueTriggerType dialogueTriggerType)
	{
		return dialogueTriggerType switch
		{
			DialogueTriggerType.OnLandmarkSelected => target == _targetLandmark, 
			DialogueTriggerType.OnLandmarkRegionEntered => target is IWorldRegion worldRegion && _targetLandmark != null && worldRegion == _targetLandmark.Region, 
			_ => false, 
		};
	}

	public override object Clone()
	{
		return new ScoutRegionObjective(this);
	}
}
