[Serializable]
public class SelectLandmarkObjective : QuestObjectiveBase, ILocalizationParamsManager
{
	public enum LandmarkMode
	{
		Tutorial,
		LandmarkVariable
	}

	[SerializeField]
	[HideInInspector]
	private string _name = "Select landmark";

	[SerializeField]
	private LandmarkMode _landmarkMode;

	[SerializeField]
	[ConditionalEnumHide("_landmarkMode", 0, true)]
	private SerializableInterface<ILandmarkBehaviourProvider> _specificLandmark;

	[SerializeField]
	[ConditionalEnumHide("_landmarkMode", 1, true)]
	[QuestVariable(QuestVariableType.Landmark)]
	private int _landmarkVariable;

	[SerializeField]
	private LandmarkAction _requiredLandmarkAction;

	[SerializeField]
	private SpawnerObjectiveBearing _bearing;

	public SelectLandmarkObjective()
	{
	}

	public SelectLandmarkObjective(SelectLandmarkObjective other)
		: base(other)
	{
		_landmarkMode = other._landmarkMode;
		_specificLandmark = other._specificLandmark;
		_landmarkVariable = other._landmarkVariable;
		_requiredLandmarkAction = other._requiredLandmarkAction;
		_bearing = other._bearing;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		if (Selector.SelectedType == ObjectType.Landmark && Selector.Selection.ObjectToSelect.TryGetComponent<Landmark>(out var component))
		{
			return IsLandmark(component);
		}
		return false;
	}

	public override void Initialize()
	{
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
		}
	}

	public override void SetActive(bool active)
	{
		base.SetActive(active);
		if (!IsCompleted() && _landmarkMode == LandmarkMode.LandmarkVariable && base.Quest.TryGetVariableValue<LandmarkSpawner>(this, _landmarkVariable, out var value))
		{
			_bearing.Initialize(this, value);
			_bearing.SetActive(active);
		}
	}

	public override void Uninitialize()
	{
		_bearing.Uninitialize();
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSelected, OnLandmarkSelected);
	}

	private void OnLandmarkSelected(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && (bool)landmarkNotificationEvent.LandmarkBehaviour && IsLandmark(landmarkNotificationEvent.LandmarkBehaviour.Landmark))
		{
			SetCompleted(completed: true);
		}
	}

	private bool IsLandmark(Landmark landmark)
	{
		switch (_landmarkMode)
		{
		case LandmarkMode.Tutorial:
			if (_specificLandmark.Value != null && !_specificLandmark.Value.ReturnIsLandmarkBehaviour(landmark.Behaviour))
			{
				return false;
			}
			break;
		case LandmarkMode.LandmarkVariable:
		{
			if (!base.Quest.TryGetVariableValue<LandmarkSpawner>(this, _landmarkVariable, out var value) || value.LandmarkBehaviour == null || value.LandmarkBehaviour.Landmark != landmark)
			{
				return false;
			}
			break;
		}
		}
		if (!(_requiredLandmarkAction == null))
		{
			if (landmark.Behaviour is ActionsBehaviour actionsBehaviour)
			{
				return actionsBehaviour.ReturnHasLandmarkAction(_requiredLandmarkAction);
			}
			return false;
		}
		return true;
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Select Landmark: " + ((_specificLandmark.Value != null) ? _specificLandmark.Value.Name : "Any") + " with action: " + ((_requiredLandmarkAction != null) ? _requiredLandmarkAction.name : "Any");
	}

	public override string GetParameterValue(string param)
	{
		if (param == "LANDMARK")
		{
			return GetLandmarkName();
		}
		return base.GetParameterValue(param);
	}

	public override object Clone()
	{
		return new SelectLandmarkObjective(this);
	}

	private string GetLandmarkName()
	{
		switch (_landmarkMode)
		{
		case LandmarkMode.Tutorial:
			if (_specificLandmark.Value == null)
			{
				return "Any";
			}
			return _specificLandmark.Value.Name;
		case LandmarkMode.LandmarkVariable:
		{
			if (base.Quest == null || !base.Quest.TryGetVariableValue<LandmarkSpawner>(_landmarkVariable, out var value))
			{
				return "NULL";
			}
			return value.Name;
		}
		default:
			return "NOT IMPLEMENTED";
		}
	}
}
[Serializable]
public class TalkObjective : QuestObjectiveBase
{
	[SerializeField]
	[HideInInspector]
	private string _name = "Talk";

	[SerializeField]
	private AgentProfile _actorToTalkTo;

	private Agent _registeredAgent;

	public TalkObjective()
	{
	}

	public TalkObjective(TalkObjective other)
		: base(other)
	{
		_actorToTalkTo = other._actorToTalkTo;
		_registeredAgent = other._registeredAgent;
	}

	public override void Initialize()
	{
		if (_actorToTalkTo != null)
		{
			MarkAgentAsHavingActiveTalkObjective();
		}
		else
		{
			GameEventDispatcher.AddListener(GameEventType.AgentMessageUpdated, OnAgentMessageUpdated);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.AgentMessageUpdated, OnAgentMessageUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.AgentSpawn, OnAgentSpawn);
		GameEventDispatcher.RemoveListener(GameEventType.AgentSelected, OnAgentSelected);
		GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, OnAgentDeath);
	}

	private void MarkAgentAsHavingActiveTalkObjective()
	{
		AgentDescriptor descriptor = _actorToTalkTo.GetDescriptor();
		foreach (Community community in Community.Communities)
		{
			foreach (Agent agent in community.Agents)
			{
				if (agent.Descriptor == descriptor)
				{
					RegisterAgent(agent);
					return;
				}
			}
		}
		GameEventDispatcher.AddListener(GameEventType.AgentSpawn, OnAgentSpawn);
	}

	private void RegisterAgent(Agent agent)
	{
		_registeredAgent = agent;
		agent.SetHasActiveTalkObjective(hasActiveObjective: true);
		GameEventDispatcher.AddListener(GameEventType.AgentSelected, OnAgentSelected);
		GameEventDispatcher.AddListener(GameEventType.AgentDeath, OnAgentDeath);
	}

	private void OnAgentMessageUpdated(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent && agentEvent.Agent != null && !agentEvent.Agent.ReturnHasMessageQueued())
		{
			SetCompleted(completed: true);
		}
	}

	private void OnAgentSpawn(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent && agentEvent.AgentDescriptor == _actorToTalkTo.GetDescriptor())
		{
			RegisterAgent(agentEvent.Agent);
		}
	}

	private void OnAgentSelected(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent && agentEvent.Agent == _registeredAgent && agentEvent.Agent.InPlayerCommunity())
		{
			SetCompleted(completed: true);
		}
	}

	private void OnAgentDeath(GameEvent gameEvent)
	{
		if (gameEvent is AgentEvent agentEvent && agentEvent.Agent == _registeredAgent)
		{
			_registeredAgent = null;
			GameEventDispatcher.RemoveListener(GameEventType.AgentSelected, OnAgentSelected);
			GameEventDispatcher.RemoveListener(GameEventType.AgentDeath, OnAgentDeath);
			GameEventDispatcher.AddListener(GameEventType.AgentSpawn, OnAgentSpawn);
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Talk to " + ((_actorToTalkTo != null) ? _actorToTalkTo.Name : "any drifter with a message");
	}

	public override object Clone()
	{
		return new TalkObjective(this);
	}
}
[Serializable]
public class ZoomCameraObjective : QuestObjectiveBase
{
	[SerializeField]
	[HideInInspector]
	private string _name = "Zoom Camera";

	[SerializeField]
	private float _minimumZoom = 0.5f;

	[SerializeField]
	private bool _includePreviousZooms;

	private float _totalZoom;

	public ZoomCameraObjective()
	{
	}

	public ZoomCameraObjective(ZoomCameraObjective other)
		: base(other)
	{
		_minimumZoom = other._minimumZoom;
		_includePreviousZooms = other._includePreviousZooms;
		_totalZoom = other._totalZoom;
	}

	public override bool IsCompleted()
	{
		if (base.IsCompleted())
		{
			return true;
		}
		return ((!_includePreviousZooms || _totalZoom != 0f) ? _totalZoom : GameManager.GameStatsManager.TotalCameraZoomChanges) >= _minimumZoom;
	}

	public override void Initialize()
	{
		if (!InitializeIsCompleted())
		{
			GameEventDispatcher.AddListener(GameEventType.ManualCameraZoom, OnCameraZoomed);
		}
	}

	public override void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.ManualCameraZoom, OnCameraZoomed);
	}

	private void OnCameraZoomed(GameEvent gameEvent)
	{
		if (gameEvent is CameraGameEvent cameraGameEvent)
		{
			_totalZoom += Mathf.Abs(cameraGameEvent.Zoom);
			if (IsCompleted())
			{
				SetCompleted(completed: true);
			}
		}
	}

	protected override string GetNonLocalizedDescription()
	{
		return "Zoom Camera";
	}

	public override object Clone()
	{
		return new ZoomCameraObjective(this);
	}
}
public class Quest : IDialogueInteractable, IPersistentReference, IPanelContext, IPage, IComparable<IPage>
{
	public enum State
	{
		NotStarted,
		Started,
		Completed,
		Failed,
		Abandoned
	}

	[Serializable]
	public class PersistentData : PersistentReference<Quest>
	{
		private readonly int _persistentID = -1;

		[OptionalField(VersionAdded = 3)]
		private readonly ushort _questGiverID;

		private readonly State _questState;

		[OptionalField(VersionAdded = 3)]
		private readonly List<QuestVariableBase.IPersistentData> _variables;

		private readonly List<IQuestObjective.IPersistentData> _objectivesData = new List<IQuestObjective.IPersistentData>();

		[OptionalField(VersionAdded = 3)]
		private readonly bool _isWaitingForDelayedStart;

		[OptionalField(VersionAdded = 2)]
		private readonly ReplayableDialogue.PersistentData _replayableDialogue;

		public ushort QuestGiverID => _questGiverID;

		public PersistentData(Quest quest)
			: base(quest)
		{
			_persistentID = GameManager.PersistenceManager.ReturnPropertiesIndex(quest.Properties);
			if (quest.QuestGiver != null)
			{
				_questGiverID = quest.QuestGiver.UniqueID;
			}
			_questState = quest.QuestState;
			_isWaitingForDelayedStart = quest.IsWaitingForDelayedStart;
			if (!((IReadOnlyCollection<QuestVariableBase>)(object)quest.Variables).IsNullOrEmpty())
			{
				_variables = new List<QuestVariableBase.IPersistentData>();
				QuestVariableBase[] variables = quest.Variables;
				for (int i = 0; i < variables.Length; i++)
				{
					if (variables[i].TryGetPersistentData(out var persistentData))
					{
						_variables.Add(persistentData);
					}
				}
			}
			if (quest.Objectives != null)
			{
				foreach (IQuestObjective objective in quest.Objectives.Objectives)
				{
					_objectivesData.Add(objective.GetPersistentData());
				}
			}
			_replayableDialogue = ReplayableDialogue.PersistentData.Get(quest._replayableDialogue);
		}

		public override void Restore()
		{
			base.Restore();
			if (TryRestore(out var _))
			{
				StoryManager.RestoreQuest(base.Instance);
			}
		}

		public bool TryRestore(out Quest instance)
		{
			instance = null;
			if (GameManager.PersistenceManager.TryReturnPropertiesReference<QuestProperties>(_persistentID, out var reference))
			{
				base.Instance = new Quest(reference);
				if (!_variables.IsNullOrEmpty())
				{
					foreach (QuestVariableBase.IPersistentData variable in _variables)
					{
						RestoreVariable(variable);
					}
				}
				if (_objectivesData.Count > 0)
				{
					base.Instance.PopulateObjectives();
					base.Instance._objectivesDataToRestore = new List<IQuestObjective.IPersistentData>(_objectivesData);
				}
				else
				{
					base.Instance.Objectives = null;
				}
				base.Instance.QuestState = ((_questState != State.Started) ? _questState : State.NotStarted);
				if (_replayableDialogue != null)
				{
					_replayableDialogue.Restore(base.Instance._replayableDialogue);
				}
				instance = base.Instance;
			}
			return instance != null;
		}

		private void RestoreVariable(QuestVariableBase.IPersistentData persistentData)
		{
			if (base.Instance != null)
			{
				QuestVariableBase[] variables = base.Instance.Variables;
				for (int i = 0; i < variables.Length && !variables[i].TryRestorePersistentData(persistentData); i++)
				{
				}
			}
		}

		public void RestoreReferences()
		{
			if (ActorDescriptor.TryGet<AgentDescriptor>(out var actorDescriptor, _questGiverID))
			{
				base.Instance.QuestGiver = actorDescriptor;
			}
			if ((GameManager.Initialized && _questState == State.Started) || _isWaitingForDelayedStart)
			{
				base.Instance.Start();
			}
			QuestVariableBase[] variables = base.Instance.Variables;
			for (int i = 0; i < variables.Length; i++)
			{
				variables[i].RestoreReferences();
			}
		}
	}

	private readonly ReplayableDialogue _replayableDialogue = new ReplayableDialogue();

	private List<DialogueBranch> _dialogueBranches;

	private List<IQuestObjective.IPersistentData> _objectivesDataToRestore;

	public int PersistentIndex { get; set; } = -1;

	public QuestProperties Properties { get; }

	public virtual DialogueTreeProperties DialogueProperties
	{
		get
		{
			if (!(Properties.DialogueProperties != null))
			{
				if (!(QuestGiver != null) || !(QuestGiver.AgentProfile != null))
				{
					return null;
				}
				return QuestGiver.AgentProfile.DialogueProperties;
			}
			return Properties.DialogueProperties;
		}
	}

	public AgentDescriptor QuestGiver { get; private set; }

	public QuestVariableBase[] Variables { get; private set; }

	public QuestObjectives Objectives { get; private set; }

	public State QuestState { get; private set; }

	public bool IsCompleted => QuestState == State.Completed;

	public bool IsWaitingForDelayedStart { get; private set; }

	public bool Tracked { get; private set; }

	public PanelID PanelID => PanelID.Achievement;

	private bool IsQuest
	{
		get
		{
			if (Properties.QuestType != QuestType.Quest)
			{
				return Properties.QuestType == QuestType.Main;
			}
			return true;
		}
	}

	string IPage.ID => null;

	string IPage.Name => Properties.QuestTitle;

	Sprite IPage.Icon => null;

	string IPage.CompareString => null;

	public Quest(QuestProperties properties)
	{
		Properties = properties;
		Variables = new QuestVariableBase[Properties.Variables.Length];
		for (int i = 0; i < Properties.Variables.Length; i++)
		{
			Variables[i] = Properties.Variables[i].Clone() as QuestVariableBase;
		}
	}

	public Quest(QuestProperties properties, AgentDescriptor questGiver)
		: this(properties)
	{
		QuestGiver = questGiver;
	}

	~Quest()
	{
		Uninitialize();
	}

	public bool TryStart()
	{
		if (QuestState == State.NotStarted)
		{
			StartDialogue(this, Properties.QuestType == QuestType.DistressSignal);
			return true;
		}
		UnityEngine.Debug.Log("Unable to try and start quest '" + Properties.name + "'. It was already started");
		return false;
	}

	public IEnumerator DelayedStart(AgentDescriptor questGiver, float delay)
	{
		IsWaitingForDelayedStart = true;
		yield return new WaitForSeconds(delay);
		IsWaitingForDelayedStart = false;
		Start(questGiver);
	}

	public void Start(AgentDescriptor questGiver = null)
	{
		if (!IsWaitingForDelayedStart)
		{
			if (!CanBeStarted())
			{
				UnityEngine.Debug.LogException(new Exception($"Quest '{Properties}' is being started, but it has already been {QuestState}."));
			}
			if (QuestGiver == null || questGiver != null)
			{
				QuestGiver = questGiver;
			}
			QuestState = State.Started;
			InitializeDialogueTriggers();
			GameEventDispatcher.AddListener(GameEventType.WorldTileRemoved, OnWorldTileRemoved);
			GameEventDispatcher.AddListener(GameEventType.DialogueBranchConditionsTriggered, OnDialogueBranchConditionsTriggered);
			GameEventDispatcher.AddListener(GameEventType.DialogueStartRequest, OnDialogueStartRequest);
			if (_objectivesDataToRestore == null && TryGetEntryPoint(out var _))
			{
				_replayableDialogue.Start(this);
			}
			else
			{
				StartObjectives();
			}
		}
	}

	public void SetCompleted()
	{
		if (QuestState != State.Completed)
		{
			Uninitialize();
			QuestState = State.Completed;
			if (IsQuest && Properties.DialogueProperties.HasDialogueBranchType(DialogueBranchType.QuestCompleted))
			{
				StartDialogue(this);
			}
			else
			{
				OnQuestCompleted();
			}
		}
	}

	private void OnQuestCompleted()
	{
		if (Properties.ShowQuestCompletePanel)
		{
			GameManager.UIManager.DisplayPanel(this);
		}
		QuestEvent.DispatchQuestUpdated(this);
		QuestEvent.DispatchQuestCompleted(this);
	}

	public void SetFailed()
	{
		if (QuestState != State.Failed)
		{
			Uninitialize();
			QuestVariableBase[] variables = Variables;
			for (int i = 0; i < variables.Length; i++)
			{
				variables[i].Dispose();
			}
			QuestState = State.Failed;
			if (Properties.EndDialogueProperties != null)
			{
				_replayableDialogue.Start(Properties.EndDialogueProperties);
			}
			QuestEvent.DispatchQuestUpdated(this);
			QuestEvent.DispatchQuestFailed(this);
		}
	}

	public void StartTracking()
	{
		if (!Tracked)
		{
			Tracked = true;
			if (StoryManager.TrackedQuest != null)
			{
				StoryManager.TrackedQuest.Tracked = false;
			}
			StoryManager.TrackedQuest = this;
			QuestEvent.Dispatch(GameEventType.QuestTracked, this);
		}
	}

	public void StopTracking()
	{
		if (Tracked)
		{
			if (StoryManager.TrackedQuest == this)
			{
				StoryManager.TrackedQuest = null;
			}
			Tracked = false;
			QuestEvent.Dispatch(GameEventType.QuestTracked, this);
		}
	}

	public void RepeatLastDialogue()
	{
		_replayableDialogue.Replay();
	}

	public bool Validate()
	{
		QuestVariableBase[] variables = Variables;
		for (int i = 0; i < variables.Length; i++)
		{
			if (!variables[i].Validate())
			{
				return false;
			}
		}
		return true;
	}

	private void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.DialogueBranchConditionsTriggered, OnDialogueBranchConditionsTriggered);
		GameEventDispatcher.RemoveListener(GameEventType.DialogueStartRequest, OnDialogueStartRequest);
		GameEventDispatcher.RemoveListener(GameEventType.WorldTileRemoved, OnWorldTileRemoved);
		if (_dialogueBranches != null)
		{
			UninitializeDialogueBranches();
		}
		if (Objectives != null)
		{
			QuestObjectives objectives = Objectives;
			objectives.OnCompleted = (System.Action)Delegate.Remove(objectives.OnCompleted, new System.Action(OnObjectivesCompleted));
			QuestObjectives objectives2 = Objectives;
			objectives2.OnObjectiveTimedOut = (Action<IQuestObjective>)Delegate.Remove(objectives2.OnObjectiveTimedOut, new Action<IQuestObjective>(OnObjectiveTimedOut));
			Objectives.Uninitialize();
			Objectives = null;
		}
		QuestVariableBase[] variables = Variables;
		for (int i = 0; i < variables.Length; i++)
		{
			variables[i].ClearReferencingObjectives();
		}
	}

	private void InitializeDialogueTriggers()
	{
		if (PopulateObjectives())
		{
			Objectives.InitializeDialogueTriggers();
		}
	}

	private void StartObjectives()
	{
		if (QuestState != State.Completed && PopulateObjectives())
		{
			QuestObjectives objectives = Objectives;
			objectives.OnCompleted = (System.Action)Delegate.Combine(objectives.OnCompleted, new System.Action(OnObjectivesCompleted));
			QuestObjectives objectives2 = Objectives;
			objectives2.OnObjectiveTimedOut = (Action<IQuestObjective>)Delegate.Combine(objectives2.OnObjectiveTimedOut, new Action<IQuestObjective>(OnObjectiveTimedOut));
			if (_objectivesDataToRestore == null)
			{
				Objectives.Start();
			}
			else
			{
				Objectives.Restore(_objectivesDataToRestore);
			}
			_objectivesDataToRestore = null;
			InitializeDialogueBranches();
			if (QuestState != State.Failed)
			{
				QuestEvent.DispatchQuestStarted(this);
			}
		}
		else
		{
			UnityEngine.Debug.LogException(new Exception($"Quest '{Properties}' failed to start its objcective!"));
		}
		QuestEvent.DispatchQuestUpdated(this);
	}

	private void OnObjectivesCompleted()
	{
		QuestObjectives objectives = Objectives;
		objectives.OnCompleted = (System.Action)Delegate.Remove(objectives.OnCompleted, new System.Action(OnObjectivesCompleted));
		SetCompleted();
	}

	private void OnObjectiveTimedOut(IQuestObjective objective)
	{
		SetFailed();
	}

	private void StartDialogue(IDialogueInteractable dialogueInteractable, bool isRadioMessage = false)
	{
		_replayableDialogue.Start(dialogueInteractable, isRadioMessage);
	}

	private void InitializeDialogueBranches()
	{
		UninitializeDialogueBranches();
		_dialogueBranches = DialogueProperties.EntryBranches.Clone();
		foreach (DialogueBranch dialogueBranch in _dialogueBranches)
		{
			if (!dialogueBranch.TriggerConditions.IsNullOrEmpty())
			{
				dialogueBranch.Initialize();
			}
		}
	}

	private void UninitializeDialogueBranches()
	{
		if (_dialogueBranches != null)
		{
			foreach (DialogueBranch dialogueBranch in _dialogueBranches)
			{
				dialogueBranch.Uninitialize();
			}
		}
		_dialogueBranches = null;
	}

	private void OnDialogueBranchConditionsTriggered(GameEvent gameEvent)
	{
		if (!(gameEvent is DialogueGameEvent dialogueGameEvent) || dialogueGameEvent.SpecificBranchEntryNode == null)
		{
			return;
		}
		DialogueTreeProperties dialogueProperties = DialogueProperties;
		if (dialogueProperties == null)
		{
			return;
		}
		foreach (DialogueBranch entryBranch in dialogueProperties.EntryBranches)
		{
			if (entryBranch.EntryNode == dialogueGameEvent.SpecificBranchEntryNode)
			{
				_replayableDialogue.Start(dialogueProperties, dialogueGameEvent.SpecificBranchEntryNode);
				break;
			}
		}
	}

	private void OnDialogueStartRequest(GameEvent gameEvent)
	{
		if (gameEvent is DialogueGameEvent dialogueGameEvent && dialogueGameEvent.DialogueInteractable == this)
		{
			DialogueNodeProperties entryPoint;
			if (dialogueGameEvent.SpecificBranchEntryNode != null)
			{
				_replayableDialogue.RememberBranchForReplay(dialogueGameEvent.SpecificBranchEntryNode, dialogueGameEvent.DialogueInteractable);
			}
			else if (dialogueGameEvent.DialogueInteractable != this && dialogueGameEvent.DialogueInteractable != null && dialogueGameEvent.DialogueInteractable.TryGetEntryPoint(out entryPoint))
			{
				_replayableDialogue.RememberBranchForReplay(entryPoint, dialogueGameEvent.DialogueInteractable);
			}
		}
	}

	private bool PopulateObjectives()
	{
		if (Objectives == null)
		{
			QuestVariableBase[] variables = Variables;
			for (int i = 0; i < variables.Length; i++)
			{
				variables[i].SetOwningQuest(this);
			}
			Objectives = Properties.Objectives.Clone() as QuestObjectives;
			Objectives.SetOwningQuest(this);
		}
		return Objectives != null;
	}

	private bool CanBeStarted()
	{
		if (QuestState != State.NotStarted)
		{
			if (QuestState == State.Completed)
			{
				return Properties.IsRestartable;
			}
			return false;
		}
		return true;
	}

	public bool HasActiveVisibleObjectives()
	{
		if (IsCompleted || Properties.IsHidden || Objectives == null)
		{
			return false;
		}
		return Objectives.HasVisibleObjectives();
	}

	public void PopulateVisibleObjectives(List<IQuestObjective> visibleObjectives)
	{
		Objectives?.PopulateVisibleObjective(visibleObjectives);
	}

	public T GetVariableValue<T>(int id)
	{
		return GetVariableValue<T>(id);
	}

	public T GetVariableValue<T>(QuestObjectiveBase objective, int id)
	{
		QuestVariableBase[] variables = Variables;
		foreach (QuestVariableBase questVariableBase in variables)
		{
			if (questVariableBase.Id == id)
			{
				return questVariableBase.Get<T>(objective);
			}
		}
		return default(T);
	}

	public bool TryGetVariableValue<T>(int id, out T value) where T : class
	{
		return TryGetVariableValue<T>(null, id, out value);
	}

	public bool TryGetVariableValue<T>(QuestObjectiveBase objective, int id, out T value) where T : class
	{
		QuestVariableBase[] variables = Variables;
		foreach (QuestVariableBase questVariableBase in variables)
		{
			if (questVariableBase.Id == id)
			{
				value = questVariableBase.Get<T>(objective);
				return value != null;
			}
		}
		value = null;
		return false;
	}

	public void SetVariableValue<T>(int id, T value)
	{
		QuestVariableBase[] variables = Variables;
		foreach (QuestVariableBase questVariableBase in variables)
		{
			if (questVariableBase.Id == id)
			{
				questVariableBase.Set(value);
				break;
			}
		}
	}

	public bool TryGetActorDescriptor(DialogueContext.ActorType actorType, out AgentDescriptor actorDescriptor)
	{
		if (actorType == DialogueContext.ActorType.QuestGiver && QuestGiver != null)
		{
			actorDescriptor = QuestGiver;
			return true;
		}
		QuestVariableBase[] variables = Variables;
		for (int i = 0; i < variables.Length; i++)
		{
			if (variables[i] is ActorVariable actorVariable && actorVariable.TryGetActorDescriptor(actorType, out actorDescriptor))
			{
				return true;
			}
		}
		return StoryManager.DialogueContext.TryGetActor(actorType, out actorDescriptor);
	}

	public void OnDialogueResponse(DialogueResponseType response, Dialogue dialogue)
	{
		switch (QuestState)
		{
		case State.NotStarted:
			if (response == DialogueResponseType.Yes || Properties.QuestType == QuestType.DistressSignal)
			{
				StoryManager.StartQuest(this);
			}
			break;
		case State.Started:
			if (response == DialogueResponseType.EndOfDialogue && (Objectives == null || !Objectives.IsStarted))
			{
				StartObjectives();
			}
			break;
		case State.Completed:
			if (response == DialogueResponseType.EndOfDialogue)
			{
				OnQuestCompleted();
			}
			break;
		}
	}

	public bool TryGetEntryPoint(out DialogueNodeProperties entryPoint)
	{
		entryPoint = null;
		if (DialogueProperties == null)
		{
			UnityEngine.Debug.LogException(new Exception($"Quest '{Properties}' has now dialogue properties set."));
			return false;
		}
		switch (QuestState)
		{
		case State.NotStarted:
			if (Properties.QuestType == QuestType.DistressSignal)
			{
				entryPoint = DialogueProperties.ReturnBranchEntryNode(DialogueBranchType.DistressSignal);
			}
			else
			{
				entryPoint = DialogueProperties.ReturnBranchEntryNode(DialogueBranchType.QuestGiver);
			}
			break;
		case State.Started:
			entryPoint = DialogueProperties.ReturnBranchEntryNode(DialogueBranchType.QuestAccepted);
			break;
		case State.Completed:
			if (Properties.QuestType != QuestType.DistressSignal)
			{
				entryPoint = DialogueProperties.ReturnBranchEntryNode(DialogueBranchType.QuestCompleted);
			}
			else
			{
				entryPoint = null;
			}
			break;
		default:
			UnityEngine.Debug.LogException(new NotImplementedException());
			entryPoint = null;
			break;
		}
		return entryPoint != null;
	}

	public bool TryGetMainSpeaker(out AgentDescriptor mainSpeaker)
	{
		mainSpeaker = QuestGiver;
		return true;
	}

	public int CompareTo(IPage other)
	{
		throw new NotImplementedException();
	}

	private void OnWorldTileRemoved(GameEvent gameEvent)
	{
		QuestVariableBase[] variables = Variables;
		for (int i = 0; i < variables.Length; i++)
		{
			if (!variables[i].Validate())
			{
				SetFailed();
				break;
			}
		}
	}
}
[Serializable]
public class QuestObjectives : ICloneable
{
	[Serializable]
	public class ObjectivesGroup
	{
		public List<int> Group = new List<int>();
	}

	private struct TimedObjective
	{
		public IQuestObjective Objective;

		public int DaysLeft;

		public TimedObjective(IQuestObjective objective, int daysLeft)
		{
			Objective = objective;
			DaysLeft = daysLeft;
		}
	}

	[SerializeField]
	[Tooltip("Groups of objective indexes that will show together on the UI. We show the next group when all the objectives of the previous one are completed")]
	[FormerlySerializedAs("_objectiveUIGroups")]
	private List<ObjectivesGroup> _objectiveGroups = new List<ObjectivesGroup>();

	[SerializeReference]
	[InstantiateSerializeReference]
	private List<IQuestObjective> _objectives = new List<IQuestObjective>();

	public System.Action OnCompleted;

	public Action<IQuestObjective> OnObjectiveTimedOut;

	private WeakReference<Quest> _owningQuest;

	private int _currentObjectivesGroupIndex = -1;

	private readonly List<IQuestObjective> _currentObjectivesGroup = new List<IQuestObjective>();

	private bool _isCompleted;

	public IReadOnlyList<IQuestObjective> Objectives => _objectives;

	public IReadOnlyList<ObjectivesGroup> ObjectiveGroups => _objectiveGroups;

	public IReadOnlyList<IQuestObjective> CurrentObjectivesGroup => _currentObjectivesGroup;

	public bool IsStarted => _currentObjectivesGroupIndex != -1;

	public void SetOwningQuest(Quest owningQuest)
	{
		_owningQuest = new WeakReference<Quest>(owningQuest);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.SetOwningQuest(owningQuest);
		}
	}

	public void InitializeDialogueTriggers()
	{
		foreach (IQuestObjective objective in _objectives)
		{
			objective.InitializeDialogueTriggers();
		}
	}

	public void Start()
	{
		foreach (IQuestObjective objective in _objectives)
		{
			objective.Initialize();
		}
		if (IsCompleted())
		{
			SetCompleted();
			return;
		}
		SetCurrentObjectivesGroupID(0);
		GameEventDispatcher.AddListener(GameEventType.QuestObjectiveUpdated, OnQuestObjectiveUpdated);
		FinalUpdate.RegisterEndOfFrameOneShot(CheckObjectivesCompletion);
	}

	~QuestObjectives()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestObjectiveUpdated, OnQuestObjectiveUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.Uninitialize();
			objective.UninitializeDialogueTriggers();
		}
	}

	public void SetCompleted()
	{
		if (!_isCompleted)
		{
			_isCompleted = true;
			Uninitialize();
			OnCompleted.SafeInvoke();
			OnCompleted = null;
		}
	}

	public void ShowNextObjectivesGroup(Quest owningQuest)
	{
		SetCurrentObjectivesGroupID(_currentObjectivesGroupIndex + 1);
		foreach (IQuestObjective item in CurrentObjectivesGroup)
		{
			item.TriggerShownToPlayer();
		}
		if (owningQuest != null)
		{
			QuestEvent.DispatchQuestUpdated(owningQuest);
		}
	}

	private void ShowNextObjectivesGroup()
	{
		if (_owningQuest.TryGetTarget(out var target) && target.Properties.QuestType != QuestType.Tutorial)
		{
			ShowNextObjectivesGroup(target);
		}
	}

	public int GetRemainingDaysCount(IQuestObjective objective)
	{
		UnityEngine.Debug.LogException(new NotImplementedException());
		return 0;
	}

	private void SetCurrentObjectivesGroupID(int id)
	{
		if (id == _currentObjectivesGroupIndex)
		{
			return;
		}
		bool flag = _objectiveGroups.IsValidIndex(id);
		if (flag && IsObjectivesGroupCompleted(id))
		{
			SetCurrentObjectivesGroupID(++id);
			return;
		}
		using ListPool<IQuestObjective>.List list = ListPool<IQuestObjective>.Get(_currentObjectivesGroup);
		_currentObjectivesGroupIndex = id;
		_currentObjectivesGroup.Clear();
		if (flag)
		{
			foreach (int item in _objectiveGroups[_currentObjectivesGroupIndex].Group)
			{
				if (item >= _objectives.Count)
				{
					UnityEngine.Debug.LogError($"Objectives group number {_currentObjectivesGroupIndex} has an index out of range of the objectives! ({item})!");
					continue;
				}
				IQuestObjective questObjective = _objectives[item];
				if (list.Contains(questObjective))
				{
					questObjective.TriggerObjectivesGroupCompleted();
					list.Remove(questObjective);
				}
				else
				{
					questObjective.SetActive(active: true);
				}
				_currentObjectivesGroup.Add(questObjective);
			}
		}
		foreach (IQuestObjective item2 in list)
		{
			item2.SetActive(active: false);
			item2.TriggerObjectivesGroupCompleted();
		}
		CheckObjectivesCompletion();
	}

	private void OnQuestObjectiveUpdated(GameEvent gameEvent)
	{
		CheckObjectivesCompletion();
	}

	private void CheckObjectivesCompletion()
	{
		List<int> list = _objectiveGroups[_currentObjectivesGroupIndex].Group;
		bool flag = true;
		bool flag2 = true;
		for (int i = 0; i < _objectives.Count; i++)
		{
			IQuestObjective questObjective = _objectives[i];
			if (!questObjective.IsOptional && !questObjective.IsCompleted())
			{
				flag = false;
				if (list.Contains(i))
				{
					flag2 = false;
					break;
				}
			}
		}
		if (flag)
		{
			SetCompleted();
		}
		else if (flag2)
		{
			FinalUpdate.RegisterEndOfFrameOneShot(ShowNextObjectivesGroup);
		}
	}

	private void OnPanelClosed(GameEvent gameEvent = null)
	{
		if (gameEvent == null || gameEvent is PanelEvent { ID: PanelID.DialoguePanel })
		{
			GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
			ShowNextObjectivesGroup();
		}
	}

	public void Uninitialize()
	{
		GameEventDispatcher.RemoveListener(GameEventType.QuestObjectiveUpdated, OnQuestObjectiveUpdated);
		GameEventDispatcher.RemoveListener(GameEventType.PanelClosed, OnPanelClosed);
		foreach (IQuestObjective objective in _objectives)
		{
			objective.Uninitialize();
			objective.UninitializeDialogueTriggers();
		}
	}

	public object Clone()
	{
		return new QuestObjectives
		{
			_isCompleted = _isCompleted,
			_objectiveGroups = _objectiveGroups,
			_objectives = _objectives.Clone()
		};
	}

	public bool IsCompleted()
	{
		return AreObjectivesCompleted(_objectives);
	}

	private bool AreObjectivesCompleted(List<IQuestObjective> objectives)
	{
		foreach (IQuestObjective objective in objectives)
		{
			if (!objective.IsOptional && !objective.IsCompleted())
			{
				return false;
			}
		}
		return true;
	}

	private bool IsObjectivesGroupCompleted(int objectivesGroupIndex)
	{
		foreach (int item in _objectiveGroups[objectivesGroupIndex].Group)
		{
			IQuestObjective questObjective = _objectives[item];
			if (!questObjective.IsOptional && !questObjective.IsCompleted())
			{
				return false;
			}
		}
		return true;
	}

	public bool HasVisibleObjectives()
	{
		if (CurrentObjectivesGroup.IsNullOrEmpty())
		{
			return false;
		}
		foreach (IQuestObjective item in CurrentObjectivesGroup)
		{
			if (!item.IsHidden)
			{
				return true;
			}
		}
		return false;
	}

	public void PopulateVisibleObjective(List<IQuestObjective> visibleObjectives)
	{
		if (CurrentObjectivesGroup.IsNullOrEmpty())
		{
			return;
		}
		foreach (IQuestObjective item in CurrentObjectivesGroup)
		{
			if (!item.IsHidden)
			{
				visibleObjectives.Add(item);
			}
		}
	}

	public void Restore(List<IQuestObjective.IPersistentData> objectivesDataToRestore)
	{
		if (_objectives.IsNullOrEmpty())
		{
			return;
		}
		foreach (IQuestObjective objective in _objectives)
		{
			int count = objectivesDataToRestore.Count;
			while (0 < count--)
			{
				if ((!PersistenceManager.DoesSaveInfoVersionComeBefore(0, 8, 6) || objectivesDataToRestore[count].ObjectiveHashCode == objective.GetHashCode()) && objectivesDataToRestore[count].ObjectiveHashCode == objective.UniqueID)
				{
					if (!objectivesDataToRestore[count].TryRestore(objective))
					{
						UnityEngine.Debug.LogException(new PersistenceException($"Could not restore objective {objective}!"));
					}
					objectivesDataToRestore.RemoveAt(count);
					break;
				}
			}
			objective.Initialize();
		}
		for (int i = 0; i < _objectiveGroups.Count; i++)
		{
			foreach (int item in _objectiveGroups[i].Group)
			{
				if (!_objectives[item].IsCompleted() && !_objectives[item].IsOptional)
				{
					SetCurrentObjectivesGroupID(i);
					GameEventDispatcher.AddListener(GameEventType.QuestObjectiveUpdated, OnQuestObjectiveUpdated);
					FinalUpdate.RegisterEndOfFrameOneShot(delegate
					{
						CheckObjectivesCompletion();
					});
					return;
				}
			}
		}
		if (objectivesDataToRestore.Count > 0)
		{
			UnityEngine.Debug.LogException(new PersistenceException("Could not restore all current objectives data!"));
		}
		else
		{
			SetCompleted();
		}
	}
}
