	{
		int count = GameManager.TimeManager.Days.Count;
		int radioBuiltDay = GameManager.RadioMessagesManager.RadioBuiltDay;
		if (radioBuiltDay < 0 || count - radioBuiltDay < _radioBuiltDays)
		{
			return count >= _totalDays;
		}
		return true;
	}
}
