public static class PathHelper
{
	public static string ConstructPath(params string[] pathParts)
	{
		if (pathParts.Length == 0)
		{
			return string.Empty;
		}
		string text = pathParts[0];
		for (int i = 1; i < pathParts.Length; i++)
		{
			text = text + Path.DirectorySeparatorChar + pathParts[i];
		}
		return text;
	}
}
public class RecordingCameraController : MonoBehaviour
{
	[Header("General")]
	[Tooltip("List of all the saved cameras.")]
	public List<CameraPresetProperties> SavedCameras = new List<CameraPresetProperties>();

	[Header("Speeds")]
	[Tooltip("Move speed of the camera.")]
	public float MoveSpeed = 50f;

	[Tooltip("Rotation speed of the camera.")]
	public float RotationSpeed = 50f;

	[SerializeField]
	[Tooltip("The speed at which speed gets incremented.")]
	private float _speedIncrement = 3f;

	[HideInInspector]
	public bool UseLocalUpAxis;

	[HideInInspector]
	public GameObject TurnaroundGameObject;

	[HideInInspector]
	public float TurnaroundVerticalAngle = 35f;

	[HideInInspector]
	public float TurnaroundSpeed = 10f;

	[HideInInspector]
	public float TurnaroundRadius = 50f;

	[HideInInspector]
	public float TurnaroundHeightOffset;

	private bool _controllerVerticalArrowPressed;

	private int _currentCameraSave;

	private float _turnaroundHorizontalAngle;

	public Camera Camera { get; private set; }

	public int CurrentCameraSave => _currentCameraSave;

	private void Awake()
	{
		Camera = GetComponent<Camera>();
	}

	private void Update()
	{
		if (GameManager.Gamepaused || CameraController.MainCamera != Camera)
		{
			return;
		}
		if (TurnaroundGameObject != null)
		{
			_turnaroundHorizontalAngle += Time.deltaTime * TurnaroundSpeed;
			float f = TurnaroundVerticalAngle * (MathF.PI / 180f);
			float f2 = _turnaroundHorizontalAngle * (MathF.PI / 180f);
			float num = Mathf.Sin(f) * TurnaroundRadius;
			float num2 = (1f - num / TurnaroundRadius) * TurnaroundRadius;
			float x = Mathf.Cos(f2) * num2 + TurnaroundGameObject.transform.position.x;
			float y = num + TurnaroundGameObject.transform.position.y;
			float z = Mathf.Sin(f2) * num2 + TurnaroundGameObject.transform.position.z;
			base.transform.position = new Vector3(x, y, z);
			base.transform.LookAt(TurnaroundGameObject.transform);
			base.transform.position += Vector3.up * TurnaroundHeightOffset;
		}
		else
		{
			CameraControls();
			CameraSaveControls();
			if (UnityEngine.Input.GetButtonDown("Controller X&B") && UnityEngine.Input.GetAxisRaw("Controller X&B") < 0f)
			{
				WaterManager.Instance.PauseWater();
			}
		}
	}

	public void CameraControls()
	{
		float axis = UnityEngine.Input.GetAxis("Cinematic Horizontal");
		float axis2 = UnityEngine.Input.GetAxis("Cinematic Forward");
		float num = UnityEngine.Input.GetAxis("Cinematic Vertical Up") - UnityEngine.Input.GetAxis("Cinematic Vertical Down");
		float axis3 = UnityEngine.Input.GetAxis("Cinematic Horizontal Rotation");
		float axis4 = UnityEngine.Input.GetAxis("Cinematic Vertical Rotation");
		float axis5 = UnityEngine.Input.GetAxis("Controller Vertical Arrows");
		if (axis5 != 0f)
		{
			if (!_controllerVerticalArrowPressed)
			{
				_controllerVerticalArrowPressed = true;
				if (axis5 < 0f)
				{
					GameManager.UIManager.ToggleUIEnabled();
				}
				else
				{
					UseLocalUpAxis = !UseLocalUpAxis;
				}
			}
		}
		else
		{
			_controllerVerticalArrowPressed = false;
		}
		if (UnityEngine.Input.GetButton("Cinematic Speed"))
		{
			MoveSpeed += UnityEngine.Input.GetAxis("Cinematic Speed") * _speedIncrement;
			MoveSpeed = Mathf.Clamp(MoveSpeed, 0f, MoveSpeed);
		}
		RotationSpeed += UnityEngine.Input.GetAxis("Controller Horizontal Arrows") * _speedIncrement;
		RotationSpeed = Mathf.Clamp(RotationSpeed, 0f, RotationSpeed);
		Vector3 zero = Vector3.zero;
		zero.x = axis * MoveSpeed * Time.deltaTime;
		zero.y = num * MoveSpeed * Time.deltaTime;
		zero.z = axis2 * MoveSpeed * Time.deltaTime;
		Vector3 zero2 = Vector3.zero;
		zero2.y = axis3 * RotationSpeed * Time.deltaTime;
		zero2.x = axis4 * RotationSpeed * Time.deltaTime;
		base.transform.Translate(zero.x, 0f, zero.z);
		base.transform.Translate(0f, zero.y, 0f, UseLocalUpAxis ? Space.Self : Space.World);
		base.transform.Rotate(Vector3.up, zero2.y, Space.World);
		base.transform.Rotate(Vector3.right, zero2.x, Space.Self);
	}

	private void CameraSaveControls()
	{
		if (UnityEngine.Input.GetButtonDown("CycleSavedCameras"))
		{
			CycleSavedCamera((int)UnityEngine.Input.GetAxisRaw("CycleSavedCameras"));
		}
		else if (UnityEngine.Input.GetButtonDown("OverrideSavedCamera"))
		{
			OverwriteCurrentCamera();
		}
		else if (UnityEngine.Input.GetButtonDown("ResetToCurrentSavedCamera"))
		{
			ResetCurrentCamera();
		}
	}

	public void ResetCurrentCamera()
	{
		UpdateCurrentCamera(GetCurrentSavedCamera());
	}

	public void OverwriteCurrentCamera()
	{
		CameraPresetProperties cameraPresetProperties = SavedCameras[_currentCameraSave];
		cameraPresetProperties.Position = base.transform.position;
		cameraPresetProperties.Rotation = base.transform.eulerAngles;
		cameraPresetProperties.FOV = Camera.fieldOfView;
	}

	public void CycleSavedCamera(int direction)
	{
		int num = _currentCameraSave + direction;
		if (num < 0)
		{
			num = SavedCameras.Count - 1;
		}
		else if (num >= SavedCameras.Count)
		{
			num = 0;
		}
		_currentCameraSave = num;
		UpdateCurrentCamera(GetCurrentSavedCamera());
	}

	public void SetSavedCamera(int index)
	{
		_currentCameraSave = index;
		UpdateCurrentCamera(GetCurrentSavedCamera());
	}

	private void UpdateCurrentCamera(CameraPresetProperties savedCamera)
	{
		base.transform.position = savedCamera.Position;
		base.transform.eulerAngles = savedCamera.Rotation;
		Camera.fieldOfView = savedCamera.FOV;
	}

	public CameraPresetProperties GetCurrentSavedCamera()
	{
		return SavedCameras[_currentCameraSave];
	}
}
public class BrokenSaveReport : FormField
{
	[SerializeField]
	private string _reportTitle = "Broken Save File";

	[SerializeField]
	[Min(0f)]
	private int _trelloListIndex = 2;

	private static readonly HashSet<string> _reportedBrokenSaveFiles = new HashSet<string>(4);

	private System.Action _onSucceededCallback;

	private System.Action _onFailedCallback;

	private bool _formWasSubmitted;

	private void OnDestroy()
	{
		if ((bool)Form)
		{
			Form.OnSubmissionSucceeded.RemoveListener(OnReportSucceeded);
			Form.OnSubmissionFailed.RemoveListener(OnReportFailed);
		}
		_onSucceededCallback = null;
		_onFailedCallback = null;
	}

	public bool CanReportSave(string saveName)
	{
		return !_reportedBrokenSaveFiles.Contains(saveName);
	}

	public void Submit(System.Action onSucceededCallback = null, System.Action onFailedCallback = null)
	{
		_formWasSubmitted = false;
		_onSucceededCallback = onSucceededCallback;
		_onFailedCallback = onFailedCallback;
		Form.Show();
	}

	protected override void FormOpened()
	{
		Form.OnSubmissionSucceeded.AddListener(OnReportSucceeded);
		Form.OnSubmissionFailed.AddListener(OnReportFailed);
		Report currentReport = Form.CurrentReport;
		currentReport.Title = _reportTitle;
		if (Form.Config != null && Form.Config.Board.Labels.TryFind(out var foundItem, (Label label) => label.name == "High Priority"))
		{
			currentReport.AddLabel(foundItem);
		}
		currentReport.List.id = Form.Config.Board.CategoryIds.GetValueClamped(_trelloListIndex);
		currentReport.List.name = Form.Config.Board.CategoryNames.GetValueClamped(_trelloListIndex);
		currentReport.AddSection("Detail");
		currentReport["Detail"].SetText("The attached Save File was unable to be loaded.\nPlease see the attached logs and stack trace for more information.");
	}

	protected override void FormSubmitted()
	{
		SaveMetaInfo saveMetaInfo = PersistenceManager.SaveMetaInfo;
		_formWasSubmitted = true;
		if (saveMetaInfo != null)
		{
			try
			{
				Form.CurrentReport.AttachFile("[Broken - " + saveMetaInfo.CommunityName + "] " + saveMetaInfo.Name + ".fs", File.ReadAllBytes(saveMetaInfo.Path));
			}
			catch (Exception exception)
			{
				UnityEngine.Debug.LogException(exception);
			}
		}
	}

	private void OnReportSucceeded()
	{
		if (PersistenceManager.SaveMetaInfo != null)
		{
			_reportedBrokenSaveFiles.Add(PersistenceManager.SaveMetaInfo.Name);
		}
		_onSucceededCallback.SafeInvoke();
		_onSucceededCallback = null;
		_onFailedCallback = null;
	}

	private void OnReportFailed()
	{
		_onFailedCallback.SafeInvoke();
		_onSucceededCallback = null;
		_onFailedCallback = null;
		_formWasSubmitted = false;
	}

	protected override void FormClosed()
	{
		Form.OnSubmissionSucceeded.RemoveListener(OnReportSucceeded);
		Form.OnSubmissionFailed.RemoveListener(OnReportFailed);
		if (!_formWasSubmitted)
		{
			OnReportFailed();
		}
	}
}
public class OutlinePass : ScriptableRenderPass
{
	private class RasterPassData
	{
		internal OutlinePass This;

		internal bool IsHighlight;
	}

	private static readonly Color _bufferClearColor = new Color(0f, 0f, 0f, 0f);

	private OutlineRenderFeature.Materials _materials;

	private MaterialPropertyBlock _mpb = new MaterialPropertyBlock();

	private TextureHandle _source;

	private TextureHandle _destination;

	private TextureHandle _outline;

	private TextureHandle _outlineComposite;

	private TextureHandle _outlinePingPong;

	private const string cString_OutlineColor = "_Color";

	private const string cString_OutlineBlurOffset = "_BlurOffset";

	private const string cString_Intensity = "_Intensity";

	private const string cString_Outline = "_Outline";

	private const string cSting_Cutout = "_Cutout";

	private const string cString_Original = "_Original";

	public readonly int OutlineColorMatId = Shader.PropertyToID("_Color");

	private static readonly int _outlineBlurOffsetMatID = Shader.PropertyToID("_BlurOffset");

	private static readonly int _intensityMatID = Shader.PropertyToID("_Intensity");

	private static readonly int _outlineMatID = Shader.PropertyToID("_Outline");

	private static readonly int _cutoutMatID = Shader.PropertyToID("_Cutout");

	private static readonly int _originalMatID = Shader.PropertyToID("_Original");

	protected OutlineRenderFeature.Settings Settings { get; private set; }

	public Material NoHighlightMaterial { get; private set; }

	public Material HighlightMaterial { get; private set; }

	public OutlinePass(OutlineRenderFeature.Settings settings, OutlineRenderFeature.Materials materials)
	{
		Settings = settings;
		_materials = materials;
		base.renderPassEvent = settings.RenderPassEvent;
		if ((bool)settings.RenderMaterialOverride)
		{
			NoHighlightMaterial = new Material(settings.RenderMaterialOverride);
		}
		else
		{
			NoHighlightMaterial = new Material(Shader.Find("Custom/PostProcessing/CommandBufferPP/Outline/OutlineReplacement"));
		}
		if (NoHighlightMaterial == null)
		{
			UnityEngine.Debug.LogError("[CommandBufferPP_Silhouette] - UNABLE TO LOAD A VALID RENDER MATERIAL.");
		}
		HighlightMaterial = new Material(NoHighlightMaterial);
		if ((bool)settings.ColorDefinition)
		{
			NoHighlightMaterial.SetColor(OutlineColorMatId, settings.ColorDefinition.OutlineColor);
			HighlightMaterial.SetColor(OutlineColorMatId, settings.ColorDefinition.HighlightColor);
		}
		else
		{
			NoHighlightMaterial.SetColor(OutlineColorMatId, settings.OutlineColor);
			HighlightMaterial.SetColor(OutlineColorMatId, settings.OutlineHighlightedColor);
		}
	}

	public override void RecordRenderGraph(RenderGraph renderGraph, ContextContainer frameData)
	{
		UniversalResourceData universalResourceData = frameData.Get<UniversalResourceData>();
		UniversalCameraData universalCameraData = frameData.Get<UniversalCameraData>();
		RenderTextureDescriptor desc = new RenderTextureDescriptor(universalCameraData.cameraTargetDescriptor.width, universalCameraData.cameraTargetDescriptor.height, RenderTextureFormat.ARGB32, 0);
		desc.useMipMap = false;
		_source = universalResourceData.activeColorTexture;
		_outline = UniversalRenderer.CreateRenderGraphTexture(renderGraph, desc, "Outline", clear: false);
		_outlineComposite = UniversalRenderer.CreateRenderGraphTexture(renderGraph, desc, "Outline  Composite", clear: false);
		_outlinePingPong = UniversalRenderer.CreateRenderGraphTexture(renderGraph, desc, "Ping Pong Texture", clear: false);
		ExecuteOutlinePass(renderGraph, isHighlight: false, _source, _outlineComposite);
		ExecuteOutlinePass(renderGraph, isHighlight: true, _outlineComposite, _outlinePingPong);
		universalResourceData.cameraColor = _outlinePingPong;
	}

	private void ExecuteOutlinePass(RenderGraph renderGraph, bool isHighlight, TextureHandle source, TextureHandle destination)
	{
		RasterPassData passData;
		using (IRasterRenderGraphBuilder rasterRenderGraphBuilder = renderGraph.AddRasterRenderPass<RasterPassData>("Outline - Highlight " + (isHighlight ? "On" : "Off"), out passData, "F:\\workspace\\p\\Assets\\Code\\URP\\Outline\\OutlinePass.cs", 109))
		{
			passData.This = this;
			passData.IsHighlight = isHighlight;
			rasterRenderGraphBuilder.AllowPassCulling(value: false);
			rasterRenderGraphBuilder.SetRenderAttachment(destination, 0);
			rasterRenderGraphBuilder.SetRenderFunc<RasterPassData>(ExecuteRasterGraphPass);
		}
		RenderOutline(renderGraph, destination, _outline);
		RenderComposite(renderGraph, source, destination, _materials.Composite);
	}

	private void RenderOutline(RenderGraph renderGraph, TextureHandle source, TextureHandle destination)
	{
		_materials.Outline.SetFloat(_intensityMatID, Settings.BlurIntensityFalloff);
		_materials.Outline.SetFloat(_outlineBlurOffsetMatID, Settings.BlurMinSpread);
		Blit(renderGraph, source, destination, _materials.Outline, 0, "Outline - Outline");
	}

	private void RenderComposite(RenderGraph renderGraph, TextureHandle Source, TextureHandle Destination, Material material)
	{
		if ((bool)material)
		{
			RenderGraphUtils.BlitMaterialParameters blitParameters = new RenderGraphUtils.BlitMaterialParameters(Source, Destination, material, 0);
			RenderGraphBlitUtility.AddBlitPass(renderGraph, blitParameters, delegate(IUnsafeRenderGraphBuilder builder)
			{
				builder.UseTexture(in _outline);
			}, delegate(MaterialPropertyBlock mpb)
			{
				mpb.SetTexture(_outlineMatID, _outline);
			}, "Composite Pass", "F:\\workspace\\p\\Assets\\Code\\URP\\Outline\\OutlinePass.cs", 136);
		}
		else
		{
			Blit(renderGraph, Source, Destination);
		}
	}

	private static void ExecuteRasterGraphPass(RasterPassData passData, RasterGraphContext context)
	{
		context.cmd.ClearRenderTarget(clearDepth: true, clearColor: true, _bufferClearColor);
		OutlineRenderManager.Instance.FillBuffer(passData.This, passData.IsHighlight, context.cmd);
	}

	private void Blit(RenderGraph renderGraph, TextureHandle source, TextureHandle destination, string passName = "Outline - Blit")
	{
		renderGraph.AddBlitPass(source, destination, Vector2.one, Vector2.zero, 0, 0, -1, 0, 0, 1, RenderGraphUtils.BlitFilterMode.ClampBilinear, passName, returnBuilder: false, "F:\\workspace\\p\\Assets\\Code\\URP\\Outline\\OutlinePass.cs", 160);
	}

	private void Blit(RenderGraph renderGraph, TextureHandle source, TextureHandle destination, Material material, int shaderPass = 0, string passName = "Outline - Blit w. Material")
	{
		RenderGraphUtils.BlitMaterialParameters blitParameters = new RenderGraphUtils.BlitMaterialParameters(source, destination, material, shaderPass);
		renderGraph.AddBlitPass(blitParameters, passName, returnBuilder: false, "F:\\workspace\\p\\Assets\\Code\\URP\\Outline\\OutlinePass.cs", 166);
	}

	public Material ReturnRenderingMaterial(bool isHighlight)
	{
		if (!isHighlight)
		{
			return NoHighlightMaterial;
		}
		return HighlightMaterial;
	}
}
public class OutlineRenderFeature : ScriptableRendererFeature
{
	[Serializable]
	public class Settings
	{
		[Header("Mode")]
		public bool _singlePass = true;

		[Header("Command Buffer")]
		public RenderPassEvent RenderPassEvent = RenderPassEvent.BeforeRenderingPostProcessing;

		[Header("Outline")]
		public Material RenderMaterialOverride;

		public bool UpdateOutlineColorsEachFrame;

		[Space(10f)]
		public Color OutlineColor = new Color(0.75f, 0.75f, 0.75f, 1f);

		public Color OutlineHighlightedColor = new Color(1f, 1f, 1f, 1f);

		[Space(10f)]
		public OutlineColorDefinitionScriptableObject ColorDefinition;

		[Space(10f)]
		[Tooltip("How many times do we want to blur our shape?")]
		public int BlurIterations = 3;

		[Tooltip("With each blur how far should we spread the shape in all six directions (in pixels)")]
		public int BlurMinSpread = 1;

		[Tooltip("How much should the blurminspread increase with each blur iteration? (ex:BlurIterations = 3,BlurMinSpread = 1,BlurIterationSpread = 3 -> blur at iteration 3 will be 1+(3*3) ")]
		public int BlurIterationSpread;

		[Range(0f, 1f)]
		[Tooltip("Controls how much the blur alpha should be reduced with each blur pass. Lower values= soft feather. 1 =  hard outline")]
		public float BlurIntensityFalloff = 1f;
	}

	public struct Materials
	{
		public Material Outline;

		public Material Composite;
	}

	public Settings settings;

	[Header("Shaders")]
	[SerializeField]
	private Shader _outlineShader;

	[SerializeField]
	private Shader _compositeShader;

	private OutlinePass _pass;

	private Materials _materials;

	public override void Create()
	{
		_materials = new Materials
		{
			Outline = CoreUtils.CreateEngineMaterial(_outlineShader),
			Composite = CoreUtils.CreateEngineMaterial(_compositeShader)
		};
		if (settings._singlePass)
		{
			_pass = new OutlinePass(settings, _materials);
		}
	}

	public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
	{
		if (_pass != null)
		{
			renderer.EnqueuePass(_pass);
		}
	}

	protected override void Dispose(bool disposing)
	{
		base.Dispose(disposing);
	}
}
