public static class ListPool<T>
{
	public class List : List<T>, IDisposable
	{
		private bool _isPooled;

		public List()
		{
		}

		public List(int capacity)
			: base(capacity)
		{
		}

		public List(IEnumerable<T> collection)
			: base(collection)
		{
		}

		public new void Add(T item)
		{
			if (_isPooled)
			{
				throw new NotSupportedException($"Adding items to a pooled list of type {typeof(T).ToString()} is not support!");
			}
			base.Add(item);
		}

		public new void AddRange(IEnumerable<T> collection)
		{
			if (_isPooled)
			{
				throw new NotSupportedException($"Adding items to a pooled list of type {typeof(T).ToString()} is not support!");
			}
			base.AddRange(collection);
		}

		public void Dispose()
		{
			if (_isPooled)
			{
				UnityEngine.Debug.LogWarning("A PooledList.List that is pooled cannot be pooled again!");
				return;
			}
			Clear();
			ListPool<T>._stack.Push(this);
			_isPooled = true;
		}

		public static List Get()
		{
			if (ListPool<T>._stack.Count == 0)
			{
				return new List();
			}
			List list = ListPool<T>._stack.Pop();
			list._isPooled = false;
			return list;
		}

		public static List Get(int minimumCapacity)
		{
			if (ListPool<T>._stack.Count == 0)
			{
				return new List(minimumCapacity);
			}
			List list = ListPool<T>._stack.Pop();
			list._isPooled = false;
			if (list.Capacity < minimumCapacity)
			{
				list.Capacity = minimumCapacity;
			}
			return list;
		}

		public static List Get(IEnumerable<T> collection)
		{
			if (ListPool<T>._stack.Count == 0)
			{
				return new List(collection);
			}
			List list = ListPool<T>._stack.Pop();
			list._isPooled = false;
			list.AddRange(collection);
			return list;
		}

		public static List Get(params T[] items)
		{
			if (ListPool<T>._stack.Count == 0)
			{
				return new List(items);
			}
			List list = ListPool<T>._stack.Pop();
			list._isPooled = false;
			list.AddRange(items);
			return list;
		}
	}

	private static Stack<List> _stack = new Stack<List>();

	public static List Get()
	{
		return List.Get();
	}

	public static List Get(int minimumCapacity)
	{
		return List.Get(minimumCapacity);
	}

	public static List Get(IEnumerable<T> collection)
	{
		return List.Get(collection);
	}

	public static List Get(params T[] items)
	{
		return List.Get(items);
	}

	public static void Add(List<T> list)
	{
		if (!(list is List list2))
		{
			UnityEngine.Debug.LogWarning("Trying to pool a list that is not poolable. This is a memory leak!");
		}
		else
		{
			list2.Dispose();
		}
	}

	public static void Add(List list)
	{
		list.Dispose();
	}

	public static bool ReturnIsPooled(List<T> list)
	{
		if (!(list is List item))
		{
			return false;
		}
		return _stack.Contains(item);
	}
}
public static class Sorting
{
	public static void SlowSort<T>(List<T> listToSort) where T : IComparable<T>
	{
		int count = listToSort.Count;
		if (count == 0)
		{
			return;
		}
		List<T> list = ListPool<T>.Get(count);
		list.Add(listToSort[0]);
		for (int i = 1; i < count; i++)
		{
			T val = listToSort[i];
			int j;
			for (j = 0; j < list.Count; j++)
			{
				if (list[j].CompareTo(val) > 0)
				{
					list.Insert(j, val);
					break;
				}
			}
			if (j == list.Count)
			{
				list.Add(val);
			}
		}
		for (int k = 0; k < count; k++)
		{
			listToSort[k] = list[k];
		}
		ListPool<T>.Add(list);
	}

	public static void SlowSort<T>(List<T> listToSort, IComparer<T> comparer)
	{
		int count = listToSort.Count;
		if (count == 0)
		{
			return;
		}
		List<T> list = ListPool<T>.Get(count);
		list.Add(listToSort[0]);
		for (int i = 1; i < count; i++)
		{
			T val = listToSort[i];
			int j;
			for (j = 0; j < list.Count; j++)
			{
				if (comparer.Compare(list[j], val) > 0)
				{
					list.Insert(j, val);
					break;
				}
			}
			if (j == list.Count)
			{
				list.Add(val);
			}
		}
		for (int k = 0; k < count; k++)
		{
			listToSort[k] = list[k];
		}
		ListPool<T>.Add(list);
	}

	public static void SlowSort<T>(List<T> listToSort, Comparison<T> comparison)
	{
		int count = listToSort.Count;
		if (count == 0)
		{
			return;
		}
		List<T> list = ListPool<T>.Get(count);
		list.Add(listToSort[0]);
		for (int i = 1; i < count; i++)
		{
			T val = listToSort[i];
			int j;
			for (j = 0; j < list.Count; j++)
			{
				if (comparison(list[j], val) > 0)
				{
					list.Insert(j, val);
					break;
				}
			}
			if (j == list.Count)
			{
				list.Add(val);
			}
		}
		for (int k = 0; k < count; k++)
		{
			listToSort[k] = list[k];
		}
		ListPool<T>.Add(list);
	}
}
