	public Agent Agent { get; private set; }

	public VitalProperties Properties { get; private set; }

	public abstract VitalType VitalType { get; }

	public Project Project { get; protected set; }

	public UnityEvent Updated { get; } = new UnityEvent();

	protected Vital(Vitals vitals)
	{
		Vitals = vitals;
		Agent = vitals.Agent;
		Properties = vitals.Properties;
	}

	public virtual void Start()
	{
	}

	public virtual void LateUpdate()
	{
	}

	public virtual void OnDestroy()
	{
	}

	public abstract void Reset();

	public abstract void ConsumeItem(Item item);

	public virtual bool RetryInstantiateProject()
	{
		return false;
	}

	public bool StartProject()
	{
		if (Project == null || Project.Target == null || Project.ReturnHasAgentAssigned(Agent) || !Project.ReturnCanRun(Agent))
		{
			if (Project != null && !Project.ReturnHasAgentAssigned(Agent) && Project.Target == null)
			{
				UnityEngine.Debug.LogException(new Exception($"Vital project '{Project.Properties}' for agent '{Agent.Name}' its target == NULL. The project is getting destroyed."));
				Project.Destroy();
				OnProjectFinished(Project, succes: false);
			}
			return false;
		}
		return Project.AssignAgent(Agent);
	}

	protected bool InstantiateProject(ProjectProperties properties, GameObject target, List<Item> items = null)
	{
		if (Project == null)
		{
			Project = new Project(properties, target, items);
			Project.Vital = VitalType;
			Project.FinishedEvent.AddListener(OnProjectFinished);
			AgentEvent.Dispatch(GameEventType.AgentVitalProjectsUpdated, Agent);
			return true;
		}
		UnityEngine.Debug.LogException(new NotSupportedException($"Vital '{VitalType}' is trying to instantiate project '{properties}', but it already has a '{Project.Properties}' project instance!"));
		return false;
	}

	public abstract void OnDayStarted();

	public virtual void OnKillAgent()
	{
		if (Project != null)
		{
			Project.FinishedEvent.RemoveListener(OnProjectFinished);
			Project.Stop(ProjectFlags.Cancelled);
			Project = null;
		}
	}

	private void OnProjectFinished(Project project, bool succes)
	{
		project.FinishedEvent.RemoveListener(OnProjectFinished);
		if (Project == project)
		{
			Project = null;
		}
		else
		{
			UnityEngine.Debug.LogException(new NotImplementedException("Project mismatch!"));
		}
	}

	public bool HasProject()
	{
		return Project != null;
	}

	public void RestoreProjectReference(Project project)
	{
		Project = project;
		if (Project != null)
		{
			Project.FinishedEvent.AddListener(OnProjectFinished);
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Agent/Vitals Properties")]
public class VitalProperties : ScriptableObject
{
	[Serializable]
	private struct Pollution
	{
		public PollutionLevels PollutionLevel;

		public float PollutionPerDay;
	}

	[Header("Hunger / Thirst")]
	public int HungerLimit = 4;

	public int ThirstLimit = 4;

	[Header("Notifications")]
	[Tooltip("The notification properties if the agent died of unspecified causes.")]
	public NotificationProperties DefaultDeathNotification;

	[Tooltip("The notification properties if the agent died of hunger.")]
	public NotificationProperties DiedOfHungerNotification;

	[Tooltip("The notification properties if the agent died of thirst.")]
	public NotificationProperties DiedOfThirstNotification;

	[Header("Assignments")]
	[Tooltip("Assignment types that this agent can't handle.")]
	public List<AssignmentType> AssignmentTypes;

	[Header("Pollution")]
	public int PollutionMaximum = 10;

	[Tooltip("Pollution level the drifter's pollution goes to after reaching the pollution maximum.")]
	public int PollutionReturn = 5;

	public Disease[] Diseases = new Disease[0];

	[SerializeField]
	private Pollution[] SwimmingPollution;

	[Header("Diets")]
	public TaggedItemPropertiesRandomizer FavouriteFoods;

	public void Initialize()
	{
		FavouriteFoods.Initialize();
	}

	public float ReturnSwimmingPollutionPerSecond()
	{
		PollutionLevels pollutionLevel = GameManager.WorldManager.CurrentRegion.PollutionLevel;
		float daytimeLength = GameManager.TimeManager.CurrentDay.DaytimeLength;
		float result = 0f;
		Pollution[] swimmingPollution = SwimmingPollution;
		for (int i = 0; i < swimmingPollution.Length; i++)
		{
			Pollution pollution = swimmingPollution[i];
			if (pollution.PollutionLevel <= pollutionLevel)
			{
				result = pollution.PollutionPerDay / daytimeLength;
			}
		}
		return result;
	}
}
public enum VitalType
{
	Hunger = 1,
	Thirst = 2,
	Rest = 3,
	Learning = 4,
	Disease = 5,
	Pollution = 6,
	None = 1024
}
public class Vitals : SceneBehaviour, IEnumerable<Vital>, IEnumerable
{
	[Tooltip("Base properties of this Agent.")]
	public VitalProperties Properties;

	private Dictionary<VitalType, Vital> _vitals = new Dictionary<VitalType, Vital>();

	private Dictionary<VitalType, DietVital> _dietVitals = new Dictionary<VitalType, DietVital>();

	private List<Vital> _projectFailedToInstantiate = new List<Vital>();

	private Rest _rest;

	public Agent Agent { get; private set; }

	public Hunger Hunger { get; private set; }

	public Thirst Thirst { get; private set; }

	public Pollution Pollution { get; private set; }

	private void Start()
	{
		foreach (Vital value in _vitals.Values)
		{
			value.Start();
		}
	}

	private void LateUpdate()
	{
		if (!Agent.IsAlive)
		{
			return;
		}
		if (IsMarkedForDeath() && Agent.Assignment == null)
		{
			KillAgent();
			return;
		}
		Agent.DrifterRig.MeshAnimator.UpdateAnimator();
		foreach (Vital value in _vitals.Values)
		{
			value.LateUpdate();
		}
	}

	private void OnDestroy()
	{
		foreach (Vital value in _vitals.Values)
		{
			value.OnDestroy();
		}
		if (Hunger != null)
		{
			Hunger.Updated.RemoveListener(UpdateMortalDangerIcon);
		}
		if (Thirst != null)
		{
			Thirst.Updated.RemoveListener(UpdateMortalDangerIcon);
		}
	}

	public void Initialize(Agent agent)
	{
		Agent = agent;
		Properties = agent.Properties.VitalProperties;
		Hunger = new Hunger(this);
		Hunger.Updated.AddListener(UpdateMortalDangerIcon);
		AddVital(Hunger);
		Thirst = new Thirst(this);
		Thirst.Updated.AddListener(UpdateMortalDangerIcon);
		AddVital(Thirst);
		Pollution = new Pollution(this);
		AddVital(Pollution);
		_rest = new Rest(this);
		AddVital(_rest);
	}

	private void AddVital(Vital vital)
	{
		_vitals.Add(vital.VitalType, vital);
		if (vital is DietVital dietVital)
		{
			_dietVitals.Add(dietVital.VitalType, dietVital);
		}
	}

	private void UpdateMortalDangerIcon()
	{
		if (IsInMortalDanger())
		{
			Agent.WorldIconHandler.AddIcon(GameManager.Settings.AgentSettings.DrifterMortalDangerIconProperties);
		}
		else
		{
			Agent.WorldIconHandler.RemoveIcon(GameManager.Settings.AgentSettings.DrifterMortalDangerIconProperties);
		}
	}

	public bool AssignProject()
	{
		if (Agent.Assignment == null)
		{
			foreach (Vital value in _vitals.Values)
			{
				if (value.StartProject())
				{
					return true;
				}
			}
			if (!IsGoingToDie())
			{
				int count = _projectFailedToInstantiate.Count;
				while (0 < count--)
				{
					Vital vital = _projectFailedToInstantiate[count];
					if (vital.RetryInstantiateProject())
					{
						_projectFailedToInstantiate.RemoveAt(count);
						return vital.StartProject();
					}
				}
			}
		}
		return false;
	}

	public void RestoreProject(Project project)
	{
		if (_vitals.TryGetValue(project.Vital, out var value))
		{
			value.RestoreProjectReference(project);
		}
		else
		{
			UnityEngine.Debug.LogWarning($"Unable to restore vital project with vital '{project.Vital}' because a project for this vital is already in the projects list.");
		}
	}

	public void IncreaseVital(VitalType vitalType, bool noDeath = false)
	{
		if (_dietVitals.TryGetValue(vitalType, out var value))
		{
			value.IncreaseAmount(noDeath);
		}
	}

	public void DecreaseVital(VitalType vitalType)
	{
		if (_dietVitals.TryGetValue(vitalType, out var value))
		{
			value.DecreaseAmount();
		}
	}

	public void ResetAllVitals()
	{
		foreach (Vital value in _vitals.Values)
		{
			value.Reset();
		}
	}

	public void OnDayStarted(GameEvent gameEvent)
	{
		foreach (Vital value in _vitals.Values)
		{
			value.OnDayStarted();
		}
	}

	public void KillAgent()
	{
		if (Agent.Community.IsPlayerCommunity() && Agent.IsAlive)
		{
			NotificationProperties properties = Properties.DefaultDeathNotification;
			switch (ReturnCauseOfDeath())
			{
			case VitalType.Hunger:
				properties = Properties.DiedOfHungerNotification;
				break;
			case VitalType.Thirst:
				properties = Properties.DiedOfThirstNotification;
				break;
			}
			GameManager.UIManager.NotificationHandler.AddNotification(properties, base.gameObject, ObjectType.Agent);
		}
		foreach (Vital value in _vitals.Values)
		{
			value.OnKillAgent();
		}
		Agent.KillAgent();
	}

	public bool TryReserveItemToConsume(VitalType vitalType, AssignmentPriority priority)
	{
		if (_dietVitals.TryGetValue(vitalType, out var value) && value.Diet != null)
		{
			return value.Diet.TryReserveItemToConsume(priority);
		}
		UnityEngine.Debug.LogException(new Exception($"Unable to reserve diet item for vital '{vitalType}', no diet was found!"));
		return false;
	}

	public void UnreserveItemToConsume(params VitalType[] vitals)
	{
		foreach (VitalType key in vitals)
		{
			if (_dietVitals.TryGetValue(key, out var value) && value.Diet != null)
			{
				value.Diet.ClearItemToConsume();
			}
		}
	}

	public bool TryAddConsumeProject(VitalType vitalType, bool noDeath = false)
	{
		if (_dietVitals.TryGetValue(vitalType, out var value))
		{
			if (value.TryInstantiateProject(noDeath))
			{
				return true;
			}
			AgentEvent.Dispatch(value.Diet.FailedEvent, Agent);
			_projectFailedToInstantiate.AddUnique(value);
			return false;
		}
		UnityEngine.Debug.LogException(new Exception($"Unable to add consume project for vital '{vitalType}'!"));
		return false;
	}

	public void ConsumeItem(Item item)
	{
		foreach (Vital value in _vitals.Values)
		{
			value.ConsumeItem(item);
		}
	}

	public void ClearLastReservedItemToConsume(params VitalType[] vitals)
	{
		foreach (VitalType key in vitals)
		{
			if (_dietVitals.TryGetValue(key, out var value))
			{
				value.Diet.ClearLastReservedItemToCosume();
			}
		}
	}

	public bool IsProjectItem(Item item)
	{
		foreach (Vital value in _vitals.Values)
		{
			if (value.Project != null && value.Project.ContainsItem(item))
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnHasProject()
	{
		foreach (Vital value in _vitals.Values)
		{
			if (value.HasProject())
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnHasProject(VitalType vitalType)
	{
		if (_vitals.TryGetValue(vitalType, out var value))
		{
			return value.HasProject();
		}
		return false;
	}

	public bool TryReturnProject(VitalType vitalType, out Project project)
	{
		project = null;
		if (_vitals.TryGetValue(vitalType, out var value))
		{
			project = value.Project;
		}
		return project != null;
	}

	public bool TryReturnDiet(VitalType vital, out Diet diet)
	{
		diet = (_dietVitals.TryGetValue(vital, out var value) ? value.Diet : null);
		return diet != null;
	}

	public bool IsInMortalDanger()
	{
		foreach (DietVital value in _dietVitals.Values)
		{
			if (value.IsInDangerOfDying())
			{
				return true;
			}
		}
		return false;
	}

	public bool IsGoingToDie()
	{
		foreach (DietVital value in _dietVitals.Values)
		{
			if (value.IsGoingToDie())
			{
				return true;
			}
		}
		return false;
	}

	public bool IsGoingToDieOfAnyOther(Vital vitalToExclude)
	{
		foreach (DietVital value in _dietVitals.Values)
		{
			if (value != vitalToExclude && value.IsGoingToDie())
			{
				return true;
			}
		}
		return false;
	}

	public bool IsMarkedForDeath()
	{
		foreach (DietVital value in _dietVitals.Values)
		{
			if (value.IsCauseOfDeath())
			{
				return true;
			}
		}
		return false;
	}

	public int ReturnDangerScore()
	{
		int num = 0;
		foreach (DietVital value in _dietVitals.Values)
		{
			if (value.IsInDangerOfDying())
			{
				num++;
			}
		}
		return num;
	}

	public VitalType ReturnCauseOfDeath()
	{
		foreach (KeyValuePair<VitalType, DietVital> dietVital in _dietVitals)
		{
			if (dietVital.Value.IsCauseOfDeath())
			{
				return dietVital.Key;
			}
		}
		return VitalType.None;
	}

	public int ReturnVitalAmount(VitalType type)
	{
		if (_dietVitals.TryGetValue(type, out var value))
		{
			return value.Amount;
		}
		return 0;
	}

	public int ReturnVitalLimit(VitalType type)
	{
		if (_dietVitals.TryGetValue(type, out var value))
		{
			return value.Limit;
		}
		return 0;
	}

	public UnityEvent ReturnVitalEvent(VitalType type)
	{
		if (_vitals.TryGetValue(type, out var value))
		{
			return value.Updated;
		}
		return null;
	}

	IEnumerator IEnumerable.GetEnumerator()
	{
		return _vitals.Values.GetEnumerator();
	}

	IEnumerator<Vital> IEnumerable<Vital>.GetEnumerator()
	{
		return _vitals.Values.GetEnumerator();
	}
}
[CreateAssetMenu(fileName = "Cluster Landmark Provider", menuName = "Flotsam/Landmarks/Cluster Landmark Provider")]
public class ClusterLandmarkProvider : ScriptableObject
{
	public struct Landmark
	{
		public ILandmarkBehaviourProvider LandmarkBehaviourProvider;

		public Vector2 Position;
	}

	private interface IEntry
	{
		bool TryGetLandmarkBehaviourCollection(out LandmarkBehaviourCollection landmarkBehaviourCollection);
	}

	[Serializable]
	private struct SingleEntry : IEntry
	{
		[Range(0f, 100f)]
		public float Chance;

		public LandmarkBehaviourCollection LandmarkBehaviourCollection;

		public bool TryGetLandmarkBehaviourCollection(out LandmarkBehaviourCollection landmarkBehaviourCollection)
		{
			if (UnityEngine.Random.value * 100f <= Chance)
			{
				landmarkBehaviourCollection = LandmarkBehaviourCollection;
				return true;
			}
			landmarkBehaviourCollection = null;
			return false;
		}
	}

	[Serializable]
	private struct WeightedListEntry : IEntry
	{
		[Range(0f, 100f)]
		public float Chance;

		public WeightedList<LandmarkBehaviourCollection> WeightedList;

		public bool TryGetLandmarkBehaviourCollection(out LandmarkBehaviourCollection landmarkBehaviourCollection)
		{
			if (UnityEngine.Random.value * 100f <= Chance)
			{
				landmarkBehaviourCollection = WeightedList.ReturnRandom();
				return true;
			}
			landmarkBehaviourCollection = null;
			return false;
		}
	}

	[SerializeReference]
	[InstantiateSerializeReference]
	private IEntry[] _primaryLandmarks;

	[SerializeField]
	private float _spawnRadius = 150f;

	public IEnumerator<ILandmarkBehaviourProvider> GetEnumerator()
	{
		IEntry[] primaryLandmarks = _primaryLandmarks;
		for (int i = 0; i < primaryLandmarks.Length; i++)
		{
			if (primaryLandmarks[i].TryGetLandmarkBehaviourCollection(out var landmarkBehaviourCollection))
			{
				yield return landmarkBehaviourCollection;
			}
		}
	}

	public Vector2 GetRandomSpawnPosition(Vector2 position, ILandmarkBehaviourProvider landmarkBehaviourProvider)
	{
		return position + UnityEngine.Random.insideUnitCircle * (_spawnRadius - landmarkBehaviourProvider.Radius);
	}
}
[CreateAssetMenu(fileName = "FallbackWorldTileProvider", menuName = "Flotsam/World/Fallback World Tile Provider")]
public class FallbackWorldTileProvider : WorldTileProvider
{
	public override WorldTile GetNextWorldTile(World world, ILandmarkPicker landmarkPicker = null)
	{
		WorldTile nextWorldTile = base.GetNextWorldTile(world, landmarkPicker);
		if (nextWorldTile == null)
		{
			UnityEngine.Debug.LogException(new Exception("FallbackWorldTileProvider was unable to generate a world tile the LandmarkPicker could pick from, falling back to a random tile."));
			return nextWorldTile;
		}
		if (Session.Profile.ActiveRun.IsDebugRun)
		{
			UnityEngine.Debug.LogError("FallbackWorldTileProvider was used to get the next WorldTile");
			return nextWorldTile;
		}
		UnityEngine.Debug.LogException(new Exception("FallbackWorldTileProvider was used to get the next WorldTile"));
		return nextWorldTile;
	}
}
