[RequireComponent(typeof(LineRenderer))]
public class PlayRadiusVisualizer : MonoBehaviour
{
	public enum RadiusType
	{
		Construction,
		Map,
		Interaction,
		Swim,
		MarkerRadius
	}

	[SerializeField]
	private int _points = 32;

	[SerializeField]
	private RadiusType _radiusType;

	private void Awake()
	{
		float radius = 0f;
		switch (_radiusType)
		{
		case RadiusType.Construction:
			radius = GameSettings.Instance.GameplaySettings.ConstructionRadius;
			break;
		case RadiusType.Map:
			radius = GameSettings.Instance.GameplaySettings.MapRadius;
			break;
		case RadiusType.Interaction:
			radius = GameSettings.Instance.GameplaySettings.InteractionRadius;
			break;
		case RadiusType.Swim:
			radius = GameSettings.Instance.GameplaySettings.SwimmingRadius;
			break;
		case RadiusType.MarkerRadius:
		{
			GameplaySettings gameplaySettings = GameSettings.Instance.GameplaySettings;
			Community playerCommunity = Community.PlayerCommunity;
			radius = (playerCommunity.HasBoat() ? gameplaySettings.InteractionRadius : gameplaySettings.SwimmingRadius);
			playerCommunity.BoatsUpdatedEvent += OnBoatBuilt;
			break;
		}
		}
		SetRadius(radius);
	}

	private void OnDestroy()
	{
		if (_radiusType == RadiusType.MarkerRadius)
		{
			Community.PlayerCommunity.BoatsUpdatedEvent -= OnBoatBuilt;
		}
	}

	private void SetRadius(float radius)
	{
		float num = 360f / (float)_points;
		Vector3[] array = new Vector3[_points];
		float y = base.transform.position.y;
		for (int i = 0; i < _points; i++)
		{
			array[i] = new Vector3(Mathf.Cos(num * (float)i * (MathF.PI / 180f)) * radius, Mathf.Sin(num * (float)i * (MathF.PI / 180f)) * radius, 0f - y);
		}
		LineRenderer component = GetComponent<LineRenderer>();
		component.positionCount = _points;
		component.SetPositions(array);
	}

	private void OnBoatBuilt()
	{
		if (_radiusType == RadiusType.MarkerRadius)
		{
			GameplaySettings gameplaySettings = GameManager.Settings.GameplaySettings;
			Community playerCommunity = Community.PlayerCommunity;
			SetRadius(playerCommunity.HasBoat() ? gameplaySettings.InteractionRadius : gameplaySettings.SwimmingRadius);
		}
	}
}
public abstract class WorldMapPointOfInterest : MonoBehaviour
{
	private List<int> _deactivatedChildIndices;

	public ISpawner Spawner { get; protected set; }

	public bool IsActive { get; private set; }

	protected virtual void OnDestroy()
	{
		Spawner.UpdatedEvent.RemoveListener(OnSpawnerUpdated);
	}

	protected void Initialize(ISpawner spawner)
	{
		Spawner = spawner;
		if (Spawner.ScoutingState == ScoutingState.Scouted)
		{
			Activate();
			return;
		}
		Spawner.UpdatedEvent.AddListener(OnSpawnerUpdated);
		Deactivate();
	}

	protected virtual void OnSpawnerUpdated(ISpawner spawner)
	{
		if (!IsActive && Spawner.ScoutingState == ScoutingState.Scouted)
		{
			Activate();
		}
	}

	protected virtual void Activate()
	{
		if (_deactivatedChildIndices != null)
		{
			foreach (int deactivatedChildIndex in _deactivatedChildIndices)
			{
				base.transform.GetChild(deactivatedChildIndex).gameObject.SetActive(value: true);
			}
			_deactivatedChildIndices.Clear();
		}
		Spawner.UpdatedEvent.RemoveListener(OnSpawnerUpdated);
		IsActive = true;
	}

	private void Deactivate()
	{
		if (_deactivatedChildIndices == null)
		{
			_deactivatedChildIndices = new List<int>(3);
		}
		int childCount = base.transform.childCount;
		for (int i = 0; i < childCount; i++)
		{
			GameObject gameObject = base.transform.GetChild(i).gameObject;
			if (gameObject.activeSelf)
			{
				gameObject.SetActive(value: false);
				_deactivatedChildIndices.Add(i);
			}
		}
		IsActive = false;
	}

	public abstract bool InitializeReveal();

	public abstract IEnumerator RevealRoutine();
}
public class CargoCapsuleDebrisReveal : WorldMapReveal
{
	public class Piece
	{
		private GameObject _piece;

		private Transform _pieceTransform;

		private ParticleSystem _impact;

		private Vector3 _fromPosition;

		private Vector3 _toPosition;

		private float _duration;

		private float _time;

		public Piece(GameObject piece, ParticleSystem impact, Quaternion rotation, float distance, float duration)
		{
			_piece = piece;
			_pieceTransform = piece.transform;
			_impact = impact;
			_pieceTransform.rotation = rotation;
			_toPosition = _pieceTransform.position;
			_fromPosition = _toPosition - _pieceTransform.forward * distance;
			_pieceTransform.position = _fromPosition;
			_duration = duration;
			_time = 0f;
			piece.SetActive(value: true);
		}

		public bool Next(float deltaTime)
		{
			if (_time >= _duration)
			{
				return false;
			}
			_time += deltaTime;
			_pieceTransform.position = Vector3.Lerp(_fromPosition, _toPosition, Mathf.Clamp01(_time / _duration));
			if (_time >= _duration)
			{
				_piece.SetActive(value: false);
				_impact?.Play();
			}
			return true;
		}
	}

	[SerializeField]
	private MeshRenderer _visualRenderer;

	[SerializeField]
	private GameObject[] _pieces;

	[SerializeField]
	private ParticleSystem[] _impacts;

	[SerializeField]
	private float _impactRotationX;

	[SerializeField]
	private float _duration;

	[SerializeField]
	private RangedFloat _durationVariation;

	[SerializeField]
	private float _distance;

	[SerializeField]
	private float _centerOnTownDelay = 5f;

	private Piece[] _pieceInstances;

	public override void Initialize(WorldMapPointOfInterest poi)
	{
	}

	public override bool InitializeReveal(WorldMapPointOfInterest poi)
	{
		Quaternion rotation = Quaternion.Euler(_impactRotationX, UnityEngine.Random.Range(0f, 1f), 0f);
		_visualRenderer.enabled = false;
		_pieceInstances = new Piece[_pieces.Length];
		for (int i = 0; i < _pieces.Length; i++)
		{
			_pieceInstances[i] = new Piece(_pieces[i], _impacts.GetValueOrNull(i), rotation, _distance, _duration + _durationVariation.ReturnRandom());
		}
		return true;
	}

	public override IEnumerator Reveal(WorldMapPointOfInterest poi)
	{
		while (Next(GameSpeedManager.UnscaledDeltaTime))
		{
			yield return null;
		}
		_visualRenderer.enabled = true;
		yield return new WaitForSeconds(_centerOnTownDelay);
	}

	private bool Next(float deltaTime)
	{
		bool result = false;
		for (int i = 0; i < _pieceInstances.Length; i++)
		{
			if (_pieceInstances[i].Next(deltaTime))
			{
				result = true;
			}
		}
		return result;
	}
}
public class SpaceshipReveal : WorldMapReveal
{
	[Header("Spaceship")]
	[SerializeField]
	private Transform _visual;

	[SerializeField]
	private int _layer = 22;

	[SerializeField]
	private Vector3 _vector;

	[SerializeField]
	private float _distance = 1000f;

	[SerializeField]
	private float _duration = 3f;

	[SerializeField]
	private float _centerOnTownDelay = 2f;

	[SerializeField]
	private ParticleSystem _heat;

	[SerializeField]
	private ParticleSystem _impact;

	private int _originalLayer;

	private Vector3 _originalLocalPosition;

	private Vector3 _offsetLocalPosition;

	private void OnDrawGizmos()
	{
		Gizmos.color = Color.green;
		Gizmos.DrawLine(_vector * 50f, -_vector * 50f);
	}

	public override void Initialize(WorldMapPointOfInterest poi)
	{
	}

	public override bool InitializeReveal(WorldMapPointOfInterest poi)
	{
		_visual.gameObject.SetActive(value: true);
		_originalLayer = _visual.gameObject.layer;
		_visual.gameObject.SetLayerRecursively(_layer);
		_originalLocalPosition = _visual.localPosition;
		_offsetLocalPosition = _originalLocalPosition + _vector * _distance;
		_visual.localPosition = _offsetLocalPosition;
		_heat?.Play();
		return true;
	}

	public override IEnumerator Reveal(WorldMapPointOfInterest poi)
	{
		float time = 0f;
		while (time < _duration)
		{
			time += GameSpeedManager.UnscaledDeltaTime;
			_visual.localPosition = Vector3.Lerp(_offsetLocalPosition, _originalLocalPosition, Mathf.Clamp01(time / _duration));
			yield return null;
		}
		_heat?.Stop();
		_impact?.Play();
		_visual.localPosition = _originalLocalPosition;
		_visual.gameObject.SetLayerRecursively(_originalLayer);
		poi.Spawner.ClearFogOfWar();
		yield return new WaitForSeconds(_centerOnTownDelay);
	}
}
