public class MapObstacle
{
	private float _poweredRadius;

	public Vector2 Position { get; private set; }

	public float Radius { get; private set; }

	public MapObstacle(Vector2 position, float radius)
	{
		Position = position;
		Radius = radius;
		_poweredRadius = Mathf.Pow(Radius, 2f);
	}

	public bool HasPointInRadius(Vector2 position)
	{
		Vector2 vector = Position - position;
		if (!(vector.sqrMagnitude <= _poweredRadius))
		{
			return Mathf.Approximately(vector.sqrMagnitude, _poweredRadius);
		}
		return true;
	}

	private Vector2 ReturnProjectedPoint(Vector2 lineStart, Vector2 lineEnd, out bool canProject)
	{
		Vector2 vector = lineEnd - lineStart;
		float sqrMagnitude = (lineEnd - lineStart).sqrMagnitude;
		float num = ((Position.x - lineStart.x) * (lineEnd.x - lineStart.x) + (Position.y - lineStart.y) * (lineEnd.y - lineStart.y)) / sqrMagnitude;
		canProject = num >= 0f && num <= 1f;
		return lineStart + num * vector;
	}

	public bool IsIntersecting(Vector2 lineStart, Vector2 lineEnd, out Vector2 projectionPoint)
	{
		projectionPoint = Vector2.zero;
		if (HasPointInRadius(lineEnd))
		{
			return true;
		}
		projectionPoint = ReturnProjectedPoint(lineStart, lineEnd, out var canProject);
		if (!canProject)
		{
			return false;
		}
		return (projectionPoint - Position).sqrMagnitude <= _poweredRadius;
	}
}
public class MapPath
{
	public struct Point
	{
		public Vector2 Position;

		public float LerpValue;

		public float DistanceToNextPoint;

		public Point(Vector2 position)
		{
			Position = position;
			LerpValue = 0f;
			DistanceToNextPoint = 0f;
		}
	}

	public enum State
	{
		Ok,
		DestinationOutOfRange,
		DestinationBlocked
	}

	public interface IStateEvaluator
	{
		State ReturnEvaluatedState(MapPath mapPath);
	}

	private float _progress;

	private MapPathCalculator _calculator;

	private List<IStateEvaluator> _stateEvaluators;

	public List<MapObstacle> Obstacles { get; private set; }

	public Transform Origin { get; private set; }

	public Vector3 Destination { get; private set; }

	public List<Point> Points { get; private set; }

	public float Length { get; protected set; }

	public float LengthDifference { get; protected set; }

	public float Progress { get; protected set; }

	public State EvaluatedState { get; private set; }

	public MapPath(MapPathCalculator calculator, List<MapObstacle> obstacles, Transform origin)
	{
		Obstacles = obstacles;
		Origin = origin;
		_calculator = calculator;
		Points = ListPool<Point>.Get();
		MapEvent.DispatchMapPathStateUpdated(EvaluatedState);
	}

	public MapPath(MapPath mapPath)
	{
		Points = new List<Point>(mapPath.Points);
		Length = mapPath.Length;
		MapEvent.DispatchMapPathStateUpdated(EvaluatedState);
	}

	public void CalculatePath(Vector3 destination)
	{
		float length = Length;
		Destination = destination;
		Points.Clear();
		Length = 0f;
		Progress = 0f;
		_calculator.CalculatePath(this, Origin.position, destination);
		CalculatePointLerpValues();
		LengthDifference = Length - length;
		if (_stateEvaluators != null)
		{
			State state = ReturnEvaluatedState();
			if (state != EvaluatedState)
			{
				EvaluatedState = state;
				MapEvent.DispatchMapPathStateUpdated(EvaluatedState);
			}
		}
	}

	private void CalculatePointLerpValues()
	{
		if (Points != null && Points.Count != 0)
		{
			float num = 0f;
			for (int i = 0; i < Points.Count; i++)
			{
				Point value = Points[i];
				value.LerpValue = num / Length;
				num += value.DistanceToNextPoint;
				Points[i] = value;
			}
		}
	}

	public void AddStateEvaluator(IStateEvaluator stateEvaluator)
	{
		if (_stateEvaluators == null)
		{
			_stateEvaluators = new List<IStateEvaluator>();
		}
		_stateEvaluators.Add(stateEvaluator);
	}

	public void AddPathPoint(Vector2 point)
	{
		Point item = new Point(point);
		int num = Points.Count - 1;
		if (0 <= num)
		{
			Point value = Points[num];
			float num2 = (value.DistanceToNextPoint = Vector2.Distance(value.Position, point));
			Length += num2;
			Points[num] = value;
		}
		Points.Add(item);
	}

	public void SetLineRendererPositions(LineRenderer lineRenderer, float currentProgress)
	{
		int num = 1;
		lineRenderer.positionCount = Points.Count;
		lineRenderer.SetPosition(0, ReturnLerpedPosition(currentProgress).Vector3TopDown(0.1f));
		for (int i = 0; i < Points.Count; i++)
		{
			Point point = Points[i];
			if (!(point.LerpValue <= currentProgress))
			{
				lineRenderer.SetPosition(num, point.Position.Vector3TopDown(0.1f));
				num++;
			}
		}
		lineRenderer.positionCount = num;
	}

	public Vector2 ReturnPosition(float distance)
	{
		if (distance > Length)
		{
			return ReturnLerpedPosition(1f);
		}
		return ReturnLerpedPosition(distance / Length);
	}

	public bool ReturnNextPosition(float distance, out Vector3 position)
	{
		Progress = Mathf.Clamp01(Progress + distance / Length);
		position = ReturnLerpedPosition(Progress).Vector3TopDown();
		return Progress < 1f;
	}

	public Vector2 ReturnLerpedPosition(float lerp)
	{
		if (Points == null || Points.Count <= 1)
		{
			return Vector2.zero;
		}
		lerp = Mathf.Clamp(lerp, 0f, 1f);
		for (int i = 0; i < Points.Count - 1; i++)
		{
			Point point = Points[i];
			Point point2 = Points[i + 1];
			if (lerp >= point.LerpValue && lerp <= point2.LerpValue)
			{
				float t = 1f / (point2.LerpValue - point.LerpValue) * (lerp - point.LerpValue);
				return Vector2.Lerp(point.Position, point2.Position, t);
			}
		}
		throw new NotImplementedException();
	}

	private State ReturnEvaluatedState()
	{
		if (_stateEvaluators == null)
		{
			return State.Ok;
		}
		State state = State.Ok;
		int num = 0;
		while (state == State.Ok && num < _stateEvaluators.Count)
		{
			state = _stateEvaluators[num++].ReturnEvaluatedState(this);
		}
		return state;
	}
}
public abstract class MapPathCalculator : ScriptableObject
{
	public abstract void CalculatePath(MapPath path, Vector3 from, Vector3 to);

	protected void CalculatePointsOnPath(List<MapObstacle> obstacles, Vector2 startPosition, Vector2 endPosition, List<Vector2> points)
	{
		points.Add(startPosition);
		MapObstacle obstacle;
		Vector2 projection;
		while (TryReturnClosestIntersectingObstacle(obstacles, startPosition, endPosition, out obstacle, out projection))
		{
			Vector2 normalized = (projection - obstacle.Position).normalized;
			startPosition = obstacle.Position + normalized * obstacle.Radius;
			points.Add(startPosition);
		}
		points.Add(endPosition);
	}

	protected bool TryReturnClosestIntersectingObstacle(List<MapObstacle> obstacles, Vector2 startPosition, Vector3 endPosition, out MapObstacle obstacle, out Vector2 projection)
	{
		float num = float.MaxValue;
		obstacle = null;
		projection = Vector2.zero;
		for (int i = 0; i < obstacles.Count; i++)
		{
			MapObstacle mapObstacle = obstacles[i];
			if (!mapObstacle.HasPointInRadius(startPosition) && !mapObstacle.HasPointInRadius(endPosition) && mapObstacle.IsIntersecting(startPosition, endPosition, out var projectionPoint))
			{
				float sqrMagnitude = (mapObstacle.Position - startPosition).sqrMagnitude;
				if (sqrMagnitude < num)
				{
					obstacle = mapObstacle;
					num = sqrMagnitude;
					projection = projectionPoint;
				}
			}
		}
		return obstacle != null;
	}
}
public class MapPathBlockedEvaluator : MapPath.IStateEvaluator
{
	private WorldMap _worldMap;

	private float _radiusSquared;

	public MapPathBlockedEvaluator(WorldMap worldMap, float radius)
	{
		_worldMap = worldMap;
		_radiusSquared = radius * radius;
	}

	public MapPath.State ReturnEvaluatedState(MapPath mapPath)
	{
		if (_worldMap.HasLandmarkInSquareRadius(mapPath.Destination.Vector2TopDown(), _radiusSquared))
		{
			return MapPath.State.DestinationBlocked;
		}
		return MapPath.State.Ok;
	}
}
public class MapPathOutOfRangeEvaluator : MapPath.IStateEvaluator
{
	private Engine _engine;

	public MapPathOutOfRangeEvaluator(Engine engine)
	{
		_engine = engine;
	}

	public MapPath.State ReturnEvaluatedState(MapPath mapPath)
	{
		if (_engine.ReturnEnergyRange() < mapPath.Length)
		{
			return MapPath.State.DestinationOutOfRange;
		}
		return MapPath.State.Ok;
	}
}
public class MapSplineDebugger : MonoBehaviour
{
	public enum CursorMode
	{
		Add = 1,
		Remove,
		Move
	}

	public struct Pathpoint
	{
		public float Curve;

		public Vector2 Waypoint;

		public Pathpoint(float curve, Vector2 waypoint)
		{
			Curve = curve;
			Waypoint = waypoint;
		}
	}

	[SerializeField]
	private MapPathCalculator _calculator;

	[Header("References")]
	[SerializeField]
	private RectTransform _pathFollower;

	[SerializeField]
	private RectTransform _town;

	[SerializeField]
	private RectTransform _viewport;

	[SerializeField]
	private DebugSplineObstacle _obstaclePrefab;

	[SerializeField]
	private UILineRenderer _mouseLine;

	[Header("Info")]
	[SerializeField]
	private TMP_InputField _obstacleAmountField;

	[SerializeField]
	private TMP_InputField _fpsField;

	private MapPath _path;

	private List<DebugSplineObstacle> _debugObstacles;

	private List<MapObstacle> _obstacles;

	private CursorMode _cursorMode = CursorMode.Add;

	private float _obstacleRadius = 75f;

	private List<Pathpoint> _pathpoints = new List<Pathpoint>();

	private float _turningRadius = 10f;

	private float _progress;

	private void Awake()
	{
		_debugObstacles = new List<DebugSplineObstacle>();
		_obstacles = new List<MapObstacle>();
		_path = new MapPath(_calculator, _obstacles, _town);
	}

	private void Update()
	{
		Vector3 vector = _viewport.InverseTransformPoint(FlotsamInputManager.MousePosition);
		switch (_cursorMode)
		{
		case CursorMode.Add:
			Update_Add(vector);
			break;
		case CursorMode.Remove:
			Update_Remove(vector);
			break;
		case CursorMode.Move:
			Update_Move(vector);
			break;
		}
		_fpsField.text = (1f / Time.deltaTime).ToString("F0");
	}

	private void Update_Add(Vector2 mousePosition)
	{
		if (UnityEngine.Input.GetMouseButtonDown(1))
		{
			AddObstacle(mousePosition);
		}
	}

	private void Update_Remove(Vector2 mousePosition)
	{
		if (UnityEngine.Input.GetMouseButtonDown(1))
		{
			RemoveObstaclesNearPosition(mousePosition);
		}
	}

	private void Update_Move(Vector2 mousePosition)
	{
		_path.CalculatePath(mousePosition.Vector3TopDown());
		Vector2[] array = new Vector2[_path.Points.Count];
		for (int i = 0; i < _path.Points.Count; i++)
		{
			array[i] = _path.Points[i].Position;
		}
		_mouseLine.Points = array;
		_pathFollower.anchoredPosition = _path.ReturnLerpedPosition(_progress);
		_progress += Time.deltaTime;
		_progress %= 1f;
	}

	public void AddObstacle(Vector2 position)
	{
		MapObstacle mapObstacle = new MapObstacle(position, _obstacleRadius);
		DebugSplineObstacle debugSplineObstacle = UnityEngine.Object.Instantiate(_obstaclePrefab, _viewport);
		debugSplineObstacle.Initialize(mapObstacle);
		_debugObstacles.Add(debugSplineObstacle);
		_obstacles.Add(mapObstacle);
		_obstacleAmountField.text = _obstacles.Count.ToString();
	}

	public void RemoveObstaclesNearPosition(Vector2 position)
	{
		int count = _debugObstacles.Count;
		if (count == 0)
		{
			return;
		}
		for (int num = count - 1; num >= 0; num--)
		{
			DebugSplineObstacle debugSplineObstacle = _debugObstacles[num];
			if (debugSplineObstacle.Obstacle.HasPointInRadius(position))
			{
				_obstacles.Remove(debugSplineObstacle.Obstacle);
				UnityEngine.Object.Destroy(debugSplineObstacle.gameObject);
				_debugObstacles.RemoveAt(num);
			}
		}
		_obstacleAmountField.text = _debugObstacles.Count.ToString();
	}

	public void Reset()
	{
		_town.localPosition = Vector2.zero;
		for (int i = 0; i < _debugObstacles.Count; i++)
		{
			UnityEngine.Object.Destroy(_debugObstacles[i].gameObject);
		}
		_debugObstacles.Clear();
		_obstacles.Clear();
	}

	public void Recenter()
	{
		_viewport.anchoredPosition = Vector2.zero;
	}

	public void SetObstacleRadius(float radius)
	{
		_obstacleRadius = radius;
	}

	public void SetObstacleOpacity(float opacity)
	{
		Color red = Color.red;
		red.a = opacity;
		for (int i = 0; i < _debugObstacles.Count; i++)
		{
			_debugObstacles[i].SetColor(red);
		}
	}

	public void SetTurnRadius(float radius)
	{
		_turningRadius = radius;
	}

	public void SetAddCursorMode(bool enabled)
	{
		if (enabled)
		{
			_cursorMode = CursorMode.Add;
		}
	}

	public void SetRemoveCursorMode(bool enabled)
	{
		if (enabled)
		{
			_cursorMode = CursorMode.Remove;
		}
	}

	public void SetMoveCursorMode(bool enabled)
	{
		if (enabled)
		{
			_cursorMode = CursorMode.Move;
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Map/Simple Path Calculator")]
public class SimpleMapPathCalculator : MapPathCalculator
{
	public override void CalculatePath(MapPath path, Vector3 from, Vector3 to)
	{
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get();
		CalculatePointsOnPath(path.Obstacles, from.Vector2TopDown(), to.Vector2TopDown(), list);
		foreach (Vector2 item in list)
		{
			path.AddPathPoint(item);
		}
	}
}
[CreateAssetMenu(menuName = "Flotsam/Map/TileProperties")]
public class TileProperties : PersistentProperties
{
	[Serializable]
	private struct RegionLandmarkBehaviourCollection
	{
		public WorldRegionType Region;

		public LandmarkBehaviourCollection LandmarkBehaviourCollection;
	}

	[SerializeField]
	private GameMode _gameMode;

	[SerializeField]
	private TileGenerator _tileGenerator;

	[SerializeField]
	private TileGeneratorBase _tutorialTileGenerator;

	[SerializeField]
	private TileGeneratorBase[] _startSubTileGenerators;

	[SerializeField]
	[FormerlySerializedAs("_tileGenerators")]
	private TileGeneratorBase[] _subTileGenerators;

	[Space]
	[Range(0f, 1f)]
	[SerializeField]
	[FormerlySerializedAs("MapOverlayWeight")]
	private float _mapOverlayWeight;

	[SerializeField]
	[FormerlySerializedAs("IsCorridor")]
	private bool _isCorridor;

	[SerializeField]
	[Range(2f, 4f)]
	private int _preferredActiveTileCount = 4;

	[SerializeField]
	[Range(5f, 10f)]
	private int _maximumActiveTileCount = 7;

	[Header("Spawning")]
	[SerializeField]
	[NamedArrayElement(new string[] { "Region" })]
	private RegionLandmarkBehaviourCollection[] _rescueLandmarkBehaviourCollections;

	[SerializeField]
	private FallbackWorldTileProvider _fallbackWorldTileProvider;

	public override Types Type => Types.TileProperties;

	public GameMode GameMode => _gameMode;

	public TileGenerator TileGenerator => _tileGenerator;

	public TileGeneratorBase[] TileGenerators => _subTileGenerators;

	public float MapOverlayWeight => _mapOverlayWeight;

	public bool IsCorridor => _isCorridor;

	public int PreferredActiveTileCount => _preferredActiveTileCount;

	public int MaximumActiveTileCount => _maximumActiveTileCount;

	public FallbackWorldTileProvider FallbackWorldTileProvider => _fallbackWorldTileProvider;

	public TileGeneratorBase ReturnStartSubTileGenerator()
	{
		if (Session.Profile.ActiveRun.IsTutorial)
		{
			if (_tutorialTileGenerator != null)
			{
				return _tutorialTileGenerator;
			}
			UnityEngine.Debug.LogError("Unable to return tutorial start tile!");
		}
		return _startSubTileGenerators[UnityEngine.Random.Range(0, _startSubTileGenerators.Length)];
	}

	public WorldTile ReturnRandomWorldTile(ILandmarkPicker landmarkPicker = null)
	{
		if (((IReadOnlyCollection<TileGeneratorBase>)(object)_subTileGenerators).IsNullOrEmpty())
		{
			return null;
		}
		if (landmarkPicker == null)
		{
			return new WorldTile(TileGenerator, _subTileGenerators.GetRandom());
		}
		using ListPool<TileGeneratorBase>.List list = ListPool<TileGeneratorBase>.Get();
		TileGeneratorBase[] subTileGenerators = _subTileGenerators;
		foreach (TileGeneratorBase tileGeneratorBase in subTileGenerators)
		{
			if (!landmarkPicker.CanPickFrom(tileGeneratorBase))
			{
				list.Add(tileGeneratorBase);
			}
		}
		if (list.Count == 0)
		{
			return null;
		}
		return new WorldTile(TileGenerator, list.GetRandom());
	}

	public static bool TryReturnDebugTileProperties(out TileProperties tileProperties)
	{
		TileGeneratorBase objectReference = DebugEnvironmentVariables.GetObjectReference<TileGeneratorBase>(DebugEnvironmentVariable.TileGenerator);
		if (objectReference != null)
		{
			tileProperties = ScriptableObject.CreateInstance<TileProperties>();
			tileProperties._startSubTileGenerators = new TileGeneratorBase[1] { objectReference };
			return true;
		}
		tileProperties = DebugEnvironmentVariables.GetObjectReference<TileProperties>(DebugEnvironmentVariable.TileProperties);
		return tileProperties != null;
	}

	public LandmarkBehaviour ReturnLandmarkBehaviour(IWorldRegion region)
	{
		RegionLandmarkBehaviourCollection[] rescueLandmarkBehaviourCollections = _rescueLandmarkBehaviourCollections;
		for (int i = 0; i < rescueLandmarkBehaviourCollections.Length; i++)
		{
			RegionLandmarkBehaviourCollection regionLandmarkBehaviourCollection = rescueLandmarkBehaviourCollections[i];
			if (regionLandmarkBehaviourCollection.Region == region.Type)
			{
				return regionLandmarkBehaviourCollection.LandmarkBehaviourCollection.ReturnLandmarkBehaviour(region.Type);
			}
		}
		RegionLandmarkBehaviourCollection random = _rescueLandmarkBehaviourCollections.GetRandom();
		UnityEngine.Debug.LogWarning($"No rescue landmark behaviour collection found for region '{region.Type}', falling back on '{random.LandmarkBehaviourCollection}'");
		return random.LandmarkBehaviourCollection.ReturnLandmarkBehaviour(WorldRegionType.Any);
	}
}
