		else if (persistentData == null)
		{
			TileSizeX = _tileSizeX;
			TileSizeZ = _tileSizeZ;
			GridSizeX = Mathf.CeilToInt(bounds.size.x / (float)TileSizeX) + _tilePadding * 2;
			GridSizeZ = Mathf.CeilToInt(bounds.size.y / (float)TileSizeZ) + _tilePadding * 2;
		}
		else
		{
			TileSizeX = persistentData.TileWidth;
			TileSizeZ = persistentData.TileDepth;
			GridSizeX = persistentData.GridWidth;
			GridSizeZ = persistentData.GridDepth;
		}
		GenerateMesh(bounds, alphas);
		if (!_isPadding)
		{
			_instances.Add(this);
		}
	}

	private void Update()
	{
		if (_debugGradient || _debugRegion != null)
		{
			UpdateAlphas(_debugRegion);
		}
	}

	private void OnDestroy()
	{
		_instances.Remove(this);
	}

	public static void ScoutArea(Vector3 position, float clearRadius)
	{
		foreach (WorldMapFogOfWar instance in _instances)
		{
			instance.UpdateAlphas(position, clearRadius);
		}
	}

	public static void ScoutRegion(IWorldRegion region)
	{
		foreach (WorldMapFogOfWar instance in _instances)
		{
			instance.UpdateAlphas(region);
		}
	}

	public void RestoreLastTileAlphas()
	{
		int num = _tilePadding + 2;
		for (int i = 0; i < _vertexRowCount; i++)
		{
			for (int j = 0; j < num; j++)
			{
				int num2 = j + i * _vertexColumnCount;
				Color color = _colors[num2];
				color.a = 1f;
				_colors[num2] = color;
			}
		}
		_mesh.colors = _colors;
	}

	private void GenerateMesh(Rect bounds, byte[] alphas)
	{
		int num = 0;
		int num2 = 0;
		Vector3 vector = new Vector3(GridSizeX * TileSizeX, 0f, GridSizeZ * TileSizeZ);
		Vector3 vector2 = bounds.center.Vector3TopDown() - vector / 2f;
		Vector3 zero = Vector3.zero;
		Vector2 zero2 = Vector2.zero;
		Vector3 up = Vector3.up;
		Bounds = bounds;
		_meshBounds = new Rect(vector2.Vector2TopDown(), vector.Vector2TopDown());
		int gridSizeX = GridSizeX;
		int gridSizeZ = GridSizeZ;
		_vertexColumnCount = gridSizeX + 1;
		_vertexRowCount = gridSizeZ + 1;
		_vertexCount = _vertexRowCount * _vertexColumnCount;
		_vertices = new Vector3[_vertexColumnCount * _vertexRowCount];
		Vector2[] array = new Vector2[_vertexCount];
		Vector3[] array2 = new Vector3[_vertexCount];
		_colors = new Color[_vertexCount];
		int[] array3 = new int[gridSizeX * gridSizeZ * 6];
		for (int i = 0; i < _vertexRowCount; i++)
		{
			zero.z = vector2.z + (float)(i * TileSizeZ);
			zero2.y = i;
			for (int j = 0; j < _vertexColumnCount; j++)
			{
				zero.x = vector2.x + (float)(j * TileSizeX);
				zero2.x = j;
				_vertices[num] = zero;
				array[num] = zero2;
				array2[num] = up;
				_colors[num] = Color.black;
				if (j < gridSizeX && i < gridSizeZ)
				{
					int num3 = num;
					int num4 = num + 1;
					int num5 = num4 + gridSizeX;
					int num6 = num5 + 1;
					array3[num2++] = num3;
					array3[num2++] = num5;
					array3[num2++] = num4;
					array3[num2++] = num4;
					array3[num2++] = num5;
					array3[num2++] = num6;
				}
				num++;
			}
		}
		_mesh = new Mesh();
		if (65535 < _vertexCount)
		{
			_mesh.indexFormat = IndexFormat.UInt32;
		}
		_mesh.vertices = _vertices;
		_mesh.uv = array;
		_mesh.normals = array2;
		RestoreAlphas(alphas, _colors, _vertexCount);
		_mesh.colors = _colors;
		_mesh.triangles = array3;
		GetComponent<MeshFilter>().mesh = _mesh;
	}

	private void UpdateAlphas(Vector3 position, float clearRadius)
	{
		if (_vertices == null)
		{
			return;
		}
		position -= _position;
		UpdateClearRect(position, clearRadius);
		for (int i = _clearRect.yMin; i < _clearRect.yMax; i++)
		{
			for (int j = _clearRect.xMin; j < _clearRect.xMax; j++)
			{
				int num = j + i * _vertexColumnCount;
				float num2 = Vector3.Distance(_vertices[num], position);
				if (num2 < clearRadius)
				{
					float a = _clearGradient.Evaluate(Mathf.Clamp01(num2 / clearRadius)).a;
					Color color = _colors[num];
					if (_debugGradient || a < color.a)
					{
						color.a = a;
						_colors[num] = color;
					}
				}
			}
		}
		_mesh.colors = _colors;
	}

	private void UpdateAlphas(IWorldRegion region)
	{
		if (_vertices == null)
		{
			return;
		}
		Vector2 vector = region.Bounds.center - WorldTile.Offset;
		float fogOfWarRegionMargin = GameSettings.Instance.GameplaySettings.FogOfWarRegionMargin;
		float num = region.Bounds.size.magnitude / 2f + fogOfWarRegionMargin;
		Vector2 vector2 = WorldTile.Offset - region.WorldTile.Offset;
		UpdateClearRect(vector, num, _regionClearRectMargin);
		for (int i = _clearRect.yMin; i < _clearRect.yMax; i++)
		{
			for (int j = _clearRect.xMin; j < _clearRect.xMax; j++)
			{
				int num2 = j + i * _vertexColumnCount;
				Vector2 vector3 = _vertices[num2].Vector2TopDown();
				if (Vector2.Distance(vector3, vector) < num && region.TryReturnDistanceToBorder(out var distance, vector3 + vector2, fogOfWarRegionMargin))
				{
					float num3 = Mathf.Sin(vector3.x * _clearDeviationFrequency) + Mathf.Cos(vector3.y * _clearDeviationFrequency);
					distance += num3 * _clearDeviation;
					float a = _clearGradient.Evaluate(1f - distance / _clearRange).a;
					Color color = _colors[num2];
					if (_debugGradient || a < color.a)
					{
						color.a = a;
						_colors[num2] = color;
					}
				}
			}
		}
		_mesh.colors = _colors;
	}

	private void RestoreAlphas(byte[] alphasToRestore, Color[] colors, int vertexCount)
	{
		if (alphasToRestore == null)
		{
			return;
		}
		int num = alphasToRestore.Length;
		if (num != _vertexCount)
		{
			UnityEngine.Debug.LogErrorFormat("alpha count ({0}) != vertex count ({1})!", num, _vertexCount);
			return;
		}
		for (int i = 0; i < num; i++)
		{
			Color color = colors[i];
			color.a = (float)(int)alphasToRestore[i] / 255f;
			colors[i] = color;
		}
	}

	private void UpdateClearRect(Vector2 center, float radius, int margin = 0)
	{
		Vector2 vector = center - _meshBounds.min;
		_clearRect.xMin = Mathf.Clamp(Mathf.FloorToInt((vector.x - radius) / (float)TileSizeX) - margin, 0, _vertexColumnCount);
		_clearRect.yMin = Mathf.Clamp(Mathf.FloorToInt((vector.y - radius) / (float)TileSizeZ) - margin, 0, _vertexRowCount);
		_clearRect.xMax = Mathf.Clamp(Mathf.CeilToInt((vector.x + radius) / (float)TileSizeX) + margin, 0, _vertexColumnCount);
		_clearRect.yMax = Mathf.Clamp(Mathf.CeilToInt((vector.y + radius) / (float)TileSizeZ) + margin, 0, _vertexRowCount);
	}

	private void UpdateClearRect(Vector3 center, float radius)
	{
		UpdateClearRect(center.Vector2TopDown(), radius);
	}

	public byte[] ReturnAlphas()
	{
		if (_colors == null)
		{
			return null;
		}
		int num = _colors.Length;
		byte[] array = new byte[num];
		for (int i = 0; i < num; i++)
		{
			array[i] = (byte)Mathf.FloorToInt(_colors[i].a * 255f);
		}
		return array;
	}
}
public class WorldMapInnerBorder : MonoBehaviour
{
	public enum Axis
	{
		X,
		Z
	}

	[SerializeField]
	private Axis _axis;

	[SerializeField]
	private Transform[] _visualtransforms;

	[SerializeField]
	private float _distanceMarkerInterval = 500f;

	[SerializeField]
	private TextMeshPro _distanceMarkerPrefab;

	private List<TextMeshPro> _distanceMarkers;

	public void UpdateWorldBounds(Rect worldBounds, WorldMapBorder.Sides side, float markerLabelOffsetX = 0f)
	{
		int i = 0;
		switch (_axis)
		{
		case Axis.X:
		{
			Vector3 position = base.transform.position;
			position.x = worldBounds.xMin;
			switch (side)
			{
			case WorldMapBorder.Sides.North:
				position.z = worldBounds.yMax;
				break;
			case WorldMapBorder.Sides.South:
				position.z = worldBounds.yMin;
				break;
			default:
				throw new NotImplementedException();
			}
			base.transform.position = position;
			Transform[] visualtransforms = _visualtransforms;
			foreach (Transform obj2 in visualtransforms)
			{
				Vector3 localPosition = obj2.localPosition;
				Vector3 localScale = obj2.localScale;
				localPosition.x = worldBounds.size.x / 2f;
				localScale.x = worldBounds.size.x;
				obj2.localPosition = localPosition;
				obj2.localScale = localScale;
			}
			if (_distanceMarkers == null)
			{
				_distanceMarkers = new List<TextMeshPro>(Mathf.CeilToInt(worldBounds.size.x / _distanceMarkerInterval));
			}
			float num2 = (float)Mathf.CeilToInt(worldBounds.xMin / _distanceMarkerInterval) * _distanceMarkerInterval;
			if (Mathf.Approximately(num2, worldBounds.xMin))
			{
				num2 += _distanceMarkerInterval;
			}
			for (; num2 < worldBounds.xMax; num2 += _distanceMarkerInterval)
			{
				TextMeshPro textMeshPro2 = ReturnDistanceMarker(i++);
				Vector3 position2 = textMeshPro2.transform.position;
				position2.x = num2;
				textMeshPro2.transform.position = position2;
				float num3 = (float)Mathf.CeilToInt((num2 + markerLabelOffsetX) / _distanceMarkerInterval) * _distanceMarkerInterval;
				textMeshPro2.name = $"Marker ({num3})";
				textMeshPro2.text = Mathf.RoundToInt(num3).ToString();
			}
			break;
		}
		case Axis.Z:
		{
			Vector3 position = base.transform.position;
			switch (side)
			{
			case WorldMapBorder.Sides.East:
				position.x = worldBounds.xMax;
				break;
			case WorldMapBorder.Sides.West:
				position.x = worldBounds.xMin;
				break;
			default:
				throw new NotImplementedException();
			}
			base.transform.position = position;
			Transform[] visualtransforms = _visualtransforms;
			foreach (Transform obj in visualtransforms)
			{
				Vector3 localScale = obj.localScale;
				localScale.x = worldBounds.size.y;
				obj.localScale = localScale;
			}
			if (_distanceMarkers == null)
			{
				_distanceMarkers = new List<TextMeshPro>(Mathf.CeilToInt(worldBounds.size.x / _distanceMarkerInterval));
			}
			float num = (float)Mathf.CeilToInt(worldBounds.yMin / _distanceMarkerInterval) * _distanceMarkerInterval;
			if (Mathf.Approximately(num, worldBounds.yMin))
			{
				num += _distanceMarkerInterval;
			}
			for (; num < worldBounds.yMax; num += _distanceMarkerInterval)
			{
				TextMeshPro textMeshPro = ReturnDistanceMarker(i++);
				Vector3 position2 = textMeshPro.transform.position;
				position2.z = num;
				textMeshPro.transform.position = position2;
				textMeshPro.name = $"Marker ({num})";
				textMeshPro.text = Mathf.RoundToInt(num).ToString();
			}
			break;
		}
		}
		if (!_distanceMarkers.IsNullOrEmpty())
		{
			for (; i < _distanceMarkers.Count; i++)
			{
				_distanceMarkers[i].gameObject.SetActive(value: false);
			}
		}
	}

	private TextMeshPro ReturnDistanceMarker(int index)
	{
		TextMeshPro textMeshPro;
		if (index < _distanceMarkers.Count)
		{
			textMeshPro = _distanceMarkers[index];
		}
		else
		{
			textMeshPro = UnityEngine.Object.Instantiate(_distanceMarkerPrefab, base.transform);
			_distanceMarkers.Add(textMeshPro);
		}
		textMeshPro.gameObject.SetActive(value: true);
		return textMeshPro;
	}
}
public class WorldMapLandmark : WorldMapPointOfInterest
{
	[SerializeField]
	private GameObject _informationGameObject;

	[SerializeField]
	private TextMeshProUGUI _nameText;

	[SerializeField]
	private float _markerPositionY = 80f;

	[SerializeField]
	[Tooltip("The renderers that need to be updated to show the progress made on the Landmark")]
	private Renderer[] _progressRenderers;

	[SerializeField]
	private ParticleSystem _rescueParticle;

	[SerializeField]
	private GameObject _revealMapIcon;

	[SerializeField]
	private WorldMapReveal _reveal;

	private LandmarkBehaviour _landmarkBehaviour;

	private float _poweredRadius;

	private Bounds _mapBounds;

	private Bounds _worldBounds;

	private RangedFloat _scaleRange;

	private Coroutine _showCoroutine;

	private Collider _collider3D;

	private WorldMapLandmarkPolygonVisual _footprint;

	public LandmarkSpawner LandmarkSpawner { get; private set; }

	public float MarkerPositionY => _markerPositionY;

	public PolygonCollider2D Collider2D { get; private set; }

	public Vector3 Scale => Vector3.one * _scaleRange.Evaluate(GameManager.WorldMapManager.WorldMap.WorldCameraController.ZoomController.CurrentZoomLevel);

	private void Awake()
	{
		if ((bool)_rescueParticle)
		{
			ParticleSystem.MainModule main = _rescueParticle.main;
			main.playOnAwake = false;
			_rescueParticle.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
		}
	}

	private void OnEnable()
	{
		if (_landmarkBehaviour is ActionsBehaviour actionsBehaviour)
		{
			foreach (LandmarkAction action in actionsBehaviour.Actions)
			{
				UpdateLandmarkAction(action);
			}
		}
		if ((bool)_landmarkBehaviour)
		{
			OnLandmarkUpdate(_landmarkBehaviour, null);
		}
		if (_showCoroutine != null)
		{
			StopCoroutine(_showCoroutine);
			_showCoroutine = StartCoroutine(ShowCoroutine());
		}
	}

	private void OnMouseEnter()
	{
		_informationGameObject.SetActive(value: true);
		AudioManager.Play(GameManager.Settings.AudioSettings.LandmarkHoverEnterAudio);
	}

	private void OnMouseExit()
	{
		_informationGameObject.SetActive(value: false);
		AudioManager.Play(GameManager.Settings.AudioSettings.LandmarkHoverExitAudio);
	}

	private void OnDisable()
	{
		_informationGameObject.SetActive(value: false);
	}

	protected override void OnDestroy()
	{
		_landmarkBehaviour.UpdatedEvent.RemoveListener(OnLandmarkUpdate);
		base.OnDestroy();
	}

	public void Initialize(LandmarkSpawner landmarkSpawner)
	{
		LandmarkSpawner = landmarkSpawner;
		_landmarkBehaviour = landmarkSpawner.LandmarkBehaviour;
		_landmarkBehaviour.UpdatedEvent.AddListener(OnLandmarkUpdate);
		_collider3D = GetComponent<Collider>();
		if (_nameText == null)
		{
			UnityEngine.Debug.LogErrorFormat("_nameText == null: '{0}'", base.name);
		}
		else
		{
			_nameText.text = _landmarkBehaviour.Name;
		}
		base.name = _landmarkBehaviour.name;
		base.transform.localPosition = landmarkSpawner.TilePosition.Vector3TopDown();
		base.transform.rotation = landmarkSpawner.Rotation;
		_poweredRadius = Mathf.Pow(GameManager.Settings.GameplaySettings.ConstructionRadius, 2f);
		_informationGameObject.SetActive(value: false);
		_scaleRange = GameSettings.Instance.LandmarkSettings.MapScaling;
		LandmarkMooringPoint landmarkMooringPoint = _landmarkBehaviour.ReturnMooringPoint();
		if ((bool)landmarkMooringPoint)
		{
			Transform entranceTransform = landmarkMooringPoint.EntranceTransform;
			GameObject obj = UnityEngine.Object.Instantiate(GameSettings.Instance.LandmarkSettings.MapMooringPointPrefab, base.transform);
			Vector3 eulerAngles = entranceTransform.transform.rotation.eulerAngles;
			eulerAngles.x = 0f;
			eulerAngles.z = 0f;
			obj.transform.localRotation = Quaternion.Euler(eulerAngles);
			obj.transform.localPosition = entranceTransform.transform.position;
		}
		Initialize((ISpawner)landmarkSpawner);
		if ((bool)_reveal)
		{
			_reveal.Initialize(this);
		}
		if (base.isActiveAndEnabled)
		{
			FinalUpdate.RegisterOneShot(OnEnable);
		}
	}

	public void UpdateScale(Vector3 scale)
	{
		if (ScoutingState.Rumored < base.Spawner.ScoutingState && _showCoroutine == null)
		{
			base.transform.localScale = Scale;
		}
	}

	public void Show(bool instant)
	{
		if (!base.IsActive)
		{
			if (instant)
			{
				Activate();
			}
			else if (_showCoroutine == null)
			{
				_showCoroutine = StartCoroutine(ShowCoroutine());
			}
		}
	}

	private IEnumerator ShowCoroutine()
	{
		Activate();
		base.transform.localScale = Vector3.zero;
		yield return Tweener.TweenRoutine(0.5f, Easing.BounceIn, true, new TransformScaleTweener(base.transform, Scale.x));
		_showCoroutine = null;
	}

	public void AquireCollider(PolygonCollider2D prefab, Transform parent)
	{
		if (!Collider2D)
		{
			Collider2D = PrefabPool.GetInstance(prefab);
			Collider2D.name = LandmarkSpawner.LandmarkBehaviour.Name;
			Collider2D.transform.SetParent(parent);
			Collider2D.transform.Reset();
			Collider2D.SetPath(0, LandmarkSpawner.TileSpacePolygon.Polygon2D);
		}
	}

	public void ReleaseCollider()
	{
		if (Collider2D != null)
		{
			PrefabPool.Repool(Collider2D);
			Collider2D = null;
		}
	}

	public bool RayCast(Ray ray, float maxDistance)
	{
		RaycastHit hitInfo;
		if ((bool)_collider3D)
		{
			return _collider3D.Raycast(ray, out hitInfo, maxDistance);
		}
		return false;
	}

	public Vector3 SelectAndCalulateEntrancePosition()
	{
		Transform transform = GameManager.WorldMapManager.WorldMap.Townheart.transform;
		Vector3 relativePosition = transform.rotation * transform.InverseTransformPoint(base.transform.position);
		GameManager.WorldMapManager.WorldMap.WorldCameraController.SetRelativePosition(relativePosition);
		return ReturnEntrancePosition(base.transform.position, base.transform.rotation);
	}

	public override bool InitializeReveal()
	{
		if ((bool)_reveal)
		{
			return _reveal.InitializeReveal(this);
		}
		return false;
	}

	public override IEnumerator RevealRoutine()
	{
		if ((bool)_reveal)
		{
			yield return _reveal.Reveal(this);
		}
	}

	protected override void OnSpawnerUpdated(ISpawner spawner)
	{
		if (!base.IsActive && LandmarkSpawner.IsBearingActive())
		{
			Activate();
		}
	}

	private void OnLandmarkUpdate(LandmarkBehaviour behaviour, object trigger)
	{
		float value = behaviour.ReturnProgress();
		UpdateLandmarkAction(trigger as ILandmarkAction);
		if (((IReadOnlyCollection<Renderer>)(object)_progressRenderers).IsNullOrEmpty())
		{
			UnityEngine.Debug.LogException(new Exception("[ART] Landmark map visual '" + base.name + "' its progress renderers have not been set yet."));
		}
		else
		{
			Renderer[] progressRenderers = _progressRenderers;
			for (int i = 0; i < progressRenderers.Length; i++)
			{
				progressRenderers[i].material.SetFloat("_Progress", value);
			}
		}
		OnSpawnerUpdated(base.Spawner);
	}

	private void UpdateLandmarkAction(ILandmarkAction action)
	{
		if (!base.isActiveAndEnabled || action == null)
		{
			return;
		}
		if (action is LandmarkActionRescue && (bool)_rescueParticle)
		{
			if (action.IsCompleted)
			{
				if (_rescueParticle.isPlaying)
				{
					_rescueParticle.Stop(withChildren: true, ParticleSystemStopBehavior.StopEmitting);
				}
			}
			else if (!_rescueParticle.isPlaying)
			{
				_rescueParticle.Play(withChildren: true);
			}
		}
		else if (action is LandmarkActionRevealMap && (bool)_revealMapIcon)
		{
			_revealMapIcon.SetActive(!action.IsCompleted);
		}
	}

	public Vector3 ReturnEntrancePosition()
	{
		return ReturnEntrancePosition(base.transform.position, base.transform.rotation);
	}

	private Vector3 ReturnEntrancePosition(Vector3 position, Quaternion rotation)
	{
		LandmarkMooringPoint landmarkMooringPoint = _landmarkBehaviour.ReturnMooringPoint();
		Vector3 vector = position + rotation * landmarkMooringPoint.transform.position.Vector3TopDown();
		Vector3 vector2 = position + rotation * landmarkMooringPoint.EntranceTransform.position.Vector3TopDown();
		Vector3 normalized = (vector2 - vector).normalized;
		if (normalized.magnitude == 0f)
		{
			return Vector3.zero;
		}
		vector2 += normalized * GameManager.Settings.GameplaySettings.ConstructionRadius;
		for (; IsInSquareRadius(vector2.Vector2TopDown(), _poweredRadius); vector2 += normalized)
		{
		}
		return vector2;
	}

	public bool IsInSquareRadius(Vector2 center, float squareRadius)
	{
		Vector2[] polygon2D = LandmarkSpawner.TileSpacePolygon.Polygon2D;
		for (int i = 0; i < polygon2D.Length; i++)
		{
			if ((center - polygon2D[i]).sqrMagnitude < squareRadius)
			{
				return true;
			}
		}
		return false;
	}

	private Vector3 ReturnClosestPosition(Bounds bounds, Vector3 position)
	{
		Vector2 vector = position.Vector2TopDown() - LandmarkSpawner.WorldPosition2D;
		Vector3 vector2 = bounds.ClosestPoint(vector.Vector3TopDown()).SetY(0f);
		return LandmarkSpawner.WorldPosition2D.Vector3TopDown() + vector2;
	}

	public Vector3 ReturnClosestMapPosition(Vector3 worldPosition)
	{
		return ReturnClosestPosition(_mapBounds, worldPosition);
	}

	public Vector3 ReturnClosestWorldPosition(Vector3 worldPosition)
	{
		return ReturnClosestPosition(_worldBounds, worldPosition);
	}

	public Vector3 ReturnClosestPolygonPosition(Vector3 position, out Vector3 edgeStart, out Vector3 edgeEnd, out float distance)
	{
		Polygon2DLine closestSide;
		Vector3 result = LandmarkSpawner.TileSpacePolygon.GetClosestPointOnPolygon(out closestSide, out distance, position.Vector2TopDown()).Vector3TopDown();
		edgeStart = closestSide.Point.Vector3TopDown();
		edgeEnd = edgeStart + closestSide.Vector.Vector3TopDown();
		return result;
	}

	private void OnDrawGizmos()
	{
		if (LandmarkSpawner != null && LandmarkSpawner.TileSpacePolygon != null)
		{
			Vector2[] polygon2D = LandmarkSpawner.TileSpacePolygon.Polygon2D;
			for (int i = 0; i < polygon2D.Length; i++)
			{
				Vector3 start = polygon2D[i].Vector3TopDown();
				int num = (i + 1) % polygon2D.Length;
				Vector3 end = polygon2D[num].Vector3TopDown();
				UnityEngine.Debug.DrawLine(start, end);
			}
		}
	}
}
public class WorldMapLandmarkMarker : MonoBehaviour
{
	[SerializeField]
	private GameObject _marker;

	[SerializeField]
	private SpriteRenderer _iconFront;

	[SerializeField]
	private SpriteRenderer _iconBack;

	private WorldMapLandmark _landmark;

	private readonly Queue<IWorldMapCompassBearingTarget> _activeBearingTargets = new Queue<IWorldMapCompassBearingTarget>();

	private RangedFloat _scaleRange;

	private void Update()
	{
		if (0 < _activeBearingTargets.Count && !IsBearingFeatureActive(_activeBearingTargets.Peek()))
		{
			DeactivateBearingTarget(_activeBearingTargets.Peek());
		}
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.CompassBearingTargetUpdate, OnCompassBearingTargetUpdate);
		GameEventDispatcher.RemoveListener(GameEventType.DeactivateCompassBearingTarget, OnCompassBearingTargetDeactivated);
	}

	public void Initialize(WorldMapLandmark landmark)
	{
		_landmark = landmark;
		_scaleRange = GameSettings.Instance.LandmarkSettings.MapScaling;
		if (_landmark.Spawner is LandmarkSpawner { ScoutingId: not WorldMapScoutingId.None })
		{
			GameEventDispatcher.AddListener(GameEventType.CompassBearingTargetUpdate, OnCompassBearingTargetUpdate);
			GameEventDispatcher.AddListener(GameEventType.DeactivateCompassBearingTarget, OnCompassBearingTargetDeactivated);
		}
		OnCompassBearingTargetUpdate(_landmark.LandmarkSpawner);
	}

	public void UpdateScale(Vector3 scale)
	{
		Transform obj = base.transform;
		Vector3 position = obj.position;
		position.y = _landmark.MarkerPositionY * scale.y;
		obj.position = position;
		obj.localScale = scale;
	}

	private void OnCompassBearingTargetUpdate(IWorldMapCompassBearingTarget bearingTarget)
	{
		if (IsBearingFeatureActive(bearingTarget))
		{
			if (!_activeBearingTargets.Contains(bearingTarget))
			{
				_activeBearingTargets.Enqueue(bearingTarget);
			}
			if (_activeBearingTargets.Peek() == bearingTarget)
			{
				ActivateBearingTarget(bearingTarget);
			}
		}
		else if (0 < _activeBearingTargets.Count)
		{
			DeactivateBearingTarget(bearingTarget);
		}
		else
		{
			base.gameObject.SetActive(value: false);
		}
	}

	private void OnCompassBearingTargetUpdate(GameEvent gameEvent)
	{
		if (gameEvent is MapEvent mapEvent && mapEvent.BearingTarget.IsBearingTo(_landmark.Spawner))
		{
			OnCompassBearingTargetUpdate(mapEvent.BearingTarget);
		}
	}

	private void OnCompassBearingTargetDeactivated(GameEvent gameEvent)
	{
		if (gameEvent is MapEvent mapEvent && mapEvent.BearingTarget.IsBearingTo(_landmark.Spawner))
		{
			DeactivateBearingTarget(mapEvent.BearingTarget);
		}
	}

	private void ActivateBearingTarget(IWorldMapCompassBearingTarget bearingTarget)
	{
		_iconFront.sprite = bearingTarget.BearingIcon;
		_iconBack.sprite = bearingTarget.BearingIcon;
		base.gameObject.SetActive(value: true);
		UpdateScale(_landmark.Scale);
	}

	private void DeactivateBearingTarget(IWorldMapCompassBearingTarget bearingTarget)
	{
		if (_activeBearingTargets.Peek() != bearingTarget)
		{
			_activeBearingTargets.Remove(bearingTarget);
			return;
		}
		_activeBearingTargets.Dequeue();
		if (_activeBearingTargets.Count > 0)
		{
			ActivateBearingTarget(_activeBearingTargets.Peek());
		}
		else
		{
			base.gameObject.SetActive(value: false);
		}
	}

	private bool IsBearingFeatureActive(IWorldMapCompassBearingTarget bearingTarget)
	{
		if (bearingTarget.IsBearingActive())
		{
			return (bearingTarget.BearingFeatures & BearingFeatures.Marker) != 0;
		}
		return false;
	}
}
