public class WorldMapSea : SceneBehaviour
{
	private const string MAP_OVERLAY_IS_VORONOI_PROPERTY = "_IsVoronoi";

	[SerializeField]
	private Material _dayMaterial;

	[SerializeField]
	private Material _nightMaterial;

	[SerializeField]
	private LineRenderer _borderPrefab;

	[SerializeField]
	private float _borderPositionY = -0.1f;

	[SerializeField]
	private LineRenderer _roadPrefab;

	[SerializeField]
	private float _roadPositionY = 1f;

	[SerializeField]
	private WorldRegionTypeFlags[] _noBorderFlags;

	private MeshFilter _meshFilter;

	private Mesh _defaultMesh;

	private MeshRenderer _meshRenderer;

	private Material _defaultMaterial;

	private Vector3 _defaultLocalScale;

	public Rect Bounds { get; private set; }

	private void OnDestroy()
	{
		if ((bool)_defaultMesh)
		{
			_meshFilter.mesh = _defaultMesh;
		}
		if ((bool)_defaultMaterial)
		{
			_meshRenderer.material = _defaultMaterial;
		}
		base.transform.localScale = _defaultLocalScale;
	}

	public void Initialize(WorldTile worldTile)
	{
		_defaultLocalScale = base.transform.localScale;
		if (worldTile.TryReturnWorldMapRegionMeshAndBounds(out var mesh, out var bounds))
		{
			if (_meshFilter == null)
			{
				_meshFilter = GetComponent<MeshFilter>();
			}
			_defaultMesh = _meshFilter.mesh;
			_meshFilter.mesh = mesh;
			_dayMaterial.SetInt("_IsVoronoi", 1);
			_nightMaterial.SetInt("_IsVoronoi", 1);
			if (_meshRenderer == null)
			{
				_meshRenderer = GetComponent<MeshRenderer>();
			}
			_defaultMaterial = _meshRenderer.material;
			_meshRenderer.material = _dayMaterial;
			base.transform.localScale = Vector3.one;
			Transform parent = ((_borderPrefab.transform.parent == null) ? base.transform : _borderPrefab.transform.parent);
			foreach (IWorldRegion region in worldTile.Regions)
			{
				InstantiateRegionBorder(region, parent);
			}
			foreach (RoadSpawner road in worldTile.Roads)
			{
				InstantiateLineRenderer(_roadPrefab, road.Nodes, parent, loop: false, _roadPositionY);
			}
			Bounds = bounds;
		}
		else
		{
			_dayMaterial.SetInt("_IsVoronoi", 0);
			_nightMaterial.SetInt("_IsVoronoi", 0);
		}
	}

	private void InstantiateRegionBorder(IWorldRegion region, Transform parent)
	{
		if (((IReadOnlyCollection<WorldRegionBorderSegment>)(object)region.Border).IsNullOrEmpty() || region.Type == WorldRegionType.Shallow)
		{
			return;
		}
		using ListPool<Vector2>.List list = ListPool<Vector2>.Get();
		int num = -1;
		int num2 = region.Border.Length;
		while (0 < num2--)
		{
			WorldRegionBorderSegment worldRegionBorderSegment = region.Border[num2];
			if (_noBorderFlags.Contains(worldRegionBorderSegment.Flags))
			{
				if (num2 != -1)
				{
					break;
				}
			}
			else
			{
				num = num2;
			}
		}
		if (num == -1)
		{
			return;
		}
		WorldRegionBorderSegment worldRegionBorderSegment2 = region.Border[num];
		WorldRegionBorderSegment worldRegionBorderSegment3 = worldRegionBorderSegment2;
		list.Add(worldRegionBorderSegment2.Start);
		int num3 = region.Border.Length;
		while (0 < num3--)
		{
			WorldRegionBorderSegment worldRegionBorderSegment = region.Border.GetValueWrapped(++num);
			if (_noBorderFlags.Contains(worldRegionBorderSegment.Flags))
			{
				if (worldRegionBorderSegment3 != null)
				{
					list.Add(worldRegionBorderSegment3.End);
					InstantiateLineRenderer(_borderPrefab, list.ToArray(), parent, loop: false, _borderPositionY);
					list.Clear();
					worldRegionBorderSegment3 = null;
				}
			}
			else
			{
				list.Add(worldRegionBorderSegment.Start);
				worldRegionBorderSegment3 = worldRegionBorderSegment;
			}
		}
		if (list.Count > 0)
		{
			list.Add(worldRegionBorderSegment3.End);
			InstantiateLineRenderer(_borderPrefab, list.ToArray(), parent, loop: false, _borderPositionY);
		}
	}

	private void InstantiateLineRenderer(LineRenderer prefab, Vector2[] positions2D, Transform parent, bool loop, float borderPositionY)
	{
		LineRenderer lineRenderer = UnityEngine.Object.Instantiate(prefab, parent);
		int num = positions2D.Length;
		Vector3[] array = new Vector3[num];
		for (int i = 0; i < num; i++)
		{
			array[i] = positions2D[i];
		}
		lineRenderer.loop = loop;
		lineRenderer.positionCount = array.Length;
		lineRenderer.SetPositions(array);
		lineRenderer.gameObject.SetActive(value: true);
		lineRenderer.transform.localScale = Vector3.one;
		lineRenderer.transform.position = new Vector3(0f, borderPositionY, 0f);
	}
}
public class WorldMapTable : MonoBehaviour
{
	[SerializeField]
	private MeshRenderer _tilePrefab;

	[SerializeField]
	private float _minimumWorldMargin = 4000f;

	[SerializeField]
	private Collider _mapPlane;

	private List<MeshRenderer> _tiles;

	public void UpdateWorldBounds(Rect worldBounds)
	{
		Vector3 size = _tilePrefab.bounds.size;
		Vector3 vector = size / 2f;
		int num = Mathf.FloorToInt((worldBounds.xMin - _minimumWorldMargin) / size.x);
		int num2 = Mathf.CeilToInt((worldBounds.xMax + _minimumWorldMargin) / size.x) - num;
		int num3 = Mathf.FloorToInt((worldBounds.yMin - _minimumWorldMargin) / size.z);
		int num4 = Mathf.CeilToInt((worldBounds.yMax + _minimumWorldMargin) / size.z) - num3;
		float num5 = (float)num * size.x + vector.x;
		float num6 = (float)num3 * size.z + vector.z;
		if (_tiles == null)
		{
			_tiles = new List<MeshRenderer>();
		}
		for (int i = 0; i < num2; i++)
		{
			for (int j = 0; j < num4; j++)
			{
				MeshRenderer meshRenderer = ReturnTile(i * num4 + j);
				Vector3 position = meshRenderer.transform.position;
				position.x = num5 + size.x * (float)i;
				position.z = num6 + size.z * (float)j;
				meshRenderer.transform.position = position;
			}
		}
		Rect rect = new Rect((float)num * size.x, (float)num3 * size.z, (float)num2 * size.x, (float)num4 * size.z);
		_mapPlane.transform.localScale = rect.size.Vector3TopDown(_mapPlane.transform.localScale.y);
		_mapPlane.transform.position = rect.center.Vector3TopDown();
	}

	private MeshRenderer ReturnTile(int index)
	{
		if (index < _tiles.Count)
		{
			return _tiles[index];
		}
		MeshRenderer meshRenderer = UnityEngine.Object.Instantiate(_tilePrefab, base.transform);
		meshRenderer.gameObject.SetActive(value: true);
		_tiles.Add(meshRenderer);
		return meshRenderer;
	}
}
public class WorldMapTile : MonoBehaviour
{
	[SerializeField]
	private WorldMapSea _worldMapSea;

	[SerializeField]
	private WorldMapFlotsam _pointOfInterestVisualPrefab;

	[SerializeField]
	private WorldMapScoutableLandmark _scoutableLandmarkPrefab;

	[SerializeField]
	private Renderer _seaRenderer;

	[SerializeField]
	private WorldMapFogOfWar _fogOfWar;

	[Header("Physics")]
	[SerializeField]
	private Transform _physicsParent;

	[SerializeField]
	private PolygonCollider2D _landmarkPhysicsPrefab;

	private List<WorldMapScoutableLandmark>[] _landmarkClusters;

	private readonly List<WorldMapScoutableLandmark> _allLandmarks = new List<WorldMapScoutableLandmark>();

	private readonly List<WorldMapFlotsam> _pointsOfInterest = new List<WorldMapFlotsam>();

	private float _landmarksInterval;

	private Transform _landmarkVisualsParent;

	private Transform _pointOfInterestVisualsParent;

	private Coroutine _initializeCoroutine;

	public WorldTile WorldTile { get; private set; }

	public void Initialize(WorldTile worldTile, float landmarksInterval, bool async)
	{
		WorldTile = worldTile;
		_landmarksInterval = landmarksInterval;
		GameEventDispatcher.AddListener(GameEventType.LandmarkSpawned, OnLandmarkSpawned);
		GameEventDispatcher.AddListener(GameEventType.LandmarkDisposed, OnLandmarkDisposed);
		GameEventDispatcher.AddListener(GameEventType.PointOfInterestSpawned, OnPointOfInterestSpawned);
		if (async)
		{
			_initializeCoroutine = CoroutineMotor.StartRoutine(InitializeCoroutine(worldTile, instant: false));
		}
		else
		{
			InitializeCoroutine(worldTile, instant: true).MoveNext();
		}
	}

	public void UpdateScouting(Vector3 townPosition, float fowRange, float scoutRange)
	{
		foreach (LandmarkSpawner landmark in WorldTile.Landmarks)
		{
			if (landmark.ScoutingState != ScoutingState.Scouted)
			{
				float num = landmark.WorldPosition.DistanceToLeveled(townPosition);
				if (num < scoutRange)
				{
					landmark.SetScoutingState(ScoutingState.Scouted);
				}
				else if (num < fowRange)
				{
					landmark.SetScoutingState(ScoutingState.Confirmed);
				}
			}
		}
		foreach (PointOfInterestSpawner item in WorldTile.PointsOfInterest)
		{
			if (item.ScoutingState != ScoutingState.Scouted && item.WorldPosition.IsInRange(townPosition, fowRange))
			{
				item.SetScoutingState(ScoutingState.Scouted);
			}
		}
	}

	public void Destroy()
	{
		if (_initializeCoroutine != null)
		{
			CoroutineMotor.StopRoutine(_initializeCoroutine);
		}
		DestroyLandmarkVisuals();
		DestroyPointOfInterestVisuals();
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkSpawned, OnLandmarkSpawned);
		GameEventDispatcher.RemoveListener(GameEventType.LandmarkDisposed, OnLandmarkDisposed);
		GameEventDispatcher.RemoveListener(GameEventType.PointOfInterestSpawned, OnPointOfInterestSpawned);
	}

	public void RestoreLastTileFOW()
	{
		_fogOfWar.RestoreLastTileAlphas();
	}

	private IEnumerator InitializeCoroutine(WorldTile worldTile, bool instant)
	{
		_fogOfWar.Initialize(worldTile);
		Vector3 localScale = _seaRenderer.transform.localScale;
		localScale.x = _fogOfWar.GridSizeX * _fogOfWar.TileSizeX;
		localScale.y = _fogOfWar.GridSizeZ * _fogOfWar.TileSizeZ;
		_seaRenderer.sharedMaterial.SetFloat("_MapOverlayScale", worldTile.Scale);
		_seaRenderer.transform.localScale = localScale;
		_worldMapSea.Initialize(worldTile);
		base.transform.localPosition = worldTile.WorldPosition;
		base.gameObject.SetActive(value: true);
		if (instant)
		{
			SpawnLandmarkVisuals(worldTile.Landmarks);
			SpawnPointOfInterestVisuals(worldTile.PointsOfInterest);
		}
		else
		{
			using ListPool<ISpawner>.List spawners = ListPool<ISpawner>.Get();
			spawners.AddRange(worldTile.Landmarks);
			spawners.AddRange(worldTile.PointsOfInterest);
			yield return SpawnVisualsAsync(spawners);
		}
		_initializeCoroutine = null;
	}

	private void SpawnLandmarkVisuals(IReadOnlyList<LandmarkSpawner> landmarks)
	{
		float x = WorldTile.WorldBounds.x;
		InitializeLandmarkVisualsSpawning();
		int i = 0;
		for (int count = landmarks.Count; i < count; i++)
		{
			SpawnLandmarkVisual(landmarks[i], x);
		}
	}

	private void InitializeLandmarkVisualsSpawning()
	{
		if (_landmarkVisualsParent == null)
		{
			_landmarkVisualsParent = new GameObject("Landmarks").transform;
			_landmarkVisualsParent.SetParent(base.transform);
			_landmarkVisualsParent.Reset();
		}
		int num = Mathf.CeilToInt(WorldTile.WorldBounds.size.x / _landmarksInterval);
		_landmarkClusters = new List<WorldMapScoutableLandmark>[num];
		for (int i = 0; i < num; i++)
		{
			_landmarkClusters[i] = new List<WorldMapScoutableLandmark>();
		}
	}

	private void OnLandmarkSpawned(GameEvent gameEvent)
	{
		if (gameEvent is LandmarkNotificationEvent landmarkNotificationEvent && WorldTile.IsParentOfLandmarkSpawner(landmarkNotificationEvent.LandmarkSpawner))
		{
			SpawnLandmarkVisual(landmarkNotificationEvent.LandmarkSpawner, WorldTile.WorldBounds.x);
		}
	}

	private void OnLandmarkDisposed(GameEvent gameEvent)
	{
		if (!(gameEvent is LandmarkNotificationEvent landmarkNotificationEvent))
		{
			return;
		}
		List<WorldMapScoutableLandmark>[] landmarkClusters = _landmarkClusters;
		foreach (List<WorldMapScoutableLandmark> list in landmarkClusters)
		{
			for (int j = 0; j < list.Count; j++)
			{
				WorldMapScoutableLandmark worldMapScoutableLandmark = list[j];
				if (worldMapScoutableLandmark.Landmark.LandmarkSpawner == landmarkNotificationEvent.LandmarkSpawner)
				{
					list.RemoveAt(j);
					UnityEngine.Object.Destroy(worldMapScoutableLandmark.gameObject);
				}
			}
		}
	}

	private bool SpawnLandmarkVisual(LandmarkSpawner spawner, float tileX)
	{
		if (!spawner.Enabled || !spawner.LandmarkBehaviour.Validate())
		{
			return false;
		}
		WorldMapLandmark worldMapLandmark = UnityEngine.Object.Instantiate(spawner.LandmarkBehaviour.MapPrefab, _landmarkVisualsParent);
		worldMapLandmark.Initialize(spawner);
		WorldMapScoutableLandmark worldMapScoutableLandmark = UnityEngine.Object.Instantiate(_scoutableLandmarkPrefab, _landmarkVisualsParent);
		worldMapScoutableLandmark.Initialize(worldMapLandmark, spawner);
		int num = Mathf.FloorToInt((spawner.WorldPosition.x - tileX) / _landmarksInterval);
		_landmarkClusters[num].Add(worldMapScoutableLandmark);
		return true;
	}

	private void DestroyLandmarkVisuals()
	{
		if (_landmarkClusters == null)
		{
			return;
		}
		List<WorldMapScoutableLandmark>[] landmarkClusters = _landmarkClusters;
		foreach (List<WorldMapScoutableLandmark> list in landmarkClusters)
		{
			foreach (WorldMapScoutableLandmark item in list)
			{
				if (!(item == null))
				{
					UnityEngine.Object.Destroy(item.gameObject);
				}
			}
			list.Clear();
		}
		_landmarkClusters = null;
	}

	private void SpawnPointOfInterestVisuals(IReadOnlyList<PointOfInterestSpawner> spawners, bool instant = true)
	{
		InitializePointOfInterestVisualsSpawning();
		int i = 0;
		for (int count = spawners.Count; i < count; i++)
		{
			SpawnPointOfInterestVisual(spawners[i]);
		}
	}

	private void InitializePointOfInterestVisualsSpawning()
	{
		if (_pointOfInterestVisualsParent == null)
		{
			_pointOfInterestVisualsParent = new GameObject("POIs").transform;
			_pointOfInterestVisualsParent.SetParent(base.transform);
			_pointOfInterestVisualsParent.Reset();
		}
		_pointsOfInterest.Clear();
	}

	private void OnPointOfInterestSpawned(GameEvent gameEvent)
	{
		if (gameEvent is MapEvent mapEvent && mapEvent.WorldTile == WorldTile)
		{
			SpawnPointOfInterestVisual(mapEvent.PointOfInterestSpawner);
		}
	}

	private void SpawnPointOfInterestVisual(PointOfInterestSpawner spawner)
	{
		WorldMapFlotsam worldMapFlotsam = UnityEngine.Object.Instantiate(_pointOfInterestVisualPrefab, _pointOfInterestVisualsParent);
		worldMapFlotsam.Initialize(spawner);
		_pointsOfInterest.Add(worldMapFlotsam);
	}

	private void DestroyPointOfInterestVisuals()
	{
		if (_pointsOfInterest.Count == 0)
		{
			return;
		}
		foreach (WorldMapFlotsam item in _pointsOfInterest)
		{
			if (!(item == null))
			{
				UnityEngine.Object.Destroy(item.gameObject);
			}
		}
		_pointsOfInterest.Clear();
	}

	private IEnumerator SpawnVisualsAsync(List<ISpawner> spawners)
	{
		float tileX = WorldTile.WorldBounds.x;
		InitializeLandmarkVisualsSpawning();
		InitializePointOfInterestVisualsSpawning();
		SpawnerSorting.ByDistanceToTownheart(spawners);
		foreach (ISpawner spawner in spawners)
		{
			switch (spawner.Type)
			{
			case ISpawnerType.Landmark:
				if (!SpawnLandmarkVisual(spawner as LandmarkSpawner, tileX))
				{
					continue;
				}
				break;
			case ISpawnerType.PointOfInterest:
				SpawnPointOfInterestVisual(spawner as PointOfInterestSpawner);
				break;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException(spawner.Type.ToString()));
				break;
			}
			yield return null;
		}
	}

	public WorldMapLandmark ReturnClosestWorldmapLandmark(Vector3 position)
	{
		using ListPool<WorldMapScoutableLandmark>.List list = ReturnLandmarks(position.Vector2TopDown());
		int count = list.Count;
		WorldMapLandmark result = null;
		float num = float.MaxValue;
		for (int i = 0; i < count; i++)
		{
			WorldMapLandmark landmark = list[i].Landmark;
			float sqrMagnitude = (landmark.transform.position - position).sqrMagnitude;
			if (sqrMagnitude < num)
			{
				result = landmark;
				num = sqrMagnitude;
			}
		}
		return result;
	}

	public bool HasLandmarkInSquareRadius(Vector2 center, float squareRadius)
	{
		using ListPool<WorldMapScoutableLandmark>.List list = ReturnLandmarks(center);
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			if (list[i].IsInSquareRadius(center, squareRadius))
			{
				return true;
			}
		}
		return false;
	}

	public bool TryReturnRaycastLandmarkInRadius(out WorldMapLandmark landmark, Ray ray, Vector2 center, float radius)
	{
		using ListPool<WorldMapScoutableLandmark>.List list = ReturnLandmarks(center);
		float num = radius * radius;
		int count = list.Count;
		for (int i = 0; i < count; i++)
		{
			landmark = list[i].Landmark;
			if (landmark.Spawner.WorldPosition2D.DistanceToSquared(center) < num && landmark.RayCast(ray, float.MaxValue))
			{
				return true;
			}
		}
		landmark = null;
		return false;
	}

	public bool TryReturnPointOfInterest(out WorldMapPointOfInterest poi, ISpawner spawner)
	{
		if (WorldTile.WorldBounds.Contains(spawner.WorldPosition2D))
		{
			switch (spawner.Type)
			{
			case ISpawnerType.Landmark:
			{
				int num = Mathf.FloorToInt((spawner.WorldPosition.x - WorldTile.WorldBounds.x) / _landmarksInterval);
				List<WorldMapScoutableLandmark> list = _landmarkClusters[num];
				int count2 = list.Count;
				while (0 < count2--)
				{
					poi = list[count2].Landmark;
					if (poi.Spawner == spawner)
					{
						return true;
					}
				}
				break;
			}
			case ISpawnerType.PointOfInterest:
			{
				int count = _pointsOfInterest.Count;
				while (0 < count--)
				{
					poi = _pointsOfInterest[count];
					if (poi.Spawner == spawner)
					{
						return true;
					}
				}
				break;
			}
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				break;
			}
		}
		poi = null;
		return false;
	}

	public WorldMapFogOfWar.PersistentData ReturnFogOfWarPersistentData()
	{
		if ((bool)_fogOfWar)
		{
			return new WorldMapFogOfWar.PersistentData(_fogOfWar);
		}
		return null;
	}

	public void UpdatePhyscis(Vector2 position, float rangeSquared)
	{
		using ListPool<WorldMapScoutableLandmark>.List list = ReturnLandmarks(position);
		foreach (WorldMapScoutableLandmark item in list)
		{
			if ((bool)item.Landmark.Collider2D)
			{
				if (!item.Landmark.IsInSquareRadius(position, rangeSquared))
				{
					item.Landmark.ReleaseCollider();
				}
			}
			else if (item.Landmark.Spawner.WorldPosition2D.DistanceToSquared(position) <= rangeSquared)
			{
				item.Landmark.AquireCollider(_landmarkPhysicsPrefab, _physicsParent);
			}
		}
	}

	public ListPool<WorldMapScoutableLandmark>.List ReturnLandmarks(Vector2 position, int range = 1)
	{
		ListPool<WorldMapScoutableLandmark>.List list = ListPool<WorldMapScoutableLandmark>.Get();
		PopulateLandmarks(list, position, range);
		return list;
	}

	public void PopulateLandmarks(List<WorldMapScoutableLandmark> landmarks, Vector2 position, int range = 1)
	{
		int num = Mathf.FloorToInt((position.x - WorldTile.WorldBounds.x) / _landmarksInterval);
		int num2 = num + range;
		for (int i = num - range; i <= num2; i++)
		{
			if (i >= 0 && _landmarkClusters.Length > i)
			{
				landmarks.AddRange(_landmarkClusters[i]);
			}
		}
	}

	public IReadOnlyList<WorldMapFlotsam> GetAllFlotsam()
	{
		return _pointsOfInterest;
	}
}
public class WorldMapTownheart : SceneBehaviour
{
	[Serializable]
	private struct Visual
	{
		public BuildableProperties BuildableProperties;

		public GameObject GameObject;

		public Animator Animator;
	}

	[SerializeField]
	[NamedArrayElement(new string[] { "BuildableProperties" })]
	private Visual[] _visuals;

	[SerializeField]
	[FormerlySerializedAs("DirectionIndicator")]
	private Transform _directionIndicator;

	[SerializeField]
	private WorldMapConstruction _worldMapConstruction;

	[Range(0.1f, 1f)]
	[SerializeField]
	private float _physicsPositionLerp = 0.9f;

	[SerializeField]
	private Transform _movementRangeTransform;

	[SerializeField]
	private GameObject _ozoneShield;

	[Header("Audio")]
	public FMODEventEmitter FMODEventEmitter;

	[FormerlySerializedAs("_engineAudio")]
	public AudioClipProperties EngineAudio;

	[FormerlySerializedAs("_movingAudio")]
	public AudioClipProperties MovingAudio;

	private Visual _visual;

	private Engine _engine;

	private List<WorldMapConstruction> _constructions;

	private WorldMapTownheartPhycis2D _physics;

	private Vector3 _targetPosition;

	private Quaternion _targetRotation;

	private PajamaLlama.ObjectPool<WorldMapConstruction> _worldMapConstructionPool;

	public Transform DirectionIndicator => _directionIndicator;

	public Vector3 Position { get; private set; }

	public bool Initialized { get; private set; }

	public bool IsMoving { get; private set; }

	public bool DidMove { get; private set; }

	private void OnEnable()
	{
		OnEnergyUpdate();
		_ozoneShield.SetActive(GameManager.WorldManager.World.HasEndTile);
	}

	private void LateUpdate()
	{
		float num = Engine.ReturnRange() * 2f;
		_movementRangeTransform.localScale = new Vector3(num, 1f, num);
		if (!(1f <= _physicsPositionLerp) && (!_targetPosition.Approximately(Position) || !_targetRotation.eulerAngles.Approximately(base.transform.rotation.eulerAngles)))
		{
			SetPositionAndRotation(Vector3.Slerp(Position, _targetPosition, _physicsPositionLerp), Quaternion.Slerp(base.transform.rotation, _targetRotation, _physicsPositionLerp));
		}
	}

	private void OnDisable()
	{
		FMODEventEmitter.Stop();
	}

	private void OnDestroy()
	{
		GameEventDispatcher.RemoveListener(GameEventType.EnergyConsumed, OnEnergyUpdate);
		GameEventDispatcher.RemoveListener(GameEventType.EnergyProduced, OnEnergyUpdate);
	}

	public void Initialize(Engine engine, WorldMapTownheartPhycis2D physics = null)
	{
		_engine = engine;
		_physics = physics;
		InitializeVisual();
		GameEventDispatcher.AddListener(GameEventType.EnergyConsumed, OnEnergyUpdate);
		GameEventDispatcher.AddListener(GameEventType.EnergyProduced, OnEnergyUpdate);
		DidMove = false;
		Position = (_targetPosition = GameManager.WorldManager.World.TownheartWorldPosition);
		_targetRotation = GameManager.WorldManager.World.TownheartRotation;
		base.transform.SetPositionAndRotation(Position, _targetRotation);
		if ((bool)_physics)
		{
			InitializeWorldMapConstructions();
		}
		Initialized = true;
	}

	public void Teleport(Vector3 position, Quaternion rotation)
	{
		if (_physics != null)
		{
			_physics.SetPositionAndRotation(position, rotation);
		}
		_targetPosition = position;
		_targetRotation = rotation;
		SetPositionAndRotation(position, rotation);
	}

	private void OnEnergyUpdate(GameEvent gameEvent = null)
	{
		_visual.Animator.SetBool("IsBatteryEmpty", _engine.EnergyGrid.IsEmpty || Engine.IsCoolingDown);
	}

	public void OnStartMove()
	{
		if (!IsMoving)
		{
			_visual.Animator.SetBool("IsMoving", value: true);
			FMODEventEmitter.StopAllAndPlay(MovingAudio);
			IsMoving = true;
			DidMove = true;
		}
	}

	public void OnEndMove()
	{
		if (IsMoving)
		{
			_visual.Animator.SetBool("IsMoving", value: false);
			FMODEventEmitter.StopAllAndPlay(EngineAudio);
			IsMoving = false;
		}
	}

	private void InitializeVisual()
	{
		bool flag = false;
		if ((bool)Construction.Townheart)
		{
			Visual[] visuals = _visuals;
			for (int i = 0; i < visuals.Length; i++)
			{
				Visual visual = visuals[i];
				if (visual.BuildableProperties == Construction.Townheart.Buildable.Properties)
				{
					_visual = visual;
					_visual.GameObject.SetActive(value: true);
					flag = true;
				}
				else
				{
					visual.GameObject.SetActive(value: false);
				}
			}
		}
		if (!flag)
		{
			_visual = _visuals[0];
			_visual.GameObject.SetActive(value: true);
		}
	}

	private void InitializeWorldMapConstructions()
	{
		_worldMapConstructionPool = new PajamaLlama.ObjectPool<WorldMapConstruction>(() => UnityEngine.Object.Instantiate(_worldMapConstruction, base.transform));
		_constructions = new List<WorldMapConstruction>();
		if (Community.PlayerCommunity != null)
		{
			foreach (Construction construction in Community.PlayerCommunity.Constructions)
			{
				AddConstruction(construction);
			}
		}
		GameEventDispatcher.AddListener(GameEventType.ConstructionAddedToCommunity, OnConstructionAddedToCommunity);
		GameEventDispatcher.AddListener(GameEventType.ConstructionRemovedFromCommunity, OnConstructionRemovedFromCommunity);
	}

	private void OnConstructionAddedToCommunity(GameEvent gameEvent)
	{
		if (gameEvent is BuildableEvent buildableEvent && buildableEvent.Buildable.TryReturnBuildableExtendable<Construction>(out var buildableExtendable) && buildableEvent.Buildable.Community == Community.PlayerCommunity)
		{
			AddConstruction(buildableExtendable);
		}
	}

	private void OnConstructionRemovedFromCommunity(GameEvent gameEvent)
	{
		if (!(gameEvent is BuildableEvent buildableEvent) || buildableEvent.Buildable.Community != Community.PlayerCommunity)
		{
			return;
		}
		int count = _constructions.Count;
		while (0 < count--)
		{
			WorldMapConstruction worldMapConstruction = _constructions[count];
			if (worldMapConstruction.Construction.Buildable == buildableEvent.Buildable)
			{
				_physics.RemoveConstruction(worldMapConstruction);
				worldMapConstruction.gameObject.SetActive(value: false);
				_worldMapConstructionPool.Return(worldMapConstruction);
				_constructions.RemoveAt(count);
				break;
			}
		}
	}

	private void AddConstruction(Construction constructionToAdd)
	{
		foreach (WorldMapConstruction construction in _constructions)
		{
			if (construction.Construction == constructionToAdd)
			{
				return;
			}
		}
		constructionToAdd.Buildable.OutlinePolygon.Update();
		WorldMapConstruction worldMapConstruction = _worldMapConstructionPool.Get();
		worldMapConstruction.Initialize(constructionToAdd);
		worldMapConstruction.gameObject.SetActive(value: true);
		_constructions.Add(worldMapConstruction);
		_physics.AddConstruction(worldMapConstruction);
	}

	public void SetTargetPositionAndRotation(Vector3 position, Quaternion rotation)
	{
		_targetPosition = position;
		_targetRotation = rotation;
		if (_physicsPositionLerp == 1f)
		{
			SetPositionAndRotation(position, rotation);
		}
	}

	private void SetPositionAndRotation(Vector3 position, Quaternion rotation)
	{
		Transform obj = base.transform;
		Vector3 position2 = (Position = position);
		obj.SetPositionAndRotation(position2, rotation);
	}
}
public class WorldMapTownheartPhycis2D : SceneBehaviour
{
	public enum Modes
	{
		MoveTo,
		Velocity,
		Force
	}

	[SerializeField]
	private Rigidbody2D _rigidbody;

	[SerializeField]
	private PolygonCollider2D _collider;

	[SerializeField]
	private CircleCollider2D _ozoneShieldCollider;

	[SerializeField]
	private PolygonCollider2D _constructionColliderPrefab;

	[SerializeField]
	private Modes _mode;

	[SerializeField]
	private float _defaultAngulareDrag = 10f;

	[SerializeField]
	private float _keyAngularDrag;

	[SerializeField]
	private float _mouseAngularDrag;

	[SerializeField]
	[Range(1f, 5f)]
	[Tooltip("Mouse rotation multiplier that is lerped based on the angle between the direct of the town and the direction to the target position.")]
	private float _mouseRotationSpeedMultiplier = 2.5f;

	[Header("Actions")]
	[SerializeField]
	private RewiredAction _forward;

	[SerializeField]
	private RewiredAction _backward;

	[SerializeField]
	private RewiredAction _rotateLeft;

	[SerializeField]
	private RewiredAction _rotateRight;

	[SerializeField]
	private UIFlagSetter _flagSetter;

	private WorldMap _worldMap;

	private Engine _engine;

	private Vector2 _position;

	private bool _doMouseMovement;

	private Vector2 _mouseMovementTarget;

	private float _mouseMovementDirection;

	private float _simulationTimer;

	private Dictionary<WorldMapConstruction, PolygonCollider2D> _colliders;

	private PajamaLlama.ObjectPool<PolygonCollider2D> _colliderPool;

	public Vector3 Position => _rigidbody.position.Vector3TopDown();

	public Quaternion Rotation => Quaternion.Euler(0f, 0f - _rigidbody.rotation, 0f);

	public bool ProcessedInput { get; private set; }

	public bool Moved { get; private set; }

	public float DistanceMoved { get; private set; }

	public MouseMovementCursorProperties.Gear Gear { get; private set; }

	public RewiredAction Forward => _forward;

	public RewiredAction Backward => _backward;

	public RewiredAction RotateLeft => _rotateLeft;

	public RewiredAction RotateRight => _rotateRight;

	private void OnEnable()
	{
		SetVelocity(0f, 0f);
		if ((bool)_ozoneShieldCollider)
		{
			_ozoneShieldCollider.gameObject.SetActive(GameManager.WorldManager.World.HasEndTile);
		}
		_rigidbody.MovePosition(_worldMap.Townheart.Position.Vector2TopDown());
		_rigidbody.MoveRotation(0f - _worldMap.Townheart.transform.rotation.eulerAngles.y);
		_position = _rigidbody.position;
	}

	private void FixedUpdate()
	{
		DistanceMoved += Vector2.Distance(_rigidbody.position, _position);
		_position = _rigidbody.position;
		_worldMap.Townheart.SetTargetPositionAndRotation(Position, Rotation);
		ProcessedInput = false;
		_flagSetter.enabled = FlotsamInputManager.IsJoystick && FlotsamInputManager.GetAnyButton(_forward.ActionId, _backward.ActionId);
		if (!_worldMap.IsTownMovementBlocked)
		{
			UpdateMovementInputs();
		}
		else
		{
			Moved = false;
		}
	}

	private void UpdateMovementInputs()
	{
		MoveWithKeys();
		if (FlotsamInputManager.HasActiveInput(InputFlags.MouseAndKeyboard) && _doMouseMovement)
		{
			MoveWithMouse(_mouseMovementTarget, _mouseMovementDirection);
		}
		Moved = _worldMap.MovementSpeed / 2f * 0.033f < DistanceMoved;
	}

	private void Update()
	{
		GameSpeed gameSpeed = GameSpeedManager.GameSpeed;
		if ((uint)(gameSpeed - -1) <= 1u)
		{
			DistanceMoved = 0f;
			if (Physics2D.simulationMode == SimulationMode2D.Script)
			{
				_simulationTimer += Time.unscaledDeltaTime;
				while (_simulationTimer >= Time.fixedDeltaTime)
				{
					_simulationTimer -= Time.fixedDeltaTime;
					Physics2D.Simulate(Time.fixedDeltaTime);
					FixedUpdate();
				}
			}
		}
		else
		{
			_simulationTimer = 0f;
		}
	}

	private void LateUpdate()
	{
		GameSpeed gameSpeed = GameSpeedManager.GameSpeed;
		if ((uint)(gameSpeed - -1) > 1u)
		{
			DistanceMoved = 0f;
		}
	}

	public void Initialize(WorldMap worldMap, Engine engine)
	{
		_worldMap = worldMap;
		_engine = engine;
		_rigidbody.transform.position = GameManager.WorldManager.World.TownheartWorldPosition.Vector2TopDown();
		_rigidbody.transform.rotation = Quaternion.Euler(0f, 0f, 0f - GameManager.WorldManager.World.TownheartRotation.eulerAngles.y);
		_colliders = new Dictionary<WorldMapConstruction, PolygonCollider2D>();
		_colliderPool = new PajamaLlama.ObjectPool<PolygonCollider2D>(() => UnityEngine.Object.Instantiate(_constructionColliderPrefab, base.transform));
	}

	public void SetPositionAndRotation(Vector3 position, Quaternion rotation)
	{
		_position = position;
		_rigidbody.transform.position = position;
		_rigidbody.transform.rotation = rotation;
	}

	public void StopMouseMovement()
	{
		_doMouseMovement = false;
	}

	private void MoveWithKeys()
	{
		Vector2 movementInput = FlotsamInputManager.GetMovementInput(_rotateLeft, _rotateRight, _backward, _forward);
		if (movementInput.sqrMagnitude != 0f)
		{
			float num = Mathf.Clamp(movementInput.y, -1f, 1f) * _worldMap.MovementSpeed;
			float num2 = Mathf.Clamp(movementInput.x, -1f, 1f) * (0f - _worldMap.RotationSpeed);
			if (Mathf.Approximately(0f, num) || Mathf.Approximately(num2, 0f))
			{
				_rigidbody.angularDamping = _defaultAngulareDrag;
			}
			else
			{
				_rigidbody.angularDamping = _keyAngularDrag;
			}
			ApplyMovementAndRotation(num, num2);
			ProcessedInput = true;
		}
	}

	private void MoveWithMouse(Vector2 target, float direction, float speedMultiplier = 1f)
	{
		float movement = direction * _worldMap.MovementSpeed * speedMultiplier;
		float num = _worldMap.RotationSpeed * Time.fixedDeltaTime;
		Vector2 to = target - _rigidbody.position;
		float num2 = ((Gear != MouseMovementCursorProperties.Gear.Reverse) ? Vector2.SignedAngle((Vector2)_rigidbody.transform.up, to) : Vector2.SignedAngle((Vector2)(-_rigidbody.transform.up), to));
		float num3 = Mathf.Abs(num2);
		num *= Mathf.Lerp(1f, _mouseRotationSpeedMultiplier, num3 / 180f);
		if (Mathf.Approximately(num2, 0f))
		{
			num = 0f;
		}
		else if (num2 < 0f)
		{
			num = Mathf.Max(0f - num, num2);
		}
		else if (0f < num2)
		{
			num = Mathf.Min(num, num2);
		}
		_rigidbody.angularDamping = _mouseAngularDrag;
		ApplyMovementAndRotation(movement, num / Time.fixedDeltaTime);
		ProcessedInput = true;
	}

	private void MoveWithJoystick()
	{
		Vector2 rightStick = FlotsamInputManager.GetRightStick();
		float angle = 0f - Vector2.SignedAngle(Vector2.up, rightStick.normalized);
		Vector3 vector = _worldMap.WorldCameraController.transform.forward.Vector3TopDown();
		Vector3 position = _worldMap.Townheart.transform.position;
		vector.Normalize();
		vector = Quaternion.AngleAxis(angle, Vector3.up) * vector;
		Vector3 vector2 = position + vector * 150f;
		_worldMap.Townheart.DirectionIndicator.transform.position = vector2;
		MoveWithMouse(vector2.Vector2TopDown(), 1f, rightStick.magnitude);
	}

	private void ApplyMovementAndRotation(float movement, float rotation)
	{
		movement = _engine.ReturnMoveableDistance(movement * Time.fixedUnscaledDeltaTime) / Time.fixedUnscaledDeltaTime;
		if (movement != 0f)
		{
			switch (_mode)
			{
			case Modes.Velocity:
				SetVelocity(movement, rotation);
				break;
			case Modes.Force:
				AddForceAndTorque(movement, rotation);
				break;
			default:
				MovePositionAndRotation(movement * Time.fixedUnscaledDeltaTime, rotation * Time.fixedUnscaledDeltaTime);
				break;
			}
		}
	}

	private void MovePositionAndRotation(float movement, float rotation)
	{
		Vector2 vector = _rigidbody.transform.up;
		_rigidbody.MovePosition(_rigidbody.position + vector * movement);
		_rigidbody.MoveRotation(_rigidbody.rotation + rotation);
	}

	private void SetVelocity(float directionalVelocity, float angularVelocity)
	{
		_rigidbody.linearVelocity = _rigidbody.transform.up * directionalVelocity;
		_rigidbody.angularVelocity = angularVelocity;
	}

	private void AddForceAndTorque(float movement, float rotation)
	{
		Vector2 force = _rigidbody.transform.up * movement * (1f / GameSpeedManager.FixedScaledDeltaTime);
		float torque = rotation * (MathF.PI / 180f) * _rigidbody.inertia / Mathf.Max(Time.timeScale, 1f);
		_rigidbody.AddForce(force, ForceMode2D.Force);
		_rigidbody.AddTorque(torque, ForceMode2D.Force);
	}

	public void SetColliderVertices(List<WorldMapConstruction> constructions)
	{
		_collider.enabled = false;
		_collider.isTrigger = true;
		_collider.pathCount = constructions.Count;
		for (int i = 0; i < _collider.pathCount; i++)
		{
			_collider.SetPath(i, constructions[i].Polygon.Polygon2D);
		}
		_collider.enabled = true;
		_rigidbody.centerOfMass = Vector2.zero;
	}

	public void AddConstruction(WorldMapConstruction construction)
	{
		if (!_colliders.TryGetValue(construction, out var value))
		{
			value = _colliderPool.Get();
			value.name = construction.Construction.Buildable.Properties.name;
			value.pathCount = 1;
			value.gameObject.SetActive(value: true);
			_colliders.Add(construction, value);
		}
		value.SetPath(0, construction.Polygon.Polygon2D);
	}

	public void RemoveConstruction(WorldMapConstruction construction)
	{
		if (_colliders.TryGetValue(construction, out var value))
		{
			value.gameObject.SetActive(value: false);
			_colliderPool.Return(value);
			_colliders.Remove(construction);
		}
	}

	public void SetMouseMovementTargetAndDirection(Vector3 mouseMovementTarget, MouseMovementCursorProperties.Gear gear)
	{
		_doMouseMovement = true;
		_mouseMovementTarget = mouseMovementTarget.Vector2TopDown();
		float mouseMovementDirection;
		switch (gear)
		{
		case MouseMovementCursorProperties.Gear.Forward:
			mouseMovementDirection = 1f;
			break;
		case MouseMovementCursorProperties.Gear.Reverse:
		case MouseMovementCursorProperties.Gear.ForwardReverse:
			mouseMovementDirection = -1f;
			break;
		default:
			mouseMovementDirection = 0f;
			break;
		}
		_mouseMovementDirection = mouseMovementDirection;
		Gear = gear;
	}
}
[RequireComponent(typeof(Renderer))]
