[ExecuteInEditMode]
public class PlanarReflection : MonoBehaviour
{
	public bool m_DisablePixelLights = true;

	public int m_TextureResolution = 1024;

	public float m_clipPlaneOffset = 0.07f;

	public LayerMask m_ReflectLayers = -1;

	private Hashtable m_ReflectionCameras = new Hashtable();

	private RenderTexture m_ReflectionTexture;

	private int m_OldReflectionTextureSize;

	private static bool s_InsideRendering;

	private Renderer _renderer;

	private Camera _currentCam;

	private MeshFilter _meshFilter;

	public void OnWillRenderObject()
	{
		if (_renderer == null)
		{
			_renderer = GetComponent<Renderer>();
		}
		if (!base.enabled || !_renderer || !_renderer.sharedMaterial || !_renderer.enabled)
		{
			return;
		}
		_currentCam = Camera.current;
		if (!_currentCam || s_InsideRendering)
		{
			return;
		}
		s_InsideRendering = true;
		CreateSurfaceObjects(_currentCam, out var reflectionCamera);
		Vector3 position = base.transform.position;
		Vector3 up = base.transform.up;
		int pixelLightCount = QualitySettings.pixelLightCount;
		if (m_DisablePixelLights)
		{
			QualitySettings.pixelLightCount = 0;
		}
		UpdateCameraModes(_currentCam, reflectionCamera);
		float w = 0f - Vector3.Dot(up, position) - m_clipPlaneOffset;
		Vector4 plane = new Vector4(up.x, up.y, up.z, w);
		Matrix4x4 reflectionMat = Matrix4x4.zero;
		CalculateReflectionMatrix(ref reflectionMat, plane);
		Vector3 position2 = _currentCam.transform.position;
		Vector3 position3 = reflectionMat.MultiplyPoint(position2);
		reflectionCamera.worldToCameraMatrix = _currentCam.worldToCameraMatrix * reflectionMat;
		Vector4 clipPlane = CameraSpacePlane(reflectionCamera, position, up, 1f);
		Matrix4x4 projectionMatrix = _currentCam.CalculateObliqueMatrix(clipPlane);
		reflectionCamera.projectionMatrix = projectionMatrix;
		reflectionCamera.cullingMask = -17 & m_ReflectLayers.value;
		reflectionCamera.targetTexture = m_ReflectionTexture;
		GL.invertCulling = true;
		reflectionCamera.transform.position = position3;
		Vector3 eulerAngles = _currentCam.transform.eulerAngles;
		reflectionCamera.transform.eulerAngles = new Vector3(0f, eulerAngles.y, eulerAngles.z);
		reflectionCamera.Render();
		reflectionCamera.transform.position = position2;
		GL.invertCulling = false;
		Material[] sharedMaterials = _renderer.sharedMaterials;
		foreach (Material material in sharedMaterials)
		{
			if (material.HasProperty("_ReflectionTex"))
			{
				material.SetTexture("_ReflectionTex", m_ReflectionTexture);
			}
		}
		if (m_DisablePixelLights)
		{
			QualitySettings.pixelLightCount = pixelLightCount;
		}
		s_InsideRendering = false;
	}

	private void OnDisable()
	{
		if ((bool)m_ReflectionTexture)
		{
			UnityEngine.Object.DestroyImmediate(m_ReflectionTexture);
			m_ReflectionTexture = null;
		}
		foreach (DictionaryEntry reflectionCamera in m_ReflectionCameras)
		{
			UnityEngine.Object.DestroyImmediate(((Camera)reflectionCamera.Value).gameObject);
		}
		m_ReflectionCameras.Clear();
	}

	private void UpdateCameraModes(Camera src, Camera dest)
	{
		if (dest == null)
		{
			return;
		}
		dest.clearFlags = src.clearFlags;
		dest.backgroundColor = src.backgroundColor;
		if (src.clearFlags == CameraClearFlags.Skybox)
		{
			Skybox skybox = src.GetComponent(typeof(Skybox)) as Skybox;
			Skybox skybox2 = dest.GetComponent(typeof(Skybox)) as Skybox;
			if (!skybox || !skybox.material)
			{
				skybox2.enabled = false;
			}
			else
			{
				skybox2.enabled = true;
				skybox2.material = skybox.material;
			}
		}
		dest.farClipPlane = src.farClipPlane;
		dest.nearClipPlane = src.nearClipPlane;
		dest.orthographic = src.orthographic;
		dest.fieldOfView = src.fieldOfView;
		dest.aspect = src.aspect;
		dest.orthographicSize = src.orthographicSize;
	}

	private void CreateSurfaceObjects(Camera currentCamera, out Camera reflectionCamera)
	{
		reflectionCamera = null;
		if (!m_ReflectionTexture || m_OldReflectionTextureSize != m_TextureResolution)
		{
			if ((bool)m_ReflectionTexture)
			{
				UnityEngine.Object.DestroyImmediate(m_ReflectionTexture);
			}
			m_ReflectionTexture = new RenderTexture(m_TextureResolution, m_TextureResolution, 16);
			m_ReflectionTexture.name = "__SurfaceReflection" + GetInstanceID();
			m_ReflectionTexture.isPowerOfTwo = true;
			m_ReflectionTexture.hideFlags = HideFlags.DontSave;
			m_OldReflectionTextureSize = m_TextureResolution;
		}
		reflectionCamera = m_ReflectionCameras[currentCamera] as Camera;
		if (!reflectionCamera)
		{
			GameObject gameObject = new GameObject("Surface Refl Camera id" + GetInstanceID() + " for " + currentCamera.GetInstanceID(), typeof(Camera), typeof(Skybox));
			reflectionCamera = gameObject.GetComponent<Camera>();
			reflectionCamera.enabled = false;
			reflectionCamera.transform.position = base.transform.position;
			reflectionCamera.transform.rotation = base.transform.rotation;
			reflectionCamera.gameObject.AddComponent<FlareLayer>();
			gameObject.hideFlags = HideFlags.DontSave;
			m_ReflectionCameras[currentCamera] = reflectionCamera;
		}
	}

	private static float sgn(float a)
	{
		if (a > 0f)
		{
			return 1f;
		}
		if (a < 0f)
		{
			return -1f;
		}
		return 0f;
	}

	private Vector4 CameraSpacePlane(Camera cam, Vector3 pos, Vector3 normal, float sideSign)
	{
		Vector3 point = pos + normal * m_clipPlaneOffset;
		Matrix4x4 worldToCameraMatrix = cam.worldToCameraMatrix;
		Vector3 lhs = worldToCameraMatrix.MultiplyPoint(point);
		Vector3 rhs = worldToCameraMatrix.MultiplyVector(normal).normalized * sideSign;
		return new Vector4(rhs.x, rhs.y, rhs.z, 0f - Vector3.Dot(lhs, rhs));
	}

	private static void CalculateReflectionMatrix(ref Matrix4x4 reflectionMat, Vector4 plane)
	{
		reflectionMat.m00 = 1f - 2f * plane[0] * plane[0];
		reflectionMat.m01 = -2f * plane[0] * plane[1];
		reflectionMat.m02 = -2f * plane[0] * plane[2];
		reflectionMat.m03 = -2f * plane[3] * plane[0];
		reflectionMat.m10 = -2f * plane[1] * plane[0];
		reflectionMat.m11 = 1f - 2f * plane[1] * plane[1];
		reflectionMat.m12 = -2f * plane[1] * plane[2];
		reflectionMat.m13 = -2f * plane[3] * plane[1];
		reflectionMat.m20 = -2f * plane[2] * plane[0];
		reflectionMat.m21 = -2f * plane[2] * plane[1];
		reflectionMat.m22 = 1f - 2f * plane[2] * plane[2];
		reflectionMat.m23 = -2f * plane[3] * plane[2];
		reflectionMat.m30 = 0f;
		reflectionMat.m31 = 0f;
		reflectionMat.m32 = 0f;
		reflectionMat.m33 = 1f;
	}
}
[RequireComponent(typeof(Renderer))]
public class FlotsamFoamTransformer : MonoBehaviour
{
	[Tooltip("If enabled transform will always try to follow the rotation of the original parent, even if reparented. Because we are dealing with foamquads only the y rotations will be respected. For the other rotations use the RotationOffsets.")]
	[SerializeField]
	private bool _maintainOriginalLocalParentRotation;

	[Tooltip("If enabled transform will always try to follow the local position relative to the original parent, even if reparented. Because we are dealing with foamquads only the xz positions will be respected. The y position will be controlled by the water and HeightOffset.")]
	[SerializeField]
	private bool _maintainOriginalLocalParentOffset;

	[Header("Transform offsets")]
	[Tooltip("How far above the water surface should the transform follow the water.")]
	[SerializeField]
	private float _heightOffset = 0.05f;

	[Tooltip("Offsets to use for the rotation of the foam.")]
	[SerializeField]
	private Vector3 _rotationOffsets = new Vector3(90f, 0f, 0f);

	private static Transform _foamParent;

	private Transform _originalParentTransform;

	private Renderer _targetFoamRenderer;

	private Buoyancy _parentBuoyancy;

	private Vector3 _targetPosition = Vector3.zero;

	private Vector3 _originalParentOffset = Vector3.zero;

	private Quaternion _originalParentRotation = Quaternion.identity;

	private void Start()
	{
		if (_foamParent == null)
		{
			_foamParent = new GameObject("FoamQuads").transform;
		}
		_originalParentTransform = base.transform.parent;
		_targetFoamRenderer = GetComponentInParent<Renderer>();
		_parentBuoyancy = GetComponentInParent<Buoyancy>();
		_originalParentOffset = base.transform.localPosition;
		_originalParentRotation = base.transform.localRotation;
		base.transform.parent = _foamParent;
		_targetPosition = _originalParentTransform.position + (_maintainOriginalLocalParentOffset ? _originalParentOffset : Vector3.zero);
		_targetPosition.y = _heightOffset;
		base.transform.position = _targetPosition;
	}

	private void Update()
	{
		if (_originalParentTransform == null || _targetFoamRenderer == null)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		if (CompareTag("Flotsam"))
		{
			if (!GameManager.WorldManager.FlotsamParent.gameObject.activeSelf)
			{
				if (_targetFoamRenderer.enabled)
				{
					_targetFoamRenderer.enabled = false;
				}
				return;
			}
			if (!_targetFoamRenderer.enabled)
			{
				_targetFoamRenderer.enabled = true;
			}
		}
		if (_maintainOriginalLocalParentRotation)
		{
			Quaternion quaternion = _originalParentTransform.rotation * _originalParentRotation;
			quaternion = Quaternion.Euler(_rotationOffsets.x, quaternion.eulerAngles.y, _rotationOffsets.y);
			base.transform.rotation = quaternion;
		}
		else
		{
			base.transform.rotation = Quaternion.Euler(_rotationOffsets.x, _originalParentTransform.rotation.eulerAngles.y, _rotationOffsets.y);
		}
		_targetPosition = _originalParentTransform.position + (_maintainOriginalLocalParentOffset ? (_originalParentTransform.rotation * _originalParentOffset) : Vector3.zero);
		_targetPosition.y = _heightOffset;
		base.transform.position = _targetPosition;
	}
}
[ExecuteInEditMode]
public class WaterManager : MonoBehaviour
{
	public class WaterHeightCalculation
	{
		public delegate void Callback(WaterHeightCalculation calculation);

		internal bool _queued;

		internal bool _locked;

		internal Exception _exception;

		private WaterManager _waterManager;

		private Transform _transform;

		private List<Vector3> _voxels;

		private Callback _callback;

		private Transform transform;

		private System.Action onWaterHeightCalculationCallback;

		public Vector3 Position { get; private set; }

		public float PositionWaterHeight { get; set; }

		public int VoxelCount { get; private set; }

		public Vector3[] VoxelPositions { get; private set; }

		public float[] VoxelWaterHeights { get; private set; }

		public bool ApplyForces { get; set; }

		public WaterHeightCalculation(Transform transform, Callback callback)
			: this(transform, null, callback)
		{
		}

		public WaterHeightCalculation(Transform transform, List<Vector3> voxels, Callback callback)
		{
			_waterManager = Instance;
			_transform = transform;
			_voxels = voxels;
			_callback = callback;
			if (voxels == null)
			{
				VoxelCount = 0;
				ApplyForces = false;
				return;
			}
			VoxelCount = voxels.Count;
			VoxelPositions = new Vector3[VoxelCount];
			VoxelWaterHeights = new float[VoxelCount];
			ApplyForces = true;
		}

		public WaterHeightCalculation(Transform transform, System.Action onWaterHeightCalculationCallback)
		{
			this.transform = transform;
			this.onWaterHeightCalculationCallback = onWaterHeightCalculationCallback;
		}

		public Vector3 UpdatePosition()
		{
			Position = _transform.position;
			return Position;
		}

		public Vector3 UpdateVoxelPosition(int index)
		{
			Vector3 vector = _transform.TransformPoint(_voxels[index]);
			VoxelPositions[index] = vector;
			return vector;
		}

		public void CopyVoxelWaterHeights(float[] arrayToCopyTo)
		{
			for (int i = 0; i < VoxelCount; i++)
			{
				arrayToCopyTo[i] = VoxelWaterHeights[i];
			}
		}

		public void Queue(Vector3 position)
		{
			if (!_locked)
			{
				Position = position;
				if (!_queued)
				{
					_queued = true;
					_waterManager.QueueWaterHeightCalcultation(this);
				}
			}
		}

		public void Queue(bool update = false)
		{
			if (_locked)
			{
				return;
			}
			if (update)
			{
				UpdatePosition();
				if (ApplyForces)
				{
					for (int i = 0; i < VoxelCount; i++)
					{
						UpdateVoxelPosition(i);
					}
				}
			}
			if (!_queued)
			{
				_queued = true;
				_waterManager.QueueWaterHeightCalcultation(this);
			}
		}

		internal void InvokeCallback()
		{
			if (_callback != null)
			{
				_callback(this);
			}
			_locked = false;
			_queued = false;
		}
	}

	private static WaterManager _instance;

	public const float NUMBER_OF_WAVES = 4f;

	[SerializeField]
	private Renderer _renderer;

	[Tooltip("If true, the WaveParameters will be updated in the shaders each frame.")]
	[SerializeField]
	private bool _refreshWaveParametersEachFrame = true;

	[Header("========================================================================================================================")]
	[Header("Gerstner Waves")]
	[Tooltip("Multiply all wavelength entries with this multiplier.")]
	[Range(0.001f, 10f)]
	[SerializeField]
	private float _waveLengthMultiplier = 1f;

	[Tooltip("Multiply all steepness entries with this multiplier.")]
	[Range(0f, 10f)]
	[SerializeField]
	private float _steepnessMultiplier = 1f;

	[Tooltip("Multiply all amplitude entries with this multiplier.")]
	[Range(0.001f, 10f)]
	[SerializeField]
	private float _amplitudeScaleMultiplier = 1f;

	[Tooltip("Multiply all speed entries with this multiplier.")]
	[Range(0f, 10f)]
	[SerializeField]
	private float _speedMultiplier = 1f;

	[Space]
	[Tooltip("Definition of first wave.")]
	[SerializeField]
	private WaveDefinition _wave01 = new WaveDefinition();

	[Tooltip("Definition of second wave.")]
	[SerializeField]
	private WaveDefinition _wave02 = new WaveDefinition();

	[Tooltip("Definition of third wave.")]
	[SerializeField]
	private WaveDefinition _wave03 = new WaveDefinition();

	[Tooltip("Definition of fourth wave.")]
	[SerializeField]
	private WaveDefinition _wave04 = new WaveDefinition();

	private bool _isInitialized;

	private Vector4 _wavelength;

	private Vector4 _speed;

	private Vector4 _phase;

	private Vector4 _amplitude;

	private Vector4 _steepness;

	private float _currentTime;

	private bool _isPaused;

	private bool _isDestroyed;

	private System.Threading.Thread _calculationThread;

	private List<WaterHeightCalculation> _mainCalculations;

	private List<WaterHeightCalculation> _sharedCalculations;

	private List<WaterHeightCalculation> _calculationCallbacks;

	private Exception _exception;

	private bool _doCalculations;

	private bool _doCalculationCallbacks;

	[HideInInspector]
	public const string _globalTimeString = "_GLOBAL_GERSTNER_Time";

	public static bool ApplicationQuitting;

	public static WaterManager Instance
	{
		get
		{
			if (_instance == null && !ApplicationQuitting)
			{
				_instance = UnityEngine.Object.FindAnyObjectByType<WaterManager>();
				if (_instance == null)
				{
					_instance = new GameObject
					{
						name = "_WATERMANAGER",
						hideFlags = HideFlags.NotEditable
					}.AddComponent<WaterManager>();
					UnityEngine.Debug.Log("=====WaterManager Created=====");
				}
			}
			return _instance;
		}
	}

	public bool IsPaused => _isPaused;

	public static WaterManager CreateInstance()
	{
		return Instance;
	}

	private void Awake()
	{
		if (_instance == null)
		{
			_instance = this;
		}
		else if (_instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		if (!_isInitialized)
		{
			Initialize();
		}
	}

	private void Initialize()
	{
		UpdateAndSetShaderProperties();
		int capacity = 1000;
		_calculationThread = new System.Threading.Thread(CalculateWaterHeightJob);
		_mainCalculations = new List<WaterHeightCalculation>(capacity);
		_sharedCalculations = new List<WaterHeightCalculation>(capacity);
		_calculationCallbacks = new List<WaterHeightCalculation>(capacity);
		_doCalculations = false;
		_isInitialized = true;
	}

	public void Update()
	{
		if (!_isInitialized)
		{
			Initialize();
		}
		if (!_isPaused)
		{
			_currentTime += GameSpeedManager.WaterDeltaTime;
		}
		if (_refreshWaveParametersEachFrame)
		{
			UpdateAndSetShaderProperties();
		}
		UpdateGlobalWaveShaderVariables();
	}

	private void LateUpdate()
	{
		if (_exception != null)
		{
			lock (_exception)
			{
				throw _exception;
			}
		}
		if (!_doCalculationCallbacks)
		{
			return;
		}
		lock (_calculationCallbacks)
		{
			int count = _calculationCallbacks.Count;
			for (int i = 0; i < count; i++)
			{
				_calculationCallbacks[i].InvokeCallback();
			}
			_calculationCallbacks.Clear();
			_doCalculationCallbacks = false;
		}
	}

	private void FixedUpdate()
	{
		if (_mainCalculations == null || _mainCalculations.Count == 0)
		{
			return;
		}
		lock (_sharedCalculations)
		{
			_sharedCalculations.AddRange(_mainCalculations);
			_mainCalculations.Clear();
			_doCalculations = true;
			if (_calculationThread.ThreadState == System.Threading.ThreadState.Unstarted)
			{
				_calculationThread.Start();
			}
		}
	}

	public void OnApplicationQuit()
	{
		ApplicationQuitting = true;
	}

	private void OnDestroy()
	{
		_isDestroyed = true;
	}

	private void UpdateAndSetShaderProperties()
	{
		ApplyWaveDefition(_wave01, 0);
		ApplyWaveDefition(_wave02, 1);
		ApplyWaveDefition(_wave03, 2);
		ApplyWaveDefition(_wave04, 3);
		Shader.SetGlobalVector("_GLOBAL_GERSTNER_Wavelength", _wavelength);
		Shader.SetGlobalVector("_GLOBAL_GERSTNER_Speed", _speed);
		Shader.SetGlobalVector("_GLOBAL_GERSTNER_Phase", _phase);
		Shader.SetGlobalVector("_GLOBAL_GERSTNER_Amplitude", _amplitude);
		Shader.SetGlobalVector("_GLOBAL_GERSTNER_Steepness", _steepness);
		Shader.SetGlobalFloat("_GLOBAL_GERSTNER_Time", _currentTime);
		_isInitialized = true;
	}

	private void ApplyWaveDefition(WaveDefinition waveDefinition, int index)
	{
		waveDefinition.ApplyMultipliers(_waveLengthMultiplier, _speedMultiplier, _steepnessMultiplier, _amplitudeScaleMultiplier);
		_wavelength[index] = waveDefinition.Wavelength;
		_speed[index] = waveDefinition.Speed;
		_phase[index] = waveDefinition.Phase;
		_amplitude[index] = waveDefinition.Amplitude;
		_steepness[index] = waveDefinition.Steepness;
		Shader.SetGlobalVector(waveDefinition.ReturnNormalizedDirectionGlobal(index), waveDefinition.NormalizedDirection);
	}

	private void UpdateGlobalWaveShaderVariables()
	{
		Shader.SetGlobalFloat("_GLOBAL_GERSTNER_Time", _currentTime);
	}

	public void PauseWater()
	{
		_isPaused = !_isPaused;
	}

	public static float ReturnsGreatestCommonDivisor(float value1, float value2)
	{
		float num = 1f;
		if (value1 == 0f || value2 == 0f)
		{
			return 1f;
		}
		float num2 = Mathf.Abs(value1);
		float num3 = Mathf.Abs(value2);
		if (num2 == num3)
		{
			return num2;
		}
		if (num2 > num3 && num2 % num3 == 0f)
		{
			return num3;
		}
		if (num3 > num2 && num3 % num2 == 0f)
		{
			return num2;
		}
		while (num3 != 0f)
		{
			num = num3;
			num3 = num2 % num3;
			num2 = num;
		}
		return num;
	}

	public static float ReturnLowestCommonMultiple(float value1, float value2)
	{
		float num = Mathf.Abs(value1);
		float num2 = Mathf.Abs(value2);
		return num / ReturnsGreatestCommonDivisor(num, num2) * num2;
	}

	public Vector3 ReturnGerstnerPosition(Vector3 position)
	{
		if (!_isInitialized)
		{
			Initialize();
		}
		Vector3 vector = _wave01.ReturnWaveOffsetGerstner(position, _currentTime) + _wave02.ReturnWaveOffsetGerstner(position, _currentTime) + _wave03.ReturnWaveOffsetGerstner(position, _currentTime) + _wave04.ReturnWaveOffsetGerstner(position, _currentTime);
		return position + vector;
	}

	public float ReturnWaterHeightOnPoint(float groundXPosition, float groundZPosition)
	{
		if (!_isInitialized)
		{
			Initialize();
		}
		return _wave01.ReturnWaveOffsetGerstnerY(groundXPosition, groundZPosition, _currentTime) + _wave02.ReturnWaveOffsetGerstnerY(groundXPosition, groundZPosition, _currentTime) + _wave03.ReturnWaveOffsetGerstnerY(groundXPosition, groundZPosition, _currentTime) + _wave04.ReturnWaveOffsetGerstnerY(groundXPosition, groundZPosition, _currentTime);
	}

	public float ReturnWaterHeightOnPoint(Vector3 point)
	{
		return ReturnWaterHeightOnPoint(point.x, point.z);
	}

	private Vector3 ReturnWaveOffsetGerstner(float length, float speed, float phase, float amplitude, float numberOfWaves, float steepness, Vector2 direction, float x, float z, float time)
	{
		float num = Vector3.Dot(Vector3.Normalize(new Vector3(direction.x, direction.y, 0f)), new Vector3(x, z, 0f));
		float num2 = MathF.PI * 2f / length;
		float f = num2 * num + speed * time + phase;
		float num3 = Mathf.Cos(f);
		float num4 = Mathf.Sin(f);
		float num5 = steepness / (num2 * amplitude * numberOfWaves);
		Vector3 result = new Vector3(0f, 0f, 0f);
		result.x = num5 * amplitude * direction.x * num3;
		result.z = num5 * amplitude * direction.y * num3;
		result.y = amplitude * num4;
		return result;
	}

	internal void QueueWaterHeightCalcultation(WaterHeightCalculation calculation)
	{
		_mainCalculations.Add(calculation);
	}

	private void CalculateWaterHeightJob()
	{
		try
		{
			while (!ApplicationQuitting && !_isDestroyed)
			{
				if (!_doCalculations)
				{
					System.Threading.Thread.Sleep(16);
					continue;
				}
				lock (_sharedCalculations)
				{
					int count = _sharedCalculations.Count;
					for (int i = 0; i < count; i++)
					{
						WaterHeightCalculation waterHeightCalculation = _sharedCalculations[i];
						waterHeightCalculation._locked = true;
						waterHeightCalculation.PositionWaterHeight = ReturnWaterHeightOnPoint(waterHeightCalculation.Position);
						if (waterHeightCalculation.ApplyForces)
						{
							int voxelCount = waterHeightCalculation.VoxelCount;
							for (int j = 0; j < voxelCount; j++)
							{
								waterHeightCalculation.VoxelWaterHeights[j] = ReturnWaterHeightOnPoint(waterHeightCalculation.VoxelPositions[j]);
							}
						}
						lock (_calculationCallbacks)
						{
							_calculationCallbacks.Add(waterHeightCalculation);
							_doCalculationCallbacks = true;
						}
					}
					_sharedCalculations.Clear();
					_doCalculations = false;
				}
			}
		}
		catch (Exception exception)
		{
			if (_exception == null)
			{
				_exception = exception;
				return;
			}
			lock (_exception)
			{
				_exception = exception;
			}
		}
	}

	public static float ReturnWaterHeight(float groundXPosition, float groundZPosition)
	{
		if (Instance == null)
		{
			return 0f;
		}
		return Instance.ReturnWaterHeightOnPoint(groundXPosition, groundZPosition);
	}

	public static Material ReturnMaterial()
	{
		if (Instance == null)
		{
			return null;
		}
		return Instance.GetComponent<MeshRenderer>().sharedMaterial;
	}

	public static void SetMaterial(Material material)
	{
		if (!(Instance == null))
		{
			Instance.GetComponent<MeshRenderer>().sharedMaterial = material;
		}
	}
}
[Serializable]
public class WaveDefinition
{
	public const string _GLOBAL_WAVELENGTH = "_GLOBAL_GERSTNER_Wavelength";

	public const string _GLOBAL_SPEED = "_GLOBAL_GERSTNER_Speed";

	public const string _GLOBAL_PHASE = "_GLOBAL_GERSTNER_Phase";

	public const string _GLOBAL_AMPLITUDE = "_GLOBAL_GERSTNER_Amplitude";

	public const string _GLOBAL_STEEPNESS = "_GLOBAL_GERSTNER_Steepness";

	private const string _GLOBAL_DIRECTION_PREFIX = "_GLOBAL_GERSTNER_Direction";

	[FormerlySerializedAs("WaveLength")]
	[Tooltip("Length to set for wave.")]
	[SerializeField]
	private float _waveLength = 100f;

	[FormerlySerializedAs("Steepness")]
	[Tooltip("Steepness to set for wave.")]
	[Range(0f, 1f)]
	[SerializeField]
	private float _steepness = 1f;

	[FormerlySerializedAs("Amplitude")]
	[Tooltip("Amplitude to set for wave.")]
	[SerializeField]
	private float _amplitude = 1f;

	[FormerlySerializedAs("Speed")]
	[Tooltip("Speed to set for wave.")]
	[SerializeField]
	private float _speed = 0.5f;

	[FormerlySerializedAs("Direction")]
	[Tooltip("Direction to set for wave.")]
	[SerializeField]
	private Vector2 _direction = new Vector2(1f, 0f);

	private float _frequency;

	private float _phase;

	private float _steepnessAmplitudeDirectionX;

	private float _steepnessAmplitudeDirectionY;

	private string _normalizedDirectionGlobal;

	public float Wavelength { get; private set; }

	public float Speed { get; private set; }

	public float Phase => _phase;

	public float Amplitude { get; private set; }

	public float Steepness { get; private set; }

	public Vector2 NormalizedDirection { get; private set; }

	public void ApplyMultipliers(float wavelengthMultiplier, float speedMultiplier, float steepnessMultiplier, float amplitudeMultiplier)
	{
		Wavelength = _waveLength * wavelengthMultiplier;
		Speed = _speed * speedMultiplier;
		Amplitude = _amplitude * amplitudeMultiplier;
		Steepness = Mathf.Clamp(_steepness * steepnessMultiplier, 0f, 1f);
		_frequency = MathF.PI * 2f / Wavelength;
		_phase = Speed / _frequency;
		NormalizedDirection = _direction.normalized;
		float num = Steepness / (_frequency * Amplitude * 4f);
		_steepnessAmplitudeDirectionX = num * Amplitude * NormalizedDirection.x;
		_steepnessAmplitudeDirectionY = num * Amplitude * NormalizedDirection.y;
	}

	public Vector3 ReturnWaveOffsetGerstner(Vector3 position, float time)
	{
		Vector2 normalized = _direction.normalized;
		float num = Vector2.Dot(_direction.normalized, new Vector2(position.x, position.z));
		float num2 = MathF.PI * 2f / Wavelength;
		float f = num2 * num + Speed * time + Phase;
		float num3 = Mathf.Cos(f);
		float num4 = Mathf.Sin(f);
		float num5 = Steepness / (num2 * Amplitude * 4f);
		Vector3 zero = Vector3.zero;
		zero.x = num5 * Amplitude * normalized.x * num3;
		zero.z = num5 * Amplitude * normalized.y * num3;
		zero.y = Amplitude * num4;
		return zero;
	}

	public float ReturnWaveOffsetGerstnerY(float x, float z, float time)
	{
		float num = Vector2.Dot(_direction.normalized, new Vector2(x, z));
		float num2 = Mathf.Sin(MathF.PI * 2f / Wavelength * num + Speed * time + Phase);
		return Amplitude * num2;
	}

	public string ReturnNormalizedDirectionGlobal(int index)
	{
		if (string.IsNullOrEmpty(_normalizedDirectionGlobal) || Application.isEditor)
		{
			_normalizedDirectionGlobal = "_GLOBAL_GERSTNER_Direction" + index;
		}
		return _normalizedDirectionGlobal;
	}
}
