public class FOW_Camera : MonoBehaviour
{
	[SerializeField]
	private LayerMask _fogOfWarLayer;

	[SerializeField]
	private MeshFilter _fogOfWarPlane;

	[SerializeField]
	private GameObject _player;

	[SerializeField]
	private float _clearRadius;

	private Mesh _mesh;

	private int _vertexCount;

	private List<Vector3> _vertices;

	private List<Color> _colors;

	private void Start()
	{
		_mesh = _fogOfWarPlane.mesh;
		_vertexCount = _mesh.vertexCount;
		_vertices = new List<Vector3>(_vertexCount);
		_colors = new List<Color>(_vertexCount);
	}

	private void Update()
	{
		Vector3 position = _player.transform.position;
		_mesh.GetVertices(_vertices);
		_mesh.GetColors(_colors);
		for (int i = 0; i < _vertexCount; i++)
		{
			float num = Vector3.Distance(_vertices[i], position);
			if (num < _clearRadius)
			{
				float num2 = num / _clearRadius;
				Color value = _colors[i];
				if (num2 < value.a)
				{
					value.a = num2;
					_colors[i] = value;
				}
			}
		}
		_mesh.SetColors(_colors);
	}

	private Color[] ReturnVertexColors(int count, Color color)
	{
		Color[] array = new Color[count];
		for (int i = 0; i < count; i++)
		{
			array[i] = color;
		}
		return array;
	}
}
public class FOW_TownheartControls : MonoBehaviour
{
	[SerializeField]
	[Range(0f, 10f)]
	private float _acceleration = 1f;

	[SerializeField]
	private RangedFloat _velocityRange = new RangedFloat(-2.5f, 10f);

	[SerializeField]
	[Range(0f, 10f)]
	private float _drag = 0.25f;

	[SerializeField]
	[Range(0f, 45f)]
	private float _rotationSpeed = 1f;

	private float _velocity;

	private void Update()
	{
		float deltaTime = Time.deltaTime;
		if (UnityEngine.Input.GetKey(KeyCode.UpArrow))
		{
			_velocity = Mathf.Min(_velocityRange.Maximum, _velocity + _acceleration * deltaTime);
		}
		else if (UnityEngine.Input.GetKey(KeyCode.DownArrow))
		{
			_velocity = Mathf.Max(_velocityRange.Minimum, _velocity - _acceleration * deltaTime);
		}
		else if (_velocity < 0f)
		{
			_velocity = Mathf.Min(0f, _velocity + _drag * deltaTime);
		}
		else
		{
			_velocity = Mathf.Max(0f, _velocity - _drag * deltaTime);
		}
		Quaternion rotation = base.transform.rotation;
		if (UnityEngine.Input.GetKey(KeyCode.LeftArrow))
		{
			rotation *= Quaternion.AngleAxis((0f - _rotationSpeed) * deltaTime, (Vector3)Vector2.up);
		}
		if (UnityEngine.Input.GetKey(KeyCode.RightArrow))
		{
			rotation *= Quaternion.AngleAxis(_rotationSpeed * deltaTime, (Vector3)Vector2.up);
		}
		base.transform.rotation = rotation;
		base.transform.position = base.transform.position + base.transform.forward * _velocity * deltaTime;
	}
}
