[Serializable]
public class PoissonDiskSampler
{
	[Serializable]
	public class WeightedDistanceRange
	{
		public int Minimum;

		public int Maximum;

		public int Weight;

		[NonSerialized]
		public int WeightThreshold;
	}

	[SerializeField]
	private int _sampleCount = 1;

	[SerializeField]
	[Range(1f, 1000f)]
	private int _minimumDistance = 50;

	[SerializeField]
	[Range(1f, 1000f)]
	private int _maximumDistance = 100;

	[SerializeField]
	[Range(1f, 100f)]
	protected int _sampleLimit = 30;

	[Header("Weighted Distance Ranges")]
	[SerializeField]
	private bool _useWeightedDistanceRanges;

	[SerializeField]
	private WeightedDistanceRange[] _weightedDistanceRanges;

	private int _weightedDistanceRangesTotalWeight;

	public List<Vector2> Samples { get; private set; }

	public int MinimumDistance { get; private set; }

	public void GenerateSamples()
	{
		GenerateSamples(_sampleCount, _sampleLimit, Vector2.zero);
	}

	public void GenerateSamples(Vector2 origin)
	{
		GenerateSamples(_sampleCount, _sampleLimit, origin);
	}

	protected void GenerateSamples(int sampleCount, int sampleLimit, Vector2 origin)
	{
		if (Samples == null)
		{
			Samples = new List<Vector2>();
		}
		else
		{
			Samples.Clear();
		}
		Samples.Add(origin);
		InitializeWeightedInstances();
		int num = 1;
		int num2 = 0;
		while (num < sampleCount && num2 < 500)
		{
			int num3 = UnityEngine.Random.Range(0, Samples.Count);
			Vector2 vector = Samples[num3];
			for (int i = 0; i < sampleLimit; i++)
			{
				Vector2 vector2 = vector + ReturnRandomOnCircle(ReturnSampleDistance());
				bool flag = false;
				if (!IsValidSample(vector2))
				{
					continue;
				}
				foreach (Vector2 sample in Samples)
				{
					flag = vector2.IsInRange(sample, MinimumDistance);
					if (flag)
					{
						break;
					}
				}
				if (!flag)
				{
					Samples.Add(vector2);
					break;
				}
			}
			if (Samples.Count == num)
			{
				if (num3 != 0)
				{
					Samples.RemoveAt(num3);
					num--;
				}
				num2++;
			}
			else
			{
				num++;
			}
		}
	}

	private void InitializeWeightedInstances()
	{
		if (_useWeightedDistanceRanges)
		{
			_weightedDistanceRangesTotalWeight = 0;
			MinimumDistance = int.MaxValue;
			WeightedDistanceRange[] weightedDistanceRanges = _weightedDistanceRanges;
			foreach (WeightedDistanceRange weightedDistanceRange in weightedDistanceRanges)
			{
				_weightedDistanceRangesTotalWeight += weightedDistanceRange.Weight;
				weightedDistanceRange.WeightThreshold = _weightedDistanceRangesTotalWeight;
				if (weightedDistanceRange.Minimum < MinimumDistance)
				{
					MinimumDistance = weightedDistanceRange.Minimum;
				}
			}
		}
		else
		{
			MinimumDistance = _minimumDistance;
		}
	}

	protected virtual bool IsValidSample(Vector2 sample)
	{
		return true;
	}

	private int ReturnSampleDistance()
	{
		int minInclusive = _minimumDistance;
		int maxExclusive = _maximumDistance;
		if (_useWeightedDistanceRanges)
		{
			int num = UnityEngine.Random.Range(0, _weightedDistanceRangesTotalWeight);
			WeightedDistanceRange[] weightedDistanceRanges = _weightedDistanceRanges;
			foreach (WeightedDistanceRange weightedDistanceRange in weightedDistanceRanges)
			{
				if (num < weightedDistanceRange.WeightThreshold)
				{
					minInclusive = weightedDistanceRange.Minimum;
					maxExclusive = weightedDistanceRange.Maximum;
					break;
				}
			}
		}
		return UnityEngine.Random.Range(minInclusive, maxExclusive);
	}

	private Vector2 ReturnRandomOnCircle(float distance)
	{
		return Quaternion.AngleAxis(UnityEngine.Random.Range(0f, 360f), Vector3.forward) * Vector2.up * distance;
	}
}
[Serializable]
public class PoissonDiskSamplerWithBounds : PoissonDiskSampler
{
	private Rect _bounds;

	public void GenerateSamples(Rect bounds)
	{
		_bounds = bounds;
		GenerateSamples(bounds.center);
	}

	protected override bool IsValidSample(Vector2 sample)
	{
		return _bounds.Contains(sample);
	}
}
[CreateAssetMenu(fileName = "LandmarkConnectionPass", menuName = "Flotsam/Procedural Generation/ConnectionPass", order = 3)]
public class LandmarkConnectionPass : TileGeneratorPass
{
	private class TileGeneratorNodeSite : FortuneSite
	{
		public TileGeneratorNode Node { get; private set; }

		public TileGeneratorNodeSite()
			: base(0.0, 0.0)
		{
		}

		public TileGeneratorNodeSite(TileGeneratorNode node)
			: base(node.Position.x, node.Position.y)
		{
			Node = node;
		}
	}

	public struct Connection
	{
		public TileGeneratorNode From;

		public TileGeneratorNode To;

		public int Tier;
	}

	[Header("Voronoi Settings")]
	[SerializeField]
	private RectInt _bounds;

	[Header("Landmark Settings")]
	[SerializeField]
	private float _spawnInterval = 500f;

	[SerializeField]
	private float _spawnDirectionRange = 250f;

	[SerializeField]
	private float _spawnWidthRange = 500f;

	[SerializeField]
	private int _spawnSampleLimit = 10;

	[SerializeField]
	private int _minimumClearDistance = 300;

	public override IEnumerator Run(TileGenerator generator, IRegion dataRegion = null)
	{
		ListPool<FortuneSite>.List list = ListPool<FortuneSite>.Get(generator.Nodes.Count + 1);
		list.Add(new TileGeneratorNodeSite(new TileGeneratorNode(Vector2.zero)));
		foreach (TileGeneratorNode node in generator.Nodes)
		{
			list.Add(new TileGeneratorNodeSite(node));
		}
		FortunesAlgorithm.Run(list, _bounds.xMin, _bounds.yMin, _bounds.xMax, _bounds.yMax);
		GenerateConnections(generator, list);
		GenerateNodes(generator);
		generator.Nodes.AddRange(base.GeneratedNodes);
		yield break;
	}

	private void GenerateConnections(TileGenerator generator, List<FortuneSite> sites)
	{
		ListPool<FortuneSite>.List list = ListPool<FortuneSite>.Get(sites[0]);
		ListPool<FortuneSite>.List list2 = ListPool<FortuneSite>.Get(sites.Count);
		int num = 0;
		while (0 < list.Count)
		{
			ListPool<FortuneSite>.List list3 = list;
			list = ListPool<FortuneSite>.Get();
			foreach (TileGeneratorNodeSite item in list3)
			{
				foreach (TileGeneratorNodeSite neighbor in item.Neighbors)
				{
					AddConnection(generator, item.Node, neighbor.Node, num);
					if (!list2.Contains(item))
					{
						list.Add(neighbor);
					}
				}
				list2.Add(item);
			}
			list3.Dispose();
			num++;
		}
		list.Dispose();
		list2.Dispose();
	}

	private void GenerateNodes(TileGenerator generator)
	{
		ListPool<TileGeneratorNode>.List list = ListPool<TileGeneratorNode>.Get(generator.Nodes);
		InitializeGeneratedNodes(list.Count);
		foreach (TileGeneratorConnection generatedConnection in base.GeneratedConnections)
		{
			float num = Mathf.FloorToInt(generatedConnection.Distance / _spawnInterval);
			if (num != 1f)
			{
				Vector2 vector = generatedConnection.Direction * (generatedConnection.Distance / num);
				Vector2 position = generatedConnection.From.Position;
				for (int i = 1; (float)i < num; i++)
				{
					GenerateNode(position + i * vector, generatedConnection.Direction, list, _spawnSampleLimit);
				}
			}
		}
	}

	private void GenerateNode(Vector2 position, Vector2 direction, List<TileGeneratorNode> samples, int sampleLimit)
	{
		Vector2 vector = new Vector2(0f - direction.y, direction.x);
		for (int i = 0; i < sampleLimit; i++)
		{
			Vector2 position2 = position + direction * UnityEngine.Random.Range(0f - _spawnDirectionRange, _spawnDirectionRange) + vector * UnityEngine.Random.Range(0f - _spawnWidthRange, _spawnWidthRange);
			if (!HasSampleInRange(samples, position2, _minimumClearDistance))
			{
				TileGeneratorNode item = new TileGeneratorNode(position2);
				base.GeneratedNodes.Add(item);
				samples.Add(item);
				break;
			}
		}
	}
}
[CreateAssetMenu(fileName = "LandmarkPass", menuName = "Flotsam/Procedural Generation/Landmark Pass", order = 3)]
public class LandmarkPass : TileGeneratorPass
{
	public class Node
	{
		public TileGeneratorNode GeneratorNode { get; private set; }

		public List<Node> Neighbors { get; private set; }

		public LandmarkBehaviour LandmarkBehaviour { get; private set; }

		public Node(TileGeneratorNode generatorNode)
		{
			GeneratorNode = generatorNode;
			Neighbors = new List<Node>();
		}

		public void TryAddNeighbor(Node potentialNeighbor, float uniqueDistance)
		{
			if (potentialNeighbor != this && !Neighbors.Contains(potentialNeighbor) && GeneratorNode.Position.IsInRange(potentialNeighbor.GeneratorNode.Position, uniqueDistance))
			{
				Neighbors.Add(potentialNeighbor);
				potentialNeighbor.Neighbors.Add(this);
			}
		}

		public void SetLandmarkBehaviour(LandmarkBehaviour landmarkBehaviour, bool hasBearing = false)
		{
			GeneratorNode.SetSpawner(new LandmarkSpawner(landmarkBehaviour, new Vector3(GeneratorNode.Position.x, 0f, GeneratorNode.Position.y), hasBearing));
			LandmarkBehaviour = landmarkBehaviour;
		}

		public bool ReturnIsPossibleLandmark(LandmarkBehaviour landmark)
		{
			foreach (Node neighbor in Neighbors)
			{
				if (neighbor.LandmarkBehaviour == landmark)
				{
					return false;
				}
			}
			return true;
		}
	}

	[SerializeField]
	private LandmarkBehaviour[] _landmarkBehaviours;

	[SerializeField]
	private float _uniqueDistance = 500f;

	[SerializeField]
	private bool _generateWithBearing;

	public override IEnumerator Run(TileGenerator generator, IRegion dataRegion = null)
	{
		List<Node> list = ReturnNodes(generator.Nodes);
		List<LandmarkBehaviour> list2 = new List<LandmarkBehaviour>(_landmarkBehaviours);
		List<int> list3 = new List<int>();
		foreach (Node item in list)
		{
			if (list2.Count == 0)
			{
				list2.AddRange(_landmarkBehaviours);
			}
			list3.Clear();
			for (int i = 0; i < list2.Count; i++)
			{
				if (item.ReturnIsPossibleLandmark(list2[i]))
				{
					list3.Add(i);
				}
			}
			if (list3.Count == 0)
			{
				UnityEngine.Debug.Log("No possible landmark in landmarksToDistribute, no landmark will be added to the world for this node.");
				continue;
			}
			int index = list3[UnityEngine.Random.Range(0, list3.Count)];
			item.SetLandmarkBehaviour(list2[index], _generateWithBearing);
			list2.RemoveAt(index);
		}
		yield break;
	}

	public List<Node> ReturnNodes(List<TileGeneratorNode> generatorNodes)
	{
		List<Node> list = new List<Node>();
		foreach (TileGeneratorNode generatorNode in generatorNodes)
		{
			if (!generatorNode.Locked)
			{
				list.Add(new Node(generatorNode));
			}
		}
		foreach (Node item in list)
		{
			foreach (Node item2 in list)
			{
				item.TryAddNeighbor(item2, _uniqueDistance);
			}
		}
		return list;
	}
}
[CreateAssetMenu(fileName = "PointOfInterestPass", menuName = "Flotsam/Procedural Generation/Point of Interest Pass", order = 2)]
public class PointOfInterestPass : TileGeneratorPass
{
	public PointOfInterestProperties[] PointsOfInterest;

	public bool UseRegions;

	public override IEnumerator Run(TileGenerator generator, IRegion dataRegion = null)
	{
		ListPool<PointOfInterestProperties>.List list = ListPool<PointOfInterestProperties>.Get(PointsOfInterest);
		foreach (TileGeneratorNode item in generator.ReturnNodes(TileGenerator.PassNodeSelectors.All))
		{
			if (!item.Locked)
			{
				item.SetSpawner(new PointOfInterestSpawner(ReturnPointOfInterestProperties(generator, item, list), item.WorldPosition));
			}
		}
		list.Dispose();
		yield break;
	}

	private PointOfInterestProperties ReturnPointOfInterestProperties(TileGenerator generator, TileGeneratorNode node, List<PointOfInterestProperties> poisToDistribute)
	{
		if (UseRegions && generator.TryReturnRegionTileProperties(node, out var pointOfInterestProperties))
		{
			return pointOfInterestProperties;
		}
		if (poisToDistribute.Count == 0)
		{
			poisToDistribute.AddRange(PointsOfInterest);
		}
		int index = UnityEngine.Random.Range(0, poisToDistribute.Count);
		pointOfInterestProperties = poisToDistribute[index];
		poisToDistribute.RemoveAt(index);
		return pointOfInterestProperties;
	}
}
[CreateAssetMenu(fileName = "PoissonDiskPass", menuName = "Flotsam/Procedural Generation/Poisson Disk Pass", order = 2)]
public class PoissonDiskPass : TileGeneratorPass
{
	[Serializable]
	public class WeightedDistanceRange
	{
		public int Minimum;

		public int Maximum;

		public int Weight;

		[NonSerialized]
		public int WeightThreshold;
	}

	public enum SampleInitialization
	{
		ZeroNode,
		GeneratorNodes,
		PassNodes,
		StartPosition
	}

	public enum Restrictions
	{
		None,
		Radial,
		Rect
	}

	[SerializeField]
	private int _sampleCount = 1;

	[SerializeField]
	[Range(1f, 100f)]
	private int _sampleLimit = 30;

	[SerializeField]
	private WeightedDistanceRange[] _weightedDistanceRanges;

	[SerializeField]
	private SampleInitialization _sampleInitialization = SampleInitialization.PassNodes;

	[SerializeField]
	private bool _generateLeafNodes;

	[SerializeField]
	[Range(0f, 10f)]
	private int _LeafMaximum = 3;

	[Header("Ristrictions")]
	[SerializeField]
	private Restrictions _restriction;

	[ConditionalEnumHide("_restriction", 1, false, HideInInspector = true)]
	[SerializeField]
	[FormerlySerializedAs("_SampleAreaStart")]
	private float _sampleAreaStart;

	[ConditionalEnumHide("_restriction", 1, false, HideInInspector = true)]
	[SerializeField]
	[FormerlySerializedAs("_SampleAreaEnd")]
	private float _sampleAreaEnd;

	[ConditionalEnumHide("_restriction", 2, false, HideInInspector = true)]
	[SerializeField]
	private Rect _sampleRect;

	[ConditionalEnumHide("_restriction", 2, false, HideInInspector = true)]
	[SerializeField]
	private Vector2 _startAreaCenter;

	[ConditionalEnumHide("_restriction", 2, false, HideInInspector = true)]
	[SerializeField]
	private float _startAreaRadius;

	[NonSerialized]
	private int _weightedDistanceRangesTotalWeight;

	[NonSerialized]
	private float _minimumDistance;

	public Restrictions Ristriction => _restriction;

	public float SampleAreaStart => _sampleAreaStart;

	public float SampleAreaEnd => _sampleAreaEnd;

	public override IEnumerator Run(TileGenerator generator, IRegion dataRegion = null)
	{
		ListPool<TileGeneratorNode>.List list = ReturnInitialSamples(generator);
		ListPool<TileGeneratorNode>.List list2 = ReturnSamplesWithoutLeaves(list);
		InitializeWeightedInstances();
		InitializeGeneratedNodes(_sampleCount);
		int num = 1;
		int num2 = _sampleCount * 2;
		int num3 = 0;
		while (base.GeneratedNodes.Count < _sampleCount && 0 < list2.Count)
		{
			int index = UnityEngine.Random.Range(0, list2.Count);
			TileGeneratorNode tileGeneratorNode = list2[index];
			TileGeneratorNode tileGeneratorNode2 = null;
			for (int i = 0; i < _sampleLimit; i++)
			{
				Vector2 vector = tileGeneratorNode.Position + ReturnRandomOnCircle(ReturnSampleDistance());
				if (!ReturnIsValidPosition(vector))
				{
					continue;
				}
				bool flag = false;
				foreach (TileGeneratorNode item in list)
				{
					flag = vector.IsInRange(item.Position, _minimumDistance);
					if (flag)
					{
						break;
					}
				}
				if (!flag)
				{
					tileGeneratorNode2 = new TileGeneratorNode(vector, tileGeneratorNode, _generateLeafNodes);
					break;
				}
			}
			if (tileGeneratorNode2 == null)
			{
				if (base.GeneratedNodes.Remove(tileGeneratorNode))
				{
					tileGeneratorNode.Dispose();
					list.Remove(tileGeneratorNode);
					list2.Remove(tileGeneratorNode);
					num--;
				}
			}
			else
			{
				base.GeneratedNodes.Add(tileGeneratorNode2);
				list.Add(tileGeneratorNode2);
				if (_generateLeafNodes)
				{
					if (_LeafMaximum <= tileGeneratorNode.LeafCount)
					{
						list2.Remove(tileGeneratorNode);
					}
				}
				else
				{
					list2.Add(tileGeneratorNode2);
				}
				num++;
			}
			num3++;
			if (num2 < num3)
			{
				break;
			}
		}
		generator.Nodes.AddRange(base.GeneratedNodes);
		list.Dispose();
		list2.Dispose();
		yield break;
	}

	private void InitializeWeightedInstances()
	{
		_weightedDistanceRangesTotalWeight = 0;
		_minimumDistance = float.MaxValue;
		WeightedDistanceRange[] weightedDistanceRanges = _weightedDistanceRanges;
		foreach (WeightedDistanceRange weightedDistanceRange in weightedDistanceRanges)
		{
			_weightedDistanceRangesTotalWeight += weightedDistanceRange.Weight;
			weightedDistanceRange.WeightThreshold = _weightedDistanceRangesTotalWeight;
			if ((float)weightedDistanceRange.Minimum < _minimumDistance)
			{
				_minimumDistance = weightedDistanceRange.Minimum;
			}
		}
	}

	private int ReturnSampleDistance()
	{
		int minInclusive = int.MaxValue;
		int maxExclusive = int.MinValue;
		int num = UnityEngine.Random.Range(0, _weightedDistanceRangesTotalWeight);
		WeightedDistanceRange[] weightedDistanceRanges = _weightedDistanceRanges;
		foreach (WeightedDistanceRange weightedDistanceRange in weightedDistanceRanges)
		{
			if (num < weightedDistanceRange.WeightThreshold)
			{
				minInclusive = weightedDistanceRange.Minimum;
				maxExclusive = weightedDistanceRange.Maximum;
				break;
			}
		}
		return UnityEngine.Random.Range(minInclusive, maxExclusive);
	}

	public static Vector2 ReturnRandomOnCircle(float distance)
	{
		return Quaternion.AngleAxis(UnityEngine.Random.Range(0f, 360f), Vector3.forward) * Vector2.up * distance;
	}

	private ListPool<TileGeneratorNode>.List ReturnInitialSamples(TileGenerator generator)
	{
		ListPool<TileGeneratorNode>.List list = ListPool<TileGeneratorNode>.Get();
		switch (generator.ReturnHasNodes() ? _sampleInitialization : SampleInitialization.ZeroNode)
		{
		case SampleInitialization.ZeroNode:
		{
			TileGeneratorNode tileGeneratorNode = new TileGeneratorNode(Vector2.zero);
			tileGeneratorNode.Lock();
			list.Add(tileGeneratorNode);
			break;
		}
		case SampleInitialization.GeneratorNodes:
			list.AddRange(generator.Nodes);
			break;
		case SampleInitialization.PassNodes:
			throw new NotImplementedException();
		case SampleInitialization.StartPosition:
		{
			TileGeneratorNode tileGeneratorNode = new TileGeneratorNode(generator.StartPosition);
			tileGeneratorNode.Lock();
			list.Add(tileGeneratorNode);
			break;
		}
		}
		return list;
	}

	private ListPool<TileGeneratorNode>.List ReturnSamplesWithoutLeaves(ListPool<TileGeneratorNode>.List allSamples)
	{
		ListPool<TileGeneratorNode>.List list = ListPool<TileGeneratorNode>.Get();
		foreach (TileGeneratorNode allSample in allSamples)
		{
			if (!allSample.IsLeaf)
			{
				list.Add(allSample);
			}
		}
		return list;
	}

	private bool ReturnIsValidPosition(Vector2 generatedPosition)
	{
		switch (_restriction)
		{
		case Restrictions.None:
			return true;
		case Restrictions.Radial:
		{
			float magnitude = generatedPosition.magnitude;
			if (_sampleAreaStart < magnitude)
			{
				return magnitude < _sampleAreaEnd;
			}
			return false;
		}
		case Restrictions.Rect:
			if (_sampleRect.Contains(generatedPosition))
			{
				return !_startAreaCenter.IsInRange(generatedPosition, _startAreaRadius);
			}
			return false;
		default:
			throw new NotImplementedException();
		}
	}
}
[CreateAssetMenu(fileName = "Region POI Pass", menuName = "Flotsam/Procedural Generation/Region POI Pass", order = 3)]
public class RegionPointOfInterestPass : TileGeneratorPass
{
	[SerializeField]
	[NamedArrayElement("_region", "_pollutionLevel", " - ")]
	private RegionPointOfInterestSettings[] _regionSettings;

	private RegionPointOfInterestSettings _activeSettings;

	private TileGeneratorRegion _region;

	private float _density;

	private int _totalPOICount;

	private RegionPassGroup _regionPassGroup;

	public int SpawnCount => _totalPOICount;

	public void Initialize(TileGenerator generator)
	{
		InitializeGeneratedNodes(generator.Regions.Count * 16);
	}

	public bool InitializeRegion(TileGeneratorRegion region)
	{
		if (TryReturnRegionSettings(region, out _activeSettings))
		{
			_region = region;
			_activeSettings.Initialize();
			_density = _activeSettings.ReturnRandomizedDensity();
			_totalPOICount = Mathf.RoundToInt(region.ReturnSurface() / _density);
			return true;
		}
		_activeSettings = null;
		return false;
	}

	public override IEnumerator Run(TileGenerator generator, IRegion dataRegion)
	{
		Dictionary<IWorldRegion, TileGeneratorRegion>.Enumerator enumerator = generator.Regions.GetEnumerator();
		Initialize(generator);
		while (enumerator.MoveNext())
		{
			TileGeneratorRegion value = enumerator.Current.Value;
			if ((dataRegion == null || value.IsRegion(dataRegion)) && InitializeRegion(value))
			{
				int count = Mathf.Min(_totalPOICount, Mathf.RoundToInt(_activeSettings.LandmarkRatio.ReturnRandom() * (float)value.Landmarks.Count));
				int num = DistributeLandmarkFlotsam(generator, value, count);
				DistributeRestFlotsam(generator, value, _totalPOICount - num);
			}
		}
		yield break;
	}

	public void Run(RegionPassGroup regionPasses, TileGeneratorRegion region)
	{
		if (_activeSettings != null)
		{
			_regionPassGroup = regionPasses;
			int count = Mathf.Min(_totalPOICount, Mathf.RoundToInt(_activeSettings.LandmarkRatio.ReturnRandom() * (float)region.Landmarks.Count));
			int num = DistributeLandmarkFlotsam(regionPasses.Generator, region, count);
			DistributeRestFlotsam(regionPasses.Generator, region, _totalPOICount - num);
		}
	}

	private int DistributeLandmarkFlotsam(TileGenerator generator, TileGeneratorRegion region, int count)
	{
		int num = 0;
		using ListPool<TileGeneratorNode>.List list = ListPool<TileGeneratorNode>.Get(region.Landmarks);
		while (num < count && 0 < list.Count)
		{
			float num2 = 0f;
			int count2 = list.Count;
			while (0 < count2--)
			{
				TileGeneratorNode tileGeneratorNode = list[count2];
				if (tileGeneratorNode.TrySetLeafChance(_activeSettings))
				{
					num2 += tileGeneratorNode.LeafChance;
				}
				else
				{
					list.RemoveAt(count2);
				}
			}
			float num3 = UnityEngine.Random.Range(0f, num2);
			float num4 = 0f;
			float num5 = 0f;
			int count3 = list.Count;
			while (0 < count3--)
			{
				TileGeneratorNode tileGeneratorNode = list[count3];
				num5 = num4 + tileGeneratorNode.LeafChance;
				if (num4 <= num3 && num3 < num5)
				{
					if (TryGenerateLandmarkFlotsamNode(out var node, region, tileGeneratorNode))
					{
						AddGeneratedNode(node, generator);
						num++;
					}
					else
					{
						list.RemoveAt(0);
					}
					break;
				}
				num4 = num5;
			}
		}
		return num;
	}

	protected bool TryGenerateLandmarkFlotsamNode(out TileGeneratorNode node, TileGeneratorRegion region, TileGeneratorNode parent, int sampleLimit = 10)
	{
		while (0 < sampleLimit)
		{
			Vector2 position = parent.Position + PoissonDiskPass.ReturnRandomOnCircle(_activeSettings.LandmarkSpawnRange.ReturnRandom());
			if (TryGenerateNode(out node, region, position))
			{
				return true;
			}
			sampleLimit--;
		}
		node = null;
		return false;
	}

	private int DistributeRestFlotsam(TileGenerator generator, TileGeneratorRegion region, int count)
	{
		if (_activeSettings.UseRegionPassesCells && _regionPassGroup != null)
		{
			RegionPassCells cells = _regionPassGroup.Cells;
			cells.SetSpawnChanceCurve(_activeSettings.RestFlotsamChancesCurve);
			return cells.DistributeNodes(generator, count, GenerateRestFlotsamNode);
		}
		using RegionPassCells regionPassCells = GetPassCells(_activeSettings, region);
		if (_activeSettings.CellSettings.CountExistingNodes)
		{
			regionPassCells.CountExistingNodes(region);
		}
		regionPassCells.SetSpawnChanceCurve(_activeSettings.RestFlotsamChancesCurve);
		return regionPassCells.DistributeNodes(generator, count, GenerateRestFlotsamNode);
	}

	private void GenerateRestFlotsamNode(Vector2 position)
	{
		TileGeneratorNode tileGeneratorNode = new TileGeneratorNode(position, null, isLeaf: true);
		tileGeneratorNode.SetSpawner(new PointOfInterestSpawner(_activeSettings.ReturnPointOfInterestProperties(), tileGeneratorNode.WorldPosition));
		_region.AddNode(tileGeneratorNode);
		_region.Generator.AddNode(tileGeneratorNode);
	}

	private bool TryGenerateNode(out TileGeneratorNode node, TileGeneratorRegion region, Vector2 position)
	{
		if (region.ReturnIsValidPosition(position, _activeSettings.LandmarkSpawnRange.Minimum))
		{
			node = new TileGeneratorNode(position, null, isLeaf: true);
			node.SetSpawner(new PointOfInterestSpawner(_activeSettings.ReturnPointOfInterestProperties(), node.WorldPosition));
			region.AddNode(node);
			return true;
		}
		node = null;
		return false;
	}

	public bool TryReturnRegionSettings(IRegion region, out RegionPointOfInterestSettings settings)
	{
		using ListPool<RegionPointOfInterestSettings>.List list = ListPool<RegionPointOfInterestSettings>.Get();
		RegionPointOfInterestSettings[] regionSettings = _regionSettings;
		foreach (RegionPointOfInterestSettings regionPointOfInterestSettings in regionSettings)
		{
			if (region.Type == regionPointOfInterestSettings.Region)
			{
				list.Add(regionPointOfInterestSettings);
			}
		}
		settings = null;
		if (0 < list.Count)
		{
			Sorting.SlowSort(list, CompareSettings);
			for (int j = 0; j < list.Count; j++)
			{
				settings = list[j];
				if (settings.PullutionLevel >= region.PollutionLevel)
				{
					break;
				}
			}
		}
		return settings != null;
	}

	public RegionPassCells GetPassCells(RegionPointOfInterestSettings settings, IRegion region)
	{
		float num = Mathf.Sqrt(_density);
		return RegionPassCells.GetFromPool(cellSize: new Vector2(num, num), settings: settings.CellSettings, region: region);
	}

	private int CompareSettings(RegionPointOfInterestSettings left, RegionPointOfInterestSettings right)
	{
		return left.PullutionLevel - right.PullutionLevel;
	}
}
[Serializable]
public class RegionPointOfInterestSettings
{
	[Serializable]
	private enum DistributionList
	{
		PointsOfInterest,
		PointOfInterestCount
	}

	[Serializable]
	private struct PointOfInterest
	{
		public int Count;

		public PointOfInterestProperties PointOfInterestProperties;
	}

	[SerializeField]
	private WorldRegionType _region;

	[SerializeField]
	private PollutionLevels _pollutionLevel;

	[Header("Flotsam Spawning")]
	[Tooltip("The amount of m2 per POI patch")]
	[SerializeField]
	private float _density;

	[Tooltip("The amount of variance allowed in the density as a percentage of the given density (e.g. 1 is 100%)")]
	[SerializeField]
	[MinMaxRangeFloat(0.5f, 2f)]
	private RangedFloat _densityVariance;

	[SerializeField]
	[MinMaxRangeFloat(0f, 1f)]
	private RangedFloat _landmarkRatio;

	[Tooltip("The chance a landmark with a given amount of flotsam pois spawns a flotsam poi. The index is the amount of pois")]
	[SerializeField]
	private AnimationCurve _landmarkPOIChances;

	[SerializeField]
	[MinMaxRangeFloat(75f, 500f)]
	private RangedFloat _landmarkSpawnRange;

	[Tooltip("The chance a cell with a given amount of landmarks and POIs spawns a flotsam poi. The index is the sum of landmarks and POIs in the cell")]
	[SerializeField]
	private AnimationCurve _restFlotsamChances;

	[Header("Cells")]
	[Tooltip("Should the cells generated by the RegionPasses be used?")]
	[SerializeField]
	private bool _useRegionPassesCells;

	[SerializeField]
	[ConditionalHide("_useRegionPassesCells", true, true)]
	private RegionPassCells.Settings _cellSettings;

	[Header("POI Distribution")]
	[SerializeField]
	private DistributionList _distributionList;

	[SerializeField]
	private PointOfInterestProperties[] _pointsOfInterest;

	[SerializeField]
	private PointOfInterest[] _pointOfInterestCount;

	private List<PointOfInterestProperties> _poisToDistribute;

	public WorldRegionType Region => _region;

	public PollutionLevels PullutionLevel => _pollutionLevel;

	public RangedFloat LandmarkRatio => _landmarkRatio;

	public RangedFloat LandmarkSpawnRange => _landmarkSpawnRange;

	public AnimationCurve LandmarkChancesCurve => _landmarkPOIChances;

	public AnimationCurve RestFlotsamChancesCurve => _restFlotsamChances;

	public bool UseRegionPassesCells => _useRegionPassesCells;

	public RegionPassCells.Settings CellSettings => _cellSettings;

	public void Initialize()
	{
		if (_poisToDistribute == null)
		{
			_poisToDistribute = new List<PointOfInterestProperties>();
		}
		else
		{
			_poisToDistribute.Clear();
		}
		PopulatePoisToDistribute();
	}

	public bool TryEvaluateLeafChance(int leafCount, out float leafChance)
	{
		if (_landmarkPOIChances.TryEvaluate(leafCount, out leafChance))
		{
			return 0f < leafChance;
		}
		return false;
	}

	public bool TryEvaluateCellSpawnChance(int nodeCount, out float cellSpawnChance)
	{
		if (_restFlotsamChances.TryEvaluate(nodeCount, out cellSpawnChance))
		{
			return 0f < cellSpawnChance;
		}
		return false;
	}

	private void PopulatePoisToDistribute()
	{
		switch (_distributionList)
		{
		case DistributionList.PointsOfInterest:
			_poisToDistribute.AddRange(_pointsOfInterest);
			break;
		case DistributionList.PointOfInterestCount:
		{
			PointOfInterest[] pointOfInterestCount = _pointOfInterestCount;
			for (int i = 0; i < pointOfInterestCount.Length; i++)
			{
				PointOfInterest pointOfInterest = pointOfInterestCount[i];
				for (int j = 0; j < pointOfInterest.Count; j++)
				{
					_poisToDistribute.Add(pointOfInterest.PointOfInterestProperties);
				}
			}
			break;
		}
		default:
			UnityEngine.Debug.LogException(new NotImplementedException());
			break;
		}
	}

	public float ReturnRandomizedDensity()
	{
		return _density * _densityVariance.ReturnRandom();
	}

	public PointOfInterestProperties ReturnPointOfInterestProperties()
	{
		if (_poisToDistribute.Count == 0)
		{
			PopulatePoisToDistribute();
		}
		int index = UnityEngine.Random.Range(0, _poisToDistribute.Count);
		PointOfInterestProperties result = _poisToDistribute[index];
		_poisToDistribute.RemoveAt(index);
		return result;
	}
}
public abstract class TileGeneratorPass : ScriptableObject
{
	public List<TileGeneratorNode> GeneratedNodes { get; protected set; }

	public List<TileGeneratorConnection> GeneratedConnections { get; protected set; }

	public abstract IEnumerator Run(TileGenerator generator, IRegion dataRegion);

	public virtual void Restore(IWorldTile worldTile)
	{
	}

	protected void InitializeGeneratedNodes(int minimumCapacity)
	{
		if (GeneratedNodes == null)
		{
			GeneratedNodes = new List<TileGeneratorNode>(minimumCapacity);
			return;
		}
		GeneratedNodes.Clear();
		if (GeneratedNodes.Capacity < minimumCapacity)
		{
			GeneratedNodes.Capacity = minimumCapacity;
		}
	}

	protected void GenerateNode(TileGenerator generator, Vector2 position)
	{
		AddGeneratedNode(new TileGeneratorNode(position), generator);
	}

	protected void AddGeneratedNode(TileGeneratorNode node, TileGenerator generator = null)
	{
		if ((bool)generator)
		{
			generator.Nodes.Add(node);
		}
		GeneratedNodes.Add(node);
	}

	protected bool RemoveGeneratedNode(TileGenerator generator, TileGeneratorNode node)
	{
		if (GeneratedNodes.Remove(node))
		{
			generator.Nodes.Remove(node);
			return true;
		}
		return false;
	}

	protected void AddConnection(TileGenerator generator, TileGeneratorNode from, TileGeneratorNode to, int tier)
	{
		TileGeneratorConnection item = new TileGeneratorConnection(from, to, tier);
		if (GeneratedConnections == null)
		{
			GeneratedConnections = new List<TileGeneratorConnection>();
		}
		foreach (TileGeneratorConnection generatedConnection in GeneratedConnections)
		{
			if ((generatedConnection.From == from || generatedConnection.To == from) && (generatedConnection.From == to || generatedConnection.To == to))
			{
				return;
			}
		}
		GeneratedConnections.Add(item);
		generator.Connections.Add(item);
	}

	public virtual bool TryReturnBounds(out Rect bounds)
	{
		bounds = default(Rect);
		return false;
	}

	protected bool HasSampleInRange(List<TileGeneratorNode> samples, Vector2 position, float range)
	{
		foreach (TileGeneratorNode sample in samples)
		{
			if (position.IsInRange(sample.Position, range))
			{
				return true;
			}
		}
		return false;
	}
}
[Serializable]
public class PoissonDiskSamplerWithRegion : PoissonDiskSampler
{
	private IRegion _region;

	public void GenerateSamples(IRegion region, int sampleCount)
	{
		_region = region;
		GenerateSamples(sampleCount, _sampleLimit, region.ReturnPositionInRegion());
	}

	protected override bool IsValidSample(Vector2 sample)
	{
		return _region.ReturnContainsPosition(sample);
	}
}
[CreateAssetMenu(fileName = "TileGenerator", menuName = "Flotsam/Procedural Generation/Tile Generator", order = 1)]
public class TileGenerator : TileGeneratorBase
{
	public enum PassNodeSelectors
	{
		All,
		Pass
	}

	[SerializeField]
	private TileGeneratorPass[] _passes;

	[SerializeField]
	private float _minimumNodeDistance;

	[SerializeField]
	private float _startAreaRadius;

	[NonSerialized]
	private int _nextPassIndex;

	[NonSerialized]
	private TileGeneratorBase _subTileGeneratorOverride;

	public bool IsStartingTile { get; private set; }

	public List<TileGeneratorNode> Nodes { get; private set; }

	public List<TileGeneratorConnection> Connections { get; private set; }

	public List<TileGeneratorPass> Passes { get; private set; }

	public List<RoadSpawner> Roads { get; private set; }

	public Dictionary<IWorldRegion, TileGeneratorRegion> Regions { get; private set; }

	public override Rect MinimumBounds
	{
		get
		{
			TryReturnBounds(out var bounds);
			return bounds;
		}
	}

	public override float Scale { get; set; } = 1f;

	public TileGeneratorPass[] EDITOR_PassAssetReferences => _passes;

	public override void Initialize(bool isStartingTile)
	{
		IsStartingTile = isStartingTile;
		Nodes = new List<TileGeneratorNode>();
		Connections = new List<TileGeneratorConnection>();
		Passes = new List<TileGeneratorPass>();
		Reset();
	}

	public void OverrideSubTileGenerator(TileGeneratorBase subTileGenerator)
	{
		_subTileGeneratorOverride = subTileGenerator;
	}

	public override IEnumerator Generate(IWorldTile worldTile)
	{
		if (worldTile == null)
		{
			UnityEngine.Debug.LogException(new NotSupportedException($"Unable to run TileGenerator {this}, IWorldTile == NULL"));
			yield break;
		}
		yield return Generate();
		if (Regions != null)
		{
			foreach (IWorldRegion key in Regions.Keys)
			{
				worldTile.AddRegion(key);
			}
		}
		foreach (TileGeneratorNode node in Nodes)
		{
			switch (node.Spawner.Type)
			{
			case ISpawnerType.PointOfInterest:
				worldTile.AddPointOfInterestSpawner(node.Spawner as PointOfInterestSpawner);
				break;
			case ISpawnerType.Landmark:
				worldTile.AddLandmarkSpawner(node.Spawner as LandmarkSpawner);
				break;
			}
		}
		if (Roads == null)
		{
			yield break;
		}
		foreach (RoadSpawner road in Roads)
		{
			worldTile.AddRoadSpawner(road);
		}
	}

	public void Editor_Generate(int seed, IRegion dataRegion)
	{
		UnityEngine.Random.InitState(seed);
		CoroutineRunner.RunCoroutine(Generate(dataRegion));
	}

	private IEnumerator Generate(IRegion dataRegion = null)
	{
		base.StartPosition = (TryReturnTownheartStartPosition(out var position) ? position.Vector2TopDown() : default(Vector2));
		foreach (TileGeneratorPass pass in Passes)
		{
			yield return pass.Run(this, dataRegion);
		}
		_nextPassIndex = Passes.Count;
	}

	public override void Restore(IWorldTile worldTile)
	{
		foreach (TileGeneratorPass pass in Passes)
		{
			pass.Restore(worldTile);
		}
	}

	public void AddRoad(RoadSpawner road)
	{
		if (Roads == null)
		{
			Roads = new List<RoadSpawner>(64);
		}
		Roads.Add(road);
	}

	public void AddRegion(IWorldRegion region)
	{
		if (Regions == null)
		{
			Regions = new Dictionary<IWorldRegion, TileGeneratorRegion>(32);
		}
		Regions.Add(region, new TileGeneratorRegion(this, region));
	}

	public void PopulateRegionNeighbors()
	{
		foreach (TileGeneratorRegion value in Regions.Values)
		{
			value.PopulateNeighbors(Regions.Values);
		}
	}

	public void AddNode(TileGeneratorNode node, bool addToRegion = false)
	{
		Nodes.Add(node);
		if (!addToRegion)
		{
			return;
		}
		Dictionary<IWorldRegion, TileGeneratorRegion>.Enumerator enumerator = Regions.GetEnumerator();
		while (enumerator.MoveNext())
		{
			if (enumerator.Current.Key.ReturnContainsPosition(node.Position))
			{
				enumerator.Current.Value.AddNode(node);
				break;
			}
		}
	}

	public void Reset()
	{
		Nodes.Clear();
		Connections.Clear();
		ClearPasses();
		if (Regions != null)
		{
			Regions.Clear();
		}
		_nextPassIndex = 0;
	}

	private void ClearPasses()
	{
		foreach (TileGeneratorPass pass in Passes)
		{
			if (Application.isPlaying)
			{
				UnityEngine.Object.Destroy(pass);
			}
			else
			{
				UnityEngine.Object.DestroyImmediate(pass);
			}
		}
		Passes.Clear();
		TileGeneratorPass[] passes = _passes;
		for (int i = 0; i < passes.Length; i++)
		{
			TileGeneratorPass tileGeneratorPass = UnityEngine.Object.Instantiate(passes[i]);
			if (tileGeneratorPass is SubTileGeneratorPass subTileGeneratorPass)
			{
				subTileGeneratorPass.OverrideSubTileGenerator(_subTileGeneratorOverride);
			}
			Passes.Add(tileGeneratorPass);
		}
	}

	public bool ReturnHasPass<T>() where T : TileGeneratorPass
	{
		TileGeneratorPass[] passes = _passes;
		for (int i = 0; i < passes.Length; i++)
		{
			if (passes[i] is T)
			{
				return true;
			}
		}
		return false;
	}

	public bool ReturnHasNodes()
	{
		if (Nodes != null)
		{
			return Nodes.Count != 0;
		}
		return false;
	}

	public List<TileGeneratorNode> ReturnNodes(PassNodeSelectors selector, int pass = 0)
	{
		if (selector != PassNodeSelectors.All && selector == PassNodeSelectors.Pass)
		{
			return Passes[pass].GeneratedNodes;
		}
		return Nodes;
	}

	public List<TileGeneratorNode> ReturnNodes(IRegion dataRegion)
	{
		Regions.GetEnumerator();
		foreach (TileGeneratorRegion value in Regions.Values)
		{
			if (value.IsRegion(dataRegion))
			{
				return value.Nodes;
			}
		}
		return null;
	}

	public bool TryReturnRegionTileProperties(TileGeneratorNode node, out PointOfInterestProperties pointOfInterestProperties)
	{
		throw new NotImplementedException();
	}

	public bool TryPopulateDebugNodeDataProvider(List<IDebugMapDataProvider> dataProviders)
	{
		if (dataProviders == null)
		{
			throw new NotSupportedException();
		}
		dataProviders.Clear();
		if (dataProviders.Capacity < Nodes.Count)
		{
			dataProviders.Capacity = Nodes.Count;
		}
		if (Nodes != null)
		{
			foreach (TileGeneratorNode node in Nodes)
			{
				dataProviders.Add(node);
			}
		}
		if (Connections != null)
		{
			foreach (TileGeneratorConnection connection in Connections)
			{
				dataProviders.Add(connection);
			}
		}
		return 0 < dataProviders.Count;
	}

	public override bool TryReturnTownheartStartPosition(out Vector3 position)
	{
		foreach (TileGeneratorPass item in ReturnPassesEnumerable())
		{
			if (item is SubTileGeneratorPass subTileGeneratorPass)
			{
				return subTileGeneratorPass.TileGenerator.TryReturnTownheartStartPosition(out position);
			}
		}
		position = default(Vector3);
		return false;
	}

	public override bool TryReturnWorldMapRegionMeshAndBounds(out Mesh mesh, out Rect bounds)
	{
		foreach (TileGeneratorPass item in ReturnPassesEnumerable())
		{
			if (item is SubTileGeneratorPass subTileGeneratorPass)
			{
				return subTileGeneratorPass.TileGenerator.TryReturnWorldMapRegionMeshAndBounds(out mesh, out bounds);
			}
		}
		return base.TryReturnWorldMapRegionMeshAndBounds(out mesh, out bounds);
	}

	public bool TryReturnBounds(out Rect bounds)
	{
		bool result = false;
		bounds = default(Rect);
		foreach (TileGeneratorPass pass in Passes)
		{
			if (pass.TryReturnBounds(out var bounds2))
			{
				bounds = bounds.Add(bounds2);
				result = true;
			}
		}
		return result;
	}

	public bool ReturnIsValidPosition(Vector2 position, float minimumNodeDistance)
	{
		if (IsStartingTile && base.StartPosition.IsInRange(position, _startAreaRadius))
		{
			return false;
		}
		foreach (TileGeneratorNode node in Nodes)
		{
			if (node.Position.IsInRange(position, minimumNodeDistance))
			{
				return false;
			}
		}
		return true;
	}

	public bool ReturnPositionIsInStartingArea(Vector2 position)
	{
		if (IsStartingTile)
		{
			return base.StartPosition.IsInRange(position, _startAreaRadius);
		}
		return false;
	}

	private IEnumerable<TileGeneratorPass> ReturnPassesEnumerable()
	{
		if (Passes.IsNullOrEmpty())
		{
			return _passes;
		}
		return Passes;
	}
}
public class TileGeneratorConnection : IDebugMapDataProvider
{
