namespace MiniJSON
{
	public static class Json
	{
		private sealed class Parser : IDisposable
		{
			private enum TOKEN
			{
				NONE,
				CURLY_OPEN,
				CURLY_CLOSE,
				SQUARED_OPEN,
				SQUARED_CLOSE,
				COLON,
				COMMA,
				STRING,
				NUMBER,
				TRUE,
				FALSE,
				NULL
			}

			private const string WORD_BREAK = "{}[],:\"";

			private StringReader json;

			private char PeekChar => Convert.ToChar(json.Peek());

			private char NextChar => Convert.ToChar(json.Read());

			private string NextWord
			{
				get
				{
					StringBuilder stringBuilder = new StringBuilder();
					while (!IsWordBreak(PeekChar))
					{
						stringBuilder.Append(NextChar);
						if (json.Peek() == -1)
						{
							break;
						}
					}
					return stringBuilder.ToString();
				}
			}

			private TOKEN NextToken
			{
				get
				{
					EatWhitespace();
					if (json.Peek() == -1)
					{
						return TOKEN.NONE;
					}
					switch (PeekChar)
					{
					case '{':
						return TOKEN.CURLY_OPEN;
					case '}':
						json.Read();
						return TOKEN.CURLY_CLOSE;
					case '[':
						return TOKEN.SQUARED_OPEN;
					case ']':
						json.Read();
						return TOKEN.SQUARED_CLOSE;
					case ',':
						json.Read();
						return TOKEN.COMMA;
					case '"':
						return TOKEN.STRING;
					case ':':
						return TOKEN.COLON;
					case '-':
					case '0':
					case '1':
					case '2':
					case '3':
					case '4':
					case '5':
					case '6':
					case '7':
					case '8':
					case '9':
						return TOKEN.NUMBER;
					default:
						return NextWord switch
						{
							"false" => TOKEN.FALSE, 
							"true" => TOKEN.TRUE, 
							"null" => TOKEN.NULL, 
							_ => TOKEN.NONE, 
						};
					}
				}
			}

			public static bool IsWordBreak(char c)
			{
				if (!char.IsWhiteSpace(c))
				{
					return "{}[],:\"".IndexOf(c) != -1;
				}
				return true;
			}

			private Parser(string jsonString)
			{
				json = new StringReader(jsonString);
			}

			public static object Parse(string jsonString)
			{
				using Parser parser = new Parser(jsonString);
				return parser.ParseValue();
			}

			public void Dispose()
			{
				json.Dispose();
				json = null;
			}

			private Dictionary<string, object> ParseObject()
			{
				Dictionary<string, object> dictionary = new Dictionary<string, object>();
				json.Read();
				while (true)
				{
					switch (NextToken)
					{
					case TOKEN.COMMA:
						continue;
					case TOKEN.NONE:
						return null;
					case TOKEN.CURLY_CLOSE:
						return dictionary;
					}
					string text = ParseString();
					if (text == null)
					{
						return null;
					}
					if (NextToken != TOKEN.COLON)
					{
						return null;
					}
					json.Read();
					dictionary[text] = ParseValue();
				}
			}

			private List<object> ParseArray()
			{
				List<object> list = new List<object>();
				json.Read();
				bool flag = true;
				while (flag)
				{
					TOKEN nextToken = NextToken;
					switch (nextToken)
					{
					case TOKEN.NONE:
						return null;
					case TOKEN.SQUARED_CLOSE:
						flag = false;
						break;
					default:
					{
						object item = ParseByToken(nextToken);
						list.Add(item);
						break;
					}
					case TOKEN.COMMA:
						break;
					}
				}
				return list;
			}

			private object ParseValue()
			{
				TOKEN nextToken = NextToken;
				return ParseByToken(nextToken);
			}

			private object ParseByToken(TOKEN token)
			{
				return token switch
				{
					TOKEN.STRING => ParseString(), 
					TOKEN.NUMBER => ParseNumber(), 
					TOKEN.CURLY_OPEN => ParseObject(), 
					TOKEN.SQUARED_OPEN => ParseArray(), 
					TOKEN.TRUE => true, 
					TOKEN.FALSE => false, 
					TOKEN.NULL => null, 
					_ => null, 
				};
			}

			private string ParseString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				json.Read();
				bool flag = true;
				while (flag)
				{
					if (json.Peek() == -1)
					{
						flag = false;
						break;
					}
					char nextChar = NextChar;
					switch (nextChar)
					{
					case '"':
						flag = false;
						break;
					case '\\':
						if (json.Peek() == -1)
						{
							flag = false;
							break;
						}
						nextChar = NextChar;
						switch (nextChar)
						{
						case '"':
						case '/':
						case '\\':
							stringBuilder.Append(nextChar);
							break;
						case 'b':
							stringBuilder.Append('\b');
							break;
						case 'f':
							stringBuilder.Append('\f');
							break;
						case 'n':
							stringBuilder.Append('\n');
							break;
						case 'r':
							stringBuilder.Append('\r');
							break;
						case 't':
							stringBuilder.Append('\t');
							break;
						case 'u':
						{
							char[] array = new char[4];
							for (int i = 0; i < 4; i++)
							{
								array[i] = NextChar;
							}
							stringBuilder.Append((char)Convert.ToInt32(new string(array), 16));
							break;
						}
						}
						break;
					default:
						stringBuilder.Append(nextChar);
						break;
					}
				}
				return stringBuilder.ToString();
			}

			private object ParseNumber()
			{
				string nextWord = NextWord;
				if (nextWord.IndexOf('.') == -1)
				{
					long.TryParse(nextWord, out var result);
					return result;
				}
				double.TryParse(nextWord, out var result2);
				return result2;
			}

			private void EatWhitespace()
			{
				while (char.IsWhiteSpace(PeekChar))
				{
					json.Read();
					if (json.Peek() == -1)
					{
						break;
					}
				}
			}
		}

		private sealed class Serializer
		{
			private StringBuilder builder;

			private Serializer()
			{
				builder = new StringBuilder();
			}

			public static string Serialize(object obj)
			{
				Serializer serializer = new Serializer();
				serializer.SerializeValue(obj);
				return serializer.builder.ToString();
			}

			private void SerializeValue(object value)
			{
				if (value == null)
				{
					builder.Append("null");
				}
				else if (value is string str)
				{
					SerializeString(str);
				}
				else if (value is bool)
				{
					builder.Append(((bool)value) ? "true" : "false");
				}
				else if (value is IList anArray)
				{
					SerializeArray(anArray);
				}
				else if (value is IDictionary obj)
				{
					SerializeObject(obj);
				}
				else if (value is char)
				{
					SerializeString(new string((char)value, 1));
				}
				else
				{
					SerializeOther(value);
				}
			}

			private void SerializeObject(IDictionary obj)
			{
				bool flag = true;
				builder.Append('{');
				foreach (object key in obj.Keys)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeString(key.ToString());
					builder.Append(':');
					SerializeValue(obj[key]);
					flag = false;
				}
				builder.Append('}');
			}

			private void SerializeArray(IList anArray)
			{
				builder.Append('[');
				bool flag = true;
				foreach (object item in anArray)
				{
					if (!flag)
					{
						builder.Append(',');
					}
					SerializeValue(item);
					flag = false;
				}
				builder.Append(']');
			}

			private void SerializeString(string str)
			{
				builder.Append('"');
				char[] array = str.ToCharArray();
				foreach (char c in array)
				{
					switch (c)
					{
					case '"':
						builder.Append("\\\"");
						continue;
					case '\\':
						builder.Append("\\\\");
						continue;
					case '\b':
						builder.Append("\\b");
						continue;
					case '\f':
						builder.Append("\\f");
						continue;
					case '\n':
						builder.Append("\\n");
						continue;
					case '\r':
						builder.Append("\\r");
						continue;
					case '\t':
						builder.Append("\\t");
						continue;
					}
					int num = Convert.ToInt32(c);
					if (num >= 32 && num <= 126)
					{
						builder.Append(c);
						continue;
					}
					builder.Append("\\u");
					builder.Append(num.ToString("x4"));
				}
				builder.Append('"');
			}

			private void SerializeOther(object value)
			{
				if (value is float)
				{
					builder.Append(((float)value).ToString("R"));
				}
				else if (value is int || value is uint || value is long || value is sbyte || value is byte || value is short || value is ushort || value is ulong)
				{
					builder.Append(value);
				}
				else if (value is double || value is decimal)
				{
					builder.Append(Convert.ToDouble(value).ToString("R"));
				}
				else
				{
					SerializeString(value.ToString());
				}
			}
		}

		public static object Deserialize(string json)
		{
			if (json == null)
			{
				return null;
			}
			return Parser.Parse(json);
		}

		public static string Serialize(object obj)
		{
			return Serializer.Serialize(obj);
		}
	}
}
namespace TMPro
{
	[RequireComponent(typeof(Selectable))]
	public class TMP_DropdownFormatableItem : MonoBehaviour
	{
		[SerializeField]
		private ScrollRect _scrollRect;

		[SerializeField]
		private TMP_DropdownItemFormatter _formatter;

		[SerializeField]
		private Toggle _toggle;

		private bool _enable;

		public bool Interactable
		{
			get
			{
				if (_toggle.isActiveAndEnabled)
				{
					return _toggle.interactable;
				}
				return false;
			}
			set
			{
				_toggle.interactable = value;
			}
		}

		private void OnEnable()
		{
			_enable = true;
		}

		private void OnDisable()
		{
			_formatter.OnItemDisabled(this);
		}

		private void LateUpdate()
		{
			if (_enable)
			{
				_formatter.OnItemEnabled(this);
				_enable = false;
			}
		}

		public void Select()
		{
			if ((bool)_toggle)
			{
				EventSystem.current.SetSelectedGameObject(_toggle.gameObject);
			}
		}

		public void Hide()
		{
			RectTransform rectTransform = base.transform as RectTransform;
			RectTransform rectTransform2 = _scrollRect.transform as RectTransform;
			RectTransform content = _scrollRect.content;
			content.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, content.sizeDelta.y - rectTransform.sizeDelta.y);
			if (content.sizeDelta.y < rectTransform2.sizeDelta.y)
			{
				rectTransform2.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, content.sizeDelta.y);
			}
			base.gameObject.SetActive(value: false);
		}

		public bool IsSelected()
		{
			return EventSystem.current.currentSelectedGameObject == _toggle.gameObject;
		}
	}
	public abstract class TMP_DropdownItemFormatter : MonoBehaviour
	{
		[Header("Dropdown Item Formatter")]
		[SerializeField]
		private TMP_Dropdown _dropdown;

		[SerializeField]
		private LocalizedString _defaultLabel;

		[SerializeField]
		private bool _hideDefaultLabel = true;

		private List<TMP_DropdownFormatableItem> _items = new List<TMP_DropdownFormatableItem>();

		private TMP_DropdownFormatableItem _firstItem;

		private bool _updateSelected;

		public int SelectedIndex => _dropdown.value - 1;

		protected virtual void OnEnable()
		{
			_dropdown.onValueChanged.AddListener(OnValueChanged);
		}

		private void LateUpdate()
		{
			if (_updateSelected)
			{
				int selectedIndex = SelectedIndex;
				_updateSelected = false;
				if (0 <= selectedIndex && selectedIndex < _items.Count && _items[selectedIndex].IsSelected())
				{
					return;
				}
				for (int i = 0; i < _items.Count; i++)
				{
					TMP_DropdownFormatableItem tMP_DropdownFormatableItem = _items[i];
					if (tMP_DropdownFormatableItem.Interactable)
					{
						tMP_DropdownFormatableItem.Select();
						return;
					}
				}
			}
			if (_dropdown.IsExpanded && FlotsamInputManager.GetUICancel(ignoreAllowCancel: true) && !HasSelectedItem())
			{
				_dropdown.OnCancel(null);
			}
		}

		protected virtual void OnDisable()
		{
			_dropdown.onValueChanged.RemoveListener(OnValueChanged);
		}

		public void Initialize(List<string> options)
		{
			options.Insert(0, _defaultLabel);
			_dropdown.ClearOptions();
			_dropdown.AddOptions(options);
		}

		public void OnItemEnabled(TMP_DropdownFormatableItem item)
		{
			if ((bool)_firstItem)
			{
				_updateSelected = true;
				_items.Add(item);
				AddItem(item);
				return;
			}
			_firstItem = item;
			if (_hideDefaultLabel)
			{
				_firstItem.Hide();
			}
		}

		public void OnItemDisabled(TMP_DropdownFormatableItem item)
		{
			if (!(item == _firstItem))
			{
				_items.Remove(item);
				RemoveItem(item);
			}
		}

		protected abstract void AddItem(TMP_DropdownFormatableItem item);

		protected abstract void RemoveItem(TMP_DropdownFormatableItem item);

		protected void ClearSelectedIndex()
		{
			_dropdown.value = 0;
		}

		protected void SetSelectedIndexWithoutNotify(int index)
		{
			int num = index + 1;
			if (0 <= num && num < _dropdown.options.Count)
			{
				_dropdown.SetValueWithoutNotify(num);
			}
		}

		protected virtual void OnSelectedIndexChanged(int selectedIndex)
		{
		}

		private void OnValueChanged(int value)
		{
			OnSelectedIndexChanged(value - 1);
		}

		private bool HasSelectedItem()
		{
			foreach (TMP_DropdownFormatableItem item in _items)
			{
				if (item.IsSelected())
				{
					return true;
				}
			}
			return false;
		}
	}
}
