	public class DefaultFileSystemRead : FileSystemActionBase
	{
		public DefaultFileSystemRead(string file_name, string directory)
			: base(FileSystemAction.Read, file_name, directory)
		{
		}

		public override bool Execute()
		{
			if (File.Exists(base.Directory + "/" + base.FileName))
			{
				base.Data = File.ReadAllBytes(base.Directory + "/" + base.FileName);
				return true;
			}
			return false;
		}
	}
	public class DefaultFileSystemWrite : FileSystemActionBase
	{
		public DefaultFileSystemWrite(string file_name, string directory, byte[] data)
			: base(FileSystemAction.Write, file_name, directory)
		{
			base.Data = data;
		}

		public override bool Execute()
		{
			File.WriteAllBytes(base.Directory + "/" + base.FileName, base.Data);
			return true;
		}
	}
	public enum FileSystemAction
	{
		Read,
		Write
	}
	public abstract class FileSystemActionBase
	{
		private string fileName;

		private string directory;

		public string FileName { get; private set; }

		public string Directory { get; private set; }

		public string Path { get; private set; }

		public FileSystemActionResult Result { get; protected set; }

		public string ResultMessage { get; protected set; }

		public byte[] Data { get; protected set; }

		internal FileSystemAction Action { get; private set; }

		public FileSystemActionBase(FileSystemAction action, string file_name, string directory)
		{
			Action = action;
			FileName = file_name;
			Directory = directory;
		}

		public abstract bool Execute();

		internal void SetResult(FileSystemActionResult result, byte[] data = null)
		{
			Result = result;
			Data = data;
		}
	}
