	public interface IStatistic
	{
		bool IsInitialized { get; }

		void Initialize(IUser player, UnityAction initialize_callback);
	}
	[Serializable]
	public class AchievementStatistics : IStatistic
	{
		[NonSerialized]
		private IUser player;

		[SerializeField]
		private List<AchievementId> unlockedAchievementTable;

		public bool IsInitialized { get; private set; }

		public void Initialize(IUser player, UnityAction initialize_callback)
		{
			this.player = player;
			if (unlockedAchievementTable == null)
			{
				unlockedAchievementTable = new List<AchievementId>();
			}
			IsInitialized = true;
		}

		public bool IsAchievementUnlocked(AchievementId achievement_id)
		{
			return unlockedAchievementTable.Contains(achievement_id);
		}

		public bool UnlockAchievement(AchievementBase achievement)
		{
			return UnlockAchievement(achievement.Id);
		}

		public bool UnlockAchievement(AchievementId achievement_id)
		{
			if (unlockedAchievementTable.Contains(achievement_id))
			{
				return false;
			}
			unlockedAchievementTable.Add(achievement_id);
			return true;
		}
	}
}
namespace M4.Encoding
{
	public static class NoEncoding
	{
		public static byte[] GetBytes(string str)
		{
			byte[] array = new byte[str.Length * 2];
			Buffer.BlockCopy(str.ToCharArray(), 0, array, 0, array.Length);
			return array;
		}

		public static string GetString(byte[] bytes)
		{
			char[] array = new char[bytes.Length / 2];
			Buffer.BlockCopy(bytes, 0, array, 0, bytes.Length);
			return new string(array);
		}
	}
}
namespace External.Zalgo2462.VoronoiLib
{
	public static class FortunesAlgorithm
	{
		public static LinkedList<VEdge> Run(List<FortuneSite> sites, double minX, double minY, double maxX, double maxY)
		{
			MinHeap<FortuneEvent> minHeap = new MinHeap<FortuneEvent>(5 * sites.Count);
			foreach (FortuneSite site in sites)
			{
				minHeap.Insert(new FortuneSiteEvent(site));
			}
			BeachLine beachLine = new BeachLine();
			LinkedList<VEdge> linkedList = new LinkedList<VEdge>();
			HashSet<FortuneCircleEvent> hashSet = new HashSet<FortuneCircleEvent>();
			while (minHeap.Count != 0)
			{
				FortuneEvent fortuneEvent = minHeap.Pop();
				if (fortuneEvent is FortuneSiteEvent)
				{
					beachLine.AddBeachSection((FortuneSiteEvent)fortuneEvent, minHeap, hashSet, linkedList);
				}
				else if (hashSet.Contains((FortuneCircleEvent)fortuneEvent))
				{
					hashSet.Remove((FortuneCircleEvent)fortuneEvent);
				}
				else
				{
					beachLine.RemoveBeachSection((FortuneCircleEvent)fortuneEvent, minHeap, hashSet, linkedList);
				}
			}
			LinkedListNode<VEdge> linkedListNode = linkedList.First;
			while (linkedListNode != null)
			{
				VEdge value = linkedListNode.Value;
				LinkedListNode<VEdge> next = linkedListNode.Next;
				if (!ClipEdge(value, minX, minY, maxX, maxY))
				{
					linkedList.Remove(linkedListNode);
				}
				linkedListNode = next;
			}
			return linkedList;
		}

		private static bool ClipEdge(VEdge edge, double minX, double minY, double maxX, double maxY)
		{
			bool flag = false;
			if (edge.End == null)
			{
				flag = ClipRay(edge, minX, minY, maxX, maxY);
			}
			else
			{
				int num = ComputeOutCode(edge.Start.X, edge.Start.Y, minX, minY, maxX, maxY);
				int num2 = ComputeOutCode(edge.End.X, edge.End.Y, minX, minY, maxX, maxY);
				while (true)
				{
					if ((num | num2) == 0)
					{
						flag = true;
						break;
					}
					if ((num & num2) != 0)
					{
						break;
					}
					double x = -1.0;
					double y = -1.0;
					int num3 = ((num != 0) ? num : num2);
					if ((num3 & 8) != 0)
					{
						x = edge.Start.X + (edge.End.X - edge.Start.X) * (maxY - edge.Start.Y) / (edge.End.Y - edge.Start.Y);
						y = maxY;
					}
					else if ((num3 & 4) != 0)
					{
						x = edge.Start.X + (edge.End.X - edge.Start.X) * (minY - edge.Start.Y) / (edge.End.Y - edge.Start.Y);
						y = minY;
					}
					else if ((num3 & 2) != 0)
					{
						y = edge.Start.Y + (edge.End.Y - edge.Start.Y) * (maxX - edge.Start.X) / (edge.End.X - edge.Start.X);
						x = maxX;
					}
					else if ((num3 & 1) != 0)
					{
						y = edge.Start.Y + (edge.End.Y - edge.Start.Y) * (minX - edge.Start.X) / (edge.End.X - edge.Start.X);
						x = minX;
					}
					if (num3 == num)
					{
						edge.Start = new VPoint(x, y);
						num = ComputeOutCode(x, y, minX, minY, maxX, maxY);
					}
					else
					{
						edge.End = new VPoint(x, y);
						num2 = ComputeOutCode(x, y, minX, minY, maxX, maxY);
					}
				}
			}
			if (edge.Neighbor != null)
			{
				bool flag2 = ClipEdge(edge.Neighbor, minX, minY, maxX, maxY);
				if (flag && flag2)
				{
					edge.Start = edge.Neighbor.End;
				}
				if (!flag && flag2)
				{
					edge.Start = edge.Neighbor.End;
					edge.End = edge.Neighbor.Start;
					flag = true;
				}
			}
			return flag;
		}

		private static int ComputeOutCode(double x, double y, double minX, double minY, double maxX, double maxY)
		{
			int num = 0;
			if (!x.ApproxEqual(minX) && !x.ApproxEqual(maxX))
			{
				if (x < minX)
				{
					num |= 1;
				}
				else if (x > maxX)
				{
					num |= 2;
				}
			}
			if (!y.ApproxEqual(minY) && !x.ApproxEqual(maxY))
			{
				if (y < minY)
				{
					num |= 4;
				}
				else if (y > maxY)
				{
					num |= 8;
				}
			}
			return num;
		}

		private static bool ClipRay(VEdge edge, double minX, double minY, double maxX, double maxY)
		{
			VPoint start = edge.Start;
			if (edge.SlopeRise.ApproxEqual(0.0))
			{
				if (!Within(start.Y, minY, maxY))
				{
					return false;
				}
				if (edge.SlopeRun > 0.0 && start.X > maxX)
				{
					return false;
				}
				if (edge.SlopeRun < 0.0 && start.X < minX)
				{
					return false;
				}
				if (Within(start.X, minX, maxX))
				{
					if (edge.SlopeRun > 0.0)
					{
						edge.End = new VPoint(maxX, start.Y);
					}
					else
					{
						edge.End = new VPoint(minX, start.Y);
					}
				}
				else if (edge.SlopeRun > 0.0)
				{
					edge.Start = new VPoint(minX, start.Y);
					edge.End = new VPoint(maxX, start.Y);
				}
				else
				{
					edge.Start = new VPoint(maxX, start.Y);
					edge.End = new VPoint(minX, start.Y);
				}
				return true;
			}
			if (edge.SlopeRun.ApproxEqual(0.0))
			{
				if (start.X < minX || start.X > maxX)
				{
					return false;
				}
				if (edge.SlopeRise > 0.0 && start.Y > maxY)
				{
					return false;
				}
				if (edge.SlopeRise < 0.0 && start.Y < minY)
				{
					return false;
				}
				if (Within(start.Y, minY, maxY))
				{
					if (edge.SlopeRise > 0.0)
					{
						edge.End = new VPoint(start.X, maxY);
					}
					else
					{
						edge.End = new VPoint(start.X, minY);
					}
				}
				else if (edge.SlopeRise > 0.0)
				{
					edge.Start = new VPoint(start.X, minY);
					edge.End = new VPoint(start.X, maxY);
				}
				else
				{
					edge.Start = new VPoint(start.X, maxY);
					edge.End = new VPoint(start.X, minY);
				}
				return true;
			}
			VPoint vPoint = new VPoint(CalcX(edge.Slope.Value, maxY, edge.Intercept.Value), maxY);
			VPoint vPoint2 = new VPoint(CalcX(edge.Slope.Value, minY, edge.Intercept.Value), minY);
			VPoint vPoint3 = new VPoint(minX, CalcY(edge.Slope.Value, minX, edge.Intercept.Value));
			VPoint vPoint4 = new VPoint(maxX, CalcY(edge.Slope.Value, maxX, edge.Intercept.Value));
			List<VPoint> list = new List<VPoint>();
			if (Within(vPoint.X, minX, maxX))
			{
				list.Add(vPoint);
			}
			if (Within(vPoint2.X, minX, maxX))
			{
				list.Add(vPoint2);
			}
			if (Within(vPoint3.Y, minY, maxY))
			{
				list.Add(vPoint3);
			}
			if (Within(vPoint4.Y, minY, maxY))
			{
				list.Add(vPoint4);
			}
			for (int num = list.Count - 1; num > -1; num--)
			{
				VPoint vPoint5 = list[num];
				double num2 = vPoint5.X - start.X;
				double num3 = vPoint5.Y - start.Y;
				if (edge.SlopeRun * num2 + edge.SlopeRise * num3 < 0.0)
				{
					list.RemoveAt(num);
				}
			}
			if (list.Count == 2)
			{
				double num4 = list[0].X - start.X;
				double num5 = list[0].Y - start.Y;
				double num6 = list[1].X - start.X;
				double num7 = list[1].Y - start.Y;
				if (num4 * num4 + num5 * num5 > num6 * num6 + num7 * num7)
				{
					edge.Start = list[1];
					edge.End = list[0];
				}
				else
				{
					edge.Start = list[0];
					edge.End = list[1];
				}
			}
			if (list.Count == 1)
			{
				edge.End = list[0];
			}
			return edge.End != null;
		}

		private static bool Within(double x, double a, double b)
		{
			if (x.ApproxGreaterThanOrEqualTo(a))
			{
				return x.ApproxLessThanOrEqualTo(b);
			}
			return false;
		}

		private static double CalcY(double m, double x, double b)
		{
			return m * x + b;
		}

		private static double CalcX(double m, double y, double b)
		{
			return (y - b) / m;
		}
	}
	public static class ParabolaMath
	{
		public const double EPSILON = 4.940656458412466E-224;

		public static double EvalParabola(double focusX, double focusY, double directrix, double x)
		{
			return 0.5 * ((x - focusX) * (x - focusX) / (focusY - directrix) + focusY + directrix);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double IntersectParabolaX(double focus1X, double focus1Y, double focus2X, double focus2Y, double directrix)
		{
			if (!focus1Y.ApproxEqual(focus2Y))
			{
				return (focus1X * (directrix - focus2Y) + focus2X * (focus1Y - directrix) + System.Math.Sqrt((directrix - focus1Y) * (directrix - focus2Y) * ((focus1X - focus2X) * (focus1X - focus2X) + (focus1Y - focus2Y) * (focus1Y - focus2Y)))) / (focus1Y - focus2Y);
			}
			return (focus1X + focus2X) / 2.0;
		}

		public static bool ApproxEqual(this double value1, double value2)
		{
			return System.Math.Abs(value1 - value2) <= 4.940656458412466E-224;
		}

		public static bool ApproxGreaterThanOrEqualTo(this double value1, double value2)
		{
			if (!(value1 > value2))
			{
				return value1.ApproxEqual(value2);
			}
			return true;
		}

		public static bool ApproxLessThanOrEqualTo(this double value1, double value2)
		{
			if (!(value1 < value2))
			{
				return value1.ApproxEqual(value2);
			}
			return true;
		}
	}
}
namespace External.Zalgo2462.VoronoiLib.Structures
{
	internal class BeachSection
	{
		internal FortuneSite Site { get; }

		internal VEdge Edge { get; set; }

		internal FortuneCircleEvent CircleEvent { get; set; }

		internal BeachSection(FortuneSite site)
		{
			Site = site;
			CircleEvent = null;
		}
	}
	internal class BeachLine
	{
		private readonly RBTree<BeachSection> beachLine;

		internal BeachLine()
		{
			beachLine = new RBTree<BeachSection>();
		}

		internal void AddBeachSection(FortuneSiteEvent siteEvent, MinHeap<FortuneEvent> eventQueue, HashSet<FortuneCircleEvent> deleted, LinkedList<VEdge> edges)
		{
			FortuneSite site = siteEvent.Site;
			double x = site.X;
			double y = site.Y;
			RBTreeNode<BeachSection> rBTreeNode = null;
			RBTreeNode<BeachSection> rBTreeNode2 = null;
			RBTreeNode<BeachSection> rBTreeNode3 = beachLine.Root;
			while (rBTreeNode3 != null && rBTreeNode == null && rBTreeNode2 == null)
			{
				double num = LeftBreakpoint(rBTreeNode3, y) - x;
				if (num > 0.0)
				{
					if (rBTreeNode3.Left == null)
					{
						rBTreeNode2 = rBTreeNode3;
					}
					else
					{
						rBTreeNode3 = rBTreeNode3.Left;
					}
					continue;
				}
				double num2 = x - RightBreakpoint(rBTreeNode3, y);
				if (num2 > 0.0)
				{
					if (rBTreeNode3.Right == null)
					{
						rBTreeNode = rBTreeNode3;
					}
					else
					{
						rBTreeNode3 = rBTreeNode3.Right;
					}
				}
				else if (num.ApproxEqual(0.0))
				{
					rBTreeNode = rBTreeNode3.Previous;
					rBTreeNode2 = rBTreeNode3;
				}
				else if (num2.ApproxEqual(0.0))
				{
					rBTreeNode = rBTreeNode3;
					rBTreeNode2 = rBTreeNode3.Next;
				}
				else
				{
					rBTreeNode = (rBTreeNode2 = rBTreeNode3);
				}
			}
			BeachSection successorData = new BeachSection(site);
			RBTreeNode<BeachSection> rBTreeNode4 = beachLine.InsertSuccessor(rBTreeNode, successorData);
			if (rBTreeNode == null && rBTreeNode2 == null)
			{
				return;
			}
			if (rBTreeNode != null && rBTreeNode == rBTreeNode2)
			{
				if (rBTreeNode.Data.CircleEvent != null)
				{
					deleted.Add(rBTreeNode.Data.CircleEvent);
					rBTreeNode.Data.CircleEvent = null;
				}
				BeachSection successorData2 = new BeachSection(rBTreeNode.Data.Site);
				rBTreeNode2 = beachLine.InsertSuccessor(rBTreeNode4, successorData2);
				double y2 = ParabolaMath.EvalParabola(rBTreeNode.Data.Site.X, rBTreeNode.Data.Site.Y, y, x);
				VPoint start = new VPoint(x, y2);
				VEdge vEdge = new VEdge(start, site, rBTreeNode.Data.Site);
				VEdge edge = (vEdge.Neighbor = new VEdge(start, rBTreeNode.Data.Site, site));
				edges.AddFirst(vEdge);
				rBTreeNode4.Data.Edge = vEdge;
				rBTreeNode2.Data.Edge = edge;
				rBTreeNode.Data.Site.Neighbors.Add(rBTreeNode4.Data.Site);
				rBTreeNode4.Data.Site.Neighbors.Add(rBTreeNode.Data.Site);
				CheckCircle(rBTreeNode, eventQueue);
				CheckCircle(rBTreeNode2, eventQueue);
			}
			else if (rBTreeNode != null && rBTreeNode2 == null)
			{
				VPoint start2 = new VPoint((rBTreeNode.Data.Site.X + site.X) / 2.0, double.MinValue);
				VEdge neighbor = new VEdge(start2, rBTreeNode.Data.Site, site);
				VEdge vEdge3 = new VEdge(start2, site, rBTreeNode.Data.Site);
				vEdge3.Neighbor = neighbor;
				edges.AddFirst(vEdge3);
				rBTreeNode.Data.Site.Neighbors.Add(rBTreeNode4.Data.Site);
				rBTreeNode4.Data.Site.Neighbors.Add(rBTreeNode.Data.Site);
				rBTreeNode4.Data.Edge = vEdge3;
			}
			else if (rBTreeNode != null && rBTreeNode != rBTreeNode2)
			{
				if (rBTreeNode.Data.CircleEvent != null)
				{
					deleted.Add(rBTreeNode.Data.CircleEvent);
					rBTreeNode.Data.CircleEvent = null;
				}
				if (rBTreeNode2.Data.CircleEvent != null)
				{
					deleted.Add(rBTreeNode2.Data.CircleEvent);
					rBTreeNode2.Data.CircleEvent = null;
				}
				FortuneSite site2 = rBTreeNode.Data.Site;
				double x2 = site2.X;
				double y3 = site2.Y;
				double num3 = site.X - x2;
				double num4 = site.Y - y3;
				FortuneSite site3 = rBTreeNode2.Data.Site;
				double num5 = site3.X - x2;
				double num6 = site3.Y - y3;
				double num7 = num3 * num6 - num4 * num5;
				double num8 = num3 * num3 + num4 * num4;
				double num9 = num5 * num5 + num6 * num6;
				VPoint vPoint = new VPoint((num6 * num8 - num4 * num9) / (2.0 * num7) + x2, (num3 * num9 - num5 * num8) / (2.0 * num7) + y3);
				rBTreeNode2.Data.Edge.End = vPoint;
				rBTreeNode4.Data.Edge = new VEdge(vPoint, site, rBTreeNode.Data.Site);
				rBTreeNode2.Data.Edge = new VEdge(vPoint, rBTreeNode2.Data.Site, site);
				edges.AddFirst(rBTreeNode4.Data.Edge);
				edges.AddFirst(rBTreeNode2.Data.Edge);
				rBTreeNode4.Data.Site.Neighbors.Add(rBTreeNode.Data.Site);
				rBTreeNode.Data.Site.Neighbors.Add(rBTreeNode4.Data.Site);
				rBTreeNode4.Data.Site.Neighbors.Add(rBTreeNode2.Data.Site);
				rBTreeNode2.Data.Site.Neighbors.Add(rBTreeNode4.Data.Site);
				CheckCircle(rBTreeNode, eventQueue);
				CheckCircle(rBTreeNode2, eventQueue);
			}
		}

		internal void RemoveBeachSection(FortuneCircleEvent circle, MinHeap<FortuneEvent> eventQueue, HashSet<FortuneCircleEvent> deleted, LinkedList<VEdge> edges)
		{
			RBTreeNode<BeachSection> toDelete = circle.ToDelete;
			double x = circle.X;
			double yCenter = circle.YCenter;
			VPoint vPoint = new VPoint(x, yCenter);
			List<RBTreeNode<BeachSection>> list = new List<RBTreeNode<BeachSection>>();
			RBTreeNode<BeachSection> previous = toDelete.Previous;
			while (previous.Data.CircleEvent != null && (x - previous.Data.CircleEvent.X).ApproxEqual(0.0) && (yCenter - previous.Data.CircleEvent.Y).ApproxEqual(0.0))
			{
				list.Add(previous);
				previous = previous.Previous;
			}
			RBTreeNode<BeachSection> next = toDelete.Next;
			while (next.Data.CircleEvent != null && (x - next.Data.CircleEvent.X).ApproxEqual(0.0) && (yCenter - next.Data.CircleEvent.Y).ApproxEqual(0.0))
			{
				list.Add(next);
				next = next.Next;
			}
			toDelete.Data.Edge.End = vPoint;
			toDelete.Next.Data.Edge.End = vPoint;
			toDelete.Data.CircleEvent = null;
			foreach (RBTreeNode<BeachSection> item in list)
			{
				item.Data.Edge.End = vPoint;
				item.Next.Data.Edge.End = vPoint;
				deleted.Add(item.Data.CircleEvent);
				item.Data.CircleEvent = null;
			}
			if (previous.Data.CircleEvent != null)
			{
				deleted.Add(previous.Data.CircleEvent);
				previous.Data.CircleEvent = null;
			}
			if (next.Data.CircleEvent != null)
			{
				deleted.Add(next.Data.CircleEvent);
				next.Data.CircleEvent = null;
			}
			VEdge vEdge = new VEdge(vPoint, next.Data.Site, previous.Data.Site);
			next.Data.Edge = vEdge;
			edges.AddFirst(vEdge);
			previous.Data.Site.Neighbors.Add(next.Data.Site);
			next.Data.Site.Neighbors.Add(previous.Data.Site);
			beachLine.RemoveNode(toDelete);
			foreach (RBTreeNode<BeachSection> item2 in list)
			{
				beachLine.RemoveNode(item2);
			}
			CheckCircle(previous, eventQueue);
			CheckCircle(next, eventQueue);
		}

		private static double LeftBreakpoint(RBTreeNode<BeachSection> node, double directrix)
		{
			RBTreeNode<BeachSection> previous = node.Previous;
			if ((node.Data.Site.Y - directrix).ApproxEqual(0.0))
			{
				return node.Data.Site.X;
			}
			if (previous == null)
			{
				return double.NegativeInfinity;
			}
			if ((previous.Data.Site.Y - directrix).ApproxEqual(0.0))
			{
				return previous.Data.Site.X;
			}
			FortuneSite site = node.Data.Site;
			FortuneSite site2 = previous.Data.Site;
			return ParabolaMath.IntersectParabolaX(site2.X, site2.Y, site.X, site.Y, directrix);
		}

		private static double RightBreakpoint(RBTreeNode<BeachSection> node, double directrix)
		{
			RBTreeNode<BeachSection> next = node.Next;
			if ((node.Data.Site.Y - directrix).ApproxEqual(0.0))
			{
				return node.Data.Site.X;
			}
			if (next == null)
			{
				return double.PositiveInfinity;
			}
			if ((next.Data.Site.Y - directrix).ApproxEqual(0.0))
			{
				return next.Data.Site.X;
			}
			FortuneSite site = node.Data.Site;
			FortuneSite site2 = next.Data.Site;
			return ParabolaMath.IntersectParabolaX(site.X, site.Y, site2.X, site2.Y, directrix);
		}

		private static void CheckCircle(RBTreeNode<BeachSection> section, MinHeap<FortuneEvent> eventQueue)
		{
			RBTreeNode<BeachSection> previous = section.Previous;
			RBTreeNode<BeachSection> next = section.Next;
			if (previous == null || next == null)
			{
				return;
			}
			FortuneSite site = previous.Data.Site;
			FortuneSite site2 = section.Data.Site;
			FortuneSite site3 = next.Data.Site;
			if (site != site3)
			{
				double x = site2.X;
				double y = site2.Y;
				double num = site.X - x;
				double num2 = site.Y - y;
				double num3 = site3.X - x;
				double num4 = site3.Y - y;
				double num5 = num * num4 - num2 * num3;
				if (!num5.ApproxGreaterThanOrEqualTo(0.0))
				{
					double num6 = num * num + num2 * num2;
					double num7 = num3 * num3 + num4 * num4;
					double num8 = (num4 * num6 - num2 * num7) / (2.0 * num5);
					double num9 = (num * num7 - num3 * num6) / (2.0 * num5);
					double num10 = num9 + y;
					FortuneCircleEvent fortuneCircleEvent = new FortuneCircleEvent(new VPoint(num8 + x, num10 + System.Math.Sqrt(num8 * num8 + num9 * num9)), num10, section);
					section.Data.CircleEvent = fortuneCircleEvent;
					eventQueue.Insert(fortuneCircleEvent);
				}
			}
		}
	}
