	public class LandmarkSpawnerBearingUpdater : QuestObjectiveBase
	{
		[SerializeField]
		private WorldMapScoutingId _scoutingIds;

		[SerializeField]
		private BearingFeatures _bearingFeatures;

		[SerializeField]
		[QuestVariable(QuestVariableType.Landmark)]
		private int _landmarkVariable;

		public LandmarkSpawnerBearingUpdater()
		{
		}

		public LandmarkSpawnerBearingUpdater(LandmarkSpawnerBearingUpdater other)
			: base(other)
		{
			_scoutingIds = other._scoutingIds;
			_bearingFeatures = other._bearingFeatures;
			_landmarkVariable = other._landmarkVariable;
		}

		public override void SetActive(bool active)
		{
			base.SetActive(active);
			if (IsCompleted())
			{
				return;
			}
			if (base.Quest.TryGetVariableValue<LandmarkSpawner>(this, _landmarkVariable, out var value))
			{
				foreach (LandmarkSpawner landmark in value.Region.Landmarks)
				{
					if ((landmark.ScoutingId & _scoutingIds) != WorldMapScoutingId.None)
					{
						landmark.SetBearingFeatures(_bearingFeatures);
					}
				}
			}
			SetCompleted(completed: true);
		}

		public override object Clone()
		{
			return new LandmarkSpawnerBearingUpdater(this);
		}
	}
	[Serializable]
	public class ScoutLandmarkObjective : QuestObjectiveBase
	{
		[SerializeField]
		[QuestVariable(QuestVariableType.Landmark)]
		private int _landmarkVariable;

		[SerializeField]
		private SpawnerObjectiveBearing _landmarkObjectiveBearing;

		[NonSerialized]
		private LandmarkSpawner _landmark;

		public ScoutLandmarkObjective()
		{
		}

		private ScoutLandmarkObjective(ScoutLandmarkObjective other)
			: base(other)
		{
			_landmarkVariable = other._landmarkVariable;
		}

		public override void Initialize()
		{
			if (base.Quest.TryGetVariableValue<LandmarkSpawner>(this, _landmarkVariable, out _landmark))
			{
				if (_landmark.ScoutingState == ScoutingState.Scouted)
				{
					SetCompleted(completed: true);
				}
				else
				{
					_landmark.UpdatedEvent.AddListener(OnLandmarkUpdated);
				}
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception("Unable to initialize ScoutLandmarkObjective"));
				SetCompleted(completed: true);
			}
		}

		public override void Uninitialize()
		{
			_landmark?.UpdatedEvent.RemoveListener(OnLandmarkUpdated);
		}

		public override object Clone()
		{
			return new ScoutLandmarkObjective(this);
		}

		private void OnLandmarkUpdated(ISpawner spawner)
		{
			if (spawner.ScoutingState == ScoutingState.Scouted)
			{
				SetCompleted(completed: true);
			}
		}
	}
