		public void Update()
		{
			int num = _keys.Length - 1;
			if (!UnityEngine.Input.GetKeyDown(_keys[num]))
			{
				return;
			}
			int num2 = num;
			while (0 < num2--)
			{
				if (!UnityEngine.Input.GetKey(_keys[num2]))
				{
					return;
				}
			}
			_onTriggered.Invoke();
