	public class ObjectPool<T>
	{
		private readonly ConcurrentBag<T> _objects;

		private readonly Func<T> _objectGenerator;

		private readonly int _capacity;

		public int Count { get; private set; }

		public ObjectPool(Func<T> objectGenerator, int capacity = 0)
		{
			_objectGenerator = objectGenerator ?? throw new ArgumentNullException("objectGenerator");
			_objects = new ConcurrentBag<T>();
			_capacity = capacity;
		}

		public T Get()
		{
			if (_objects.TryTake(out var result))
			{
				return result;
			}
			if (_capacity <= 0 || Count < _capacity)
			{
				Count++;
				return _objectGenerator();
			}
			return default(T);
		}

		public bool TryGet(out T instance)
		{
			instance = Get();
			return instance != null;
		}

		public bool CanGet()
		{
			if (0 >= _objects.Count && _capacity > 0)
			{
				return Count < _capacity;
			}
			return true;
		}

		public void Return(T item)
		{
			if (item != null)
			{
				_objects.Add(item);
			}
		}
	}
	[Serializable]
	public class WeightedList<T>
	{
		[Serializable]
		public class Entry
		{
			public T Object;

			public float Weight;

			public float WeightThreshold { get; private set; }

			public bool TryEvaluateThreshold(float totalWeight)
			{
				if (Weight == 0f)
				{
					return false;
				}
				totalWeight += Weight;
				WeightThreshold = totalWeight;
				return true;
			}

			public bool TryGetObject(float value, out T obj)
			{
				if (value < WeightThreshold)
				{
					obj = Object;
					return true;
				}
				obj = default(T);
				return false;
			}
		}

		[SerializeField]
		private Entry[] _entries;

		public T ReturnRandom(float progress = 0f)
		{
			using PooledList<Entry> pooledList = PooledList<Entry>.Get(_entries.Length);
			float num = 0f;
			Entry[] entries = _entries;
			foreach (Entry entry in entries)
			{
				if (entry.TryEvaluateThreshold(num))
				{
					num = entry.WeightThreshold;
					pooledList.Add(entry);
				}
			}
			float value = UnityEngine.Random.Range(0f, num);
			foreach (Entry item in pooledList)
			{
				if (item.TryGetObject(value, out var obj))
				{
					return obj;
				}
			}
			throw new NotSupportedException("[WeightedList.ReturnRandom] No Object was returned!");
		}
	}
	[Serializable]
	public class WeightedObjectList
	{
		public enum Mode
		{
			Value,
			Range,
			Curve
		}

		[Serializable]
		public class Entry
		{
			public UnityEngine.Object Object;

			public float Weight;

			public float WeightTo;

			[Range(0f, 1f)]
			public float ActiveThreshold;

			public AnimationCurve WeightCurve;

			public float WeightThreshold { get; private set; }

			public bool TryEvaluateThreshold(Mode mode, float time, float totalWeight)
			{
				float num = Weight;
				switch (mode)
				{
				case Mode.Range:
					num = ((!(time < ActiveThreshold)) ? Mathf.Lerp(Weight, WeightTo, (time - ActiveThreshold) / (1f - ActiveThreshold)) : 0f);
					break;
				case Mode.Curve:
					num = WeightCurve.Evaluate(time);
					break;
				}
				if (num == 0f)
				{
					return false;
				}
				totalWeight += num;
				WeightThreshold = totalWeight;
				return true;
			}

			public bool TryGetObject(float value, out UnityEngine.Object obj)
			{
				if (value < WeightThreshold)
				{
					obj = Object;
					return true;
				}
				obj = null;
				return false;
			}
		}

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		private bool _useCachedList;

		[SerializeField]
		private Entry[] _entries;

		public bool TryReturnRandom<T>(out T obj, float progress = 0f) where T : UnityEngine.Object
		{
			obj = ReturnRandom(progress) as T;
			return obj != null;
		}

		public UnityEngine.Object ReturnRandom(float progress = 0f)
		{
			using PooledList<Entry> pooledList = PooledList<Entry>.Get(_entries.Length);
			float num = 0f;
			Entry[] entries = _entries;
			foreach (Entry entry in entries)
			{
				if (entry.TryEvaluateThreshold(_mode, progress, num))
				{
					num = entry.WeightThreshold;
					pooledList.Add(entry);
				}
			}
			float value = UnityEngine.Random.Range(0f, num);
			foreach (Entry item in pooledList)
			{
				if (item.TryGetObject(value, out var obj))
				{
					return obj;
				}
			}
			throw new NotSupportedException("[WeightedList.ReturnRandom] No Object was returned!");
		}

		public void ReturnObjectList<T>(List<T> objectList) where T : UnityEngine.Object
		{
			Entry[] entries = _entries;
			for (int i = 0; i < entries.Length; i++)
			{
				if (entries[i].Object is T itemToAdd)
				{
					objectList.AddUnique(itemToAdd);
				}
			}
		}
	}
