	[Serializable]
	public struct RangedFloat
	{
		public float Minimum;

		public float Maximum;

		public RangedFloat(float minimum, float maximum)
		{
			Minimum = minimum;
			Maximum = maximum;
		}

		public float Evaluate(float percentage)
		{
			return Mathf.Lerp(Minimum, Maximum, percentage);
		}

		public bool ReturnContainsValue(float value)
		{
			if (Minimum <= value)
			{
				return value <= Maximum;
			}
			return false;
		}

		public float ReturnRandom()
		{
			return UnityEngine.Random.Range(Minimum, Maximum);
		}
	}
	[Serializable]
	public struct RangedInt
	{
		public int Minimum;

		public int Maximum;

		public RangedInt(int minimum, int maximum)
		{
			Minimum = minimum;
			Maximum = maximum;
		}

		public int EvaluateRounded(float percentage)
		{
			return Mathf.RoundToInt(Mathf.Lerp(Minimum, Maximum, percentage));
		}

		public int ReturnSize()
		{
			if (Minimum >= Maximum)
			{
				return Minimum - Maximum;
			}
			return Maximum - Minimum;
		}

		public int ReturnRandom()
		{
			return UnityEngine.Random.Range(Minimum, Maximum);
		}

		public bool ReturnContains(int value)
		{
			if (value >= Minimum)
			{
				return Maximum >= value;
			}
			return false;
		}
	}
}
