		public static void Log(object message, UnityEngine.Object referencedObject = null, int level = 2)
		{
		}

		public static void Warning(object message, UnityEngine.Object referencedObject = null, bool onlyShowInEditor = false)
		{
			if (!onlyShowInEditor || Application.isEditor)
			{
				string text = "";
				UnityEngine.Debug.LogWarning("<color=maroon><b>" + text + message?.ToString() + "</b></color>", referencedObject);
			}
		}

