		{
			UnityEngine.Debug.LogError("" + message, referencedObject);
		}

		public static void ComponentPath(UnityEngine.Component component)
		{
		}

		public static string ReturnComponentPath(UnityEngine.Component component)
		{
			using ListPool<string>.List list = ListPool<string>.Get(10);
			Transform parent = component.transform;
			while ((bool)parent)
			{
				list.Insert(0, parent.name);
				parent = parent.parent;
			}
			return string.Join(">", list);
		}

		public static string ReturnPathFromComponentInParent<T>(UnityEngine.Component component) where T : UnityEngine.Component
		{
			return component.name;
		}

		private static StringBuilder ReturnStringBuilder()
		{
			if (_stringBuilder == null)
			{
				_stringBuilder = new StringBuilder();
			}
			else
			{
				_stringBuilder.Clear();
			}
			return _stringBuilder;
		}
	}
