namespace PajamaLlama.Utilities
{
	public static class ColorConsts
	{
		public static readonly Color WHITE_TRANSPARENT = new Color(0f, 0f, 0f, 0f);

		public static readonly Color BLACK_TRANSPARENT = new Color(1f, 1f, 1f, 0f);
	}
	public class CoroutineRunner
	{
		private static CoroutineRunner _instance;

		private Stack<IEnumerator> _stack = new Stack<IEnumerator>();

		private IEnumerator _activeCoroutine;

		public static void RunCoroutine(IEnumerator coroutine)
		{
			if (_instance == null)
			{
				_instance = new CoroutineRunner();
			}
			_instance.Run(coroutine);
		}

		private void Run(IEnumerator coroutine)
		{
			_stack.Push(coroutine);
			while (_stack.TryPop(out _activeCoroutine))
			{
				while (_activeCoroutine.MoveNext())
				{
					if (_activeCoroutine.Current is IEnumerator activeCoroutine)
					{
						_stack.Push(_activeCoroutine);
						_activeCoroutine = activeCoroutine;
					}
				}
			}
			_activeCoroutine = null;
		}

		public static bool IsRunning(object obj)
		{
			if (_instance != null)
			{
				return _instance._activeCoroutine == obj;
			}
			return false;
		}
	}
	[DefaultExecutionOrder(int.MaxValue)]
	public class FinalUpdate : MonoBehaviour
	{
		private static FinalUpdate _instance;

		private static bool _allowRegistering = true;

		private readonly List<System.Action> _listeners = new List<System.Action>(16);

		private readonly List<System.Action> _oneShots = new List<System.Action>(16);

		private readonly List<System.Action> _endOfFrameListeners = new List<System.Action>(16);

		private readonly List<System.Action> _endOfFrameOneShots = new List<System.Action>(16);

		private readonly List<System.Action> _gameStartOneshots = new List<System.Action>(16);

		private readonly List<System.Action> _actions = new List<System.Action>(16);

		private void Awake()
		{
			if ((bool)_instance)
			{
				UnityEngine.Object.Destroy(base.gameObject);
				return;
			}
			_instance = this;
			UnityEngine.Object.DontDestroyOnLoad(this);
		}

		private IEnumerator Start()
		{
			WaitForEndOfFrame waitForEndOfFrame = new WaitForEndOfFrame();
			while (base.enabled)
			{
				yield return waitForEndOfFrame;
				Invoke(_endOfFrameListeners);
				List<System.Action> listeners = new List<System.Action>(_endOfFrameOneShots);
				_endOfFrameOneShots.Clear();
				Invoke(listeners);
			}
		}

		private void LateUpdate()
		{
			Invoke(_listeners);
			Invoke(_oneShots, oneshot: true);
		}

		private void OnDestroy()
		{
			_allowRegistering = false;
		}

		private void Invoke(List<System.Action> listeners, bool oneshot = false)
		{
			_actions.Clear();
			_actions.AddRange(listeners);
			if (oneshot)
			{
				listeners.Clear();
			}
			foreach (System.Action action in _actions)
			{
				action();
			}
		}

		public static void Register(System.Action listener)
		{
			if (_allowRegistering)
			{
				GetInstance()._listeners.AddUnique(listener);
			}
		}

		public static void RegisterOneShot(System.Action oneShot)
		{
			if (_allowRegistering)
			{
				GetInstance()._oneShots.AddUnique(oneShot);
			}
		}

		public static void RegisterEndOfFrame(System.Action listener)
		{
			if (_allowRegistering)
			{
				GetInstance()._endOfFrameListeners.AddUnique(listener);
			}
		}

		public static void RegisterEndOfFrameOneShot(System.Action oneShot)
		{
			if (_allowRegistering)
			{
				GetInstance()._endOfFrameOneShots.AddUnique(oneShot);
			}
		}

		public static void RegisterGameStartOneShot(System.Action oneShot)
		{
			if (_allowRegistering)
			{
				FinalUpdate instance = GetInstance();
				if (instance._gameStartOneshots.Count == 0)
				{
					GameEventDispatcher.AddListener(GameEventType.GameStart, instance.OnGameStart);
				}
				instance._gameStartOneshots.AddUnique(oneShot);
			}
		}

		public static bool Unregister(System.Action listener)
		{
			if (_instance != null)
			{
				return _instance._listeners.Remove(listener);
			}
			return false;
		}

		public static bool UnregisterEndOfFrame(System.Action listener)
		{
			if (_instance != null)
			{
				return _instance._endOfFrameListeners.Remove(listener);
			}
			return false;
		}

		private static FinalUpdate GetInstance()
		{
			if (_instance == null)
			{
				new GameObject("FinalUpdate", typeof(FinalUpdate));
			}
			return _instance;
		}

		private void OnGameStart(GameEvent gameEvent)
		{
			GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnGameStart);
			foreach (System.Action gameStartOneshot in _gameStartOneshots)
			{
				gameStartOneshot();
			}
			_gameStartOneshots.Clear();
		}
	}
