namespace PajamaLlama.Procedural
{
	[Serializable]
	public class TaggedItemPropertiesRandomizer
	{
		public enum Modes
		{
			Random,
			RandomFromCachedList
		}

		[SerializeField]
		private Modes _mode;

		[SerializeField]
		private Item.Tags _tag = Item.Tags.Food;

		[SerializeField]
		private ItemProperties[] _itemsToExclude;

		[SerializeField]
		[Tooltip("The amount of times the items are added to the cached list.")]
		[ConditionalEnumHide("_mode", 1, false, HideInInspector = true)]
		private int _cachedListRefillCount = 1;

		private List<ItemProperties> _itemPropertiesToRandomize;

		private List<ItemProperties> _itemPropertiesToDistribute;

		public void Initialize()
		{
			_itemPropertiesToRandomize = new List<ItemProperties>();
			foreach (ItemProperties item in GameManager.Settings.ItemSettings.ReturnItemPropertiesWithTag(_tag))
			{
				if (!_itemsToExclude.Contains(item))
				{
					_itemPropertiesToRandomize.Add(item);
				}
			}
			if (_mode == Modes.RandomFromCachedList)
			{
				if (_itemPropertiesToDistribute == null)
				{
					_itemPropertiesToDistribute = new List<ItemProperties>();
				}
				else
				{
					_itemPropertiesToDistribute.Clear();
				}
			}
		}

		public ItemProperties GetRandom()
		{
			switch (_mode)
			{
			case Modes.Random:
				return _itemPropertiesToRandomize[UnityEngine.Random.Range(0, _itemPropertiesToRandomize.Count)];
			case Modes.RandomFromCachedList:
				if (_itemPropertiesToDistribute.Count == 0)
				{
					_cachedListRefillCount = Mathf.Max(1, _cachedListRefillCount);
					for (int i = 0; i < _cachedListRefillCount; i++)
					{
						_itemPropertiesToDistribute.AddRange(_itemPropertiesToRandomize);
					}
				}
				while (0 < _itemPropertiesToDistribute.Count)
				{
					int index = UnityEngine.Random.Range(0, _itemPropertiesToDistribute.Count);
					ItemProperties itemProperties = _itemPropertiesToDistribute[index];
					_itemPropertiesToDistribute.RemoveAt(index);
					if (!(itemProperties == null))
					{
						return itemProperties;
					}
				}
				UnityEngine.Debug.LogException(new Exception("Unable to return random item. It seems like there are some null references in the item list"));
				return null;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				return null;
			}
		}
	}
	public enum VEdgeConnection
	{
		None,
		EndToStart,
		StartToEnd,
		EndToEnd,
		StartToStart
	}
	public class Voronoi
	{
		public static List<VoronoiSite> Sites { get; private set; }

		public static LinkedList<VEdge> Edges { get; private set; }

		public static void Generate(List<Vector2> sites, Rect bounds, int itterations = 0)
		{
			GetGenerateEnumerator(sites, bounds, itterations).MoveNext();
		}

		public static IEnumerator GetGenerateEnumerator(List<Vector2> sites, Rect bounds, int itterations, bool debug = false)
		{
			itterations = Mathf.Max(itterations, 1);
			if (Sites == null)
			{
				Sites = new List<VoronoiSite>();
			}
			else
			{
				Sites.Clear();
			}
			foreach (Vector2 site in sites)
			{
				Sites.Add(new VoronoiSite(site));
			}
			for (int i = 0; i < itterations; i++)
			{
				RunFortunesAlgorithm(Sites, bounds);
				if (debug)
				{
					yield return null;
				}
				if (0 < i)
				{
					CenterSitePositions(Sites);
				}
			}
		}

		private static void RunFortunesAlgorithm(List<VoronoiSite> voronoiSites, Rect bounds)
		{
			using PooledList<FortuneSite> sites = PooledList<FortuneSite>.Get(voronoiSites);
			Edges = FortunesAlgorithm.Run(sites, bounds.xMin, bounds.yMin, bounds.xMax, bounds.yMax);
			foreach (VEdge edge in Edges)
			{
				(edge.Left as VoronoiSite).AddEdge(edge);
				(edge.Right as VoronoiSite).AddEdge(edge);
			}
			int num = 0;
			foreach (VoronoiSite voronoiSite in voronoiSites)
			{
				voronoiSite.ConstructPolygon(bounds);
				num++;
			}
		}

		private static void CenterSitePositions(List<VoronoiSite> voronoisSites)
		{
			foreach (VoronoiSite voronoisSite in voronoisSites)
			{
				voronoisSite.SetPositionToCellCenterAndReset();
			}
		}
	}
	public static class VoronoiExtensions
	{
		public static Vector2 ToVector2(this VPoint vPoint)
		{
			return new Vector2((float)vPoint.X, (float)vPoint.Y);
		}

		public static bool IsOnOrOutsideBounds(this VPoint vPoint, Rect bounds)
		{
			if (!(vPoint.X <= (double)bounds.xMin) && !((double)bounds.xMax <= vPoint.X) && !(vPoint.Y <= (double)bounds.yMin))
			{
				return (double)bounds.yMax <= vPoint.Y;
			}
			return true;
		}

		public static bool TryGetBoundsCollision(this VPoint vPoint, Rect bounds, out Vector2 collision)
		{
			bool result = false;
			collision = Vector2.zero;
			if (vPoint.X <= (double)bounds.xMin)
			{
				collision.x = bounds.xMin;
				result = true;
			}
			else if ((double)bounds.xMax <= vPoint.X)
			{
				collision.x = bounds.xMax;
				result = true;
			}
			if (vPoint.Y <= (double)bounds.yMin)
			{
				collision.y = bounds.xMin;
				result = true;
			}
			else if ((double)bounds.yMax <= vPoint.Y)
			{
				collision.y = bounds.xMax;
				result = true;
			}
			return result;
		}

		public static void Flip(this VEdge edge)
		{
			VPoint start = edge.Start;
			edge.Start = edge.End;
			edge.End = start;
		}

		public static float SignedAngle(this VEdge edge, VEdge other)
		{
			Vector2 vector;
			Vector2 to;
			if (edge.End == other.Start)
			{
				vector = edge.Start.ToVector2() - edge.End.ToVector2();
				to = other.End.ToVector2() - other.Start.ToVector2();
			}
			else
			{
				if (edge.Start != other.End)
				{
					return 0f;
				}
				vector = edge.End.ToVector2() - edge.Start.ToVector2();
				to = other.Start.ToVector2() - other.End.ToVector2();
			}
			return Vector2.SignedAngle(vector, to);
		}
	}
	[Serializable]
	public class VoronoiRegion : IRegion
	{
		[SerializeField]
		[HideInInspector]
		private List<int> _siteIndices;

		[SerializeField]
		private WorldRegionType _region;

		[SerializeField]
		private PollutionLevels _pollutionLevel;

		[SerializeField]
		private QuestProperties _questProperties;

		[SerializeField]
		[ConditionalHide("_questProperties", true)]
		private QuestGiver _questGiver;

		[SerializeReference]
		[InstantiateSerializeReference]
		private ScenarioTriggerableBase[] _onEnterTriggerables;

		public List<int> SiteIndices => _siteIndices;

		public WorldRegionType Type => _region;

		public PollutionLevels PollutionLevel => _pollutionLevel;

		public QuestProperties QuestProperties => _questProperties;

		public QuestGiver QuestGiver => _questGiver;

		public List<VEdge> BorderEdges { get; private set; }

		public Rect Bounds => ReturnBounds();

		public ScenarioTriggerableBase[] EnterTriggerables => _onEnterTriggerables;

		public VoronoiRegion(IEnumerable<int> voronoiSiteCollection, WorldRegionType region)
		{
			_siteIndices = new List<int>(voronoiSiteCollection);
			_region = region;
			UpdateBorderEdges();
		}

		public void AddSites(IList<int> sitesToAdd)
		{
			if (SiteIndices.AddUniqueRange(sitesToAdd))
			{
				UpdateBorderEdges();
			}
		}

		public bool RemoveSite(int index)
		{
			if (SiteIndices.Remove(index))
			{
				UpdateBorderEdges();
				return true;
			}
			return false;
		}

		public void UpdateBorderEdges(bool sort = false)
		{
			if (BorderEdges == null)
			{
				BorderEdges = new List<VEdge>();
			}
			else
			{
				BorderEdges.Clear();
			}
			if (_siteIndices == null)
			{
				return;
			}
			foreach (int siteIndex in _siteIndices)
			{
				foreach (VEdge item in Voronoi.Sites[siteIndex].Cell)
				{
					if (!BorderEdges.Remove(item))
					{
						BorderEdges.Add(item);
					}
				}
			}
			if (sort)
			{
				SortBorderEdges();
			}
		}

		private void SortBorderEdges()
		{
			if (BorderEdges.IsNullOrEmpty())
			{
				return;
			}
			using PooledList<VEdge> pooledList = PooledList<VEdge>.Get();
			VEdge next = BorderEdges[0];
			VEdge vEdge = null;
			do
			{
				BorderEdges.Remove(next);
				pooledList.Add(next);
				vEdge = next;
			}
			while (TryGetNextEdge(out next, vEdge, BorderEdges));
			BorderEdges.Clear();
			BorderEdges.AddRange(pooledList);
		}

		private bool TryGetNextEdge(out VEdge next, VEdge previous, List<VEdge> edges)
		{
			for (int i = 0; i < edges.Count; i++)
			{
				next = edges[i];
				if (next.Start == previous.End)
				{
					return true;
				}
				if (next.End == previous.End)
				{
					next.Flip();
					return true;
				}
			}
			next = null;
			return false;
		}

		public void GenerateTriangles(List<Vector3> vertices, List<int> triangles, List<Vector2> uvs)
		{
			Vector2 regionUVOffset = GetRegionUVOffset();
			foreach (int siteIndex in _siteIndices)
			{
				Voronoi.Sites[siteIndex].GenerateMeshTriangles(vertices, triangles, uvs, regionUVOffset);
			}
		}

		private Vector2 GetRegionUVOffset()
		{
			switch (Type)
			{
			case WorldRegionType.Forest:
				return new Vector2(0f, 0.75f);
			case WorldRegionType.Rural:
				return new Vector2(0.25f, 0.75f);
			case WorldRegionType.City:
				return new Vector2(0.5f, 0.75f);
			case WorldRegionType.PollutedWoods:
				return new Vector2(0.75f, 0.75f);
			case WorldRegionType.Farmland:
				return new Vector2(0f, 0.5f);
			case WorldRegionType.Shallow:
				return new Vector2(0.25f, 0.5f);
			case WorldRegionType.Industry:
				return new Vector2(0.75f, 0.5f);
			case WorldRegionType.Utopia:
				return new Vector2(0f, 0.25f);
			case WorldRegionType.PollutionBelt:
				return new Vector2(0.25f, 0.25f);
			default:
				UnityEngine.Debug.LogError("Region type not supported!");
				return Vector2.zero;
			}
		}

		public bool ReturnContainsPosition(Vector2 position)
		{
			if (Voronoi.Sites.IsNullOrEmpty())
			{
				return false;
			}
			foreach (int siteIndex in _siteIndices)
			{
				VoronoiSite voronoiSite = Voronoi.Sites[siteIndex];
				if (voronoiSite.Polygon != null && voronoiSite.Polygon.Bounds.Contains(position) && voronoiSite.Polygon.ReturnPointIsOverlapping(position))
				{
					return true;
				}
			}
			return false;
		}

		public bool TryReturnDistanceToBorder(Vector2 tilePosition, out float distance)
		{
			foreach (int siteIndex in _siteIndices)
			{
				VoronoiSite voronoiSite = Voronoi.Sites[siteIndex];
				if (voronoiSite.Polygon.ReturnPointIsOverlapping(tilePosition))
				{
					distance = ReturnDistanceToBorder(voronoiSite, tilePosition, out var _);
					return true;
				}
			}
			distance = float.MaxValue;
			return false;
		}

		private float ReturnDistanceToBorder(VoronoiSite site, Vector2 position, out Vector2 projection)
		{
			projection = Vector2.zero;
			if (BorderEdges == null)
			{
				return 0f;
			}
			float num = float.MaxValue;
			foreach (VEdge item in site.Cell)
			{
				if (BorderEdges.Contains(item))
				{
					Vector2 vector = new Polygon2DLine(item.Start.ToVector2(), item.End.ToVector2()).ReturnProjection(position);
					float num2 = position.DistanceToSquared(vector);
					if (num2 < num)
					{
						projection = vector;
						num = num2;
					}
				}
			}
			return Mathf.Sqrt(num);
		}

		public Rect ReturnBounds()
		{
			Vector2 vector = new Vector2(float.MaxValue, float.MaxValue);
			Vector2 vector2 = new Vector2(float.MinValue, float.MinValue);
			foreach (int siteIndex in SiteIndices)
			{
				VoronoiSite voronoiSite = Voronoi.Sites[siteIndex];
				vector = Vector2.Min(vector, voronoiSite.Polygon.Bounds.min);
				vector2 = Vector2.Max(vector2, voronoiSite.Polygon.Bounds.max);
			}
			return new Rect(vector, vector2 - vector);
		}

		public float ReturnSurface()
		{
			float num = 0f;
			foreach (int siteIndex in _siteIndices)
			{
				num += Voronoi.Sites[siteIndex].ComputeSurface();
			}
			return num;
		}

		public float ReturnOverlap(Polygon2DBase polygon)
		{
			float num = 0f;
			foreach (int siteIndex in _siteIndices)
			{
				if (Voronoi.Sites[siteIndex].Polygon.TryGetOverlap(polygon, out var overlap))
				{
					num += overlap;
				}
			}
			return num;
		}

		public Vector2 ReturnPositionInRegion()
		{
			return Voronoi.Sites[_siteIndices[UnityEngine.Random.Range(0, _siteIndices.Count)]].Position;
		}
	}
	public class VoronoiSite : FortuneSite
	{
		private static readonly Vector2 AXIS_MULTIPLIER = new Vector2(1f, -1f);

		private Mesh _mesh;

		public Vector2 Position { get; private set; }

		public List<Vector2> Vertices { get; private set; }

		public bool HasEdgesOnBounds { get; private set; }

		public Polygon Polygon { get; private set; }

		public Color DEBUG_Color { get; private set; }

		public VoronoiSite(Vector2 position)
			: base(position.x, position.y)
		{
			Position = position;
		}

		public VoronoiSite(float x, float y)
			: this(new Vector2(x, y))
		{
		}

		public void AddEdge(VEdge edge)
		{
			base.Cell.Add(edge);
		}

		public void ConstructPolygon(Rect bounds)
		{
			if (base.Cell.Count == 0)
			{
				return;
			}
			using (PooledList<VEdge> pooledList = PooledList<VEdge>.Get(base.Cell.Count))
			{
				VEdge nextEdge = GetCellStartEdge(base.Cell, bounds);
				VEdge vEdge = null;
				do
				{
					base.Cell.Remove(nextEdge);
					pooledList.Add(nextEdge);
					vEdge = nextEdge;
				}
				while (TryGetNextEdge(out nextEdge, vEdge, base.Cell, bounds));
				base.Cell.Clear();
				base.Cell.AddRange(pooledList);
			}
			HasEdgesOnBounds = VoronoiLibFunctions.AddBoundsEdgesToCell(base.Cell, bounds);
			if (Vertices == null)
			{
				Vertices = new List<Vector2>(base.Cell.Count);
			}
			else
			{
				Vertices.Clear();
			}
			if (0f <= base.Cell[0].SignedAngle(base.Cell[1]))
			{
				foreach (VEdge item in base.Cell)
				{
					Vertices.Add(item.Start.ToVector2());
				}
			}
			else
			{
				int count = base.Cell.Count;
				while (0 < count--)
				{
					Vertices.Add(base.Cell[count].Start.ToVector2());
				}
			}
			Polygon = new Polygon(Vertices);
		}

		public void SetPositionToCellCenterAndReset()
		{
			if (!base.Cell.IsNullOrEmpty())
			{
				Position = GetCentroid();
				base.X = Position.x;
				base.Y = Position.y;
			}
			base.Cell.Clear();
			base.Neighbors.Clear();
		}

		private bool TryGetNextEdge(out VEdge nextEdge, VEdge previousEdge, List<VEdge> edges, Rect bounds)
		{
			Vector2 collision;
			bool flag = previousEdge.End.TryGetBoundsCollision(bounds, out collision);
			VEdge vEdge = null;
			nextEdge = null;
			if (edges.Count == 0)
			{
				return false;
			}
			for (int i = 0; i < base.Cell.Count; i++)
			{
				nextEdge = base.Cell[i];
				if (previousEdge.End == nextEdge.Start)
				{
					return true;
				}
				if (previousEdge.End == nextEdge.End)
				{
					nextEdge.Flip();
					return true;
				}
				if (flag)
				{
					if (nextEdge.Start.TryGetBoundsCollision(bounds, out var collision2) && collision == collision2)
					{
						vEdge = new VEdge(previousEdge.End, this, null)
						{
							End = nextEdge.Start
						};
					}
					else if (nextEdge.End.TryGetBoundsCollision(bounds, out collision2) && collision == collision2)
					{
						vEdge = new VEdge(previousEdge.End, this, null)
						{
							End = nextEdge.End
						};
					}
				}
			}
			nextEdge = vEdge ?? throw new NotSupportedException("Huh?");
			return true;
		}

		public float ComputeSurface()
		{
			using ListPool<Vector3>.List list = ListPool<Vector3>.Get();
			using ListPool<int>.List list2 = ListPool<int>.Get();
			using ListPool<Vector2>.List uvs = ListPool<Vector2>.Get();
			float num = 0f;
			GenerateMeshTriangles(list, list2, uvs, Vector2.zero);
			for (int i = 0; i < list2.Count; i += 3)
			{
				Vector3 vector = list[list2[i]];
				Vector3 vector2 = list[list2[i + 1]];
				Vector3 vector3 = list[list2[i + 2]];
				float magnitude = (vector2 - vector).magnitude;
				float magnitude2 = (vector3 - vector2).magnitude;
				float magnitude3 = (vector - vector3).magnitude;
				float num2 = (magnitude + magnitude2 + magnitude3) / 2f;
				num += Mathf.Sqrt(num2 * (num2 - magnitude) * (num2 - magnitude2) * (num2 - magnitude3));
			}
			return num;
		}

		public VEdge GetCellStartEdge(List<VEdge> cell, Rect bounds)
		{
			foreach (VEdge item in cell)
			{
				if (item.Start.IsOnOrOutsideBounds(bounds))
				{
					return item;
				}
				if (item.End.IsOnOrOutsideBounds(bounds))
				{
					item.Flip();
					return item;
				}
			}
			return cell[0];
		}

		public Vector2 GetCentroid()
		{
			if (base.Cell.IsNullOrEmpty())
			{
				return Vector2.zero;
			}
			double num = 0.0;
			double num2 = 0.0;
			int num3 = 0;
			foreach (VEdge item in base.Cell)
			{
				num += item.Start.X + item.End.X;
				num2 += item.Start.Y + item.End.Y;
				num3 += 2;
			}
			return new Vector2((float)num / (float)num3, (float)num2 / (float)num3);
		}

		public Mesh GetMesh(out Vector2 centroid)
		{
			centroid = GetCentroid();
			if (_mesh == null)
			{
				int count = Vertices.Count;
				int num = count + 1;
				Vector3[] array = new Vector3[num];
				int[] array2 = new int[count * 3];
				array[0] = Vector2.zero;
				for (int i = 0; i < count; i++)
				{
					array[i + 1] = (Vertices[i] - centroid) * AXIS_MULTIPLIER;
					int num2 = i * 3;
					array2[num2] = 0;
					array2[num2 + 1] = PajamaLlama.Math.Math.IncrementIndexWrapped(i, num);
					array2[num2 + 2] = PajamaLlama.Math.Math.IncrementIndexWrapped(i, num, 2);
				}
				array2[^1] = 1;
				_mesh = new Mesh();
				_mesh.SetVertices(array);
				_mesh.SetTriangles(array2, 0);
			}
			return _mesh;
		}

		public void GenerateMeshTriangles(List<Vector3> vertices, List<int> triangles, List<Vector2> uvs, Vector2 uvOffset)
		{
			int count = Vertices.Count;
			int maxIndex = count + 1;
			int count2 = vertices.Count;
			vertices.Add(GetCentroid());
			uvs.Add(uvOffset);
			for (int i = 0; i < count; i++)
			{
				vertices.Add(Vertices[i]);
				uvs.Add(uvOffset);
				triangles.Add(count2);
				triangles.Add(count2 + PajamaLlama.Math.Math.IncrementIndexWrapped(i, maxIndex));
				triangles.Add(count2 + PajamaLlama.Math.Math.IncrementIndexWrapped(i, maxIndex, 2));
			}
			triangles[triangles.Count - 1] = count2 + 1;
		}
	}
}
