namespace PajamaLlama.Math
{
	public static class Geometry2D
	{
		private const float INTERSECT_VECTOR_MULTIPLIER = 1000f;

		public static void ComputeConvexHullIndices(List<Vector2> vertices, List<int> indices)
		{
			int num = GetMinVertexIndex(vertices);
			int count = vertices.Count;
			int num2 = 0;
			Vector2 directionToNextVertex = Vector2.up;
			while (!indices.Contains(num) && num2 < count)
			{
				indices.Add(num);
				num = GetNextVertexIndex(vertices, num, directionToNextVertex, out directionToNextVertex);
				num2++;
			}
		}

		private static int GetMinVertexIndex(List<Vector2> vertices)
		{
			Vector2 vector = new Vector2(float.MaxValue, float.MaxValue);
			int count = vertices.Count;
			int result = -1;
			for (int i = 0; i < count; i++)
			{
				Vector2 vector2 = vertices[i];
				if (vector2.x < vector.x)
				{
					vector = vector2;
				}
				else
				{
					if (vector2.x != vector.x || !(vector2.y < vector.y))
					{
						continue;
					}
					vector.y = vector2.y;
				}
				result = i;
			}
			return result;
		}

		private static int GetNextVertexIndex(List<Vector2> vertices, int currentVertexIndex, Vector2 directionToCurrentVertex, out Vector2 directionToNextVertex)
		{
			Vector2 vector = vertices[currentVertexIndex];
			int result = -1;
			float num = float.MaxValue;
			directionToNextVertex = default(Vector2);
			for (int i = 0; i < vertices.Count; i++)
			{
				if (i == currentVertexIndex)
				{
					continue;
				}
				Vector2 vector2 = vertices[i] - vector;
				float num2 = Vector2.SignedAngle(vector2, directionToCurrentVertex);
				if (0f <= num2 && num2 < 180f)
				{
					if (num2 < num)
					{
						num = num2;
						directionToNextVertex = vector2;
						result = i;
					}
					else if (num2 == num && directionToNextVertex.sqrMagnitude < vector2.sqrMagnitude)
					{
						directionToNextVertex = vector2;
						result = i;
					}
				}
			}
			return result;
		}

		public static ListPool<Vector2>.List ScalePolygon(Vector2[] vertices, float scale)
		{
			int num = vertices.Length;
			if (num < 3)
			{
				throw new NotSupportedException();
			}
			Vector2 zero = Vector2.zero;
			for (int i = 0; i < num; i++)
			{
				zero += vertices[i];
			}
			zero /= (float)num;
			ListPool<Vector2>.List list = ListPool<Vector2>.Get(num);
			for (int j = 0; j < num; j++)
			{
				list.Add(zero + (vertices[j] - zero) * scale);
			}
			return list;
		}

		public static void AddPaddingToPolygon(List<Vector2> vertices, List<Vector2> paddedVertices, float padding)
		{
			int count = vertices.Count;
			if (count < 3)
			{
				throw new NotSupportedException();
			}
			paddedVertices.Clear();
			if (paddedVertices.Capacity < count)
			{
				paddedVertices.Capacity = count;
			}
			Vector2 vertexLeft = vertices[count - 2];
			Vector2 vector = vertices[count - 1];
			for (int i = 0; i < count; i++)
			{
				Vector2 vector2 = vertices[i];
				if (TryReturnPaddedPolygonVertex(vertexLeft, vector, vector2, padding, out var paddedVertex))
				{
					paddedVertices.Add(paddedVertex);
				}
				vertexLeft = vector;
				vector = vector2;
			}
		}

		public static ListPool<Vector2>.List AddPaddingToPolygon(Vector2[] vertices, float padding)
		{
			int num = vertices.Length;
			if (num < 3)
			{
				throw new NotSupportedException();
			}
			ListPool<Vector2>.List list = ListPool<Vector2>.Get(num);
			Vector2 vertexLeft = vertices[num - 2];
			Vector2 vector = vertices[num - 1];
			for (int i = 0; i < num; i++)
			{
				Vector2 vector2 = vertices[i];
				if (TryReturnPaddedPolygonVertex(vertexLeft, vector, vector2, padding, out var paddedVertex))
				{
					list.Add(paddedVertex);
				}
				vertexLeft = vector;
				vector = vector2;
			}
			return list;
		}

		private static bool TryReturnPaddedPolygonVertex(Vector2 vertexLeft, Vector2 vertex, Vector2 vertexRight, float padding, out Vector2 paddedVertex)
		{
			Vector2 normalized = (vertex - vertexLeft).normalized;
			Vector2 vector = new Vector2(0f - normalized.y, normalized.x);
			Vector2 linePoint = vertex + vector * padding;
			Vector2 normalized2 = (vertex - vertexRight).normalized;
			Vector2 vector2 = new Vector2(normalized2.y, 0f - normalized2.x);
			return TryIntersect(linePoint2: vertex + vector2 * padding, linePoint1: linePoint, lineVector1: normalized * 1000f, lineVector2: normalized2 * 1000f, intersectionPoint: out paddedVertex);
		}

		public static bool TryIntersect(Vector2 linePoint1, Vector2 lineVector1, Vector2 linePoint2, Vector2 lineVector2, out Vector2 intersectionPoint)
		{
			lineVector2 = -lineVector2;
			Vector2 vector = linePoint1 - linePoint2;
			float num = lineVector2.y * vector.x - lineVector2.x * vector.y;
			float num2 = lineVector1.x * vector.y - lineVector1.y * vector.x;
			float num3 = lineVector1.y * lineVector2.x - lineVector1.x * lineVector2.y;
			intersectionPoint = default(Vector2);
			if (num3 == 0f)
			{
				return false;
			}
			if (num3 > 0f)
			{
				if (num < 0f || num > num3 || num2 < 0f || num2 > num3)
				{
					return false;
				}
			}
			else if (num > 0f || num < num3 || num2 > 0f || num2 < num3)
			{
				return false;
			}
			intersectionPoint = linePoint1 + lineVector1 * num / num3;
			return true;
		}
	}
	public static class Triangulator2D
	{
		public interface Vertex
		{
			Vector2 Position { get; }
		}

		public struct Triangle
		{
			public Vector2 VertexA;

			public Vector2 VertexB;

			public Vector2 VertexC;

			public int IndexVertexA;

			public int IndexVertexB;

			public int IndexVertexC;

			public Vector2 VectorAB;

			public Vector2 VectorAC;

			public float AngleAB_AC;

			public override string ToString()
			{
				return $"VertexA: {VertexA}, VertexB: {VertexB}, VertexC: {VertexC}, IndexVertexA: {IndexVertexA}, IndexVertexB: {IndexVertexB}, IndexVertexC: {IndexVertexC}, VectorAB: {VectorAB}, VectorAC: {VectorAC}, AngleAB_AC: {AngleAB_AC}";
			}
		}

		private static List<Vector2> _vertices;

		private static Triangle _triangle;

		private static Vector2[] _triangleVertices = new Vector2[3];

		private static List<Vector2> _verticesToDecompose;

		private static List<Vector2> _convexVertices = new List<Vector2>();

		private static Polygon _polygon = new Polygon();

		public static IEnumerator<Triangle> GetTriangulateEnumerator(IEnumerable<Vertex> vertices)
		{
			PopulateVertices(vertices);
			return GetTriangulationEnumerator(_vertices);
		}

		public static Vector2 TriangulateCentroid(IEnumerable<Vector2> vertices)
		{
			IEnumerator<Triangle> triangulationEnumerator = GetTriangulationEnumerator(vertices);
			Vector2 zero = Vector2.zero;
			int num = 0;
			while (triangulationEnumerator.MoveNext())
			{
				zero += (_triangle.VertexA + _triangle.VertexB + _triangle.VertexC) / 3f;
				num++;
			}
			if (0 >= num)
			{
				return Vector2.negativeInfinity;
			}
			return zero / num;
		}

		public static Vector2 TriangulateCentroid(IEnumerable<Vertex> vertices)
		{
			PopulateVertices(vertices);
			return TriangulateCentroid(_vertices);
		}

		private static IEnumerator<Triangle> GetTriangulationEnumerator(IEnumerable<Vector2> vertices)
		{
			using PooledList<Vector2> vertexList = PooledList<Vector2>.Get(vertices);
			float vertexDirection = ComputeDirection(vertexList);
			int lastEarIndex = 0;
			while (TryFindEar(vertexList, lastEarIndex, vertexDirection))
			{
				lastEarIndex = _triangle.IndexVertexA;
				vertexList.RemoveAt(lastEarIndex);
				yield return _triangle;
			}
		}

		private static bool TryFindEar(List<Vector2> vertices, int startIndex, float vertexDirection)
		{
			IEnumerator<Triangle> triangleEnumerator = GetTriangleEnumerator(vertices, startIndex);
			while (triangleEnumerator.MoveNext())
			{
				if (Mathf.Sign(_triangle.AngleAB_AC) != vertexDirection)
				{
					continue;
				}
				_triangleVertices[0] = _triangle.VertexA;
				_triangleVertices[1] = _triangle.VertexB;
				_triangleVertices[2] = _triangle.VertexC;
				if (_polygon == null)
				{
					_polygon = new Polygon();
				}
				_polygon.Update(_triangleVertices);
				bool flag = false;
				foreach (Vector2 vertex in vertices)
				{
					if (!(vertex == _triangle.VertexA) && !(vertex == _triangle.VertexB) && !(vertex == _triangle.VertexC) && _polygon.ReturnPointIsOverlapping(vertex))
					{
						flag = true;
						break;
					}
				}
				if (!flag)
				{
					return true;
				}
			}
			return false;
		}

		public static IEnumerator<Vector2[]> GetDecomposeEnumerator(IEnumerable<Vertex> vertices)
		{
			PopulateVertices(vertices);
			using PooledList<Vector2> verticesToDecompose = PooledList<Vector2>.Get(_vertices);
			using PooledList<Vector2> convexVertices = PooledList<Vector2>.Get();
			while (2 < _verticesToDecompose.Count)
			{
				convexVertices.Clear();
				for (int i = 0; i < verticesToDecompose.Count; i++)
				{
					TryAddConvexVertex(verticesToDecompose[i], convexVertices, _vertices);
				}
				yield return convexVertices.ToArray();
			}
		}

		private static bool TryAddConvexVertex(Vector2 vertex, List<Vector2> convexVertices, List<Vector2> allVertices)
		{
			convexVertices.Add(vertex);
			if (convexVertices.Count < 3)
			{
				return true;
			}
			if (IsConvex(convexVertices) && !IsAnyPointOVerlapping(convexVertices, allVertices))
			{
				return true;
			}
			if (convexVertices.Count == 3)
			{
				convexVertices.RemoveAt(0);
				return true;
			}
			convexVertices.Remove(vertex);
			return false;
		}

		public static bool IsConvex(List<Vector2> vertices)
		{
			IEnumerator<Triangle> triangleEnumerator = GetTriangleEnumerator(vertices);
			float num = 0f;
			while (triangleEnumerator.MoveNext())
			{
				Triangle current = triangleEnumerator.Current;
				if (num == 0f)
				{
					num = current.AngleAB_AC;
					continue;
				}
				if (num < 0f && 0f < current.AngleAB_AC)
				{
					return false;
				}
				if (!(0f < num) || !(current.AngleAB_AC < 0f))
				{
					continue;
				}
				return false;
			}
			return true;
		}

		private static void PopulateVertices(IEnumerable<Vertex> vertices)
		{
			if (_vertices == null)
			{
				_vertices = new List<Vector2>();
			}
			else
			{
				_vertices.Clear();
			}
			foreach (Vertex vertex in vertices)
			{
				_vertices.Add(vertex.Position);
			}
		}

		private static float ComputeDirection(List<Vector2> vertices)
		{
			IEnumerator<Triangle> triangleEnumerator = GetTriangleEnumerator(vertices);
			float num = 0f;
			while (triangleEnumerator.MoveNext())
			{
				num += _triangle.AngleAB_AC;
			}
			return Mathf.Sign(num);
		}

		private static bool IsAnyPointOVerlapping(List<Vector2> polygon, List<Vector2> points)
		{
			if (_polygon == null)
			{
				_polygon = new Polygon();
			}
			_polygon.Update(polygon);
			foreach (Vector2 point in points)
			{
				if (!polygon.Contains(point) && _polygon.ReturnPointIsOverlapping(point))
				{
					return true;
				}
			}
			return false;
		}

		private static IEnumerator<Triangle> GetTriangleEnumerator(List<Vector2> vertices, int startIndex = 0)
		{
			int vertexCount = vertices.Count;
			int index = Math.WrapIndex(startIndex, vertexCount);
			if (vertexCount >= 3)
			{
				_triangle.IndexVertexA = index;
				_triangle.VertexA = vertices[_triangle.IndexVertexA];
				_triangle.IndexVertexB = Math.WrapIndex(index - 1, vertexCount);
				_triangle.VertexB = vertices[_triangle.IndexVertexB];
				_triangle.VectorAB = _triangle.VertexB - _triangle.VertexA;
				for (int i = 0; i < vertexCount; i++)
				{
					int num = index + 1;
					index = num;
					_triangle.IndexVertexC = Math.WrapIndex(num, vertexCount);
					_triangle.VertexC = vertices[_triangle.IndexVertexC];
					_triangle.VectorAC = _triangle.VertexC - _triangle.VertexA;
					_triangle.AngleAB_AC = Vector2.SignedAngle(_triangle.VectorAB, _triangle.VectorAC);
					yield return _triangle;
					_triangle.IndexVertexB = _triangle.IndexVertexA;
					_triangle.VertexB = _triangle.VertexA;
					_triangle.IndexVertexA = _triangle.IndexVertexC;
					_triangle.VertexA = _triangle.VertexC;
					_triangle.VectorAB = _triangle.VertexB - _triangle.VertexA;
				}
			}
		}
	}
	public class Math
	{
		public static int WrapIndex(int index, int maxIndex)
		{
			int num = index % maxIndex;
			if (num < 0)
			{
				num += maxIndex;
			}
			return num;
		}

		public static int IncrementIndexWrapped(int index, int maxIndex, int amount = 1)
		{
			return (index + amount) % maxIndex;
		}

		public static int DecrementIndexWrapped(int index, int maxIndex, int amount = 1)
		{
			int num = (index - amount) % maxIndex;
			if (num < 0)
			{
				return num + maxIndex;
			}
			return num;
		}

		public static Vector2 ReturnPerpendicularVector(Vector2 vector)
		{
			return new Vector2(0f - vector.y, vector.x);
		}

		public static Vector2 ReturnSmallestVector(List<Vector2> points)
		{
			Vector2 vector = points[0];
			for (int i = 0; i < points.Count; i++)
			{
				vector = Vector2.Min(vector, points[i]);
			}
			return vector;
		}

		public static Vector2 ReturnBiggestVector(List<Vector2> points)
		{
			Vector3 vector = points[0];
			for (int i = 0; i < points.Count; i++)
			{
				vector = Vector2.Max((Vector2)vector, points[i]);
			}
			return vector;
