	public static class Bezier
	{
		private static float CalculateBinomialFactor(int n, int k)
		{
			return CalculateFactorial(n) / (CalculateFactorial(k) * CalculateFactorial(n - k));
		}

		private static int CalculateFactorial(int n)
		{
			if (n <= 1)
			{
				return 1;
			}
			return n * CalculateFactorial(n - 1);
		}

		private static Vector3 CalculateCurvePoint(float t, int n, int k, Vector3 point)
		{
			_ = Vector3.zero;
			return CalculateBernsteinPolynomial(t, n, k) * point;
		}

		public static Vector3 CalculatePointInTime(float t, List<Vector3> points)
		{
			int n = points.Count - 1;
			Vector3 zero = Vector3.zero;
			for (int i = 0; i < points.Count; i++)
			{
				int num = i;
				zero += CalculateCurvePoint(t, n, num, points[num]);
			}
			return zero;
		}

		private static float CalculateBernsteinPolynomial(float t, int n, int k)
		{
			return CalculateBinomialFactor(n, k) * Mathf.Pow(1f - t, n - k) * Mathf.Pow(t, k);
		}

		public static Vector3 CalculateDerivative(float t, List<Vector3> points)
		{
			Vector3 zero = Vector3.zero;
			int num = points.Count - 1;
			for (int i = 0; i < points.Count - 1; i++)
			{
				int num2 = i;
				zero += (points[num2 + 1] - points[num2]) * CalculateBernsteinPolynomial(t, num - 1, num2);
			}
			return zero * num;
		}

		public static Vector2 CalculateBezierPoint(float t, Vector2 startPosition, Vector2 startCurve, Vector2 endCurve, Vector2 endPosition)
		{
			float num = 1f - t;
			float num2 = t * t;
			float num3 = num * num;
			float num4 = num3 * num;
			float num5 = num2 * t;
			return num4 * startPosition + 3f * num3 * t * startCurve + 3f * num * num2 * endCurve + num5 * endPosition;
		}

		public static Vector3 CalculateQuadraticBezierPoint(float t, Vector3 startPoint, Vector3 middlePoint, Vector3 endPoint)
		{
			float num = 1f - t;
			float num2 = t * t;
			return num * num * startPoint + 2f * num * t * middlePoint + num2 * endPoint;
		}
	}
	public static class MathExtensions
	{
		private static Rectangle _tempPolygon = new Rectangle();

		public static Vector3 Vector3TopDown(this Vector2 vector, float y = 0f)
		{
			return new Vector3(vector.x, y, vector.y);
		}

		public static Vector3 Vector3TopDown(this Vector3 vector)
		{
			return new Vector3(vector.x, 0f, vector.z);
		}

		public static Vector2 Normalize(this Vector2 vector)
		{
			float x = vector.x;
			float y = vector.y;
			float num = Mathf.Sqrt(x * x + y * y);
			return new Vector2(x / num, y / num);
		}

		public static float DistanceToSquared(this Vector2 from, Vector2 to)
		{
			float num = to.x - from.x;
			float num2 = to.y - from.y;
			return num * num + num2 * num2;
		}

		public static float DistanceToSquared(this Vector2 from, float pointX, float pointY)
		{
			float num = pointX - from.x;
			float num2 = pointY - from.y;
			return num * num + num2 * num2;
		}

		public static bool IsInRange(this Vector2 from, Vector2 to, float distance)
		{
			float num = to.x - from.x;
			float num2 = to.y - from.y;
			return num * num + num2 * num2 < distance * distance;
		}

		public static float Angle(this Vector2 from, Vector2 to)
		{
			float x = from.x;
			float y = from.y;
			float num = Mathf.Sqrt(x * x + y * y);
			float num2 = x / num;
			y /= num;
			float x2 = to.x;
			float y2 = to.y;
			float num3 = Mathf.Sqrt(x2 * x2 + y2 * y2);
			x2 /= num3;
			y2 /= num3;
			return Mathf.Acos(num2 * x2 + y * y2) * 57.29578f;
		}

		public static float Cross(this Vector2 left, Vector2 right)
		{
			return left.x * right.y - right.x * left.y;
		}

		public static Vector2 Average(this IReadOnlyList<Vector2> vectors)
		{
			if (vectors == null || vectors.Count == 0)
			{
				return Vector2.zero;
			}
			float num = 0f;
			float num2 = 0f;
			foreach (Vector2 vector in vectors)
			{
				num += vector.x;
				num2 += vector.y;
			}
			return new Vector2(num / (float)vectors.Count, num2 / (float)vectors.Count);
		}

		public static bool Approximately(this Vector2 vector, Vector2 other, float margin)
		{
			margin *= margin;
			return (vector - other).sqrMagnitude < margin;
		}

