		public static bool TryReturnClosest<T>(this List<T> components, out T closestComponent, Vector3 position, float range) where T : UnityEngine.Component
		{
			float num = range * range;
			closestComponent = null;
			foreach (T component in components)
			{
				float num2 = position.DistanceToSquared(component.transform.position);
				if (num2 < num)
				{
					num = num2;
					closestComponent = component;
				}
			}
			return closestComponent;
		}
	}
