namespace PajamaLlama.Distribution
{
	[Serializable]
	public abstract class PickingListBase<T> : IDisposable
	{
		public enum PickingOrder
		{
			InOrder = 0,
			Random = 16,
			RandomWithElimination = 17
		}

		[SerializeField]
		private PickingOrder _pickingOrder;

		[Tooltip("Limits the amount of items that can be picked, if the value is 0 the amount of items that can be picked is unlimited.")]
		[SerializeField]
		[Min(0f)]
		private int _pickingLimit;

		private ListPool<T>.List _pickingItemCache;

		private int _pickIndex;

		private int _pickedItemCount;

		public abstract T[] Items { get; }

		public int Count
		{
			get
			{
				if (Items != null)
				{
					return Items.Length;
				}
				return 0;
			}
		}

		public T PickItem()
		{
			return _pickingOrder switch
			{
				PickingOrder.Random => PickRandom(), 
				PickingOrder.RandomWithElimination => PickRandomWithElimination(), 
				_ => PickInOrder(), 
			};
		}

		public bool TryPickItem(out T pickedItem)
		{
			if (0 < _pickingLimit && _pickingLimit <= _pickedItemCount)
			{
				Dispose();
				pickedItem = default(T);
				return false;
			}
			pickedItem = PickItem();
			_pickedItemCount++;
			return true;
		}

		public bool IsEmpty()
		{
			return ((IReadOnlyCollection<T>)(object)Items).IsNullOrEmpty();
		}

		private T PickInOrder()
		{
			T result = Items[_pickIndex++];
			if (Items.Length <= _pickIndex)
			{
				_pickIndex = 0;
			}
			return result;
		}

		private T PickRandom()
		{
			return Items.GetRandom();
		}

		private T PickRandomWithElimination()
		{
			if (_pickingItemCache == null)
			{
				_pickingItemCache = ListPool<T>.Get(Items.Length);
			}
			if (_pickingItemCache.Count == 0)
			{
				_pickingItemCache.AddRange(Items);
			}
			int randomIndex = _pickingItemCache.GetRandomIndex();
			T result = _pickingItemCache[randomIndex];
			_pickingItemCache.RemoveAt(randomIndex);
			return result;
		}

		public void Dispose()
		{
			_pickingItemCache?.Dispose();
			_pickedItemCount = 0;
			_pickIndex = 0;
		}
	}
	[Serializable]
	public class SerializeFieldPickingList<T> : PickingListBase<T>
	{
		[SerializeField]
		private T[] _items;

		public override T[] Items => _items;
	}
	[Serializable]
	public class SerializeReferencePickingList<T> : PickingListBase<T>
	{
		[SerializeReference]
		[InstantiateSerializeReference]
		private T[] _items;

		public override T[] Items => _items;
	}
}
namespace PajamaLlama.Debugging
{
	public static class ErrorBlock
	{
		private static StringBuilder _errors;

		private static bool _hasErrors;

		public static void Begin()
		{
			if (_errors == null)
			{
				_errors = new StringBuilder();
			}
			else
			{
				_errors.Clear();
			}
			_hasErrors = false;
		}

		public static void AppendError(string error)
		{
			_errors.AppendLine(error);
			_hasErrors = true;
		}

		public static void AppendErrorFormat(string formattedError, params object[] args)
		{
			AppendError(string.Format(formattedError, args));
		}

		public static void End()
		{
			if (_hasErrors)
			{
				throw new Exception(_errors.ToString());
			}
		}
	}
	public static class LogBlock
	{
		private static StringBuilder _logs;

		private static bool _hasLogs;

		public static void Begin()
		{
			if (_logs == null)
			{
				_logs = new StringBuilder();
			}
			else
			{
				_logs.Clear();
			}
			_hasLogs = false;
		}

		public static void Log(string error)
		{
			_logs.AppendLine(error);
			_hasLogs = true;
		}

		public static void LogFormat(string formattedError, params object[] args)
		{
			Log(string.Format(formattedError, args));
		}

		public static bool End(out string log)
		{
			if (_hasLogs)
			{
				log = _logs.ToString();
				return true;
			}
			log = null;
			return false;
		}
	}
}
namespace PajamaLlama.Collections.Managed
{
	public class CollectionManager : MonoBehaviour
	{
		private static CollectionManager _instance;

		private List<IManagedCollection> _collections;

		private static CollectionManager GetInstance()
		{
			if (_instance == null)
			{
				_instance = new GameObject().AddComponent<CollectionManager>();
				_instance.name = "CollectionManager";
			}
			return _instance;
		}

		private void Awake()
		{
			if (_instance == null)
			{
				_instance = this;
				_collections = new List<IManagedCollection>();
			}
			else
			{
				UnityEngine.Object.Destroy(this);
				UnityEngine.Debug.LogException(new Exception("There can be only one active CollectionManager!"));
			}
		}

		private void OnDestroy()
		{
			foreach (IManagedCollection collection in _collections)
			{
				collection.OnDestroy();
			}
			_collections.Clear();
			if (_instance == this)
			{
				_instance = null;
			}
		}

		internal static void RegisterCollection(IManagedCollection collection)
		{
			GetInstance()._collections.AddUnique(collection);
		}
	}
	internal interface IManagedCollection
	{
		internal void OnDestroy();
	}
	public class ManagedDictionary<TKey, TValue> : IManagedCollection
	{
		private Dictionary<TKey, TValue> _instance;

		void IManagedCollection.OnDestroy()
		{
			if (_instance != null)
			{
				_instance.Clear();
				_instance = null;
			}
		}

		public Dictionary<TKey, TValue> Get()
		{
			if (_instance == null)
			{
				CollectionManager.RegisterCollection(this);
				_instance = new Dictionary<TKey, TValue>();
			}
			return _instance;
		}
	}
	public class ManagedHashSet<T> : IManagedCollection
	{
		private HashSet<T> _instance;

		void IManagedCollection.OnDestroy()
		{
			if (_instance != null)
			{
				_instance.Clear();
				_instance = null;
			}
		}

		public HashSet<T> Get()
		{
			if (_instance == null)
			{
				CollectionManager.RegisterCollection(this);
				_instance = new HashSet<T>();
			}
			return _instance;
		}
	}
