		private static string GetDurationString(float duration, SurvivalGuideProperties survivalGuideProperties)
		{
			int num = Mathf.FloorToInt(duration / 60f);
			int num2 = Mathf.FloorToInt(duration % 60f);
			_stringParams[_durationMinutesParam] = num.ToString();
			_stringParams[_durationSecondsParam] = num2.ToString();
			_durationStringBuilder.Clear();
			if (num > 0)
			{
				string translation = survivalGuideProperties.MinutesString;
				LocalizationManager.ApplyLocalizationParams(ref translation, _stringParams);
				_durationStringBuilder.Append(translation);
				if (num2 > 0)
				{
					_durationStringBuilder.Append(" ");
				}
			}
			if (num2 > 0)
			{
				string translation2 = survivalGuideProperties.SecondsString;
				LocalizationManager.ApplyLocalizationParams(ref translation2, _stringParams);
				_durationStringBuilder.Append(translation2);
			}
			return _durationStringBuilder.ToString();
		}
	}
	internal class CategoryPage : Page, ICategoryPage
	{
		private Transform _transform;

		public List<IPage> SubPages { get; private set; }

		internal CategoryPage(string id, LocalizedString name)
			: base(id, name, null)
		{
			SubPages = new List<IPage>();
		}

		internal void AddEntry(Page entry)
		{
			SubPages.Add(entry);
		}

		internal void RemoveEntry(Page entry)
		{
			SubPages.Remove(entry);
		}

		internal void SortPages()
		{
			Sorting.SlowSort(SubPages);
		}

		protected override List<WidgetContainer> GenerateWidgets(SurvivalGuideProperties survivalGuideProperties)
		{
			return null;
		}

		public bool TryGetPage<T>(out T page, string pageId) where T : class, IPage
		{
			int count = SubPages.Count;
			while (0 < count--)
			{
				page = SubPages[count] as T;
				if (page != null && page.ID == pageId)
				{
					return true;
				}
			}
			page = null;
			return false;
		}

		public Transform GetTransform(Transform parent)
		{
			if (_transform == null)
			{
				_transform = UnityEngine.Object.Instantiate(SurvivalGuideManager.Properties.CategoryParentPrefab, parent).transform;
				_transform.name = "Category_" + base.ID;
			}
			return _transform;
		}
	}
	public class CategoryPageIndex : PageIndex
	{
		[FormerlySerializedAs("Accordion")]
		[SerializeField]
		private AccordionElement _accordion;

		[SerializeField]
		private ChildBehaviourCache<PageIndex> _indexPrefab;

		public AccordionElement Accordion => _accordion;

		public List<PageIndex> SubPageIndices { get; private set; } = new List<PageIndex>();

		internal override void Initialize(IPage page)
		{
			base.Initialize(page);
			ICategoryPage obj = (page as ICategoryPage) ?? throw new NotImplementedException();
			SubPageIndices.Clear();
			_indexPrefab.Reset();
			foreach (IPage subPage in obj.SubPages)
			{
				PageIndex pageIndex = _indexPrefab.Get(active: true);
				pageIndex.Initialize(subPage);
				pageIndex.Parent = this;
				SubPageIndices.Add(pageIndex);
			}
			if (_accordion.SelectableGroup.Initialization == SelectableGroup.InitializationMode.Script)
			{
				_accordion.SelectableGroup.Initialize(clearSelected: true);
			}
		}

		internal bool TryGetPageIndexSelectable(out Selectable selectable, IPage page)
		{
			for (int i = 0; i < _indexPrefab.Count; i++)
			{
				PageIndex pageIndex = _indexPrefab[i];
				if (pageIndex.Page == page)
				{
					selectable = pageIndex.Selectable;
					return true;
				}
			}
			selectable = null;
			return false;
		}

		internal bool TryGetPageIndex<T>(out T pageIndex, IPage page) where T : PageIndex
		{
			for (int i = 0; i < _indexPrefab.Count; i++)
			{
				pageIndex = _indexPrefab[i] as T;
				if (pageIndex != null && pageIndex.Page == page)
				{
					return true;
				}
			}
			pageIndex = null;
			return false;
		}

		internal void ToggleOn()
		{
			if ((bool)_accordion)
			{
				_accordion.ToggleOn(instantTransition: true);
			}
		}
	}
	internal class DrifterAttributePage : Page
	{
		public DrifterAttributes.Attribute Attribute { get; private set; }

		public DrifterAttributes Attributes { get; private set; }

		private DrifterAttributePage(DrifterAttributes.Attribute attribute, DrifterAttributes attributes)
			: base(attribute.SurvivalGuideLink, attribute.Name, null)
		{
			Attribute = attribute;
			Attributes = attributes;
		}

		internal static List<Page> Generate(DrifterAttributes drifterattributes, CategoryPage category)
		{
			List<Page> list = new List<Page>();
			foreach (DrifterAttributes.AttributeType item in from e in DrifterAttributes.ReturnAttributeTypes()
				orderby e.ToString()
				select e)
			{
				if (item != DrifterAttributes.AttributeType.None)
				{
					DrifterAttributes.Attribute attribute = drifterattributes.ReturnAttribute(item);
					if (attribute.ShowInRerollDropdown)
					{
						Page page = new DrifterAttributePage(attribute, drifterattributes);
						list.Add(page);
						category.AddEntry(page);
					}
				}
			}
			return list;
		}

		protected override List<WidgetContainer> GenerateWidgets(SurvivalGuideProperties survivalGuideProperties)
		{
			if (!survivalGuideProperties.TryReturnWidgetContainerStyle("vertical", out var style) || !survivalGuideProperties.TryReturnStyle("text-paragraph", out var widget))
			{
				UnityEngine.Debug.LogException(new NotImplementedException());
				return new List<WidgetContainer>();
			}
			string text = Attribute.Description;
			text = text + "\n\n" + Attribute.ModifierTooltip;
			text = DrifterAttributes.ReplaceModifiers(text, Attributes, Attribute.Type, 1);
			return new List<WidgetContainer>
			{
				new WidgetContainer(style, new List<Tuple<BaseWidget, BaseWidget.BaseParameters>>
				{
					new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new TextWidget.Parameters(text))
				})
			};
		}
	}
