		}
	}
	internal class ResourcePage : Page
	{
		private static List<Producer> _producers;

		public ItemProperties Properties { get; private set; }

		public ResourcePage(ItemProperties itemProperties)
			: base(itemProperties.SurvivalGuideIdentifier, itemProperties.LocalizedNameTerm, itemProperties.InventorySprite)
		{
			Properties = itemProperties;
		}

		internal static List<Page> Generate(ItemProperties[] items, BuildableProperties[] buildables, CategoryPage category)
		{
			if (_producers == null)
			{
				_producers = new List<Producer>();
			}
			else
			{
				_producers.Clear();
			}
			for (int i = 0; i < buildables.Length; i++)
			{
				if (buildables[i].Prefab.TryGetComponent<Producer>(out var component))
				{
					_producers.Add(component);
				}
			}
			List<Page> list = new List<Page>(items.Length);
			foreach (ItemProperties itemProperties in items)
			{
				if (!itemProperties.IsSuperItem)
				{
					Page page = new ResourcePage(itemProperties);
					category.AddEntry(page);
					list.Add(page);
				}
			}
			return list;
		}

		protected override List<WidgetContainer> GenerateWidgets(SurvivalGuideProperties survivalGuideProperties)
		{
			if (!survivalGuideProperties.TryReturnWidgetContainerStyle("vertical", out var _) || !survivalGuideProperties.TryReturnStyle("text-paragraph", out var _))
			{
				UnityEngine.Debug.LogException(new NotImplementedException());
				return new List<WidgetContainer>();
			}
			List<WidgetContainer> list = new List<WidgetContainer>();
			list.AddRange(ReturnResourceInfo(survivalGuideProperties));
			using ListPool<Producer>.List list2 = ListPool<Producer>.Get();
			using ListPool<Producer>.List list3 = ListPool<Producer>.Get();
			foreach (Producer producer in _producers)
			{
				if (producer.ReturnProducesItem(Properties))
				{
					list2.Add(producer);
				}
				if (producer.ReturnUsesItem(Properties))
				{
					list3.Add(producer);
				}
			}
			list.AddRange(ReturnResourceProducers(survivalGuideProperties, survivalGuideProperties.ProducedInString, list2));
			list.AddRange(ReturnResourceProducers(survivalGuideProperties, survivalGuideProperties.UsedInString, list3));
			return list;
		}

		private List<WidgetContainer> ReturnResourceInfo(SurvivalGuideProperties survivalGuideProperties)
		{
			if (!survivalGuideProperties.TryReturnWidgetContainerStyle("vertical", out var style) || !survivalGuideProperties.TryReturnStyle("labelledimagevalue-paragraph", out var widget) || !survivalGuideProperties.TryReturnStyle("padding", out var widget2))
			{
				UnityEngine.Debug.LogException(new NotImplementedException());
				return new List<WidgetContainer>();
			}
			List<Tuple<BaseWidget, BaseWidget.BaseParameters>> list = new List<Tuple<BaseWidget, BaseWidget.BaseParameters>>
			{
				new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new LabelledImageValueWidget.Parameters(survivalGuideProperties.ItemTypeString, $"<color=#{ColorUtility.ToHtmlStringRGBA(Properties.ItemType.LabelColor)}>{Properties.ItemType.Name}</color>", Properties.ItemType.Icon, 40f, null, survivalGuideProperties.ItemTypeBackgroundSprite, Properties.ItemType.Color))
			};
			if (Properties.Quality != null)
			{
				list.Add(new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new LabelledImageValueWidget.Parameters(survivalGuideProperties.FoodQualityString, $"<color=#{ColorUtility.ToHtmlStringRGBA(Properties.Quality.LabelColor)}>{Properties.Quality.Name}</color>", Properties.Quality.Icon, 40f)));
			}
			if (Properties.ConsumptionPollution > 0)
			{
				list.Add(new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new LabelledImageValueWidget.Parameters(survivalGuideProperties.FoodPollutionString, Properties.ConsumptionPollution.ToString(), survivalGuideProperties.PollutionSprite, 40f)));
			}
			if (GameManager.Settings.BuildableSettings.WeightMode == BuildableSettings.WeightModes.Items)
			{
				list.Add(new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new LabelledImageValueWidget.Parameters(survivalGuideProperties.WeightString, Properties.Weight.ToString(), survivalGuideProperties.WeightSprite, 40f)));
			}
			list.Add(new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget2, new PaddingWidget.Parameters(20f)));
			return new List<WidgetContainer>
			{
				new WidgetContainer(style, list)
			};
		}

		private static List<WidgetContainer> ReturnResourceProducers(SurvivalGuideProperties survivalGuideProperties, LocalizedString title, List<Producer> producers)
		{
			if (!survivalGuideProperties.TryReturnWidgetContainerStyle("vertical", out var style) || !survivalGuideProperties.TryReturnStyle("text-subtitle-underlined", out var widget) || !survivalGuideProperties.TryReturnStyle("labelledimage-paragraph", out var widget2))
			{
				UnityEngine.Debug.LogException(new NotImplementedException());
				return new List<WidgetContainer>();
			}
			if (producers.Count <= 0)
			{
				return new List<WidgetContainer>();
			}
			List<Tuple<BaseWidget, BaseWidget.BaseParameters>> list = new List<Tuple<BaseWidget, BaseWidget.BaseParameters>>
			{
				new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget, new TextWidget.Parameters(title))
			};
			Vector2 dimensions = new Vector2(40f, 40f);
			foreach (Producer producer in producers)
			{
				BuildableProperties properties = producer.GetComponent<Buildable>().Properties;
				string text = "<style=\"SGLink\"><link=" + properties.SurvivalGuideIdentifier + ">" + properties.Name + "</link></style>";
				list.Add(new Tuple<BaseWidget, BaseWidget.BaseParameters>(widget2, new LabelledImageWidget.Parameters(text, properties.IconSprite, dimensions, properties.SurvivalGuideIdentifier)));
			}
			return new List<WidgetContainer>
			{
				new WidgetContainer(style, list)
			};
		}
	}
	public class SurvivalGuide : Panel, ISelectableGroupFirstSelectedProvider, ILocalizationGenderProvider, ILocalizationParamsManager
	{
		[SerializeField]
		[Tooltip("The inputs for which the page indices should be selected when the panel is opened.")]
		private InputFlags _selectableInputs = InputFlags.Joystick;

		[SerializeField]
		private Transform _pagesParent;

		[SerializeField]
		private GameObject _backgroundPatterns;

		[SerializeField]
		private Transform _indexParent;

		[SerializeField]
		private Button _previousButton;

		[SerializeField]
		private Accordion _indexAccordion;

		[Space]
		[SerializeField]
		private ScrollRect _indexScrollRect;

		[SerializeField]
		private ScrollRect _pageScrollRect;

		[Space]
		[SerializeField]
		private GameObject _titleGameObject;

		[SerializeField]
		private TextMeshProUGUI _titleText;

		[SerializeField]
		private Image _titleImage;

		private SurvivalGuideProperties _properties;

		private Page _selectedPage;

		private List<CategoryPage> _survivalGuide;

		private Dictionary<string, Page> _pages;

		private Stack<Page> _selectionStack;

		private List<CategoryPageIndex> _index;

		private Accordion.Transition _accordionAnimation;

		private static HashSet<string> _pageIds = new HashSet<string>();

		Agent.EGender ILocalizationGenderProvider.LocalizationGender => Agent.EGender.Male;

		private void OnEnable()
		{
			LocalizationManager.ParamManagers.Add(this);
			_indexScrollRect.normalizedPosition = new Vector2(0f, 1f);
			_pageScrollRect.normalizedPosition = new Vector2(0f, 1f);
			if (TryGetSelectedPageIndexSelectable(out var category, out var _))
			{
				FinalUpdate.RegisterOneShot(category.ToggleOn);
			}
			if (_backgroundPatterns != null)
			{
				_backgroundPatterns.SetActive(value: true);
			}
		}

		private void OnDisable()
		{
			if (_backgroundPatterns != null)
			{
				_backgroundPatterns.SetActive(value: false);
			}
			LocalizationManager.ParamManagers.Remove(this);
		}

		private void OnDestroy()
		{
			GameEventDispatcher.RemoveListener(GameEventType.OpenSurvivalGuidePage, OnPageOpenEvent);
		}

		public void Initialize(SurvivalGuideProperties properties)
		{
			LocalizationManager.ParamManagers.Add(this);
			_titleGameObject.SetActive(value: false);
			ClearPageIds();
			_properties = properties;
			_survivalGuide = properties.CreateSurvivalGuide();
			_index = GenerateIndex(_survivalGuide, _indexParent);
			_pages = new Dictionary<string, Page>();
			_selectionStack = new Stack<Page>();
			_previousButton.interactable = false;
			_accordionAnimation = _indexAccordion.transition;
			GameEventDispatcher.AddListener(GameEventType.OpenSurvivalGuidePage, OnPageOpenEvent);
			LocalizationManager.ParamManagers.Remove(this);
		}

		private List<CategoryPageIndex> GenerateIndex(List<CategoryPage> survivalGuide, Transform parent)
		{
			List<CategoryPageIndex> list = new List<CategoryPageIndex>();
			foreach (CategoryPage item in survivalGuide)
			{
				CategoryPageIndex categoryPageIndex = UnityEngine.Object.Instantiate(_properties.CategoryIndexPrefab, parent);
				list.Add(categoryPageIndex);
				categoryPageIndex.Initialize(item);
			}
			return list;
		}

		private void OnPageOpenEvent(GameEvent gameEvent)
		{
			if (gameEvent is StringEvent stringEvent)
			{
				Select(stringEvent.Data);
			}
			if (gameEvent is PageEvent pageEvent)
			{
				Select(pageEvent.Page.ID);
			}
			if (!base.gameObject.activeInHierarchy)
			{
				GameManager.UIManager.DisplayPanel(PanelID.SurvivalGuide);
			}
		}

		private void Select(string pageID, bool addToStack = true)
		{
			if (!TryGetPage(out var page, pageID))
			{
				UnityEngine.Debug.LogException(new Exception("There is no page with that ID " + pageID + " present."));
				return;
			}
			if (_selectedPage != null)
			{
				_selectedPage.SetActive(active: false);
				if (addToStack)
				{
					_selectionStack.Push(_selectedPage);
				}
			}
			base.gameObject.SetActive(value: true);
			_selectedPage = page;
			_selectedPage.SetActive(active: true);
			_titleGameObject.SetActive(value: true);
			_titleText.text = page.Name;
			_titleImage.gameObject.SetActive(page.Icon != null);
			_titleImage.sprite = page.Icon;
			_previousButton.interactable = _selectionStack.Count > 0;
			new StringEvent(GameEventType.SurvivalGuidePageOpened, _selectedPage.ID).Dispatch();
		}

		public void PreviousPage()
		{
			if (_selectionStack.TryPop(out var result))
			{
				Select(result.ID, addToStack: false);
			}
		}

		public void StopSearching(string text)
		{
			if (text.Length <= 0)
			{
				StopSearching();
			}
		}

		private void StopSearching()
		{
			foreach (CategoryPageIndex item in _index)
			{
				item.gameObject.SetActive(value: true);
				foreach (PageIndex subPageIndex in item.SubPageIndices)
				{
					subPageIndex.gameObject.SetActive(value: true);
				}
				item.Accordion.UpdateGroup();
				item.Accordion.isOn = false;
			}
			_indexAccordion.transition = _accordionAnimation;
		}

		public void Search(string text)
		{
			if (text.Length <= 0)
			{
				StopSearching(text);
				return;
			}
			_indexAccordion.transition = Accordion.Transition.Instant;
			foreach (CategoryPageIndex item in _index)
			{
				int num = 0;
				foreach (PageIndex subPageIndex in item.SubPageIndices)
				{
					bool flag = Regex.IsMatch(subPageIndex.Page.Name, text, RegexOptions.IgnoreCase);
					if (flag)
					{
						num++;
					}
					subPageIndex.gameObject.SetActive(flag);
				}
				if (item.Accordion.group != null)
				{
					item.Accordion.group = null;
				}
				bool flag2 = num > 0;
				item.gameObject.SetActive(flag2);
				item.Accordion.isOn = flag2;
				item.Accordion.OnValueChanged(flag2);
			}
		}

		private bool TryGetPage(out Page page, string pageId)
		{
			if (_pages.TryGetValue(pageId, out page))
			{
				return true;
			}
			if (TryGetPageAndParent(out page, out var parent, pageId))
			{
				page.GenerateWidgets(UnityEngine.Object.Instantiate(_properties.PageParentPrefab, parent));
				_pages.Add(pageId, page);
				return true;
			}
			page = null;
			return false;
		}

		private bool TryGetPageAndParent(out Page page, out Transform parent, string pageId)
		{
			foreach (CategoryPage item in _survivalGuide)
			{
				if (item.TryGetPage<Page>(out page, pageId))
				{
					parent = item.GetTransform(_pagesParent);
					return true;
				}
			}
			page = null;
			parent = null;
			return false;
		}

		internal static string GetUniquePageId(string pageId, string pageName)
		{
			int num = 0;
			string text = pageId;
			while (!_pageIds.Add(text))
			{
				UnityEngine.Debug.LogErrorFormat("ID '{0}' for page '{1}' is already in use for another page!", text, pageName);
				text = $"{pageId}_{++num}";
			}
			return text;
		}

		internal static void ClearPageIds()
		{
			_pageIds.Clear();
		}

		public bool TryGetFirstSelected(out Selectable selectable)
		{
			if (TryGetSelectedPageIndexSelectable(out var _, out selectable))
			{
				return FlotsamInputManager.HasActiveInput(_selectableInputs);
			}
			selectable = null;
			return false;
		}

		private bool TryGetSelectedPageIndexSelectable(out CategoryPageIndex category, out Selectable selectable)
		{
			if (_selectedPage != null)
			{
				int count = _index.Count;
				while (0 < count--)
				{
					category = _index[count];
					if (category.TryGetPageIndexSelectable(out selectable, _selectedPage))
					{
						return true;
					}
				}
			}
			category = null;
			selectable = null;
			return false;
		}
	}
	[Serializable]
	internal class SurvivalGuideCategories
	{
		[Serializable]
		private struct Category
		{
			public string id;

			public string title;

			public Page[] pages;
		}

		[Serializable]
		private struct Page
		{
			public string id;

			public string name;

			public string icon;

			public string path;
		}

		[SerializeField]
		private Category[] categories;

		internal void CreateCategoryPages(List<CategoryPage> categoryPages)
		{
			Category[] array = categories;
			for (int i = 0; i < array.Length; i++)
			{
				Category category = array[i];
				CategoryPage categoryPage = new CategoryPage(category.id, category.title);
				categoryPages.Add(categoryPage);
				if (((IReadOnlyCollection<Page>)(object)category.pages).IsNullOrEmpty())
				{
					continue;
				}
				Page[] pages = category.pages;
				for (int j = 0; j < pages.Length; j++)
				{
					Page page = pages[j];
					Sprite icon = null;
					if (!string.IsNullOrEmpty(page.icon))
					{
						Resources.Load<Sprite>(page.icon);
					}
					categoryPage.AddEntry(new JSONPage(page.id, page.name, icon, page.path));
				}
			}
		}
	}
