namespace PajamaLlama.Fltsm.UI
{
	public abstract class GameSetupPage : MonoBehaviour
	{
		public bool IsCompleted { get; protected set; }

		public abstract bool Activate();

		public abstract GameSetup Apply(GameSetup gameSetup);

		public virtual void Deactivate()
		{
			base.gameObject.SetActive(value: false);
		}
	}
	public class GameSetupPanel : MonoBehaviour
	{
		[SerializeField]
		private GameSetupPage[] _pages;

		[SerializeField]
		private Button _buttonContinue;

		private GameSetup _gameSetup;

		private int _activePanelIndex;

		private GameSetupPage _activePanel;

		public TileProperties SelectedTileProperties { get; set; }

		public bool IsTutorial { get; set; }

		private void OnEnable()
		{
			ActivateOptionPanel(0);
			_buttonContinue.onClick.AddListener(OnContinue);
		}

		private void Update()
		{
			_buttonContinue.interactable = _activePanel.IsCompleted;
		}

		private void OnDisable()
		{
			if ((bool)_activePanel)
			{
				_activePanel.Deactivate();
				_activePanel = null;
			}
			_buttonContinue.onClick.RemoveListener(OnContinue);
		}

		public bool Activate(GameSetup gameSetup)
		{
			if (((IReadOnlyCollection<GameSetupPage>)(object)_pages).IsNullOrEmpty())
			{
				return false;
			}
			_gameSetup = gameSetup;
			base.gameObject.SetActive(value: true);
			return true;
		}

		private void ActivateOptionPanel(int index)
		{
			if (index < _pages.Length)
			{
				if ((bool)_activePanel)
				{
					_activePanel.Deactivate();
				}
				_activePanelIndex = index;
				_activePanel = _pages[index];
				if (_activePanel.Activate())
				{
					return;
				}
			}
			OnContinue();
		}

		private void OnContinue()
		{
			int num = _activePanelIndex + 1;
			if ((bool)_activePanel)
			{
				_gameSetup = _activePanel.Apply(_gameSetup);
			}
			if (num < _pages.Length)
			{
				ActivateOptionPanel(num);
			}
			else
			{
				Session.Profile.StartRun(_gameSetup);
			}
		}
	}
	public class ScenarioSelectionPage : GameSetupPage
	{
		[SerializeField]
		private ScenarioToggle[] _scenarioToggles;

		public override bool Activate()
		{
			return base.enabled;
		}

		public override GameSetup Apply(GameSetup gameSetup)
		{
			ScenarioToggle[] scenarioToggles = _scenarioToggles;
			foreach (ScenarioToggle scenarioToggle in scenarioToggles)
			{
				if (scenarioToggle.isOn)
				{
					gameSetup.TileProperties = scenarioToggle.TileProperties;
					gameSetup.IsTutorial = scenarioToggle.IsTutorial;
					break;
				}
			}
			return gameSetup;
		}
	}
