		protected override void Awake()
		{
			base.Awake();
			base.AddOptions(_offLabel, _onLabel);
		}

		public void SetIsOnWithoutNotify(bool isOn)
		{
			if (isOn)
			{
				SetIndexWithoutNotify(1);
			}
			else
			{
				SetIndexWithoutNotify(0);
