namespace PajamaLlama.UI.Formatting
{
	[Serializable]
	public struct ColorRange
	{
		private enum RangeType
		{
			Range = 0,
			SmallerThen = 1,
			SmallerThenOrEqual = 2,
			LargerThen = 3,
			LargerThenOrEqual = 4,
			Any = 16
		}

		[SerializeField]
		private RangeType _rangeType;

		public int from;

		[ConditionalEnumHide("_rangeType", 0, false)]
		public int to;

		public Color Color;

		public bool IsInRange(int value)
		{
			switch (_rangeType)
			{
			case RangeType.Range:
				if (from <= value)
				{
					return value <= to;
				}
				return false;
			case RangeType.SmallerThen:
				return value < from;
			case RangeType.SmallerThenOrEqual:
				return value <= from;
			case RangeType.LargerThen:
				return from < value;
			case RangeType.LargerThenOrEqual:
				return from <= value;
			case RangeType.Any:
				return true;
			default:
				throw new NotImplementedException();
			}
		}
	}
	[Serializable]
	public struct IntFormatter
	{
		[SerializeField]
		private SignStyle _signStyle;

		[SerializeField]
		private ColorRange[] _colorRanges;

		public void Format(TextMeshProUGUI tmpText, int value, bool setActive = true)
		{
			switch (_signStyle)
			{
			case SignStyle.NegativeOnly:
				tmpText.text = value.ToString();
				break;
			case SignStyle.NegativeAndPositive:
				tmpText.text = ((value < 0) ? value.ToString() : $"+{value}");
				break;
			case SignStyle.NegativeAndPositiveZeroExcluded:
				tmpText.text = ((value <= 0) ? value.ToString() : $"+{value}");
				break;
			case SignStyle.None:
				tmpText.text = Mathf.Abs(value).ToString();
				break;
			}
			if (setActive)
			{
				tmpText.gameObject.SetActive(value: true);
			}
			if (((IReadOnlyCollection<ColorRange>)(object)_colorRanges).IsNullOrEmpty())
			{
				return;
			}
			ColorRange[] colorRanges = _colorRanges;
			for (int i = 0; i < colorRanges.Length; i++)
			{
				ColorRange colorRange = colorRanges[i];
				if (colorRange.IsInRange(value))
				{
					tmpText.color = colorRange.Color;
				}
			}
		}

		public void Format(TextMeshProUGUI tmpText, float value, bool setActive = true)
		{
			Format(tmpText, Mathf.RoundToInt(value), setActive);
		}
	}
	public enum SignStyle
	{
		NegativeOnly,
		NegativeAndPositive,
		NegativeAndPositiveZeroExcluded,
		None
	}
}
namespace PajamaLlama.I2Language
{
	public interface ILocalizationParameter
	{
		string GetParameterValue(string parameter);
	}
	[Serializable]
	public class LocalizationParameters
	{
		[SerializeReference]
		[SubclassSelector]
		private ILocalizationParameter[] _localizationParameters;

		public string GetParameterValue(string parameter)
		{
			if (((IReadOnlyCollection<ILocalizationParameter>)(object)_localizationParameters).IsNullOrEmpty())
			{
				return parameter;
			}
			string empty = string.Empty;
			ILocalizationParameter[] localizationParameters = _localizationParameters;
			foreach (ILocalizationParameter localizationParameter in localizationParameters)
			{
				if (localizationParameter != null)
				{
					empty = localizationParameter.GetParameterValue(parameter);
					if (empty != null && empty != parameter)
					{
						return empty;
					}
				}
			}
			return parameter;
		}
	}
