namespace PajamaLlama.External.EasyFeedback
{
	public class EasyFeedbackLogCollector : FormElement
	{
		private StringBuilder _log;

		private string _lastLogString;

		private string _lastStackTrace;

		private LogType _lastLogType;

		private int _lastLogCount;

		public override void Awake()
		{
			base.Awake();
			switch (Application.platform)
			{
			case RuntimePlatform.OSXEditor:
			case RuntimePlatform.OSXPlayer:
			case RuntimePlatform.WindowsPlayer:
			case RuntimePlatform.WindowsEditor:
			case RuntimePlatform.LinuxPlayer:
			case RuntimePlatform.LinuxEditor:
				_log = new StringBuilder();
				Application.logMessageReceived += HandleLog;
				break;
			}
		}

		protected override void FormClosed()
		{
		}

		protected override void FormOpened()
		{
		}

		protected override void FormSubmitted()
		{
			if (_lastLogString != null)
			{
				AppendLog(_lastLogString, _lastStackTrace, _lastLogType, _lastLogCount);
			}
			byte[] bytes = Encoding.ASCII.GetBytes(_log.ToString());
			Form.CurrentReport.AttachFile("log.txt", bytes);
		}

		private void HandleLog(string logString, string stackTrace, LogType logType)
		{
			if (logString != _lastLogString || stackTrace != _lastStackTrace || _lastLogType != logType)
			{
				AppendLog(_lastLogString, _lastStackTrace, _lastLogType, _lastLogCount);
				_lastLogString = logString;
				_lastStackTrace = stackTrace;
				_lastLogType = logType;
				_lastLogCount = 1;
			}
			else
			{
				_lastLogCount++;
			}
		}

		private void AppendLog(string logString, string stackTrace, LogType logType, int count)
		{
			if (logType == LogType.Exception)
			{
				_log.AppendLine($"({count}) {logString}");
			}
			else
			{
				_log.Append($"{logType.ToString()} ({count}): {logString}");
			}
			_log.AppendLine(stackTrace);
		}
	}
}
namespace PajamaLlama.Flotsam
{
	public class FlotsamSaveTask : SaveTaskBase
	{
		private static FlotsamSaveTask _instance;

		private SaveInfoMetaData _cachedMetaData;

		public WorldPersistentData WorldPersistentData { get; private set; }

		public SaveMetaInfo SaveMetaInfo { get; private set; }

		private FlotsamSaveTask(PlayerProfile player)
			: base(player)
		{
		}

		public static bool Queue(PlayerProfile player, SaveInfo saveInfo)
		{
			if (_instance == null)
			{
				_instance = new FlotsamSaveTask(player);
			}
			return _instance.Queue(saveInfo);
		}

		protected override void OnQueued()
		{
			_cachedMetaData.Copy(base.SaveInfo);
			if (GameManager.PersistenceManager.TryGetWorldPersistentData(out var worldPersistentData))
			{
				WorldPersistentData = worldPersistentData;
			}
		}

		protected override void OnCompleted()
		{
			if (!base.Success)
			{
				base.SaveInfo.SetMetaData(_cachedMetaData);
			}
		}

		protected override byte[] GetData()
		{
			lock (WorldPersistentData)
			{
				byte[] array = WorldPersistentData.Serialize();
				if (base.SaveInfo.ObjectType == SaveObjectType.SaveMetaInfo)
				{
					return PersistenceLifeCycle.Serialize(new SaveMetaInfo(base.SaveInfo, array));
				}
				return array;
			}
		}
	}
	public abstract class SaveTaskBase : ThreadPoolManager.ITask
	{
		private static bool _queued;

		private static float _timeStamp;

		private PlayerProfile _player;

		private Exception _exception;

		public SaveInfo SaveInfo { get; protected set; }

		public bool Completed { get; private set; }

		public bool Success { get; private set; }

		public Exception Exception => _exception;

		protected SaveTaskBase(PlayerProfile player)
		{
			_player = player;
			_queued = false;
		}

		public bool Queue(SaveInfo saveInfo)
		{
			if (_queued || Time.realtimeSinceStartup - _timeStamp < Session.Platform.MinimumSaveInterval)
			{
				return false;
			}
			if (ThreadPoolManager.QueueTask(this))
			{
				_queued = true;
				SaveInfo = saveInfo;
				SaveInfo.Timestamp();
				Completed = false;
				OnQueued();
				return true;
			}
			return false;
		}

		public void ThreadPoolWaitCallback(object state)
		{
			try
			{
				byte[] data = GetData();
				SaveInfo.SetSize(data.Length);
				_player.SaveFile(SaveInfo.Path, data, OnSaveFileResult);
			}
			catch (Exception exception)
			{
				_exception = exception;
				Success = false;
				Completed = true;
			}
		}

		public void UnityCompletedCallback()
		{
			if (Exception != null)
			{
				UnityEngine.Debug.LogException(Exception);
			}
			_queued = false;
			_timeStamp = Time.realtimeSinceStartup;
			OnCompleted();
			AsyncSaveEvent.DispatchCompleted(this);
		}

		protected abstract void OnQueued();

		protected abstract void OnCompleted();

		private void OnSaveFileResult(StorageActionResult result)
		{
			Success = result.Succes;
			Completed = true;
		}

		protected abstract byte[] GetData();
	}
