namespace PajamaLlama.Flotsam.Procedural
{
	public interface IRegionPass
	{
		int SpawnCount { get; }

		void Initialize(TileGenerator tileGenerator);

		bool InitializeRegion(TileGeneratorRegion region);

		void Run(RegionPassGroup regionPasses, TileGeneratorRegion region);

		void Uninitialize();
	}
	public class RegionPassCells : IDisposable
	{
		[Serializable]
		public class Settings
		{
			[SerializeField]
			[Range(0f, 1f)]
			[Tooltip("The minimum amount of overlap a cell requires to allow spawning.")]
			public float _minimumCellOverlap = 0.5f;

			[SerializeField]
			[Tooltip("Should nodes that are in the region when the cell is initialized be counted?")]
			public bool _countExistingNodes;

			[SerializeField]
			[Tooltip("The curve with spawn chances base on the amount of nodes in the cell.")]
			public AnimationCurve _spawnChangeCurve;

			[SerializeField]
			[Tooltip("Should the node count be corrected base on the amount of overlap with the region?")]
			public bool _applyOverlapCorrection = true;

			[Header("Spawning")]
			[SerializeField]
			[Tooltip("Padding used when generating a random position in a cell.")]
			public float _padding;

			[SerializeField]
			[Min(0f)]
			[Tooltip("The minimum distance spawned nodes should be apart from eachother")]
			public float _mininumNodeDistance = 100f;

			public float MinimumCellOverlap => _minimumCellOverlap;

			public bool CountExistingNodes => _countExistingNodes;

			public AnimationCurve SpawnChangeCurve => _spawnChangeCurve;

			public bool ApplyOverlapCorrection => _applyOverlapCorrection;

			public float Padding => _padding;

			public float MininumNodeDistance => _mininumNodeDistance;

			public float EvaluateSpawnChance(float nodeCount)
			{
				if (SpawnChangeCurve == null)
				{
					return 1f;
				}
				return SpawnChangeCurve.Evaluate(nodeCount);
			}
		}

		private class Cell : IDisposable
		{
			private static List<Cell> _pool;

			private float _overlap;

			private bool _applyOverlapCorrection;

			public int Row { get; private set; }

			public int Column { get; private set; }

			public Rect Rect { get; private set; }

			public float Overlap { get; private set; }

			public int NodeCount { get; private set; }

			public float Chance { get; private set; }

			public bool IsBorderCell { get; private set; }

			private Cell()
			{
			}

			public static bool TryGet(out Cell cell, IRegion region, Rect rect, Settings settings)
			{
				float num = region.ReturnOverlap(rect.GetTempPolygon()) / (rect.width * rect.height);
				cell = null;
				if (num <= 0f || num < settings.MinimumCellOverlap)
				{
					return false;
				}
				if (_pool.IsNullOrEmpty())
				{
					cell = new Cell();
				}
				else
				{
					int index = _pool.Count - 1;
					cell = _pool[index];
					_pool.RemoveAt(index);
				}
				cell.Rect = rect;
				cell.NodeCount = 0;
				cell.Overlap = num;
				cell.ApplySpawnChanceCurve(settings.SpawnChangeCurve);
				return true;
			}

			private static void ReturnToPool(Cell cell)
			{
				if (_pool == null)
				{
					_pool = new List<Cell>(32);
				}
				_pool.Add(cell);
			}

			public void Dispose()
			{
				ReturnToPool(this);
			}

			public void SetRowAndColumn(int row, int column)
			{
				Row = row;
				Column = column;
			}

			public void AddNode(AnimationCurve spawnChanceCurve)
			{
				NodeCount++;
				ApplySpawnChanceCurve(spawnChanceCurve);
			}

			public void ApplySpawnChanceCurve(AnimationCurve spawnChanceCurve)
			{
				if (spawnChanceCurve != null)
				{
					float num = NodeCount;
					if (_applyOverlapCorrection)
					{
						num /= _overlap;
					}
					Chance = spawnChanceCurve.Evaluate(num);
				}
			}
		}

		public delegate void GenerateNode(Vector2 position);

		private static Queue<RegionPassCells> _pool = new Queue<RegionPassCells>();

		private IRegion _region;

		private List<Cell> _cells = new List<Cell>(128);

		private List<Cell> _spawnChanceCells = new List<Cell>(128);

		private AnimationCurve _spawnChanceCurve;

		private float _cellPadding;

		private float _minimumNodeDistance;

		public static RegionPassCells GetFromPool(Settings settings, IRegion region, Vector2 cellSize)
		{
			if (!_pool.TryDequeue(out var result))
			{
				result = new RegionPassCells();
			}
			result.Initialize(settings, region, cellSize);
			return result;
		}

		public static void ReturnToPool(RegionPassCells instance)
		{
			_pool.Enqueue(instance);
		}

		private void Initialize(Settings settings, IRegion region, Vector2 cellSize)
		{
			_region = region;
			_cellPadding = settings.Padding;
			_minimumNodeDistance = settings.MininumNodeDistance;
			int num = Mathf.RoundToInt(region.Bounds.width / cellSize.x);
			int num2 = Mathf.RoundToInt(region.Bounds.height / cellSize.y);
			cellSize.x = region.Bounds.width / (float)num;
			cellSize.y = region.Bounds.height / (float)num2;
			Rect rect = new Rect(region.Bounds.min, cellSize);
			for (int i = 0; i < num2; i++)
			{
				rect.x = region.Bounds.xMin;
				for (int j = 0; j < num; j++)
				{
					if (Cell.TryGet(out var cell, region, rect, settings))
					{
						cell.SetRowAndColumn(i, j);
						_cells.Add(cell);
					}
					rect.x += cellSize.x;
				}
				rect.y += cellSize.y;
			}
			SetSpawnChanceCurve(settings.SpawnChangeCurve);
		}

		public void CountExistingNodes(TileGeneratorRegion region)
		{
			foreach (Cell cell in _cells)
			{
				foreach (TileGeneratorNode node in region.Nodes)
				{
					if (cell.Rect.Contains(node.Position))
					{
						cell.AddNode(null);
					}
				}
			}
			SetSpawnChanceCurve(_spawnChanceCurve);
		}

		public void SetSpawnChanceCurve(AnimationCurve spawnChanceCurve)
		{
			_spawnChanceCurve = spawnChanceCurve;
			_spawnChanceCells.Clear();
			foreach (Cell cell in _cells)
			{
				cell.ApplySpawnChanceCurve(_spawnChanceCurve);
				if (0f < cell.Chance)
				{
					_spawnChanceCells.Add(cell);
				}
			}
		}

		public int DistributeNodes(TileGenerator tileGenerator, int count, GenerateNode generateNode)
		{
			int num = _spawnChanceCells.Count;
			int num2 = 0;
			float num3 = 0f;
			for (int i = 0; i < num; i++)
			{
				num3 += _spawnChanceCells[i].Chance;
			}
			while (0 < count && 0 < num)
			{
				float num4 = UnityEngine.Random.Range(0f, num3);
				float num5 = 0f;
				float num6 = 0f;
				for (int j = 0; j < num; j++)
				{
					Cell cell = _spawnChanceCells[j];
					num6 += cell.Chance;
					if (num4 < num5 || num6 < num4)
					{
						continue;
					}
					if (TryGenerateNode(tileGenerator, cell, generateNode))
					{
						num2++;
						count--;
						num3 -= cell.Chance;
						cell.AddNode(_spawnChanceCurve);
						if (0f < cell.Chance)
						{
							num3 += cell.Chance;
							break;
						}
					}
					_spawnChanceCells.RemoveAt(j);
					num--;
					break;
				}
			}
			return num2;
		}

		private bool TryGenerateNode(TileGenerator tileGenerator, Cell cell, GenerateNode generateNode, int sampleLimit = 10)
		{
			while (0 < sampleLimit)
			{
				Vector2 position = cell.Rect.RandomPosition(_cellPadding);
				if (_region.ReturnContainsPosition(position) && tileGenerator.ReturnIsValidPosition(position, _minimumNodeDistance))
				{
					generateNode(position);
					return true;
				}
				sampleLimit--;
			}
			return false;
		}

		public void Dispose()
		{
			foreach (Cell cell in _cells)
			{
				cell.Dispose();
			}
			_cells.Clear();
			_spawnChanceCells.Clear();
			ReturnToPool(this);
		}
	}
	[CreateAssetMenu(fileName = "Region Pass Group", menuName = "Flotsam/Procedural Generation/Region Pass Group", order = 3)]
	public class RegionPassGroup : TileGeneratorPass
	{
		public enum CellSizeMethod
		{
			Manual,
			LongestSideCount,
			ShortestSideCount
		}

		[Header("Region Pass")]
		[SerializeField]
		private WorldRegionType[] _regions;

		[SerializeReference]
		[SubclassSelector]
		private IRegionPass[] _passes;

		[SerializeField]
		private RegionPassCells.Settings _cellSettings;

		[SerializeField]
		private CellSizeMethod _cellSizeMethod;

		[SerializeField]
		[ConditionalEnumHide("_cellSizeMethod", 0, true)]
		private Vector2 _cellSize;

		[SerializeField]
		[ConditionalEnumHide("_cellSizeMethod", 1, 2, true)]
		private int _cellCount;

		public TileGenerator Generator { get; private set; }

		public RegionPassCells Cells { get; private set; }

		public override IEnumerator Run(TileGenerator generator, IRegion dataRegion)
		{
			bool acceptsAnyRegion = _regions.Contains(WorldRegionType.Any);
			Initialize(generator);
			if (dataRegion != null)
			{
				if (!acceptsAnyRegion && !_regions.Contains(dataRegion.Type))
				{
					yield break;
				}
				foreach (TileGeneratorRegion value in generator.Regions.Values)
				{
					if (value.IsRegion(dataRegion))
					{
						Run(generator, value);
						yield break;
					}
				}
			}
			else
			{
				TileGeneratorRegion startRegion = null;
				if (generator.IsStartingTile)
				{
					foreach (TileGeneratorRegion value2 in generator.Regions.Values)
					{
						if ((acceptsAnyRegion || _regions.Contains(value2.Type)) && value2.ReturnContainsPosition(generator.StartPosition))
						{
							startRegion = value2;
							Run(generator, value2);
						}
					}
				}
				foreach (TileGeneratorRegion value3 in generator.Regions.Values)
				{
					if (value3 != startRegion)
					{
						if (acceptsAnyRegion || _regions.Contains(value3.Type))
						{
							Run(generator, value3);
						}
						yield return null;
					}
				}
			}
			Uninitialize();
		}

		private void Run(TileGenerator generator, TileGeneratorRegion region)
		{
			int num = 0;
			IRegionPass[] passes = _passes;
			foreach (IRegionPass regionPass in passes)
			{
				regionPass.InitializeRegion(region);
				num += regionPass.SpawnCount;
			}
			Generator = generator;
			Cells = RegionPassCells.GetFromPool(_cellSettings, region, GetCellSize(region));
			passes = _passes;
			for (int i = 0; i < passes.Length; i++)
			{
				passes[i].Run(this, region);
			}
			Cells.Dispose();
			Cells = null;
		}

		private void Initialize(TileGenerator tileGenerator)
		{
			IRegionPass[] passes = _passes;
			for (int i = 0; i < passes.Length; i++)
			{
				passes[i].Initialize(tileGenerator);
			}
		}

		private void Uninitialize()
		{
			IRegionPass[] passes = _passes;
			for (int i = 0; i < passes.Length; i++)
			{
				passes[i].Uninitialize();
			}
		}

		private Vector2 GetCellSize(IRegion region)
		{
			switch (_cellSizeMethod)
			{
			case CellSizeMethod.LongestSideCount:
			{
				float num = ((!(region.Bounds.width < region.Bounds.height)) ? (region.Bounds.width / (float)_cellCount) : (region.Bounds.height / (float)_cellCount));
				return new Vector2(num, num);
			}
			case CellSizeMethod.ShortestSideCount:
			{
				float num = ((!(region.Bounds.width < region.Bounds.height)) ? (region.Bounds.height / (float)_cellCount) : (region.Bounds.width / (float)_cellCount));
				return new Vector2(num, num);
			}
			default:
				return _cellSize;
			}
		}
	}
	[Serializable]
	public class ShallowStartRegionPass : IRegionPass
	{
		[SerializeField]
		private WorldRegionType[] _supportedRegions = new WorldRegionType[1] { WorldRegionType.Any };

		[SerializeField]
		private RangedFloat _spawnDistanceRange = new RangedFloat(250f, 350f);

		[SerializeField]
		private Vector2 _spawnDirection = Vector2.right;

		[SerializeField]
		private float _spawnDirectionDeviationMaximum = 30f;

		[SerializeField]
		[Min(0f)]
		private float _minimumNodeDistance;

		[Tooltip("The branch chance for a given level of the tree, the last value applies to all levels following that.")]
		[SerializeField]
		[Range(0f, 100f)]
		private float[] _branchChances = new float[2] { 100f, 33f };

		[SerializeField]
		private int _maxBranchCount = 3;

		[SerializeField]
		private PointOfInterestProperties[] _firstPointsOfInterest;

		[SerializeField]
		private PointOfInterestProperties[] _randomizedPointsOfInterest;

		[NonSerialized]
		private TileGenerator _tileGenerator;

		[NonSerialized]
		private ListPool<PointOfInterestProperties>.List _poisToDistribute;

		public int SpawnCount => 0;

		public void Initialize(TileGenerator tileGenerator)
		{
			_tileGenerator = tileGenerator;
			_poisToDistribute = ListPool<PointOfInterestProperties>.Get(_firstPointsOfInterest);
		}

		public bool InitializeRegion(TileGeneratorRegion region)
		{
			return true;
		}

		public void Run(RegionPassGroup regionPasses, TileGeneratorRegion region)
		{
			if (!_tileGenerator.IsStartingTile || !SupportsRegion(region) || !region.ReturnContainsPosition(_tileGenerator.StartPosition))
			{
				return;
			}
			using ListPool<TileGeneratorNode>.List list = ListPool<TileGeneratorNode>.Get();
			region.PopulateNeighorScoutingLandmarkNodes(list);
			foreach (TileGeneratorNode item in list)
			{
				GeneratePath(region, _tileGenerator.StartPosition, item.Position);
			}
		}

		public void Uninitialize()
		{
		}

		private void GeneratePath(TileGeneratorRegion region, Vector2 position, Vector2 targetPosition)
		{
			int num = 0;
			using ListPool<Vector2>.List list = ListPool<Vector2>.Get(16);
			list.Add(position);
			while (0 < list.Count)
			{
				int num2 = list.Count;
				int num3 = 0;
				float valueClamped = _branchChances.GetValueClamped(num);
				int num4 = num2;
				while (0 < num4-- && num3 < _maxBranchCount)
				{
					int index = UnityEngine.Random.Range(0, num2 - 1);
					position = list[index];
					if (TryAddNode(out var nodePosition, region, position))
					{
						list.Add(nodePosition);
						list.RemoveAt(index);
						num2--;
						num3++;
						if (num3 < _maxBranchCount && (float)UnityEngine.Random.Range(0, 100) <= valueClamped && TryAddNode(out nodePosition, region, position))
						{
							list.Add(nodePosition);
							num3++;
						}
					}
				}
				list.RemoveRange(0, num2);
				num++;
			}
		}

		private bool TryAddNode(out Vector2 nodePosition, TileGeneratorRegion region, Vector2 position, int itterations = 5)
		{
			for (int i = 0; i < itterations; i++)
			{
				Vector2 vector = Quaternion.Euler(0f, 0f, UnityEngine.Random.Range(0f - _spawnDirectionDeviationMaximum, _spawnDirectionDeviationMaximum)) * _spawnDirection;
				vector *= _spawnDistanceRange.ReturnRandom();
				nodePosition = position + vector;
				if (region.ReturnIsValidPosition(nodePosition, _minimumNodeDistance))
				{
					TileGeneratorNode tileGeneratorNode = new TileGeneratorNode(nodePosition, null, isLeaf: true);
					tileGeneratorNode.SetSpawner(new PointOfInterestSpawner(GetNextPointOfInterestProperties(), tileGeneratorNode.WorldPosition));
					region.AddNode(tileGeneratorNode);
					_tileGenerator.AddNode(tileGeneratorNode);
					return true;
				}
			}
			nodePosition = default(Vector2);
			return false;
		}

		private PointOfInterestProperties GetNextPointOfInterestProperties()
		{
			if (_poisToDistribute.Count == 0)
			{
				_poisToDistribute.AddRange(_randomizedPointsOfInterest);
				_poisToDistribute.Shuffle();
			}
			PointOfInterestProperties result = _poisToDistribute[0];
			_poisToDistribute.RemoveAt(0);
			return result;
		}

		private bool SupportsRegion(TileGeneratorRegion region)
		{
			if (!_supportedRegions.Contains(WorldRegionType.Any))
			{
				return _supportedRegions.Contains(region.Type);
			}
			return true;
		}
	}
