namespace PajamaLlama.Flotsam.Persistence
{
	public sealed class BinaryFormatterBinder : SerializationBinder
	{
		private static readonly Type TYPE_ICollection = typeof(ICollection);

		private static readonly Type TYPE_IDictionary = typeof(IDictionary);

		private readonly Dictionary<string, Type> _bindableTypes = new Dictionary<string, Type>();

		private readonly List<string> _bindableAssemblies = new List<string>();

		public BinaryFormatterBinder(params Type[] types)
		{
			PopulateBindableUnityEngineTypes();
			foreach (Type type in types)
			{
				PopulateBindableTypes(type);
			}
		}

		public override Type BindToType(string assemblyName, string typeName)
		{
			if (_bindableAssemblies.Contains(assemblyName) && _bindableTypes.TryGetValue(typeName, out var value))
			{
				return value;
			}
			throw new NotSupportedException("Unable to bind type '" + typeName + "' from assembly '" + assemblyName + "'");
		}

		public void LogBindableTypes()
		{
			string text = "";
			string text2 = "";
			foreach (string bindableAssembly in _bindableAssemblies)
			{
				text = text + bindableAssembly + "\r\n";
			}
			foreach (string key in _bindableTypes.Keys)
			{
				text2 = text2 + key + "\r\n";
			}
			UnityEngine.Debug.Log("BindableAssemblies:\r\n" + text);
			UnityEngine.Debug.Log("BindableTypes:\r\n" + text2);
		}

		private void PopulateBindableUnityEngineTypes()
		{
			AddBindableType(typeof(Vector2));
			AddBindableType(typeof(Vector3));
			AddBindableType(typeof(Quaternion));
			AddBindableType(typeof(Rect));
		}

		private void PopulateBindableTypes(Type type)
		{
			if (!type.IsSerializable && !type.IsInterface && !type.IsAbstract)
			{
				return;
			}
			if (type.IsArray)
			{
				PopulateBindableTypes(type.GetElementType());
			}
			else
			{
				if (!AddBindableType(type))
				{
					return;
				}
				if (type.IsGenericType && TYPE_ICollection.IsAssignableFrom(type))
				{
					Type[] genericArguments = type.GetGenericArguments();
					Type[] array = genericArguments;
					foreach (Type type2 in array)
					{
						PopulateBindableTypes(type2);
					}
					if (TYPE_IDictionary.IsAssignableFrom(type))
					{
						object obj = Activator.CreateInstance(type);
						Type type3 = type.GetProperty("Comparer").GetValue(obj).GetType();
						AddBindableType(type3);
						AddBindableType(typeof(KeyValuePair<, >).MakeGenericType(genericArguments));
					}
					return;
				}
				FieldInfo[] fields = type.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
				foreach (FieldInfo fieldInfo in fields)
				{
					if (!fieldInfo.IsNotSerialized)
					{
						PopulateBindableTypes(fieldInfo.FieldType);
					}
				}
				if (!type.Assembly.FullName.Contains("Assembly-CSharp"))
				{
					return;
				}
				foreach (Type item in (IEnumerable<Type>)(from t in type.Assembly.GetTypes()
					where t != type && type.IsAssignableFrom(t)
					select t).ToArray())
				{
					PopulateBindableTypes(item);
				}
			}
		}

		private bool AddBindableType(Type type)
		{
			if (_bindableTypes.TryAdd(type.FullName, type))
			{
				_bindableAssemblies.AddUnique(type.Assembly.FullName);
				return true;
			}
			return false;
		}
	}
}
namespace PajamaLlama.Flotsam.Performance
{
	public class UpdateManager : MonoBehaviour
	{
		private List<IUpdateManagerFixedUpdateTarget> _fixedUpdateTargets;

		private int _fixedUpdateTargetCount;

		private List<IUpdateManagerUpdateTarget> _updateTargets;

		private int _updateTargetCount;

		private List<IUpdateManagerLateUpdateTarget> _lateUpdateTargets;

		private int _lateUpdateTargetCount;

		public void Initialize()
		{
			_fixedUpdateTargets = new List<IUpdateManagerFixedUpdateTarget>(1000);
			_updateTargets = new List<IUpdateManagerUpdateTarget>(1000);
			_lateUpdateTargets = new List<IUpdateManagerLateUpdateTarget>(1000);
		}

		private void FixedUpdate()
		{
			for (int i = 0; i < _fixedUpdateTargetCount; i++)
			{
				_fixedUpdateTargets[i].UpdateManager_FixedUpdate();
			}
		}

		private void Update()
		{
			float deltaTime = Time.deltaTime;
			int frameCount = Time.frameCount;
			for (int i = 0; i < _updateTargetCount; i++)
			{
				_updateTargets[i].UpdateManager_Update(deltaTime, frameCount);
			}
		}

		private void LateUpdate()
		{
			for (int i = 0; i < _lateUpdateTargetCount; i++)
			{
				_lateUpdateTargets[i].UpdateManager_LateUpdate();
			}
		}

		public void RegisterFixedUpdateTarget(IUpdateManagerFixedUpdateTarget target)
		{
			_fixedUpdateTargets.Add(target);
			_fixedUpdateTargetCount++;
		}

		public void UnregisterFixedUpdateTarget(IUpdateManagerFixedUpdateTarget target)
		{
			if (_fixedUpdateTargets.Remove(target))
			{
				_fixedUpdateTargetCount--;
			}
		}

		public void RegisterUpdateTarget(IUpdateManagerUpdateTarget target)
		{
			_updateTargets.Add(target);
			_updateTargetCount++;
		}

		public void UnregisterUpdateTarget(IUpdateManagerUpdateTarget target)
		{
			if (_updateTargets.Remove(target))
			{
				_updateTargetCount--;
			}
		}

		public void RegisterLateUpdateTarget(IUpdateManagerLateUpdateTarget target)
		{
			_lateUpdateTargets.Add(target);
			_lateUpdateTargetCount++;
		}

		public void UnregisterLateUpdateTarget(IUpdateManagerLateUpdateTarget target)
		{
			if (_lateUpdateTargets.Remove(target))
			{
				_lateUpdateTargetCount--;
			}
		}
	}
}
namespace PajamaLlama.Flotsam.World
{
	[CreateAssetMenu(fileName = "Voronoi Data", menuName = "Flotsam/Procedural/Voronoi/Voronoi Data")]
	public class VoronoiData : TileGeneratorBase
	{
		public enum GenerationMethod
		{
			Random,
			PoissonDisk
		}

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		private bool _randomSeed;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		private int _seed;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		private GenerationMethod _generationMethod;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		[ConditionalEnumHide("_generationMethod", 0, false, HideInInspector = true)]
		private int _randomSiteCount;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		[ConditionalEnumHide("_generationMethod", 0, false, HideInInspector = true)]
		private int _randomSiteEdgePadding = 250;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, null)]
		[ConditionalEnumHide("_generationMethod", 1, false, HideInInspector = true)]
		private PoissonDiskSamplerWithBounds _poissonDiskSiteGenerator;

		[SerializeField]
		[EditorInspectorGUIField("Voronoi", 0, "Bounds")]
		private Rect _voronoiBounds = new Rect(-4000f, -4000f, 8000f, 8000f);

		[SerializeField]
		private List<VoronoiRegion> _regions;

		[SerializeField]
		private Texture _worldMapTexture;

		[SerializeField]
		private Vector3 _worldMapNormal = Vector3.up;

		[Header("Editor")]
		[SerializeField]
		private Material[] _regionMaterials;

		[SerializeField]
		private HandmadeTileGenerator.Townheart _townheart;

		[SerializeField]
		private List<HandmadeTileGenerator.Landmark> _landmarks;

		[SerializeField]
		private List<HandmadeTileGenerator.PointOfInterest> _pointsOfInterest;

		[SerializeField]
		private List<HandmadeTileGenerator.Road> _roads;

		[Header("Narrative")]
		[SerializeField]
		private bool _isEndTile;

		private List<Vector2> _siteCache;

		private Mesh _cachedMesh;

		private static Rectangle _rectangle = new Rectangle();

		public bool RandomSeed => _randomSeed;

		public Rect VoronoiBounds => _voronoiBounds;

		public List<VoronoiRegion> Regions => _regions;

		public override Rect MinimumBounds => _voronoiBounds;

		public override float Scale
		{
			get
			{
				return 1f;
			}
			set
			{
				throw new NotImplementedException();
			}
		}

		public override bool IsEndTile => _isEndTile;

		public override void Initialize(bool isStartingTile)
		{
		}

		public override IEnumerator Generate(IWorldTile worldTile)
		{
			yield return GenerateRegionsAndRoads(worldTile);
			foreach (HandmadeTileGenerator.Landmark landmark in _landmarks)
			{
				LandmarkSpawner landmarkSpawner = new LandmarkSpawner(landmark.ReturnLandmarkBehaviour(), landmark.Position, landmark.Rotation);
				landmarkSpawner.SetScoutingState(landmark.ScoutingState);
				worldTile.AddLandmarkSpawner(landmarkSpawner);
			}
			yield return null;
			foreach (HandmadeTileGenerator.PointOfInterest item in _pointsOfInterest)
			{
				worldTile.AddPointOfInterestSpawner(new PointOfInterestSpawner(item.PointOfInterestProperties, item.Position));
			}
		}

		public override void Restore(IWorldTile worldTile)
		{
			CoroutineRunner.RunCoroutine(GenerateRegionsAndRoads(worldTile));
		}

		private IEnumerator GenerateRegionsAndRoads(IWorldTile worldTile)
		{
			VoronoiTask task = new VoronoiTask(GenerateSites(), _voronoiBounds);
			if (ThreadPoolManager.QueueTask(task))
			{
				yield return new WaitForThreadpoolManagerTask(task);
			}
			else
			{
				Voronoi.Generate(GenerateSites(), _voronoiBounds);
			}
			using ListPool<VoronoiWorldRegion>.List worldRegions = ListPool<VoronoiWorldRegion>.Get(_regions.Count);
			yield return PopulateRegions(worldRegions);
			yield return null;
			foreach (VoronoiWorldRegion item in worldRegions)
			{
				worldTile.AddRegion(item);
			}
			worldTile.PopulateRegionNeighbors();
			yield return null;
			foreach (HandmadeTileGenerator.Road road in _roads)
			{
				if (road.Nodes.Length == 0)
				{
					UnityEngine.Debug.LogException(new Exception("A road with 0 nodes was encoutered during WorldTile generation"));
				}
				else
				{
					worldTile.AddRoadSpawner(new RoadSpawner(road));
				}
			}
			yield return null;
			_cachedMesh = GenerateMesh();
			yield return null;
		}

		private IEnumerator PopulateRegions(List<VoronoiWorldRegion> worldRegions)
		{
			foreach (VoronoiRegion region in _regions)
			{
				worldRegions.Add(new VoronoiWorldRegion(region, _voronoiBounds));
				yield return null;
			}
			foreach (VoronoiWorldRegion worldRegion in worldRegions)
			{
				worldRegion.PopulateNeighbors(worldRegions);
			}
		}

		public override bool TryReturnTownheartStartPosition(out Vector3 position)
		{
			if (_townheart != null)
			{
				position = _townheart.GetPosition();
				return true;
			}
			position = default(Vector3);
			return false;
		}

		public List<Vector2> GenerateSites()
		{
			if (_siteCache == null)
			{
				_siteCache = new List<Vector2>(1024);
			}
			else
			{
				_siteCache.Clear();
			}
			UnityEngine.Random.State state = UnityEngine.Random.state;
			UnityEngine.Random.InitState(_seed);
			switch (_generationMethod)
			{
			case GenerationMethod.Random:
			{
				Rect rect = new Rect(_voronoiBounds);
				rect.xMin += _randomSiteEdgePadding;
				rect.yMin += _randomSiteEdgePadding;
				rect.xMax -= _randomSiteEdgePadding;
				rect.yMax -= _randomSiteEdgePadding;
				for (int i = 0; i < _randomSiteCount; i++)
				{
					_siteCache.Add(rect.RandomPosition());
				}
				break;
			}
			case GenerationMethod.PoissonDisk:
				_poissonDiskSiteGenerator.GenerateSamples(_voronoiBounds);
				_siteCache.AddRange(_poissonDiskSiteGenerator.Samples);
				break;
			}
			UnityEngine.Random.state = state;
			return _siteCache;
		}

		public bool TryGetRegionMaterial(out Material material, WorldRegionType region)
		{
			material = null;
			if (_regionMaterials == null)
			{
				return false;
			}
			int num = (int)(region - 1);
			if (0 <= num && num < _regionMaterials.Length)
			{
				material = _regionMaterials[num];
				return true;
			}
			return material != null;
		}

		public Mesh GenerateMesh()
		{
			List<Vector3> list = new List<Vector3>();
			List<int> list2 = new List<int>();
			List<Vector2> list3 = new List<Vector2>();
			foreach (VoronoiRegion region in _regions)
			{
				region.GenerateTriangles(list, list2, list3);
			}
			Vector3[] array = new Vector3[list.Count];
			for (int i = 0; i < array.Length; i++)
			{
				array[i] = _worldMapNormal;
			}
			return new Mesh
			{
				vertices = list.ToArray(),
				triangles = list2.ToArray(),
				uv = list3.ToArray(),
				normals = array
			};
		}

		public override bool TryReturnWorldMapRegionMeshAndBounds(out Mesh mesh, out Rect bounds)
		{
			if (_cachedMesh == null)
			{
				_cachedMesh = GenerateMesh();
			}
			mesh = _cachedMesh;
			bounds = _voronoiBounds;
			return mesh != null;
		}

		public bool IntersectsWithRoad(Polygon2DBase polygon, float width)
		{
			foreach (HandmadeTileGenerator.Road road in _roads)
			{
				if (road.Nodes.Length < 1)
				{
					continue;
				}
				Vector2 vector = road.Nodes[0];
				for (int i = 1; i < road.Nodes.Length; i++)
				{
					Vector2 vector2 = road.Nodes[i];
					_rectangle.Set(vector, vector2 - vector, width);
					if (polygon.IsOverlapping(_rectangle))
					{
						return true;
					}
					vector = vector2;
				}
			}
			return false;
		}

		public override bool HasRegionOfType(params WorldRegionType[] worldRegionTypes)
		{
			foreach (VoronoiRegion region in _regions)
			{
				if (worldRegionTypes.Contains(region.Type))
				{
					return true;
				}
			}
			return false;
		}
	}
	public class VoronoiTask : ThreadPoolManager.ITask
	{
		private List<Vector2> _sites;

		private Rect _bounds;

		private Exception _exception;

		public bool Completed { get; private set; }

		public VoronoiTask(List<Vector2> sites, Rect bounds)
		{
			_sites = sites;
			_bounds = bounds;
		}

		public void ThreadPoolWaitCallback(object state)
		{
			try
			{
				Execute();
			}
			catch (Exception exception)
			{
				_exception = exception;
			}
			finally
			{
				Completed = true;
			}
		}

		public void UnityCompletedCallback()
		{
			if (_exception != null)
			{
				throw _exception;
			}
		}

		private void Execute()
		{
			Voronoi.Generate(_sites, _bounds);
		}
	}
	public class RoadSpawner : ISpawner
	{
		internal class RoadElement
		{
			internal Vector3 Position;

			internal Vector3 SpawnPosition;

			internal Quaternion Rotation;

			internal Quaternion SpawnRotation;

			internal int PrefabPoolIndex;

			internal GameObject Instance;

			public RoadElement(Vector3 position, Quaternion rotation)
			{
				SpawnPosition = (Position = position);
				SpawnRotation = (Rotation = rotation);
				PrefabPoolIndex = -1;
			}
		}

		[Serializable]
		public struct PersistentData
		{
			public string Name;

			public Vector2[] Nodes;

			public PersistentData(RoadSpawner roadSpawner)
			{
				Name = roadSpawner.Name;
				Nodes = roadSpawner.Nodes;
			}

			public RoadSpawner ReturnInstance()
			{
				return new RoadSpawner(Name, Nodes);
			}
		}

		private Vector3 _worldTileOffset = Vector3.zero;

		private RoadElement[] _roadElements;

		private WorldManager _worldManager;

		private static List<PrefabPool> _roadPools;

		public string Name { get; private set; }

		public ISpawnerType Type => ISpawnerType.Road;

		public Sprite Icon => null;

		public WorldTile WorldTile => null;

		public Vector3 WorldPosition => Vector3.zero;

		public Vector2 WorldPosition2D => Vector2.zero;

		public Vector2 TilePosition => Vector2.zero;

		public WorldRegionType RegionType => WorldRegionType.None;

		public ScoutingState ScoutingState => ScoutingState.Scouted;

		public Vector2[] Nodes { get; private set; }

		public ISpawnerEvent UpdatedEvent { get; }

		private RoadSpawner(string name, Vector2[] nodes)
		{
			int num = nodes.Length - 1;
			Vector2 vector = nodes[0];
			Vector2 right = Vector2.right;
			Nodes = nodes;
			_roadElements = new RoadElement[num];
			for (int i = 0; i < num; i++)
			{
				Vector2 vector2 = nodes[i + 1];
				Vector2 vector3 = vector2 - vector;
				Vector2 vector4 = vector + vector3 / 2f;
				_roadElements[i] = new RoadElement(vector4.Vector3TopDown(), Quaternion.Euler(0f, 0f - Vector2.SignedAngle(right, vector3), 0f));
				vector = vector2;
			}
			Name = name;
		}

		internal RoadSpawner(HandmadeTileGenerator.Road road)
			: this(road.Name, road.Nodes)
		{
		}

		public void Initialize()
		{
		}

		public void SetWorldTileOffset(Vector3 offset)
		{
			_worldTileOffset = offset;
			RoadElement[] roadElements = _roadElements;
			for (int i = 0; i < roadElements.Length; i++)
			{
				roadElements[i].Position += offset;
			}
		}

		public void Spawn(Transform parent = null)
		{
			if (!TryReturnWorldManager(out var worldManager))
			{
				return;
			}
			RoadElement[] roadElements = _roadElements;
			foreach (RoadElement roadElement in roadElements)
			{
				if (worldManager.IsInSpawnRadius(roadElement.SpawnPosition))
				{
					if (!roadElement.Instance)
					{
						roadElement.Instance = GetInstance(roadElement);
					}
					roadElement.Instance.transform.SetParent(parent);
					roadElement.Instance.transform.position = roadElement.SpawnPosition;
					roadElement.Instance.transform.rotation = roadElement.SpawnRotation;
				}
				else if ((bool)roadElement.Instance)
				{
					_roadPools[roadElement.PrefabPoolIndex].ReleaseInstance(roadElement.Instance);
					roadElement.Instance = null;
				}
			}
		}

		public bool Despawn(bool destroyInstance)
		{
			RoadElement[] roadElements = _roadElements;
			foreach (RoadElement roadElement in roadElements)
			{
				if ((bool)roadElement.Instance)
				{
					_roadPools[roadElement.PrefabPoolIndex].ReleaseInstance(roadElement.Instance);
					roadElement.Instance = null;
				}
			}
			return true;
		}

		public void Move(Vector3 movement)
		{
			throw new NotSupportedException();
		}

		public void RepositionRelativeToTownheart(Vector3 townheartPosition, Quaternion townheartRotation)
		{
			RoadElement[] roadElements = _roadElements;
			foreach (RoadElement obj in roadElements)
			{
				Vector3 vector = obj.Position - townheartPosition;
				obj.SpawnPosition = Quaternion.Inverse(townheartRotation) * vector;
				obj.SpawnRotation = obj.Rotation * Quaternion.Inverse(townheartRotation);
			}
		}

		public void CountItems(InventoryAuditor auditor)
		{
			throw new NotSupportedException();
		}

		public float ReturnDistance(Vector3 position)
		{
			float num = float.MaxValue;
			RoadElement[] roadElements = _roadElements;
			foreach (RoadElement roadElement in roadElements)
			{
				float num2 = position.DistanceToSquared(roadElement.Position);
				if (num2 < num)
				{
					num = num2;
				}
			}
			return Mathf.Sqrt(num);
		}

		private bool TryReturnWorldManager(out WorldManager worldManager)
		{
			worldManager = _worldManager;
			if ((bool)worldManager)
			{
				return true;
			}
			worldManager = (_worldManager = GameManager.WorldManager);
			return worldManager != null;
		}

		private GameObject GetInstance(RoadElement roadElement)
		{
			if (_roadPools == null)
			{
				_roadPools = new List<PrefabPool>();
				GameObject[] roads = GameSettings.ReturnWorldSettings().Roads;
				foreach (GameObject prefab in roads)
				{
					_roadPools.Add(new PrefabPool(prefab, "Road Elements", 16));
				}
			}
			if (roadElement.PrefabPoolIndex == -1)
			{
				roadElement.PrefabPoolIndex = UnityEngine.Random.Range(0, _roadPools.Count);
			}
			return _roadPools[roadElement.PrefabPoolIndex].GetInstance();
		}
	}
