		[SerializeField]
		private Townheart _townheart;

		[SerializeField]
		private List<Landmark> _landmarks;

		[SerializeField]
		private List<PointOfInterest> _pointsOfInterest;

		[SerializeField]
		private List<Road> _roads;

		[SerializeField]
		private List<Region> _regions;

		[SerializeField]
		private Vector2 _minimumSize = new Vector2(10240f, 10240f);

		[SerializeField]
		[Range(0.1f, 10f)]
		private float _scale = 1f;

		public override Rect MinimumBounds => new Rect(-(_minimumSize / 2f), _minimumSize / 2f);

		public override float Scale
		{
			get
			{
				return _scale;
			}
			set
			{
			}
		}

		public override void Initialize(bool isStartingTile)
		{
			if (_scale < 1f)
			{
				_scale = 1f;
			}
		}

		public override IEnumerator Generate(IWorldTile worldTile)
		{
			GenerateRegionsAndRoads(worldTile);
			foreach (Landmark landmark in _landmarks)
			{
				worldTile.AddLandmarkSpawner(new LandmarkSpawner(landmark.ReturnLandmarkBehaviour(), landmark.Position * _scale, landmark.Rotation));
			}
			foreach (PointOfInterest item in _pointsOfInterest)
			{
				worldTile.AddPointOfInterestSpawner(new PointOfInterestSpawner(item.PointOfInterestProperties, item.Position * _scale));
			}
			yield break;
		}

		public override void Restore(IWorldTile worldTile)
		{
			GenerateRegionsAndRoads(worldTile);
			foreach (Landmark landmark in _landmarks)
			{
				if (!landmark.IsInteractable())
				{
					worldTile.AddLandmarkSpawner(new LandmarkSpawner(landmark.ReturnLandmarkBehaviour(), landmark.Position * _scale, landmark.Rotation));
				}
			}
		}

		private void GenerateRegionsAndRoads(IWorldTile worldTile)
		{
			foreach (Region region in _regions)
			{
				if (2 < region.Polygon.Count)
				{
					worldTile.AddRegion(new HandMadeWorldRegion(region));
				}
			}
			foreach (Road road in _roads)
			{
				if (1 < road.Nodes.Length)
				{
					worldTile.AddRoadSpawner(new RoadSpawner(road));
				}
			}
		}

		public override bool TryReturnTownheartStartPosition(out Vector3 position)
		{
			position = _townheart.Position;
			return true;
		}
	}
	[CreateAssetMenu(fileName = "First Landmark Cluster Generator", menuName = "Flotsam/Procedural Generation/Landmarks/First Cluster Generator")]
	public class FirstLandmarkClusterGenerator : LandmarkClusterGeneratorBase
	{
		[SerializeField]
		private ClusterLandmarkProvider _scoutCluster;

		[SerializeField]
		private WeightedList<ClusterLandmarkProvider> _otherClusters;

		private LandmarkGeneratorBase _landmarkGenerator;

		public override void Run<T>(IRegion region, List<T> clusters)
		{
			base.GeneratedLandmarks.Clear();
			GenerateClusterLandmarks(clusters[0], _scoutCluster);
			for (int i = 1; i < clusters.Count; i++)
			{
				GenerateClusterLandmarks(clusters[i], _otherClusters.ReturnRandom());
			}
		}

		private void GenerateClusterLandmarks(ILandmarkCluster cluster, ClusterLandmarkProvider clusterLandmarkProvider)
		{
			IEnumerator<ILandmarkBehaviourProvider> enumerator = clusterLandmarkProvider.GetEnumerator();
			Vector2 position;
			while (enumerator.MoveNext() && TryReturnLandmarkPosition(out position, cluster.Position, clusterLandmarkProvider, enumerator.Current))
			{
				AddLandmark(enumerator.Current, position);
			}
		}

		private bool TryReturnLandmarkPosition(out Vector2 position, Vector2 clusterPosition, ClusterLandmarkProvider landmarkProvider, ILandmarkBehaviourProvider landmarkBehaviourProvider, int maxItterations = 100)
		{
			for (int i = 0; i < maxItterations; i++)
			{
				position = landmarkProvider.GetRandomSpawnPosition(clusterPosition, landmarkBehaviourProvider);
				if (IsValidPosition(landmarkBehaviourProvider, position))
				{
					return true;
				}
			}
			position = default(Vector2);
			return false;
		}
	}
	public interface ILandmarkCluster
	{
		Vector2 Position { get; }

		int Count { get; }

		void Add(ILandmarkBehaviourProvider landmarkBehaviourProvider, Vector2 position);
	}
	public abstract class LandmarkClusterGeneratorBase : ScriptableObject
	{
		public LandmarkGeneratorBase LandmarkGenerator { get; private set; }

		public List<LandmarkGeneratorBase.Landmark> GeneratedLandmarks { get; private set; } = new List<LandmarkGeneratorBase.Landmark>();

		public void Initialize(LandmarkGeneratorBase landmarkGenerator)
		{
			LandmarkGenerator = landmarkGenerator;
		}

		public abstract void Run<T>(IRegion region, List<T> clusters) where T : ILandmarkCluster;

		protected void AddLandmark(ILandmarkBehaviourProvider landmarkBehaviourProvider, Vector2 position)
		{
			GeneratedLandmarks.Add(new LandmarkGeneratorBase.Landmark(landmarkBehaviourProvider, position));
			LandmarkGenerator.AddLandmark(landmarkBehaviourProvider, position);
		}

		public bool IsValidPosition(ILandmarkBehaviourProvider landmarkBehaviourProvider, Vector2 position)
		{
			if (!LandmarkGenerator.IsValidPosition(position))
			{
				return false;
			}
			foreach (LandmarkGeneratorBase.Landmark generatedLandmark in GeneratedLandmarks)
			{
				if (Vector2.Distance(generatedLandmark.Position, position) < generatedLandmark.LandmarkBehaviourProvider.Radius + landmarkBehaviourProvider.Radius)
				{
					return false;
				}
			}
			return true;
		}
	}
	[CreateAssetMenu(fileName = "Second Landmark Cluster Generator", menuName = "Flotsam/Procedural Generation/Landmarks/Second Cluster Generator")]
	public class SecondLandmarkClusterGenerator : LandmarkClusterGeneratorBase
	{
		[SerializeField]
		private float _density = 100f;

		[SerializeField]
		private LandmarkBehaviourCollection _scoutLandmarkBehaviourCollection;

		[SerializeField]
		private WeightedList<WeightedList<LandmarkBehaviourCollection>> _distributer;

		[SerializeField]
		private int _clusterMinimumCount;

		[SerializeField]
		private int _clusterMaximumCount;

		[SerializeField]
		private float _clusterSpawnRadius;

		private LandmarkGeneratorBase _landmarkGenrator;

		private List<LandmarkBehaviourCollection> _distributionList = new List<LandmarkBehaviourCollection>();

		public override void Run<T>(IRegion region, List<T> clusters)
		{
			float num = region.ReturnSurface();
			int num2 = Mathf.RoundToInt(num / _density);
			using ListPool<T>.List list = ListPool<T>.Get(clusters);
			UnityEngine.Debug.Log($"Spawning {num2} landmarks, in a region with a surface of {num}m2.");
			base.GeneratedLandmarks.Clear();
			if (!TryAddLandmark(clusters[0], _scoutLandmarkBehaviourCollection))
			{
				UnityEngine.Debug.LogError("Unable to add scout landmark");
			}
			for (int i = 0; i < _clusterMinimumCount; i++)
			{
				foreach (T item in list)
				{
					ILandmarkCluster landmarkCluster = item;
					num2--;
					if (landmarkCluster.Count != i)
					{
						DistributeLandmark(landmarkCluster);
					}
				}
			}
			while (0 < num2-- && 0 < list.Count)
			{
				int index = UnityEngine.Random.Range(0, list.Count);
				ILandmarkCluster landmarkCluster2 = list[index];
				if (!DistributeLandmark(landmarkCluster2) || landmarkCluster2.Count >= _clusterMaximumCount)
				{
					list.RemoveAt(index);
				}
			}
		}

		private bool DistributeLandmark(ILandmarkCluster cluster)
		{
			if (TryAddLandmark(cluster, _distributer.ReturnRandom().ReturnRandom()))
			{
				return true;
			}
			return false;
		}

		private bool TryAddLandmark(ILandmarkCluster cluster, ILandmarkBehaviourProvider landmarkBehaviourProvider)
		{
			if (TryGetValidPosition(out var position, cluster, landmarkBehaviourProvider))
			{
				AddLandmark(landmarkBehaviourProvider, position);
				return true;
			}
			return false;
		}

		public bool TryGetValidPosition(out Vector2 position, ILandmarkCluster cluster, ILandmarkBehaviourProvider landmarkBehaviourProvider, int maxItterations = 25)
		{
			for (int i = 0; i < maxItterations; i++)
			{
				position = GetRandomSpawnPosition(cluster.Position, landmarkBehaviourProvider);
				if (IsValidPosition(landmarkBehaviourProvider, position))
				{
					return true;
				}
			}
			position = default(Vector2);
			return false;
		}

		public Vector2 GetRandomSpawnPosition(Vector2 position, ILandmarkBehaviourProvider landmarkBehaviourProvider)
		{
			return position + UnityEngine.Random.insideUnitCircle * (_clusterSpawnRadius - landmarkBehaviourProvider.Radius);
		}
	}
	public interface ILandmarkEditor : IWorldEditorWindow
	{
		void AddLandmark(ILandmarkBehaviourProvider landmarkBehaviourProvider, Vector2 position);

		void RemoveLandmarksInRegion(IRegion region);
	}
	public abstract class LandmarkGeneratorBase : ScriptableObject
	{
		public struct Landmark
