	public class MoraleWarning : AgentReferenceUIElement
	{
		[SerializeField]
		private GameObject _warningGameObject;

		[SerializeField]
		private Image _iconImage;

		[SerializeField]
		private RangedFloat _displayInterval = new RangedFloat(45f, 75f);

		[SerializeField]
		private float _displayTime = 10f;

		private float _currentTimer;

		private float _displayTimer;

		private bool _hasNegativeMoraleModifiers;

		private void Update()
		{
			if (_warningGameObject.activeSelf)
			{
				_displayTimer += GameSpeedManager.PausableUnscaledDeltaTime;
				if (_displayTimer >= _displayTime)
				{
					_warningGameObject.SetActive(value: false);
				}
			}
			else if (_hasNegativeMoraleModifiers)
			{
				_currentTimer -= GameSpeedManager.PausableUnscaledDeltaTime;
				if (_currentTimer <= 0f)
				{
					DisplayWarning();
				}
			}
		}

		protected override void Subscribe(Agent agent)
		{
			agent.Morale.UpdatedEvent.AddListener(UpdateMorale);
			UpdateMorale();
		}

		protected override void Unsubscribe(Agent agent)
		{
			agent.Morale.UpdatedEvent.RemoveListener(UpdateMorale);
		}

		protected override void UpdateAgent(Agent agent)
		{
			base.UpdateAgent(agent);
			_currentTimer = _displayInterval.ReturnRandom();
			_currentTimer -= UnityEngine.Random.Range(0f, _currentTimer);
		}

		private void UpdateMorale()
		{
			_currentTimer = _displayInterval.ReturnRandom();
			_hasNegativeMoraleModifiers = TryReturnMostPressingEffect(out var moraleEffect);
			if (_hasNegativeMoraleModifiers)
			{
				_iconImage.sprite = moraleEffect.ReturnSprite();
			}
		}

		private void DisplayWarning()
		{
			_currentTimer = _displayInterval.ReturnRandom();
			_displayTimer = 0f;
			_warningGameObject.SetActive(value: true);
		}

		private bool TryReturnMostPressingEffect(out MoraleEffect moraleEffect)
		{
			int num = 0;
			MoraleEffect moraleEffect2 = null;
			if (_agent.Morale.HasNegativeModifier())
			{
				MoraleEffect[] moraleEffects = _agent.Morale.MoraleEffects;
				foreach (MoraleEffect moraleEffect3 in moraleEffects)
				{
					int num2 = moraleEffect3.ReturnModifier();
					if (moraleEffect3.IsActive() && num2 < 0 && num2 < num)
					{
						moraleEffect2 = moraleEffect3;
						num = num2;
					}
				}
			}
			moraleEffect = moraleEffect2;
			return moraleEffect != null;
		}

		public bool IsActive()
		{
			return _warningGameObject.activeSelf;
		}
	}
	[DisallowMultipleComponent]
	public class MoraleCategoryTooltip : Tooltip
	{
		private MoraleCategory _moraleCategory;

		private Agent _agent;

		private static readonly StringBuilder _tooltipBuilder = new StringBuilder();

		public MoraleProperties MoraleProperties
		{
			get
			{
				if (!(_agent == null))
				{
					return _agent.Morale.Properties;
				}
				return null;
			}
		}

		public int CurrentLevel
		{
			get
			{
				if (!(_agent == null))
				{
					return _agent.Attributes.Level;
				}
				return 0;
			}
		}

		public int MaximumLevel
		{
			get
			{
				if (!(_agent == null))
				{
					return _agent.Attributes.MaximumDrifterLevel;
				}
				return 0;
			}
		}

		public void Initialize(MoraleCategory category, Agent agent)
		{
			_moraleCategory = category;
			_agent = agent;
			LocalizedText = category.Name;
		}

		public override string ParsedText()
		{
			_tooltipBuilder.Clear();
			_tooltipBuilder.AppendLine("<style=\"Tooltip Name\">" + base.ParsedText() + "</style>");
			string replacement = $"<color=#{ColorUtility.ToHtmlStringRGBA(_moraleCategory.Color)}>{_moraleCategory.SpeedMultiplier:0%}</color>";
			_tooltipBuilder.AppendLine(Regex.Replace(_moraleCategory.EffectTooltip, "%SPEED%", replacement, RegexOptions.IgnoreCase));
			if (MoraleProperties != null && MoraleProperties.TryReturnCategoryLimits(CurrentLevel, MaximumLevel, _moraleCategory, out var limits))
			{
				string input = Regex.Replace(_moraleCategory.RangeTooltip, "%MINIMUM%", limits.Minimum.ToString().AddSign(limits.Minimum), RegexOptions.IgnoreCase);
				input = Regex.Replace(input, "%MAXIMUM%", limits.Maximum.ToString().AddSign(limits.Maximum), RegexOptions.IgnoreCase);
				_tooltipBuilder.AppendLine(input);
			}
			return _tooltipBuilder.ToString();
		}
	}
	[CreateAssetMenu(menuName = "Flotsam/Agent/Morale/Effects/Affinity Morale Effect")]
	public class AffinityMoraleEffect : MoraleEffect
	{
		[Serializable]
		public class PersistentData : BasePersistentData
		{
			public PersistentData(AffinityMoraleEffect moraleEffect)
				: base(moraleEffect)
			{
			}
		}

		[SerializeField]
		private float levelsPerPoint;

		[SerializeField]
		private LocalizedString _description = "";

		[SerializeField]
		private Sprite _icon;

		private bool _isActive;

		private int _modifier;

		public override void Initialize(Agent agent, MoraleEffect properties)
		{
			base.Initialize(agent, properties);
			GameEventDispatcher.AddListener(GameEventType.GameStart, OnGameStart);
			GameEventDispatcher.AddListener(GameEventType.AgentAttributeLeveled, OnAgentAttributeLeveled);
		}

		public override void Destroy()
		{
			GameEventDispatcher.RemoveListener(GameEventType.AgentAttributeLeveled, OnAgentAttributeLeveled);
		}

		private void OnGameStart(GameEvent gameEvent)
		{
			GameEventDispatcher.RemoveListener(GameEventType.GameStart, OnGameStart);
			UpdateModifier();
		}

		private void OnAgentAttributeLeveled(GameEvent gameEvent)
		{
			if (gameEvent is AttributeEvent attributeEvent && attributeEvent.Agent == _agent)
			{
				UpdateModifier();
			}
		}

		public override bool IsActive()
		{
			return _isActive;
		}

		public override string ReturnDescription()
		{
			return _description;
		}

		public override Sprite ReturnSprite()
		{
			return _icon;
		}

		public override int ReturnModifier()
		{
			return _modifier;
		}

		public override bool TryReturnAttributeEffect(out DrifterAttributesEffect effect)
		{
			effect = null;
			return false;
		}

		private void UpdateModifier()
		{
			_modifier = 0;
			DrifterAttributes.AttributeType[] array = DrifterAttributes.ReturnAttributeTypes();
			foreach (DrifterAttributes.AttributeType type in array)
			{
				int num = _agent.Attributes.ReturnAffinityAmount(type);
				int num2 = _agent.Attributes.ReturnAttributeExpertise(type);
				_modifier += Mathf.CeilToInt((float)num2 / levelsPerPoint) * num;
			}
			if (_modifier == 0)
			{
				Deactivate();
			}
			else
			{
				Activate();
			}
		}

		protected override void Activate()
		{
			if (!_isActive)
			{
				_isActive = true;
				base.Activate();
			}
		}

		protected override void Deactivate()
		{
			if (_isActive)
			{
				_isActive = false;
				base.Deactivate();
			}
		}

		public override void Restore(BasePersistentData persistentData)
		{
			if (!persistentData.TryReturnCast<PersistentData>(out var _))
			{
				throw new NotImplementedException();
			}
			UpdateModifier();
		}

		public override BasePersistentData ReturnPersistentData()
		{
			return new PersistentData(this);
		}
	}
