		{
			if (!persistentData.TryReturnCast<EnergyLowPersistentData>(out var _))
			{
				throw new NotImplementedException();
			}
		}

		public override BasePersistentData ReturnPersistentData()
		{
			return new EnergyLowPersistentData(this);
		}
