		private void OnVitalsUpdated(GameEvent gameEvent)
		{
			int currentValue = CurrentValue;
			if (currentValue != _lastValue)
			{
				UpdateAttributeEffect();
				if (currentValue == 0)
				{
					Deactivate();
				}
				else
				{
					Activate();
