		{
			DaysOnFloor = Mathf.Max(0, daysOnFloor);
			ClearCurrentEffect();
			SetCurrentEffect();
		}

		private void SetCurrentEffect()
		{
			if (MoraleEffect.TryReturnAttributeEffect(_effects, DaysOnFloor, out var currentStack, out var effect))
