	[CreateAssetMenu(menuName = "Flotsam/Agent/Morale/Effects/Working Affinity")]
	public class WorkingAffinityMoraleEffect : MoraleEffect
	{
		[Serializable]
		public class WorkingPersistentData : BasePersistentData
		{
			public bool IsWorking;

			[OptionalField(VersionAdded = 2)]
			public int Modifier;

			public int AffinityAmount;

			public WorkingPersistentData(WorkingAffinityMoraleEffect moraleEffect)
				: base(moraleEffect)
			{
				IsWorking = moraleEffect.IsWorking;
				Modifier = moraleEffect._modifier;
			}
		}

		[SerializeField]
		private LocalizedString _description = "";

		[SerializeField]
		private Sprite _icon;

		[FormerlySerializedAs("_thresholdModifiers")]
		[SerializeField]
		private MoraleEffectModifierThreshold[] _modifierThresholds;

		private static AssignmentType[] _assignmentTypes;

		private int _modifier;

		public bool IsWorking { get; private set; }

		public override void Initialize(Agent agent, MoraleEffect properties)
		{
			base.Initialize(agent, properties);
			IsWorking = false;
			_modifier = 0;
			if (_assignmentTypes == null)
			{
				_assignmentTypes = (AssignmentType[])Enum.GetValues(typeof(AssignmentType));
			}
			_agent.OnAssignmentUpdatedEvent.AddListener(OnAssignmentUpdated);
			_agent.Attributes.AttributesUpdatedEvent.AddListener(OnUpdateModifier);
		}

		public override void Destroy()
		{
			_agent.OnAssignmentUpdatedEvent.RemoveListener(OnAssignmentUpdated);
			_agent.Attributes.AttributesUpdatedEvent.RemoveListener(OnUpdateModifier);
		}

		private void OnAssignmentUpdated(Agent agent)
		{
			OnUpdateModifier();
		}

		private void OnUpdateModifier()
		{
			if (_agent.Assignment != null)
			{
				_modifier = 0;
				AssignmentType[] assignmentTypes = _assignmentTypes;
				foreach (AssignmentType assignmentType in assignmentTypes)
				{
					if (TryReturnAttributeType(assignmentType, _agent.Assignment, out var attributeType))
					{
						_modifier += ReturnModifier(attributeType) * _agent.Attributes.ReturnAffinityAmount(attributeType);
					}
				}
				if (0 < _modifier)
				{
					Activate();
					return;
				}
			}
			Deactivate();
		}

		protected override void Activate()
		{
			IsWorking = true;
			base.Activate();
		}

		protected override void Deactivate()
		{
			IsWorking = false;
			_modifier = 0;
			base.Deactivate();
		}

		public int ReturnTooltipModifier(int affinityAmount)
		{
			if (!((IReadOnlyCollection<MoraleEffectModifierThreshold>)(object)_modifierThresholds).IsNullOrEmpty())
			{
				return _modifierThresholds[0].Modifier * affinityAmount;
			}
			return 0;
		}

		public override bool IsActive()
		{
			return IsWorking;
		}

		public override int ReturnModifier()
		{
			return _modifier;
		}

		public override string ReturnDescription()
		{
			return _description;
		}

		public override Sprite ReturnSprite()
		{
			return _icon;
		}

		public override bool TryReturnAttributeEffect(out DrifterAttributesEffect effect)
		{
			effect = null;
			return false;
		}

		private bool TryReturnAttributeType(AssignmentType assignmentType, ProjectAssignment assignment, out DrifterAttributes.AttributeType attributeType)
		{
			attributeType = DrifterAttributes.AttributeType.None;
			if (assignment == null || assignment.Project == null || (assignment.Project.AssignmentTypes & assignmentType) == 0)
			{
				return false;
			}
			switch (assignmentType)
			{
			case AssignmentType.Constructing:
				attributeType = DrifterAttributes.AttributeType.Construction;
				break;
			case AssignmentType.Hauling:
			case AssignmentType.EelectricityManagement:
				attributeType = DrifterAttributes.AttributeType.Athletics;
				break;
			case AssignmentType.LiquidHandling:
				attributeType = DrifterAttributes.AttributeType.Liquids;
				break;
			case AssignmentType.Crafting:
				attributeType = DrifterAttributes.AttributeType.Recycling;
				break;
			case AssignmentType.Cooking:
				attributeType = DrifterAttributes.AttributeType.Cooking;
				break;
			case AssignmentType.Fishing:
				attributeType = DrifterAttributes.AttributeType.Fishing;
				break;
			case AssignmentType.BuoySalvaging:
			case AssignmentType.LandmarkInteraction:
				attributeType = DrifterAttributes.AttributeType.Salvaging;
				break;
			case AssignmentType.Medicine:
				attributeType = DrifterAttributes.AttributeType.Medicine;
				break;
			case AssignmentType.Researching:
				attributeType = DrifterAttributes.AttributeType.Research;
				break;
			}
			return attributeType != DrifterAttributes.AttributeType.None;
		}

		private int ReturnModifier(DrifterAttributes.AttributeType attributeType)
		{
			int num = _agent.Attributes.ReturnAttributeExpertise(attributeType);
			int result = 0;
			MoraleEffectModifierThreshold[] modifierThresholds = _modifierThresholds;
			for (int i = 0; i < modifierThresholds.Length; i++)
			{
				MoraleEffectModifierThreshold moraleEffectModifierThreshold = modifierThresholds[i];
				if (moraleEffectModifierThreshold.Threshold <= (float)num)
				{
					result = moraleEffectModifierThreshold.Modifier;
				}
			}
			return result;
		}

		public override void Restore(BasePersistentData persistentData)
		{
			if (persistentData.TryReturnCast<WorkingPersistentData>(out var persistentData2))
			{
				IsWorking = persistentData2.IsWorking;
				_modifier = persistentData2.Modifier;
				return;
			}
			throw new NotImplementedException();
		}

		public override BasePersistentData ReturnPersistentData()
		{
			return new WorkingPersistentData(this);
		}
	}
	public class Morale : SceneBehaviour
	{
		[Serializable]
		public class PersistentData
		{
			public MoraleEffect.BasePersistentData[] MoraleEffects;

			public PersistentData(Morale morale)
			{
				int num = morale.MoraleEffects.Length;
				MoraleEffects = new MoraleEffect.BasePersistentData[num];
				for (int i = 0; i < num; i++)
				{
					MoraleEffects[i] = morale.MoraleEffects[i].ReturnPersistentData();
				}
			}

			public void Restore(Morale morale)
			{
				MoraleEffect[] moraleEffects = morale.MoraleEffects;
				foreach (MoraleEffect moraleEffect in moraleEffects)
				{
					if (TryReturnPersistentData(moraleEffect, out var persistentData))
					{
						moraleEffect.Restore(persistentData);
					}
				}
			}

			private bool TryReturnPersistentData(MoraleEffect effect, out MoraleEffect.BasePersistentData persistentData)
			{
				MoraleEffect.BasePersistentData[] moraleEffects = MoraleEffects;
				foreach (MoraleEffect.BasePersistentData basePersistentData in moraleEffects)
				{
					if (basePersistentData != null && basePersistentData.PropertiesIndex == effect.PropertiesIndex)
					{
						persistentData = basePersistentData;
						return true;
					}
				}
				persistentData = null;
				return false;
			}
		}

		[SerializeField]
		[FormerlySerializedAs("Properties")]
		private MoraleProperties _properties;

		private Agent _agent;

		private TimeManager _timeManager;

		public UnityEvent UpdatedEvent { get; private set; }

		public UnityEvent CategoryUpdatedEvent { get; private set; }

		public MoraleProperties Properties => _properties;

		public MoraleEffect[] MoraleEffects { get; private set; }

		public int CurrentMood { get; private set; }

		public int CurrentMorale { get; private set; }

		public float CurrentMoraleFloat { get; private set; }

		public MoraleCategory CurrentMoraleCategory { get; private set; }

		public int MoraleNeed => Mathf.Min(_agent.Attributes.Level, _properties.MoraleNeedCap);

		public float ExperienceMultiplier { get; private set; }

		public float SpeedMultiplier { get; private set; }

		private void Update()
		{
			CurrentMood = ReturnMoodScore();
			switch (_properties.Style)
			{
			case MoraleStyle.AddMoodToMorale:
			{
				float num2 = (float)CurrentMood / _timeManager.CurrentDay.HourLength * Time.deltaTime;
				CurrentMoraleFloat = Mathf.Clamp(CurrentMoraleFloat + num2, _properties.MoraleRange.Minimum, _properties.MoraleRange.Maximum);
				break;
			}
			case MoraleStyle.MoodIsMoraleTarget:
			{
				float num = Mathf.Clamp(CurrentMood, _properties.MoraleRange.Minimum, _properties.MoraleRange.Maximum);
				float num2 = _properties.MoraleTargetSpeed / _timeManager.CurrentDay.HourLength * Time.deltaTime;
				if (CurrentMoraleFloat < num)
				{
					CurrentMoraleFloat = Mathf.Min(CurrentMoraleFloat + num2, num);
				}
				if (CurrentMoraleFloat > num)
				{
					CurrentMoraleFloat = Mathf.Max(CurrentMoraleFloat - num2, num);
				}
				break;
			}
			case MoraleStyle.MoodIsMorale:
				CurrentMoraleFloat = CurrentMood;
				break;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				return;
			}
			int num3 = Mathf.RoundToInt(CurrentMoraleFloat);
			if (num3 != CurrentMorale)
			{
				CurrentMorale = num3;
				UpdateCategory();
				UpdatedEvent.Invoke();
				GameEventDispatcher.Dispatch(GameEventType.AgentMoraleUpdate);
			}
			MoraleEffect[] moraleEffects = MoraleEffects;
			for (int i = 0; i < moraleEffects.Length; i++)
			{
				moraleEffects[i].Update();
			}
		}

		private void OnDestroy()
		{
			_agent.OnDeath.RemoveListener(OnDeath);
			ClearMoraleEffects();
			GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnAgentAddedToPlayerCommunity);
		}

		public void Initialize(Agent agent)
		{
			_agent = agent;
			_agent.OnDeath.AddListener(OnDeath);
			_timeManager = GameManager.TimeManager;
			MoraleEffects = new MoraleEffect[_properties.MoralEffectProperties.Length];
			UpdatedEvent = new UnityEvent();
			CategoryUpdatedEvent = new UnityEvent();
			for (int i = 0; i < MoraleEffects.Length; i++)
			{
				MoraleEffect moraleEffect = _properties.MoralEffectProperties[i];
				MoraleEffect moraleEffect2 = UnityEngine.Object.Instantiate(moraleEffect);
				moraleEffect2.Initialize(agent, moraleEffect);
				MoraleEffects[i] = moraleEffect2;
				moraleEffect2.UpdatedEvent.AddListener(OnMoraleEffectUpdated);
			}
			InitializeMoodAndMorale();
			if (_agent.Community != Community.PlayerCommunity)
			{
				GameEventDispatcher.AddListener(GameEventType.AgentAddedToPlayerCommunity, OnAgentAddedToPlayerCommunity);
			}
		}

		private void InitializeMoodAndMorale()
		{
			CurrentMood = ReturnMoodScore();
			CurrentMorale = CurrentMood;
			CurrentMoraleFloat = CurrentMood;
			UpdateCategory();
		}

		private void UpdateCategory()
		{
			if (TryReturnCategory(out var category, CurrentMorale))
			{
				if (CurrentMoraleCategory != category)
				{
					CurrentMoraleCategory = category;
					ExperienceMultiplier = category.ExperienceMultiplier;
					SpeedMultiplier = category.SpeedMultiplier;
					CategoryUpdatedEvent.Invoke();
				}
			}
			else if (ExperienceMultiplier != 1f || SpeedMultiplier != 1f)
			{
				ExperienceMultiplier = 1f;
				SpeedMultiplier = 1f;
				UnityEngine.Debug.LogException(new NotSupportedException($"Unable to set morale category for morale score {CurrentMorale}"));
				CategoryUpdatedEvent.Invoke();
			}
		}

		private void ClearMoraleEffects()
		{
			for (int i = 0; i < MoraleEffects.Length; i++)
			{
				MoraleEffect obj = MoraleEffects[i];
				obj.UpdatedEvent.RemoveListener(OnMoraleEffectUpdated);
				obj.Destroy();
			}
		}

		private void OnAgentAddedToPlayerCommunity(GameEvent gameEvent)
		{
			if (gameEvent is AgentEvent agentEvent && agentEvent.Agent == _agent)
			{
				InitializeMoodAndMorale();
				UpdatedEvent.Invoke();
				GameEventDispatcher.RemoveListener(GameEventType.AgentAddedToPlayerCommunity, OnAgentAddedToPlayerCommunity);
			}
		}

		private void OnDeath()
		{
			_agent.OnDeath.RemoveListener(OnDeath);
			ClearMoraleEffects();
		}

		private void OnMoraleEffectUpdated()
		{
			UpdatedEvent.Invoke();
			GameEventDispatcher.Dispatch(GameEventType.AgentMoraleUpdate);
		}

		public bool HasNegativeModifier()
		{
			MoraleEffect[] moraleEffects = MoraleEffects;
			foreach (MoraleEffect moraleEffect in moraleEffects)
			{
				if (moraleEffect.IsActive() && moraleEffect.ReturnModifier() < 0)
				{
					return true;
				}
			}
			return false;
		}

		public int ReturnMoraleModifierSum()
		{
			int num = 0;
			MoraleEffect[] moraleEffects = MoraleEffects;
			foreach (MoraleEffect moraleEffect in moraleEffects)
			{
				if (moraleEffect.IsActive())
				{
					num += moraleEffect.ReturnModifier();
				}
			}
			return num;
		}

		public int ReturnMoodScore()
		{
			if (!_properties.SubtractNeed)
			{
				return ReturnMoraleModifierSum();
			}
			return ReturnMoraleModifierSum() - MoraleNeed;
		}

		public bool TryReturnCurrentCategory(out MoraleCategory category)
		{
			int index;
			return _properties.TryReturnCategory(CurrentMorale, MoraleNeed, _agent.Attributes.MaximumDrifterLevel, out category, out index);
		}

		public bool TryReturnCategory(out MoraleCategory category, int score)
		{
			int index;
			return _properties.TryReturnCategory(score, MoraleNeed, _agent.Attributes.MaximumDrifterLevel, out category, out index);
		}

		public bool TryReturnCurrentCategory(out MoraleCategory category, out int index)
		{
			return _properties.TryReturnCategory(CurrentMorale, MoraleNeed, _agent.Attributes.MaximumDrifterLevel, out category, out index);
		}

		public bool TryReturnMoraleEffectByIndex(int propertiesIndex, out MoraleEffect moraleEffect)
		{
			for (int i = 0; i < MoraleEffects.Length; i++)
			{
				moraleEffect = MoraleEffects[i];
				if (moraleEffect.PropertiesIndex == propertiesIndex)
				{
					return true;
				}
			}
			moraleEffect = null;
			return false;
		}
	}
	[Serializable]
	public class MoraleCategory
	{
		public MoraleCategoryId Id;

		[MinMaxRangeInt(0, 100)]
		public RangedInt Size;

		[FormerlySerializedAs("ExpertiseModifier")]
		public float ExperienceMultiplier = 1f;

		public float SpeedMultiplier = 1f;

		public Color Color = Color.white;

		public int MinimumLevel;

		public Sprite Icon;

		[Header("Text")]
		public LocalizedString Name = "";

		public LocalizedString EffectTooltip = "";

		public LocalizedString RangeTooltip = "";

		public bool IsAvailable(int currentLevel)
		{
			return currentLevel >= MinimumLevel;
		}

		public int ReturnCurrentSize(float lerp)
		{
			return Mathf.RoundToInt(Mathf.Lerp(Size.Minimum, Size.Maximum, lerp));
		}

		public int ReturnRelativeSize(int level, int maxLevel, IReadOnlyList<MoraleCategory> moraleCategories, RangedInt moraleRange)
		{
			float lerp = (float)level / (float)maxLevel;
			int num = ReturnCurrentSize(lerp);
			int num2 = ReturnSize(moraleCategories, level, maxLevel);
			int num3 = moraleRange.ReturnSize();
			return Mathf.RoundToInt((float)num / (float)num2 * (float)num3);
		}

		public static int ReturnSize(IReadOnlyList<MoraleCategory> moraleCategories, int currentLevel, int maximumLevel)
		{
			float lerp = (float)currentLevel / (float)maximumLevel;
			int num = 0;
			int count = moraleCategories.Count;
			for (int i = 0; i < count; i++)
			{
				MoraleCategory moraleCategory = moraleCategories[i];
				if (moraleCategory.IsAvailable(currentLevel))
				{
					num += moraleCategory.ReturnCurrentSize(lerp);
				}
			}
			return num;
		}
	}
	public enum MoraleCategoryId
	{
		None,
		Depressed,
		Unhappy,
		Neutral,
		Happy,
		Ecstatic
	}
	public enum MoraleStyle
	{
		MoodIsMorale,
		AddMoodToMorale,
		MoodIsMoraleTarget
	}
	[CreateAssetMenu(menuName = "Flotsam/Agent/Morale/Properties")]
	public class MoraleProperties : ScriptableObject
	{
		[SerializeField]
		private MoraleStyle _style;

		[SerializeField]
		private bool _subtractNeed = true;

		public MoraleEffect[] MoralEffectProperties = new MoraleEffect[0];

		public MoraleCategory[] Categories = new MoraleCategory[0];

		[MinMaxRangeInt(-100, 100)]
		public RangedInt MoraleRange;

		public int MoraleNeedCap = 10;

		[Tooltip("The amount of morale lost/gained per day, when moving to target morale score.")]
		[SerializeField]
		[ConditionalEnumHide("_style", 2, false, HideInInspector = true)]
		private float _moraleTargetSpeed = 10f;

		public MoraleStyle Style => _style;

		public bool SubtractNeed => _subtractNeed;

		public float MoraleTargetSpeed => _moraleTargetSpeed;

		public bool TryReturnCategoryLimits(int currentLevel, int maxLevel, MoraleCategory category, out RangedInt limits)
		{
			int num = MoraleRange.Minimum;
			MoraleRange.ReturnSize();
			for (int i = 0; i < Categories.Length; i++)
			{
				MoraleCategory moraleCategory = Categories[i];
				if (moraleCategory.IsAvailable(currentLevel))
				{
					int num2 = moraleCategory.ReturnRelativeSize(currentLevel, maxLevel, Categories, MoraleRange);
					int num3 = num + num2;
					if (i < Categories.Length - 1)
					{
						num3--;
					}
					num3 = Mathf.Clamp(num3, MoraleRange.Minimum, MoraleRange.Maximum);
					if (moraleCategory == category)
					{
						limits = new RangedInt(num, num3);
						return true;
					}
					num += num2;
				}
			}
			limits = default(RangedInt);
			return false;
		}

		public bool TryReturnCategory(int morale, int currentLevel, int maxLevel, out MoraleCategory category, out int index)
		{
			int num = MoraleRange.Minimum;
			morale = Mathf.Clamp(morale, MoraleRange.Minimum, MoraleRange.Maximum);
			for (index = 0; index < Categories.Length; index++)
			{
				category = Categories[index];
				if (category.IsAvailable(currentLevel))
				{
					int num2 = category.ReturnRelativeSize(currentLevel, maxLevel, Categories, MoraleRange);
					int num3 = num + num2;
					if ((num2 == 0 && morale == num) || (morale >= num && morale < num3) || (num3 == MoraleRange.Maximum && morale == num3))
					{
						return true;
					}
					num = num3;
				}
			}
			category = null;
			return false;
		}
	}
