	[CreateAssetMenu(fileName = "Prototype Scenario", menuName = "Flotsam/Scenarios/Prototype")]
	public class PrototypeScenario : ScenarioBase
	{
		[Serializable]
		public class PersistentData : PersistentDataBase
		{
			public PersistentData(PrototypeScenario instance)
				: base(instance)
			{
			}

			public override ScenarioBase Restore(PrototypeScenario fallbackScenario = null)
			{
				ScenarioBase scenarioBase = base.Restore(fallbackScenario);
				if (scenarioBase == null)
				{
					scenarioBase = fallbackScenario.GetInstance();
					RestoreQueuedWorldTiles(scenarioBase);
				}
				return scenarioBase;
			}
		}

		[SerializeReference]
		[InstantiateSerializeReference]
		private IScenarioTrigger[] _triggers;

		public override void OnFirstStart()
		{
			base.WorldTileProvider.QueueStartTiles();
		}

		protected override void OnStart()
		{
			IScenarioTrigger[] triggers = _triggers;
			for (int i = 0; i < triggers.Length; i++)
			{
				triggers[i].Initialize();
			}
		}

		public override IScenarioPersistentData GetPersistentData()
		{
			return new PersistentData(this);
		}
	}
	public abstract class ScenarioBase : PersistentProperties
	{
		[Serializable]
		public abstract class PersistentDataBase : IScenarioPersistentData
		{
			[OptionalField(VersionAdded = 1)]
			private readonly int _propertiesIndex = -1;

			[OptionalField(VersionAdded = 1)]
			private readonly ScenarioWorldTileProvider.QueuedWorldTilePersistentData[] _queuedWorldTiles;

			[OptionalField(VersionAdded = 2)]
			private readonly List<long> _triggered = new List<long>();

			public int ScenarioIndex => _propertiesIndex;

			public PersistentDataBase(ScenarioBase instance)
			{
				_propertiesIndex = instance.GetIndex();
				IReadOnlyList<ScenarioWorldTileProvider.QueuedWorldTile> queuedWorldTiles = instance._worldTilesProvider.QueuedWorldTiles;
				long[] managedReferenceIds = ManagedReferenceUtility.GetManagedReferenceIds(instance);
				foreach (long num in managedReferenceIds)
				{
					if (ManagedReferenceUtility.GetManagedReference(instance, num) is ScenarioTriggerableBase { WasTriggered: not false })
					{
						_triggered.Add(num);
					}
				}
				if (!queuedWorldTiles.IsNullOrEmpty())
				{
					_queuedWorldTiles = new ScenarioWorldTileProvider.QueuedWorldTilePersistentData[queuedWorldTiles.Count];
					for (int j = 0; j < _queuedWorldTiles.Length; j++)
					{
						_queuedWorldTiles[j] = new ScenarioWorldTileProvider.QueuedWorldTilePersistentData(queuedWorldTiles[j]);
					}
				}
			}

			public virtual ScenarioBase Restore(PrototypeScenario fallbackScenario = null)
			{
				if (GameManager.PersistenceManager.TryReturnPropertiesReference<ScenarioBase>(ScenarioIndex, out var reference))
				{
					ScenarioBase instance = reference.GetInstance();
					instance.Restored = true;
					RestoreQueuedWorldTiles(instance);
					RestoreTriggerables(instance);
					return instance;
				}
				return null;
			}

			protected void RestoreQueuedWorldTiles(ScenarioBase instance)
			{
				if (!((IReadOnlyCollection<ScenarioWorldTileProvider.QueuedWorldTilePersistentData>)(object)_queuedWorldTiles).IsNullOrEmpty())
				{
					instance._worldTilesProvider.Restore(_queuedWorldTiles);
				}
			}

			protected void RestoreTriggerables(ScenarioBase instance)
			{
				if (_triggered.IsNullOrEmpty())
				{
					return;
				}
				foreach (long item in _triggered)
				{
					if (ManagedReferenceUtility.GetManagedReference(instance, item) is ScenarioTriggerableBase scenarioTriggerableBase)
					{
						scenarioTriggerableBase.RestoreWasTriggered();
					}
				}
			}
		}

		[SerializeField]
		private ScenarioBase _successor;

		[SerializeField]
		private ScenarioWorldTileProvider _worldTilesProvider = new ScenarioWorldTileProvider();

		public override Types Type => Types.Scenario;

		protected global::World World { get; private set; }

		public ScenarioWorldTileProvider WorldTileProvider => _worldTilesProvider;

		public bool Restored { get; private set; }

		public virtual void Update()
		{
		}

		public virtual void LateUpdate()
		{
		}

		public new ScenarioBase GetInstance()
		{
			return base.GetInstance() as ScenarioBase;
		}

		public void Start()
		{
			GameManager.WorldManager.World.SetWorldTileProvider(WorldTileProvider);
			OnRegionEntered();
			GameEventDispatcher.AddListener(GameEventType.RegionEntered, OnRegionEntered);
			if (!Restored)
			{
				OnFirstStart();
			}
			QueueGlobalProjects();
			OnStart();
		}

		public virtual void OnFirstStart()
		{
		}

		protected abstract void OnStart();

		public virtual void Destroy()
		{
			GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
		}

		public virtual void QueueWorldTile(TileGeneratorBase worldTile, int indexOffset = 0, int minimumIndex = 0)
		{
			_worldTilesProvider.QueueWorldTile(worldTile, indexOffset, minimumIndex);
		}

		protected virtual void QueueGlobalProjects()
		{
			Community.PlayerCommunity?.QueueGlobalProjects(GameSettings.Instance.ProjectSettings);
		}

		protected virtual void OnRegionEntered(GameEvent gameEvent = null)
		{
			if (GameManager.WorldManager.CurrentRegion.TryReturnScoutingLandmark(out var scoutingLandmark) && scoutingLandmark.ScoutingState < ScoutingState.Rumored)
			{
				scoutingLandmark.SetScoutingState(ScoutingState.Rumored);
			}
		}

		protected void SpawnTownheartAndStartingResources()
		{
			if (Construction.Townheart != null)
			{
				return;
			}
			Vector3 positionTownheart = GameManager.Settings.SessionSettings.StartingScenario.PositionTownheart;
			Buildable buildable = ((!Session.Profile.ActiveRun.TownheartProperties) ? GameManager.Settings.SessionSettings.StartingScenario.Townheart : Session.Profile.ActiveRun.TownheartProperties.Prefab);
			Buildable buildable2 = Buildable.Place(buildable, positionTownheart, Quaternion.identity, 0, instantPlacement: true);
			if (buildable2.TryReturnBuildableExtendable<MooringPoint>(out var buildableExtendable))
			{
				buildableExtendable.SpawnStartingBoat();
			}
			Construction.Townheart = buildable2.ReturnExtendable<Construction>();
			List<CountedItemProperty> startingResources = GameManager.Settings.SessionSettings.StartingScenario.StartingResources;
			for (int i = 0; i < startingResources.Count; i++)
			{
				CountedItemProperty countedItemProperty = startingResources[i];
				for (int j = 0; j < countedItemProperty.Amount; j++)
				{
					Community.PlayerCommunity.SpawnItemToAvailableStorage(countedItemProperty.ItemProperties);
				}
			}
		}

		public bool TryGetSuccessor(out ScenarioBase successor)
		{
			successor = _successor;
			return successor != null;
		}

		public abstract IScenarioPersistentData GetPersistentData();
	}
	[Serializable]
	public class ScenarioTileProvider
	{
		[SerializeReference]
		[InstantiateSerializeReference]
		private IScenarioTriggerableCondition[] _conditions;

		[SerializeField]
		private WorldTileProviderBase _provider;

		[SerializeField]
		private bool _isFallback;

		[SerializeField]
		[ConditionalHide("_isFallback", true)]
		private bool _debugRunOnly;

		public bool TryGetWorldTile(out WorldTile worldTile, global::World world, ILandmarkPicker landmarkPicker)
		{
			worldTile = null;
			if (_debugRunOnly && !Session.Profile.ActiveRun.IsDebugRun)
			{
				return false;
			}
			IScenarioTriggerableCondition[] conditions = _conditions;
			for (int i = 0; i < conditions.Length; i++)
			{
				if (!conditions[i].IsMet())
				{
					return false;
				}
			}
			if (_isFallback)
			{
				if (Session.Profile.ActiveRun.IsDebugRun)
				{
					UnityEngine.Debug.LogError("The next world tile was generated by a fallback ScenarioTileProvider");
				}
				else
				{
					UnityEngine.Debug.LogException(new Exception("The next world tile was generated by a fallback ScenarioTileProvider"));
				}
			}
			return _provider.TryGetNextWorldTile(out worldTile, world, landmarkPicker);
		}
	}
	[Serializable]
	public class ScenarioWorldTileProvider : IWorldTileProvider
	{
		public class QueuedWorldTile
		{
			public TileGeneratorBase Worldtile { get; private set; }

			public int Index { get; private set; }

			public QueuedWorldTile(TileGeneratorBase worldTile, int index)
			{
				Worldtile = worldTile;
				Index = index;
			}
		}

		[Serializable]
		public struct QueuedWorldTilePersistentData
		{
			public int WorldTileIndex;

			public int Index;

			public QueuedWorldTilePersistentData(QueuedWorldTile instance)
			{
				WorldTileIndex = GameManager.PersistenceManager.ReturnPropertiesIndex(instance.Worldtile);
				Index = instance.Index;
			}
		}

		[SerializeField]
		private List<TileGeneratorBase> _startTiles = new List<TileGeneratorBase>();

		[SerializeField]
		private List<ScenarioTileProvider> _tileProviders = new List<ScenarioTileProvider>();

		private readonly List<QueuedWorldTile> _queuedWorldTiles = new List<QueuedWorldTile>();

		public IReadOnlyList<QueuedWorldTile> QueuedWorldTiles => _queuedWorldTiles;

		public void QueueStartTiles()
		{
			foreach (TileGeneratorBase startTile in _startTiles)
			{
				QueueWorldTile(startTile);
			}
		}

		public void QueueWorldTile(TileGeneratorBase WorldTile, int indexOffset = 0, int minimumIndex = 0)
		{
			int num = Mathf.Max(WorldManager.ReturnLastTileIndex() + indexOffset, minimumIndex);
			foreach (QueuedWorldTile queuedWorldTile in _queuedWorldTiles)
			{
				if (queuedWorldTile.Index >= num)
				{
					if (queuedWorldTile.Index == num)
					{
						num++;
					}
					if (num < queuedWorldTile.Index)
					{
						_queuedWorldTiles.Insert(num, new QueuedWorldTile(WorldTile, num));
						return;
					}
				}
			}
			_queuedWorldTiles.Add(new QueuedWorldTile(WorldTile, num));
		}

		public WorldTile GetNextWorldTile(global::World world, ILandmarkPicker landmarkPicker = null)
		{
			if (TryDequeueWorldTile(WorldManager.ReturnLastTileIndex() + 1, out var worldTile))
			{
				return new WorldTile(world.TileProperties.TileGenerator, worldTile);
			}
			if (TryGetWorldTile(out var worldTile2, world, landmarkPicker))
			{
				return worldTile2;
			}
			return null;
		}

		private bool TryDequeueWorldTile(int index, out TileGeneratorBase worldTile)
		{
			if (_queuedWorldTiles.Count > 0)
			{
				QueuedWorldTile queuedWorldTile = _queuedWorldTiles[0];
				if (queuedWorldTile.Index <= index)
				{
					if (queuedWorldTile.Index < index)
					{
						UnityEngine.Debug.LogWarning("Encountered queued world tile with index that is lower than the index of the last active world tile... whoops?!");
					}
					worldTile = queuedWorldTile.Worldtile;
					_queuedWorldTiles.RemoveAt(0);
					return true;
				}
			}
			worldTile = null;
			return false;
		}

		private bool TryGetWorldTile(out WorldTile worldTile, global::World world, ILandmarkPicker landmarkPicker)
		{
			foreach (ScenarioTileProvider tileProvider in _tileProviders)
			{
				if (tileProvider.TryGetWorldTile(out worldTile, world, landmarkPicker))
				{
					return true;
				}
			}
			UnityEngine.Debug.LogException(new Exception("Active scenario was unable to generate next WorldTile."));
			worldTile = null;
			return false;
		}

		public void Restore(QueuedWorldTilePersistentData[] queuedWorldTiles)
		{
			for (int i = 0; i < queuedWorldTiles.Length; i++)
			{
				QueuedWorldTilePersistentData queuedWorldTilePersistentData = queuedWorldTiles[i];
				if (GameManager.PersistenceManager.TryReturnPropertiesReference<TileGeneratorBase>(queuedWorldTilePersistentData.WorldTileIndex, out var reference))
				{
					_queuedWorldTiles.Add(new QueuedWorldTile(reference, queuedWorldTilePersistentData.Index));
				}
				else
				{
					UnityEngine.Debug.LogException(new PersistenceException("Unable to restore QueuedWorldTile!"));
				}
			}
		}
	}
	[CreateAssetMenu(fileName = "Starting Scenario", menuName = "Flotsam/Scenarios/Start")]
	public class StartingScenario : ScenarioBase
	{
		[Serializable]
		public class PersistentData : PersistentDataBase
		{
			private int _triggerIndex = -1;

			public PersistentData(StartingScenario instance)
				: base(instance)
			{
				_triggerIndex = instance._triggerIndex;
			}

			public override ScenarioBase Restore(PrototypeScenario fallbackScenario = null)
			{
				if (base.Restore(fallbackScenario) is StartingScenario startingScenario)
				{
					startingScenario._triggerIndexToRestore = Mathf.Max(1, _triggerIndex);
					return startingScenario;
				}
				return null;
			}
		}

		[SerializeReference]
		[InstantiateSerializeReference]
		private List<ScenarioTriggerableBase> _triggerables = new List<ScenarioTriggerableBase>();

		[SerializeField]
		private ScenarioBase _nextScenario;

		[Header("Editor Settings")]
		[SerializeField]
		[Min(0f)]
		[Tooltip("The amount of drifters that should be spawned when the scenario starts. If 0 the new game panel is triggered.")]
		private int _startingDrifterCount = 3;

		[SerializeField]
		[Min(0f)]
		[Tooltip("The index that should be triggered when the scenario starts. Only triggers if 'Starting Drifter Count' > 0. when 'Triggerables' count <= index, 'Next scenario' will be triggered.")]
		private int _startingTriggerableIndex = 2;

		[SerializeReference]
		[InstantiateSerializeReference]
		[Tooltip("It sometimes can usefull to add triggers to the starting scenario while testing.")]
		private IScenarioTrigger[] _triggers;

		private int _triggerIndex = -1;

		private int _triggerIndexToRestore = -1;

		private ScenarioTriggerableBase _currentTriggerable;

		public override void OnFirstStart()
		{
			if (Session.Profile.ActiveRun.IsDebugRun)
			{
				IScenarioTrigger[] triggers = _triggers;
				for (int i = 0; i < triggers.Length; i++)
				{
					triggers[i].Initialize();
				}
				SpawnTownheartAndStartingResources();
				if (0 < _startingDrifterCount)
				{
					for (int j = 0; j < _startingDrifterCount; j++)
					{
						GameManager.AgentManager.SpawnStartingAgent(AgentDescriptor.CreateInstance());
					}
					if (_startingTriggerableIndex < _triggerables.Count)
					{
						Trigger(_startingTriggerableIndex);
					}
					else
					{
						StoryManager.StartScenario(_nextScenario);
					}
					return;
				}
			}
			else if (Session.Profile.ActiveRun.Saves.Count > 0)
			{
				StoryManager.StartScenario(_nextScenario);
				return;
			}
			GameEventDispatcher.AddListener(GameEventType.NewGamePanelClosed, OnNewGamePanelClosed);
			UnityEngine.Object.Instantiate(GameManager.Settings.SessionSettings.StartingScenario.StartMessage).Initialize();
		}

		protected override void OnStart()
		{
			if (_triggerIndexToRestore >= 0)
			{
				Trigger(_triggerIndexToRestore);
			}
		}

		public override void Destroy()
		{
			GameEventDispatcher.RemoveListener(GameEventType.NewGamePanelClosed, OnNewGamePanelClosed);
			GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnTriggerableScoutTowerRevealDialogueEnded);
			base.Destroy();
		}

		private void TriggerNext()
		{
			int num = _triggerIndex + 1;
			if (num < _triggerables.Count)
			{
				Trigger(num);
			}
			else
			{
				StoryManager.StartScenario(_nextScenario);
			}
		}

		private void Trigger(int index)
		{
			if (index <= _triggerIndex)
			{
				return;
			}
			_triggerIndex = index;
			_currentTriggerable = _triggerables[_triggerIndex];
			if (_currentTriggerable is TriggerableDialogue triggerableDialogue)
			{
				if (triggerableDialogue.TryTrigger())
				{
					triggerableDialogue.EndOfDialogueEvent.AddListener(OnEndOfDialogue);
				}
				else
				{
					TriggerNext();
				}
			}
		}

		private void OnNewGamePanelClosed(GameEvent gameEvent)
		{
			GameEventDispatcher.AddListener(GameEventType.NewGamePanelClosed, OnNewGamePanelClosed);
			TriggerNext();
		}

		private void OnEndOfDialogue(TriggerableDialogue triggerableDialogue)
		{
			triggerableDialogue.EndOfDialogueEvent.RemoveListener(OnEndOfDialogue);
			TriggerNext();
		}

		protected override void QueueGlobalProjects()
		{
			if (base.Restored)
			{
				base.QueueGlobalProjects();
			}
		}

		protected override void OnRegionEntered(GameEvent gameEvent = null)
		{
			base.OnRegionEntered(gameEvent);
			if (gameEvent != null && _currentTriggerable is TriggerableScoutTowerReveal triggerableScoutTowerReveal && triggerableScoutTowerReveal.TryTrigger())
			{
				GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
				GameEventDispatcher.AddListener(GameEventType.DialogueEnded, OnTriggerableScoutTowerRevealDialogueEnded);
			}
		}

		private void OnTriggerableScoutTowerRevealDialogueEnded(GameEvent gameEvent)
		{
			GameEventDispatcher.RemoveListener(GameEventType.DialogueEnded, OnTriggerableScoutTowerRevealDialogueEnded);
			TriggerNext();
		}

		public override IScenarioPersistentData GetPersistentData()
		{
			return new PersistentData(this);
		}
	}
	[Serializable]
	public abstract class ScenarioTriggerableBase
	{
		[SerializeReference]
		[InstantiateSerializeReference]
		private IScenarioTriggerableCondition[] _conditions;

		[SerializeField]
		private bool _isRetriggerable;

		public virtual bool WasTriggered { get; private set; }

		protected bool IsRetriggerable => _isRetriggerable;

		public void Initialize()
		{
			WasTriggered = !_isRetriggerable && (WasTriggered || GetWasTriggered());
		}

		public bool ConditionsAreMet()
		{
			IScenarioTriggerableCondition[] conditions = _conditions;
			for (int i = 0; i < conditions.Length; i++)
			{
				if (!conditions[i].IsMet())
				{
					return false;
				}
			}
			return true;
		}

		public bool TryTrigger(AgentDescriptor actorDescriptor = null)
		{
			if (!WasTriggered && ConditionsAreMet() && Trigger(actorDescriptor))
			{
				WasTriggered = !_isRetriggerable;
				return true;
			}
			return false;
		}

		protected abstract bool Trigger(AgentDescriptor actorDescriptor);

		protected virtual bool GetWasTriggered()
		{
			return false;
		}

		protected void Reset()
		{
			WasTriggered = false;
		}

		internal virtual void RestoreWasTriggered()
		{
			WasTriggered = !_isRetriggerable;
		}
	}
