	[Serializable]
	public class GameStatsCondition : IScenarioTriggerableCondition
	{
		private enum GameStat
		{
			ActorStat
		}

		private enum Condition
		{
			StatIsSmallerThanValue,
			StatIsSmallerThanOrEqualsValue,
			StatIsLargerThanValue,
			StatIsLargerThanOrEqualsValue,
			StatEqualsValue
		}

		[SerializeField]
		private GameStat _stat;

		[SerializeField]
		[ConditionalEnumHide("_stat", 0, false, HideInInspector = true)]
		private ActorType _actorType;

		[SerializeField]
		[ConditionalEnumHide("_stat", 0, false, HideInInspector = true)]
		private ActorStat _actorStat;

		[SerializeField]
		private int _value;

		[SerializeField]
		private Condition _condition;

		public bool IsMet()
		{
			int stat = GetStat();
			switch (_condition)
			{
			case Condition.StatIsSmallerThanValue:
				return stat < _value;
			case Condition.StatIsSmallerThanOrEqualsValue:
				return stat <= _value;
			case Condition.StatIsLargerThanValue:
				return stat > _value;
			case Condition.StatIsLargerThanOrEqualsValue:
				return stat >= _value;
			case Condition.StatEqualsValue:
				return stat == _value;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException(_condition.ToString()));
				return false;
			}
		}

		private int GetStat()
		{
			if (_stat == GameStat.ActorStat)
			{
				return GameStatsManager.GetActorStat(_actorType, _actorStat);
			}
			return 0;
		}
	}
