	[Serializable]
	public class RegionCondition : IScenarioTriggerableCondition
	{
		private enum Mode
		{
			Current,
			CurrentNeighors,
			CurrentAndNeighbors,
			RegionTriggers
		}

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		private WorldRegionType[] _regions;

		[SerializeField]
		private WorldRegionFlags _excludeFlags;

		[SerializeField]
		[Tooltip("Is this condition used for a triggerable that spawns a Landmark?")]
		private bool _isSpawnCondition = true;

		public bool IsMet()
		{
			IWorldRegion region;
			switch (_mode)
			{
			case Mode.Current:
				if (WorldManager.TryReturnCurrentRegion(out region))
				{
					return IsMatch(region);
				}
				return false;
			case Mode.CurrentNeighors:
				if (WorldManager.TryReturnCurrentRegion(out region))
				{
					return HasMatch(region.Neighbors);
				}
				return false;
			case Mode.CurrentAndNeighbors:
				if (WorldManager.TryReturnCurrentRegion(out region))
				{
					if (!IsMatch(region))
					{
						return HasMatch(region.Neighbors);
					}
					return true;
				}
				return false;
			case Mode.RegionTriggers:
				return HasMatch(RegionTriggers.Regions);
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				return false;
			}
		}

		private bool HasMatch(IReadOnlyList<IWorldRegion> regions)
		{
			foreach (IWorldRegion region in regions)
			{
				if (IsMatch(region))
				{
					return true;
				}
			}
			return false;
		}

		private bool IsMatch(IWorldRegion region)
		{
			if ((region.Flags & _excludeFlags) == 0 && _regions.Contains(region.Type))
			{
				if (_isSpawnCondition)
				{
					return region.HasUnscoutedDisabledLandmarks();
				}
				return true;
			}
			return false;
		}
	}
	[Serializable]
	public class RegionNeighborCondition : IScenarioTriggerableCondition
	{
		[SerializeField]
		private WorldRegionType[] _regionTypes;

		[SerializeField]
		private WorldRegionFlags _excludeFlags;

		public bool IsMet()
		{
			if (!WorldManager.TryReturnCurrentRegion(out var region))
			{
				return false;
			}
			foreach (IWorldRegion neighbor in region.Neighbors)
			{
				if (_regionTypes.Contains(neighbor.Type) && (neighbor.Flags & _excludeFlags) == 0)
				{
					return true;
				}
			}
			return false;
		}
	}
	[Serializable]
	public class VitalCondition : IScenarioTriggerableCondition
	{
		[SerializeField]
		private VitalType _vital;

		[SerializeField]
		[Tooltip("The condition is met when the value of the vital is higher than the threshold.")]
		private float _threshold;

		[SerializeField]
		[Min(1f)]
		[Tooltip("The number of drifters that must be over the threshold.")]
		private int _drifterCount = 1;

		public bool IsMet()
		{
			int num = 0;
			foreach (Agent agent in Community.PlayerCommunity.Agents)
			{
				if (_threshold < GetVital(agent))
				{
					num++;
				}
			}
			return _drifterCount <= num;
		}

		private float GetVital(Agent agent)
		{
			switch (_vital)
			{
			case VitalType.Hunger:
				return agent.Vitals.Hunger.Amount;
			case VitalType.Thirst:
				return agent.Vitals.Thirst.Amount;
			case VitalType.Pollution:
				return agent.Vitals.Pollution.Level;
			default:
				UnityEngine.Debug.LogException(new NotImplementedException($"No implementation for VitalType.{_vital}"));
				return 0f;
			}
		}
	}
