	[Serializable]
	public class RegionEnteredTrigger : IScenarioTrigger
	{
		[Tooltip("Cooldown between triggering in seconds")]
		[SerializeField]
		private float _cooldown = 900f;

		[SerializeReference]
		[SubclassSelector]
		private IScenarioTriggerableCondition[] _conditions;

		[Tooltip("Triggered the first time a region with a scout landmark is entered.")]
		[SerializeReference]
		[SubclassSelector]
		private ScenarioTriggerableBase _firstScoutableRegionTriggerable;

		[Tooltip("When triggered the quest triggerables will be traversed first. Only one quest triggerable can be triggered at a time.")]
		[SerializeReference]
		[SubclassSelector]
		private TriggerableQuest[] _triggerableQuests;

		[Tooltip("When no quest triggerable was triggered, this list is traversed in order. Only one triggerable can be triggered at a time.")]
		[SerializeReference]
		[SubclassSelector]
		private ScenarioTriggerableBase[] _triggerables;

		[NonSerialized]
		private float _lastTriggerTimeStamp;

		public void Initialize()
		{
			GameEventDispatcher.AddListener(GameEventType.RegionEntered, OnRegionEntered);
		}

		public void Uninitialize()
		{
			GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
		}

		private void OnRegionEntered(GameEvent gameEvent)
		{
			if (!(gameEvent is MapEvent mapEvent) || (_firstScoutableRegionTriggerable != null && IsFirstScoutableRegion(mapEvent.Region) && _firstScoutableRegionTriggerable.TryTrigger()) || !mapEvent.Region.HasUnscoutedDisabledLandmarks() || mapEvent.Region.StartQuest())
			{
				return;
			}
			float currentPlayTime = GameManager.TimeManager.CurrentPlayTime;
			if (currentPlayTime - _lastTriggerTimeStamp < _cooldown)
			{
				return;
			}
			IScenarioTriggerableCondition[] conditions = _conditions;
			for (int i = 0; i < conditions.Length; i++)
			{
				if (!conditions[i].IsMet())
				{
					return;
				}
			}
			if (Trigger())
			{
				_lastTriggerTimeStamp = currentPlayTime;
			}
		}

		private bool Trigger()
		{
			TriggerableQuest[] triggerableQuests = _triggerableQuests;
			for (int i = 0; i < triggerableQuests.Length; i++)
			{
				if (triggerableQuests[i].TryTrigger())
				{
					return true;
				}
			}
			ScenarioTriggerableBase[] triggerables = _triggerables;
			for (int i = 0; i < triggerables.Length; i++)
			{
				if (triggerables[i].TryTrigger())
				{
					return true;
				}
			}
			return false;
		}

		private bool IsFirstScoutableRegion(IWorldRegion region)
		{
			if (region.WorldTile.Index != 0 || !region.TryReturnScoutingLandmark(out var scoutingLandmark))
			{
				return false;
			}
			foreach (IWorldRegion neighbor in region.Neighbors)
			{
				if ((neighbor.Flags & WorldRegionFlags.Visited) != WorldRegionFlags.None && region.TryReturnScoutingLandmark(out scoutingLandmark))
				{
					return false;
				}
			}
			return true;
		}
	}
	[Serializable]
	public class RegionTriggers : IScenarioTrigger
	{
		[Header("Region Entered")]
		[SerializeField]
		[Tooltip("Triggers when first region is entered, irregardless of 'Region Entered Trigger Conditions'")]
		private SerializeReferencePickingList<ScenarioTriggerableBase> _firstEnteredRegionTriggerables;

		[SerializeReference]
		[InstantiateSerializeReference]
		private TriggerableQuest[] _regionEnteredTriggerableQuests;

		[Header("Scout Region")]
		[SerializeField]
		private SerializeReferencePickingList<ScenarioTriggerableBase> _firstScoutedRegionTriggerables;

		[SerializeField]
		private int _firstScoutedRegionMaxTriggerCount = 2;

		[SerializeReference]
		[InstantiateSerializeReference]
		[FormerlySerializedAs("_regionEnteredTriggerConditions")]
		private IScenarioTriggerableCondition[] _regionEnteredFallbackTriggerConditions;

		[Header("Default")]
		[SerializeReference]
		[InstantiateSerializeReference]
		private TriggerableQuest[] _triggerableQuests;

		[SerializeReference]
		[InstantiateSerializeReference]
		[FormerlySerializedAs("_triggerables")]
		private ScenarioTriggerableBase[] _spawningTriggerables;

		public static List<IWorldRegion> Regions { get; private set; } = new List<IWorldRegion>(8);

		public void Initialize()
		{
			TriggerableQuest[] triggerableQuests = _triggerableQuests;
			for (int i = 0; i < triggerableQuests.Length; i++)
			{
				triggerableQuests[i].Initialize();
			}
			GameEventDispatcher.AddListener(GameEventType.RegionEntered, OnRegionEntered);
			GameEventDispatcher.AddListener(GameEventType.ScoutRegion, OnScoutRegion);
			GameEventDispatcher.AddListener(GameEventType.RegionScouted, OnRegionScouted);
		}

		public void Uninitialize()
		{
			GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
			GameEventDispatcher.RemoveListener(GameEventType.ScoutRegion, OnScoutRegion);
			GameEventDispatcher.RemoveListener(GameEventType.RegionScouted, OnRegionScouted);
		}

		private void OnRegionEntered(GameEvent gameEvent)
		{
			if (!(gameEvent is MapEvent mapEvent))
			{
				return;
			}
			if (mapEvent.Region.IsFirstWithFlags(WorldRegionFlags.Visited))
			{
				PickAndTrigger(_firstEnteredRegionTriggerables);
			}
			else
			{
				if (!WorldManager.TryReturnCurrentRegion(out var region))
				{
					return;
				}
				Regions.Clear();
				Regions.Add(region);
				TriggerableQuest[] regionEnteredTriggerableQuests = _regionEnteredTriggerableQuests;
				for (int i = 0; i < regionEnteredTriggerableQuests.Length; i++)
				{
					if (regionEnteredTriggerableQuests[i].TryTrigger())
					{
						return;
					}
				}
				if (ConditionsAreMet(_regionEnteredFallbackTriggerConditions))
				{
					TriggerDefault();
				}
			}
		}

		private void OnScoutRegion(GameEvent gameEvent)
		{
			if (gameEvent is ScoutingEvent scoutingEvent)
			{
				IWorldRegion region;
				if (scoutingEvent.Region.IsFirstWithFlags(WorldRegionFlags.Scouted) && !_firstScoutedRegionTriggerables.IsEmpty())
				{
					PickAndTrigger(_firstScoutedRegionTriggerables, _firstScoutedRegionMaxTriggerCount);
				}
				else if (WorldManager.TryReturnCurrentRegion(out region))
				{
					AgentDescriptor actorDescriptor = ((scoutingEvent.Agent != null) ? scoutingEvent.Agent.Descriptor : null);
					Regions.Clear();
					Regions.AddRange(region.Neighbors);
					TriggerDefault(actorDescriptor);
				}
			}
		}

		private void OnRegionScouted(GameEvent gameEvent)
		{
			_ = gameEvent is ScoutingEvent;
		}

		private void TriggerDefault(AgentDescriptor actorDescriptor = null)
		{
			TriggerableQuest[] triggerableQuests = _triggerableQuests;
			for (int i = 0; i < triggerableQuests.Length && !triggerableQuests[i].TryTrigger(actorDescriptor); i++)
			{
			}
			ScenarioTriggerableBase[] spawningTriggerables = _spawningTriggerables;
			for (int i = 0; i < spawningTriggerables.Length; i++)
			{
				spawningTriggerables[i].TryTrigger(actorDescriptor);
			}
		}

		private void PickAndTrigger<T>(PickingListBase<T> pickingList, int max = 1) where T : ScenarioTriggerableBase
		{
			int num = 0;
			int count = pickingList.Count;
			while (0 < count--)
			{
				if (pickingList.TryPickItem(out var pickedItem) && pickedItem.TryTrigger())
				{
					num++;
					if (max <= num)
					{
						break;
					}
				}
			}
		}

		private bool ConditionsAreMet(IScenarioTriggerableCondition[] conditions)
		{
			for (int i = 0; i < conditions.Length; i++)
			{
				if (!conditions[i].IsMet())
				{
					return false;
				}
			}
			return true;
		}
	}
	[Serializable]
	public class TownWeightTrigger : IScenarioTrigger
	{
		[SerializeField]
		private ScenarioTriggerableBase[] _triggerables;

		public void Initialize()
		{
			ScenarioTriggerableBase[] triggerables = _triggerables;
			for (int i = 0; i < triggerables.Length; i++)
			{
				if (!triggerables[i].WasTriggered)
				{
					GameEventDispatcher.AddListener(GameEventType.WeightTierUpdated, OnWeightTierUpdated);
					break;
				}
			}
		}

		public void Uninitialize()
		{
			GameEventDispatcher.RemoveListener(GameEventType.WeightTierUpdated, OnWeightTierUpdated);
		}

		private void TryUninitialize()
		{
			ScenarioTriggerableBase[] triggerables = _triggerables;
			for (int i = 0; i < triggerables.Length; i++)
			{
				if (!triggerables[i].WasTriggered)
				{
					return;
				}
			}
			GameEventDispatcher.AddListener(GameEventType.WeightTierUpdated, OnWeightTierUpdated);
		}

		private void OnWeightTierUpdated(GameEvent gameEvent)
		{
			if (!(gameEvent is WeightEvent))
			{
				return;
			}
			ScenarioTriggerableBase[] triggerables = _triggerables;
			for (int i = 0; i < triggerables.Length; i++)
			{
				if (triggerables[i].TryTrigger())
				{
					TryUninitialize();
				}
			}
		}
	}
	[CreateAssetMenu(fileName = "Tutorial Scenario", menuName = "Flotsam/Scenarios/Tutorial")]
	public class TutorialScenario : ScenarioBase
	{
		[Serializable]
		public class PersistentData : PersistentDataBase
		{
			private readonly int _questsCompletedCount;

			public PersistentData(TutorialScenario instance)
				: base(instance)
			{
				_questsCompletedCount = instance._questsCompletedCount;
			}

			public void Restore(ScenarioBase scenario)
			{
				if (scenario is TutorialScenario tutorialScenario)
				{
					tutorialScenario._questsCompletedCount = _questsCompletedCount;
				}
			}
		}

		[SerializeReference]
		[InstantiateSerializeReference]
		private List<IScenarioTrigger> _triggers = new List<IScenarioTrigger>();

		[SerializeField]
		[Tooltip("This list does not handle triggering them, it's only used to see if we completed them all. To trigger them, please use the Triggers list.")]
		private List<QuestProperties> _tutorialsToComplete = new List<QuestProperties>();

		[SerializeField]
		private ScenarioBase _nextScenario;

		[SerializeField]
		private List<AgentProfile> _firstDriftersPool = new List<AgentProfile>();

		[SerializeField]
		[Tooltip("The maximum durationof the tutorial in days. After the Max Duration the next scenario will be triggered")]
		private int _maxDuration = 25;

		[NonSerialized]
		private int _questsCompletedCount;

		public override void OnFirstStart()
		{
			SpawnTownheartAndStartingResources();
			base.WorldTileProvider.QueueStartTiles();
			SpawnStartingDrifters();
		}

		protected override void OnStart()
		{
			if (AreTutorialQuestsCompleted())
			{
				StartNextScenario();
				return;
			}
			GameEventDispatcher.AddListener(GameEventType.CompletedQuestsUpdated, OnCompletedQuestsUpdated);
			GameEventDispatcher.AddListener(GameEventType.DayEnded, OnDayEnded);
			foreach (IScenarioTrigger trigger in _triggers)
			{
				trigger.Initialize();
			}
			if (!base.Restored)
			{
				GameEventDispatcher.Dispatch(GameEventType.NarrativeStart);
			}
		}

		public override void Destroy()
		{
			GameEventDispatcher.RemoveListener(GameEventType.RegionEntered, OnRegionEntered);
			GameEventDispatcher.RemoveListener(GameEventType.QuestCompleted, OnCompletedQuestsUpdated);
			GameEventDispatcher.RemoveListener(GameEventType.DayEnded, OnDayEnded);
			base.Destroy();
		}

		public override void QueueWorldTile(TileGeneratorBase worldTile, int indexOffset = 0, int minimumIndex = 0)
		{
			base.WorldTileProvider.QueueWorldTile(worldTile, indexOffset, minimumIndex);
		}

		private void SpawnStartingDrifters()
		{
			int i = 0;
			int inhabitants = GameManager.Settings.SessionSettings.StartingScenario.Inhabitants;
			if (!_firstDriftersPool.IsNullOrEmpty())
			{
				i = Mathf.Min(_firstDriftersPool.Count, inhabitants);
				if (_firstDriftersPool.Count <= inhabitants)
				{
					SpawnAllDrifters();
				}
				else
				{
					SpawnRandomDrifters(inhabitants);
				}
			}
			for (; i < inhabitants; i++)
			{
				GameManager.AgentManager.SpawnStartingAgent(AgentDescriptor.CreateInstance());
			}
		}

		private void SpawnAllDrifters()
		{
			foreach (AgentProfile item in _firstDriftersPool)
			{
				GameManager.AgentManager.SpawnStartingAgent(item.GetDescriptor());
			}
		}

		private void SpawnRandomDrifters(int count)
		{
			using ListPool<AgentProfile>.List list = ListPool<AgentProfile>.Get(_firstDriftersPool);
			for (int i = 0; i < count; i++)
			{
				int randomIndex = list.GetRandomIndex();
				AgentProfile agentProfile = list[randomIndex];
				GameManager.AgentManager.SpawnStartingAgent(agentProfile.GetDescriptor());
				list.RemoveAtSwapBack(randomIndex);
			}
		}

		private void OnCompletedQuestsUpdated(GameEvent gameEvent)
		{
			if (AreTutorialQuestsCompleted())
			{
				StartNextScenario();
			}
		}

		private void OnDayEnded(GameEvent gameEvent)
		{
			if (gameEvent is DayEvent dayEvent && dayEvent.Days.Count > _maxDuration)
			{
				UnityEngine.Debug.LogException(new Exception($"The tutorial surpassed its maximum duarion of {_maxDuration} days."));
				StartNextScenario();
			}
			else
			{
				OnCompletedQuestsUpdated(null);
			}
		}

		private void StartNextScenario()
		{
			Destroy();
			if (_nextScenario != null)
			{
				StoryManager.StartScenario(_nextScenario);
			}
			else
			{
				UnityEngine.Debug.LogException(new Exception("Unable to start next scenario because its is NULL"));
			}
		}

		private bool AreTutorialQuestsCompleted()
		{
			if (_tutorialsToComplete.IsNullOrEmpty())
			{
				return true;
			}
			foreach (QuestProperties item in _tutorialsToComplete)
			{
				if (!StoryManager.IsQuestCompleted(item))
				{
					return false;
				}
			}
			return true;
		}

		public override IScenarioPersistentData GetPersistentData()
		{
			return new PersistentData(this);
		}
	}
	[Serializable]
	public class ActorVariable : QuestVariableBase
	{
		[SerializeField]
		private DialogueContext.ActorType _actorType;

		[SerializeField]
		private AgentProfile _actorProfile;

		public override QuestVariableType Type => QuestVariableType.Actor;

		public DialogueContext.ActorType ActorType => _actorType;

		public ActorVariable()
		{
		}

		private ActorVariable(ActorVariable other)
			: base(other)
		{
			_actorType = other._actorType;
			_actorProfile = other._actorProfile;
		}

		public override object Clone()
		{
			return new ActorVariable(this);
		}

		public override bool Initialize()
		{
			return true;
		}

		public override bool Validate()
		{
			return true;
		}

		protected override T Get<T>()
		{
			AgentProfile actorProfile = _actorProfile;
			if (actorProfile is T)
			{
				return (T)(object)((actorProfile is T) ? actorProfile : null);
			}
			AgentDescriptor descriptor = _actorProfile.GetDescriptor();
			if (descriptor is T)
			{
				return (T)(object)((descriptor is T) ? descriptor : null);
			}
			return default(T);
		}

		public bool TryGetActorDescriptor(DialogueContext.ActorType actorType, out AgentDescriptor actorDescriptor)
		{
			actorDescriptor = ((actorType == _actorType && _actorProfile != null) ? _actorProfile.GetDescriptor() : null);
			return actorDescriptor != null;
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			if (_actorProfile == null)
			{
				UnityEngine.Debug.LogError($"Actor variable conditions for quest '{questProperties}' are not met, Actor Profile is NULL!");
				return false;
			}
			return true;
		}

		public override bool TryGetPersistentData(out IPersistentData persistentData)
		{
			persistentData = null;
			return false;
		}

		public override bool TryRestorePersistentData(IPersistentData persistentData)
		{
			persistentData = null;
			return false;
		}
	}
