	[Serializable]
	public class LandmarkVariable : QuestLandmarkVariableBase
	{
		public enum Mode
		{
			FindOrPick,
			FindOnWorldTile
		}

		[SerializeField]
		private LandmarkBehaviourProviderReference _landmark;

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		[ConditionalEnumHide("_mode", 0, true)]
		private bool _tryToFindLandmark = true;

		[Header("Spawning")]
		[SerializeReference]
		[ConditionalEnumHide("_mode", 0, true)]
		[SubclassSelector]
		private ILandmarkPickerSettings _spawnSettings = new LandmarkPicker.Settings();

		[SerializeField]
		[ConditionalEnumHide("_mode", 1, true)]
		[QuestVariable(QuestVariableType.WorldTile)]
		private int _worldTileVariable;

		public LandmarkVariable()
		{
		}

		public LandmarkVariable(LandmarkVariable other)
			: base(other)
		{
			_landmark = other._landmark;
			_mode = other._mode;
			_tryToFindLandmark = other._tryToFindLandmark;
			_spawnSettings = other._spawnSettings;
			_worldTileVariable = other._worldTileVariable;
		}

		public override void SetOwningQuest(Quest owningQuest)
		{
			base.SetOwningQuest(owningQuest);
			_spawnSettings.SetOwningQuest(owningQuest);
		}

		protected override LandmarkSpawner GetLandmarkSpawner()
		{
			switch (_mode)
			{
			case Mode.FindOrPick:
			{
				LandmarkSpawner landmarkSpawner;
				if (_tryToFindLandmark)
				{
					landmarkSpawner = GameManager.WorldManager.World.GetNearestLandmarkOfType(_landmark);
					if (landmarkSpawner != null)
					{
						return landmarkSpawner;
					}
				}
				if (_spawnSettings.Spawn(out landmarkSpawner, _landmark))
				{
					return landmarkSpawner;
				}
				break;
			}
			case Mode.FindOnWorldTile:
			{
				if (!base.OwningQuest.TryGetVariableValue<WorldTile>(_worldTileVariable, out var value))
				{
					break;
				}
				foreach (LandmarkSpawner landmark in value.Landmarks)
				{
					if (_landmark.ReturnIsLandmarkBehaviour(landmark.LandmarkBehaviour))
					{
						return landmark;
					}
				}
				break;
			}
			}
			UnityEngine.Debug.LogException(new Exception("Unable to initialize Landmark variable '" + base.Name + "'"));
			return null;
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			return _spawnSettings.CanSpawn();
		}

		public override object Clone()
		{
			return new LandmarkVariable(this);
		}
	}
	[Serializable]
	public class POIVariable : QuestVariableBase
	{
		public enum SpawnMode
		{
			Distance,
			Triangulation
		}

		[Serializable]
		private struct LandmarkBehaviourProviderReferenceArray
		{
			public LandmarkBehaviourProviderReference[] Array;
		}

		[SerializeField]
		private PointOfInterestProperties _poiProperties;

		[SerializeField]
		private SpawnMode _spawnMode;

		[Header("Spawn Settings")]
		[Tooltip("The distance from the town the Point of Interest will be spawned at on the X-Axis.")]
		[SerializeField]
		[ConditionalEnumHide("_spawnMode", 0, true)]
		[Min(0f)]
		private float _distanceX = 1500f;

		[Tooltip("The maximum distance the Point of Interest will be spawned at on the Y-Axis, relative to the town position")]
		[SerializeField]
		[ConditionalEnumHide("_spawnMode", 0, true)]
		[Min(0f)]
		private float _distanceY = 500f;

		[Tooltip("Landmarks used for triangulation.")]
		[SerializeField]
		[ConditionalEnumHide("_spawnMode", 1, true)]
		[Wrapper("Array")]
		private LandmarkBehaviourProviderReferenceArray _landmarks;

		[Tooltip("The radius in which a position will be generated relative to the position generated using Distance X and Distance Y")]
		[SerializeField]
		[Min(0f)]
		private float _radius = 250f;

		[NonSerialized]
		private PointOfInterestSpawner _spawner;

		public override QuestVariableType Type => QuestVariableType.PointOfInterest;

		public POIVariable()
		{
		}

		private POIVariable(POIVariable other)
			: base(other)
		{
			_poiProperties = other._poiProperties;
			_spawnMode = other._spawnMode;
			_distanceX = other._distanceX;
			_distanceY = other._distanceY;
			_landmarks = other._landmarks;
			_radius = other._radius;
		}

		public override object Clone()
		{
			return new POIVariable(this);
		}

		public override bool Initialize()
		{
			global::World world = GameManager.WorldManager.World;
			_spawner = world.GetNearestPOIOfType(_poiProperties);
			if (_spawner != null)
			{
				return true;
			}
			switch (_spawnMode)
			{
			case SpawnMode.Distance:
				return world.TrySpawnPointOfInterest(out _spawner, _poiProperties, _distanceX, _distanceY);
			case SpawnMode.Triangulation:
			{
				Vector3 zero = Vector3.zero;
				int num = 0;
				LandmarkBehaviourProviderReference[] array = _landmarks.Array;
				foreach (LandmarkBehaviourProviderReference landmarkBehaviourProviderReference in array)
				{
					if (TryGetLandmarkSpawner(out var landmarkSpawner, landmarkBehaviourProviderReference))
					{
						zero += landmarkSpawner.WorldPosition;
						num++;
					}
					else
					{
						UnityEngine.Debug.LogException(new Exception($"Unable to find '{landmarkBehaviourProviderReference}' for POI triangulation"));
					}
				}
				if (0 < num)
				{
					return world.TrySpawnPointOfInterest(out _spawner, _poiProperties, zero / num);
				}
				return false;
			}
			default:
				UnityEngine.Debug.LogException(new NotImplementedException());
				return false;
			}
		}

		public override bool Validate()
		{
			if (IsReferencedByActiveObjective())
			{
				if (_spawner != null)
				{
					return _spawner.WorldTile.IsActive;
				}
				return false;
			}
			return true;
		}

		protected override T Get<T>()
		{
			if (_spawner == null)
			{
				Initialize();
			}
			PointOfInterestSpawner spawner = _spawner;
			if (spawner is T)
			{
				return (T)(object)((spawner is T) ? spawner : null);
			}
			PointOfInterestProperties poiProperties = _poiProperties;
			if (poiProperties is T)
			{
				return (T)(object)((poiProperties is T) ? poiProperties : null);
			}
			return default(T);
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			if (_spawner == null)
			{
				UnityEngine.Debug.LogError($"POI variable conditions for quest '{questProperties}' are not met, POI spawner is NULL!");
				return false;
			}
			return true;
		}

		private bool TryGetLandmarkSpawner(out LandmarkSpawner landmarkSpawner, LandmarkBehaviourProviderReference landmarkBehaviourReference)
		{
			landmarkSpawner = GameManager.WorldManager.World.GetNearestLandmarkOfType(landmarkBehaviourReference);
			return landmarkSpawner != null;
		}

		public override bool TryGetPersistentData(out IPersistentData persistentData)
		{
			persistentData = null;
			return false;
		}

		public override bool TryRestorePersistentData(IPersistentData persistentData)
		{
			return false;
		}
	}
	[Serializable]
	public abstract class QuestLandmarkVariableBase : QuestVariableBase
	{
		[Serializable]
		public class PersistentData : IPersistentData
		{
			private uint _id;

			private LandmarkSpawner.PersistentReference _reference;

			public uint ID => _id;

			public LandmarkSpawner.PersistentReference Reference => _reference;

			public PersistentData(QuestLandmarkVariableBase questLandmarkVariableBase)
			{
				_ = questLandmarkVariableBase._landmarkSpawner.Region;
				_id = questLandmarkVariableBase.Id;
				_reference = questLandmarkVariableBase._landmarkSpawner.GetPersistentReference();
			}
		}

		[NonSerialized]
		protected LandmarkSpawner _landmarkSpawner;

		[NonSerialized]
		private PersistentData _persistentData;

		public override QuestVariableType Type => QuestVariableType.Landmark;

		public QuestLandmarkVariableBase()
		{
		}

		public QuestLandmarkVariableBase(QuestLandmarkVariableBase other)
			: base(other)
		{
		}

		public override bool Initialize()
		{
			if (_landmarkSpawner == null)
			{
				_landmarkSpawner = GetLandmarkSpawner();
			}
			return _landmarkSpawner != null;
		}

		public override bool Validate()
		{
			if (IsReferencedByActiveObjective())
			{
				if (_landmarkSpawner != null)
				{
					return _landmarkSpawner.WorldTile.IsActive;
				}
				return false;
			}
			return true;
		}

		public override void Dispose()
		{
			_landmarkSpawner?.Dispose();
			_landmarkSpawner = null;
		}

		protected override T Get<T>()
		{
			if (_landmarkSpawner == null && !TryRestore())
			{
				_landmarkSpawner = GetLandmarkSpawner();
			}
			LandmarkSpawner landmarkSpawner = _landmarkSpawner;
			if (landmarkSpawner is T)
			{
				return (T)(object)((landmarkSpawner is T) ? landmarkSpawner : null);
			}
			return default(T);
		}

		protected abstract LandmarkSpawner GetLandmarkSpawner();

		public override bool TryGetPersistentData(out IPersistentData persistentData)
		{
			if (_landmarkSpawner == null)
			{
				persistentData = null;
				return false;
			}
			persistentData = new PersistentData(this);
			return true;
		}

		public override bool TryRestorePersistentData(IPersistentData persistentData)
		{
			if (persistentData.ID == base.Id)
			{
				_persistentData = persistentData as PersistentData;
				if (_persistentData == null)
				{
					UnityEngine.Debug.LogException(new Exception("Unable to restore QuestLandmarkVariable.PersistentData, cast failed."));
				}
				return true;
			}
			return false;
		}

		protected virtual bool TryRestore()
		{
			if (_persistentData == null)
			{
				return false;
			}
			if (_persistentData.Reference.TryGet(out _landmarkSpawner))
			{
				return true;
			}
			UnityEngine.Debug.LogException(new Exception("Unable to restore landmark variable."));
			_persistentData = null;
			return false;
		}
	}
