	[Serializable]
	public abstract class QuestVariableBase : ICloneable
	{
		public interface IPersistentData
		{
			uint ID { get; }
		}

		[SerializeField]
		[UnityEngine.UI.Extensions.ReadOnly]
		private uint _id;

		[SerializeField]
		private string _name;

		private ListPool<QuestObjectiveBase>.List _referencingObjectives;

		public abstract QuestVariableType Type { get; }

		public string Name => _name;

		public uint Id => _id;

		public Quest OwningQuest { get; private set; }

		public QuestVariableBase()
		{
		}

		public QuestVariableBase(QuestVariableBase other)
		{
			_id = other._id;
			_name = other._name;
		}

		public virtual void SetOwningQuest(Quest quest)
		{
			OwningQuest = quest;
		}

		public void ClearReferencingObjectives()
		{
			_referencingObjectives?.Dispose();
		}

		public abstract bool Initialize();

		public abstract bool Validate();

		public virtual void Dispose()
		{
		}

		public T Get<T>(QuestObjectiveBase objective)
		{
			T result = Get<T>();
			if (objective != null)
			{
				if (_referencingObjectives == null)
				{
					_referencingObjectives = ListPool<QuestObjectiveBase>.Get();
				}
				_referencingObjectives.AddUnique(objective);
			}
			return result;
		}

		protected abstract T Get<T>();

		public virtual void Set<T>(T value)
		{
			UnityEngine.Debug.Log(new NotImplementedException());
		}

		public bool IsReferencedByActiveObjective()
		{
			if (_referencingObjectives.IsNullOrEmpty())
			{
				return false;
			}
			foreach (QuestObjectiveBase referencingObjective in _referencingObjectives)
			{
				if (referencingObjective.IsActive && !referencingObjective.IsOptional && !referencingObjective.IsCompleted())
				{
					return true;
				}
			}
			return false;
		}

		public abstract bool ConditionsAreMet(QuestProperties questProperties);

		public abstract object Clone();

		public abstract bool TryGetPersistentData(out IPersistentData persistentData);

		public abstract bool TryRestorePersistentData(IPersistentData persistentData);

		public virtual void RestoreReferences()
		{
		}
	}
	[Serializable]
	public class QuestVariableReference
	{
		[SerializeField]
		private QuestProperties _questProperties;

		[SerializeField]
		private int _variableId;

		public T GetValue<T>(Quest quest = null) where T : class
		{
			if (TryGetValue<T>(out var value))
			{
				return value;
			}
			return null;
		}

		public bool TryGetValue<T>(out T value, Quest quest = null) where T : class
		{
			if (quest == null)
			{
				using (ListPool<Quest>.List list = ListPool<Quest>.Get())
				{
					foreach (Quest activeQuest in GameManager.StoryManager.ActiveQuests)
					{
						if (activeQuest.Properties == _questProperties)
						{
							list.Add(activeQuest);
						}
					}
					if (list.Count == 0)
					{
						UnityEngine.Debug.LogException(new ArgumentException($"Unable to get quest variable value; No active quest found with quest properties '{_questProperties}'"));
					}
					else
					{
						if (1 >= list.Count)
						{
							return list[0].TryGetVariableValue<T>(_variableId, out value);
						}
						UnityEngine.Debug.LogException(new ArgumentException($"Unable to get quest variable value; Multiple active quests found with quest properties '{_questProperties}'"));
					}
					value = null;
					return false;
				}
			}
			return quest.TryGetVariableValue<T>(_variableId, out value);
		}
	}
