	[Serializable]
	public class RescueLandmarkVariable : QuestLandmarkVariableBase
	{
		public enum Mode
		{
			AgentProfile,
			QuestGiver,
			QuestVariable,
			Any
		}

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		[ConditionalEnumHide("_mode", 0, true)]
		private AgentProfile _actorProfile;

		[SerializeField]
		[ConditionalEnumHide("_mode", 2, true)]
		[QuestVariable(QuestVariableType.Actor)]
		private QuestVariableReference _questVariable;

		[Header("Spawning")]
		[SerializeReference]
		[SubclassSelector]
		private ILandmarkPickerSettings _spawnSettings = new LandmarkPicker.Settings();

		public RescueLandmarkVariable()
		{
		}

		public RescueLandmarkVariable(RescueLandmarkVariable other)
			: base(other)
		{
			_mode = other._mode;
			_actorProfile = other._actorProfile;
			_questVariable = other._questVariable;
			_spawnSettings = other._spawnSettings;
		}

		public override void SetOwningQuest(Quest owningQuest)
		{
			base.SetOwningQuest(owningQuest);
			_spawnSettings.SetOwningQuest(owningQuest);
		}

		protected override LandmarkSpawner GetLandmarkSpawner()
		{
			LandmarkSpawner landmarkSpawner = null;
			AgentDescriptor actorDescriptor;
			if (TryGetActorProfile(out var actorProfile))
			{
				actorProfile.Spawn(_spawnSettings, out landmarkSpawner);
			}
			else if (TryGetActorDescriptor(out actorDescriptor))
			{
				_spawnSettings.SpawnDrifter(out landmarkSpawner, actorDescriptor);
			}
			if (landmarkSpawner == null)
			{
				UnityEngine.Debug.LogException(new Exception("RescueLandmarkVariable was unable to spawn rescue landmark."));
			}
			return landmarkSpawner;
		}

		protected override T Get<T>()
		{
			if (TryGetActorProfile(out var actorProfile) && actorProfile is T)
			{
				return (T)(object)((actorProfile is T) ? actorProfile : null);
			}
			if (TryGetActorDescriptor(out var actorDescriptor) && actorDescriptor is T)
			{
				return (T)(object)((actorDescriptor is T) ? actorDescriptor : null);
			}
			return base.Get<T>();
		}

		public bool TryGetActorProfile(out AgentProfile actorProfile)
		{
			actorProfile = null;
			switch (_mode)
			{
			case Mode.AgentProfile:
				actorProfile = _actorProfile;
				break;
			case Mode.QuestGiver:
				if (base.OwningQuest != null && base.OwningQuest.QuestGiver != null)
				{
					actorProfile = base.OwningQuest.QuestGiver.AgentProfile;
				}
				break;
			case Mode.QuestVariable:
				actorProfile = _questVariable.GetValue<AgentProfile>(base.OwningQuest);
				break;
			case Mode.Any:
				UnityEngine.Debug.LogException(new NotImplementedException());
				break;
			}
			return actorProfile != null;
		}

		private bool TryGetActorDescriptor(out AgentDescriptor actorDescriptor)
		{
			actorDescriptor = null;
			switch (_mode)
			{
			case Mode.AgentProfile:
				if ((bool)_actorProfile)
				{
					actorDescriptor = _actorProfile.GetDescriptor();
				}
				break;
			case Mode.QuestGiver:
				if (base.OwningQuest != null)
				{
					actorDescriptor = base.OwningQuest.QuestGiver;
				}
				break;
			case Mode.QuestVariable:
				actorDescriptor = _questVariable.GetValue<AgentDescriptor>(base.OwningQuest);
				break;
			case Mode.Any:
				UnityEngine.Debug.LogException(new NotImplementedException());
				break;
			}
			return actorDescriptor != null;
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			return _spawnSettings.CanSpawn();
		}

		public override object Clone()
		{
			return new RescueLandmarkVariable(this);
		}
	}
	[Serializable]
	public class ScoutingLandmarkVariable : QuestLandmarkVariableBase
	{
		public enum Mode
		{
			SpecificLandmark,
			RegionType,
			CurrentRegion,
			LandmarkVariableRegion
		}

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		[ConditionalEnumHide("_mode", 0, true)]
		private LandmarkBehaviourProviderReference _specificLandmark;

		[SerializeField]
		[ConditionalEnumHide("_mode", 1, true)]
		private WorldRegionType _regionType;

		[SerializeField]
		[ConditionalEnumHide("_mode", 3, true)]
		[QuestVariable(QuestVariableType.Landmark)]
		private int _landmarkVariable;

		[NonSerialized]
		private LandmarkSpawner _scoutingLandmark;

		[NonSerialized]
		private float _distanceToScoutingLandmark;

		public ScoutingLandmarkVariable()
		{
		}

		public ScoutingLandmarkVariable(ScoutingLandmarkVariable other)
			: base(other)
		{
			_mode = other._mode;
			_specificLandmark = other._specificLandmark;
			_regionType = other._regionType;
			_landmarkVariable = other._landmarkVariable;
		}

		protected override LandmarkSpawner GetLandmarkSpawner()
		{
			Vector3 townheartWorldPosition = GameManager.WorldManager.World.TownheartWorldPosition;
			IWorldRegion currentRegion = GameManager.WorldManager.CurrentRegion;
			_scoutingLandmark = null;
			_distanceToScoutingLandmark = float.MaxValue;
			switch (_mode)
			{
			case Mode.SpecificLandmark:
				InitializeSpecificLandmark(_specificLandmark, townheartWorldPosition, currentRegion);
				break;
			case Mode.RegionType:
				InitializeRegionType(_regionType, townheartWorldPosition, currentRegion);
				break;
			case Mode.CurrentRegion:
				InitializeCurrentRegion(currentRegion);
				break;
			case Mode.LandmarkVariableRegion:
				base.OwningQuest.GetVariableValue<LandmarkSpawner>(_landmarkVariable)?.Region.TryReturnScoutingLandmark(out _scoutingLandmark);
				break;
			}
			return _scoutingLandmark;
		}

		private void InitializeSpecificLandmark(ILandmarkBehaviourProvider specificLandmark, Vector3 townheartPosition, IWorldRegion currentRegion)
		{
			using ListPool<LandmarkSpawner>.List list = ListPool<LandmarkSpawner>.Get();
			GameManager.WorldManager.World.GetAllScoutingLandmarks(list);
			foreach (LandmarkSpawner item in list)
			{
				if (specificLandmark == null || specificLandmark.ReturnIsLandmarkBehaviour(item.LandmarkBehaviour))
				{
					TrySetTargetLandmark(item, townheartPosition, currentRegion);
				}
			}
		}

		private void InitializeRegionType(WorldRegionType regionType, Vector3 townheartPosition, IWorldRegion currentRegion)
		{
			using ListPool<LandmarkSpawner>.List list = ListPool<LandmarkSpawner>.Get();
			GameManager.WorldManager.World.GetAllScoutingLandmarks(list);
			foreach (LandmarkSpawner item in list)
			{
				if (item.RegionType == regionType)
				{
					TrySetTargetLandmark(item, townheartPosition, currentRegion);
				}
			}
		}

		private void InitializeCurrentRegion(IWorldRegion currentRegion)
		{
			currentRegion.TryReturnScoutingLandmark(out _scoutingLandmark);
		}

		private bool TrySetTargetLandmark(LandmarkSpawner landmark, Vector3 townheartPosition, IWorldRegion currentRegion)
		{
			Vector3 vector = landmark.WorldPosition - townheartPosition;
			if (vector.x < 0f && landmark.Region != currentRegion)
			{
				return false;
			}
			float sqrMagnitude = vector.sqrMagnitude;
			if (sqrMagnitude < _distanceToScoutingLandmark)
			{
				_distanceToScoutingLandmark = sqrMagnitude;
				_scoutingLandmark = landmark;
				return true;
			}
			return false;
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			UnityEngine.Debug.LogException(new NotImplementedException());
			return true;
		}

		public override object Clone()
		{
			return new ScoutingLandmarkVariable(this);
		}
	}
	[Serializable]
	public class WorldTileVariable : QuestVariableBase
	{
		[SerializeField]
		private WorldTileProviderBase _tileProvider;

		[NonSerialized]
		private WorldTile _worldTile;

		public override QuestVariableType Type => QuestVariableType.WorldTile;

		public WorldTileVariable()
		{
		}

		public WorldTileVariable(WorldTileVariable other)
			: base(other)
		{
			_tileProvider = other._tileProvider;
		}

		public override object Clone()
		{
			return new WorldTileVariable(this);
		}

		public override bool Initialize()
		{
			return true;
		}

		public override bool Validate()
		{
			if (_worldTile != null)
			{
				return _worldTile.IsActive;
			}
			return true;
		}

		protected override T Get<T>()
		{
			if (_worldTile == null)
			{
				_worldTile = GetWorldTile();
			}
			WorldTile worldTile = _worldTile;
			if (worldTile is T)
			{
				return (T)(object)((worldTile is T) ? worldTile : null);
			}
			return default(T);
		}

		private WorldTile GetWorldTile()
		{
			if (GameManager.WorldManager == null || GameManager.WorldManager.World == null)
			{
				return null;
			}
			global::World world = GameManager.WorldManager.World;
			foreach (WorldTile tile in world.Tiles)
			{
				if (_tileProvider.Contains(tile.SubTileGeneratorPrefab))
				{
					_worldTile = tile;
					break;
				}
			}
			_worldTile = _tileProvider.GetNextWorldTile(world);
			world.AddNextTile(_worldTile, synchronous: true);
			return _worldTile;
		}

		public override bool ConditionsAreMet(QuestProperties questProperties)
		{
			return true;
		}

		public override bool TryGetPersistentData(out IPersistentData persistentData)
		{
			persistentData = null;
			return false;
		}

		public override bool TryRestorePersistentData(IPersistentData persistentData)
		{
			return false;
		}
	}
