namespace UnityEngine.Rendering.RenderGraphModule
{
	public static class RenderGraphBlitUtility
	{
		private class BlitMaterialPassData
		{
			public int sourceTexturePropertyID;

			public TextureHandle source;

			public TextureHandle destination;

			public Vector2 scale;

			public Vector2 offset;

			public Material material;

			public int shaderPass;

			public MaterialPropertyBlock propertyBlock;

			public int sourceSlice;

			public int destinationSlice;

			public int numSlices;

			public int sourceMip;

			public int destinationMip;

			public int numMips;

			public RenderGraphUtils.FullScreenGeometryType geometry;

			public int sourceSlicePropertyID;

			public int sourceMipPropertyID;

			public int scaleBiasPropertyID;

			public UnityAction<MaterialPropertyBlock> materialCallback;
		}

		private static MaterialPropertyBlock s_PropertyBlock = new MaterialPropertyBlock();

		private static Vector4 s_BlitScaleBias = default(Vector4);

		private static Mesh s_TriangleMesh;

		private static Mesh s_QuadMesh;

		public static void AddBlitPass(RenderGraph graph, RenderGraphUtils.BlitMaterialParameters blitParameters, UnityAction<IUnsafeRenderGraphBuilder> builderCallback, UnityAction<MaterialPropertyBlock> materialCallback, string passName = "Blit Pass Utility w. Material", [CallerFilePath] string file = "", [CallerLineNumber] int line = 0)
		{
			TextureDesc textureDesc = graph.GetTextureDesc(in blitParameters.source);
			TextureDesc textureDesc2 = graph.GetTextureDesc(in blitParameters.destination);
			int num = (int)math.log2(math.max(math.max(textureDesc.width, textureDesc.height), textureDesc.slices)) + 1;
			int num2 = (int)math.log2(math.max(math.max(textureDesc2.width, textureDesc2.height), textureDesc2.slices)) + 1;
			if (blitParameters.numSlices == -1)
			{
				blitParameters.numSlices = textureDesc2.slices - blitParameters.destinationSlice;
			}
			if (blitParameters.numSlices > textureDesc2.slices - blitParameters.destinationSlice || (blitParameters.sourceSlice != -1 && blitParameters.numSlices > textureDesc.slices - blitParameters.sourceSlice))
			{
				throw new ArgumentException("BlitPass: " + passName + " attempts to blit too many slices. The pass will be skipped.");
			}
			if (blitParameters.numMips == -1)
			{
				blitParameters.numMips = num2 - blitParameters.destinationMip;
			}
			if (blitParameters.numMips > num2 - blitParameters.destinationMip || (blitParameters.sourceMip != -1 && blitParameters.numMips > num - blitParameters.sourceMip))
			{
				throw new ArgumentException("BlitPass: " + passName + " attempts to blit too many mips. The pass will be skipped.");
			}
			BlitMaterialPassData passData;
			using IUnsafeRenderGraphBuilder unsafeRenderGraphBuilder = graph.AddUnsafePass<BlitMaterialPassData>(passName, out passData, file, line);
			passData.sourceTexturePropertyID = blitParameters.sourceTexturePropertyID;
			passData.source = blitParameters.source;
			passData.destination = blitParameters.destination;
			passData.scale = blitParameters.scale;
			passData.offset = blitParameters.offset;
			passData.material = blitParameters.material;
			passData.shaderPass = blitParameters.shaderPass;
			passData.propertyBlock = blitParameters.propertyBlock;
			passData.sourceSlice = blitParameters.sourceSlice;
			passData.destinationSlice = blitParameters.destinationSlice;
			passData.numSlices = blitParameters.numSlices;
			passData.sourceMip = blitParameters.sourceMip;
			passData.destinationMip = blitParameters.destinationMip;
			passData.numMips = blitParameters.numMips;
			passData.geometry = blitParameters.geometry;
			passData.sourceSlicePropertyID = blitParameters.sourceSlicePropertyID;
			passData.sourceMipPropertyID = blitParameters.sourceMipPropertyID;
			passData.scaleBiasPropertyID = blitParameters.scaleBiasPropertyID;
			passData.materialCallback = materialCallback;
			unsafeRenderGraphBuilder.UseTexture(in blitParameters.source);
			unsafeRenderGraphBuilder.UseTexture(in blitParameters.destination, AccessFlags.Write);
			builderCallback?.Invoke(unsafeRenderGraphBuilder);
			unsafeRenderGraphBuilder.SetRenderFunc(delegate(BlitMaterialPassData data, UnsafeGraphContext context)
			{
				BlitMaterialRenderFunc(data, context);
			});
		}

		private static void BlitMaterialRenderFunc(BlitMaterialPassData data, UnsafeGraphContext context)
		{
			s_BlitScaleBias.x = data.scale.x;
			s_BlitScaleBias.y = data.scale.y;
			s_BlitScaleBias.z = data.offset.x;
			s_BlitScaleBias.w = data.offset.y;
			CommandBuffer nativeCommandBuffer = CommandBufferHelpers.GetNativeCommandBuffer(context.cmd);
			if (data.propertyBlock == null)
			{
				data.propertyBlock = s_PropertyBlock;
			}
			data.propertyBlock.SetTexture(data.sourceTexturePropertyID, data.source);
			if (data.sourceSlice == -1)
			{
				data.propertyBlock.SetInt(data.sourceSlicePropertyID, 0);
			}
			if (data.sourceMip == -1)
			{
				data.propertyBlock.SetInt(data.sourceMipPropertyID, 0);
			}
			data.propertyBlock.SetVector(data.scaleBiasPropertyID, s_BlitScaleBias);
			data.materialCallback?.Invoke(data.propertyBlock);
			for (int i = 0; i < data.numSlices; i++)
			{
				for (int j = 0; j < data.numMips; j++)
				{
					if (data.sourceSlice != -1)
					{
						data.propertyBlock.SetInt(data.sourceSlicePropertyID, data.sourceSlice + i);
					}
					if (data.sourceMip != -1)
					{
						data.propertyBlock.SetInt(data.sourceMipPropertyID, data.sourceMip + j);
					}
					context.cmd.SetRenderTarget(data.destination, data.destinationMip + j, CubemapFace.Unknown, data.destinationSlice + i);
					switch (data.geometry)
					{
					case RenderGraphUtils.FullScreenGeometryType.Mesh:
						DrawQuadMesh(nativeCommandBuffer, data.material, data.shaderPass, data.propertyBlock);
						break;
					case RenderGraphUtils.FullScreenGeometryType.ProceduralQuad:
						DrawQuad(nativeCommandBuffer, data.material, data.shaderPass, data.propertyBlock);
						break;
					case RenderGraphUtils.FullScreenGeometryType.ProceduralTriangle:
						DrawTriangle(nativeCommandBuffer, data.material, data.shaderPass, data.propertyBlock);
						break;
					}
				}
			}
		}

		internal static void DrawTriangle(CommandBuffer cmd, Material material, int shaderPass, MaterialPropertyBlock propertyBlock)
		{
			if (SystemInfo.graphicsShaderLevel < 30)
			{
				cmd.DrawMesh(GetTriangleMesh(), Matrix4x4.identity, material, 0, shaderPass, propertyBlock);
			}
			else
			{
				cmd.DrawProcedural(Matrix4x4.identity, material, shaderPass, MeshTopology.Triangles, 3, 1, propertyBlock);
			}
		}

		internal static void DrawQuadMesh(CommandBuffer cmd, Material material, int shaderPass, MaterialPropertyBlock propertyBlock)
		{
			cmd.DrawMesh(GetQuadMesh(), Matrix4x4.identity, material, 0, shaderPass, propertyBlock);
		}

		internal static void DrawQuad(CommandBuffer cmd, Material material, int shaderPass, MaterialPropertyBlock propertyBlock)
		{
			if (SystemInfo.graphicsShaderLevel < 30)
			{
				cmd.DrawMesh(GetQuadMesh(), Matrix4x4.identity, material, 0, shaderPass, propertyBlock);
			}
			else
			{
				cmd.DrawProcedural(Matrix4x4.identity, material, shaderPass, MeshTopology.Quads, 4, 1, propertyBlock);
			}
		}

		private static Mesh GetTriangleMesh()
		{
			if (SystemInfo.graphicsShaderLevel < 30)
			{
				if (!s_TriangleMesh)
				{
					float z = -1f;
					if (SystemInfo.usesReversedZBuffer)
					{
						z = 1f;
					}
					s_TriangleMesh = new Mesh();
					s_TriangleMesh.vertices = GetFullScreenTriangleVertexPosition(z);
					s_TriangleMesh.uv = GetFullScreenTriangleTexCoord();
					s_TriangleMesh.triangles = new int[3] { 0, 1, 2 };
				}
				return s_TriangleMesh;
			}
			throw new NotSupportedException();
		}

		private static Mesh GetQuadMesh()
		{
			if (!s_QuadMesh)
			{
				float z = -1f;
				if (SystemInfo.usesReversedZBuffer)
				{
					z = 1f;
				}
				s_QuadMesh = new Mesh();
				s_QuadMesh.vertices = GetQuadVertexPosition(z);
				s_QuadMesh.uv = GetQuadTexCoord();
				s_QuadMesh.triangles = new int[6] { 0, 1, 2, 0, 2, 3 };
			}
			return s_QuadMesh;
		}

		private static Vector3[] GetFullScreenTriangleVertexPosition(float z)
		{
			Vector3[] array = new Vector3[3];
			for (int i = 0; i < 3; i++)
			{
				Vector2 vector = new Vector2((i << 1) & 2, i & 2);
				array[i] = new Vector3(vector.x * 2f - 1f, vector.y * 2f - 1f, z);
			}
			return array;
		}

		private static Vector2[] GetFullScreenTriangleTexCoord()
		{
			Vector2[] array = new Vector2[3];
			for (int i = 0; i < 3; i++)
			{
				if (SystemInfo.graphicsUVStartsAtTop)
				{
					array[i] = new Vector2((i << 1) & 2, 1f - (float)(i & 2));
				}
				else
				{
					array[i] = new Vector2((i << 1) & 2, i & 2);
				}
			}
			return array;
		}

		private static Vector3[] GetQuadVertexPosition(float z)
		{
			Vector3[] array = new Vector3[4];
			for (uint num = 0u; num < 4; num++)
			{
				uint num2 = num >> 1;
				uint num3 = num & 1;
				float x = num2;
				float y = (1 - (num2 + num3)) & 1;
				array[num] = new Vector3(x, y, z);
			}
			return array;
		}

		private static Vector2[] GetQuadTexCoord()
		{
			Vector2[] array = new Vector2[4];
			for (uint num = 0u; num < 4; num++)
			{
				uint num2 = num >> 1;
				uint num3 = num & 1;
				float x = num2;
				float num4 = (num2 + num3) & 1;
				if (SystemInfo.graphicsUVStartsAtTop)
				{
					num4 = 1f - num4;
				}
				array[num] = new Vector2(x, num4);
			}
			return array;
		}
	}
