	public static class Extensions
	{
		public static void Navigate(this BaseEventData eventData, GameObject go)
		{
			if (go != null && go.activeInHierarchy)
			{
				eventData.selectedObject = go;
			}
		}

		public static void Navigate(this BaseEventData eventData, Selectable selectable)
		{
			if (selectable != null && selectable.IsActive())
			{
				eventData.selectedObject = selectable.gameObject;
			}
		}

		public static void AddTrigger(this EventTrigger eventTrigger, EventTriggerType eventTriggerType, UnityAction<BaseEventData> listener)
		{
			List<EventTrigger.Entry> triggers = eventTrigger.triggers;
			if (!EvenTrigger_GetTrigger(triggers, eventTriggerType, out var trigger))
			{
				trigger = new EventTrigger.Entry
				{
					eventID = eventTriggerType
				};
				triggers.Add(trigger);
			}
			trigger.callback.AddListener(listener);
		}

		public static void RemoveTrigger(this EventTrigger eventTrigger, EventTriggerType eventTriggerType, UnityAction<BaseEventData> listener)
		{
			if (EvenTrigger_GetTrigger(eventTrigger.triggers, eventTriggerType, out var trigger))
			{
				trigger.callback.RemoveListener(listener);
			}
		}

		public static void Clear(this EventTrigger eventTrigger)
		{
			List<EventTrigger.Entry> triggers = eventTrigger.triggers;
			foreach (EventTrigger.Entry item in triggers)
			{
				item.callback.RemoveAllListeners();
			}
			triggers.Clear();
		}

		private static bool EvenTrigger_GetTrigger(List<EventTrigger.Entry> triggers, EventTriggerType eventTriggerType, out EventTrigger.Entry trigger)
		{
			for (int i = 0; i < triggers.Count; i++)
			{
				trigger = triggers[i];
				if (trigger.eventID == eventTriggerType)
				{
					return true;
				}
			}
			trigger = null;
			return false;
		}

		public static void ResetTriggers(this Selectable selectable)
		{
			Animator animator = selectable.animator;
			AnimationTriggers animationTriggers = selectable.animationTriggers;
			animator.ResetTrigger(animationTriggers.normalTrigger);
			animator.ResetTrigger(animationTriggers.highlightedTrigger);
			animator.ResetTrigger(animationTriggers.pressedTrigger);
			animator.ResetTrigger(animationTriggers.selectedTrigger);
			animator.ResetTrigger(animationTriggers.disabledTrigger);
		}

		public static void SetNavigationMode(this Selectable selectable, Navigation.Mode mode)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.mode = mode;
				selectable.navigation = navigation;
			}
		}

		public static void SetSelectOnUp(this Selectable selectable, Selectable selectOnUp)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.mode = Navigation.Mode.Explicit;
				navigation.selectOnUp = selectOnUp;
				selectable.navigation = navigation;
			}
		}

		public static void SetSelectOnRight(this Selectable selectable, Selectable selectOnRight)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.mode = Navigation.Mode.Explicit;
				navigation.selectOnRight = selectOnRight;
				selectable.navigation = navigation;
			}
		}

		public static void SetSelectOnDown(this Selectable selectable, Selectable selectOnDown)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.mode = Navigation.Mode.Explicit;
				navigation.selectOnDown = selectOnDown;
				selectable.navigation = navigation;
			}
		}

		public static void SetSelectOnLeft(this Selectable selectable, Selectable selectOnLeft)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.mode = Navigation.Mode.Explicit;
				navigation.selectOnLeft = selectOnLeft;
				selectable.navigation = navigation;
			}
		}

		public static void ClearNavigation(this Selectable selectable)
		{
			if ((bool)selectable)
			{
				Navigation navigation = selectable.navigation;
				navigation.selectOnUp.SetSelectOnDown(null);
				navigation.selectOnUp = null;
				navigation.selectOnRight.SetSelectOnLeft(null);
				navigation.selectOnRight = null;
				navigation.selectOnDown.SetSelectOnUp(null);
				navigation.selectOnDown = null;
				navigation.selectOnLeft.SetSelectOnRight(null);
				navigation.selectOnLeft = null;
				selectable.navigation = navigation;
			}
		}
	}
	public class ScrollRectSelectionScroller : MonoBehaviour
	{
		public enum Mode
		{
			EventSystem,
			Provider
		}

		public interface IProvider
		{
			GameObject SelectedGameObject { get; }

			bool Reset => false;
		}

		[SerializeField]
		private ScrollRect _scrollRect;

		[SerializeField]
		private Mode _mode;

		[SerializeField]
		[ConditionalEnumHide("_mode", 1, false, HideInInspector = true)]
		[InterfaceReference(typeof(IProvider))]
		private Object _provider;

		[SerializeField]
		[Tooltip("should the selected object be centered in the viewport? (If possible based on the bounds of the content)")]
		private bool _center;

		[SerializeField]
		[ConditionalHide("_center", Inverse = true)]
		private Vector2 _padding = Vector2.zero;

		[SerializeField]
		private Easing _easing;

		[SerializeField]
		[ConditionalEnumHide("_easing", 0, false, Inverse = true)]
		private float _easingDuration = 1f;

		[SerializeField]
		[ConditionalEnumHide("_easing", 0, false, Inverse = true)]
		private bool _easingUsesUnscaledTime = true;

		[SerializeField]
		[Tooltip("The input types for which this SelectableGroup should be initialized.")]
		private InputFlags _supportedInputTypes = InputFlags.Joystick;

		private RectTransform _viewport;

		private RectTransform _content;

		private GameObject _currentSelectedGameObject;

		private Coroutine _easingRoutine;

		private RectTransformAnchoredPositionTweener _tweener;

		private Vector2 _contentMin;

		private Vector2 _contentMax;

		private IProvider _providerReference;

		private void Awake()
		{
			if (_scrollRect == null)
			{
				_scrollRect = GetComponent<ScrollRect>();
			}
			_viewport = _scrollRect.viewport;
			_content = _scrollRect.content;
			_providerReference = _provider as IProvider;
		}

		private void OnEnable()
		{
			if ((bool)_scrollRect.horizontalScrollbar)
			{
				_scrollRect.horizontalScrollbar.numberOfSteps = 0;
			}
			if ((bool)_scrollRect.verticalScrollbar)
			{
				_scrollRect.verticalScrollbar.numberOfSteps = 0;
			}
			UpdateCurrentSelectedGameObject();
		}

		private void LateUpdate()
		{
			UpdateCurrentSelectedGameObject();
		}

		public void SnapToGameObject(GameObject go)
		{
			SetCurrentSelectedGameObject(go, Easing.None);
		}

		private void UpdateCurrentSelectedGameObject()
		{
			if ((FlotsamInputManager.ActiveInput & _supportedInputTypes) == 0)
			{
				return;
			}
			switch (_mode)
			{
			case Mode.EventSystem:
			{
				EventSystem current = EventSystem.current;
				if ((bool)current)
				{
					SetCurrentSelectedGameObject(current.currentSelectedGameObject, _easing);
				}
				break;
			}
			case Mode.Provider:
				SetCurrentSelectedGameObject(_providerReference.SelectedGameObject, (!_providerReference.Reset) ? _easing : Easing.None);
				break;
			}
		}

		private void SetCurrentSelectedGameObject(GameObject go, Easing easing)
		{
			if (!(go == null) && !(go == _currentSelectedGameObject) && go.transform.IsChildOf(_content))
			{
				ScrollToGameObject(go, (!(_currentSelectedGameObject == null)) ? easing : Easing.None);
				_currentSelectedGameObject = go;
			}
		}

		private void ScrollToGameObject(GameObject go, Easing easing)
		{
			RectTransform other = go.transform as RectTransform;
			Rect rect = _viewport.InverseTransformRect(other);
			Rect rect2 = _viewport.rect;
			Vector2 anchoredPosition = _content.anchoredPosition;
			if (!_center)
			{
				rect2.min += _padding;
				rect2.size -= _padding * 2f;
			}
			UpdateScrollBounds(_viewport.rect, _content, ref _contentMin, ref _contentMax);
			if (_scrollRect.horizontal)
			{
				if (_center)
				{
					anchoredPosition.x += rect2.center.x - rect.center.x;
				}
				else if (rect.width < rect2.width && rect.x < rect2.x)
				{
					anchoredPosition.x += rect2.x - rect.x;
				}
				else if (rect2.xMax < rect.xMax)
				{
					anchoredPosition.x += rect2.xMax - rect.xMax;
				}
				anchoredPosition.x = Mathf.Clamp(anchoredPosition.x, _contentMin.x, _contentMax.x);
			}
			if (_scrollRect.vertical)
			{
				if (_center)
				{
					anchoredPosition.y += rect2.center.y - rect.center.y;
				}
				else if (rect.height < rect2.height && rect.y < rect2.y)
				{
					anchoredPosition.y += rect2.y - rect.y;
				}
				else if (rect2.yMax < rect.yMax)
				{
					anchoredPosition.y += rect2.yMax - rect.yMax;
				}
				anchoredPosition.y = Mathf.Clamp(anchoredPosition.y, _contentMin.y, _contentMax.y);
			}
			if (easing == Easing.None)
			{
				_content.anchoredPosition = anchoredPosition;
				return;
			}
			if (_easingRoutine != null)
			{
				Tweener.StopTween(_easingRoutine);
			}
			if (_tweener == null)
			{
				_tweener = new RectTransformAnchoredPositionTweener(_content, anchoredPosition);
			}
			else
			{
				_tweener.Initialize(_content, anchoredPosition);
			}
			_easingRoutine = Tweener.StartTween(_easingDuration, easing, _easingUsesUnscaledTime, _tweener);
		}

		private void UpdateScrollBounds(Rect view, RectTransform content, ref Vector2 min, ref Vector2 max)
		{
			Rect rect = _viewport.InverseTransformRect(_content);
			if (rect.width <= view.width)
			{
				max.x = (min.x = view.width * content.pivot.x - content.anchorMin.x * view.width);
			}
			else
			{
				max.x = rect.width * content.pivot.x - content.anchorMin.x * view.width;
				min.x = max.x - rect.width + view.width;
			}
			if (rect.height <= view.height)
			{
				max.y = (min.y = view.height * content.pivot.y - content.anchorMin.y * view.height);
				return;
			}
			max.y = rect.height * content.pivot.y - content.anchorMin.y * view.height;
			min.y = max.y - rect.height + view.height;
		}
	}
}
namespace UnityEngine.UI.Extensions
{
	[RequireComponent(typeof(VerticalLayoutGroup), typeof(ContentSizeFitter), typeof(ToggleGroup))]
	[AddComponentMenu("UI/Extensions/Accordion/Accordion Group")]
	public class Accordion : MonoBehaviour
	{
		public enum Transition
		{
			Instant,
			Tween
		}

		[SerializeField]
		private Transition m_Transition;

		[SerializeField]
		private float m_TransitionDuration = 0.3f;

		[SerializeField]
		private SelectableGroup m_SelectableGroup;

		[SerializeField]
		private RewiredAction m_CloseAction;

		private List<AccordionElement> _elements;

		public Transition transition
		{
			get
			{
				return m_Transition;
			}
			set
			{
				m_Transition = value;
			}
		}

		public float transitionDuration
		{
			get
			{
				return m_TransitionDuration;
			}
			set
			{
				m_TransitionDuration = value;
			}
		}

		public SelectableGroup SelectableGroup => m_SelectableGroup;

		private void OnEnable()
		{
			Initialize();
		}

		private void LateUpdate()
		{
			if (!m_CloseAction.GetButtonDown())
			{
				return;
			}
			foreach (AccordionElement element in _elements)
			{
				if (element.isOn)
				{
					element.isOn = false;
				}
			}
		}

		public void Initialize()
		{
			if (_elements == null)
			{
				_elements = new List<AccordionElement>(base.transform.childCount);
			}
			else
			{
				_elements.Clear();
			}
			GetComponentsInChildren(_elements);
		}

		public void ToggleParent(Transform transform, bool instantTransition = false)
		{
			foreach (AccordionElement element in _elements)
			{
				element.ToggleParent(transform, instantTransition);
			}
		}
	}
	[RequireComponent(typeof(RectTransform), typeof(LayoutElement))]
	[AddComponentMenu("UI/Extensions/Accordion/Accordion Element")]
	public class AccordionElement : Toggle
	{
		[NonSerialized]
		private readonly TweenRunner<FloatTween> m_FloatTweenRunner;

		[SerializeField]
		private float m_MinHeight = 18f;

		[SerializeField]
		private SelectableGroup m_SelectableGroup;

		private Accordion m_Accordion;

		private RectTransform m_RectTransform;

		private LayoutElement m_LayoutElement;

		public SelectableGroup SelectableGroup => m_SelectableGroup;

		protected AccordionElement()
		{
			if (m_FloatTweenRunner == null)
			{
				m_FloatTweenRunner = new TweenRunner<FloatTween>();
			}
			m_FloatTweenRunner.Init(this);
		}

		protected override void Awake()
		{
			base.Awake();
			toggleTransition = ToggleTransition.None;
			m_Accordion = base.gameObject.GetComponentInParent<Accordion>();
			m_RectTransform = base.transform as RectTransform;
			m_LayoutElement = base.gameObject.GetComponent<LayoutElement>();
			onValueChanged.AddListener(OnValueChanged);
			UpdateGroup();
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			if ((bool)m_LayoutElement && base.isOn)
			{
				m_LayoutElement.preferredHeight = GetExpandedHeight();
			}
		}

		public void ToggleParent(Transform child, bool instantTransition = false)
		{
			if (child.IsChildOf(base.transform))
			{
				ToggleOn(instantTransition);
			}
		}

		public void OnValueChanged(bool state)
		{
			DoTransition(state, (m_Accordion != null) ? m_Accordion.transition : Accordion.Transition.Instant);
		}

		internal void ToggleOn(bool instantTransition = false)
		{
			if (!base.isOn || instantTransition)
			{
				if ((bool)m_Accordion)
				{
					LayoutRebuilder.ForceRebuildLayoutImmediate(m_Accordion.transform as RectTransform);
				}
				SetIsOnWithoutNotify(value: true);
				DoTransition(open: true, (!instantTransition && !(m_Accordion == null)) ? m_Accordion.transition : Accordion.Transition.Instant);
			}
		}

		internal void UpdateGroup()
		{
			if (base.group == null)
			{
				base.group = GetComponentInParent<ToggleGroup>();
			}
		}

		private void DoTransition(bool open, Accordion.Transition transition)
		{
			if (m_LayoutElement == null)
			{
				return;
			}
			switch (transition)
			{
			case Accordion.Transition.Instant:
				if (open)
				{
					m_LayoutElement.preferredHeight = GetExpandedHeight();
				}
				else
				{
					m_LayoutElement.preferredHeight = m_MinHeight;
				}
				break;
			case Accordion.Transition.Tween:
				if (open)
				{
					StartTween(m_MinHeight, GetExpandedHeight());
				}
				else
				{
					StartTween(m_RectTransform.rect.height, m_MinHeight);
				}
				break;
			}
			if ((bool)m_Accordion.SelectableGroup && (bool)m_SelectableGroup)
			{
				if (open)
				{
					m_Accordion.SelectableGroup.Addchild(this, m_SelectableGroup);
				}
				else
				{
					m_Accordion.SelectableGroup.RemoveChild(m_SelectableGroup);
				}
			}
		}

		private float GetExpandedHeight()
		{
			if (m_LayoutElement == null)
			{
				return m_MinHeight;
			}
			float preferredHeight = m_LayoutElement.preferredHeight;
			m_LayoutElement.preferredHeight = -1f;
			float preferredHeight2 = LayoutUtility.GetPreferredHeight(m_RectTransform);
			m_LayoutElement.preferredHeight = preferredHeight;
			return preferredHeight2;
		}

		private void StartTween(float startFloat, float targetFloat)
		{
			float duration = ((m_Accordion != null) ? m_Accordion.transitionDuration : 0.3f);
			FloatTween info = new FloatTween
			{
				duration = duration,
				startFloat = startFloat,
				targetFloat = targetFloat
			};
			info.AddOnChangedCallback(SetHeight);
			info.ignoreTimeScale = true;
			m_FloatTweenRunner.StartTween(info);
		}

		private void SetHeight(float height)
		{
			if (!(m_LayoutElement == null))
			{
				m_LayoutElement.preferredHeight = height;
			}
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/BoxSlider")]
	public class BoxSlider : Selectable, IDragHandler, IEventSystemHandler, IInitializePotentialDragHandler, ICanvasElement
	{
		public enum Direction
		{
			LeftToRight,
			RightToLeft,
			BottomToTop,
			TopToBottom
		}

		[Serializable]
		public class BoxSliderEvent : UnityEvent<float, float>
		{
		}

		private enum Axis
		{
			Horizontal,
			Vertical
		}

		[SerializeField]
		private RectTransform m_HandleRect;

		[Space(6f)]
		[SerializeField]
		private float m_MinValue;

		[SerializeField]
		private float m_MaxValue = 1f;

		[SerializeField]
		private bool m_WholeNumbers;

		[SerializeField]
		private float m_ValueX = 1f;

		[SerializeField]
		private float m_ValueY = 1f;

		[Space(6f)]
		[SerializeField]
		private BoxSliderEvent m_OnValueChanged = new BoxSliderEvent();

		private Transform m_HandleTransform;

		private RectTransform m_HandleContainerRect;

		private Vector2 m_Offset = Vector2.zero;

		private DrivenRectTransformTracker m_Tracker;

		public RectTransform HandleRect
		{
			get
			{
				return m_HandleRect;
			}
			set
			{
				if (SetClass(ref m_HandleRect, value))
				{
					UpdateCachedReferences();
					UpdateVisuals();
				}
			}
		}

		public float MinValue
		{
			get
			{
				return m_MinValue;
			}
			set
			{
				if (SetStruct(ref m_MinValue, value))
				{
					SetX(m_ValueX);
					SetY(m_ValueY);
					UpdateVisuals();
				}
			}
		}

		public float MaxValue
		{
			get
			{
				return m_MaxValue;
			}
			set
			{
				if (SetStruct(ref m_MaxValue, value))
				{
					SetX(m_ValueX);
					SetY(m_ValueY);
					UpdateVisuals();
				}
			}
		}

		public bool WholeNumbers
		{
			get
			{
				return m_WholeNumbers;
			}
			set
			{
				if (SetStruct(ref m_WholeNumbers, value))
				{
					SetX(m_ValueX);
					SetY(m_ValueY);
					UpdateVisuals();
				}
			}
		}

		public float ValueX
		{
			get
			{
				if (WholeNumbers)
				{
					return Mathf.Round(m_ValueX);
				}
				return m_ValueX;
			}
			set
			{
				SetX(value);
			}
		}

		public float NormalizedValueX
		{
			get
			{
				if (Mathf.Approximately(MinValue, MaxValue))
				{
					return 0f;
				}
				return Mathf.InverseLerp(MinValue, MaxValue, ValueX);
			}
			set
			{
				ValueX = Mathf.Lerp(MinValue, MaxValue, value);
			}
		}

		public float ValueY
		{
			get
			{
				if (WholeNumbers)
				{
					return Mathf.Round(m_ValueY);
				}
				return m_ValueY;
			}
			set
			{
				SetY(value);
			}
		}

		public float NormalizedValueY
		{
			get
			{
				if (Mathf.Approximately(MinValue, MaxValue))
				{
					return 0f;
				}
				return Mathf.InverseLerp(MinValue, MaxValue, ValueY);
			}
			set
			{
				ValueY = Mathf.Lerp(MinValue, MaxValue, value);
			}
		}

		public BoxSliderEvent OnValueChanged
		{
			get
			{
				return m_OnValueChanged;
			}
			set
			{
				m_OnValueChanged = value;
			}
		}

		private float StepSize
		{
			get
			{
				if (!WholeNumbers)
				{
					return (MaxValue - MinValue) * 0.1f;
				}
				return 1f;
			}
		}

		protected BoxSlider()
		{
		}

		public virtual void Rebuild(CanvasUpdate executing)
		{
		}

		public void LayoutComplete()
		{
		}

		public void GraphicUpdateComplete()
		{
		}

		public static bool SetClass<T>(ref T currentValue, T newValue) where T : class
		{
			if ((currentValue == null && newValue == null) || (currentValue != null && currentValue.Equals(newValue)))
			{
				return false;
			}
			currentValue = newValue;
			return true;
		}

		public static bool SetStruct<T>(ref T currentValue, T newValue) where T : struct
		{
			if (currentValue.Equals(newValue))
			{
				return false;
			}
			currentValue = newValue;
			return true;
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			UpdateCachedReferences();
			SetX(m_ValueX, sendCallback: false);
			SetY(m_ValueY, sendCallback: false);
			UpdateVisuals();
		}

		protected override void OnDisable()
		{
			m_Tracker.Clear();
			base.OnDisable();
		}

		private void UpdateCachedReferences()
		{
			if ((bool)m_HandleRect)
			{
				m_HandleTransform = m_HandleRect.transform;
				if (m_HandleTransform.parent != null)
				{
					m_HandleContainerRect = m_HandleTransform.parent.GetComponent<RectTransform>();
				}
			}
			else
			{
				m_HandleContainerRect = null;
			}
		}

		private void SetX(float input)
		{
			SetX(input, sendCallback: true);
		}

		private void SetX(float input, bool sendCallback)
		{
			float num = Mathf.Clamp(input, MinValue, MaxValue);
			if (WholeNumbers)
			{
				num = Mathf.Round(num);
			}
			if (m_ValueX != num)
			{
				m_ValueX = num;
				UpdateVisuals();
				if (sendCallback)
				{
					m_OnValueChanged.Invoke(num, ValueY);
				}
			}
		}

		private void SetY(float input)
		{
			SetY(input, sendCallback: true);
		}

		private void SetY(float input, bool sendCallback)
		{
			float num = Mathf.Clamp(input, MinValue, MaxValue);
			if (WholeNumbers)
			{
				num = Mathf.Round(num);
			}
			if (m_ValueY != num)
			{
				m_ValueY = num;
				UpdateVisuals();
				if (sendCallback)
				{
					m_OnValueChanged.Invoke(ValueX, num);
				}
			}
		}

		protected override void OnRectTransformDimensionsChange()
		{
			base.OnRectTransformDimensionsChange();
			UpdateVisuals();
		}

		private void UpdateVisuals()
		{
			m_Tracker.Clear();
			if (m_HandleContainerRect != null)
			{
				m_Tracker.Add(this, m_HandleRect, DrivenTransformProperties.Anchors);
				Vector2 zero = Vector2.zero;
				Vector2 one = Vector2.one;
				float value = (one[0] = NormalizedValueX);
				zero[0] = value;
				value = (one[1] = NormalizedValueY);
				zero[1] = value;
				m_HandleRect.anchorMin = zero;
				m_HandleRect.anchorMax = one;
			}
		}

		private void UpdateDrag(PointerEventData eventData, Camera cam)
		{
			RectTransform handleContainerRect = m_HandleContainerRect;
			if (handleContainerRect != null && handleContainerRect.rect.size[0] > 0f && RectTransformUtility.ScreenPointToLocalPointInRectangle(handleContainerRect, eventData.position, cam, out var localPoint))
			{
				localPoint -= handleContainerRect.rect.position;
				float normalizedValueX = Mathf.Clamp01((localPoint - m_Offset)[0] / handleContainerRect.rect.size[0]);
				NormalizedValueX = normalizedValueX;
				float normalizedValueY = Mathf.Clamp01((localPoint - m_Offset)[1] / handleContainerRect.rect.size[1]);
				NormalizedValueY = normalizedValueY;
			}
		}

		private bool CanDrag(PointerEventData eventData)
		{
			if (IsActive() && IsInteractable())
			{
				return eventData.button == PointerEventData.InputButton.Left;
			}
			return false;
		}

		public override void OnPointerDown(PointerEventData eventData)
		{
			if (!CanDrag(eventData))
			{
				return;
			}
			base.OnPointerDown(eventData);
			m_Offset = Vector2.zero;
			if (m_HandleContainerRect != null && RectTransformUtility.RectangleContainsScreenPoint(m_HandleRect, eventData.position, eventData.enterEventCamera))
			{
				if (RectTransformUtility.ScreenPointToLocalPointInRectangle(m_HandleRect, eventData.position, eventData.pressEventCamera, out var localPoint))
				{
					m_Offset = localPoint;
				}
				m_Offset.y = 0f - m_Offset.y;
			}
			else
			{
				UpdateDrag(eventData, eventData.pressEventCamera);
			}
		}

		public virtual void OnDrag(PointerEventData eventData)
		{
			if (CanDrag(eventData))
			{
				UpdateDrag(eventData, eventData.pressEventCamera);
			}
		}

		public virtual void OnInitializePotentialDrag(PointerEventData eventData)
		{
			eventData.useDragThreshold = false;
		}

		Transform ICanvasElement.get_transform()
		{
			return base.transform;
		}
	}
	public class TiltWindow : MonoBehaviour
	{
		public Vector2 range = new Vector2(5f, 3f);

		private Transform mTrans;

		private Quaternion mStart;

		private Vector2 mRot = Vector2.zero;

		private void Start()
		{
			mTrans = base.transform;
			mStart = mTrans.localRotation;
		}

		private void Update()
		{
			Vector3 mousePosition = Input.mousePosition;
			float num = (float)Screen.width * 0.5f;
			float num2 = (float)Screen.height * 0.5f;
			float x = Mathf.Clamp((mousePosition.x - num) / num, -1f, 1f);
			float y = Mathf.Clamp((mousePosition.y - num2) / num2, -1f, 1f);
			mRot = Vector2.Lerp(mRot, new Vector2(x, y), Time.deltaTime * 5f);
			mTrans.localRotation = mStart * Quaternion.Euler((0f - mRot.y) * range.y, mRot.x * range.x, 0f);
		}
	}
	public enum AutoCompleteSearchType
	{
		ArraySort,
		Linq
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/AutoComplete ComboBox")]
	public class AutoCompleteComboBox : MonoBehaviour
	{
		[Serializable]
		public class SelectionChangedEvent : UnityEvent<string, bool>
		{
		}

		[Serializable]
		public class SelectionTextChangedEvent : UnityEvent<string>
		{
		}

		[Serializable]
		public class SelectionValidityChangedEvent : UnityEvent<bool>
		{
		}

		public Color disabledTextColor;

		public List<string> AvailableOptions;

		private bool _isPanelActive;

		private bool _hasDrawnOnce;

		private InputField _mainInput;

		private RectTransform _inputRT;

		private RectTransform _rectTransform;

		private RectTransform _overlayRT;

		private RectTransform _scrollPanelRT;

		private RectTransform _scrollBarRT;

		private RectTransform _slidingAreaRT;

		private RectTransform _itemsPanelRT;

		private Canvas _canvas;

		private RectTransform _canvasRT;

		private ScrollRect _scrollRect;

		private List<string> _panelItems;

		private List<string> _prunedPanelItems;

		private Dictionary<string, GameObject> panelObjects;

		private GameObject itemTemplate;

		[SerializeField]
		private float _scrollBarWidth = 20f;

		[SerializeField]
		private int _itemsToDisplay;

		public bool SelectFirstItemOnStart;

		[SerializeField]
		[Tooltip("Change input text color based on matching items")]
		private bool _ChangeInputTextColorBasedOnMatchingItems;

		public Color ValidSelectionTextColor = Color.green;

		public Color MatchingItemsRemainingTextColor = Color.black;

		public Color NoItemsRemainingTextColor = Color.red;

		public AutoCompleteSearchType autocompleteSearchType = AutoCompleteSearchType.Linq;

		private bool _selectionIsValid;

		public SelectionTextChangedEvent OnSelectionTextChanged;

		public SelectionValidityChangedEvent OnSelectionValidityChanged;

		public SelectionChangedEvent OnSelectionChanged;

		public DropDownListItem SelectedItem { get; private set; }

		public string Text { get; private set; }

		public float ScrollBarWidth
		{
			get
			{
				return _scrollBarWidth;
			}
			set
			{
				_scrollBarWidth = value;
				RedrawPanel();
			}
		}

		public int ItemsToDisplay
		{
			get
			{
				return _itemsToDisplay;
			}
			set
			{
				_itemsToDisplay = value;
				RedrawPanel();
			}
		}

		public bool InputColorMatching
		{
			get
			{
				return _ChangeInputTextColorBasedOnMatchingItems;
			}
			set
			{
				_ChangeInputTextColorBasedOnMatchingItems = value;
				if (_ChangeInputTextColorBasedOnMatchingItems)
				{
					SetInputTextColor();
				}
			}
		}

		public void Awake()
		{
			Initialize();
		}

		public void Start()
		{
			if (SelectFirstItemOnStart && AvailableOptions.Count > 0)
			{
				ToggleDropdownPanel(directClick: false);
				OnItemClicked(AvailableOptions[0]);
			}
		}

		private bool Initialize()
		{
			bool result = true;
			try
			{
				_rectTransform = GetComponent<RectTransform>();
				_inputRT = _rectTransform.Find("InputField").GetComponent<RectTransform>();
				_mainInput = _inputRT.GetComponent<InputField>();
				_overlayRT = _rectTransform.Find("Overlay").GetComponent<RectTransform>();
				_overlayRT.gameObject.SetActive(value: false);
				_scrollPanelRT = _overlayRT.Find("ScrollPanel").GetComponent<RectTransform>();
				_scrollBarRT = _scrollPanelRT.Find("Scrollbar").GetComponent<RectTransform>();
				_slidingAreaRT = _scrollBarRT.Find("SlidingArea").GetComponent<RectTransform>();
				_itemsPanelRT = _scrollPanelRT.Find("Items").GetComponent<RectTransform>();
				_canvas = GetComponentInParent<Canvas>();
				_canvasRT = _canvas.GetComponent<RectTransform>();
				_scrollRect = _scrollPanelRT.GetComponent<ScrollRect>();
				_scrollRect.scrollSensitivity = _rectTransform.sizeDelta.y / 2f;
				_scrollRect.movementType = ScrollRect.MovementType.Clamped;
				_scrollRect.content = _itemsPanelRT;
				itemTemplate = _rectTransform.Find("ItemTemplate").gameObject;
				itemTemplate.SetActive(value: false);
			}
			catch (NullReferenceException exception)
			{
				Debug.LogException(exception);
				Debug.LogError("Something is setup incorrectly with the dropdownlist component causing a Null Refernece Exception");
				result = false;
			}
			panelObjects = new Dictionary<string, GameObject>();
			_prunedPanelItems = new List<string>();
			_panelItems = new List<string>();
			RebuildPanel();
			return result;
		}

		private void RebuildPanel()
		{
			_panelItems.Clear();
			_prunedPanelItems.Clear();
			panelObjects.Clear();
			foreach (string availableOption in AvailableOptions)
			{
				_panelItems.Add(availableOption.ToLower());
			}
			List<GameObject> list = new List<GameObject>(panelObjects.Values);
			int num = 0;
			while (list.Count < AvailableOptions.Count)
			{
				GameObject gameObject = Object.Instantiate(itemTemplate);
				gameObject.name = "Item " + num;
				gameObject.transform.SetParent(_itemsPanelRT, worldPositionStays: false);
				list.Add(gameObject);
				num++;
			}
			for (int i = 0; i < list.Count; i++)
			{
				list[i].SetActive(i <= AvailableOptions.Count);
				if (i < AvailableOptions.Count)
				{
					list[i].name = "Item " + i + " " + _panelItems[i];
					list[i].transform.Find("Text").GetComponent<Text>().text = _panelItems[i];
					Button component = list[i].GetComponent<Button>();
					component.onClick.RemoveAllListeners();
					string textOfItem = _panelItems[i];
					component.onClick.AddListener(delegate
					{
						OnItemClicked(textOfItem);
					});
					panelObjects[_panelItems[i]] = list[i];
				}
			}
			SetInputTextColor();
		}

		private void OnItemClicked(string item)
		{
			Text = item;
			_mainInput.text = Text;
			ToggleDropdownPanel(directClick: true);
		}

		private void RedrawPanel()
		{
			float num = ((_panelItems.Count > ItemsToDisplay) ? _scrollBarWidth : 0f);
			_scrollBarRT.gameObject.SetActive(_panelItems.Count > ItemsToDisplay);
			if (!_hasDrawnOnce || _rectTransform.sizeDelta != _inputRT.sizeDelta)
			{
				_hasDrawnOnce = true;
				_inputRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_inputRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _rectTransform.sizeDelta.y);
				_scrollPanelRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.anchoredPosition = new Vector2(0f, 0f - _rectTransform.sizeDelta.y);
				_overlayRT.SetParent(_canvas.transform, worldPositionStays: false);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _canvasRT.sizeDelta.x);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _canvasRT.sizeDelta.y);
				_overlayRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.SetParent(_overlayRT, worldPositionStays: true);
			}
			if (_panelItems.Count >= 1)
			{
				float num2 = _rectTransform.sizeDelta.y * (float)Mathf.Min(_itemsToDisplay, _panelItems.Count);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_itemsPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _scrollPanelRT.sizeDelta.x - num - 5f);
				_itemsPanelRT.anchoredPosition = new Vector2(5f, 0f);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, num);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, 0f);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2 - _scrollBarRT.sizeDelta.x);
			}
		}

		public void OnValueChanged(string currText)
		{
			Text = currText;
			PruneItems(currText);
			RedrawPanel();
			if (_panelItems.Count == 0)
			{
				_isPanelActive = true;
				ToggleDropdownPanel(directClick: false);
			}
			else if (!_isPanelActive)
			{
				ToggleDropdownPanel(directClick: false);
			}
			bool num = _panelItems.Contains(Text) != _selectionIsValid;
			_selectionIsValid = _panelItems.Contains(Text);
			OnSelectionChanged.Invoke(Text, _selectionIsValid);
			OnSelectionTextChanged.Invoke(Text);
			if (num)
			{
				OnSelectionValidityChanged.Invoke(_selectionIsValid);
			}
			SetInputTextColor();
		}

		private void SetInputTextColor()
		{
			if (InputColorMatching)
			{
				if (_selectionIsValid)
				{
					_mainInput.textComponent.color = ValidSelectionTextColor;
				}
				else if (_panelItems.Count > 0)
				{
					_mainInput.textComponent.color = MatchingItemsRemainingTextColor;
				}
				else
				{
					_mainInput.textComponent.color = NoItemsRemainingTextColor;
				}
			}
		}

		public void ToggleDropdownPanel(bool directClick)
		{
			_isPanelActive = !_isPanelActive;
			_overlayRT.gameObject.SetActive(_isPanelActive);
			if (_isPanelActive)
			{
				base.transform.SetAsLastSibling();
			}
		}

		private void PruneItems(string currText)
		{
			if (autocompleteSearchType == AutoCompleteSearchType.Linq)
			{
				PruneItemsLinq(currText);
			}
			else
			{
				PruneItemsArray(currText);
			}
		}

		private void PruneItemsLinq(string currText)
		{
			currText = currText.ToLower();
			string[] array = _panelItems.Where((string x) => !x.Contains(currText)).ToArray();
			foreach (string text in array)
			{
				panelObjects[text].SetActive(value: false);
				_panelItems.Remove(text);
				_prunedPanelItems.Add(text);
			}
			array = _prunedPanelItems.Where((string x) => x.Contains(currText)).ToArray();
			foreach (string text2 in array)
			{
				panelObjects[text2].SetActive(value: true);
				_panelItems.Add(text2);
				_prunedPanelItems.Remove(text2);
			}
		}

		private void PruneItemsArray(string currText)
		{
			string value = currText.ToLower();
			for (int num = _panelItems.Count - 1; num >= 0; num--)
			{
				string text = _panelItems[num];
				if (!text.Contains(value))
				{
					panelObjects[_panelItems[num]].SetActive(value: false);
					_panelItems.RemoveAt(num);
					_prunedPanelItems.Add(text);
				}
			}
			for (int num2 = _prunedPanelItems.Count - 1; num2 >= 0; num2--)
			{
				string text2 = _prunedPanelItems[num2];
				if (text2.Contains(value))
				{
					panelObjects[_prunedPanelItems[num2]].SetActive(value: true);
					_prunedPanelItems.RemoveAt(num2);
					_panelItems.Add(text2);
				}
			}
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/ComboBox")]
	public class ComboBox : MonoBehaviour
	{
		[Serializable]
		public class SelectionChangedEvent : UnityEvent<string>
		{
		}

		public Color disabledTextColor;

		public List<string> AvailableOptions;

		[SerializeField]
		private float _scrollBarWidth = 20f;

		[SerializeField]
		private int _itemsToDisplay;

		public SelectionChangedEvent OnSelectionChanged;

		private bool _isPanelActive;

		private bool _hasDrawnOnce;

		private InputField _mainInput;

		private RectTransform _inputRT;

		private RectTransform _rectTransform;

		private RectTransform _overlayRT;

		private RectTransform _scrollPanelRT;

		private RectTransform _scrollBarRT;

		private RectTransform _slidingAreaRT;

		private RectTransform _itemsPanelRT;

		private Canvas _canvas;

		private RectTransform _canvasRT;

		private ScrollRect _scrollRect;

		private List<string> _panelItems;

		private Dictionary<string, GameObject> panelObjects;

		private GameObject itemTemplate;

		public DropDownListItem SelectedItem { get; private set; }

		public string Text { get; private set; }

		public float ScrollBarWidth
		{
			get
			{
				return _scrollBarWidth;
			}
			set
			{
				_scrollBarWidth = value;
				RedrawPanel();
			}
		}

		public int ItemsToDisplay
		{
			get
			{
				return _itemsToDisplay;
			}
			set
			{
				_itemsToDisplay = value;
				RedrawPanel();
			}
		}

		public void Awake()
		{
			Initialize();
		}

		private bool Initialize()
		{
			bool result = true;
			try
			{
				_rectTransform = GetComponent<RectTransform>();
				_inputRT = _rectTransform.Find("InputField").GetComponent<RectTransform>();
				_mainInput = _inputRT.GetComponent<InputField>();
				_overlayRT = _rectTransform.Find("Overlay").GetComponent<RectTransform>();
				_overlayRT.gameObject.SetActive(value: false);
				_scrollPanelRT = _overlayRT.Find("ScrollPanel").GetComponent<RectTransform>();
				_scrollBarRT = _scrollPanelRT.Find("Scrollbar").GetComponent<RectTransform>();
				_slidingAreaRT = _scrollBarRT.Find("SlidingArea").GetComponent<RectTransform>();
				_itemsPanelRT = _scrollPanelRT.Find("Items").GetComponent<RectTransform>();
				_canvas = GetComponentInParent<Canvas>();
				_canvasRT = _canvas.GetComponent<RectTransform>();
				_scrollRect = _scrollPanelRT.GetComponent<ScrollRect>();
				_scrollRect.scrollSensitivity = _rectTransform.sizeDelta.y / 2f;
				_scrollRect.movementType = ScrollRect.MovementType.Clamped;
				_scrollRect.content = _itemsPanelRT;
				itemTemplate = _rectTransform.Find("ItemTemplate").gameObject;
				itemTemplate.SetActive(value: false);
			}
			catch (NullReferenceException exception)
			{
				Debug.LogException(exception);
				Debug.LogError("Something is setup incorrectly with the dropdownlist component causing a Null Refernece Exception");
				result = false;
			}
			panelObjects = new Dictionary<string, GameObject>();
			_panelItems = AvailableOptions.ToList();
			RebuildPanel();
			return result;
		}

		private void RebuildPanel()
		{
			_panelItems.Clear();
			foreach (string availableOption in AvailableOptions)
			{
				_panelItems.Add(availableOption.ToLower());
			}
			_panelItems.Sort();
			List<GameObject> list = new List<GameObject>(panelObjects.Values);
			panelObjects.Clear();
			int num = 0;
			while (list.Count < AvailableOptions.Count)
			{
				GameObject gameObject = Object.Instantiate(itemTemplate);
				gameObject.name = "Item " + num;
				gameObject.transform.SetParent(_itemsPanelRT, worldPositionStays: false);
				list.Add(gameObject);
				num++;
			}
			for (int i = 0; i < list.Count; i++)
			{
				list[i].SetActive(i <= AvailableOptions.Count);
				if (i < AvailableOptions.Count)
				{
					list[i].name = "Item " + i + " " + _panelItems[i];
					list[i].transform.Find("Text").GetComponent<Text>().text = _panelItems[i];
					Button component = list[i].GetComponent<Button>();
					component.onClick.RemoveAllListeners();
					string textOfItem = _panelItems[i];
					component.onClick.AddListener(delegate
					{
						OnItemClicked(textOfItem);
					});
					panelObjects[_panelItems[i]] = list[i];
				}
			}
		}

		private void OnItemClicked(string item)
		{
			Text = item;
			_mainInput.text = Text;
			ToggleDropdownPanel(directClick: true);
		}

		private void RedrawPanel()
		{
			float num = ((_panelItems.Count > ItemsToDisplay) ? _scrollBarWidth : 0f);
			_scrollBarRT.gameObject.SetActive(_panelItems.Count > ItemsToDisplay);
			if (!_hasDrawnOnce || _rectTransform.sizeDelta != _inputRT.sizeDelta)
			{
				_hasDrawnOnce = true;
				_inputRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_inputRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _rectTransform.sizeDelta.y);
				_scrollPanelRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.anchoredPosition = new Vector2(0f, 0f - _rectTransform.sizeDelta.y);
				_overlayRT.SetParent(_canvas.transform, worldPositionStays: false);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _canvasRT.sizeDelta.x);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _canvasRT.sizeDelta.y);
				_overlayRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.SetParent(_overlayRT, worldPositionStays: true);
			}
			if (_panelItems.Count >= 1)
			{
				float num2 = _rectTransform.sizeDelta.y * (float)Mathf.Min(_itemsToDisplay, _panelItems.Count);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_itemsPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _scrollPanelRT.sizeDelta.x - num - 5f);
				_itemsPanelRT.anchoredPosition = new Vector2(5f, 0f);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, num);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, 0f);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2 - _scrollBarRT.sizeDelta.x);
			}
		}

		public void OnValueChanged(string currText)
		{
			Text = currText;
			RedrawPanel();
			if (_panelItems.Count == 0)
			{
				_isPanelActive = true;
				ToggleDropdownPanel(directClick: false);
			}
			else if (!_isPanelActive)
			{
				ToggleDropdownPanel(directClick: false);
			}
			OnSelectionChanged.Invoke(Text);
		}

		public void ToggleDropdownPanel(bool directClick)
		{
			_isPanelActive = !_isPanelActive;
			_overlayRT.gameObject.SetActive(_isPanelActive);
			if (_isPanelActive)
			{
				base.transform.SetAsLastSibling();
			}
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/Dropdown List")]
	public class DropDownList : MonoBehaviour
	{
		[Serializable]
		public class SelectionChangedEvent : UnityEvent<int>
		{
		}

		public Color disabledTextColor;

		public List<DropDownListItem> Items;

		public bool OverrideHighlighted = true;

		private bool _isPanelActive;

		private bool _hasDrawnOnce;

		private DropDownListButton _mainButton;

		private RectTransform _rectTransform;

		private RectTransform _overlayRT;

		private RectTransform _scrollPanelRT;

		private RectTransform _scrollBarRT;

		private RectTransform _slidingAreaRT;

		private RectTransform _itemsPanelRT;

		private Canvas _canvas;

		private RectTransform _canvasRT;

		private ScrollRect _scrollRect;

		private List<DropDownListButton> _panelItems;

		private GameObject _itemTemplate;

		[SerializeField]
		private float _scrollBarWidth = 20f;

		private int _selectedIndex = -1;

		[SerializeField]
		private int _itemsToDisplay;

		public bool SelectFirstItemOnStart;

		public SelectionChangedEvent OnSelectionChanged;

		public DropDownListItem SelectedItem { get; private set; }

		public float ScrollBarWidth
		{
			get
			{
				return _scrollBarWidth;
			}
			set
			{
				_scrollBarWidth = value;
				RedrawPanel();
			}
		}

		public int ItemsToDisplay
		{
			get
			{
				return _itemsToDisplay;
			}
			set
			{
				_itemsToDisplay = value;
				RedrawPanel();
			}
		}

		public void Start()
		{
			Initialize();
			if (SelectFirstItemOnStart && Items.Count > 0)
			{
				ToggleDropdownPanel(directClick: false);
				OnItemClicked(0);
			}
		}

		private bool Initialize()
		{
			bool result = true;
			try
			{
				_rectTransform = GetComponent<RectTransform>();
				_mainButton = new DropDownListButton(_rectTransform.Find("MainButton").gameObject);
				_overlayRT = _rectTransform.Find("Overlay").GetComponent<RectTransform>();
				_overlayRT.gameObject.SetActive(value: false);
				_scrollPanelRT = _overlayRT.Find("ScrollPanel").GetComponent<RectTransform>();
				_scrollBarRT = _scrollPanelRT.Find("Scrollbar").GetComponent<RectTransform>();
				_slidingAreaRT = _scrollBarRT.Find("SlidingArea").GetComponent<RectTransform>();
				_itemsPanelRT = _scrollPanelRT.Find("Items").GetComponent<RectTransform>();
				_canvas = GetComponentInParent<Canvas>();
				_canvasRT = _canvas.GetComponent<RectTransform>();
				_scrollRect = _scrollPanelRT.GetComponent<ScrollRect>();
				_scrollRect.scrollSensitivity = _rectTransform.sizeDelta.y / 2f;
				_scrollRect.movementType = ScrollRect.MovementType.Clamped;
				_scrollRect.content = _itemsPanelRT;
				_itemTemplate = _rectTransform.Find("ItemTemplate").gameObject;
				_itemTemplate.SetActive(value: false);
			}
			catch (NullReferenceException exception)
			{
				Debug.LogException(exception);
				Debug.LogError("Something is setup incorrectly with the dropdownlist component causing a Null Reference Exception");
				result = false;
			}
			_panelItems = new List<DropDownListButton>();
			RebuildPanel();
			RedrawPanel();
			return result;
		}

		private void RebuildPanel()
		{
			if (Items.Count == 0)
			{
				return;
			}
			int num = _panelItems.Count;
			while (_panelItems.Count < Items.Count)
			{
				GameObject gameObject = Object.Instantiate(_itemTemplate);
				gameObject.name = "Item " + num;
				gameObject.transform.SetParent(_itemsPanelRT, worldPositionStays: false);
				_panelItems.Add(new DropDownListButton(gameObject));
				num++;
			}
			for (int i = 0; i < _panelItems.Count; i++)
			{
				if (i < Items.Count)
				{
					DropDownListItem item = Items[i];
					_panelItems[i].txt.text = item.Caption;
					if (item.IsDisabled)
					{
						_panelItems[i].txt.color = disabledTextColor;
					}
					if (_panelItems[i].btnImg != null)
					{
						_panelItems[i].btnImg.sprite = null;
					}
					_panelItems[i].img.sprite = item.Image;
					_panelItems[i].img.color = ((item.Image == null) ? new Color(1f, 1f, 1f, 0f) : (item.IsDisabled ? new Color(1f, 1f, 1f, 0.5f) : Color.white));
					int ii = i;
					_panelItems[i].btn.onClick.RemoveAllListeners();
					_panelItems[i].btn.onClick.AddListener(delegate
					{
						OnItemClicked(ii);
						if (item.OnSelect != null)
						{
							item.OnSelect();
						}
					});
				}
				_panelItems[i].gameobject.SetActive(i < Items.Count);
			}
		}

		private void OnItemClicked(int indx)
		{
			if (indx != _selectedIndex && OnSelectionChanged != null)
			{
				OnSelectionChanged.Invoke(indx);
			}
			_selectedIndex = indx;
			ToggleDropdownPanel(directClick: true);
			UpdateSelected();
		}

		private void UpdateSelected()
		{
			SelectedItem = ((_selectedIndex > -1 && _selectedIndex < Items.Count) ? Items[_selectedIndex] : null);
			if (SelectedItem == null)
			{
				return;
			}
			if (SelectedItem.Image != null)
			{
				_mainButton.img.sprite = SelectedItem.Image;
				_mainButton.img.color = Color.white;
			}
			else
			{
				_mainButton.img.sprite = null;
			}
			_mainButton.txt.text = SelectedItem.Caption;
			if (OverrideHighlighted)
			{
				for (int i = 0; i < _itemsPanelRT.childCount; i++)
				{
					_panelItems[i].btnImg.color = ((_selectedIndex == i) ? _mainButton.btn.colors.highlightedColor : new Color(0f, 0f, 0f, 0f));
				}
			}
		}

		private void RedrawPanel()
		{
			float num = ((Items.Count > ItemsToDisplay) ? _scrollBarWidth : 0f);
			if (!_hasDrawnOnce || _rectTransform.sizeDelta != _mainButton.rectTransform.sizeDelta)
			{
				_hasDrawnOnce = true;
				_mainButton.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_mainButton.rectTransform.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _rectTransform.sizeDelta.y);
				_mainButton.txt.rectTransform.offsetMax = new Vector2(4f, 0f);
				_scrollPanelRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.anchoredPosition = new Vector2(0f, 0f - _rectTransform.sizeDelta.y);
				_overlayRT.SetParent(_canvas.transform, worldPositionStays: false);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _canvasRT.sizeDelta.x);
				_overlayRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _canvasRT.sizeDelta.y);
				_overlayRT.SetParent(base.transform, worldPositionStays: true);
				_scrollPanelRT.SetParent(_overlayRT, worldPositionStays: true);
			}
			if (Items.Count >= 1)
			{
				float num2 = _rectTransform.sizeDelta.y * (float)Mathf.Min(_itemsToDisplay, Items.Count);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_scrollPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _rectTransform.sizeDelta.x);
				_itemsPanelRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _scrollPanelRT.sizeDelta.x - num - 5f);
				_itemsPanelRT.anchoredPosition = new Vector2(5f, 0f);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, num);
				_scrollBarRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, 0f);
				_slidingAreaRT.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, num2 - _scrollBarRT.sizeDelta.x);
			}
		}

		public void ToggleDropdownPanel(bool directClick)
		{
			_overlayRT.transform.localScale = new Vector3(1f, 1f, 1f);
			_scrollBarRT.transform.localScale = new Vector3(1f, 1f, 1f);
			_isPanelActive = !_isPanelActive;
			_overlayRT.gameObject.SetActive(_isPanelActive);
			if (_isPanelActive)
			{
				base.transform.SetAsLastSibling();
			}
		}
	}
