	[AddComponentMenu("UI/Extensions/Radial Slider")]
	[RequireComponent(typeof(Image))]
	public class RadialSlider : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerDownHandler, IPointerUpHandler
	{
		[Serializable]
		public class RadialSliderValueChangedEvent : UnityEvent<int>
		{
		}

		[Serializable]
		public class RadialSliderTextValueChangedEvent : UnityEvent<string>
		{
		}

		private bool isPointerDown;

		private bool isPointerReleased;

		private bool lerpInProgress;

		private Vector2 m_localPos;

		private float m_targetAngle;

		private float m_lerpTargetAngle;

		private float m_startAngle;

		private float m_currentLerpTime;

		private float m_lerpTime;

		private Camera m_eventCamera;

		private Image m_image;

		[SerializeField]
		[Tooltip("Radial Gradient Start Color")]
		private Color m_startColor = Color.green;

		[SerializeField]
		[Tooltip("Radial Gradient End Color")]
		private Color m_endColor = Color.red;

		[Tooltip("Move slider absolute or use Lerping?\nDragging only supported with absolute")]
		[SerializeField]
		private bool m_lerpToTarget;

		[Tooltip("Curve to apply to the Lerp\nMust be set to enable Lerp")]
		[SerializeField]
		private AnimationCurve m_lerpCurve;

		[Tooltip("Event fired when value of control changes, outputs an INT angle value")]
		[SerializeField]
		private RadialSliderValueChangedEvent _onValueChanged = new RadialSliderValueChangedEvent();

		[Tooltip("Event fired when value of control changes, outputs a TEXT angle value")]
		[SerializeField]
		private RadialSliderTextValueChangedEvent _onTextValueChanged = new RadialSliderTextValueChangedEvent();

		public float Angle
		{
			get
			{
				return RadialImage.fillAmount * 360f;
			}
			set
			{
				if (LerpToTarget)
				{
					StartLerp(value / 360f);
				}
				else
				{
					UpdateRadialImage(value / 360f);
				}
			}
		}

		public float Value
		{
			get
			{
				return RadialImage.fillAmount;
			}
			set
			{
				if (LerpToTarget)
				{
					StartLerp(value);
				}
				else
				{
					UpdateRadialImage(value);
				}
			}
		}

		public Color EndColor
		{
			get
			{
				return m_endColor;
			}
			set
			{
				m_endColor = value;
			}
		}

		public Color StartColor
		{
			get
			{
				return m_startColor;
			}
			set
			{
				m_startColor = value;
			}
		}

		public bool LerpToTarget
		{
			get
			{
				return m_lerpToTarget;
			}
			set
			{
				m_lerpToTarget = value;
			}
		}

		public AnimationCurve LerpCurve
		{
			get
			{
				return m_lerpCurve;
			}
			set
			{
				m_lerpCurve = value;
				m_lerpTime = LerpCurve[LerpCurve.length - 1].time;
			}
		}

		public bool LerpInProgress => lerpInProgress;

		public Image RadialImage
		{
			get
			{
				if (m_image == null)
				{
					m_image = GetComponent<Image>();
					m_image.type = Image.Type.Filled;
					m_image.fillMethod = Image.FillMethod.Radial360;
					m_image.fillOrigin = 3;
					m_image.fillAmount = 0f;
				}
				return m_image;
			}
		}

		public RadialSliderValueChangedEvent onValueChanged
		{
			get
			{
				return _onValueChanged;
			}
			set
			{
				_onValueChanged = value;
			}
		}

		public RadialSliderTextValueChangedEvent onTextValueChanged
		{
			get
			{
				return _onTextValueChanged;
			}
			set
			{
				_onTextValueChanged = value;
			}
		}

		private void Awake()
		{
			if (LerpCurve != null && LerpCurve.length > 0)
			{
				m_lerpTime = LerpCurve[LerpCurve.length - 1].time;
			}
			else
			{
				m_lerpTime = 1f;
			}
		}

		private void Update()
		{
			if (isPointerDown)
			{
				m_targetAngle = GetAngleFromMousePoint();
				if (!lerpInProgress)
				{
					if (!LerpToTarget)
					{
						UpdateRadialImage(m_targetAngle);
						NotifyValueChanged();
					}
					else
					{
						if (isPointerReleased)
						{
							StartLerp(m_targetAngle);
						}
						isPointerReleased = false;
					}
				}
			}
			if (lerpInProgress && Value != m_lerpTargetAngle)
			{
				m_currentLerpTime += Time.deltaTime;
				float num = m_currentLerpTime / m_lerpTime;
				if (LerpCurve != null && LerpCurve.length > 0)
				{
					UpdateRadialImage(Mathf.Lerp(m_startAngle, m_lerpTargetAngle, LerpCurve.Evaluate(num)));
				}
				else
				{
					UpdateRadialImage(Mathf.Lerp(m_startAngle, m_lerpTargetAngle, num));
				}
			}
			if (m_currentLerpTime >= m_lerpTime || Value == m_lerpTargetAngle)
			{
				lerpInProgress = false;
				UpdateRadialImage(m_lerpTargetAngle);
				NotifyValueChanged();
			}
		}

		private void StartLerp(float targetAngle)
		{
			if (!lerpInProgress)
			{
				m_startAngle = Value;
				m_lerpTargetAngle = targetAngle;
				m_currentLerpTime = 0f;
				lerpInProgress = true;
			}
		}

		private float GetAngleFromMousePoint()
		{
			RectTransformUtility.ScreenPointToLocalPointInRectangle(base.transform as RectTransform, Input.mousePosition, m_eventCamera, out m_localPos);
			return (Mathf.Atan2(0f - m_localPos.y, m_localPos.x) * 180f / MathF.PI + 180f) / 360f;
		}

		private void UpdateRadialImage(float targetAngle)
		{
			RadialImage.fillAmount = targetAngle;
			RadialImage.color = Color.Lerp(m_startColor, m_endColor, targetAngle);
		}

		private void NotifyValueChanged()
		{
			_onValueChanged.Invoke((int)(m_targetAngle * 360f));
			_onTextValueChanged.Invoke(((int)(m_targetAngle * 360f)).ToString());
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			m_eventCamera = eventData.enterEventCamera;
		}

		public void OnPointerDown(PointerEventData eventData)
		{
			m_eventCamera = eventData.enterEventCamera;
			isPointerDown = true;
		}

		public void OnPointerUp(PointerEventData eventData)
		{
			isPointerDown = false;
			isPointerReleased = true;
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[DisallowMultipleComponent]
	[AddComponentMenu("UI/Extensions/Re-orderable list")]
	public class ReorderableList : MonoBehaviour
	{
		[Serializable]
		public struct ReorderableListEventStruct
		{
			public GameObject DroppedObject;

			public int FromIndex;

			public ReorderableList FromList;

			public bool IsAClone;

			public GameObject SourceObject;

			public int ToIndex;

			public ReorderableList ToList;

			public void Cancel()
			{
				SourceObject.GetComponent<ReorderableListElement>().isValid = false;
			}
		}

		[Serializable]
		public class ReorderableListHandler : UnityEvent<ReorderableListEventStruct>
		{
		}

		[Tooltip("Child container with re-orderable items in a layout group")]
		public LayoutGroup ContentLayout;

		[Tooltip("Parent area to draw the dragged element on top of containers. Defaults to the root Canvas")]
		public RectTransform DraggableArea;

		[Tooltip("Can items be dragged from the container?")]
		public bool IsDraggable = true;

		[Tooltip("Should the draggable components be removed or cloned?")]
		public bool CloneDraggedObject;

		[Tooltip("Can new draggable items be dropped in to the container?")]
		public bool IsDropable = true;

		[Header("UI Re-orderable Events")]
		public ReorderableListHandler OnElementDropped = new ReorderableListHandler();

		public ReorderableListHandler OnElementGrabbed = new ReorderableListHandler();

		public ReorderableListHandler OnElementRemoved = new ReorderableListHandler();

		public ReorderableListHandler OnElementAdded = new ReorderableListHandler();

		private RectTransform _content;

		private ReorderableListContent _listContent;

		public RectTransform Content
		{
			get
			{
				if (_content == null)
				{
					_content = ContentLayout.GetComponent<RectTransform>();
				}
				return _content;
			}
		}

		private Canvas GetCanvas()
		{
			Transform parent = base.transform;
			Canvas canvas = null;
			int num = 100;
			int num2 = 0;
			while (canvas == null && num2 < num)
			{
				canvas = parent.gameObject.GetComponent<Canvas>();
				if (canvas == null)
				{
					parent = parent.parent;
				}
				num2++;
			}
			return canvas;
		}

		private void Awake()
		{
			if (ContentLayout == null)
			{
				Debug.LogError("You need to have a child LayoutGroup content set for the list: " + base.name, base.gameObject);
				return;
			}
			if (DraggableArea == null)
			{
				DraggableArea = base.transform.root.GetComponentInChildren<Canvas>().GetComponent<RectTransform>();
			}
			if (IsDropable && !GetComponent<Graphic>())
			{
				Debug.LogError("You need to have a Graphic control (such as an Image) for the list [" + base.name + "] to be droppable", base.gameObject);
				return;
			}
			_listContent = ContentLayout.gameObject.AddComponent<ReorderableListContent>();
			_listContent.Init(this);
		}

		public void TestReOrderableListTarget(ReorderableListEventStruct item)
		{
			Debug.Log("Event Received");
			Debug.Log("Hello World, is my item a clone? [" + item.IsAClone + "]");
		}
	}
	public class ReorderableListContent : MonoBehaviour
	{
		private List<Transform> _cachedChildren;

		private List<ReorderableListElement> _cachedListElement;

		private ReorderableListElement _ele;

		private ReorderableList _extList;

		private RectTransform _rect;

		private void OnEnable()
		{
			if ((bool)_rect)
			{
				StartCoroutine(RefreshChildren());
			}
		}

		public void OnTransformChildrenChanged()
		{
			if (base.isActiveAndEnabled)
			{
				StartCoroutine(RefreshChildren());
			}
		}

		public void Init(ReorderableList extList)
		{
			_extList = extList;
			_rect = GetComponent<RectTransform>();
			_cachedChildren = new List<Transform>();
			_cachedListElement = new List<ReorderableListElement>();
			StartCoroutine(RefreshChildren());
		}

		private IEnumerator RefreshChildren()
		{
			for (int i = 0; i < _rect.childCount; i++)
			{
				if (!_cachedChildren.Contains(_rect.GetChild(i)))
				{
					_ele = _rect.GetChild(i).gameObject.GetComponent<ReorderableListElement>() ?? _rect.GetChild(i).gameObject.AddComponent<ReorderableListElement>();
					_ele.Init(_extList);
					_cachedChildren.Add(_rect.GetChild(i));
					_cachedListElement.Add(_ele);
				}
			}
			yield return 0;
			for (int num = _cachedChildren.Count - 1; num >= 0; num--)
			{
				if (_cachedChildren[num] == null)
				{
					_cachedChildren.RemoveAt(num);
					_cachedListElement.RemoveAt(num);
				}
			}
		}
	}
	public class ReorderableListDebug : MonoBehaviour
	{
		public Text DebugLabel;

		private void Awake()
		{
			ReorderableList[] array = Object.FindObjectsByType<ReorderableList>(FindObjectsSortMode.None);
			for (int i = 0; i < array.Length; i++)
			{
				array[i].OnElementDropped.AddListener(ElementDropped);
			}
		}

		private void ElementDropped(ReorderableList.ReorderableListEventStruct droppedStruct)
		{
			DebugLabel.text = "";
			Text debugLabel = DebugLabel;
			debugLabel.text = debugLabel.text + "Dropped Object: " + droppedStruct.DroppedObject.name + "\n";
			Text debugLabel2 = DebugLabel;
			debugLabel2.text = debugLabel2.text + "Is Clone ?: " + droppedStruct.IsAClone + "\n";
			if (droppedStruct.IsAClone)
			{
				Text debugLabel3 = DebugLabel;
				debugLabel3.text = debugLabel3.text + "Source Object: " + droppedStruct.SourceObject.name + "\n";
			}
			DebugLabel.text += $"From {droppedStruct.FromList.name} at Index {droppedStruct.FromIndex} \n";
			DebugLabel.text += $"To {droppedStruct.ToList.name} at Index {droppedStruct.ToIndex} \n";
		}
	}
	[RequireComponent(typeof(RectTransform))]
	public class ReorderableListElement : MonoBehaviour, IDragHandler, IEventSystemHandler, IBeginDragHandler, IEndDragHandler
	{
		[Tooltip("Can this element be dragged?")]
		public bool IsGrabbable = true;

		[Tooltip("Can this element be transfered to another list")]
		public bool IsTransferable = true;

		[Tooltip("Can this element be dropped in space?")]
		public bool isDroppableInSpace;

		private readonly List<RaycastResult> _raycastResults = new List<RaycastResult>();

		private ReorderableList _currentReorderableListRaycasted;

		private RectTransform _draggingObject;

		private LayoutElement _draggingObjectLE;

		private Vector2 _draggingObjectOriginalSize;

		private RectTransform _fakeElement;

		private LayoutElement _fakeElementLE;

		private int _fromIndex;

		private bool _isDragging;

		private RectTransform _rect;

		private ReorderableList _reorderableList;

		internal bool isValid;

		public void OnBeginDrag(PointerEventData eventData)
		{
			isValid = true;
			if (_reorderableList == null)
			{
				return;
			}
			if (!_reorderableList.IsDraggable || !IsGrabbable)
			{
				_draggingObject = null;
				return;
			}
			if (!_reorderableList.CloneDraggedObject)
			{
				_draggingObject = _rect;
				_fromIndex = _rect.GetSiblingIndex();
				if (_reorderableList.OnElementRemoved != null)
				{
					_reorderableList.OnElementRemoved.Invoke(new ReorderableList.ReorderableListEventStruct
					{
						DroppedObject = _draggingObject.gameObject,
						IsAClone = _reorderableList.CloneDraggedObject,
						SourceObject = (_reorderableList.CloneDraggedObject ? base.gameObject : _draggingObject.gameObject),
						FromList = _reorderableList,
						FromIndex = _fromIndex
					});
				}
				if (!isValid)
				{
					_draggingObject = null;
					return;
				}
			}
			else
			{
				GameObject gameObject = Object.Instantiate(base.gameObject);
				_draggingObject = gameObject.GetComponent<RectTransform>();
			}
			_draggingObjectOriginalSize = base.gameObject.GetComponent<RectTransform>().rect.size;
			_draggingObjectLE = _draggingObject.GetComponent<LayoutElement>();
			_draggingObject.SetParent(_reorderableList.DraggableArea, worldPositionStays: true);
			_draggingObject.SetAsLastSibling();
			_fakeElement = new GameObject("Fake").AddComponent<RectTransform>();
			_fakeElementLE = _fakeElement.gameObject.AddComponent<LayoutElement>();
			RefreshSizes();
			if (_reorderableList.OnElementGrabbed != null)
			{
				_reorderableList.OnElementGrabbed.Invoke(new ReorderableList.ReorderableListEventStruct
				{
					DroppedObject = _draggingObject.gameObject,
					IsAClone = _reorderableList.CloneDraggedObject,
					SourceObject = (_reorderableList.CloneDraggedObject ? base.gameObject : _draggingObject.gameObject),
					FromList = _reorderableList,
					FromIndex = _fromIndex
				});
				if (!isValid)
				{
					CancelDrag();
					return;
				}
			}
			_isDragging = true;
		}

		public void OnDrag(PointerEventData eventData)
		{
			if (!_isDragging)
			{
				return;
			}
			if (!isValid)
			{
				CancelDrag();
				return;
			}
			Canvas componentInParent = _draggingObject.GetComponentInParent<Canvas>();
			RectTransformUtility.ScreenPointToWorldPointInRectangle(componentInParent.GetComponent<RectTransform>(), eventData.position, componentInParent.worldCamera, out var worldPoint);
			_draggingObject.position = worldPoint;
			EventSystem.current.RaycastAll(eventData, _raycastResults);
			for (int i = 0; i < _raycastResults.Count; i++)
			{
				_currentReorderableListRaycasted = _raycastResults[i].gameObject.GetComponent<ReorderableList>();
				if (_currentReorderableListRaycasted != null)
				{
					break;
				}
			}
			if (_currentReorderableListRaycasted == null || !_currentReorderableListRaycasted.IsDropable)
			{
				RefreshSizes();
				_fakeElement.transform.SetParent(_reorderableList.DraggableArea, worldPositionStays: false);
				return;
			}
			if (_fakeElement.parent != _currentReorderableListRaycasted)
			{
				_fakeElement.SetParent(_currentReorderableListRaycasted.Content, worldPositionStays: false);
			}
			float num = float.PositiveInfinity;
			int siblingIndex = 0;
			float num2 = 0f;
			for (int j = 0; j < _currentReorderableListRaycasted.Content.childCount; j++)
			{
				RectTransform component = _currentReorderableListRaycasted.Content.GetChild(j).GetComponent<RectTransform>();
				if (_currentReorderableListRaycasted.ContentLayout is VerticalLayoutGroup)
				{
					num2 = Mathf.Abs(component.position.y - worldPoint.y);
				}
				else if (_currentReorderableListRaycasted.ContentLayout is HorizontalLayoutGroup)
				{
					num2 = Mathf.Abs(component.position.x - worldPoint.x);
				}
				else if (_currentReorderableListRaycasted.ContentLayout is GridLayoutGroup)
				{
					num2 = Mathf.Abs(component.position.x - worldPoint.x) + Mathf.Abs(component.position.y - worldPoint.y);
				}
				if (num2 < num)
				{
					num = num2;
					siblingIndex = j;
				}
			}
			RefreshSizes();
			_fakeElement.SetSiblingIndex(siblingIndex);
			_fakeElement.gameObject.SetActive(value: true);
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			_isDragging = false;
			if (_draggingObject != null)
			{
				if (_currentReorderableListRaycasted != null && _currentReorderableListRaycasted.IsDropable && (IsTransferable || _currentReorderableListRaycasted == _reorderableList))
				{
					ReorderableList.ReorderableListEventStruct arg = new ReorderableList.ReorderableListEventStruct
					{
						DroppedObject = _draggingObject.gameObject,
						IsAClone = _reorderableList.CloneDraggedObject,
						SourceObject = (_reorderableList.CloneDraggedObject ? base.gameObject : _draggingObject.gameObject),
						FromList = _reorderableList,
						FromIndex = _fromIndex,
						ToList = _currentReorderableListRaycasted,
						ToIndex = _fakeElement.GetSiblingIndex()
					};
					if ((bool)_reorderableList && _reorderableList.OnElementDropped != null)
					{
						_reorderableList.OnElementDropped.Invoke(arg);
					}
					if (!isValid)
					{
						CancelDrag();
						return;
					}
					RefreshSizes();
					_draggingObject.SetParent(_currentReorderableListRaycasted.Content, worldPositionStays: false);
					_draggingObject.rotation = _currentReorderableListRaycasted.transform.rotation;
					_draggingObject.SetSiblingIndex(_fakeElement.GetSiblingIndex());
					_reorderableList.OnElementAdded.Invoke(arg);
					if (!isValid)
					{
						throw new Exception("It's too late to cancel the Transfer! Do so in OnElementDropped!");
					}
				}
				else if (isDroppableInSpace)
				{
					_reorderableList.OnElementDropped.Invoke(new ReorderableList.ReorderableListEventStruct
					{
						DroppedObject = _draggingObject.gameObject,
						IsAClone = _reorderableList.CloneDraggedObject,
						SourceObject = (_reorderableList.CloneDraggedObject ? base.gameObject : _draggingObject.gameObject),
						FromList = _reorderableList,
						FromIndex = _fromIndex
					});
				}
				else
				{
					CancelDrag();
				}
			}
			if (_fakeElement != null)
			{
				Object.Destroy(_fakeElement.gameObject);
			}
		}

		private void CancelDrag()
		{
			_isDragging = false;
			if (_reorderableList.CloneDraggedObject)
			{
				Object.Destroy(_draggingObject.gameObject);
			}
			else
			{
				RefreshSizes();
				_draggingObject.SetParent(_reorderableList.Content, worldPositionStays: false);
				_draggingObject.rotation = _reorderableList.Content.transform.rotation;
				_draggingObject.SetSiblingIndex(_fromIndex);
				ReorderableList.ReorderableListEventStruct arg = new ReorderableList.ReorderableListEventStruct
				{
					DroppedObject = _draggingObject.gameObject,
					IsAClone = _reorderableList.CloneDraggedObject,
					SourceObject = (_reorderableList.CloneDraggedObject ? base.gameObject : _draggingObject.gameObject),
					FromList = _reorderableList,
					FromIndex = _fromIndex,
					ToList = _reorderableList,
					ToIndex = _fromIndex
				};
				_reorderableList.OnElementAdded.Invoke(arg);
				if (!isValid)
				{
					throw new Exception("Transfer is already Cancelled.");
				}
			}
			if (_fakeElement != null)
			{
				Object.Destroy(_fakeElement.gameObject);
			}
		}

		private void RefreshSizes()
		{
			Vector2 sizeDelta = _draggingObjectOriginalSize;
			if (_currentReorderableListRaycasted != null && _currentReorderableListRaycasted.IsDropable && _currentReorderableListRaycasted.Content.childCount > 0)
			{
				Transform child = _currentReorderableListRaycasted.Content.GetChild(0);
				if (child != null)
				{
					sizeDelta = child.GetComponent<RectTransform>().rect.size;
				}
			}
			_draggingObject.sizeDelta = sizeDelta;
			LayoutElement fakeElementLE = _fakeElementLE;
			float preferredHeight = (_draggingObjectLE.preferredHeight = sizeDelta.y);
			fakeElementLE.preferredHeight = preferredHeight;
			LayoutElement fakeElementLE2 = _fakeElementLE;
			preferredHeight = (_draggingObjectLE.preferredWidth = sizeDelta.x);
			fakeElementLE2.preferredWidth = preferredHeight;
		}

		public void Init(ReorderableList reorderableList)
		{
			_reorderableList = reorderableList;
			_rect = GetComponent<RectTransform>();
		}
	}
	[AddComponentMenu("UI/Extensions/RescalePanels/RescaleDragPanel")]
	public class RescaleDragPanel : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IDragHandler
	{
		private Vector2 pointerOffset;

		private RectTransform canvasRectTransform;

		private RectTransform panelRectTransform;

		private Transform goTransform;

		private void Awake()
		{
			Canvas componentInParent = GetComponentInParent<Canvas>();
			if (componentInParent != null)
			{
				canvasRectTransform = componentInParent.transform as RectTransform;
				panelRectTransform = base.transform.parent as RectTransform;
				goTransform = base.transform.parent;
			}
		}

		public void OnPointerDown(PointerEventData data)
		{
			panelRectTransform.SetAsLastSibling();
			RectTransformUtility.ScreenPointToLocalPointInRectangle(panelRectTransform, data.position, data.pressEventCamera, out pointerOffset);
		}

		public void OnDrag(PointerEventData data)
		{
			if (!(panelRectTransform == null))
			{
				Vector2 screenPoint = ClampToWindow(data);
				if (RectTransformUtility.ScreenPointToLocalPointInRectangle(canvasRectTransform, screenPoint, data.pressEventCamera, out var localPoint))
				{
					panelRectTransform.localPosition = localPoint - new Vector2(pointerOffset.x * goTransform.localScale.x, pointerOffset.y * goTransform.localScale.y);
				}
			}
		}

		private Vector2 ClampToWindow(PointerEventData data)
		{
			Vector2 position = data.position;
			Vector3[] array = new Vector3[4];
			canvasRectTransform.GetWorldCorners(array);
			float x = Mathf.Clamp(position.x, array[0].x, array[2].x);
			float y = Mathf.Clamp(position.y, array[0].y, array[2].y);
			return new Vector2(x, y);
		}
	}
	[AddComponentMenu("UI/Extensions/RescalePanels/RescalePanel")]
	public class RescalePanel : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IDragHandler
	{
		public Vector2 minSize;

		public Vector2 maxSize;

		private RectTransform rectTransform;

		private Transform goTransform;

		private Vector2 currentPointerPosition;

		private Vector2 previousPointerPosition;

		private RectTransform thisRectTransform;

		private Vector2 sizeDelta;

		private void Awake()
		{
			rectTransform = base.transform.parent.GetComponent<RectTransform>();
			goTransform = base.transform.parent;
			thisRectTransform = GetComponent<RectTransform>();
			sizeDelta = thisRectTransform.sizeDelta;
		}

		public void OnPointerDown(PointerEventData data)
		{
			rectTransform.SetAsLastSibling();
			RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, data.position, data.pressEventCamera, out previousPointerPosition);
		}

		public void OnDrag(PointerEventData data)
		{
			if (!(rectTransform == null))
			{
				Vector3 localScale = goTransform.localScale;
				RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, data.position, data.pressEventCamera, out currentPointerPosition);
				Vector2 vector = currentPointerPosition - previousPointerPosition;
				localScale += new Vector3((0f - vector.y) * 0.001f, (0f - vector.y) * 0.001f, 0f);
				localScale = new Vector3(Mathf.Clamp(localScale.x, minSize.x, maxSize.x), Mathf.Clamp(localScale.y, minSize.y, maxSize.y), 1f);
				goTransform.localScale = localScale;
				previousPointerPosition = currentPointerPosition;
				float num = sizeDelta.x / goTransform.localScale.x;
				Vector2 vector2 = new Vector2(num, num);
				thisRectTransform.sizeDelta = vector2;
			}
		}
	}
	[AddComponentMenu("UI/Extensions/RescalePanels/ResizePanel")]
	public class ResizePanel : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IDragHandler
	{
		public Vector2 minSize;

		public Vector2 maxSize;

		private RectTransform rectTransform;

		private Vector2 currentPointerPosition;

		private Vector2 previousPointerPosition;

		private float ratio;

		private void Awake()
		{
			rectTransform = base.transform.parent.GetComponent<RectTransform>();
			float width = rectTransform.rect.width;
			float height = rectTransform.rect.height;
			ratio = height / width;
			minSize = new Vector2(0.1f * width, 0.1f * height);
			maxSize = new Vector2(10f * width, 10f * height);
		}

		public void OnPointerDown(PointerEventData data)
		{
			rectTransform.SetAsLastSibling();
			RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, data.position, data.pressEventCamera, out previousPointerPosition);
		}

		public void OnDrag(PointerEventData data)
		{
			if (!(rectTransform == null))
			{
				Vector2 sizeDelta = rectTransform.sizeDelta;
				RectTransformUtility.ScreenPointToLocalPointInRectangle(rectTransform, data.position, data.pressEventCamera, out currentPointerPosition);
				Vector2 vector = currentPointerPosition - previousPointerPosition;
				sizeDelta += new Vector2(vector.x, ratio * vector.x);
				sizeDelta = new Vector2(Mathf.Clamp(sizeDelta.x, minSize.x, maxSize.x), Mathf.Clamp(sizeDelta.y, minSize.y, maxSize.y));
				rectTransform.sizeDelta = sizeDelta;
				previousPointerPosition = currentPointerPosition;
			}
		}
	}
	[AddComponentMenu("UI/Extensions/Segmented Control")]
	[RequireComponent(typeof(RectTransform))]
	public class SegmentedControl : UIBehaviour
	{
		[Serializable]
		public class SegmentSelectedEvent : UnityEvent<int>
		{
		}

		private Selectable[] m_segments;

		[SerializeField]
		[Tooltip("A GameObject with an Image to use as a separator between segments. Size of the RectTransform will determine the size of the separator used.\nNote, make sure to disable the separator GO so that it does not affect the scene")]
		private Graphic m_separator;

		private float m_separatorWidth;

		[SerializeField]
		[Tooltip("When True, it allows each button to be toggled on/off")]
		private bool m_allowSwitchingOff;

		[SerializeField]
		[Tooltip("The selected default for the control (zero indexed array)")]
		private int m_selectedSegmentIndex = -1;

		[SerializeField]
		[Tooltip("Event to fire once the selection has been changed")]
		private SegmentSelectedEvent m_onValueChanged = new SegmentSelectedEvent();

		protected internal Selectable selectedSegment;

		[SerializeField]
		public Color selectedColor;

		protected float SeparatorWidth
		{
			get
			{
				if (m_separatorWidth == 0f && (bool)separator)
				{
					m_separatorWidth = separator.rectTransform.rect.width;
					Image component = separator.GetComponent<Image>();
					if ((bool)component)
					{
						m_separatorWidth /= component.pixelsPerUnit;
					}
				}
				return m_separatorWidth;
			}
		}

		public Selectable[] segments
		{
			get
			{
				if (m_segments == null || m_segments.Length == 0)
				{
					m_segments = GetChildSegments();
				}
				return m_segments;
			}
		}

		public Graphic separator
		{
			get
			{
				return m_separator;
			}
			set
			{
				m_separator = value;
				m_separatorWidth = 0f;
				LayoutSegments();
			}
		}

		public bool allowSwitchingOff
		{
			get
			{
				return m_allowSwitchingOff;
			}
			set
			{
				m_allowSwitchingOff = value;
			}
		}

		public int selectedSegmentIndex
		{
			get
			{
				return Array.IndexOf(segments, selectedSegment);
			}
			set
			{
				value = System.Math.Max(value, -1);
				value = System.Math.Min(value, segments.Length - 1);
				m_selectedSegmentIndex = value;
				if (value == -1)
				{
					if ((bool)selectedSegment)
					{
						selectedSegment.GetComponent<Segment>().selected = false;
						selectedSegment = null;
					}
				}
				else
				{
					segments[value].GetComponent<Segment>().selected = true;
				}
			}
		}

		public SegmentSelectedEvent onValueChanged
		{
			get
			{
				return m_onValueChanged;
			}
			set
			{
				m_onValueChanged = value;
			}
		}

		protected SegmentedControl()
		{
		}

		protected override void Start()
		{
			base.Start();
			LayoutSegments();
			if (m_selectedSegmentIndex != -1)
			{
				selectedSegmentIndex = m_selectedSegmentIndex;
			}
		}

		private Selectable[] GetChildSegments()
		{
			Selectable[] componentsInChildren = GetComponentsInChildren<Selectable>();
			if (componentsInChildren.Length < 2)
			{
				throw new InvalidOperationException("A segmented control must have at least two Button children");
			}
			for (int i = 0; i < componentsInChildren.Length; i++)
			{
				Segment segment = componentsInChildren[i].GetComponent<Segment>();
				if (segment == null)
				{
					segment = componentsInChildren[i].gameObject.AddComponent<Segment>();
				}
				segment.index = i;
			}
			return componentsInChildren;
		}

		public void SetAllSegmentsOff()
		{
			selectedSegment = null;
		}

		private void RecreateSprites()
		{
			for (int i = 0; i < segments.Length; i++)
			{
				if (segments[i].image == null)
				{
					continue;
				}
				Sprite sprite = segments[i].image.sprite;
				if (sprite.border.x != 0f && sprite.border.z != 0f)
				{
					Rect rect = sprite.rect;
					Vector4 border = sprite.border;
					if (i > 0)
					{
						rect.xMin = border.x;
						border.x = 0f;
					}
					if (i < segments.Length - 1)
					{
						rect.xMax = border.z;
						border.z = 0f;
					}
					segments[i].image.sprite = Sprite.Create(sprite.texture, rect, sprite.pivot, sprite.pixelsPerUnit, 0u, SpriteMeshType.FullRect, border);
				}
			}
		}

		public void LayoutSegments()
		{
			RecreateSprites();
			RectTransform rectTransform = base.transform as RectTransform;
			float num = rectTransform.rect.width / (float)segments.Length - SeparatorWidth * (float)(segments.Length - 1);
			for (int i = 0; i < segments.Length; i++)
			{
				float num2 = (num + SeparatorWidth) * (float)i;
				RectTransform component = segments[i].GetComponent<RectTransform>();
				component.anchorMin = Vector2.zero;
				component.anchorMax = Vector2.zero;
				component.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Left, num2, num);
				component.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Top, 0f, rectTransform.rect.height);
				if ((bool)separator && i > 0)
				{
					Transform transform = base.gameObject.transform.Find("Separator " + i);
					Graphic obj = ((transform != null) ? transform.GetComponent<Graphic>() : Object.Instantiate(separator.gameObject).GetComponent<Graphic>());
					obj.gameObject.name = "Separator " + i;
					obj.gameObject.SetActive(value: true);
					obj.rectTransform.SetParent(base.transform, worldPositionStays: false);
					obj.rectTransform.anchorMin = Vector2.zero;
					obj.rectTransform.anchorMax = Vector2.zero;
					obj.rectTransform.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Left, num2 - SeparatorWidth, SeparatorWidth);
					obj.rectTransform.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Top, 0f, rectTransform.rect.height);
				}
			}
		}
	}
	[RequireComponent(typeof(Selectable))]
	public class Segment : UIBehaviour, IPointerClickHandler, IEventSystemHandler, ISubmitHandler, IPointerEnterHandler, IPointerExitHandler, IPointerDownHandler, IPointerUpHandler, ISelectHandler, IDeselectHandler
	{
		internal int index;

		[SerializeField]
		private Color textColor;

		internal bool leftmost => index == 0;

		internal bool rightmost => index == segmentControl.segments.Length - 1;

		public bool selected
		{
			get
			{
				return segmentControl.selectedSegment == button;
			}
			set
			{
				SetSelected(value);
			}
		}

		internal SegmentedControl segmentControl => GetComponentInParent<SegmentedControl>();

		internal Selectable button => GetComponent<Selectable>();

		protected Segment()
		{
		}

		public virtual void OnPointerClick(PointerEventData eventData)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				selected = true;
			}
		}

		public virtual void OnPointerEnter(PointerEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnPointerExit(PointerEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnPointerDown(PointerEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnPointerUp(PointerEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnSelect(BaseEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnDeselect(BaseEventData eventData)
		{
			MaintainSelection();
		}

		public virtual void OnSubmit(BaseEventData eventData)
		{
			selected = true;
		}

		private void SetSelected(bool value)
		{
			if (value && button.IsActive() && button.IsInteractable())
			{
				if (segmentControl.selectedSegment == button)
				{
					if (segmentControl.allowSwitchingOff)
					{
						Deselect();
					}
					else
					{
						MaintainSelection();
					}
					return;
				}
				if ((bool)segmentControl.selectedSegment)
				{
					Segment component = segmentControl.selectedSegment.GetComponent<Segment>();
					segmentControl.selectedSegment = null;
					component.TransitionButton();
				}
				segmentControl.selectedSegment = button;
				StoreTextColor();
				TransitionButton();
				segmentControl.onValueChanged.Invoke(index);
			}
			else if (segmentControl.selectedSegment == button)
			{
				Deselect();
			}
		}

		private void Deselect()
		{
			segmentControl.selectedSegment = null;
			TransitionButton();
			segmentControl.onValueChanged.Invoke(-1);
		}

		private void MaintainSelection()
		{
			if (!(button != segmentControl.selectedSegment))
			{
				TransitionButton(instant: true);
			}
		}

		internal void TransitionButton()
		{
			TransitionButton(instant: false);
		}

		internal void TransitionButton(bool instant)
		{
			Color color = (selected ? segmentControl.selectedColor : button.colors.normalColor);
			Color color2 = (selected ? button.colors.normalColor : textColor);
			Sprite newSprite = (selected ? button.spriteState.pressedSprite : null);
			string triggername = (selected ? button.animationTriggers.pressedTrigger : button.animationTriggers.normalTrigger);
			switch (button.transition)
			{
			case Selectable.Transition.ColorTint:
				StartColorTween(color * button.colors.colorMultiplier, instant);
				ChangeTextColor(color2 * button.colors.colorMultiplier);
				break;
			case Selectable.Transition.SpriteSwap:
				DoSpriteSwap(newSprite);
				break;
			case Selectable.Transition.Animation:
				TriggerAnimation(triggername);
				break;
			}
		}

		private void StartColorTween(Color targetColor, bool instant)
		{
			if (!(button.targetGraphic == null))
			{
				button.targetGraphic.CrossFadeColor(targetColor, instant ? 0f : button.colors.fadeDuration, ignoreTimeScale: true, useAlpha: true);
			}
		}

		internal void StoreTextColor()
		{
			Text componentInChildren = GetComponentInChildren<Text>();
			if ((bool)componentInChildren)
			{
				textColor = componentInChildren.color;
			}
		}

		private void ChangeTextColor(Color targetColor)
		{
			Text componentInChildren = GetComponentInChildren<Text>();
			if ((bool)componentInChildren)
			{
				componentInChildren.color = targetColor;
			}
		}

		private void DoSpriteSwap(Sprite newSprite)
		{
			if (!(button.image == null))
			{
				button.image.overrideSprite = newSprite;
			}
		}

		private void TriggerAnimation(string triggername)
		{
			if (!(button.animator == null) && button.animator.isActiveAndEnabled && button.animator.hasBoundPlayables && !string.IsNullOrEmpty(triggername))
			{
				button.animator.ResetTrigger(button.animationTriggers.normalTrigger);
				button.animator.ResetTrigger(button.animationTriggers.pressedTrigger);
				button.animator.ResetTrigger(button.animationTriggers.highlightedTrigger);
				button.animator.ResetTrigger(button.animationTriggers.disabledTrigger);
				button.animator.SetTrigger(triggername);
			}
		}
	}
	public class ExampleSelectable : MonoBehaviour, IBoxSelectable
	{
		private bool _selected;

		private bool _preSelected;

		private SpriteRenderer spriteRenderer;

		private Image image;

		private Text text;

		public bool selected
		{
			get
			{
				return _selected;
			}
			set
			{
				_selected = value;
			}
		}

		public bool preSelected
		{
			get
			{
				return _preSelected;
			}
			set
			{
				_preSelected = value;
			}
		}

		private void Start()
		{
			spriteRenderer = base.transform.GetComponent<SpriteRenderer>();
			image = base.transform.GetComponent<Image>();
			text = base.transform.GetComponent<Text>();
		}

		private void Update()
		{
			Color color = Color.white;
			if (preSelected)
			{
				color = Color.yellow;
			}
			if (selected)
			{
				color = Color.green;
			}
			if ((bool)spriteRenderer)
			{
				spriteRenderer.color = color;
			}
			else if ((bool)text)
			{
				text.color = color;
			}
			else if ((bool)image)
			{
				image.color = color;
			}
			else if ((bool)GetComponent<Renderer>())
			{
				GetComponent<Renderer>().material.color = color;
			}
		}

		Transform IBoxSelectable.get_transform()
		{
			return base.transform;
		}
	}
	public interface IBoxSelectable
	{
		bool selected { get; set; }

		bool preSelected { get; set; }

		Transform transform { get; }
	}
	[RequireComponent(typeof(Canvas))]
	[AddComponentMenu("UI/Extensions/Selection Box")]
	public class SelectionBox : MonoBehaviour
	{
		public class SelectionEvent : UnityEvent<IBoxSelectable[]>
		{
		}

		public Color color;

		public Sprite art;

		private Vector2 origin;

		public RectTransform selectionMask;

		private RectTransform boxRect;

		private IBoxSelectable[] selectables;

		private MonoBehaviour[] selectableGroup;

		private IBoxSelectable clickedBeforeDrag;

		private IBoxSelectable clickedAfterDrag;

		public SelectionEvent onSelectionChange = new SelectionEvent();

		private void ValidateCanvas()
		{
			if (base.gameObject.GetComponent<Canvas>().renderMode != RenderMode.ScreenSpaceOverlay)
			{
				throw new Exception("SelectionBox component must be placed on a canvas in Screen Space Overlay mode.");
			}
			CanvasScaler component = base.gameObject.GetComponent<CanvasScaler>();
			if ((bool)component && component.enabled && (!Mathf.Approximately(component.scaleFactor, 1f) || component.uiScaleMode != CanvasScaler.ScaleMode.ConstantPixelSize))
			{
				Object.Destroy(component);
				Debug.LogWarning("SelectionBox component is on a gameObject with a Canvas Scaler component. As of now, Canvas Scalers without the default settings throw off the coordinates of the selection box. Canvas Scaler has been removed.");
			}
		}

		private void SetSelectableGroup(IEnumerable<MonoBehaviour> behaviourCollection)
		{
			if (behaviourCollection == null)
			{
				selectableGroup = null;
				return;
			}
			List<MonoBehaviour> list = new List<MonoBehaviour>();
			foreach (MonoBehaviour item in behaviourCollection)
			{
				if (item is IBoxSelectable)
				{
					list.Add(item);
				}
			}
			selectableGroup = list.ToArray();
		}

		private void CreateBoxRect()
		{
			GameObject gameObject = new GameObject();
			gameObject.name = "Selection Box";
			gameObject.transform.parent = base.transform;
			gameObject.AddComponent<Image>();
			boxRect = gameObject.transform as RectTransform;
		}

		private void ResetBoxRect()
		{
			Image component = boxRect.GetComponent<Image>();
			component.color = color;
			component.sprite = art;
			origin = Vector2.zero;
			boxRect.anchoredPosition = Vector2.zero;
			boxRect.sizeDelta = Vector2.zero;
			boxRect.anchorMax = Vector2.zero;
			boxRect.anchorMin = Vector2.zero;
			boxRect.pivot = Vector2.zero;
			boxRect.gameObject.SetActive(value: false);
		}

		private void BeginSelection()
		{
			if (!Input.GetMouseButtonDown(0))
			{
				return;
			}
			boxRect.gameObject.SetActive(value: true);
			origin = new Vector2(Input.mousePosition.x, Input.mousePosition.y);
			if (!PointIsValidAgainstSelectionMask(origin))
			{
				ResetBoxRect();
				return;
			}
			boxRect.anchoredPosition = origin;
			MonoBehaviour[] array = ((selectableGroup != null) ? selectableGroup : Object.FindObjectsByType<MonoBehaviour>(FindObjectsSortMode.None));
			List<IBoxSelectable> list = new List<IBoxSelectable>();
			MonoBehaviour[] array2 = array;
			for (int i = 0; i < array2.Length; i++)
			{
				if (array2[i] is IBoxSelectable boxSelectable)
				{
					list.Add(boxSelectable);
					if (!Input.GetKey(KeyCode.LeftShift))
					{
						boxSelectable.selected = false;
					}
				}
			}
			selectables = list.ToArray();
			clickedBeforeDrag = GetSelectableAtMousePosition();
		}

		private bool PointIsValidAgainstSelectionMask(Vector2 screenPoint)
		{
			if (!selectionMask)
			{
				return true;
			}
			Camera screenPointCamera = GetScreenPointCamera(selectionMask);
			return RectTransformUtility.RectangleContainsScreenPoint(selectionMask, screenPoint, screenPointCamera);
		}

		private IBoxSelectable GetSelectableAtMousePosition()
		{
			if (!PointIsValidAgainstSelectionMask(Input.mousePosition))
			{
				return null;
			}
			IBoxSelectable[] array = selectables;
			foreach (IBoxSelectable boxSelectable in array)
			{
				RectTransform rectTransform = boxSelectable.transform as RectTransform;
				if ((bool)rectTransform)
				{
					Camera screenPointCamera = GetScreenPointCamera(rectTransform);
					if (RectTransformUtility.RectangleContainsScreenPoint(rectTransform, Input.mousePosition, screenPointCamera))
					{
						return boxSelectable;
					}
				}
				else
				{
					float magnitude = boxSelectable.transform.GetComponent<Renderer>().bounds.extents.magnitude;
					if (Vector2.Distance(GetScreenPointOfSelectable(boxSelectable), (Vector2)Input.mousePosition) <= magnitude)
					{
						return boxSelectable;
					}
				}
			}
			return null;
		}

		private void DragSelection()
		{
			if (Input.GetMouseButton(0) && boxRect.gameObject.activeSelf)
			{
				Vector2 vector = new Vector2(Input.mousePosition.x, Input.mousePosition.y);
				Vector2 sizeDelta = vector - origin;
				Vector2 anchoredPosition = origin;
				if (sizeDelta.x < 0f)
				{
					anchoredPosition.x = vector.x;
					sizeDelta.x = 0f - sizeDelta.x;
				}
				if (sizeDelta.y < 0f)
				{
					anchoredPosition.y = vector.y;
					sizeDelta.y = 0f - sizeDelta.y;
				}
				boxRect.anchoredPosition = anchoredPosition;
				boxRect.sizeDelta = sizeDelta;
				IBoxSelectable[] array = selectables;
				foreach (IBoxSelectable boxSelectable in array)
				{
					Vector3 vector2 = GetScreenPointOfSelectable(boxSelectable);
					boxSelectable.preSelected = RectTransformUtility.RectangleContainsScreenPoint(boxRect, vector2, null) && PointIsValidAgainstSelectionMask(vector2);
				}
				if (clickedBeforeDrag != null)
				{
					clickedBeforeDrag.preSelected = true;
				}
			}
		}

		private void ApplySingleClickDeselection()
		{
			if (clickedBeforeDrag != null && clickedAfterDrag != null && clickedBeforeDrag.selected && clickedBeforeDrag.transform == clickedAfterDrag.transform)
			{
				clickedBeforeDrag.selected = false;
				clickedBeforeDrag.preSelected = false;
			}
		}

		private void ApplyPreSelections()
		{
			IBoxSelectable[] array = selectables;
			foreach (IBoxSelectable boxSelectable in array)
			{
				if (boxSelectable.preSelected)
				{
					boxSelectable.selected = true;
					boxSelectable.preSelected = false;
				}
			}
		}

		private Vector2 GetScreenPointOfSelectable(IBoxSelectable selectable)
		{
			RectTransform rectTransform = selectable.transform as RectTransform;
			if ((bool)rectTransform)
			{
				return RectTransformUtility.WorldToScreenPoint(GetScreenPointCamera(rectTransform), selectable.transform.position);
			}
			return Camera.main.WorldToScreenPoint(selectable.transform.position);
		}

		private Camera GetScreenPointCamera(RectTransform rectTransform)
		{
			Canvas canvas = null;
			RectTransform rectTransform2 = rectTransform;
			do
			{
				canvas = rectTransform2.GetComponent<Canvas>();
				if ((bool)canvas && !canvas.isRootCanvas)
				{
					canvas = null;
				}
				rectTransform2 = (RectTransform)rectTransform2.parent;
			}
			while (canvas == null);
			switch (canvas.renderMode)
			{
			case RenderMode.ScreenSpaceOverlay:
				return null;
			case RenderMode.ScreenSpaceCamera:
				if (!canvas.worldCamera)
				{
					return Camera.main;
				}
				return canvas.worldCamera;
			default:
				return Camera.main;
			}
		}

		public IBoxSelectable[] GetAllSelected()
		{
			if (selectables == null)
			{
				return new IBoxSelectable[0];
			}
			List<IBoxSelectable> list = new List<IBoxSelectable>();
			IBoxSelectable[] array = selectables;
			foreach (IBoxSelectable boxSelectable in array)
			{
				if (boxSelectable.selected)
				{
					list.Add(boxSelectable);
				}
			}
			return list.ToArray();
		}

		private void EndSelection()
		{
			if (Input.GetMouseButtonUp(0) && boxRect.gameObject.activeSelf)
			{
				clickedAfterDrag = GetSelectableAtMousePosition();
				ApplySingleClickDeselection();
				ApplyPreSelections();
				ResetBoxRect();
				onSelectionChange.Invoke(GetAllSelected());
			}
		}

		private void Start()
		{
			ValidateCanvas();
			CreateBoxRect();
			ResetBoxRect();
		}

		private void Update()
		{
			BeginSelection();
			DragSelection();
			EndSelection();
		}
	}
	[AddComponentMenu("UI/Extensions/Stepper")]
	[RequireComponent(typeof(RectTransform))]
	public class Stepper : UIBehaviour
	{
		[Serializable]
		public class StepperValueChangedEvent : UnityEvent<int>
		{
		}

		private Selectable[] _sides;

		[SerializeField]
		[Tooltip("The current step value of the control")]
		private int _value;

		[SerializeField]
		[Tooltip("The minimum step value allowed by the control. When reached it will disable the '-' button")]
		private int _minimum;

		[SerializeField]
		[Tooltip("The maximum step value allowed by the control. When reached it will disable the '+' button")]
		private int _maximum = 100;

		[SerializeField]
		[Tooltip("The step increment used to increment / decrement the step value")]
		private int _step = 1;

		[SerializeField]
		[Tooltip("Does the step value loop around from end to end")]
		private bool _wrap;

		[SerializeField]
		[Tooltip("A GameObject with an Image to use as a separator between segments. Size of the RectTransform will determine the size of the separator used.\nNote, make sure to disable the separator GO so that it does not affect the scene")]
		private Graphic _separator;

		private float _separatorWidth;

		[SerializeField]
		private StepperValueChangedEvent _onValueChanged = new StepperValueChangedEvent();

		private float separatorWidth
		{
			get
			{
				if (_separatorWidth == 0f && (bool)separator)
				{
					_separatorWidth = separator.rectTransform.rect.width;
					Image component = separator.GetComponent<Image>();
					if ((bool)component)
					{
						_separatorWidth /= component.pixelsPerUnit;
					}
				}
				return _separatorWidth;
			}
		}

		public Selectable[] sides
		{
			get
			{
				if (_sides == null || _sides.Length == 0)
				{
					_sides = GetSides();
				}
				return _sides;
			}
		}

		public int value
		{
			get
			{
				return _value;
			}
			set
			{
				_value = value;
			}
		}

		public int minimum
		{
			get
			{
				return _minimum;
			}
			set
			{
				_minimum = value;
			}
		}

		public int maximum
		{
			get
			{
				return _maximum;
			}
			set
			{
				_maximum = value;
			}
		}

		public int step
		{
			get
			{
				return _step;
			}
			set
			{
				_step = value;
			}
		}

		public bool wrap
		{
			get
			{
				return _wrap;
			}
			set
			{
				_wrap = value;
			}
		}

		public Graphic separator
		{
			get
			{
				return _separator;
			}
			set
			{
				_separator = value;
				_separatorWidth = 0f;
				LayoutSides(sides);
			}
		}

		public StepperValueChangedEvent onValueChanged
		{
			get
			{
				return _onValueChanged;
			}
			set
			{
				_onValueChanged = value;
			}
		}

		protected Stepper()
		{
		}

		private Selectable[] GetSides()
		{
			Selectable[] componentsInChildren = GetComponentsInChildren<Selectable>();
			if (componentsInChildren.Length != 2)
			{
				throw new InvalidOperationException("A stepper must have two Button children");
			}
			for (int i = 0; i < 2; i++)
			{
				if (componentsInChildren[i].GetComponent<StepperSide>() == null)
				{
					componentsInChildren[i].gameObject.AddComponent<StepperSide>();
				}
			}
			if (!wrap)
			{
				DisableAtExtremes(componentsInChildren);
			}
			LayoutSides(componentsInChildren);
			return componentsInChildren;
		}

		public void StepUp()
		{
			Step(step);
		}

		public void StepDown()
		{
			Step(-step);
		}

		private void Step(int amount)
		{
			value += amount;
			if (wrap)
			{
				if (value > maximum)
				{
					value = minimum;
				}
				if (value < minimum)
				{
					value = maximum;
				}
			}
			else
			{
				value = System.Math.Max(minimum, value);
				value = System.Math.Min(maximum, value);
				DisableAtExtremes(sides);
			}
			_onValueChanged.Invoke(value);
		}

		private void DisableAtExtremes(Selectable[] sides)
		{
			sides[0].interactable = wrap || value > minimum;
			sides[1].interactable = wrap || value < maximum;
		}

		private void RecreateSprites(Selectable[] sides)
		{
			for (int i = 0; i < 2; i++)
			{
				if (sides[i].image == null)
				{
					continue;
				}
				Sprite sprite = sides[i].image.sprite;
				if (sprite.border.x != 0f && sprite.border.z != 0f)
				{
					Rect rect = sprite.rect;
					Vector4 border = sprite.border;
					if (i == 0)
					{
						rect.xMax = border.z;
						border.z = 0f;
					}
					else
					{
						rect.xMin = border.x;
						border.x = 0f;
					}
					sides[i].image.sprite = Sprite.Create(sprite.texture, rect, sprite.pivot, sprite.pixelsPerUnit, 0u, SpriteMeshType.FullRect, border);
				}
			}
		}

		public void LayoutSides(Selectable[] sides = null)
		{
			sides = sides ?? this.sides;
			RecreateSprites(sides);
			RectTransform rectTransform = base.transform as RectTransform;
			float num = rectTransform.rect.width / 2f - separatorWidth;
			for (int i = 0; i < 2; i++)
			{
				float inset = ((i == 0) ? 0f : (num + separatorWidth));
				RectTransform component = sides[i].GetComponent<RectTransform>();
				component.anchorMin = Vector2.zero;
				component.anchorMax = Vector2.zero;
				component.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Left, inset, num);
				component.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Top, 0f, rectTransform.rect.height);
			}
			if ((bool)separator)
			{
				Transform transform = base.gameObject.transform.Find("Separator");
				Graphic obj = ((transform != null) ? transform.GetComponent<Graphic>() : Object.Instantiate(separator.gameObject).GetComponent<Graphic>());
				obj.gameObject.name = "Separator";
				obj.gameObject.SetActive(value: true);
				obj.rectTransform.SetParent(base.transform, worldPositionStays: false);
				obj.rectTransform.anchorMin = Vector2.zero;
				obj.rectTransform.anchorMax = Vector2.zero;
				obj.rectTransform.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Left, num, separatorWidth);
				obj.rectTransform.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Top, 0f, rectTransform.rect.height);
			}
		}
	}
	[RequireComponent(typeof(Selectable))]
	public class StepperSide : UIBehaviour, IPointerClickHandler, IEventSystemHandler, ISubmitHandler
	{
		private Selectable button => GetComponent<Selectable>();

		private Stepper stepper => GetComponentInParent<Stepper>();

		private bool leftmost => button == stepper.sides[0];

		protected StepperSide()
		{
		}

		public virtual void OnPointerClick(PointerEventData eventData)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				Press();
			}
		}

		public virtual void OnSubmit(BaseEventData eventData)
		{
			Press();
		}

		private void Press()
		{
			if (button.IsActive() && button.IsInteractable())
			{
				if (leftmost)
				{
					stepper.StepDown();
				}
				else
				{
					stepper.StepUp();
				}
			}
		}
	}
	[AddComponentMenu("UI/Extensions/TextPic")]
	[ExecuteInEditMode]
	public class TextPic : Text, IPointerClickHandler, IEventSystemHandler, IPointerExitHandler, IPointerEnterHandler, ISelectHandler
	{
		[Serializable]
		public struct IconName
		{
			public string name;

			public Sprite sprite;

			public Vector2 offset;

			public Vector2 scale;
		}

		[Serializable]
		public class HrefClickEvent : UnityEvent<string>
		{
		}

		private class HrefInfo
		{
			public int startIndex;

			public int endIndex;

			public string name;

			public readonly List<Rect> boxes = new List<Rect>();
		}

		private readonly List<Image> m_ImagesPool = new List<Image>();

		private readonly List<GameObject> culled_ImagesPool = new List<GameObject>();

		private bool clearImages;

		private Object thisLock = new Object();

		private readonly List<int> m_ImagesVertexIndex = new List<int>();

		private static readonly Regex s_Regex = new Regex("<quad name=(.+?) size=(\\d*\\.?\\d+%?) width=(\\d*\\.?\\d+%?) />", RegexOptions.Singleline);

		private string fixedString;

		[SerializeField]
		[Tooltip("Allow click events to be received by parents, (default) blocks")]
		private bool m_ClickParents;

		private string m_OutputText;

		public IconName[] inspectorIconList;

		[Tooltip("Global scaling factor for all images")]
		public float ImageScalingFactor = 1f;

		public string hyperlinkColor = "blue";

		[SerializeField]
		public Vector2 imageOffset = Vector2.zero;

		private Button button;

		private Selectable highlightselectable;

		private List<Vector2> positions = new List<Vector2>();

		private string previousText = "";

		public bool isCreating_m_HrefInfos = true;

		private readonly List<HrefInfo> m_HrefInfos = new List<HrefInfo>();

		private static readonly StringBuilder s_TextBuilder = new StringBuilder();

		private static readonly Regex s_HrefRegex = new Regex("<a href=([^>\\n\\s]+)>(.*?)(</a>)", RegexOptions.Singleline);

		[SerializeField]
		private HrefClickEvent m_OnHrefClick = new HrefClickEvent();

		public bool AllowClickParents
		{
			get
			{
				return m_ClickParents;
			}
			set
			{
				m_ClickParents = value;
			}
		}

		public HrefClickEvent onHrefClick
		{
			get
			{
				return m_OnHrefClick;
			}
			set
			{
				m_OnHrefClick = value;
			}
		}

		public override void SetVerticesDirty()
		{
			base.SetVerticesDirty();
			UpdateQuadImage();
		}

		private new void Start()
		{
			button = GetComponentInParent<Button>();
			if (button != null)
			{
				CanvasGroup canvasGroup = GetComponent<CanvasGroup>();
				if (canvasGroup == null)
				{
					canvasGroup = base.gameObject.AddComponent<CanvasGroup>();
				}
				canvasGroup.blocksRaycasts = false;
				highlightselectable = canvasGroup.GetComponent<Selectable>();
			}
			else
			{
				highlightselectable = GetComponent<Selectable>();
			}
			Reset_m_HrefInfos();
			base.Start();
		}

		protected void UpdateQuadImage()
		{
			m_OutputText = GetOutputText();
			m_ImagesVertexIndex.Clear();
			foreach (Match item2 in s_Regex.Matches(m_OutputText))
			{
				int item = item2.Index * 4 + 3;
				m_ImagesVertexIndex.Add(item);
				m_ImagesPool.RemoveAll((Image image2) => image2 == null);
				if (m_ImagesPool.Count == 0)
				{
					GetComponentsInChildren(m_ImagesPool);
				}
				if (m_ImagesVertexIndex.Count > m_ImagesPool.Count)
				{
					GameObject gameObject = DefaultControls.CreateImage(default(DefaultControls.Resources));
					gameObject.layer = base.gameObject.layer;
					RectTransform rectTransform = gameObject.transform as RectTransform;
					if ((bool)rectTransform)
					{
						rectTransform.SetParent(base.rectTransform);
						rectTransform.localPosition = Vector3.zero;
						rectTransform.localRotation = Quaternion.identity;
						rectTransform.localScale = Vector3.one;
					}
					m_ImagesPool.Add(gameObject.GetComponent<Image>());
				}
				string value = item2.Groups[1].Value;
				Image image = m_ImagesPool[m_ImagesVertexIndex.Count - 1];
				Vector2 vector = Vector2.zero;
				if ((image.sprite == null || image.sprite.name != value) && inspectorIconList != null && inspectorIconList.Length != 0)
				{
					IconName[] array = inspectorIconList;
					for (int num = 0; num < array.Length; num++)
					{
						IconName iconName = array[num];
						if (iconName.name == value)
						{
							image.sprite = iconName.sprite;
							image.rectTransform.sizeDelta = new Vector2((float)base.fontSize * ImageScalingFactor * iconName.scale.x, (float)base.fontSize * ImageScalingFactor * iconName.scale.y);
							vector = iconName.offset;
							break;
						}
					}
				}
				image.enabled = true;
				if (positions.Count == m_ImagesPool.Count)
				{
					image.rectTransform.anchoredPosition = (positions[m_ImagesVertexIndex.Count - 1] += vector);
				}
			}
			for (int num2 = m_ImagesVertexIndex.Count; num2 < m_ImagesPool.Count; num2++)
			{
				if ((bool)m_ImagesPool[num2])
				{
					m_ImagesPool[num2].gameObject.SetActive(value: false);
					m_ImagesPool[num2].gameObject.hideFlags = HideFlags.HideAndDontSave;
					culled_ImagesPool.Add(m_ImagesPool[num2].gameObject);
					m_ImagesPool.Remove(m_ImagesPool[num2]);
				}
			}
			if (culled_ImagesPool.Count > 1)
			{
				clearImages = true;
			}
		}

		protected override void OnPopulateMesh(VertexHelper toFill)
		{
			string text = m_Text;
			m_Text = GetOutputText();
			base.OnPopulateMesh(toFill);
			m_Text = text;
			positions.Clear();
			UIVertex vertex = default(UIVertex);
			for (int i = 0; i < m_ImagesVertexIndex.Count; i++)
			{
				int num = m_ImagesVertexIndex[i];
				Vector2 sizeDelta = m_ImagesPool[i].rectTransform.sizeDelta;
				if (num < toFill.currentVertCount)
				{
					toFill.PopulateUIVertex(ref vertex, num);
					positions.Add(new Vector2(vertex.position.x + sizeDelta.x / 2f, vertex.position.y + sizeDelta.y / 2f) + imageOffset);
					toFill.PopulateUIVertex(ref vertex, num - 3);
					Vector3 position = vertex.position;
					int num2 = num;
					int num3 = num - 3;
					while (num2 > num3)
					{
						toFill.PopulateUIVertex(ref vertex, num);
						vertex.position = position;
						toFill.SetUIVertex(vertex, num2);
						num2--;
					}
				}
			}
			if (m_ImagesVertexIndex.Count != 0)
			{
				m_ImagesVertexIndex.Clear();
			}
			foreach (HrefInfo hrefInfo in m_HrefInfos)
			{
				hrefInfo.boxes.Clear();
				if (hrefInfo.startIndex >= toFill.currentVertCount)
				{
					continue;
				}
				toFill.PopulateUIVertex(ref vertex, hrefInfo.startIndex);
				Vector3 position2 = vertex.position;
				Bounds bounds = new Bounds(position2, Vector3.zero);
				int j = hrefInfo.startIndex;
				for (int endIndex = hrefInfo.endIndex; j < endIndex && j < toFill.currentVertCount; j++)
				{
					toFill.PopulateUIVertex(ref vertex, j);
					position2 = vertex.position;
					if (position2.x < bounds.min.x)
					{
						hrefInfo.boxes.Add(new Rect((Vector2)bounds.min, (Vector2)bounds.size));
						bounds = new Bounds(position2, Vector3.zero);
					}
					else
					{
						bounds.Encapsulate(position2);
					}
				}
				hrefInfo.boxes.Add(new Rect((Vector2)bounds.min, (Vector2)bounds.size));
			}
			UpdateQuadImage();
		}

		protected string GetOutputText()
		{
			s_TextBuilder.Length = 0;
			int num = 0;
			fixedString = text;
			if (inspectorIconList != null && inspectorIconList.Length != 0)
			{
				IconName[] array = inspectorIconList;
				for (int i = 0; i < array.Length; i++)
				{
					IconName iconName = array[i];
					if (iconName.name != null && iconName.name != "")
					{
						fixedString = fixedString.Replace(iconName.name, "<quad name=" + iconName.name + " size=" + base.fontSize + " width=1 />");
					}
				}
			}
			int num2 = 0;
			foreach (Match item2 in s_HrefRegex.Matches(fixedString))
			{
				s_TextBuilder.Append(fixedString.Substring(num, item2.Index - num));
				s_TextBuilder.Append("<color=" + hyperlinkColor + ">");
				Group obj = item2.Groups[1];
				if (isCreating_m_HrefInfos)
				{
					HrefInfo item = new HrefInfo
					{
						startIndex = s_TextBuilder.Length * 4,
						endIndex = (s_TextBuilder.Length + item2.Groups[2].Length - 1) * 4 + 3,
						name = obj.Value
					};
					m_HrefInfos.Add(item);
				}
				else if (m_HrefInfos.Count > 0)
				{
					m_HrefInfos[num2].startIndex = s_TextBuilder.Length * 4;
					m_HrefInfos[num2].endIndex = (s_TextBuilder.Length + item2.Groups[2].Length - 1) * 4 + 3;
					num2++;
				}
				s_TextBuilder.Append(item2.Groups[2].Value);
				s_TextBuilder.Append("</color>");
				num = item2.Index + item2.Length;
			}
			if (isCreating_m_HrefInfos)
			{
				isCreating_m_HrefInfos = false;
			}
			s_TextBuilder.Append(fixedString.Substring(num, fixedString.Length - num));
			return s_TextBuilder.ToString();
		}

		public void OnPointerClick(PointerEventData eventData)
		{
			RectTransformUtility.ScreenPointToLocalPointInRectangle(base.rectTransform, eventData.position, eventData.pressEventCamera, out var localPoint);
			foreach (HrefInfo hrefInfo in m_HrefInfos)
			{
				List<Rect> boxes = hrefInfo.boxes;
				for (int i = 0; i < boxes.Count; i++)
				{
					if (boxes[i].Contains(localPoint))
					{
						m_OnHrefClick.Invoke(hrefInfo.name);
						return;
					}
				}
			}
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			if (m_ImagesPool.Count < 1)
			{
				return;
			}
			foreach (Image item in m_ImagesPool)
			{
				if (highlightselectable != null && highlightselectable.isActiveAndEnabled)
				{
					item.color = highlightselectable.colors.highlightedColor;
				}
			}
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			if (m_ImagesPool.Count < 1)
			{
				return;
			}
			foreach (Image item in m_ImagesPool)
			{
				if (highlightselectable != null && highlightselectable.isActiveAndEnabled)
				{
					item.color = highlightselectable.colors.normalColor;
				}
				else
				{
					item.color = color;
				}
			}
		}

		public void OnSelect(BaseEventData eventData)
		{
			if (m_ImagesPool.Count < 1)
			{
				return;
			}
			foreach (Image item in m_ImagesPool)
			{
				if (highlightselectable != null && highlightselectable.isActiveAndEnabled)
				{
					item.color = highlightselectable.colors.highlightedColor;
				}
			}
		}

		private void Update()
		{
			lock (thisLock)
			{
				if (clearImages)
				{
					for (int i = 0; i < culled_ImagesPool.Count; i++)
					{
						Object.DestroyImmediate(culled_ImagesPool[i]);
					}
					culled_ImagesPool.Clear();
					clearImages = false;
				}
			}
			if (previousText != text)
			{
				Reset_m_HrefInfos();
			}
		}

		private void Reset_m_HrefInfos()
		{
			previousText = text;
			m_HrefInfos.Clear();
			isCreating_m_HrefInfos = true;
		}
	}
	[RequireComponent(typeof(Image))]
	[AddComponentMenu("UI/Extensions/UI_Knob")]
	public class UI_Knob : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IPointerUpHandler, IPointerEnterHandler, IPointerExitHandler, IBeginDragHandler, IDragHandler
	{
		public enum Direction
		{
			CW,
			CCW
		}

		[Tooltip("Direction of rotation CW - clockwise, CCW - counterClockwise")]
		public Direction direction;

		[HideInInspector]
		public float knobValue;

		[Tooltip("Max value of the knob, maximum RAW output value knob can reach, overrides snap step, IF set to 0 or higher than loops, max value will be set by loops")]
		public float maxValue;

		[Tooltip("How many rotations knob can do, if higher than max value, the latter will limit max value")]
		public int loops = 1;

		[Tooltip("Clamp output value between 0 and 1, usefull with loops > 1")]
		public bool clampOutput01;

		[Tooltip("snap to position?")]
		public bool snapToPosition;

		[Tooltip("Number of positions to snap")]
		public int snapStepsPerLoop = 10;

		[Space(30f)]
		public KnobFloatValueEvent OnValueChanged;

		private float _currentLoops;

		private float _previousValue;

		private float _initAngle;

		private float _currentAngle;

		private Vector2 _currentVector;

		private Quaternion _initRotation;

		private bool _canDrag;

		public void OnPointerDown(PointerEventData eventData)
		{
			_canDrag = true;
		}

		public void OnPointerUp(PointerEventData eventData)
		{
			_canDrag = false;
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			_canDrag = true;
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			_canDrag = false;
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			SetInitPointerData(eventData);
		}

		private void SetInitPointerData(PointerEventData eventData)
		{
			_initRotation = base.transform.rotation;
			_currentVector = eventData.position - (Vector2)base.transform.position;
			_initAngle = Mathf.Atan2(_currentVector.y, _currentVector.x) * 57.29578f;
		}

		public void OnDrag(PointerEventData eventData)
		{
			if (!_canDrag)
			{
				SetInitPointerData(eventData);
				return;
			}
			_currentVector = eventData.position - (Vector2)base.transform.position;
			_currentAngle = Mathf.Atan2(_currentVector.y, _currentVector.x) * 57.29578f;
			Quaternion quaternion = Quaternion.AngleAxis(_currentAngle - _initAngle, base.transform.forward);
			quaternion.eulerAngles = new Vector3(0f, 0f, quaternion.eulerAngles.z);
			Quaternion rotation = _initRotation * quaternion;
			if (direction == Direction.CW)
			{
				knobValue = 1f - rotation.eulerAngles.z / 360f;
				if (snapToPosition)
				{
					SnapToPosition(ref knobValue);
					rotation.eulerAngles = new Vector3(0f, 0f, 360f - 360f * knobValue);
				}
			}
			else
			{
				knobValue = rotation.eulerAngles.z / 360f;
				if (snapToPosition)
				{
					SnapToPosition(ref knobValue);
					rotation.eulerAngles = new Vector3(0f, 0f, 360f * knobValue);
				}
			}
			if (Mathf.Abs(knobValue - _previousValue) > 0.5f)
			{
				if (knobValue < 0.5f && loops > 1 && _currentLoops < (float)(loops - 1))
				{
					_currentLoops += 1f;
				}
				else if (knobValue > 0.5f && _currentLoops >= 1f)
				{
					_currentLoops -= 1f;
				}
				else
				{
					if (knobValue > 0.5f && _currentLoops == 0f)
					{
						knobValue = 0f;
						base.transform.localEulerAngles = Vector3.zero;
						SetInitPointerData(eventData);
						InvokeEvents(knobValue + _currentLoops);
						return;
					}
					if (knobValue < 0.5f && _currentLoops == (float)(loops - 1))
					{
						knobValue = 1f;
						base.transform.localEulerAngles = Vector3.zero;
						SetInitPointerData(eventData);
						InvokeEvents(knobValue + _currentLoops);
						return;
					}
				}
			}
			if (maxValue > 0f && knobValue + _currentLoops > maxValue)
			{
				knobValue = maxValue;
				float z = ((direction == Direction.CW) ? (360f - 360f * maxValue) : (360f * maxValue));
				base.transform.localEulerAngles = new Vector3(0f, 0f, z);
				SetInitPointerData(eventData);
				InvokeEvents(knobValue);
			}
			else
			{
				base.transform.rotation = rotation;
				InvokeEvents(knobValue + _currentLoops);
				_previousValue = knobValue;
			}
		}

		private void SnapToPosition(ref float knobValue)
		{
			float num = 1f / (float)snapStepsPerLoop;
			float num2 = Mathf.Round(knobValue / num) * num;
			knobValue = num2;
		}

		private void InvokeEvents(float value)
		{
			if (clampOutput01)
			{
				value /= (float)loops;
			}
			OnValueChanged.Invoke(value);
		}
	}
	[Serializable]
	public class KnobFloatValueEvent : UnityEvent<float>
	{
	}
	[AddComponentMenu("UI/Effects/Extensions/BestFit Outline")]
	public class BestFitOutline : Shadow
	{
		protected BestFitOutline()
		{
		}

		public override void ModifyMesh(Mesh mesh)
		{
			if (!IsActive())
			{
				return;
			}
			List<UIVertex> list = new List<UIVertex>();
			using (VertexHelper vertexHelper = new VertexHelper(mesh))
			{
				vertexHelper.GetUIVertexStream(list);
			}
			Text component = GetComponent<Text>();
			float num = 1f;
			if ((bool)component && component.resizeTextForBestFit)
			{
				num = (float)component.cachedTextGenerator.fontSizeUsedForBestFit / (float)(component.resizeTextMaxSize - 1);
			}
			int start = 0;
			int count = list.Count;
			ApplyShadowZeroAlloc(list, base.effectColor, start, list.Count, base.effectDistance.x * num, base.effectDistance.y * num);
			start = count;
			int count2 = list.Count;
			ApplyShadowZeroAlloc(list, base.effectColor, start, list.Count, base.effectDistance.x * num, (0f - base.effectDistance.y) * num);
			start = count2;
			int count3 = list.Count;
			ApplyShadowZeroAlloc(list, base.effectColor, start, list.Count, (0f - base.effectDistance.x) * num, base.effectDistance.y * num);
			start = count3;
			_ = list.Count;
			ApplyShadowZeroAlloc(list, base.effectColor, start, list.Count, (0f - base.effectDistance.x) * num, (0f - base.effectDistance.y) * num);
			using VertexHelper vertexHelper2 = new VertexHelper();
			vertexHelper2.AddUIVertexTriangleStream(list);
			vertexHelper2.FillMesh(mesh);
		}
	}
	public class CUIBezierCurve : MonoBehaviour
	{
		public static readonly int CubicBezierCurvePtNum = 4;

		[SerializeField]
		protected Vector3[] controlPoints;

		public System.Action OnRefresh;

		public Vector3[] ControlPoints => controlPoints;

		public void Refresh()
		{
			if (OnRefresh != null)
			{
				OnRefresh();
			}
		}

		public Vector3 GetPoint(float _time)
		{
			float num = 1f - _time;
			return num * num * num * controlPoints[0] + 3f * num * num * _time * controlPoints[1] + 3f * num * _time * _time * controlPoints[2] + _time * _time * _time * controlPoints[3];
		}

		public Vector3 GetTangent(float _time)
		{
			float num = 1f - _time;
			return 3f * num * num * (controlPoints[1] - controlPoints[0]) + 6f * num * _time * (controlPoints[2] - controlPoints[1]) + 3f * _time * _time * (controlPoints[3] - controlPoints[2]);
		}

		public void ReportSet()
		{
			if (controlPoints == null)
			{
				controlPoints = new Vector3[CubicBezierCurvePtNum];
				controlPoints[0] = new Vector3(0f, 0f, 0f);
				controlPoints[1] = new Vector3(0f, 1f, 0f);
				controlPoints[2] = new Vector3(1f, 1f, 0f);
				controlPoints[3] = new Vector3(1f, 0f, 0f);
			}
			_ = 1;
			_ = controlPoints.Length;
			_ = CubicBezierCurvePtNum;
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[RequireComponent(typeof(Graphic))]
	[DisallowMultipleComponent]
	[AddComponentMenu("UI/Effects/Extensions/Curly UI Graphic")]
	public class CUIGraphic : BaseMeshEffect
	{
		public static readonly int bottomCurveIdx = 0;

		public static readonly int topCurveIdx = 1;

		[Tooltip("Set true to make the curve/morph to work. Set false to quickly see the original UI.")]
		[SerializeField]
		protected bool isCurved = true;

		[Tooltip("Set true to dynamically change the curve according to the dynamic change of the UI layout")]
		[SerializeField]
		protected bool isLockWithRatio = true;

		[Tooltip("Pick a higher resolution to improve the quality of the curved graphic.")]
		[SerializeField]
		[Range(0.01f, 30f)]
		protected float resolution = 5f;

		protected RectTransform rectTrans;

		[Tooltip("Put in the Graphic you want to curve/morph here.")]
		[SerializeField]
		protected Graphic uiGraphic;

		[Tooltip("Put in the reference Graphic that will be used to tune the bezier curves. Think button image and text.")]
		[SerializeField]
		protected CUIGraphic refCUIGraphic;

		[Tooltip("Do not touch this unless you are sure what you are doing. The curves are (re)generated automatically.")]
		[SerializeField]
		protected CUIBezierCurve[] refCurves;

		[HideInInspector]
		[SerializeField]
		protected Vector3_Array2D[] refCurvesControlRatioPoints;

		protected List<UIVertex> reuse_quads = new List<UIVertex>();

		public bool IsCurved => isCurved;

		public bool IsLockWithRatio => isLockWithRatio;

		public RectTransform RectTrans => rectTrans;

		public Graphic UIGraphic => uiGraphic;

		public CUIGraphic RefCUIGraphic => refCUIGraphic;

		public CUIBezierCurve[] RefCurves => refCurves;

		public Vector3_Array2D[] RefCurvesControlRatioPoints => refCurvesControlRatioPoints;

		protected void solveDoubleEquationWithVector(float _x_1, float _y_1, float _x_2, float _y_2, Vector3 _constant_1, Vector3 _contant_2, out Vector3 _x, out Vector3 _y)
		{
			if (Mathf.Abs(_x_1) > Mathf.Abs(_x_2))
			{
				Vector3 vector = _constant_1 * _x_2 / _x_1;
				float num = _y_1 * _x_2 / _x_1;
				_y = (_contant_2 - vector) / (_y_2 - num);
				if (_x_2 != 0f)
				{
					_x = (vector - num * _y) / _x_2;
				}
				else
				{
					_x = (_constant_1 - _y_1 * _y) / _x_1;
				}
			}
			else
			{
				Vector3 vector = _contant_2 * _x_1 / _x_2;
				float num = _y_2 * _x_1 / _x_2;
				_x = (_constant_1 - vector) / (_y_1 - num);
				if (_x_1 != 0f)
				{
					_y = (vector - num * _x) / _x_1;
				}
				else
				{
					_y = (_contant_2 - _y_2 * _x) / _x_2;
				}
			}
		}

		protected UIVertex uiVertexLerp(UIVertex _a, UIVertex _b, float _time)
		{
			return new UIVertex
			{
				position = Vector3.Lerp(_a.position, _b.position, _time),
				normal = Vector3.Lerp(_a.normal, _b.normal, _time),
				tangent = Vector3.Lerp((Vector3)_a.tangent, (Vector3)_b.tangent, _time),
				uv0 = Vector2.Lerp((Vector2)_a.uv0, (Vector2)_b.uv0, _time),
				uv1 = Vector2.Lerp((Vector2)_a.uv1, (Vector2)_b.uv1, _time),
				color = Color.Lerp((Color)_a.color, (Color)_b.color, _time)
			};
		}

		protected UIVertex uiVertexBerp(UIVertex v_bottomLeft, UIVertex v_topLeft, UIVertex v_topRight, UIVertex v_bottomRight, float _xTime, float _yTime)
		{
			UIVertex b = uiVertexLerp(v_topLeft, v_topRight, _xTime);
			UIVertex a = uiVertexLerp(v_bottomLeft, v_bottomRight, _xTime);
			return uiVertexLerp(a, b, _yTime);
		}

		protected void tessellateQuad(List<UIVertex> _quads, int _thisQuadIdx)
		{
			UIVertex v_bottomLeft = _quads[_thisQuadIdx];
			UIVertex v_topLeft = _quads[_thisQuadIdx + 1];
			UIVertex v_topRight = _quads[_thisQuadIdx + 2];
			UIVertex v_bottomRight = _quads[_thisQuadIdx + 3];
			float num = 100f / resolution;
			int num2 = Mathf.Max(1, Mathf.CeilToInt((v_topLeft.position - v_bottomLeft.position).magnitude / num));
			int num3 = Mathf.Max(1, Mathf.CeilToInt((v_topRight.position - v_topLeft.position).magnitude / num));
			int num4 = 0;
			for (int i = 0; i < num3; i++)
			{
				int num5 = 0;
				while (num5 < num2)
				{
					_quads.Add(default(UIVertex));
					_quads.Add(default(UIVertex));
					_quads.Add(default(UIVertex));
					_quads.Add(default(UIVertex));
					float xTime = (float)i / (float)num3;
					float yTime = (float)num5 / (float)num2;
					float xTime2 = (float)(i + 1) / (float)num3;
					float yTime2 = (float)(num5 + 1) / (float)num2;
					_quads[_quads.Count - 4] = uiVertexBerp(v_bottomLeft, v_topLeft, v_topRight, v_bottomRight, xTime, yTime);
					_quads[_quads.Count - 3] = uiVertexBerp(v_bottomLeft, v_topLeft, v_topRight, v_bottomRight, xTime, yTime2);
					_quads[_quads.Count - 2] = uiVertexBerp(v_bottomLeft, v_topLeft, v_topRight, v_bottomRight, xTime2, yTime2);
					_quads[_quads.Count - 1] = uiVertexBerp(v_bottomLeft, v_topLeft, v_topRight, v_bottomRight, xTime2, yTime);
					num5++;
					num4++;
				}
			}
		}

		protected void tessellateGraphic(List<UIVertex> _verts)
		{
			for (int i = 0; i < _verts.Count; i += 6)
			{
				reuse_quads.Add(_verts[i]);
				reuse_quads.Add(_verts[i + 1]);
				reuse_quads.Add(_verts[i + 2]);
				reuse_quads.Add(_verts[i + 4]);
			}
			int num = reuse_quads.Count / 4;
			for (int j = 0; j < num; j++)
			{
				tessellateQuad(reuse_quads, j * 4);
			}
			reuse_quads.RemoveRange(0, num * 4);
			_verts.Clear();
			for (int k = 0; k < reuse_quads.Count; k += 4)
			{
				_verts.Add(reuse_quads[k]);
				_verts.Add(reuse_quads[k + 1]);
				_verts.Add(reuse_quads[k + 2]);
				_verts.Add(reuse_quads[k + 2]);
				_verts.Add(reuse_quads[k + 3]);
				_verts.Add(reuse_quads[k]);
			}
			reuse_quads.Clear();
		}

		protected override void OnRectTransformDimensionsChange()
		{
			if (isLockWithRatio)
			{
				UpdateCurveControlPointPositions();
			}
		}

		public void Refresh()
		{
			ReportSet();
			for (int i = 0; i < refCurves.Length; i++)
			{
				CUIBezierCurve cUIBezierCurve = refCurves[i];
				if (cUIBezierCurve.ControlPoints != null)
				{
					Vector3[] controlPoints = cUIBezierCurve.ControlPoints;
					for (int j = 0; j < CUIBezierCurve.CubicBezierCurvePtNum; j++)
					{
						Vector3 value = controlPoints[j];
						value.x = (value.x + rectTrans.rect.width * rectTrans.pivot.x) / rectTrans.rect.width;
						value.y = (value.y + rectTrans.rect.height * rectTrans.pivot.y) / rectTrans.rect.height;
						refCurvesControlRatioPoints[i][j] = value;
					}
				}
			}
			if (uiGraphic != null)
			{
				uiGraphic.enabled = false;
				uiGraphic.enabled = true;
			}
		}

		protected override void Awake()
		{
			base.Awake();
			OnRectTransformDimensionsChange();
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			OnRectTransformDimensionsChange();
		}

		public virtual void ReportSet()
		{
			if (rectTrans == null)
			{
				rectTrans = GetComponent<RectTransform>();
			}
			if (refCurves == null)
			{
				refCurves = new CUIBezierCurve[2];
			}
			bool flag = true;
			for (int i = 0; i < 2; i++)
			{
				flag &= refCurves[i] != null;
			}
			if (!(flag & (refCurves.Length == 2)))
			{
				CUIBezierCurve[] array = refCurves;
				for (int j = 0; j < 2; j++)
				{
					if (refCurves[j] == null)
					{
						GameObject gameObject = new GameObject();
						gameObject.transform.SetParent(base.transform);
						gameObject.transform.localPosition = Vector3.zero;
						gameObject.transform.localEulerAngles = Vector3.zero;
						if (j == 0)
						{
							gameObject.name = "BottomRefCurve";
						}
						else
						{
							gameObject.name = "TopRefCurve";
						}
						array[j] = gameObject.AddComponent<CUIBezierCurve>();
					}
					else
					{
						array[j] = refCurves[j];
					}
					array[j].ReportSet();
				}
				refCurves = array;
			}
			if (refCurvesControlRatioPoints == null)
			{
				refCurvesControlRatioPoints = new Vector3_Array2D[refCurves.Length];
				for (int k = 0; k < refCurves.Length; k++)
				{
					refCurvesControlRatioPoints[k].array = new Vector3[refCurves[k].ControlPoints.Length];
				}
				FixTextToRectTrans();
				Refresh();
			}
			for (int l = 0; l < 2; l++)
			{
				refCurves[l].OnRefresh = Refresh;
			}
		}

		public void FixTextToRectTrans()
		{
			for (int i = 0; i < refCurves.Length; i++)
			{
				CUIBezierCurve cUIBezierCurve = refCurves[i];
				for (int j = 0; j < CUIBezierCurve.CubicBezierCurvePtNum; j++)
				{
					if (cUIBezierCurve.ControlPoints != null)
					{
						Vector3[] controlPoints = cUIBezierCurve.ControlPoints;
						if (i == 0)
						{
							controlPoints[j].y = (0f - rectTrans.rect.height) * rectTrans.pivot.y;
						}
						else
						{
							controlPoints[j].y = rectTrans.rect.height - rectTrans.rect.height * rectTrans.pivot.y;
						}
						controlPoints[j].x = rectTrans.rect.width * (float)j / (float)(CUIBezierCurve.CubicBezierCurvePtNum - 1);
						controlPoints[j].x -= rectTrans.rect.width * rectTrans.pivot.x;
						controlPoints[j].z = 0f;
					}
				}
			}
		}

		public void ReferenceCUIForBCurves()
		{
			Vector3 localPosition = rectTrans.localPosition;
			localPosition.x += (0f - rectTrans.rect.width) * rectTrans.pivot.x + refCUIGraphic.rectTrans.rect.width * refCUIGraphic.rectTrans.pivot.x;
			localPosition.y += (0f - rectTrans.rect.height) * rectTrans.pivot.y + refCUIGraphic.rectTrans.rect.height * refCUIGraphic.rectTrans.pivot.y;
			Vector3 vector = new Vector3(localPosition.x / refCUIGraphic.RectTrans.rect.width, localPosition.y / refCUIGraphic.RectTrans.rect.height, localPosition.z);
			Vector3 vector2 = new Vector3((localPosition.x + rectTrans.rect.width) / refCUIGraphic.RectTrans.rect.width, (localPosition.y + rectTrans.rect.height) / refCUIGraphic.RectTrans.rect.height, localPosition.z);
			refCurves[0].ControlPoints[0] = refCUIGraphic.GetBCurveSandwichSpacePoint(vector.x, vector.y) - rectTrans.localPosition;
			refCurves[0].ControlPoints[3] = refCUIGraphic.GetBCurveSandwichSpacePoint(vector2.x, vector.y) - rectTrans.localPosition;
			refCurves[1].ControlPoints[0] = refCUIGraphic.GetBCurveSandwichSpacePoint(vector.x, vector2.y) - rectTrans.localPosition;
			refCurves[1].ControlPoints[3] = refCUIGraphic.GetBCurveSandwichSpacePoint(vector2.x, vector2.y) - rectTrans.localPosition;
			for (int i = 0; i < refCurves.Length; i++)
			{
				CUIBezierCurve obj = refCurves[i];
				float yTime = ((i == 0) ? vector.y : vector2.y);
				Vector3 bCurveSandwichSpacePoint = refCUIGraphic.GetBCurveSandwichSpacePoint(vector.x, yTime);
				Vector3 bCurveSandwichSpacePoint2 = refCUIGraphic.GetBCurveSandwichSpacePoint(vector2.x, yTime);
				float num = 0.25f;
				float num2 = 0.75f;
				Vector3 bCurveSandwichSpacePoint3 = refCUIGraphic.GetBCurveSandwichSpacePoint((vector.x * 0.75f + vector2.x * 0.25f) / 1f, yTime);
				Vector3 bCurveSandwichSpacePoint4 = refCUIGraphic.GetBCurveSandwichSpacePoint((vector.x * 0.25f + vector2.x * 0.75f) / 1f, yTime);
				float x_ = 3f * num2 * num2 * num;
				float y_ = 3f * num2 * num * num;
				float x_2 = 3f * num * num * num2;
				float y_2 = 3f * num * num2 * num2;
				Vector3 constant_ = bCurveSandwichSpacePoint3 - Mathf.Pow(num2, 3f) * bCurveSandwichSpacePoint - Mathf.Pow(num, 3f) * bCurveSandwichSpacePoint2;
				Vector3 contant_ = bCurveSandwichSpacePoint4 - Mathf.Pow(num, 3f) * bCurveSandwichSpacePoint - Mathf.Pow(num2, 3f) * bCurveSandwichSpacePoint2;
				solveDoubleEquationWithVector(x_, y_, x_2, y_2, constant_, contant_, out var _x, out var _y);
				obj.ControlPoints[1] = _x - rectTrans.localPosition;
				obj.ControlPoints[2] = _y - rectTrans.localPosition;
			}
		}

		public override void ModifyMesh(Mesh _mesh)
		{
			if (!IsActive())
			{
				return;
			}
			using VertexHelper vertexHelper = new VertexHelper(_mesh);
			ModifyMesh(vertexHelper);
			vertexHelper.FillMesh(_mesh);
		}

		public override void ModifyMesh(VertexHelper _vh)
		{
			if (IsActive())
			{
				List<UIVertex> list = new List<UIVertex>();
				_vh.GetUIVertexStream(list);
				modifyVertices(list);
				_vh.Clear();
				_vh.AddUIVertexTriangleStream(list);
			}
		}

		protected virtual void modifyVertices(List<UIVertex> _verts)
		{
			if (!IsActive())
			{
				return;
			}
			tessellateGraphic(_verts);
			if (isCurved)
			{
				for (int i = 0; i < _verts.Count; i++)
				{
					UIVertex value = _verts[i];
					float xTime = (value.position.x + rectTrans.rect.width * rectTrans.pivot.x) / rectTrans.rect.width;
					float yTime = (value.position.y + rectTrans.rect.height * rectTrans.pivot.y) / rectTrans.rect.height;
					Vector3 bCurveSandwichSpacePoint = GetBCurveSandwichSpacePoint(xTime, yTime);
					value.position.x = bCurveSandwichSpacePoint.x;
					value.position.y = bCurveSandwichSpacePoint.y;
					value.position.z = bCurveSandwichSpacePoint.z;
					_verts[i] = value;
				}
			}
		}

		public void UpdateCurveControlPointPositions()
		{
			ReportSet();
			for (int i = 0; i < refCurves.Length; i++)
			{
				CUIBezierCurve cUIBezierCurve = refCurves[i];
				for (int j = 0; j < refCurves[i].ControlPoints.Length; j++)
				{
					Vector3 vector = refCurvesControlRatioPoints[i][j];
					vector.x = vector.x * rectTrans.rect.width - rectTrans.rect.width * rectTrans.pivot.x;
					vector.y = vector.y * rectTrans.rect.height - rectTrans.rect.height * rectTrans.pivot.y;
					cUIBezierCurve.ControlPoints[j] = vector;
				}
			}
		}

		public Vector3 GetBCurveSandwichSpacePoint(float _xTime, float _yTime)
		{
			return refCurves[0].GetPoint(_xTime) * (1f - _yTime) + refCurves[1].GetPoint(_xTime) * _yTime;
		}

		public Vector3 GetBCurveSandwichSpaceTangent(float _xTime, float _yTime)
		{
			return refCurves[0].GetTangent(_xTime) * (1f - _yTime) + refCurves[1].GetTangent(_xTime) * _yTime;
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[RequireComponent(typeof(Image))]
	[AddComponentMenu("UI/Effects/Extensions/Curly UI Image")]
	public class CUIImage : CUIGraphic
	{
		public static int SlicedImageCornerRefVertexIdx = 2;

		public static int FilledImageCornerRefVertexIdx = 0;

		[Tooltip("For changing the size of the corner for tiled or sliced Image")]
		[HideInInspector]
		[SerializeField]
		public Vector2 cornerPosRatio = Vector2.one * -1f;

		[HideInInspector]
		[SerializeField]
		protected Vector2 oriCornerPosRatio = Vector2.one * -1f;

		public Vector2 OriCornerPosRatio => oriCornerPosRatio;

		public Image UIImage => (Image)uiGraphic;

		public static int ImageTypeCornerRefVertexIdx(Image.Type _type)
		{
			if (_type == Image.Type.Sliced)
			{
				return SlicedImageCornerRefVertexIdx;
			}
			return FilledImageCornerRefVertexIdx;
		}

		public override void ReportSet()
		{
			if (uiGraphic == null)
			{
				uiGraphic = GetComponent<Image>();
			}
			base.ReportSet();
		}

		protected override void modifyVertices(List<UIVertex> _verts)
		{
			if (!IsActive())
			{
				return;
			}
			if (UIImage.type == Image.Type.Filled)
			{
				Debug.LogWarning("Might not work well Radial Filled at the moment!");
			}
			else if (UIImage.type == Image.Type.Sliced || UIImage.type == Image.Type.Tiled)
			{
				if (cornerPosRatio == Vector2.one * -1f)
				{
					cornerPosRatio = _verts[ImageTypeCornerRefVertexIdx(UIImage.type)].position;
					cornerPosRatio.x = (cornerPosRatio.x + rectTrans.pivot.x * rectTrans.rect.width) / rectTrans.rect.width;
					cornerPosRatio.y = (cornerPosRatio.y + rectTrans.pivot.y * rectTrans.rect.height) / rectTrans.rect.height;
					oriCornerPosRatio = cornerPosRatio;
				}
				if (cornerPosRatio.x < 0f)
				{
					cornerPosRatio.x = 0f;
				}
				if (cornerPosRatio.x >= 0.5f)
				{
					cornerPosRatio.x = 0.5f;
				}
				if (cornerPosRatio.y < 0f)
				{
					cornerPosRatio.y = 0f;
				}
				if (cornerPosRatio.y >= 0.5f)
				{
					cornerPosRatio.y = 0.5f;
				}
				for (int i = 0; i < _verts.Count; i++)
				{
					UIVertex value = _verts[i];
					float num = (value.position.x + rectTrans.rect.width * rectTrans.pivot.x) / rectTrans.rect.width;
					float num2 = (value.position.y + rectTrans.rect.height * rectTrans.pivot.y) / rectTrans.rect.height;
					num = ((!(num < oriCornerPosRatio.x)) ? ((!(num > 1f - oriCornerPosRatio.x)) ? Mathf.Lerp(cornerPosRatio.x, 1f - cornerPosRatio.x, (num - oriCornerPosRatio.x) / (1f - oriCornerPosRatio.x * 2f)) : Mathf.Lerp(1f - cornerPosRatio.x, 1f, (num - (1f - oriCornerPosRatio.x)) / oriCornerPosRatio.x)) : Mathf.Lerp(0f, cornerPosRatio.x, num / oriCornerPosRatio.x));
					num2 = ((!(num2 < oriCornerPosRatio.y)) ? ((!(num2 > 1f - oriCornerPosRatio.y)) ? Mathf.Lerp(cornerPosRatio.y, 1f - cornerPosRatio.y, (num2 - oriCornerPosRatio.y) / (1f - oriCornerPosRatio.y * 2f)) : Mathf.Lerp(1f - cornerPosRatio.y, 1f, (num2 - (1f - oriCornerPosRatio.y)) / oriCornerPosRatio.y)) : Mathf.Lerp(0f, cornerPosRatio.y, num2 / oriCornerPosRatio.y));
					value.position.x = num * rectTrans.rect.width - rectTrans.rect.width * rectTrans.pivot.x;
					value.position.y = num2 * rectTrans.rect.height - rectTrans.rect.height * rectTrans.pivot.y;
					_verts[i] = value;
				}
			}
			base.modifyVertices(_verts);
		}
	}
