	[AddComponentMenu("UI/Effects/Extensions/Gradient")]
	public class Gradient : BaseMeshEffect
	{
		[SerializeField]
		private GradientMode _gradientMode;

		[SerializeField]
		private GradientDir _gradientDir;

		[SerializeField]
		private bool _overwriteAllColor;

		[SerializeField]
		private Color _vertex1 = Color.white;

		[SerializeField]
		private Color _vertex2 = Color.black;

		private Graphic targetGraphic;

		public GradientMode GradientMode
		{
			get
			{
				return _gradientMode;
			}
			set
			{
				_gradientMode = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public GradientDir GradientDir
		{
			get
			{
				return _gradientDir;
			}
			set
			{
				_gradientDir = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public bool OverwriteAllColor
		{
			get
			{
				return _overwriteAllColor;
			}
			set
			{
				_overwriteAllColor = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public Color Vertex1
		{
			get
			{
				return _vertex1;
			}
			set
			{
				_vertex1 = value;
				base.graphic.SetAllDirty();
			}
		}

		public Color Vertex2
		{
			get
			{
				return _vertex2;
			}
			set
			{
				_vertex2 = value;
				base.graphic.SetAllDirty();
			}
		}

		protected override void Awake()
		{
			targetGraphic = GetComponent<Graphic>();
		}

		public override void ModifyMesh(VertexHelper vh)
		{
			int currentVertCount = vh.currentVertCount;
			if (!IsActive() || currentVertCount == 0)
			{
				return;
			}
			List<UIVertex> list = new List<UIVertex>();
			vh.GetUIVertexStream(list);
			UIVertex vertex = default(UIVertex);
			if (_gradientMode == GradientMode.Global)
			{
				if (_gradientDir == GradientDir.DiagonalLeftToRight || _gradientDir == GradientDir.DiagonalRightToLeft)
				{
					_gradientDir = GradientDir.Vertical;
				}
				float num = ((_gradientDir == GradientDir.Vertical) ? list[list.Count - 1].position.y : list[list.Count - 1].position.x);
				float num2 = ((_gradientDir == GradientDir.Vertical) ? list[0].position.y : list[0].position.x) - num;
				for (int i = 0; i < currentVertCount; i++)
				{
					vh.PopulateUIVertex(ref vertex, i);
					if (_overwriteAllColor || !(vertex.color != targetGraphic.color))
					{
						ref Color32 color = ref vertex.color;
						color *= Color.Lerp(_vertex2, _vertex1, (((_gradientDir == GradientDir.Vertical) ? vertex.position.y : vertex.position.x) - num) / num2);
						vh.SetUIVertex(vertex, i);
					}
				}
				return;
			}
			for (int j = 0; j < currentVertCount; j++)
			{
				vh.PopulateUIVertex(ref vertex, j);
				if (_overwriteAllColor || CompareCarefully(vertex.color, targetGraphic.color))
				{
					switch (_gradientDir)
					{
					case GradientDir.Vertical:
					{
						ref Color32 color4 = ref vertex.color;
						color4 *= ((j % 4 == 0 || (j - 1) % 4 == 0) ? _vertex1 : _vertex2);
						break;
					}
					case GradientDir.Horizontal:
					{
						ref Color32 color5 = ref vertex.color;
						color5 *= ((j % 4 == 0 || (j - 3) % 4 == 0) ? _vertex1 : _vertex2);
						break;
					}
					case GradientDir.DiagonalLeftToRight:
					{
						ref Color32 color3 = ref vertex.color;
						color3 *= ((j % 4 == 0) ? _vertex1 : (((j - 2) % 4 == 0) ? _vertex2 : Color.Lerp(_vertex2, _vertex1, 0.5f)));
						break;
					}
					case GradientDir.DiagonalRightToLeft:
					{
						ref Color32 color2 = ref vertex.color;
						color2 *= (((j - 1) % 4 == 0) ? _vertex1 : (((j - 3) % 4 == 0) ? _vertex2 : Color.Lerp(_vertex2, _vertex1, 0.5f)));
						break;
					}
					}
					vh.SetUIVertex(vertex, j);
				}
			}
		}

		private bool CompareCarefully(Color col1, Color col2)
		{
			if (Mathf.Abs(col1.r - col2.r) < 0.003f && Mathf.Abs(col1.g - col2.g) < 0.003f && Mathf.Abs(col1.b - col2.b) < 0.003f && Mathf.Abs(col1.a - col2.a) < 0.003f)
			{
				return true;
			}
			return false;
		}
	}
	public enum GradientMode
	{
		Global,
		Local
	}
	public enum GradientDir
	{
		Vertical,
		Horizontal,
		DiagonalLeftToRight,
		DiagonalRightToLeft
	}
	[AddComponentMenu("UI/Effects/Extensions/Gradient2")]
	public class Gradient2 : BaseMeshEffect
	{
		public enum Type
		{
			Horizontal,
			Vertical,
			Radial,
			Diamond
		}

		public enum Blend
		{
			Override,
			Add,
			Multiply
		}

		[SerializeField]
		private Type _gradientType;

		[SerializeField]
		private Blend _blendMode = Blend.Multiply;

		[SerializeField]
		[Range(-1f, 1f)]
		private float _offset;

		[SerializeField]
		private UnityEngine.Gradient _effectGradient = new UnityEngine.Gradient
		{
			colorKeys = new GradientColorKey[2]
			{
				new GradientColorKey(Color.black, 0f),
				new GradientColorKey(Color.white, 1f)
			}
		};

		public Blend BlendMode
		{
			get
			{
				return _blendMode;
			}
			set
			{
				_blendMode = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public UnityEngine.Gradient EffectGradient
		{
			get
			{
				return _effectGradient;
			}
			set
			{
				_effectGradient = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public Type GradientType
		{
			get
			{
				return _gradientType;
			}
			set
			{
				_gradientType = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public float Offset
		{
			get
			{
				return _offset;
			}
			set
			{
				_offset = value;
				base.graphic.SetVerticesDirty();
			}
		}

		public override void ModifyMesh(VertexHelper helper)
		{
			if (!IsActive() || helper.currentVertCount == 0)
			{
				return;
			}
			List<UIVertex> list = new List<UIVertex>();
			helper.GetUIVertexStream(list);
			int count = list.Count;
			switch (GradientType)
			{
			case Type.Horizontal:
			{
				float num30 = list[0].position.x;
				float num31 = list[0].position.x;
				float num32 = 0f;
				for (int num33 = count - 1; num33 >= 1; num33--)
				{
					num32 = list[num33].position.x;
					if (num32 > num31)
					{
						num31 = num32;
					}
					else if (num32 < num30)
					{
						num30 = num32;
					}
				}
				float num34 = 1f / (num31 - num30);
				UIVertex vertex4 = default(UIVertex);
				for (int num35 = 0; num35 < helper.currentVertCount; num35++)
				{
					helper.PopulateUIVertex(ref vertex4, num35);
					vertex4.color = BlendColor(vertex4.color, EffectGradient.Evaluate((vertex4.position.x - num30) * num34 - Offset));
					helper.SetUIVertex(vertex4, num35);
				}
				break;
			}
			case Type.Vertical:
			{
				float num18 = list[0].position.y;
				float num19 = list[0].position.y;
				float num20 = 0f;
				for (int num21 = count - 1; num21 >= 1; num21--)
				{
					num20 = list[num21].position.y;
					if (num20 > num19)
					{
						num19 = num20;
					}
					else if (num20 < num18)
					{
						num18 = num20;
					}
				}
				float num22 = 1f / (num19 - num18);
				UIVertex vertex2 = default(UIVertex);
				for (int l = 0; l < helper.currentVertCount; l++)
				{
					helper.PopulateUIVertex(ref vertex2, l);
					vertex2.color = BlendColor(vertex2.color, EffectGradient.Evaluate((vertex2.position.y - num18) * num22 - Offset));
					helper.SetUIVertex(vertex2, l);
				}
				break;
			}
			case Type.Diamond:
			{
				float num23 = list[0].position.y;
				float num24 = list[0].position.y;
				float num25 = 0f;
				for (int num26 = count - 1; num26 >= 1; num26--)
				{
					num25 = list[num26].position.y;
					if (num25 > num24)
					{
						num24 = num25;
					}
					else if (num25 < num23)
					{
						num23 = num25;
					}
				}
				float num27 = 1f / (num24 - num23);
				helper.Clear();
				for (int m = 0; m < count; m++)
				{
					helper.AddVert(list[m]);
				}
				float num28 = (num23 + num24) / 2f;
				UIVertex v3 = new UIVertex
				{
					position = (Vector3.right + Vector3.up) * num28 + Vector3.forward * list[0].position.z,
					normal = list[0].normal,
					color = Color.white
				};
				helper.AddVert(v3);
				for (int n = 1; n < count; n++)
				{
					helper.AddTriangle(n - 1, n, count);
				}
				helper.AddTriangle(0, count - 1, count);
				UIVertex vertex3 = default(UIVertex);
				for (int num29 = 0; num29 < helper.currentVertCount; num29++)
				{
					helper.PopulateUIVertex(ref vertex3, num29);
					vertex3.color = BlendColor(vertex3.color, EffectGradient.Evaluate(Vector3.Distance(vertex3.position, v3.position) * num27 - Offset));
					helper.SetUIVertex(vertex3, num29);
				}
				break;
			}
			case Type.Radial:
			{
				float num = list[0].position.x;
				float num2 = list[0].position.x;
				float num3 = list[0].position.y;
				float num4 = list[0].position.y;
				float num5 = 0f;
				float num6 = 0f;
				for (int num7 = count - 1; num7 >= 1; num7--)
				{
					num5 = list[num7].position.x;
					if (num5 > num2)
					{
						num2 = num5;
					}
					else if (num5 < num)
					{
						num = num5;
					}
					num6 = list[num7].position.y;
					if (num6 > num4)
					{
						num4 = num6;
					}
					else if (num6 < num3)
					{
						num3 = num6;
					}
				}
				float num8 = 1f / (num2 - num);
				float num9 = 1f / (num4 - num3);
				helper.Clear();
				float num10 = (num2 + num) / 2f;
				float num11 = (num3 + num4) / 2f;
				float num12 = (num2 - num) / 2f;
				float num13 = (num4 - num3) / 2f;
				UIVertex v = new UIVertex
				{
					position = Vector3.right * num10 + Vector3.up * num11 + Vector3.forward * list[0].position.z,
					normal = list[0].normal,
					color = Color.white
				};
				int num14 = 64;
				for (int i = 0; i < num14; i++)
				{
					UIVertex v2 = default(UIVertex);
					float num15 = (float)i * 360f / (float)num14;
					float num16 = Mathf.Cos(MathF.PI / 180f * num15) * num12;
					float num17 = Mathf.Sin(MathF.PI / 180f * num15) * num13;
					v2.position = Vector3.right * num16 + Vector3.up * num17 + Vector3.forward * list[0].position.z;
					v2.normal = list[0].normal;
					v2.color = Color.white;
					helper.AddVert(v2);
				}
				helper.AddVert(v);
				for (int j = 1; j < num14; j++)
				{
					helper.AddTriangle(j - 1, j, num14);
				}
				helper.AddTriangle(0, num14 - 1, num14);
				UIVertex vertex = default(UIVertex);
				for (int k = 0; k < helper.currentVertCount; k++)
				{
					helper.PopulateUIVertex(ref vertex, k);
					vertex.color = BlendColor(vertex.color, EffectGradient.Evaluate(Mathf.Sqrt(Mathf.Pow(Mathf.Abs(vertex.position.x - num10) * num8, 2f) + Mathf.Pow(Mathf.Abs(vertex.position.y - num11) * num9, 2f)) * 2f - Offset));
					helper.SetUIVertex(vertex, k);
				}
				break;
			}
			}
		}

		private Color BlendColor(Color colorA, Color colorB)
		{
			return BlendMode switch
			{
				Blend.Add => colorA + colorB, 
				Blend.Multiply => colorA * colorB, 
				_ => colorB, 
			};
		}
	}
	[AddComponentMenu("UI/Effects/Extensions/Letter Spacing")]
	public class LetterSpacing : BaseMeshEffect
	{
		[SerializeField]
		private float m_spacing;

		public float spacing
		{
			get
			{
				return m_spacing;
			}
			set
			{
				if (m_spacing != value)
				{
					m_spacing = value;
					if (base.graphic != null)
					{
						base.graphic.SetVerticesDirty();
					}
				}
			}
		}

		protected LetterSpacing()
		{
		}

		public override void ModifyMesh(VertexHelper vh)
		{
			if (!IsActive())
			{
				return;
			}
			List<UIVertex> list = new List<UIVertex>();
			vh.GetUIVertexStream(list);
			Text component = GetComponent<Text>();
			if (component == null)
			{
				Debug.LogWarning("LetterSpacing: Missing Text component");
				return;
			}
			string[] array = component.text.Split('\n');
			float num = spacing * (float)component.fontSize / 100f;
			float num2 = 0f;
			int num3 = 0;
			switch (component.alignment)
			{
			case TextAnchor.UpperLeft:
			case TextAnchor.MiddleLeft:
			case TextAnchor.LowerLeft:
				num2 = 0f;
				break;
			case TextAnchor.UpperCenter:
			case TextAnchor.MiddleCenter:
			case TextAnchor.LowerCenter:
				num2 = 0.5f;
				break;
			case TextAnchor.UpperRight:
			case TextAnchor.MiddleRight:
			case TextAnchor.LowerRight:
				num2 = 1f;
				break;
			}
			foreach (string text in array)
			{
				float num4 = (float)(text.Length - 1) * num * num2;
				for (int j = 0; j < text.Length; j++)
				{
					int index = num3 * 6;
					int index2 = num3 * 6 + 1;
					int index3 = num3 * 6 + 2;
					int index4 = num3 * 6 + 3;
					int index5 = num3 * 6 + 4;
					int num5 = num3 * 6 + 5;
					if (num5 > list.Count - 1)
					{
						return;
					}
					UIVertex value = list[index];
					UIVertex value2 = list[index2];
					UIVertex value3 = list[index3];
					UIVertex value4 = list[index4];
					UIVertex value5 = list[index5];
					UIVertex value6 = list[num5];
					Vector3 vector = Vector3.right * (num * (float)j - num4);
					value.position += vector;
					value2.position += vector;
					value3.position += vector;
					value4.position += vector;
					value5.position += vector;
					value6.position += vector;
					list[index] = value;
					list[index2] = value2;
					list[index3] = value3;
					list[index4] = value4;
					list[index5] = value5;
					list[num5] = value6;
					num3++;
				}
				num3++;
			}
			vh.Clear();
			vh.AddUIVertexTriangleStream(list);
		}
	}
