			}
			set
			{
				ChangeVal(value);
				yOffset = value;
			}
		}

		private void OnEnable()
		{
			if (effector == null)
			{
				GameObject gameObject = new GameObject("effector");
				effectRoot = new GameObject("ShineEffect");
				effectRoot.transform.SetParent(base.transform);
				effectRoot.AddComponent<Image>().sprite = base.gameObject.GetComponent<Image>().sprite;
				effectRoot.GetComponent<Image>().type = base.gameObject.GetComponent<Image>().type;
				effectRoot.AddComponent<Mask>().showMaskGraphic = false;
				effectRoot.transform.localScale = Vector3.one;
				effectRoot.GetComponent<RectTransform>().anchoredPosition3D = Vector3.zero;
				effectRoot.GetComponent<RectTransform>().anchorMax = Vector2.one;
				effectRoot.GetComponent<RectTransform>().anchorMin = Vector2.zero;
				effectRoot.GetComponent<RectTransform>().offsetMax = Vector2.zero;
				effectRoot.GetComponent<RectTransform>().offsetMin = Vector2.zero;
				effectRoot.transform.SetAsFirstSibling();
				gameObject.AddComponent<RectTransform>();
				gameObject.transform.SetParent(effectRoot.transform);
				effectorRect = gameObject.GetComponent<RectTransform>();
				effectorRect.localScale = Vector3.one;
				effectorRect.anchoredPosition3D = Vector3.zero;
				effectorRect.gameObject.AddComponent<ShineEffect>();
				effectorRect.anchorMax = Vector2.one;
				effectorRect.anchorMin = Vector2.zero;
				effectorRect.Rotate(0f, 0f, -8f);
				effector = gameObject.GetComponent<ShineEffect>();
				effectorRect.offsetMax = Vector2.zero;
				effectorRect.offsetMin = Vector2.zero;
				OnValidate();
			}
		}

		private void OnValidate()
		{
			effector.Yoffset = yOffset;
			effector.Width = width;
			if (yOffset <= -1f || yOffset >= 1f)
			{
				effectRoot.SetActive(value: false);
			}
			else if (!effectRoot.activeSelf)
			{
				effectRoot.SetActive(value: true);
			}
		}

		private void ChangeVal(float value)
		{
			effector.Yoffset = value;
			if (value <= -1f || value >= 1f)
			{
				effectRoot.SetActive(value: false);
			}
			else if (!effectRoot.activeSelf)
			{
				effectRoot.SetActive(value: true);
			}
		}

		private void OnDestroy()
		{
			if (!Application.isPlaying)
			{
				Object.DestroyImmediate(effectRoot);
			}
			else
			{
				Object.Destroy(effectRoot);
			}
		}
	}
	[ExecuteInEditMode]
	[AddComponentMenu("UI/Effects/Extensions/SoftMaskScript")]
	public class SoftMaskScript : MonoBehaviour
	{
		private const string SHADER = "UI Extensions/SoftMaskShader";

		private Material mat;

		private Canvas cachedCanvas;

		private Transform cachedCanvasTransform;

		private readonly Vector3[] m_WorldCorners = new Vector3[4];

		private readonly Vector3[] m_CanvasCorners = new Vector3[4];

		[Tooltip("The area that is to be used as the container.")]
		public RectTransform MaskArea;

		[Tooltip("Texture to be used to do the soft alpha")]
		public Texture AlphaMask;

		[Tooltip("At what point to apply the alpha min range 0-1")]
		[Range(0f, 1f)]
		public float CutOff;

		[Tooltip("Implement a hard blend based on the Cutoff")]
		public bool HardBlend;

		[Tooltip("Flip the masks alpha value")]
		public bool FlipAlphaMask;

		[Tooltip("If a different Mask Scaling Rect is given, and this value is true, the area around the mask will not be clipped")]
		public bool DontClipMaskScalingRect;

		private Vector2 maskOffset = Vector2.zero;

		private Vector2 maskScale = Vector2.one;

		private void Start()
		{
			if (MaskArea == null)
			{
				MaskArea = GetComponent<RectTransform>();
			}
			Text component = GetComponent<Text>();
			if (component != null && TryFindShader(out var shader, "UI Extensions/SoftMaskShader"))
			{
				mat = new Material(shader);
				component.material = mat;
				cachedCanvas = component.canvas;
				cachedCanvasTransform = cachedCanvas.transform;
				if (base.transform.parent.GetComponent<Mask>() == null)
				{
					base.transform.parent.gameObject.AddComponent<Mask>();
				}
				base.transform.parent.GetComponent<Mask>().enabled = false;
			}
			else
			{
				Graphic component2 = GetComponent<Graphic>();
				if (component2 != null && TryFindShader(out shader, "UI Extensions/SoftMaskShader"))
				{
					mat = new Material(shader);
					component2.material = mat;
					cachedCanvas = component2.canvas;
					cachedCanvasTransform = cachedCanvas.transform;
				}
			}
		}

		private void Update()
		{
			if (cachedCanvas != null)
			{
				SetMask();
			}
		}

		private void SetMask()
		{
			Rect canvasRect = GetCanvasRect();
			Vector2 size = canvasRect.size;
			maskScale.Set(1f / size.x, 1f / size.y);
			maskOffset = -canvasRect.min;
			maskOffset.Scale(maskScale);
			mat.SetTextureOffset("_AlphaMask", maskOffset);
			mat.SetTextureScale("_AlphaMask", maskScale);
			mat.SetTexture("_AlphaMask", AlphaMask);
			mat.SetFloat("_HardBlend", HardBlend ? 1 : 0);
			mat.SetInt("_FlipAlphaMask", FlipAlphaMask ? 1 : 0);
			mat.SetInt("_NoOuterClip", DontClipMaskScalingRect ? 1 : 0);
			mat.SetFloat("_CutOff", CutOff);
		}

		public Rect GetCanvasRect()
		{
			if (cachedCanvas == null)
			{
				return default(Rect);
			}
			MaskArea.GetWorldCorners(m_WorldCorners);
			for (int i = 0; i < 4; i++)
			{
				m_CanvasCorners[i] = cachedCanvasTransform.InverseTransformPoint(m_WorldCorners[i]);
			}
			return new Rect(m_CanvasCorners[0].x, m_CanvasCorners[0].y, m_CanvasCorners[2].x - m_CanvasCorners[0].x, m_CanvasCorners[2].y - m_CanvasCorners[0].y);
		}

		private bool TryFindShader(out Shader shader, string name)
		{
			shader = Shader.Find(name);
			if (shader == null)
			{
				Debug.LogException(new Exception("SoftMask attached to '" + base.transform.HierarchyPathToString() + "' was unable to find shader '" + name + "'"));
				return false;
			}
			Debug.Log("SoftMask attached to '" + base.transform.HierarchyPathToString() + "' was able to find shader '" + name + "'");
			return true;
		}
	}
	[RequireComponent(typeof(RectTransform), typeof(Graphic))]
	[DisallowMultipleComponent]
	[AddComponentMenu("UI/Effects/Extensions/Flippable")]
	public class UIFlippable : BaseMeshEffect
	{
		[SerializeField]
		private bool m_Horizontal;

		[SerializeField]
		private bool m_Veritical;

		public bool horizontal
		{
			get
			{
				return m_Horizontal;
			}
			set
			{
				m_Horizontal = value;
			}
		}

		public bool vertical
		{
			get
			{
				return m_Veritical;
			}
			set
			{
				m_Veritical = value;
			}
		}

		public override void ModifyMesh(VertexHelper verts)
		{
			RectTransform rectTransform = base.transform as RectTransform;
			for (int i = 0; i < verts.currentVertCount; i++)
			{
				UIVertex vertex = default(UIVertex);
				verts.PopulateUIVertex(ref vertex, i);
				vertex.position = new Vector3(m_Horizontal ? (vertex.position.x + (rectTransform.rect.center.x - vertex.position.x) * 2f) : vertex.position.x, m_Veritical ? (vertex.position.y + (rectTransform.rect.center.y - vertex.position.y) * 2f) : vertex.position.y, vertex.position.z);
				verts.SetUIVertex(vertex, i);
			}
		}
	}
	[ExecuteInEditMode]
	[RequireComponent(typeof(CanvasRenderer), typeof(ParticleSystem))]
	[AddComponentMenu("UI/Effects/Extensions/UIParticleSystem")]
	public class UIParticleSystem : MaskableGraphic
	{
		[Tooltip("Having this enabled run the system in LateUpdate rather than in Update making it faster but less precise (more clunky)")]
		public bool fixedTime = true;

		private Transform _transform;

		private ParticleSystem pSystem;

		private ParticleSystem.Particle[] particles;

		private UIVertex[] _quad = new UIVertex[4];

		private Vector4 imageUV = Vector4.zero;

		private ParticleSystem.TextureSheetAnimationModule textureSheetAnimation;

		private int textureSheetAnimationFrames;

		private Vector2 textureSheetAnimationFrameSize;

		private ParticleSystemRenderer pRenderer;

		private Material currentMaterial;

		private Texture currentTexture;

		private ParticleSystem.MainModule mainModule;

		public override Texture mainTexture => currentTexture;

		protected bool Initialize()
		{
			if (_transform == null)
			{
				_transform = base.transform;
			}
			if (pSystem == null)
			{
				pSystem = GetComponent<ParticleSystem>();
				if (pSystem == null)
				{
					return false;
				}
				mainModule = pSystem.main;
				if (pSystem.main.maxParticles > 14000)
				{
					mainModule.maxParticles = 14000;
				}
				pRenderer = pSystem.GetComponent<ParticleSystemRenderer>();
				if (pRenderer != null)
				{
					pRenderer.enabled = false;
				}
				Material material = new Material(Shader.Find("UI Extensions/Particles/Additive"));
				if (this.material == null)
				{
					this.material = material;
				}
				currentMaterial = this.material;
				if ((bool)currentMaterial && currentMaterial.HasProperty("_MainTex"))
				{
					currentTexture = currentMaterial.mainTexture;
					if (currentTexture == null)
					{
						currentTexture = Texture2D.whiteTexture;
					}
				}
				this.material = currentMaterial;
				mainModule.scalingMode = ParticleSystemScalingMode.Hierarchy;
				particles = null;
			}
			if (particles == null)
			{
				particles = new ParticleSystem.Particle[pSystem.main.maxParticles];
			}
			imageUV = new Vector4(0f, 0f, 1f, 1f);
			textureSheetAnimation = pSystem.textureSheetAnimation;
			textureSheetAnimationFrames = 0;
			textureSheetAnimationFrameSize = Vector2.zero;
			if (textureSheetAnimation.enabled)
			{
				textureSheetAnimationFrames = textureSheetAnimation.numTilesX * textureSheetAnimation.numTilesY;
				textureSheetAnimationFrameSize = new Vector2(1f / (float)textureSheetAnimation.numTilesX, 1f / (float)textureSheetAnimation.numTilesY);
			}
			return true;
		}

		protected override void Awake()
		{
			base.Awake();
			if (!Initialize())
			{
				base.enabled = false;
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			vh.Clear();
			if (!base.gameObject.activeInHierarchy)
			{
				return;
			}
			Vector2 zero = Vector2.zero;
			Vector2 zero2 = Vector2.zero;
			Vector2 zero3 = Vector2.zero;
			int num = pSystem.GetParticles(particles);
			for (int i = 0; i < num; i++)
			{
				ParticleSystem.Particle particle = particles[i];
				Vector2 vector = ((mainModule.simulationSpace == ParticleSystemSimulationSpace.Local) ? particle.position : _transform.InverseTransformPoint(particle.position));
				float num2 = (0f - particle.rotation) * (MathF.PI / 180f);
				float f = num2 + MathF.PI / 2f;
				Color32 currentColor = particle.GetCurrentColor(pSystem);
				float num3 = particle.GetCurrentSize(pSystem) * 0.5f;
				if (mainModule.scalingMode == ParticleSystemScalingMode.Shape)
				{
					vector /= base.canvas.scaleFactor;
				}
				Vector4 vector2 = imageUV;
				if (textureSheetAnimation.enabled)
				{
					float num4 = 1f - particle.remainingLifetime / particle.startLifetime;
					if (textureSheetAnimation.frameOverTime.curveMin != null)
					{
						num4 = textureSheetAnimation.frameOverTime.curveMin.Evaluate(1f - particle.remainingLifetime / particle.startLifetime);
					}
					else if (textureSheetAnimation.frameOverTime.curve != null)
					{
						num4 = textureSheetAnimation.frameOverTime.curve.Evaluate(1f - particle.remainingLifetime / particle.startLifetime);
					}
					else if (textureSheetAnimation.frameOverTime.constant > 0f)
					{
						num4 = textureSheetAnimation.frameOverTime.constant - particle.remainingLifetime / particle.startLifetime;
					}
					num4 = Mathf.Repeat(num4 * (float)textureSheetAnimation.cycleCount, 1f);
					int num5 = 0;
					switch (textureSheetAnimation.animation)
					{
					case ParticleSystemAnimationType.WholeSheet:
						num5 = Mathf.FloorToInt(num4 * (float)textureSheetAnimationFrames);
						break;
					case ParticleSystemAnimationType.SingleRow:
					{
						num5 = Mathf.FloorToInt(num4 * (float)textureSheetAnimation.numTilesX);
						int rowIndex = textureSheetAnimation.rowIndex;
						num5 += rowIndex * textureSheetAnimation.numTilesX;
						break;
					}
					}
					num5 %= textureSheetAnimationFrames;
					vector2.x = (float)(num5 % textureSheetAnimation.numTilesX) * textureSheetAnimationFrameSize.x;
					vector2.y = (float)Mathf.FloorToInt(num5 / textureSheetAnimation.numTilesX) * textureSheetAnimationFrameSize.y;
					vector2.z = vector2.x + textureSheetAnimationFrameSize.x;
					vector2.w = vector2.y + textureSheetAnimationFrameSize.y;
				}
				zero.x = vector2.x;
				zero.y = vector2.y;
				_quad[0] = UIVertex.simpleVert;
				_quad[0].color = currentColor;
				_quad[0].uv0 = zero;
				zero.x = vector2.x;
				zero.y = vector2.w;
				_quad[1] = UIVertex.simpleVert;
				_quad[1].color = currentColor;
				_quad[1].uv0 = zero;
				zero.x = vector2.z;
				zero.y = vector2.w;
				_quad[2] = UIVertex.simpleVert;
				_quad[2].color = currentColor;
				_quad[2].uv0 = zero;
				zero.x = vector2.z;
				zero.y = vector2.y;
				_quad[3] = UIVertex.simpleVert;
				_quad[3].color = currentColor;
				_quad[3].uv0 = zero;
				if (num2 == 0f)
				{
					zero2.x = vector.x - num3;
					zero2.y = vector.y - num3;
					zero3.x = vector.x + num3;
					zero3.y = vector.y + num3;
					zero.x = zero2.x;
					zero.y = zero2.y;
					_quad[0].position = zero;
					zero.x = zero2.x;
					zero.y = zero3.y;
					_quad[1].position = zero;
					zero.x = zero3.x;
					zero.y = zero3.y;
					_quad[2].position = zero;
					zero.x = zero3.x;
					zero.y = zero2.y;
					_quad[3].position = zero;
				}
				else
				{
					Vector2 vector3 = new Vector2(Mathf.Cos(num2), Mathf.Sin(num2)) * num3;
					Vector2 vector4 = new Vector2(Mathf.Cos(f), Mathf.Sin(f)) * num3;
					_quad[0].position = vector - vector3 - vector4;
					_quad[1].position = vector - vector3 + vector4;
					_quad[2].position = vector + vector3 + vector4;
					_quad[3].position = vector + vector3 - vector4;
				}
				vh.AddUIVertexQuad(_quad);
			}
		}

		private void Update()
		{
			if (!fixedTime && Application.isPlaying)
			{
				pSystem.Simulate(Time.unscaledDeltaTime, withChildren: false, restart: false, fixedTimeStep: true);
				SetAllDirty();
				if ((currentMaterial != null && currentTexture != currentMaterial.mainTexture) || (material != null && currentMaterial != null && material.shader != currentMaterial.shader))
				{
					pSystem = null;
					Initialize();
				}
			}
		}

		private void LateUpdate()
		{
			if (!Application.isPlaying)
			{
				SetAllDirty();
			}
			else if (fixedTime)
			{
				pSystem.Simulate(Time.unscaledDeltaTime, withChildren: false, restart: false, fixedTimeStep: true);
				SetAllDirty();
				if ((currentMaterial != null && currentTexture != currentMaterial.mainTexture) || (material != null && currentMaterial != null && material.shader != currentMaterial.shader))
				{
					pSystem = null;
					Initialize();
				}
			}
			if (!(material == currentMaterial))
			{
				pSystem = null;
				Initialize();
			}
		}
	}
	[AddComponentMenu("Layout/Extensions/Curved Layout")]
	public class CurvedLayout : LayoutGroup
	{
		public Vector3 CurveOffset;

		[Tooltip("axis along which to place the items, Normalized before use")]
		public Vector3 itemAxis;

		[Tooltip("size of each item along the Normalized axis")]
		public float itemSize;

		public float centerpoint = 0.5f;

		protected override void OnEnable()
		{
			base.OnEnable();
			CalculateRadial();
		}

		public override void SetLayoutHorizontal()
		{
		}

		public override void SetLayoutVertical()
		{
		}

		public override void CalculateLayoutInputVertical()
		{
			CalculateRadial();
		}

		public override void CalculateLayoutInputHorizontal()
		{
			CalculateRadial();
		}

		private void CalculateRadial()
		{
			m_Tracker.Clear();
			if (base.transform.childCount == 0)
			{
				return;
			}
			Vector2 pivot = new Vector2((float)((int)base.childAlignment % 3) * 0.5f, (float)((int)base.childAlignment / 3) * 0.5f);
			Vector3 vector = new Vector3(GetStartOffset(0, GetTotalPreferredSize(0)), GetStartOffset(1, GetTotalPreferredSize(1)), 0f);
			float num = 0f;
			float num2 = 1f / (float)base.transform.childCount;
			Vector3 vector2 = itemAxis.normalized * itemSize;
			for (int i = 0; i < base.transform.childCount; i++)
			{
				RectTransform rectTransform = (RectTransform)base.transform.GetChild(i);
				if (rectTransform != null)
				{
					m_Tracker.Add(this, rectTransform, DrivenTransformProperties.Anchors | DrivenTransformProperties.AnchoredPosition | DrivenTransformProperties.Pivot);
					Vector3 vector3 = vector + vector2;
					vector = (rectTransform.localPosition = vector3 + (num - centerpoint) * CurveOffset);
					rectTransform.pivot = pivot;
					Vector2 anchorMin = (rectTransform.anchorMax = new Vector2(0.5f, 0.5f));
					rectTransform.anchorMin = anchorMin;
					num += num2;
				}
			}
		}
	}
	public class FancyScrollView<TData, TContext> : MonoBehaviour where TContext : class
	{
		[SerializeField]
		[Range(float.Epsilon, 1f)]
		private float cellInterval;

		[SerializeField]
		[Range(0f, 1f)]
		private float cellOffset;

		[SerializeField]
		private bool loop;

		[SerializeField]
		private GameObject cellBase;

		private float currentPosition;

		private readonly List<FancyScrollViewCell<TData, TContext>> cells = new List<FancyScrollViewCell<TData, TContext>>();

		protected TContext context;

		protected List<TData> cellData = new List<TData>();

		protected void Awake()
		{
			cellBase.SetActive(value: false);
		}

		protected void SetContext(TContext context)
		{
			this.context = context;
			for (int i = 0; i < cells.Count; i++)
			{
				cells[i].SetContext(context);
			}
		}

		private FancyScrollViewCell<TData, TContext> CreateCell()
		{
			GameObject obj = Object.Instantiate(cellBase);
			obj.SetActive(value: true);
			FancyScrollViewCell<TData, TContext> component = obj.GetComponent<FancyScrollViewCell<TData, TContext>>();
			RectTransform rectTransform = component.transform as RectTransform;
			Vector3 localScale = component.transform.localScale;
			Vector2 sizeDelta = Vector2.zero;
			Vector2 offsetMin = Vector2.zero;
			Vector2 offsetMax = Vector2.zero;
			if ((bool)rectTransform)
			{
				sizeDelta = rectTransform.sizeDelta;
				offsetMin = rectTransform.offsetMin;
				offsetMax = rectTransform.offsetMax;
			}
			component.transform.SetParent(cellBase.transform.parent);
			component.transform.localScale = localScale;
			if ((bool)rectTransform)
			{
				rectTransform.sizeDelta = sizeDelta;
				rectTransform.offsetMin = offsetMin;
				rectTransform.offsetMax = offsetMax;
			}
			component.SetContext(context);
			component.SetVisible(visible: false);
			return component;
		}

		private void UpdateCellForIndex(FancyScrollViewCell<TData, TContext> cell, int dataIndex)
		{
			if (loop)
			{
				dataIndex = GetLoopIndex(dataIndex, cellData.Count);
			}
			else if (dataIndex < 0 || dataIndex > cellData.Count - 1)
			{
				cell.SetVisible(visible: false);
				return;
			}
			cell.SetVisible(visible: true);
			cell.DataIndex = dataIndex;
			cell.UpdateContent(cellData[dataIndex]);
		}

		private int GetLoopIndex(int index, int length)
		{
			if (index < 0)
			{
				index = length - 1 + (index + 1) % length;
			}
			else if (index > length - 1)
			{
				index %= length;
			}
			return index;
		}

		protected void UpdateContents()
		{
			UpdatePosition(currentPosition);
		}

		protected void UpdatePosition(float position)
		{
			currentPosition = position;
			float num = position - cellOffset / cellInterval;
			float num2 = (Mathf.Ceil(num) - num) * cellInterval;
			int num3 = Mathf.CeilToInt(num);
			int num4 = 0;
			int num5 = 0;
			float num6 = num2;
			while (num6 <= 1f)
			{
				if (num4 >= cells.Count)
				{
					cells.Add(CreateCell());
				}
				num6 += cellInterval;
				num4++;
			}
			num4 = 0;
			for (float num7 = num2; num7 <= 1f; num7 += cellInterval)
			{
				int num8 = num3 + num4;
				num5 = GetLoopIndex(num8, cells.Count);
				if (cells[num5].gameObject.activeSelf)
				{
					cells[num5].UpdatePosition(num7);
				}
				UpdateCellForIndex(cells[num5], num8);
				num4++;
			}
			num5 = GetLoopIndex(num3 + num4, cells.Count);
			while (num4 < cells.Count)
			{
				cells[num5].SetVisible(visible: false);
				num4++;
				num5 = GetLoopIndex(num3 + num4, cells.Count);
			}
		}
	}
