	[AddComponentMenu("Layout/Extensions/Flow Layout Group")]
	public class FlowLayoutGroup : LayoutGroup
	{
		public float SpacingX;

		public float SpacingY;

		public bool ExpandHorizontalSpacing;

		public bool ChildForceExpandWidth;

		public bool ChildForceExpandHeight;

		private float _layoutHeight;

		private readonly IList<RectTransform> _rowList = new List<RectTransform>();

		protected bool IsCenterAlign
		{
			get
			{
				if (base.childAlignment != TextAnchor.LowerCenter && base.childAlignment != TextAnchor.MiddleCenter)
				{
					return base.childAlignment == TextAnchor.UpperCenter;
				}
				return true;
			}
		}

		protected bool IsRightAlign
		{
			get
			{
				if (base.childAlignment != TextAnchor.LowerRight && base.childAlignment != TextAnchor.MiddleRight)
				{
					return base.childAlignment == TextAnchor.UpperRight;
				}
				return true;
			}
		}

		protected bool IsMiddleAlign
		{
			get
			{
				if (base.childAlignment != TextAnchor.MiddleLeft && base.childAlignment != TextAnchor.MiddleRight)
				{
					return base.childAlignment == TextAnchor.MiddleCenter;
				}
				return true;
			}
		}

		protected bool IsLowerAlign
		{
			get
			{
				if (base.childAlignment != TextAnchor.LowerLeft && base.childAlignment != TextAnchor.LowerRight)
				{
					return base.childAlignment == TextAnchor.LowerCenter;
				}
				return true;
			}
		}

		public override void CalculateLayoutInputHorizontal()
		{
			base.CalculateLayoutInputHorizontal();
			float totalMin = GetGreatestMinimumChildWidth() + (float)base.padding.left + (float)base.padding.right;
			SetLayoutInputForAxis(totalMin, -1f, -1f, 0);
		}

		public override void SetLayoutHorizontal()
		{
			SetLayout(base.rectTransform.rect.width, 0, layoutInput: false);
		}

		public override void SetLayoutVertical()
		{
			SetLayout(base.rectTransform.rect.width, 1, layoutInput: false);
		}

		public override void CalculateLayoutInputVertical()
		{
			_layoutHeight = SetLayout(base.rectTransform.rect.width, 1, layoutInput: true);
		}

		public float SetLayout(float width, int axis, bool layoutInput)
		{
			float height = base.rectTransform.rect.height;
			float num = base.rectTransform.rect.width - (float)base.padding.left - (float)base.padding.right;
			float num2 = (IsLowerAlign ? ((float)base.padding.bottom) : ((float)base.padding.top));
			float num3 = 0f;
			float num4 = 0f;
			for (int i = 0; i < base.rectChildren.Count; i++)
			{
				int index = (IsLowerAlign ? (base.rectChildren.Count - 1 - i) : i);
				RectTransform rectTransform = base.rectChildren[index];
				float preferredSize = LayoutUtility.GetPreferredSize(rectTransform, 0);
				float preferredSize2 = LayoutUtility.GetPreferredSize(rectTransform, 1);
				preferredSize = Mathf.Min(preferredSize, num);
				if (num3 + preferredSize > num)
				{
					num3 -= SpacingX;
					if (!layoutInput)
					{
						float yOffset = CalculateRowVerticalOffset(height, num2, num4);
						LayoutRow(_rowList, num3, num4, num, base.padding.left, yOffset, axis);
					}
					_rowList.Clear();
					num2 += num4;
					num2 += SpacingY;
					num4 = 0f;
					num3 = 0f;
				}
				num3 += preferredSize;
				_rowList.Add(rectTransform);
				if (preferredSize2 > num4)
				{
					num4 = preferredSize2;
				}
				if (i < base.rectChildren.Count - 1)
				{
					num3 += SpacingX;
				}
			}
			if (!layoutInput)
			{
				float yOffset2 = CalculateRowVerticalOffset(height, num2, num4);
				num3 -= SpacingX;
				LayoutRow(_rowList, num3, num4, num - ((_rowList.Count > 1) ? SpacingX : 0f), base.padding.left, yOffset2, axis);
			}
			_rowList.Clear();
			num2 += num4;
			num2 += (float)(IsLowerAlign ? base.padding.top : base.padding.bottom);
			if (layoutInput && axis == 1)
			{
				SetLayoutInputForAxis(num2, num2, -1f, axis);
			}
			return num2;
		}

		private float CalculateRowVerticalOffset(float groupHeight, float yOffset, float currentRowHeight)
		{
			if (IsLowerAlign)
			{
				return groupHeight - yOffset - currentRowHeight;
			}
			if (IsMiddleAlign)
			{
				return groupHeight * 0.5f - _layoutHeight * 0.5f + yOffset;
			}
			return yOffset;
		}

		protected void LayoutRow(IList<RectTransform> contents, float rowWidth, float rowHeight, float maxWidth, float xOffset, float yOffset, int axis)
		{
			float num = xOffset;
			if (!ChildForceExpandWidth && IsCenterAlign)
			{
				num += (maxWidth - rowWidth) * 0.5f;
			}
			else if (!ChildForceExpandWidth && IsRightAlign)
			{
				num += maxWidth - rowWidth;
			}
			float num2 = 0f;
			float num3 = 0f;
			if (ChildForceExpandWidth)
			{
				num2 = (maxWidth - rowWidth) / (float)_rowList.Count;
			}
			else if (ExpandHorizontalSpacing)
			{
				num3 = (maxWidth - rowWidth) / (float)(_rowList.Count - 1);
				if (_rowList.Count > 1)
				{
					if (IsCenterAlign)
					{
						num -= num3 * 0.5f * (float)(_rowList.Count - 1);
					}
					else if (IsRightAlign)
					{
						num -= num3 * (float)(_rowList.Count - 1);
					}
				}
			}
			for (int i = 0; i < _rowList.Count; i++)
			{
				int index = (IsLowerAlign ? (_rowList.Count - 1 - i) : i);
				RectTransform rect = _rowList[index];
				float a = LayoutUtility.GetPreferredSize(rect, 0) + num2;
				float num4 = LayoutUtility.GetPreferredSize(rect, 1);
				if (ChildForceExpandHeight)
				{
					num4 = rowHeight;
				}
				a = Mathf.Min(a, maxWidth);
				float num5 = yOffset;
				if (IsMiddleAlign)
				{
					num5 += (rowHeight - num4) * 0.5f;
				}
				else if (IsLowerAlign)
				{
					num5 += rowHeight - num4;
				}
				if (ExpandHorizontalSpacing && i > 0)
				{
					num += num3;
				}
				if (axis == 0)
				{
					SetChildAlongAxis(rect, 0, num, a);
				}
				else
				{
					SetChildAlongAxis(rect, 1, num5, num4);
				}
				if (i < _rowList.Count - 1)
				{
					num += a + SpacingX;
				}
			}
		}

		public float GetGreatestMinimumChildWidth()
		{
			float num = 0f;
			for (int i = 0; i < base.rectChildren.Count; i++)
			{
				num = Mathf.Max(LayoutUtility.GetMinWidth(base.rectChildren[i]), num);
			}
			return num;
		}
	}
	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("Layout/Extensions/Horizontal Scroll Snap")]
	public class HorizontalScrollSnap : ScrollSnapBase, IEndDragHandler, IEventSystemHandler
	{
		private void Start()
		{
			_isVertical = false;
			_childAnchorPoint = new Vector2(0f, 0.5f);
			_currentPage = StartingScreen;
			panelDimensions = base.gameObject.GetComponent<RectTransform>().rect;
			UpdateLayout();
		}

		private void Update()
		{
			if (!_lerp && _scroll_rect.velocity == Vector2.zero)
			{
				if (!_settled && !_pointerDown && !IsRectSettledOnaPage(_screensContainer.localPosition))
				{
					ScrollToClosestElement();
				}
				return;
			}
			if (_lerp)
			{
				_screensContainer.localPosition = Vector3.Lerp(_screensContainer.localPosition, _lerp_target, transitionSpeed * Time.deltaTime);
				if (Vector3.Distance(_screensContainer.localPosition, _lerp_target) < 0.1f)
				{
					_screensContainer.localPosition = _lerp_target;
					_lerp = false;
					EndScreenChange();
				}
			}
			base.CurrentPage = GetPageforPosition(_screensContainer.localPosition);
			if (!_pointerDown && ((double)_scroll_rect.velocity.x > 0.01 || (double)_scroll_rect.velocity.x < 0.01) && IsRectMovingSlowerThanThreshold(0f))
			{
				ScrollToClosestElement();
			}
		}

		private bool IsRectMovingSlowerThanThreshold(float startingSpeed)
		{
			if (!(_scroll_rect.velocity.x > startingSpeed) || !(_scroll_rect.velocity.x < (float)SwipeVelocityThreshold))
			{
				if (_scroll_rect.velocity.x < startingSpeed)
				{
					return _scroll_rect.velocity.x > (float)(-SwipeVelocityThreshold);
				}
				return false;
			}
			return true;
		}

		private void DistributePages()
		{
			_screens = _screensContainer.childCount;
			_scroll_rect.horizontalNormalizedPosition = 0f;
			int num = 0;
			float num2 = 0f;
			float num3 = 0f;
			float num4 = (_childSize = (float)(int)panelDimensions.width * ((PageStep == 0f) ? 3f : PageStep));
			for (int i = 0; i < _screensContainer.transform.childCount; i++)
			{
				RectTransform component = _screensContainer.transform.GetChild(i).gameObject.GetComponent<RectTransform>();
				num3 = num + (int)((float)i * num4);
				component.sizeDelta = new Vector2(panelDimensions.width, panelDimensions.height);
				component.anchoredPosition = new Vector2(num3, 0f);
				Vector2 vector = (component.pivot = _childAnchorPoint);
				Vector2 anchorMin = (component.anchorMax = vector);
				component.anchorMin = anchorMin;
			}
			num2 = num3 + (float)(num * -1);
			_screensContainer.offsetMax = new Vector2(num2, 0f);
		}

		public void AddChild(GameObject GO)
		{
			AddChild(GO, WorldPositionStays: false);
		}

		public void AddChild(GameObject GO, bool WorldPositionStays)
		{
			_scroll_rect.horizontalNormalizedPosition = 0f;
			GO.transform.SetParent(_screensContainer, WorldPositionStays);
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			SetScrollContainerPosition();
		}

		public void RemoveChild(int index, out GameObject ChildRemoved)
		{
			RemoveChild(index, WorldPositionStays: false, out ChildRemoved);
		}

		public void RemoveChild(int index, bool WorldPositionStays, out GameObject ChildRemoved)
		{
			ChildRemoved = null;
			if (index >= 0 && index <= _screensContainer.childCount)
			{
				_scroll_rect.horizontalNormalizedPosition = 0f;
				Transform child = _screensContainer.transform.GetChild(index);
				child.SetParent(null, WorldPositionStays);
				ChildRemoved = child.gameObject;
				InitialiseChildObjectsFromScene();
				DistributePages();
				if ((bool)MaskArea)
				{
					UpdateVisible();
				}
				if (_currentPage > _screens - 1)
				{
					base.CurrentPage = _screens - 1;
				}
				SetScrollContainerPosition();
			}
		}

		public void RemoveAllChildren(out GameObject[] ChildrenRemoved)
		{
			RemoveAllChildren(WorldPositionStays: false, out ChildrenRemoved);
		}

		public void RemoveAllChildren(bool WorldPositionStays, out GameObject[] ChildrenRemoved)
		{
			int childCount = _screensContainer.childCount;
			ChildrenRemoved = new GameObject[childCount];
			for (int num = childCount - 1; num >= 0; num--)
			{
				ChildrenRemoved[num] = _screensContainer.GetChild(num).gameObject;
				ChildrenRemoved[num].transform.SetParent(null, WorldPositionStays);
			}
			_scroll_rect.horizontalNormalizedPosition = 0f;
			base.CurrentPage = 0;
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
		}

		private void SetScrollContainerPosition()
		{
			_scrollStartPosition = _screensContainer.localPosition.x;
			_scroll_rect.horizontalNormalizedPosition = (float)_currentPage / (float)(_screens - 1);
			OnCurrentScreenChange(_currentPage);
		}

		public void UpdateLayout()
		{
			_lerp = false;
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			SetScrollContainerPosition();
			OnCurrentScreenChange(_currentPage);
		}

		private void OnRectTransformDimensionsChange()
		{
			if (_childAnchorPoint != Vector2.zero)
			{
				UpdateLayout();
			}
		}

		private void OnEnable()
		{
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			if (JumpOnEnable || !RestartOnEnable)
			{
				SetScrollContainerPosition();
			}
			if (RestartOnEnable)
			{
				GoToScreen(StartingScreen);
			}
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			_pointerDown = false;
			if (!_scroll_rect.horizontal)
			{
				return;
			}
			float num = Vector3.Distance(_startPosition, _screensContainer.localPosition);
			if (UseFastSwipe && num < panelDimensions.width && num >= (float)FastSwipeThreshold)
			{
				_scroll_rect.velocity = Vector3.zero;
				if (_startPosition.x - _screensContainer.localPosition.x > 0f)
				{
					NextScreen();
				}
				else
				{
					PreviousScreen();
				}
			}
		}
	}
	internal interface IScrollSnap
	{
		void ChangePage(int page);

		void SetLerp(bool value);

		int CurrentPage();

		void StartScreenChange();
	}
	[AddComponentMenu("Layout/Extensions/Radial Layout")]
	public class RadialLayout : LayoutGroup
	{
		public float fDistance;

		[Range(0f, 360f)]
		public float MinAngle;

		[Range(0f, 360f)]
		public float MaxAngle;

		[Range(0f, 360f)]
		public float StartAngle;

		protected override void OnEnable()
		{
			base.OnEnable();
			CalculateRadial();
		}

		public override void SetLayoutHorizontal()
		{
		}

		public override void SetLayoutVertical()
		{
		}

		public override void CalculateLayoutInputVertical()
		{
			CalculateRadial();
		}

		public override void CalculateLayoutInputHorizontal()
		{
			CalculateRadial();
		}

		private void CalculateRadial()
		{
			m_Tracker.Clear();
			if (base.transform.childCount == 0)
			{
				return;
			}
			float num = (MaxAngle - MinAngle) / (float)base.transform.childCount;
			float num2 = StartAngle;
			for (int i = 0; i < base.transform.childCount; i++)
			{
				RectTransform rectTransform = (RectTransform)base.transform.GetChild(i);
				if (rectTransform != null)
				{
					m_Tracker.Add(this, rectTransform, DrivenTransformProperties.Anchors | DrivenTransformProperties.AnchoredPosition | DrivenTransformProperties.Pivot);
					Vector3 vector = new Vector3(Mathf.Cos(num2 * (MathF.PI / 180f)), Mathf.Sin(num2 * (MathF.PI / 180f)), 0f);
					rectTransform.localPosition = vector * fDistance;
					Vector2 vector2 = (rectTransform.pivot = new Vector2(0.5f, 0.5f));
					Vector2 anchorMin = (rectTransform.anchorMax = vector2);
					rectTransform.anchorMin = anchorMin;
					num2 += num;
				}
			}
		}
	}
	public class ScrollPositionController : UIBehaviour, IBeginDragHandler, IEventSystemHandler, IEndDragHandler, IDragHandler
	{
		[Serializable]
		public class UpdatePositionEvent : UnityEvent<float>
		{
		}

		[Serializable]
		public class ItemSelectedEvent : UnityEvent<int>
		{
		}

		[Serializable]
		private struct Snap
		{
			public bool Enable;

			public float VelocityThreshold;

			public float Duration;
		}

		private enum ScrollDirection
		{
			Vertical,
			Horizontal
		}

		private enum MovementType
		{
			Unrestricted,
			Elastic,
			Clamped
		}

		[SerializeField]
		private RectTransform viewport;

		[SerializeField]
		private ScrollDirection directionOfRecognize;

		[SerializeField]
		private MovementType movementType = MovementType.Elastic;

		[SerializeField]
		private float elasticity = 0.1f;

		[SerializeField]
		private float scrollSensitivity = 1f;

		[SerializeField]
		private bool inertia = true;

		[SerializeField]
		[Tooltip("Only used when inertia is enabled")]
		private float decelerationRate = 0.03f;

		[SerializeField]
		[Tooltip("Only used when inertia is enabled")]
		private Snap snap = new Snap
		{
			Enable = true,
			VelocityThreshold = 0.5f,
			Duration = 0.3f
		};

		[SerializeField]
		private int dataCount;

		[Tooltip("Event that fires when the position of an item changes")]
		public UpdatePositionEvent OnUpdatePosition;

		[Tooltip("Event that fires when an item is selected/focused")]
		public ItemSelectedEvent OnItemSelected;

		private Vector2 pointerStartLocalPosition;

		private float dragStartScrollPosition;

		private float currentScrollPosition;

		private bool dragging;

		private float velocity;

		private float prevScrollPosition;

		private bool autoScrolling;

		private float autoScrollDuration;

		private float autoScrollStartTime;

		private float autoScrollPosition;

		void IBeginDragHandler.OnBeginDrag(PointerEventData eventData)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				pointerStartLocalPosition = Vector2.zero;
				RectTransformUtility.ScreenPointToLocalPointInRectangle(viewport, eventData.position, eventData.pressEventCamera, out pointerStartLocalPosition);
				dragStartScrollPosition = currentScrollPosition;
				dragging = true;
			}
		}

		void IDragHandler.OnDrag(PointerEventData eventData)
		{
			if (eventData.button == PointerEventData.InputButton.Left && dragging && RectTransformUtility.ScreenPointToLocalPointInRectangle(viewport, eventData.position, eventData.pressEventCamera, out var localPoint))
			{
				Vector2 vector = localPoint - pointerStartLocalPosition;
				float num = ((directionOfRecognize == ScrollDirection.Horizontal) ? (0f - vector.x) : vector.y) / GetViewportSize() * scrollSensitivity + dragStartScrollPosition;
				float num2 = CalculateOffset(num);
				num += num2;
				if (movementType == MovementType.Elastic && num2 != 0f)
				{
					num -= RubberDelta(num2, scrollSensitivity);
				}
				UpdatePosition(num);
			}
		}

		void IEndDragHandler.OnEndDrag(PointerEventData eventData)
		{
			if (eventData.button == PointerEventData.InputButton.Left)
			{
				dragging = false;
			}
		}

		private float GetViewportSize()
		{
			if (directionOfRecognize != ScrollDirection.Horizontal)
			{
				return viewport.rect.size.y;
			}
			return viewport.rect.size.x;
		}

		private float CalculateOffset(float position)
		{
			if (movementType == MovementType.Unrestricted)
			{
				return 0f;
			}
			if (position < 0f)
			{
				return 0f - position;
			}
			if (position > (float)(dataCount - 1))
			{
				return (float)(dataCount - 1) - position;
			}
			return 0f;
		}

		private void UpdatePosition(float position)
		{
			currentScrollPosition = position;
			if (OnUpdatePosition != null)
			{
				OnUpdatePosition.Invoke(currentScrollPosition);
			}
		}

		private float RubberDelta(float overStretching, float viewSize)
		{
			return (1f - 1f / (Mathf.Abs(overStretching) * 0.55f / viewSize + 1f)) * viewSize * Mathf.Sign(overStretching);
		}

		public void SetDataCount(int dataCont)
		{
			dataCount = dataCont;
		}

		private void Update()
		{
			float unscaledDeltaTime = Time.unscaledDeltaTime;
			float num = CalculateOffset(currentScrollPosition);
			if (autoScrolling)
			{
				float num2 = Mathf.Clamp01((Time.unscaledTime - autoScrollStartTime) / Mathf.Max(autoScrollDuration, float.Epsilon));
				float position = Mathf.Lerp(dragStartScrollPosition, autoScrollPosition, EaseInOutCubic(0f, 1f, num2));
				UpdatePosition(position);
				if (Mathf.Approximately(num2, 1f))
				{
					autoScrolling = false;
					if (OnItemSelected != null)
					{
						OnItemSelected.Invoke(Mathf.RoundToInt(GetLoopPosition(autoScrollPosition, dataCount)));
					}
				}
			}
			else if (!dragging && (num != 0f || velocity != 0f))
			{
				float num3 = currentScrollPosition;
				if (movementType == MovementType.Elastic && num != 0f)
				{
					float currentVelocity = velocity;
					num3 = Mathf.SmoothDamp(currentScrollPosition, currentScrollPosition + num, ref currentVelocity, elasticity, float.PositiveInfinity, unscaledDeltaTime);
					velocity = currentVelocity;
				}
				else if (inertia)
				{
					velocity *= Mathf.Pow(decelerationRate, unscaledDeltaTime);
					if (Mathf.Abs(velocity) < 0.001f)
					{
						velocity = 0f;
					}
					num3 += velocity * unscaledDeltaTime;
					if (snap.Enable && Mathf.Abs(velocity) < snap.VelocityThreshold)
					{
						ScrollTo(Mathf.RoundToInt(currentScrollPosition), snap.Duration);
					}
				}
				else
				{
					velocity = 0f;
				}
				if (velocity != 0f)
				{
					if (movementType == MovementType.Clamped)
					{
						num = CalculateOffset(num3);
						num3 += num;
					}
					UpdatePosition(num3);
				}
			}
			if (!autoScrolling && dragging && inertia)
			{
				float b = (currentScrollPosition - prevScrollPosition) / unscaledDeltaTime;
				velocity = Mathf.Lerp(velocity, b, unscaledDeltaTime * 10f);
			}
			if (currentScrollPosition != prevScrollPosition)
			{
				prevScrollPosition = currentScrollPosition;
			}
		}

		public void ScrollTo(int index, float duration)
		{
			velocity = 0f;
			autoScrolling = true;
			autoScrollDuration = duration;
			autoScrollStartTime = Time.unscaledTime;
			dragStartScrollPosition = currentScrollPosition;
			autoScrollPosition = ((movementType == MovementType.Unrestricted) ? CalculateClosestPosition(index) : ((float)index));
		}

		private float CalculateClosestPosition(int index)
		{
			float num = GetLoopPosition(index, dataCount) - GetLoopPosition(currentScrollPosition, dataCount);
			if (Mathf.Abs(num) > (float)dataCount * 0.5f)
			{
				num = Mathf.Sign(0f - num) * ((float)dataCount - Mathf.Abs(num));
			}
			return num + currentScrollPosition;
		}

		private float GetLoopPosition(float position, int length)
		{
			if (position < 0f)
			{
				position = (float)(length - 1) + (position + 1f) % (float)length;
			}
			else if (position > (float)(length - 1))
			{
				position %= (float)length;
			}
			return position;
		}

		private float EaseInOutCubic(float start, float end, float value)
		{
			value /= 0.5f;
			end -= start;
			if (value < 1f)
			{
				return end * 0.5f * value * value * value + start;
			}
			value -= 2f;
			return end * 0.5f * (value * value * value + 2f) + start;
		}
	}
	[ExecuteInEditMode]
	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("UI/Extensions/Scroll Snap")]
	public class ScrollSnap : MonoBehaviour, IBeginDragHandler, IEventSystemHandler, IEndDragHandler, IDragHandler, IScrollSnap
	{
		public enum ScrollDirection
		{
			Horizontal,
			Vertical
		}

		public delegate void PageSnapChange(int page);

		private ScrollRect _scroll_rect;

		private RectTransform _scrollRectTransform;

		private Transform _listContainerTransform;

		private int _pages;

		private int _startingPage;

		private Vector3[] _pageAnchorPositions;

		private Vector3 _lerpTarget;

		private bool _lerp;

		private float _listContainerMinPosition;

		private float _listContainerMaxPosition;

		private float _listContainerSize;

		private RectTransform _listContainerRectTransform;

		private Vector2 _listContainerCachedSize;

		private float _itemSize;

		private int _itemsCount;

		private bool _startDrag = true;

		private Vector3 _positionOnDragStart;

		private int _pageOnDragStart;

		private bool _fastSwipeTimer;

		private int _fastSwipeCounter;

		private int _fastSwipeTarget = 10;

		[Tooltip("Button to go to the next page. (optional)")]
		public Button NextButton;

		[Tooltip("Button to go to the previous page. (optional)")]
		public Button PrevButton;

		[Tooltip("Number of items visible in one page of scroll frame.")]
		[Range(1f, 100f)]
		public int ItemsVisibleAtOnce = 1;

		[Tooltip("Sets minimum width of list items to 1/itemsVisibleAtOnce.")]
		public bool AutoLayoutItems = true;

		[Tooltip("If you wish to update scrollbar numberOfSteps to number of active children on list.")]
		public bool LinkScrolbarSteps;

		[Tooltip("If you wish to update scrollrect sensitivity to size of list element.")]
		public bool LinkScrolrectScrollSensitivity;

		public bool UseFastSwipe = true;

		public int FastSwipeThreshold = 100;

		public ScrollDirection direction;

		private bool fastSwipe;

		public event PageSnapChange onPageChange;

		private void Start()
		{
			_lerp = false;
			_scroll_rect = base.gameObject.GetComponent<ScrollRect>();
			_scrollRectTransform = base.gameObject.GetComponent<RectTransform>();
			_listContainerTransform = _scroll_rect.content;
			_listContainerRectTransform = _listContainerTransform.GetComponent<RectTransform>();
			UpdateListItemsSize();
			UpdateListItemPositions();
			PageChanged(CurrentPage());
			if ((bool)NextButton)
			{
				NextButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					NextScreen();
				});
			}
			if ((bool)PrevButton)
			{
				PrevButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					PreviousScreen();
				});
			}
			if (_scroll_rect.horizontalScrollbar != null && _scroll_rect.horizontal)
			{
				_scroll_rect.horizontalScrollbar.gameObject.AddComponent<ScrollSnapScrollbarHelper>().ss = this;
			}
			if (_scroll_rect.verticalScrollbar != null && _scroll_rect.vertical)
			{
				_scroll_rect.verticalScrollbar.gameObject.AddComponent<ScrollSnapScrollbarHelper>().ss = this;
			}
		}

		public void UpdateListItemsSize()
		{
			float num = 0f;
			float num2 = 0f;
			if (direction == ScrollDirection.Horizontal)
			{
				num = _scrollRectTransform.rect.width / (float)ItemsVisibleAtOnce;
				num2 = _listContainerRectTransform.rect.width / (float)_itemsCount;
			}
			else
			{
				num = _scrollRectTransform.rect.height / (float)ItemsVisibleAtOnce;
				num2 = _listContainerRectTransform.rect.height / (float)_itemsCount;
			}
			_itemSize = num;
			if (LinkScrolrectScrollSensitivity)
			{
				_scroll_rect.scrollSensitivity = _itemSize;
			}
			if (!AutoLayoutItems || num2 == num || _itemsCount <= 0)
			{
				return;
			}
			if (direction == ScrollDirection.Horizontal)
			{
				foreach (Transform item in _listContainerTransform)
				{
					GameObject gameObject = item.gameObject;
					if (gameObject.activeInHierarchy)
					{
						LayoutElement layoutElement = gameObject.GetComponent<LayoutElement>();
						if (layoutElement == null)
						{
							layoutElement = gameObject.AddComponent<LayoutElement>();
						}
						layoutElement.minWidth = _itemSize;
					}
				}
				return;
			}
			foreach (Transform item2 in _listContainerTransform)
			{
				GameObject gameObject2 = item2.gameObject;
				if (gameObject2.activeInHierarchy)
				{
					LayoutElement layoutElement2 = gameObject2.GetComponent<LayoutElement>();
					if (layoutElement2 == null)
					{
						layoutElement2 = gameObject2.AddComponent<LayoutElement>();
					}
					layoutElement2.minHeight = _itemSize;
				}
			}
		}

		public void UpdateListItemPositions()
		{
			if (_listContainerRectTransform.rect.size.Equals(_listContainerCachedSize))
			{
				return;
			}
			int num = 0;
			foreach (Transform item in _listContainerTransform)
			{
				if (item.gameObject.activeInHierarchy)
				{
					num++;
				}
			}
			_itemsCount = 0;
			Array.Resize(ref _pageAnchorPositions, num);
			if (num > 0)
			{
				_pages = Mathf.Max(num - ItemsVisibleAtOnce + 1, 1);
				if (direction == ScrollDirection.Horizontal)
				{
					_scroll_rect.horizontalNormalizedPosition = 0f;
					_listContainerMaxPosition = _listContainerTransform.localPosition.x;
					_scroll_rect.horizontalNormalizedPosition = 1f;
					_listContainerMinPosition = _listContainerTransform.localPosition.x;
					_listContainerSize = _listContainerMaxPosition - _listContainerMinPosition;
					for (int i = 0; i < _pages; i++)
					{
						_pageAnchorPositions[i] = new Vector3(_listContainerMaxPosition - _itemSize * (float)i, _listContainerTransform.localPosition.y, _listContainerTransform.localPosition.z);
					}
				}
				else
				{
					_scroll_rect.verticalNormalizedPosition = 1f;
					_listContainerMinPosition = _listContainerTransform.localPosition.y;
					_scroll_rect.verticalNormalizedPosition = 0f;
					_listContainerMaxPosition = _listContainerTransform.localPosition.y;
					_listContainerSize = _listContainerMaxPosition - _listContainerMinPosition;
					for (int j = 0; j < _pages; j++)
					{
						_pageAnchorPositions[j] = new Vector3(_listContainerTransform.localPosition.x, _listContainerMinPosition + _itemSize * (float)j, _listContainerTransform.localPosition.z);
					}
				}
				UpdateScrollbar(LinkScrolbarSteps);
				_startingPage = Mathf.Min(_startingPage, _pages);
				ResetPage();
			}
			if (_itemsCount != num)
			{
				PageChanged(CurrentPage());
			}
			_itemsCount = num;
			_listContainerCachedSize.Set(_listContainerRectTransform.rect.size.x, _listContainerRectTransform.rect.size.y);
		}

		public void ResetPage()
		{
			if (direction == ScrollDirection.Horizontal)
			{
				_scroll_rect.horizontalNormalizedPosition = ((_pages > 1) ? ((float)_startingPage / (float)(_pages - 1)) : 0f);
			}
			else
			{
				_scroll_rect.verticalNormalizedPosition = ((_pages > 1) ? ((float)(_pages - _startingPage - 1) / (float)(_pages - 1)) : 0f);
			}
		}

		private void UpdateScrollbar(bool linkSteps)
		{
			if (linkSteps)
			{
				if (direction == ScrollDirection.Horizontal)
				{
					if (_scroll_rect.horizontalScrollbar != null)
					{
						_scroll_rect.horizontalScrollbar.numberOfSteps = _pages;
					}
				}
				else if (_scroll_rect.verticalScrollbar != null)
				{
					_scroll_rect.verticalScrollbar.numberOfSteps = _pages;
				}
			}
			else if (direction == ScrollDirection.Horizontal)
			{
				if (_scroll_rect.horizontalScrollbar != null)
				{
					_scroll_rect.horizontalScrollbar.numberOfSteps = 0;
				}
			}
			else if (_scroll_rect.verticalScrollbar != null)
			{
				_scroll_rect.verticalScrollbar.numberOfSteps = 0;
			}
		}

		private void LateUpdate()
		{
			UpdateListItemsSize();
			UpdateListItemPositions();
			if (_lerp)
			{
				UpdateScrollbar(linkSteps: false);
				_listContainerTransform.localPosition = Vector3.Lerp(_listContainerTransform.localPosition, _lerpTarget, 7.5f * Time.deltaTime);
				if (Vector3.Distance(_listContainerTransform.localPosition, _lerpTarget) < 0.001f)
				{
					_listContainerTransform.localPosition = _lerpTarget;
					_lerp = false;
					UpdateScrollbar(LinkScrolbarSteps);
				}
				if (Vector3.Distance(_listContainerTransform.localPosition, _lerpTarget) < 10f)
				{
					PageChanged(CurrentPage());
				}
			}
			if (_fastSwipeTimer)
			{
				_fastSwipeCounter++;
			}
		}

		public void NextScreen()
		{
			UpdateListItemPositions();
			if (CurrentPage() < _pages - 1)
			{
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[CurrentPage() + 1];
				PageChanged(CurrentPage() + 1);
			}
		}

		public void PreviousScreen()
		{
			UpdateListItemPositions();
			if (CurrentPage() > 0)
			{
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[CurrentPage() - 1];
				PageChanged(CurrentPage() - 1);
			}
		}

		private void NextScreenCommand()
		{
			if (_pageOnDragStart < _pages - 1)
			{
				int num = Mathf.Min(_pages - 1, _pageOnDragStart + ItemsVisibleAtOnce);
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[num];
				PageChanged(num);
			}
		}

		private void PrevScreenCommand()
		{
			if (_pageOnDragStart > 0)
			{
				int num = Mathf.Max(0, _pageOnDragStart - ItemsVisibleAtOnce);
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[num];
				PageChanged(num);
			}
		}

		public int CurrentPage()
		{
			float value;
			if (direction == ScrollDirection.Horizontal)
			{
				value = _listContainerMaxPosition - _listContainerTransform.localPosition.x;
				value = Mathf.Clamp(value, 0f, _listContainerSize);
			}
			else
			{
				value = _listContainerTransform.localPosition.y - _listContainerMinPosition;
				value = Mathf.Clamp(value, 0f, _listContainerSize);
			}
			return Mathf.Clamp(Mathf.RoundToInt(value / _itemSize), 0, _pages);
		}

		public void SetLerp(bool value)
		{
			_lerp = value;
		}

		public void ChangePage(int page)
		{
			if (0 <= page && page < _pages)
			{
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[page];
				PageChanged(page);
			}
		}

		private void PageChanged(int currentPage)
		{
			_startingPage = currentPage;
			if ((bool)NextButton)
			{
				NextButton.interactable = currentPage < _pages - 1;
			}
			if ((bool)PrevButton)
			{
				PrevButton.interactable = currentPage > 0;
			}
			if (this.onPageChange != null)
			{
				this.onPageChange(currentPage);
			}
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			UpdateScrollbar(linkSteps: false);
			_fastSwipeCounter = 0;
			_fastSwipeTimer = true;
			_positionOnDragStart = eventData.position;
			_pageOnDragStart = CurrentPage();
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			_startDrag = true;
			float num = 0f;
			num = ((direction != ScrollDirection.Horizontal) ? (0f - _positionOnDragStart.y + eventData.position.y) : (_positionOnDragStart.x - eventData.position.x));
			if (UseFastSwipe)
			{
				fastSwipe = false;
				_fastSwipeTimer = false;
				if (_fastSwipeCounter <= _fastSwipeTarget && System.Math.Abs(num) > (float)FastSwipeThreshold)
				{
					fastSwipe = true;
				}
				if (fastSwipe)
				{
					if (num > 0f)
					{
						NextScreenCommand();
					}
					else
					{
						PrevScreenCommand();
					}
				}
				else
				{
					_lerp = true;
					_lerpTarget = _pageAnchorPositions[CurrentPage()];
				}
			}
			else
			{
				_lerp = true;
				_lerpTarget = _pageAnchorPositions[CurrentPage()];
			}
		}

		public void OnDrag(PointerEventData eventData)
		{
			_lerp = false;
			if (_startDrag)
			{
				OnBeginDrag(eventData);
				_startDrag = false;
			}
		}

		public void StartScreenChange()
		{
		}
	}
	public class ScrollSnapBase : MonoBehaviour, IBeginDragHandler, IEventSystemHandler, IDragHandler, IScrollSnap
	{
		[Serializable]
		public class SelectionChangeStartEvent : UnityEvent
		{
		}

		[Serializable]
		public class SelectionPageChangedEvent : UnityEvent<int>
		{
		}

		[Serializable]
		public class SelectionChangeEndEvent : UnityEvent<int>
		{
		}

		internal Rect panelDimensions;

		internal RectTransform _screensContainer;

		internal bool _isVertical;

		internal int _screens = 1;

		internal float _scrollStartPosition;

		internal float _childSize;

		private float _childPos;

		private float _maskSize;

		internal Vector2 _childAnchorPoint;

		internal ScrollRect _scroll_rect;

		internal Vector3 _lerp_target;

		internal bool _lerp;

		internal bool _pointerDown;

		internal bool _settled = true;

		internal Vector3 _startPosition;

		[Tooltip("The currently active page")]
		internal int _currentPage;

		internal int _previousPage;

		internal int _halfNoVisibleItems;

		internal bool _moveStarted;

		private int _bottomItem;

		private int _topItem;

		[Tooltip("The screen / page to start the control on\n*Note, this is a 0 indexed array")]
		[SerializeField]
		public int StartingScreen;

		[Tooltip("The distance between two pages based on page height, by default pages are next to each other")]
		[SerializeField]
		[Range(0f, 8f)]
		public float PageStep = 1f;

		[Tooltip("The gameobject that contains toggles which suggest pagination. (optional)")]
		public GameObject Pagination;

		[Tooltip("Button to go to the previous page. (optional)")]
		public GameObject PrevButton;

		[Tooltip("Button to go to the next page. (optional)")]
		public GameObject NextButton;

		[Tooltip("Transition speed between pages. (optional)")]
		public float transitionSpeed = 7.5f;

		[Tooltip("Fast Swipe makes swiping page next / previous (optional)")]
		public bool UseFastSwipe;

		[Tooltip("Offset for how far a swipe has to travel to initiate a page change (optional)")]
		public int FastSwipeThreshold = 100;

		[Tooltip("Speed at which the ScrollRect will keep scrolling before slowing down and stopping (optional)")]
		public int SwipeVelocityThreshold = 100;

		[Tooltip("The visible bounds area, controls which items are visible/enabled. *Note Should use a RectMask. (optional)")]
		public RectTransform MaskArea;

		[Tooltip("Pixel size to buffer arround Mask Area. (optional)")]
		public float MaskBuffer = 1f;

		[Tooltip("By default the container will lerp to the start when enabled in the scene, this option overrides this and forces it to simply jump without lerping")]
		public bool JumpOnEnable;

		[Tooltip("By default the container will return to the original starting page when enabled, this option overrides this behaviour and stays on the current selection")]
		public bool RestartOnEnable;

		[Tooltip("(Experimental)\nBy default, child array objects will use the parent transform\nHowever you can disable this for some interesting effects")]
		public bool UseParentTransform = true;

		[Tooltip("Scroll Snap children. (optional)\nEither place objects in the scene as children OR\nPrefabs in this array, NOT BOTH")]
		public GameObject[] ChildObjects;

		[SerializeField]
		[Tooltip("Event fires when a user starts to change the selection")]
		private SelectionChangeStartEvent m_OnSelectionChangeStartEvent = new SelectionChangeStartEvent();

		[SerializeField]
		[Tooltip("Event fires as the page changes, while dragging or jumping")]
		private SelectionPageChangedEvent m_OnSelectionPageChangedEvent = new SelectionPageChangedEvent();

		[SerializeField]
		[Tooltip("Event fires when the page settles after a user has dragged")]
		private SelectionChangeEndEvent m_OnSelectionChangeEndEvent = new SelectionChangeEndEvent();

		public int CurrentPage
		{
			get
			{
				return _currentPage;
			}
			internal set
			{
				if ((value != _currentPage && value >= 0 && value < _screensContainer.childCount) || (value == 0 && _screensContainer.childCount == 0))
				{
					_previousPage = _currentPage;
					_currentPage = value;
					if ((bool)MaskArea)
					{
						UpdateVisible();
					}
					if (!_lerp)
					{
						ScreenChange();
					}
					OnCurrentScreenChange(_currentPage);
				}
			}
		}

		public SelectionChangeStartEvent OnSelectionChangeStartEvent
		{
			get
			{
				return m_OnSelectionChangeStartEvent;
			}
			set
			{
				m_OnSelectionChangeStartEvent = value;
			}
		}

		public SelectionPageChangedEvent OnSelectionPageChangedEvent
		{
			get
			{
				return m_OnSelectionPageChangedEvent;
			}
			set
			{
				m_OnSelectionPageChangedEvent = value;
			}
		}

		public SelectionChangeEndEvent OnSelectionChangeEndEvent
		{
			get
			{
				return m_OnSelectionChangeEndEvent;
			}
			set
			{
				m_OnSelectionChangeEndEvent = value;
			}
		}

		private void Awake()
		{
			if (_scroll_rect == null)
			{
				_scroll_rect = base.gameObject.GetComponent<ScrollRect>();
			}
			if ((bool)_scroll_rect.horizontalScrollbar && _scroll_rect.horizontal)
			{
				_scroll_rect.horizontalScrollbar.gameObject.AddComponent<ScrollSnapScrollbarHelper>().ss = this;
			}
			if ((bool)_scroll_rect.verticalScrollbar && _scroll_rect.vertical)
			{
				_scroll_rect.verticalScrollbar.gameObject.AddComponent<ScrollSnapScrollbarHelper>().ss = this;
			}
			panelDimensions = base.gameObject.GetComponent<RectTransform>().rect;
			if (StartingScreen < 0)
			{
				StartingScreen = 0;
			}
			_screensContainer = _scroll_rect.content;
			InitialiseChildObjects();
			if ((bool)NextButton)
			{
				NextButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					NextScreen();
				});
			}
			if ((bool)PrevButton)
			{
				PrevButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					PreviousScreen();
				});
			}
		}

		internal void InitialiseChildObjects()
		{
			if (ChildObjects != null && ChildObjects.Length != 0)
			{
				if (_screensContainer.transform.childCount > 0)
				{
					Debug.LogError("ScrollRect Content has children, this is not supported when using managed Child Objects\n Either remove the ScrollRect Content children or clear the ChildObjects array");
				}
				else
				{
					InitialiseChildObjectsFromArray();
				}
			}
			else
			{
				InitialiseChildObjectsFromScene();
			}
		}

		internal void InitialiseChildObjectsFromScene()
		{
			int childCount = _screensContainer.childCount;
			ChildObjects = new GameObject[childCount];
			for (int i = 0; i < childCount; i++)
			{
				ChildObjects[i] = _screensContainer.transform.GetChild(i).gameObject;
				if ((bool)MaskArea && ChildObjects[i].activeSelf)
				{
					ChildObjects[i].SetActive(value: false);
				}
			}
		}

		internal void InitialiseChildObjectsFromArray()
		{
			int num = ChildObjects.Length;
			for (int i = 0; i < num; i++)
			{
				GameObject gameObject = Object.Instantiate(ChildObjects[i]);
				if (UseParentTransform)
				{
					RectTransform component = gameObject.GetComponent<RectTransform>();
					component.rotation = _screensContainer.rotation;
					component.localScale = _screensContainer.localScale;
					component.position = _screensContainer.position;
				}
				gameObject.transform.SetParent(_screensContainer.transform);
				ChildObjects[i] = gameObject;
				if ((bool)MaskArea && ChildObjects[i].activeSelf)
				{
					ChildObjects[i].SetActive(value: false);
				}
			}
		}

		internal void UpdateVisible()
		{
			if (!MaskArea || ChildObjects == null || ChildObjects.Length < 1 || _screensContainer.childCount < 1)
			{
				return;
			}
			_maskSize = (_isVertical ? MaskArea.rect.height : MaskArea.rect.width);
			_halfNoVisibleItems = (int)System.Math.Round(_maskSize / (_childSize * MaskBuffer), MidpointRounding.AwayFromZero) / 2;
			_bottomItem = (_topItem = 0);
			for (int num = _halfNoVisibleItems + 1; num > 0; num--)
			{
				_bottomItem = ((_currentPage - num >= 0) ? num : 0);
				if (_bottomItem > 0)
				{
					break;
				}
			}
			for (int num2 = _halfNoVisibleItems + 1; num2 > 0; num2--)
			{
				_topItem = ((_screensContainer.childCount - _currentPage - num2 >= 0) ? num2 : 0);
				if (_topItem > 0)
				{
					break;
				}
			}
			for (int i = CurrentPage - _bottomItem; i < CurrentPage + _topItem; i++)
			{
				try
				{
					ChildObjects[i].SetActive(value: true);
				}
				catch
				{
					Debug.Log("Failed to setactive child [" + i + "]");
				}
			}
			if (_currentPage > _halfNoVisibleItems)
			{
				ChildObjects[CurrentPage - _bottomItem].SetActive(value: false);
			}
			if (_screensContainer.childCount - _currentPage > _topItem)
			{
				ChildObjects[CurrentPage + _topItem].SetActive(value: false);
			}
		}

		public void NextScreen()
		{
			if (_currentPage < _screens - 1)
			{
				if (!_lerp)
				{
					StartScreenChange();
				}
				_lerp = true;
				CurrentPage = _currentPage + 1;
				GetPositionforPage(_currentPage, ref _lerp_target);
				ScreenChange();
			}
		}

		public void PreviousScreen()
		{
			if (_currentPage > 0)
			{
				if (!_lerp)
				{
					StartScreenChange();
				}
				_lerp = true;
				CurrentPage = _currentPage - 1;
				GetPositionforPage(_currentPage, ref _lerp_target);
				ScreenChange();
			}
		}

		public void GoToScreen(int screenIndex)
		{
			if (screenIndex <= _screens - 1 && screenIndex >= 0)
			{
				if (!_lerp)
				{
					StartScreenChange();
				}
				_lerp = true;
				CurrentPage = screenIndex;
				GetPositionforPage(_currentPage, ref _lerp_target);
				ScreenChange();
			}
		}

		internal int GetPageforPosition(Vector3 pos)
		{
			if (!_isVertical)
			{
				return (int)System.Math.Round((_scrollStartPosition - pos.x) / _childSize);
			}
			return (int)System.Math.Round((_scrollStartPosition - pos.y) / _childSize);
		}

		internal bool IsRectSettledOnaPage(Vector3 pos)
		{
			if (!_isVertical)
			{
				return 0f - (pos.x - _scrollStartPosition) / _childSize == (float)(-(int)System.Math.Round((pos.x - _scrollStartPosition) / _childSize));
			}
			return 0f - (pos.y - _scrollStartPosition) / _childSize == (float)(-(int)System.Math.Round((pos.y - _scrollStartPosition) / _childSize));
		}

		internal void GetPositionforPage(int page, ref Vector3 target)
		{
			_childPos = (0f - _childSize) * (float)page;
			if (_isVertical)
			{
				target.y = _childPos + _scrollStartPosition;
			}
			else
			{
				target.x = _childPos + _scrollStartPosition;
			}
		}

		internal void ScrollToClosestElement()
		{
			_lerp = true;
			CurrentPage = GetPageforPosition(_screensContainer.localPosition);
			GetPositionforPage(_currentPage, ref _lerp_target);
			OnCurrentScreenChange(_currentPage);
		}

		internal void OnCurrentScreenChange(int currentScreen)
		{
			ChangeBulletsInfo(currentScreen);
			ToggleNavigationButtons(currentScreen);
		}

		private void ChangeBulletsInfo(int targetScreen)
		{
			if ((bool)Pagination)
			{
				for (int i = 0; i < Pagination.transform.childCount; i++)
				{
					Pagination.transform.GetChild(i).GetComponent<Toggle>().isOn = ((targetScreen == i) ? true : false);
				}
			}
		}

		private void ToggleNavigationButtons(int targetScreen)
		{
			if ((bool)PrevButton)
			{
				PrevButton.GetComponent<Button>().interactable = targetScreen > 0;
			}
			if ((bool)NextButton)
			{
				NextButton.GetComponent<Button>().interactable = targetScreen < _screensContainer.transform.childCount - 1;
			}
		}

		private void OnValidate()
		{
			if (_scroll_rect == null)
			{
				_scroll_rect = GetComponent<ScrollRect>();
			}
			if (!_scroll_rect.horizontal && !_scroll_rect.vertical)
			{
				Debug.LogError("ScrollRect has to have a direction, please select either Horizontal OR Vertical with the appropriate control.");
			}
			if (_scroll_rect.horizontal && _scroll_rect.vertical)
			{
				Debug.LogError("ScrollRect has to be unidirectional, only use either Horizontal or Vertical on the ScrollRect, NOT both.");
			}
			int childCount = base.gameObject.GetComponent<ScrollRect>().content.childCount;
			if (childCount != 0 || ChildObjects != null)
			{
				int num = ((ChildObjects == null || ChildObjects.Length == 0) ? childCount : ChildObjects.Length);
				if (StartingScreen > num - 1)
				{
					StartingScreen = num - 1;
				}
				if (StartingScreen < 0)
				{
					StartingScreen = 0;
				}
			}
			if (MaskBuffer <= 0f)
			{
				MaskBuffer = 1f;
			}
			if (PageStep < 0f)
			{
				PageStep = 0f;
			}
			if (PageStep > 8f)
			{
				PageStep = 9f;
			}
		}

		public void StartScreenChange()
		{
			if (!_moveStarted)
			{
				_moveStarted = true;
				OnSelectionChangeStartEvent.Invoke();
			}
		}

		internal void ScreenChange()
		{
			OnSelectionPageChangedEvent.Invoke(_currentPage);
		}

		internal void EndScreenChange()
		{
			OnSelectionChangeEndEvent.Invoke(_currentPage);
			_settled = true;
			_moveStarted = false;
		}

		public Transform CurrentPageObject()
		{
			return _screensContainer.GetChild(CurrentPage);
		}

		public void CurrentPageObject(out Transform returnObject)
		{
			returnObject = _screensContainer.GetChild(CurrentPage);
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			_pointerDown = true;
			_settled = false;
			StartScreenChange();
			_startPosition = _screensContainer.localPosition;
		}

		public void OnDrag(PointerEventData eventData)
		{
			_lerp = false;
		}

		int IScrollSnap.CurrentPage()
		{
			return CurrentPage = GetPageforPosition(_screensContainer.localPosition);
		}

		public void SetLerp(bool value)
		{
			_lerp = value;
		}

		public void ChangePage(int page)
		{
			GoToScreen(page);
		}
	}
	public class ScrollSnapScrollbarHelper : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IPointerUpHandler, IBeginDragHandler, IEndDragHandler, IDragHandler
	{
		internal IScrollSnap ss;

		public void OnBeginDrag(PointerEventData eventData)
		{
			OnScrollBarDown();
		}

		public void OnDrag(PointerEventData eventData)
		{
			ss.CurrentPage();
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			OnScrollBarUp();
		}

		public void OnPointerDown(PointerEventData eventData)
		{
			OnScrollBarDown();
		}

		public void OnPointerUp(PointerEventData eventData)
		{
			OnScrollBarUp();
		}

		private void OnScrollBarDown()
		{
			if (ss != null)
			{
				ss.SetLerp(value: false);
				ss.StartScreenChange();
			}
		}

		private void OnScrollBarUp()
		{
			ss.SetLerp(value: true);
			ss.ChangePage(ss.CurrentPage());
		}
	}
	[AddComponentMenu("Layout/Extensions/Table Layout Group")]
	public class TableLayoutGroup : LayoutGroup
	{
		public enum Corner
		{
			UpperLeft,
			UpperRight,
			LowerLeft,
			LowerRight
		}

		[SerializeField]
		protected Corner startCorner;

		[SerializeField]
		protected float[] columnWidths = new float[1] { 96f };

		[SerializeField]
		protected float minimumRowHeight = 32f;

		[SerializeField]
		protected bool flexibleRowHeight = true;

		[SerializeField]
		protected float columnSpacing;

		[SerializeField]
		protected float rowSpacing;

		private float[] preferredRowHeights;

		public Corner StartCorner
		{
			get
			{
				return startCorner;
			}
			set
			{
				SetProperty(ref startCorner, value);
			}
		}

		public float[] ColumnWidths
		{
			get
			{
				return columnWidths;
			}
			set
			{
				SetProperty(ref columnWidths, value);
			}
		}

		public float MinimumRowHeight
		{
			get
			{
				return minimumRowHeight;
			}
			set
			{
				SetProperty(ref minimumRowHeight, value);
			}
		}

		public bool FlexibleRowHeight
		{
			get
			{
				return flexibleRowHeight;
			}
			set
			{
				SetProperty(ref flexibleRowHeight, value);
			}
		}

		public float ColumnSpacing
		{
			get
			{
				return columnSpacing;
			}
			set
			{
				SetProperty(ref columnSpacing, value);
			}
		}

		public float RowSpacing
		{
			get
			{
				return rowSpacing;
			}
			set
			{
				SetProperty(ref rowSpacing, value);
			}
		}

		public override void CalculateLayoutInputHorizontal()
		{
			base.CalculateLayoutInputHorizontal();
			float num = base.padding.horizontal;
			int num2 = Mathf.Min(base.rectChildren.Count, columnWidths.Length);
			for (int i = 0; i < num2; i++)
			{
				num += columnWidths[i];
				num += columnSpacing;
			}
			num -= columnSpacing;
			SetLayoutInputForAxis(num, num, 0f, 0);
		}

		public override void CalculateLayoutInputVertical()
		{
			int num = columnWidths.Length;
			int num2 = Mathf.CeilToInt((float)base.rectChildren.Count / (float)num);
			preferredRowHeights = new float[num2];
			float num3 = base.padding.vertical;
			float num4 = base.padding.vertical;
			if (num2 > 1)
			{
				float num5 = (float)(num2 - 1) * rowSpacing;
				num3 += num5;
				num4 += num5;
			}
			if (flexibleRowHeight)
			{
				float num6 = 0f;
				float num7 = 0f;
				for (int i = 0; i < num2; i++)
				{
					num6 = minimumRowHeight;
					num7 = minimumRowHeight;
					for (int j = 0; j < num; j++)
					{
						int num8 = i * num + j;
						if (num8 == base.rectChildren.Count)
						{
							break;
						}
						num7 = Mathf.Max(LayoutUtility.GetPreferredHeight(base.rectChildren[num8]), num7);
						num6 = Mathf.Max(LayoutUtility.GetMinHeight(base.rectChildren[num8]), num6);
					}
					num3 += num6;
					num4 += num7;
					preferredRowHeights[i] = num7;
				}
			}
			else
			{
				for (int k = 0; k < num2; k++)
				{
					preferredRowHeights[k] = minimumRowHeight;
				}
				num3 += (float)num2 * minimumRowHeight;
				num4 = num3;
			}
			num4 = Mathf.Max(num3, num4);
			SetLayoutInputForAxis(num3, num4, 1f, 1);
		}

		public override void SetLayoutHorizontal()
		{
			if (columnWidths.Length == 0)
			{
				columnWidths = new float[1];
			}
			int num = columnWidths.Length;
			int num2 = (int)startCorner % 2;
			float num3 = 0f;
			float num4 = 0f;
			int num5 = Mathf.Min(base.rectChildren.Count, columnWidths.Length);
			for (int i = 0; i < num5; i++)
			{
				num4 += columnWidths[i];
				num4 += columnSpacing;
			}
			num4 -= columnSpacing;
			num3 = GetStartOffset(0, num4);
			if (num2 == 1)
			{
				num3 += num4;
			}
			float num6 = num3;
			for (int j = 0; j < base.rectChildren.Count; j++)
			{
				int num7 = j % num;
				if (num7 == 0)
				{
					num6 = num3;
				}
				if (num2 == 1)
				{
					num6 -= columnWidths[num7];
				}
				SetChildAlongAxis(base.rectChildren[j], 0, num6, columnWidths[num7]);
				num6 = ((num2 != 1) ? (num6 + (columnWidths[num7] + columnSpacing)) : (num6 - columnSpacing));
			}
		}

		public override void SetLayoutVertical()
		{
			int num = columnWidths.Length;
			int num2 = preferredRowHeights.Length;
			int num3 = (int)startCorner / 2;
			float num4 = 0f;
			float num5 = 0f;
			for (int i = 0; i < num2; i++)
			{
				num5 += preferredRowHeights[i];
			}
			if (num2 > 1)
			{
				num5 += (float)(num2 - 1) * rowSpacing;
			}
			num4 = GetStartOffset(1, num5);
			if (num3 == 1)
			{
				num4 += num5;
			}
			float num6 = num4;
			for (int j = 0; j < num2; j++)
			{
				if (num3 == 1)
				{
					num6 -= preferredRowHeights[j];
				}
				for (int k = 0; k < num; k++)
				{
					int num7 = j * num + k;
					if (num7 == base.rectChildren.Count)
					{
						break;
					}
					SetChildAlongAxis(base.rectChildren[num7], 1, num6, preferredRowHeights[j]);
				}
				num6 = ((num3 != 1) ? (num6 + (preferredRowHeights[j] + rowSpacing)) : (num6 - rowSpacing));
			}
			preferredRowHeights = null;
		}
	}
	[ExecuteInEditMode]
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("Layout/Extensions/Tile Size Fitter")]
	public class TileSizeFitter : UIBehaviour, ILayoutSelfController, ILayoutController
	{
		[SerializeField]
		private Vector2 m_Border = Vector2.zero;

		[SerializeField]
		private Vector2 m_TileSize = Vector2.zero;

		[NonSerialized]
		private RectTransform m_Rect;

		private DrivenRectTransformTracker m_Tracker;

		public Vector2 Border
		{
			get
			{
				return m_Border;
			}
			set
			{
				if (SetPropertyUtility.SetStruct(ref m_Border, value))
				{
					SetDirty();
				}
			}
		}

		public Vector2 TileSize
		{
			get
			{
				return m_TileSize;
			}
			set
			{
				if (SetPropertyUtility.SetStruct(ref m_TileSize, value))
				{
					SetDirty();
				}
			}
		}

		private RectTransform rectTransform
		{
			get
			{
				if (m_Rect == null)
				{
					m_Rect = GetComponent<RectTransform>();
				}
				return m_Rect;
			}
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			SetDirty();
		}

		protected override void OnDisable()
		{
			m_Tracker.Clear();
			LayoutRebuilder.MarkLayoutForRebuild(rectTransform);
			base.OnDisable();
		}

		protected override void OnRectTransformDimensionsChange()
		{
			UpdateRect();
		}

		private void UpdateRect()
		{
			if (IsActive())
			{
				m_Tracker.Clear();
				m_Tracker.Add(this, rectTransform, DrivenTransformProperties.Anchors | DrivenTransformProperties.AnchoredPosition);
				rectTransform.anchorMin = Vector2.zero;
				rectTransform.anchorMax = Vector2.one;
				rectTransform.anchoredPosition = Vector2.zero;
				m_Tracker.Add(this, rectTransform, DrivenTransformProperties.SizeDelta);
				Vector2 vector = GetParentSize() - Border;
				if (TileSize.x > 0.001f)
				{
					vector.x -= Mathf.Floor(vector.x / TileSize.x) * TileSize.x;
				}
				else
				{
					vector.x = 0f;
				}
				if (TileSize.y > 0.001f)
				{
					vector.y -= Mathf.Floor(vector.y / TileSize.y) * TileSize.y;
				}
				else
				{
					vector.y = 0f;
				}
				rectTransform.sizeDelta = -vector;
			}
		}

		private Vector2 GetParentSize()
		{
			RectTransform rectTransform = this.rectTransform.parent as RectTransform;
			if (!rectTransform)
			{
				return Vector2.zero;
			}
			return rectTransform.rect.size;
		}

		public virtual void SetLayoutHorizontal()
		{
		}

		public virtual void SetLayoutVertical()
		{
		}

		protected void SetDirty()
		{
			if (IsActive())
			{
				UpdateRect();
			}
		}
	}
	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("Layout/Extensions/Vertical Scroller")]
	public class UIVerticalScroller : MonoBehaviour
	{
		[Tooltip("Scrollable area (content of desired ScrollRect)")]
		public RectTransform _scrollingPanel;

		[Tooltip("Elements to populate inside the scroller")]
		public GameObject[] _arrayOfElements;

		[Tooltip("Center display area (position of zoomed content)")]
		public RectTransform _center;

		[Tooltip("Select the item to be in center on start. (optional)")]
		public int StartingIndex = -1;

		[Tooltip("Button to go to the next page. (optional)")]
		public GameObject ScrollUpButton;

		[Tooltip("Button to go to the previous page. (optional)")]
		public GameObject ScrollDownButton;

		[Tooltip("Event fired when a specific item is clicked, exposes index number of item. (optional)")]
		public UnityEvent<int> ButtonClicked;

		private float[] distReposition;

		private float[] distance;

		private int minElementsNum;

		private int elementLength;

		private float deltaY;

		private string result;

		public UIVerticalScroller()
		{
		}

		public UIVerticalScroller(RectTransform scrollingPanel, GameObject[] arrayOfElements, RectTransform center)
		{
			_scrollingPanel = scrollingPanel;
			_arrayOfElements = arrayOfElements;
			_center = center;
		}

		public void Awake()
		{
			ScrollRect component = GetComponent<ScrollRect>();
			if (!_scrollingPanel)
			{
				_scrollingPanel = component.content;
			}
			if (!_center)
			{
				Debug.LogError("Please define the RectTransform for the Center viewport of the scrollable area");
			}
			if (_arrayOfElements != null && _arrayOfElements.Length != 0)
			{
				return;
			}
			int childCount = component.content.childCount;
			if (childCount > 0)
			{
				_arrayOfElements = new GameObject[childCount];
				for (int i = 0; i < childCount; i++)
				{
					_arrayOfElements[i] = component.content.GetChild(i).gameObject;
				}
			}
		}

		public void Start()
		{
			if (_arrayOfElements.Length < 1)
			{
				Debug.Log("No child content found, exiting..");
				return;
			}
			elementLength = _arrayOfElements.Length;
			distance = new float[elementLength];
			distReposition = new float[elementLength];
			deltaY = _arrayOfElements[0].GetComponent<RectTransform>().rect.height * (float)elementLength / 3f * 2f;
			Vector2 anchoredPosition = new Vector2(_scrollingPanel.anchoredPosition.x, 0f - deltaY);
			_scrollingPanel.anchoredPosition = anchoredPosition;
			for (int i = 0; i < _arrayOfElements.Length; i++)
			{
				AddListener(_arrayOfElements[i], i);
			}
			if ((bool)ScrollUpButton)
			{
				ScrollUpButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					ScrollUp();
				});
			}
			if ((bool)ScrollDownButton)
			{
				ScrollDownButton.GetComponent<Button>().onClick.AddListener(delegate
				{
					ScrollDown();
				});
			}
			if (StartingIndex > -1)
			{
				StartingIndex = ((StartingIndex > _arrayOfElements.Length) ? (_arrayOfElements.Length - 1) : StartingIndex);
				SnapToElement(StartingIndex);
			}
		}

		private void AddListener(GameObject button, int index)
		{
			button.GetComponent<Button>().onClick.AddListener(delegate
			{
				DoSomething(index);
			});
		}

		private void DoSomething(int index)
		{
			if (ButtonClicked != null)
			{
				ButtonClicked.Invoke(index);
			}
		}

		public void Update()
		{
			if (_arrayOfElements.Length < 1)
			{
				return;
			}
			for (int i = 0; i < elementLength; i++)
			{
				distReposition[i] = _center.GetComponent<RectTransform>().position.y - _arrayOfElements[i].GetComponent<RectTransform>().position.y;
				distance[i] = Mathf.Abs(distReposition[i]);
				float num = Mathf.Max(0.7f, 1f / (1f + distance[i] / 200f));
				_arrayOfElements[i].GetComponent<RectTransform>().transform.localScale = new Vector3(num, num, 1f);
			}
			float num2 = Mathf.Min(distance);
			for (int j = 0; j < elementLength; j++)
			{
				_arrayOfElements[j].GetComponent<CanvasGroup>().interactable = false;
				if (num2 == distance[j])
				{
					minElementsNum = j;
					_arrayOfElements[j].GetComponent<CanvasGroup>().interactable = true;
					result = _arrayOfElements[j].GetComponentInChildren<Text>().text;
				}
			}
			ScrollingElements(0f - _arrayOfElements[minElementsNum].GetComponent<RectTransform>().anchoredPosition.y);
		}

		private void ScrollingElements(float position)
		{
			float y = Mathf.Lerp(_scrollingPanel.anchoredPosition.y, position, Time.deltaTime * 1f);
			Vector2 anchoredPosition = new Vector2(_scrollingPanel.anchoredPosition.x, y);
			_scrollingPanel.anchoredPosition = anchoredPosition;
		}

		public string GetResults()
		{
			return result;
		}

		public void SnapToElement(int element)
		{
			float num = _arrayOfElements[0].GetComponent<RectTransform>().rect.height * (float)element;
			Vector2 anchoredPosition = new Vector2(_scrollingPanel.anchoredPosition.x, 0f - num);
			_scrollingPanel.anchoredPosition = anchoredPosition;
		}

		public void ScrollUp()
		{
			float num = _arrayOfElements[0].GetComponent<RectTransform>().rect.height / 1.2f;
			Vector2 b = new Vector2(_scrollingPanel.anchoredPosition.x, _scrollingPanel.anchoredPosition.y - num);
			_scrollingPanel.anchoredPosition = Vector2.Lerp(_scrollingPanel.anchoredPosition, b, 1f);
		}

		public void ScrollDown()
		{
			float num = _arrayOfElements[0].GetComponent<RectTransform>().rect.height / 1.2f;
			Vector2 anchoredPosition = new Vector2(_scrollingPanel.anchoredPosition.x, _scrollingPanel.anchoredPosition.y + num);
			_scrollingPanel.anchoredPosition = anchoredPosition;
		}
	}
	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("Layout/Extensions/Vertical Scroll Snap")]
	public class VerticalScrollSnap : ScrollSnapBase, IEndDragHandler, IEventSystemHandler
	{
		private void Start()
		{
			_isVertical = true;
			_childAnchorPoint = new Vector2(0.5f, 0f);
			_currentPage = StartingScreen;
			panelDimensions = base.gameObject.GetComponent<RectTransform>().rect;
			UpdateLayout();
		}

		private void Update()
		{
			if (!_lerp && _scroll_rect.velocity == Vector2.zero)
			{
				if (!_settled && !_pointerDown && !IsRectSettledOnaPage(_screensContainer.localPosition))
				{
					ScrollToClosestElement();
				}
				return;
			}
			if (_lerp)
			{
				_screensContainer.localPosition = Vector3.Lerp(_screensContainer.localPosition, _lerp_target, transitionSpeed * Time.deltaTime);
				if (Vector3.Distance(_screensContainer.localPosition, _lerp_target) < 0.1f)
				{
					_screensContainer.localPosition = _lerp_target;
					_lerp = false;
					EndScreenChange();
				}
			}
			base.CurrentPage = GetPageforPosition(_screensContainer.localPosition);
			if (!_pointerDown && ((double)_scroll_rect.velocity.y > 0.01 || (double)_scroll_rect.velocity.y < -0.01) && IsRectMovingSlowerThanThreshold(0f))
			{
				ScrollToClosestElement();
			}
		}

		private bool IsRectMovingSlowerThanThreshold(float startingSpeed)
		{
			if (!(_scroll_rect.velocity.y > startingSpeed) || !(_scroll_rect.velocity.y < (float)SwipeVelocityThreshold))
			{
				if (_scroll_rect.velocity.y < startingSpeed)
				{
					return _scroll_rect.velocity.y > (float)(-SwipeVelocityThreshold);
				}
				return false;
			}
			return true;
		}

		public void DistributePages()
		{
			_screens = _screensContainer.childCount;
			_scroll_rect.verticalNormalizedPosition = 0f;
			float num = 0f;
			float num2 = 0f;
			Rect rect = base.gameObject.GetComponent<RectTransform>().rect;
			float num3 = 0f;
			float num4 = (_childSize = (float)(int)rect.height * ((PageStep == 0f) ? 3f : PageStep));
			for (int i = 0; i < _screensContainer.transform.childCount; i++)
			{
				RectTransform component = _screensContainer.transform.GetChild(i).gameObject.GetComponent<RectTransform>();
				num3 = num + (float)i * num4;
				component.sizeDelta = new Vector2(rect.width, rect.height);
				component.anchoredPosition = new Vector2(0f, num3);
				Vector2 vector = (component.pivot = _childAnchorPoint);
				Vector2 anchorMin = (component.anchorMax = vector);
				component.anchorMin = anchorMin;
			}
			num2 = num3 + num * -1f;
			_screensContainer.GetComponent<RectTransform>().offsetMax = new Vector2(0f, num2);
		}

		public void AddChild(GameObject GO)
		{
			AddChild(GO, WorldPositionStays: false);
		}

		public void AddChild(GameObject GO, bool WorldPositionStays)
		{
			_scroll_rect.verticalNormalizedPosition = 0f;
			GO.transform.SetParent(_screensContainer, WorldPositionStays);
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			SetScrollContainerPosition();
		}

		public void RemoveChild(int index, out GameObject ChildRemoved)
		{
			RemoveChild(index, WorldPositionStays: false, out ChildRemoved);
		}

		public void RemoveChild(int index, bool WorldPositionStays, out GameObject ChildRemoved)
		{
			ChildRemoved = null;
			if (index >= 0 && index <= _screensContainer.childCount)
			{
				_scroll_rect.verticalNormalizedPosition = 0f;
				Transform child = _screensContainer.transform.GetChild(index);
				child.SetParent(null, WorldPositionStays);
				ChildRemoved = child.gameObject;
				InitialiseChildObjectsFromScene();
				DistributePages();
				if ((bool)MaskArea)
				{
					UpdateVisible();
				}
				if (_currentPage > _screens - 1)
				{
					base.CurrentPage = _screens - 1;
				}
				SetScrollContainerPosition();
			}
		}

		public void RemoveAllChildren(out GameObject[] ChildrenRemoved)
		{
			RemoveAllChildren(WorldPositionStays: false, out ChildrenRemoved);
		}

		public void RemoveAllChildren(bool WorldPositionStays, out GameObject[] ChildrenRemoved)
		{
			int childCount = _screensContainer.childCount;
			ChildrenRemoved = new GameObject[childCount];
			for (int num = childCount - 1; num >= 0; num--)
			{
				ChildrenRemoved[num] = _screensContainer.GetChild(num).gameObject;
				ChildrenRemoved[num].transform.SetParent(null, WorldPositionStays);
			}
			_scroll_rect.verticalNormalizedPosition = 0f;
			base.CurrentPage = 0;
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
		}

		private void SetScrollContainerPosition()
		{
			_scrollStartPosition = _screensContainer.localPosition.y;
			_scroll_rect.verticalNormalizedPosition = (float)_currentPage / (float)(_screens - 1);
			OnCurrentScreenChange(_currentPage);
		}

		public void UpdateLayout()
		{
			_lerp = false;
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			SetScrollContainerPosition();
			OnCurrentScreenChange(_currentPage);
		}

		private void OnRectTransformDimensionsChange()
		{
			if (_childAnchorPoint != Vector2.zero)
			{
				UpdateLayout();
			}
		}

		private void OnEnable()
		{
			InitialiseChildObjectsFromScene();
			DistributePages();
			if ((bool)MaskArea)
			{
				UpdateVisible();
			}
			if (JumpOnEnable || !RestartOnEnable)
			{
				SetScrollContainerPosition();
			}
			if (RestartOnEnable)
			{
				GoToScreen(StartingScreen);
			}
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			_pointerDown = false;
			if (!_scroll_rect.vertical)
			{
				return;
			}
			float num = Vector3.Distance(_startPosition, _screensContainer.localPosition);
			if (UseFastSwipe && num < panelDimensions.height + (float)FastSwipeThreshold && num >= 1f)
			{
				_scroll_rect.velocity = Vector3.zero;
				if (_startPosition.y - _screensContainer.localPosition.y > 0f)
				{
					NextScreen();
				}
				else
				{
					PreviousScreen();
				}
			}
		}
	}
	public abstract class Menu<T> : Menu where T : Menu<T>
	{
		public static T Instance { get; private set; }

		protected virtual void Awake()
		{
			Instance = (T)this;
		}

		protected virtual void OnDestroy()
		{
			Instance = null;
		}

		protected static void Open()
		{
			if (Instance == null)
			{
				MenuManager.Instance.CreateInstance(typeof(T).Name);
			}
			else
			{
				Instance.gameObject.SetActive(value: true);
			}
			MenuManager.Instance.OpenMenu(Instance);
		}

		protected static void Close()
		{
			if (Instance == null)
			{
				Debug.LogErrorFormat("Trying to close menu {0} but Instance is null", typeof(T));
			}
			else
			{
				MenuManager.Instance.CloseMenu(Instance);
			}
		}

		public override void OnBackPressed()
		{
			Close();
		}
	}
	public abstract class Menu : MonoBehaviour
	{
		[Tooltip("Destroy the Game Object when menu is closed (reduces memory usage)")]
		public bool DestroyWhenClosed = true;

		[Tooltip("Disable menus that are under this one in the stack")]
		public bool DisableMenusUnderneath = true;

		public abstract void OnBackPressed();
	}
	[AddComponentMenu("UI/Extensions/Menu Manager")]
	[DisallowMultipleComponent]
	public class MenuManager : MonoBehaviour
	{
		public Menu[] MenuScreens;

		public int StartScreen;

		private Stack<Menu> menuStack = new Stack<Menu>();

		public static MenuManager Instance { get; set; }

		private void Awake()
		{
			Instance = this;
			if (MenuScreens.Length > StartScreen)
			{
				CreateInstance(MenuScreens[StartScreen].name);
				OpenMenu(MenuScreens[StartScreen]);
			}
			else
			{
				Debug.LogError("Not enough Menu Screens configured");
			}
		}

		private void OnDestroy()
		{
			Instance = null;
		}

		public void CreateInstance<T>() where T : Menu
		{
			Object.Instantiate(GetPrefab<T>(), base.transform);
		}

		public void CreateInstance(string MenuName)
		{
			Object.Instantiate(GetPrefab(MenuName), base.transform);
		}

		public void OpenMenu(Menu instance)
		{
			if (menuStack.Count > 0)
			{
				if (instance.DisableMenusUnderneath)
				{
					foreach (Menu item in menuStack)
					{
						item.gameObject.SetActive(value: false);
						if (item.DisableMenusUnderneath)
						{
							break;
						}
					}
				}
				Canvas component = instance.GetComponent<Canvas>();
				Canvas component2 = menuStack.Peek().GetComponent<Canvas>();
				component.sortingOrder = component2.sortingOrder + 1;
			}
			menuStack.Push(instance);
		}

		private GameObject GetPrefab(string PrefabName)
		{
			for (int i = 0; i < MenuScreens.Length; i++)
			{
				if (MenuScreens[i].name == PrefabName)
				{
					return MenuScreens[i].gameObject;
				}
			}
			throw new MissingReferenceException("Prefab not found for " + PrefabName);
		}

		private T GetPrefab<T>() where T : Menu
		{
			FieldInfo[] fields = GetType().GetFields(BindingFlags.DeclaredOnly | BindingFlags.Instance | BindingFlags.Public);
			for (int i = 0; i < fields.Length; i++)
			{
				T val = fields[i].GetValue(this) as T;
				if (val != null)
				{
					return val;
				}
			}
			throw new MissingReferenceException("Prefab not found for type " + typeof(T));
		}

		public void CloseMenu(Menu menu)
		{
			if (menuStack.Count == 0)
			{
				Debug.LogErrorFormat(menu, "{0} cannot be closed because menu stack is empty", menu.GetType());
			}
			else if (menuStack.Peek() != menu)
			{
				Debug.LogErrorFormat(menu, "{0} cannot be closed because it is not on top of stack", menu.GetType());
			}
			else
			{
				CloseTopMenu();
			}
		}

		public void CloseTopMenu()
		{
			Menu menu = menuStack.Pop();
			if (menu.DestroyWhenClosed)
			{
				Object.Destroy(menu.gameObject);
			}
			else
			{
				menu.gameObject.SetActive(value: false);
			}
			foreach (Menu item in menuStack)
			{
				item.gameObject.SetActive(value: true);
				if (item.DisableMenusUnderneath)
				{
					break;
				}
			}
		}

		private void Update()
		{
			if (Input.GetKeyDown(KeyCode.Escape) && menuStack.Count > 0)
			{
				menuStack.Peek().OnBackPressed();
			}
		}
	}
	public abstract class SimpleMenu<T> : Menu<T> where T : SimpleMenu<T>
