				return m_b;
			}
			set
			{
				m_b = value;
			}
		}

		public float C
		{
			get
			{
				return m_c;
			}
			set
			{
				m_c = value;
			}
		}

		public float D
		{
			get
			{
				return m_d;
			}
			set
			{
				m_d = value;
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			vh.Clear();
			float num = base.rectTransform.rect.width / 2f;
			m_a = System.Math.Min(1f, System.Math.Max(0f, m_a));
			m_b = System.Math.Min(1f, System.Math.Max(0f, m_b));
			m_c = System.Math.Min(1f, System.Math.Max(0f, m_c));
			m_d = System.Math.Min(1f, System.Math.Max(0f, m_d));
			Color32 color = this.color;
			vh.AddVert(new Vector3((0f - num) * m_a, 0f), color, new Vector2(0f, 0f));
			vh.AddVert(new Vector3(0f, num * m_b), color, new Vector2(0f, 1f));
			vh.AddVert(new Vector3(num * m_c, 0f), color, new Vector2(1f, 1f));
			vh.AddVert(new Vector3(0f, (0f - num) * m_d), color, new Vector2(1f, 0f));
			vh.AddTriangle(0, 1, 2);
			vh.AddTriangle(2, 3, 0);
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/UI Circle")]
	public class UICircle : UIPrimitiveBase
	{
		[Tooltip("The circular fill percentage of the primitive, affected by FixedToSegments")]
		[Range(0f, 100f)]
		[SerializeField]
		private int m_fillPercent = 100;

		[Tooltip("Should the primitive fill draw by segments or absolute percentage")]
		public bool FixedToSegments;

		[Tooltip("Draw the primitive filled or as a line")]
		[SerializeField]
		private bool m_fill = true;

		[Tooltip("If not filled, the thickness of the primitive line")]
		[SerializeField]
		private float m_thickness = 5f;

		[Tooltip("The number of segments to draw the primitive, more segments = smoother primitive")]
		[Range(0f, 360f)]
		[SerializeField]
		private int m_segments = 360;

		public int FillPercent
		{
			get
			{
				return m_fillPercent;
			}
			set
			{
				m_fillPercent = value;
				SetAllDirty();
			}
		}

		public bool Fill
		{
			get
			{
				return m_fill;
			}
			set
			{
				m_fill = value;
				SetAllDirty();
			}
		}

		public float Thickness
		{
			get
			{
				return m_thickness;
			}
			set
			{
				m_thickness = value;
				SetAllDirty();
			}
		}

		public int Segments
		{
			get
			{
				return m_segments;
			}
			set
			{
				m_segments = value;
				SetAllDirty();
			}
		}

		private void Update()
		{
			m_thickness = Mathf.Clamp(m_thickness, 0f, base.rectTransform.rect.width / 2f);
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			float outer = (0f - base.rectTransform.pivot.x) * base.rectTransform.rect.width;
			float inner = (0f - base.rectTransform.pivot.x) * base.rectTransform.rect.width + m_thickness;
			vh.Clear();
			Vector2 prevX = Vector2.zero;
			Vector2 prevY = Vector2.zero;
			Vector2 vector = new Vector2(0f, 0f);
			Vector2 vector2 = new Vector2(0f, 1f);
			Vector2 vector3 = new Vector2(1f, 1f);
			Vector2 vector4 = new Vector2(1f, 0f);
			Vector2 pos;
			Vector2 pos2;
			Vector2 pos3;
			Vector2 pos4;
			if (FixedToSegments)
			{
				float num = (float)m_fillPercent / 100f;
				float num2 = 360f / (float)m_segments;
				int num3 = (int)((float)(m_segments + 1) * num);
				for (int i = 0; i < num3; i++)
				{
					float f = MathF.PI / 180f * ((float)i * num2);
					float c = Mathf.Cos(f);
					float s = Mathf.Sin(f);
					vector = new Vector2(0f, 1f);
					vector2 = new Vector2(1f, 1f);
					vector3 = new Vector2(1f, 0f);
					vector4 = new Vector2(0f, 0f);
					StepThroughPointsAndFill(outer, inner, ref prevX, ref prevY, out pos, out pos2, out pos3, out pos4, c, s);
					vh.AddUIVertexQuad(SetVbo(new Vector2[4] { pos, pos2, pos3, pos4 }, new Vector2[4] { vector, vector2, vector3, vector4 }));
				}
				return;
			}
			float width = base.rectTransform.rect.width;
			float height = base.rectTransform.rect.height;
			float num4 = (float)m_fillPercent / 100f * (MathF.PI * 2f) / (float)m_segments;
			float num5 = 0f;
			for (int j = 0; j < m_segments + 1; j++)
			{
				float c2 = Mathf.Cos(num5);
				float s2 = Mathf.Sin(num5);
				StepThroughPointsAndFill(outer, inner, ref prevX, ref prevY, out pos, out pos2, out pos3, out pos4, c2, s2);
				vector = new Vector2(pos.x / width + 0.5f, pos.y / height + 0.5f);
				vector2 = new Vector2(pos2.x / width + 0.5f, pos2.y / height + 0.5f);
				vector3 = new Vector2(pos3.x / width + 0.5f, pos3.y / height + 0.5f);
				vector4 = new Vector2(pos4.x / width + 0.5f, pos4.y / height + 0.5f);
				vh.AddUIVertexQuad(SetVbo(new Vector2[4] { pos, pos2, pos3, pos4 }, new Vector2[4] { vector, vector2, vector3, vector4 }));
				num5 += num4;
			}
		}

		private void StepThroughPointsAndFill(float outer, float inner, ref Vector2 prevX, ref Vector2 prevY, out Vector2 pos0, out Vector2 pos1, out Vector2 pos2, out Vector2 pos3, float c, float s)
		{
			pos0 = prevX;
			pos1 = new Vector2(outer * c, outer * s);
			if (m_fill)
			{
				pos2 = Vector2.zero;
				pos3 = Vector2.zero;
			}
			else
			{
				pos2 = new Vector2(inner * c, inner * s);
				pos3 = prevY;
			}
			prevX = pos1;
			prevY = pos2;
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/Cut Corners")]
	public class UICornerCut : UIPrimitiveBase
	{
		public Vector2 cornerSize = new Vector2(16f, 16f);

		[Header("Corners to cut")]
		[SerializeField]
		private bool m_cutUL = true;

		[SerializeField]
		private bool m_cutUR;

		[SerializeField]
		private bool m_cutLL;

		[SerializeField]
		private bool m_cutLR;

		[Tooltip("Up-Down colors become Left-Right colors")]
		[SerializeField]
		private bool m_makeColumns;

		[Header("Color the cut bars differently")]
		[SerializeField]
		private bool m_useColorUp;

		[SerializeField]
		private Color32 m_colorUp;

		[SerializeField]
		private bool m_useColorDown;

		[SerializeField]
		private Color32 m_colorDown;

		public bool CutUL
		{
			get
			{
				return m_cutUL;
			}
			set
			{
				m_cutUL = value;
				SetAllDirty();
			}
		}

		public bool CutUR
		{
			get
			{
				return m_cutUR;
			}
			set
			{
				m_cutUR = value;
				SetAllDirty();
			}
		}

		public bool CutLL
		{
			get
			{
				return m_cutLL;
			}
			set
			{
				m_cutLL = value;
				SetAllDirty();
			}
		}

		public bool CutLR
		{
			get
			{
				return m_cutLR;
			}
			set
			{
				m_cutLR = value;
				SetAllDirty();
			}
		}

		public bool MakeColumns
		{
			get
			{
				return m_makeColumns;
			}
			set
			{
				m_makeColumns = value;
				SetAllDirty();
			}
		}

		public bool UseColorUp
		{
			get
			{
				return m_useColorUp;
			}
			set
			{
				m_useColorUp = value;
			}
		}

		public Color32 ColorUp
		{
			get
			{
				return m_colorUp;
			}
			set
			{
				m_colorUp = value;
			}
		}

		public bool UseColorDown
		{
			get
			{
				return m_useColorDown;
			}
			set
			{
				m_useColorDown = value;
			}
		}

		public Color32 ColorDown
		{
			get
			{
				return m_colorDown;
			}
			set
			{
				m_colorDown = value;
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			Rect rect = base.rectTransform.rect;
			Rect rect2 = rect;
			Color32 color = this.color;
			bool flag = m_cutUL | m_cutUR;
			bool flag2 = m_cutLL | m_cutLR;
			bool flag3 = m_cutLL | m_cutUL;
			bool flag4 = m_cutLR | m_cutUR;
			if (!(flag || flag2) || !(cornerSize.sqrMagnitude > 0f))
			{
				return;
			}
			vh.Clear();
			if (flag3)
			{
				rect2.xMin += cornerSize.x;
			}
			if (flag2)
			{
				rect2.yMin += cornerSize.y;
			}
			if (flag)
			{
				rect2.yMax -= cornerSize.y;
			}
			if (flag4)
			{
				rect2.xMax -= cornerSize.x;
			}
			Vector2 vector;
			Vector2 vector2;
			Vector2 vector3;
			Vector2 vector4;
			if (m_makeColumns)
			{
				vector = new Vector2(rect.xMin, m_cutUL ? rect2.yMax : rect.yMax);
				vector2 = new Vector2(rect.xMax, m_cutUR ? rect2.yMax : rect.yMax);
				vector3 = new Vector2(rect.xMin, m_cutLL ? rect2.yMin : rect.yMin);
				vector4 = new Vector2(rect.xMax, m_cutLR ? rect2.yMin : rect.yMin);
				if (flag3)
				{
					AddSquare(vector3, vector, new Vector2(rect2.xMin, rect.yMax), new Vector2(rect2.xMin, rect.yMin), rect, m_useColorUp ? m_colorUp : color, vh);
				}
				if (flag4)
				{
					AddSquare(vector2, vector4, new Vector2(rect2.xMax, rect.yMin), new Vector2(rect2.xMax, rect.yMax), rect, m_useColorDown ? m_colorDown : color, vh);
				}
			}
			else
			{
				vector = new Vector2(m_cutUL ? rect2.xMin : rect.xMin, rect.yMax);
				vector2 = new Vector2(m_cutUR ? rect2.xMax : rect.xMax, rect.yMax);
				vector3 = new Vector2(m_cutLL ? rect2.xMin : rect.xMin, rect.yMin);
				vector4 = new Vector2(m_cutLR ? rect2.xMax : rect.xMax, rect.yMin);
				if (flag2)
				{
					AddSquare(vector4, vector3, new Vector2(rect.xMin, rect2.yMin), new Vector2(rect.xMax, rect2.yMin), rect, m_useColorDown ? m_colorDown : color, vh);
				}
				if (flag)
				{
					AddSquare(vector, vector2, new Vector2(rect.xMax, rect2.yMax), new Vector2(rect.xMin, rect2.yMax), rect, m_useColorUp ? m_colorUp : color, vh);
				}
			}
			if (m_makeColumns)
			{
				AddSquare(new Rect(rect2.xMin, rect.yMin, rect2.width, rect.height), rect, color, vh);
			}
			else
			{
				AddSquare(new Rect(rect.xMin, rect2.yMin, rect.width, rect2.height), rect, color, vh);
			}
		}

		private static void AddSquare(Rect rect, Rect rectUV, Color32 color32, VertexHelper vh)
		{
			int num = AddVert(rect.xMin, rect.yMin, rectUV, color32, vh);
			int idx = AddVert(rect.xMin, rect.yMax, rectUV, color32, vh);
			int num2 = AddVert(rect.xMax, rect.yMax, rectUV, color32, vh);
			int idx2 = AddVert(rect.xMax, rect.yMin, rectUV, color32, vh);
			vh.AddTriangle(num, idx, num2);
			vh.AddTriangle(num2, idx2, num);
		}

		private static void AddSquare(Vector2 a, Vector2 b, Vector2 c, Vector2 d, Rect rectUV, Color32 color32, VertexHelper vh)
		{
			int num = AddVert(a.x, a.y, rectUV, color32, vh);
			int idx = AddVert(b.x, b.y, rectUV, color32, vh);
			int num2 = AddVert(c.x, c.y, rectUV, color32, vh);
			int idx2 = AddVert(d.x, d.y, rectUV, color32, vh);
			vh.AddTriangle(num, idx, num2);
			vh.AddTriangle(num2, idx2, num);
		}

		private static int AddVert(float x, float y, Rect area, Color32 color32, VertexHelper vh)
		{
			vh.AddVert(uv0: new Vector2(Mathf.InverseLerp(area.xMin, area.xMax, x), Mathf.InverseLerp(area.yMin, area.yMax, y)), position: new Vector3(x, y), color: color32);
			return vh.currentVertCount - 1;
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/UIGridRenderer")]
	public class UIGridRenderer : UILineRenderer
	{
		[SerializeField]
		private int m_GridColumns = 10;

		[SerializeField]
		private int m_GridRows = 10;

		public int GridColumns
		{
			get
			{
				return m_GridColumns;
			}
			set
			{
				if (m_GridColumns != value)
				{
					m_GridColumns = value;
					SetAllDirty();
				}
			}
		}

		public int GridRows
		{
			get
			{
				return m_GridRows;
			}
			set
			{
				if (m_GridRows != value)
				{
					m_GridRows = value;
					SetAllDirty();
				}
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			relativeSize = true;
			int num = GridRows * 3 + 1;
			if (GridRows % 2 == 0)
			{
				num++;
			}
			num += GridColumns * 3 + 1;
			m_points = new Vector2[num];
			int num2 = 0;
			for (int i = 0; i < GridRows; i++)
			{
				float x = 1f;
				float x2 = 0f;
				if (i % 2 == 0)
				{
					x = 0f;
					x2 = 1f;
				}
				float y = (float)i / (float)GridRows;
				m_points[num2].x = x;
				m_points[num2].y = y;
				num2++;
				m_points[num2].x = x2;
				m_points[num2].y = y;
				num2++;
				m_points[num2].x = x2;
				m_points[num2].y = (float)(i + 1) / (float)GridRows;
				num2++;
			}
			if (GridRows % 2 == 0)
			{
				m_points[num2].x = 1f;
				m_points[num2].y = 1f;
				num2++;
			}
			m_points[num2].x = 0f;
			m_points[num2].y = 1f;
			num2++;
			for (int j = 0; j < GridColumns; j++)
			{
				float y2 = 1f;
				float y3 = 0f;
				if (j % 2 == 0)
				{
					y2 = 0f;
					y3 = 1f;
				}
				float x3 = (float)j / (float)GridColumns;
				m_points[num2].x = x3;
				m_points[num2].y = y2;
				num2++;
				m_points[num2].x = x3;
				m_points[num2].y = y3;
				num2++;
				m_points[num2].x = (float)(j + 1) / (float)GridColumns;
				m_points[num2].y = y3;
				num2++;
			}
			if (GridColumns % 2 == 0)
			{
				m_points[num2].x = 1f;
				m_points[num2].y = 1f;
			}
			else
			{
				m_points[num2].x = 1f;
				m_points[num2].y = 0f;
			}
			base.OnPopulateMesh(vh);
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/UILineRenderer")]
	[RequireComponent(typeof(RectTransform))]
	public class UILineRenderer : UIPrimitiveBase
	{
		private enum SegmentType
		{
			Start,
			Middle,
			End,
			Full
		}

		public enum JoinType
		{
			Bevel,
			Miter
		}

		public enum BezierType
		{
			None,
			Quick,
			Basic,
			Improved,
			Catenary
		}

		private const float MIN_MITER_JOIN = MathF.PI / 12f;

		private const float MIN_BEVEL_NICE_JOIN = MathF.PI / 6f;

		private static Vector2 UV_TOP_LEFT;

		private static Vector2 UV_BOTTOM_LEFT;

		private static Vector2 UV_TOP_CENTER_LEFT;

		private static Vector2 UV_TOP_CENTER_RIGHT;

		private static Vector2 UV_BOTTOM_CENTER_LEFT;

		private static Vector2 UV_BOTTOM_CENTER_RIGHT;

		private static Vector2 UV_TOP_RIGHT;

		private static Vector2 UV_BOTTOM_RIGHT;

		private static Vector2[] startUvs;

		private static Vector2[] middleUvs;

		private static Vector2[] endUvs;

		private static Vector2[] fullUvs;

		[SerializeField]
		[Tooltip("Points to draw lines between\n Can be improved using the Resolution Option")]
		internal Vector2[] m_points;

		[SerializeField]
		[Tooltip("Thickness of the line")]
		internal float lineThickness = 2f;

		[SerializeField]
		[Tooltip("Use the relative bounds of the Rect Transform (0,0 -> 0,1) or screen space coordinates")]
		internal bool relativeSize;

		[SerializeField]
		[Tooltip("Do the points identify a single line or split pairs of lines")]
		internal bool lineList;

		[SerializeField]
		[Tooltip("Add end caps to each line\nMultiple caps when used with Line List")]
		internal bool lineCaps;

		[SerializeField]
		[Tooltip("Resolution of the Bezier curve, different to line Resolution")]
		internal int bezierSegmentsPerCurve = 10;

		[Tooltip("The type of Join used between lines, Square/Mitre or Curved/Bevel")]
		public JoinType LineJoins;

		[Tooltip("Bezier method to apply to line, see docs for options\nCan't be used in conjunction with Resolution as Bezier already changes the resolution")]
		public BezierType BezierMode;

		[HideInInspector]
		public bool drivenExternally;

		public float LineThickness
		{
			get
			{
				return lineThickness;
			}
			set
			{
				lineThickness = value;
				SetAllDirty();
			}
		}

		public bool RelativeSize
		{
			get
			{
				return relativeSize;
			}
			set
			{
				relativeSize = value;
				SetAllDirty();
			}
		}

		public bool LineList
		{
			get
			{
				return lineList;
			}
			set
			{
				lineList = value;
				SetAllDirty();
			}
		}

		public bool LineCaps
		{
			get
			{
				return lineCaps;
			}
			set
			{
				lineCaps = value;
				SetAllDirty();
			}
		}

		public int BezierSegmentsPerCurve
		{
			get
			{
				return bezierSegmentsPerCurve;
			}
			set
			{
				bezierSegmentsPerCurve = value;
			}
		}

		public Vector2[] Points
		{
			get
			{
				return m_points;
			}
			set
			{
				if (m_points != value)
				{
					m_points = value;
					SetAllDirty();
				}
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			if (m_points == null)
			{
				return;
			}
			GeneratedUVs();
			Vector2[] array = m_points;
			if (BezierMode != BezierType.None && BezierMode != BezierType.Catenary && m_points.Length > 3)
			{
				BezierPath bezierPath = new BezierPath();
				bezierPath.SetControlPoints(array);
				bezierPath.SegmentsPerCurve = bezierSegmentsPerCurve;
				array = (BezierMode switch
				{
					BezierType.Basic => bezierPath.GetDrawingPoints0(), 
					BezierType.Improved => bezierPath.GetDrawingPoints1(), 
					_ => bezierPath.GetDrawingPoints2(), 
				}).ToArray();
			}
			if (BezierMode == BezierType.Catenary && m_points.Length == 2)
			{
				array = new CableCurve(array)
				{
					slack = base.Resoloution,
					steps = BezierSegmentsPerCurve
				}.Points();
			}
			if (base.ImproveResolution != ResolutionMode.None)
			{
				array = IncreaseResolution(array);
			}
			float num = ((!relativeSize) ? 1f : base.rectTransform.rect.width);
			float num2 = ((!relativeSize) ? 1f : base.rectTransform.rect.height);
			float num3 = (0f - base.rectTransform.pivot.x) * num;
			float num4 = (0f - base.rectTransform.pivot.y) * num2;
			vh.Clear();
			List<UIVertex[]> list = new List<UIVertex[]>();
			if (lineList)
			{
				for (int i = 1; i < array.Length; i += 2)
				{
					Vector2 vector = array[i - 1];
					Vector2 vector2 = array[i];
					vector = new Vector2(vector.x * num + num3, vector.y * num2 + num4);
					vector2 = new Vector2(vector2.x * num + num3, vector2.y * num2 + num4);
					if (lineCaps)
					{
						list.Add(CreateLineCap(vector, vector2, SegmentType.Start));
					}
					list.Add(CreateLineSegment(vector, vector2, SegmentType.Middle));
					if (lineCaps)
					{
						list.Add(CreateLineCap(vector, vector2, SegmentType.End));
					}
				}
			}
			else
			{
				for (int j = 1; j < array.Length; j++)
				{
					Vector2 vector3 = array[j - 1];
					Vector2 vector4 = array[j];
					vector3 = new Vector2(vector3.x * num + num3, vector3.y * num2 + num4);
					vector4 = new Vector2(vector4.x * num + num3, vector4.y * num2 + num4);
					if (lineCaps && j == 1)
					{
						list.Add(CreateLineCap(vector3, vector4, SegmentType.Start));
					}
					list.Add(CreateLineSegment(vector3, vector4, SegmentType.Middle));
					if (lineCaps && j == array.Length - 1)
					{
						list.Add(CreateLineCap(vector3, vector4, SegmentType.End));
					}
				}
			}
			for (int k = 0; k < list.Count; k++)
			{
				if (!lineList && k < list.Count - 1)
				{
					Vector3 vector5 = list[k][1].position - list[k][2].position;
					Vector3 vector6 = list[k + 1][2].position - list[k + 1][1].position;
					float num5 = Vector2.Angle((Vector2)vector5, (Vector2)vector6) * (MathF.PI / 180f);
					float num6 = Mathf.Sign(Vector3.Cross(vector5.normalized, vector6.normalized).z);
					float num7 = lineThickness / (2f * Mathf.Tan(num5 / 2f));
					Vector3 position = list[k][2].position - vector5.normalized * num7 * num6;
					Vector3 position2 = list[k][3].position + vector5.normalized * num7 * num6;
					JoinType joinType = LineJoins;
					if (joinType == JoinType.Miter)
					{
						if (num7 < vector5.magnitude / 2f && num7 < vector6.magnitude / 2f && num5 > MathF.PI / 12f)
						{
							list[k][2].position = position;
							list[k][3].position = position2;
							list[k + 1][0].position = position2;
							list[k + 1][1].position = position;
						}
						else
						{
							joinType = JoinType.Bevel;
						}
					}
					if (joinType == JoinType.Bevel)
					{
						if (num7 < vector5.magnitude / 2f && num7 < vector6.magnitude / 2f && num5 > MathF.PI / 6f)
						{
							if (num6 < 0f)
							{
								list[k][2].position = position;
								list[k + 1][1].position = position;
							}
							else
							{
								list[k][3].position = position2;
								list[k + 1][0].position = position2;
							}
						}
						UIVertex[] verts = new UIVertex[4]
						{
							list[k][2],
							list[k][3],
							list[k + 1][0],
							list[k + 1][1]
						};
						vh.AddUIVertexQuad(verts);
					}
				}
				vh.AddUIVertexQuad(list[k]);
			}
			if (vh.currentVertCount > 64000)
			{
				Debug.LogError("Max Verticies size is 64000, current mesh vertcies count is [" + vh.currentVertCount + "] - Cannot Draw");
				vh.Clear();
			}
		}

		private UIVertex[] CreateLineCap(Vector2 start, Vector2 end, SegmentType type)
		{
			switch (type)
			{
			case SegmentType.Start:
			{
				Vector2 start2 = start - (end - start).normalized * lineThickness / 2f;
				return CreateLineSegment(start2, start, SegmentType.Start);
			}
			case SegmentType.End:
			{
				Vector2 end2 = end + (end - start).normalized * lineThickness / 2f;
				return CreateLineSegment(end, end2, SegmentType.End);
			}
			default:
				Debug.LogError("Bad SegmentType passed in to CreateLineCap. Must be SegmentType.Start or SegmentType.End");
				return null;
			}
		}

		private UIVertex[] CreateLineSegment(Vector2 start, Vector2 end, SegmentType type)
		{
			Vector2 vector = new Vector2(start.y - end.y, end.x - start.x).normalized * lineThickness / 2f;
			Vector2 vector2 = start - vector;
			Vector2 vector3 = start + vector;
			Vector2 vector4 = end + vector;
			Vector2 vector5 = end - vector;
			return type switch
			{
				SegmentType.Start => SetVbo(new Vector2[4] { vector2, vector3, vector4, vector5 }, startUvs), 
				SegmentType.End => SetVbo(new Vector2[4] { vector2, vector3, vector4, vector5 }, endUvs), 
				SegmentType.Full => SetVbo(new Vector2[4] { vector2, vector3, vector4, vector5 }, fullUvs), 
				_ => SetVbo(new Vector2[4] { vector2, vector3, vector4, vector5 }, middleUvs), 
			};
		}

		protected override void GeneratedUVs()
		{
			if (base.activeSprite != null)
			{
				Vector4 outerUV = DataUtility.GetOuterUV(base.activeSprite);
				Vector4 innerUV = DataUtility.GetInnerUV(base.activeSprite);
				UV_TOP_LEFT = new Vector2(outerUV.x, outerUV.y);
				UV_BOTTOM_LEFT = new Vector2(outerUV.x, outerUV.w);
				UV_TOP_CENTER_LEFT = new Vector2(innerUV.x, innerUV.y);
				UV_TOP_CENTER_RIGHT = new Vector2(innerUV.z, innerUV.y);
				UV_BOTTOM_CENTER_LEFT = new Vector2(innerUV.x, innerUV.w);
				UV_BOTTOM_CENTER_RIGHT = new Vector2(innerUV.z, innerUV.w);
				UV_TOP_RIGHT = new Vector2(outerUV.z, outerUV.y);
				UV_BOTTOM_RIGHT = new Vector2(outerUV.z, outerUV.w);
			}
			else
			{
				UV_TOP_LEFT = Vector2.zero;
				UV_BOTTOM_LEFT = new Vector2(0f, 1f);
				UV_TOP_CENTER_LEFT = new Vector2(0.5f, 0f);
				UV_TOP_CENTER_RIGHT = new Vector2(0.5f, 0f);
				UV_BOTTOM_CENTER_LEFT = new Vector2(0.5f, 1f);
				UV_BOTTOM_CENTER_RIGHT = new Vector2(0.5f, 1f);
				UV_TOP_RIGHT = new Vector2(1f, 0f);
				UV_BOTTOM_RIGHT = Vector2.one;
			}
			startUvs = new Vector2[4] { UV_TOP_LEFT, UV_BOTTOM_LEFT, UV_BOTTOM_CENTER_LEFT, UV_TOP_CENTER_LEFT };
			middleUvs = new Vector2[4] { UV_TOP_CENTER_LEFT, UV_BOTTOM_CENTER_LEFT, UV_BOTTOM_CENTER_RIGHT, UV_TOP_CENTER_RIGHT };
			endUvs = new Vector2[4] { UV_TOP_CENTER_RIGHT, UV_BOTTOM_CENTER_RIGHT, UV_BOTTOM_RIGHT, UV_TOP_RIGHT };
			fullUvs = new Vector2[4] { UV_TOP_LEFT, UV_BOTTOM_LEFT, UV_BOTTOM_RIGHT, UV_TOP_RIGHT };
		}

		protected override void ResolutionToNativeSize(float distance)
		{
			if (base.UseNativeSize)
			{
				m_Resolution = distance / (base.activeSprite.rect.width / base.pixelsPerUnit);
				lineThickness = base.activeSprite.rect.height / base.pixelsPerUnit;
			}
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/UILineTextureRenderer")]
	public class UILineTextureRenderer : UIPrimitiveBase
	{
		[SerializeField]
		private Rect m_UVRect = new Rect(0f, 0f, 1f, 1f);

		[SerializeField]
		private Vector2[] m_points;

		public float LineThickness = 2f;

		public bool UseMargins;

		public Vector2 Margin;

		public bool relativeSize;

		public Rect uvRect
		{
			get
			{
				return m_UVRect;
			}
			set
			{
				if (!(m_UVRect == value))
				{
					m_UVRect = value;
					SetVerticesDirty();
				}
			}
		}

		public Vector2[] Points
		{
			get
			{
				return m_points;
			}
			set
			{
				if (m_points != value)
				{
					m_points = value;
					SetAllDirty();
				}
			}
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			if (m_points == null || m_points.Length < 2)
			{
				m_points = new Vector2[2]
				{
					new Vector2(0f, 0f),
					new Vector2(1f, 1f)
				};
			}
			int num = 24;
			float num2 = base.rectTransform.rect.width;
			float num3 = base.rectTransform.rect.height;
			float num4 = (0f - base.rectTransform.pivot.x) * base.rectTransform.rect.width;
			float num5 = (0f - base.rectTransform.pivot.y) * base.rectTransform.rect.height;
			if (!relativeSize)
			{
				num2 = 1f;
				num3 = 1f;
			}
			List<Vector2> list = new List<Vector2>();
			list.Add(m_points[0]);
			Vector2 item = m_points[0] + (m_points[1] - m_points[0]).normalized * num;
			list.Add(item);
			for (int i = 1; i < m_points.Length - 1; i++)
			{
				list.Add(m_points[i]);
			}
			item = m_points[m_points.Length - 1] - (m_points[m_points.Length - 1] - m_points[m_points.Length - 2]).normalized * num;
			list.Add(item);
			list.Add(m_points[m_points.Length - 1]);
			Vector2[] array = list.ToArray();
			if (UseMargins)
			{
				num2 -= Margin.x;
				num3 -= Margin.y;
				num4 += Margin.x / 2f;
				num5 += Margin.y / 2f;
			}
			vh.Clear();
			Vector2 vector = Vector2.zero;
			Vector2 vector2 = Vector2.zero;
			for (int j = 1; j < array.Length; j++)
			{
				Vector2 vector3 = array[j - 1];
				Vector2 vector4 = array[j];
				vector3 = new Vector2(vector3.x * num2 + num4, vector3.y * num3 + num5);
				vector4 = new Vector2(vector4.x * num2 + num4, vector4.y * num3 + num5);
				float z = Mathf.Atan2(vector4.y - vector3.y, vector4.x - vector3.x) * 180f / MathF.PI;
				Vector2 vector5 = vector3 + new Vector2(0f, (0f - LineThickness) / 2f);
				Vector2 vector6 = vector3 + new Vector2(0f, LineThickness / 2f);
				Vector2 vector7 = vector4 + new Vector2(0f, LineThickness / 2f);
				Vector2 vector8 = vector4 + new Vector2(0f, (0f - LineThickness) / 2f);
				vector5 = RotatePointAroundPivot(vector5, vector3, new Vector3(0f, 0f, z));
				vector6 = RotatePointAroundPivot(vector6, vector3, new Vector3(0f, 0f, z));
				vector7 = RotatePointAroundPivot(vector7, vector4, new Vector3(0f, 0f, z));
				vector8 = RotatePointAroundPivot(vector8, vector4, new Vector3(0f, 0f, z));
				Vector2 zero = Vector2.zero;
				Vector2 vector9 = new Vector2(0f, 1f);
				Vector2 vector10 = new Vector2(0.5f, 0f);
				Vector2 vector11 = new Vector2(0.5f, 1f);
				Vector2 vector12 = new Vector2(1f, 0f);
				Vector2 vector13 = new Vector2(1f, 1f);
				Vector2[] uvs = new Vector2[4] { vector10, vector11, vector11, vector10 };
				if (j > 1)
				{
					vh.AddUIVertexQuad(SetVbo(new Vector2[4] { vector, vector2, vector5, vector6 }, uvs));
				}
				if (j == 1)
				{
					uvs = new Vector2[4] { zero, vector9, vector11, vector10 };
				}
				else if (j == array.Length - 1)
				{
					uvs = new Vector2[4] { vector10, vector11, vector13, vector12 };
				}
				vh.AddUIVertexQuad(SetVbo(new Vector2[4] { vector5, vector6, vector7, vector8 }, uvs));
				vector = vector7;
				vector2 = vector8;
			}
		}

		public Vector3 RotatePointAroundPivot(Vector3 point, Vector3 pivot, Vector3 angles)
		{
			Vector3 vector = point - pivot;
			vector = Quaternion.Euler(angles) * vector;
			point = vector + pivot;
			return point;
		}
	}
	[AddComponentMenu("UI/Extensions/Primitives/UI Polygon")]
	public class UIPolygon : UIPrimitiveBase
	{
		public bool fill = true;

		public float thickness = 5f;

		[Range(3f, 360f)]
		public int sides = 3;

		[Range(0f, 360f)]
		public float rotation;

		[Range(0f, 1f)]
		public float[] VerticesDistances = new float[3];

		private float size;

		public void DrawPolygon(int _sides)
		{
			sides = _sides;
			VerticesDistances = new float[_sides + 1];
			for (int i = 0; i < _sides; i++)
			{
				VerticesDistances[i] = 1f;
			}
			rotation = 0f;
			SetAllDirty();
		}

		public void DrawPolygon(int _sides, float[] _VerticesDistances)
		{
			sides = _sides;
			VerticesDistances = _VerticesDistances;
			rotation = 0f;
			SetAllDirty();
		}

		public void DrawPolygon(int _sides, float[] _VerticesDistances, float _rotation)
		{
			sides = _sides;
			VerticesDistances = _VerticesDistances;
			rotation = _rotation;
			SetAllDirty();
		}

		private void Update()
		{
			size = base.rectTransform.rect.width;
			if (base.rectTransform.rect.width > base.rectTransform.rect.height)
			{
				size = base.rectTransform.rect.height;
			}
			else
			{
				size = base.rectTransform.rect.width;
			}
			thickness = Mathf.Clamp(thickness, 0f, size / 2f);
		}

		protected override void OnPopulateMesh(VertexHelper vh)
		{
			vh.Clear();
			Vector2 vector = Vector2.zero;
			Vector2 vector2 = Vector2.zero;
			Vector2 vector3 = new Vector2(0f, 0f);
			Vector2 vector4 = new Vector2(0f, 1f);
			Vector2 vector5 = new Vector2(1f, 1f);
			Vector2 vector6 = new Vector2(1f, 0f);
			float num = 360f / (float)sides;
			int num2 = sides + 1;
			if (VerticesDistances.Length != num2)
			{
				VerticesDistances = new float[num2];
				for (int i = 0; i < num2 - 1; i++)
				{
					VerticesDistances[i] = 1f;
				}
			}
			VerticesDistances[num2 - 1] = VerticesDistances[0];
			for (int j = 0; j < num2; j++)
			{
				float num3 = (0f - base.rectTransform.pivot.x) * size * VerticesDistances[j];
				float num4 = (0f - base.rectTransform.pivot.x) * size * VerticesDistances[j] + thickness;
				float f = MathF.PI / 180f * ((float)j * num + rotation);
				float num5 = Mathf.Cos(f);
				float num6 = Mathf.Sin(f);
				vector3 = new Vector2(0f, 1f);
				vector4 = new Vector2(1f, 1f);
				vector5 = new Vector2(1f, 0f);
				vector6 = new Vector2(0f, 0f);
				Vector2 vector7 = vector;
				Vector2 vector8 = new Vector2(num3 * num5, num3 * num6);
				Vector2 vector9;
				Vector2 vector10;
				if (fill)
				{
					vector9 = Vector2.zero;
					vector10 = Vector2.zero;
				}
				else
				{
					vector9 = new Vector2(num4 * num5, num4 * num6);
					vector10 = vector2;
				}
				vector = vector8;
				vector2 = vector9;
				vh.AddUIVertexQuad(SetVbo(new Vector2[4] { vector7, vector8, vector9, vector10 }, new Vector2[4] { vector3, vector4, vector5, vector6 }));
			}
		}
	}
	public enum ResolutionMode
	{
		None,
		PerSegment,
		PerLine
	}
	public class UIPrimitiveBase : MaskableGraphic, ILayoutElement, ICanvasRaycastFilter
	{
		protected static Material s_ETC1DefaultUI;

		[SerializeField]
		private Sprite m_Sprite;

		[NonSerialized]
		private Sprite m_OverrideSprite;

		internal float m_EventAlphaThreshold = 1f;

		[SerializeField]
		private ResolutionMode m_improveResolution;

		[SerializeField]
		protected float m_Resolution;

		[SerializeField]
		private bool m_useNativeSize;

		public Sprite sprite
		{
			get
			{
				return m_Sprite;
			}
			set
			{
				if (SetPropertyUtility.SetClass(ref m_Sprite, value))
				{
					GeneratedUVs();
