		protected UIPrimitiveBase()
		{
			base.useLegacyMeshGeneration = false;
		}

		protected UIVertex[] SetVbo(Vector2[] vertices, Vector2[] uvs)
		{
			UIVertex[] array = new UIVertex[4];
			for (int i = 0; i < vertices.Length; i++)
			{
				UIVertex simpleVert = UIVertex.simpleVert;
				simpleVert.color = color;
				simpleVert.position = vertices[i];
				simpleVert.uv0 = uvs[i];
				array[i] = simpleVert;
			}
			return array;
		}

		protected Vector2[] IncreaseResolution(Vector2[] input)
		{
			List<Vector2> list = new List<Vector2>();
			switch (ImproveResolution)
			{
			case ResolutionMode.PerLine:
			{
				float num3 = 0f;
				float num = 0f;
				for (int j = 0; j < input.Length - 1; j++)
				{
					num3 += Vector2.Distance(input[j], input[j + 1]);
				}
				ResolutionToNativeSize(num3);
				num = num3 / m_Resolution;
				int num4 = 0;
				for (int k = 0; k < input.Length - 1; k++)
				{
					Vector2 vector3 = input[k];
					list.Add(vector3);
					Vector2 vector4 = input[k + 1];
					float num5 = Vector2.Distance(vector3, vector4) / num;
					float num6 = 1f / num5;
					for (int l = 0; (float)l < num5; l++)
					{
						list.Add(Vector2.Lerp(vector3, vector4, (float)l * num6));
						num4++;
					}
					list.Add(vector4);
				}
				break;
			}
			case ResolutionMode.PerSegment:
			{
				for (int i = 0; i < input.Length - 1; i++)
				{
					Vector2 vector = input[i];
					list.Add(vector);
					Vector2 vector2 = input[i + 1];
					ResolutionToNativeSize(Vector2.Distance(vector, vector2));
					float num = 1f / m_Resolution;
					for (float num2 = 1f; num2 < m_Resolution; num2 += 1f)
					{
						list.Add(Vector2.Lerp(vector, vector2, num * num2));
					}
					list.Add(vector2);
				}
				break;
			}
			}
			return list.ToArray();
		}

		protected virtual void GeneratedUVs()
		{
		}

		protected virtual void ResolutionToNativeSize(float distance)
		{
		}

		public virtual void CalculateLayoutInputHorizontal()
		{
		}

		public virtual void CalculateLayoutInputVertical()
		{
		}

		public virtual bool IsRaycastLocationValid(Vector2 screenPoint, Camera eventCamera)
		{
			if (m_EventAlphaThreshold >= 1f)
			{
				return true;
			}
			Sprite sprite = overrideSprite;
			if (sprite == null)
			{
				return true;
			}
			RectTransformUtility.ScreenPointToLocalPointInRectangle(base.rectTransform, screenPoint, eventCamera, out var localPoint);
			Rect pixelAdjustedRect = GetPixelAdjustedRect();
			localPoint.x += base.rectTransform.pivot.x * pixelAdjustedRect.width;
			localPoint.y += base.rectTransform.pivot.y * pixelAdjustedRect.height;
			localPoint = MapCoordinate(localPoint, pixelAdjustedRect);
			Rect textureRect = sprite.textureRect;
			Vector2 vector = new Vector2(localPoint.x / textureRect.width, localPoint.y / textureRect.height);
			float u = Mathf.Lerp(textureRect.x, textureRect.xMax, vector.x) / (float)sprite.texture.width;
			float v = Mathf.Lerp(textureRect.y, textureRect.yMax, vector.y) / (float)sprite.texture.height;
			try
			{
				return sprite.texture.GetPixelBilinear(u, v).a >= m_EventAlphaThreshold;
			}
			catch (UnityException ex)
			{
				Debug.LogError("Using clickAlphaThreshold lower than 1 on Image whose sprite texture cannot be read. " + ex.Message + " Also make sure to disable sprite packing for this sprite.", this);
				return true;
			}
		}

		private Vector2 MapCoordinate(Vector2 local, Rect rect)
		{
			_ = sprite.rect;
			return new Vector2(local.x * rect.width, local.y * rect.height);
		}

		private Vector4 GetAdjustedBorders(Vector4 border, Rect rect)
		{
			for (int i = 0; i <= 1; i++)
			{
				float num = border[i] + border[i + 2];
				if (rect.size[i] < num && num != 0f)
				{
					float num2 = rect.size[i] / num;
					border[i] *= num2;
					border[i + 2] *= num2;
				}
			}
			return border;
		}

		protected override void OnEnable()
		{
			base.OnEnable();
			SetAllDirty();
		}
	}
	public enum NavigationMode
	{
		Auto,
		Manual
	}
	[RequireComponent(typeof(EventSystem))]
	[AddComponentMenu("Event/Extensions/Tab Navigation Helper")]
	public class TabNavigationHelper : MonoBehaviour
	{
		private EventSystem _system;

		private Selectable StartingObject;

		private Selectable LastObject;

		[Tooltip("The path to take when user is tabbing through ui components.")]
		public Selectable[] NavigationPath;

		[Tooltip("Use the default Unity navigation system or a manual fixed order using Navigation Path")]
		public NavigationMode NavigationMode;

		[Tooltip("If True, this will loop the tab order from last to first automatically")]
		public bool CircularNavigation;

		private void Start()
		{
			_system = GetComponent<EventSystem>();
			if (_system == null)
			{
				Debug.LogError("Needs to be attached to the Event System component in the scene");
			}
			if (NavigationMode == NavigationMode.Manual && NavigationPath.Length != 0)
			{
				StartingObject = NavigationPath[0].gameObject.GetComponent<Selectable>();
			}
			if (StartingObject == null && CircularNavigation)
			{
				SelectDefaultObject(out StartingObject);
			}
		}

		public void Update()
		{
			Selectable next = null;
			if (LastObject == null && _system.currentSelectedGameObject != null)
			{
				next = _system.currentSelectedGameObject.GetComponent<Selectable>().FindSelectableOnDown();
				while (next != null)
				{
					LastObject = next;
					next = next.FindSelectableOnDown();
				}
			}
			if (Input.GetKeyDown(KeyCode.Tab) && Input.GetKey(KeyCode.LeftShift))
			{
				if (NavigationMode == NavigationMode.Manual && NavigationPath.Length != 0)
				{
					for (int num = NavigationPath.Length - 1; num >= 0; num--)
					{
						if (!(_system.currentSelectedGameObject != NavigationPath[num].gameObject))
						{
							next = ((num == 0) ? NavigationPath[NavigationPath.Length - 1] : NavigationPath[num - 1]);
							break;
						}
					}
				}
				else if (_system.currentSelectedGameObject != null)
				{
					next = _system.currentSelectedGameObject.GetComponent<Selectable>().FindSelectableOnUp();
					if (next == null && CircularNavigation)
					{
						next = LastObject;
					}
				}
				else
				{
					SelectDefaultObject(out next);
				}
			}
			else if (Input.GetKeyDown(KeyCode.Tab))
			{
				if (NavigationMode == NavigationMode.Manual && NavigationPath.Length != 0)
				{
					for (int i = 0; i < NavigationPath.Length; i++)
					{
						if (!(_system.currentSelectedGameObject != NavigationPath[i].gameObject))
						{
							next = ((i == NavigationPath.Length - 1) ? NavigationPath[0] : NavigationPath[i + 1]);
							break;
						}
					}
				}
				else if (_system.currentSelectedGameObject != null)
				{
					next = _system.currentSelectedGameObject.GetComponent<Selectable>().FindSelectableOnDown();
					if (next == null && CircularNavigation)
					{
						next = StartingObject;
					}
				}
				else
				{
					SelectDefaultObject(out next);
				}
			}
			else if (_system.currentSelectedGameObject == null)
			{
				SelectDefaultObject(out next);
			}
			if (CircularNavigation && StartingObject == null)
			{
				StartingObject = next;
			}
			selectGameObject(next);
		}

		private void SelectDefaultObject(out Selectable next)
		{
			if ((bool)_system.firstSelectedGameObject)
			{
				next = _system.firstSelectedGameObject.GetComponent<Selectable>();
			}
			else
			{
				next = null;
			}
		}

		private void selectGameObject(Selectable selectable)
		{
			if (selectable != null)
			{
				InputField component = selectable.GetComponent<InputField>();
				if (component != null)
				{
					component.OnPointerClick(new PointerEventData(_system));
				}
				_system.SetSelectedGameObject(selectable.gameObject, new BaseEventData(_system));
			}
		}
	}
	[AddComponentMenu("UI/Extensions/Bound Tooltip/Tooltip Item")]
	public class BoundTooltipItem : MonoBehaviour
	{
		public Text TooltipText;

		public Vector3 ToolTipOffset;

		private static BoundTooltipItem instance;

		public bool IsActive => base.gameObject.activeSelf;

		public static BoundTooltipItem Instance
		{
			get
			{
				if (instance == null)
				{
					instance = Object.FindAnyObjectByType<BoundTooltipItem>();
				}
				return instance;
			}
		}

		private void Awake()
		{
			instance = this;
			if (!TooltipText)
			{
				TooltipText = GetComponentInChildren<Text>();
			}
			HideTooltip();
