	[AddComponentMenu("UI/Extensions/Bound Tooltip/Tooltip Trigger")]
	public class BoundTooltipTrigger : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler, ISelectHandler, IDeselectHandler
	{
		[TextArea]
		public string text;

		public bool useMousePosition;

		public Vector3 offset;

		public void OnPointerEnter(PointerEventData eventData)
		{
			if (useMousePosition)
			{
				StartHover(new Vector3(eventData.position.x, eventData.position.y, 0f));
			}
			else
			{
				StartHover(base.transform.position + offset);
			}
		}

		public void OnSelect(BaseEventData eventData)
		{
			StartHover(base.transform.position);
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			StopHover();
		}

		public void OnDeselect(BaseEventData eventData)
		{
			StopHover();
		}

		private void StartHover(Vector3 position)
		{
			BoundTooltipItem.Instance.ShowTooltip(text, position);
		}

		private void StopHover()
		{
			BoundTooltipItem.Instance.HideTooltip();
		}
	}
	[AddComponentMenu("UI/Extensions/HoverTooltip")]
	public class HoverTooltip : MonoBehaviour
	{
		public int horizontalPadding;

		public int verticalPadding;

		public Text thisText;

		public HorizontalLayoutGroup hlG;

		public RectTransform bgImage;

		private Image bgImageSource;

		private bool firstUpdate;

		private bool inside;

		private RenderMode GUIMode;

		private Camera GUICamera;

		private Vector3 lowerLeft;

		private Vector3 upperRight;

		private float currentYScaleFactor;

		private float currentXScaleFactor;

		private float defaultYOffset;

		private float defaultXOffset;

		private float tooltipRealHeight;

		private float tooltipRealWidth;

		private void Start()
		{
			GUICamera = GameObject.Find("GUICamera").GetComponent<Camera>();
			GUIMode = base.transform.parent.parent.GetComponent<Canvas>().renderMode;
			bgImageSource = bgImage.GetComponent<Image>();
			inside = false;
			HideTooltipVisibility();
			base.transform.parent.gameObject.SetActive(value: false);
		}

		public void SetTooltip(string text)
		{
			NewTooltip();
			thisText.text = text;
			OnScreenSpaceCamera();
		}

		public void SetTooltip(string[] texts)
		{
			NewTooltip();
			string text = "";
			int num = 0;
			foreach (string text2 in texts)
			{
				text = ((num != 0) ? (text + "\n" + text2) : (text + text2));
				num++;
			}
			thisText.text = text;
			OnScreenSpaceCamera();
		}

		public void SetTooltip(string text, bool test)
		{
			NewTooltip();
			thisText.text = text;
			OnScreenSpaceCamera();
		}

		public void OnScreenSpaceCamera()
		{
			Vector3 position = GUICamera.ScreenToViewportPoint(Input.mousePosition);
			float num = 0f;
			float num2 = 0f;
			float num3 = GUICamera.ViewportToScreenPoint(position).x + tooltipRealWidth * bgImage.pivot.x;
			if (num3 > upperRight.x)
			{
				float num4 = upperRight.x - num3;
				num2 = ((!((double)num4 > (double)defaultXOffset * 0.75)) ? (defaultXOffset - tooltipRealWidth * 2f) : num4);
				Vector3 position2 = new Vector3(GUICamera.ViewportToScreenPoint(position).x + num2, 0f, 0f);
				position.x = GUICamera.ScreenToViewportPoint(position2).x;
			}
			num3 = GUICamera.ViewportToScreenPoint(position).x - tooltipRealWidth * bgImage.pivot.x;
			if (num3 < lowerLeft.x)
			{
				float num5 = lowerLeft.x - num3;
				num2 = ((!((double)num5 < (double)defaultXOffset * 0.75 - (double)tooltipRealWidth)) ? (tooltipRealWidth * 2f) : (0f - num5));
				Vector3 position3 = new Vector3(GUICamera.ViewportToScreenPoint(position).x - num2, 0f, 0f);
				position.x = GUICamera.ScreenToViewportPoint(position3).x;
			}
			num3 = GUICamera.ViewportToScreenPoint(position).y - (bgImage.sizeDelta.y * currentYScaleFactor * bgImage.pivot.y - tooltipRealHeight);
			if (num3 > upperRight.y)
			{
				float num6 = upperRight.y - num3;
				num = bgImage.sizeDelta.y * currentYScaleFactor * bgImage.pivot.y;
				num = ((!((double)num6 > (double)defaultYOffset * 0.75)) ? (defaultYOffset - tooltipRealHeight * 2f) : num6);
				Vector3 position4 = new Vector3(position.x, GUICamera.ViewportToScreenPoint(position).y + num, 0f);
				position.y = GUICamera.ScreenToViewportPoint(position4).y;
			}
			num3 = GUICamera.ViewportToScreenPoint(position).y - bgImage.sizeDelta.y * currentYScaleFactor * bgImage.pivot.y;
			if (num3 < lowerLeft.y)
			{
				float num7 = lowerLeft.y - num3;
				num = bgImage.sizeDelta.y * currentYScaleFactor * bgImage.pivot.y;
				num = ((!((double)num7 < (double)defaultYOffset * 0.75 - (double)tooltipRealHeight)) ? (tooltipRealHeight * 2f) : num7);
				Vector3 position5 = new Vector3(position.x, GUICamera.ViewportToScreenPoint(position).y + num, 0f);
				position.y = GUICamera.ScreenToViewportPoint(position5).y;
			}
			base.transform.parent.transform.position = new Vector3(GUICamera.ViewportToWorldPoint(position).x, GUICamera.ViewportToWorldPoint(position).y, 0f);
			base.transform.parent.gameObject.SetActive(value: true);
			inside = true;
		}

		public void HideTooltip()
		{
			if (GUIMode == RenderMode.ScreenSpaceCamera && this != null)
			{
				base.transform.parent.gameObject.SetActive(value: false);
				inside = false;
				HideTooltipVisibility();
			}
		}

		private void Update()
		{
			LayoutInit();
			if (inside && GUIMode == RenderMode.ScreenSpaceCamera)
			{
				OnScreenSpaceCamera();
			}
		}

		private void LayoutInit()
		{
			if (firstUpdate)
			{
				firstUpdate = false;
				bgImage.sizeDelta = new Vector2(hlG.preferredWidth + (float)horizontalPadding, hlG.preferredHeight + (float)verticalPadding);
				defaultYOffset = bgImage.sizeDelta.y * currentYScaleFactor * bgImage.pivot.y;
				defaultXOffset = bgImage.sizeDelta.x * currentXScaleFactor * bgImage.pivot.x;
				tooltipRealHeight = bgImage.sizeDelta.y * currentYScaleFactor;
				tooltipRealWidth = bgImage.sizeDelta.x * currentXScaleFactor;
				ActivateTooltipVisibility();
			}
		}

		private void NewTooltip()
		{
			firstUpdate = true;
			lowerLeft = GUICamera.ViewportToScreenPoint(new Vector3(0f, 0f, 0f));
			upperRight = GUICamera.ViewportToScreenPoint(new Vector3(1f, 1f, 0f));
			currentYScaleFactor = (float)Screen.height / base.transform.root.GetComponent<CanvasScaler>().referenceResolution.y;
			currentXScaleFactor = (float)Screen.width / base.transform.root.GetComponent<CanvasScaler>().referenceResolution.x;
		}

		public void ActivateTooltipVisibility()
		{
			Color color = thisText.color;
			thisText.color = new Color(color.r, color.g, color.b, 1f);
			bgImageSource.color = new Color(bgImageSource.color.r, bgImageSource.color.g, bgImageSource.color.b, 0.8f);
		}

		public void HideTooltipVisibility()
		{
			Color color = thisText.color;
			thisText.color = new Color(color.r, color.g, color.b, 0f);
			bgImageSource.color = new Color(bgImageSource.color.r, bgImageSource.color.g, bgImageSource.color.b, 0f);
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/Tooltip")]
	public class ToolTip : MonoBehaviour
	{
		private Text _text;

		private RectTransform _rectTransform;

		private bool _inside;

		private float width;

		private float height;

		private float YShift;

		private float xShift;

		private RenderMode _guiMode;

		private Camera _guiCamera;

		public void Awake()
		{
			Canvas componentInParent = GetComponentInParent<Canvas>();
			_guiCamera = componentInParent.worldCamera;
			_guiMode = componentInParent.renderMode;
			_rectTransform = GetComponent<RectTransform>();
			_text = GetComponentInChildren<Text>();
			_inside = false;
			xShift = 0f;
			YShift = -30f;
			base.gameObject.SetActive(value: false);
		}

		public void SetTooltip(string ttext)
		{
			if (_guiMode == RenderMode.ScreenSpaceCamera)
			{
				_text.text = ttext;
				_rectTransform.sizeDelta = new Vector2(_text.preferredWidth + 40f, _text.preferredHeight + 25f);
				OnScreenSpaceCamera();
			}
		}

		public void HideTooltip()
		{
			if (_guiMode == RenderMode.ScreenSpaceCamera)
			{
				base.gameObject.SetActive(value: false);
				_inside = false;
			}
		}

		private void FixedUpdate()
		{
			if (_inside && _guiMode == RenderMode.ScreenSpaceCamera)
			{
				OnScreenSpaceCamera();
			}
		}

		public void OnScreenSpaceCamera()
		{
			Vector3 position = _guiCamera.ScreenToViewportPoint(Input.mousePosition - new Vector3(xShift, YShift, 0f));
			Vector3 vector = _guiCamera.ViewportToWorldPoint(position);
			width = _rectTransform.sizeDelta[0];
			height = _rectTransform.sizeDelta[1];
			Vector3 vector2 = _guiCamera.ViewportToWorldPoint(new Vector3(0f, 0f, 0f));
			Vector3 vector3 = _guiCamera.ViewportToWorldPoint(new Vector3(1f, 1f, 0f));
			float num = vector.x + width / 2f;
			if (num > vector3.x)
			{
				Vector3 vector4 = new Vector3(num - vector3.x, 0f, 0f);
				Vector3 position2 = new Vector3(vector.x - vector4.x, position.y, 0f);
				position.x = _guiCamera.WorldToViewportPoint(position2).x;
			}
			num = vector.x - width / 2f;
			if (num < vector2.x)
			{
				Vector3 vector5 = new Vector3(vector2.x - num, 0f, 0f);
				Vector3 position3 = new Vector3(vector.x + vector5.x, position.y, 0f);
				position.x = _guiCamera.WorldToViewportPoint(position3).x;
			}
			num = vector.y + height / 2f;
			if (num > vector3.y)
			{
				Vector3 vector6 = new Vector3(0f, 35f + height / 2f, 0f);
				Vector3 position4 = new Vector3(position.x, vector.y - vector6.y, 0f);
				position.y = _guiCamera.WorldToViewportPoint(position4).y;
			}
			num = vector.y - height / 2f;
			if (num < vector2.y)
			{
				Vector3 vector7 = new Vector3(0f, 35f + height / 2f, 0f);
				Vector3 position5 = new Vector3(position.x, vector.y + vector7.y, 0f);
				position.y = _guiCamera.WorldToViewportPoint(position5).y;
			}
			base.transform.position = new Vector3(vector.x, vector.y, 0f);
			base.gameObject.SetActive(value: true);
			_inside = true;
		}
	}
	[RequireComponent(typeof(RectTransform))]
	[AddComponentMenu("UI/Extensions/UI Window Base")]
	public class UIWindowBase : MonoBehaviour, IBeginDragHandler, IEventSystemHandler, IDragHandler, IEndDragHandler
	{
		private RectTransform m_transform;

		private bool _isDragging;

		public static bool ResetCoords;

		private Vector3 m_originalCoods = Vector3.zero;

		private Canvas m_canvas;

		private RectTransform m_canvasRectTransform;

		public int KeepWindowInCanvas = 5;

		private void Start()
		{
			m_transform = GetComponent<RectTransform>();
			m_originalCoods = m_transform.position;
			m_canvas = GetComponentInParent<Canvas>();
			m_canvasRectTransform = m_canvas.GetComponent<RectTransform>();
		}

		private void Update()
		{
			if (ResetCoords)
			{
				resetCoordinatePosition();
			}
		}

		public void OnDrag(PointerEventData eventData)
		{
			if (_isDragging)
			{
				Vector3 vector = ScreenToCanvas(eventData.position) - ScreenToCanvas(eventData.position - eventData.delta);
				m_transform.localPosition += vector;
			}
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			if (!(eventData.pointerCurrentRaycast.gameObject == null) && eventData.pointerCurrentRaycast.gameObject.name == base.name)
			{
				_isDragging = true;
			}
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			_isDragging = false;
		}

		private void resetCoordinatePosition()
		{
			m_transform.position = m_originalCoods;
			ResetCoords = false;
		}

		private Vector3 ScreenToCanvas(Vector3 screenPosition)
		{
			Vector2 sizeDelta = m_canvasRectTransform.sizeDelta;
			Vector3 result;
			Vector2 vector;
			Vector2 vector2;
			if (m_canvas.renderMode == RenderMode.ScreenSpaceOverlay || (m_canvas.renderMode == RenderMode.ScreenSpaceCamera && m_canvas.worldCamera == null))
			{
				result = screenPosition;
				vector = Vector2.zero;
				vector2 = sizeDelta;
			}
			else
			{
				Ray ray = m_canvas.worldCamera.ScreenPointToRay(screenPosition);
				if (!new Plane(m_canvasRectTransform.forward, m_canvasRectTransform.position).Raycast(ray, out float enter))
				{
					throw new Exception("Is it practically possible?");
				}
				Vector3 position = ray.origin + ray.direction * enter;
				result = m_canvasRectTransform.InverseTransformPoint(position);
				vector = -Vector2.Scale(sizeDelta, m_canvasRectTransform.pivot);
				vector2 = Vector2.Scale(sizeDelta, Vector2.one - m_canvasRectTransform.pivot);
			}
			result.x = Mathf.Clamp(result.x, vector.x + (float)KeepWindowInCanvas, vector2.x - (float)KeepWindowInCanvas);
			result.y = Mathf.Clamp(result.y, vector.y + (float)KeepWindowInCanvas, vector2.y - (float)KeepWindowInCanvas);
			return result;
		}
	}
	public class BezierPath
	{
		public int SegmentsPerCurve = 10;

		public float MINIMUM_SQR_DISTANCE = 0.01f;

		public float DIVISION_THRESHOLD = -0.99f;

		private List<Vector2> controlPoints;

		private int curveCount;

		public BezierPath()
		{
			controlPoints = new List<Vector2>();
		}

		public void SetControlPoints(List<Vector2> newControlPoints)
		{
			controlPoints.Clear();
			controlPoints.AddRange(newControlPoints);
			curveCount = (controlPoints.Count - 1) / 3;
		}

		public void SetControlPoints(Vector2[] newControlPoints)
		{
			controlPoints.Clear();
			controlPoints.AddRange(newControlPoints);
			curveCount = (controlPoints.Count - 1) / 3;
		}

		public List<Vector2> GetControlPoints()
		{
			return controlPoints;
		}

		public void Interpolate(List<Vector2> segmentPoints, float scale)
		{
			controlPoints.Clear();
			if (segmentPoints.Count < 2)
			{
				return;
			}
			for (int i = 0; i < segmentPoints.Count; i++)
			{
				if (i == 0)
				{
					Vector2 vector = segmentPoints[i];
					Vector2 vector2 = segmentPoints[i + 1] - vector;
					Vector2 item = vector + scale * vector2;
					controlPoints.Add(vector);
					controlPoints.Add(item);
				}
				else if (i == segmentPoints.Count - 1)
				{
					Vector2 vector3 = segmentPoints[i - 1];
					Vector2 vector4 = segmentPoints[i];
					Vector2 vector5 = vector4 - vector3;
					Vector2 item2 = vector4 - scale * vector5;
					controlPoints.Add(item2);
					controlPoints.Add(vector4);
				}
				else
				{
					Vector2 vector6 = segmentPoints[i - 1];
					Vector2 vector7 = segmentPoints[i];
					Vector2 vector8 = segmentPoints[i + 1];
					Vector2 normalized = (vector8 - vector6).normalized;
					Vector2 item3 = vector7 - scale * normalized * (vector7 - vector6).magnitude;
					Vector2 item4 = vector7 + scale * normalized * (vector8 - vector7).magnitude;
					controlPoints.Add(item3);
					controlPoints.Add(vector7);
					controlPoints.Add(item4);
				}
			}
			curveCount = (controlPoints.Count - 1) / 3;
		}

		public void SamplePoints(List<Vector2> sourcePoints, float minSqrDistance, float maxSqrDistance, float scale)
		{
			if (sourcePoints.Count < 2)
			{
				return;
			}
			Stack<Vector2> stack = new Stack<Vector2>();
			stack.Push(sourcePoints[0]);
			Vector2 vector = sourcePoints[1];
			int num = 2;
			for (num = 2; num < sourcePoints.Count; num++)
			{
				if ((vector - sourcePoints[num]).sqrMagnitude > minSqrDistance && (stack.Peek() - sourcePoints[num]).sqrMagnitude > maxSqrDistance)
				{
					stack.Push(vector);
				}
				vector = sourcePoints[num];
			}
			Vector2 vector2 = stack.Pop();
			Vector2 vector3 = stack.Peek();
			Vector2 normalized = (vector3 - vector).normalized;
			float magnitude = (vector - vector2).magnitude;
			float magnitude2 = (vector2 - vector3).magnitude;
			vector2 += normalized * ((magnitude2 - magnitude) / 2f);
			stack.Push(vector2);
			stack.Push(vector);
			Interpolate(new List<Vector2>(stack), scale);
		}

		public Vector2 CalculateBezierPoint(int curveIndex, float t)
		{
			int num = curveIndex * 3;
			Vector2 p = controlPoints[num];
			Vector2 p2 = controlPoints[num + 1];
			Vector2 p3 = controlPoints[num + 2];
			Vector2 p4 = controlPoints[num + 3];
			return CalculateBezierPoint(t, p, p2, p3, p4);
		}

		public List<Vector2> GetDrawingPoints0()
		{
			List<Vector2> list = new List<Vector2>();
			for (int i = 0; i < curveCount; i++)
			{
				if (i == 0)
				{
					list.Add(CalculateBezierPoint(i, 0f));
				}
				for (int j = 1; j <= SegmentsPerCurve; j++)
				{
					float t = (float)j / (float)SegmentsPerCurve;
					list.Add(CalculateBezierPoint(i, t));
				}
			}
			return list;
		}

		public List<Vector2> GetDrawingPoints1()
		{
			List<Vector2> list = new List<Vector2>();
			for (int i = 0; i < controlPoints.Count - 3; i += 3)
			{
				Vector2 p = controlPoints[i];
				Vector2 p2 = controlPoints[i + 1];
				Vector2 p3 = controlPoints[i + 2];
				Vector2 p4 = controlPoints[i + 3];
				if (i == 0)
				{
					list.Add(CalculateBezierPoint(0f, p, p2, p3, p4));
				}
				for (int j = 1; j <= SegmentsPerCurve; j++)
				{
					float t = (float)j / (float)SegmentsPerCurve;
					list.Add(CalculateBezierPoint(t, p, p2, p3, p4));
				}
			}
			return list;
		}

		public List<Vector2> GetDrawingPoints2()
		{
			List<Vector2> list = new List<Vector2>();
			for (int i = 0; i < curveCount; i++)
			{
				List<Vector2> list2 = FindDrawingPoints(i);
				if (i != 0)
				{
					list2.RemoveAt(0);
				}
				list.AddRange(list2);
			}
			return list;
		}

		private List<Vector2> FindDrawingPoints(int curveIndex)
		{
			List<Vector2> list = new List<Vector2>();
			Vector2 item = CalculateBezierPoint(curveIndex, 0f);
			Vector2 item2 = CalculateBezierPoint(curveIndex, 1f);
			list.Add(item);
			list.Add(item2);
			FindDrawingPoints(curveIndex, 0f, 1f, list, 1);
			return list;
		}

		private int FindDrawingPoints(int curveIndex, float t0, float t1, List<Vector2> pointList, int insertionIndex)
		{
			Vector2 vector = CalculateBezierPoint(curveIndex, t0);
			Vector2 vector2 = CalculateBezierPoint(curveIndex, t1);
			if ((vector - vector2).sqrMagnitude < MINIMUM_SQR_DISTANCE)
			{
				return 0;
			}
			float num = (t0 + t1) / 2f;
			Vector2 vector3 = CalculateBezierPoint(curveIndex, num);
			Vector2 normalized = (vector - vector3).normalized;
			Vector2 normalized2 = (vector2 - vector3).normalized;
			if (Vector2.Dot(normalized, normalized2) > DIVISION_THRESHOLD || Mathf.Abs(num - 0.5f) < 0.0001f)
			{
				int num2 = 0;
				num2 += FindDrawingPoints(curveIndex, t0, num, pointList, insertionIndex);
				pointList.Insert(insertionIndex + num2, vector3);
				num2++;
				return num2 + FindDrawingPoints(curveIndex, num, t1, pointList, insertionIndex + num2);
			}
			return 0;
		}

		private Vector2 CalculateBezierPoint(float t, Vector2 p0, Vector2 p1, Vector2 p2, Vector2 p3)
		{
			float num = 1f - t;
			float num2 = t * t;
			float num3 = num * num;
			float num4 = num3 * num;
			float num5 = num2 * t;
			return num4 * p0 + 3f * num3 * t * p1 + 3f * num * num2 * p2 + num5 * p3;
		}
	}
	public static class CLZF2
	{
		private static readonly uint HLOG = 14u;

		private static readonly uint HSIZE = 16384u;

		private static readonly uint MAX_LIT = 32u;

		private static readonly uint MAX_OFF = 8192u;

		private static readonly uint MAX_REF = 264u;

		private static readonly long[] HashTable = new long[HSIZE];

		public static byte[] Compress(byte[] inputBytes)
		{
			int num = inputBytes.Length * 2;
			byte[] output = new byte[num];
			int num2;
			for (num2 = lzf_compress(inputBytes, ref output); num2 == 0; num2 = lzf_compress(inputBytes, ref output))
			{
				num *= 2;
				output = new byte[num];
			}
			byte[] array = new byte[num2];
			Buffer.BlockCopy(output, 0, array, 0, num2);
			return array;
		}

		public static byte[] Decompress(byte[] inputBytes)
		{
			int num = inputBytes.Length * 2;
			byte[] output = new byte[num];
			int num2;
			for (num2 = lzf_decompress(inputBytes, ref output); num2 == 0; num2 = lzf_decompress(inputBytes, ref output))
			{
				num *= 2;
				output = new byte[num];
			}
			byte[] array = new byte[num2];
			Buffer.BlockCopy(output, 0, array, 0, num2);
			return array;
		}

		public static int lzf_compress(byte[] input, ref byte[] output)
		{
			int num = input.Length;
			int num2 = output.Length;
			Array.Clear(HashTable, 0, (int)HSIZE);
			uint num3 = 0u;
			uint num4 = 0u;
			uint num5 = (uint)((input[num3] << 8) | input[num3 + 1]);
			int num6 = 0;
			while (true)
			{
				if (num3 < num - 2)
				{
					num5 = (num5 << 8) | input[num3 + 2];
					long num7 = ((num5 ^ (num5 << 5)) >> (int)(24 - HLOG - num5 * 5)) & (HSIZE - 1);
					long num8 = HashTable[num7];
					HashTable[num7] = num3;
					long num9;
					if ((num9 = num3 - num8 - 1) < MAX_OFF && num3 + 4 < num && num8 > 0 && input[num8] == input[num3] && input[num8 + 1] == input[num3 + 1] && input[num8 + 2] == input[num3 + 2])
					{
						uint num10 = 2u;
						uint num11 = (uint)(num - (int)num3) - num10;
						num11 = ((num11 > MAX_REF) ? MAX_REF : num11);
						if (num4 + num6 + 1 + 3 >= num2)
						{
							return 0;
						}
						do
						{
							num10++;
						}
						while (num10 < num11 && input[num8 + num10] == input[num3 + num10]);
						if (num6 != 0)
						{
							output[num4++] = (byte)(num6 - 1);
							num6 = -num6;
							do
							{
								output[num4++] = input[num3 + num6];
							}
							while (++num6 != 0);
						}
						num10 -= 2;
						num3++;
						if (num10 < 7)
						{
							output[num4++] = (byte)((num9 >> 8) + (num10 << 5));
						}
						else
						{
							output[num4++] = (byte)((num9 >> 8) + 224);
							output[num4++] = (byte)(num10 - 7);
						}
						output[num4++] = (byte)num9;
						num3 += num10 - 1;
						num5 = (uint)((input[num3] << 8) | input[num3 + 1]);
						num5 = (num5 << 8) | input[num3 + 2];
						HashTable[((num5 ^ (num5 << 5)) >> (int)(24 - HLOG - num5 * 5)) & (HSIZE - 1)] = num3;
						num3++;
						num5 = (num5 << 8) | input[num3 + 2];
						HashTable[((num5 ^ (num5 << 5)) >> (int)(24 - HLOG - num5 * 5)) & (HSIZE - 1)] = num3;
						num3++;
						continue;
					}
				}
				else if (num3 == num)
				{
					break;
				}
				num6++;
				num3++;
				if (num6 == MAX_LIT)
				{
					if (num4 + 1 + MAX_LIT >= num2)
					{
						return 0;
					}
					output[num4++] = (byte)(MAX_LIT - 1);
					num6 = -num6;
					do
					{
						output[num4++] = input[num3 + num6];
					}
					while (++num6 != 0);
				}
			}
			if (num6 != 0)
			{
				if (num4 + num6 + 1 >= num2)
				{
					return 0;
				}
				output[num4++] = (byte)(num6 - 1);
				num6 = -num6;
				do
				{
					output[num4++] = input[num3 + num6];
				}
				while (++num6 != 0);
			}
			return (int)num4;
		}

		public static int lzf_decompress(byte[] input, ref byte[] output)
		{
			int num = input.Length;
			int num2 = output.Length;
			uint num3 = 0u;
			uint num4 = 0u;
			do
			{
				uint num5 = input[num3++];
				if (num5 < 32)
				{
					num5++;
					if (num4 + num5 > num2)
					{
						return 0;
					}
					do
					{
						output[num4++] = input[num3++];
					}
					while (--num5 != 0);
					continue;
				}
				uint num6 = num5 >> 5;
				int num7 = (int)(num4 - ((num5 & 0x1F) << 8) - 1);
				if (num6 == 7)
				{
					num6 += input[num3++];
				}
				num7 -= input[num3++];
				if (num4 + num6 + 2 > num2)
				{
					return 0;
				}
				if (num7 < 0)
				{
					return 0;
				}
				output[num4++] = output[num7++];
				output[num4++] = output[num7++];
				do
				{
					output[num4++] = output[num7++];
				}
				while (--num6 != 0);
			}
			while (num3 < num);
			return (int)num4;
		}
	}
	[Serializable]
	public class CableCurve
	{
		[SerializeField]
		private Vector2 m_start;

		[SerializeField]
		private Vector2 m_end;

		[SerializeField]
		private float m_slack;

		[SerializeField]
		private int m_steps;

		[SerializeField]
		private bool m_regen;

		private static Vector2[] emptyCurve = new Vector2[2]
		{
			new Vector2(0f, 0f),
			new Vector2(0f, 0f)
		};

		[SerializeField]
		private Vector2[] points;

		public bool regenPoints
		{
			get
			{
				return m_regen;
			}
			set
			{
				m_regen = value;
			}
		}

		public Vector2 start
		{
			get
			{
				return m_start;
			}
			set
			{
				if (value != m_start)
				{
					m_regen = true;
				}
				m_start = value;
			}
		}

		public Vector2 end
		{
			get
			{
				return m_end;
			}
			set
			{
				if (value != m_end)
				{
					m_regen = true;
				}
				m_end = value;
			}
		}

		public float slack
		{
			get
			{
				return m_slack;
			}
			set
			{
				if (value != m_slack)
				{
					m_regen = true;
				}
				m_slack = Mathf.Max(0f, value);
			}
		}

		public int steps
		{
			get
			{
				return m_steps;
			}
			set
			{
				if (value != m_steps)
				{
					m_regen = true;
				}
				m_steps = Mathf.Max(2, value);
			}
		}

		public Vector2 midPoint
		{
			get
			{
				Vector2 result = Vector2.zero;
				if (m_steps == 2)
				{
					return (points[0] + points[1]) * 0.5f;
				}
				if (m_steps > 2)
				{
					int num = m_steps / 2;
					result = ((m_steps % 2 != 0) ? points[num] : ((points[num] + points[num + 1]) * 0.5f));
				}
				return result;
			}
		}

		public CableCurve()
		{
			points = emptyCurve;
			m_start = Vector2.up;
			m_end = Vector2.up + Vector2.right;
			m_slack = 0.5f;
			m_steps = 20;
			m_regen = true;
		}

		public CableCurve(Vector2[] inputPoints)
		{
			points = inputPoints;
			m_start = inputPoints[0];
			m_end = inputPoints[1];
			m_slack = 0.5f;
			m_steps = 20;
			m_regen = true;
		}

		public CableCurve(CableCurve v)
		{
			points = v.Points();
			m_start = v.start;
			m_end = v.end;
			m_slack = v.slack;
			m_steps = v.steps;
			m_regen = v.regenPoints;
		}

		public Vector2[] Points()
		{
			if (!m_regen)
			{
				return points;
			}
			if (m_steps < 2)
			{
				return emptyCurve;
			}
			float num = Vector2.Distance(m_end, m_start);
			float num2 = Vector2.Distance(new Vector2(m_end.x, m_start.y), m_start);
			float num3 = num + Mathf.Max(0.0001f, m_slack);
			float num4 = 0f;
			float y = m_start.y;
			float num5 = num2;
			float y2 = end.y;
			if (num5 - num4 == 0f)
			{
				return emptyCurve;
			}
			float num6 = Mathf.Sqrt(Mathf.Pow(num3, 2f) - Mathf.Pow(y2 - y, 2f)) / (num5 - num4);
			int num7 = 30;
			int num8 = 0;
			int num9 = num7 * 10;
			bool flag = false;
			float num10 = 0f;
			float num11 = 0f;
			float num12 = 100f;
			float num13 = 0f;
			for (int i = 0; i < num7; i++)
			{
				for (int j = 0; j < 10; j++)
				{
					num8++;
					num11 = num10 + num12;
					num13 = (float)System.Math.Sinh(num11) / num11;
					if (!float.IsInfinity(num13))
					{
						if (num13 == num6)
						{
							flag = true;
							num10 = num11;
							break;
						}
						if (num13 > num6)
						{
							break;
						}
						num10 = num11;
						if (num8 > num9)
						{
							flag = true;
							break;
						}
					}
				}
				if (flag)
				{
					break;
				}
				num12 *= 0.1f;
			}
			float num14 = (num5 - num4) / 2f / num10;
			float num15 = (num4 + num5 - num14 * Mathf.Log((num3 + y2 - y) / (num3 - y2 + y))) / 2f;
			float num16 = (y2 + y - num3 * (float)System.Math.Cosh(num10) / (float)System.Math.Sinh(num10)) / 2f;
			points = new Vector2[m_steps];
			float num17 = m_steps - 1;
			for (int k = 0; k < m_steps; k++)
			{
				float num18 = (float)k / num17;
				Vector2 zero = Vector2.zero;
				zero.x = Mathf.Lerp(start.x, end.x, num18);
				zero.y = num14 * (float)System.Math.Cosh((num18 * num2 - num15) / num14) + num16;
				points[k] = zero;
			}
			m_regen = false;
			return points;
		}
	}
	public class Circle
	{
		[SerializeField]
		private float xAxis;

		[SerializeField]
		private float yAxis;

		[SerializeField]
		private int steps;

		public float X
		{
			get
			{
				return xAxis;
			}
			set
			{
				xAxis = value;
			}
		}

		public float Y
		{
			get
			{
				return yAxis;
			}
			set
			{
				yAxis = value;
			}
		}

		public int Steps
		{
			get
			{
				return steps;
			}
			set
			{
				steps = value;
			}
		}

		public Circle(float radius)
		{
			xAxis = radius;
			yAxis = radius;
			steps = 1;
		}

		public Circle(float radius, int steps)
		{
			xAxis = radius;
			yAxis = radius;
			this.steps = steps;
		}

		public Circle(float xAxis, float yAxis)
		{
			this.xAxis = xAxis;
			this.yAxis = yAxis;
			steps = 10;
		}

		public Circle(float xAxis, float yAxis, int steps)
		{
			this.xAxis = xAxis;
			this.yAxis = yAxis;
			this.steps = steps;
		}

		public Vector2 Evaluate(float t)
		{
			float num = 360f / (float)steps;
			float f = MathF.PI / 180f * num * t;
			float x = Mathf.Sin(f) * xAxis;
			float y = Mathf.Cos(f) * yAxis;
			return new Vector2(x, y);
		}

		public void Evaluate(float t, out Vector2 eval)
		{
			float num = 360f / (float)steps;
			float f = MathF.PI / 180f * num * t;
			eval.x = Mathf.Sin(f) * xAxis;
			eval.y = Mathf.Cos(f) * yAxis;
		}
	}
