	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("UI/Extensions/Scrollrect Conflict Manager")]
	public class ScrollConflictManager : MonoBehaviour, IBeginDragHandler, IEventSystemHandler, IEndDragHandler, IDragHandler
	{
		public ScrollRect ParentScrollRect;

		private ScrollRect _myScrollRect;

		private bool scrollOther;

		private bool scrollOtherHorizontally;

		private void Awake()
		{
			_myScrollRect = GetComponent<ScrollRect>();
			scrollOtherHorizontally = _myScrollRect.vertical;
			if (scrollOtherHorizontally)
			{
				if (_myScrollRect.horizontal)
				{
					Debug.Log("You have added the SecondScrollRect to a scroll view that already has both directions selected");
				}
				if (!ParentScrollRect.horizontal)
				{
					Debug.Log("The other scroll rect doesnt support scrolling horizontally");
				}
			}
			else if (!ParentScrollRect.vertical)
			{
				Debug.Log("The other scroll rect doesnt support scrolling vertically");
			}
		}

		public void OnBeginDrag(PointerEventData eventData)
		{
			float num = Mathf.Abs(eventData.position.x - eventData.pressPosition.x);
			float num2 = Mathf.Abs(eventData.position.y - eventData.pressPosition.y);
			if (scrollOtherHorizontally)
			{
				if (num > num2)
				{
					scrollOther = true;
					_myScrollRect.enabled = false;
					ParentScrollRect.OnBeginDrag(eventData);
				}
			}
			else if (num2 > num)
			{
				scrollOther = true;
				_myScrollRect.enabled = false;
				ParentScrollRect.OnBeginDrag(eventData);
			}
		}

		public void OnEndDrag(PointerEventData eventData)
		{
			if (scrollOther)
			{
				scrollOther = false;
				_myScrollRect.enabled = true;
				ParentScrollRect.OnEndDrag(eventData);
			}
		}

		public void OnDrag(PointerEventData eventData)
		{
			if (scrollOther)
			{
				ParentScrollRect.OnDrag(eventData);
			}
		}
	}
	[AddComponentMenu("UI/Extensions/ScrollRectEx")]
	public class ScrollRectEx : ScrollRect
	{
		private bool routeToParent;

		private void DoForParents<T>(Action<T> action) where T : IEventSystemHandler
		{
			Transform parent = base.transform.parent;
			while (parent != null)
			{
				Component[] components = parent.GetComponents<Component>();
				foreach (Component component in components)
				{
					if (component is T)
					{
						action((T)(IEventSystemHandler)component);
					}
				}
				parent = parent.parent;
			}
		}

		public override void OnInitializePotentialDrag(PointerEventData eventData)
		{
			DoForParents(delegate(IInitializePotentialDragHandler parent)
			{
				parent.OnInitializePotentialDrag(eventData);
			});
			base.OnInitializePotentialDrag(eventData);
		}

		public override void OnDrag(PointerEventData eventData)
		{
			if (routeToParent)
			{
				DoForParents(delegate(IDragHandler parent)
				{
					parent.OnDrag(eventData);
				});
			}
			else
			{
				base.OnDrag(eventData);
			}
		}

		public override void OnBeginDrag(PointerEventData eventData)
		{
			if (!base.horizontal && System.Math.Abs(eventData.delta.x) > System.Math.Abs(eventData.delta.y))
			{
				routeToParent = true;
			}
			else if (!base.vertical && System.Math.Abs(eventData.delta.x) < System.Math.Abs(eventData.delta.y))
			{
				routeToParent = true;
			}
			else
			{
				routeToParent = false;
			}
			if (routeToParent)
			{
				DoForParents(delegate(IBeginDragHandler parent)
				{
					parent.OnBeginDrag(eventData);
				});
			}
			else
			{
				base.OnBeginDrag(eventData);
			}
		}

		public override void OnEndDrag(PointerEventData eventData)
		{
			if (routeToParent)
			{
				DoForParents(delegate(IEndDragHandler parent)
				{
					parent.OnEndDrag(eventData);
				});
			}
			else
			{
				base.OnEndDrag(eventData);
			}
			routeToParent = false;
		}

		public override void OnScroll(PointerEventData eventData)
		{
			if (!base.horizontal && System.Math.Abs(eventData.scrollDelta.x) > System.Math.Abs(eventData.scrollDelta.y))
			{
				routeToParent = true;
			}
			else if (!base.vertical && System.Math.Abs(eventData.scrollDelta.x) < System.Math.Abs(eventData.scrollDelta.y))
			{
				routeToParent = true;
			}
			else
			{
				routeToParent = false;
			}
			if (routeToParent)
			{
				DoForParents(delegate(IScrollHandler parent)
				{
					parent.OnScroll(eventData);
				});
			}
			else
			{
				base.OnScroll(eventData);
			}
		}
	}
