	[AddComponentMenu("UI/Extensions/UI Highlightable Extension")]
	[RequireComponent(typeof(RectTransform), typeof(Graphic))]
	public class UIHighlightable : MonoBehaviour, IPointerEnterHandler, IEventSystemHandler, IPointerExitHandler, IPointerDownHandler, IPointerUpHandler
	{
		[Serializable]
		public class InteractableChangedEvent : UnityEvent<bool>
		{
		}

		private Graphic m_Graphic;

		private bool m_Highlighted;

		private bool m_Pressed;

		[SerializeField]
		[Tooltip("Can this panel be interacted with or is it disabled? (does not affect child components)")]
		private bool m_Interactable = true;

		[SerializeField]
		[Tooltip("Does the panel remain in the pressed state when clicked? (default false)")]
		private bool m_ClickToHold;

		[Tooltip("The default color for the panel")]
		public Color NormalColor = Color.grey;

		[Tooltip("The color for the panel when a mouse is over it or it is in focus")]
		public Color HighlightedColor = Color.yellow;

		[Tooltip("The color for the panel when it is clicked/held")]
		public Color PressedColor = Color.green;

		[Tooltip("The color for the panel when it is not interactable (see Interactable)")]
		public Color DisabledColor = Color.gray;

		[Tooltip("Event for when the panel is enabled / disabled, to enable disabling / enabling of child or other gameobjects")]
		public InteractableChangedEvent OnInteractableChanged;

		public bool Interactable
		{
			get
			{
				return m_Interactable;
			}
			set
			{
				m_Interactable = value;
				HighlightInteractable(m_Graphic);
				OnInteractableChanged.Invoke(m_Interactable);
			}
		}

		public bool ClickToHold
		{
			get
			{
				return m_ClickToHold;
			}
			set
			{
				m_ClickToHold = value;
			}
		}

		private void Awake()
		{
			m_Graphic = GetComponent<Graphic>();
		}

		public void OnPointerEnter(PointerEventData eventData)
		{
			if (Interactable && !m_Pressed)
			{
				m_Highlighted = true;
				m_Graphic.color = HighlightedColor;
			}
		}

		public void OnPointerExit(PointerEventData eventData)
		{
			if (Interactable && !m_Pressed)
			{
				m_Highlighted = false;
				m_Graphic.color = NormalColor;
			}
		}

		public void OnPointerDown(PointerEventData eventData)
		{
			if (Interactable)
			{
				m_Graphic.color = PressedColor;
				if (ClickToHold)
				{
					m_Pressed = !m_Pressed;
				}
			}
		}

		public void OnPointerUp(PointerEventData eventData)
		{
			if (!m_Pressed)
			{
				HighlightInteractable(m_Graphic);
			}
		}

		private void HighlightInteractable(Graphic graphic)
		{
			if (m_Interactable)
			{
				if (m_Highlighted)
				{
					graphic.color = HighlightedColor;
				}
				else
				{
					graphic.color = NormalColor;
				}
			}
			else
			{
				graphic.color = DisabledColor;
			}
		}
	}
	[AddComponentMenu("UI/Extensions/UI Line Connector")]
	[RequireComponent(typeof(UILineRenderer))]
	[ExecuteInEditMode]
	public class UILineConnector : MonoBehaviour
	{
		public RectTransform[] transforms;

		private Vector2[] previousPositions;

		private RectTransform canvas;

		private RectTransform rt;

		private UILineRenderer lr;

		private void Awake()
		{
			canvas = GetComponentInParent<RectTransform>().GetParentCanvas().GetComponent<RectTransform>();
			rt = GetComponent<RectTransform>();
			lr = GetComponent<UILineRenderer>();
		}

		private void Update()
		{
			if (transforms == null || transforms.Length < 1)
			{
				return;
			}
			if (previousPositions != null && previousPositions.Length == transforms.Length)
			{
				bool flag = false;
				for (int i = 0; i < transforms.Length; i++)
				{
					if (!flag && previousPositions[i] != transforms[i].anchoredPosition)
					{
						flag = true;
					}
				}
				if (!flag)
				{
					return;
				}
			}
			Vector2 pivot = rt.pivot;
			_ = canvas.pivot;
			Vector3[] array = new Vector3[transforms.Length];
			Vector3[] array2 = new Vector3[transforms.Length];
			Vector2[] array3 = new Vector2[transforms.Length];
			for (int j = 0; j < transforms.Length; j++)
			{
				array[j] = transforms[j].TransformPoint(pivot);
			}
			for (int k = 0; k < transforms.Length; k++)
			{
				array2[k] = canvas.InverseTransformPoint(array[k]);
			}
			for (int l = 0; l < transforms.Length; l++)
			{
				array3[l] = new Vector2(array2[l].x, array2[l].y);
			}
			lr.Points = array3;
			lr.RelativeSize = false;
			lr.drivenExternally = true;
			previousPositions = new Vector2[transforms.Length];
			for (int m = 0; m < transforms.Length; m++)
			{
				previousPositions[m] = transforms[m].anchoredPosition;
			}
		}
	}
	[RequireComponent(typeof(ScrollRect))]
	[AddComponentMenu("UI/Extensions/UIScrollToSelection")]
	public class UIScrollToSelection : MonoBehaviour
	{
		public enum ScrollType
		{
			VERTICAL,
			HORIZONTAL,
			BOTH
		}

		[Header("[ Settings ]")]
		[SerializeField]
		private ScrollType scrollDirection;

		[SerializeField]
		private float scrollSpeed = 10f;

		[Header("[ Input ]")]
		[SerializeField]
		private bool cancelScrollOnInput;

		[SerializeField]
		private List<KeyCode> cancelScrollKeycodes = new List<KeyCode>();

		protected RectTransform LayoutListGroup
		{
			get
			{
				if (!(TargetScrollRect != null))
				{
					return null;
				}
				return TargetScrollRect.content;
			}
		}

		protected ScrollType ScrollDirection => scrollDirection;

		protected float ScrollSpeed => scrollSpeed;

		protected bool CancelScrollOnInput => cancelScrollOnInput;

		protected List<KeyCode> CancelScrollKeycodes => cancelScrollKeycodes;

		protected RectTransform ScrollWindow { get; set; }

		protected ScrollRect TargetScrollRect { get; set; }

		protected EventSystem CurrentEventSystem => EventSystem.current;

		protected GameObject LastCheckedGameObject { get; set; }

		protected GameObject CurrentSelectedGameObject => EventSystem.current.currentSelectedGameObject;

		protected RectTransform CurrentTargetRectTransform { get; set; }

		protected bool IsManualScrollingAvailable { get; set; }

		protected virtual void Awake()
		{
			TargetScrollRect = GetComponent<ScrollRect>();
			ScrollWindow = TargetScrollRect.GetComponent<RectTransform>();
		}

		protected virtual void Start()
		{
		}

		protected virtual void Update()
		{
			UpdateReferences();
			CheckIfScrollingShouldBeLocked();
			ScrollRectToLevelSelection();
		}

		private void UpdateReferences()
		{
			if (CurrentSelectedGameObject != LastCheckedGameObject)
			{
				CurrentTargetRectTransform = ((CurrentSelectedGameObject != null) ? CurrentSelectedGameObject.GetComponent<RectTransform>() : null);
				if (CurrentSelectedGameObject != null && CurrentSelectedGameObject.transform.parent == LayoutListGroup.transform)
				{
					IsManualScrollingAvailable = false;
				}
			}
			LastCheckedGameObject = CurrentSelectedGameObject;
		}

		private void CheckIfScrollingShouldBeLocked()
		{
			if (!CancelScrollOnInput || IsManualScrollingAvailable)
			{
				return;
			}
			for (int i = 0; i < CancelScrollKeycodes.Count; i++)
			{
				if (Input.GetKeyDown(CancelScrollKeycodes[i]))
				{
					IsManualScrollingAvailable = true;
					break;
				}
			}
		}

		private void ScrollRectToLevelSelection()
		{
			if (TargetScrollRect == null || LayoutListGroup == null || ScrollWindow == null || IsManualScrollingAvailable)
			{
				return;
			}
			RectTransform currentTargetRectTransform = CurrentTargetRectTransform;
			if (!(currentTargetRectTransform == null) && !(currentTargetRectTransform.transform.parent != LayoutListGroup.transform))
			{
				switch (ScrollDirection)
				{
				case ScrollType.VERTICAL:
					UpdateVerticalScrollPosition(currentTargetRectTransform);
					break;
				case ScrollType.HORIZONTAL:
					UpdateHorizontalScrollPosition(currentTargetRectTransform);
					break;
				case ScrollType.BOTH:
					UpdateVerticalScrollPosition(currentTargetRectTransform);
					UpdateHorizontalScrollPosition(currentTargetRectTransform);
					break;
				}
			}
		}

		private void UpdateVerticalScrollPosition(RectTransform selection)
		{
			float position = 0f - selection.anchoredPosition.y - selection.rect.height * (1f - selection.pivot.y);
			float height = selection.rect.height;
			float height2 = ScrollWindow.rect.height;
			float y = LayoutListGroup.anchoredPosition.y;
			float scrollOffset = GetScrollOffset(position, y, height, height2);
			TargetScrollRect.verticalNormalizedPosition += scrollOffset / LayoutListGroup.rect.height * Time.unscaledDeltaTime * scrollSpeed;
		}

		private void UpdateHorizontalScrollPosition(RectTransform selection)
		{
			float position = 0f - selection.anchoredPosition.x - selection.rect.width * (1f - selection.pivot.x);
			float width = selection.rect.width;
			float width2 = ScrollWindow.rect.width;
			float listAnchorPosition = 0f - LayoutListGroup.anchoredPosition.x;
			float num = 0f - GetScrollOffset(position, listAnchorPosition, width, width2);
			TargetScrollRect.horizontalNormalizedPosition += num / LayoutListGroup.rect.width * Time.unscaledDeltaTime * scrollSpeed;
		}

		private float GetScrollOffset(float position, float listAnchorPosition, float targetLength, float maskLength)
		{
			if (position < listAnchorPosition + targetLength / 2f)
			{
				return listAnchorPosition + maskLength - (position - targetLength);
			}
			if (position + targetLength > listAnchorPosition + maskLength)
			{
				return listAnchorPosition + maskLength - (position + targetLength);
			}
			return 0f;
		}
	}
	[AddComponentMenu("UI/Extensions/UI ScrollTo Selection XY")]
	[RequireComponent(typeof(ScrollRect))]
	public class UIScrollToSelectionXY : MonoBehaviour
	{
		public float scrollSpeed = 10f;

		[SerializeField]
		private RectTransform layoutListGroup;

		private RectTransform targetScrollObject;

		private bool scrollToSelection = true;

		private RectTransform scrollWindow;

		private RectTransform currentCanvas;

		private ScrollRect targetScrollRect;

		private void Start()
		{
			targetScrollRect = GetComponent<ScrollRect>();
			scrollWindow = targetScrollRect.GetComponent<RectTransform>();
		}

		private void Update()
		{
			ScrollRectToLevelSelection();
		}

		private void ScrollRectToLevelSelection()
		{
			EventSystem current = EventSystem.current;
			if (targetScrollRect == null || layoutListGroup == null || scrollWindow == null)
			{
				return;
			}
			RectTransform rectTransform = ((current.currentSelectedGameObject != null) ? current.currentSelectedGameObject.GetComponent<RectTransform>() : null);
			if (rectTransform != targetScrollObject)
			{
				scrollToSelection = true;
			}
			if (!(rectTransform == null) && scrollToSelection && !(rectTransform.transform.parent != layoutListGroup.transform))
			{
				bool flag = false;
				bool flag2 = false;
				if (targetScrollRect.vertical)
				{
					float num = 0f - rectTransform.anchoredPosition.y;
					float y = layoutListGroup.anchoredPosition.y;
					float num2 = 0f;
					num2 = y - num;
					targetScrollRect.verticalNormalizedPosition += num2 / layoutListGroup.sizeDelta.y * Time.deltaTime * scrollSpeed;
					flag2 = Mathf.Abs(num2) < 2f;
				}
				if (targetScrollRect.horizontal)
				{
					float num3 = 0f - rectTransform.anchoredPosition.x;
					float x = layoutListGroup.anchoredPosition.x;
					float num4 = 0f;
					num4 = x - num3;
					targetScrollRect.horizontalNormalizedPosition += num4 / layoutListGroup.sizeDelta.x * Time.deltaTime * scrollSpeed;
					flag = Mathf.Abs(num4) < 2f;
				}
				if (flag && flag2)
				{
					scrollToSelection = false;
				}
				targetScrollObject = rectTransform;
			}
		}
	}
	[AddComponentMenu("UI/Extensions/UI Selectable Extension")]
	[RequireComponent(typeof(Selectable))]
	public class UISelectableExtension : MonoBehaviour, IPointerDownHandler, IEventSystemHandler, IPointerUpHandler
	{
		[Serializable]
		public class UIButtonEvent : UnityEvent<PointerEventData.InputButton>
		{
		}

		[Tooltip("Event that fires when a button is initially pressed down")]
		public UIButtonEvent OnButtonPress;

		[Tooltip("Event that fires when a button is released")]
		public UIButtonEvent OnButtonRelease;

		[Tooltip("Event that continually fires while a button is held down")]
		public UIButtonEvent OnButtonHeld;

		private bool _pressed;

		private PointerEventData _heldEventData;

		void IPointerDownHandler.OnPointerDown(PointerEventData eventData)
		{
			if (OnButtonPress != null)
			{
				OnButtonPress.Invoke(eventData.button);
			}
			_pressed = true;
			_heldEventData = eventData;
		}

		void IPointerUpHandler.OnPointerUp(PointerEventData eventData)
		{
			if (OnButtonRelease != null)
			{
				OnButtonRelease.Invoke(eventData.button);
