		{
		}

		private void OnDisable()
		{
			_pressed = false;
		}
	}
	[AddComponentMenu("UI/Extensions/UI Infinite Scroll")]
	public class UI_InfiniteScroll : MonoBehaviour
	{
		[Tooltip("If false, will Init automatically, otherwise you need to call Init() method")]
		public bool InitByUser;

		private ScrollRect _scrollRect;

		private ContentSizeFitter _contentSizeFitter;

		private VerticalLayoutGroup _verticalLayoutGroup;

		private HorizontalLayoutGroup _horizontalLayoutGroup;

		private GridLayoutGroup _gridLayoutGroup;

		private bool _isVertical;

		private bool _isHorizontal;

		private float _disableMarginX;

		private float _disableMarginY;

		private bool _hasDisabledGridComponents;

		private List<RectTransform> items = new List<RectTransform>();

		private Vector2 _newAnchoredPosition = Vector2.zero;

		private float _treshold = 100f;

		private int _itemCount;

		private float _recordOffsetX;

		private float _recordOffsetY;

		private void Awake()
		{
			if (!InitByUser)
			{
				Init();
			}
		}

		public void Init()
		{
			if (GetComponent<ScrollRect>() != null)
			{
				_scrollRect = GetComponent<ScrollRect>();
				_scrollRect.onValueChanged.AddListener(OnScroll);
				_scrollRect.movementType = ScrollRect.MovementType.Unrestricted;
				for (int i = 0; i < _scrollRect.content.childCount; i++)
				{
					items.Add(_scrollRect.content.GetChild(i).GetComponent<RectTransform>());
				}
				if (_scrollRect.content.GetComponent<VerticalLayoutGroup>() != null)
				{
					_verticalLayoutGroup = _scrollRect.content.GetComponent<VerticalLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<HorizontalLayoutGroup>() != null)
				{
					_horizontalLayoutGroup = _scrollRect.content.GetComponent<HorizontalLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<GridLayoutGroup>() != null)
				{
					_gridLayoutGroup = _scrollRect.content.GetComponent<GridLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<ContentSizeFitter>() != null)
				{
					_contentSizeFitter = _scrollRect.content.GetComponent<ContentSizeFitter>();
				}
				_isHorizontal = _scrollRect.horizontal;
				_isVertical = _scrollRect.vertical;
				if (_isHorizontal && _isVertical)
				{
					Debug.LogError("UI_InfiniteScroll doesn't support scrolling in both directions, plase choose one direction (horizontal or vertical)");
				}
				_itemCount = _scrollRect.content.childCount;
			}
			else
			{
				Debug.LogError("UI_InfiniteScroll => No ScrollRect component found");
			}
		}

		private void DisableGridComponents()
		{
			if (_isVertical)
			{
				_recordOffsetY = items[0].GetComponent<RectTransform>().anchoredPosition.y - items[1].GetComponent<RectTransform>().anchoredPosition.y;
				_disableMarginY = _recordOffsetY * (float)_itemCount / 2f;
			}
			if (_isHorizontal)
			{
				_recordOffsetX = items[1].GetComponent<RectTransform>().anchoredPosition.x - items[0].GetComponent<RectTransform>().anchoredPosition.x;
				_disableMarginX = _recordOffsetX * (float)_itemCount / 2f;
			}
			if ((bool)_verticalLayoutGroup)
			{
				_verticalLayoutGroup.enabled = false;
			}
			if ((bool)_horizontalLayoutGroup)
			{
				_horizontalLayoutGroup.enabled = false;
			}
			if ((bool)_contentSizeFitter)
			{
				_contentSizeFitter.enabled = false;
			}
			if ((bool)_gridLayoutGroup)
			{
				_gridLayoutGroup.enabled = false;
			}
			_hasDisabledGridComponents = true;
		}

		public void OnScroll(Vector2 pos)
		{
			if (!_hasDisabledGridComponents)
			{
				DisableGridComponents();
			}
			for (int i = 0; i < items.Count; i++)
			{
				if (_isHorizontal)
				{
					if (_scrollRect.transform.InverseTransformPoint(items[i].gameObject.transform.position).x > _disableMarginX + _treshold)
					{
						_newAnchoredPosition = items[i].anchoredPosition;
						_newAnchoredPosition.x -= (float)_itemCount * _recordOffsetX;
						items[i].anchoredPosition = _newAnchoredPosition;
						_scrollRect.content.GetChild(_itemCount - 1).transform.SetAsFirstSibling();
					}
					else if (_scrollRect.transform.InverseTransformPoint(items[i].gameObject.transform.position).x < 0f - _disableMarginX)
					{
						_newAnchoredPosition = items[i].anchoredPosition;
						_newAnchoredPosition.x += (float)_itemCount * _recordOffsetX;
						items[i].anchoredPosition = _newAnchoredPosition;
						_scrollRect.content.GetChild(0).transform.SetAsLastSibling();
					}
				}
				if (_isVertical)
				{
					if (_scrollRect.transform.InverseTransformPoint(items[i].gameObject.transform.position).y > _disableMarginY + _treshold)
					{
						_newAnchoredPosition = items[i].anchoredPosition;
						_newAnchoredPosition.y -= (float)_itemCount * _recordOffsetY;
						items[i].anchoredPosition = _newAnchoredPosition;
						_scrollRect.content.GetChild(_itemCount - 1).transform.SetAsFirstSibling();
					}
					else if (_scrollRect.transform.InverseTransformPoint(items[i].gameObject.transform.position).y < 0f - _disableMarginY)
					{
						_newAnchoredPosition = items[i].anchoredPosition;
						_newAnchoredPosition.y += (float)_itemCount * _recordOffsetY;
						items[i].anchoredPosition = _newAnchoredPosition;
						_scrollRect.content.GetChild(0).transform.SetAsLastSibling();
					}
				}
			}
		}
	}
	[AddComponentMenu("UI/Extensions/UI Scrollrect Occlusion")]
	public class UI_ScrollRectOcclusion : MonoBehaviour
	{
		public bool InitByUser;

		private ScrollRect _scrollRect;

		private ContentSizeFitter _contentSizeFitter;

		private VerticalLayoutGroup _verticalLayoutGroup;

		private HorizontalLayoutGroup _horizontalLayoutGroup;

		private GridLayoutGroup _gridLayoutGroup;

		private bool _isVertical;

		private bool _isHorizontal;

		private float _disableMarginX;

		private float _disableMarginY;

		private bool hasDisabledGridComponents;

		private List<RectTransform> items = new List<RectTransform>();

		private void Awake()
		{
			if (!InitByUser)
			{
				Init();
			}
		}

		public void Init()
		{
			if (GetComponent<ScrollRect>() != null)
			{
				_scrollRect = GetComponent<ScrollRect>();
				_scrollRect.onValueChanged.AddListener(OnScroll);
				_isHorizontal = _scrollRect.horizontal;
				_isVertical = _scrollRect.vertical;
				for (int i = 0; i < _scrollRect.content.childCount; i++)
				{
					items.Add(_scrollRect.content.GetChild(i).GetComponent<RectTransform>());
				}
				if (_scrollRect.content.GetComponent<VerticalLayoutGroup>() != null)
				{
					_verticalLayoutGroup = _scrollRect.content.GetComponent<VerticalLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<HorizontalLayoutGroup>() != null)
				{
					_horizontalLayoutGroup = _scrollRect.content.GetComponent<HorizontalLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<GridLayoutGroup>() != null)
				{
					_gridLayoutGroup = _scrollRect.content.GetComponent<GridLayoutGroup>();
				}
				if (_scrollRect.content.GetComponent<ContentSizeFitter>() != null)
				{
					_contentSizeFitter = _scrollRect.content.GetComponent<ContentSizeFitter>();
				}
			}
			else
			{
				Debug.LogError("UI_ScrollRectOcclusion => No ScrollRect component found");
			}
		}

		private void DisableGridComponents()
		{
			if (_isVertical)
			{
				_disableMarginY = _scrollRect.GetComponent<RectTransform>().rect.height / 2f + items[0].sizeDelta.y;
			}
			if (_isHorizontal)
			{
				_disableMarginX = _scrollRect.GetComponent<RectTransform>().rect.width / 2f + items[0].sizeDelta.x;
			}
			if ((bool)_verticalLayoutGroup)
			{
				_verticalLayoutGroup.enabled = false;
			}
			if ((bool)_horizontalLayoutGroup)
			{
				_horizontalLayoutGroup.enabled = false;
			}
			if ((bool)_contentSizeFitter)
			{
				_contentSizeFitter.enabled = false;
			}
			if ((bool)_gridLayoutGroup)
			{
				_gridLayoutGroup.enabled = false;
			}
			hasDisabledGridComponents = true;
		}

		public void OnScroll(Vector2 pos)
		{
			if (!hasDisabledGridComponents)
			{
				DisableGridComponents();
			}
			for (int i = 0; i < items.Count; i++)
			{
				if (_isVertical && _isHorizontal)
				{
					if (_scrollRect.transform.InverseTransformPoint(items[i].position).y < 0f - _disableMarginY || _scrollRect.transform.InverseTransformPoint(items[i].position).y > _disableMarginY || _scrollRect.transform.InverseTransformPoint(items[i].position).x < 0f - _disableMarginX || _scrollRect.transform.InverseTransformPoint(items[i].position).x > _disableMarginX)
					{
						items[i].gameObject.SetActive(value: false);
					}
					else
					{
						items[i].gameObject.SetActive(value: true);
					}
					continue;
				}
				if (_isVertical)
				{
					if (_scrollRect.transform.InverseTransformPoint(items[i].position).y < 0f - _disableMarginY || _scrollRect.transform.InverseTransformPoint(items[i].position).y > _disableMarginY)
					{
						items[i].gameObject.SetActive(value: false);
					}
					else
					{
						items[i].gameObject.SetActive(value: true);
					}
				}
				if (_isHorizontal)
				{
					if (_scrollRect.transform.InverseTransformPoint(items[i].position).x < 0f - _disableMarginX || _scrollRect.transform.InverseTransformPoint(items[i].position).x > _disableMarginX)
					{
						items[i].gameObject.SetActive(value: false);
					}
					else
					{
						items[i].gameObject.SetActive(value: true);
					}
				}
			}
		}
	}
	[AddComponentMenu("UI/Extensions/UI Tween Scale")]
	public class UI_TweenScale : MonoBehaviour
	{
		public AnimationCurve animCurve;

		[Tooltip("Animation speed multiplier")]
		public float speed = 1f;

		[Tooltip("If true animation will loop, for best effect set animation curve to loop on start and end point")]
		public bool isLoop;

		[Tooltip("If true animation will start automatically, otherwise you need to call Play() method to start the animation")]
		public bool playAtAwake;

		[Space(10f)]
		[Header("Non uniform scale")]
		[Tooltip("If true component will scale by the same amount in X and Y axis, otherwise use animCurve for X scale and animCurveY for Y scale")]
		public bool isUniform = true;

		public AnimationCurve animCurveY;

		private Vector3 initScale;

		private Transform myTransform;

		private Vector3 newScale = Vector3.one;

		private void Awake()
		{
			myTransform = GetComponent<Transform>();
			initScale = myTransform.localScale;
			if (playAtAwake)
			{
				Play();
			}
		}

		public void Play()
		{
			StartCoroutine("Tween");
		}

		private IEnumerator Tween()
		{
			myTransform.localScale = initScale;
			float t = 0f;
			float maxT = animCurve.keys[animCurve.length - 1].time;
			while (t < maxT || isLoop)
			{
				t += speed * Time.deltaTime;
				if (!isUniform)
				{
					newScale.x = 1f * animCurve.Evaluate(t);
					newScale.y = 1f * animCurveY.Evaluate(t);
					myTransform.localScale = newScale;
				}
				else
				{
					myTransform.localScale = Vector3.one * animCurve.Evaluate(t);
				}
				yield return null;
			}
		}

		public void ResetTween()
		{
			StopCoroutine("Tween");
			myTransform.localScale = initScale;
		}
	}
	public static class RectTransformExtension
	{
		public static Vector2 switchToRectTransform(this RectTransform from, RectTransform to)
		{
			Vector2 vector = new Vector2(from.rect.width * from.pivot.x + from.rect.xMin, from.rect.height * from.pivot.y + from.rect.yMin);
			Vector2 screenPoint = RectTransformUtility.WorldToScreenPoint(null, from.position);
			screenPoint += vector;
			RectTransformUtility.ScreenPointToLocalPointInRectangle(to, screenPoint, null, out var localPoint);
			Vector2 vector2 = new Vector2(to.rect.width * to.pivot.x + to.rect.xMin, to.rect.height * to.pivot.y + to.rect.yMin);
			return to.anchoredPosition + localPoint - vector2;
		}
	}
	[AddComponentMenu("UI/Extensions/VR Cursor")]
	public class VRCursor : MonoBehaviour
	{
		public float xSens;

		public float ySens;

		private Collider currentCollider;

		private void Update()
		{
			Vector3 position = default(Vector3);
			position.x = Input.mousePosition.x * xSens;
			position.y = Input.mousePosition.y * ySens - 1f;
			position.z = base.transform.position.z;
			base.transform.position = position;
			VRInputModule.cursorPosition = base.transform.position;
			if (Input.GetMouseButtonDown(0) && (bool)currentCollider)
			{
				VRInputModule.PointerSubmit(currentCollider.gameObject);
			}
		}

		private void OnTriggerEnter(Collider other)
		{
			VRInputModule.PointerEnter(other.gameObject);
			currentCollider = other;
		}

		private void OnTriggerExit(Collider other)
		{
			VRInputModule.PointerExit(other.gameObject);
			currentCollider = null;
		}
	}
	[AddComponentMenu("Event/VR Input Module")]
	public class VRInputModule : BaseInputModule
	{
		public static GameObject targetObject;

		private static VRInputModule _singleton;

		private int counter;

		private static bool mouseClicked;

		public static Vector3 cursorPosition;

		protected override void Awake()
		{
			_singleton = this;
		}

		public override void Process()
		{
			if (targetObject == null)
			{
				mouseClicked = false;
			}
		}

		public static void PointerSubmit(GameObject obj)
		{
			targetObject = obj;
			mouseClicked = true;
			if (mouseClicked)
			{
				BaseEventData baseEventData = new BaseEventData(_singleton.eventSystem);
				baseEventData.selectedObject = targetObject;
				ExecuteEvents.Execute(targetObject, baseEventData, ExecuteEvents.submitHandler);
				MonoBehaviour.print("clicked " + targetObject.name);
				mouseClicked = false;
			}
		}

		public static void PointerExit(GameObject obj)
		{
			MonoBehaviour.print("PointerExit " + obj.name);
			PointerEventData eventData = new PointerEventData(_singleton.eventSystem);
			ExecuteEvents.Execute(obj, eventData, ExecuteEvents.pointerExitHandler);
			ExecuteEvents.Execute(obj, eventData, ExecuteEvents.deselectHandler);
		}

		public static void PointerEnter(GameObject obj)
		{
			MonoBehaviour.print("PointerEnter " + obj.name);
			PointerEventData pointerEventData = new PointerEventData(_singleton.eventSystem);
			pointerEventData.pointerEnter = obj;
			RaycastResult pointerCurrentRaycast = new RaycastResult
			{
				worldPosition = cursorPosition
			};
			pointerEventData.pointerCurrentRaycast = pointerCurrentRaycast;
			ExecuteEvents.Execute(obj, pointerEventData, ExecuteEvents.pointerEnterHandler);
		}
	}
}
