	[RequireComponent(typeof(Text))]
	public class ColorLabel : MonoBehaviour
	{
		public ColorPickerControl picker;

		public ColorValues type;

		public string prefix = "R: ";

		public float minValue;

		public float maxValue = 255f;

		public int precision;

		private Text label;

		private void Awake()
		{
			label = GetComponent<Text>();
		}

		private void OnEnable()
		{
			if (Application.isPlaying && picker != null)
			{
				picker.onValueChanged.AddListener(ColorChanged);
				picker.onHSVChanged.AddListener(HSVChanged);
			}
		}

		private void OnDestroy()
		{
			if (picker != null)
			{
				picker.onValueChanged.RemoveListener(ColorChanged);
				picker.onHSVChanged.RemoveListener(HSVChanged);
			}
		}

		private void ColorChanged(Color color)
		{
			UpdateValue();
		}

		private void HSVChanged(float hue, float sateration, float value)
		{
			UpdateValue();
		}

		private void UpdateValue()
		{
			if (picker == null)
			{
				label.text = prefix + "-";
				return;
			}
			float value = minValue + picker.GetValue(type) * (maxValue - minValue);
			label.text = prefix + ConvertToDisplayString(value);
		}

		private string ConvertToDisplayString(float value)
		{
			if (precision > 0)
			{
				return value.ToString("f " + precision);
			}
			return Mathf.FloorToInt(value).ToString();
		}
	}
	public class ColorPickerControl : MonoBehaviour
	{
		private float _hue;

		private float _saturation;

		private float _brightness;

		private float _red;

		private float _green;

		private float _blue;

		private float _alpha = 1f;

		public ColorChangedEvent onValueChanged = new ColorChangedEvent();

		public HSVChangedEvent onHSVChanged = new HSVChangedEvent();

		public Color CurrentColor
		{
			get
			{
				return new Color(_red, _green, _blue, _alpha);
			}
			set
			{
				if (!(CurrentColor == value))
				{
					_red = value.r;
					_green = value.g;
					_blue = value.b;
					_alpha = value.a;
					RGBChanged();
					SendChangedEvent();
				}
			}
		}

		public float H
		{
			get
			{
				return _hue;
			}
			set
			{
				if (_hue != value)
				{
					_hue = value;
					HSVChanged();
					SendChangedEvent();
				}
			}
		}

		public float S
		{
			get
			{
				return _saturation;
			}
			set
			{
				if (_saturation != value)
				{
					_saturation = value;
					HSVChanged();
					SendChangedEvent();
				}
			}
		}

		public float V
		{
			get
			{
				return _brightness;
			}
			set
			{
				if (_brightness != value)
				{
					_brightness = value;
					HSVChanged();
					SendChangedEvent();
				}
			}
		}

		public float R
		{
			get
			{
				return _red;
			}
			set
			{
				if (_red != value)
				{
					_red = value;
					RGBChanged();
					SendChangedEvent();
				}
			}
		}

		public float G
		{
			get
			{
				return _green;
			}
			set
			{
				if (_green != value)
				{
					_green = value;
					RGBChanged();
					SendChangedEvent();
				}
			}
		}

		public float B
		{
			get
			{
				return _blue;
			}
			set
			{
				if (_blue != value)
				{
					_blue = value;
					RGBChanged();
					SendChangedEvent();
				}
			}
		}

		private float A
		{
			get
			{
				return _alpha;
			}
			set
			{
				if (_alpha != value)
				{
					_alpha = value;
					SendChangedEvent();
				}
			}
		}

		private void Start()
		{
			SendChangedEvent();
		}

		private void RGBChanged()
		{
			HsvColor hsvColor = HSVUtil.ConvertRgbToHsv(CurrentColor);
			_hue = hsvColor.NormalizedH;
			_saturation = hsvColor.NormalizedS;
			_brightness = hsvColor.NormalizedV;
		}

		private void HSVChanged()
		{
			Color color = HSVUtil.ConvertHsvToRgb(_hue * 360f, _saturation, _brightness, _alpha);
			_red = color.r;
			_green = color.g;
			_blue = color.b;
		}

		private void SendChangedEvent()
		{
			onValueChanged.Invoke(CurrentColor);
			onHSVChanged.Invoke(_hue, _saturation, _brightness);
		}

		public void AssignColor(ColorValues type, float value)
		{
			switch (type)
			{
			case ColorValues.R:
				R = value;
				break;
			case ColorValues.G:
				G = value;
				break;
			case ColorValues.B:
				B = value;
				break;
			case ColorValues.A:
				A = value;
				break;
			case ColorValues.Hue:
				H = value;
				break;
			case ColorValues.Saturation:
				S = value;
				break;
			case ColorValues.Value:
				V = value;
				break;
			}
		}

		public float GetValue(ColorValues type)
		{
			return type switch
			{
				ColorValues.R => R, 
				ColorValues.G => G, 
				ColorValues.B => B, 
				ColorValues.A => A, 
				ColorValues.Hue => H, 
				ColorValues.Saturation => S, 
				ColorValues.Value => V, 
				_ => throw new NotImplementedException(""), 
			};
		}
	}
