	[RequireComponent(typeof(RawImage))]
	[ExecuteInEditMode]
	public class ColorSliderImage : MonoBehaviour
	{
		public ColorPickerControl picker;

		public ColorValues type;

		public Slider.Direction direction;

		private RawImage image;

		private RectTransform RectTransform => base.transform as RectTransform;

		private void Awake()
		{
			image = GetComponent<RawImage>();
			if ((bool)image)
			{
				RegenerateTexture();
			}
			else
			{
				Debug.LogWarning("Missing RawImage on object [" + base.name + "]");
			}
		}

		private void OnEnable()
		{
			if (picker != null && Application.isPlaying)
			{
				picker.onValueChanged.AddListener(ColorChanged);
				picker.onHSVChanged.AddListener(ColorChanged);
			}
		}

		private void OnDisable()
		{
			if (picker != null)
			{
				picker.onValueChanged.RemoveListener(ColorChanged);
				picker.onHSVChanged.RemoveListener(ColorChanged);
			}
		}

		private void OnDestroy()
		{
			if (image.texture != null)
			{
				Object.DestroyImmediate(image.texture);
			}
		}

		private void ColorChanged(Color newColor)
		{
			switch (type)
			{
			case ColorValues.R:
			case ColorValues.G:
			case ColorValues.B:
			case ColorValues.Saturation:
			case ColorValues.Value:
				RegenerateTexture();
				break;
			case ColorValues.A:
			case ColorValues.Hue:
				break;
			}
		}

		private void ColorChanged(float hue, float saturation, float value)
		{
			switch (type)
			{
			case ColorValues.R:
			case ColorValues.G:
			case ColorValues.B:
			case ColorValues.Saturation:
			case ColorValues.Value:
				RegenerateTexture();
				break;
			case ColorValues.A:
			case ColorValues.Hue:
				break;
			}
		}

		private void RegenerateTexture()
		{
			if (!picker)
			{
				Debug.LogWarning("Missing Picker on object [" + base.name + "]");
			}
			Color32 color = ((picker != null) ? picker.CurrentColor : Color.black);
			float num = ((picker != null) ? picker.H : 0f);
			float num2 = ((picker != null) ? picker.S : 0f);
			float num3 = ((picker != null) ? picker.V : 0f);
			bool flag = direction == Slider.Direction.BottomToTop || direction == Slider.Direction.TopToBottom;
			bool flag2 = direction == Slider.Direction.TopToBottom || direction == Slider.Direction.RightToLeft;
			int num4;
			switch (type)
			{
			case ColorValues.R:
			case ColorValues.G:
			case ColorValues.B:
			case ColorValues.A:
				num4 = 255;
				break;
			case ColorValues.Hue:
				num4 = 360;
				break;
			case ColorValues.Saturation:
			case ColorValues.Value:
				num4 = 100;
				break;
			default:
				throw new NotImplementedException("");
			}
			Texture2D texture2D = ((!flag) ? new Texture2D(num4, 1) : new Texture2D(1, num4));
			texture2D.hideFlags = HideFlags.DontSave;
			Color32[] array = new Color32[num4];
			switch (type)
			{
			case ColorValues.R:
			{
				for (byte b3 = 0; b3 < num4; b3++)
				{
					array[flag2 ? (num4 - 1 - b3) : b3] = new Color32(b3, color.g, color.b, byte.MaxValue);
				}
				break;
			}
			case ColorValues.G:
			{
				for (byte b = 0; b < num4; b++)
				{
					array[flag2 ? (num4 - 1 - b) : b] = new Color32(color.r, b, color.b, byte.MaxValue);
				}
				break;
			}
			case ColorValues.B:
			{
				for (byte b2 = 0; b2 < num4; b2++)
				{
					array[flag2 ? (num4 - 1 - b2) : b2] = new Color32(color.r, color.g, b2, byte.MaxValue);
				}
				break;
			}
			case ColorValues.A:
			{
				for (byte b4 = 0; b4 < num4; b4++)
				{
					array[flag2 ? (num4 - 1 - b4) : b4] = new Color32(b4, b4, b4, byte.MaxValue);
				}
				break;
			}
			case ColorValues.Hue:
			{
				for (int k = 0; k < num4; k++)
				{
					array[flag2 ? (num4 - 1 - k) : k] = HSVUtil.ConvertHsvToRgb(k, 1.0, 1.0, 1f);
				}
				break;
			}
			case ColorValues.Saturation:
			{
				for (int j = 0; j < num4; j++)
				{
					array[flag2 ? (num4 - 1 - j) : j] = HSVUtil.ConvertHsvToRgb(num * 360f, (float)j / (float)num4, num3, 1f);
				}
				break;
			}
			case ColorValues.Value:
			{
				for (int i = 0; i < num4; i++)
				{
					array[flag2 ? (num4 - 1 - i) : i] = HSVUtil.ConvertHsvToRgb(num * 360f, num2, (float)i / (float)num4, 1f);
				}
				break;
			}
			default:
				throw new NotImplementedException("");
			}
			texture2D.SetPixels32(array);
			texture2D.Apply();
			if (image.texture != null)
			{
				Object.DestroyImmediate(image.texture);
			}
			image.texture = texture2D;
			switch (direction)
			{
			case Slider.Direction.BottomToTop:
			case Slider.Direction.TopToBottom:
				image.uvRect = new Rect(0f, 0f, 2f, 1f);
				break;
			case Slider.Direction.LeftToRight:
			case Slider.Direction.RightToLeft:
				image.uvRect = new Rect(0f, 0f, 1f, 2f);
				break;
			}
		}
	}
	public enum ColorValues
	{
		R,
		G,
		B,
		A,
		Hue,
		Saturation,
		Value
	}
	public static class HSVUtil
	{
		public static HsvColor ConvertRgbToHsv(Color color)
		{
			return ConvertRgbToHsv((int)(color.r * 255f), (int)(color.g * 255f), (int)(color.b * 255f));
		}

		public static HsvColor ConvertRgbToHsv(double r, double b, double g)
		{
			double num = 0.0;
			double num2 = System.Math.Min(System.Math.Min(r, g), b);
			double num3 = System.Math.Max(System.Math.Max(r, g), b);
			double num4 = num3 - num2;
			double num5 = ((num3 != 0.0) ? (num4 / num3) : 0.0);
			if (num5 == 0.0)
			{
				num = 360.0;
			}
			else
			{
				if (r == num3)
				{
					num = (g - b) / num4;
				}
				else if (g == num3)
				{
					num = 2.0 + (b - r) / num4;
				}
				else if (b == num3)
				{
					num = 4.0 + (r - g) / num4;
				}
				num *= 60.0;
				if (num <= 0.0)
				{
					num += 360.0;
				}
			}
			return new HsvColor
			{
				H = 360.0 - num,
				S = num5,
				V = num3 / 255.0
			};
		}

		public static Color ConvertHsvToRgb(double h, double s, double v, float alpha)
		{
			double num = 0.0;
			double num2 = 0.0;
			double num3 = 0.0;
			if (s == 0.0)
			{
				num = v;
				num2 = v;
				num3 = v;
			}
			else
			{
				h = ((h != 360.0) ? (h / 60.0) : 0.0);
				int num4 = (int)h;
				double num5 = h - (double)num4;
				double num6 = v * (1.0 - s);
				double num7 = v * (1.0 - s * num5);
				double num8 = v * (1.0 - s * (1.0 - num5));
				switch (num4)
				{
				case 0:
					num = v;
					num2 = num8;
					num3 = num6;
					break;
				case 1:
					num = num7;
					num2 = v;
					num3 = num6;
					break;
				case 2:
					num = num6;
					num2 = v;
					num3 = num8;
					break;
				case 3:
					num = num6;
					num2 = num7;
					num3 = v;
					break;
				case 4:
					num = num8;
					num2 = num6;
					num3 = v;
					break;
				default:
					num = v;
					num2 = num6;
					num3 = num7;
					break;
				}
			}
			return new Color((float)num, (float)num2, (float)num3, alpha);
		}
	}
	public struct HsvColor
	{
		public double H;

		public double S;

		public double V;

		public float NormalizedH
		{
			get
			{
				return (float)H / 360f;
			}
			set
			{
				H = (double)value * 360.0;
			}
		}

		public float NormalizedS
		{
			get
			{
				return (float)S;
			}
			set
			{
				S = value;
			}
		}

		public float NormalizedV
		{
			get
			{
				return (float)V;
			}
			set
			{
				V = value;
			}
		}

		public HsvColor(double h, double s, double v)
		{
			H = h;
			S = s;
			V = v;
		}

		public override string ToString()
		{
			return "{" + H.ToString("f2") + "," + S.ToString("f2") + "," + V.ToString("f2") + "}";
		}
	}
	[RequireComponent(typeof(InputField))]
	public class HexColorField : MonoBehaviour
	{
		public ColorPickerControl ColorPicker;

		public bool displayAlpha;

		private InputField hexInputField;

		private const string hexRegex = "^#?(?:[0-9a-fA-F]{3,4}){1,2}$";

		private void Awake()
		{
			hexInputField = GetComponent<InputField>();
			hexInputField.onEndEdit.AddListener(UpdateColor);
			ColorPicker.onValueChanged.AddListener(UpdateHex);
		}

		private void OnDestroy()
		{
			hexInputField.onValueChanged.RemoveListener(UpdateColor);
			ColorPicker.onValueChanged.RemoveListener(UpdateHex);
		}

		private void UpdateHex(Color newColor)
		{
			hexInputField.text = ColorToHex(newColor);
		}

		private void UpdateColor(string newHex)
		{
			if (HexToColor(newHex, out var color))
			{
				ColorPicker.CurrentColor = color;
			}
			else
			{
				Debug.Log("hex value is in the wrong format, valid formats are: #RGB, #RGBA, #RRGGBB and #RRGGBBAA (# is optional)");
			}
		}

		private string ColorToHex(Color32 color)
		{
			if (displayAlpha)
			{
				return $"#{color.r:X2}{color.g:X2}{color.b:X2}{color.a:X2}";
			}
			return $"#{color.r:X2}{color.g:X2}{color.b:X2}";
		}

		public static bool HexToColor(string hex, out Color32 color)
		{
			if (Regex.IsMatch(hex, "^#?(?:[0-9a-fA-F]{3,4}){1,2}$"))
			{
				int num = (hex.StartsWith("#") ? 1 : 0);
				if (hex.Length == num + 8)
				{
					color = new Color32(byte.Parse(hex.Substring(num, 2), NumberStyles.AllowHexSpecifier), byte.Parse(hex.Substring(num + 2, 2), NumberStyles.AllowHexSpecifier), byte.Parse(hex.Substring(num + 4, 2), NumberStyles.AllowHexSpecifier), byte.Parse(hex.Substring(num + 6, 2), NumberStyles.AllowHexSpecifier));
				}
				else if (hex.Length == num + 6)
				{
					color = new Color32(byte.Parse(hex.Substring(num, 2), NumberStyles.AllowHexSpecifier), byte.Parse(hex.Substring(num + 2, 2), NumberStyles.AllowHexSpecifier), byte.Parse(hex.Substring(num + 4, 2), NumberStyles.AllowHexSpecifier), byte.MaxValue);
				}
				else if (hex.Length == num + 4)
				{
					color = new Color32(byte.Parse(hex[num].ToString() + hex[num], NumberStyles.AllowHexSpecifier), byte.Parse(hex[num + 1].ToString() + hex[num + 1], NumberStyles.AllowHexSpecifier), byte.Parse(hex[num + 2].ToString() + hex[num + 2], NumberStyles.AllowHexSpecifier), byte.Parse(hex[num + 3].ToString() + hex[num + 3], NumberStyles.AllowHexSpecifier));
				}
				else
				{
					color = new Color32(byte.Parse(hex[num].ToString() + hex[num], NumberStyles.AllowHexSpecifier), byte.Parse(hex[num + 1].ToString() + hex[num + 1], NumberStyles.AllowHexSpecifier), byte.Parse(hex[num + 2].ToString() + hex[num + 2], NumberStyles.AllowHexSpecifier), byte.MaxValue);
				}
				return true;
			}
			color = default(Color32);
			return false;
		}
	}
	[RequireComponent(typeof(BoxSlider), typeof(RawImage))]
	[ExecuteInEditMode]
	public class SVBoxSlider : MonoBehaviour
	{
		public ColorPickerControl picker;

		private BoxSlider slider;

		private RawImage image;

		private float lastH = -1f;

		private bool listen = true;

		public RectTransform RectTransform => base.transform as RectTransform;

		private void Awake()
		{
			slider = GetComponent<BoxSlider>();
			image = GetComponent<RawImage>();
			RegenerateSVTexture();
		}

		private void OnEnable()
		{
			if (Application.isPlaying && picker != null)
			{
				slider.OnValueChanged.AddListener(SliderChanged);
				picker.onHSVChanged.AddListener(HSVChanged);
			}
		}

		private void OnDisable()
		{
			if (picker != null)
			{
				slider.OnValueChanged.RemoveListener(SliderChanged);
				picker.onHSVChanged.RemoveListener(HSVChanged);
			}
		}

		private void OnDestroy()
		{
			if (image.texture != null)
			{
				Object.DestroyImmediate(image.texture);
			}
		}

		private void SliderChanged(float saturation, float value)
		{
			if (listen)
			{
				picker.AssignColor(ColorValues.Saturation, saturation);
				picker.AssignColor(ColorValues.Value, value);
			}
			listen = true;
		}

		private void HSVChanged(float h, float s, float v)
		{
			if (lastH != h)
			{
				lastH = h;
				RegenerateSVTexture();
			}
			if (s != slider.NormalizedValueX)
			{
				listen = false;
				slider.NormalizedValueX = s;
			}
			if (v != slider.NormalizedValueY)
			{
				listen = false;
				slider.NormalizedValueY = v;
			}
		}

		private void RegenerateSVTexture()
		{
			double h = ((picker != null) ? (picker.H * 360f) : 0f);
			if (image.texture != null)
			{
				Object.DestroyImmediate(image.texture);
			}
			Texture2D texture2D = new Texture2D(100, 100)
			{
				hideFlags = HideFlags.DontSave
			};
			for (int i = 0; i < 100; i++)
			{
				Color32[] array = new Color32[100];
				for (int j = 0; j < 100; j++)
				{
					array[j] = HSVUtil.ConvertHsvToRgb(h, (float)i / 100f, (float)j / 100f, 1f);
				}
				texture2D.SetPixels32(i, 0, 1, 100, array);
			}
			texture2D.Apply();
			image.texture = texture2D;
		}
	}
}
namespace UnityEngine.UI.Extensions.Tweens
{
	public struct FloatTween : ITweenValue
	{
		public class FloatTweenCallback : UnityEvent<float>
		{
		}

		public class FloatFinishCallback : UnityEvent
		{
		}

		private float m_StartFloat;

		private float m_TargetFloat;

		private float m_Duration;

		private bool m_IgnoreTimeScale;

		private FloatTweenCallback m_Target;

		private FloatFinishCallback m_Finish;

		public float startFloat
		{
			get
			{
				return m_StartFloat;
			}
			set
			{
				m_StartFloat = value;
			}
		}

		public float targetFloat
		{
			get
			{
				return m_TargetFloat;
			}
			set
			{
				m_TargetFloat = value;
			}
		}

		public float duration
		{
			get
			{
				return m_Duration;
			}
			set
			{
				m_Duration = value;
			}
		}

		public bool ignoreTimeScale
		{
			get
			{
				return m_IgnoreTimeScale;
			}
			set
			{
				m_IgnoreTimeScale = value;
			}
		}

		public void TweenValue(float floatPercentage)
		{
			if (ValidTarget())
			{
				m_Target.Invoke(Mathf.Lerp(m_StartFloat, m_TargetFloat, floatPercentage));
			}
		}

		public void AddOnChangedCallback(UnityAction<float> callback)
		{
			if (m_Target == null)
			{
				m_Target = new FloatTweenCallback();
			}
			m_Target.AddListener(callback);
		}

		public void AddOnFinishCallback(UnityAction callback)
		{
			if (m_Finish == null)
			{
				m_Finish = new FloatFinishCallback();
			}
			m_Finish.AddListener(callback);
		}

		public bool GetIgnoreTimescale()
		{
			return m_IgnoreTimeScale;
		}

		public float GetDuration()
		{
			return m_Duration;
		}

		public bool ValidTarget()
		{
			return m_Target != null;
		}

		public void Finished()
		{
			if (m_Finish != null)
			{
				m_Finish.Invoke();
			}
		}
	}
	internal interface ITweenValue
	{
		bool ignoreTimeScale { get; }

		float duration { get; }

		void TweenValue(float floatPercentage);

		bool ValidTarget();

		void Finished();
	}
	internal class TweenRunner<T> where T : struct, ITweenValue
	{
		protected MonoBehaviour m_CoroutineContainer;

		protected IEnumerator m_Tween;

		private static IEnumerator Start(T tweenInfo)
		{
			if (tweenInfo.ValidTarget())
			{
				float elapsedTime = 0f;
				while (elapsedTime < tweenInfo.duration)
				{
					elapsedTime += (tweenInfo.ignoreTimeScale ? Time.unscaledDeltaTime : Time.deltaTime);
					float floatPercentage = Mathf.Clamp01(elapsedTime / tweenInfo.duration);
					tweenInfo.TweenValue(floatPercentage);
					yield return null;
				}
				tweenInfo.TweenValue(1f);
				tweenInfo.Finished();
			}
		}

		public void Init(MonoBehaviour coroutineContainer)
		{
			m_CoroutineContainer = coroutineContainer;
		}

		public void StartTween(T info)
		{
			if (m_CoroutineContainer == null)
			{
				Debug.LogWarning("Coroutine container not configured... did you forget to call Init?");
				return;
			}
			if (m_Tween != null)
			{
				m_CoroutineContainer.StopCoroutine(m_Tween);
				m_Tween = null;
			}
			if (!m_CoroutineContainer.gameObject.activeInHierarchy)
			{
				info.TweenValue(1f);
				return;
			}
			m_Tween = Start(info);
			m_CoroutineContainer.StartCoroutine(m_Tween);
		}
	}
}
