	[AddComponentMenu("Rewired/Input Manager")]
	[EditorBrowsable(EditorBrowsableState.Never)]
	public sealed class InputManager : InputManager_Base
	{
		private bool ignoreRecompile;

		protected override void OnInitialized()
		{
			SubscribeEvents();
		}

		protected override void OnDeinitialized()
		{
			UnsubscribeEvents();
		}

		protected override void DetectPlatform()
		{
			scriptingBackend = ScriptingBackend.Mono;
			scriptingAPILevel = ScriptingAPILevel.Net20;
			editorPlatform = EditorPlatform.None;
			platform = Rewired.Platforms.Platform.Unknown;
			webplayerPlatform = WebplayerPlatform.None;
			isEditor = false;
			if (SystemInfo.deviceName == null)
			{
				_ = string.Empty;
			}
			if (SystemInfo.deviceModel == null)
			{
				_ = string.Empty;
			}
			platform = Rewired.Platforms.Platform.Windows;
			scriptingBackend = ScriptingBackend.Mono;
			scriptingAPILevel = ScriptingAPILevel.NetStandard20;
		}

		protected override void CheckRecompile()
		{
		}

		protected override IExternalTools GetExternalTools()
		{
			return new ExternalTools();
		}

		private bool CheckDeviceName(string searchPattern, string deviceName, string deviceModel)
		{
			if (!Regex.IsMatch(deviceName, searchPattern, RegexOptions.IgnoreCase))
			{
				return Regex.IsMatch(deviceModel, searchPattern, RegexOptions.IgnoreCase);
			}
			return true;
		}

		private void SubscribeEvents()
		{
			UnsubscribeEvents();
			SceneManager.sceneLoaded += OnSceneLoaded;
		}

		private void UnsubscribeEvents()
		{
			SceneManager.sceneLoaded -= OnSceneLoaded;
		}

		private void OnSceneLoaded(Scene scene, LoadSceneMode mode)
		{
			OnSceneLoaded();
		}
	}
}
namespace Rewired.Localization
{
	[AddComponentMenu("Rewired/Localization/Localized String Provider")]
	public class LocalizedStringProvider : LocalizedStringProviderBase
	{
		[SerializeField]
		[Tooltip("A JSON file containing localizied string key value pairs.")]
		private TextAsset _localizedStringsFile;

		[NonSerialized]
		private Dictionary<string, string> _dictionary = new Dictionary<string, string>();

		[NonSerialized]
		private bool _initialized;

		protected virtual Dictionary<string, string> dictionary
		{
			get
			{
				return _dictionary;
			}
			set
			{
				_dictionary = value;
			}
		}

		public virtual TextAsset localizedStringsFile
		{
			get
			{
				return _localizedStringsFile;
			}
			set
			{
				_localizedStringsFile = value;
				Reload();
			}
		}

		protected override bool initialized => _initialized;

		protected override bool Initialize()
		{
			_initialized = TryLoadLocalizedStringData();
			return _initialized;
		}

		protected virtual bool TryLoadLocalizedStringData()
		{
			_dictionary.Clear();
			if (_localizedStringsFile != null)
			{
				try
				{
					_dictionary = JsonParser.FromJson<Dictionary<string, string>>(_localizedStringsFile.text);
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
				}
			}
			return _dictionary.Count > 0;
		}

		protected override bool TryGetLocalizedString(string key, out string result)
		{
			if (!_initialized)
			{
				result = null;
				return false;
			}
			return _dictionary.TryGetValue(key, out result);
		}
	}
	public abstract class LocalizedStringProviderBase : MonoBehaviour, ILocalizedStringProvider
	{
		[SerializeField]
		[Tooltip("Determines if localized strings should be fetched immediately in bulk when available. If false, strings will be fetched when queried.")]
		private bool _prefetch;

		public virtual bool prefetch
		{
			get
			{
				return _prefetch;
			}
			set
			{
				_prefetch = value;
				if (base.gameObject.activeInHierarchy && base.enabled && ReInput.isReady && ReInput.localization.localizedStringProvider == this)
				{
					ReInput.localization.prefetch = value;
				}
			}
		}

		protected abstract bool initialized { get; }

		protected virtual void OnEnable()
		{
			if (!initialized)
			{
				Initialize();
			}
			TrySetLocalizedStringProvider();
		}

		protected virtual void OnDisable()
		{
			if (ReInput.isReady && ReInput.localization.localizedStringProvider == this)
			{
				ReInput.localization.localizedStringProvider = null;
			}
			ReInput.InitializedEvent -= TrySetLocalizedStringProvider;
		}

		protected virtual void Update()
		{
		}

		protected virtual void TrySetLocalizedStringProvider()
		{
			ReInput.InitializedEvent -= TrySetLocalizedStringProvider;
			ReInput.InitializedEvent += TrySetLocalizedStringProvider;
			if (ReInput.isReady)
			{
				if (!UnityTools.IsNullOrDestroyed(ReInput.localization.localizedStringProvider))
				{
					UnityEngine.Debug.LogWarning("A localized string provider is already set. Only one localized string provider can exist at a time.");
					return;
				}
				ReInput.localization.localizedStringProvider = this;
				ReInput.localization.prefetch = _prefetch;
			}
		}

		protected abstract bool Initialize();

		public virtual void Reload()
		{
			Initialize();
			if (base.gameObject.activeInHierarchy && base.enabled && ReInput.isReady && ReInput.localization.localizedStringProvider == this)
			{
				ReInput.localization.Reload();
			}
		}

		protected abstract bool TryGetLocalizedString(string key, out string result);

		bool ILocalizedStringProvider.TryGetLocalizedString(string key, out string result)
		{
			return TryGetLocalizedString(key, out result);
		}
	}
}
