namespace Rewired.Data
{
	public class UserDataStore_File : UserDataStore_KeyValue
	{
		private sealed class DataStore : IDataStore
		{
			private Dictionary<string, object> _data;

			private readonly string _absFilePath;

			private IDataHandler _dataHandler;

			public DataStore(string fileName, string absDirectory, IDataHandler dataHandler)
			{
				_absFilePath = Path.Combine(absDirectory, fileName);
				if (dataHandler == null)
				{
					throw new ArgumentNullException("dataHandler");
				}
				_dataHandler = dataHandler;
				_data = new Dictionary<string, object>();
				Load();
			}

			public bool TryGetValue(string key, out object value)
			{
				if (string.IsNullOrEmpty(key))
				{
					value = null;
					return false;
				}
				return _data.TryGetValue(key, out value);
			}

			public bool SetValue(string key, object value)
			{
				if (string.IsNullOrEmpty(key))
				{
					return false;
				}
				_data[key] = value;
				return true;
			}

			public bool Save()
			{
				try
				{
					return _dataHandler.Save(_absFilePath, JsonWriter.ToJson(_data));
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
					return false;
				}
			}

			public bool Load()
			{
				try
				{
					string data;
					bool num = _dataHandler.Load(_absFilePath, out data);
					if (num)
					{
						Dictionary<string, object> dictionary = JsonParser.FromJson<Dictionary<string, object>>(data);
						if (dictionary == null)
						{
							dictionary = new Dictionary<string, object>();
						}
						_data = dictionary;
					}
					return num;
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
					return false;
				}
			}

			public bool Clear()
			{
				bool result;
				try
				{
					result = _dataHandler.Clear(_absFilePath);
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
					result = false;
				}
				_data.Clear();
				return result;
			}
		}

		private sealed class LocalFileDataHandler : IDataHandler
		{
			private readonly Func<DataFormat> _dataFormatDelegate;

			private readonly Codec _codec;

			public LocalFileDataHandler(Func<DataFormat> dataFormatDelegate, Codec codec)
			{
				if (dataFormatDelegate == null)
				{
					throw new ArgumentNullException("dataFormatDelegate");
				}
				_dataFormatDelegate = dataFormatDelegate;
				if (codec == null)
				{
					codec = new UTF8Text();
				}
				_codec = codec;
			}

			public bool Load(string absoluteFilePath, out string data)
			{
				data = null;
				if (string.IsNullOrEmpty(absoluteFilePath))
				{
					return false;
				}
				if (!File.Exists(absoluteFilePath))
				{
					return false;
				}
				try
				{
					switch (_dataFormatDelegate())
					{
					case DataFormat.Binary:
					{
						byte[] array = File.ReadAllBytes(absoluteFilePath);
						data = _codec.Decode(array);
						return array != null && array.Length != 0;
					}
					case DataFormat.Text:
						data = File.ReadAllText(absoluteFilePath);
						return !string.IsNullOrEmpty(data);
					default:
						throw new NotImplementedException();
					}
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
					return false;
				}
			}

			public bool Save(string absoluteFilePath, string data)
			{
				if (string.IsNullOrEmpty(absoluteFilePath))
				{
					return false;
				}
				try
				{
					string directoryName = Path.GetDirectoryName(absoluteFilePath);
					if (!string.IsNullOrEmpty(directoryName) && !Directory.Exists(directoryName))
					{
						Directory.CreateDirectory(directoryName);
					}
					switch (_dataFormatDelegate())
					{
					case DataFormat.Binary:
						File.WriteAllBytes(absoluteFilePath, _codec.Encode(data));
						break;
					case DataFormat.Text:
						File.WriteAllText(absoluteFilePath, data);
						break;
					default:
						throw new NotImplementedException();
					}
					return true;
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
					return false;
				}
			}

			public bool Clear(string absoluteFilePath)
			{
				if (string.IsNullOrEmpty(absoluteFilePath))
				{
					return false;
				}
				try
				{
					if (File.Exists(absoluteFilePath))
					{
						File.Delete(absoluteFilePath);
						return true;
					}
				}
				catch (Exception message)
				{
					UnityEngine.Debug.LogError(message);
				}
				return false;
			}
		}

		private abstract class Codec
		{
			public abstract byte[] Encode(string @string);

			public abstract string Decode(byte[] data);
		}

		private sealed class UTF8Text : Codec
		{
			public override byte[] Encode(string @string)
			{
				return Encoding.UTF8.GetBytes(@string);
			}

			public override string Decode(byte[] data)
			{
				return Encoding.UTF8.GetString(data);
			}
		}

		private sealed class CLZF2 : Codec
		{
			private readonly Rewired.Utils.Libraries.CLZF2.CLZF2 _cLZF2;

			public CLZF2()
			{
				_cLZF2 = new Rewired.Utils.Libraries.CLZF2.CLZF2();
			}

			public override byte[] Encode(string @string)
			{
				return _cLZF2.Compress(Encoding.UTF8.GetBytes(@string));
			}

			public override string Decode(byte[] data)
			{
				return Encoding.UTF8.GetString(_cLZF2.Decompress(data));
			}
		}

		public interface IDataHandler
		{
			bool Load(string absoluteFilePath, out string data);

			bool Save(string absoluteFilePath, string data);

			bool Clear(string absoluteFilePath);
		}

		public enum DataFormat
		{
			Text,
			Binary
		}

		private static readonly string thisScriptName = typeof(UserDataStore_File).Name;

		private const string logPrefix = "Rewired: ";

		private const string defaultExtensionText = ".json";

		private const string defaultExtensionBinary = ".bin";

		private const string defaultFileName = "RewiredSaveData.json";

		[Tooltip("The data file name. Changing this will make saved data already stored with the old file name no longer accessible.")]
		[SerializeField]
		private string _fileName = "RewiredSaveData.json";

		[Tooltip("Determines if the file should be stored as binary or text. Changing this will make saved data already stored no longer accessible.")]
		[SerializeField]
		private DataFormat _dataFormat;

		[NonSerialized]
		private string __directory;

		[NonSerialized]
		private DataStore _dataStore;

		[NonSerialized]
		private IDataHandler __dataHandler;

		[NonSerialized]
		private bool _initialized;

		public string directory
		{
			get
			{
				if (string.IsNullOrEmpty(__directory))
				{
					return __directory = Application.persistentDataPath;
				}
				return __directory;
			}
			set
			{
				__directory = value;
				if (_initialized)
				{
					OnDataSourceChanged();
				}
			}
		}

		public string fileName
		{
			get
			{
				return _fileName;
			}
			set
			{
				_fileName = value;
				if (_initialized)
				{
					OnDataSourceChanged();
				}
			}
		}

		public DataFormat dataFormat
		{
			get
			{
				return _dataFormat;
			}
			set
			{
				_dataFormat = value;
				if (_initialized)
				{
					OnDataSourceChanged();
				}
			}
		}

		protected IDataHandler dataHandler
		{
			get
			{
				if (__dataHandler == null)
				{
					return __dataHandler = new LocalFileDataHandler(() => _dataFormat, new CLZF2());
				}
				return __dataHandler;
			}
			set
			{
				__dataHandler = value;
				if (_initialized)
				{
					OnDataSourceChanged();
				}
			}
		}

		protected override IDataStore dataStore => _dataStore;

		protected virtual void SetInitialValues()
		{
		}

		protected override void OnInitialize()
		{
			SetInitialValues();
			_initialized = true;
			OnDataSourceChanged();
			base.OnInitialize();
		}

		private void OnDataSourceChanged()
		{
			_dataStore = new DataStore((!string.IsNullOrEmpty(_fileName)) ? _fileName : "RewiredSaveData.json", directory, dataHandler);
		}
	}
	public abstract class UserDataStore_KeyValue : UserDataStore
	{
		private class ControllerAssignmentSaveInfo
		{
			public class PlayerInfo
			{
				public int id;

				public bool hasKeyboard;

				public bool hasMouse;

				public JoystickInfo[] joysticks;

				public int joystickCount
				{
					get
					{
						if (joysticks == null)
						{
							return 0;
						}
						return joysticks.Length;
					}
				}

				public int IndexOfJoystick(int joystickId)
				{
					for (int i = 0; i < joystickCount; i++)
					{
						if (joysticks[i] != null && joysticks[i].id == joystickId)
						{
							return i;
						}
					}
					return -1;
				}

				public bool ContainsJoystick(int joystickId)
				{
					return IndexOfJoystick(joystickId) >= 0;
				}
			}

			public class JoystickInfo
			{
				public Guid instanceGuid;

				public string hardwareIdentifier;

				public int id;
			}

			public PlayerInfo[] players;

			public int playerCount
			{
				get
				{
					if (players == null)
					{
						return 0;
					}
					return players.Length;
				}
			}

			public ControllerAssignmentSaveInfo()
			{
			}

			public ControllerAssignmentSaveInfo(int playerCount)
			{
				players = new PlayerInfo[playerCount];
				for (int i = 0; i < playerCount; i++)
				{
					players[i] = new PlayerInfo();
				}
			}

			public int IndexOfPlayer(int playerId)
			{
				for (int i = 0; i < playerCount; i++)
				{
					if (players[i] != null && players[i].id == playerId)
					{
						return i;
					}
				}
				return -1;
			}

			public bool ContainsPlayer(int playerId)
			{
				return IndexOfPlayer(playerId) >= 0;
			}
		}

		private class JoystickAssignmentHistoryInfo
		{
			public readonly Joystick joystick;

			public readonly int oldJoystickId;

			public JoystickAssignmentHistoryInfo(Joystick joystick, int oldJoystickId)
			{
				if (joystick == null)
				{
					throw new ArgumentNullException("joystick");
				}
				this.joystick = joystick;
				this.oldJoystickId = oldJoystickId;
			}
		}

		protected interface IDataStore
		{
			bool Save();

			bool Load();

			bool Clear();

			bool TryGetValue(string key, out object result);

			bool SetValue(string key, object value);
		}

		[Serializable]
		protected class ControllerElementByRoleMap
		{
			[Serializable]
			public struct Entry
			{
				public int actionId;

				public ControllerElementType elementType;

				public AxisRange axisRange;

				public bool invert;

				public Pole axisContribution;

				public bool TryGetElementAssignment(ControllerType controllerType, Controller.Element targetElement, out ElementAssignment assignment)
				{
					if (targetElement.type == elementType)
					{
						assignment = ElementAssignment.CompleteAssignment(controllerType, targetElement.type, targetElement.elementIdentifier.id, axisRange, KeyCode.None, ModifierKeyFlags.None, actionId, axisContribution, invert);
						return true;
					}
					switch (elementType)
					{
					case ControllerElementType.Axis:
						if (targetElement.type == ControllerElementType.Button)
						{
							Pole pole = axisContribution;
							if (axisRange == AxisRange.Full && invert)
							{
								pole = Pole.Negative;
							}
							assignment = ElementAssignment.CompleteAssignment(controllerType, targetElement.type, targetElement.elementIdentifier.id, AxisRange.Full, KeyCode.None, ModifierKeyFlags.None, actionId, pole, invert: false);
							return true;
						}
						assignment = default(ElementAssignment);
						return false;
					case ControllerElementType.Button:
						if (targetElement.type == ControllerElementType.Axis)
						{
							assignment = ElementAssignment.CompleteAssignment(controllerType, targetElement.type, targetElement.elementIdentifier.id, AxisRange.Positive, KeyCode.None, ModifierKeyFlags.None, actionId, axisContribution, invert: false);
							return true;
						}
						assignment = default(ElementAssignment);
						return false;
					default:
						assignment = default(ElementAssignment);
						return false;
					}
				}

				public override string ToString()
				{
					StringBuilder stringBuilder = new StringBuilder();
					stringBuilder.Append("actionId: ");
					stringBuilder.Append(actionId);
					stringBuilder.Append("\nelementType: ");
					stringBuilder.Append(elementType);
					stringBuilder.Append("\naxisRange: ");
					stringBuilder.Append(axisRange);
					stringBuilder.Append("\ninvert: ");
					stringBuilder.Append(invert);
					stringBuilder.Append("\naxisContribution: ");
					stringBuilder.Append(axisContribution);
					return stringBuilder.ToString();
				}
			}

			[DoNotSerialize]
			public string role;

			public List<Entry> data;

			[Preserve]
			public ControllerElementByRoleMap()
			{
				data = new List<Entry>();
			}

			public void Add(ActionElementMap elementMap)
			{
				data.Add(new Entry
				{
					actionId = elementMap.actionId,
					elementType = elementMap.elementType,
					axisRange = elementMap.axisRange,
					invert = elementMap.invert,
					axisContribution = elementMap.axisContribution
				});
			}

			public override string ToString()
			{
				StringBuilder stringBuilder = new StringBuilder();
				stringBuilder.Append("role: ");
				stringBuilder.Append(role);
				stringBuilder.Append("\nentries:");
				stringBuilder.Append((data != null) ? data.Count : 0);
				stringBuilder.Append("\n");
				if (data != null)
				{
					for (int i = 0; i < data.Count; i++)
					{
						stringBuilder.Append("Entry[");
						stringBuilder.Append(i);
						stringBuilder.Append("]:\n");
						stringBuilder.Append(data[i]);
					}
				}
				return stringBuilder.ToString();
			}

			public string ToJson()
			{
				return JsonWriter.ToJson(this);
			}

			public static ControllerElementByRoleMap FromJson(string role, string json)
			{
				ControllerElementByRoleMap controllerElementByRoleMap = JsonParser.FromJson<ControllerElementByRoleMap>(json);
				if (controllerElementByRoleMap != null)
				{
					controllerElementByRoleMap.role = role;
				}
				return controllerElementByRoleMap;
			}
		}

