	public abstract class GlyphOrTextBase<TGlyphComponent, TGlyphGraphic, TTextComponent> : GlyphOrTextBase where TGlyphComponent : Behaviour where TGlyphGraphic : class where TTextComponent : Behaviour
	{
		[SerializeField]
		private TTextComponent _textComponent;

		[SerializeField]
		private TGlyphComponent _glyphComponent;

		public TTextComponent textComponent
		{
			get
			{
				return _textComponent;
			}
			set
			{
				_textComponent = value;
			}
		}

		public TGlyphComponent glyphComponent
		{
			get
			{
				return _glyphComponent;
			}
			set
			{
				_glyphComponent = value;
			}
		}

		protected abstract TGlyphGraphic glyphGraphic { get; set; }

		public override void ShowText(string text)
		{
			if (_textComponent == null)
			{
				return;
			}
			if (!string.Equals(textString, text, StringComparison.Ordinal))
			{
				textString = text;
			}
			if (!_textComponent.gameObject.activeSelf)
			{
				_textComponent.gameObject.SetActive(value: true);
				if (!base.gameObject.activeSelf)
				{
					base.gameObject.SetActive(value: true);
				}
			}
			Hide(TypeFlags.Glyph);
		}

		public override void ShowGlyph(object glyph)
		{
			if (glyph != null && !(glyph is TGlyphGraphic))
			{
				UnityEngine.Debug.LogError("Rewired: Glyph does not implement " + typeof(TGlyphGraphic).Name + ".");
			}
			else
			{
				ShowGlyph((TGlyphGraphic)glyph);
			}
		}

		public virtual void ShowGlyph(TGlyphGraphic glyph)
		{
			if (_glyphComponent == null)
			{
				return;
			}
			if (glyphGraphic != glyph)
			{
				glyphGraphic = glyph;
			}
			if (!_glyphComponent.gameObject.activeSelf)
			{
				_glyphComponent.gameObject.SetActive(value: true);
				if (!base.gameObject.activeSelf)
				{
					base.gameObject.SetActive(value: true);
				}
			}
			Hide(TypeFlags.Text);
		}

		protected override void Hide(TypeFlags flags)
		{
			if (_textComponent != null && (flags & TypeFlags.Text) != TypeFlags.None && _textComponent.gameObject.activeSelf)
			{
				_textComponent.gameObject.SetActive(value: false);
			}
			if (_glyphComponent != null && (flags & TypeFlags.Glyph) != TypeFlags.None && _glyphComponent.gameObject.activeSelf)
			{
				_glyphComponent.gameObject.SetActive(value: false);
			}
			if ((_glyphComponent == null || !_glyphComponent.gameObject.activeSelf) && (_textComponent == null || !_textComponent.gameObject.activeSelf))
			{
				base.gameObject.SetActive(value: false);
			}
		}
	}
	public class GlyphProvider : MonoBehaviour, IGlyphProvider
	{
		[SerializeField]
		[Tooltip("Determines if glyphs should be fetched immediately in bulk when available. If false, glyphs will be fetched when queried.")]
		private bool _prefetch;

		[SerializeField]
		[Tooltip("A list of glyph set collections. At least one collection must be assigned.")]
		private List<GlyphSetCollection> _glyphSetCollections;

		[NonSerialized]
		private readonly Dictionary<string, object> _glyphs = new Dictionary<string, object>();

		[NonSerialized]
		private bool _initialized;

		public bool prefetch
		{
			get
			{
				return _prefetch;
			}
			set
			{
				_prefetch = value;
				if (base.isActiveAndEnabled && ReInput.isReady && ReInput.glyphs.glyphProvider == this)
				{
					ReInput.glyphs.prefetch = value;
				}
			}
		}

		public List<GlyphSetCollection> glyphSetCollections
		{
			get
			{
				return _glyphSetCollections;
			}
			set
			{
				_glyphSetCollections = value;
				Reload();
			}
		}

		protected Dictionary<string, object> glyphs => _glyphs;

		protected virtual void OnEnable()
		{
			if (!_initialized)
			{
				Initialize();
			}
			TrySetGlyphProvider();
		}

		protected virtual void OnDisable()
		{
			if (ReInput.isReady && ReInput.glyphs.glyphProvider == this)
			{
				ReInput.glyphs.glyphProvider = null;
			}
			ReInput.InitializedEvent -= TrySetGlyphProvider;
		}

		protected virtual void Update()
		{
		}

		protected virtual void TrySetGlyphProvider()
		{
			ReInput.InitializedEvent -= TrySetGlyphProvider;
			ReInput.InitializedEvent += TrySetGlyphProvider;
			if (ReInput.isReady)
			{
				if (!UnityTools.IsNullOrDestroyed(ReInput.glyphs.glyphProvider))
				{
					UnityEngine.Debug.LogWarning("Rewired: A glyph provider is already set. Only one glyph provider can exist at a time.");
					return;
				}
				ReInput.glyphs.glyphProvider = this;
				ReInput.glyphs.prefetch = _prefetch;
			}
		}

		protected virtual bool Initialize()
		{
			_initialized = false;
			if (_glyphSetCollections == null)
			{
				return false;
			}
			_glyphs.Clear();
			StringBuilder stringBuilder = new StringBuilder();
			for (int i = 0; i < _glyphSetCollections.Count; i++)
			{
				GlyphSetCollection glyphSetCollection = _glyphSetCollections[i];
				if (glyphSetCollection == null)
				{
					continue;
				}
				foreach (GlyphSet item in glyphSetCollection.IterateSetsRecursively())
				{
					if (item == null || item.baseKeys == null)
					{
						continue;
					}
					int num = item.baseKeys.Length;
					for (int j = 0; j < num; j++)
					{
						if (string.IsNullOrEmpty(item.baseKeys[j]))
						{
							continue;
						}
						int glyphCount = item.glyphCount;
						for (int k = 0; k < glyphCount; k++)
						{
							GlyphSet.EntryBase entry = item.GetEntry(k);
							if (entry != null && !string.IsNullOrEmpty(entry.key) && entry.GetValue() != null)
							{
								stringBuilder.Append(item.baseKeys[j]);
								stringBuilder.Append('/');
								stringBuilder.Append(entry.key);
								string text = stringBuilder.ToString();
								stringBuilder.Length = 0;
								if (_glyphs.ContainsKey(text))
								{
									UnityEngine.Debug.LogError("Rewired: Duplicate glyph key found: " + text);
								}
								else
								{
									_glyphs.Add(text, entry.GetValue());
								}
							}
						}
					}
				}
			}
			_initialized = true;
			return true;
		}

		public void Reload()
		{
			Initialize();
			if (base.isActiveAndEnabled && ReInput.isReady && ReInput.glyphs.glyphProvider == this)
			{
				ReInput.glyphs.Reload();
			}
		}

		bool IGlyphProvider.TryGetGlyph(string key, out object result)
		{
			if (!_initialized)
			{
				result = null;
				return false;
			}
			return _glyphs.TryGetValue(key, out result);
		}
	}
