			public abstract class Pool
			{
				public abstract bool Return(Tag obj);
			}

			public sealed class Pool<T> : Pool where T : Tag, new()
			{
				private readonly List<T> _list;

				public Pool()
				{
					_list = new List<T>();
				}

				public T Get()
				{
					T val;
					if (_list.Count == 0)
					{
						val = new T();
						if (val != null)
						{
							val.pool = this;
						}
						return val;
					}
					int index = _list.Count - 1;
					val = _list[index];
					_list.RemoveAt(index);
					return val;
				}

				public override bool Return(Tag obj)
				{
					if (!(obj is T val) || val.pool != this)
					{
						return false;
					}
					val.Clear();
					if (_list.Contains(val))
					{
						return false;
					}
					_list.Add(val);
					return true;
				}
			}

			public readonly TagType tagType;

			private Pool _pool;

			protected Pool pool
			{
				get
				{
					return _pool;
				}
				set
				{
					_pool = value;
				}
			}

			protected Tag(TagType tagType)
			{
				this.tagType = tagType;
			}

			public void ReturnToPool()
			{
				if (_pool != null)
				{
					_pool.Return(this);
				}
			}

			protected abstract void Clear();

			public static void Clear(List<Tag> list)
			{
				int count = list.Count;
				for (int i = 0; i < count; i++)
				{
					if (list[i] != null)
					{
						list[i].ReturnToPool();
					}
				}
				list.Clear();
			}
		}

