		public override void SetCancelCallback(System.Action cancelCallback)
		{
			base.SetCancelCallback(cancelCallback);
			if (cancelCallback == null || slider == null)
			{
				return;
			}
			if (slider is ICustomSelectable)
			{
				(slider as ICustomSelectable).CancelEvent += delegate
				{
					cancelCallback();
				};
				return;
			}
			EventTrigger eventTrigger = slider.GetComponent<EventTrigger>();
			if (eventTrigger == null)
			{
				eventTrigger = slider.gameObject.AddComponent<EventTrigger>();
			}
			EventTrigger.Entry entry = new EventTrigger.Entry();
			entry.callback = new EventTrigger.TriggerEvent();
			entry.eventID = EventTriggerType.Cancel;
			entry.callback.AddListener(delegate
			{
				cancelCallback();
			});
			if (eventTrigger.triggers == null)
			{
				eventTrigger.triggers = new List<EventTrigger.Entry>();
			}
			eventTrigger.triggers.Add(entry);
		}
	}
	public static class UITools
	{
		public static GameObject InstantiateGUIObject<T>(GameObject prefab, Transform parent, string name) where T : UnityEngine.Component
		{
			GameObject gameObject = InstantiateGUIObject_Pre<T>(prefab, parent, name);
			if (gameObject == null)
			{
				return null;
			}
			RectTransform component = gameObject.GetComponent<RectTransform>();
			if (component == null)
			{
				UnityEngine.Debug.LogError(name + " prefab is missing RectTransform component!");
			}
			else
			{
				component.localScale = Vector3.one;
			}
			return gameObject;
		}

		public static GameObject InstantiateGUIObject<T>(GameObject prefab, Transform parent, string name, Vector2 pivot, Vector2 anchorMin, Vector2 anchorMax, Vector2 anchoredPosition) where T : UnityEngine.Component
		{
			GameObject gameObject = InstantiateGUIObject_Pre<T>(prefab, parent, name);
			if (gameObject == null)
			{
				return null;
			}
			RectTransform component = gameObject.GetComponent<RectTransform>();
			if (component == null)
			{
				UnityEngine.Debug.LogError(name + " prefab is missing RectTransform component!");
			}
			else
			{
				component.localScale = Vector3.one;
				component.pivot = pivot;
				component.anchorMin = anchorMin;
				component.anchorMax = anchorMax;
				component.anchoredPosition = anchoredPosition;
			}
			return gameObject;
		}

		private static GameObject InstantiateGUIObject_Pre<T>(GameObject prefab, Transform parent, string name) where T : UnityEngine.Component
		{
			if (prefab == null)
			{
				UnityEngine.Debug.LogError(name + " prefab is null!");
				return null;
			}
			GameObject gameObject = UnityEngine.Object.Instantiate(prefab);
			if (!string.IsNullOrEmpty(name))
			{
				gameObject.name = name;
			}
			T component = gameObject.GetComponent<T>();
			if (component == null)
			{
				UnityEngine.Debug.LogError(name + " prefab is missing the " + component.GetType().ToString() + " component!");
				return null;
			}
			if (parent != null)
			{
				gameObject.transform.SetParent(parent, worldPositionStays: false);
			}
			return gameObject;
		}

		public static Vector3 GetPointOnRectEdge(RectTransform rectTransform, Vector2 dir)
		{
			if (rectTransform == null)
			{
				return Vector3.zero;
			}
			if (dir != Vector2.zero)
			{
				dir /= Mathf.Max(Mathf.Abs(dir.x), Mathf.Abs(dir.y));
			}
			Rect rect = rectTransform.rect;
			dir = rect.center + Vector2.Scale(rect.size, dir * 0.5f);
			return dir;
		}

		public static Rect GetWorldSpaceRect(RectTransform rt)
		{
			if (rt == null)
			{
				return default(Rect);
			}
			Rect rect = rt.rect;
			Vector2 vector = rt.TransformPoint(new Vector2(rect.xMin, rect.yMin));
			Vector2 vector2 = rt.TransformPoint(new Vector2(rect.xMin, rect.yMax));
			Vector2 vector3 = rt.TransformPoint(new Vector2(rect.xMax, rect.yMin));
			return new Rect(vector.x, vector.y, vector3.x - vector.x, vector2.y - vector.y);
		}

		public static Rect TransformRectTo(Transform from, Transform to, Rect rect)
		{
			Vector3 position;
			Vector3 position2;
			Vector3 position3;
			if (from != null)
			{
				position = from.TransformPoint(new Vector2(rect.xMin, rect.yMin));
				position2 = from.TransformPoint(new Vector2(rect.xMin, rect.yMax));
				position3 = from.TransformPoint(new Vector2(rect.xMax, rect.yMin));
			}
			else
			{
				position = new Vector2(rect.xMin, rect.yMin);
				position2 = new Vector2(rect.xMin, rect.yMax);
				position3 = new Vector2(rect.xMax, rect.yMin);
			}
			if (to != null)
			{
				position = to.InverseTransformPoint(position);
				position2 = to.InverseTransformPoint(position2);
				position3 = to.InverseTransformPoint(position3);
			}
			return new Rect(position.x, position.y, position3.x - position.x, position.y - position2.y);
		}

		public static Rect InvertY(Rect rect)
		{
			return new Rect(rect.xMin, rect.yMin, rect.width, 0f - rect.height);
		}

		public static void SetInteractable(Selectable selectable, bool state, bool playTransition)
		{
			if (selectable == null)
			{
				return;
			}
			if (!playTransition)
			{
				if (selectable.transition == Selectable.Transition.ColorTint)
				{
					ColorBlock colors = selectable.colors;
					float fadeDuration = colors.fadeDuration;
					colors.fadeDuration = 0f;
					selectable.colors = colors;
					selectable.interactable = state;
					colors.fadeDuration = fadeDuration;
					selectable.colors = colors;
				}
				else
				{
					selectable.interactable = state;
				}
			}
			else
			{
				selectable.interactable = state;
			}
		}
	}
	[AddComponentMenu("")]
	[RequireComponent(typeof(CanvasGroup))]
	public class Window : MonoBehaviour
	{
		public class Timer
		{
			private bool _started;

			private float end;

			public bool started => _started;

			public bool finished
			{
				get
				{
					if (!started)
					{
						return false;
					}
					if (Time.realtimeSinceStartup < end)
					{
						return false;
					}
					_started = false;
					return true;
				}
			}

			public float remaining
			{
				get
				{
					if (!_started)
					{
						return 0f;
					}
					return end - Time.realtimeSinceStartup;
				}
			}

			public void Start(float length)
			{
				end = Time.realtimeSinceStartup + length;
				_started = true;
			}

			public void Stop()
			{
				_started = false;
			}
		}

		public Image backgroundImage;

		public GameObject content;

		private bool _initialized;

		private int _id = -1;

		private RectTransform _rectTransform;

		private Text _titleText;

		private List<Text> _contentText;

		private GameObject _defaultUIElement;

		private Action<int> _updateCallback;

		private Func<int, bool> _isFocusedCallback;

		private Timer _timer;

		private CanvasGroup _canvasGroup;

		public UnityAction cancelCallback;

		private GameObject lastUISelection;

		public bool hasFocus
		{
			get
			{
				if (_isFocusedCallback == null)
				{
					return false;
				}
				return _isFocusedCallback(_id);
			}
		}

		public int id => _id;

		public RectTransform rectTransform
		{
			get
			{
				if (_rectTransform == null)
				{
					_rectTransform = base.gameObject.GetComponent<RectTransform>();
				}
				return _rectTransform;
			}
		}

		public Text titleText => _titleText;

		public List<Text> contentText => _contentText;

		public GameObject defaultUIElement
		{
			get
			{
				return _defaultUIElement;
			}
			set
			{
				_defaultUIElement = value;
			}
		}

		public Action<int> updateCallback
		{
			get
			{
				return _updateCallback;
			}
			set
			{
				_updateCallback = value;
			}
		}

		public Timer timer => _timer;

		public int width
		{
			get
			{
				return (int)rectTransform.sizeDelta.x;
			}
			set
			{
				Vector2 sizeDelta = rectTransform.sizeDelta;
				sizeDelta.x = value;
				rectTransform.sizeDelta = sizeDelta;
			}
		}

		public int height
		{
			get
			{
				return (int)rectTransform.sizeDelta.y;
			}
			set
			{
				Vector2 sizeDelta = rectTransform.sizeDelta;
				sizeDelta.y = value;
				rectTransform.sizeDelta = sizeDelta;
			}
		}

		protected bool initialized => _initialized;

		private void OnEnable()
		{
			StartCoroutine("OnEnableAsync");
		}

		protected virtual void Update()
		{
			if (_initialized && hasFocus)
			{
				CheckUISelection();
				if (_updateCallback != null)
				{
					_updateCallback(_id);
				}
			}
		}

		public virtual void Initialize(int id, Func<int, bool> isFocusedCallback)
		{
			if (_initialized)
			{
				UnityEngine.Debug.LogError("Window is already initialized!");
				return;
			}
			_id = id;
			_isFocusedCallback = isFocusedCallback;
			_timer = new Timer();
			_contentText = new List<Text>();
			_canvasGroup = GetComponent<CanvasGroup>();
			_initialized = true;
		}

		public void SetSize(int width, int height)
		{
			rectTransform.sizeDelta = new Vector2(width, height);
		}

		public void CreateTitleText(GameObject prefab, Vector2 offset)
		{
			CreateText(prefab, ref _titleText, "Title Text", UIPivot.TopCenter, UIAnchor.TopHStretch, offset);
		}

		public void CreateTitleText(GameObject prefab, Vector2 offset, string text)
		{
			CreateTitleText(prefab, offset);
			SetTitleText(text);
		}

		public void AddContentText(GameObject prefab, UIPivot pivot, UIAnchor anchor, Vector2 offset)
		{
			Text textComponent = null;
			CreateText(prefab, ref textComponent, "Content Text", pivot, anchor, offset);
			_contentText.Add(textComponent);
		}

		public void AddContentText(GameObject prefab, UIPivot pivot, UIAnchor anchor, Vector2 offset, string text)
		{
			AddContentText(prefab, pivot, anchor, offset);
			SetContentText(text, _contentText.Count - 1);
		}

		public void AddContentImage(GameObject prefab, UIPivot pivot, UIAnchor anchor, Vector2 offset)
		{
			CreateImage(prefab, "Image", pivot, anchor, offset);
		}

		public void AddContentImage(GameObject prefab, UIPivot pivot, UIAnchor anchor, Vector2 offset, string text)
		{
			AddContentImage(prefab, pivot, anchor, offset);
		}

		public void CreateButton(GameObject prefab, UIPivot pivot, UIAnchor anchor, Vector2 offset, string buttonText, UnityAction confirmCallback, UnityAction cancelCallback, bool setDefault)
		{
			if (prefab == null)
			{
				return;
			}
			ButtonInfo buttonInfo;
			GameObject gameObject = CreateButton(prefab, "Button", anchor, pivot, offset, out buttonInfo);
			if (!(gameObject == null))
			{
				Button component = gameObject.GetComponent<Button>();
				if (confirmCallback != null)
				{
					component.onClick.AddListener(confirmCallback);
				}
				CustomButton customButton = component as CustomButton;
				if (cancelCallback != null && customButton != null)
				{
					customButton.CancelEvent += cancelCallback;
				}
				if (buttonInfo.text != null)
				{
					buttonInfo.text.text = buttonText;
				}
				if (setDefault)
				{
					_defaultUIElement = gameObject;
				}
			}
		}

		public string GetTitleText(string text)
		{
			if (_titleText == null)
			{
				return string.Empty;
			}
			return _titleText.text;
		}

		public void SetTitleText(string text)
		{
			if (!(_titleText == null))
			{
				_titleText.text = text;
			}
		}

		public string GetContentText(int index)
		{
			if (_contentText == null || _contentText.Count <= index || _contentText[index] == null)
			{
				return string.Empty;
			}
			return _contentText[index].text;
		}

		public float GetContentTextHeight(int index)
		{
			if (_contentText == null || _contentText.Count <= index || _contentText[index] == null)
			{
				return 0f;
			}
			return _contentText[index].rectTransform.sizeDelta.y;
		}

		public void SetContentText(string text, int index)
		{
			if (_contentText != null && _contentText.Count > index && !(_contentText[index] == null))
			{
				_contentText[index].text = text;
			}
		}

		public void SetUpdateCallback(Action<int> callback)
		{
			updateCallback = callback;
		}

		public virtual void TakeInputFocus()
		{
			if (!(EventSystem.current == null))
			{
				EventSystem.current.SetSelectedGameObject(_defaultUIElement);
				Enable();
			}
		}

		public virtual void Enable()
		{
			_canvasGroup.interactable = true;
		}

		public virtual void Disable()
		{
			_canvasGroup.interactable = false;
		}

		public virtual void Cancel()
		{
			if (initialized && cancelCallback != null)
			{
				cancelCallback();
			}
		}

		private void CreateText(GameObject prefab, ref Text textComponent, string name, UIPivot pivot, UIAnchor anchor, Vector2 offset)
		{
			if (prefab == null || content == null)
			{
				return;
			}
			if (textComponent != null)
			{
				UnityEngine.Debug.LogError("Window already has " + name + "!");
				return;
			}
			GameObject gameObject = UITools.InstantiateGUIObject<Text>(prefab, content.transform, name, pivot, anchor.min, anchor.max, offset);
			if (!(gameObject == null))
			{
				textComponent = gameObject.GetComponent<Text>();
			}
		}

		private void CreateImage(GameObject prefab, string name, UIPivot pivot, UIAnchor anchor, Vector2 offset)
		{
			if (!(prefab == null) && !(content == null))
			{
				UITools.InstantiateGUIObject<Image>(prefab, content.transform, name, pivot, anchor.min, anchor.max, offset);
			}
		}

		private GameObject CreateButton(GameObject prefab, string name, UIAnchor anchor, UIPivot pivot, Vector2 offset, out ButtonInfo buttonInfo)
		{
			buttonInfo = null;
			if (prefab == null)
			{
				return null;
			}
			GameObject gameObject = UITools.InstantiateGUIObject<ButtonInfo>(prefab, content.transform, name, pivot, anchor.min, anchor.max, offset);
			if (gameObject == null)
			{
				return null;
			}
			buttonInfo = gameObject.GetComponent<ButtonInfo>();
			if (gameObject.GetComponent<Button>() == null)
			{
				UnityEngine.Debug.Log("Button prefab is missing Button component!");
				return null;
			}
			if (buttonInfo == null)
			{
				UnityEngine.Debug.Log("Button prefab is missing ButtonInfo component!");
				return null;
			}
			return gameObject;
		}

		private IEnumerator OnEnableAsync()
		{
			yield return 1;
			if (!(EventSystem.current == null))
			{
				if (defaultUIElement != null)
				{
					EventSystem.current.SetSelectedGameObject(defaultUIElement);
				}
				else
				{
					EventSystem.current.SetSelectedGameObject(null);
				}
			}
		}

		private void CheckUISelection()
		{
			if (hasFocus && !(EventSystem.current == null))
			{
				if (EventSystem.current.currentSelectedGameObject == null)
				{
					RestoreDefaultOrLastUISelection();
				}
				lastUISelection = EventSystem.current.currentSelectedGameObject;
			}
		}

		private void RestoreDefaultOrLastUISelection()
		{
			if (hasFocus)
			{
				if (lastUISelection == null || !lastUISelection.activeInHierarchy)
				{
					SetUISelection(_defaultUIElement);
				}
				else
				{
					SetUISelection(lastUISelection);
				}
			}
		}

		private void SetUISelection(GameObject selection)
		{
			if (!(EventSystem.current == null))
			{
				EventSystem.current.SetSelectedGameObject(selection);
			}
		}
	}
}
namespace Rewired.Demos
{
	[AddComponentMenu("")]
	public class ControlMapperDemoMessage : MonoBehaviour
	{
		public ControlMapper controlMapper;

		public Selectable defaultSelectable;

		private void Awake()
		{
			if (controlMapper != null)
			{
				controlMapper.ScreenClosedEvent += OnControlMapperClosed;
				controlMapper.ScreenOpenedEvent += OnControlMapperOpened;
			}
		}

		private void Start()
		{
			SelectDefault();
		}

		private void OnControlMapperClosed()
		{
			base.gameObject.SetActive(value: true);
			StartCoroutine(SelectDefaultDeferred());
		}

		private void OnControlMapperOpened()
		{
			base.gameObject.SetActive(value: false);
		}

		private void SelectDefault()
		{
			if (!(EventSystem.current == null) && defaultSelectable != null)
			{
				EventSystem.current.SetSelectedGameObject(defaultSelectable.gameObject);
			}
		}

		private IEnumerator SelectDefaultDeferred()
		{
			yield return null;
			SelectDefault();
		}
	}
	[AddComponentMenu("")]
	public class ControlRemappingDemo1 : MonoBehaviour
	{
		private class ControllerSelection
		{
			private int _id;

			private int _idPrev;

			private ControllerType _type;

			private ControllerType _typePrev;

			public int id
			{
				get
				{
					return _id;
				}
				set
				{
					_idPrev = _id;
					_id = value;
				}
			}

			public ControllerType type
			{
				get
				{
					return _type;
				}
				set
				{
					_typePrev = _type;
					_type = value;
				}
			}

			public int idPrev => _idPrev;

			public ControllerType typePrev => _typePrev;

			public bool hasSelection => _id >= 0;

			public ControllerSelection()
			{
				Clear();
			}

			public void Set(int id, ControllerType type)
			{
				this.id = id;
				this.type = type;
			}

			public void Clear()
			{
				_id = -1;
				_idPrev = -1;
				_type = ControllerType.Joystick;
				_typePrev = ControllerType.Joystick;
			}
		}

		private class DialogHelper
		{
			public enum DialogType
			{
				None = 0,
				JoystickConflict = 1,
				ElementConflict = 2,
				KeyConflict = 3,
				DeleteAssignmentConfirmation = 10,
				AssignElement = 11
			}

			private const float openBusyDelay = 0.25f;

			private const float closeBusyDelay = 0.1f;

			private DialogType _type;

			private bool _enabled;

			private float _busyTime;

			private bool _busyTimerRunning;

			private Action<int> drawWindowDelegate;

			private GUI.WindowFunction drawWindowFunction;

			private WindowProperties windowProperties;

			private int currentActionId;

			private Action<int, UserResponse> resultCallback;

			private float busyTimer
			{
				get
				{
					if (!_busyTimerRunning)
					{
						return 0f;
					}
					return _busyTime - Time.realtimeSinceStartup;
				}
			}

			public bool enabled
			{
				get
				{
					return _enabled;
				}
				set
				{
					if (value)
					{
						if (_type != DialogType.None)
						{
							StateChanged(0.25f);
						}
					}
					else
					{
						_enabled = value;
						_type = DialogType.None;
						StateChanged(0.1f);
					}
				}
			}

			public DialogType type
			{
				get
				{
					if (!_enabled)
					{
						return DialogType.None;
					}
					return _type;
				}
				set
				{
					if (value == DialogType.None)
					{
						_enabled = false;
						StateChanged(0.1f);
					}
					else
					{
						_enabled = true;
						StateChanged(0.25f);
					}
					_type = value;
				}
			}

			public bool busy => _busyTimerRunning;

			public DialogHelper()
			{
				drawWindowDelegate = DrawWindow;
				drawWindowFunction = drawWindowDelegate.Invoke;
			}

			public void StartModal(int queueActionId, DialogType type, WindowProperties windowProperties, Action<int, UserResponse> resultCallback)
			{
				StartModal(queueActionId, type, windowProperties, resultCallback, -1f);
			}

			public void StartModal(int queueActionId, DialogType type, WindowProperties windowProperties, Action<int, UserResponse> resultCallback, float openBusyDelay)
			{
				currentActionId = queueActionId;
				this.windowProperties = windowProperties;
				this.type = type;
				this.resultCallback = resultCallback;
				if (openBusyDelay >= 0f)
				{
					StateChanged(openBusyDelay);
				}
			}

			public void Update()
			{
				Draw();
				UpdateTimers();
			}

			public void Draw()
			{
				if (_enabled)
				{
					bool flag = GUI.enabled;
					GUI.enabled = true;
					GUILayout.Window(windowProperties.windowId, windowProperties.rect, drawWindowFunction, windowProperties.title);
					GUI.FocusWindow(windowProperties.windowId);
					if (GUI.enabled != flag)
					{
						GUI.enabled = flag;
					}
				}
			}

			public void DrawConfirmButton()
			{
				DrawConfirmButton("Confirm");
			}

			public void DrawConfirmButton(string title)
			{
				bool flag = GUI.enabled;
				if (busy)
				{
					GUI.enabled = false;
				}
				if (GUILayout.Button(title))
				{
					Confirm(UserResponse.Confirm);
				}
				if (GUI.enabled != flag)
				{
					GUI.enabled = flag;
				}
			}

			public void DrawConfirmButton(UserResponse response)
			{
				DrawConfirmButton(response, "Confirm");
			}

			public void DrawConfirmButton(UserResponse response, string title)
			{
				bool flag = GUI.enabled;
				if (busy)
				{
					GUI.enabled = false;
				}
				if (GUILayout.Button(title))
				{
					Confirm(response);
				}
				if (GUI.enabled != flag)
				{
					GUI.enabled = flag;
				}
			}

			public void DrawCancelButton()
			{
				DrawCancelButton("Cancel");
			}

			public void DrawCancelButton(string title)
			{
				bool flag = GUI.enabled;
				if (busy)
				{
					GUI.enabled = false;
				}
				if (GUILayout.Button(title))
				{
					Cancel();
				}
				if (GUI.enabled != flag)
				{
					GUI.enabled = flag;
				}
			}

			public void Confirm()
			{
				Confirm(UserResponse.Confirm);
			}

			public void Confirm(UserResponse response)
			{
				resultCallback(currentActionId, response);
				Close();
			}

			public void Cancel()
			{
				resultCallback(currentActionId, UserResponse.Cancel);
				Close();
			}

			private void DrawWindow(int windowId)
			{
				windowProperties.windowDrawDelegate(windowProperties.title, windowProperties.message);
			}

			private void UpdateTimers()
			{
				if (_busyTimerRunning && busyTimer <= 0f)
				{
					_busyTimerRunning = false;
				}
			}

			private void StartBusyTimer(float time)
			{
				_busyTime = time + Time.realtimeSinceStartup;
				_busyTimerRunning = true;
			}

			private void Close()
			{
				Reset();
				StateChanged(0.1f);
			}

			private void StateChanged(float delay)
			{
				StartBusyTimer(delay);
			}

			private void Reset()
			{
				_enabled = false;
				_type = DialogType.None;
				currentActionId = -1;
				resultCallback = null;
			}

			private void ResetTimers()
			{
				_busyTimerRunning = false;
			}

			public void FullReset()
			{
				Reset();
				ResetTimers();
			}
		}

		private abstract class QueueEntry
		{
			public enum State
			{
				Waiting,
				Confirmed,
				Canceled
			}

			private static int uidCounter;

			public int id { get; protected set; }

			public QueueActionType queueActionType { get; protected set; }

			public State state { get; protected set; }

			public UserResponse response { get; protected set; }

			protected static int nextId
			{
				get
				{
					int result = uidCounter;
					uidCounter++;
					return result;
				}
			}

			public QueueEntry(QueueActionType queueActionType)
			{
				id = nextId;
				this.queueActionType = queueActionType;
			}

			public void Confirm(UserResponse response)
			{
				state = State.Confirmed;
				this.response = response;
			}

			public void Cancel()
			{
				state = State.Canceled;
			}
		}

		private class JoystickAssignmentChange : QueueEntry
		{
			public int playerId { get; private set; }

			public int joystickId { get; private set; }

			public bool assign { get; private set; }

			public JoystickAssignmentChange(int newPlayerId, int joystickId, bool assign)
				: base(QueueActionType.JoystickAssignment)
			{
				playerId = newPlayerId;
				this.joystickId = joystickId;
				this.assign = assign;
			}
		}

		private class ElementAssignmentChange : QueueEntry
		{
			public ElementAssignmentChangeType changeType { get; set; }

			public InputMapper.Context context { get; private set; }

			public ElementAssignmentChange(ElementAssignmentChangeType changeType, InputMapper.Context context)
				: base(QueueActionType.ElementAssignment)
			{
				this.changeType = changeType;
				this.context = context;
			}

			public ElementAssignmentChange(ElementAssignmentChange other)
				: this(other.changeType, other.context.Clone())
			{
			}
		}

		private class FallbackJoystickIdentification : QueueEntry
		{
			public int joystickId { get; private set; }

			public string joystickName { get; private set; }

			public FallbackJoystickIdentification(int joystickId, string joystickName)
				: base(QueueActionType.FallbackJoystickIdentification)
			{
				this.joystickId = joystickId;
				this.joystickName = joystickName;
			}
		}

		private class Calibration : QueueEntry
		{
			public int selectedElementIdentifierId;

			public bool recording;

			public Player player { get; private set; }

			public ControllerType controllerType { get; private set; }

			public Joystick joystick { get; private set; }

			public CalibrationMap calibrationMap { get; private set; }

			public Calibration(Player player, Joystick joystick, CalibrationMap calibrationMap)
				: base(QueueActionType.Calibrate)
			{
				this.player = player;
				this.joystick = joystick;
				this.calibrationMap = calibrationMap;
				selectedElementIdentifierId = -1;
			}
		}

