	[RequireComponent(typeof(RectTransform))]
	public class BarViewPosImageFill : ProgressBarProView
	{
		[SerializeField]
		private RectTransform rectTrans;

		[SerializeField]
		private Image referenceImage;

		[Range(-1f, 1f)]
		[SerializeField]
		private float offset;

		public override void UpdateView(float currentValue, float targetValue)
		{
			rectTrans.anchorMin = GetAnchor(currentValue);
			rectTrans.anchorMax = GetAnchor(currentValue);
		}

		private Vector2 GetAnchor(float currentDisplay)
		{
			return referenceImage.fillMethod switch
			{
				Image.FillMethod.Horizontal => GetAnchorHorizontal(currentDisplay, referenceImage.fillOrigin), 
				Image.FillMethod.Vertical => GetAnchorVertical(currentDisplay, referenceImage.fillOrigin), 
				Image.FillMethod.Radial360 => GetAnchorRadial360(currentDisplay, referenceImage.fillOrigin, referenceImage.fillClockwise), 
				_ => Vector2.one * 0.5f, 
			};
		}

		private Vector2 GetAnchorHorizontal(float fillAmount, int fillOrigin)
		{
			float x = ((fillOrigin != 1) ? fillAmount : (1f - fillAmount));
			return new Vector2(x, 0.5f + 0.5f * offset);
		}

		private Vector2 GetAnchorVertical(float fillAmount, int fillOrigin)
		{
			float y = ((fillOrigin != 1) ? fillAmount : (1f - fillAmount));
			return new Vector2(0.5f + 0.5f * offset, y);
		}

		private Vector2 GetAnchorRadial360(float fillAmount, int fillOrigin, bool fillClockwise)
		{
			float num = 360f * (fillClockwise ? (0f - fillAmount) : fillAmount);
			switch (fillOrigin)
			{
			case 0:
				num += (fillClockwise ? (-90f) : 90f);
				break;
			case 3:
				num += (fillClockwise ? (-180f) : 180f);
				break;
			case 2:
				num += (fillClockwise ? (-270f) : 270f);
				break;
			}
			return GetPointOnCircle(num);
		}

		private Vector2 GetPointOnCircle(float degrees)
		{
			float num = 0.25f + 0.25f * offset;
			return new Vector2(0.5f + num * Mathf.Cos(MathF.PI / 180f * degrees), 0.5f + num * Mathf.Sin(MathF.PI / 180f * degrees));
		}
	}
	[RequireComponent(typeof(RectTransform))]
	public class BarViewScale : ProgressBarProView
	{
		[SerializeField]
		protected RectTransform graphic;

		[Header("Color Options")]
		[Tooltip("If true, then the scale animates for each change. Otherwise it scales constantly based on value")]
		[SerializeField]
		private bool animateOnChange = true;

		[SerializeField]
		private Vector3 minSize = Vector3.one;

		[SerializeField]
		private Vector3 maxSize = new Vector3(2f, 2f, 2f);

		[Tooltip("A value of 0 is minSize, a value of 1 is maxSize. Time goes from 0 to 1.")]
		[SerializeField]
		private AnimationCurve scale;

		[SerializeField]
		private float animDuration = 0.2f;

		private Coroutine scaleAnim;

		private void OnEnable()
		{
			UpdateScale();
		}

		public override void NewChangeStarted(float currentValue, float targetValue)
		{
			if (base.gameObject.activeInHierarchy && animateOnChange)
			{
				if (scaleAnim != null)
				{
					StopCoroutine(scaleAnim);
				}
				scaleAnim = StartCoroutine(DoBarScaleAnim(animDuration));
			}
		}

		private IEnumerator DoBarScaleAnim(float duration)
		{
			float time = 0f;
			while (time < duration)
			{
				UpdateScale(time / duration);
				time += Time.deltaTime;
				yield return null;
			}
			UpdateScale();
			scaleAnim = null;
		}

		public override void UpdateView(float currentValue, float targetValue)
		{
			if (!animateOnChange && scaleAnim == null)
			{
				UpdateScale(currentValue);
			}
		}

		private void UpdateScale(float value = 0f)
		{
			graphic.localScale = GetCurrentScale(value);
		}

		private Vector3 GetCurrentScale(float percentage)
		{
			return Vector3.Lerp(minSize, maxSize, scale.Evaluate(percentage));
		}
	}
	[RequireComponent(typeof(RectTransform))]
	public class BarViewSizeAnchors : ProgressBarProView
	{
		public enum FillType
		{
			LeftToRight,
			RightToLeft,
			TopToBottom,
			BottomToTop
		}

		[SerializeField]
		protected RectTransform rectTrans;

		[SerializeField]
		protected FillType fillType;

		[SerializeField]
		private bool hideOnEmpty = true;

		[SerializeField]
		private bool useDiscreteSteps;

		[SerializeField]
		private int numSteps = 10;

		protected DrivenRectTransformTracker m_Tracker;

		protected bool isDisplaySizeZero;

		public override bool CanUpdateView(float currentValue, float targetValue)
		{
			if (!base.isActiveAndEnabled)
			{
				return isDisplaySizeZero;
			}
			return true;
		}

		public override void UpdateView(float currentValue, float targetValue)
		{
			if (hideOnEmpty && currentValue <= 0f)
			{
				rectTrans.gameObject.SetActive(value: false);
				isDisplaySizeZero = true;
			}
			else
			{
				isDisplaySizeZero = false;
				rectTrans.gameObject.SetActive(value: true);
				SetPivot(0f, currentValue);
			}
		}

		protected void SetPivot(float startEdge, float endEdge)
		{
			if (useDiscreteSteps)
			{
				startEdge = Mathf.Round(startEdge * (float)numSteps) / (float)numSteps;
				endEdge = Mathf.Round(endEdge * (float)numSteps) / (float)numSteps;
			}
			UpdateTracker();
			switch (fillType)
			{
			case FillType.LeftToRight:
				rectTrans.anchorMin = new Vector2(startEdge, rectTrans.anchorMin.y);
				rectTrans.anchorMax = new Vector2(endEdge, rectTrans.anchorMax.y);
				break;
			case FillType.RightToLeft:
				rectTrans.anchorMin = new Vector2(1f - endEdge, rectTrans.anchorMin.y);
				rectTrans.anchorMax = new Vector2(1f - startEdge, rectTrans.anchorMax.y);
				break;
			case FillType.BottomToTop:
				rectTrans.anchorMin = new Vector2(rectTrans.anchorMin.x, startEdge);
				rectTrans.anchorMax = new Vector2(rectTrans.anchorMax.x, endEdge);
				break;
			case FillType.TopToBottom:
				rectTrans.anchorMin = new Vector2(rectTrans.anchorMin.x, 1f - endEdge);
				rectTrans.anchorMax = new Vector2(rectTrans.anchorMax.x, 1f - startEdge);
				break;
			}
		}

		private void UpdateTracker()
		{
			if (fillType == FillType.LeftToRight || fillType == FillType.RightToLeft)
			{
				m_Tracker.Add(this, rectTrans, DrivenTransformProperties.AnchorMinX | DrivenTransformProperties.AnchorMaxX);
			}
			else
			{
				m_Tracker.Add(this, rectTrans, DrivenTransformProperties.AnchorMinY | DrivenTransformProperties.AnchorMaxY);
			}
		}

		private void OnDisable()
		{
			m_Tracker.Clear();
		}
	}
	[RequireComponent(typeof(Image))]
	public class BarViewSizeAnchorsShadow : BarViewSizeAnchors
	{
		public enum ShadowType
		{
			Gaining,
			Losing
		}

		[SerializeField]
		private ShadowType shadowType;

		public override void UpdateView(float currentValue, float targetValue)
		{
			if (Mathf.Approximately(currentValue, targetValue) || (shadowType == ShadowType.Gaining && targetValue < currentValue) || (shadowType == ShadowType.Losing && targetValue > currentValue))
			{
				rectTrans.gameObject.SetActive(value: false);
				isDisplaySizeZero = true;
				return;
			}
			isDisplaySizeZero = false;
			rectTrans.gameObject.SetActive(value: true);
			if (shadowType == ShadowType.Gaining)
			{
				SetPivot(0f, targetValue);
			}
			else
			{
				SetPivot(targetValue, currentValue);
			}
		}
	}
	[RequireComponent(typeof(Image))]
	public class BarViewSizeImageFill : ProgressBarProView
	{
		[SerializeField]
		protected Image image;

		[SerializeField]
		private bool hideOnEmpty = true;

		[SerializeField]
		private bool useDiscreteSteps;

		[SerializeField]
		private int numSteps = 10;

		private bool isDisplaySizeZero;

		public override bool CanUpdateView(float currentValue, float targetValue)
		{
			if (!base.isActiveAndEnabled)
			{
				return isDisplaySizeZero;
			}
			return true;
		}

		public override void UpdateView(float currentValue, float targetValue)
		{
			if (hideOnEmpty && currentValue <= 0f)
			{
				image.gameObject.SetActive(value: false);
				isDisplaySizeZero = true;
			}
			else
			{
				isDisplaySizeZero = false;
				image.gameObject.SetActive(value: true);
				image.fillAmount = GetDisplayValue(currentValue);
			}
		}

		private float GetDisplayValue(float display)
		{
			if (!useDiscreteSteps)
			{
				return display;
			}
			return Mathf.Round(display * (float)numSteps) / (float)numSteps;
		}
	}
	[RequireComponent(typeof(Text))]
	public class BarViewValueText : ProgressBarProView
	{
		[SerializeField]
		private Text text;

		[SerializeField]
		private string prefix = "";

		[SerializeField]
		private float minValue;

		[SerializeField]
		private float maxValue = 100f;

		[SerializeField]
		private int numDecimals;

		[SerializeField]
		private bool showMaxValue;

		[SerializeField]
		private string numberUnit = "%";

		[SerializeField]
		private string suffix = "";

		private float lastDisplayValue;

		public override bool CanUpdateView(float currentValue, float targetValue)
		{
			float roundedDisplayValue = GetRoundedDisplayValue(currentValue);
			if (currentValue >= 0f && Mathf.Approximately(lastDisplayValue, roundedDisplayValue))
			{
				return false;
			}
			lastDisplayValue = GetRoundedDisplayValue(currentValue);
			return true;
		}

		public override void UpdateView(float currentValue, float targetValue)
		{
			text.text = prefix + FormatNumber(GetRoundedDisplayValue(currentValue)) + numberUnit + (showMaxValue ? (" / " + FormatNumber(maxValue) + numberUnit) : "") + suffix;
		}

		private float GetDisplayValue(float num)
		{
			return Mathf.Lerp(minValue, maxValue, num);
		}

		private float GetRoundedDisplayValue(float num)
		{
			float displayValue = GetDisplayValue(num);
			if (numDecimals == 0)
			{
				return Mathf.Round(displayValue);
			}
			float num2 = Mathf.Pow(10f, numDecimals);
			return Mathf.Round(displayValue * num2) / num2;
		}

		private string FormatNumber(float num)
		{
			return num.ToString("N" + numDecimals);
		}
	}
	public abstract class ProgressBarProView : MonoBehaviour
	{
		public virtual void NewChangeStarted(float currentValue, float targetValue)
		{
		}

		public virtual void SetBarColor(Color color)
		{
		}

		public virtual bool CanUpdateView(float currentValue, float targetValue)
		{
			return base.isActiveAndEnabled;
		}

		public abstract void UpdateView(float currentValue, float targetValue);
	}
