		public static Texture2D SaveTemplateIcon
		{
			get
			{
				if (saveTemplateIcon == null)
				{
					saveTemplateIcon = new Texture2D(512, 512, TextureFormat.ARGB32, mipChain: false);
					saveTemplateIcon.LoadImage(saveTemplateIconBytes);
					saveTemplateIcon.Apply();
				}
				return saveTemplateIcon;
			}
		}

		public static Texture2D LoadTemplateIcon
		{
			get
			{
				if (loadTemplateIcon == null)
				{
					loadTemplateIcon = new Texture2D(512, 512, TextureFormat.ARGB32, mipChain: false);
					loadTemplateIcon.LoadImage(loadTemplateIconBytes);
					loadTemplateIcon.Apply();
				}
				return loadTemplateIcon;
			}
		}

		public static Texture2D NullIcon
		{
			get
			{
				if (nullIcon == null)
				{
					nullIcon = new Texture2D(512, 512, TextureFormat.ARGB32, mipChain: false);
					nullIcon.LoadImage(nullIconBytes);
					nullIcon.Apply();
				}
				return nullIcon;
			}
		}

		public static Texture2D AddIcon
		{
			get
			{
				if (addIcon == null)
				{
					addIcon = new Texture2D(512, 512, TextureFormat.ARGB32, mipChain: false);
					addIcon.LoadImage(addIconBytes);
					addIcon.Apply();
				}
				return addIcon;
			}
		}

		public static Texture2D SaveMeshIcon
		{
			get
			{
				if (saveMeshIcon == null)
				{
					saveMeshIcon = new Texture2D(128, 128, TextureFormat.ARGB32, mipChain: false);
					saveMeshIcon.LoadImage(saveMeshIconBytes);
					saveMeshIcon.Apply();
				}
				return saveMeshIcon;
			}
		}
	}
	public static class CombineUtility
	{
		public struct MeshInstance
		{
			public Mesh mesh;

			public int subMeshIndex;

			public Matrix4x4 transform;
		}

		private static int vertexCount;

		private static int triangleCount;

		private static int stripCount;

		private static int curStripCount;

		private static Vector3[] vertices;

		private static Vector3[] normals;

		private static Vector4[] tangents;

		private static Vector2[] uv;

		private static Vector2[] uv1;

		private static Color[] colors;

		private static int[] triangles;

		private static int[] strip;

		private static int offset;

		private static int triangleOffset;

		private static int stripOffset;

		private static int vertexOffset;

		private static Matrix4x4 invTranspose;

		public const string combinedMeshName = "Combined Mesh";

		private static Vector4 p4;

		private static Vector3 p;

		public static Mesh Combine(MeshInstance[] combines, bool generateStrips)
		{
			vertexCount = 0;
			triangleCount = 0;
			stripCount = 0;
			MeshInstance[] array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance = array[i];
				if (!(meshInstance.mesh != null))
				{
					continue;
				}
				vertexCount += meshInstance.mesh.vertexCount;
				if (!generateStrips)
				{
					continue;
				}
				curStripCount = meshInstance.mesh.GetTriangles(meshInstance.subMeshIndex).Length;
				if (curStripCount != 0)
				{
					if (stripCount != 0)
					{
						if ((stripCount & 1) == 1)
						{
							stripCount += 3;
						}
						else
						{
							stripCount += 2;
						}
					}
					stripCount += curStripCount;
				}
				else
				{
					generateStrips = false;
				}
			}
			if (!generateStrips)
			{
				array = combines;
				for (int i = 0; i < array.Length; i++)
				{
					MeshInstance meshInstance2 = array[i];
					if (meshInstance2.mesh != null)
					{
						triangleCount += meshInstance2.mesh.GetTriangles(meshInstance2.subMeshIndex).Length;
					}
				}
			}
			vertices = new Vector3[vertexCount];
			normals = new Vector3[vertexCount];
			tangents = new Vector4[vertexCount];
			uv = new Vector2[vertexCount];
			uv1 = new Vector2[vertexCount];
			colors = new Color[vertexCount];
			triangles = new int[triangleCount];
			strip = new int[stripCount];
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance3 = array[i];
				if (meshInstance3.mesh != null)
				{
					Copy(meshInstance3.mesh.vertexCount, meshInstance3.mesh.vertices, vertices, ref offset, meshInstance3.transform);
				}
			}
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance4 = array[i];
				if (meshInstance4.mesh != null)
				{
					invTranspose = meshInstance4.transform;
					invTranspose = invTranspose.inverse.transpose;
					CopyNormal(meshInstance4.mesh.vertexCount, meshInstance4.mesh.normals, normals, ref offset, invTranspose);
				}
			}
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance5 = array[i];
				if (meshInstance5.mesh != null)
				{
					invTranspose = meshInstance5.transform;
					invTranspose = invTranspose.inverse.transpose;
					CopyTangents(meshInstance5.mesh.vertexCount, meshInstance5.mesh.tangents, tangents, ref offset, invTranspose);
				}
			}
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance6 = array[i];
				if (meshInstance6.mesh != null)
				{
					Copy(meshInstance6.mesh.vertexCount, meshInstance6.mesh.uv, uv, ref offset);
				}
			}
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance7 = array[i];
				if (meshInstance7.mesh != null)
				{
					Copy(meshInstance7.mesh.vertexCount, meshInstance7.mesh.uv2, uv1, ref offset);
				}
			}
			offset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance8 = array[i];
				if (meshInstance8.mesh != null)
				{
					CopyColors(meshInstance8.mesh.vertexCount, meshInstance8.mesh.colors, colors, ref offset);
				}
			}
			triangleOffset = 0;
			stripOffset = 0;
			vertexOffset = 0;
			array = combines;
			for (int i = 0; i < array.Length; i++)
			{
				MeshInstance meshInstance9 = array[i];
				if (!(meshInstance9.mesh != null))
				{
					continue;
				}
				if (generateStrips)
				{
					int[] array2 = meshInstance9.mesh.GetTriangles(meshInstance9.subMeshIndex);
					if (stripOffset != 0)
					{
						if ((stripOffset & 1) == 1)
						{
							strip[stripOffset] = strip[stripOffset - 1];
							strip[stripOffset + 1] = array2[0] + vertexOffset;
							strip[stripOffset + 2] = array2[0] + vertexOffset;
							stripOffset += 3;
						}
						else
						{
							strip[stripOffset] = strip[stripOffset - 1];
							strip[stripOffset + 1] = array2[0] + vertexOffset;
							stripOffset += 2;
						}
					}
					for (int j = 0; j < array2.Length; j++)
					{
						strip[j + stripOffset] = array2[j] + vertexOffset;
					}
					stripOffset += array2.Length;
				}
				else
				{
					int[] array3 = meshInstance9.mesh.GetTriangles(meshInstance9.subMeshIndex);
					for (int k = 0; k < array3.Length; k++)
					{
						triangles[k + triangleOffset] = array3[k] + vertexOffset;
					}
					triangleOffset += array3.Length;
				}
				vertexOffset += meshInstance9.mesh.vertexCount;
			}
			Mesh mesh = new Mesh();
			mesh.name = "Combined Mesh";
			mesh.vertices = vertices;
			mesh.normals = normals;
			mesh.colors = colors;
			mesh.uv = uv;
			mesh.uv2 = uv1;
			mesh.tangents = tangents;
			if (generateStrips)
			{
				mesh.SetTriangles(strip, 0);
			}
			else
			{
				mesh.triangles = triangles;
			}
			return mesh;
		}

		private static void Copy(int vertexcount, Vector3[] src, Vector3[] dst, ref int offset, Matrix4x4 transform)
		{
			for (int i = 0; i < src.Length; i++)
			{
				dst[i + offset] = transform.MultiplyPoint(src[i]);
			}
			offset += vertexcount;
		}

		private static void CopyNormal(int vertexcount, Vector3[] src, Vector3[] dst, ref int offset, Matrix4x4 transform)
		{
			for (int i = 0; i < src.Length; i++)
			{
				dst[i + offset] = transform.MultiplyVector(src[i]).normalized;
			}
			offset += vertexcount;
		}

		private static void Copy(int vertexcount, Vector2[] src, Vector2[] dst, ref int offset)
		{
			for (int i = 0; i < src.Length; i++)
			{
				dst[i + offset] = src[i];
			}
			offset += vertexcount;
		}

		private static void CopyColors(int vertexcount, Color[] src, Color[] dst, ref int offset)
		{
			for (int i = 0; i < src.Length; i++)
			{
				dst[i + offset] = src[i];
			}
			offset += vertexcount;
		}

		private static void CopyTangents(int vertexcount, Vector4[] src, Vector4[] dst, ref int offset, Matrix4x4 transform)
		{
			for (int i = 0; i < src.Length; i++)
			{
				p4 = src[i];
				p = new Vector3(p4.x, p4.y, p4.z);
				p = transform.MultiplyVector(p).normalized;
				dst[i + offset] = new Vector4(p.x, p.y, p.z, p4.w);
			}
			offset += vertexcount;
		}
	}
	public static class FavouriteTemplatesUtility
	{
		public static XDocument SaveFavouriteTemplates(List<string> favouriteTemplates, string filePath)
		{
			if (string.IsNullOrEmpty(filePath))
			{
				throw new ArgumentNullException("filePath", "MeshBrush: the specified file path is null or empty (and thus invalid). Couldn't save favourite templates list...");
			}
			if (favouriteTemplates == null)
			{
				throw new ArgumentNullException("favouriteTemplates", "MeshBrush: The passed list of favourite templates is null. Cancelling saving operation...");
			}
			for (int num = favouriteTemplates.Count - 1; num >= 0; num--)
			{
				if (!File.Exists(favouriteTemplates[num]))
				{
					favouriteTemplates.RemoveAt(num);
				}
			}
			XDocument xDocument = new XDocument(new XElement("favouriteMeshBrushTemplates", favouriteTemplates.Select((string template) => new XElement("template", new XElement("path", template)))));
			xDocument.Save(filePath);
			return xDocument;
		}

		public static List<string> LoadFavouriteTemplates(string filePath)
		{
			if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
			{
				throw new ArgumentException("MeshBrush: the specified file path is invalid or doesn't exist! Can't load favourite templates list...", "filePath");
			}
			return new List<string>(from path in XDocument.Load(filePath).Descendants("path")
				select path.Value);
		}

		public static bool LoadFavouriteTemplates(string filePath, List<string> targetList)
		{
			if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
			{
				throw new ArgumentException("MeshBrush: the specified file path is invalid or doesn't exist! Can't load favourite templates list...", "filePath");
			}
			if (targetList == null)
			{
				throw new ArgumentNullException("targetList", "MeshBrush: cannot write favourite templates to the specified target list because it is null.");
			}
			try
			{
				targetList.Clear();
				foreach (XElement item in XDocument.Load(filePath).Descendants("path"))
				{
					targetList.Add(item.Value);
				}
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("MeshBrush: loading favourite templates list failed. Error message: " + ex.Message);
				return false;
			}
			return true;
		}
	}
	public static class MeshTransformationUtility
	{
		public static void ApplyRandomScale(Transform targetTransform, Vector2 range)
		{
			float num = Mathf.Abs(UnityEngine.Random.Range(range.x, range.y));
			targetTransform.localScale = new Vector3(num, num, num);
		}

		public static void ApplyRandomScale(Transform targetTransform, Vector4 scaleRanges)
		{
			float f = UnityEngine.Random.Range(scaleRanges.x, scaleRanges.y);
			float f2 = UnityEngine.Random.Range(scaleRanges.z, scaleRanges.w);
			targetTransform.localScale = new Vector3
			{
				x = Mathf.Abs(f),
				y = Mathf.Abs(f2),
				z = Mathf.Abs(f)
			};
		}

		public static void ApplyRandomScale(Transform targetTransform, Vector2 rangeX, Vector2 rangeY, Vector2 rangeZ)
		{
			targetTransform.localScale = new Vector3
			{
				x = Mathf.Abs(UnityEngine.Random.Range(rangeX.x, rangeX.y)),
				y = Mathf.Abs(UnityEngine.Random.Range(rangeY.x, rangeY.y)),
				z = Mathf.Abs(UnityEngine.Random.Range(rangeZ.x, rangeZ.y))
			};
		}

		public static void AddConstantScale(Transform targetTransform, Vector2 range)
		{
			float num = UnityEngine.Random.Range(range.x, range.y);
			Vector3 localScale = targetTransform.localScale + new Vector3(num, num, num);
			localScale.x = Mathf.Abs(localScale.x);
			localScale.y = Mathf.Abs(localScale.y);
			localScale.z = Mathf.Abs(localScale.z);
			targetTransform.localScale = localScale;
		}

		public static void AddConstantScale(Transform targetTransform, float x, float y, float z)
		{
			Vector3 localScale = targetTransform.localScale + new Vector3
			{
				x = Mathf.Abs(x),
				y = Mathf.Abs(y),
				z = Mathf.Abs(z)
			};
			targetTransform.localScale = localScale;
		}

		public static void ApplyRandomRotation(Transform targetTransform, float randomRotationIntensityPercentage)
		{
			float y = UnityEngine.Random.Range(0f, 3.6f * randomRotationIntensityPercentage);
			targetTransform.Rotate(new Vector3(0f, y, 0f));
		}

		public static void ApplyMeshOffset(Transform targetTransform, float offset, Vector3 direction)
		{
			targetTransform.Translate(direction.normalized * offset * 0.01f, Space.World);
		}
	}
	public static class TemplateMigrationUtility
	{
		public static bool TryMigrate(string filePath)
		{
			if (string.IsNullOrEmpty(filePath) || !File.Exists(filePath))
			{
				UnityEngine.Debug.LogError("MeshBrush: The specified template file path is invalid or doesn't exist! Cancelling migration process...");
				return false;
			}
			try
			{
				XDocument xDocument = XDocument.Load(filePath);
				MeshBrush meshBrush = new GameObject("MeshBrush Template Migration Utility")
				{
					hideFlags = HideFlags.HideAndDontSave
				}.AddComponent<MeshBrush>();
				foreach (XElement item in xDocument.Descendants())
				{
					switch (item.Name.LocalName)
					{
					case "meshBrushTemplate":
					{
						XAttribute xAttribute = item.Attribute("version");
						if (xAttribute != null && 1.9f <= float.Parse(xAttribute.Value))
						{
							UnityEngine.Debug.LogWarning("MeshBrush: The template you tried to migrate actually is already up to date with the current format. Cancelling process...");
							return false;
						}
						break;
					}
					case "active":
					case "isActive":
						meshBrush.active = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "groupName":
						meshBrush.groupName = item.Value;
						break;
					case "classicUI":
						meshBrush.classicUI = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "previewIconSize":
						meshBrush.previewIconSize = float.Parse(item.Value);
						break;
					case "lockSceneView":
						meshBrush.lockSceneView = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "trisCounter":
						meshBrush.stats = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "globalPaintingLayers":
					{
						int num7 = 0;
						foreach (XElement item2 in item.Elements())
						{
							meshBrush.layerMask[num7] = string.CompareOrdinal(item2.Value, "false") != 0;
							num7++;
						}
						break;
					}
					case "paintKey":
						meshBrush.paintKey = (KeyCode)Enum.Parse(typeof(KeyCode), item.Value);
						break;
					case "deleteKey":
						meshBrush.deleteKey = (KeyCode)Enum.Parse(typeof(KeyCode), item.Value);
						break;
					case "combineAreaKey":
						meshBrush.combineKey = (KeyCode)Enum.Parse(typeof(KeyCode), item.Value);
						break;
					case "increaseRadiusKey":
						meshBrush.increaseRadiusKey = (KeyCode)Enum.Parse(typeof(KeyCode), item.Value);
						break;
					case "decreaseRadiusKey":
						meshBrush.decreaseRadiusKey = (KeyCode)Enum.Parse(typeof(KeyCode), item.Value);
						break;
					case "brushRadius":
						meshBrush.radius = float.Parse(item.Value);
						break;
					case "color":
					case "brushColor":
						meshBrush.color = new Color(float.Parse(item.Element("r").Value), float.Parse(item.Element("g").Value), float.Parse(item.Element("b").Value), float.Parse(item.Element("a").Value));
						break;
					case "useMeshDensity":
						meshBrush.useDensity = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "minMeshDensity":
						meshBrush.densityRange.x = float.Parse(item.Value);
						break;
					case "maxMeshDensity":
						meshBrush.densityRange.y = float.Parse(item.Value);
						break;
					case "minNrOfMeshes":
						meshBrush.quantityRange.x = float.Parse(item.Value);
						break;
					case "maxNrOfMeshes":
						meshBrush.quantityRange.y = float.Parse(item.Value);
						break;
					case "delay":
						meshBrush.delay = float.Parse(item.Value);
						break;
					case "verticalOffset":
					{
						float num6 = float.Parse(item.Value);
						meshBrush.offsetRange = new Vector2(num6, num6);
						break;
					}
					case "alignWithStroke":
						meshBrush.strokeAlignment = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "slopeInfluence":
					{
						float num5 = float.Parse(item.Value);
						meshBrush.slopeInfluenceRange = new Vector2(num5, num5);
						break;
					}
					case "useSlopeFilter":
						meshBrush.useSlopeFilter = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "maxSlopeFilterAngle":
					{
						float num4 = float.Parse(item.Value);
						meshBrush.angleThresholdRange = new Vector2(num4, num4);
						break;
					}
					case "inverseSlopeFilter":
						meshBrush.inverseSlopeFilter = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "manualReferenceVectorSampling":
						meshBrush.manualReferenceVectorSampling = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "showReferenceVectorInSceneGUI":
						meshBrush.showReferenceVectorInSceneView = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "slopeReferenceVector":
						meshBrush.slopeReferenceVector = new Vector3(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value), float.Parse(item.Element("z").Value));
						break;
					case "slopeReferenceVector_HandleLocation":
						meshBrush.slopeReferenceVectorSampleLocation = new Vector3(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value), float.Parse(item.Element("z").Value));
						break;
					case "yAxisIsTangent":
						meshBrush.yAxisTangent = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "scattering":
					{
						float num3 = float.Parse(item.Value);
						meshBrush.scatteringRange = new Vector2(num3, num3);
						break;
					}
					case "autoStatic":
						meshBrush.autoStatic = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "useOverlapFilter":
						meshBrush.useOverlapFilter = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "randomAbsMinDist":
						meshBrush.minimumAbsoluteDistanceRange = new Vector2(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value));
						break;
					case "uniformScale":
						meshBrush.uniformRandomScale = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "constantUniformScale":
						meshBrush.uniformAdditiveScale = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_SetOfMeshesToPaint":
						meshBrush.meshesFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_Templates":
						meshBrush.templatesFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_CustomizeKeyboardShortcuts":
						meshBrush.keyBindingsFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_BrushSettings":
						meshBrush.brushFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_Slopes":
						meshBrush.slopesFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_Randomizers":
						meshBrush.randomizersFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_OverlapFilter":
						meshBrush.overlapFilterFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_ApplyAdditiveScale":
						meshBrush.additiveScaleFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "foldoutState_Optimize":
						meshBrush.optimizationFoldout = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					case "randomUniformRange":
						meshBrush.randomScaleRange = new Vector2(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value));
						break;
					case "randomNonUniformRange":
						meshBrush.randomScaleRangeX = (meshBrush.randomScaleRangeZ = new Vector2(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value)));
						meshBrush.randomScaleRangeY = new Vector2(float.Parse(item.Element("z").Value), float.Parse(item.Element("w").Value));
						break;
					case "constantAdditiveScale":
					{
						float num2 = float.Parse(item.Value);
						meshBrush.additiveScaleRange = new Vector2(num2, num2);
						break;
					}
					case "constantScaleXYZ":
						meshBrush.additiveScaleNonUniform = new Vector3(float.Parse(item.Element("x").Value), float.Parse(item.Element("y").Value), float.Parse(item.Element("z").Value));
						break;
					case "randomRotation":
					{
						float num = float.Parse(item.Value);
						meshBrush.randomRotationRange = new Vector2(num, num);
						break;
					}
					case "autoSelectOnCombine":
						meshBrush.autoSelectOnCombine = string.CompareOrdinal(item.Value, "true") == 0;
						break;
					}
				}
				meshBrush.SaveTemplate(filePath.Replace(".meshbrush", "__migrated.xml"));
			}
			catch (Exception ex)
			{
				UnityEngine.Debug.LogError("MeshBrush: Failed to migrate template file \"" + filePath + "\". Perhaps the file is corrupted? " + ex.ToString());
				return false;
			}
			return true;
		}
	}
	public static class VectorClampingUtility
	{
		public static void ClampVector(ref Vector2 vector, float minX, float maxX, float minY, float maxY)
		{
			vector.x = Mathf.Clamp(vector.x, minX, maxX);
			vector.y = Mathf.Clamp(vector.y, minY, maxY);
		}

		public static void ClampVector(ref Vector3 vector, float minX, float maxX, float minY, float maxY, float minZ, float maxZ)
		{
			vector.x = Mathf.Clamp(vector.x, minX, maxX);
			vector.y = Mathf.Clamp(vector.y, minY, maxY);
			vector.z = Mathf.Clamp(vector.z, minZ, maxZ);
		}

		public static void ClampVector(ref Vector4 vector, float minX, float maxX, float minY, float maxY, float minZ, float maxZ, float minW, float maxW)
		{
			vector.x = Mathf.Clamp(vector.x, minX, maxX);
			vector.y = Mathf.Clamp(vector.y, minY, maxY);
			vector.z = Mathf.Clamp(vector.z, minZ, maxZ);
			vector.w = Mathf.Clamp(vector.w, minW, maxW);
		}
	}
