	internal interface ILocalizeFontSizeBehaviour
	{
		void ApplyOverride(LocalizeFontSize.Override fontSizeOverride);

		void Restore();
	}
	public class LocalizeFontSize : MonoBehaviour
	{
		[Serializable]
		internal struct Override
		{
			[SerializeField]
			internal string languageCode;

			[SerializeField]
			internal int fontSize;

			[SerializeField]
			internal int fontSizeMin;

			[SerializeField]
			internal int fontSizeMax;
		}

		[SerializeField]
		private List<Override> _overrides;

		private bool _initialized;

		private ILocalizeFontSizeBehaviour _behaviour;

		private bool Initialize()
		{
			if (_initialized)
			{
				return true;
			}
			_behaviour = ReturnBehaviour();
			if (_behaviour == null)
			{
				return false;
			}
			_initialized = true;
			return true;
		}

		private void OnEnable()
		{
			if (Initialize())
			{
				ApplyOverride();
				LocalizationManager.OnLocalizeEvent += ApplyOverride;
			}
			else
			{
				UnityEngine.Debug.LogWarning("LocalizeFontSize could not be initialized (missing Text or TextMeshProUGUI?)! Destroying it.");
				UnityEngine.Object.Destroy(this);
			}
		}

		private void OnDisable()
		{
			LocalizationManager.OnLocalizeEvent -= ApplyOverride;
		}

		public void ApplyOverride()
		{
			if (_behaviour == null)
			{
				return;
			}
			string currentLanguageCode = LocalizationManager.CurrentLanguageCode;
			foreach (Override @override in _overrides)
			{
				if (@override.languageCode == currentLanguageCode)
				{
					_behaviour.ApplyOverride(@override);
					break;
				}
			}
		}

		private ILocalizeFontSizeBehaviour ReturnBehaviour()
		{
			Text component = GetComponent<Text>();
			if ((bool)component)
			{
				return new LocalizeTextFontSize(component);
			}
			TMP_Text component2 = GetComponent<TMP_Text>();
			if ((bool)component2)
			{
				return new LocalizeTextMeshProFontSize(component2);
			}
			return null;
		}
	}
	internal class LocalizeTextFontSize : ILocalizeFontSizeBehaviour
	{
		private Text _text;

		private int _originalFontSize;

		private int _originalResizeTextMinSize;

		private int _originalResizeTextMaxSize;

		public LocalizeTextFontSize(Text text)
		{
			_text = text;
			_originalFontSize = text.fontSize;
			_originalResizeTextMinSize = text.resizeTextMinSize;
			_originalResizeTextMaxSize = text.resizeTextMaxSize;
		}

		public void ApplyOverride(LocalizeFontSize.Override fontSizeOverride)
		{
			if (_text.resizeTextForBestFit)
			{
				_text.resizeTextMinSize = fontSizeOverride.fontSizeMin;
				_text.resizeTextMaxSize = fontSizeOverride.fontSizeMax;
			}
			else
			{
				_text.fontSize = fontSizeOverride.fontSize;
			}
		}

		public void Restore()
		{
			if (_text.resizeTextForBestFit)
			{
				_text.resizeTextMinSize = _originalResizeTextMinSize;
				_text.resizeTextMaxSize = _originalResizeTextMaxSize;
			}
			else
			{
				_text.fontSize = _originalFontSize;
			}
		}
	}
	internal class LocalizeTextMeshProFontSize : ILocalizeFontSizeBehaviour
	{
		private TMP_Text _textMeshPro;

		private float _originalFontSize;

		private float _originalFontSizeMin;

		private float _originalFontSizeMax;

		public LocalizeTextMeshProFontSize(TMP_Text textMeshPro)
		{
			_textMeshPro = textMeshPro;
			_originalFontSize = textMeshPro.fontSize;
			_originalFontSizeMin = textMeshPro.fontSizeMin;
			_originalFontSizeMax = textMeshPro.fontSizeMax;
		}

		public void ApplyOverride(LocalizeFontSize.Override fontSizeOverride)
		{
			if (_textMeshPro.enableAutoSizing)
			{
				_textMeshPro.fontSizeMin = fontSizeOverride.fontSizeMin;
				_textMeshPro.fontSizeMax = fontSizeOverride.fontSizeMax;
			}
			else
			{
				_textMeshPro.fontSize = fontSizeOverride.fontSize;
			}
		}

		public void Restore()
		{
			if (_textMeshPro.enableAutoSizing)
			{
				_textMeshPro.fontSizeMin = _originalFontSizeMin;
				_textMeshPro.fontSizeMax = _originalFontSizeMax;
			}
			else
			{
				_textMeshPro.fontSize = _originalFontSize;
			}
		}
	}
