namespace AllIn1SpriteShader
{
	[ExecuteInEditMode]
	public class All1CreateUnifiedOutline : MonoBehaviour
	{
		[SerializeField]
		private Material outlineMaterial;

		[SerializeField]
		private Transform outlineParentTransform;

		[Space]
		[Header("Only needed if Sprite (ignored if UI)")]
		[SerializeField]
		private int duplicateOrderInLayer = -100;

		[SerializeField]
		private string duplicateSortingLayer = "Default";

		[Space]
		[Header("This operation will delete the component")]
		[SerializeField]
		private bool createUnifiedOutline;

		private void Update()
		{
			if (!createUnifiedOutline)
			{
				return;
			}
			if (outlineMaterial == null)
			{
				createUnifiedOutline = false;
				MissingMaterial();
				return;
			}
			List<Transform> transforms = new List<Transform>();
			GetAllChildren(base.transform, ref transforms);
			foreach (Transform item in transforms)
			{
				CreateOutlineSpriteDuplicate(item.gameObject);
			}
			CreateOutlineSpriteDuplicate(base.gameObject);
			UnityEngine.Object.DestroyImmediate(this);
		}

		private void CreateOutlineSpriteDuplicate(GameObject target)
		{
			bool flag = false;
			SpriteRenderer component = target.GetComponent<SpriteRenderer>();
			Image component2 = target.GetComponent<Image>();
			if (component != null)
			{
				flag = false;
			}
			else if (component2 != null)
			{
				flag = true;
			}
			else if (component == null && component2 == null && !base.transform.Equals(outlineParentTransform))
			{
				return;
			}
			GameObject gameObject = new GameObject();
			gameObject.name = target.name + "Outline";
			gameObject.transform.position = target.transform.position;
			gameObject.transform.rotation = target.transform.rotation;
			gameObject.transform.localScale = target.transform.lossyScale;
			if (outlineParentTransform == null)
			{
				gameObject.transform.parent = target.transform;
			}
			else
			{
				gameObject.transform.parent = outlineParentTransform;
			}
			if (!flag)
			{
				SpriteRenderer spriteRenderer = gameObject.AddComponent<SpriteRenderer>();
				spriteRenderer.sprite = component.sprite;
				spriteRenderer.sortingOrder = duplicateOrderInLayer;
				spriteRenderer.sortingLayerName = duplicateSortingLayer;
				spriteRenderer.material = outlineMaterial;
				spriteRenderer.flipX = component.flipX;
				spriteRenderer.flipY = component.flipY;
			}
			else
			{
				Image image = gameObject.AddComponent<Image>();
				image.sprite = component2.sprite;
				image.material = outlineMaterial;
			}
		}

		private void MissingMaterial()
		{
		}

		private void GetAllChildren(Transform parent, ref List<Transform> transforms)
		{
			foreach (Transform item in parent)
			{
				transforms.Add(item);
				GetAllChildren(item, ref transforms);
			}
		}
	}
	public class RandomSeed : MonoBehaviour
	{
		private void Start()
		{
			Renderer component = GetComponent<Renderer>();
			if (component != null)
			{
				if (component.material != null)
				{
					component.material.SetFloat("_RandomSeed", UnityEngine.Random.Range(0f, 1000f));
				}
				else
				{
					UnityEngine.Debug.LogError("Missing Renderer or Material: " + base.gameObject.name);
				}
				return;
			}
			Image component2 = GetComponent<Image>();
			if (component2 != null)
			{
				if (component2.material != null)
				{
					component2.material.SetFloat("_RandomSeed", UnityEngine.Random.Range(0f, 1000f));
				}
				else
				{
					UnityEngine.Debug.LogError("Missing Material on UI Image: " + base.gameObject.name);
				}
			}
			else
			{
				UnityEngine.Debug.LogError("Missing Renderer or UI Image on: " + base.gameObject.name);
			}
		}
	}
	[ExecuteInEditMode]
	public class SetAtlasUvs : MonoBehaviour
	{
		[SerializeField]
		private bool updateEveryFrame;

		private Renderer render;

		private SpriteRenderer spriteRender;

		private Image uiImage;

		private bool isUI;

		private void Start()
		{
			Setup();
		}

		private void Reset()
		{
			Setup();
		}

		private void Setup()
		{
			if (GetRendererReferencesIfNeeded())
			{
				GetAndSetUVs();
			}
			if (!updateEveryFrame && Application.isPlaying && this != null)
			{
				base.enabled = false;
			}
		}

		private void OnWillRenderObject()
		{
			if (updateEveryFrame)
			{
				GetAndSetUVs();
			}
		}

		public void GetAndSetUVs()
		{
			if (GetRendererReferencesIfNeeded())
			{
				if (!isUI)
				{
					Rect textureRect = spriteRender.sprite.textureRect;
					textureRect.x /= spriteRender.sprite.texture.width;
					textureRect.width /= spriteRender.sprite.texture.width;
					textureRect.y /= spriteRender.sprite.texture.height;
					textureRect.height /= spriteRender.sprite.texture.height;
					render.sharedMaterial.SetFloat("_MinXUV", textureRect.xMin);
					render.sharedMaterial.SetFloat("_MaxXUV", textureRect.xMax);
					render.sharedMaterial.SetFloat("_MinYUV", textureRect.yMin);
					render.sharedMaterial.SetFloat("_MaxYUV", textureRect.yMax);
				}
				else
				{
					Rect textureRect2 = uiImage.sprite.textureRect;
					textureRect2.x /= uiImage.sprite.texture.width;
					textureRect2.width /= uiImage.sprite.texture.width;
					textureRect2.y /= uiImage.sprite.texture.height;
					textureRect2.height /= uiImage.sprite.texture.height;
					uiImage.material.SetFloat("_MinXUV", textureRect2.xMin);
					uiImage.material.SetFloat("_MaxXUV", textureRect2.xMax);
					uiImage.material.SetFloat("_MinYUV", textureRect2.yMin);
					uiImage.material.SetFloat("_MaxYUV", textureRect2.yMax);
				}
			}
		}

		public void ResetAtlasUvs()
		{
			if (GetRendererReferencesIfNeeded())
			{
				if (!isUI)
				{
					render.sharedMaterial.SetFloat("_MinXUV", 0f);
					render.sharedMaterial.SetFloat("_MaxXUV", 1f);
					render.sharedMaterial.SetFloat("_MinYUV", 0f);
					render.sharedMaterial.SetFloat("_MaxYUV", 1f);
				}
				else
				{
					uiImage.material.SetFloat("_MinXUV", 0f);
					uiImage.material.SetFloat("_MaxXUV", 1f);
					uiImage.material.SetFloat("_MinYUV", 0f);
					uiImage.material.SetFloat("_MaxYUV", 1f);
				}
			}
		}

		public void UpdateEveryFrame(bool everyFrame)
		{
			updateEveryFrame = everyFrame;
		}

		private bool GetRendererReferencesIfNeeded()
		{
			if (spriteRender == null)
			{
				spriteRender = GetComponent<SpriteRenderer>();
			}
			if (spriteRender != null)
			{
				if (spriteRender.sprite == null)
				{
					UnityEngine.Object.DestroyImmediate(this);
					return false;
				}
				if (render == null)
				{
					render = GetComponent<Renderer>();
				}
				isUI = false;
			}
			else
			{
				if (uiImage == null)
				{
					uiImage = GetComponent<Image>();
					if (!(uiImage != null))
					{
						UnityEngine.Object.DestroyImmediate(this);
						return false;
					}
				}
				if (render == null)
				{
					render = GetComponent<Renderer>();
				}
				isUI = true;
			}
			if (spriteRender == null && uiImage == null)
			{
				UnityEngine.Object.DestroyImmediate(this);
				return false;
			}
			return true;
		}
	}
	[ExecuteInEditMode]
	public class SetGlobalTime : MonoBehaviour
	{
		private int globalTime;

		private void Start()
		{
			globalTime = Shader.PropertyToID("globalUnscaledTime");
